<node TEXT="Подзапросы. SUBSTR" ID="ID_853735075" CREATED="1526130094825" MODIFIED="1729081165455"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Подзапросы</b>&#xa0;&#xa0;- вложенные запросы.
    </p>
    <p>
      
    </p>
    <p>
      <b>Получение подстроки</b>
    </p>
    <p>
      <span style="color: #008000;">SELECT SUBSTR('this string', 6);&#xa0;&#xa0;-- Вернуть знаки строки начиная с 6 позиции до конца --&gt; string </span>
    </p>
    <p>
      <span style="color: #008000;">SELECT released, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;SUBSTR(released, 1, 4) AS year, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;SUBSTR(released, 6, 2) AS month, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;SUBSTR(released, 9, 2) AS day </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;FROM album </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;ORDER BY released </span>
    </p>
    <p>
      <span style="color: #008000;">;</span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">SELECT * FROM album WHERE id IN ( </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;SELECT DISTINCT album_id FROM track WHERE duration &lt;= 90 </span>
    </p>
    <p>
      <span style="color: #008000;">) ;</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Представления" ID="ID_51420718" CREATED="1527421063531" MODIFIED="1729081165272"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Сохранить запрос в базе данных для повторного использования
    </p>
    <p>
      
    </p>
    <p>
      <b><span style="color: #008000;">CREATE VIEW</span></b><span style="color: #008000;">&#xa0;trackView AS </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;SELECT id, album_id, title, track_number, duration / 60 AS m, duration % 60 AS s FROM track; </span>
    </p>
    <p>
      <span style="color: #008000;">SELECT * FROM <b>trackView</b>; </span>
    </p>
    <p>
      
    </p>
    <p>
      <b><span style="color: #008000;">DROP VIEW</span></b><span style="color: #008000;">&#xa0;trackView;</span>&#xa0;&#xa0;-- Удалить представление
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Транзакции" ID="ID_1785284478" CREATED="1527413581734" MODIFIED="1729081165125"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1706354230">Транзакция</a>&#xa0;&#xa0;&#xa0;<a href="#ID_862685360">TCL</a>
    </p>
    <ul>
      <li>
        транзакция <b>увеличивает быстродействие</b>&#xa0;при большом количестве операторов вставки, поскольку системе не нужно каждый раз подтверждать,что данные успешно записаны. Для этого <b>блок операторов оформляем как транзакцию</b>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">BEGIN TRANSACTION;</span>&#xa0;&#xa0;-- Начало (группировка) транзакции
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&lt;транзакция1&gt;; </span>
    </p>
    <p>
      <span style="color: #008000;">END TRANSACTION;</span>&#xa0;&#xa0;-- Конец транзакции
    </p>
    <p>
      
    </p>
    <p>
      <b>Отличия в разных СУБД</b>
    </p>
    <ul>
      <li>
        BEGIN TRANSACTION == START TRANSACTION == BEGIN
      </li>
      <li>
        END TRANSACTION == COMMIT TRANSACTION == COMMIT == END
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Триггеры" ID="ID_948822842" CREATED="1527418409271" MODIFIED="1729081164751"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Триггеры </b>
    </p>
    <ul>
      <li>
        для обновления таблицы при изменении другой таблицы
      </li>
      <li>
        для предотвращения изменения строк, которые уже согласованы или не должны изменяться
      </li>
      <li>
        RAISE() - действительна только внутри триггера. Создает сигнал, указывающий СУБД сделать что-то специфичное (откатить транзакцию)
      </li>
      <li>
        для создания временных меток в таблицах
      </li>
    </ul>
    <p>
      <b><span style="color: #008000;">CREATE TRIGGER</span></b><span style="color: #008000;">&#xa0;newWidgetSale <b>AFTER&#xa0;INSERT</b>&#xa0;ON widgetSale</span>&#xa0;&#xa0;-- <b>Выполение после события</b>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0; <b>BEGIN</b>&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;UPDATE widgetCustomer SET last_order_id = <b>NEW</b>.id WHERE widgetCustomer.id = NEW.customer_id;&#xa0;</span>&#xa0;-- Основная инструкция триггера
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0; <b>END</b>&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000;">; </span>
    </p>
    <p>
      
    </p>
    <p>
      <b><span style="color: #008000;">CREATE TRIGGER</span></b><span style="color: #008000;">&#xa0;updateWidgetSale <b>BEFORE UPDATE</b>&#xa0;ON Tab2</span>&#xa0;&#xa0;&#xa0;-- <b>Выполняется перед обновлением</b>&#xa0;&#xa0;таблицы Tab2
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0; <b>BEGIN</b>&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;SELECT <b>RAISE</b>(ROLLBACK, 'cannot update table &quot;Tab2&quot;') FROM Tab2 </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;WHERE id = NEW.id AND reconciled = 1; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0; <b>END</b>&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000;">; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">CREATE TRIGGER stampSale AFTER INSERT ON widgetSale </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;BEGIN </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;UPDATE widgetSale SET stamp = DATETIME('now') WHERE id = NEW.id; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;UPDATE widgetCustomer SET last_order_id = NEW.id, stamp = DATETIME('now') </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;WHERE widgetCustomer.id = NEW.customer_id; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;INSERT INTO widgetLog (stamp, event, username, tablename, table_id) </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;VALUES (DATETIME('now'), 'INSERT', 'TRIGGER', 'widgetSale', NEW.id); </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;END </span>
    </p>
    <p>
      <span style="color: #008000;">;</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Операторы - адм. операции - DCL" FOLDED="true" ID="ID_1134907847" CREATED="1525533318204" MODIFIED="1570802291645"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Data Control Language (DCL)</b>&#160;&#8212; &#1087;&#1086;&#1076;&#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1086; &#1103;&#1079;&#1099;&#1082;&#1072; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1041;&#1044; SQL, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1086;&#1077; &#1076;&#1083;&#1103; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1093; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1081;, &#1087;&#1088;&#1080;&#1089;&#1074;&#1072;&#1080;&#1074;&#1072;&#1102;&#1097;&#1080;&#1093; &#1080;&#1083;&#1080; &#1086;&#1090;&#1084;&#1077;&#1085;&#1103;&#1102;&#1097;&#1080;&#1093; &#1087;&#1088;&#1072;&#1074;&#1086; (&#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1102;) &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1041;&#1044;, &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1041;&#1044;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1090;&#1077; &#1080;&#1083;&#1080; &#1080;&#1085;&#1099;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1099; SQL.
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;GRANT &#8212; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1089;&#1074;&#1086;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;;
    </p>
    <p>
      &#160;&#160;&#160;&#160;REVOKE &#8212; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1086;&#1090;&#1084;&#1077;&#1085;&#1099; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;.
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        &#1074;&#1089;&#1105; &#1086;&#1095;&#1077;&#1085;&#1100; &#1089;&#1080;&#1083;&#1100;&#1085;&#1086; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1054;&#1057; &#1080; &#1057;&#1059;&#1041;&#1044;
      </li>
    </ul>
  </body>
</html></richcontent>
