<node TEXT="OVERLAPS" ID="ID_621477514" CREATED="1526976576387" MODIFIED="1550069149181"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1077;&#1088;&#1077;&#1082;&#1088;&#1099;&#1090;&#1080;&#1103;</b>
    </p>
    <p>
      &lt;&#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1086;&#1088; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;&gt; <b>OVERLAPS</b>&#160; &lt;&#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1086;&#1088; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;&gt;
    </p>
    <p>
      
    </p>
    <p>
      &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;, &#1073;&#1091;&#1076;&#1077;&#1090; &#1083;&#1080; &#1086;&#1076;&#1080;&#1085; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1087;&#1077;&#1088;&#1077;&#1082;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076;&#1099;.
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1088;&#1080;&#1084;&#1077;&#1088;&#1099;:
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;(Datetime &#8216;1992-11&#8217; Interval &#8216;0004-01&#8217;) OVERLAPS (Datetime &#8216;1994-11&#8217;, Datetime &#8216;1994-02&#8217;)
    </p>
    <p>
      &#160;&#160;&#160;&#160;(Datetime &#8216;1992-11&#8217; Interval &#8216;-0004-01&#8217;) OVERLAPS (Datetime &#8216;1994-11&#8217;, Datetime &#8216;1994-02&#8217;)
    </p>
  </body>
</html></richcontent>
