    <p>
      <b>AS</b>&#160;-&#160;&#160;&#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1077; (&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077;) &#1080;&#1084;&#1103; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072; &#1080;&#1083;&#1080; &#1080;&#1084;&#1077;&#1085;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;
    </p>
    <ul>
      <li>
        &#1055;&#1089;&#1077;&#1074;&#1076;&#1086;&#1085;&#1080;&#1084;&#1099; &#1095;&#1072;&#1089;&#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1080;&#1084;&#1077;&#1085;&#1072; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1086;&#1074; &#1073;&#1086;&#1083;&#1077;&#1077; &#1095;&#1080;&#1090;&#1072;&#1077;&#1084;&#1099;&#1084;&#1080;
      </li>
      <li>
        &#1055;&#1089;&#1077;&#1074;&#1076;&#1086;&#1085;&#1080;&#1084; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1074;&#1088;&#1077;&#1084;&#1103; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;
      </li>
    </ul>
    <p>
      <b>&#1057;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089; (&#1089;&#1090;&#1086;&#1083;&#1073;&#1077;&#1094;)</b>
