<node TEXT="Агрегатные функции (COUNT, MAX, MIN, SUM, AVG)" ID="ID_1603761874" CREATED="1525527115854" MODIFIED="1550068999812"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1367870796">GROUP BY</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1040;&#1075;&#1088;&#1077;&#1075;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1077; (&#1072;&#1075;&#1088;&#1077;&#1075;&#1072;&#1090;&#1085;&#1099;&#1077;), &#1075;&#1088;&#1091;&#1087;&#1087;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;</b>&#160; - &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1103;&#1090; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1077; &#1080; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1102;&#1090; &#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;.
    </p>
    <ul>
      <li>
        &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; COUNT() &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;
      </li>
      <li>
        &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; AVG() &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1086;&#1075;&#1086; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072;
      </li>
      <li>
        &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; SUM() &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1089;&#1091;&#1084;&#1084;&#1091; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1086;&#1075;&#1086; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072;
      </li>
      <li>
        &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; MIN() &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1085;&#1072;&#1080;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072;
      </li>
      <li>
        &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; MAX() &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1085;&#1072;&#1080;&#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072;
      </li>
      <li>
        &#1091;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;, &#1086;&#1090;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077; &#1086;&#1090; NULL
      </li>
    </ul>
    <p>
      <font color="#008000">SELECT <b>COUNT</b>(*) FROM Tab1;</font>&#160;&#160;# <b>&#1057;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100;</b>&#160; &#1074;&#1089;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1077;. &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1082;&#1086;&#1083;-&#1074;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;
    </p>
    <p>
      <font color="#008000">SELECT <b>COUNT</b>(*) FROM Employee WHERE Salary &gt; 20000;</font>&#160;&#160;# &#1063;&#1080;&#1089;&#1083;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1085;&#1080;&#1082;&#1086;&#1074; &#1089; &#1079;&#1087; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; 20&#1082;
    </p>
    <p>
      <font color="#008000">SELECT <b>MAX</b>(column_name) FROM Product;</font>&#160;&#160;# &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; <b>&#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102;</b>&#160; &#1094;&#1077;&#1085;&#1091; &#1074; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1077;. <b>MIN</b>
    </p>
    <p>
      <font color="#008000">SELECT <b>SUM</b>(TotalDue) FROM Order WHERE CustomerID = 3;</font>&#160;&#160;-- <b>&#1057;&#1091;&#1084;&#1084;&#1072;</b>&#160; &#1074;&#1089;&#1077;&#1093; &#1079;&#1072;&#1082;&#1072;&#1079;&#1086;&#1074; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; 3
    </p>
    <p>
      <font color="#008000">SELECT <b>AVG</b>(column_name) FROM table_name;</font>&#160;&#160;-- <b>&#1057;&#1088;&#1077;&#1076;&#1085;&#1077;&#1077;</b>&#160;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;&#160;&#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Функции для выч. числ. значения" ID="ID_816742512" CREATED="1526130011089" MODIFIED="1550149980082"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1072;&#1090;&#1077;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1080; &#1082;&#1086;&#1085;&#1089;&#1090;&#1072;&#1085;&#1090;&#1099; &#1074; MySQL</b>
    </p>
    <p>
      ABS()&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1072;&#1073;&#1089;&#1086;&#1083;&#1102;&#1090;&#1085;&#1086;&#1077; (&#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; ) &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      ACOS()&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1072;&#1088;&#1082;&#1082;&#1086;&#1089;&#1080;&#1085;&#1091;&#1089;
    </p>
    <p>
      ASIN()&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1072;&#1088;&#1082;&#1089;&#1080;&#1085;&#1091;&#1089;
    </p>
    <p>
      ATAN()&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1072;&#1088;&#1082;&#1090;&#1072;&#1085;&#1075;&#1077;&#1085;&#1089;
    </p>
    <p>
      ATANT2()&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1072;&#1088;&#1082;&#1090;&#1072;&#1085;&#1075;&#1077;&#1085;&#1089; &#1076;&#1074;&#1091;&#1093; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;
    </p>
    <p>
      CEIL()&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1054;&#1082;&#1088;&#1091;&#1075;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074;&#1074;&#1077;&#1088;&#1093;
    </p>
    <p>
      CEILING()&#160;&#160;&#1057;&#1080;&#1085;&#1086;&#1085;&#1080;&#1084; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1077;&#1075;&#1086;
    </p>
    <p>
      CONV()&#160;&#160;&#160;&#160;&#160;&#1052;&#1077;&#1085;&#1103;&#1077;&#1090; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091; &#1089;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      COS&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1082;&#1086;&#1089;&#1080;&#1085;&#1091;&#1089;
    </p>
    <p>
      COT()&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1082;&#1086;&#1090;&#1072;&#1085;&#1075;&#1077;&#1085;&#1089;
    </p>
    <p>
      CRC32()&#160;&#160;&#160;&#160;&#1042;&#1099;&#1095;&#1080;&#1089;&#1083;&#1103;&#1077;&#1090; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1091;&#1102; &#1089;&#1091;&#1084;&#1084;&#1091;
    </p>
    <p>
      DEGREES() &#1055;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1077;&#1090; &#1088;&#1072;&#1076;&#1080;&#1072;&#1085;&#1099; &#1074; &#1075;&#1088;&#1072;&#1076;&#1091;&#1089;&#1099;
    </p>
    <p>
      EXP()&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1077;(&#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072;&#1090;&#1091;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1083;&#1086;&#1075;&#1072;&#1088;&#1080;&#1092;&#1084;&#1072;) &#1074; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1081; &#1089;&#1090;&#1077;&#1087;&#1077;&#1085;&#1080;
    </p>
    <p>
      FLOOR()&#160;&#160;&#160;&#1054;&#1082;&#1088;&#1091;&#1075;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074;&#1085;&#1080;&#1079;
    </p>
    <p>
      LN()&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1085;&#1072;&#1090;&#1091;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1083;&#1086;&#1075;&#1072;&#1088;&#1080;&#1092;&#1084; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;
    </p>
    <p>
      LOG()&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1083;&#1086;&#1075;&#1072;&#1088;&#1080;&#1092;&#1084; &#1087;&#1077;&#1088;&#1074;&#1086;&#1075;&#1086; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;
    </p>
    <p>
      LOG10()&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1083;&#1086;&#1075;&#1072;&#1088;&#1080;&#1092;&#1084; &#1087;&#1086; &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102; 10
    </p>
    <p>
      LOG2()&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1083;&#1086;&#1075;&#1072;&#1088;&#1080;&#1092;&#1084; &#1087;&#1086; &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102; 2
    </p>
    <p>
      MOD()&#160;&#160;&#160;&#160;&#160;&#160;&#1044;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1102;, &#1075;&#1076;&#1077; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090; - &#1076;&#1077;&#1083;&#1080;&#1084;&#1086;&#1077;
    </p>
    <p>
      PI()&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1080;&#1088;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1095;&#1080;&#1089;&#1083;&#1072; &#1055;&#1080;
    </p>
    <p>
      POW()&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090; &#1074; &#1089;&#1090;&#1077;&#1087;&#1077;&#1085;&#1100;, &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090; - &#1089;&#1090;&#1077;&#1087;&#1077;&#1085;&#1100;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1086;&#1079;&#1074;&#1077;&#1089;&#1090;&#1080;
    </p>
    <p>
      POWER()&#160;&#160;&#1057;&#1080;&#1085;&#1086;&#1085;&#1080;&#1084; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1077;&#1075;&#1086;
    </p>
    <p>
      RADIANS() &#1055;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1077;&#1090; &#1074; &#1088;&#1072;&#1076;&#1080;&#1072;&#1085;&#1099;
    </p>
    <p>
      RAND()&#160;&#160;&#160;&#160;&#160;&#160;&#1055;&#1089;&#1077;&#1074;&#1076;&#1086;&#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1089; &#1087;&#1083;&#1072;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1090;&#1086;&#1095;&#1082;&#1086;&#1081; &#1074; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1077; &#1086;&#1090; 0 &#1076;&#1086; 1
    </p>
    <p>
      ROUND()&#160;&#160;&#160;&#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1086;&#1082;&#1088;&#1091;&#1075;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1084;&#1072;&#1090;&#1077;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;&#1084; &#1076;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1079;&#1085;&#1072;&#1082;&#1072;
    </p>
    <p>
      SIGN()&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1079;&#1085;&#1072;&#1082; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;
    </p>
    <p>
      SIN()&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1089;&#1080;&#1085;&#1091;&#1089;
    </p>
    <p>
      SQRT()&#160;&#160;&#160;&#160;&#160;&#1050;&#1074;&#1072;&#1076;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1082;&#1086;&#1088;&#1077;&#1085;&#1100;
    </p>
    <p>
      TAN()&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1090;&#1072;&#1085;&#1075;&#1077;&#1085;&#1089;
    </p>
    <p>
      TRUNCATE()&#160;&#160;&#1055;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1077;&#1090; &#1095;&#1080;&#1089;&#1083;&#1086;, &#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1103; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;-&#1074;&#1086; &#1079;&#1085;&#1072;&#1082;&#1086;&#1074; &#1087;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1087;&#1103;&#1090;&#1086;&#1081;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="NULL функции" ID="ID_1867592141" CREATED="1550150036964" MODIFIED="1550150422620"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>IFNULL(), ISNULL(), COALESCE(), NVL()</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>MySQL</b>. The MySQL <b>IFNULL()</b>&#160;function lets you return an alternative value if an expression is NULL:
    </p>
    <p>
      <font color="#008000">SELECT ProductName, UnitPrice * (UnitsInStock + IFNULL(UnitsOnOrder, 0)) </font>
    </p>
    <p>
      <font color="#008000">FROM Products </font>
    </p>
    <p>
      or we can use the <b>COALESCE()</b>&#160;function, like this:
    </p>
    <p>
      <font color="#008000">SELECT ProductName, UnitPrice * (UnitsInStock + COALESCE(UnitsOnOrder, 0)) </font>
    </p>
    <p>
      <font color="#008000">FROM Products </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>SQL Server. </b>The SQL Server <b>ISNULL()</b>&#160;function lets you return an alternative value when an expression is NULL:
    </p>
    <p>
      <font color="#008000">SELECT ProductName, UnitPrice * (UnitsInStock + ISNULL(UnitsOnOrder, 0)) </font>
    </p>
    <p>
      <font color="#008000">FROM Products</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>MS Access. </b>The MS Access <b>IsNull()</b>&#160;function returns TRUE (-1) if the expression is a null value, otherwise FALSE (0):
    </p>
    <p>
      <font color="#008000">SELECT ProductName, UnitPrice * (UnitsInStock + IIF(IsNull(UnitsOnOrder), 0, UnitsOnOrder)) </font>
    </p>
    <p>
      <font color="#008000">FROM Products</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>Oracle. </b>The Oracle <b>NVL()</b>&#160;function achieves the same result:
    </p>
    <p>
      <font color="#008000">SELECT ProductName, UnitPrice * (UnitsInStock + NVL(UnitsOnOrder, 0)) </font>
    </p>
    <p>
      <font color="#008000">FROM Products </font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Оптимизация" POSITION="bottom_or_right" ID="ID_975113706" CREATED="1728899672887" MODIFIED="1729170724591"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_258267982">INDEX</a>&#xa0; <a href="#ID_1949750923">Индексы</a>&#xa0;
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        Желательно использовать первичный ключ в каждой таблице - так создаётся индекс, и при запросе связанных через внешний ключ данных выборка будет работать гораздо быстрее
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Запросы" POSITION="bottom_or_right" ID="ID_588065048" CREATED="1759653945173" MODIFIED="1767362210829"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1445272606">SQL</a>&#xa0; <a href="#ID_271718517">Работа с БД (SQL)</a>&#xa0; <a href="#ID_1925885652">Работа с Таблицами (SQL)</a>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        имена баз данных чувствительны к регистру
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">SHOW STATUS LIKE '</span><span style="color: #008000; font-weight: bold;">Questions</span><span style="color: #008000;">';</span>&#xa0;&#xa0;&#xa0;# Статус с фильтрацией (кол-во запросов)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Запросы</span>
    </p>
    <p>
      <span style="color: #008000;">SELECT User, Host, Password_expired FROM </span><span style="color: #008000; font-weight: bold;">user</span><span style="color: #008000;">;</span>&#xa0;&#xa0;# Данные из таблицы <span style="font-weight: bold;">user</span>
    </p>
    <ul>
      <li>
        User: Имя пользователя учетной записи MySQL
      </li>
      <li>
        Host: Хост, с которого разрешено подключение этому пользователю
      </li>
      <li>
        Password_expired: Указывает, истек ли срок действия пароля
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      \G (ego)&#xa0;&#xa0;- Вертикальный вывод записей
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="База данных" POSITION="bottom_or_right" ID="ID_1287137793" CREATED="1767012868234" MODIFIED="1767342975896"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1066030078">mysqladmin</a>&#xa0; <a href="#ID_1445272606">SQL</a>&#xa0; <a href="#ID_271718517">Работа с БД (SQL)</a>&#xa0; <a href="#ID_1925885652">Работа с Таблицами (SQL)</a>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        имена баз данных чувствительны к регистру
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">mysql -u root&#xa0;-p</span>&#xa0;&#xa0;# запустим клиент MySQL
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Инфо</span>
    </p>
    <p>
      <span style="color: #008000;">SELECT VERSION();</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Версия</span>&#xa0;сервера MySQL
    </p>
    <p>
      <span style="color: #008000;">SHOW STATUS;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Статус</span>&#xa0;сервера
    </p>
    <p>
      <span style="color: #008000;">SELECT DATABASE();</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Текущая</span><span style="font-weight: normal;">&#xa0;&#xa0;БД </span>
    </p>
    <p>
      <span style="color: #008000;">SELECT USER();</span>&#xa0;&#xa0;# Текущий <span style="font-weight: bold;">пользователь </span>
    </p>
    <p>
      <span style="color: #008000;">SHOW TABLES;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Таблицы</span>&#xa0;в текущей БД
    </p>
    <p>
      <span style="color: #008000;">SHOW STATUS LIKE 'Questions';</span>&#xa0;&#xa0;# Статус с фильтрацией (кол-во запросов)
    </p>
    <p>
      <span style="color: #008000;">SHOW VARIABLES;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Переменные</span>&#xa0;конфигурации сервера
    </p>
    <p>
      <span style="color: #008000;">SHOW VARIABLES LIKE '%buffer%';</span>&#xa0;&#xa0;# Переменные <span style="font-weight: bold;">с фильтрацией </span>
    </p>
    <ul>
      <li>
        % - шаблонный символ (wildcard), любая последовательность символов (включая пустую)
      </li>
    </ul>
    <p>
      <span style="color: #008000;">SHOW VARIABLES LIKE 'port';</span>&#xa0;&#xa0;# На каком порту запущен MySQL
    </p>
    <p>
      
    </p>
    <p>
      <b>Работа с БД</b>
    </p>
    <p>
      <span style="color: #008000;">SELECT DATABASE();</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Текущая</span><span style="font-weight: normal;">&#xa0;&#xa0;БД</span>
    </p>
    <p>
      <span style="color: #008000;">SHOW DATABASES;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Список</span><span style="font-weight: normal;">&#xa0;&#xa0;всех БД, </span>присутствующих на вашем сервере MySQL
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">information_schema</span>: БД, которая предоставляет доступ к метаданным базы данных
      </li>
      <li>
        <span style="font-weight: bold;">mysql</span>: Системная БД, содержащая информацию о пользовательских учетных записях и привилегиях
      </li>
      <li>
        <span style="font-weight: bold;">performance_schema</span>: БД для мониторинга выполнения сервера MySQL на низком уровне
      </li>
      <li>
        <span style="font-weight: bold;">sys</span>: БД, которая предоставляет набор объектов для интерпретации данных, собранных схемой Performance Schema
      </li>
    </ul>
    <p>
      <span style="color: #008000;">USE dbname;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Переключиться</span>&#xa0;на базу данных dbname
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">CREATE&#xa0;DATABASE dbname;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать</span>&#xa0;БД
    </p>
    <p>
      <span style="color: #008000;">DROP&#xa0;DATABASE dbname;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Удалить</span>&#xa0;БД
    </p>
    <p>
      <span style="color: #0000c0;">mysqladmin -u root -p </span><span style="color: #0000c0; font-weight: bold;">create</span><span style="color: #0000c0;">&#xa0;dbname</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать </span>БД
    </p>
    <p>
      <span style="color: #0000c0;">mysqladmin -u root -p </span><span style="color: #0000c0; font-weight: bold;">drop</span><span style="color: #0000c0;">&#xa0;dbname</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Удалить </span>БД
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">EXIT;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Выйти</span>&#xa0;из оболочки MySQL
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Таблицы" FOLDED="true" POSITION="bottom_or_right" ID="ID_1997345228" CREATED="1526032201147" MODIFIED="1767364818221"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_271718517">Работа с БД (SQL)</a>&#xa0; <a href="#ID_1925885652">Работа с Таблицами (SQL)</a>&#xa0;&#xa0;<a href="#ID_1369972357">Типы данных</a>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">SHOW TABLES;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Таблицы</span>&#xa0;в текущей БД
    </p>
    <p>
      <span style="color: #008000;">DESCRIBE mytable;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Структура</span>&#xa0;таблицы
    </p>
    <p>
      <span style="color: #008000;">SHOW CREATE TABLE inventory_items;</span>&#xa0;&#xa0;# Показать полный оператор CREATE TABLE, включая все ограничения
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">SHOW INDEX FROM products;</span>&#xa0;&#xa0;# Все <span style="font-weight: bold;">индексы</span>&#xa0;на таблице
    </p>
    <p>
      <span style="color: #008000;">SHOW TABLE STATUS FROM store; </span>&#xa0;# <span style="font-weight: bold;">Статус таблиц</span>
    </p>
    <ul>
      <li>
        Хранилище (storage engine)
      </li>
      <li>
        Формат строки (row format)
      </li>
      <li>
        Количество строк
      </li>
      <li>
        Средняя длина строки
      </li>
      <li>
        Размер данных
      </li>
      <li>
        Размер индексов
      </li>
    </ul>
    <p>
      <span style="color: #008000;">SHOW FULL COLUMNS FROM products;</span>&#xa0;&#xa0;# Подробная информация <span style="font-weight: bold;">о столбце</span>
    </p>
    <ul>
      <li>
        Тип столбца
      </li>
      <li>
        Сравнение (collation)
      </li>
      <li>
        Привилегии
      </li>
      <li>
        Комментарии
      </li>
    </ul>
    <p>
      # Информация о таблицах из базы данных INFORMATION_SCHEMA
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">SELECT </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;TABLE_NAME, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;ENGINE, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;TABLE_ROWS, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;AVG_ROW_LENGTH, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;DATA_LENGTH, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;INDEX_LENGTH </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">FROM </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;INFORMATION_SCHEMA.TABLES </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WHERE </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;TABLE_SCHEMA = 'store';</span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">-- Создание таблицы</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">CREATE TABLE users ( </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;id INT AUTO_INCREMENT PRIMARY KEY, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;name VARCHAR(100) NOT NULL </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">);</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">-- Добавить новый столбец</span>&#xa0;- добавляет новый столбец с именем manufacturer после столбца name
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ALTER TABLE products </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console; font-weight: bold;">ADD COLUMN</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;manufacturer VARCHAR(100) AFTER name; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">-- Изменить существующий столбец</span>&#xa0;- изменяет столбец description на строку переменной длины с максимальной длиной 500 символов. Также устанавливается значение по умолчанию 'No description available' для новых строк.
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ALTER TABLE products </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console; font-weight: bold;">MODIFY COLUMN</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;description VARCHAR(500) NOT NULL DEFAULT 'No description available'; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">-- Переименовать столбец</span>&#xa0;- переименовывает столбец weight в product_weight и изменяет его тип данных на десятичное число с 8 цифрами в общей сложности и 2 десятичными знаками
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ALTER TABLE products </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console; font-weight: bold;">CHANGE COLUMN</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;weight product_weight DECIMAL(8,2); </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">-- Удалить столбец</span>&#xa0;- удаляет столбец in_stock из таблицы
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ALTER TABLE products </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">DROP COLUMN in_stock; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">-- Добавим составной индекс</span>&#xa0;для улучшения производительности запросов - создает составной индекс на столбцах name и manufacturer
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ALTER TABLE products </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ADD INDEX idx_name_manufacturer (name, manufacturer); </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">-- Безопасное удаление таблицы </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">DROP TABLE IF EXISTS inventory_items;</span>
    </p>
    <ul>
      <li>
        сначала нужно удалить таблицы с <span style="font-weight: bold;">внешними ключами</span>&#xa0;(foreign key constraints)
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="Типы данных" FOLDED="true" POSITION="bottom_or_right" ID="ID_1369972357" CREATED="1519112080526" MODIFIED="1767091335065"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Числовые типы</span>
    </p>
    <ul>
      <li>
        INT - целое число (обычно от −2 147 483 648 до 2 147 483 647). Подходит для ID, счётчиков и т.п.
      </li>
      <li>
        DECIMAL(M, D) - точное десятичное число с M цифрами всего и D после запятой. Используется, где важна точность: деньги, метрики
      </li>
      <li>
        FLOAT / DOUBLE - приблизительные числа с плавающей точкой. Подходят для научных расчётов, где допустима погрешность

        <ul>
          <li>
            FLOAT - одинарная точность (~7 цифр)
          </li>
          <li>
            DOUBLE - двойная точность (~15-17 цифр)
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Строковые типы</span>
    </p>
    <ul>
      <li>
        VARCHAR(n) - строка переменной длины до n символов (макс. 65 535). Экономит место
      </li>
      <li>
        CHAR(n) -&#xa0;&#xa0;строка фиксированной длины n символов (макс. 255). Быстрее для коротких, всегда одинаковых значений (например, коды стран: RU, US)
      </li>
      <li>
        TEXT - длинный текст (до 65 535 байт). Есть варианты: TINYTEXT, MEDIUMTEXT, LONGTEXT - для ещё больших объёмов
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Типы даты и времени</span>
    </p>
    <ul>
      <li>
        DATE - только дата в формате ГГГГ-ММ-ДД (например, 2025-12-30)
      </li>
      <li>
        TIME - только время в формате ЧЧ:ММ:СС (например, 14:30:00)
      </li>
      <li>
        DATETIME - дата и время вместе: ГГГГ-ММ-ДД ЧЧ:ММ:СС (например, 2025-12-30 14:30:00).&#xa0;Хранит значение «как есть», без привязки к часовым поясам.
      </li>
      <li>
        TIMESTAMP - дата и времени в формате ГГГГ-ММ-ДД ЧЧ:ММ:СС

        <ul>
          <li>
            Хранится как **число секунд с 1970-01-01 00:00:00 UTC** (Unix-время)
          </li>
          <li>
            Автоматически конвертируется в/из временной зоны соединения при записи и чтении
          </li>
          <li>
            Диапазон: от 1970-01-01 00:00:01 UTC до 2038-01-19 03:14:07 UTC (ограничение 32-битного Unix-времени)
          </li>
          <li>
            Зависит от часового пояса - полезен, если пользователи в разных регионах
          </li>
        </ul>
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="Числовые" FOLDED="true" ID="ID_1611245071" CREATED="1526029266568" MODIFIED="1767089853120"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><a href="#ID_1446542012">вещественные</a>&#xa0;&#xa0;(Real)</b>&#xa0;&#xa0;- имеют погрешность. Имеют дробную часть
    </p>
    <ul>
      <li>
        REAL(precision)
      </li>
      <li>
        FLOAT(precision)
      </li>
      <li>
        DECIMAL(precision, scale) - число с десятичной точкой фиксированной точности
      </li>
      <li>
        MONEY(precision, scale) - для фин. расчетов
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="Целые числа (INTEGER)" ID="ID_1763839780" CREATED="1530277088972" MODIFIED="1767363875663"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Целые числа: тип данных INTEGER</b>
    </p>
    <p>
      INTEGER(precision) - целые числа без дробной части
    </p>
    <ul>
      <li>
        <b>BIGINT</b>&#xa0;(8 байт)&#xa0;от -2^63 (-9 223 372 036 854 775 808) до 2^63-1 (9 223 372 036 854 775 807)<br/>0 - 18446744073709551615
      </li>
      <li>
        <b>INT</b>&#xa0;(4 байта)&#xa0;от -2^31 (-2 147 483 648) до 2^31-1 (2 147 483 647)<br/>0 - 4294967295
      </li>
      <li>
        <b>MEDIUMINT</b>&#xa0;(3 байта) (-8388608 до 8388608)<br/>0 - 16777215<br/><span style="color: #ff0000;">не исп. в T-SQL&#xa0;</span>
      </li>
      <li>
        <b>SMALLINT</b>&#xa0;(2 байта)&#xa0;от -2^15 (-32768) до 2^15-1 (32767)<br/>0 - 65535
      </li>
      <li>
        <b>TINYINT</b>&#xa0;(1 байт) от -128 до 127&#xa0;беззнаковое, по умолчанию (TINYINT UNSIGNED)<br/>0 до 255 - беззнаковое (TINYINT UNSIGNED)
      </li>
      <li>
        <b>NUMERIC</b>&#xa0;и <b>DECIMAL</b>&#xa0;- для денежных данных<br/><span style="color: #008000;">salary <b>DECIMAL</b>(5,2)&#xa0; </span># 5 - общее кол-во знаков, 2 - кол-во знаков после запятой. От -99, 99 до 99,99 (до 999,99, если не нужен знак)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      Чтобы поле quantity_in_stock не допускало отрицательных значений, нужно добавить ограничение CHECK
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">quantity_in_stock int(11) CHECK (quantity_in_stock &gt;= 0)</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Числа с плавающей точкой" ID="ID_1512598000" CREATED="1530278324390" MODIFIED="1530279121207"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>FLOAT</b>(M, D) - &#1090;&#1080;&#1087; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089; &#1086;&#1076;&#1080;&#1085;&#1072;&#1088;&#1085;&#1086;&#1081; &#1090;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;, &#1087;&#1086;&#1076; &#1085;&#1077;&#1075;&#1086; &#1074;&#1099;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; 4 &#1073;&#1072;&#1081;&#1090;&#1072;. M - &#1086;&#1073;&#1097;&#1077;&#1077; &#1082;&#1086;&#1083;-&#1074;&#1086; &#1094;&#1080;&#1092;&#1088;. D - &#1094;&#1080;&#1092;&#1088; &#1087;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1087;&#1103;&#1090;&#1086;&#1081;
    </p>
    <p>
      <b>DOUBLE</b>(M, D) - &#1090;&#1080;&#1087; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086;&#1074;&#1099;&#1096;&#1077;&#1085;&#1085;&#1086;&#1081; &#1080;&#1083;&#1080; &#1076;&#1074;&#1086;&#1081;&#1085;&#1086;&#1081; &#1090;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1080;, &#1087;&#1086;&#1076; &#1085;&#1077;&#1075;&#1086; &#1074;&#1099;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; 8 &#1073;&#1072;&#1081;&#1090;
    </p>
    <ul>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1095;&#1080;&#1089;&#1083;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1099;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1080;&#1079; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1072;, &#1090;&#1086; MySQL &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090; &#1086;&#1082;&#1088;&#1091;&#1075;&#1083;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        &#1063;&#1080;&#1089;&#1083;&#1072; &#1089; &#1087;&#1083;&#1072;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1090;&#1086;&#1095;&#1082;&#1086;&#1081; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1085;&#1077;&#1090;&#1086;&#1095;&#1085;&#1086;
      </li>
      <li>
        &#1056;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1099; &#1089;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1103; &#1095;&#1080;&#1089;&#1077;&#1083; &#1089; &#1087;&#1083;&#1072;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1090;&#1086;&#1095;&#1082;&#1086;&#1081; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1085;&#1077;&#1087;&#1088;&#1077;&#1076;&#1089;&#1082;&#1072;&#1079;&#1091;&#1077;&#1084;&#1099;
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Числа с фиксированной точкой" ID="ID_1171835865" CREATED="1530277589667" MODIFIED="1530354421879"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1042; MySQL &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1099; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1086; <b>DECIMAL</b>&#160;&#1080; <b>NUMERIC</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>DECIMAL(<i>&#1090;&#1086;&#1095;&#1085;&#1085;&#1086;&#1089;&#1090;&#1100; - &#1095;&#1080;&#1089;&#1083;&#1086; &#1079;&#1085;&#1072;&#1082;&#1086;&#1074;, &#1076;&#1088;&#1086;&#1073;&#1085;&#1072;&#1103; &#1095;&#1072;&#1089;&#1090;&#1100;</i>)</b>&#160; - &#1095;&#1080;&#1089;&#1083;&#1086; &#1089; &#1076;&#1077;&#1089;&#1103;&#1090;&#1080;&#1095;&#1085;&#1086;&#1081; &#1090;&#1086;&#1095;&#1082;&#1086;&#1081; &#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1081; &#1090;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1080;
    </p>
    <ul>
      <li>
        DECIMAL(5,2)&#160;&#160;-- &#1055;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1086;&#1090; -99.99 &#1076;&#1086; 999.99
      </li>
      <li>
        DECIMAL&#160;&#160;-- &#1069;&#1082;&#1074;&#1080;&#1074;&#1072;&#1083;&#1077;&#1085;&#1090;&#1085;&#1072; DECIMAL(10,0)
      </li>
      <li>
        &#1084;&#1072;&#1082;&#1089;. &#1082;&#1086;&#1083;-&#1074;&#1086; &#1094;&#1080;&#1092;&#1088; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; DECIMAL &#1088;&#1072;&#1074;&#1085;&#1086; 65
      </li>
    </ul>
  </body>
</html></richcontent>
