<node TEXT="Двоичные числовые значения" ID="ID_282040550" CREATED="1530353983669" MODIFIED="1530355326192"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1044;&#1074;&#1086;&#1080;&#1095;&#1085;&#1099;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;</b>
    </p>
    <ul>
      <li>
        MySQL &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1100; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082;&#1072;&#1082; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; 0 &#1080; 1
      </li>
      <li>
        &#1090;&#1080;&#1087; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; <b>BIT(M)</b>, &#1075;&#1076;&#1077; M - &#1094;&#1077;&#1083;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1086;&#1090; 1 &#1076;&#1086; 64 &#1073;&#1080;&#1090;
      </li>
      <li>
        &#1086;&#1073;&#1097;&#1072;&#1103; &#1092;&#1086;&#1088;&#1084;&#1072; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1095;&#1080;&#1089;&#1077;&#1083; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; BIT: <b>b'value'</b>, &#1075;&#1076;&#1077; value - &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; 0 &#1080; 1<br/>&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, <b>b'1011101'</b>
      </li>
      <li>
        &#1077;&#1089;&#1083;&#1080; &#1082;&#1086;&#1083;-&#1074;&#1086; 0 &#1080; 1 &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;, &#1095;&#1077;&#1084; &#1095;&#1080;&#1089;&#1083;&#1086; M, MySQL &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090; &#1085;&#1091;&#1083;&#1080;
      </li>
      <li>
        &#1095;&#1080;&#1089;&#1083;&#1072;, &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1099;&#1077; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; BIT &#1084;&#1086;&#1078;&#1085;&#1086; &#1083;&#1077;&#1075;&#1082;&#1086; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1074; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1089;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1103;
      </li>
    </ul>
    <p>
      &#1055;&#1088;&#1080;&#1084;&#1077;&#1088;
    </p>
    <p>
      <font color="#0000c0">CREATE TABLE t1 (b BIT(8)); </font>
    </p>
    <p>
      <font color="#0000c0">INSERT INTO t1 SET b = b'10110111'; </font>
    </p>
    <p>
      <font color="#0000c0">INSERT INTO t1 SET b = b'1010'; </font>
    </p>
    <p>
      <font color="#0000c0">SELECT b+0, BIN(b+0), OCT(b+0), HEX(b+0) FROM t1; </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="/, %, TYPEOF, ROUND" ID="ID_1062520508" CREATED="1527407970684" MODIFIED="1530358183195"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_301635848">&#1040;&#1088;&#1080;&#1092;&#1084;&#1077;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1099;</a>
    </p>
    <ul>
      <li>
        <b>TYPEOF</b>() - &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1090;&#1080;&#1087; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        / - &#1094;&#1077;&#1083;&#1086;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1085;&#1086;&#1077; &#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        %&#160;&#160;- <font size="2">&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1082; &#1087;&#1088;&#1080; &#1094;&#1077;&#1083;&#1086;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1085;&#1086;&#1084; &#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1080;. 5 % 2 = 1</font>
      </li>
      <li>
        <b>ROUND</b>(&#1095;&#1080;&#1089;&#1083;&#1086;, &#1082;&#1086;&#1083;-&#1074;&#1086; &#1079;&#1085;&#1072;&#1082;&#1086;&#1074;) - &#1086;&#1082;&#1088;&#1091;&#1075;&#1083;&#1077;&#1085;&#1080;&#1077;
      </li>
    </ul>
    <p>
      <font color="#008000">SELECT(1+1);</font>&#160;&#160;-- --&gt; 2
    </p>
    <p>
      <font color="#008000">SELECT <b>TYPEOF</b>(1+1);</font>&#160;&#160;-- &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1090;&#1080;&#1087; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; --&gt; integer
    </p>
    <p>
      <font color="#008000">SELECT <b>TYPEOF</b>(1+1.0);</font>&#160;&#160;-- &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1090;&#1080;&#1087; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; --&gt; real
    </p>
    <p>
      <font color="#008000">SELECT <b>TYPEOF</b>( 'fox' );</font>&#160;&#160;-- &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1090;&#1080;&#1087; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; --&gt; text
    </p>
    <p>
      <font color="#008000">SELECT( 'fox' );</font>&#160;&#160;-- &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1090;&#1080;&#1087; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; --&gt; text
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">SELECT <b>1 / 2</b>;</font>&#160;&#160;-- --&gt; 0
    </p>
    <p>
      <font color="#008000">SELECT <b>1.0 / 2</b>;</font>&#160;&#160;-- --&gt; 0.5
    </p>
    <p>
      <font color="#008000">SELECT <b>CAST(1 AS REAL)</b>&#160;/ 2;</font>&#160;&#160;-- --&gt; 0.5
    </p>
    <p>
      <font color="#008000">SELECT 11 / 5, 11 % 5;</font>&#160;&#160;-- --&gt;
    </p>
    <p>
      --&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;2&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;1
    </p>
    <p>
      <font color="#008000">SELECT <b>ROUND</b>(1.55555, 3);</font>&#160;&#160;-- --&gt; 1.556
    </p>
  </body>
</html></richcontent>
