  <body>
    <p>
      <b>BLOB</b>&#160;&#1080; <b>&#1058;&#1045;&#1061;&#1058;</b>&#160;- &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1086;&#1073;&#1098;&#1077;&#1084;&#1086;&#1074; &#1076;&#1074;&#1086;&#1080;&#1095;&#1085;&#1099;&#1093; &#1080;&#1083;&#1080; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1100;&#1085;&#1099;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;.
    </p>
    <ul>
      <li>
        &#1063;&#1090;&#1077;&#1085;&#1080;&#1077; &#1080;&#1079; &#1076;&#1086;&#1087;. &#1092;&#1072;&#1081;&#1083;&#1072; (&#1080;&#1083;&#1080; &#1088;&#1072;&#1085;&#1100;&#1096;&#1077; &#1090;&#1072;&#1082; &#1073;&#1099;&#1083;&#1086;???)
      </li>
      <li>
        &#1057;&#1089;&#1099;&#1083;&#1086;&#1095;&#1085;&#1099;&#1077; &#1087;&#1086;&#1083;&#1103; &#1080; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090; blob-&#1087;&#1086;&#1083;&#1103;
      </li>
      <li>
        &#1047;&#1072;&#1085;&#1080;&#1084;&#1072;&#1102;&#1090; &#1084;&#1077;&#1089;&#1090;&#1072; &#1088;&#1086;&#1074;&#1085;&#1086; &#1089;&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1085;&#1080;&#1093; &#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1083;&#1080; (&#1085;&#1077; &#1074;&#1089;&#1077; &#1084;&#1077;&#1089;&#1090;&#1086;)
      </li>
      <li>
        &#1076;&#1083;&#1103; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1086;&#1074; BLOB &#1080; TEXT &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;
      </li>
      <li>
        MySQL &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; BLOB &#1080; TEXT <b>&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1078;&#1077;&#1089;&#1090;&#1082;&#1086;&#1084; &#1076;&#1080;&#1089;&#1082;&#1077;</b>. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1086;&#1087;&#1099;&#1090;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1089;&#1086; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072;&#1084;&#1080; BLOB &#1080;&#1083;&#1080; TEXT, &#1090;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072; &#1089; &#1101;&#1090;&#1080;&#1084;&#1080; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072;&#1084;&#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1085;&#1072; &#1078;&#1077;&#1089;&#1090;&#1082;&#1086;&#1084; &#1076;&#1080;&#1089;&#1082;&#1077;, &#1072; &#1085;&#1077; &#1074; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;
      </li>
    </ul>
    <p>
      <b>C&#1080;&#1084;&#1074;&#1086;&#1083;&#1100;&#1085;&#1099;&#1081; &#1090;&#1080;&#1087; (TEXT)</b>
    </p>
    <ul>
