      </li>
      <li>
        MEDIUMBLOB&#160;&#160;2^24-1 (16M-1) =&#160;&#160;(16777215 &#1073;&#1072;&#1081;&#1090;)
      </li>
      <li>
        LONGBLOB 2^32-1 (4G-1) = (4,29E+09 &#1073;&#1072;&#1081;&#1090;)
      </li>
    </ul>
    <p>
      
