<node TEXT="ENUM" ID="ID_665182341" CREATED="1530020323372" MODIFIED="1530360594723"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>ENUM (&#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1077;)</b>&#160; - &#1089;&#1090;&#1086;&#1083;&#1073;&#1077;&#1094;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1080;&#1079; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072; &#1076;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1084;&#1099;&#1093; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;, &#1103;&#1074;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1074; &#1089;&#1087;&#1077;&#1094;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072; &#1074; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;.
    </p>
    <ul>
      <li>
        &#1054;&#1095;&#1077;&#1085;&#1100; &#1082;&#1086;&#1084;&#1087;&#1072;&#1082;&#1090;&#1085;&#1099;&#1081; &#1090;&#1080;&#1087; - &#1080;&#1084; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;
      </li>
      <li>
        MySQL &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1080;&#1079; &#1089;&#1090;&#1088;&#1086;&#1082;&#1086;&#1074;&#1086;&#1075;&#1086; &#1090;&#1080;&#1087;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1086;&#1081; &#1080; &#1085;&#1072;&#1086;&#1073;&#1086;&#1088;&#1086;&#1090; &#1087;&#1088;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080;
      </li>
      <li>
        &#1053;&#1077;&#1083;&#1100;&#1079;&#1103; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074; &#1089;&#1090;&#1086;&#1083;&#1073;&#1077;&#1094; ENUM, &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;
      </li>
      <li>
        &#1050;&#1072;&#1078;&#1076;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072; ENUM &#1085;&#1091;&#1084;&#1077;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1080;&#1083;&#1080; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1080; &#1082; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072;&#1084; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1077; (&#1085;&#1077; &#1087;&#1091;&#1090;&#1072;&#1090;&#1100; &#1089; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1072;&#1084;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;)
      </li>
      <li>
        &#1052;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1085;&#1099;&#1081; &#1090;&#1077;&#1086;&#1088;&#1077;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;&#160;&#1074; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1080; &#1088;&#1072;&#1074;&#1077;&#1085; 65535 (&#1085;&#1072; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1077; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1091;&#1084; &#1084;&#1077;&#1085;&#1077;&#1077; 3000 &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; - &#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1085;&#1086; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;&#1094;&#1080;&#1080; MySQL)
      </li>
      <li>
        &#1042; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1074; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1080; ENUM &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1083;&#1080;&#1090;&#1077;&#1088;&#1072;&#1083;&#1099; (&#1089;&#1090;&#1088;&#1086;&#1082;&#1086;&#1074;&#1099;&#1077; &#1080;&#1083;&#1080; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1099;&#1077;), &#1085;&#1086; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077; (&#1076;&#1072;&#1078;&#1077; &#1089;&#1072;&#1084;&#1099;&#1077; &#1087;&#1088;&#1086;&#1089;&#1090;&#1099;&#1077;) &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;
      </li>
    </ul>
    <p>
      &#1069;&#1090;&#1080;&#1084; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1090;&#1072;&#1082;&#1078;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1091;&#1089;&#1090;&#1072;&#1103; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072; (&quot;&quot;) &#1080;&#1083;&#1080; NULL &#1087;&#1088;&#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103;&#1093;:
    </p>
    <ul>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1089;&#1090;&#1072;&#1074;&#1082;&#1072; &#1085;&#1077;&#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1085;&#1086;&#1075;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074; &#1089;&#1090;&#1086;&#1083;&#1073;&#1077;&#1094; ENUM (&#1090;.&#1077;. &#1074;&#1089;&#1090;&#1072;&#1074;&#1082;&#1072; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;, &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1085;&#1086;&#1081; &#1074; &#1089;&#1087;&#1080;&#1089;&#1082;&#1077; &#1076;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1084;&#1099;&#1093;), &#1090;&#1086; &#1074;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1091;&#1089;&#1090;&#1072;&#1103; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072;, &#1095;&#1090;&#1086; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1077;&#1084; &#1085;&#1072; &#1086;&#1096;&#1080;&#1073;&#1086;&#1095;&#1085;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;. &#1069;&#1090;&#1072; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072; &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090; &quot;&#1086;&#1073;&#1099;&#1095;&#1085;&#1086;&#1081;&quot; &#1087;&#1091;&#1089;&#1090;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1087;&#1086; &#1090;&#1086;&#1084;&#1091; &#1087;&#1088;&#1080;&#1079;&#1085;&#1072;&#1082;&#1091;, &#1095;&#1090;&#1086; &#1086;&#1085;&#1072; &#1080;&#1084;&#1077;&#1077;&#1090; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;, &#1088;&#1072;&#1074;&#1085;&#1086;&#1077; 0
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; ENUM &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; NULL, &#1090;&#1086; &#1090;&#1086;&#1075;&#1076;&#1072; NULL &#1090;&#1086;&#1078;&#1077; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1076;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1084;&#1099;&#1084; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; - NULL. &#1045;&#1089;&#1083;&#1080; ENUM &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; NOT NULL, &#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1080;&#1079; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072; &#1076;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1084;&#1099;&#1093; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;.
      </li>
    </ul>
    <p>
      <b>&#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;,</b>
    </p>
    <p>
      &#1074; &#1103;&#1095;&#1077;&#1081;&#1082;&#1091; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1077;&#1085;&#1100; &#1085;&#1077;&#1076;&#1077;&#1083;&#1080; (&#1086;&#1076;&#1080;&#1085; &#1080;&#1079; &#1089;&#1077;&#1084;&#1080;).
    </p>
  </body>
