  <body>
    <p>
      <b>&#1052;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1086; SET</b>&#160; - &#1089;&#1090;&#1088;&#1086;&#1082;&#1086;&#1074;&#1099;&#1081; &#1090;&#1080;&#1087;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1085;&#1086;&#1083;&#1100; &#1080;&#1083;&#1080; &#1073;&#1086;&#1083;&#1077;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;, &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; &#1080;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1086; &#1080;&#1079; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072; &#1076;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1084;&#1099;&#1093; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;, &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;. &#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1072; SET &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1079;&#1072;&#1087;&#1103;&#1090;&#1099;&#1084;&#1080;. &#1050;&#1072;&#1082; &#1089;&#1083;&#1077;&#1076;&#1089;&#1090;&#1074;&#1080;&#1077;, &#1089;&#1072;&#1084;&#1080; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1072; &#1085;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1079;&#1072;&#1087;&#1103;&#1090;&#1099;&#1093;.
    </p>
    <ul>
      <li>
        &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; 64 &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; (&#1079;&#1072;&#1088;&#1072;&#1085;&#1077;&#1077; &#1087;&#1088;&#1077;&#1076;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093;)
      </li>
      <li>
        &#1087;&#1086;&#1093;&#1086;&#1078; &#1085;&#1072; ENUM, &#1085;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1074; &#1086;&#1076;&#1085;&#1091; &#1103;&#1095;&#1077;&#1081;&#1082;&#1091;
      </li>
      <li>
        &#1082; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;&#1084; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072; SET, &#1082;&#1072;&#1082; &#1080; &#1082; ENUM &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1091;
      </li>
      <li>
        &#1087;&#1088;&#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1089;&#1090;&#1088;&#1086;&#1082; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1103; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1080;&#1079; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; SET &#1085;&#1077; &#1080;&#1084;&#1077;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;, MySQL &#1074;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090; &#1101;&#1090;&#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074; &#1090;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077;, &#1074; &#1082;&#1072;&#1082;&#1086;&#1084; &#1074;&#1099; &#1080;&#1093; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1083;&#1080; &#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;
      </li>
    </ul>
    <p>
      <b>&#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;</b>, &#1089;&#1090;&#1086;&#1083;&#1073;&#1077;&#1094;, &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#160;&quot;&quot; &quot;&#1087;&#1085;&#1076;&quot; &quot;&#1074;&#1090;&quot; &quot;&#1087;&#1085;&#1076;, &#1074;&#1090;&quot;
    </p>
    <p>
      <font color="#0000c0">SET(&quot;&#1087;&#1085;&#1076;&quot;, &quot;&#1074;&#1090;&quot;) NOT NULL</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Календарные" ID="ID_701314173" CREATED="1526029472433" MODIFIED="1550215222446"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1608731112">NTP</a>
    </p>
    <ul>
      <li>
        &#1058;&#1080;&#1087;&#1099; &#1076;&#1072;&#1090; &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1102;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1086;&#1074; &#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1085;&#1086;&#1074;&#1086;&#1081; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1074; &#1041;&#1044;
      </li>
      <li>
        &#1060;&#1086;&#1088;&#1084;&#1072;&#1090; &#1076;&#1072;&#1090;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1074;&#1099; &#1087;&#1099;&#1090;&#1072;&#1077;&#1090;&#1077;&#1089;&#1100; &#1074;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1084; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072; &#1076;&#1072;&#1090;&#1099; &#1074; &#1041;&#1044;
      </li>
      <li>
        &#1063;&#1090;&#1086;&#1073;&#1099; &#1074;&#1072;&#1096;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1073;&#1099;&#1083;&#1080; &#1087;&#1088;&#1086;&#1089;&#1090;&#1099;&#1084;&#1080; &#1080; &#1091;&#1076;&#1086;&#1073;&#1085;&#1099;&#1084;&#1080; &#1074; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1080;, <b>&#1085;&#1077; &#1076;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1081;&#1090;&#1077; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1074; &#1076;&#1072;&#1090;&#1072;&#1093;</b>
      </li>
    </ul>
    <p>
      <b>&#1057;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1086;&#1087;&#1090;&#1080;&#1084;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1090;&#1080;&#1087;&#1099; </b>
    </p>
    <ul>
      <li>
        &#1047;&#1072;&#1087;&#1080;&#1089;&#1100; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1086;&#1090; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1075;&#1086; &#1082; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1084;&#1091; - &#1075;&#1086;&#1076;, &#1084;&#1077;&#1089;&#1103;&#1094;, &#1076;&#1077;&#1085;&#1100;, &#1095;&#1072;&#1089;&#1099;, &#1084;&#1080;&#1085;&#1091;&#1090;&#1099;, &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1099;
      </li>
      <li>
        DATE. &#1086;&#1090; 1001-01-01 &#1076;&#1086; 9999-12-31. <b>3 &#1073;&#1072;&#1081;&#1090;&#1072;</b>
      </li>
      <li>
        TIME. &#1086;&#1090; -838:59:59 &#1076;&#1086; -838:59:59 <b>3 &#1073;&#1072;&#1081;&#1090;&#1072;</b>
      </li>
      <li>
        DATETIME. &#1086;&#1090; 1001-01-01 00:00:00 &#1076;&#1086; 9999-12-31 23:59:59. <b>8 &#1073;&#1072;&#1081;&#1090;</b>
      </li>
      <li>
        TIMESTAMP. &#1086;&#1090; 1970-01-01 00:00:00 &#1076;&#1086; 2037 <b>4 &#1073;&#1072;&#1081;&#1090;&#1072;</b>&#160;- UNIX-&#1074;&#1088;&#1077;&#1084;&#1103; (POSIX-&#1074;&#1088;&#1077;&#1084;&#1103;)
      </li>
      <li>
        YEAR. &#1086;&#1090; 1900 &#1076;&#1086; 2155 &#1086;&#1090; 1970 &#1076;&#1086; 2069 <b>1 &#1073;&#1072;&#1081;&#1090;</b>
      </li>
      <li>
        INTERVAL
      </li>
    </ul>
    <p>
      <b>&#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;</b>
    </p>
    <ul>
      <li>
        DATE()
      </li>
      <li>
        TIME()
      </li>
      <li>
        DATETIME()
      </li>
      <li>
        STRFTIME()
      </li>
    </ul>
    <p>
      <font color="#008000">SELECT DATETIME('now');</font>&#160;&#160;-- &#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1084;&#1077;&#1090;&#1082;&#1091; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; (&#1090;&#1077;&#1082;&#1091;&#1097;&#1072;&#1103;, UTC)
    </p>
    <p>
      <font color="#008000">SELECT DATETIME('now', '+1 day');</font>&#160;&#160;-- &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; 1 &#1076;&#1077;&#1085;&#1100; &#1082; &#1090;&#1077;&#1082;. &#1076;&#1072;&#1090;&#1077;
    </p>
    <p>
      <font color="#008000">SELECT DATETIME('now', '+3 hours', '+2 days');</font>&#160;&#160;-- &#1091;&#1095;&#1077;&#1089;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;
    </p>
    <p>
      <font color="#008000">SELECT CURENT_TIMESTAMP(), CURENT_TIMESTAMP, NOW(), LOCALTIME(), LOCALTIME, LOCALTIMESTAMP, LOCALTIMESTAMP()&#160;&#160;--</font>&#160;&#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077; &#1076;&#1072;&#1090;&#1072; &#1080; &#1074;&#1088;&#1077;&#1084;&#1103;
    </p>
    <p>
      
    </p>
    <p>
      # CURDATE &#1048; CURTIME - &#1086;&#1088;&#1080;&#1075;&#1080;&#1085;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103;, &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1089;&#1077;&#1074;&#1076;&#1086;&#1085;&#1080;&#1084;&#1099;
    </p>
    <p>
      <font color="#008000">SELECT <b>CURDATE</b>(), CURRENT_DATE(), CURRENT_DATE;</font>&#160;&#160;-- &#1058;&#1077;&#1082;&#1091;&#1097;&#1072;&#1103; &#1076;&#1072;&#1090;&#1072;.
    </p>
    <p>
      <font color="#008000">SELECT <b>CURTIME</b>(), CURRENT_TIME(), CURRENT_TIME;</font>&#160;&#160;-- &#1058;&#1077;&#1082;&#1091;&#1097;&#1077;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="NULL, NOT NULL" ID="ID_1401143279" CREATED="1526029498066" MODIFIED="1729155177746"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1787881854">NULL (оператор)</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>NULL</b>&#xa0;- значение отсутствует
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">SELECT * FROM table_name WHERE c1 <b>IS&#xa0;NULL</b></span>&#xa0;&#xa0;-- Проверка на NULL
    </p>
    <p>
      <span style="color: #008000;">SELECT * FROM table_name WHERE c1 <b>IS&#xa0;NOT NULL</b></span>&#xa0;&#xa0;-- Строки не содержат NULL
    </p>
    <p>
      
    </p>
    <p>
      <b>Таблица с заполнением всех полей</b>
    </p>
    <p>
      <span style="color: #008000;">CREATE TABLE test ( </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;a INTEGER <b>NOT NULL</b>, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;b TEXT <b>NOT NULL</b>, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;c TEXT <b>NOT NULL</b>&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000;">);</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="UNIQUE" ID="ID_1963994677" CREATED="1729155291370" MODIFIED="1729155580457"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">UNIQUE</span>&#xa0;указывает, что значения в этом столбце должны быть уникальными.
    </p>
    <p>
      
    </p>
    <p>
      CREATE TABLE courses (ID integer, Название varchar(200) NOT NULL <span style="font-weight: bold;">UNIQUE</span>);
    </p>
  </body>
</html></richcontent>
</node>
