<node TEXT="пример - типы данных" POSITION="bottom_or_right" ID="ID_795901225" CREATED="1767090834601" MODIFIED="1767364854623"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">CREATE TABLE products ( </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;id INT AUTO_INCREMENT PRIMARY KEY, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;name VARCHAR(100) NOT NULL, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;price DECIMAL(10,2) NOT NULL, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;description TEXT, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;weight FLOAT, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;in_stock BOOLEAN, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;created_at DATETIME DEFAULT CURRENT_TIMESTAMP, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;last_updated TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">);</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">CREATE TABLE books ( </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;id INT AUTO_INCREMENT PRIMARY KEY, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;title VARCHAR(200) NOT NULL, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;price DECIMAL(5,2), </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;publication_date DATE, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;page_count INT, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;description TEXT, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;quantity_in_stock INT CHECK (quantity_in_stock &gt;= 0) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">);</span>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">id</span>: Автоинкрементируемое целое число, которое служит в качестве первичного ключа
      </li>
      <li>
        <span style="font-weight: bold;">name</span>: Строка переменной длины, которая не может быть NULL
      </li>
      <li>
        <span style="font-weight: bold;">price</span>: Точное десятичное число с 10 цифрами в общей сложности и 2 десятичными знаками
      </li>
      <li>
        <span style="font-weight: bold;">description</span>: Текстовое поле для более длинных описаний
      </li>
      <li>
        <span style="font-weight: bold;">weight</span>: Число с плавающей точкой для приблизительных десятичных значений
      </li>
      <li>
        <span style="font-weight: bold;">in_stock</span>: Булево поле (TRUE/FALSE)
      </li>
      <li>
        <span style="font-weight: bold;">created_at</span>: Автоматически сохраняет временную метку создания
      </li>
      <li>
        <span style="font-weight: bold;">last_updated</span>: Автоматически обновляется при изменении записи
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="пример - ограничения" POSITION="bottom_or_right" ID="ID_1119358215" CREATED="1767091529099" MODIFIED="1767092071573"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">CREATE TABLE categories ( </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;category_id INT AUTO_INCREMENT </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">PRIMARY KEY</span><span style="color: #008000; font-family: Lucida Console;">, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;category_name VARCHAR(50) </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">NOT NULL</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">UNIQUE</span><span style="color: #008000; font-family: Lucida Console;">, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;description VARCHAR(200), </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;active BOOLEAN </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">DEFAULT</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;TRUE </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">); </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">CREATE TABLE inventory_items ( </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;item_id INT AUTO_INCREMENT </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">PRIMARY KEY</span><span style="color: #008000; font-family: Lucida Console;">, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;category_id INT, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;sku VARCHAR(20) NOT NULL </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">UNIQUE</span><span style="color: #008000; font-family: Lucida Console;">, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;item_name VARCHAR(100) </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">NOT NULL</span><span style="color: #008000; font-family: Lucida Console;">, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;quantity INT </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">NOT NULL</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">CHECK</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;(quantity &gt;= 0), </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;unit_price DECIMAL(10,2) </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">NOT NULL</span><span style="color: #008000; font-family: Lucida Console;">, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">FOREIGN KEY</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;(category_id) REFERENCES categories(category_id) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">);</span>
    </p>
    <p>
      
    </p>
    <p>
      Ограничения:
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">PRIMARY KEY</span>&#xa0;(Первичный ключ): Гарантирует уникальную идентификацию каждой записи
      </li>
      <li>
        <span style="font-weight: bold;">UNIQUE</span>&#xa0;(Уникальное значение): Предотвращает дублирование значений в столбце
      </li>
      <li>
        <span style="font-weight: bold;">NOT NULL</span>&#xa0;(Не NULL): Гарантирует, что столбец не может содержать значения NULL
      </li>
      <li>
        <span style="font-weight: bold;">CHECK</span>&#xa0;(Проверка): Проверяет данные перед их вставкой
      </li>
      <li>
        <span style="font-weight: bold;">FOREIGN KEY</span>&#xa0;(Внешний ключ): Гарантирует целостность ссылок между таблицами
      </li>
      <li>
        <span style="font-weight: bold;">DEFAULT</span>&#xa0;(Значение по умолчанию): Предоставляет значение по умолчанию, если оно не указано
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
</node>
<node TEXT="Данные" POSITION="bottom_or_right" ID="ID_118378433" CREATED="1767341747118" MODIFIED="1767544316926"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1691964825">SELECT</a>&#xa0;&#xa0;<a href="#ID_158439273">INSERT</a>&#xa0;&#xa0;<a href="#ID_1917275707">UPDATE</a>&#xa0;&#xa0;<a href="#ID_230130962">DELETE</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">SELECT * FROM &lt;таблица&gt;;&#xa0; </span><span style="font-family: Lucida Console;">#&#xa0; </span><span style="font-weight: bold; font-family: Lucida Console;">Выборка</span><span style="font-family: Lucida Console;">&#xa0;данных </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">SELECT * FROM users; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">SELECT name, price FROM products WHERE price &lt; 50.00;</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Выборка </span><span style="font-weight: bold; font-family: Lucida Console;">с фильтрацией</span><span style="font-family: Lucida Console;">&#xa0;результатов </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">SELECT&#xa0; </span><span style="font-family: Lucida Console;"># Использование </span><span style="font-weight: bold; font-family: Lucida Console;">псевдонимов&#xa0;столбцов</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;name </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">AS</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;product_name,&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Переименовывает name в product_name </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;price </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">AS</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;retail_price, &#xa0;&#xa0;&#xa0;&#xa0;# Переименовывает price в retail_price </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;price * 0.8 </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">AS</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;sale_price&#xa0;&#xa0;# Вычисляет цену по скидке (со скидкой 20%) и называет ее sale_price </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">FROM products; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">SELECT name FROM products WHERE name </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">IN</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;('Coffee Maker', 'Blender');&#xa0; </span><span style="font-family: Lucida Console;"># Выборка c </span><span style="font-family: Lucida Console; font-weight: bold;">проверкой вхождения (IN)</span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">INSERT INTO &lt;таблица&gt; (&lt;столбец&gt;) VALUES (&lt;значение&gt;);&#xa0; </span><span style="font-family: Lucida Console;">#&#xa0;</span><span style="font-weight: bold; font-family: Lucida Console;">Вставка</span><span style="font-family: Lucida Console;">&#xa0;данных </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">INSERT INTO users (name) VALUES ('Алиса'); </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">INSERT INTO products (name, price, description) VALUES </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;('Toaster', 3.99, '2-slice toaster with multiple browning settings'), </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;('Blender', 4.99, 'High-speed blender for smoothies and soups'), </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;('Microwave', 5.99, '1000-watt microwave with digital controls'); </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      Всегда используйте <span style="font-weight: bold; color: #ff0000;">WHERE</span>&#xa0;с <span style="font-weight: normal;">UPDATE</span>! <span style="color: #ff0000;">Без WHERE</span>&#xa0;обновление повлияет на <span style="color: #ff0000;">ВСЕ строки</span>&#xa0;в таблице.
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">UPDATE &lt;таблица&gt; SET &lt;столбец&gt; = &lt;новое_значение&gt; </span><span style="color: #ff0000; font-family: Lucida Console; font-weight: bold;">WHERE</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;&lt;условие&gt;;</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# </span><span style="font-weight: bold; font-family: Lucida Console;">Обновление </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">UPDATE users SET name = 'Боб' </span><span style="font-family: Lucida Console; font-weight: normal; color: #008000;">WHERE</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;id = 1;</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">UPDATE products&#xa0; </span><span style="font-family: Lucida Console;"># Обновить </span><span style="font-family: Lucida Console; font-weight: bold;">несколько столбцов</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">SET </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;price = 89.99, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;description = 'Professional-grade high-speed blender for smoothies and soups' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WHERE name = 'Blender'; </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">DELETE FROM &lt;таблица&gt; </span><span style="color: #ff0000; font-family: Lucida Console;">WHERE</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;&lt;условие&gt;;</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# </span><span style="font-weight: bold; font-family: Lucida Console;">Удаление</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">DELETE FROM products WHERE name = 'Toaster';</span>
    </p>
  </body>
</html></richcontent>
</node>
