<node TEXT="MySQL NDB Cluster" FOLDED="true" ID="ID_381050184" CREATED="1551706302720" MODIFIED="1551706639302"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_2188643">&#1056;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;</a>&#160; <a href="#ID_1202372477">Galera Cluster</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>MySQL NDB Cluster</b>&#160;(Network Database Cluster) - &#1101;&#1090;&#1086; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1041;&#1044;, &#1083;&#1077;&#1078;&#1072;&#1097;&#1072;&#1103; &#1074; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072; MySQL.
    </p>
    <ul>
      <li>
        &#1074;&#1099;&#1089;&#1086;&#1082;&#1072;&#1103; &#1080;&#1079;&#1073;&#1099;&#1090;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;, &#1072;&#1076;&#1072;&#1087;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1076;&#1083;&#1103; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1081; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1099;. &#1054;&#1085; &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1085;&#1077;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086; &#1086;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; MySQL &#1089; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084;&#1080;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1102;&#1097;&#1080;&#1084;&#1080; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1091; &#1095;&#1077;&#1088;&#1077;&#1079; API NDB
      </li>
      <li>
        MySQL Cluster &#1080;&#1085;&#1090;&#1077;&#1075;&#1088;&#1080;&#1088;&#1091;&#1077;&#1090; &#1074; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; MySQL &#1089; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1080;&#1079;&#1091;&#1077;&#1084;&#1099;&#1084; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1086;&#1084; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086; &#1080;&#1084;&#1077;&#1085;&#1080; NDB
      </li>
      <li>
        MySQL Cluster &#1091;&#1084;&#1077;&#1077;&#1090; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100;

        <ul>
          <li>
            &#1074;&#1099;&#1073;&#1086;&#1088;&#1082;&#1091; &#1087;&#1086; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1086;&#1084;&#1091; &#1082;&#1083;&#1102;&#1095;&#1091;
          </li>
          <li>
            &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; (&#1088;&#1072;&#1079;&#1084;&#1072;&#1079;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089; &#1080;&#1079;&#1073;&#1099;&#1090;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086; &#1085;&#1086;&#1076;&#1072;&#1084;)
          </li>
          <li>
            &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1100; (&#1084;&#1077;&#1085;&#1077;&#1076;&#1078;&#1077;&#1088; &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1085;&#1086;&#1076; &#1080; &#1088;&#1077;&#1072;&#1080;&#1075;&#1088;&#1091;&#1077;&#1090; &#1090;&#1077;&#1084; &#1080;&#1083;&#1080; &#1080;&#1085;&#1099;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;)
          </li>
        </ul>
      </li>
      <li>
        &#1055;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1085;&#1072;&#1103; &#1084;&#1072;&#1089;&#1090;&#1077;&#1088;-&#1084;&#1072;&#1089;&#1090;&#1077;&#1088; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;, &#1086;&#1095;&#1077;&#1085;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072;&#1103; in-memory &#1041;&#1044;
      </li>
      <li>
        &#1063;&#1090;&#1086;&#1073;&#1099; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1099;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; <b>&#1090;&#1088;&#1080; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1091;&#1079;&#1083;&#1086;&#1074;</b>: &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1076;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; &#1080; &#1076;&#1083;&#1103; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;. &#1044;&#1083;&#1103; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1080; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;, &#1074; &#1082;&#1072;&#1078;&#1076;&#1091;&#1102; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1085;&#1077; &#1084;&#1077;&#1085;&#1077;&#1077; 3 &#1091;&#1079;&#1083;&#1086;&#1074;.
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="Типы узлов" ID="ID_187148192" CREATED="1551528904422" MODIFIED="1570734741227"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1042; MySQL Cluster &#1082;&#1072;&#1078;&#1076;&#1072;&#1103; &#1095;&#1072;&#1089;&#1090;&#1100; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072; &#1080;&#1084;&#1077;&#1085;&#1091;&#1077;&#1090;&#1089;&#1103; node (&#1091;&#1079;&#1077;&#1083;). &#1044;&#1083;&#1103; MySQL Cluster &#1091;&#1079;&#1077;&#1083; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1084;. &#1052;&#1086;&#1078;&#1077;&#1090; &#1080;&#1084;&#1077;&#1090;&#1100;&#1089;&#1103; &#1083;&#1102;&#1073;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1091;&#1079;&#1083;&#1086;&#1074; &#1085;&#1072; &#1086;&#1076;&#1085;&#1086;&#1084; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1077;. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1091;&#1079;&#1077;&#1083; &#1080;&#1084;&#1077;&#1077;&#1090; &#1090;&#1080;&#1087;, &#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1091;&#1079;&#1083;&#1086;&#1074; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1090;&#1080;&#1087;&#1072; &#1074; MySQL Cluster. &#1042; &#1084;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072; MySQL &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1086; &#1082;&#1088;&#1072;&#1081;&#1085;&#1077;&#1081; &#1084;&#1077;&#1088;&#1077; &#1090;&#1088;&#1080; &#1091;&#1079;&#1083;&#1072;:
    </p>
    <ul>
      <li>
        <b>&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1072;&#1103; &#1085;&#1086;&#1076;&#1072; (management-&#1085;&#1086;&#1076;&#1072;), MGM.</b>&#160;&#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; <b>ndbmgmd</b>. &#1054;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;, &#1082;&#1072;&#1078;&#1076;&#1072;&#1103; &#1085;&#1086;&#1076;&#1072; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1077;&#1081; &#1085;&#1086;&#1076;&#1077; &#1087;&#1088;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1102; &#1082; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1091;. &#1055;&#1086;&#1090;&#1088;&#1077;&#1073;&#1083;&#1103;&#1077;&#1090; &#1085;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1093; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1074;, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1095;&#1072;&#1089;&#1090;&#1086; &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1076;&#1085;&#1086;&#1084; &#1078;&#1077; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1085;&#1086;&#1076;&#1086;&#1081;. &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1074;&#1099;&#1093;&#1086;&#1076;&#1072; &#1080;&#1079; &#1089;&#1090;&#1088;&#1086;&#1103; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1077;&#1081; &#1085;&#1086;&#1076;&#1099;, &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088; &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1078;&#1080;&#1090; &#1085;&#1086;&#1088;&#1084;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091;, &#1085;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1077;&#1085; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082; &#1085;&#1086;&#1076;. &#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1086;&#1076;&#1085;&#1091; &#1080;&#1083;&#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1093; &#1085;&#1086;&#1076;.
      </li>
      <li>
        <b>&#1044;&#1072;&#1090;&#1072;-&#1085;&#1086;&#1076;&#1072; (ndb-&#1085;&#1086;&#1076;&#1072;).</b>&#160;&#1069;&#1090;&#1086; &#1090;&#1080;&#1087; &#1091;&#1079;&#1083;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1080; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090; &#1041;&#1044; &#1085;&#1077;&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;. &#1042;&#1072;&#1078;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072; NoOfReplicas (&#1095;&#1080;&#1089;&#1083;&#1086; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;) - &#1095;&#1080;&#1089;&#1083;&#1086; &#1076;&#1072;&#1090;&#1072;-&#1085;&#1086;&#1076; &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1089;&#1103; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1081; &#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090;. &#1054;&#1073;&#1097;&#1077;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1076;&#1072;&#1090;&#1072;-&#1085;&#1086;&#1076; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1082;&#1088;&#1072;&#1090;&#1085;&#1086; &#1095;&#1080;&#1089;&#1083;&#1091; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;. &#1043;&#1088;&#1091;&#1087;&#1087;&#1072; &#1085;&#1086;&#1076; - &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1086;&#1076; (&#1095;&#1080;&#1089;&#1083;&#1086; &#1085;&#1086;&#1076; &#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1077; &#1088;&#1072;&#1074;&#1085;&#1086; &#1095;&#1080;&#1089;&#1083;&#1091; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;), &#1093;&#1088;&#1072;&#1085;&#1103;&#1097;&#1080;&#1093; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1095;&#1085;&#1091;&#1102; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; NoOfReplicas = 2, &#1095;&#1080;&#1089;&#1083;&#1086; &#1085;&#1086;&#1076; - 6. &#1050;&#1072;&#1078;&#1076;&#1072;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1088;&#1072;&#1079;&#1073;&#1080;&#1090;&#1072; &#1085;&#1072; 6 &#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; (&#1087;&#1086; &#1093;&#1077;&#1096;&#1091; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1082;&#1083;&#1102;&#1095;&#1072;), &#1087;&#1088;&#1086;&#1085;&#1091;&#1084;&#1077;&#1088;&#1091;&#1077;&#1084; &#1080;&#1093; F1,F2,F3,F4,F5,F6. 6 &#1085;&#1086;&#1076; (D1,D2,D3,D4,D5,D6) &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090; 3 &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; - &#1082;&#1072;&#1078;&#1076;&#1072;&#1103; &#1085;&#1086;&#1076;&#1072; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; (D1,D2) &#1093;&#1088;&#1072;&#1085;&#1080;&#1090; &#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099; F1,F2; &#1085;&#1086;&#1076;&#1099; &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; D3,D4 &#1093;&#1088;&#1072;&#1085;&#1103;&#1090; &#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099; F3,F4; &#1085;&#1086;&#1076;&#1099; &#1090;&#1088;&#1077;&#1090;&#1100;&#1077;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; D5,D6 &#1093;&#1088;&#1072;&#1085;&#1103;&#1090; &#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099; F5,F6. &#1042;&#1099;&#1093;&#1086;&#1076; &#1080;&#1079; &#1089;&#1090;&#1088;&#1086;&#1103; &#1074;&#1089;&#1077;&#1093; &#1085;&#1086;&#1076; &#1086;&#1076;&#1085;&#1086;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1087;&#1088;&#1080;&#1074;&#1086;&#1076;&#1080;&#1090; &#1082; &#1086;&#1090;&#1082;&#1072;&#1079;&#1091; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;.
      </li>
      <li>
        <b>SQL-&#1085;&#1086;&#1076;&#1072;, API-&#1085;&#1086;&#1076;&#1072;, &#1050;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1081; &#1091;&#1079;&#1077;&#1083;.&#160;&#160;&#1059;&#1079;&#1077;&#1083; &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; SQL-&#1082;&#1086;&#1084;&#1072;&#1085;&#1076;.</b>&#160;&#1048;&#1089;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; <b>mysqld</b>. SQL-&#1085;&#1086;&#1076;&#1072; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; &#1080; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1076;&#1072;&#1090;&#1072;-&#1085;&#1086;&#1076;&#1072;&#1084; &#1079;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080;. &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1078;&#1076;&#1072;&#1103; SQL-&#1085;&#1086;&#1076;&#1072; &#1074;&#1087;&#1088;&#1072;&#1074;&#1077; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1077; &#1085;&#1077;-NDB &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; (MyISAM, Innodb, ...), &#1082;&#1072;&#1082; &#1077;&#1089;&#1083;&#1080; &#1073;&#1099; &#1086;&#1085;&#1072; &#1085;&#1077; &#1074;&#1093;&#1086;&#1076;&#1080;&#1083;&#1072; &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;.
      </li>
    </ul>
  </body>
</html></richcontent>
