    </p>
    <p>
      
    </p>
    <p>
      &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1085;&#1091;&#1078;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1074;&#1077;&#1076;&#1091;&#1097;&#1080;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, manager.mysql.cluster. &#1069;&#1090;&#1086; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1090; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1074;&#1077;&#1076;&#1086;&#1084;&#1099;&#1084;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1084;&#1080;.
