      &#1042;&#1077;&#1076;&#1091;&#1097;&#1080;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1086;. &#1045;&#1075;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1080; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100; &#1073;&#1077;&#1079; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086;&#1077;&#1074; &#1076;&#1083;&#1103; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;. &#1054;&#1085; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1087;&#1077;&#1088;&#1074;&#1086;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1085;&#1086;&#1076; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;, &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1080; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; MySQL.
    </p>
    <p>
