    </p>
    <p>
      &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1080;&#1079; &#1090;&#1088;&#1105;&#1093; &#1090;&#1080;&#1087;&#1086;&#1074; &#1091;&#1079;&#1083;&#1086;&#1074;. &#1059;&#1079;&#1083;&#1086;&#1074; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1089;&#1082;&#1086;&#1083;&#1100; &#1091;&#1075;&#1086;&#1076;&#1085;&#1086; &#1084;&#1085;&#1086;&#1075;&#1086;. &#1042; &#1101;&#1090;&#1086;&#1084; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1089;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1085;&#1072; &#1073;&#1072;&#1079;&#1086;&#1074;&#1072;&#1103; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; &#1080;&#1079; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; SQL &#1080; Management &#1091;&#1079;&#1083;&#1072; &#1080; &#1076;&#1074;&#1091;&#1093; &#1091;&#1079;&#1083;&#1086;&#1074; &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1091;&#1079;&#1083;&#1072; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; (Management &#1091;&#1079;&#1083;&#1072;)</b>
    </p>
    <p>
      &#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; &#1076;&#1083;&#1103; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      <font color="#0000c0">mkdir /var/lib/mysql-cluster</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; <b>config.ini</b>&#160;&#1080; &#1074; &#1085;&#1105;&#1084; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;:
    </p>
    <p>
      <font color="#008000">[ndb_mgmd] </font>
    </p>
    <p>
      <font color="#008000">hostname=manager.mysql.cluster&#160;&#160;# Hostname &#1091;&#1079;&#1083;&#1072; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; </font>
    </p>
    <p>
      <font color="#008000">datadir=/var/lib/mysql-cluster&#160;&#160;# &#1044;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1103; &#1076;&#1083;&#1103; &#1083;&#1086;&#1075;&#1086;&#1074; </font>
    </p>
    <p>
      <font color="#008000">[ndbd] </font>
    </p>
    <p>
      <font color="#008000">hostname=node1.mysql.cluster&#160;&#160;&#160;&#160;# Hostname &#1091;&#1079;&#1083;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; </font>
    </p>
    <p>
      <font color="#008000">datadir=/usr/local/mysql/data&#160;&#160;&#160;# &#1044;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1103; &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; </font>
    </p>
    <p>
      <font color="#008000">[ndbd] </font>
    </p>
    <p>
      <font color="#008000">hostname=node2.mysql.cluster&#160;&#160;&#160;&#160;# Hostname &#1091;&#1079;&#1083;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; </font>
    </p>
    <p>
      <font color="#008000">datadir=/usr/local/mysql/data&#160;&#160;&#160;# &#1044;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1103; &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; </font>
    </p>
    <p>
      <font color="#008000">[mysqld] </font>
    </p>
    <p>
      <font color="#008000">hostname=manager.mysql.cluster&#160;&#160;# Hostname SQL-&#1091;&#1079;&#1083;&#1072;</font>
    </p>
    <p>
      <font color="#0000c0">/opt/mysql/server-5.6/bin/ndb_mgmd -f /var/lib/mysql-cluster/config.ini </font>&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1091;&#1079;&#1077;&#1083; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#0000c0">service mysql restart &amp;&amp; sudo ndbd --initial</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1082; &#1091;&#1079;&#1083;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1091;&#1079;&#1083;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;</b>
    </p>
    <p>
      <font color="#0000c0">vim /etc/my.cnf </font>&#160;# &#1053;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1092;&#1072;&#1081;&#1083;
    </p>
    <p>
      <font color="#008000">[mysql_cluster]&#160; </font># &#1048; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1074; &#1085;&#1077;&#1075;&#1086; &#1072;&#1076;&#1088;&#1077;&#1089; &#1091;&#1079;&#1083;&#1072; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#008000">ndb-connectstring=manager.mysql.cluster</font>
    </p>
    <p>
      <font color="#0000c0">sudo /opt/mysql/server-5.6/bin/ndbd </font>&#160;# &#1055;&#1088;&#1080; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1080; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1090;&#1072;&#1082;&#1078;&#1077; &#1091;&#1073;&#1077;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072; &#1087;&#1086;&#1076; &#1085;&#1080;&#1093;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1091;&#1079;&#1083;&#1072; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;. &#1055;&#1086;&#1089;&#1083;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086; &#1091;&#1079;&#1077;&#1083; &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; SQL-&#1091;&#1079;&#1083;&#1072;</b>
    </p>
    <p>
      &#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; &#1090;&#1072;&#1082;&#1078;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; <b>/etc/my.cnf</b>
    </p>
    <p>
      <font color="#008000">[mysqld] </font>
    </p>
    <p>
      <font color="#008000">datadir=/usr/local/mysql/data </font>
    </p>
    <p>
      <font color="#008000">socket=/tmp/mysql.sock </font>
    </p>
    <p>
      <font color="#008000">user=mysql </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">ndbcluster </font>
    </p>
    <p>
      <font color="#008000">ndb-connectstring=manager.mysql.cluster </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">[mysql_cluster] </font>
    </p>
    <p>
      <font color="#008000">ndb-connectstring=manager.mysql.cluster </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">[mysqld_safe] </font>
    </p>
    <p>
      <font color="#008000">log-error=/var/log/mysqld.log </font>
    </p>
    <p>
      <font color="#008000">pid-file=/var/run/mysqld/mysqld.pid</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1061;&#1086;&#1088;&#1086;&#1096;&#1080;&#1084; &#1087;&#1086;&#1076;&#1093;&#1086;&#1076;&#1086;&#1084; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1076;&#1083;&#1103; MySQL, &#1085;&#1086; &#1101;&#1090;&#1086;&#1090; &#1096;&#1072;&#1075; &#1086;&#1087;&#1091;&#1097;&#1077;&#1085;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">sudo service mysql restart</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1082; &#1091;&#1079;&#1083;&#1072; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;:
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Установка Galera Cluster (Ubuntu 16)" ID="ID_713314125" CREATED="1551685363921" MODIFIED="1551706322882"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1202372477">MariaDB Galera Cluster</a>
    </p>
    <p>
      
    </p>
    <p>
      &#1058;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;. &#1058;&#1088;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; Ubuntu 16.04, &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1084;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084; &#1089; 1&#1043;&#1041; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1064;&#1072;&#1075; 1.&#160;&#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1103; Galera &#1085;&#1072; &#1074;&#1089;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1099;</b>
    </p>
    <p>
      <font color="#0000c0">apt-key adv --keyserver keyserver.ubuntu.com --recv BC19DDBA</font>&#160;&#160;# &#1053;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1076;&#1086;&#1073;&#1072;&#1074;&#1100;&#1090;&#1077; &#1082;&#1083;&#1102;&#1095; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1103; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1080; &#1087;&#1086;&#1076;&#1083;&#1080;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;
    </p>
    <p>
      <font color="#0000c0">vim /etc/apt/sources.list.d/galera.list</font>&#160;&#160;# &#1055;&#1086;&#1089;&#1083;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082; &#1084;&#1099; &#1080;&#1084;&#1077;&#1077;&#1084; &#1076;&#1086;&#1074;&#1077;&#1088;&#1077;&#1085;&#1085;&#1099;&#1081; &#1082;&#1083;&#1102;&#1095; &#1074; &#1041;&#1044; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;, &#1084;&#1099; &#1084;&#1086;&#1078;&#1077;&#1084; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1080; &#1085;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;:
    </p>
    <p>
      <font color="#008000">deb http://releases.galeracluster.com/mysql-wsrep-5.6/ubuntu xenial main </font>
    </p>
    <p>
      <font color="#008000">deb http://releases.galeracluster.com/galera-3/ubuntu xenial main</font>
    </p>
    <p>
      <font color="#0000c0">vim /etc/apt/preferences.d/galera.pref</font>&#160;&#160;# &#1056;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1080; Codership &#1090;&#1077;&#1087;&#1077;&#1088;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1090;&#1088;&#1077;&#1093; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074;. &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; &#1074;&#1072;&#1078;&#1085;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; apt &#1086;&#1090;&#1076;&#1072;&#1074;&#1072;&#1083;&#1072; &#1087;&#1088;&#1077;&#1076;&#1087;&#1086;&#1095;&#1090;&#1077;&#1085;&#1080;&#1077; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1103;&#1084; Codership, &#1072; &#1085;&#1077; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1091; &#1080;&#1089;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1074;&#1077;&#1088;&#1089;&#1080;&#1081; &#1055;&#1054;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1075;&#1086; &#1076;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072; Galera
    </p>
    <p>
      <font color="#008000"># Prefer Codership repository </font>
    </p>
    <p>
      <font color="#008000">Package: * </font>
    </p>
    <p>
      <font color="#008000">Pin: origin releases.galeracluster.com </font>
    </p>
    <p>
      <font color="#008000">Pin-Priority: 1001 </font>
    </p>
    <p>
      <font color="#0000c0">vim apt-get update</font>&#160;&#160;# &#1063;&#1090;&#1086;&#1073;&#1099; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1084;&#1072;&#1085;&#1080;&#1092;&#1077;&#1089;&#1090;&#1099; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1080;&#1079; &#1085;&#1086;&#1074;&#1099;&#1093; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1077;&#1074;
    </p>
    <p>
      <b>&#1064;&#1072;&#1075; 2.&#160;&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; MySQL &#1080; Galera &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1093;</b>
    </p>
    <p>
      <font color="#0000c0">apt-get install galera-3 galera-arbitrator-3 mysql-wsrep-5.6</font>&#160;&#160;# &#1053;&#1072; &#1074;&#1089;&#1077;&#1093; &#1090;&#1088;&#1077;&#1093; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1093; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074;&#1077;&#1088;&#1089;&#1080;&#1102; MySQL, &#1080;&#1089;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1091;&#1102; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089; Galera, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; Galera &#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1077;&#1081;
    </p>
    <p>
      apt-get install rsync&#160;&#160;# &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; rsync &#1085;&#1072; &#1090;&#1088;&#1077;&#1093; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1093;
    </p>
    <p>
      <b>&#1064;&#1072;&#1075; 3.&#160;&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1085;&#1086;&#1076;&#1099;</b>
    </p>
    <p>
      &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1091;&#1079;&#1077;&#1083; &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1080;&#1084;&#1077;&#1090;&#1100; &#1087;&#1086;&#1095;&#1090;&#1080; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1095;&#1085;&#1091;&#1102; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;. C&#1076;&#1077;&#1083;&#1072;&#1077;&#1084; &#1074;&#1089;&#1102; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; &#1085;&#1072; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1077;, &#1072; &#1079;&#1072;&#1090;&#1077;&#1084; &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1077;&#1084; &#1077;&#1077; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1091;&#1079;&#1083;&#1099;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; MySQL &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085; &#1085;&#1072; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1091; <b>/etc/mysql/conf.d</b>&#160;&#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1080;&#1079; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;, &#1086;&#1082;&#1072;&#1085;&#1095;&#1080;&#1074;&#1072;&#1102;&#1097;&#1080;&#1093;&#1089;&#1103; &#1085;&#1072; <b>.cnf</b>. C&#1086;&#1079;&#1076;&#1072;&#1076;&#1080;&#1084; &#1092;&#1072;&#1081;&#1083; &#1074; &#1101;&#1090;&#1086;&#1084; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1077; &#1089;&#1086; &#1074;&#1089;&#1077;&#1084;&#1080; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1074;&#1072;&#1084;&#1080;, &#1089;&#1087;&#1077;&#1094;&#1080;&#1092;&#1080;&#1095;&#1085;&#1099;&#1084;&#1080; &#1076;&#1083;&#1103; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;:
    </p>
    <p>
      <font color="#0000c0">vim /etc/mysql/conf.d/galera.cnf</font>
    </p>
    <p>
      <font color="#008000">[mysqld]</font>&#160;&#160;# &#1053;&#1091;&#1078;&#1085;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;, &#1082;&#1072;&#1089;&#1072;&#1102;&#1097;&#1080;&#1077;&#1089;&#1103; ip &#1080; &#1080;&#1084;&#1077;&#1085;&#1080; &#1085;&#1086;&#1076;&#1099;
    </p>
    <p>
      <font color="#008000">binlog_format=ROW </font>
    </p>
    <p>
      <font color="#008000">default-storage-engine=innodb </font>
    </p>
    <p>
      <font color="#008000">innodb_autoinc_lock_mode=2 </font>
    </p>
    <p>
      <font color="#008000">bind-address=0.0.0.0 </font>
    </p>
    <p>
      <font color="#008000"># Galera Provider Configuration </font>
    </p>
    <p>
      <font color="#008000">wsrep_on=ON </font>
    </p>
    <p>
      <font color="#008000">wsrep_provider=/usr/lib/galera/libgalera_smm.so </font>
    </p>
    <p>
      <font color="#008000"># Galera Cluster Configuration </font>
    </p>
    <p>
      <font color="#008000">wsrep_cluster_name=&quot;test_cluster&quot; </font>
    </p>
    <p>
      <font color="#008000">wsrep_cluster_address=&quot;gcomm://<b>first_ip,second_ip,third_ip</b>&quot; </font>
    </p>
    <p>
      <font color="#008000"># Galera Synchronization Configuration </font>
    </p>
    <p>
      <font color="#008000">wsrep_sst_method=rsync </font>
    </p>
    <p>
      <font color="#008000"># Galera Node Configuration </font>
    </p>
    <p>
      <font color="#008000">wsrep_node_address=&quot;<b>this_node_ip</b>&quot; </font>
    </p>
    <p>
      <font color="#008000">wsrep_node_name=&quot;<b>this_node_name</b>&quot;</font>
    </p>
    <p>
      <b>&#1064;&#1072;&#1075; 4. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1086;&#1089;&#1090;&#1072;&#1074;&#1096;&#1080;&#1093;&#1089;&#1103; &#1085;&#1086;&#1076;</b>
    </p>
    <p>
      <font color="#0000c0">vim /etc/mysql/conf.d/galera.cnf </font>&#160;# &#1053;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1080;&#1079; &#1086;&#1089;&#1090;&#1072;&#1074;&#1096;&#1080;&#1093;&#1089;&#1103; &#1091;&#1079;&#1083;&#1086;&#1074; &#1086;&#1090;&#1082;&#1088;&#1086;&#1081;&#1090;&#1077; &#1092;&#1072;&#1081;&#1083; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;. &#1042;&#1089;&#1090;&#1072;&#1074;&#1100;&#1090;&#1077; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;, &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1091;&#1102; &#1089; &#1087;&#1077;&#1088;&#1074;&#1086;&#1075;&#1086; &#1091;&#1079;&#1083;&#1072;, &#1079;&#1072;&#1090;&#1077;&#1084; &#1086;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1077; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; &#1091;&#1079;&#1083;&#1072;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1080;&#1083;&#1080; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1084;&#1086;&#1077; &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103; &#1076;&#1083;&#1103; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1075;&#1086; &#1091;&#1079;&#1083;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1074;&#1099; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1077;. &#1048;, &#1085;&#1072;&#1082;&#1086;&#1085;&#1077;&#1094;, &#1086;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1077; &#1077;&#1075;&#1086; &#1080;&#1084;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1083;&#1102;&#1073;&#1086;&#1081; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;, &#1087;&#1086;&#1084;&#1086;&#1075;&#1072;&#1102;&#1097;&#1077;&#1081; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1091;&#1079;&#1077;&#1083; &#1074; &#1092;&#1072;&#1081;&#1083;&#1072;&#1093; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072;
    </p>
    <p>
      <font color="#008000"><b>. . .</b>&#160;</font>
    </p>
    <p>
      <font color="#008000"># Galera Node Configuration </font>
    </p>
    <p>
      <font color="#008000">wsrep_node_address=&quot;<b>this_node_ip</b>&quot; </font>
    </p>
    <p>
      <font color="#008000">wsrep_node_name=&quot;<b>this_node_name</b>&quot; </font>
    </p>
    <p>
      <font color="#008000"><b>. . .</b>&#160;</font>
    </p>
    <p>
      <b>&#1064;&#1072;&#1075; 5. &#1047;&#1072;&#1087;&#1091;&#1089;&#1082; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;. </b>
    </p>
    <p>
      <font color="#0000c0">systemctl stop mysql</font>&#160;&#160;# &#1054;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1097;&#1091;&#1102; &#1089;&#1083;&#1091;&#1078;&#1073;&#1091; MySQL &#1085;&#1077; &#1074;&#1089;&#1077;&#1093; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1093;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1072;&#1096; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088; &#1084;&#1086;&#1078;&#1085;&#1086; &#1073;&#1099;&#1083;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1082; &#1089;&#1077;&#1090;&#1080;
    </p>
    <p>
      <font color="#0000c0">/etc/init.d/mysql start --wsrep-new-cluster</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077; &#1085;&#1072; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1085;&#1086;&#1076;&#1077;
    </p>
    <p>
      <font color="#0000c0">systemctl start mysql</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077; &#1085;&#1072; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1085;&#1086;&#1076;&#1072;&#1093;
    </p>
    <p>
      <font color="#0000c0">mysql -u root -p -e &quot;SHOW STATUS LIKE 'wsrep_cluster_size'&quot;</font>&#160; &#160;# &#1055;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1095;&#1080;&#1089;&#1083;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074; &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077;
    </p>
  </body>
