        &#1079;&#1072;&#1097;&#1080;&#1090;&#1072; &#1086;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1081; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1080; &#171;split brain&#187; &#8211; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1074;&#1079;&#1074;&#1077;&#1096;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1086;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;. &#1044;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077;&#1095;&#1105;&#1090;&#1085;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1091;&#1079;&#1083;&#1086;&#1074; &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077; &#1080;&#1083;&#1080; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1100; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084;&#1091; &#1091;&#1079;&#1083;&#1091; &#1077;&#1075;&#1086; &#171;&#1074;&#1077;&#1089;&#187; - &#1095;&#1080;&#1089;&#1083;&#1086;, &#1090;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1085;&#1080; &#1074; &#1082;&#1072;&#1082;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1085;&#1091;&#1090;&#1100; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1080;, &#1095;&#1090;&#1086; &#1087;&#1088;&#1080; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1080; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1072; &#1091;&#1079;&#1083;&#1086;&#1074; &#1085;&#1072; &#1076;&#1074;&#1077; &#1095;&#1072;&#1089;&#1090;&#1080;, &#1089;&#1091;&#1084;&#1084;&#1072; &#1074;&#1077;&#1089;&#1086;&#1074; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074; &#1086;&#1073;&#1077;&#1080;&#1093; &#1095;&#1072;&#1089;&#1090;&#1103;&#1093; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#10