    <p>
      <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072; Galera &#1085;&#1072; MariaDB 10.1 &#1074; Ubuntu 16.04</b>
    </p>
    <ul>
      <li>
        &#1052;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084; &#1076;&#1074;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; (&#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1086;&#1073;&#1083;&#1072;&#1095;&#1085;&#1099;&#1077; &#1080;&#1083;&#1080; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077;). &#1044;&#1083;&#1103; &#1087;&#1088;&#1086;&#1084;&#1099;&#1096;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1081;&#1090;&#1077; &#1095;&#1077;&#1090;&#1099;&#1088;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; (&#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1084;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084; &#1090;&#1088;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;)
