    <ul>
      <li>
        &#1053;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; 10.1, <b>MariaDB &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1103;&#1077;&#1090; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; MariaDB Server &#1080; MariaDB Galera Server &#1074; &#1086;&#1076;&#1080;&#1085; &#1087;&#1072;&#1082;&#1077;&#1090;</b>. &#1055;&#1086;&#1090;&#1086;&#1084;&#1091; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; mariadb-server &#8211; Galera &#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1077;&#1081; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1103;&#1090;&#1089;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;
      </li>
      <li>
        &#1042;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1087;&#1088;&#1077;&#1076;&#1083;&#1086;&#1078;&#1080;&#1090; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072; MariaDB. &#1053;&#1077;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086; &#1086;&#1090; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082;&#1086;&#1081; &#1074;&#1099; &#1074;&#1099;&#1073;&#1077;&#1088;&#1077;&#1090;&#1077; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1086;&#1085; <b>&#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1084; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1085;&#1086;&#1076;&#1099; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;</b>
