    </p>
    <p>
      <font color="#0000c0">mysql -u <b>debian-sys-maint</b>&#160;-p</font>&#160;&#160;#&#160;&#160;&#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1077;&#1089;&#1100; &#1082; mysql. &#1059;&#1082;&#1072;&#1078;&#1080;&#1090;&#1077; &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1086; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086;, &#1079;&#1085;&#1072;&#1095;&#1080;&#1090;, &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1072; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;. &#1045;&#1089;&#1083;&#1080; &#1078;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1077; &#1091;&#1076;&#1072;&#1083;&#1086;&#1089;&#1100;, &#1091;&#1073;&#1077;&#1076;&#1080;&#1090;&#1077;&#1089;&#1100;, &#1095;&#1090;&#1086; &#1101;&#1090;&#1086;&#1090; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1085;&#1086;&#1076;&#1077;, &#1072; &#1079;&#1072;&#1090;&#1077;&#1084; &#1074;&#1089;&#1090;&#1072;&#1074;&#1100;&#1090;&#1077; &#1077;&#1075;&#1086; &#1074; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091;: update mysql.user set password=PASSWORD('password_from_debian.cnf') where User='debian-sys-maint'; &#1057;&#1085;&#1086;&#1074;&#1072; &#1087;&#1086;&#1087;&#1088;&#1086;&#1073;&#1091;&#1081;&#1090;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;.
    </p>
    <p>
      <b>&#1064;&#1072;&#1075; 8. &#1058;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;</b>
    </p>
    <p>
      <b>8.1 &#1042;&#1085;&#1077;&#1089;&#1080;&#1090;&#1077; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074; &#1041;&#1044; &#1085;&#1072; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1085;&#1086;&#1076;&#1077;</b>. &#1057;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1089;&#1086;&#1079;&#1076;&#1072;&#1076;&#1091;&#1090; &#1041;&#1044; playground &#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; equipment.
    </p>
    <p>
      <font color="#0000c0">mysql -u root -p -e 'CREATE DATABASE playground; </font>
    </p>
    <p>
      <font color="#0000c0">CREATE TABLE playground.equipment ( id INT NOT NULL AUTO_INCREMENT, type VARCHAR(50), quant INT, color VARCHAR(25), PRIMARY KEY(id)); </font>
    </p>
    <p>
      <font color="#0000c0">INSERT INTO playground.equipment (type, quant, color) VALUES (&quot;slide&quot;, 2, &quot;blue&quot;);'</font>
    </p>
    <p>
      <b>8.2 &#1055;&#1077;&#1088;&#1077;&#1081;&#1076;&#1080;&#1090;&#1077; &#1085;&#1072; &#1074;&#1090;&#1086;&#1088;&#1091;&#1102; &#1085;&#1086;&#1076;&#1091;</b>&#160;&#1080; &#1091;&#1073;&#1077;&#1076;&#1080;&#1090;&#1077;&#1089;&#1100;, &#1095;&#1090;&#1086; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1102;:
    </p>
    <p>
      <font color="#0000c0">mysql -u root -p -e 'SELECT * FROM playground.equipment;'&#160;&#160;# </font>&#1045;&#1089;&#1083;&#1080; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;, &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;, &#1074;&#1074;&#1077;&#1076;&#1105;&#1085;&#1085;&#1099;&#1077; &#1085;&#1072; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1085;&#1086;&#1076;&#1077;, &#1087;&#1086;&#1103;&#1074;&#1103;&#1090;&#1089;&#1103; &#1074; &#1041;&#1044; &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#1085;&#1086;&#1076;&#1099;.
    </p>
    <p>
      <font color="#0000c0">mysql -u root -p -e 'INSERT INTO playground.equipment (type, quant, color) VALUES (&quot;swing&quot;, 10, &quot;yellow&quot;);' </font>&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1100;&#1090;&#1077; &#1085;&#1086;&#1074;&#1099;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;
    </p>
    <p>
      <b>8.3 &#1055;&#1077;&#1088;&#1077;&#1081;&#1076;&#1080;&#1090;&#1077; &#1085;&#1072; &#1090;&#1088;&#1077;&#1090;&#1100;&#1102; &#1085;&#1086;&#1076;&#1091; &#1080; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1090;&#1077; &#1041;&#1044;.</b>&#160;
    </p>
    <p>
      <font color="#0000c0">mysql -u root -p -e 'SELECT * FROM playground.equipment;'&#160;&#160;# &#1044;&#1086;&#1083;&#1078;&#1085;&#1099; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;, &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1089; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1080; &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#1085;&#1086;&#1076;&#1099;</font>
    </p>
    <p>
      <font color="#0000c0">mysql -u root -p -e 'INSERT INTO playground.equipment (type, quant, color) VALUES (&quot;seesaw&quot;, 3, &quot;green&quot;);'</font>&#160;&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1100;&#1090;&#1077; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1085;&#1086;&#1074;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <b>8.4 &#1042;&#1077;&#1088;&#1085;&#1080;&#1090;&#1077;&#1089;&#1100; &#1085;&#1072; &#1087;&#1077;&#1088;&#1074;&#1091;&#1102; &#1085;&#1086;&#1076;&#1091;.</b>&#160;
    </p>
    <p>
      <font color="#0000c0">mysql -u root -p -e 'SELECT * FROM playground.equipment;' </font>&#160;# &#1047;&#1072;&#1087;&#1088;&#1086;&#1089;&#1080;&#1090;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1041;&#1044;. &#1059;&#1076;&#1086;&#1089;&#1090;&#1086;&#1074;&#1077;&#1088;&#1100;&#1090;&#1077;&#1089;&#1100; &#1095;&#1090;&#1086; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1085;&#1086;&#1076;&#1072;&#1084;&#1080; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Подготовка" FOLDED="true" ID="ID_576701309" CREATED="1551613544262" MODIFIED="1729155229898"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_713314125">Установка Galera Cluster на MySQL</a>
    </p>
    <ul>
      <li>
        необходимость <b>отключения Query Cache</b>&#xa0;(в итоге, при переходе с одиночного сервера БД на кластерный вариант, скорость чтения сложных запросов падает в разы. А нагрузка на сервер, соизмеримо возрастает)
      </li>
      <li>
        <b>Кеша не должно быть много</b>. Самый большой размер, который вообще стоит устанавливать, это не более 512МБ. Вот почему: <b>Если в любой из таблиц, выборка из которой есть в кеше, проиcходят изменения (вставка или изменение строк), то MySQL удаляет из кеша такие выборки</b>. Такой подход ускоряет работу MySQL, но может быть неэффективным для систем с большим количеством запросов на изменение таблиц. Это приводит к тому, что таблицы просто блокируются в режиме <b>Waiting for query cache lock</b>
      </li>
    </ul>
    <p>
      <b>1. Подготовка</b>
    </p>
    <p>
      Если мы переводим одиночную инсталяцию MySQL в кластерное исполнение:
    </p>
    <p>
      1.1 Убедимся что все наши БД не содержат таблиц с движком MyISAM. <a href="#ID_699557177">Устранить</a>
    </p>
    <p>
      <span style="color: #008000;">SELECT table_schema, table_name FROM INFORMATION_SCHEMA.TABLES WHERE engine = 'myisam'; </span>
    </p>
    <p>
      1.2 Убедимся что у всех таблиц в наших БД есть первичные ключи. <a href="#ID_847349686">Устранить</a>
    </p>
    <p>
      <span style="color: #008000;">SELECT table_catalog, table_schema, table_name, engine </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;FROM information_schema.tables </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;WHERE (table_catalog, table_schema, table_name) NOT IN </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;(SELECT table_catalog, table_schema, table_name </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;FROM information_schema.table_constraints </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;WHERE constraint_type = 'PRIMARY KEY') </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;AND table_schema NOT IN ('information_schema', 'pg_catalog');</span>
    </p>
    <p>
      
    </p>
    <p>
      Отключить selinux - это требование разработчиков MariaDB
    </p>
    <p>
      <span style="color: #0000c0;">sed -i 's/SELINUX=enforcing/SELINUX=disabled/g' /etc/selinux/config </span>
    </p>
    <p>
      <span style="color: #0000c0;">echo 0 &gt; /selinux/enforce</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>На всех нодах, должно быть правильно установленно время, это обязательно.</b>&#xa0;&#xa0;Иначе вы столкнётесь с тем что, при SST ноды с донора, синхронизируемая нода будет просто чего-то ждать, без каких бы то ни было признаком активности.
    </p>
    <p>
      <span style="color: #0000c0;">yum install ntp -y </span>
    </p>
    <p>
      <span style="color: #0000c0;">chkconfig ntpd on </span>
    </p>
    <p>
      <span style="color: #0000c0;">/etc/init.d/ntpd stop </span>
    </p>
    <p>
      <span style="color: #0000c0;">ntpdate&#xa0;&#xa0;165.193.126.229 0.ru.pool.ntp.org 1.ru.pool.ntp.org 2.ru.pool.ntp.org 3.ru.pool.ntp.org </span>
    </p>
    <p>
      <span style="color: #0000c0;">/etc/init.d/ntpd start</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="1.1" ID="ID_699557177" CREATED="1551613963791" MODIFIED="1551777132834"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1044;&#1083;&#1103; &#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1103; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099; &#1077;&#1089;&#1090;&#1100; 2 &#1087;&#1091;&#1090;&#1080;:
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090; 1</b>
    </p>
    <p>
      <font color="#0000c0">mysql &#1080;&#1084;&#1103;_&#1073;&#1072;&#1079;&#1099;_&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; -e &quot;show table status where Engine='MyISAM';&quot; | awk 'NR&gt;1 {print &quot;ALTER TABLE &quot;$1&quot; ENGINE = InnoDB;&quot;}' | mysql &#1080;&#1084;&#1103;_&#1073;&#1072;&#1079;&#1099;_&#1076;&#1072;&#1085;&#1085;&#1099;&#1093;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090; 2</b>
    </p>
    <p>
      <font color="#0000c0">mysql &#1080;&#1084;&#1103;_&#1073;&#1072;&#1079;&#1099;_&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; -e &quot;show table status where Engine='MyISAM';&quot; | awk '{print $1}' | xargs -t -i pt-online-schema-change --alter-foreign-keys-method=auto --alter &quot;ENGINE=InnoDB&quot; --execute --statistics --set-vars=&quot;wait_timeout=10000,innodb_lock_wait_timeout=10,lock_wait_timeout=180&quot; --progress=time,1 D=&#1080;&#1084;&#1103;_&#1073;&#1072;&#1079;&#1099;_&#1076;&#1072;&#1085;&#1085;&#1099;&#1093;,t={}</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1076;&#1086;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086;-&#1090;&#1072;&#1082;&#1080; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;. &#1040; &#1074;&#1086;&#1090; &#1089; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1084;&#1080; &#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1072;&#1102;&#1090; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099;. &#1058;&#1072;&#1082; &#1082;&#1072;&#1082; &#1082;&#1086;&#1085;&#1074;&#1077;&#1088;&#1090;&#1072;&#1094;&#1080;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1076;&#1086;&#1083;&#1075;&#1086;, &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1072; &#1080; &#1074;&#1089;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080; &#1089; &#1085;&#1077;&#1081; &#1089;&#1090;&#1072;&#1085;&#1091;&#1090; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1099;&#1084;&#1080;, &#1095;&#1090;&#1086; &#1085;&#1077;&#1087;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086; &#1089;&#1082;&#1072;&#1078;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1080; &#1091;&#1089;&#1083;&#1091;&#1075;/&#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1086;&#1074;. &#1044;&#1083;&#1103; &#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1103; &#1101;&#1090;&#1086;&#1081; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099; &#1085;&#1072;&#1084; &#1087;&#1086;&#1084;&#1086;&#1078;&#1077;&#1090; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; pt-online-schema-change &#1080;&#1079; &#1082;&#1086;&#1084;&#1087;&#1083;&#1077;&#1082;&#1090;&#1072; percona-toolkit.
    </p>
    <p>
      
    </p>
    <p>
      &#1057;&#1090;&#1072;&#1074;&#1080;&#1090;&#1089;&#1103; &#1101;&#1090;&#1072; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; &#1080;&#1079; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1072;&#1088;&#1080;&#1103; &#1076;&#1083;&#1103; CentOS:
    </p>
    <p>
      <font color="#0000c0">rpm -Uhv http://www.percona.com/downloads/percona-release/percona-release-0.0-1.x86_64.rpm</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1042;&#1072;&#1078;&#1085;&#1086; &#1053;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1091; &#1082;&#1086;&#1085;&#1074;&#1077;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;&#1086;&#1081; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1073;&#1099;&#1083; &#1080;&#1083;&#1080; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1099;&#1081; (PRIMARY), &#1080;&#1083;&#1080; &#1091;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; (UNIQUE) &#1082;&#1083;&#1102;&#1095;, &#1080;&#1085;&#1072;&#1095;&#1077; &#1074;&#1099;&#1076;&#1072;&#1089;&#1090; &#1086;&#1096;&#1080;&#1073;&#1082;&#1091;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1090;&#1072;&#1082;&#1091;&#1102;:
    </p>
    <p>
      <font size="1">Cannot chunk the original table `database`.`NAMETABLE01_NOKEY`: There is no good index and the table is oversized. at /usr/bin/pt-online-schema-change line 5442.</font>
    </p>
  </body>
</html></richcontent>
