<node TEXT="Балансировка трафика" ID="ID_1083349475" CREATED="1551777309029" MODIFIED="1574839991834"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1041;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077; Galera</b>
    </p>
    <p>
      
