      &#1069;&#1090;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1103;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086; &#1084;&#1077;&#1088;&#1077; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1103; &#1085;&#1086;&#1074;&#1099;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;. &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1074;&#1099; &#1091;&#1073;&#1077;&#1076;&#1080;&#1083;&#1080;&#1089;&#1100;, &#1095;&#1090;&#1086; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1097;&#1080;&#1082; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1084;&#1080; &#1073;&#1101;&#1082;&#1101;&#1085;&#1076;&#1072;.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Миграция" ID="ID_1105888587" CREATED="1551783677433" MODIFIED="1551783696667"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      ----------------------------------------------------
    </p>
    <p>
      &#1042;&#1099; &#1084;&#1086;&#1078;&#1077;&#1090;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1084;&#1080;&#1075;&#1088;&#1072;&#1094;&#1080;&#1102; &#1080;&#1079; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1099; MariaDB &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1085;&#1091;&#1102; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1091; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;:
    </p>
    <p>
      ## &#1053;&#1072; &#1089;&#1090;&#1072;&#1088;&#1086;&#1084; MariaDB &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;##
    </p>
    <p>
      ## &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077; &#1076;&#1072;&#1084;&#1087; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; foobar &#1073;&#1077;&#1079; &#1076;&#1074;&#1080;&#1078;&#1082;&#1072; ##
    </p>
    <p>
      $ mysqldump -u root -p --skip-create-options foobar &gt; foobar.sql
    </p>
    <p>
      ## &#1050;&#1086;&#1087;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; foobar.sql &#1085;&#1072; &#1083;&#1102;&#1073;&#1091;&#1102; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1085;&#1091;&#1102; &#1085;&#1086;&#1076;&#1091;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; mdb02 ##
    </p>
    <p>
      $ scp foobar.sql 192.168.2.46:/root/
    </p>
    <p>
      ## &#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1077; &#1041;&#1044;, &#1085;&#1072; mdb02 ##
    </p>
    <p>
      $ mysql -u root -p foobar &lt; foobar.sql
    </p>
  </body>
</html></richcontent>
</node>
</node>
</node>
<node TEXT="Комментарии" ID="ID_1015500396" CREATED="1724329872800" MODIFIED="1764659091759"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Комментарии </b>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">mysql&gt; SELECT 1+1;</span>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;<b>#</b>&#xa0;Этот комментарий продолжается до конца строки
    </p>
    <p>
      <span style="color: #0000c0;">mysql&gt; SELECT 1+1;</span>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;<b>--</b>&#xa0;Этот комментарий продолжается до конца строки
    </p>
    <p>
      <span style="color: #0000c0;">mysql&gt; SELECT 1</span>&#xa0;<b>/*</b>&#xa0;Это комментарий в строке <b>*/</b>&#xa0;<span style="color: #0000c0;">+ 1;</span>
    </p>
    <p>
      <span style="color: #0000c0;">mysql&gt; SELECT 1+</span>
    </p>
    <p>
      <b>/*</b>
    </p>
    <p>
      Это многострочный
    </p>
    <p>
      комментарий
    </p>
    <p>
      <b>*/</b>
    </p>
    <p>
      <span style="color: #0000c0;">1; </span>
    </p>
  </body>
</html></richcontent>
</node>
