<node TEXT="Улучшение производительности MySQL" ID="ID_573375955" CREATED="1542447180530" MODIFIED="1542447303939"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1057;&#1082;&#1088;&#1080;&#1087;&#1090; MySQL Tuner -&#160;&#160;&#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1072;&#1094;&#1080;&#1080; &#1087;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1077; MySQL &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080;.
    </p>
    <ul>
      <li>
        &#1055;&#1077;&#1088;&#1077;&#1076; &#1090;&#1077;&#1084; &#1082;&#1072;&#1082; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;, &#1076;&#1072;&#1081;&#1090;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1087;&#1086;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1085;&#1077; &#1084;&#1077;&#1085;&#1077;&#1077; &#1095;&#1077;&#1084; 24 &#1095;&#1072;&#1089;&#1072;. &#1063;&#1077;&#1084; &#1076;&#1086;&#1083;&#1100;&#1096;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1088;&#1077;&#1084;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099;, &#1090;&#1077;&#1084; &#1090;&#1086;&#1095;&#1085;&#1077;&#1077; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1080;
      </li>
    </ul>
    <p>
      &#1057;&#1082;&#1072;&#1095;&#1072;&#1081;&#1090;&#1077; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;:
    </p>
    <p>
      <font color="#0000c0">wget https://raw.githubusercontent.com/major/MySQLTuner-perl/master/mysqltuner.pl</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1047;&#1072;&#1090;&#1077;&#1084; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077;:
    </p>
    <p>
      <font color="#0000c0">perl ./mysqltuner.pl</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1074;&#1072;&#1084; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1077;&#1076;&#1083;&#1086;&#1078;&#1077;&#1085;&#1086; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1089;&#1091;&#1087;&#1077;&#1088;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1072; &#1079;&#1072;&#1090;&#1077;&#1084; &#1074;&#1099;&#1074;&#1077;&#1076;&#1077;&#1085; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1072;&#1094;&#1080;&#1081; &#1087;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1077; &#1080; &#1079;&#1072;&#1084;&#1077;&#1095;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080;. &#1069;&#1090;&#1086; &#1086;&#1090;&#1083;&#1080;&#1095;&#1085;&#1072;&#1103; &#1090;&#1086;&#1095;&#1082;&#1072; &#1076;&#1083;&#1103; &#1086;&#1087;&#1090;&#1080;&#1084;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
    </p>
  </body>
</html></richcontent>
