    </p>
    <p>
      <b>my.ini </b>(Program Files\MySQL Server 5.1\)&#160;- &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1092;&#1072;&#1081;&#1083; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;. &#1054;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; ini &#1092;&#1072;&#1081;&#1083;&#1099; &#1074; &#1101;&#1090;&#1086;&#1081; &#1087;&#1072;&#1087;&#1082;&#1077; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1099; &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;&#1072; (&#1076;&#1077;&#1084;&#1086; &#1092;&#1072;&#1081;&#1083;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1072; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090;)
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1087;&#1077;&#1088;&#1077;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; <b>my-default.ini</b>&#160; &#1074; <b>my.ini</b>, &#1090;&#1086; &#1086;&#1085; &#1089;&#1090;&#1072;&#1085;&#1077;&#1090; &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;&#1086;&#1084;
