    </p>
    <p>
      &#1063;&#1090;&#1086;&#1073;&#1099; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1089;&#1077;&#1072;&#1085;&#1089; &#1085;&#1077; &#1079;&#1072;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1085;&#1077;&#1089;&#1090;&#1080; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075; (<b>my.ini</b>).
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1050;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080;. </b>&#1054;&#1076;&#1085;&#1072;&#1082;&#1086; &#1074; &#1083;&#1086;&#1075;&#1080; &#1082;&#1080;&#1088;&#1080;&#1083;&#1080;&#1094;&#1072; &#1087;&#1080;&#1096;&#1077;&#1090;&#1089;&#1103; &#1082;&#1088;&#1080;&#1074;&#1086; (&#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1086;&#1087;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; phpMyAdmin)
