    </p>
    <p>
      3.2 &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1087;&#1082;&#1091; mysql\<b>logs</b>&#160;&#1076;&#1083;&#1103; log-&#1092;&#1072;&#1081;&#1083;&#1086;&#1074;
    </p>
    <p>
      3.3 &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1087;&#1082;&#1091; mysql\<b>tmp</b>&#160;&#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;
    </p>
    <p>
      3.4 &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1087;&#1082;&#1091; mysql\<b>files</b>&#160;&#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;
    </p>
    <p>
      4. &#1055;&#1077;&#1088;&#1077;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; MySQL\bin\<b>my-default</b>&#160;&#1074; ...\<b>my.ini</b>&#160;&#1080; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1091;&#1077;&#1084; <a href="#ID_131043325">&#1076;&#1083;&#1103; &#1080;&#1085;&#1080;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;</a>
    </p>
    <p>
      5. <font color="#0000c0">&gt; mysqld --initialize --console</font>&#160;&#160;# &#1048;&#1085;&#1080;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; MySQL &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1089; &#1074;&#1099;&#1074;&#1086;&#1076;&#1086;&#1084; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1074; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077;. &#1042;&#1099;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; &#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; MySQL &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; (&#1089;&#1086;&#1093;&#1088;. &#1074; &#1073;&#1083;&#1086;&#1082;&#1085;&#1086;&#1090;). &#1045;&#1089;&#1083;&#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1087;&#1086;&#1090;&#1077;&#1088;&#1103;&#1085; &#1089;&#1084;. <a href="#ID_255242524">&#1057;&#1073;&#1088;&#1086;&#1089; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;</a>
    </p>
    <p>
      6. <font color="#0000c0">&gt; mysqld --console</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1082; MySQL &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1089; &#1074;&#1099;&#1074;&#1086;&#1076;&#1086;&#1084; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082; &#1085;&#1072; &#1101;&#1082;&#1088;&#1072;&#1085;
    </p>
    <p>
      7. &#1056;&#1072;&#1089;&#1087;&#1072;&#1082;&#1086;&#1074;&#1072;&#1090;&#1100; <b>MySQL Workbench</b>&#160;+ <b>Microsoft Visual &#1057;++ 2013</b>&#160;+ <b>Microsoft .NET Framework 4.6.2</b>
    </p>
    <p>
      8. MySQL Workbench&#160;&gt; + &gt;
    </p>
    <p>
      &#160;&#160;Hostname: 127.0.0.1
    </p>
    <p>
      &#160;&#160;Username: root
    </p>
    <p>
      &#160;&#160;Password: Store in Vault
    </p>
    <p>
      &#160;&#160;&#1057;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1084;&#1086;&#1078;&#1085;&#1086; 2-&#1103; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1072;&#1084;&#1080;: <b>&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; Workbench</b>&#160;&#1080;&#1083;&#1080; <a href="#ID_255242524">&#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083;</a>&#160; &#1074; &#1082;&#1086;&#1088;&#1085;&#1077;&#1074;&#1086;&#1084; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1077; MySQL &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1090;&#1091;&#1076;&#1072; SQL-&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;
    </p>
    <p>
      &#160;&#160;&#1052;&#1077;&#1085;&#1103;&#1077;&#1084; &#1087;&#1091;&#1090;&#1080; &#1082; &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;&#1091;.&#160;&#160;<i>&#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; \ &#1050;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; \ Edit Connection \ System Profile \ Configuration File</i>
    </p>
    <p>
      9. &#1044;&#1083;&#1103; &#1091;&#1076;&#1086;&#1073;&#1089;&#1090;&#1074;&#1072; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; 2 &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <table border="0" style="width: 80%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p>
            mysql\<b>start.bat</b>
          </p>
          <p>
            <font color="#008000">@echo off </font>
          </p>
          <p>
            <font color="#008000">start C:\mysql\bin\mysqld </font>
          </p>
          <p>
            <font color="#008000">exit</font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            mysql\<b>stop.bat</b>&#160;(&#1077;&#1089;&#1083;&#1080; &#1091; &#1087;&#1086;&#1083;&#1100;&#1079;. &#1085;&#1077;&#1090; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;)
          </p>
          <p>
            <font color="#008000">@echo off </font>
          </p>
          <p>
            <font color="#008000">start C:\mysql\bin\mysqladmin -u root shutdown</font>
          </p>
          <p>
            <font color="#008000">exit</font>
          </p>
        </td>
      </tr>
    </table>
  </body>
</html></richcontent>
<node TEXT="my.ini (для инициализации)" ID="ID_131043325" CREATED="1529348233646" MODIFIED="1530262020799"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>[mysqld]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000"># C&#1083;&#1077;&#1096;&#1080; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; Unix, &#1077;&#1089;&#1083;&#1080; &#1087;&#1091;&#1090;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089; &#1087;&#1088;&#1086;&#1073;&#1077;&#1083;&#1072;&#1084;&#1080;, &#1090;&#1086; &#1079;&#1072;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1074; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1080; &quot; &quot; </font>
    </p>
    <p>
      <font color="#008000"># &#1047;&#1072;&#1076;&#1072;&#1090;&#1100; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1087;&#1088;&#1080;&#1085;&#1091;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; </font>
    </p>
    <p>
      <font color="#008000"><b>character-set-server</b>&#160;= utf8 </font>
    </p>
    <p>
      <font color="#008000"><b>collation-server</b>&#160;= utf8_general_ci </font>
    </p>
    <p>
      <font color="#008000"># &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; &#1079;&#1086;&#1085;&#1091; &#1087;&#1086; UTC </font>
    </p>
    <p>
      <font color="#008000"><b>default-time-zone</b>&#160;= '+00:00'</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># &#1047;&#1072;&#1076;&#1072;&#1090;&#1100; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1076;&#1074;&#1080;&#1078;&#1086;&#1082; </font>
    </p>
    <p>
      <font color="#008000"><b>default_tmp_storage_engine</b>&#160;= InnoDB </font>
    </p>
    <p>
      <font color="#008000"><b>default-storage-engine</b>&#160;= InnoDB </font>
    </p>
    <p>
      <font color="#008000"># &#1055;&#1091;&#1083; &#1076;&#1083;&#1103; &#1076;&#1074;&#1080;&#1078;&#1082;&#1072; innodb. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; 50% &#1086;&#1090; RAM. &#1044;&#1083;&#1103; &#1090;&#1077;&#1089;&#1090;&#1072; &#1087;&#1086;&#1081;&#1076;&#1077;&#1090; 128&#1052;&#1041; </font>
    </p>
    <p>
      <font color="#008000"><b>innodb_buffer_pool_size</b>&#160;= 128M&#160; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>basedir</b>&#160;= C:/mysql&#160; </font>
    </p>
    <p>
      <font color="#008000"><b>datadir</b>&#160;= C:/mysql/data </font>
    </p>
    <p>
      <font color="#008000"><b>port</b>&#160;= 3306 </font>
    </p>
    <p>
      <font color="#008000"><b>socket</b>=C:/mysql/tmp/mysql.sock </font>
    </p>
    <p>
      <font color="#008000"># IP-&#1072;&#1076;&#1088;&#1077;&#1089;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1089;&#1083;&#1091;&#1096;&#1080;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084; </font>
    </p>
    <p>
      <font color="#008000"><b>bind-address</b>=127.0.0.1 </font>
    </p>
    <p>
      <font color="#008000"># &#1055;&#1072;&#1087;&#1082;&#1072;, &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; MySQL &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1075;&#1091;&#1078;&#1072;&#1090;&#1100; &#1080; &#1074;&#1099;&#1075;&#1088;&#1091;&#1078;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083;&#1099; </font>
    </p>
    <p>
      <font color="#008000"><b>secure-file-priv</b>=C:/mysql/files</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># LOG </font>
    </p>
    <p>
      <font color="#008000"># MySQL &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1081; &#1083;&#1086;&#1075; &#1089;&#1074;&#1086;&#1080; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;. &#1059;&#1076;&#1086;&#1073;&#1085;&#1086; &#1076;&#1083;&#1103; Portable &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; </font>
    </p>
    <p>
      <font color="#008000"><b>log_syslog</b>=0&#160; </font>
    </p>
    <p>
      <font color="#008000"># &#1057;&#1102;&#1076;&#1072; &#1087;&#1080;&#1096;&#1077;&#1084; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; </font>
    </p>
    <p>
      <font color="#008000"><b>log_error</b>=C:/mysql/logs/mysql-error.log </font>
    </p>
    <p>
      <font color="#008000"># &#1044;&#1083;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1086; &#1084;&#1077;&#1076;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;&#1093; </font>
    </p>
    <p>
      <font color="#008000"><b>slow-query-log-file</b>=C:/mysql/logs/mysql-slow.log </font>
    </p>
    <p>
      <font color="#008000"># &#1059;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; &#1079;&#1086;&#1085;&#1091; &#1087;&#1088;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1074; log-&#1092;&#1072;&#1081;&#1083; </font>
    </p>
    <p>
      <font color="#008000"><b>log_timestamps</b>&#160;= UTC </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1076;&#1074;&#1080;&#1078;&#1082;&#1072; </font>
    </p>
    <p>
      <font color="#008000"><b>join_buffer_size</b>&#160;= 128M </font>
    </p>
    <p>
      <font color="#008000"><b>sort_buffer_size</b>&#160;= 2M </font>
    </p>
    <p>
      <font color="#008000"><b>read_rnd_buffer_size</b>&#160;= 2M </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># &#1056;&#1077;&#1078;&#1080;&#1084; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1081;, &#1085;&#1072; &#1090;&#1077;&#1089;&#1090;&#1086;&#1074;&#1086;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1083;&#1091;&#1095;&#1096;&#1077; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; </font>
    </p>
    <p>
      <font color="#008000">#<b>sql_mode</b>=NO_ENGINE_SUBSTITUTION,STRICT_TRANS_TABLES </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>[mysqld-5.7]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000"><b>sql_mode</b>=TRADITIONAL</font>
    </p>
  </body>
</html></richcontent>
</node>
