      <b>Checkpointer</b>&#160;- &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;. &#1087;&#1088;&#1086;&#1089;&#1099;&#1087;&#1072;&#1077;&#1090;&#1089;&#1103; --&gt; &#1080;&#1076;&#1077;&#1090; &#1074; Shared buffers --&gt; &#1080;&#1097;&#1077;&#1090; &#1075;&#1088;&#1103;&#1079;&#1085;&#1099;&#1077; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; --&gt; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1080;&#1079; &#1085;&#1072; &#1076;&#1080;&#1089;&#1082; --&gt; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1074; pg_control &#1092;&#1072;&#1081;&#1083; &#1080;&#1085;&#1092;. &#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1075;&#1086; checkpoint --&gt; fsync --&gt; &#1089;&#1090;&#1072;&#1088;&#1099;&#1077; pg_xlog &#1091;&#1076;&#1072;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103;.
    </p>
  </body>
</html></richcontent>
</node>
