<node TEXT="Autovacuum" ID="ID_1444252939" CREATED="1526381080201" MODIFIED="1527851215833"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Autovacuum </b>
    </p>
    <ul>
      <li>
        &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1090; &#1087;&#1086;&#1084;&#1077;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1085;&#1072; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080;. &#1044;&#1077;&#1083;&#1072;&#1077;&#1090; &#1086;&#1090;&#1084;&#1077;&#1090;&#1082;&#1091; &#1074; fsm (free space map). &#1054;&#1089;&#1074;&#1086;&#1073;&#1086;&#1078;&#1076;&#1077;&#1085;&#1085;&#1086;&#1077; &#1084;&#1077;&#1089;&#1090;&#1086; OS'&#1084;&#1077; &#1085;&#1077; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1102;&#1090;&#1089;&#1103;. &#1042;&#1086;&#1079;&#1074;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074; &#1101;&#1090;&#1086;&#1081; &#1078;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077;. &#1044;&#1083;&#1103; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090;&#1072; &#1084;&#1077;&#1089;&#1090;&#1072; &#1074; OS <font color="#ff0000">&#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1087;&#1088;&#1086;&#1073;&#1086;&#1074;&#1072;&#1090;</font>&#1100; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; <b>vacuum full (</b>&#1053;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1080;&#1073;&#1086; &#1073;&#1091;&#1076;&#1091;&#1090; &#1079;&#1072;&#1083;&#1086;&#1095;&#1077;&#1085;&#1099; &#1074;&#1089;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;)
      </li>
      <li>
        &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1076;&#1083;&#1103; &#1086;&#1087;&#1090;&#1080;&#1084;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;
      </li>
    </ul>
    <p>
      Autovacuum structs -&#160;&#160;&#1074; Shared memory
    </p>
    <p>
      Autovacuum launcher - &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; worker'&#1086;&#1074;
    </p>
    <p>
      Autovacuum&#160;&#160;worker - &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089; &#1076;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080;
    </p>
  </body>
</html></richcontent>
</node>
