<node TEXT="WAL" ID="ID_21916639" CREATED="1526381288537" MODIFIED="1527854784540"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1046;&#1091;&#1088;&#1085;&#1072;&#1083; (WAL)</b>
    </p>
    <p>
      &#1042; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083; &#1091;&#1087;&#1088;&#1077;&#1078;&#1076;&#1072;&#1102;&#1097;&#1077;&#1081; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; (<b>write-ahead log</b>) &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103;, &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1072;&#1103; &#1076;&#1083;&#1103; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1086;&#1075;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074;&#1089;&#1077;&#1093; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1081; &#1087;&#1088;&#1080; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1089;&#1073;&#1086;&#1103;
    </p>
    <ul>
      <li>
        &#1054;&#1073;&#1103;&#1079;&#1072;&#1085; &#1087;&#1086;&#1087;&#1072;&#1089;&#1090;&#1100; &#1085;&#1072; &#1076;&#1080;&#1089;&#1082; &#1088;&#1072;&#1085;&#1100;&#1096;&#1077;, &#1095;&#1077;&#1084; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1085;&#1099;&#1077; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;
      </li>
      <li>
        <p>
          <b>&#1050;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1072;&#1103; &#1090;&#1086;&#1095;&#1082;&#1072;</b>&#160; &#8211; &#1087;&#1088;&#1080;&#1085;&#1091;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1089;&#1073;&#1088;&#1086;&#1089; &#1085;&#1072; &#1076;&#1080;&#1089;&#1082; &#1074;&#1089;&#1077;&#1093; &#1075;&#1088;&#1103;&#1079;&#1085;&#1099;&#1093; &#1073;&#1091;&#1092;&#1077;&#1088;&#1086;&#1074;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1084;&#1085;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; - &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; <a href="#ID_461884801">checkpointer</a>
        </p>
      </li>
    </ul>
    <p>
      &#1055;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; <b>wal writer</b>
    </p>
    <ul>
      <li>
        &#1077;&#1089;&#1083;&#1080; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1084;&#1080;&#1090;, backend &#1087;&#1080;&#1096;&#1077;&#1090; xlog &#1073;&#1077;&#1079; fsync. &#1055;&#1080;&#1096;&#1077;&#1090; &#1074; Xlog Buffers. &#1054;&#1090;&#1090;&#1091;&#1076;&#1072; WAL writer &#1073;&#1077;&#1088;&#1077;&#1090; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1080; &#1089; fsync &#1087;&#1080;&#1096;&#1077;&#1090; &#1085;&#1072; &#1076;&#1080;&#1089;&#1082;
      </li>
      <li>
        &#1047;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1092;&#1080;&#1082;&#1089;&#1072;&#1094;&#1080;&#1080;, &#1083;&#1080;&#1073;&#1086; &#1072;&#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1085;&#1086; (&#1073;&#1099;&#1089;&#1090;&#1088;&#1077;&#1077;, &#1085;&#1086; &#1084;&#1077;&#1085;&#1077;&#1077; &#1085;&#1072;&#1076;&#1077;&#1078;&#1085;&#1086;)
      </li>
      <li>
        &#1057;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1092;&#1072;&#1081;&#1083;&#1099; (&#1087;&#1086; 16 &#1052;&#1041;) - &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099;, &#1089;&#1090;&#1072;&#1088;&#1099;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1072;&#1088;&#1093;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; - &#1055;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; <b>wal archiver</b>. &#1048;&#1083;&#1080; &#1087;&#1077;&#1088;&#1077;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;
      </li>
    </ul>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
