<node TEXT="--Shared memory" ID="ID_697234232" CREATED="1526379716362" MODIFIED="1527851215118"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Shared buffers, &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084;&#1072;&#1103; &#1087;&#1072;&#1084;&#1103;&#1090;&#1100; </b>
    </p>
    <ul>
      <li>
        Autovacuum structs - &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1077;&#1077;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1074;&#1089;&#1077;&#1093; &#1074;&#1086;&#1088;&#1082;&#1077;&#1088;&#1086;&#1074; &#1092;&#1086;&#1088;&#1082;&#1072;&#1083; postmaster, &#1080;&#1085;&#1092;. &#1079;&#1076;&#1077;&#1089;&#1100;.
      </li>
      <li>
        Multi-XACT buffers
      </li>
      <li>
        Shared invalidation - Backend &#1084;&#1077;&#1085;&#1103;&#1103; &#1095;&#1090;&#1086;-&#1090;&#1086; &#1074; RelCache, Catalog cache, Pkan cache - &#1082;&#1083;&#1072;&#1076;&#1077;&#1090; &#1089;&#1102;&#1076;&#1072; &#1080;&#1085;&#1092;. &#1086;&#1073; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103;&#1093;
      </li>
      <li>
        Bgwriter structs - &#1080;&#1085;&#1092;. &#1086; &#1090;&#1086;&#1084;, &#1082;&#1072;&#1082;&#1080;&#1077; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &#1089;&#1077;&#1081;&#1095;&#1072;&#1089; &#1087;&#1080;&#1096;&#1091;&#1090;&#1089;&#1103;
      </li>
      <li>
        ProcArray - &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081; &#1080;&#1085;&#1092;. &#1086; &#1074;&#1089;&#1077;&#1093; backend'&#1072;&#1093; (&#1085;&#1086;&#1084;&#1077;&#1088;&#1072;&#1093; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1081;, &#1073;&#1072;&#1079;&#1072;&#1093; &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084;&#1080; &#1086;&#1085;&#1080; &#1089;&#1077;&#1081;&#1095;&#1072;&#1089; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090;, &#1086; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;&#1093;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1086;&#1085;&#1080; &#1078;&#1076;&#1091;&#1090;)
      </li>
      <li>
        Locs info
      </li>
      <li>
        Xlog Buffers - &#1093;&#1088;&#1072;&#1085;&#1080;&#1090; &#1080;&#1085;&#1092;. &#1086; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1084; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1081; (&#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1080; &#1080;&#1093; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077;)
      </li>
      <li>
        Clog buffers
      </li>
      <li>
        Subtrans buffers
      </li>
      <li>
        Two-Phase stucts
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="--PGDATA directory" ID="ID_441754888" CREATED="1526380670293" MODIFIED="1527851214727"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>PGDATA directory</b>&#160;- &#1079;&#1076;&#1077;&#1089;&#1100; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1089;&#1103; &#1041;&#1044;
    </p>
    <ul>
      <li>
        based

        <ul>
          <li>
            &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;. &#1087;&#1086; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1091; &#1085;&#1072; &#1073;&#1072;&#1079;&#1091; (&#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1092;&#1072;&#1081;&#1083;&#1099; &#1087;&#1086; 1GB). &#1060;&#1072;&#1081;&#1083;&#1099; &#1087;&#1086; 1GB &#1088;&#1072;&#1079;&#1073;&#1080;&#1090;&#1099; &#1085;&#1072; 8KB &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;.
          </li>
          <li>
            &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099;

            <ul>
              <li>
                fsm (free space map) - &#1080;&#1085;&#1092;&#1086; &#1086; &#1089;&#1074;&#1086;&#1073;&#1086;&#1076;&#1085;&#1099;&#1093; &#1082;&#1091;&#1089;&#1082;&#1072;&#1093;
              </li>
              <li>
                vm (visability map) - &#1076;&#1083;&#1103; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084;&#1072;
              </li>
            </ul>
          </li>
        </ul>
      </li>
      <li>
        pg_xlog (REDO log)

        <ul>
          <li>
            &#1092;&#1072;&#1081;&#1083;&#1099; &#1087;&#1086; 16MB
          </li>
          <li>
            &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
          </li>
        </ul>
      </li>
      <li>
        global

        <ul>
          <li>
            pg_control
          </li>
        </ul>
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Версии" ID="ID_1133100993" CREATED="1527850358913" MODIFIED="1729080606167"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Версии системы</b>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">dpkg -l | grep postgresql</span>
    </p>
    <p>
      <span style="color: #0000c0;">psql -V&#xa0;</span>&#xa0;# или --version
    </p>
    <p>
      <span style="color: #008000;">SELECT version(); </span>
    </p>
    <p>
      <span style="color: #008000;">SHOW server_version;</span>
    </p>
    <p>
      
    </p>
    <p>
      Нумерация версий PostgreSQL: 9.4.4
    </p>
    <ul>
      <li>
        Мажорная версия – 9.4, минорная – 4.
      </li>
      <li>
        <b>Мажорная версия</b>&#xa0;&#xa0;– добавление новой функциональности
      </li>
      <li>
        <b>Минорная версия</b>&#xa0;&#xa0;– исправление ошибок
      </li>
      <li>
        Для использования рекомендуется последняя минорная версия
      </li>
      <li>
        PGDG выполняет поддержку мажорных версий в течении 5 лет
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Структура каталога данных" ID="ID_1184768879" CREATED="1736326394767" MODIFIED="1736326488273"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      
    </p>
    <p>
      /var/lib/postgresql/14/main/
    </p>
    <p>
