<node TEXT="При запуске сервера" ID="ID_1395231340" CREATED="1528617010892" MODIFIED="1529097384772"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1087;&#1088;&#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">$ pg_ctl start -o</font>
    </p>
    <p>
      <b>&#1048;&#1051;&#1048;</b>&#160;<font color="#0000c0">$ postgres -c</font>
    </p>
    <ul>
      <li>
        &#1048;&#1084;&#1077;&#1102;&#1090; &#1087;&#1088;&#1077;&#1076;&#1087;&#1086;&#1095;&#1090;&#1077;&#1085;&#1080;&#1077; &#1087;&#1077;&#1088;&#1077;&#1076; &#1092;&#1072;&#1081;&#1083;&#1072;&#1084;&#1080; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
      </li>
      <li>
        &#1054;&#1087;&#1094;&#1080;&#1080; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1074; &#1092;&#1072;&#1081;&#1083;&#1077; <b>postmaster.opts</b>
      </li>
    </ul>
    <p>
      &#1047;&#1072;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1074; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; &#1087;&#1088;&#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <p>
      <font color="#0000c0">$ pg_ctl start -l logfile -o &quot;-c max_connections=50 -c shared_buffers=512MB&quot;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1059;&#1079;&#1085;&#1072;&#1090;&#1100; &#1091;&#1089;&#1090;&#1088;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1074; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;</b>
    </p>
    <p>
      <font color="#0000c0">select * from pg_settings where source = 'command line';</font>
    </p>
    <p>
      <font color="#0000c0">$ cat $PGDATA/postmaster.opts</font>&#160;&#160;# &#1055;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072; <b>postmaster.opts</b>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Во время выполнения" FOLDED="true" ID="ID_294889780" CREATED="1528620999646" MODIFIED="1529097384590"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1042;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;. </b>&#1044;&#1083;&#1103; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1088;&#1080; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1072;: &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; SHOW; &#1042;&#1099;&#1079;&#1086;&#1074; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; current_settings; &#1047;&#1072;&#1087;&#1088;&#1086;&#1089; &#1082; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102; pg_settings
    </p>
    <p>
      <font color="#0000c0"><b>SHOW</b>&#160;conf_parameter; </font>
    </p>
    <p>
      <font color="#0000c0"><b>current_setting</b>('conf_parameter') </font>
    </p>
    <p>
      <font color="#0000c0">SELECT setting, unit FROM <b>pg_settings</b>&#160;</font>
    </p>
    <p>
      <font color="#0000c0">WHERE name = 'conf_parameter';</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072;/&#1089;&#1073;&#1088;&#1086;&#1089; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;. </b>&#1044;&#1083;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1090;&#1072;&#1082;&#1078;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1090;&#1088;&#1080; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1072;: &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; SET; &#1042;&#1099;&#1079;&#1086;&#1074; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; set_config; &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077; UPDATE &#1076;&#1083;&#1103; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; pg_settings. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#8212; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1072;&#1103;
    </p>
    <p>
      <font color="#0000c0"><b>SET</b>&#160;[LOCAL] conf_parameter TO value; </font>
    </p>
    <p>
      <font color="#0000c0"><b>set_config</b>('conf_parameter', 'value', [true|false]) </font>
    </p>
    <p>
      <font color="#0000c0"><b>UPDATE pg_settings</b>&#160;</font>
    </p>
    <p>
      <font color="#0000c0">SET setting = 'value' </font>
    </p>
    <p>
      <font color="#0000c0">WHERE name = 'conf_parameter'; </font>
    </p>
    <p>
      <font color="#0000c0">RESET conf_parameter | ALL;</font>&#160;&#160;-- &#1057;&#1073;&#1088;&#1086;&#1089; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;
    </p>
    <p>
      
    </p>
    <p>
      &#1053;&#1077;&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; LOCAL &#1074; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1077; SET &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1081; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1080;. &#1047;&#1072; &#1101;&#1090;&#1086; &#1078;&#1077; &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1090;&#1088;&#1077;&#1090;&#1080;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#1074; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; set_config (true &#8211; &#1076;&#1083;&#1103; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1081; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1080;)
    </p>
  </body>
</html></richcontent>
<node TEXT="Пример1" ID="ID_1717224412" CREATED="1528624529462" MODIFIED="1528625385361"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;</b>
    </p>
    <p>
      3 &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1072;
    </p>
    <p>
      =&gt; SET work_mem TO '8MB';
    </p>
    <p>
      ------------------------------------------------
    </p>
    <p>
      =&gt; select set_config('work_mem', '8MB', false);
    </p>
    <p>
      ------------------------------------------------
    </p>
    <p>
      =&gt; UPDATE pg_settings
    </p>
    <p>
      =&gt; SET&#160;&#160;&#160;&#160;setting = '8MB'
    </p>
    <p>
      =&gt; WHERE&#160;&#160;name = 'work_mem';
    </p>
    <p>
      
    </p>
    <p>
      <b>UPDATE &#1085;&#1072; pg_settings &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; set_config()</b>
    </p>
    <p>
      =&gt; \d+ pg_settings
    </p>
    <p>
      FROM pg_show_all_settings() a(name, setting, unit, category, short_desc, extra_desc, context, vartype, source, min_val, max_val, enumvals, boot_val, reset_val, sourcefile, sourceline);
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Rules:
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;pg_settings_n AS
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;ON UPDATE TO pg_settings DO INSTEAD NOTHING
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;pg_settings_u AS
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;ON UPDATE TO pg_settings
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;WHERE new.name = old.name DO&#160;&#160;SELECT set_config(old.name, new.setting, false) AS set_config&#160;&#160;&#160;&#160;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Пример2" ID="ID_1305957569" CREATED="1528624652566" MODIFIED="1528625643227"><richcontent TYPE="NOTE">
<html>
