  </head>
  <body>
    <p>
      <b>&#1063;&#1090;&#1077;&#1085;&#1080;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; </b>
    </p>
    <p>
      3 &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1072;
    </p>
    <p>
      <font color="#0000c0">=&gt; SHOW work_mem; </font>
    </p>
    <p>
      -----------------------------------<font color="#0000c0">&#160;</font>
    </p>
    <p>
      <font color="#0000c0">=&gt; select current_setting ('work_mem'); </font>
    </p>
    <p>
