<node TEXT="2. Настройка" FOLDED="true" ID="ID_1794776482" CREATED="1528104316950" MODIFIED="1528356525112"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; <b>&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1101;&#1090;&#1072;&#1087;&#1077; &#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1103;&#1094;&#1080;&#1080;</b>
    </p>
    <ul>
      <li>
        <b>1GB</b>&#160;&#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1092;&#1072;&#1081;&#1083;&#1072; (&#1074; PGDATA directory)
      </li>
      <li>
        <b>16MB</b>&#160;&#1088;&#1072;&#1079;&#1084;&#1077;&#1088; xlog
      </li>
      <li>
        <b>8KB</b>&#160;&#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; Shared buffers
      </li>
    </ul>
    <p>
      <font color="#0000c0">$ sudo adduser <b>postgres</b></font>&#160;&#160;# <b>1.1</b>&#160;&#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1087;&#1086;&#1076; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1057;&#1059;&#1041;&#1044;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">$ sudo passwd postgres</font>&#160;&#160;# <b>1.2</b>&#160;&#1047;&#1072;&#1076;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;
    </p>
    <p>
      <font color="#0000c0">$ sudo mkdir /usr/local/pgsql/<b>data</b></font><b>&#160;</b>&#160;# <b>2.1</b>&#160; &#1050;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1076;&#1083;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
    </p>
    <p>
      <font color="#0000c0">$ sudo chown <b>postgres</b>&#160;/usr/local/pgsql/<b>data</b></font>&#160;&#160;# <b>2.2</b>&#160; &#1054;&#1085; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102; postgres
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072; &#1073;&#1072;&#1079; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.<font color="#ff0000">&#160; </font></b><font color="#ff0000">&#1044;&#1072;&#1083;&#1077;&#1077; &#1074;&#1089;&#1077; &#1087;&#1086;&#1076; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; <b>postgres</b>!</font>
    </p>
    <p>
      <b>3. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; &#1086;&#1082;&#1088;&#1091;&#1078;&#1077;&#1085;&#1080;&#1103;:</b>
    </p>
    <p>
      <font color="#0000c0">$ export PATH=/usr/local/pgsql/bin:$PATH</font>
    </p>
    <p>
      <font color="#0000c0">$ export MANPATH=/usr/local/pgsql/share/man:$MANPATH</font>&#160;&#160;# &#1045;&#1089;&#1083;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1072; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;&#1094;&#1080;&#1103;, &#1090;&#1086; MANPATH &#1087;&#1086;&#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1100; &#1089;&#1087;&#1088;&#1072;&#1074;&#1082;&#1091; &#1087;&#1086; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072;&#1084; Posgres &#1095;&#1077;&#1088;&#1077;&#1079; man
    </p>
    <p>
      <font color="#0000c0">$ export PGDATA=/usr/local/pgsql/data</font>
    </p>
    <ul>
      <li>
        &#1074;&#1084;&#1077;&#1089;&#1090;&#1086; <b>$PGDATA</b>&#160;&#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1087;&#1091;&#1090;&#1100; &#1074; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1077; -D (<font color="#0000c0">-D /usr/local/pgsql/data</font>) &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1099;
      </li>
      <li>
        &#1076;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1074; &#1092;&#1072;&#1081;&#1083; /home/postgres/<b>.bash_profile</b>
      </li>
    </ul>
    <p>
      <b>4. &#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; (&#1080;&#1085;&#1080;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;).</b>&#160; <b>Initdb</b>&#160;&#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090; <a href="#ID_249807350">3 &#1041;&#1044;</a>
    </p>
    <ul>
      <li>
        <b>template0</b>&#160;- &#1096;&#1072;&#1073;&#1083;&#1086;&#1085; &#1073;&#1072;&#1079;&#1099;, &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1102;&#1090;&#1089;&#1103;
      </li>
      <li>
        <b>template1</b>&#160;- &#1096;&#1072;&#1073;&#1083;&#1086;&#1085; &#1073;&#1072;&#1079;&#1099;, &#1080;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077;; &#1084;&#1086;&#1078;&#1085;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1086;&#1073;&#1097;&#1080;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1080; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        <b>postgres</b>&#160;- &#1073;&#1072;&#1079;&#1072; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1081; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;
      </li>
    </ul>
    <p>
      <font color="#0000c0">$ initdb -k </font>&#160;# <b>-k</b>&#160;&#1057;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &#1073;&#1091;&#1076;&#1091;&#1090; &#1089;&#1085;&#1072;&#1073;&#1078;&#1077;&#1085;&#1099; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1099;&#1084;&#1080; &#1089;&#1091;&#1084;&#1084;&#1072;&#1084;&#1080; &#1080; Postgres &#1087;&#1088;&#1080; &#1095;&#1090;&#1077;&#1085;&#1080;&#1080; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1090;&#1100; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1099;&#1077; &#1089;&#1091;&#1084;&#1084;&#1099;. &#1045;&#1089;&#1083;&#1080; &#1089; &#1076;&#1080;&#1089;&#1082;&#1086;&#1084; &#1085;&#1072;&#1095;&#1085;&#1091;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099;, &#1090;&#1086; &#1101;&#1090;&#1086; &#1087;&#1086;&#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1088;&#1072;&#1079;&#1091; &#1086;&#1073; &#1101;&#1090;&#1086;&#1084; &#1091;&#1079;&#1085;&#1072;&#1090;&#1100;
    </p>
    <p>
      &#1080;&#1083;&#1080; <font color="#0000c0">$ pg_ctl initdb -o &quot;-k&quot; </font>
    </p>
  </body>
</html></richcontent>
<node TEXT="template0&#xa;template1&#xa;postgres" ID="ID_249807350" CREATED="1528192285620" MODIFIED="1528356174002"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1060;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; <b>template0</b>, &#1080;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1082;&#1083;&#1086;&#1085;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; <b>template1</b>&#160;&#1080; <b>postgres</b>&#160;&#8212; &#1090;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1080;&#1085;&#1080;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072; &#1074;&#1089;&#1077; &#1090;&#1088;&#1080; &#1073;&#1072;&#1079;&#1099; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1099;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1064;&#1072;&#1073;&#1083;&#1086;&#1085; template1</b>&#160;&#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1080; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1103;. &#1042;&#1089;&#1077;, &#1095;&#1090;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1086; &#1074; template1, &#1073;&#1091;&#1076;&#1077;&#1090; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1082;&#1072;&#1078;&#1076;&#1091;&#1102; &#1085;&#1086;&#1074;&#1091;&#1102; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.
    </p>
    <p>
      <b>&#1064;&#1072;&#1073;&#1083;&#1086;&#1085; template0</b>&#160;<font color="#ff0000">&#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1080;&#1079;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103;</font>. &#1054;&#1085; &#1087;&#1088;&#1080;&#1075;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; &#1084;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084; &#1074; &#1076;&#1074;&#1091;&#1093; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1103;&#1093;.
    </p>
    <ul>
      <li>
        &#1042;&#1086;-&#1087;&#1077;&#1088;&#1074;&#1099;&#1093;, <b>&#1076;&#1083;&#1103; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1041;&#1044;</b>&#160;&#1080;&#1079; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1081; &#1082;&#1086;&#1087;&#1080;&#1080;, &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1085;&#1086;&#1081; <b>pg_dump</b>&#160;(&#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1074; &#1101;&#1090;&#1091; &#1082;&#1086;&#1087;&#1080;&#1102; &#1087;&#1086;&#1087;&#1072;&#1076;&#1091;&#1090; &#1085;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1041;&#1044;, &#1085;&#1086; &#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099;, &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074; template1 (&#1089;&#1084;&#160;&#171;&#1051;&#1086;&#1075;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#187;)
      </li>
      <li>
        &#1042;&#1086;-&#1074;&#1090;&#1086;&#1088;&#1099;&#1093;, <b>&#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1085;&#1086;&#1074;&#1086;&#1081; &#1041;&#1044;</b>&#160;&#1089; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1082;&#1086;&#1081;, &#1086;&#1090;&#1083;&#1080;&#1095;&#1085;&#1086;&#1081; &#1086;&#1090; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1081; &#1087;&#1088;&#1080; &#1080;&#1085;&#1080;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;.
      </li>
    </ul>
    <p>
      <b>&#1041;&#1072;&#1079;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; postgres</b>&#160;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; postgres. &#1054;&#1085;&#1072; &#1085;&#1077; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081;, &#1085;&#1086; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1099; &#1087;&#1088;&#1077;&#1076;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1102;&#1090; &#1077;&#1077; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077;, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1077;&#1077; <b>&#1085;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1091;&#1076;&#1072;&#1083;&#1103;&#1090;&#1100;</b>, &#1076;&#1072;&#1078;&#1077; &#1077;&#1089;&#1083;&#1080; &#1086;&#1085;&#1072; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1072;.
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="3. Установка расширений" FOLDED="true" ID="ID_1365024640" CREATED="1528114889220" MODIFIED="1528281983800"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1081; </b>
    </p>
    <ul>
      <li>
        &#1058;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100;, &#1077;&#1089;&#1083;&#1080; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1083;&#1080; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1083;&#1080; &#1073;&#1077;&#1079; &#1085;&#1080;&#1093;
      </li>
      <li>
        &#1055;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084;&#1099;&#1077;

        <ul>
          <li>
            &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1103; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; (45 &#1096;&#1090;&#1091;&#1082;)
          </li>
          <li>
            &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1077; &#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; (9 &#1096;&#1090;&#1091;&#1082;)
          </li>
          <li>
            &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1081;, &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1074; &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1082;&#1091;: http://www.postgresql.org/docs/9.4/static/contrib.html
          </li>
        </ul>
      </li>
      <li>
        &#1050;&#1088;&#1086;&#1084;&#1077; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1081;, &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1074; &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1082;&#1091;, &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1072; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1081;.
      </li>
    </ul>
    <p>
      <b>&#1057;&#1073;&#1086;&#1088;&#1082;&#1072; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072;</b>. &#1055;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1087;&#1086;&#1076; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;
    </p>
    <ul>
      <li>
        &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1081; (&#1080;&#1079; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072; contrib/) &#1080;&#1083;&#1080; &#1076;&#1083;&#1103; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; (&#1080;&#1079; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072; contrib/.../)
      </li>
      <li>
        &#1076;&#1083;&#1103; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;, &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1093; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; SQL, &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; CREATE EXTENSION &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; (&#1080;&#1079; SQL)
      </li>
      <li>
        &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1103; &#1080;&#1084;&#1077;&#1102;&#1090; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1091;&#1102; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1102; &#1087;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1077;
      </li>
    </ul>
    <p>
      <font color="#0000c0">$ make</font>&#160;&#160;# &#1048;&#1079; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072; (cantrib/&#1053;&#1077;&#1086;&#1073;&#1093;_&#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077;) &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1082;&#1086;&#1076;&#1086;&#1074;
    </p>
    <p>
      <font color="#0000c0">$ sudo make install</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1042; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1079;&#1072;&#1076;&#1072;&#1085;&#1080;&#1080; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1081; <b>oid2name</b>&#160;&#1080; <b>pgcrypto</b>, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1090;&#1077;&#1084;&#1077; &#171;&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1073;&#1072;&#1079;&#1072;&#1084;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;&#187;. &#1042; &#1090;&#1086;&#1081; &#1078;&#1077; &#1090;&#1077;&#1084;&#1077; &#1088;&#1072;&#1089;&#1089;&#1084;&#1072;&#1090;&#1088;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1103; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; CREATE EXTENSION.
    </p>
  </body>
</html></richcontent>
<node TEXT="pgcrypto" ID="ID_1946077690" CREATED="1528198055373" MODIFIED="1528199647414"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">=&gt; \c template1</font>&#160;&#160;-- <b>&#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;&#1089;&#1103;</b>&#160; &#1082; &#1073;&#1072;&#1079;&#1077; template1. &#1063;&#1090;&#1086;&#1073;&#1099; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085; &#1084;&#1086;&#1078;&#1085;&#1086; &#1073;&#1099;&#1083;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1073;&#1072;&#1079;&#1099;, &#1082; &#1085;&#1077;&#1084;&#1091; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1099;&#1093; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1081;, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; <b>&#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1084;&#1089;&#1103;</b>&#160; &#1086;&#1090; &#1073;&#1072;&#1079;&#1099; template1&#160; <font color="#0000c0">=&gt; \c postgres</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#160;=&gt; create extension pgcrypto;</font>&#160;&#160;--&#160;&#160;<b>&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077; pgcrypto &#1074; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1077; template1</b>. &#1053;&#1086;&#1074;&#1099;&#1077; &#1041;&#1044; &#1073;&#1091;&#1076;&#1091;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1091;&#1078;&#1077; &#1089; &#1101;&#1090;&#1080;&#1084; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077;&#1084;. &#1045;&#1089;&#1083;&#1080; &#1073;&#1099; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077; pgcrypto &#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1086; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; make install, &#1084;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1083;&#1080; &#1073;&#1099; &#1086;&#1096;&#1080;&#1073;&#1082;&#1091; &quot;ERROR: could not open extension control file...&quot;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;</b>
    </p>
    <p>
      <font color="#0000c0">=&gt; select digest('Hello, world!', 'md5');</font>&#160;&#160;-- &#1042;&#1099;&#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1100; MD5-&#1076;&#1072;&#1081;&#1076;&#1078;&#1077;&#1089;&#1090;
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Пример" POSITION="bottom_or_right" ID="ID_984006718" CREATED="1529095558423" MODIFIED="1529095669909"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1072;</b>
    </p>
    <p>
      1. &#1057;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100; PostgreSQL &#1073;&#1077;&#1079; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1081; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1077;&#1075;&#1086;
    </p>
    <p>
      2. &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;, &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;
    </p>
    <p>
      3. &#1059;&#1073;&#1077;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103;, &#1095;&#1090;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;
    </p>
    <p>
      4. &#1054;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;
    </p>
    <p>
      5. &#1057;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077; oid2name
    </p>
    <p>
      
    </p>
    <p>
      -- &#1087;&#1086;&#1076; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;
    </p>
    <p>
      <font color="#0000c0">$ cd ~ </font>
    </p>
    <p>
      <font color="#0000c0">$ wget https://ftp.postgresql.org/pub/source/v9.4.4/postgresql-9.4.4.tar.gz </font>
    </p>
    <p>
      <font color="#0000c0">$ tar xzf postgresql-9.4.4.tar.gz </font>
    </p>
    <p>
      <font color="#0000c0">$ cd postgresql-9.4.4/ </font>
    </p>
    <p>
      <font color="#0000c0">$ ./configure </font>
    </p>
    <p>
      <font color="#0000c0">$ make </font>
    </p>
    <p>
      <font color="#0000c0">$ sudo make install </font>
    </p>
    <p>
      <font color="#0000c0">$ sudo adduser postgres </font>
    </p>
    <p>
      <font color="#0000c0">$ sudo mkdir /usr/local/pgsql/data </font>
    </p>
    <p>
      <font color="#0000c0">$ sudo chown postgres /usr/local/pgsql/data</font>
    </p>
    <p>
      
    </p>
    <p>
      -- &#1087;&#1086;&#1076; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; postgres
    </p>
    <p>
      <font color="#0000c0">$ echo 'export PATH=/usr/local/pgsql/bin:$PATH' &gt;&gt; ~/.profile </font>
    </p>
    <p>
      <font color="#0000c0">$ echo 'export PGDATA=/usr/local/pgsql/data' &gt;&gt; ~/.profile </font>
    </p>
    <p>
      <font color="#0000c0">$ . ~/.profile </font>
    </p>
    <p>
      <font color="#0000c0">$ initdb -k </font>
    </p>
    <p>
      <font color="#0000c0">$ pg_ctl start -l logfile </font>
    </p>
    <p>
      <font color="#0000c0">$ psql -c 'select now();'</font>
    </p>
    <p>
      
    </p>
    <p>
      -- &#1087;&#1086;&#1076; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; postgres
    </p>
    <p>
      <font color="#0000c0">$ pg_ctl stop -m fast</font>
    </p>
    <p>
      
    </p>
    <p>
      -- &#1087;&#1086;&#1076; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;
    </p>
    <p>
      <font color="#0000c0">$ cd ~/postgresql-9.4.4/contrib/oid2name </font>
    </p>
    <p>
      <font color="#0000c0">$ make </font>
    </p>
    <p>
      <font color="#0000c0">$ sudo make install</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Пакет postgresql-contrib" ID="ID_1159934207" CREATED="1735137081533" MODIFIED="1735137145812"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Пакет postgresql-contrib содержит дополнительные модули и расширения для PostgreSQL, которые не включены в основной дистрибутив базы данных. Эти модули предоставляют различные функции и возможности, которые могут быть полезны для разработчиков и администраторов баз данных.
    </p>
    <p>
      
    </p>
    <p>
      Вот несколько примеров того, что может включать postgresql-contrib:
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_trgm – предоставляет возможность поиска по частичному совпадению строк (fuzzy matching) с использованием триграмм.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль btree_gist – позволяет создавать индексы типа GiST для типов данных B-tree.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль hstore – поддерживает хранение пар &quot;ключ-значение&quot; внутри одной колонки таблицы.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль cube – добавляет поддержку многомерных кубов и операций над ними.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль earthdistance – обеспечивает вычисление расстояний между точками на поверхности Земли.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль intarray – предоставляет операции над массивами целых чисел.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pageinspect – используется для анализа структуры страниц базы данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль tablefunc – включает функции для работы с таблицами как с массивами.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль fuzzystrmatch – предлагает функции для сравнения строк по схожести (например, Levenshtein distance).
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль unaccent – удаляет диакритические знаки из текста.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль tsearch2 – устаревший модуль полнотекстового поиска, который был заменен модулем pg_catalog.pg_ts_dict.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль adminpack – инструменты для управления сервером через SQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль dict_xsyn – словарь синонимов для полнотекстового поиска.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль seg – сегментация текста для полнотекстового поиска.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль lo – поддержка больших объектов (Large Objects).
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль ltree – работа с иерархическими структурами данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль test_parser – тестовый парсер для проверки синтаксиса запросов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль timetravel – временные метаданные для отслеживания изменений в базе данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль uuid-ossp – генерация UUID.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль xml2 – обработка XML-данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль citext – нечувствительный к регистру текстовый тип данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль auto_explain – автоматическое объяснение планов выполнения запросов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль chkpass – проверка паролей.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль dblink – связь с другими базами данных PostgreSQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль file_fdw – доступ к файлам через внешние данные.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_buffercache – информация о буферном кэше.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_freespacemap – отображение свободного пространства в таблице.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_prewarm – предварительное прогревание данных в кэше.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_stat_statements – сбор статистики по выполненным запросам.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgcrypto – криптографические функции.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgrowlocks – мониторинг блокировок строк.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgstattuple – статистика по кортежам.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль plpgsql_check – статический анализатор кода PL/pgSQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль refint – управление ссылочной целостностью.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль session_variables – переменные сессии.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль sslinfo – информация о SSL-соединениях.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль vacuumlo – очистка больших объектов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль vodka – утилиты для тестирования производительности.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль oid2name – преобразование OID в имена объектов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль passwordcheck – проверка сложности пароля.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_hint_plan – подсказки для оптимизатора запросов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pglogical – логическая репликация.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_partman – управление разделенными таблицами.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_repack – реорганизация таблиц и индексов без блокировки.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_rman – резервное копирование и восстановление.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_shardman – шардинг данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_standby – инструменты для управления standby-сервером.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_wait_sampling – выборка информации о блокировках.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgaudit – аудит действий пользователей.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgbackrest – резервное копирование и восстановление.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgbench – инструмент для нагрузочного тестирования.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgcat – просмотр содержимого базы данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgcli – интерактивный клиент PostgreSQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgcluu – кластеризация и балансировка нагрузки.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgdg – менеджер пакетов для PostgreSQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_dumpall – экспорт всех баз данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_ls_dir – список файлов в каталоге.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgpool-II – пул соединений и балансировка нагрузки.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgprobackup – резервное копирование и восстановление.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_recvlogical – прием логической репликации.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_rewind – синхронизация баз данных после сбоя.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_sendrecv – отправка и получение сообщений.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_stat_kcache – статистика использования кеша.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_top – монитор активности сервера.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_upgrade – обновление версии PostgreSQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_visibility – видимость данных в таблицах.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pgxnclient – клиент для XN Subsystem.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль plprofiler – профилирование функций PL/pgSQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль psql_odbc – подключение к ODBC источникам данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль reindexdb – перестроение индексов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль repmgr – управление репликами PostgreSQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль restore_command – команда восстановления базы данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль set_user – установка пользователя для текущего сеанса.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль shm_to_disk – перенос данных из общей памяти на диск.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль sqlsmith – генератор случайных SQL-запросов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль tabcomplete – автодополнение команд в psql.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль timescaledb – временная база данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль wal2json – конвертер WAL-файлов в JSON.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль walmgr – управление WAL-файлами.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль xlogdump – дамп WAL-файлов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль zheap – альтернативный механизм хранения данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль zstd – сжатие данных с использованием алгоритма Zstandard.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль zerofill – заполнение пустых мест нулями.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль zombie_check – проверка наличия зомби-процессов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль zoneminder – интеграция с системой видеонаблюдения ZoneMinder.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль zookeeper – интеграция с Apache ZooKeeper.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль zsync – синхронизация данных между серверами.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль bdr – двунаправленная репликация.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль bloom – индексирование по методу Блума.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль btree_gin – индексация B-tree с использованием GiN.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль citus – горизонтальное масштабирование PostgreSQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль crunchy-frog – расширение безопасности PostgreSQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль cstore_fdw – внешний источник данных для столбчатых хранилищ.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль dbfdw – внешний источник данных для DBF-файлов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;*Модуль edb» – расширения от EnterpriseDB.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль fdw_info – информация об внешних источниках данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль fdw_sample – пример внешнего источника данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль foreign-data-wrapper – интерфейс для внешних источников данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль hadoop_fdw – внешний источник данных для Hadoop.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль hyperloglog – приближенное подсчитывание уникальных значений.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль ip4r – работа с IP-адресами.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль jsonb_plpython – обработка JSONB с помощью Python.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль ltree_gin – индексация LTree с использованием GiN.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль madtimer – таймеры для мониторинга активности.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль multicorn – универсальный FDW для различных источников данных.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль orafce – эмуляция некоторых возможностей Oracle.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль parquet_s3_fdw – внешний источник данных для Parquet-файлов в S3.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_activity – мониторинг активности сервера.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_auto_failover – автоматическое переключение при отказе.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_bigm – большие карты битовых массивов.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_cron – планировщик задач в PostgreSQL.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_jieba – китайский сегментатор текста.
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;Модуль pg_pathman – управление разделением таблиц
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Запуск" ID="ID_1295733386" CREATED="1528112232057" MODIFIED="1728911742393"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Запуск сервера</b>
    </p>
    <ul>
      <li>
        <p>
          История команд сохраняется в файле <b>~/.psql_history </b>или <b>$PSQL_HISTORY</b>, или <b>HISTFILE</b>
        </p>
      </li>
      <li>
        <p>
          При запуске выполняются <b>скрипты</b>:
        </p>
        <ul>
          <li>
            <p>
              <b>psqlrc</b>&#xa0;общий системный файл (<span style="color: #0000c0;">$ pg_config --sysconfdir</span>&#xa0;&#xa0;# Найти psqlrc)
            </p>
          </li>
          <li>
            <p>
              <b>~/.psqlrc</b>&#xa0;(или <b>$PSQLRC</b>)&#xa0;&#xa0;пользовательский файл
            </p>
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <b>Запуск</b>
    </p>
    <p>
      <span style="color: #0000c0;">$ postgres &gt;logfile 2&gt;&amp;1 &amp;</span>&#xa0;&#xa0;# Запуск в фоне (&amp;) с ведением лога
    </p>
    <p>
      или <span style="color: #0000c0;">$ pg_ctl start -l logfile</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Проверка</b>
    </p>
    <p>
      <span style="color: #0000c0;">$ psql -c 'select now()' </span>
    </p>
    <p>
      <span style="color: #0000c0;">$ pg_ctl status</span>&#xa0;&#xa0;# <b>PID</b>&#xa0;процесса. Также PID можно найти в файле /usr/local/pgsql/data/<b>postmaster.pid</b>.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Остановка" ID="ID_1250490875" CREATED="1528191505688" MODIFIED="1728912769810"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Остановка сервера </b>
    </p>
    <ul>
      <li>
        Можно воспользоваться <b>pg_ctl</b>, а можно вручную послать соответствующий сигнал процессу postmaster
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">$ pg_ctl stop -m &lt;<b>smart</b>&#xa0;| <b>fast</b>&#xa0;| <b>immediate</b>&gt;</span>
    </p>
    <ul>
      <li>
        <b>smart</b>&#xa0;ожидает завершения всех сеансов и выполняет контрольную точку<br/>(kill -TERM pid)
      </li>
      <li>
        <b>fast</b>&#xa0;принудительно завершает сеансы и выполняет контрольную точку<br/>(kill -INT pid)
      </li>
      <li>
        <b>immediate</b>&#xa0;принудительно завершает сеансы, при запуске потребуется восстановление<br/>(kill -QUIT pid)
      </li>
    </ul>
    <p>
      Удобный способ, позволяющий <b>уменьшить время простоя</b>&#xa0;&#xa0;(при выполнении первой контрольной точки система работоспособна; вторая контрольная точка выполнится уже быстро):
    </p>
    <p>
      <span style="color: #0000c0;">$ psql -c CHECKPOINT &amp;&amp; pg_ctl stop -m fast</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="psql" POSITION="bottom_or_right" ID="ID_1825522199" CREATED="1528180169891" MODIFIED="1737467559084"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>psql</b>&#xa0;- терминальный клиент для работы с PostgreSQL
    </p>
    <ul>
      <li>
        Поставляется вместе с СУБД
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">psql -c &quot;\du&quot;</span>&#xa0;&#xa0;# du (display users) Список всех ролей с их атрибутами
    </p>
    <p>
      <span style="color: #0000c0;">psql -U postgres -c &quot;CREATE ROLE admin WITH LOGIN PASSWORD 'admin' CREATEDB CREATEROLE;&quot;</span>&#xa0;&#xa0;# Отправить команду
    </p>
    <p>
      <span style="color: #0000c0;">psql&#xa0;-U postgres</span>&#xa0;&#xa0;# Запуск терминала --&gt; <span style="color: #008000;">postgres=# </span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo -iu postgres psql</span>
    </p>
    <p>
      <span style="color: #008000;">select * from pg_class;</span>&#xa0;&#xa0;# Вывести всю таблицу
    </p>
    <ul>
      <li>
        <span style="color: #008000;">\</span>&#xa0;&#xa0;(обратный слеш): В psql это символ, который используется для обозначения метакоманд (команд, которые интерпретируются самим клиентом psql, а не отправляются на сервер как SQL)
      </li>
      <li>
        <span style="color: #008000;">\d</span>&#xa0;- (display) отображать различные объекты БД
      </li>
      <li>
        <span style="color: #008000;">\du</span>&#xa0;- пользователи
      </li>
      <li>
        <span style="color: #008000;">\dt</span>&#xa0;- таблицы
      </li>
      <li>
        <span style="color: #008000;">\dv</span>&#xa0;- представления
      </li>
      <li>
        <span style="color: #008000;">\df</span>&#xa0;- функции
      </li>
      <li>
        \l - Cписок доступных БД
      </li>
      <li>
        <span style="color: #008000;">\c temp1 postgres</span>&#xa0;&#xa0;# Подключиться к БД temp1 под пользователем postgres<br/><span style="color: #008000;">\c[onnect] database username host port</span>&#xa0;&#xa0;# Переподключиться
      </li>
      <li>
        <span style="color: #008000;">\q</span>&#xa0;&#xa0;# Выход из терминала
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Безопасность" FOLDED="true" POSITION="bottom_or_right" ID="ID_1759922109" CREATED="1528955440359" MODIFIED="1729082375403"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      В документации под аутентификацией понимаются: Идентификация + Аутентификация + Авторизация
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Сменить пароль</span>
    </p>
    <p>
      <span style="color: #008000;">SELECT * FROM pg_roles WHERE rolname='sysadmin';</span>&#xa0;&#xa0;# Все атрибуты роли
    </p>
    <p>
      <span style="color: #008000;">ALTER USER postgres with encrypted </span><span style="color: #008000; font-weight: bold;">password</span><span style="color: #008000;">&#xa0;&#xa0;'SuperStongPassword';</span>&#xa0;&#xa0;# Установить пользователям пароли
    </p>
    <p>
      <span style="color: #008000;">ALTER USER sysadmin with encrypted password 'MyPassword';</span>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="# Пример" ID="ID_835759062" CREATED="1529097678109" MODIFIED="1729694264679"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Практика</b>
    </p>
    <p>
      1. Измените конфигурационные файлы (предварительно сохранив оригиналы) таким образом, чтобы:
    </p>
    <ul>
      <li>
        безусловно разрешить локальное соединение пользователю postgres
      </li>
      <li>
        разрешить сетевые подключения всем пользователям к любым
      </li>
      <li>
        базам данных с аутентификацией по паролю с шифрованием MD5
      </li>
    </ul>
    <p>
      2. Создайте пользователя enc с зашифрованным паролем и пользователя unenc с незашифрованным.
    </p>
    <p>
      3. Подключитесь к БД postgres под пользователем enc
    </p>
    <p>
      4. Узнайте пароль пользователя unenc из таблицы pg_authid. Получилось? Почему?
    </p>
    <p>
      5. Выйдите из psql и подключитесь как postgres. Посмотрите пароли пользователей enc и unenc.
    </p>
    <p>
      6. Восстановите исходные конфигурационные файлы.
    </p>
    <p>
      
    </p>
    <p>
      <b>Решение</b>
    </p>
    <p>
      <span style="color: #0000c0;">$ cd $PGDATA </span>
    </p>
    <p>
      <span style="color: #0000c0;">$ cp pg_hba.conf pg_hba.conf.default</span>
    </p>
    <p>
      -- редактируем файл pg_hba.conf в любом редакторе
    </p>
    <p>
      <span style="color: #0000c0;">$ cat pg_hba.conf</span>
    </p>
    <p>
      <span style="color: #008000;">local all postgres trust </span>
    </p>
    <p>
      <span style="color: #008000;">host all all all md5</span>
    </p>
    <p>
      <span style="color: #0000c0;">$ pg_ctl reload</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">$ psql </span>
    </p>
    <p>
      <span style="color: #0000c0;"># create user enc encrypted password 'enc'; </span>
    </p>
    <p>
      <span style="color: #0000c0;"># create user unenc unencrypted password 'unenc';</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">$ psql postgres enc -h localhost</span>
    </p>
    <p>
      <span style="color: #008000;">Password for user enc: enc</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">&gt; select rolpassword from pg_authid where rolname='unenc';</span>
    </p>
    <p>
      -- permission denied
    </p>
    <p>
      <span style="color: #0000c0;">&gt; \dp pg_catalog.pg_authid</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">$ psql </span>
    </p>
    <p>
      <span style="color: #0000c0;"># select rolname, rolpassword from pg_authid where rolname like '%enc';</span>
    </p>
    <p>
      <span style="color: #008000;">enc | md59ad9487992ed433fd63349ea544f41d7 </span>
    </p>
    <p>
      <span style="color: #008000;">unenc | unenc</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">$ cp pg_hba.conf.default pg_hba.conf; pg_ctl reload</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Конф. файлы" ID="ID_1685472201" CREATED="1528955704475" MODIFIED="1529097966505"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099;</b>
