    <p>
      
    </p>
    <p>
      <b>&#1056;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;.</b>&#160; &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;, &#1089;&#1074;&#1103;&#1079;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1080; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1077;&#1081;, &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1085;&#1077; &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077;, &#1072; &#1074; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;&#1072;&#1093;
    </p>
    <ul>
      <li>
        &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; <b>$PGDATA/*.conf</b>&#160; (&#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1093; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;)
      </li>
      <li>
        <font color="#008000">select name, setting<br color="#008000"/>from pg_settings<br color="#008000"/>where category = 'File Locations';</font>
      </li>
      <li>
        &#1092;&#1072;&#1081;&#1083;&#1099; &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;, &#1079;&#1072;&#1090;&#1077;&#1084; &#1087;&#1088;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1080;&#1079;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1084;
      </li>
    </ul>
    <p>
      <b>&#1044;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103; &#1087;&#1088;&#1080; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080;</b>
    </p>
    <ul>
      <li>
        &#1092;&#1072;&#1081;&#1083;&#1099; &#1095;&#1080;&#1090;&#1072;&#1102;&#1090;&#1089;&#1103; &#1086;&#1076;&#1080;&#1085; &#1088;&#1072;&#1079; &#1087;&#1088;&#1080; &#1089;&#1090;&#1072;&#1088;&#1090;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1087;&#1088;&#1080; &#1080;&#1093; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080; &#1085;&#1072;&#1076;&#1086; &#1087;&#1086;&#1087;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100;:<br/><font color="#0000c0">$ pg_ctl reload</font>&#160;(&#1080;&#1083;&#1080; <font color="#0000c0">kill -HUP</font>, &#1080;&#1083;&#1080; <font color="#0000c0">select pg_reload_conf()</font>)
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
