    <p>
      <b>md5</b>&#160;- &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1074; &#1074;&#1080;&#1076;&#1077; MD5-&#1076;&#1072;&#1081;&#1076;&#1078;&#1077;&#1089;&#1090;&#1072;. &#1052;&#1077;&#1090;&#1086;&#1076; &#171;md5&#187; &#1089;&#1088;&#1072;&#1074;&#1085;&#1080;&#1074;&#1072;&#1077;&#1090; MD5-&#1076;&#1072;&#1081;&#1076;&#1078;&#1077;&#1089;&#1090; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103; &#1089; MD5-&#1076;&#1072;&#1081;&#1076;&#1078;&#1077;&#1089;&#1090;&#1086;&#1084; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;, &#1093;&#1088;&#1072;&#1085;&#1103;&#1097;&#1077;&#1075;&#1086;&#1089;&#1103; &#1074; &#1073;&#1072;&#1079;&#1077;. &#1040;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; MD5 &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1077;&#1090; &#1074;&#1074;&#1077;&#1076;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1074; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074;, &#1087;&#1086; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; (&#1093;&#1086;&#1090;&#1103; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; MD5 &#1085;&#1077; &#1089;&#1095;&#1080;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1089;&#1090;&#1086;&#1081;&#1082;&#1080;&#1084;). &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; &#1101;&#1090;&#1086; &#1085;&#1077; &#1079;&#1072;&#1097;&#1080;&#1097;&#1072;&#1077;&#1090; &#1086;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#10