    </p>
    <p>
      &#1050;&#1083;&#1080;&#1077;&#1085;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1073;&#1072;&#1079;&#1077;, &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1103; &#1080;&#1084;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1057;&#1059;&#1041;&#1044;. &#1042; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; &#1088;&#1072;&#1089;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1085;&#1085;&#1099;&#1093; &#1088;&#1072;&#1085;&#1077;&#1077; &#1084;&#1077;&#1090;&#1086;&#1076;&#1086;&#1074; (&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1102;&#1090; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1102; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1080;&#1084;&#1077;&#1085;&#1080;), &#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1080; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;,
    </p>
    <p>
      &#1080; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074;&#1085;&#1077; &#1057;&#1059;&#1041;&#1044;. &#1042; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1077; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086;&#1081; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; PostgreSQL &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090;:
    </p>
    <p>
      1. &#1080;&#1084;&#1103;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1077; &#1087;&#1088;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; (&#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1077; &#1080;&#1084;&#1103; &#1057;&#1059;&#1041;&#1044;),
    </p>
    <p>
      2. &#1080;&#1084;&#1103;, &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1077; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1086;&#1081; (&#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1077; &#1080;&#1084;&#1103;).
    </p>
    <p>
      &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1074;&#1089;&#1077; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1084;&#1077;&#1090;&#1086;&#1076;&#1099; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1090; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1082;&#1072;&#1082; &#1084;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084; &#1086;&#1076;&#1080;&#1085; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; <b>map</b>. &#1054;&#1085; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1089;&#1086;&#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; &#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1080;&#1084;&#1077;&#1085;.
    </p>
    <p>
      
    </p>
    <p>
      <b>ident [map=...]</b>&#160;- &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1080;&#1084;&#1077;&#1085;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1076;&#1083;&#1103; TCP &#1091; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; (RFC 1413)
    </p>
    <p>
      <b>peer [map=...]</b>&#160;- &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1080;&#1084;&#1077;&#1085;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1091; &#1103;&#1076;&#1088;&#1072; &#1054;&#1057; (&#1076;&#1083;&#1103; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1081;). &#1069;&#1090;&#1086; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075; ident &#1076;&#1083;&#1103; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081; (&#1077;&#1089;&#1083;&#1080; &#1076;&#1083;&#1103; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; ident, &#1090;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085; peer).
    </p>
    <p>
      <b>cert [map=...]</b>&#160;- &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1086;&#1075;&#1086; SSL-&#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072;
    </p>
    <p>
      <b>gss [map=... &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;]</b>&#160; - &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; Kerberos &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; GSSAPI (RFC 1964). &#1055;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; (single sign-on).
    </p>
    <p>
      <b>sspi [map=... &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;]</b>&#160; - &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; Kerberos/NTLM &#1076;&#1083;&#1103; Windows. &#1055;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;.
    </p>
  </body>
</html></richcontent>
<node TEXT="Соответствие имен (map)&#xa;pg_ident.conf" ID="ID_1056801735" CREATED="1528962315250" MODIFIED="1528962896226"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1080;&#1084;&#1077;&#1085;</b>
    </p>
    <p>
      <b>pg_ident.conf (&#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; ident_file)</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1072; &#1092;&#1072;&#1081;&#1083;&#1072;</b>
    </p>
    <ul>
      <li>
        &#1089;&#1090;&#1088;&#1086;&#1082;&#1072; &#8212; &#1085;&#1072;&#1073;&#1086;&#1088; &#1087;&#1086;&#1083;&#1077;&#1081;, &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1080;&#1090;&#1077;&#1083;&#1100; &#8212; &#1087;&#1088;&#1086;&#1073;&#1077;&#1083; &#1080;&#1083;&#1080; &#1090;&#1072;&#1073;&#1091;&#1083;&#1103;&#1094;&#1080;&#1103;
      </li>
      <li>
        &#1087;&#1091;&#1089;&#1090;&#1099;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1080; &#1090;&#1077;&#1082;&#1089;&#1090; &#1087;&#1086;&#1089;&#1083;&#1077; # &#1080;&#1075;&#1085;&#1086;&#1088;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103;
      </li>
    </ul>
    <p>
      <b>&#1055;&#1086;&#1083;&#1103;</b>
    </p>
    <ul>
      <li>
        <b>&#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1103;</b>&#160; (&#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1077; map &#1074; <b>pg_hba.conf</b>). &#1053;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1103; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1088;&#1072;&#1079;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100; &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1089;&#1086;&#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072; pg_ident.conf (&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1083;&#1103; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; &#1074; pg_hba.conf).
      </li>
      <li>
        <b>&#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1077; &#1080;&#1084;&#1103;</b>&#160; (&#1089;&#1095;&#1080;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1099;&#1084; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;&#1084;, &#1077;&#1089;&#1083;&#1080; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089; &#1082;&#1086;&#1089;&#1086;&#1081; &#1095;&#1077;&#1088;&#1090;&#1099;).

        <p>
          &#1042;&#1085;&#1077;&#1096;&#1085;&#1077;&#1077; &#1080;&#1084;&#1103; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084;, &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1084;&#1099;&#1084; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1086;&#1081; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1080;&#1083;&#1080; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1084; &#1074; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1077;. &#1045;&#1089;&#1083;&#1080; &#1101;&#1090;&#1086; &#1087;&#1086;&#1083;&#1077; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089; &#1082;&#1086;&#1089;&#1086;&#1081; &#1095;&#1077;&#1088;&#1090;&#1099;, &#1090;&#1086; &#1077;&#1075;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089;&#1095;&#1080;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1099;&#1084; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;&#1084;. &#1069;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1080;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1077; &#1080; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1077; &#1080;&#1084;&#1077;&#1085;&#1072; &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;&#1072;&#1084;&#1080; &#1080;&#1083;&#1080; &#1089;&#1091;&#1092;&#1092;&#1080;&#1082;&#1089;&#1072;&#1084;&#1080;.
        </p>
      </li>
      <li>
        <b>&#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1077; &#1080;&#1084;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1041;&#1044;</b>. &#1042;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1077; &#1080;&#1084;&#1103; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;. &#1047;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1089;&#1086;&#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1072;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1077; &#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1077; &#1080;&#1084;&#1077;&#1085;&#1072;, &#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1084;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1057;&#1059;&#1041;&#1044; &#1087;&#1086;&#1076; &#1076;&#1072;&#1085;&#1085;&#1099;&#1084; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; (&#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1086;, &#1087;&#1088;&#1080; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1080; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086;&#1081; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;).
      </li>
    </ul>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
</node>
</node>
</node>
</node>
<node TEXT="БД" FOLDED="true" POSITION="bottom_or_right" ID="ID_1498937792" CREATED="1528197209985" MODIFIED="1737552627564"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_997515904"><span style="font-weight: normal;">Таблицы</span></a><span style="font-weight: normal;">&#xa0;&#xa0;<a href="#ID_1617442989">Данные</a></span>&#xa0;&#xa0;<a href="#ID_1498937792">БД</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Список БД</b>
    </p>
    <p>
      <span style="color: #0000c0;">psql <b>-l (малая L) </b></span>
    </p>
    <p>
      <span style="color: #008000;">\l&#xa0;\list </span># сокращенно от \list
    </p>
    <p>
      <span style="color: #008000; font-weight: bold;">SELECT datname</span><span style="color: #008000;">, datistemplate, datallowconn, datconnlimit </span><span style="color: #008000; font-weight: bold;">FROM pg_database;</span><span style="color: #008000;">&#xa0;</span>
    </p>
    <ul>
      <li>
        datistemplate&#xa0;- является ли база данных шаблоном (t - шаблон);
      </li>
      <li>
        datallowconn&#xa0;&#xa0;- разрешены ли соединения с базой данных (f - не разрешать)
      </li>
      <li>
        datconnlimit&#xa0;&#xa0;- максимальное количество соединений (-1 = без ограничений)
      </li>
      <li>
        При необходимости флаги можно изменить с помощью <b>update</b>.
      </li>
    </ul>
    <p>
      <b>Размер БД</b>&#xa0;
    </p>
    <p>
      <span style="color: #0000c0;">=&gt; select <b>pg_database_size</b>('test0');</span>&#xa0;&#xa0;-- в байтах
    </p>
    <p>
      <span style="color: #0000c0;">=&gt; select <b>pg_size_pretty</b>(pg_database_size('test0'));</span>&#xa0;&#xa0;-- в читаемом виде
    </p>
    <p>
      
    </p>
    <p>
      <b>Подключиться \ Отключиться к БД </b>
    </p>
    <p>
      <span style="color: #0000c0;">psql -U username -h hostname -d БД_name</span>
    </p>
    <p>
      <span style="color: #008000;">\c template1</span>&#xa0;&#xa0;# \c(onnect). <span style="font-weight: normal;">Подключиться&#xa0;&#xa0;к БД template1</span>
    </p>
    <p>
      \с&#xa0;&#xa0;# Отключиться от БД
    </p>
    <p>
      
    </p>
    <p>
      <b>Установить расширение. </b>Чтобы шаблон можно было использовать для создания базы, к нему не должно быть активных подключений,
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;=&gt; create extension pgcrypto;</span>&#xa0;&#xa0;--&#xa0;&#xa0;<b>Установить расширение pgcrypto в шаблоне template1</b>. Новые БД будут создаваться уже с этим расширением. Если бы расширение pgcrypto не было установлено с помощью make install, мы получили бы ошибку &quot;ERROR: could not open extension control file...&quot;
    </p>
    <p>
      
    </p>
    <p>
      <b>Создать новую БД</b>
    </p>
    <p>
      <span style="color: #0000c0;">createdb test </span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo -u postres createdb -O wikiuser my_wiki</span>&#xa0;&#xa0;# Создать БД принадлежащую созданному пользователю
    </p>
    <p>
      <span style="color: #008000;">CREATE DATABASE test;</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Переименовать БД</b>
    </p>
    <p>
      <span style="color: #0000c0;">=&gt; alter database &lt;nameDB&gt; rename to &lt;newnameDB&gt;;</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Изменить количество соединений</b>
    </p>
    <p>
      <span style="color: #0000c0;">=&gt; alter database test connection limit 10;</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Удалить БД</b>&#xa0;(если к ней нет активных подключений).
    </p>
    <p>
      <span style="color: #0000c0;">sudo -iu postgres dropdb my_wiki </span>
    </p>
    <p>
      <span style="color: #0000c0;">psql -U postgres -c 'drop database my_wiki;'</span>
    </p>
    <p>
      <span style="color: #008000;">DROP DATABASE test; </span>
    </p>
    <p>
      <span style="color: #008000;">DROP DATABASE IF EXISTS test;</span><span style="color: #0000c0;">&#xa0;</span>Если база данных не существует, команда DROP DATABASE будет ругаться: ERROR:&#xa0;&#xa0;database &quot;test&quot; does not exist. Поэтому можно воспользоваться другой формой (она применима и к удалению других объектов):
    </p>
    <p>
      -----------------------------------------------------
    </p>
    <p>
      <span style="font-weight: bold;">Завершить все активные подключения к указанной БД</span>
    </p>
    <p>
      SELECT pg_terminate_backend(pg_stat_activity.pid)
    </p>
    <p>
      FROM pg_stat_activity
    </p>
    <p>
      WHERE pg_stat_activity.datname = 'имя_БД'
    </p>
    <p>
      AND pid &lt;&gt; pg_backend_pid();
    </p>
  </body>
</html></richcontent>
<node TEXT="Пример" ID="ID_969189314" CREATED="1529095923151" MODIFIED="1729150240870"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Практика</b>
    </p>
    <p>
      1. Создать базу данных DB5 из шаблона template0 (синтаксис любой команды можно посмотреть в psql
    </p>
    <p>
      с помощью \help и \help command)
    </p>
    <p>
      2. Вычислить объем, занимаемый базой данных
    </p>
    <p>
      3. Создать в базе данных DB5 произвольную таблицу T и добавить в нее несколько записей
    </p>
    <p>
      4. Вычислить объем, занимаемый таблицей и всей базой данных, сравнить с п. 2
    </p>
    <p>
      
    </p>
    <p>
      <b>Решение</b>
    </p>
    <p>
      <span style="color: #0000c0;"># create database db5 template template0; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;"># select pg_database_size('db5'); </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;"># \c db5 </span>
    </p>
    <p>
      <span style="color: #0000c0;"># create table t(n numeric); </span>
    </p>
    <p>
      <span style="color: #0000c0;"># insert into t values (1), (2), (3); </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;"># select pg_table_size('t'); </span>
    </p>
    <p>
      <span style="color: #0000c0;"># select pg_database_size('db5');</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Внешний вид" POSITION="bottom_or_right" ID="ID_1105186162" CREATED="1528185004316" MODIFIED="1729083579363"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        Если вывод команды SQL не помещется на экран, для его отображения можно использовать специальную программу <b>$PAGER</b>. Использование можно включать или выключать с помощью <b>\pset pager on|off</b>
      </li>
      <li>
        Для управления выводом используется команда <b>\pset</b>&#xa0;в разных вариациях. Например, можно включить отображение полей &quot;в столбик&quot;: <b>\pset expanded on|off</b>&#xa0;или просто <b>\x</b>
      </li>
      <li>
        Если вывод предстоит <b>разбирать</b>&#xa0;&#xa0;программно, то можно<br/>а) убрать выравнивание полей <span style="color: #0000c0;">=#&#xa0;\pset format unaligned</span>&#xa0;&#xa0;ИЛИ&#xa0; <span style="color: #0000c0;">=#&#xa0;\a</span><br/>б) убрать вывод заголовка таблицы <span style="color: #0000c0;">=#&#xa0;\pset tuples_only on</span>&#xa0;&#xa0;ИЛИ&#xa0; <span style="color: #0000c0;">=#&#xa0;\t</span><br/>в) заменить разделитель <span style="color: #0000c0;">=#&#xa0;\pset fieldsep ' '</span>
      </li>
      <li>
        Включить формат вывода <b>HTML</b>:&#xa0;<span style="color: #0000c0;">=#&#xa0;\pset format html</span>
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">echo '\timing on' &gt;&gt; ~/.psqlrc</span>&#xa0;&#xa0;# Настроить psql так, чтобы для каждой команды печаталось время ее выполнения. Убедиться, что при
    </p>
    <p>
      повторном запуске эта настройка сохраняется
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Данные" POSITION="bottom_or_right" ID="ID_1617442989" CREATED="1729173290426" MODIFIED="1729765375448"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1762993257">Работа с данными (SQL)</a>&#xa0; <a href="#ID_1498937792">БД</a>&#xa0; <a href="#ID_997515904"><span style="font-weight: normal;">Таблицы</span></a><span style="font-weight: normal;">&#xa0;</span>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Импорт данных</span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo -u postgres psql -d sysadmin_db &lt; schema.sql </span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo -u postgres psql -d sysadmin_db &lt; data.sql </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">psql -d sysadmin_db -c &quot;select count(*) from студенты;&quot;</span>&#xa0;&#xa0;&#xa0;# Проверить кол-во записей в БД
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Диагностика" POSITION="bottom_or_right" ID="ID_10249973" CREATED="1736336699170" MODIFIED="1736336876527"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">/var/crash/_usr_lib_postgresql_14_bin_postgres.115.crash</span>
    </p>
    <ul>
      <li>
        файл создается, когда происходит сбой процесса PostgreSQL
      </li>
      <li>
        &#xa0;Содержит информацию о состоянии процесса PostgreSQL на момент его краха
      </li>
      <li>
        115 -&#xa0;&#xa0;в названии файла указывает на идентификатор процесса (PID), который потерпел крах
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
