  <body>
    <p>
      &#1055;&#1056;&#1045;&#1044;&#1057;&#1058;&#1040;&#1042;&#1051;&#1045;&#1053;&#1048;&#1071;
    </p>
    <p>
      ~~~~~~~~~~~~~
    </p>
    <p>
      
    </p>
    <p>
      &#1057;&#1086;&#1079;&#1076;&#1072;&#1076;&#1080;&#1084; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1089;&#1091;&#1084;&#1084;&#1099; &#1076;&#1086;&#1093;&#1086;&#1076;&#1072; &#1087;&#1086; &#1075;&#1086;&#1088;&#1086;&#1076;&#1072;&#1084; &#1079;&#1072; &#1074;&#1089;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103;.
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; create view revenue_by_city as
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt;&#160;&#160;&#160;select city, sum(amount) from revenue group by city;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;CREATE VIEW
    </p>
    <p>
      
    </p>
    <p>
      &#1047;&#1072;&#1087;&#1088;&#1086;&#1089; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1087;&#1088;&#1080; &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1080; &#1082; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102;:
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; \timing on
    </p>
    <p>
