<node TEXT="Буфер запроса" POSITION="bottom_or_right" ID="ID_1316568480" CREATED="1528186065971" MODIFIED="1729083397684"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Буфер запроса</b>
    </p>
    <ul>
      <li>
        Последняя команда SQL попадает в буфер запроса.
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">=&gt; select now();</span>
    </p>
    <p>
      <span style="color: #0000c0;">=&gt; \p[rint]</span>&#xa0;&#xa0;-- Вывести содержимое буфера
    </p>
    <p>
      <span style="color: #0000c0;">=&gt; \g</span>&#xa0;&#xa0;-- Выполнить команду, не вводя ее заново
    </p>
    <p>
      <span style="color: #0000c0;">=&gt; \w[rite] &lt;file&gt;</span>&#xa0;-- Записать содержимое буфера в файл
    </p>
    <p>
      <span style="color: #0000c0;">=&gt; \r[eset]</span>&#xa0;&#xa0;-- Очистить буфер
    </p>
    <p>
      <span style="color: #0000c0;">=&gt; \watch &lt;seconds&gt;</span>&#xa0;&#xa0;-- Периодически выполнять команду из буфера
    </p>
    <p>
      <span style="color: #0000c0;">=&gt; \e[dit]</span>&#xa0;&#xa0;-- Отредактировать буфер, после чего отредактированная команда выполнится
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Индексы" FOLDED="true" POSITION="bottom_or_right" ID="ID_1802274103" CREATED="1526467732372" MODIFIED="1729179756466"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1949750923">Индексы</a>&#xa0; <a href="#ID_258267982">INDEX</a>&#xa0;
    </p>
    <p>
      &#xa0;
    </p>
    <p>
      <b>Индексы. </b>Индексы используются для получения быстрого доступа к (обычно) небольшой части имеющихся данных. Некоторые типы индексов выдают упорядоченные значения и могут также использоваться для сортировки.
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">\di </span>
    </p>
    <p>
      <span style="color: #008000;">\d &lt;таблица&gt; </span>
    </p>
    <p>
      <span style="color: #008000;">\d+ &lt;таблица&gt;</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">SELECT * FROM pg_stat_user_indexes;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Статистика</span>&#xa0;- как часто используются индексы
    </p>
    <p>
      <span style="color: #008000;">SELECT indexname, indexdef FROM pg_indexes WHERE tablename = '</span><span style="color: #0000c0;">имя таблицы</span><span style="color: #008000;">';</span>
    </p>
    <p>
      <span style="color: #008000;">SELECT schemaname, indexname, tablename FROM pg_indexes WHERE schemaname NOT IN ('pg_catalog', 'information_schema') ORDER BY schemaname, indexname;</span>
    </p>
    <p>
      <span style="color: #008000;">SELECT * FROM pg_indexes; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Детальная информация о структуре индексов</span>
    </p>
    <p>
      <span style="color: #008000;">SELECT </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;n.nspname AS schema_name, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;t.relname AS table_name, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;i.relname AS index_name, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;pg_get_indexdef(i.oid) AS index_definition </span>
    </p>
    <p>
      <span style="color: #008000;">FROM </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;pg_class t </span>
    </p>
    <p>
      <span style="color: #008000;">JOIN pg_index idx ON t.oid = idx.indrelid </span>
    </p>
    <p>
      <span style="color: #008000;">JOIN pg_class i ON i.oid = idx.indexrelid </span>
    </p>
    <p>
      <span style="color: #008000;">JOIN pg_namespace n ON t.relnamespace = n.oid </span>
    </p>
    <p>
      <span style="color: #008000;">WHERE </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;t.relkind = 'r'&#xa0;&#xa0;-- 'r' indicates ordinary tables </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;AND n.nspname NOT IN ('pg_catalog', 'information_schema') </span>
    </p>
    <p>
      <span style="color: #008000;">ORDER BY </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;schema_name, table_name, index_name; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Детальная информация о структуре индексов (по конкретной таблице)</span>
    </p>
    <p>
      <span style="color: #008000;">SELECT </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;n.nspname AS schema_name, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;t.relname AS table_name, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;i.relname AS index_name, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;pg_get_indexdef(i.oid) AS index_definition </span>
    </p>
    <p>
      <span style="color: #008000;">FROM </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;pg_class t </span>
    </p>
    <p>
      <span style="color: #008000;">JOIN pg_index idx ON t.oid = idx.indrelid </span>
    </p>
    <p>
      <span style="color: #008000;">JOIN pg_class i ON i.oid = idx.indexrelid </span>
    </p>
    <p>
      <span style="color: #008000;">JOIN pg_namespace n ON t.relnamespace = n.oid </span>
    </p>
    <p>
      <span style="color: #008000;">WHERE </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;t.relname = '</span><span style="font-weight: bold;">students</span><span style="color: #008000;">' </span>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-- Укажите имя таблицы
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;AND n.nspname NOT IN ('pg_catalog', 'information_schema');</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="Примеры" ID="ID_300290440" CREATED="1528451295362" MODIFIED="1729180228690"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      ИНДЕКСЫ
    </p>
    <p>
      ~~~~~~~
    </p>
    <p>
      
    </p>
    <p>
      Создадим большую таблицу:
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;=&gt; create table bigtable(id serial, t text);
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;CREATE TABLE
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;=&gt; insert into bigtable
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;=&gt;&#xa0;&#xa0;&#xa0;select s.id, 'This is a line #' || s.id from generate_series(1,1000000) as s(id);
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;INSERT 0 1000000
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;=&gt; select count(*) from bigtable;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;count&#xa0;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;---------
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;1000000
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;(1 row)
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      
    </p>
    <p>
      Сколько времени занимает поиск одного значения в такой таблице?
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;=&gt; <span style="color: #008000;">\timing on</span>
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Timing is on.
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;=&gt; select * from bigtable where id=42;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;id |&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;t&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;----+--------------------
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;42 | This is a line #42
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;(1 row)
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Time: 73,611 ms
    </p>
    <p>
      
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      
    </p>
    <p>
      Теперь проиндексируем таблицу:
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;=&gt; create unique index bigtable_id on bigtable(id);
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;CREATE INDEX
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Time: 336,124 ms
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;=&gt; select * from bigtable where id=42;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;id |&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;t&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;----+--------------------
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;42 | This is a line #42
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;(1 row)
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Time: 0,406 ms
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;=&gt; <span style="color: #008000;">\timing off</span>
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Timing is off.
    </p>
    <p>
      
    </p>
    <p>
      Индекс не является универсальным средством увеличения производительности. В общем случае
    </p>
    <p>
      индекс может быть полезен, если из таблицы требуется выбрать существенно меньше данных,
    </p>
    <p>
      чем в ней находится. Кроме того, надо учитывать накладные расходы на обновление индекса
    </p>
    <p>
      при изменении таблицы.
    </p>
    <p>
      
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Кластер" FOLDED="true" ID="ID_1252306682" CREATED="1728995842923" MODIFIED="1738333009916"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_812578722">pg_dumpall: копия кластера</a>&#xa0;&#xa0;<a href="#ID_861200213">Общие таблицы кластера</a>&#xa0; <a href="#ID_2188643">Репликация</a>&#xa0; <a href="#ID_758738649">High-Availability</a>&#xa0;&#xa0;&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Репликация</span>&#xa0;- процесс синхронизации содержимого между копиями
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Основной сервер</span>&#xa0;- <span style="font-weight: bold;">Primary Server</span>&#xa0;- <span style="font-weight: bold;">Master Server - </span>отвечает за обработку записей и предоставляет доступ к данным для операций чтения и записи
    </p>
    <p>
      <span style="font-weight: bold;">Резервный сервер</span>&#xa0;- <span style="font-weight: bold;">Standby Server</span>&#xa0;- <span style="font-weight: bold;">Replica Server</span>&#xa0;- служит для резервирования и может принимать на себя функции основного в случае его сбоя
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Автоматическое переключение (failover)</span>&#xa0;- в случае сбоя главного сервера, автоматическое переключение позволяет быстро и без вмешательства администратора активировать резервный сервер
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">Patroni</span>&#xa0;- framework, разработанный на языке python, для построения кластера Postgres высокой доступности на основе потоковой репликации. После установки и настройки Patroni на всех узлах, <span style="font-weight: bold;">Patroni сам определит</span>, какой узел будет мастером, а какие — слейвами, и обеспечит автоматическое переключение ролей в случае необходимости
      </li>
      <li>
        <span style="font-weight: bold;">pgpool-II</span>&#xa0;- выполняет мониторинг состояния серверов и может автоматически переключать роли между основным и резервным сервером при обнаружении проблем. Настройки на каждом узле. <span style="color: #ff0000;">Похоже лаб.работа взята как чать отсюда.</span>
      </li>
      <li>
        <span style="font-weight: bold;">Pacemaker + Corosync</span>&#xa0;- без прокси, настройки на каждом узле

        <ul>
          <li>
            Pacemaker - отвечает за управление ресурсами и состоянием узлов
          </li>
          <li>
            Corosync - обеспечивает коммуникацию между узлами и обнаружение отказов
          </li>
        </ul>
      </li>
      <li>
        <span style="font-weight: bold;">repmgr</span>&#xa0;- служба следит за состоянием серверов и, в случае отказа основного узла, автоматически инициирует процесс переключения на резервный
      </li>
      <li>
        PostgreSQL Automatic Failover (PAF) - выглядит неплохо, настройки на каждом сервере. Нужно компилировать. Репозиторий не обновлялся несколько лет
      </li>
      <li>
        Stolon - репозиторий несколько лет не обновляется, ставится через Go. SQLIte на каждом узле
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">pg_lsclusters</span>&#xa0;&#xa0;# Статус кластера
    </p>
    <p>
      <span style="color: #0000c0;">pg_ctlcluster 14 main status&#xa0;&#xa0;# </span>pg_ctlcluster &lt;версия&gt; &lt;кластер&gt; status
    </p>
    <ul>
      <li>
        &#xa0;&#xa0;&#xa0;&#xa0;start — для запуска кластера.
      </li>
      <li>
        &#xa0;&#xa0;&#xa0;&#xa0;stop — для остановки кластера.
      </li>
      <li>
        &#xa0;&#xa0;&#xa0;&#xa0;restart — для перезапуска кластера.
      </li>
      <li>
        &#xa0;&#xa0;&#xa0;&#xa0;promote — для повышения резервного кластера до основного.
      </li>
      <li>
        &#xa0;&#xa0;&#xa0;&#xa0;demote — для понижения основного кластера до резервного.
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">pg_createcluster &lt;версия&gt; &lt;имя_кластера&gt;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создает</span>&#xa0;новый кластер PostgreSQL
    </p>
    <p>
      <span style="color: #0000c0;">pg_dropcluster &lt;версия&gt; &lt;имя_кластера&gt;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Удаляет</span>&#xa0;существующий кластер PostgreSQL
    </p>
    <p>
      <span style="color: #0000c0;">pg_ctlcluster &lt;версия&gt; &lt;имя_кластера&gt; start</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Управляет</span>&#xa0;состоянием кластеров (запуск, остановка, перезапуск)
    </p>
    <p>
      <span style="color: #0000c0;">pg_upgradecluster &lt;старая_версия&gt; &lt;имя_старого_кластера&gt; &lt;новая_версия&gt;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Обновление</span>&#xa0;кластера до новой версии PostgreSQL
    </p>
    <p>
      <span style="color: #0000c0;">pg_renamecluster &lt;версия&gt; &lt;старое_имя&gt; &lt;новое_имя&gt;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Переименование</span>&#xa0;кластера PostgreSQL
    </p>
    <p>
      <span style="color: #0000c0;">pg_promotecluster &lt;версия&gt; &lt;имя_реплицируемого_кластера&gt;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Повышение реплики</span>&#xa0;до основного сервера (если используется репликация)
    </p>
  </body>
</html></richcontent>
<node TEXT="Пример. Трансляция журналов на резервные серверы" ID="ID_1016300686" CREATED="1728998881938" MODIFIED="1735467389754"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_646967228">Установка PostgreSQL на Ubuntu 22.04</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Трансляция журналов на резервные серверы</span><span style="font-weight: normal;">&#xa0;(один из видов кластеров)</span>
    </p>
    <ul>
      <li>
        главный сервер постоянно транслирует изменения на резервные
      </li>
      <li>
        если главный сервер выйдет из строя, его функции заберёт один из запасных
      </li>
      <li>
        сервера PostgreSQL одинаковой версии
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">-----Главный сервер-----</span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo -u postgres createuser --replication -P </span><span style="color: #0000c0; font-weight: bold;">syncuser</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать роль</span>, с которой будет подключаться резервный сервер
    </p>
    <ul>
      <li>
        -P здесь - ввод пароля для новой роли
      </li>
      <li>
        --replication - права пользователя на репликацию
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">vim /etc/postgresql/14/main/</span><span style="color: #0000c0; font-weight: bold;">pg_hba.conf</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Настроить аутентификацию</span>&#xa0;для созданной роли syncuser
    </p>
    <p>
      <span style="color: #008000;">host&#xa0;&#xa0;</span><span style="color: #008000; font-weight: bold;">replication</span><span style="color: #008000;">&#xa0;&#xa0;&#xa0;</span><span style="color: #008000; font-weight: normal;">syncuser</span><span style="color: #008000;">&#xa0;&#xa0;&#xa0;&lt;IP резервного сервера&gt;/32&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;scram-sha-256</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">replication</span>&#xa0;- вместо БД здесь специальная псевдобаза, что даёт роли право подключаться для репликации
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">vim /etc/postgresql/14/main/</span><span style="color: #0000c0; font-weight: bold;">postgresql.conf</span><span style="font-weight: normal;">&#xa0;&#xa0;# </span><span style="font-weight: bold;">Настроить WAL</span>
    </p>
    <p>
      <span style="color: #008000;">wal_level = replica</span>
    </p>
    <ul>
      <li>
        WAL (Write Ahead Log) - журнал предзаписи, обеспечивающий целостность данных: информация записывается сначала в него, а затем изменяется уже в самой БД на диске
      </li>
      <li>
        WAL можно воспринимать как журнал транзакций, а wal_level определяет объём записываемых в него данных
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">systemctl restart postgresql</span>&#xa0;&#xa0;# Перезапустить сервер
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">-----Резервный сервер----- </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #0000c0;">apt update &amp;&amp; apt upgrade -y </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #0000c0;">apt install postgresql</span>
    </p>
    <p>
      <span style="font-weight: normal; color: #0000c0;">vim /etc/postgresql/14/main/postgresql.conf</span><span style="font-weight: normal;">&#xa0;&#xa0;# Обслуживать запросы на чтение параллельно с главным сервером </span>
    </p>
    <p>
      <span style="color: #008000;">hot_standby = on</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl </span><span style="color: #0000c0; font-weight: bold;">stop</span><span style="color: #0000c0;">&#xa0;postgresql</span>&#xa0;&#xa0;# Остановить службу
    </p>
    <p>
      <span style="color: #0000c0;">sudo -u postgres rm -rf /var/lib/postgresql/14/main/</span>&#xa0;&#xa0;# Удалить текущие БД на резервном сервере
    </p>
    <p>
      <span style="color: #0000c0;">sudo -u postgres pg_basebackup -h MAIN_IP -D /var/lib/postgresql/14/main -U syncuser -P -v -R</span>&#xa0;&#xa0;# Создать бэкап БД с главного сервера. Использовать ранее созданную роль syncuser
    </p>
    <ul>
      <li>
        h MAIN_IP - адрес главного сервера
      </li>
      <li>
        D - каталог, куда нужно положить бэкап
      </li>
      <li>
        U - пользователь для подключения
      </li>
      <li>
        P - запрашивает ввод пароля
      </li>
      <li>
        v - выводит подробный лог выполнения команды
      </li>
      <li>
        R - создаёт в каталоге с базами данных файл standby.signal. Это маркер для сервера PostgreSQL, что нужно запуститься в резервном режиме
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">systemctl start postgresql</span>&#xa0;&#xa0;# Запустить службу
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">pg_ctlcluster 14 main promote</span>&#xa0;&#xa0;#&#xa0; <span style="font-weight: bold;">Ручное переключение&#xa0;резервного кластера PostgreSQL в режим основного</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Patroni" FOLDED="true" ID="ID_1091147403" CREATED="1735920544773" MODIFIED="1773051964978"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_630945607">etcd</a>&#xa0; <a href="#ID_980063778">PostgreSQL</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Patroni</span>&#xa0;- инструмент оркестрации высокой доступности (High Availability Orchestrator) для PostgreSQL, который автоматизирует управление репликацией, мониторинг состояния узлов и отработку отказов (failover), используя распределённое хранилище (etcd, Consul, ZooKeeper, Kubernetes) для достижения консенсуса и выбора лидера. На базе Python
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Основные возможности</span>
    </p>
    <ul>
      <li>
        Автоматический failover - Автоматическое повышение реплики до лидера при сбое
      </li>
      <li>
        Ручное/плановое переключение - Команда failover или switchover для контролируемой смены лидера
      </li>
      <li>
        Репликация - Поддержка синхронной, асинхронной и каскадной репликации
      </li>
      <li>
        pg_rewind - Автоматический запуск для восстановления рассинхронизированных узлов
      </li>
      <li>
        Event hooks - Обработчики событий: смена роли, старт/стоп/рестарт узла
      </li>
      <li>
        REST API - Мониторинг и управление через :8008
      </li>
      <li>
        CLI (patronictl) - Управление кластером из командной строки
      </li>
      <li>
        DCS - критический компонент: потеря кворума etcd/Consul блокирует переключения
      </li>
      <li>
        Начинайте с асинхронной репликации и patronictl, постепенно добавляя синхронную репликацию и event hooks по мере роста требований к HA
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="/etc/patroni.yml" ID="ID_932264160" CREATED="1773050109055" MODIFIED="1773051873135"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1642398281">YAML</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Конфигурация Patroni</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># ==================== Блок настройки PostgreSQL ==================== </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">postgresql: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Путь к бинарным файлам PostgreSQL (initdb, pg_ctl, postgres и др.) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;bin_dir: /usr/lib/postgresql/14/bin </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Директория для хранения данных кластера PostgreSQL (PGDATA) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;data_dir: /var/lib/postgresql/data </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Адрес и порт, на котором PostgreSQL будет слушать подключения </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# 0.0.0.0 — слушать все сетевые интерфейсы </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;listen: 0.0.0.0:5432 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Публичный адрес узла для подключения других узлов кластера и клиентов </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Должен быть достижим извне, в отличие от listen </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;connect_address: 10.128.0.3:5432 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Настройки аутентификации для внутренних операций Patroni </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;authentication: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# Учётная запись для репликации между узлами </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;replication: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;username: replicator&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Логин репликатора </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;password: &lt;secret&gt;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Пароль (лучше использовать secrets из DCS) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# Учётная запись суперпользователя для управления экземпляром </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;superuser: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;username: postgres&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Логин суперпользователя </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;password: &lt;secret&gt;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Пароль </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Параметры postgresql.conf, которые Patroni будет управлять автоматически </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;parameters: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# Уровень записи WAL: replica — обязательно для репликации </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;wal_level: replica </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# Разрешить чтение на репликах (hot standby) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;hot_standby: &quot;on&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# Включение архивирования WAL-файлов </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;archive_mode: &quot;on&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# Команда для архивации: копирование в локальную директорию </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# %p — полный путь к файлу, %f — имя файла </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;archive_command: 'cp %p /var/lib/postgresql/wal_archive/%f' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# Требуется для работы pg_rewind при рассинхронизации узлов </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;wal_log_hints: &quot;on&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# Максимальное количество одновременных репликационных соединений </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;max_wal_senders: 10 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# Количество WAL-файлов для ретеншена в pg_wal (для ускорения восстановления) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;wal_keep_size: 128MB </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Директория для архивных WAL-файлов (должна существовать и быть доступна) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;recovery_conf: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;restore_command: 'cp /var/lib/postgresql/wal_archive/%f %p' </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># ==================== Настройки REST API Patroni ==================== </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">restapi: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Адрес и порт для прослушивания входящих HTTP-запросов к API </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;listen: 0.0.0.0:8008 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Публичный адрес API, который используют другие узлы для проверки здоровья </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;connect_address: 10.128.0.3:8008 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# (Опционально) Базовая аутентификация для защиты API </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# authentication: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;#&#xa0;&#xa0;&#xa0;username: admin </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;#&#xa0;&#xa0;&#xa0;password: &lt;api_secret&gt; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># ==================== Настройки распределённого хранилища (DCS) ==================== </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Patroni использует DCS для хранения состояния кластера и выбора лидера </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">etcd: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Список адресов узлов etcd (формат: хост:порт) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# Patroni попробует подключиться к любому из них </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;hosts: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;- 10.128.0.2:2379 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;- 10.128.0.5:2379 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;- 10.128.0.6:2379 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# (Опционально) Префикс ключей в DCS — полезно для изоляции нескольких кластеров </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# namespace: /service/postgres-prod </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># ==================== Теги управления поведением узла ==================== </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">tags: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# true — узел никогда не будет повышен до лидера (только реплика) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;nofailover: false </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# true — узел исключается из балансировки читающих подключений </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;noloadbalance: false </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# true — узел может быть использован как источник для клонирования новых узлов </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;clonefrom: false </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;# true — узел будет получать приоритет при выборе лидера (но не гарантия) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;nosync: false</span>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        connect_address - Чтобы другие узлы знали, как подключиться к этому экземпляру<br/>&lt;реальный_ип&gt;:5432
      </li>
      <li>
        wal_log_hints - Обязателен для работы pg_rewind<br/>&quot;on&quot;
      </li>
      <li>
        archive_command - Сохранение WAL для восстановления и репликации<br/>cp %p /archive/%f
      </li>
      <li>
        nofailover - Исключить узел из кандидатов в лидеры (например, для реплики только на чтение)<br/>true/false
      </li>
      <li>
        hosts в etcd - Обеспечение отказоустойчивости самого DCS. Минимум 3 адреса
      </li>
      <li>
        Не храните пароли в открытом виде в `patroni.yml`. Используйте возможности вашего DCS (например, etcd с аутентификацией) или внешние секрет-менеджеры, а в конфиге указывайте только ссылки на них.
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="/etc/patroni.yml" ID="ID_895333887" CREATED="1738652202770" MODIFIED="1738652582259"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">--- </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">scope: my_cluster </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">namespace: /service/ </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">name: db-01 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">restapi: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;listen: 0.0.0.0:8008 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;connect_address: 10.128.0.3:8008 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">etcd: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;hosts: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- 10.128.0.3:2379 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- 10.128.0.4:2379 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- 10.128.0.9:2379 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">bootstrap: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;dcs: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ttl: 30 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;loop_wait: 10 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;retry_timeout: 10 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;# maximum_lag_on_failover: 1048576&#xa0;&#xa0;# Пока пробую без него </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;# master_start_timeout: 300 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;# synchronous_mode: false </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;postgresql: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;use_pg_rewind: true </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;use_slots: true </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;parameters: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;wal_level: replica </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;hot_standby: &quot;on&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;logging_collector: 'on' </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;max_wal_senders: 5 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;max_replication_slots: 5 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;wal_log_hints: &quot;on&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;#archive_mode: &quot;on&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;#archive_timeout: 600 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;#archive_command: &quot;cp -f %p /home/postgres/archived/%f&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;#recovery_conf: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;#restore_command: cp /home/postgres/archived/%f %p </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;pg_hba: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- host replication replicator 10.128.0.0/24 scram-sha-256 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- host replication replicator 127.0.0.1/32 trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- host all all 10.128.0.0/24 scram-sha-256 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- local all all trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- host all all 127.0.0.1/32 trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- host all all ::1/128 trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- local replication all trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- host replication all 127.0.0.1/32 trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- host replication all ::1/128 trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;pg_hba: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- host replication replicator 10.128.0.0/24 scram-sha-256 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- host replication replicator 127.0.0.1/32 trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- host all all 10.128.0.0/24 scram-sha-256 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- local all all trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- host all all 127.0.0.1/32 trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- host all all ::1/128 trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- local replication all trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- host replication all 127.0.0.1/32 trust </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- host replication all ::1/128 trust </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;initdb:&#xa0;&#xa0;# Note: It needs to be a list (some options need values, others are switches) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- encoding: UTF8 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;- data-checksums </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;post_bootstrap: /usr/local/bin/patroni.post-bootstrap.sh </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">postgresql: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;listen: 0.0.0.0:5432 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;connect_address: 10.128.0.3:5432 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;data_dir: &quot;/var/lib/postgresql/14/main&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;bin_dir: &quot;/usr/lib/postgresql/14/bin&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;config_dir: &quot;/etc/postgresql/14/main&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;pgpass: /tmp/pgpass0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;authentication: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;replication: </span>
