<node TEXT="patroni.service" ID="ID_1325017533" CREATED="1736497605784" MODIFIED="1736589259568"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_407747048">Сервисы</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/systemd/system/patroni.service</span>&#xa0;&#xa0;# Создать файл сервиса patroni
    </p>
    <p>
      <span style="color: #008000;">[Unit] </span>
    </p>
    <p>
      <span style="color: #008000;">Description=Patroni high-availability PostgreSQL </span>
    </p>
    <p>
      <span style="color: #008000;">After=network-online.target </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000;">[Service] </span>
    </p>
    <p>
      <span style="color: #008000;">User=postgres </span>
    </p>
    <p>
      <span style="color: #008000;">Type=simple </span>
    </p>
    <p>
      <span style="color: #008000;">ExecStart=/usr/local/bin/patroni /etc/patroni.yml </span>
    </p>
    <p>
      <span style="color: #008000;">Restart=always </span>
    </p>
    <p>
      <span style="color: #008000;">RestartSec=5 </span>
    </p>
    <p>
      <span style="color: #008000;">LimitNOFILE=1024 </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000;">[Install] </span>
    </p>
    <p>
      <span style="color: #008000;">WantedBy=multi-user.target</span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">systemctl daemon-reload</span>&#xa0;&#xa0;# Перечитать файлы юнитов. Система пересматривает все файлы юнитов (*.service, *.socket, *.target и т.д.)
    </p>
    <p>
      <span style="color: #0000c0;">systemctl enable patroni.service </span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl start patroni.service</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Команды" ID="ID_1066172650" CREATED="1773051843532" MODIFIED="1773052299328"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Чеклист перед запуском</span>
    </p>
    <p>
      # Директория данных существует и имеет правильные права
    </p>
    <p>
      <span style="color: #0000c0;">sudo mkdir -p /var/lib/postgresql/data </span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo chown -R postgres:postgres /var/lib/postgresql/data </span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo chmod 700 /var/lib/postgresql/data</span>
    </p>
    <p>
      # Директория для WAL-архива подготовлена
    </p>
    <p>
      <span style="color: #0000c0;">sudo mkdir -p /var/lib/postgresql/wal_archive </span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo chown postgres:postgres /var/lib/postgresql/wal_archive</span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo rm -rf /var/lib/postgresql/wal_archive/*</span>&#xa0;&#xa0;# Очистка при неудачном первом запуске
    </p>
    <p>
      # Конфигурационный файл доступен пользователю postgres
    </p>
    <p>
      <span style="color: #0000c0;">sudo chown postgres:postgres /etc/patroni.yml </span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo chmod 644 /etc/patroni.yml</span>
    </p>
    <p>
      # Сеть: порты 5432 и 8008 открыты между узлами кластера
    </p>
    <p>
      # DCS (etcd) доступен и отвечает на запросы
    </p>
    <p>
      <span style="color: #0000c0;">etcdctl --endpoints=http://10.128.0.2:2379 endpoint health </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Запуск</span>
    </p>
    <p>
      <span style="color: #0000c0;">sudo -u postgres patroni /etc/patroni.yml</span>&#xa0;&#xa0;# От имени пользователя postgres
    </p>
    <p>
      <span style="color: #0000c0;">sudo systemctl start patroni</span>&#xa0;&#xa0;# Или как systemd-сервис (рекомендуется)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Управление через patronictl</span>
    </p>
    <p>
      <span style="color: #0000c0;">patronictl -c /etc/patroni.yml list</span>&#xa0;&#xa0;# Список узлов в кластере и их роли. Кто лидер, кто реплика
    </p>
    <p>
      <span style="color: #0000c0;">patronictl -c /etc/patroni.yml switchover</span>&#xa0;&#xa0;# Плановая смена лидера (без потерь)
    </p>
    <p>
      <span style="color: #0000c0;">patronictl -c /etc/patroni.yml failover</span>&#xa0;&#xa0;# Аварийное переключение (failover)
    </p>
    <p>
      <span style="color: #0000c0;">patronictl -c /etc/patroni.yml failover --force --candidate db-01</span>
    </p>
    <p>
      <span style="color: #0000c0;">patronictl -c /etc/patroni.yml restart db-01</span>&#xa0;&#xa0;# Перезапуск узла
    </p>
    <p>
      <span style="color: #0000c0;">patronictl -c /etc/patroni.yml history</span>&#xa0;&#xa0;# Просмотр истории событий
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Мониторинг</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl http://10.128.0.3:8008/patroni</span>&#xa0;&#xa0;# Статус узла через REST API
    </p>
    <p>
      <span style="color: #0000c0;">curl http://10.128.0.3:8008</span>&#xa0;&#xa0;# краткий статус
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Проверка DCS (etcd)</span>
    </p>
    <p>
      <span style="color: #0000c0;">etcdctl member list</span>
    </p>
    <p>
      <span style="color: #0000c0;">etcdctl get /service/batman/leader --print-value-only</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
