<node TEXT="Статистика вызова функций" ID="ID_1552429897" CREATED="1528970269140" MODIFIED="1528970285637"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1058;&#1040;&#1058;&#1048;&#1057;&#1058;&#1048;&#1050;&#1040; &#1042;&#1067;&#1047;&#1054;&#1042;&#1040; &#1060;&#1059;&#1053;&#1050;&#1062;&#1048;&#1049;</b>
    </p>
    <p>
      &#1057;&#1086;&#1079;&#1076;&#1072;&#1076;&#1080;&#1084; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102;:
    </p>
    <p>
      =&gt; create function f() returns integer as $$ select 1; $$ language sql;
    </p>
    <p>
      =&gt; begin;
    </p>
    <p>
      =&gt; select sum(f()) from generate_series(1,100);
    </p>
    <p>
      =&gt; select * from pg_stat_xact_user_functions;
    </p>
    <p>
      =&gt; commit;
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1086;&#1095;&#1077;&#1084;&#1091; &#1085;&#1077;&#1090; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080;? &#1044;&#1077;&#1083;&#1086; &#1074; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1087;&#1088;&#1086;&#1089;&#1090;&#1099;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1087;&#1086;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1085;&#1077;&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1074; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;.
    </p>
    <p>
      &#1057;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1085;&#1077; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;.
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      &#1057;&#1086;&#1079;&#1076;&#1072;&#1076;&#1080;&#1084; &#1073;&#1086;&#1083;&#1077;&#1077; &#1089;&#1083;&#1086;&#1078;&#1085;&#1091;&#1102; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102;.
    </p>
    <p>
      =&gt; create function f1() returns integer as $$ begin return 1; end; $$ language plpgsql;
    </p>
    <p>
      =&gt; begin;
    </p>
    <p>
      =&gt; select sum(f1()) from generate_series(1,100);
    </p>
    <p>
      =&gt; select * from pg_stat_xact_user_functions;
    </p>
    <p>
      =&gt; commit;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Анализ журнала" ID="ID_5476488" CREATED="1528970315194" MODIFIED="1528970331142"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1040;&#1053;&#1040;&#1051;&#1048;&#1047; &#1046;&#1059;&#1056;&#1053;&#1040;&#1051;&#1040;</b>
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1089;&#1072;&#1084;&#1099;&#1081; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086;&#1081; &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1085;&#1072;&#1089; &#1080;&#1085;&#1090;&#1077;&#1088;&#1077;&#1089;&#1091;&#1102;&#1090; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; FATAL:
    </p>
    <p>
      $ grep FATAL ~postgres/logfile | tail -n 10&#160;&#160;# &#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; terminating connection &#1074;&#1099;&#1079;&#1074;&#1072;&#1085;&#1086; &#1090;&#1077;&#1084;, &#1095;&#1090;&#1086; &#1084;&#1099; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1072;&#1083;&#1080; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;.
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      &#1053;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1084; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1074;&#1099;&#1076;&#1072;&#1095;&#1080; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072;.
    </p>
    <p>
      =&gt; alter system set log_line_prefix='!!! pid=%p: ';
    </p>
    <p>
      =&gt; alter system set log_duration='on';
    </p>
    <p>
      =&gt; alter system set log_statement='all';
    </p>
    <p>
      pg_ctl reload
    </p>
    <p>
      server signaled
    </p>
    <p>
      ---------------------------------------------------------------------
    </p>
    <p>
      &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1084; &#1082;&#1072;&#1082;&#1091;&#1102;-&#1085;&#1080;&#1073;&#1091;&#1076;&#1100; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091;:
    </p>
    <p>
      =&gt; select sum(random()) from generate_series(1,1000000);
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      &#1048; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;:
    </p>
    <p>
      $ egrep ^!!! ~postgres/logfile | tail -n 2
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Коллектор статистики" ID="ID_425713488" CREATED="1528965027110" MODIFIED="1528967944351"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1073;&#1086;&#1088; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080;. </b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; <b>stats collector</b>
    </p>
    <p>
      &#1042;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1077; &#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072; &#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;&#1080;&#1085;&#1075;&#1072; PostgreSQL &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1090; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1080; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
    </p>
    <p>
      &#1057;&#1073;&#1086;&#1088;&#1086;&#1084; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080; &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;&#1089;&#1103; &#1092;&#1086;&#1085;&#1086;&#1074;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; <b>stats collector</b>.
    </p>
    <p>
      &#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086;&#1084; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1095;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1090;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1080; &#1085;&#1072;&#1082;&#1083;&#1072;&#1076;&#1085;&#1099;&#1077; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1099;.
    </p>
    <ul>
      <li>
        &#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1080; &#1092;&#1086;&#1085;&#1086;&#1074;&#1099;&#1093; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1074; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; - <b>track_activities</b>&#160;- &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;
      </li>
      <li>
        &#1054;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1103; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1084; &#1080; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1072;&#1084; (&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1099;, &#1079;&#1072;&#1090;&#1088;&#1086;&#1085;&#1091;&#1090;&#1099;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;) - <b>track_counts</b>&#160;- &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;, &#1085;&#1091;&#1078;&#1077;&#1085; &#1076;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080;
      </li>
      <li>
        <p>
          &#1054;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1103; &#1082; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072;&#1084; - <b>track_io_timing</b>&#160;- &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;
        </p>
      </li>
      <li>
        <p>
          &#1042;&#1099;&#1079;&#1086;&#1074;&#1099; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081; - <b>track_functions - </b>&#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;
        </p>
      </li>
    </ul>
    <p>
      &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1091;&#1102; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1086;&#1081; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1080;. &#1047;&#1072;&#1090;&#1077;&#1084; &#1101;&#1090;&#1072; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1072; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1091;-&#1082;&#1086;&#1083;&#1083;&#1077;&#1082;&#1090;&#1086;&#1088;&#1091;. &#1050;&#1086;&#1083;&#1083;&#1077;&#1082;&#1090;&#1086;&#1088; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090; &#1080; &#1072;&#1075;&#1088;&#1077;&#1075;&#1080;&#1088;&#1091;&#1077;&#1090; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1089;&#1086; &#1074;&#1089;&#1077;&#1093; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1074;. &#1056;&#1072;&#1079; &#1074; &#1087;&#1086;&#1083;&#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1099; (&#1074;&#1088;&#1077;&#1084;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1103;&#1094;&#1080;&#1080;) &#1082;&#1086;&#1083;&#1083;&#1077;&#1082;&#1090;&#1086;&#1088; &#1089;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1074; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; <b>$PGDATA/pg_stat_temp</b>. (&#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1087;&#1077;&#1088;&#1077;&#1085;&#1077;&#1089;&#1077;&#1085;&#1080;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072; &#1074; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1091;&#1102; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091; &#1074; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1089;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080;)
    </p>
    <p>
      &#1050;&#1086;&#1075;&#1076;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1079;&#1072;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1077;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1077; (&#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1080;&#1083;&#1080; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;), &#1074; &#1077;&#1075;&#1086; &#1087;&#1072;&#1084;&#1103;&#1090;&#1100; &#1095;&#1080;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1103;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072;&#1103; &#1074;&#1077;&#1088;&#1089;&#1080;&#1103; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080; &#8212; &#1101;&#1090;&#1086; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1085;&#1080;&#1084;&#1082;&#1086;&#1084; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080;.
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1087;&#1086;&#1087;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1103;&#1074;&#1085;&#1086;, &#1089;&#1085;&#1080;&#1084;&#1086;&#1082; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1086; &#1082;&#1086;&#1085;&#1094;&#1072; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1080;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1090;&#1100; &#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1089;&#1090;&#1100;.
    </p>
    <p>
      &#1058;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1080;&#1079;-&#1079;&#1072; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1077;&#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; &#1085;&#1077; &#1089;&#1072;&#1084;&#1091;&#1102; &#1089;&#1074;&#1077;&#1078;&#1091;&#1102; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#8212; &#1085;&#1086; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1101;&#1090;&#1086; &#1080; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103;.
    </p>
    <p>
      &#1055;&#1088;&#1080; &#1086;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1082;&#1086;&#1083;&#1083;&#1077;&#1082;&#1090;&#1086;&#1088; &#1089;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1074; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1074; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; <b>$PGDATA/pg_stat</b>.
    </p>
  </body>
</html></richcontent>
</node>
