    <p>
      <b>&#1046;&#1091;&#1088;&#1085;&#1072;&#1083; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;</b>
    </p>
    <p>
      &#1042; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1086;&#1095;&#1090;&#1080; &#1074;&#1077;&#1089;&#1100; &#1074;&#1099;&#1074;&#1086;&#1076; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1087;&#1088;&#1077;&#1074;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072; &#1074; &#1091;&#1079;&#1082;&#1086;&#1077; &#1084;&#1077;&#1089;&#1090;&#1086; &#1076;&#1083;&#1103; &#1076;&#1080;&#1089;&#1082;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1040;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;
    </p>
    <p>
      &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1088;&#1077;&#1096;&#1080;&#1090;&#1100;, &#1082;&#1072;&#1082;&#1072;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1074;&#1072;&#1078;&#1085;&#1072;, &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1090;&#1100; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1077; &#1084;&#1077;&#1089;&#1090;&#1086; &#1085;&#1072; &#1076;&#1080;&#1089;&#1082;&#1077; &#1076;&#1083;&#1103; &#1077;&#1077; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1080; &#1086;&#1094;&#1077;&#1085;&#1080;&#1090;&#1100; &#1074;&#1083;&#1080;&#1103;&#1085;&#1080;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072; &#1085;&#1072; &#1086;&#1073;&#1097;&#1091;&#1102; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;.
