<node TEXT="Ротация журналов" ID="ID_913149341" CREATED="1528968324169" MODIFIED="1528969078404"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1056;&#1086;&#1090;&#1072;&#1094;&#1080;&#1103; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1086;&#1074;. </b>&#1045;&#1089;&#1083;&#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; <font color="#0000c0">$ pg_ctl start -l logfile</font>, &#1090;&#1086; &#1074;&#1099;&#1074;&#1086;&#1076; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1084; &#1092;&#1072;&#1081;&#1083;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1099;&#1088;&#1072;&#1089;&#1090;&#1080; &#1076;&#1086; &#1086;&#1075;&#1088;&#1086;&#1084;&#1085;&#1099;&#1093; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1086;&#1074;. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1090;&#1072; &#1080;&#1083;&#1080; &#1080;&#1085;&#1072;&#1103; &#1089;&#1093;&#1077;&#1084;&#1072; &#1088;&#1086;&#1090;&#1072;&#1094;&#1080;&#1080; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1086;&#1074;.
    </p>
    <p>
      <b>&#1042;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1077; &#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072;</b>&#160;(&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;, &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;)
    </p>
    <ul>
      <li>
        <b>logging_collector = on</b>&#160;&#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1092;&#1086;&#1085;&#1086;&#1074;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;, &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1102;&#1097;&#1080;&#1081; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1080; &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081; &#1080;&#1093; &#1074; &#1092;&#1072;&#1081;&#1083;&#1099;
      </li>
      <li>
        <b>log_destination = stderr, csvlog, syslog...</b>&#160;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072;
      </li>
      <li>
        <b>log_truncate_on_rotation = on</b>&#160;&#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1091;&#1078;&#1077; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099;
      </li>
      <li>
        <b>log_filename</b>&#160;&#1084;&#1072;&#1089;&#1082;&#1072; &#1080;&#1084;&#1077;&#1085;&#1080; &#1092;&#1072;&#1081;&#1083;&#1072;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1084;&#1086;&#1075;&#1091;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1087;&#1077;&#1094;&#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1099; &#1076;&#1072;&#1090;&#1099; &#1080; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;
      </li>
      <li>
        <b>log_rotation_age</b>&#160;&#1074;&#1088;&#1077;&#1084;&#1103; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1081; &#1092;&#1072;&#1081;&#1083; &#1074; &#1084;&#1080;&#1085;&#1091;&#1090;&#1072;&#1093;.
      </li>
      <li>
        &#1082;&#1086;&#1084;&#1073;&#1080;&#1085;&#1080;&#1088;&#1091;&#1103; &#1084;&#1072;&#1089;&#1082;&#1091; &#1092;&#1072;&#1081;&#1083;&#1072; &#1080; &#1074;&#1088;&#1077;&#1084;&#1103; &#1088;&#1086;&#1090;&#1072;&#1094;&#1080;&#1080;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084; &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1089;&#1093;&#1077;&#1084;&#1099;:<br/>postgresql-%H.log, 60 24 &#1092;&#1072;&#1081;&#1083;&#1072; &#1074; &#1089;&#1091;&#1090;&#1082;&#1080;<br/>postgresql-%a.log, 1440 7 &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1074; &#1085;&#1077;&#1076;&#1077;&#1083;&#1102;
      </li>
    </ul>
    <p>
      <b>&#1042;&#1085;&#1077;&#1096;&#1085;&#1080;&#1077; &#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072;.</b>&#160;&#1040;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1086;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1084;&#1080; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072;&#1084;&#1080; &#1088;&#1086;&#1090;&#1072;&#1094;&#1080;&#1080;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; rotatelogs.
    </p>
    <ul>
      <li>
        &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, Apache rotatelogs
      </li>
      <li>
        pg_ctl start | rotatelogs &#1080;&#1084;&#1103;_&#1092;&#1072;&#1081;&#1083;&#1072; 86400 -n 24
      </li>
    </ul>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
