<node TEXT="Путь поиска" ID="ID_651849249" CREATED="1528523050232" MODIFIED="1529096892838"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1091;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1080;&#1089;&#1082; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074;</b>
    </p>
    <ul>
      <li>
        &#1082;&#1074;&#1072;&#1083;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103; (schema.name) &#1103;&#1074;&#1085;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1089;&#1093;&#1077;&#1084;&#1091;
      </li>
      <li>
        &#1080;&#1084;&#1103; &#1073;&#1077;&#1079; &#1082;&#1074;&#1072;&#1083;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1072; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1089;&#1093;&#1077;&#1084;&#1072;&#1093;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074; &#1087;&#1091;&#1090;&#1080; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;
      </li>
    </ul>
    <p>
      <b>&#1055;&#1091;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;</b>
    </p>
    <p>
      <font color="#0000c0">SHOW search_path;</font>&#160;&#160;-- &#1055;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1087;&#1091;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;. (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#8212; &quot;$user&quot;,public)
    </p>
    <ul>
      <li>
        &quot;$user&quot; &#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090; &#1089;&#1093;&#1077;&#1084;&#1091; &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1089;&#1093;&#1077;&#1084;&#1072; &#1085;&#1077; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090;, &#1086;&#1085;&#1072; &#1080;&#1075;&#1085;&#1086;&#1088;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;
      </li>
      <li>
        &#1087;&#1077;&#1088;&#1074;&#1072;&#1103; &#1103;&#1074;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1072;&#1103; &#1074; &#1087;&#1091;&#1090;&#1080; (&#1080; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1072;&#1103;) &#1089;&#1093;&#1077;&#1084;&#1072; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1081; &#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074;
      </li>
    </ul>
    <p>
      <b>&#1055;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;</b>&#160; (&#1072; &#1079;&#1085;&#1072;&#1095;&#1080;&#1090;, &#1080;&#1084;&#1103; &#1077;&#1097;&#1077; &#1085;&#1077; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090;) &#1086;&#1085; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090; &#1074; &#1087;&#1077;&#1088;&#1074;&#1091;&#1102; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1091;&#1102; &#1074; &#1087;&#1091;&#1090;&#1080; &#1089;&#1093;&#1077;&#1084;&#1091;.
    </p>
    <p>
      &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1086;&#1076;&#1089;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090; &#1076;&#1074;&#1072; &#1089;&#1094;&#1077;&#1085;&#1072;&#1088;&#1080;&#1103;.
    </p>
    <p>
      1. &#1042;&#1089;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1089;&#1086; &#1089;&#1093;&#1077;&#1084;&#1086;&#1081; public.
    </p>
    <p>
      2. &#1045;&#1089;&#1083;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1089;&#1093;&#1077;&#1084;&#1091; &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1101;&#1090;&#1086;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1089;&#1086; &#1089;&#1074;&#1086;&#1077;&#1081; &#1089;&#1093;&#1077;&#1084;&#1086;&#1081;.
    </p>
    <p>
      &#1052;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1089;&#1094;&#1077;&#1085;&#1072;&#1088;&#1080;&#1080;, &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1074; &#1087;&#1091;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;.
    </p>
    <p>
      
    </p>
    <p>
      <b>set search_path</b>&#160;&#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1091;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072; &#1085;&#1072; &#1074;&#1088;&#1077;&#1084;&#1103; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Специальные случаи" ID="ID_809174029" CREATED="1528526188799" MODIFIED="1529096892668"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1089;&#1083;&#1091;&#1095;&#1072;&#1080;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1093;&#1077;&#1084;&#1072; pg_temp.</b>&#160;&#1042;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1099; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1089;&#1093;&#1077;&#1084;. &#1044;&#1083;&#1103; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1089;&#1093;&#1077;&#1084;&#1072; &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; pg_temp_N. &#1048;&#1084;&#1103; pg_temp &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1089;&#1099;&#1083;&#1082;&#1086;&#1081; &#1085;&#1072; &#1077;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; &#1089;&#1093;&#1077;&#1084;&#1091;
    </p>
    <ul>
      <li>
        &#1076;&#1083;&#1103; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089;&#1093;&#1077;&#1084;&#1099; <b>pg_temp_N</b>
      </li>
      <li>
        <b>pg_temp</b>&#160;&#8212; &#1089;&#1089;&#1099;&#1083;&#1082;&#1072; &#1085;&#1072; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; &#1089;&#1093;&#1077;&#1084;&#1091; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072;
      </li>
      <li>
        &#1077;&#1089;&#1083;&#1080; pg_temp &#1085;&#1077;&#1090; &#1074; &#1087;&#1091;&#1090;&#1080;, &#1086;&#1085;&#1072; &#1085;&#1077;&#1103;&#1074;&#1085;&#1086; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1091;&#1084;&#1077;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081;
      </li>
      <li>
        &#1087;&#1086; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1085;&#1080;&#1080; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072; &#1074;&#1089;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1089;&#1093;&#1077;&#1084;&#1099; &#1091;&#1076;&#1072;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103;, &#1089;&#1072;&#1084;&#1072; &#1089;&#1093;&#1077;&#1084;&#1072; &#1086;&#1089;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072;&#1093;.
      </li>
    </ul>
    <p>
      <b>&#1057;&#1093;&#1077;&#1084;&#1072; pg_catalog. </b>&#1042;&#160;&#1089;&#1093;&#1077;&#1084;&#1077; pg_catalog &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072; (&#1074; &#1095;&#1072;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080;, &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; pg_*)
    </p>
    <ul>
      <li>
        &#1089;&#1093;&#1077;&#1084;&#1072; &#1076;&#1083;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072;
      </li>
      <li>
        &#1077;&#1089;&#1083;&#1080; pg_catalog &#1085;&#1077;&#1090; &#1074; &#1087;&#1091;&#1090;&#1080;, &#1086;&#1085;&#1072; &#1085;&#1077;&#1103;&#1074;&#1085;&#1086; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1091;&#1084;&#1077;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; (&#1085;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077; pg_temp)
      </li>
      <li>
        &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; current_schemas(true) &#1087;&#1086;&#1082;&#1072;&#1078;&#1077;&#1090; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1099;&#1081; &#1087;&#1091;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;
      </li>
    </ul>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
