        &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1085;&#1077; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; &#1087;&#1091;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;
