<node TEXT="Привилегии" FOLDED="true" ID="ID_199272655" CREATED="1528521638510" MODIFIED="1729690948509"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Доступ к объектам БД</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>Владелец объекта</b>
    </p>
    <ul>
      <li>
        роль, создавшая объект
      </li>
      <li>
        может быть изменен (<span style="color: #0000c0;">ALTER OBJECT OWNER TO new_role</span>)
      </li>
      <li>
        роли, включенные в роль владельца
      </li>
    </ul>
    <p>
      <b>Доступ к объекту имеют</b>
    </p>
    <ul>
      <li>
        суперпользователь — полный
      </li>
      <li>
        владелец объекта — полный, но может быть ограничен
      </li>
      <li>
        другие роли — в рамках выданных привилегий
      </li>
    </ul>
    <p>
      <b>Право выдачи и отзыва привилегий имеют</b>
    </p>
    <ul>
      <li>
        суперпользователь
      </li>
      <li>
        владелец
      </li>
      <li>
        роль, получившая привилегию с указанием with grant option
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="# Примеры" FOLDED="true" ID="ID_807743167" CREATED="1528530116390" MODIFIED="1529097089526"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1056;&#1048;&#1042;&#1048;&#1051;&#1045;&#1043;&#1048;&#1048; </b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select * from t1;</font>&#160;&#160;-- &#1055;&#1086;&#1087;&#1088;&#1086;&#1073;&#1091;&#1077;&#1084; &#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077; t1. &#1054;&#1096;&#1080;&#1073;&#1082;&#1072; &#1074; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1090;&#1072;&#1082;&#1086;&#1081; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1085;&#1077;&#1090; &#1091; &#1085;&#1072;&#1089; &#1074; &#1087;&#1091;&#1090;&#1080; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;:
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select current_schemas(true);</font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select * from role1.t1;</font>&#160;&#160;-- &#1054;&#1073;&#1088;&#1072;&#1090;&#1080;&#1084;&#1089;&#1103; &#1089; &#1103;&#1074;&#1085;&#1099;&#1084; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1077;&#1084; &#1080;&#1084;&#1077;&#1085;&#1080; &#1089;&#1093;&#1077;&#1084;&#1099;. &#1044;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1089;&#1093;&#1077;&#1084;&#1077; &#1085;&#1077;&#1090;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1084;&#1099; &#1085;&#1077; &#1089;&#1091;&#1087;&#1077;&#1088;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;, &#1085;&#1077; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1077;&#1094;, &#1080; &#1091; &#1085;&#1072;&#1089; &#1085;&#1077;&#1090; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1081;.
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \dn+ role1</font>&#160;&#160;-- &#1042; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; access privileges &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1086;&#1083;&#1100;, &#1082;&#1072;&#1082;&#1080;&#1084;&#1080; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;&#1084;&#1080; &#1086;&#1085;&#1072; &#1085;&#1072;&#1076;&#1077;&#1083;&#1077;&#1085;&#1072; &#1080; &#1082;&#1077;&#1084; &#1086;&#1085;&#1080; &#1077;&#1081; &#1074;&#1099;&#1076;&#1072;&#1085;&#1099;: &#1088;&#1086;&#1083;&#1100;=&#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;/&#1082;&#1077;&#1084;_&#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1099;
    </p>
    <p>
      <b>&#1042;&#1099;&#1076;&#1072;&#1076;&#1080;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1089;&#1093;&#1077;&#1084;&#1077; &#1076;&#1083;&#1103; role2.</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \c - role1</font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; grant create, usage on schema role1 to role2;</font>&#160;&#160;-- &#1055;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103; &#1085;&#1077; &#1074;&#1099;&#1076;&#1072;&#1083;&#1072;&#1089;&#1100;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1091; &#1085;&#1072;&#1089; &#1085;&#1077;&#1090; &#1087;&#1088;&#1072;&#1074;&#1072; &#1077;&#1077; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1076;&#1072;&#1095;&#1080;.
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dn+</font>&#160;&#160;-- &#1055;&#1091;&#1089;&#1090;&#1072;&#1103; &#1088;&#1086;&#1083;&#1100; &#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090; &#1088;&#1086;&#1083;&#1100; public (&#1086;&#1073;&#1097;&#1072;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1088;&#1086;&#1083;&#1077;&#1081;). &#1054;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1077; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077;, &#1095;&#1090;&#1086; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1074;&#1089;&#1077; &#1080;&#1084;&#1077;&#1102;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1089;&#1093;&#1077;&#1084;&#1077; public.
    </p>
    <p>
      <b>&#1057;&#1076;&#1077;&#1083;&#1072;&#1077;&#1084; role1 &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1077;&#1084; &#1089;&#1093;&#1077;&#1084;&#1099; role1:</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - postgres</font>
    </p>
    <p>
      <font color="#0000c0">postgres=# alter schema role1 owner to role1;</font>
    </p>
    <p>
      <font color="#0000c0">postgres=# \dn+</font>
    </p>
    <p>
      <b>&#1042;&#1099;&#1076;&#1072;&#1077;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;:</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - role1</font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; grant create, usage on schema role1 to role2;</font>
    </p>
    <p>
      <b>&#1055;&#1086;&#1087;&#1088;&#1086;&#1073;&#1091;&#1077;&#1084; &#1089;&#1085;&#1086;&#1074;&#1072; &#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077;:</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - role2</font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select * from role1.t1;</font>&#160;&#160;-- &#1053;&#1072; &#1101;&#1090;&#1086;&#1090; &#1088;&#1072;&#1079; &#1091; &#1085;&#1072;&#1089; &#1077;&#1089;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1089;&#1093;&#1077;&#1084;&#1077;, &#1085;&#1086; &#1085;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1089;&#1072;&#1084;&#1086;&#1081; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077;.
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \dp role1.t1</font>&#160;&#160;-- &#1055;&#1091;&#1089;&#1090;&#1086;&#1077; &#1087;&#1086;&#1083;&#1077; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1081; &#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1077;&#1089;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1091; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1072;
    </p>
    <p>
      &#1080; &#1086;&#1085;&#1080; &#1085;&#1077; &#1084;&#1077;&#1085;&#1103;&#1083;&#1080;&#1089;&#1100;.
    </p>
    <p>
      <b>&#1042;&#1099;&#1076;&#1072;&#1076;&#1080;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1085;&#1072; &#1095;&#1090;&#1077;&#1085;&#1080;&#1077;:</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \c - role1</font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; grant select on t1 to role2;</font>
    </p>
    <p>
      &#1055;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1084; &#1080; &#1090;&#1086;&#1084; &#1078;&#1077; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077;: &#1088;&#1086;&#1083;&#1100;=&#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;/&#1082;&#1077;&#1084;_&#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1099;,
    </p>
    <p>
      &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1090;&#1080;&#1087;&#1072; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072; &#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1080;&#1093; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082;. &#1044;&#1083;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1101;&#1090;&#1086;:
    </p>
    <p>
      &#160;&#160;a = insert&#160;&#160;&#160;&#160;- &#1074;&#1089;&#1090;&#1072;&#1074;&#1082;&#1072;&#160;&#160;(append)
    </p>
    <p>
      &#160;&#160;r = select&#160;&#160;&#160;&#160;- &#1095;&#1090;&#1077;&#1085;&#1080;&#1077;&#160;&#160;&#160;(read)
    </p>
    <p>
      &#160;&#160;w = update&#160;&#160;&#160;&#160;- &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;&#160;&#160;&#160;(write)
    </p>
    <p>
      &#160;&#160;d = delete&#160;&#160;&#160;&#160;- &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077; (delete)
    </p>
    <p>
      &#160;&#160;D = truncate&#160;&#160;- &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1072;&#160;&#160;(DELETE)
    </p>
    <p>
      &#160;&#160;x = reference - &#1089;&#1089;&#1099;&#1083;&#1082;&#1072;&#160;&#160;&#160;(x-ref?)
    </p>
    <p>
      &#160;&#160;t = trigger&#160;&#160;&#160;- &#1090;&#1088;&#1080;&#1075;&#1075;&#1077;&#1088;&#160;&#160;(trigger)
    </p>
    <p>
      <b>&#1057;&#1085;&#1086;&#1074;&#1072; &#1087;&#1086;&#1087;&#1088;&#1086;&#1073;&#1091;&#1077;&#1084; &#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077;:</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - role2</font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select * from role1.t1;</font>&#160;&#160;-- &#1053;&#1072; &#1101;&#1090;&#1086;&#1090; &#1088;&#1072;&#1079; &#1089; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;&#1084;&#1080; &#1074;&#1089;&#1077; &#1074; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077;.
    </p>
    <p>
      <b>&#1044;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077; &#1073;&#1077;&#1079; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1103; &#1089;&#1093;&#1077;&#1084;&#1099;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1087;&#1091;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;.</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; set search_path=role1;</font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select current_schemas(true); </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select * from t1; </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; insert into t1 values (42);</font>&#160;&#160;-- &#1055;&#1086;&#1087;&#1088;&#1086;&#1073;&#1091;&#1077;&#1084; &#1090;&#1077;&#1087;&#1077;&#1088;&#1100; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091;. &#1054;&#1096;&#1080;&#1073;&#1082;&#1072;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103; &#1085;&#1072; &#1074;&#1089;&#1090;&#1072;&#1074;&#1082;&#1091; &#1085;&#1077; &#1074;&#1099;&#1076;&#1072;&#1085;&#1072;.
    </p>
    <p>
      <b>&#1042;&#1099;&#1076;&#1072;&#1076;&#1080;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1085;&#1072; &#1074;&#1089;&#1090;&#1072;&#1074;&#1082;&#1091; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1089;&#1093;&#1077;&#1084;&#1099;.</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \c - role1 </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; grant insert on all tables in schema role1 to role2; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp role1.*</font>
    </p>
    <p>
      <b>&#1055;&#1086;&#1087;&#1088;&#1086;&#1073;&#1091;&#1077;&#1084; &#1074;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;:</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - role2 </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; insert into t1 values (42);</font>&#160;&#160;-- &#1055;&#1086;&#1095;&#1077;&#1084;&#1091; &#1085;&#1077; &#1085;&#1072;&#1081;&#1076;&#1077;&#1085;&#1072; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; t1? &#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1085;&#1077; &#1085;&#1072;&#1081;&#1076;&#1077;&#1085;&#1072;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1087;&#1091;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1086;&#1081; set &#1085;&#1072; &#1074;&#1088;&#1077;&#1084;&#1103; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072;, &#1072; &#1084;&#1099; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1083;&#1080;&#1089;&#1100; &#1087;&#1086;&#1076; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1091;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072; &#1076;&#1086;&#1083;&#1075;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;, &#1085;&#1072;&#1076;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; alter role set search_path. A &#1087;&#1086;&#1082;&#1072; &#1073;&#1091;&#1076;&#1077;&#1084; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;&#1084; &#1089; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1077;&#1084; &#1089;&#1093;&#1077;&#1084;&#1099;.
    </p>
    <p>
      <font color="#0000c0">role2=&gt; insert into role1.t1 values (42); </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; insert into role1.t2 values (1,2); </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select * from role1.t2;</font>&#160;&#160;-- &#1055;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1087;&#1088;&#1086;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100; &#1074;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1084;&#1099; &#1085;&#1077; &#1089;&#1084;&#1086;&#1078;&#1077;&#1084;:
    </p>
    <p>
      <b>&#1055;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1102; &#1095;&#1090;&#1077;&#1085;&#1080;&#1103; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1076;&#1072;&#1090;&#1100; &#1085;&#1072; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1099;:</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \c - role1 </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; grant select(m) on t2 to role2; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp t2</font>
    </p>
    <p>
      <b>&#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;:</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - role2 </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select * from role1.t2; </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select m from role1.t2; </font>
    </p>
    <p>
      <b>&#1045;&#1089;&#1083;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1076;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;, &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1103;&#1103; &#1080;&#1093; &#1103;&#1074;&#1085;&#1086;.</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \c - role1 </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; grant all on t1 to role2; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp t1</font>
    </p>
    <p>
      <b>&#1058;&#1077;&#1087;&#1077;&#1088;&#1100; role2 &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099; &#1074;&#1089;&#1077; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;:</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - role2 </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; delete from role1.t1;</font>
    </p>
    <p>
      <b>&#1040; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1072;&#1084;&#1086;&#1081; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;?</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; drop table role1.t1;</font>&#160;&#160;-- &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1084;&#1086;&#1078;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1077;&#1094; (&#1080;&#1083;&#1080; &#1089;&#1091;&#1087;&#1077;&#1088;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;),
    </p>
    <p>
      &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1077; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090;.
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1056;&#1048;&#1042;&#1048;&#1051;&#1045;&#1043;&#1048;&#1048; &#1055;&#1054; &#1059;&#1052;&#1054;&#1051;&#1063;&#1040;&#1053;&#1048;&#1070;
    </p>
    <p>
      ~~~~~~~~~~~~~~~~~~~~~~~
    </p>
    <p>
      
    </p>
    <p>
      &#1056;&#1072;&#1089;&#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;.
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1=&gt; \c - role1
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;You are now connected to database &quot;postgres&quot; as user &quot;role1&quot;.
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1=&gt; \ddp
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Default access privileges
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Owner | Schema | Type | Access privileges
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-------+--------+------+-------------------
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;(0 rows)
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;
    </p>
    <p>
      
    </p>
    <p>
      &#1048;&#1079;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1085;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1099;.
    </p>
    <p>
      
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;, role2 &#1085;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090; &#1082; &#1085;&#1077;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;, &#1095;&#1090;&#1086; &#1074;&#1087;&#1086;&#1083;&#1085;&#1077; &#1086;&#1095;&#1077;&#1074;&#1080;&#1076;&#1085;&#1086;:
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1=&gt; create table t3(n numeric);
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;CREATE TABLE
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1=&gt; \dp t3
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Access privileges
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Schema | Name | Type&#160;&#160;| Access privileges | Column access privileges
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160; --------+------+-------+-------------------+--------------------------
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1&#160;&#160;| t3&#160;&#160;&#160;| table |&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;|
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;(1 row)
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;
    </p>
    <p>
      
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      
    </p>
    <p>
      &#1053;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1081; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;:
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1=&gt; alter default privileges
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; for role role1
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; in schema role1
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; grant select on tables to role2;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;ALTER DEFAULT PRIVILEGES
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1=&gt; \ddp
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Default access privileges
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Owner | Schema | Type&#160;&#160;| Access privileges
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-------+--------+-------+-------------------
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1 | role1&#160;&#160;| table | role2=r/role1
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;(1 row)
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;
    </p>
    <p>
      
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      
    </p>
    <p>
      &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1083;&#1102;&#1073;&#1086;&#1081; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1088;&#1086;&#1083;&#1100;&#1102; role1 &#1074; &#1089;&#1093;&#1077;&#1084;&#1077; role1 &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085; role2.
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1=&gt; drop table t3;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;DROP TABLE
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1=&gt; create table t3(n numeric);
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;CREATE TABLE
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1=&gt; \dp t3
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Access privileges
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Schema | Name | Type&#160;&#160;|&#160;&#160;Access privileges&#160;&#160;| Column access privileges
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160; --------+------+-------+---------------------+--------------------------
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;role1&#160;&#160;| t3&#160;&#160;&#160;| table | role1=arwdDxt/role1+|
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;|&#160;&#160;&#160;&#160;&#160;&#160;|&#160;&#160;&#160;&#160;&#160;&#160;&#160;| role2=r/role1&#160;&#160;&#160;&#160;&#160;&#160;&#160;|
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;(1 row)
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;
    </p>
  </body>
