<node TEXT="# Пример 1" ID="ID_1412275519" CREATED="1529097047026" MODIFIED="1529097272550"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1072;</b>
    </p>
    <p>
      &#1054;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091; &#1090;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1076;&#1085;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1080; &#1080;&#1084;&#1077;&#1083;&#1080; &#1087;&#1086;&#1083;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1084;, &#1072; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1084;&#1086;&#1075;&#1083;&#1080; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1072;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1090;&#1100;, &#1085;&#1086; &#1085;&#1077; &#1080;&#1079;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102;.
    </p>
    <p>
      1. &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; DB11 &#1080; &#1076;&#1074;&#1077; &#1088;&#1086;&#1083;&#1080;: writer &#1080; reader.
    </p>
    <p>
      2. &#1054;&#1090;&#1086;&#1079;&#1074;&#1072;&#1090;&#1100; &#1091; &#1088;&#1086;&#1083;&#1080; public &#1074;&#1089;&#1077; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1085;&#1072; &#1089;&#1093;&#1077;&#1084;&#1091; public, &#1074;&#1099;&#1076;&#1072;&#1090;&#1100; &#1101;&#1090;&#1080; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1088;&#1086;&#1083;&#1080; writer &#1080; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; usage &#8212; &#1088;&#1086;&#1083;&#1080; reader.
    </p>
    <p>
      3. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1090;&#1072;&#1082;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1088;&#1086;&#1083;&#1100; reader &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1083;&#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1085;&#1072; &#1095;&#1090;&#1077;&#1085;&#1080;&#1077; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1084;, &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1072;&#1097;&#1080;&#1084; writer &#1074; &#1089;&#1093;&#1077;&#1084;&#1077; public.
    </p>
    <p>
      4. &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; w1 &#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1077; writer &#1080; r1 &#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1077; reader.
    </p>
    <p>
      5. &#1055;&#1086;&#1076; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; writer &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091;.
    </p>
    <p>
      6. &#1059;&#1073;&#1077;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103;, &#1095;&#1090;&#1086; r1 &#1080;&#1084;&#1077;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1095;&#1090;&#1077;&#1085;&#1080;&#1077;, &#1072; w1 &#1080;&#1084;&#1077;&#1077;&#1090; &#1087;&#1086;&#1083;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077;, &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1103; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1056;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077;</b>
    </p>
    <p>
      <font color="#0000c0"># create database db11; </font>
    </p>
    <p>
      <font color="#0000c0"># create user writer; </font>
    </p>
    <p>
      <font color="#0000c0"># create user reader; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># \c db11 </font>
    </p>
    <p>
      <font color="#0000c0"># revoke all on schema public from public; </font>
    </p>
    <p>
      <font color="#0000c0"># grant all on schema public to writer; </font>
    </p>
    <p>
      <font color="#0000c0"># grant usage on schema public to reader; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># alter default privileges for role writer in schema public grant select on tables to reader; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># create user w1 in role writer; </font>
    </p>
    <p>
      <font color="#0000c0"># create user r1 in role reader; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># \c - writer </font>
    </p>
    <p>
      <font color="#0000c0"># create table t(n numeric); </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># \c - w1 </font>
    </p>
    <p>
      <font color="#0000c0"># insert into t values (42);</font>
    </p>
    <p>
      -- ok
    </p>
    <p>
      <font color="#0000c0"># \c - r1 </font>
    </p>
    <p>
      <font color="#0000c0"># select * from t;</font>
    </p>
    <p>
      -- ok
    </p>
    <p>
      <font color="#0000c0"># update t set n=n+1;</font>
    </p>
    <p>
      -- &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;
    </p>
    <p>
      <font color="#0000c0"># \c - w1 </font>
    </p>
    <p>
      <font color="#0000c0"># drop table t;</font>
    </p>
    <p>
      -- ok
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Создание объектов" ID="ID_1905234270" CREATED="1528531368192" MODIFIED="1529097091206"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1054;&#1047;&#1044;&#1040;&#1053;&#1048;&#1045; &#1054;&#1041;&#1066;&#1045;&#1050;&#1058;&#1054;&#1042; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1088;&#1086;&#1083;&#1100; role1 &#1080; &#1086;&#1076;&#1085;&#1086;&#1080;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; &#1089;&#1093;&#1077;&#1084;&#1091;. &#1069;&#1090;&#1072; &#1088;&#1086;&#1083;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1077;&#1084; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074;.</b>
    </p>
    <p>
      <font color="#0000c0">psql </font>
    </p>
    <p>
      <font color="#0000c0">postgres=# create user role1; </font>
    </p>
    <p>
      <font color="#0000c0">postgres=# create schema role1; </font>
    </p>
    <p>
      <font color="#0000c0">postgres=# grant create, usage on schema role1 to role1; </font>
    </p>
    <p>
      <font color="#0000c0">postgres=# \c - role1 </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; select current_schemas(true);</font>
    </p>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1076;&#1074;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1080; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102;</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; create table t1(n numeric); </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; create table t2(n numeric, m numeric); </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; create function f1() returns integer as $$ select 1; $$ language sql;</font>
    </p>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1088;&#1086;&#1083;&#1100; role2, &#1080;&#1079;-&#1087;&#1086;&#1076; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1073;&#1091;&#1076;&#1077;&#1084; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;&#1084; role1.</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - postgres </font>
    </p>
    <p>
      <font color="#0000c0">postgres=# create user role2; </font>
    </p>
    <p>
      <font color="#0000c0">postgres=# \c - role2</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
