<node TEXT="Привилегии для группы" FOLDED="true" ID="ID_44930587" CREATED="1528527509852" MODIFIED="1528530333269"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1076;&#1083;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099;</b>
    </p>
    <p>
      &#1057;&#1091;&#1087;&#1077;&#1088;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1080;&#1084;&#1077;&#1077;&#1090; &#1085;&#1077;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082;&#1086; &#1074;&#1089;&#1077;&#1084; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;&#1084;. &#1053;&#1086; &#1085;&#1077; &#1087;&#1086;&#1090;&#1086;&#1084;&#1091;, &#1095;&#1090;&#1086; &#1091; &#1085;&#1077;&#1075;&#1086; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;, &#1072; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1076;&#1083;&#1103; &#1085;&#1077;&#1075;&#1086; &#1085;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1080; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1056;&#1086;&#1083;&#1100; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;</b>
    </p>
    <ul>
      <li>
        &#1085;&#1077;&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; (&#1074; &#1090;&#1086;&#1084; &#1095;&#1080;&#1089;&#1083;&#1077; &#1082;&#1072;&#1082; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1077;&#1094;)
      </li>
      <li>
        &#1095;&#1077;&#1088;&#1077;&#1079; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1099;&#1077; &#1088;&#1086;&#1083;&#1080;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1086;&#1085;&#1072; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090;
      </li>
      <li>
        &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1089;&#1077;&#1074;&#1076;&#1086;&#1088;&#1086;&#1083;&#1100; public, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1074;&#1093;&#1086;&#1076;&#1103;&#1090; &#1074;&#1089;&#1077; &#1088;&#1086;&#1083;&#1080;
      </li>
    </ul>
    <p>
      <b>&#1055;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1081; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1072; inherit.</b>&#160; &#1056;&#1086;&#1083;&#1100; &#1089; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1086;&#1084; <b>inherit</b>&#160; (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;) &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1086;&#1073;&#1083;&#1072;&#1076;&#1072;&#1077;&#1090; &#1082;&#1072;&#1082; &#1089;&#1074;&#1086;&#1080;&#1084;&#1080; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;&#1084;&#1080;, &#1090;&#1072;&#1082; &#1080; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;&#1084;&#1080; &#1074;&#1089;&#1077;&#1093; &#1075;&#1088;&#1091;&#1087;&#1087;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1086;&#1085;&#1072; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090;. &#1045;&#1089;&#1083;&#1080; &#1078;&#1077; &#1088;&#1086;&#1083;&#1100; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1072; &#1073;&#1077;&#1079; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1072; inherit, &#1090;&#1086; &#1086;&#1085;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1086;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;&#1084;&#1080; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099;, &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1074; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; <b>set role</b>&#160;&#1080; &#1090;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084; &#171;&#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1080;&#1074;&#1096;&#1080;&#1089;&#1100;&#187; &#1085;&#1072; &#1101;&#1090;&#1091; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1091;&#1102; &#1088;&#1086;&#1083;&#1100;.
    </p>
    <p>
      <font color="#0000c0">CREATE ROLE role [<b>INHERIT</b>];</font>&#160;&#160;-- &#1040;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084;&#1080; &#1086;&#1073;&#1083;&#1072;&#1076;&#1072;&#1077;&#1090;
    </p>
    <p>
      &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1072;&#1103; &#1088;&#1086;&#1083;&#1100;
    </p>
    <p>
      <font color="#0000c0">CREATE ROLE role <b>NOINHERIT</b>;</font>&#160;&#160;-- &#1055;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1080; &#1103;&#1074;&#1085;&#1086;&#1084; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080;: SET ROLE group;
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="Примеры" ID="ID_43125000" CREATED="1528532197148" MODIFIED="1528532975612"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1043;&#1056;&#1059;&#1055;&#1055;&#1054;&#1042;&#1067;&#1045; &#1055;&#1056;&#1048;&#1042;&#1048;&#1051;&#1045;&#1043;&#1048;&#1048;</b>
    </p>
    <p>
      
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1074;&#1099;&#1076;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1102; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1086;&#1081; &#1088;&#1086;&#1083;&#1080;, &#1090;&#1086; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1074; &#1085;&#1077;&#1077; &#1088;&#1086;&#1083;&#1080; (&#1089; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1086;&#1084; inherit)
    </p>
    <p>
      &#1073;&#1091;&#1076;&#1091;&#1090; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1086;&#1073;&#1083;&#1072;&#1076;&#1072;&#1090;&#1100; &#1080; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1099;&#1084;&#1080; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;&#1084;&#1080;.
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \du role1</font>&#160;&#160;-- &#1055;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1074; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1072;&#1093; &#1085;&#1077; &#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1089;&#1103; &quot;No inheritance&quot;, &#1091; role2 &#1090;&#1072;&#1082;&#1086;&#1081; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; &#1077;&#1089;&#1090;&#1100;.
    </p>
    <p>
      <b>&#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1084;, &#1089;&#1084;&#1086;&#1078;&#1077;&#1084; &#1083;&#1080; &#1084;&#1099; &#1074;&#1099;&#1079;&#1074;&#1072;&#1090;&#1100; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102;.</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select role1.f1();</font>&#160;&#160;-- &#1052;&#1086;&#1078;&#1077;&#1084;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1088;&#1086;&#1083;&#1100; public &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1080;&#1084;&#1077;&#1077;&#1090; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1102; &#1085;&#1072;
    </p>
    <p>
      <b>&#1054;&#1090;&#1079;&#1086;&#1074;&#1077;&#1084; &#1101;&#1090;&#1091; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1102;.</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \c - role1 </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; revoke execute on all functions in schema role1 from public; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - role2</font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; select role1.f1();</font>&#160;&#160;-- &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1084;. &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102; &#1074;&#1099;&#1079;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103;, &#1095;&#1090;&#1086; &#1080; &#1090;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1083;&#1086;&#1089;&#1100;.
    </p>
    <p>
      <b>&#1055;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1085;&#1072; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1077; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1084;. &#1045;&#1089;&#1090;&#1100; &#1083;&#1080; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1085;&#1072; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1091; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; t2?</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; truncate table role1.t2;&#160;&#160;-- &#1044;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1085;&#1077;&#1090;. </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \dp role1.t2</font>
    </p>
    <p>
      <b>&#1042;&#1099;&#1076;&#1072;&#1076;&#1080;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1088;&#1086;&#1083;&#1080; public.</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \c - role1 </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; grant truncate on table t2 to public; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp t2</font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - role2&#160;&#160;-- &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1084; &#1089;&#1085;&#1086;&#1074;&#1072;. </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; truncate table role1.t2;</font>&#160;&#160;-- &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1087;&#1086;&#1103;&#1074;&#1080;&#1083;&#1089;&#1103;.
    </p>
  </body>
</html></richcontent>
</node>
</node>
