<node TEXT="Примеры" ID="ID_1433388955" CREATED="1528533013163" MODIFIED="1528537545737"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1045;&#1056;&#1045;&#1044;&#1040;&#1063;&#1040; &#1055;&#1056;&#1040;&#1042;&#1040;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1076;&#1080;&#1084; &#1090;&#1088;&#1077;&#1090;&#1100;&#1102; &#1088;&#1086;&#1083;&#1100; &#1080; &#1087;&#1086;&#1087;&#1088;&#1086;&#1073;&#1091;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1100; &#1077;&#1081; &#1087;&#1088;&#1072;&#1074;&#1072; &#1085;&#1072; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091;, &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1072;&#1097;&#1091;&#1102; role1.</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \c - postgres </font>
    </p>
    <p>
      <font color="#0000c0">postgres=# create user role3;</font>
    </p>
    <p>
      <b>&#1059; &#1088;&#1086;&#1083;&#1080; role2 &#1077;&#1089;&#1090;&#1100; &#1087;&#1086;&#1083;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; t1:</b>
    </p>
    <p>
      <font color="#0000c0">postgres=# \c - role2 </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \dp role1.t1 </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; grant select on role1.t1 to role3;</font>&#160;&#160;-- &#1053;&#1086; &#1086;&#1085;&#1072; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1100; &#1089;&#1074;&#1086;&#1080; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;:
    </p>
    <p>
      <b>&#1063;&#1090;&#1086;&#1073;&#1099; &#1101;&#1090;&#1086; &#1073;&#1099;&#1083;&#1086; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;, role1 &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1074;&#1099;&#1076;&#1072;&#1090;&#1100; role2 &#1087;&#1088;&#1072;&#1074;&#1086; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1076;&#1072;&#1095;&#1080;. </b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \c - role1 </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; grant select,update on t1 to role2 with grant option; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp t1</font>&#160;&#160;-- &#1047;&#1074;&#1077;&#1079;&#1076;&#1086;&#1095;&#1082;&#1080; &#1089;&#1087;&#1088;&#1072;&#1074;&#1072; &#1086;&#1090; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090; &#1087;&#1088;&#1072;&#1074;&#1086; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1076;&#1072;&#1095;&#1080;.
    </p>
    <p>
      <b>&#1058;&#1077;&#1087;&#1077;&#1088;&#1100; role2 &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100;&#1089;&#1103; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;&#1084;&#1080;, &#1074; &#1090;&#1086;&#1084; &#1095;&#1080;&#1089;&#1083;&#1077; &#1080; &#1087;&#1088;&#1072;&#1074;&#1086;&#1084; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1076;&#1072;&#1095;&#1080;.</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - role2 </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; grant select on role1.t1 to role3 with grant option; </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; grant update on role1.t1 to role3; </font>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \dp role1.t1</font>
    </p>
    <p>
      <b>&#1056;&#1086;&#1083;&#1100; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1086;&#1076;&#1085;&#1091; &#1080; &#1090;&#1091; &#1078;&#1077; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1102; &#1080;&#1079; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1086;&#1074;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;:</b>
    </p>
    <p>
      <font color="#0000c0">role2=&gt; \c - role1 </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; grant update on role1.t1 to role3; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp role1.t1 </font>
    </p>
    <p>
      <b>&#1054;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1077; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077;: &#1077;&#1089;&#1083;&#1080; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103; &#1074;&#1099;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1091;&#1087;&#1077;&#1088;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;, &#1086;&#1085;&#1072; &#1074;&#1099;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090; &#1080;&#1084;&#1077;&#1085;&#1080; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1072;.</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \c - postgres </font>
    </p>
    <p>
      <font color="#0000c0">postgres=# grant truncate on role1.t1 to role3; </font>
    </p>
    <p>
      <font color="#0000c0">postgres=# \dp role1.t1 </font>
    </p>
    <p>
      <b>&#1056;&#1086;&#1083;&#1100; &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1090;&#1086;&#1079;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1091; &#1090;&#1086;&#1081; &#1088;&#1086;&#1083;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1086;&#1085;&#1072; &#1080;&#1093; &#1085;&#1077;&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1074;&#1099;&#1076;&#1072;&#1083;&#1072;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, role1 &#1085;&#1077; &#1089;&#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1090;&#1086;&#1079;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1072;&#1074;&#1086; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1076;&#1072;&#1095;&#1080; &#1091; role3.</b>
    </p>
    <p>
      <font color="#0000c0">postgres=# \c - role1 </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; revoke grant option for select on role1.t1 from role3; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp t1</font>&#160;&#160;-- &#1061;&#1086;&#1090;&#1103; &#1085;&#1080;&#1082;&#1072;&#1082;&#1086;&#1081; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; &#1085;&#1077; &#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;, &#1085;&#1086; &#1087;&#1088;&#1072;&#1074;&#1072; &#1085;&#1077; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1083;&#1080;&#1089;&#1100;:
    </p>
    <p>
      <b>&#1058;&#1072;&#1082;&#1072;&#1103; &#1078;&#1077; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1103; &#1080; &#1089; &#1089;&#1072;&#1084;&#1086;&#1081; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1077;&#1081;.</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; revoke select on role1.t1 from role3; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp t1 </font>
    </p>
    <p>
      <b>&#1042; &#1090;&#1086; &#1078;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1088;&#1086;&#1083;&#1100; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1090;&#1086;&#1079;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1091; &#1088;&#1086;&#1083;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1086;&#1085;&#1072; &#1080;&#1093; &#1074;&#1099;&#1076;&#1072;&#1083;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1103;&#1103; &#1091;&#1089;&#1087;&#1077;&#1083;&#1072; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1076;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1082;&#1086;&#1084;&#1091;-&#1083;&#1080;&#1073;&#1086; &#1077;&#1097;&#1077;:</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; revoke grant option for select on role1.t1 from role2; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; revoke select on role1.t1 from role2; </font>
    </p>
    <p>
      <b>&#1042; &#1090;&#1072;&#1082;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1085;&#1072;&#1076;&#1086; &#1086;&#1090;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086; &#1074;&#1089;&#1077;&#1081; &#1080;&#1077;&#1088;&#1072;&#1088;&#1093;&#1080;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; cascade.</b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp t1 </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; revoke grant option for select on role1.t1 from role2 cascade; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp t1</font>&#160;&#160;-- &#1050;&#1072;&#1082; &#1074;&#1080;&#1076;&#1080;&#1084;, &#1091; role2 &#1087;&#1088;&#1086;&#1087;&#1072;&#1083;&#1086; &#1087;&#1088;&#1072;&#1074;&#1086; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1076;&#1072;&#1095;&#1080; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;, &#1072; &#1091; role3 &#1073;&#1099;&#1083;&#1072; &#1086;&#1090;&#1086;&#1079;&#1074;&#1072;&#1085;&#1072; &#1089;&#1072;&#1084;&#1072; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;.
    </p>
    <p>
      <b>&#1040;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1090;&#1086;&#1079;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086; &#1080;&#1077;&#1088;&#1072;&#1088;&#1093;&#1080;&#1080; &#1080; &#1089;&#1072;&#1084;&#1091; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1102;. </b>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; revoke select on role1.t1 from role2 cascade; </font>
    </p>
    <p>
      <font color="#0000c0">role1=&gt; \dp t1</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Отзыв по иерархии" ID="ID_1444094811" CREATED="1528527541430" MODIFIED="1528529953157"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1054;&#1090;&#1079;&#1099;&#1074; &#1087;&#1086; &#1080;&#1077;&#1088;&#1072;&#1088;&#1093;&#1080;&#1080;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1054;&#1090;&#1079;&#1099;&#1074; &#1089;&#1072;&#1084;&#1086;&#1081; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;.</b>&#160; &#1056;&#1086;&#1083;&#1100; &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1090;&#1086;&#1079;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1102; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1091; &#1090;&#1086;&#1081; &#1088;&#1086;&#1083;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1086;&#1085;&#1072; &#1077;&#1075;&#1086; &#1074;&#1099;&#1076;&#1072;&#1083;&#1072;. &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; &#1087;&#1088;&#1080; &#1086;&#1090;&#1079;&#1099;&#1074;&#1077; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1086;&#1090;&#1086;&#1079;&#1074;&#1072;&#1085;&#1072; &#1091; &#1074;&#1089;&#1077;&#1093; &#1088;&#1086;&#1083;&#1077;&#1081; &#1074; &#1080;&#1077;&#1088;&#1072;&#1088;&#1093;&#1080;&#1080;. &#1044;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1072;&#1076;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1086;&#1077; &#1089;&#1083;&#1086;&#1074;&#1086; cascade. &#1045;&#1089;&#1083;&#1080; &#1080;&#1077;&#1088;&#1072;&#1088;&#1093;&#1080;&#1103; &#1085;&#1077;&#1087;&#1091;&#1089;&#1090;&#1072; &#1080; cascade &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;, &#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1085;&#1077;&#1090; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;
    </p>
    <p>
      <font color="#0000c0">role1: REVOKE SELECT ON tbl FROM role2 CASCADE;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1054;&#1090;&#1079;&#1099;&#1074; &#1087;&#1088;&#1072;&#1074;&#1072; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1076;&#1072;&#1095;&#1080;.</b>&#160; &#1055;&#1088;&#1072;&#1074;&#1086; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1076;&#1072;&#1095;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1090;&#1086;&#1079;&#1074;&#1072;&#1090;&#1100;, &#1085;&#1077; &#1086;&#1090;&#1079;&#1099;&#1074;&#1072;&#1103; &#1091; &#1088;&#1086;&#1083;&#1080; &#1089;&#1072;&#1084;&#1086; &#1087;&#1086;&#1083;&#1085;&#1086;&#1084;&#1086;&#1095;&#1080;&#1077;. &#1069;&#1090;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; revoke grant option for. &#1057;&#1083;&#1086;&#1074;&#1086; cascade &#1080;&#1084;&#1077;&#1077;&#1090; &#1079;&#1076;&#1077;&#1089;&#1100; &#1090;&#1072;&#1082;&#1086;&#1077; &#1078;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1072;&#1082; &#1080; &#1087;&#1088;&#1080; &#1086;&#1090;&#1079;&#1099;&#1074;&#1077; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;
    </p>
    <p>
      <font color="#0000c0">role1: REVOKE GRANT OPTION FOR</font>
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; <font color="#0000c0">SELECT ON tbl FROM role2 CASCADE;</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1088;&#1086;&#1083;&#1100; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1076;&#1072;&#1074;&#1072;&#1083;&#1072; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1102; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1088;&#1086;&#1083;&#1103;&#1084;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1077; CASCADE &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Привилегии по умолчанию" ID="ID_114400419" CREATED="1528527561369" MODIFIED="1729690507117"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Привилегии по умолчанию</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>По умолчанию роль public получает ряд привилегий</b>
    </p>
    <ul>
      <li>
        для баз данных CONNECT (подключение), TEMPORARY (создание временных таблиц)
      </li>
      <li>
        для схемы public CREATE (создание объектов), USAGE (доступ к объектам)
      </li>
      <li>
        для схем pg_catalog и information_schema&#xa0;&#xa0;USAGE (доступ к объектам)
      </li>
      <li>
        для функций EXECUTE (выполнение)
      </li>
    </ul>
    <p>
      <b>Дополнительные привилегии по умолчанию</b>
    </p>
    <ul>
      <li>
        ALTER DEFAULT PRIVILEGES
      </li>
      <li>
        <span style="color: #0000c0;">\ddp</span>
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
</node>
<node TEXT="Резервное копирование" ID="ID_256644177" CREATED="1737274096474" MODIFIED="1737449951069"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Wal-g
    </p>
    <h3>
      <span style="font-weight: bold;">Создание бэкапов </span>
    </h3>
    <p>
      <span style="font-weight: bold;">Создание бэкапов </span>
    </p>
    <p>
      <span style="font-weight: bold;">pg_dump</span><span style="font-weight: normal;">&#xa0;- для создания логических резервных копий одной БД </span>
    </p>
    <p>
      <span style="font-weight: bold;">pg_dumpall</span><span style="font-weight: normal;">&#xa0;- позволяет создать резервную копию всех БД в кластере, включая информацию о ролях и табличных пространствах в виде одного SQL-скрипта. Требует прав </span><span style="font-weight: bold;">суперпользователя</span><span style="font-weight: normal;">&#xa0;для выполнения и восстановления, так как необходимо создать роли и базы данны </span>
    </p>
    <p>
      <span style="font-weight: bold;">pg_basebackup</span><span style="font-weight: normal;">&#xa0;- для создания бинарных резервных копий работающего кластера PostgreSQL. Требуемые права - Суперпользователь / REPLICATION </span>
    </p>
    <ul>
      <li>
        Создание полной копии файлов кластера без влияния на работу других клиентов
      </li>
      <li>
        Поддержка потоковой репликации и восстановления на заданный момент времени
      </li>
      <li>
        Не позволяет создавать резервные копии отдельных БД; всегда создаётся копия всего кластера
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">pg_backupcluster</span><span style="font-weight: normal;">&#xa0;- обёртка над pg_basebackup и pg_dump - более удобный интерфейс для создания резервных копий. </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">pg_dump -h &lt;адрес_хоста&gt; -U &lt;имя_пользователя&gt; -Fc -f &lt;дамп.dump&gt; &lt;имя_базы&gt; </span>
    </p>
    <p>
      <span style="color: #0000c0;">pg_dump -h &lt;адрес_хоста&gt; -U &lt;имя_пользователя&gt; -Fc &lt;имя_базы&gt; </span><span style="color: #0000c0; font-weight: bold;">&gt;</span><span style="color: #0000c0;">&#xa0;&#xa0;&lt;дамп.dump&gt;</span>
    </p>
    <p>
      -F, --format= c | d | t | p (custom, directory, tar, plain text (default) - формат дампа
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">c (custom)</span><span style="font-weight: normal;">&#xa0;- эффективное сжатие и хранение данных. Восстановление - pg_restore. Можно выбирать отдельные объекты для восстановления. Возможно параллельное восстановление</span>
      </li>
      <li>
        <span style="font-weight: bold;">d (directory)</span><span style="font-weight: normal;">&#xa0;- дамп создается в виде каталога, содержащего множество файлов. Восстановление - pg_restore. Возможно параллельное восстановление</span>
      </li>
      <li>
        <span style="font-weight: bold;">t (tar)</span><span style="font-weight: normal;">&#xa0;- дамп создается в формате tar, единый архивный файл, содержащий все объекты БД. Восстановление - pg_restore</span>
      </li>
      <li>
        <span style="font-weight: bold;">p&#xa0;(plain text (default))</span>&#xa0;- дамп создается в обычном текстовом формате (SQL-скрипт). Восстановление - <span style="font-weight: bold;">psql</span>
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">pg_dumpall -U &lt;пользователь&gt; &gt; &lt;имя_файла.sql&gt;</span>&#xa0;&#xa0;# Создать резервную копию всех БД в кластере, включая информацию о ролях и табличных пространствах
    </p>
    <p>
      
    </p>
    <h3>
      <span style="font-weight: bold;">Восстановление</span>
    </h3>
    <p>
      <span style="font-weight: bold;">psql</span><span style="font-weight: normal;">&#xa0;- восстановление из текстового SQL-дампа</span>
    </p>
    <p>
      <span style="font-weight: bold;">pg_restore</span><span style="font-weight: normal;">&#xa0;- восстановление отдельных БД из архивов, созданных с помощью pg_dump</span>
    </p>
    <p>
      <span style="font-weight: bold;">pg_restorecluster</span>&#xa0;- для восстановления целого кластера PostgreSQL из резервной копии, созданной с помощью утилиты <span style="font-weight: normal;">pg_backupcluster </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #0000c0;">psql -U &lt;пользователь&gt; -d &lt;имя_базы&gt; &lt; &lt;имя_файла.sql&gt;</span><span style="font-weight: normal;">&#xa0;&#xa0;# Восстановить из текстового SQL-дампа</span>
    </p>
    <p>
      <span style="color: #0000c0;">psql -U &lt;пользователь&gt; -f &lt;полный_дамп.sql&gt;</span>&#xa0;&#xa0;# Восстановить все БД из дампа (pg_dumpall)
    </p>
    <p>
      <span style="font-weight: normal; color: #0000c0;">pg_restore -U &lt;имя_пользователя&gt; -d &lt;имя_базы&gt; &lt;дамп.dump&gt;</span><span style="font-weight: normal;">&#xa0;&#xa0;# Восстановить из бинарного дампа (формат custom) </span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">-U</span>: Указывает имя пользователя для подключения к БД
      </li>
      <li>
        <span style="font-weight: bold;">-W</span>: Принуждает к запросу пароля перед подключением
      </li>
      <li>
        Убедитесь, что все необходимые пользователи существуют в целевой БД перед восстановлением. Если они отсутствуют, восстановление может завершиться ошибкой
      </li>
      <li>
        <span style="font-weight: bold;">--no-acl</span>: позволит избежать ошибок, связанных с отсутствующими пользователями
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Системный каталог (словарь)" FOLDED="true" POSITION="bottom_or_right" ID="ID_186881210" CREATED="1528353622175" MODIFIED="1728995826512"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Системный каталог</b>&#xa0;(словарь данных - в некоторых СУБД) - набор таблиц и представлений, с информацией о содержимом СУБД
    </p>
    <ul>
      <li>
        Из системного каталога можно получить <b>метаинформацию</b>&#xa0;&#xa0;с описанием<br/>всех объектов СУБД<br align="-webkit-auto" style="font-variant: normal; letter-spacing: normal; line-height: normal; text-indent: 0px; text-transform: none; white-space: normal; word-spacing: 0px;"/>
      </li>
      <li>
        Для работы с системным каталогом предусмотрен <b>SQL интерфейс</b><br align="-webkit-auto" style="font-variant: normal; letter-spacing: normal; line-height: normal; text-indent: 0px; text-transform: none; white-space: normal; word-spacing: 0px;"/>- <b>просмотр</b>: SELECT<br/>- <b>изменение</b>: DDL (CREATE, ALTER, DROP)<br align="-webkit-auto" style="font-variant: normal; letter-spacing: normal; line-height: normal; text-indent: 0px; text-transform: none; white-space: normal; word-spacing: 0px;"/>
      </li>
      <li>
        Все таблицы и представления системного каталога располагаются в схеме <b>pg_catalog</b><br align="-webkit-auto" style="font-variant: normal; letter-spacing: normal; line-height: normal; text-indent: 0px; text-transform: none; white-space: normal; word-spacing: 0px;"/>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>Системный каталог в psql </b>
    </p>
    <p>
      <span style="color: #0000c0;">$ psql -E</span>&#xa0;&#xa0;# psql будет выводить не только выдачу, но и как она формировалась (команды SQL)
    </p>
    <p>
      &#xa0;&#xa0;--&gt; &#xa0;Команды <b>\d* [pattern]</b>
    </p>
    <ul>
      <li>
        списки по типам объектов (<b>\dt</b>, <b>\dv</b>, <b>\df</b>)
      </li>
      <li>
        дополнительная информация — <b>модификатор +</b>
      </li>
      <li>
        системные объекты (объекты системного каталога) вместе с пользовательскими — <b>модификатор S</b>&#xa0;-
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      Системный каталог в psql
    </p>
    <p>
      Правила именования объектов
    </p>
    <p>
      Общие таблицы кластера БД
    </p>
    <p>
      Специальные типы данных
    </p>
    <p>
      Системные представления
    </p>
    <p>
      Исходный код
    </p>
  </body>
</html></richcontent>
<node TEXT="# Пример 1" ID="ID_674244051" CREATED="1529096211249" MODIFIED="1529096336238"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1072;</b>
    </p>
    <p>
      1. &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; pg_class
    </p>
    <p>
      2. &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1088;&#1086;&#1073;&#1085;&#1086;&#1077;(+) &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; pg_tables
    </p>
    <p>
      3. &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1080; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081;, &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1102;&#1097;&#1080;&#1093;&#1089;&#1103; &#1085;&#1072; 'pg_stat'
    </p>
    <p>
      4. &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081;, &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1102;&#1097;&#1080;&#1093;&#1089;&#1103; &#1089; 'pg_catalog.pg_'
    </p>
    <p>
      5*. &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1090;&#1077;&#1082;&#1089;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1074;&#1099;&#1074;&#1086;&#1076;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;: \d+ pg_views
    </p>
    <p>
      
    </p>
    <p>
      &#1056;&#1077;&#1096;&#1077;&#1085;&#1080;&#1103; &#1079;&#1072;&#1076;&#1072;&#1095; 1-4
    </p>
    <p>
      <font color="#0000c0">$ psql</font>
    </p>
    <p>
      1.<font color="#0000c0">postgres=# \d pg_class</font>
    </p>
    <p>
      2.<font color="#0000c0">postgres=# \d+ pg_tables</font>
    </p>
    <p>
      3.<font color="#0000c0">postgres=# \dtv pg_stat*</font>
    </p>
    <p>
      4.<font color="#0000c0">postgres=# \df pg_catalog.pg_*</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1056;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1079;&#1072;&#1076;&#1072;&#1095;&#1080; 5
    </p>
    <p>
      <font color="#0000c0">$ psql -E </font>
    </p>
    <p>
      <font color="#0000c0">postgres=# \d+ pg_views</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="# Пример 2" ID="ID_102018547" CREATED="1528372680798" MODIFIED="1529096336272"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1041;&#1044; &#1080; &#1090;&#1077;&#1089;&#1090;&#1086;&#1074;&#1099;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099;</b>
    </p>
    <p>
      <font color="#0000c0">$ psql postgres -c &quot;CREATE DATABASE dba1_07_demo;&quot; </font>
    </p>
    <p>
      <font color="#0000c0">$ psql dba1_07_demo </font>
    </p>
    <p>
      <font color="#0000c0">=&gt; create table master_table (id int primary key, c text not null);</font>&#160; &#160;-- &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1084;&#1072;&#1089;&#1090;&#1077;&#1088;-&#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091;
    </p>
    <p>
      <font color="#0000c0">=&gt; comment on table master_table is '&#1058;&#1077;&#1089;&#1090;&#1086;&#1074;&#1072;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;';</font>&#160; -- &#1057;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1085;&#1077;&#1077; &#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1081;
    </p>
    <p>
      <font color="#0000c0">=&gt; create table detail_table (id int references master_table(id), c text);</font>&#160;-- &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1076;&#1077;&#1090;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091;, &#1089;&#1089;&#1099;&#1083;&#1072;&#1102;&#1097;&#1091;&#1102;&#1089;&#1103; &#1085;&#1072; &#1084;&#1072;&#1089;&#1090;&#1077;&#1088;
    </p>
    <p>
      <font color="#0000c0">=&gt; create view my_view as select * from detail_table;</font>&#160;&#160;-- &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#0000c0">=&gt; comment on column my_view.id is '&#1048;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;';</font>&#160; &#160;-- &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1081; &#1085;&#1072; &#1089;&#1090;&#1086;&#1083;&#1073;&#1077;&#1094; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">=&gt; \dt pg_catalog.*</font>&#160;&#160;-- &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1089;&#1083;&#1086;&#1074;&#1072;&#1088;&#1103;
    </p>
    <p>
      <font color="#0000c0">=&gt; \dv pg_catalog.*</font>&#160;&#160;-- &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1089;&#1083;&#1086;&#1074;&#1072;&#1088;&#1103;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1087;&#1080;&#1089;&#1086;&#1082; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1093; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081; &#1076;&#1083;&#1103; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074;&#160; </b>
    </p>
    <p>
      <font color="#0000c0">=&gt; \x</font>&#160;&#160;-- &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081; &#1089; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077;&#1084;. On \ Off
    </p>
    <p>
      <font color="#0000c0">=&gt; \df pg_catalog.pg_*size</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">=&gt; \sf pg_table_size</font>&#160;&#160;-- &#1055;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1103; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;
    </p>
    <p>
      <font color="#0000c0">\ef function_name</font>&#160;&#160;-- &#1056;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;
    </p>
    <p>
      <b>&#1055;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072; &#1073;&#1072;&#1079; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072;</b>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; select pd.datname as database_name </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt;&#160;&#160;&#160;&#160;&#160;&#160;&#160;,pg_database_size (pd.oid) as db_size_bytes </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt;&#160;&#160;&#160;&#160;&#160;&#160;&#160;,pg_size_pretty( </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;pg_database_size (pd.oid) </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;) as db_size_text </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt;&#160;&#160;&#160;from pg_database pd; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">=&gt; \dt</font>&#160;&#160;-- &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;
    </p>
    <p>
      <font color="#0000c0">=&gt; \dv</font>&#160;&#160;-- &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081;
    </p>
    <p>
      <font color="#0000c0">=&gt; \dtvismE</font>&#160;&#160;-- &#1054;&#1076;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1086;&#1081; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1090;&#1080;&#1087;&#1086;&#1074; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074;
    </p>
    <p>
      &#160;&#160;t - &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;
    </p>
    <p>
      &#160;&#160;v - &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      &#160;&#160;i - &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1099;
    </p>
    <p>
      &#160;&#160;s - &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080;
    </p>
    <p>
      &#160;&#160;m - &#1084;&#1072;&#1090;&#1077;&#1088;&#1080;&#1072;&#1083;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      &#160;&#160;E - &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;
    </p>
    <p>
      <font color="#0000c0">=&gt; \dt+</font>&#160;&#160;-- &#1052;&#1086;&#1076;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; + &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1091;&#1102; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102;. &#1057;&#1086;&#1089;&#1090;&#1072;&#1074; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1087;&#1088;&#1077;&#1076;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085; &#1080; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1090;&#1080;&#1087;&#1072; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;
    </p>
    <p>
      <font color="#0000c0">=&gt; \dtS *table*</font>&#160;&#160;-- &#1052;&#1086;&#1076;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; S &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1074; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1080; &#1082; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1084;
    </p>
    <p>
      <font color="#0000c0">=&gt; \d master_table</font>&#160;&#160;-- &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086;&#1073; &#1086;&#1076;&#1085;&#1086;&#1084; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1077; (&#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;, &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;, &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;, &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1074;&#1085;&#1077;&#1096;&#1085;&#1103;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;)
    </p>
    <p>
      <font color="#0000c0">=&gt; \d+ my_view</font>&#160;&#160;-- &#1052;&#1086;&#1076;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; + &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1080; &#1076;&#1083;&#1103; \d
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; REG* &#1090;&#1080;&#1087;&#1086;&#1074;.</b>
    </p>
    <p>
      &#1053;&#1072;&#1087;&#1080;&#1096;&#1077;&#1084; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1099; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; my_view.
    </p>
    <p>
      &#1053;&#1072;&#1084; &#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1091;&#1102;&#1090;&#1089;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072;:
    </p>
    <p>
      &#160;&#160;pg_class - &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074;, &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1103; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      &#160;&#160;pg_attribute - &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1086;&#1074;
    </p>
    <p>
      <font color="#0000c0">=&gt; select oid, relname from pg_class limit 5; </font>
    </p>
    <p>
      <font color="#0000c0">=&gt; select attrelid, attname from pg_attribute limit 5;</font>
    </p>
    <p>
      &#1044;&#1074;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1089;&#1074;&#1103;&#1079;&#1072;&#1085;&#1099; &#1087;&#1086; pg_class.OID - pg_attribute.attrelid. &#1047;&#1072;&#1087;&#1088;&#1086;&#1089; &#1085;&#1072; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1076;&#1074;&#1091;&#1093; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;
    </p>
    <p>
      <font color="#0000c0">=&gt; select c.attrelid, c.attname </font>
    </p>
    <p>
      <font color="#0000c0">=&gt;&#160;&#160;&#160;from pg_attribute c, pg_class t </font>
    </p>
    <p>
      <font color="#0000c0">=&gt;&#160;&#160;where c.attrelid = t.oid </font>
    </p>
    <p>
      <font color="#0000c0">=&gt;&#160;&#160;&#160;&#160;and t.relname = 'my_view';</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1047;&#1072;&#1087;&#1088;&#1086;&#1089; &#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; regclass:
    </p>
    <p>
      <font color="#0000c0">=&gt; select attrelid, attname </font>
    </p>
    <p>
      <font color="#0000c0">=&gt;&#160;&#160;&#160;from pg_attribute </font>
    </p>
    <p>
      <font color="#0000c0">=&gt;&#160;&#160;where attrelid = 'my_view'::regclass; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">psql postgres -c &quot;DROP DATABASE dba1_07_demo;&quot; </font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Правила именования" ID="ID_723500236" CREATED="1528363948781" MODIFIED="1549630182038"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;</b>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        &#1053;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1080; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089; '<b>pg_</b>'. &#1044;&#1083;&#1103; &#1087;&#1088;&#1077;&#1076;&#1086;&#1090;&#1074;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1090;&#1077;&#1085;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1086;&#1085;&#1092;&#1083;&#1080;&#1082;&#1090;&#1086;&#1074;, &#1085;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099;, &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1102;&#1097;&#1080;&#1077;&#1089;&#1103; &#1089; 'pg_'
      </li>
      <li>
        &#1053;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1086;&#1074; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1080;&#1084;&#1077;&#1102;&#1090; 3-&#1093; &#1073;&#1091;&#1082;&#1074;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;. &#1055;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1080;&#1084;&#1077;&#1085;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072;. &#1055;&#1086;&#1089;&#1083;&#1077; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;&#1072; &#1085;&#1077;&#1090; &#1079;&#1085;&#1072;&#1082;&#1072; &#1087;&#1086;&#1076;&#1095;&#1077;&#1088;&#1082;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; '_'.<br align="-webkit-auto" style="font-variant: normal; letter-spacing: normal; line-height: normal; text-indent: 0px; text-transform: none; white-space: normal; word-spacing: 0px"/>

        <ul>
          <li>
            pg_proc &#8211; &#1074;&#1089;&#1077; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1099; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089; '<b>pro</b>'
          </li>
          <li>
            pg_attribute &#8211; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089; '<b>att</b>'
          </li>
          <li>
            pg_namespace &#8211; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089; '<b>nsp</b>'
          </li>
          <li>
            pg_tablespace &#8211; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089; '<b>spc</b>'
          </li>
          <li>
            pg_class &#8211; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089; '<b>rel</b>'
          </li>
        </ul>
      </li>
      <li>
        &#1053;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1093; &#1089;&#1083;&#1086;&#1074;&#1072;&#1088;&#1103; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1074; &#1085;&#1080;&#1078;&#1085;&#1077;&#1084; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1077;
      </li>
    </ul>
    <p>
      <b>&#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;,</b>
    </p>
    <p>
      <font color="#0000c0">select * from pg_tablespace where spcname = 'pg_global';</font>
    </p>
    <p>
      &#1042;&#1089;&#1077; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1099; pg_tablespace &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089; 'spc', &#1072; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1089;&#1090;&#1074;&#1072; &#1074; where &#1085;&#1091;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1074; &#1085;&#1080;&#1078;&#1085;&#1077;&#1084; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1077;.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Общие таблицы кластера" ID="ID_861200213" CREATED="1528368093997" MODIFIED="1728996005721"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1252306682"><span style="font-weight: normal;">Кластер</span></a>
    </p>
    <p>
      
    </p>
    <p>
      У каждой БД кластера свой набор таблиц системного каталога
    </p>
    <p>
      
    </p>
    <p>
      <b>8 глобальных для кластера БД таблиц:</b>
    </p>
    <ul>
      <li>
        базы данных: <b>pg_database</b>
      </li>
      <li>
        табличные пространства: <b>pg_tablespace</b>
      </li>
      <li>
        роли: <b>pg_authid</b>, <b>pg_auth_members</b>
      </li>
      <li>
        настройки для ролей и БД: <b>pg_db_role_settings</b>
      </li>
      <li>
        шаблоны процедурных языков: <b>pg_pltemplate</b>
      </li>
      <li>
        зависимости и описания для общих объектов: <b>pg_shdepend</b>, <b>pg_shdescription</b>
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Специальные типы данных" ID="ID_1549296576" CREATED="1528371208005" MODIFIED="1529096190689"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1090;&#1080;&#1087;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;</b><br align="-webkit-auto" style="font-variant: normal; letter-spacing: normal; line-height: normal; text-indent: 0px; text-transform: none; white-space: normal; word-spacing: 0px"/>
    </p>
    <p>
      
    </p>
    <p>
      <b>OID</b>&#160;(Object Identifier) -&#160;&#1090;&#1080;&#1087; &#1076;&#1083;&#1103; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1072; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;, &#1101;&#1090;&#1086; &#1089;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1089;&#1090;&#1086;&#1083;&#1073;&#1077;&#1094;. &#1069;&#1090;&#1086; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1094;&#1077;&#1083;&#1086;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1090;&#1080;&#1087; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1089; &#1088;&#1072;&#1079;&#1088;&#1103;&#1076;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; 32 &#1073;&#1080;&#1090;&#1072; (4294967296), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1086;&#1073;&#1085;&#1091;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1080;. &#1048;&#1084;&#1077;&#1085;&#1085;&#1086; &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091;, &#1077;&#1075;&#1086; &#1085;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;. &#1044;&#1083;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072; &#1101;&#1090;&#1086;&#1075;&#1086; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086;, &#1086;&#1076;&#1085;&#1072;&#1082;&#1086; &#1076;&#1083;&#1103; &#1088;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1099;&#1093; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1041;&#1044; &#1101;&#1090;&#1086;&#1090; &#1089;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100;&#1089;&#1103;. &#1055;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1080; &#1089;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082; &#1086;&#1073;&#1085;&#1091;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080; &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1091;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; OID &#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1089;&#1103; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;
    </p>
    <ul>
      <li>
        &#1055;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1099;&#1081;/&#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1081; &#1082;&#1083;&#1102;&#1095;&#1080; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072;
      </li>
      <li>
        &#1053;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103;, &#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;<br/>(CREATE TABLE &#8230; WITH OIDS)
      </li>
      <li>
        &#1057;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1089;&#1090;&#1086;&#1083;&#1073;&#1077;&#1094;, &#1085;&#1091;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1103;&#1074;&#1085;&#1086;:<br/>SELECT OID, * FROM pg_database
      </li>
    </ul>
    <p>
      <b>REG* &#1090;&#1080;&#1087;&#1099;</b>
    </p>
    <ul>
      <li>
        &#1055;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072; &#1082; OID<br/>SELECT * FROM pg_attribute<br/>WHERE attrelid = 'my_table'::REGCLASS;
      </li>
      <li>
        &#1053;&#1077; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1089;&#1083;&#1086;&#1074;&#1072;&#1088;&#1103;
      </li>
    </ul>
    <p>
      REG* &#1090;&#1080;&#1087;&#1099; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1076;&#1083;&#1103; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1093; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074;:
    </p>
    <ul>
      <li>
        &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;: regproc, regprocedure
      </li>
      <li>
        &#1054;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1099;: regoper, regoperator
      </li>
      <li>
        &#1054;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103;: regclass
      </li>
      <li>
        &#1058;&#1080;&#1087;&#1099;: regtype
      </li>
      <li>
        &#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;: regconfig
      </li>
      <li>
        &#1057;&#1083;&#1086;&#1074;&#1072;&#1088;&#1080; &#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;: regdictionary
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Системные представления" ID="ID_1094432602" CREATED="1528371799644" MODIFIED="1529096190475"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1077; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1063;&#1072;&#1089;&#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099;</b>. &#1055;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1077; &#1095;&#1072;&#1089;&#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1084; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072;. &#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072; &#1076;&#1083;&#1103; &#1089;&#1074;&#1103;&#1079;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1086;&#1073;&#1086;&#1081; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090; OID. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1095;&#1080;&#1090;&#1072;&#1077;&#1084;&#1099;&#1077; &#1080;&#1084;&#1077;&#1085;&#1072; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1082;&#1083;&#1102;&#1095;&#1077;&#1081; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1089; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1084;&#1080;. &#1044;&#1083;&#1103; &#1085;&#1072;&#1080;&#1073;&#1086;&#1083;&#1077;&#1077; &#1087;&#1086;&#1087;&#1091;&#1083;&#1103;&#1088;&#1085;&#1099;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1099; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;.
    </p>
    <ul>
      <li>
        pg_tables, pg_views, pg_user, &#8230;
      </li>
    </ul>
    <p>
      <b>&#1058;&#1077;&#1082;&#1091;&#1097;&#1077;&#1077; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.</b>&#160; &#1056;&#1103;&#1076; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1077; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1093; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1086;&#1082;, &#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;.
    </p>
    <ul>
      <li>
        pg_locks, pg_prepared_statements, &#8230;
      </li>
    </ul>
    <p>
      <b>&#1057;&#1086;&#1073;&#1088;&#1072;&#1085;&#1085;&#1072;&#1103; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1072;.</b>&#160; &#1053;&#1072;&#1073;&#1086;&#1088; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1093; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081;, &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1102;&#1097;&#1080;&#1093;&#1089;&#1103; &#1085;&#1072; pg_stat, &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1089;&#1086;&#1073;&#1088;&#1072;&#1085;&#1085;&#1086;&#1081; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1077;
    </p>
    <ul>
      <li>
        pg_stat*
      </li>
    </ul>
    <p>
      <b>&#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;.</b>&#160; &#1057;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; pg_settings &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072;&#1093; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <ul>
      <li>
        pg_settings
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      &#1055;&#1086;&#1083;&#1085;&#1099;&#1081; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082;: <font color="#0000c0">\dv pg_catalog.*</font>
