<node TEXT="Сопровождение" FOLDED="true" ID="ID_1880181317" CREATED="1528970605161" MODIFIED="1728899398018"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Задачи сопровождения</b>
    </p>
    <p>
      <b>Обязательные периодические задачи</b>
    </p>
    <ul>
      <li>
        очистка страниц от старых версий строк (<b>vacuum</b>)
      </li>
      <li>
        обновление статистики (<b>vacuum</b>)
      </li>
      <li>
        обновление карт видимости и свободного пространства (<b>vacuum</b>)
      </li>
      <li>
        избежание переполнения номера транзакции (<b>vacuum</b>)
      </li>
      <li>
        мониторинг индексов. Индексы требует определенного присмотра и иногда может потребоваться их перестроение
      </li>
      <li>
        резервное копирование
      </li>
    </ul>
    <p>
      <b>Выполняются фоновыми процессами или вручную (скриптами)</b>
    </p>
  </body>
</html></richcontent>
<node TEXT="# Пример" ID="ID_1078274415" CREATED="1529098217447" MODIFIED="1529098367972"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1072;</b>
    </p>
    <p>
      1. &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; autovacuum &#1080; &#1091;&#1073;&#1077;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103;, &#1095;&#1090;&#1086; &#1086;&#1085; &#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;.
    </p>
    <p>
      2. &#1042; &#1073;&#1072;&#1079;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; DB15 &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1089; &#1086;&#1076;&#1085;&#1080;&#1084; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1099;&#1084; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1086;&#1084; &#1080; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089; &#1087;&#1086; &#1101;&#1090;&#1086;&#1081; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077;.
    </p>
    <p>
      3. &#1042;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; 100 000 &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1099;&#1093; &#1095;&#1080;&#1089;&#1077;&#1083;.
    </p>
    <p>
      4. &#1053;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1088;&#1072;&#1079; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1086;&#1074;&#1080;&#1085;&#1091; &#1089;&#1090;&#1088;&#1086;&#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;, &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1080;&#1088;&#1091;&#1103; &#1085;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1096;&#1072;&#1075;&#1077; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1080; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1072;
    </p>
    <p>
      5. &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; vacuum full.
    </p>
    <p>
      6. &#1055;&#1086;&#1074;&#1090;&#1086;&#1088;&#1080;&#1090;&#1100; &#1087;&#1091;&#1085;&#1082;&#1090; 4, &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; vacuum.
    </p>
    <p>
      7. &#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; autovacuum.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1056;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077;</b>
    </p>
    <p>
      <font color="#0000c0"># alter system set autovacuum = off; </font>
    </p>
    <p>
      <font color="#0000c0">$ pg_ctl reload </font>
    </p>
    <p>
      <font color="#0000c0">$ ps -o pid,command --ppid `head -n 1 $PGDATA/postmaster.pid` </font>
    </p>
    <p>
      <font color="#0000c0"># show autovacuum </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># create database db15; </font>
    </p>
    <p>
      <font color="#0000c0"># \c db15 </font>
    </p>
    <p>
      <font color="#0000c0"># create table t(n numeric); </font>
    </p>
    <p>
      <font color="#0000c0"># create index t_n on t(n); </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># insert into t select random() from generate_series(1,100000); </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># select pg_size_pretty(pg_table_size('t')), pg_size_pretty(pg_indexes_size('t')); </font>
    </p>
    <p>
      <font color="#0000c0"># update t set n=n where n &lt; 0.5;</font>
    </p>
    <p>
      -- &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1080;&#1090;&#1100; (&#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1086; &#1088;&#1072;&#1089;&#1090;&#1077;&#1090;)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># vacuum full t;</font>
    </p>
    <p>
      -- &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1074;&#1077;&#1088;&#1085;&#1091;&#1083;&#1089;&#1103; &#1082; &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084;&#1091;, &#1080;&#1085;&#1076;&#1077;&#1082;&#1089; &#1089;&#1090;&#1072;&#1083; &#1082;&#1086;&#1084;&#1087;&#1072;&#1082;&#1090;&#1085;&#1077;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># select pg_size_pretty(pg_table_size('t')), pg_size_pretty(pg_indexes_size('t')); </font>
    </p>
    <p>
      <font color="#0000c0"># update t set n=n where n &lt; 0.5; </font>
    </p>
    <p>
      <font color="#0000c0"># vacuum t;</font>
    </p>
    <p>
      -- &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1080;&#1090;&#1100; (&#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1083;&#1089;&#1103; &#1086;&#1076;&#1080;&#1085; &#1088;&#1072;&#1079; &#1080; &#1089;&#1090;&#1072;&#1073;&#1080;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1083;&#1089;&#1103;)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># alter system set autovacuum = on; </font>
    </p>
    <p>
      <font color="#0000c0">$ pg_ctl reload</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Очистка" FOLDED="true" ID="ID_549836306" CREATED="1528972143412" MODIFIED="1528985636492"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1054;&#1095;&#1080;&#1089;&#1090;&#1082;&#1072;</b>
    </p>
    <p>
      
    </p>
    <p>
      &#1053;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080; &#1074;&#1099;&#1079;&#1074;&#1072;&#1085;&#1072; &#1090;&#1077;&#1084;, &#1095;&#1090;&#1086; &#1087;&#1088;&#1080; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080; &#1080; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1080; &#1089;&#1090;&#1088;&#1086;&#1082; &#1074; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072;&#1093; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1080;&#1093; &#1089;&#1090;&#1072;&#1088;&#1099;&#1077; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080;, &#1082;&#1072;&#1082; &#1090;&#1086;&#1075;&#1086; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084; &#1084;&#1085;&#1086;&#1075;&#1086;&#1074;&#1077;&#1088;&#1089;&#1080;&#1086;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080;. &#1057;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1086;&#1074; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094; &#1086;&#1090; &#1074;&#1077;&#1088;&#1089;&#1080;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1102;&#1090;&#1089;&#1103; &#1085;&#1080; &#1076;&#1083;&#1103; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1089;&#1085;&#1080;&#1084;&#1082;&#1072;.&#160;
    </p>
    <ul>
      <li>
        <b>autovacuum - </b>&#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;
      </li>
      <li>
        <b>vacuum - &#1088;&#1091;&#1095;&#1085;&#1086;&#1081; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;</b>
      </li>
      <li>
        <b>vacuum full</b>&#160;- &#1087;&#1088;&#1080; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1086;&#1084; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074;&#1099;&#1088;&#1072;&#1089;&#1090;&#1072;&#1102;&#1090; &#1085;&#1072; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1091;&#1102; &#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1085;&#1091; &#1079;&#1072; &#1089;&#1095;&#1077;&#1090; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081; &#1084;&#1077;&#1078;&#1076;&#1091; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1084;&#1080; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080;. &#1045;&#1089;&#1083;&#1080; &#1092;&#1072;&#1081;&#1083;&#1099; &#1074;&#1099;&#1088;&#1086;&#1089;&#1083;&#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;, &#1095;&#1077;&#1084; &#1101;&#1090;&#1086; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1088;&#1072;&#1079;&#1091;&#1084;&#1085;&#1099;&#1084; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1079;&#1072; &#1089;&#1095;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1086;&#1074;&#1099;&#1093; &#1074;&#1085;&#1077;&#1087;&#1083;&#1072;&#1085;&#1086;&#1074;&#1099;&#1093; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1081;), &#1090;&#1086; &#1076;&#1083;&#1103; &#1086;&#1089;&#1074;&#1086;&#1073;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1084;&#1077;&#1089;&#1090;&#1072; &#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082; vacuum full.
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="autovacuum (фоновый процесс )" ID="ID_372101256" CREATED="1528983719995" MODIFIED="1528984137944"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1060;&#1086;&#1085;&#1086;&#1074;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; autovacuum - </b>&#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1089; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1086;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1099; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1081; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1076;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1088;&#1072;&#1079;&#1088;&#1072;&#1089;&#1090;&#1072;&#1085;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;.
    </p>
    <ul>
      <li>
        &#1055;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1087;&#1072;&#1088;&#1072;&#1083;&#1083;&#1077;&#1083;&#1100;&#1085;&#1086; &#1089; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;&#1080; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1103;&#1084;&#1080;, &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1103; &#1092;&#1072;&#1081;&#1083;&#1099; &#1087;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1086;. &#1054;&#1085; &#1085;&#1077; &#1084;&#1080;&#1085;&#1080;&#1084;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1090; &#1084;&#1077;&#1089;&#1090;&#1086;, &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1077;&#1084;&#1086;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;&#1084;&#1080;, &#1080; &#1085;&#1077; &#1091;&#1084;&#1077;&#1085;&#1100;&#1096;&#1072;&#1077;&#1090; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; (&#1079;&#1072; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1103;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094; &#1074; &#1082;&#1086;&#1085;&#1094;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072; &#1086;&#1089;&#1074;&#1086;&#1073;&#1086;&#1078;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;)
