      <font color="#0000c0"># vacuum full</font>&#160;&#160;-- &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1072; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;
    </p>
    <p>
      <font color="#0000c0"># vacuum full</font>&#160;&#160;-- &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1072; &#1074;&#1089;&#1077;&#1081; &#1041;&#1044;
    </p>
    <p>
      <font color="#0000c0">$ vacuumdb --full</font>&#160;&#160;-- &#1086;&#1073;&#1077;&#1088;&#1090;&#1082;&#1072; &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074; &#1054;&#1057;
    </p>
    <ul>
      <li>
        &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1080; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1086;&#1074;, &#1091;&#1084;&#1077;&#1085;&#1100;&#1096;&#1072;&#1103; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1080; &#1084;&#1080;&#1085;&#1080;&#1084;&#1080;&#1079;&#1080;&#1088;&#1091;&#1103; &#1084;&#1077;&#1089;&#1090;&#1086;
      </li>
      <li>
        &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; &#1101;&#1082;&#1089;&#1082;&#1083;&#1102;&#1079;&#1080;&#1074;&#1085;&#1086;&#1081; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1080; &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1087;&#1072;&#1088;&#1072;&#1083;&#1083;&#1077;&#1083;&#1100;&#1085;&#1086; &#1089; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;&#1080; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1103;&#1084;&#1080;
      </li>
      <li>
        &#1087;&#1086;&#1083;&#1077;&#1079;&#1077;&#1085; &#1087;&#1088;&#1080; &#1087;&#1086;&#1083;&#1085;&#1086;&#1084; &#1080;&#1083;&#1080; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1084; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;
      </li>
      <li>
        &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1086;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100;&#1089;&#1103; <b>TRUNCATE</b>&#160;&#1074;&#1084;&#1077;&#1089;&#1090;&#1086; <b>DELETE (</b>&#1045;&#1089;&#1083;&#1080; &#1088;&#1077;&#1095;&#1100; &#1080;&#1076;&#1077;&#1090; &#1086;&#1073; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1087;&#1086;&#1089;&#1083;&#1077; &#1084;&#1072;&#1089;&#1089;&#1086;&#1074;&#1099;&#1093; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;). &#160;<b>Truncate</b>&#160;&#1089;&#1088;&#1072;&#1079;&#1091; &#1078;&#1077; &#1086;&#1089;&#1074;&#1086;&#1073;&#1086;&#1078;&#1076;&#1072;&#1077;&#1090; &#1074;&#1089;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;, &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1103; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080;. &#1053;&#1086; &#1085;&#1072;&#1076;&#1086; &#1080;&#1084;&#1077;&#1090;&#1100; &#1074; &#1074;&#1080;&#1076;&#1091;, &#1095;&#1090;&#1086; truncate &#1093;&#1086;&#1090;&#1103; &#1080; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1086;&#1081; (&#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1086;&#1090;&#1084;&#1077;&#1085;&#1077;&#1085; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1086;&#1081; rollback), &#1085;&#1086; &#1074;&#1077;&#1076;&#1077;&#1090; &#1089;&#1077;&#1073;&#1103; &#1085;&#1077; &#1090;&#1072;&#1082;, &#1082;&#1072;&#1082; delete: &#1086;&#1085; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1101;&#1082;&#1089;&#1082;&#1083;&#1102;&#1079;&#1080;&#1074;&#1085;&#1091;&#1102; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1091; &#1085;&#1072; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091;. &#1058;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, truncate &#1085;&#1072;&#1095;&#1085;&#1077;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1077;&#1085;&#1080;&#1103; &#1074;&#1089;&#1077;&#1093; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1081;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1093; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; (&#1093;&#1086;&#1090;&#1103; &#1073;&#1099; &#1080; &#1076;&#1083;&#1103; &#1095;&#1090;&#1077;&#1085;&#1080;&#1103;), &#1080; &#1087;&#1086;&#1082;&#1072; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1103; &#1089; truncate &#1085;&#1077; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1080;&#1090;&#1089;&#1103;, &#1083;&#1102;&#1073;&#1086;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; (&#1093;&#1086;&#1090;&#1103; &#1073;&#1099; &#1080; &#1085;&#1072; &#1095;&#1090;&#1077;&#1085;&#1080;&#1077;)
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1078;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1101;&#1082;&#1089;&#1082;&#1083;&#1102;&#1079;&#1080;&#1074;&#1085;&#1072;&#1103; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1085;&#1077;&#1078;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1088;&#1072;&#1089;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1077;&#1077; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077; <b>pg_repack</b>, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1077;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1080;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1073;&#1077;&#1079; &#1085;&#1077;&#1077;.
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
