  <body>
    <p>
      <b>&#1054;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080;. </b>&#1058;&#1086;&#1095;&#1085;&#1072;&#1103; &#1080; &#1072;&#1082;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1072; &#1078;&#1080;&#1079;&#1085;&#1077;&#1085;&#1085;&#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1072; &#1076;&#1083;&#1103; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;&#1081; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1086;&#1087;&#1090;&#1080;&#1084;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1060;&#1086;&#1085;&#1086;&#1074;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; autovacuum</b>
    </p>
    <ul>
      <li>
        &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1103;&#1077;&#1090; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1087;&#1088;&#1080; &#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103;&#1093;
      </li>
      <li>
        <p>
          &#1045;&#1089;&#1083;&#1080; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086;, &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074; &#1088;&#1091;&#1095;&#1085;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; (analyze) &#1080;&#1083;&#1080; &#1074;&#1084;&#1077;&#1089;&#1090;&#1077; &#1089; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1086;&#1081; (vacuum analyze)
        </p>
      </li>
    </ul>
    <p>
      <b>ANALYZE</b>
    </p>
    <ul>
      <li>
        <font color="#0000c0"># analyze [&#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;]</font>&#160;&#160;-- &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080; (&#1072;&#1085;&#1072;&#1083;&#1080;&#1079;)
      </li>
      <li>
        <font color="#0000c0">$ vacuumdb --analyze-only</font>&#160;&#160;-- &#1086;&#1073;&#1077;&#1088;&#1090;&#1082;&#1072;
      </li>
      <li>
        &#1055;&#1088;&#1080; &#1089;&#1073;&#1086;&#1088;&#1077; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080; &#1095;&#1080;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1072;&#1103; &#1074;&#1099;&#1073;&#1086;&#1088;&#1082;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;. &#1069;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1090;&#1100; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1076;&#1072;&#1078;&#1077; &#1087;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1084;
      </li>
      <li>
        &#1056;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1077; &#1090;&#1086;&#1095;&#1085;&#1099;&#1081;, &#1085;&#1086; &#1074; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;&#1074; &#1074; &#1101;&#1090;&#1086;&#1084; &#1085;&#1077;&#1090; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1089;&#1090;&#1088;&#1072;&#1096;&#1085;&#1086;&#1075;&#1086;. &#1055;&#1088;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1074;&#1099;&#1073;&#1086;&#1088;&#1082;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1090;&#1100;.
      </li>
    </ul>
    <p>
      <b>VACUUM</b>
    </p>
    <ul>
      <li>
        <font color="#0000c0"># vacuum analyze [&#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;]</font>&#160; &#160;-- &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1072; &#1080; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;
      </li>
      <li>
        <font color="#0000c0">$ vacuumdb --analyze</font>&#160;&#160;-- &#1086;&#1073;&#1077;&#1088;&#1090;&#1082;&#1072;
      </li>
      <li>
        &#1087;&#1086;&#1084;&#1080;&#1084;&#1086; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080; &#1090;&#1072;&#1082;&#1078;&#1077; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1103;&#1077;&#1090; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091;
      </li>
    </ul>
    <p>
      
    </p>
  </body>
</html></richcontent>
