<node TEXT="Обновление карт" ID="ID_1850701082" CREATED="1528986744597" MODIFIED="1529046828197"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1054;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1082;&#1072;&#1088;&#1090;</b>
    </p>
    <p>
      <b>&#1050;&#1072;&#1088;&#1090;&#1072; &#1074;&#1080;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; (vm)</b>
    </p>
    <ul>
