<node TEXT="Перестроение без блокировки" ID="ID_1828894885" CREATED="1529048661000" MODIFIED="1529049229103"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1077;&#1088;&#1077;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1080;&#1077; &#1073;&#1077;&#1079; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; - </b>&#1087;&#1077;&#1088;&#1077;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1080;&#1077; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1072; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; &#1074; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1096;&#1072;&#1075;&#1086;&#1074;.
    </p>
    <p>
      
    </p>
    <p>
      &#1057;&#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1086;&#1074;&#1099;&#1081; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089; &#1074; &#1085;&#1077;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; (&#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1086;&#1077; &#1089;&#1083;&#1086;&#1074;&#1086; concurrently), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1074;&#1077;&#1089;&#1090;&#1080; &#1087;&#1072;&#1088;&#1072;&#1083;&#1083;&#1077;&#1083;&#1100;&#1085;&#1091;&#1102; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091; &#1089; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077;&#1081;. &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; &#1085;&#1077;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1077;&#1091;&#1076;&#1072;&#1095;&#1085;&#1086; (&#1080;&#1079;-&#1079;&#1072; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1086;&#1082;) &#8212; &#1074; &#1090;&#1072;&#1082;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089; &#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1080; &#1087;&#1086;&#1087;&#1088;&#1086;&#1073;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1077;&#1097;&#1077; &#1088;&#1072;&#1079;. &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1090;&#1072;&#1082;&#1072;&#1103; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1103; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1080;.
    </p>
    <p>
      &#1047;&#1072;&#1090;&#1077;&#1084; &#1089;&#1090;&#1072;&#1088;&#1099;&#1081; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103;. &#1051;&#1080;&#1073;&#1086;, &#1077;&#1089;&#1083;&#1080; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089; &#1091;&#1095;&#1072;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1074; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1080; &#1094;&#1077;&#1083;&#1086;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080;, &#1089;&#1090;&#1072;&#1088;&#1086;&#1077; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; (&#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080; &#1089;&#1090;&#1072;&#1088;&#1099;&#1081; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;) &#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1086;&#1074;&#1086;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1077;&#1088;&#1077;&#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1073;&#1077;&#1079; &#1101;&#1082;&#1089;&#1082;&#1083;&#1102;&#1079;&#1080;&#1074;&#1085;&#1086;&#1081; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080;</b>
    </p>
    <p>
      <font color="#0000c0"># create index new on ... concurrently;</font>
    </p>
    <p>
      <font color="#0000c0"># drop index old;</font>
    </p>
    <ul>
      <li>
        &#1076;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1086;&#1074; &#1087;&#1086; &#1086;&#1076;&#1085;&#1080;&#1084; &#1080; &#1090;&#1077;&#1084; &#1078;&#1077; &#1087;&#1086;&#1083;&#1103;&#1084;
      </li>
      <li>
        &#1085;&#1077; &#1074;&#1089;&#1077; &#1090;&#1080;&#1087;&#1099; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1086;&#1074; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1090; &#1085;&#1077;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077;
      </li>
      <li>
        &#1085;&#1077;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1085;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;
      </li>
      <li>
        &#1085;&#1077;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1077;&#1091;&#1076;&#1072;&#1095;&#1085;&#1086;
      </li>
    </ul>
    <p>
      <b>&#1048;&#1085;&#1076;&#1077;&#1082;&#1089; &#1089; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1094;&#1077;&#1083;&#1086;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080;</b>
    </p>
    <p>
      <font color="#0000c0"># create unique index new on ... concurrently; </font>
    </p>
    <p>
      <font color="#0000c0"># alter table ... </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;drop constraint old, </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;add constraint new [unique|primary key] using index new;</font>
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Резервирование" FOLDED="true" ID="ID_1034911599" CREATED="1529051595872" MODIFIED="1529051899160">
<node TEXT="Логическое" FOLDED="true" ID="ID_792883471" CREATED="1529051610213" MODIFIED="1728995982447"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Логическое резервирование </b>- это набор команд SQL, восстанавливающий кластер (или базу данных, или отдельный объект) с нуля
    </p>
    <p>
      
    </p>
    <p>
      Команды можно выполнить на другой версии СУБД (при наличии совместимости на уровне команд) или на другой архитектуре (не требуется двоичная совместимость). Однако для большой базы выполняться они будут долго.
    </p>
    <p>
      
    </p>
    <p>
      <b>Сравнение форматов</b>
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;<b>plain&#xa0;&#xa0;&#xa0;custom&#xa0;&#xa0;&#xa0;directory&#xa0;&#xa0;&#xa0;tar</b>
    </p>
    <p>
      утилита для восстановления&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;psql&#xa0;&#xa0; <u>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;pg_restore&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0; </u>&#xa0;&#xa0;
    </p>
    <p>
      сжатие&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;<u>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;zlib&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;</u>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-
    </p>
    <p>
      выборочное восстановление&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;да&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;да&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;да
    </p>
    <p>
      параллельное резервирование&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;да&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-
    </p>
    <p>
      параллельное восстановление&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;да&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;да&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-
    </p>
  </body>
</html></richcontent>
<node TEXT="Примеры" ID="ID_313062619" CREATED="1529081282329" MODIFIED="1529098497461"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1072;</b>
    </p>
    <p>
      1. &#1057;&#1086;&#1079;&#1076;&#1072;&#1081;&#1090;&#1077; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; DB16.
    </p>
    <p>
      2. &#1057;&#1086;&#1079;&#1076;&#1072;&#1081;&#1090;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1089; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1084;&#1080; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072;&#1084;&#1080; &#1074; &#1101;&#1090;&#1086;&#1081; &#1041;&#1044;.
    </p>
    <p>
      3. &#1057;&#1086;&#1079;&#1076;&#1072;&#1081;&#1090;&#1077; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1091;&#1102; &#1082;&#1086;&#1087;&#1080;&#1102; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.
    </p>
    <p>
      4. &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091;.
    </p>
    <p>
      5. &#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1080;&#1079; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1081; &#1082;&#1086;&#1087;&#1080;&#1080; &#1074; &#1041;&#1044; postgres.
    </p>
    <p>
      6. &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1077; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.
    </p>
    <p>
      7. &#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1077; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080;&#1079; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1081; &#1082;&#1086;&#1087;&#1080;&#1080;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1056;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077;</b>
    </p>
    <p>
      <font color="#0000c0"># create database db16; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># \c db16 </font>
    </p>
    <p>
      <font color="#0000c0"># create table t(n numeric); </font>
    </p>
    <p>
      <font color="#0000c0"># insert into t values (1), (2), (3); </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">$ pg_dump --format=custom -f db16.dump -d db16</font>
    </p>
    <p>
      -- &#1087;&#1086;&#1076;&#1086;&#1081;&#1076;&#1077;&#1090; &#1080; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; directory
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># drop table t; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">$ pg_restore --table t -d postgres db16.dump </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># \c postgres </font>
    </p>
    <p>
      <font color="#0000c0"># drop database db16; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">$ pg_restore --create -d postgres db16.dump</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="copy: копия таблицы" FOLDED="true" ID="ID_910099885" CREATED="1529052380170" MODIFIED="1529053122608"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>COPY: &#1082;&#1086;&#1087;&#1080;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;&#160;&#160;-- </b>&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1072;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; COPY &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; <b>&#1073;&#1099;&#1089;&#1090;&#1088;&#1077;&#1077;</b>, &#1095;&#1077;&#1084; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1099;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; INSERT &#8212; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1084;&#1085;&#1086;&#1075;&#1086; &#1088;&#1072;&#1079; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;, &#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1084;&#1085;&#1086;&#1075;&#1086; &#1088;&#1072;&#1079; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;.
    </p>
    <p>
      <b>&#1058;&#1086;&#1085;&#1082;&#1086;&#1089;&#1090;&#1100;</b>: &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; <b>copy from</b>&#160;&#1085;&#1077; &#1087;&#1088;&#1080;&#1074;&#1086;&#1076;&#1080;&#1090; &#1082; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1102; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083; (rules), &#1093;&#1086;&#1090;&#1103; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1094;&#1077;&#1083;&#1086;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080; &#1090;&#1088;&#1080;&#1075;&#1075;&#1077;&#1088;&#1099; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1056;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; </b>
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1086;&#1076;&#1085;&#1086;&#1081; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1086;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1086;&#1081; COPY. &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; (&#1080;&#1083;&#1080; &#1095;&#1072;&#1089;&#1090;&#1100; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1086;&#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;, &#1080;&#1083;&#1080; &#1076;&#1072;&#1078;&#1077; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;) &#1083;&#1080;&#1073;&#1086; &#1074; &#1092;&#1072;&#1081;&#1083;, &#1083;&#1080;&#1073;&#1086; &#1085;&#1072; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">copy tbl to 'file';</font>&#160;&#160;-- &#1074;&#1099;&#1074;&#1086;&#1076; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1074; &#1092;&#1072;&#1081;&#1083;
    </p>
    <p>
      <font color="#0000c0">copy (select * from tbl) to stdout</font>&#160;&#160;-- &#1074;&#1099;&#1074;&#1086;&#1076; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1085;&#1072; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0">(format text,</font>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-- &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; (text, csv, binary)
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0">delimiter ',',</font>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-- &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1080;&#1090;&#1077;&#1083;&#1100; &#1087;&#1086;&#1083;&#1077;&#1081;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0">null '&lt;null&gt;');</font>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-- &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; null
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;</b>
    </p>
    <p>
      &#1057;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1080;&#1079; &#1092;&#1072;&#1081;&#1083;&#1072; &#1080;&#1083;&#1080; &#1080;&#1079; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1089; &#1087;&#1086;&#1083;&#1103;&#1084;&#1080; &#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1080;&#1093; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091;. &#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1085;&#1077; &#1086;&#1095;&#1080;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1085;&#1086;&#1074;&#1099;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1082; &#1091;&#1078;&#1077; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1084;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">copy tbl from 'file';</font>&#160;&#160;-- &#1087;&#1088;&#1086;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100; &#1080;&#1079; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      <font color="#0000c0">copy tbl from stdin;</font>&#160;&#160;-- &#1087;&#1088;&#1086;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100; &#1089; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080; &#1076;&#1086; EOF &#1080;&#1083;&#1080; \.
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="Примеры" ID="ID_995471490" CREATED="1529081445912" MODIFIED="1529081463667"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>COPY</b>
    </p>
    <p>
      &#1057;&#1086;&#1079;&#1076;&#1072;&#1076;&#1080;&#1084; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1074; &#1085;&#1077;&#1081;.
    </p>
    <p>
      =&gt; create database db;
    </p>
    <p>
      =&gt; \c db
    </p>
    <p>
      =&gt; create table t(id numeric, s text);
    </p>
    <p>
      =&gt; insert into t values (1, 'Hi there!');
    </p>
    <p>
      =&gt; insert into t values (2, '');
    </p>
    <p>
      =&gt; insert into t values (3, null);
    </p>
    <p>
      =&gt; select * from t;
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      &#1042;&#1086;&#1090; &#1082;&#1072;&#1082; &#1074;&#1099;&#1075;&#1083;&#1103;&#1076;&#1080;&#1090; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1074; &#1074;&#1099;&#1074;&#1086;&#1076;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; COPY:
    </p>
    <p>
      =&gt; copy t to stdout;
    </p>
    <p>
      &#1054;&#1073;&#1088;&#1072;&#1090;&#1080;&#1084; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1090;&#1086;, &#1095;&#1090;&#1086; &#1087;&#1091;&#1089;&#1090;&#1072;&#1103; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072; &#1080; null - &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;, &#1093;&#1086;&#1090;&#1103; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1103; select &#1101;&#1090;&#1086;&#1075;&#1086; &#1080; &#1085;&#1077; &#1079;&#1072;&#1084;&#1077;&#1090;&#1085;&#1086;.
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      &#1040;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;:
    </p>
    <p>
      =&gt; truncate table t;
    </p>
    <p>
      =&gt; copy t from stdin;
    </p>
    <p>
      =&gt; 1&#160;&#160;&#160;&#160;Hi there!
    </p>
    <p>
      =&gt; 2&#160;&#160;&#160;
    </p>
    <p>
      =&gt; 3&#160;&#160;&#160;&#160;\N
    </p>
    <p>
      =&gt; \.
    </p>
    <p>
      -----------------------------------------------------------------------
    </p>
    <p>
      &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1084;:
    </p>
    <p>
      =&gt; select * from t;
    </p>
    <p>
      =&gt; copy t to stdout;
    </p>
  </body>
</html></richcontent>
</node>
</node>
