  </head>
  <body>
    <p>
      <b>pg_dump: &#1082;&#1086;&#1087;&#1080;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074;</b>
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086;&#1083;&#1085;&#1086;&#1094;&#1077;&#1085;&#1085;&#1086;&#1081; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1081; &#1082;&#1086;&#1087;&#1080;&#1080; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; pg_dump. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1080;&#1084;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072; (--file), &#1090;&#1086; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; &#1074;&#1099;&#1074;&#1077;&#1076;&#1077;&#1090; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090; &#1085;&#1072; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;. &#1040; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1086;&#1084; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; psql, &#1080; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;, &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1097;&#1080;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1056;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1080;&#1083;&#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074; &#1074; &#1089;&#1093;&#1077;&#1084;&#1077;. </b>&#1064;&#1072;&#1073;&#1083;&#1086;&#1085; &#1080;&#1084;&#1077;&#1085;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1082;&#1083;&#1102;&#1095;&#1077; --table. &#1064;&#1072;&#1073;&#1083;&#1086;&#1085; &#1076;&#1083;&#1103; &#1089;&#1093;&#1077;&#1084;&#1099; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1082;&#1083;&#1102;&#1095;&#1077; --schema (&#1074; &#1101;&#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1099; &#1074;&#1089;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1074; &#1101;&#1090;&#1086;&#1081; &#1089;&#1093;&#1077;&#1084;&#1077;). &#1050;&#1083;&#1102;&#1095;&#1080; --data-only &#1080; --schema-only &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1097;&#1080;&#1084;&#1080;
    </p>
    <p>
      <font color="#0000c0">pg_dump --table=tbl -d db</font>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;# &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1087;&#1086; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1091;
    </p>
    <p>
      <font color="#0000c0">pg_dump --schema=scm -d db</font>&#160;&#160;&#160;# &#1089;&#1093;&#1077;&#1084;&#1099; &#1089;&#1086; &#1074;&#1089;&#1077;&#1084;&#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;&#1084;&#1080;
    </p>
    <p>
      <b>&#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;</b>
    </p>
    <p>
      <font color="#0000c0">--data-only</font>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; DML. &#1057;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;
    </p>
    <p>
      <font color="#0000c0">--schema-only</font>&#160;&#160;&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; DDL. &#1057;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074;
    </p>
    <p>
      <font color="#0000c0">--clean</font>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1087;&#1088;&#1077;&#1076;&#1074;&#1072;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#0000c0">--compress=N</font>&#160;&#160;&#1089;&#1078;&#1072;&#1090;&#1080;&#1077; (&#1085;&#1091;&#1078;&#1077;&#1085; zlib), N=0..9. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1086;
    </p>
    <p>
      <font color="#0000c0">--file=dump (-f)</font>&#160;&#160;&#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1077; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072; &#1074; &#1092;&#1072;&#1081;&#1083;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;</b>
    </p>
    <p>
      &#1063;&#1090;&#1086;&#1073;&#1099; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1080;&#1079; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1081; &#1082;&#1086;&#1087;&#1080;&#1080;, &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1087;&#1088;&#1086;&#1075;&#1085;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; &#1095;&#1077;&#1088;&#1077;&#1079; psql.
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084;&#1099;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1074; &#1073;&#1072;&#1079;&#1077;, &#1091;&#1076;&#1086;&#1073;&#1085;&#1086; &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1082;&#1083;&#1102;&#1095; --clean, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090; &#1074; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1087;&#1086; &#1087;&#1088;&#1077;&#1076;&#1074;&#1072;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1084;&#1091; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1102; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074;.
    </p>
    <p>
      <font color="#0000c0">psql -f dump</font>
    </p>
  </body>
</html></richcontent>
