<node TEXT="Холодное резервирование" ID="ID_12942000" CREATED="1529082973797" MODIFIED="1529085173901"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1061;&#1086;&#1083;&#1086;&#1076;&#1085;&#1086;&#1077; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;. </b>&#1057;&#1084;&#1099;&#1089;&#1083; &#1093;&#1086;&#1083;&#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1086;&#1089;&#1090;&#1086;&#1080;&#1090; &#1074; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1082;&#1086;&#1087;&#1080;&#1102; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1074; &#1090;&#1086;&#1090; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1086;&#1085;&#1072; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;. &#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1080;&#1079; &#1090;&#1072;&#1082;&#1086;&#1081; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1081; &#1082;&#1086;&#1087;&#1080;&#1080; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086;:
    </p>
    <p>
      &#1092;&#1072;&#1081;&#1083;&#1099; &#1088;&#1072;&#1079;&#1074;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#8212; &#1080; &#1086;&#1085; &#1089;&#1088;&#1072;&#1079;&#1091; &#1078;&#1077; &#1075;&#1086;&#1090;&#1086;&#1074; &#1082; &#1088;&#1072;&#1073;&#1086;&#1090;&#1077;. &#1050; &#1089;&#1086;&#1078;&#1072;&#1083;&#1077;&#1085;&#1080;&#1102;, &#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1081; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1090;&#1072;&#1082;&#1091;&#1102; &#1082;&#1086;&#1087;&#1080;&#1102; &#8212; &#1072;&#1082;&#1082;&#1091;&#1088;&#1072;&#1090;&#1085;&#1086; (&#1089; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077;&#1084; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1086;&#1081; &#1090;&#1086;&#1095;&#1082;&#1080;) &#1086;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;. &#1052;&#1080;&#1085;&#1091;&#1089; &#1087;&#1086;&#1085;&#1103;&#1090;&#1077;&#1085;:
    </p>
    <p>
      &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
    </p>
    <p>
      <b>&#1040;&#1082;&#1082;&#1091;&#1088;&#1072;&#1090;&#1085;&#1086; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;. </b>&#1055;&#1088;&#1086;&#1089;&#1090;&#1086;&#1081; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1082;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100; &#1079;&#1072; &#1089;&#1095;&#1077;&#1090; &#1087;&#1088;&#1077;&#1076;&#1074;&#1072;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; rsync (&#1080;&#1083;&#1080; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;) &#1087;&#1088;&#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1097;&#1077;&#1084; &#1089;&#1077;&#1074;&#1077;&#1088;&#1077;. &#1058;&#1086;&#1075;&#1076;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1086;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; rsync &#1076;&#1086;&#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; (&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093;, &#1087;&#1088;&#1077;&#1076;&#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;, &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1077; &#1084;&#1085;&#1086;&#1075;&#1086;).
