    </p>
    <p>
      <b>&#1057;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1086;&#1074; &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1083;&#1103; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;? </b>&#1042; &#1075;&#1086;&#1088;&#1103;&#1095;&#1091;&#1102; &#1082;&#1086;&#1087;&#1080;&#1102; &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086; &#1087;&#1086;&#1087;&#1072;&#1076;&#1091;&#1090; &#1085;&#1077;&#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;. &#1055;&#1088;&#1080; &#1093;&#1086;&#1083;&#1086;&#1076;&#1085;&#1086;&#1084; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1077; &#1076;&#1083;&#1103; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1099; (&#1089; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1081; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1086;&#1081; &#1090;&#1086;&#1095;&#1082;&#1080;) &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1074; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077;. &#1044;&#1083;&#1103; &#1075;&#1086;&#1088;&#1103;&#1095;&#1077;&#1081; &#1082;&#1086;&#1087;&#1080;&#1080; &#1101;&#1090;&#1086; &#1085;&#1077; &#1090;&#1072;&#1082;: &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; (&#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099;) &#1087;&#1086;&#1089;&#1090;&#1077;&#1087;&#1077;&#1085;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103;, &#1080; &#1079;&#1072; &#1074;&#1088;&#1077;&#1084;&#1103; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1060;&#1057; &#1085;&#1091;&#1078;&#1085;&#1099;&#1081; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1090;&#1077;&#1088;&#1103;&#1085;. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1085;&#1072;&#1076;&#1086; &#1083;&#1080;&#1073;&#1086; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; wal_keep_segments, &#1083;&#1080;&#1073;&#1086; &#1074; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#171;&#1087;&#1077;&#1088;&#1077;&#1093;&#1074;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100;&#187; &#1087;&#1086;&#1090;&#1086;&#1082; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1100; &#1101;&#1090;&#1091; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102;.
    </p>
    <ul>
      <li>
        &#1086;&#1090; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1081; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1086;&#1081; &#1090;&#1086;&#1095;&#1082;&#1080; &#1079;&#1072; &#1074;&#1089;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1060;&#1057;
      </li>
      <li>
        &#1080;&#1084;&#1077;&#1077;&#1090; &#1089;&#1084;&#1099;&#1089;&#1083; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1091;&#1102; &#1090;&#1086;&#1095;&#1082;&#1091; &#1087;&#1077;&#1088;&#1077;&#1076; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084;
      </li>
      <li>
        &#1083;&#1080;&#1073;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; wal_keep_segments &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084;, &#1083;&#1080;&#1073;&#1086; &#1074; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1085;&#1072;&#1076;&#1086; &#1086;&#1090;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1099; &#171;&#1074; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091;&#187;
      </li>
    </ul>
    <p>
      <b>&#1042; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072;&#1093; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1074;&#1089;&#1103; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1072;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103;. </b>&#1042;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1072; &#1089;&#1086;&#1089;&#1090;&#1086;&#1080;&#1090; &#1074; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; wal_level = minimal, &#1095;&#1090;&#1086; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1091;&#1084;&#1077;&#1074;&#1072;&#1077;&#1090; &#1086;&#1087;&#1090;&#1080;&#1084;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102;, &#1089;&#1074;&#1103;&#1079;&#1072;&#1085;&#1085;&#1091;&#1102; &#1089; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1086;&#1084;. &#1056;&#1103;&#1076; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;, &#1087;&#1086;&#1088;&#1086;&#1078;&#1076;&#1072;&#1102;&#1097;&#1080;&#1081; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1086;&#1073;&#1098;&#1077;&#1084; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1081; (create table as select, create index, alter table set tablespace, copy from &#1080; &#1076;&#1088;.), &#1085;&#1077; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103;. &#1042;&#1084;&#1077;&#1089;&#1090;&#1086; &#1101;&#1090;&#1086; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089;&#1088;&#1072;&#1079;&#1091; &#1078;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1076;&#1080;&#1089;&#1082; (fsync), &#1095;&#1090;&#1086; &#1089;&#1072;&#1084;&#1086; &#1087;&#1086; &#1089;&#1077;&#1073;&#1077; &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1076;&#1086;&#1083;&#1075;&#1086;&#1074;&#1077;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; wal_level &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1082;&#1072;&#1082; &#1084;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084; &#1074; archive. &#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
    </p>
    <ul>
      <li>
        &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1074; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083; &#1085;&#1077; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1102;&#1090; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;, &#1080;&#1079;&#1084;&#1077;&#1085;&#1103;&#1102;&#1097;&#1080;&#1077; &#1084;&#1085;&#1086;&#1075;&#1086; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; (create table as select, create index, copy from &#1080; &#1090;. &#1087;.) - &#1076;&#1083;&#1103; &#1085;&#1080;&#1093; &#1076;&#1086;&#1083;&#1075;&#1086;&#1074;&#1077;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; fsync
      </li>
