      <b>&#1053;&#1072;&#1095;&#1072;&#1083;&#1086; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;: pg_start_backup(). </b>&#1069;&#1090;&#1080; &#1078;&#1077; &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; pg_start_backup(), &#1077;&#1089;&#1083;&#1080; &#1093;&#1086;&#1095;&#1077;&#1090;&#1089;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1081; &#1075;&#1080;&#1073;&#1082;&#1086;&#1089;&#1090;&#1080;, &#1095;&#1077;&#1084; &#1076;&#1072;&#1077;&#1090; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072;.
    </p>
    <ul>
      <li>
        &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1091;&#1102; &#1090;&#1086;&#1095;&#1082;&#1091; --checkpoint=fast|spread &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086; &#1080;&#1083;&#1080; &#1084;&#1077;&#1076;&#1083;&#1077;&#1085;&#1085;&#1086;
      </li>
      <li>
        &#1085;&#1072; &#1074;&#1088;&#1077;&#1084;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; full_page_writes (&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1074; WAL &#1087;&#1086;&#1083;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1074;&#1086;&#1084; &#1077;&#1077; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1086;&#1081; &#1090;&#1086;&#1095;&#1082;&#1080;)
      </li>
    </ul>
    <p>
      <b>&#1050;&#1086;&#1087;&#1080;&#1088;&#1091;&#1077;&#1090; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1091;&#1102; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091; &#1074; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1081; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;</b>
    </p>
    <p>
      --format=plain|tar &#1092;&#1072;&#1081;&#1083;&#1099; &#1080; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1080; &#1080;&#1083;&#1080; tar
    </p>
    <p>
      <b>&#1050;&#1086;&#1087;&#1080;&#1088;&#1091;&#1077;&#1090; &#1074; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;/pg_xlog &#1074;&#1089;&#1077; &#1085;&#1091;&#1078;&#1085;&#1099;&#1077; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099; WAL. </b>WAL &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1100; &#1076;&#1074;&#1091;&#1084;&#1103; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1072;&#1084;&#1080; (&#1082;&#1083;&#1102;&#1095; --xlogmethod): &#1083;&#1080;&#1073;&#1086; &#1074; &#1089;&#1072;&#1084;&#1086;&#1084; &#1082;&#1086;&#1085;&#1094;&#1077; (&#1090;&#1086;&#1075;&#1076;&#1072; &#1085;&#1072;&#1076;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; wal_keep_segments &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084;), &#1083;&#1080;&#1073;&#1086; &#1085;&#1077;&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1074; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099;.
    </p>
    <p>
      <font color="#0000c0">--xlog-method=fetch</font>&#160;&#160;&#160;&#160;&#160;&#160;&#1074; &#1089;&#1072;&#1084;&#1086;&#1084; &#1082;&#1086;&#1085;&#1094;&#1077; (wal_keep_segments)
    </p>
    <p>
      <font color="#0000c0">--xlog-method=stream</font>&#160;&#160;&#160;&#1074; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; (&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1083;&#1103; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1072; plain)
    </p>
    <p>
      <b>&#1050;&#1086;&#1085;&#1077;&#1094; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;: pg_stop_backup(). </b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1082;&#1086;&#1087;&#1080;&#1080; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080;&#1085;&#1091;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1085;&#1072; &#1085;&#1086;&#1074;&#1099;&#1081; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090; WAL. &#1069;&#1090;&#1086; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1072;&#1102;&#1097;&#1077;&#1077; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; pg_stop_backup().
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="Настройки" ID="ID_1575055531" CREATED="1529086627530" MODIFIED="1529087907610"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1072;&#1074;&#1072; &#1076;&#1083;&#1103; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;</b>
    </p>
    <p>
      &#1059;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; pg_basebackup &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1083;&#1080;&#1073;&#1086; &#1087;&#1086;&#1076; <b>&#1089;&#1091;&#1087;&#1077;&#1088;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;</b>, &#1083;&#1080;&#1073;&#1086; &#1087;&#1086;&#1076; &#1088;&#1086;&#1083;&#1100;&#1102; &#1089; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1086;&#1084; <b>replication</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;. </b>&#1055;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1085;&#1077; &#1089; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084;&#1080; &#1073;&#1072;&#1079;&#1072;&#1084;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1072; &#1089; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1086;&#1084; &#1074; &#1094;&#1077;&#1083;&#1086;&#1084; (&#1074; &#1090;&#1086;&#1084; &#1095;&#1080;&#1089;&#1083;&#1077; &#1089; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072;&#1084;&#1080; WAL, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1086;&#1090;&#1085;&#1086;&#1089;&#1103;&#1090;&#1089;&#1103; &#1082;&#1086; &#1074;&#1089;&#1077;&#1084;&#1091; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1091;), &#1086;&#1085;&#1072; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1087;&#1086; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084;&#1091; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1101;&#1090;&#1086; &#1073;&#1099;&#1083;&#1086; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1076;&#1074;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;.
    </p>
    <ul>
      <li>
        &#1074; <b>pg_hba.conf</b>&#160;&#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1041;&#1044; <b>replication</b>&#160; &#8212; &#1101;&#1090;&#1086; &#1085;&#1077; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1041;&#1044;, &#1101;&#1090;&#1086; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1086;&#1084; &#1074; &#1094;&#1077;&#1083;&#1086;&#1084;, &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1103; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1099; &#1087;&#1088;&#1077;&#1076;&#1074;&#1072;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; (&#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; all &#1085;&#1077; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086;, replication &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;)
      </li>
      <li>
        &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; <b>max_wal_senders</b>&#160; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1088;&#1072;&#1074;&#1077;&#1085; &#1082;&#1072;&#1082; &#1084;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084; 1 (&#1072; &#1077;&#1089;&#1083;&#1080; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1086;&#1074; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1084;&#1077;&#1090;&#1086;&#1076; stream &#8212; &#1090;&#1086; &#1082;&#1072;&#1082; &#1084;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084; 2). &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1086;&#1085; &#1088;&#1072;&#1074;&#1077;&#1085; &#1085;&#1091;&#1083;&#1102;
      </li>
    </ul>
    <p>
      <b>&#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;</b>
    </p>
    <ul>
      <li>
        &#1088;&#1072;&#1079;&#1074;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1077;&#1084; &#1082;&#1086;&#1087;&#1080;&#1102;
      </li>
      <li>
        &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
