      </li>
      <li>
        &#1085;&#1086; &#1090;&#1086;&#1078;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1087;&#1086;&#1087;&#1072;&#1089;&#1090;&#1100; &#1074; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1091;&#1102; &#1082;&#1086;&#1087;&#1080;&#1102;
      </li>
      <li>
        &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1100;&#1085;&#1099;&#1077; &#1089;&#1089;&#1099;&#1083;&#1082;&#1080; &#1074; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1077; pg_tblspc &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1085;&#1099;&#1084;&#1080;
      </li>
    </ul>
    <p>
      &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; <b>tar</b>. &#1055;&#1088;&#1080; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; tar &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; &#1090;&#1072;&#1082;&#1086;&#1077; &#1058;&#1055; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1084;&#1077;&#1097;&#1077;&#1085;&#1086; &#1074; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; tar&#1092;&#1072;&#1081;&#1083; &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084;, &#1088;&#1072;&#1074;&#1085;&#1099;&#1084; OID &#1090;&#1072;&#1073;&#1083;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1089;&#1090;&#1074;&#1072;.
    </p>
    <ul>
      <li>
        &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; <b>OID.tar</b>&#160; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; &#1090;&#1072;&#1073;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1089;&#1090;&#1074;, <b>base.tar</b>&#160; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1074;&#1089;&#1077; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077;
      </li>
    </ul>
    <p>
      &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; <b>plain</b>
    </p>
    <ul>
      <li>
        &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1089;&#1090;&#1074;&#1072; &#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1074; &#1090;&#1077; &#1078;&#1077; &#1072;&#1073;&#1089;&#1086;&#1083;&#1102;&#1090;&#1085;&#1099;&#1077; &#1087;&#1091;&#1090;&#1080;. &#1045;&#1089;&#1083;&#1080; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; pg_basebackup &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;, &#1101;&#1090;&#1086; &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1090; &#1082; &#1086;&#1096;&#1080;&#1073;&#1082;&#1077; directory &quot;&#8230;&quot; exists but is not empty. &#1055;&#1088;&#1077;&#1076;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1095;&#1090;&#1086; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1075;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
      </li>
      <li>
        &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1090;&#1072;&#1073;&#1083;&#1080;&#1095;&#1085;&#1099;&#1084; &#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1089;&#1090;&#1074;&#1072;&#1084; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1087;&#1091;&#1090;&#1080;, &#1080; &#1086;&#1085;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1088;&#1080; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1080;&#1079; &#1082;&#1086;&#1087;&#1080;&#1080;:<br/><font color="#0000c0">&#160;--tablespace-mapping=&#1089;&#1090;&#1072;&#1088;&#1099;&#1081;_&#1087;&#1091;&#1090;&#1100;=&#1085;&#1086;&#1074;&#1099;&#1081;_&#1087;&#1091;&#1090;&#1100;</font>
      </li>
    </ul>
  </body>
