      </li>
      <li>
        &#1077;&#1089;&#1083;&#1080; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1086; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1086;&#1084; 0, &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; (&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1091;&#1089;&#1090;&#1086;&#1081; &#1092;&#1072;&#1081;&#1083; pg_xlog/archive_status/N.done)
