  <head>
    
  </head>
  <body>
    <p>
      <b>&#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;. </b>&#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1072;&#1088;&#1093;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086;&#1081;, &#1083;&#1080;&#1096;&#1100; &#1073;&#1099; &#1086;&#1085;&#1072; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1072;&#1083;&#1072;&#1089;&#1100; &#1089; &#1085;&#1091;&#1083;&#1077;&#1074;&#1099;&#1084; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1086;&#1084; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1091;&#1089;&#1087;&#1077;&#1093;&#1072;. (&#1057;&#1090;&#1072;&#1090;&#1091;&#1089; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1074;&#1099;&#1074;&#1086;&#1076;&#1072; echo $? &#1087;&#1086;&#1089;&#1083;&#1077; &#1085;&#1077;&#1077;)
    </p>
    <ul>
      <li>
        &#1084;&#1086;&#1078;&#1077;&#1090; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090; &#1074; &#1083;&#1102;&#1073;&#1086;&#1077; &#1091;&#1076;&#1086;&#1073;&#1085;&#1086;&#1077; &#1084;&#1077;&#1089;&#1090;&#1086;
      </li>
      <li>
        &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1086; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1086;&#1084; 0 &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1080; &#1091;&#1089;&#1087;&#1077;&#1093;&#1077; (&#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100;: command; echo $?)
      </li>
      <li>
        &#1085;&#1077; &#1089;&#1090;&#1086;&#1080;&#1090; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100; &#1091;&#1078;&#1077; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099;
      </li>
      <li>
        &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1089;&#1073;&#1086;&#1088; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; logging_collector (&#1089;&#1084;. &#1090;&#1077;&#1084;&#1091; <a href="#ID_86710042">&#1052;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;&#1080;&#1085;&#1075;</a>), &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1074; &#1101;&#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1086;&#1073; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;&#1093; &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1074; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
      </li>
    </ul>
    <p>
      &#1042; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1077; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1099; &#1087;&#1086;&#1076;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080;
    </p>
    <p>
      <b>%p</b>&#160;&#160;&#160;&#160;&#1087;&#1086;&#1083;&#1085;&#1099;&#1081; &#1087;&#1091;&#1090;&#1100; &#1082; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1091; WAL
