    </p>
    <p>
      <font color="#0000c0">my_backup_script.sh &quot;%p&quot; &quot;%f&quot;</font>&#160;&#160;# &#1045;&#1089;&#1083;&#1080; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1091;&#1084;&#1077;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1083;&#1086;&#1078;&#1085;&#1072;&#1103; &#1083;&#1086;&#1075;&#1080;&#1082;&#1072;, &#1090;&#1086; &#1077;&#1077; &#1091;&#1076;&#1086;&#1073;&#1085;&#1086; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1074; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; &#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1080;&#1084;&#1103; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072; &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
