        &#1086;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;
      </li>
      <li>
        &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1084; &#1080;&#1079; $PGDATA &#1074;&#1089;&#1077; (&#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1086;&#1095;&#1080;&#1097;&#1072;&#1077;&#1084; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1089;&#1090;&#1074;), &#1082;&#1088;&#1086;&#1084;&#1077; pg_xlog/ (&#1089; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080; WAL, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1090;&#1072;&#1084; &#1084;&#1086;&#1075;&#1083;&#1080; &#1086;&#1089;&#1090;&#1072;&#1090;&#1100;&#1089;&#1103; &#1077;&#1097;&#1077; &#1085;&#1077; &#1072;&#1088;&#1093;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099;). &#1050;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; pg_xlog &#1080;&#1084;&#1077;&#1077;&#1090; &#1089;&#1084;&#1099;&#1089;&#1083; &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086; &#1085;&#1072; &#1074;&#1089;&#1103;&#1082;&#1080;&#1081; &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;
      </li>
      <li>
        &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084; &#1092;&#1072;&#1081;&#1083;&#1099; &#1080;&#1079; &#1073;&#1072;&#1079;&#1086;&#1074;&#1086;&#1081; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1081; &#1082;&#1086;&#1087;&#1080;&#1080; (&#1082;&#1088;&#1086;&#1084;&#1077; pg_xlog/ &#8212; &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1080; &#1077;&#1089;&#1090;&#1100; &#1074; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1081; &#1082;&#1086;&#1087;&#1080;&#1080;, &#1090;&#1086; &#1074; &#1085;&#1077;&#1084; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1089;&#1090;&#1072;&#1088;&#1099;&#1077; &#1080; &#1091;&#1078;&#1077; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1099;&#1077; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099; WAL)
