  <body>
    <p>
      &#1055;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1084; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090; <b>&#1076;&#1074;&#1072; &#1092;&#1072;&#1081;&#1083;&#1072;. </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1060;&#1072;&#1081;&#1083; &#1084;&#1077;&#1090;&#1082;&#1080; backup_label. </b>&#1054;&#1085; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1073;&#1072;&#1079;&#1086;&#1074;&#1086;&#1081; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1081; &#1082;&#1086;&#1087;&#1080;&#1080; &#1080; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077;, &#1074;&#1088;&#1077;&#1084;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1082;&#1086;&#1087;&#1080;&#1080; &#1080; -&#160;&#160;&#1089;&#1072;&#1084;&#1086;&#1077; &#1074;&#1072;&#1078;&#1085;&#1086;&#1077; - <b>&#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072; WAL</b>, &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1085;&#1072;&#1076;&#1086; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1090;&#1100;
    </p>
    <p>
      &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081; &#1092;&#1072;&#1081;&#1083; recovery.conf. </b>&#1042; &#1084;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1077;, &#1074; &#1092;&#1072;&#1081;&#1083;&#1077; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; restore_command, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091;, &#171;&#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1091;&#1102;&#187; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1077; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; archive_command. &#1054;&#1085;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; &#1074; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080;, &#1080; &#1090;&#1086;&#1078;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1086; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1086;&#1084; 0 &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1080; &#1091;&#1089;&#1087;&#1077;&#1093;&#1077;. &#1069;&#1090;&#1086; &#1086;&#1095;&#1077;&#1085;&#1100; &#1074;&#1072;&#1078;&#1085;&#1086;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1074; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1076;&#1083;&#1103; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1085;&#1077; &#1086;&#1082;&#1072;&#1078;&#1077;&#1090;&#1089;&#1103; &#1074; &#1072;&#1088;&#1093;&#1080;&#1074;&#1077; &#8212; &#1101;&#1090;&#1086; &#1085;&#1077; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;, &#1085;&#1086; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1080;&#1090;&#1100;&#1089;&#1103; &#1089; &#1085;&#1077;&#1085;&#1091;&#1083;&#1077;&#1074;&#1099;&#1084; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1086;&#1084;. &#1042; &#1090;&#1072;&#1082;&#1086;&#1084; &#1084;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1077; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1073;&#1091;&#1076;&#1091;&#1090; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1099; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086; &#1073;&#1083;&#1080;&#1079;&#1082;&#1086; &#1082; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090;&#1091; &#1089;&#1073;&#1086;&#1103;.
    </p>
    <ul>
      <li>
        &#1087;&#1080;&#1096;&#1077;&#1090;&#1089;&#1103; &#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;. &#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1092;&#1072;&#1081;&#1083;&#1072; &#1074; <b>share/recovery.conf.sample</b>&#160; (&#1090;&#1086;&#1095;&#1085;&#1086;&#1077; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072; &#1087;&#1086;&#1076;&#1089;&#1082;&#1072;&#1078;&#1077;&#1090; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; <font color="#0000c0">pg_config --sharedir</font>)
      </li>
      <li>
        restore_command &#8212; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072;, &#171;&#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1072;&#1103;&#187; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1077; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1086; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1086;&#1084; 0 &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1080; &#1091;&#1089;&#1087;&#1077;&#1093;&#1077;<br/><b>&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1099;:</b><br/><font color="#0000c0">cp /&#1072;&#1088;&#1093;&#1080;&#1074;/%f %p</font><br/><font color="#0000c0">gunzip &lt; /&#1072;&#1088;&#1093;&#1080;&#1074;/%f &gt; %p</font>
      </li>
      <li>
        &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1085;&#1072;&#1082;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074;&#1089;&#1077; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099; WAL
      </li>
    </ul>
  </body>
</html></richcontent>
