        &#1045;&#1089;&#1083;&#1080; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1085;&#1072; &#1082;&#1072;&#1082;&#1086;&#1081;-&#1090;&#1086; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1074; &#1087;&#1088;&#1086;&#1096;&#1083;&#1086;&#1084;, &#1085;&#1072;&#1076;&#1086; &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1090;&#1100; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099; WAL &#171;&#1074; &#1087;&#1088;&#1086;&#1096;&#1083;&#1086;&#1081; &#1078;&#1080;&#1079;&#1085;&#1080;&#187; &#1080; &#171;&#1074; &#1101;&#1090;&#1086;&#1081; &#1078;&#1080;&#1079;&#1085;&#1080;&#187;
