<node TEXT="Таблицы" FOLDED="true" POSITION="bottom_or_right" ID="ID_997515904" CREATED="1528441665474" MODIFIED="1737037063553"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1925885652">Работа с таблицами (SQL)</a>&#xa0;&#xa0;<a href="#ID_1498937792">БД</a>&#xa0; <a href="#ID_1617442989"><span style="font-weight: normal;">Данные</span></a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>Таблицы</b>
    </p>
    <p>
      <span style="color: #008000;">\c имя_БД</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Подключиться</span>&#xa0;к БД
    </p>
    <p>
      <span style="color: #008000;">\dt </span>или<span style="color: #008000;">&#xa0;\d&#xa0;</span>&#xa0;# \d - (<span style="font-weight: bold;">display</span>). Таблицы в текущей схеме
    </p>
    <p>
      <span style="color: #008000;">\dt *.*</span>&#xa0;&#xa0;# Таблицы во всех схемах
    </p>
    <p>
      <span style="color: #008000;">\dt public.*</span>&#xa0;&#xa0;# Таблицы в конкретной схеме
    </p>
    <p>
      <span style="color: #008000;">SELECT * FROM pg_catalog.pg_tables;</span><span style="color: #0000c0;">&#xa0; </span># Системные таблицы
    </p>
    <p>
      <span style="color: #008000;">\d &lt;таблица&gt;</span>&#xa0;или <span style="color: #008000;">\d+ &lt;таблица&gt;</span>&#xa0;&#xa0;# Все данные по таблице
    </p>
    <p>
      <span style="color: #008000;">\dT</span>&#xa0;&#xa0;# список всех типов данных
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Отключиться от БД</span>
    </p>
    <p>
      <span style="color: #008000;">\c postgres</span>&#xa0;&#xa0;# Подключение к другой базе данных
    </p>
    <p>
      <span style="color: #008000;">\q</span>&#xa0;&#xa0;# Полностью выйти из интерфейса psql
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Можно использовать регулярные выражения с некоторыми ограничениями</span>
    </p>
    <p>
      <span style="color: #008000;">\dt (public|s).(s|t)</span>
    </p>
    <p>
      <span style="font-family: Monospaced;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;List of relations </span>
    </p>
    <p>
      <span style="font-family: Monospaced;">&#xa0;Schema | Name | Type&#xa0;&#xa0;| Owner </span>
    </p>
    <p>
      <span style="font-family: Monospaced;">--------+------+-------+------- </span>
    </p>
    <p>
      <span style="font-family: Monospaced;">&#xa0;public | s&#xa0;&#xa0;&#xa0;&#xa0;| table | cpn </span>
    </p>
    <p>
      <span style="font-family: Monospaced;">&#xa0;public | t&#xa0;&#xa0;&#xa0;&#xa0;| table | cpn </span>
    </p>
    <p>
      <span style="font-family: Monospaced;">&#xa0;s&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| t&#xa0;&#xa0;&#xa0;&#xa0;| table | cpn </span>
    </p>
  </body>
</html></richcontent>
<node TEXT="Пример 1" ID="ID_1429216869" CREATED="1529096451907" MODIFIED="1729165244118"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1072;</b>
    </p>
    <p>
      1. &#1042; &#1073;&#1072;&#1079;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; DB8 &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; observations &#1076;&#1083;&#1103; &#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072;&#1073;&#1083;&#1102;&#1076;&#1077;&#1085;&#1080;&#1081; &#1079;&#1072; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1086;&#1081;.
    </p>
    <p>
      &#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1103;:
    </p>
    <p>
      &#8211; date_taken &#8212; &#1076;&#1072;&#1090;&#1072; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1081;, &#1085;&#1077; &#1087;&#1091;&#1089;&#1090;&#1086;&#1077;
    </p>
    <p>
      &#8211; temp &#8212; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1072;, &#1086;&#1090; &#8209;60&#176;C &#1076;&#1086; +60&#176;C
    </p>
    <p>
      2. &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1083;&#1100;&#1085;&#1099;&#1093; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081;; &#1091;&#1073;&#1077;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103;, &#1095;&#1090;&#1086; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090;.
    </p>
    <p>
      3. &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; observ_fahrenheit, &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1077; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1091; &#1074; &#1075;&#1088;&#1072;&#1076;&#1091;&#1089;&#1072;&#1093; &#1060;&#1072;&#1088;&#1077;&#1085;&#1075;&#1077;&#1081;&#1090;&#1072; (&#176;F = &#176;C&#8729;9/5 + 32).
    </p>
    <p>
      4. &#1055;&#1088;&#1086;&#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1087;&#1086; &#1076;&#1072;&#1090;&#1077; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1081;.
    </p>
    <p>
      
    </p>
    <p>
      &#1056;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#0000c0"># create database db8; </font>
    </p>
    <p>
      <font color="#0000c0"># \c db8 </font>
    </p>
    <p>
      <font color="#0000c0"># create table observations( </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;date_taken date not null, </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;temp numeric check( temp between -60 and 60 ) </font>
    </p>
    <p>
      <font color="#0000c0">); </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># insert into observations values (current_date, 25), (current_date-1, 22); </font>
    </p>
    <p>
      <font color="#0000c0"># insert into observations values (current_date, 70);</font>
    </p>
    <p>
      -- new row for relation &quot;observations&quot; violates check constraint
    </p>
    <p>
      <font color="#0000c0">&quot;observations_temp_check&quot; </font>
    </p>
    <p>
      <font color="#0000c0"># insert into observations values (null, 20);</font>
    </p>
    <p>
      -- null value in column &quot;date_taken&quot; violates not-null constraint
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># create view observ_fahrenheit as </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;select date_taken, temp as celsius, round(temp*5/9+32) as </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;fahrenheit from observations; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># create index observations_date on observations(date_taken);</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Пример 2" ID="ID_670809878" CREATED="1528451178917" MODIFIED="1729165247712"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      
    </p>
    <p>
      &#1058;&#1040;&#1041;&#1051;&#1048;&#1062;&#1067;, &#1058;&#1048;&#1055;&#1067; &#1048; &#1054;&#1043;&#1056;&#1040;&#1053;&#1048;&#1063;&#1045;&#1053;&#1048;&#1071;
    </p>
    <p>
      ~~~~~~~~~~~~~~~~~~~~~~~~~~~
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1088;&#1080;&#1084;&#1077;&#1088; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1089; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084;&#1080; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1086;&#1074; &#1080; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080; &#1094;&#1077;&#1083;&#1086;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080;:
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; create table people(
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt;&#160;&#160;&#160;id numeric primary key,
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt;&#160;&#160;&#160;name varchar(100) not null,
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt;&#160;&#160;&#160;employed boolean,
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt;&#160;&#160;&#160;constraint uname unique(name)
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; );
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;CREATE TABLE
    </p>
    <p>
      
    </p>
    <p>
      &#1057;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1091;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077; &#1090;&#1080;&#1087;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;
    </p>
    <p>
