  </head>
  <body>
    <p>
      &#1055;&#1054;&#1057;&#1051;&#1045;&#1044;&#1054;&#1042;&#1040;&#1058;&#1045;&#1051;&#1068;&#1053;&#1054;&#1057;&#1058;&#1048;
    </p>
    <p>
      ~~~~~~~~~~~~~~~~~~
    </p>
    <p>
      
    </p>
    <p>
      &#1057;&#1086;&#1079;&#1076;&#1072;&#1076;&#1080;&#1084; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100;:
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; create sequence s start with 2 cache 10;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;CREATE SEQUENCE
    </p>
    <p>
      
    </p>
    <p>
      &#1045;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1076;&#1083;&#1103; &#1075;&#1077;&#1085;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080; &#1091;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1082;&#1083;&#1102;&#1095;&#1072;:
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; insert into people values (nextval('s'), '&#1055;&#1077;&#1090;&#1088;&#1086;&#1074;', false);
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;INSERT 0 1
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;=&gt; select currval('s');
