      <b>&#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;, &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1077; &#1087;&#1088;&#1080; DDL-&#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072;&#1093; </b>(&#1080;&#1079;&#1084;&#1077;&#1085;&#1103;&#1102;&#1097;&#1080;&#1093; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;), &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1087;&#1088;&#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076; create index, alter table, drop type &#1080; &#1090;. &#1087;.
    </p>
    <ul>
      <li>
        &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1084; &#1103;&#1079;&#1099;&#1082;&#1077;, &#1082;&#1088;&#1086;&#1084;&#1077; SQL
