<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>contrib </b>
    </p>
    <p>
      
    </p>
    <p>
      pg_stat_statements - &#1076;&#1077;&#1096;&#1077;&#1074;&#1086; &#1087;&#1080;&#1096;&#1077;&#1090; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1087;&#1088;&#1086; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      pg_buffercache - &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100;, &#1095;&#1090;&#1086; &#1089;&#1077;&#1081;&#1095;&#1072;&#1089; &#1077;&#1089;&#1090;&#1100; &#1074; shared buffers
    </p>
    <p>
      pg_prewarm - &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &quot;&#1087;&#1088;&#1086;&#1075;&#1088;&#1077;&#1090;&#1100;&quot; shared buffers
    </p>
    <p>
      pg_bench - &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; PostgreSQL
    </p>
    <p>
      pg_upgrade - &#1076;&#1083;&#1103; &#1072;&#1087;&#1075;&#1088;&#1077;&#1081;&#1076;&#1072; &#1084;&#1077;&#1078;&#1076;&#1091; &#1084;&#1072;&#1078;&#1086;&#1088;&#1085;&#1099;&#1084;&#1080; (&#1089;&#1090;&#1072;&#1088;&#1096;&#1080;&#1084;&#1080;) &#1074;&#1077;&#1088;&#1089;&#1080;&#1103;&#1084;&#1080; PostgreSQL
    </p>
    <p>
      autoexplain - &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1074; &#1083;&#1086;&#1075;&#1072;&#1093; &#1101;&#1082;&#1089;&#1087;&#1083;&#1077;&#1081;&#1085;&#1099; &#1076;&#1086;&#1083;&#1075;&#1080;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;
    </p>
    <p>
      pg_crypto - &#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1075;&#1088;&#1072;&#1092;&#1080;&#1103;
    </p>
    <p>
      oid2name - &#1044;&#1083;&#1103; &#1089;&#1086;&#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; OID &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; &#1089; &#1080;&#1084;&#1077;&#1085;&#1072;&#1084;&#1080; &#1073;&#1072;&#1079; &#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;
    </p>
