          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b><span style="color: #008000;">WHERE</span></b><span style="color: #008000;">&#xa0;ISBN = '9780992461256'</span>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">db.book.<b>update</b>( </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;{ ISBN: '9780992461256' }, </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;{ $<b>set</b>: { price: 19.99 } } </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">);</span>
          </p>
        </td>
      </tr>
    </table>
    <table border="0" style="width: 80%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>Delete</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b><span style="color: #008000;">DELETE FROM</span></b><span style="color: #008000;">&#xa0;book </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b><span style="color: #008000;">WHERE</span></b><span style="color: #008000;">&#xa0;publisher_id = 'SP001';</span>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">db.book.<b>remove</b>({ </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;&quot;publisher.name&quot;: &quot;SitePoint&quot;</span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">});</span>
          </p>
        </td>
      </tr>
    </table>
    <table border="0" style="width: 80%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>Search</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b><span style="color: #008000;">SELECT</span></b><span style="color: #008000;">&#xa0;title <b>FROM</b>&#xa0;book </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b><span style="color: #008000;">WHERE</span></b><span style="color: #008000;">&#xa0;price &gt; 10</span>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">db.book.<b>find</b>( </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;{ price: { &amp;gt;: 10 } }, </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;{ _id: 0, title: 1 } </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">);</span>
          </p>
        </td>
      </tr>
    </table>
    <table border="0" style="width: 80%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>Count</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b><span style="color: #008000;">SELECT</span></b><span style="color: #008000;">&#xa0;<b>COUNT</b>(1) <b>FROM</b>&#xa0;book </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b><span style="color: #008000;">WHERE</span></b><span style="color: #008000;">&#xa0;publisher_id = 'SP001'</span>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">db.book.<b>count</b>({ </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;&quot;publisher.name&quot;: &quot;SitePoint&quot;</span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">});</span>
          </p>
        </td>
      </tr>
    </table>
    <table border="0" style="width: 80%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>Aggregation</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b><span style="color: #008000;">SELECT</span></b><span style="color: #008000;">&#xa0;format, <b>COUNT</b>(1) <b>AS</b>&#xa0;'total' <b>FROM</b>&#xa0;book </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b><span style="color: #008000;">GROUP BY</span></b><span style="color: #008000;">&#xa0;format;</span>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">db.book.<b>aggregate</b>([ </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;{ $group: </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;{ </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;_id: &quot;<b>$format</b>&quot;, </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;total: { $sum: 1 } </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;} </span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">&#xa0;&#xa0;}</span>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <span style="color: #008000;">]);</span>
          </p>
        </td>
      </tr>
    </table>
  </body>
</html></richcontent>
