<node TEXT="Mongo Shell (mongosh)" ID="ID_883507818" CREATED="1527669793865" MODIFIED="1729515466308"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        поддерживается <a href="#ID_794988334">Javascript</a>
      </li>
      <li>
        при помощи Javascript можно добавлять, удалять записи, выполнять обновления
      </li>
      <li>
        точка с запятой (;) в конце запроса или команды не является обязательной
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">mongosh</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Запустить</span>&#xa0;&#xa0;оболочку. <span style="font-weight: bold;">Выйти</span>: <span style="color: #008000;">exit</span>, <span style="color: #008000;">.exit</span>, Ctrl+D
    </p>
    <p>
      <span style="color: #008000;">help</span>&#xa0;&#xa0;# Справка
    </p>
    <p>
      <span style="color: #008000; font-weight: bold;">show</span><span style="color: #008000;">&#xa0;dbs</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Список&#xa0;доступных БД</span>
    </p>
    <p>
      <span style="color: #008000; font-weight: bold;">use</span><span style="color: #008000;">&#xa0;mydb</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать БД</span>. Создает БД и переходит в нее
    </p>
    <p>
      <span style="color: #008000;">db.dropDatabase()</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Удалить БД</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-weight: bold;">show</span><span style="color: #008000;">&#xa0;collections</span>&#xa0;или <span style="color: #008000; font-weight: bold;">show</span><span style="color: #008000;">&#xa0;tables</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Список коллекций</span>&#xa0;в текущей базе
    </p>
    <p>
      <span style="color: #008000;">db.createCollection(&quot;&lt;коллекция&gt;&quot;)</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать новую коллекцию в БД</span>&#xa0;- с помощью метода <span style="font-weight: bold;">createCollection </span>
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.drop()</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Удалить коллекцию</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.find()</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Список документов</span>&#xa0;в коллекции
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.find</span><span style="color: #008000; font-weight: bold;">One</span><span style="color: #008000;">()</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Один</span>&#xa0;документ
    </p>
    <p>
      <span style="color: #008000; font-family: SansSerif;">db.&lt;коллекция&gt;.find({}, { _id: 0, Поле1: 1, Поле2: 1 })</span><span style="font-family: SansSerif;">&#xa0;&#xa0;# </span><span style="font-family: SansSerif; font-weight: bold;">Выборочное содержимое коллекции. </span><span style="font-family: SansSerif; font-weight: bold; color: #0000c0;">Информативный вывод</span>
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.insertOne({ key: &quot;value&quot; })</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Вставить документы</span>&#xa0;в коллекцию - через <span style="font-weight: bold;">insertOne</span>&#xa0;или <span style="font-weight: bold;">insertMany</span>:&#xa0;
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.updateOne({ критерий }, { $set: { поле: новое_значение } })</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Обновить документ</span>&#xa0;в коллекции по определённому критерию
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.updateMany({ критерий }, { $set: { поле: новое_значение } })</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Обновить несколько документов</span>&#xa0;разом по определённому критерию
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.createIndex({ Поле1: 1 })</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать индекс</span>&#xa0;в коллекции по Полю1
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.getIndexes()</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Индексы</span>&#xa0;коллекции
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.dropIndex(&lt;индекс&gt;)</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Удалить индекс</span>&#xa0;из коллекции
    </p>
  </body>
</html></richcontent>
</node>
