<node TEXT="Пользователи и роли" FOLDED="true" ID="ID_1331110236" CREATED="1527773183943" MODIFIED="1729417300898"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Все пользователи во всех БД</span>
    </p>
    <p>
      <span style="color: #008000;">use admin </span>
    </p>
    <p>
      <span style="color: #008000;">db.system.users.find() </span>
    </p>
    <p>
      <span style="color: #008000;">db.runCommand({ usersInfo: 1, showCredentials: false }) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.adminCommand({ usersInfo: 1, showPrivileges: true, showCredentials: false }) </span>
    </p>
    <p>
      <span style="color: #008000;">db.adminCommand({ usersInfo: 1, showCredentials: false }).users.forEach(printjson) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.getUsers()</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Пользователи конкретной БД</span>. При этом нужно находиться в БД
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.getUser(&quot;username&quot;)</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Информация</span>&#xa0;о пользователе
    </p>
    <p>
      db.runCommand({ connectionStatus: 1 })&#xa0;&#xa0;# <span style="font-weight: bold;">Информация</span>&#xa0;о текущем соединении в т.ч. пользователе
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.createUser({&#xa0;&#xa0;# </span><span style="font-weight: bold;">Создать</span>&#xa0;пользователя
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;user: &quot;username&quot;, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;pwd: &quot;password&quot;, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;roles: [ { role: &quot;readWrite&quot;, db: &quot;databaseName&quot; } ] </span>
    </p>
    <p>
      <span style="color: #008000;">})</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.dropUser(&quot;username&quot;)</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Удалить</span>&#xa0;пользователя
    </p>
  </body>
</html></richcontent>
<node TEXT="Аутентификация" ID="ID_319472799" CREATED="1729415344411" MODIFIED="1729417576366"><richcontent TYPE="NOTE">
<text> &lt;html&gt;
    &lt;body&gt;
    &lt;ul&gt;
      &lt;li&gt;
        изначально после установки &lt;span style=&quot;color: #ff0000;&quot;&gt;пользователей нет&lt;/span&gt;&amp;nbsp;- &lt;span style=&quot;font-weight: bold;&quot;&gt;полный 
        доступ&lt;/span&gt;
      &lt;/li&gt;
    &lt;/ul&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #0000c0;&quot;&gt;vim /etc/mongod.conf&lt;/span&gt;&amp;nbsp;&amp;nbsp;# &lt;span style=&quot;font-weight: bold;&quot;&gt;Включить 
      аутентификацию&lt;/span&gt;
    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;security: &lt;/span&gt;
    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;authorization: &amp;quot;enabled&amp;quot;&lt;/span&gt;&lt;br&gt;
    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #0000c0;&quot;&gt;systemctl restart mongod&lt;/span&gt;&amp;nbsp;&amp;nbsp;#&amp;nbsp;&amp;nbsp;Перезапустить MongoDB
    &lt;/p&gt;
    &lt;p&gt;
      
    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;db.runCommand({ connectionStatus: 1 })&lt;/span&gt;&amp;nbsp;&amp;nbsp;# &lt;span style=&quot;font-weight: bold;&quot;&gt;Текущий 
      статус аутентификации&lt;/span&gt;
    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;db.auth(&amp;quot;username&amp;quot;, &amp;quot;password&amp;quot;)&lt;/span&gt;&amp;nbsp;&amp;nbsp;# 
      &lt;span style=&quot;font-weight: bold;&quot;&gt;Проверка&lt;/span&gt;&amp;nbsp;аутентификации текущего пользователя
    &lt;/p&gt;
    &lt;p&gt;
      
    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;use admin
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000; font-weight: bold;&quot;&gt;db.changeUserPassword&lt;/span&gt;&lt;span style=&quot;color: #008000;&quot;&gt;(&amp;quot;username&amp;quot;, 
      &amp;quot;newPassword&amp;quot;)&lt;/span&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;# &lt;span style=&quot;font-weight: bold;&quot;&gt;Изменить 
      пароль&lt;/span&gt;&amp;nbsp;пользователя
    &lt;/p&gt;
    &lt;p&gt;
      
    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;use admin
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000; font-weight: bold;&quot;&gt;db.updateUser&lt;/span&gt;&lt;span style=&quot;color: #008000;&quot;&gt;(
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;&amp;nbsp;&amp;nbsp;&amp;quot;username&amp;quot;,
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;&amp;nbsp;&amp;nbsp;{
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;pwd: &amp;quot;newPassword&amp;quot;,
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;mechanisms: [&amp;quot;SCRAM-SHA-256&amp;quot;]
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;&amp;nbsp;&amp;nbsp;}
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;)&lt;/span&gt;
    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;font-weight: bold;&quot;&gt;
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000; font-weight: bold;&quot;&gt;db.runCommand&lt;/span&gt;&lt;span style=&quot;color: #008000;&quot;&gt;({
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;&amp;nbsp;&amp;nbsp;updateUser: &amp;quot;yourUsername&amp;quot;,
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;&amp;nbsp;&amp;nbsp;pwd: &amp;quot;newPassword&amp;quot;,
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;&amp;nbsp;&amp;nbsp;mechanisms: [&amp;quot;SCRAM-SHA-256&amp;quot;]
&lt;/span&gt;    &lt;/p&gt;
    &lt;p&gt;
      &lt;span style=&quot;color: #008000;&quot;&gt;})&lt;/span&gt;
    &lt;/p&gt;
  &lt;/body&gt;
&lt;/html&gt;
</text></richcontent>
</node>
<node TEXT="Аутентификация. Админ." POSITION="bottom_or_right" ID="ID_475949291" CREATED="1729343085494" MODIFIED="1729415433427"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Создать нового пользователя с правами администратора в базе данных MongoDB</span>
    </p>
    <p>
      <span style="color: #0000c0;">mongosh</span>
    </p>
    <p>
      <span style="color: #008000;">use admin</span>&#xa0;&#xa0;# Подключиться к базе admin
    </p>
    <p>
      <span style="color: #008000;">db.createUser({user:&quot;Some_Admin_Account&quot;, pwd:passwordPrompt(), roles:[{role:&quot;userAdminAnyDatabase&quot;, db:&quot;admin&quot;}, &quot;readWriteAnyDatabase&quot;]})&#xa0;</span>&#xa0;# Запрос<span style="font-weight: bold;">&#xa0;попросит ввести пароль </span>пользователя
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">user:</span>&#xa0;Имя нового пользователя, в данном случае &quot;Some_Admin_Account&quot;.
      </li>
      <li>
        <span style="font-weight: bold;">pwd:</span>&#xa0;Пароль нового пользователя. Функция passwordPrompt() запрашивает пароль у пользователя, чтобы он мог ввести его без отображения на экране.
      </li>
      <li>
        <span style="font-weight: bold;">roles:</span>&#xa0;Массив ролей, которые назначаются новому пользователю. В данном случае пользователь получает две роли:
      </li>
      <li>
        {role: &quot;<span style="font-weight: bold;">userAdminAnyDatabase</span>&quot;, db: &quot;admin&quot;}: Эта роль дает пользователю возможность создавать и управлять пользователями и ролями во всех базах данных кластера.
      </li>
      <li>
        &quot;<span style="font-weight: bold;">readWriteAnyDatabase</span>&quot;: Эта роль дает пользователю возможность читать и писать данные во всех базах данных кластера.
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">vim /etc/mongod.conf</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Включить аутентификацию</span>
    </p>
    <p>
      <span style="color: #008000;">security: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;authorization: &quot;enabled&quot;</span><br/>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl restart mongod</span>&#xa0;&#xa0;#&#xa0;&#xa0;Перезапустить MongoDB
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Роли" ID="ID_694436594" CREATED="1729414190686" MODIFIED="1729416355337"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #008000;">db.getRoles({ showBuiltinRoles: true })</span>&#xa0;&#xa0;#&#xa0; <span style="font-weight: bold;">Список</span>&#xa0;всех ролей БД
    </p>
    <p>
      <span style="color: #008000;">db.getRole(&quot;roleName&quot;, { showPrivileges: true })</span>&#xa0;&#xa0;&#xa0;# <span style="font-weight: bold;">Информация</span>&#xa0;о роли
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.createRole({</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать</span>&#xa0;роль
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;role: &quot;myCustomRole&quot;, </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;privileges: [ </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;{ resource: { db: &quot;myDB&quot;, collection: &quot;&quot; }, actions: [ &quot;find&quot;, &quot;insert&quot;, &quot;update&quot;, &quot;remove&quot; ] } </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;], </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;roles: [] </span>
    </p>
    <p>
      <span style="color: #008000;">})</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.updateRole(&quot;roleName&quot;, {&#xa0; </span>#&#xa0; <span style="font-weight: bold;">Обновить</span>&#xa0;&#xa0;роль
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;privileges: [ </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;{ resource: { db: &quot;myDB&quot;, collection: &quot;&quot; }, actions: [ &quot;find&quot;, &quot;insert&quot; ] } </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;], </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;roles: [] </span>
    </p>
    <p>
      <span style="color: #008000;">})</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.dropRole(&quot;roleName&quot;)</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Удалить</span>&#xa0;роль
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.grantRolesToUser(&quot;username&quot;, [ &quot;role1&quot;, { role: &quot;role2&quot;, db: &quot;database&quot; } ])</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Предоставить</span>&#xa0;&#xa0;роль пользователю
    </p>
    <p>
      <span style="color: #008000;">db.revokeRolesFromUser(&quot;username&quot;, [ &quot;role1&quot;, { role: &quot;role2&quot;, db: &quot;database&quot; } ])</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Отозвать</span>&#xa0;&#xa0;роль у пользователя
    </p>
    <p>
      <span style="color: #008000;">db.updateUser(&quot;username&quot;, {</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Обновить пользователя</span>&#xa0;(изменение ролей, механизма аутентификации и т.д.)
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;roles: [ { role: &quot;readWrite&quot;, db: &quot;newDatabase&quot; } ], </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;pwd: &quot;newPassword&quot; </span>
    </p>
    <p>
      <span style="color: #008000;">})</span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Управление. БД" POSITION="bottom_or_right" ID="ID_350948076" CREATED="1527575674985" MODIFIED="1729503468216"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <b>создавать БД отдельной командой не нужно</b>, будет создана автоматически при добавлении документа
      </li>
    </ul>
    <p>
      <span style="color: #008000;">show dbs</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Список</span>&#xa0;всех существующих БД
    </p>
    <p>
      <span style="color: #008000;">use db_name</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать</span>&#xa0;/ <span style="font-weight: bold;">Перейти</span>&#xa0;(если БД уже есть) БД
    </p>
    <p>
      <span style="color: #008000;">db</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Имя</span>&#xa0;текущей БД
    </p>
    <p>
      <span style="color: #008000;">db.getName()</span>
    </p>
    <p>
      <span style="color: #008000;">db.dropDatabase()&#xa0;</span>&#xa0;# <span style="font-weight: bold;">Удалить</span>&#xa0;БД. Нужно находиться в удаляемой БД
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Управление. Коллекции" POSITION="bottom_or_right" ID="ID_1462408315" CREATED="1527590766454" MODIFIED="1729595389026"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1789601351">Коллекция</a>
    </p>
    <ul>
      <li>
        <b>создавать коллекции отдельной командой не нужно</b>, будет создана автоматически при добавлении документа
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-weight: bold;">show</span><span style="color: #008000;">&#xa0;collections</span>&#xa0;или <span style="color: #008000; font-weight: bold;">show</span><span style="color: #008000;">&#xa0;tables</span><span style="font-weight: normal;">&#xa0;&#xa0;# </span><span style="font-weight: bold;">Список</span><span style="font-weight: normal;">&#xa0;коллекций&#xa0;в текущей БД</span>
    </p>
    <p>
      <span style="color: #008000;">db.mycollection.find()</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Содержимое коллекции. </span>
    </p>
    <p>
      <span style="color: #008000; font-family: SansSerif;">db.mycollection.find({}, { _id: 0, firstName: 1, lastName: 1, gpa: 1 })</span><span style="font-family: SansSerif;">&#xa0;&#xa0;# </span><span style="font-family: SansSerif; font-weight: bold;">Выборочное содержимое коллекции. </span><span style="font-family: SansSerif; font-weight: bold; color: #0000c0;">Информативный вывод</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">find()</span>&#xa0;- команда для поиска документов в коллекции. Первый аргумент в ней <span style="font-weight: bold;">{ }</span>&#xa0;- фильтр запроса, у нас он пустой, что означает, что будут возвращены все документы. Второй аргумент - критерии отбора данных.
      </li>
      <li>
        <span style="font-weight: bold;">{ _id: 0, firstName: 1, lastName: 1 }</span>&#xa0;- критерии отбора данных. Они определяют, какие поля включить в результирующие документы

        <ul>
          <li>
            <span style="font-weight: normal;">_id: </span><span style="font-weight: bold;">0</span>&#xa0;- исключающий поле _id из результатов. Для исключения других полей их достатночно не влкючать в перечень
          </li>
          <li>
            <span style="font-weight: normal;">firstName: </span><span style="font-weight: bold;">1</span>&#xa0;включает поле firstName, аналогично с lastName: 1
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <span style="color: #008000;">db.createCollection(&quot;mycollection&quot;)</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать</span><span style="font-weight: normal;">&#xa0;новую коллекцию в БД&#xa0;с помощью метода createCollection </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">db.renameCollection(&quot;oldCollection&quot;, &quot;newCollection&quot;)&#xa0;&#xa0;</span><span style="font-weight: normal;"># </span><span style="font-weight: bold;">Переименовать</span><span style="font-weight: normal;">&#xa0;коллекцию</span>
    </p>
    <p>
      <span style="color: #008000; font-weight: normal;">db.oldCollection.renameCollection('newCollection')</span>
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.drop()</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Удалить коллекцию</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Управление. Документы" FOLDED="true" POSITION="bottom_or_right" ID="ID_98036797" CREATED="1527674700235" MODIFIED="1729595413249"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1288546475">Документ</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.find()</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Список</span>&#xa0;документов в коллекции
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.find</span><span style="color: #008000; font-weight: bold;">({gender:’f’})</span>&#xa0;&#xa0;# Список документов <span style="font-weight: bold;">с условиями</span>
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.find</span><span style="color: #008000; font-weight: bold;">One</span><span style="color: #008000;">()</span>&#xa0;&#xa0;# Вывести <span style="font-weight: bold;">один</span>&#xa0;документ
    </p>
    <p>
      <span style="color: #008000; font-family: SansSerif;">db.mycollection.find({}, { _id: 0, firstName: 1, lastName: 1, gpa: 1 })</span><span style="font-family: SansSerif;">&#xa0;&#xa0;# </span><span style="font-family: SansSerif; font-weight: bold;">Выборочное содержимое коллекции. </span><span style="font-family: SansSerif; font-weight: bold; color: #0000c0;">Информативный вывод</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">find()</span>&#xa0;- команда для поиска документов в коллекции. Первый аргумент в ней <span style="font-weight: bold;">{ }</span>&#xa0;- фильтр запроса, у нас он пустой, что означает, что будут возвращены все документы. Второй аргумент - критерии отбора данных.
      </li>
      <li>
        <span style="font-weight: bold;">{ _id: 0, firstName: 1, lastName: 1 }</span>&#xa0;- критерии отбора данных. Они определяют, какие поля включить в результирующие документы

        <ul>
          <li>
            <span style="font-weight: normal;">_id: </span><span style="font-weight: bold;">0</span>&#xa0;- исключающий поле _id из результатов. Для исключения других полей их достатночно не влкючать в перечень
          </li>
          <li>
            <span style="font-weight: normal;">firstName: </span><span style="font-weight: bold;">1</span>&#xa0;включает поле firstName, аналогично с lastName: 1
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.find({}, { _id: 0, ID: 1, Поле1: 1, Поле2: 1 })</span><span style="color: #008000; font-weight: bold;">.sort({ Поле2: 1 })</span><span style="font-weight: bold;">&#xa0;</span>&#xa0;# <span style="font-weight: bold;">Сортировка</span><span style="font-weight: normal;">&#xa0;по Полю2 </span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">.sort({ Поле2: 1 })</span><span style="font-weight: normal;">&#xa0;- будет сортировать в обратном порядке. а -1 - наоборот.</span>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.</span><span style="font-weight: bold; color: #008000;">insertOne</span><span style="color: #008000;">({ document })&#xa0; </span># <span style="font-weight: bold;">Вставить документы</span>
    </p>
    <p>
      <span style="color: #008000; font-weight: bold;">db.faculties.insertMany</span><span style="color: #008000;">([ {ID: 1, Faculty: &quot;Факультет 1&quot;, gpa: 9 },{ ID: 2, Faculty: &quot;Факультет 2&quot;, gpa: 8 } ])</span>
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.deleteMany({})</span>&#xa0;&#xa0;#<span style="font-weight: bold;">&#xa0;&#xa0;Удалить все документы</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="Удаление документа" POSITION="bottom_or_right" ID="ID_73489303" CREATED="1527672280232" MODIFIED="1729596094817"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1399823114"><span style="font-weight: normal;">test (linux)</span></a><span style="font-weight: normal;">&#xa0;</span>
    </p>
    <ul>
      <li>
        delete - удаление одного или нескольких документов из коллекции по определённому критерию
      </li>
      <li>
        drop -&#xa0;&#xa0;удаление всей коллекции
      </li>
    </ul>
    <p>
      <b>Удаление</b>
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.deleteOne({ &lt;фильтр&gt; })&#xa0;</span>&#xa0;# Удалить <span style="font-weight: bold;">первый</span>&#xa0;документ, соответствующий указанному критерию
    </p>
    <p>
      <span style="color: #008000;">db.users.deleteOne({ name: &quot;John Doe&quot; })</span>
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.deleteMany({})</span>&#xa0;&#xa0;#<span style="font-weight: bold;">&#xa0;&#xa0;Удалить все документы</span>
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.deleteMany(&lt;фильтр&gt;)</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Удалить все</span>&#xa0;документы, соответствующие указанному критерию
    </p>
    <p>
      <span style="color: #008000;">db.users.deleteMany({ age: { $lt: 18 } })</span>&#xa0;&#xa0;# Удалить все документы в коллекции users, у которых поле age меньше 18
    </p>
    <p>
      <span style="color: #008000;">db.products.deleteMany({ price: { $gt: 100 } })</span>&#xa0;&#xa0;# Удалить все продукты с ценой больше 100
    </p>
    <ul>
      <li>
        $gt (больше)
      </li>
      <li>
        $lt (меньше)
      </li>
      <li>
        $gte (больше или равно)
      </li>
      <li>
        $lte (меньше или равно)
      </li>
      <li>
        $ne (не равно)
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Обновление (update)" POSITION="bottom_or_right" ID="ID_1176726450" CREATED="1527674731280" MODIFIED="1729593998256"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Обновление данных (массивов и объектов) </b>
    </p>
    <ul>
      <li>
        по умолчанию MongoDB обновляет <b>только один документ</b>
      </li>
      <li>
        update по умолчанию заменяет <b>весь</b>&#xa0;&#xa0;документ
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">db.&lt;коллекция&gt;.update({ filter }, { update })</span>
    </p>
    <p>
      Параметры:
    </p>
    <ul>
      <li>
        filter - фильтр, соответствующий документам, которые нужно обновить
      </li>
      <li>
        update - оператор обновления. Он определяет изменения, которые нужно внести в соответствующие документы
      </li>
    </ul>
    <p>
      Операторы обновления (update):
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">$set</span>&#xa0;- <span style="font-weight: bold;">заменяет</span>&#xa0;существующие значения полей указанными
      </li>
      <li>
        <span style="font-weight: bold;">$unset</span>&#xa0;- удаляет указанные поля из документа
      </li>
      <li>
        <span style="font-weight: bold;">$push</span>&#xa0;- добавляет значения в массив
      </li>
      <li>
        <span style="font-weight: bold;">$pull</span>&#xa0;- удаляет значения из массива.
      </li>
      <li>
        <span style="font-weight: bold;">$inc</span>&#xa0;- <span style="font-weight: bold;">увеличивает</span>&#xa0;значение числового поля на указанное значение
      </li>
      <li>
        <span style="font-weight: bold;">$mul</span>&#xa0;- <span style="font-weight: bold;">умножает</span>&#xa0;значение числового поля на указанное значение
      </li>
    </ul>
    <p>
      <span style="color: #008000;">db.user.</span><span style="color: #008000; font-weight: bold;">updateOne</span><span style="color: #008000;">({ ID: 5 }, { </span><span style="color: #008000; font-weight: bold;">$set:</span><span style="color: #008000;">&#xa0;{ firstName: 'Иван', lastName: 'Иванов' } })</span>&#xa0;&#xa0;&#xa0;# <span style="font-weight: bold;">Обновить один документ</span>. Фильтр по полю ID:5db.students.<span style="color: #008000;">db.user.updateOne({ ID: 5 }, { </span><span style="color: #008000; font-weight: bold;">$inc:</span><span style="color: #008000;">&#xa0;{ gpa: 1.5 } }) </span>&#xa0;# <span style="font-weight: bold;">Увеличить значение на</span>&#xa0;1.5
    </p>
  </body>
</html></richcontent>
</node>
</node>
