<node TEXT="Or и And" ID="ID_1856745928" CREATED="1527680223975" MODIFIED="1527766420609"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <table border="0" style="width: 80%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p>
            <b>Or</b>
          </p>
          <p>
            <font color="#0000c0"><b>db.collection.find({ </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>&#160;&#160;&#160;&#160;$or: [ </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;condition_1, </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;condition_2, </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#8230; </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;condition_n </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>] </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>})</b></font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p>
            <b>And</b>
          </p>
          <p>
            <font color="#0000c0"><b>db.collection.find({ </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>&#160;&#160;&#160;&#160;$and: [ </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;condition_1, </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;condition_2, </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#8230; </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;condition_n </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>] </b></font>
          </p>
          <p>
            <font color="#0000c0"><b>})</b></font>
          </p>
        </td>
      </tr>
    </table>
    <table border="0" style="width: 80%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#0000c0">db.posts.find({$<b>or</b>: [</font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#0000c0">{title: {$regex: /mongo/i}},</font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#0000c0">{title: {$regex: /webgl/i}}]},</font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#0000c0">{title: true})</font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            # &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1103; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1074; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1077; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090;&#1089;&#1103; &#1083;&#1080;&#1073;&#1086; mongo &#1083;&#1080;&#1073;&#1086; webgl
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
