      <font color="#0000c0">db.collection2.find{field: {<b>$exists</b>: true/false}} </font>
    </p>
    <p>
      <font color="#0000c0">db.post.find({comments: {$exist: true}})</font>&#160;&#160;# &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;, &#1080;&#1084;&#1077;&#1102;&#1097;&#1080;&#1077; &#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1080;
    </p>
