<node TEXT="Массив" ID="ID_14255909" CREATED="1527682379132" MODIFIED="1527683449190"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1056;&#1072;&#1073;&#1086;&#1090;&#1072; &#1089; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;&#1084;&#1080; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1080;&#1089;&#1082; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081;</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">db.collection2.find({<b>array_field: {$in, [1,2,3]}</b>}) </font>
    </p>
    <p>
      <font color="#0000c0">db.collection2.find({<b>array_field: {$all, [1,2,3]}</b>}) </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">db.post.find ({}, {tags: true})</font>&#160;&#160;# &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1074;&#1089;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1089; &#1090;&#1077;&#1075;&#1072;&#1084;&#1080;
    </p>
    <p>
      <font color="#0000c0">db.post.find ({tags: game}, {tags: true})</font>&#160;&#160;# &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1074;&#1089;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1089; &#1090;&#1077;&#1075;&#1086;&#1084; 'game'
    </p>
    <ul>
      <li>
        <b>&#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; in</b>&#160;- &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;. &#1045;&#1089;&#1083;&#1080; &#1093;&#1086;&#1090;&#1100; &#1086;&#1076;&#1080;&#1085; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1074; &#1087;&#1086;&#1083;&#1077; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;, &#1090;&#1086; &#1074;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;
      </li>
      <li>
        <b>&#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; all</b>&#160;- &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074; &#1087;&#1086;&#1083;&#1077; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;
      </li>
    </ul>
    <p>
      
