<node TEXT="Курсоры" ID="ID_930290106" CREATED="1527749158303" MODIFIED="1527841817920"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1050;&#1091;&#1088;&#1089;&#1086;&#1088;</b>&#160;- &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; &#1089; &#1084;&#1077;&#1090;&#1086;&#1076;&#1072;&#1084;&#1080; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1073;&#1086;&#1088;&#1072; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">cursor = db.collection.find() </font>
    </p>
    <p>
      <font color="#0000c0">cursor.<b>hasNext</b>()</font>&#160;&#160;#&#160;&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; true \ false &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1090;&#1086;&#1075;&#1086; &#1077;&#1089;&#1090;&#1100; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1072;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1080;&#1083;&#1080; &#1085;&#1077;&#1090;
    </p>
    <p>
      <font color="#0000c0">cursor.<b>next</b>()</font>&#160;&#160;# &#1055;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076; &#1082; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1081; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080;. &#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1048;&#1090;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;, &#1087;&#1077;&#1088;&#1077;&#1073;&#1080;&#1088;&#1072;&#1102;&#1097;&#1080;&#1081; &#1074;&#1089;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1087;&#1086;&#1082;&#1072; &#1091; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1072; &#1084;&#1077;&#1090;&#1086;&#1076; hasNext &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; true</b>
    </p>
    <p>
      <font color="#0000c0">while (cursor.hasNext()) { </font>
    </p>
    <p>
      <font color="#0000c0">printjson(cursor.next()) </font>
    </p>
    <p>
      <font color="#0000c0">}</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1077;&#1090;&#1086;&#1076; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1072; sort. </b>&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;. &#1052;&#1077;&#1085;&#1103;&#1077;&#1090; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1085;&#1086;&#1089;&#1090;&#1100; &#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1087;&#1086; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1091;. &#1042; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;, &#1075;&#1076;&#1077; &#1082;&#1083;&#1102;&#1095; - &#1101;&#1090;&#1086; &#1087;&#1086;&#1083;&#1077;, &#1072; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; - (1) - &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;, (-1) - &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1072;&#1103; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;
    </p>
    <p>
      <font color="#0000c0">db.collection.find().<b>sort</b>(order) </font>
    </p>
    <p>
      <font color="#0000c0">db.posts.find({}, {title: true}).sort({title: 1})</font>&#160;&#160;# &#1042;&#1089;&#1077; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1080; &#1073;&#1083;&#1086;&#1075;&#1072; &#1074; &#1072;&#1083;&#1092;&#1072;&#1074;&#1080;&#1090;&#1085;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1077;&#1090;&#1086;&#1076; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1072; skip</b>. &#1055;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;-&#1074;&#1086; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; &#1080; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077;
    </p>
    <p>
      <font color="#0000c0">db.collection.find().<b>skip</b>(count) </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1077;&#1090;&#1086;&#1076; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1072; limit</b>. &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1082;&#1086;&#1083;-&#1074;&#1086; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; &#1074; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1077;.
    </p>
    <p>
      <font color="#0000c0">db.collection.find().<b>limit</b>(count)</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">db.collection.<b>find</b>().<b>sort</b>(order).<b>skip</b>(count).<b>limit</b>(count)</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Агрегация данных" FOLDED="true" ID="ID_1222509667" CREATED="1527759772913" MODIFIED="1729599901866"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Агрегационный пайплайн</span>&#xa0;- механизм для выполнения операций агрегации данных (например, суммирования, сортировки, группировки и других) в коллекциях MongoDB. С помощью агрегационного пайплайа можно:
    </p>
    <ul>
      <li>
        фильтровать; группировать; преобразовывать; сортировать; уникализировать;
      </li>
      <li>
        вычислять агрегатные функции, например, среднее значение, сумму, минимум, максимум и так далее.
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Операторы</span>
    </p>
    <ul>
      <li>
        $match - фильтрует документы в потоке по заданному критерию
      </li>
      <li>
        $group -&#xa0;группирует документы по определённому полю и применяет агрегационные функции к данным каждой группы
      </li>
      <li>
        $project - преобразует каждый документ в потоке (добавляет илу удаляет поля из документа)
      </li>
      <li>
        $sort - сортирует документы в результате агрегации по заданному полю
      </li>
      <li>
        $facet - позволяет выполнять несколько агрегационных операций параллельно и объединять их результаты
      </li>
      <li>
        $unwind - разбивает массивные поля документа на документы поменьше, что упрощает их обработку в пайплайне
      </li>
      <li>
        $lookup - выполняет операцию объединения (join) с другой коллекцией MongoDB
      </li>
      <li>
        $addFields - добавляет в документе новое поле или обновляет существующее
      </li>
      <li>
        $redact - применяет правила доступа к данным на уровне документов
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>Агрегация в MongoDB </b>
    </p>
    <ul>
      <li>
        в виде потокового преобразования данных
      </li>
      <li>
        Поэтапно
      </li>
      <li>
        Изменение данных на каждом этапе
      </li>
      <li>
        агрегация не одним большим запросом (как в SQL), а делится на <b>несколько малых стадий</b>
      </li>
    </ul>
    <p>
      <b>Поток стадий.</b>&#xa0;&#xa0;Метод aggregation в качестве параметра принимает массив из стадий.
    </p>
    <p>
      <span style="color: #0000c0;">db.collection.aggregation([ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;{stage1: options1}, </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;{stage2: options2}, </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;... </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;{stageN: optionsN}, </span>
    </p>
    <p>
      <span style="color: #0000c0;">])</span>
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
