<node TEXT="для множеств" ID="ID_342487340" CREATED="1527762744321" MODIFIED="1527841973943"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1054;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">{ <b>$setEquals:</b>&#160;[ &lt;&#1052;&#1072;&#1089;&#1089;&#1080;&#1074;1&gt;, &lt;&#1052;&#1072;&#1089;&#1089;&#1080;&#1074;2&gt;, ... ] }</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>$setEquals</b>&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; true &#1077;&#1089;&#1083;&#1080; &#1074;&#1089;&#1077; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1099; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086; &#1086;&#1090; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1072; &#1080; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1077;&#1085;&#1080;&#1081;. &#1048; false &#1074; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1083;&#1091;&#1095;&#1072;&#1103;&#1093;
    </p>
    <p>
      <b>$setIntersection</b>&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1077;&#1089;&#1090;&#1100; &#1074; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1080;&#1079; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;&#1093;
    </p>
    <p>
      <b>$setUnion</b>&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1077;&#1089;&#1090;&#1100; &#1093;&#1086;&#1090;&#1103; &#1073;&#1099; &#1074; &#1086;&#1076;&#1085;&#1086;&#1084; &#1080;&#1079; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;.
    </p>
    <p>
      <b>$setDifference</b>&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1077; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1103;&#1102;&#1090;&#1089;&#1103; &#1074; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;&#1093;.
    </p>
    <p>
      <b>$setIsSubset</b>&#160;&#1055;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1076;&#1074;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072; &#1080; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; true &#1077;&#1089;&#1083;&#1080; &#1074;&#1089;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; &#1087;&#1077;&#1088;&#1074;&#1086;&#1075;&#1086; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;, &#1077;&#1089;&#1090;&#1100; &#1074;&#1086; &#1074;&#1090;&#1086;&#1088;&#1086;&#1084; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1077;.
    </p>
    <p>
      <b>$anyElementTrue</b>&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; true &#1077;&#1089;&#1083;&#1080; &#1093;&#1086;&#1090;&#1103;-&#1073;&#1099; &#1086;&#1076;&#1080;&#1085; &#1080;&#1079; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; == true
    </p>
    <p>
      <b>$allElementsTrue</b>&#160;&#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; true &#1077;&#1089;&#1083;&#1080; &#1074;&#1089;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; == true
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Пример" ID="ID_770047340" CREATED="1729600161216" MODIFIED="1729600235125"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Представим, что у нас есть две коллекции: users и posts. В первой — информация о пользователях, включая их имя, возраст и ID, а во второй — посты, которые пользователи опубликовали, включая сами тексты, ID пользователей, дату публикации и количество лайков.
    </p>
    <p>
      Мы хотим выбрать все посты, которые написаны пользователями старше 30 лет и у которых больше cотни лайков. Результат запроса нужно записать в новую коллекцию popular_posts.
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      db.users.aggregate([
    </p>
    <p>
      &#xa0;&#xa0;{
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;$lookup: {
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;from: &quot;posts&quot;,
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;localField: &quot;userId&quot;,
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;foreignField: &quot;userId&quot;,
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;as: &quot;userPosts&quot;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;}
    </p>
    <p>
      &#xa0;&#xa0;},
    </p>
    <p>
      &#xa0;&#xa0;{
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;$match: {
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;$and: [
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;{ age: { $gt: 30 } },
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;{ &quot;userPosts.likes&quot;: { $gt: 100 } }
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;]
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;}
    </p>
    <p>
      &#xa0;&#xa0;},
    </p>
    <p>
      &#xa0;&#xa0;{
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;$out: &quot;popular_posts&quot;
    </p>
    <p>
      &#xa0;&#xa0;}
    </p>
    <p>
      ])
    </p>
    <p>
      
    </p>
    <p>
      Мы используем $lookup, чтобы объединить коллекции users и posts по полю userId. Затем с помощью $match фильтруем пользователей старше 30 лет и посты, у которых больше ста лайков. Наконец, с помощью $out результаты агрегации записываются в новую коллекцию popular_posts.
    </p>
    <p>
      В итоге мы создали новую коллекцию, куда вошли только те посты, которые написаны пользователями старше 30 лет и у которых больше сотни лайков.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Пример" ID="ID_1842414866" CREATED="1729600166262" MODIFIED="1729600272248"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      У нас есть две коллекции: authors и books. Первая&#xa0;&#xa0;содержит информацию об авторах книг, включая их имя, страну и возраст, а вторая — о самих книгах, включая их название, жанр и ID автора.
    </p>
    <p>
      Наша задача — соединить данные из обеих коллекций, выбрать книги, написанные авторами старше 40 лет в жанре фэнтези, и создать новую коллекцию fantasy_books_over_40.
    </p>
    <p>
      
    </p>
    <p>
      db.authors.aggregate([
    </p>
    <p>
      &#xa0;&#xa0;{
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;$lookup: {
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;from: &quot;books&quot;,
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;localField: &quot;_id&quot;,
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;foreignField: &quot;authorId&quot;,
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;as: &quot;author_books&quot;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;}
    </p>
    <p>
      &#xa0;&#xa0;},
    </p>
    <p>
      &#xa0;&#xa0;{
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;$unwind: &quot;$author_books&quot;
    </p>
    <p>
      &#xa0;&#xa0;},
    </p>
    <p>
      &#xa0;&#xa0;{
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;$addFields: {
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;author_age: {
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;$subtract: [2022, &quot;$age&quot;]
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;}
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;}
    </p>
    <p>
      &#xa0;&#xa0;},
    </p>
    <p>
      &#xa0;&#xa0;{
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;$facet: {
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;fantasy_books: [
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;{
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;$match: {
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&quot;author_age&quot;: { $gt: 40 },
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&quot;author_books.genre&quot;: &quot;fantasy&quot;
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;}
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;}
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;]
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;}
    </p>
    <p>
      &#xa0;&#xa0;},
    </p>
    <p>
      &#xa0;&#xa0;{
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;$unwind: &quot;$fantasy_books&quot;
    </p>
    <p>
      &#xa0;&#xa0;},
    </p>
    <p>
      &#xa0;&#xa0;{
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;$out: &quot;fantasy_books_over_40&quot;
    </p>
    <p>
      &#xa0;&#xa0;}
    </p>
    <p>
      ])
    </p>
    <p>
      
    </p>
    <p>
      Здесь мы используем оператор $lookup, чтобы объединить данные из коллекций books и&#xa0;&#xa0;authors на основе совпадения ID автора. Дальше применяем оператор $unwind для разворачивания массива author_books, а также $addFields, чтобы вычислить возраст автора.
    </p>
    <p>
      Затем используем $facet для несколько этапов агрегации. Мы выбираем книги, написанные в жанре фэнтези авторами старше 40 лет, после чего результат записывается в новую коллекцию fantasy_books_over_40.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Пример" ID="ID_784617257" CREATED="1729600170174" MODIFIED="1729600171796"/>
<node TEXT="Пример" POSITION="bottom_or_right" ID="ID_1107610778" CREATED="1729424394558" MODIFIED="1729601347141"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_354590035">Валидационная схема JSON</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">use </span><span style="color: #008000; font-weight: bold;">yp_db</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать Б</span>Д
    </p>
    <p>
      <span style="color: #008000; font-weight: bold;">db.createCollection</span><span style="color: #008000; font-weight: normal;">('students', {validator: {$jsonSchema: {bsonType: 'object',required: ['ID', 'firstName', 'lastName', 'age', 'gpa'],properties: {ID: { bsonType: 'number' },firstName: { bsonType: 'string' },lastName: { bsonType: 'string' },age: { bsonType: 'number' },gpa: { bsonType: 'number' }}}}});</span><span style="color: #008000;">&#xa0;&#xa0;&#xa0;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Добавить коллекции</span>
    </p>
    <p>
      <span style="color: #008000; font-weight: bold;">db.createCollection</span><span style="color: #008000; font-weight: normal;">('faculties', {validator: {$jsonSchema: {bsonType: 'object',required: ['ID', 'Faculty', 'gpa'],properties: {ID: { bsonType: 'number' },Faculty: { bsonType: 'string' },gpa: { bsonType: 'number' }}}}});</span>
    </p>
    <p>
      <span style="font-weight: bold;">db.createCollection('students')</span>&#xa0;- создаёт новую коллекцию с именем students в текущей БД
    </p>
    <p>
      <span style="font-weight: bold;">{validator: {$jsonSchema: ...}}</span>&#xa0;- определяет валидационную схему JSON для коллекции students. Она указана в объекте $jsonSchema
    </p>
    <p>
      <span style="font-weight: bold;">{bsonType: 'object', required: ['ID', 'firstName', 'lastName', 'age', 'gpa'], properties: {...}}</span>&#xa0;- сама валидационная схема JSON, определяющая:
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">bsonType: 'object'</span>&#xa0;- указывает, что документ должен быть объектом
      </li>
      <li>
        <span style="font-weight: bold;">required: ['ID', 'firstName', 'lastName', 'age', 'gpa']</span>&#xa0;- указывает, что поля ID, firstName, lastName, age и gpa обязательны для каждого документа в коллекции
      </li>
      <li>
        <span style="font-weight: bold;">properties</span>&#xa0;- определяет типы данных для каждого из обязательных полей

        <ul>
          <li>
            ID: должно быть числом (bsonType: 'number')
          </li>
          <li>
            firstName: должно быть строкой (bsonType: 'string')
          </li>
          <li>
            lastName: должно быть строкой (bsonType: 'string')
          </li>
          <li>
            age: должно быть числом (bsonType: 'number')
          </li>
          <li>
            gpa: должно быть числом (bsonType: 'number')
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <span style="color: #008000; font-weight: bold;">db.faculties.insertMany</span><span style="color: #008000;">([ {ID: 1, Faculty: &quot;Факультет 1&quot;, gpa: 9 },{ ID: 2, Faculty: &quot;Факультет 2&quot;, gpa: 8 } ])</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Вставить документы</span>
    </p>
    <p>
      <span style="color: #008000; font-weight: bold;">db.students.insertMany</span><span style="color: #008000;">([ { ID: 1, firstName: 'Ivan', lastName: 'Ivanov', age: 35, gpa: 7.8 }, { ID: 2, firstName: 'Aleksandr', lastName: 'Aleksandrov', age: 26, gpa: 6.8 }, ]) </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">db.students.find({}, { _id: 0, firstName: 1, lastName: 1, gpa: 1 })&#xa0;</span>&#xa0;# Список документов в коллекции
    </p>
    <p>
      <span style="color: #008000;">db.students.find({}, { _id: 0, ID: 1, firstName: 1, lastName: 1, gpa: 1 }).pretty({ full: true, shell: true, query: false }).sort({ gpa: 1 })</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Сортировка по gpa </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">db.students.createIndex({ firstName: 1 })</span><span style="font-weight: normal;">&#xa0;&#xa0;# Создать </span><span style="font-weight: bold;">индекс</span><span style="font-weight: normal;">&#xa0;&#xa0;по полю firstName </span>
    </p>
    <p>
      <span style="font-weight: bold; color: #008000;">db.students.updateOne</span><span style="font-weight: normal; color: #008000;">({ ID: 5 }, { </span><span style="font-weight: bold; color: #008000;">$set:</span><span style="font-weight: normal; color: #008000;">&#xa0;{ firstName: 'Иван', lastName: 'Иванов' } })</span><span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;# </span><span style="font-weight: bold;">Изменить</span><span style="font-weight: normal;">&#xa0;данные </span>
    </p>
    <p>
      <span style="font-weight: bold; color: #008000;">db.students.updateOne</span><span style="font-weight: normal; color: #008000;">({ ID: 10 }, { </span><span style="font-weight: bold; color: #008000;">$inc:</span><span style="font-weight: normal; color: #008000;">&#xa0;{ gpa: 1.5 } })</span><span style="font-weight: normal;">&#xa0;&#xa0;# </span><span style="font-weight: bold;">Добавить</span><span style="font-weight: normal;">&#xa0;1.5 балла к текущему значению </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal;">У нас есть пять факультетов и десять студентов. Создадим новую коллекцию Score и запишем в неё, на какой курс поступили студенты при условии, что основа поступления — конкурсная. Всего же на каждом факультете по два места. </span>
    </p>
    <p>
      <span style="font-weight: normal;">Создаём коллекцию Score: </span>
    </p>
    <p>
      <span style="font-weight: normal;">db.createCollection(&quot;Score&quot;); </span>
    </p>
    <p>
      <span style="font-weight: normal;">db.students.find().sort({ gpa: -1 }).forEach(student =&gt; { </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;let availableFaculty = db.faculties.findOne({ studentCount: { $lt: 2 }, gpa: { $lte: student.gpa }, &quot;admittedStudents&quot;: { $nin: [student.lastName] } }); </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;if (availableFaculty) { </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;db.faculties.updateOne({ _id: availableFaculty._id }, { </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;$inc: { studentCount: 1 }, </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;$push: { admittedStudents: student.lastName } </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;}); </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;db.Score.insertOne({ </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&quot;lastName&quot;: student.lastName, </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&quot;gpa&quot;: student.gpa, </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&quot;faculty&quot;: availableFaculty.Faculty </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;}); </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;} else { </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;print(`Студент ${student.lastName} не был зачислен ни на один факультет.`); </span>
    </p>
    <p>
      <span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;} </span>
    </p>
    <p>
      <span style="font-weight: normal;">}); </span>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        <span style="font-weight: normal;">db.students.find().sort({ gpa: -1 }).forEach(student =&gt; { — так мы ищем всех студентов в коллекции students и сортируем их по убыванию среднего балла (GPA), выполняя для каждого следующий код. </span>
      </li>
      <li>
        <span style="font-weight: normal;">let availableFaculty = db.faculties.findOne({ studentCount: { $lt: 2 }, gpa: { $lte: student.gpa }, &quot;admittedStudents&quot;: { $nin: [student.lastName] } }); — теперь ищем факультет, который удовлетворяет нашим условиям:</span><br/><span style="font-weight: normal;">- количество студентов на факультете меньше двух;</span><br/><span style="font-weight: normal;">- средний балл GPA на факультете не превышает GPA текущего студента;</span><br/><span style="font-weight: normal;">- текущий студент ещё не зачислен на этот факультет. </span>
      </li>
      <li>
        <span style="font-weight: normal;">if (availableFaculty) { — если нашли подходящий факультет для студента, выполняем следующий код. </span>
      </li>
      <li>
        <span style="font-weight: normal;">db.faculties.updateOne({ _id: availableFaculty._id }, { $inc: { studentCount: 1 }, $push: { admittedStudents: student.lastName } }); — так увеличиваем количество студентов на факультете на одного и добавляем фамилию текущего студента в список зачисленных. </span>
      </li>
      <li>
        <span style="font-weight: normal;">db.Score.insertOne({ &quot;lastName&quot;: student.lastName, &quot;gpa&quot;: student.gpa, &quot;faculty&quot;: availableFaculty.Faculty }); — записываем информацию о студенте (фамилию, средний балл, факультет) в коллекцию Score. </span>
      </li>
      <li>
        <span style="font-weight: normal;">else { print(Студент ${student.lastName} не был зачислен ни на один факультет.); } — если не удалось найти подходящий факультет для студента, выводим сообщение о том, что студента никуда не зачислили.</span>
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
