    </p>
    <p>
      &#1058;&#1086;&#1078;&#1077; &#1095;&#1090;&#1086; &#1080; $in &#1085;&#1086; &#1085;&#1072;&#1086;&#1073;&#1086;&#1088;&#1086;&#1090;, &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1082;&#1072;&#1082;&#1086;&#1077;-&#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090;
    </p>
    <p>
      <b>$or</b>&#160;- &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; &#1080;&#1083;&#1080;. &#1050;&#1083;&#1072;&#1089;&#1089;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; &#1080;&#1083;&#1080;, &#1073;&#1077;&#1088;&#1077;&#1090; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1080; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090; &#1095;&#1090;&#1086;
    </p>
    <p>
      &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1102; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1093;&#1086;&#1090;&#1103; &#1073;&#1099; &#1086;&#1076;&#1085;&#1086; &#1080;&#1079; &#1085;&#1080;&#1093;
    </p>
    <p>
      <b>$and</b>&#160;- &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; &quot;&#1080;&quot;. &#1054;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; &#1080; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1074;&#1089;&#1077;&#1093; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1074;
    </p>
    <p>
      &#1080;&#1089;&#1082;&#1086;&#1084;&#1099;&#1093; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;&#1093;.
    </p>
    <p>
      <b>$not</b>&#160;- &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; &#1086;&#1090;&#1088;&#1080;&#1094;&#1072;&#1085;&#1080;&#1103;. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090; &#1095;&#1090;&#1086;&#1073;&#1099; &#1074; &#1074;&#1099;&#1073;&#1086;&#1088;&#1082;&#1077; &#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1093;
    </p>
    <p>
      &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1102;
    </p>
    <p>
      <b>$nor</b>&#160;- &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; &#1085;&#1077; &#1080;&#1083;&#1080;.
    </p>
    <p>
      <b>$exists</b>&#160;- &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1087;&#1086;&#1083;&#1103; &#1085;&#1072; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;. $exists &#1080;&#1079;&#1074;&#1083;&#1077;&#1082;&#1072;&#1077;&#1090; &#1090;&#1077; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1082;&#1083;&#1102;&#1095; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1080;&#1083;&#1080; &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090;
    </p>
    <p>
      <b>$mod</b>&#160;&#1054;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; $mod &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1074;&#1099;&#1073;&#1086;&#1088;&#1082;&#1080; &#1087;&#1086;&#1083;&#1077;&#1081;, &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1076;&#1077;&#1083;&#1103;&#1090;&#1089;&#1103; &#1085;&#1072; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090; &#1080; &#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1082; &#1086;&#1090; &#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; (qty % 5 = 0)
    </p>
    <p>
      <b>$all</b>&#160;- &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1077; &#1074;&#1089;&#1077;&#1084;. &#1044;&#1077;&#1083;&#1072;&#1077;&#1090; &#1074;&#1099;&#1073;&#1086;&#1088;&#1082;&#1091; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1095;&#1077;&#1084; &#1087;&#1086; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1091; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;
    </p>
    <p>
      <b>$elemMatch</b>&#160;&#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1088;&#1072;&#1074;&#1085;&#1080;&#1090;&#1100; &#1076;&#1074;&#1072; &#1080; &#1073;&#1086;&#1083;&#1077;&#1077; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1086;&#1074;, &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1072;&#1097;&#1080;&#1093; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1087;&#1086;&#1076;&#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1091;. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1074; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1077; &#1077;&#1089;&#1090;&#1100; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1087;&#1086;&#1076;&#1087;&#1072;&#1076;&#1072;&#1102;&#1097;&#1080;&#1081; &#1087;&#1086;&#1076; &#1074;&#1089;&#1077; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103;
    </p>
    <p>
      <b>$size</b>&#160;- &#1080;&#1097;&#1077;&#1090; &#1087;&#1086; &#1076;&#1083;&#1080;&#1085;&#1077; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;. &#1054;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; $size &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072; &#1088;&#1072;&#1074;&#1085;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1102; $size
    </p>
    <p>
      <b>$</b>&#160;- &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;. $ &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1089;&#1083;&#1091;&#1095;&#1072;&#1103;&#1093;. &#1050;&#1086;&#1075;&#1076;&#1072; &#1084;&#1099; &#1085;&#1077; &#1079;&#1085;&#1072;&#1077;&#1084; &#1087;&#1086;&#1076; &#1082;&#1072;&#1082;&#1080;&#1084;
    </p>
    <p>
      &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1086;&#1084; &#1083;&#1077;&#1078;&#1080;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1077; &#1085;&#1086; &#1093;&#1086;&#1090;&#1080;&#1084; &#1077;&#1075;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1090;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &quot;&#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&quot; &#1048; &#1084;&#1099; &#1093;&#1086;&#1090;&#1080;&#1084;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072; &#1087;&#1086; &#1085;&#1080;&#1084; &#1074;&#1099;&#1074;&#1077;&#1083;&#1086;&#1089;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1085;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;, &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1091;, &#1072; &#1085;&#1077; &#1074;&#1077;&#1089;&#1100; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;, &#1085;&#1086; &#1079;&#1072;&#1088;&#1072;&#1085;&#1077;&#1077; &#1084;&#1099; &#1085;&#1077; &#1079;&#1085;&#1072;&#1077;&#1084; &#1082;&#1072;&#1082;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1072;&#1084; &#1089;&#1090;&#1086;&#1080;&#1090;
    </p>
    <p>
      <b>$slice</b>&#160;- &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;. $slice &#8212; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1093;&#1088;&#1072;&#1085;&#1103;&#1097;&#1080;&#1093;&#1089;&#1103; &#1074; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1077;.
    </p>
