    <p>
      <b>&#160;</b>- &#1087;&#1077;&#1088;&#1077;&#1073;&#1086;&#1088; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1081;, &#1087;&#1077;&#1088;&#1077;&#1093;&#1074;&#1072;&#1090; &#1093;&#1077;&#1085;&#1076;&#1096;&#1077;&#1081;&#1082;&#1072; airodump &#1080;&#1083;&#1080; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088; &#1087;&#1086; eapol &#1074; wireshark-&#1077;. &#1042; &#1083;&#1102;&#1073;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1090;&#1077; &#1085;&#1072; &#1074;&#1088;&#1077;&#1084;&#1103; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1074; &#1093;&#1077;&#1085;&#1076;&#1096;&#1077;&#1081;&#1082;&#1077;, &#1086;&#1085;&#1086; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1086;&#1095;&#1077;&#1085;&#1100; &#1073;&#1083;&#1080;&#1079;&#1082;&#1080;&#1084;, &#1080;&#1085;&#1072;&#1095;&#1077; &#1077;&#1089;&#1083;&#1080; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1073;&#1091;&#1076;&#1091;&#1090; &#1080;&#1079; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1093;&#1077;&#1085;&#1076;&#1096;&#1077;&#1081;&#1082;&#1086;&#1074;, &#1074;&#1099; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1085;&#1077; &#1087;&#1086;&#1076;&#1073;&#1077;&#1088;&#1077;&#1090;&#1077;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1079;&#1072;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; &#1087;&#1077;&#1088;&#1077;&#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;&#1089;&#1103;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; deauth &#1095;&#1077;&#1088;&#1077;&#1079; aireplay
    </p>
    <p>
      &#1050;&#1088;&#1086;&#1084;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086;, &#1077;&#1089;&#1090;&#1100; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1075;&#1080; &#1085;&#1072; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1091;&#1103;&#1079;&#1074;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080;: &#1076;&#1083;&#1103; wps, &#1080; &#1090;&#1076;. &#1053;&#1086; &#1085;&#1072; &#1074;&#1087;&#1089; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1090;&#1086;&#1103;&#1090;&#1100; &#1088;&#1077;&#1081;&#1090;&#1083;&#1080;&#1084;&#1080;&#1090; &#1085;&#1072; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      &#1074; &#1082;&#1072;&#1082;&#1080;&#1093;-&#1090;&#1086; &#1074;&#1077;&#1088;&#1089;&#1080;&#1103;&#1093; &#1072;&#1080;&#1088;&#1082;&#1088;&#1077;&#1082;&#1072; airodump &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1083; &#1093;&#1077;&#1085;&#1076;&#1096;&#1077;&#1081;&#1082; &#1085;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;, &#1090;&#1077; &#1087;&#1086; &#1085;&#1077;&#1084;&#1091; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1073;&#1099;&#1083;&#1086; &#1087;&#1086;&#1076;&#1088;&#1073;&#1088;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;; &#1085;&#1077; &#1087;&#1086;&#1084;&#1085;&#1102; &#1074; &#1095;&#1077;&#1084; &#1090;&#1072;&#1084; &#1073;&#1099;&#1083;&#1086; &#1076;&#1077;&#1083;&#1086;, &#1085;&#1086; &#1090;&#1086;&#1075;&#1076;&#1072; &#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1084; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1086;&#1084; &#1073;&#1099;&#1083; &#1074;&#1072;&#1077;&#1088;&#1096;&#1072;&#1088;&#1082;)
