    </p>
    <p>
      <font color="#008000">action = iptables-allports[name=PBX-GUI, port=http, protocol=tcp] </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;sendmaiI-whois[name=PBX-GUI, dest=log@ya.ru, sender=fail2ban@ya.ru] </font>
    </p>
    <p>
      <font color="#008000">logpath = /var/log/httpd/error_log </font>
    </p>
    <p>
      <font color="#008000">maxretry = 3&#160;</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="/etc/fail2ban/action.d/iptables.conf" ID="ID_230022378" CREATED="1537882052432" MODIFIED="1537882749449"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000">[Definition] </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># Option: actionstart </font>
    </p>
    <p>
      <font color="#008000"># Notes.: command executed once at the start of Fatl2Ban. </font>
    </p>
    <p>
      <font color="#008000"># Values: CMD </font>
    </p>
    <p>
      <font color="#008000">actionstart = iptables -N fail2ban-&lt;name&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;iptables -A fail2ban-&lt;name&gt; -j RETURN </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;iptables -I INPUT -p &lt;protocol&gt; --dport &lt;port&gt; -j fail2ban-&lt;name&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># Option: actionstop </font>
    </p>
    <p>
      <font color="#008000"># Notes.: command executed once at the end of Fatl2Ban </font>
    </p>
    <p>
      <font color="#008000"># Values: CMD </font>
    </p>
    <p>
      <font color="#008000">actionstop = iptables -D INPUT -p &lt;protocol&gt; --dport &lt;port&gt; -j fail2ban-&lt;name&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;iptables -F fail2ban-&lt;name&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;iptables -X faiI2ban-&lt;name&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># Option: actioncheck </font>
    </p>
    <p>
      <font color="#008000"># Notes.: command executed once before each actionban command </font>
    </p>
    <p>
      <font color="#008000"># Values: CMD </font>
    </p>
    <p>
      <font color="#008000">actioncheck = iptables -n -L INPUT | grep -q fail2ban-&lt;name&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># Option: actionban </font>
    </p>
    <p>
      <font color="#008000"># Hotes.: command executed when banning an IP. Take care that the </font>
    </p>
    <p>
      <font color="#008000"># command is executed with Fail2Ban user rights. </font>
    </p>
    <p>
      <font color="#008000"># Tags: &lt;ip&gt; IP address </font>
    </p>
    <p>
      <font color="#008000"># &lt;failures&gt; number of failures </font>
    </p>
    <p>
      <font color="#008000"># &lt;time&gt; unix timestamp of the ban time </font>
    </p>
    <p>
      <font color="#008000"># Values: CMD </font>
    </p>
    <p>
      <font color="#008000">actionban = iptables -I fail2ban-&lt;name&gt; 1 -s &lt;ip&gt; -j DROP </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># Option: actionunban </font>
    </p>
    <p>
      <font color="#008000"># Hotes.: command executed when unbanning an IP. Take care that the </font>
    </p>
    <p>
      <font color="#008000"># command is executed with FaiI2Ban user rights. </font>
    </p>
    <p>
      <font color="#008000"># Tags: &lt;ip&gt; IP address </font>
    </p>
    <p>
      <font color="#008000"># &lt;failures&gt; number of failures </font>
    </p>
    <p>
      <font color="#008000"># &lt;time&gt; unix timestamp of the ban time </font>
    </p>
    <p>
      <font color="#008000"># Values: CMD </font>
    </p>
    <p>
      <font color="#008000">actionunban = iptables -D fail2ban-&lt;name&gt; -s &lt;ip&gt; -j DROP</font>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node ID="ID_1819299321" CREATED="1537882938802" MODIFIED="1537883423924"><richcontent TYPE="NODE">

<html>
