    <span class="fontstyle0">/etc/fail2ban/filter.d/asterisk.conf</span><br align="-webkit-auto" style="font-variant: normal; letter-spacing: normal; line-height: normal; text-indent: 0px; text-transform: none; white-space: normal; word-spacing: 0px"/>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000">failregex = Registration from '.*' failed for&#160;'&lt;HOST&gt;(:[0-9]{1,5})?' - Wrong password </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Registration from '.*' failed for '&lt;HOST&gt;(:[0-9]{1,5})?' - No matching peer found </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Registration from '.*' failed for '&lt;HOST&gt;(:[0-9]{1,5})?' - Device does not match ACL </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Registration from '.*' failed for '&lt;HOST&gt;(:[0-9]{1,5})?' - Username/auth name mismatch </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;Registration from '.*' failed for '&lt;HOST&gt;(:[0-9]{1,5})?' - Peer is not supposed to register </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;NOTICE.* &lt;HOST&gt; failed to authenticate as '.*'$ </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;NOTICE.* .*: No registration for peer '.*' (from &lt;HOST&gt;) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;NOTICE.* .*: Host &lt;HOST&gt; failed MD5 authentication for '.*' (.*) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;VERBOSE.* logger.c: -- .*IP/&lt;HOST&gt;-.* Playing 'ss-noservice' (language '.*' )</font>
    </p>
  </body>
</html></richcontent>
