<node TEXT="server.py" ID="ID_47213600" CREATED="1753605977654" MODIFIED="1753606014367"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from http.server import ThreadingHTTPServer, BaseHTTPRequestHandler </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from datetime import datetime </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">class RequestHandler(BaseHTTPRequestHandler): </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;def do_GET(self): </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;self.send_response(200) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;self.send_header('Content-type', 'text/plain') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;self.end_headers() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;now = datetime.now() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;response_string = now.strftime(&quot;Время %-I:%M %p, UTC.\n&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;self.wfile.write(bytes(response_string, &quot;utf-8&quot;)) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">def startServer(): </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;try: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;server = ThreadingHTTPServer(('', 80), RequestHandler) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;print(&quot;Listening on &quot; + &quot;:&quot;.join(map(str, server.server_address))) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;server.serve_forever() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;except KeyboardInterrupt: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;server.shutdown() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">if __name__== &quot;__main__&quot;: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;startServer()</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="пример - Python-приложения" FOLDED="true" POSITION="bottom_or_right" ID="ID_39584250" CREATED="1748673145146" MODIFIED="1762357116059"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#xa0;<a href="#ID_1893271929">pip</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Пример Dockerfile для Python-приложения</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Базовый образ </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">FROM python:3.12-slim </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Установка рабочей директории </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WORKDIR /app </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Копирование зависимостей и их установка </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">COPY requirements.txt . </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">RUN pip install --no-cache-dir --disable-pip-version-check -r requirements.txt </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Копирование остальных файлов </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">COPY . . </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Порт приложения </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">EXPOSE 8000 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Запуск </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">CMD [&quot;gunicorn&quot;, &quot;--bind&quot;, &quot;0.0.0.0:8000&quot;, &quot;app:app&quot;] </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">--no-cache-dir</span>&#xa0;- отключает кэширование pip, уменьшая размер образа
      </li>
      <li>
        <span style="font-weight: bold;">--disable-pip-version-check</span>&#xa0;- для избежания ненужных предупреждений при сборке
      </li>
    </ul>
  </body>
</html></richcontent>
