    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;image: docker.io/irk2adm/timeserver:5 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console; font-weight: bold;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;affinity:</span><span style="color: #008000; font-family: Lucida Console; font-weight: normal;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Правило предпочтения подов</span>
