    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;matchLabels: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;pod: timeserver-pod </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;template: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;metadata: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;labels: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;pod: timeserver-pod </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;spec: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;containers: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- name: timeserver-container </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;image: docker.io/irk2adm/timeserver:2 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;readinessProbe: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;initialDelaySeconds: 15 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;periodSeconds: 30 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;httpGet: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">path: /readyz</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;port: 80 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;scheme: HTTP </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;timeoutSeconds: 2 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;failureThreshold: 1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;successThreshold: 1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;livenessProbe: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;initialDelaySeconds: 30 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;periodSeconds: 30 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;httpGet: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">path: /healthz</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;port: 80 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;scheme: HTTP </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;timeoutSeconds: 5 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;failureThreshold: 3 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;successThreshold: 1 </span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
</node>
<node TEXT="Проверка готовности" FOLDED="true" ID="ID_1103719601" CREATED="1753689565202" MODIFIED="1755854804183"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1210793083">Проверка жизнеспособности</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Проверка готовности (readiness)</span>&#xa0;- определяет, готов ли контейнер к обработке трафика
    </p>
    <ul>
      <li>
        Можно использовать простой ответ с HTTP-заголовком, чтобы не тратить ресурсы на отображение целой HTML-страницы
      </li>
      <li>
        проверка готовности в большинстве случаев должна проверять такие внешние зависимости, как подключение к базе данных
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Типы проверок</span>
    </p>
    <ul>
      <li>
        Протокол HTTP
      </li>
      <li>
        Протокол TCP
      </li>
      <li>
        Bash-скрипт
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      Полезно использовать при обновлении
    </p>
    <p>
      <span style="color: #0000c0;">EXTERNAL_IP=&lt;IP-адрес_web-сервера&gt; </span>
    </p>
    <p>
      <span style="color: #0000c0;">watch -n 0.25 -d curl &quot;http://$EXTERNAL_IP&quot; </span>
    </p>
  </body>
</html></richcontent>
<node TEXT="deploy.yaml" ID="ID_45381460" CREATED="1753945218983" MODIFIED="1753948266918"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">apiVersion: apps/v1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">kind: Deployment </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">metadata: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;name: timeserver </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">spec: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;replicas: 3 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;selector: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;matchLabels: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;pod: timeserver-pod </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;template: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;metadata: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;labels: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;pod: timeserver-pod </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;spec: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;containers: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- name: timeserver-container </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;image: docker.io/irk2adm/timeserver:1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">readinessProbe:</span><span style="color: #008000; font-family: Lucida Console;">&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;initialDelaySeconds: 15&#xa0;&#xa0;# Начальная задержка </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;periodSeconds: 30&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Интервал </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;httpGet:&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Выполнить HTTP-запрос </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;path: / </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;port: 80 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;scheme: HTTP </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;timeoutSeconds: 2&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Таймаут ответа </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;failureThreshold: 1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;successThreshold: 1 </span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">failureThreshold</span>&#xa0;- Признаком неготовности контейнера считается получение хотя бы одного ответа с кодом ошибки
      </li>
      <li>
        <span style="font-weight: bold;">successThreshold</span>&#xa0;- Признаком возвращения контейнера в состояние готовности считается получение хотя бы одного ответа с кодом успешного завершения
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="псевдокод проверки подключения к БД" ID="ID_1791935966" CREATED="1753949445286" MODIFIED="1753949544031"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      # псевдокод проверки подключения к БД:
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">result = sql.execute(&quot;SELECT id FROM users LIMIT 1;&quot;) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">if result: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;http_response(200, &quot;Ready&quot;) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">else: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;http_response(503, &quot;Not Ready&quot;)</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Протокол TCP" ID="ID_727013354" CREATED="1753955370536" MODIFIED="1753955476138"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        Протокол TCP рекомендуется использовать в случае TCP-сервисов, не использующих протокол HTTP (например, SMTP-сервисов)
      </li>
      <li>
        Такая проверка выдает успешный результат при успешном открытии соединения:
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">readinessProbe: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;initialDelaySeconds: 15 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;periodSeconds: 30 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;tcpSocket: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;port: 25 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;successThreshold: 1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;failureThreshold: 1 </span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="через curl" ID="ID_588530246" CREATED="1763302509412" MODIFIED="1763303346331"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_115897549">curl</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Примеры прямого обращения к API-серверу через curl</span>
    </p>
    <ul>
      <li>
        $TOKEN - токен аутентификации (обычно из ServiceAccount)
      </li>
      <li>
        $KUBERNETES_HOST и $KUBERNETES_PORT - адрес API-сервера (например, localhost:6443)
      </li>
      <li>
        -k - игнорировать проверку SSL-сертификата (не использовать в проде)
      </li>
      <li>
        pod.json - файл с описанием пода в формате JSON
      </li>
      <li>
        Для --data-binary и PUT/POST - тело запроса должно быть валидным JSON
      </li>
      <li>
        Вместо ca.crt можно использовать --insecure (-k), но это снижает безопасность
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Получение списка подов</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -k -H &quot;Authorization: Bearer $TOKEN&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-H 'Accept: application/json' \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&quot;https://$KUBERNETES_HOST:$KUBERNETES_PORT/api/v1/namespaces/default/pods&quot;</span>
    </p>
    <p>
      <span style="font-weight: bold;">Создание пода</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -k -X POST \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-H &quot;Authorization: Bearer $TOKEN&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-H 'Content-Type: application/json' \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-H 'Accept: application/json' \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;--data-binary @pod.json \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&quot;https://$KUBERNETES_HOST:$KUBERNETES_PORT/api/v1/namespaces/default/pods&quot; </span>
    </p>
    <p>
      <span style="font-weight: bold;">Удалить под</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -X DELETE -H &quot;Authorization: Bearer $TOKEN&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;--cacert ca.crt \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&quot;https://$APISERVER/api/v1/namespaces/$NAMESPACE/pods/pod-name&quot;</span>
    </p>
    <p>
      <span style="font-weight: bold;">Получить логи пода</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -k -H &quot;Authorization: Bearer $TOKEN&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;--cacert ca.crt \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&quot;https://$APISERVER/api/v1/namespaces/$NAMESPACE/pods/pod-name/log&quot;</span>
    </p>
    <p>
      <span style="font-weight: bold;">Получение состояния узла</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -k -H &quot;Authorization: Bearer $TOKEN&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-H 'Accept: application/json' \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&quot;https://$KUBERNETES_HOST:$KUBERNETES_PORT/api/v1/nodes/$NODE_NAME&quot;</span>
    </p>
    <p>
      <span style="font-weight: bold;">Получить статус узла</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -k -H &quot;Authorization: Bearer $TOKEN&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;--cacert ca.crt \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&quot;https://$APISERVER/api/v1/nodes/node-name/status&quot;</span>
    </p>
    <p>
      <span style="font-weight: bold;">Обновить ConfigMap</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -X PUT -H &quot;Authorization: Bearer $TOKEN&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;-H &quot;Content-Type: application/json&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;--cacert ca.crt \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;--data-binary @updated-configmap.json \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&quot;https://$APISERVER/api/v1/namespaces/$NAMESPACE/configmaps/configmap-name&quot;</span>
    </p>
    <p>
      <span style="font-weight: bold;">Прокси-доступ к поду</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -k -H &quot;Authorization: Bearer $TOKEN&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;--cacert ca.crt \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&quot;https://$APISERVER/api/v1/namespaces/$NAMESPACE/pods/pod-name/proxy/&quot;</span>
    </p>
    <p>
      <span style="font-weight: bold;">Получить все ресурсы указанного типа (например, Service)</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -k -H &quot;Authorization: Bearer $TOKEN&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;--cacert ca.crt \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&quot;https://$APISERVER/api/v1/namespaces/$NAMESPACE/services&quot;</span>
    </p>
    <p>
      <span style="font-weight: bold;">Получить список кластерных ресурсов (например, Namespace)</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -k -H &quot;Authorization: Bearer $TOKEN&quot; \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;--cacert ca.crt \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&quot;https://$APISERVER/api/v1/namespaces&quot;</span>
    </p>
    <p>
      <span style="font-weight: bold;">Для аутентификации также можно использовать клиентский сертификат:</span>
    </p>
    <p>
      <span style="color: #0000c0;">curl -k --cert client.crt --key client.key \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;-H 'Accept: application/json' \ </span>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&quot;https://$KUBERNETES_HOST:$KUBERNETES_PORT/api/v1/namespaces/default/pods&quot;</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Конфигурирование" FOLDED="true" POSITION="bottom_or_right" ID="ID_966155573" CREATED="1752733619844" MODIFIED="1755509425067"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1595226177">vim</a>&#xa0; <a href="#ID_221814142">ConfigMap</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">kubectl edit cm -n kube-system kube-proxy</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">kubectl edit</span>&#xa0;- Редактирует ресурс Kubernetes прямо в кластере (аналогично kubectl apply, но открывает редактор для изменений &quot;на лету&quot;). После сохранения изменений Kubernetes автоматически применит новую конфигурацию
      </li>
      <li>
        <span style="font-weight: bold;">cm</span>&#xa0;(сокр. от configmap). ConfigMap - объект Kubernetes, хранящий конфигурационные данные в виде пар ключ-значение
      </li>
      <li>
        <span style="font-weight: bold;">kube-proxy</span>&#xa0;- имя ConfigMap, который управляет настройками kube-proxy
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">После выполнения команды</span>
    </p>
    <p>
      1. Откроется текстовый редактор (по умолчанию vim или nano, в зависимости от настроек KUBE_EDITOR)
    </p>
    <p>
      2. Вы увидите YAML-конфигурацию ConfigMap
    </p>
    <p>
      3. После редактирования и сохранения <span style="font-weight: bold;">изменения применятся автоматически</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Альтернативные способы изменения ConfigMap</span>
    </p>
    <p>
      1. Через <span style="font-weight: bold; color: #0000c0;">kubectl patch</span>&#xa0;(если нужно изменить одно поле)
    </p>
    <p>
      <span style="color: #0000c0;">kubectl patch cm -n kube-system kube-proxy --patch '{&quot;data&quot;:{&quot;config.conf&quot;:&quot;...новый конфиг...&quot;}}'</span>
    </p>
    <p>
      2. Через <span style="font-weight: bold; color: #0000c0;">kubectl apply</span>&#xa0;(если есть локальный файл конфига)
    </p>
    <p>
      <span style="color: #0000c0;">kubectl apply -f kube-proxy-config.yaml</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="ConfigMap" FOLDED="true" ID="ID_221814142" CREATED="1755507548607" MODIFIED="1755509371298"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">ConfigMap</span>&#xa0;- объект, предназначенный для хранения неконфиденциальных конф. данных в формате &quot;ключ-значение&quot;. Он позволяет отделить конфигурацию от образов контейнеров, что делает приложения более переносимыми и удобными для управления
    </p>
    <ul>
      <li>
        Хранить настройки централизованно
      </li>
      <li>
        Хранение конфигов - настройки приложений (например, application.properties, nginx.conf)
      </li>
      <li>
        Переменные среды (env) - передача параметров в контейнер через переменные окружения
      </li>
      <li>
        Монтирование как файлы - подмена конфигурационных файлов в контейнере
      </li>
      <li>
        Менять конфиги без пересборки образов
      </li>
      <li>
        Использовать одни и те же конфиги в разных подах
      </li>
      <li>
        Не предназначен для хранения секретов (для этого есть Secret)
      </li>
      <li>
        Обновление: Если ConfigMap обновляется, смонтированные файлы обновляются автоматически (но не всегда)
      </li>
      <li>
        Только для чтения: Контейнеры не могут изменять ConfigMap
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="Пример - ConfigMap для Nginx" ID="ID_1347933306" CREATED="1755508537939" MODIFIED="1755508644641"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">ConfigMap для Nginx</span>
    </p>
    <p>
      
    </p>
    <p>
      1. Создаем ConfigMap с конфигом Nginx
    </p>
    <p>
      <span style="color: #0000c0;">kubectl create configmap nginx-config --from-file=nginx.conf</span>
    </p>
    <p>
      
    </p>
    <p>
      2. Монтируем его в под
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">apiVersion: v1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">kind: Pod </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">metadata: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;name: nginx-pod </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">spec: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;containers: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;- name: nginx </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;image: nginx </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;volumeMounts: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- name: nginx-conf </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;mountPath: /etc/nginx/nginx.conf </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;subPath: nginx.conf&#xa0;&#xa0;# Чтобы не перезаписать всю директорию </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;volumes: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;- name: nginx-conf </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;configMap: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;name: nginx-config </span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Использование в Pod" ID="ID_398461419" CREATED="1755508399869" MODIFIED="1755508700460"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Как использовать ConfigMap в Pod </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Как переменные окружения (env)</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">apiVersion: v1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">kind: Pod </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">metadata: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;name: my-pod </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">spec: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;containers: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;- name: my-container </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;image: nginx </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;envFrom: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- configMapRef: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;name: my-config </span>
    </p>
    <p>
      # Или выборочно:&#xa0;
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">env: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;- name: DB_URL </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;valueFrom: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;configMapKeyRef: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;name: my-config </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;key: database.url</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Как файлы (volume mount)</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">volumes: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;- name: config-volume </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;configMap: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;name: my-config </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">containers: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;- name: my-container </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;image: nginx </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;volumeMounts: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- name: config-volume </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;mountPath: /etc/config</span>
    </p>
    <ul>
      <li>
        Каждый ключ из ConfigMap станет отдельным файлом в /etc/config
      </li>
      <li>
        Например, database.url --&gt; файл /etc/config/database.url
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. Как отдельный файл (items)</span>
    </p>
    <p>
      Если нужно смонтировать только определенный ключ:&#xa0;
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">volumes: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;- name: config-volume </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;configMap: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;name: my-config </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;items: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- key: app.properties </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;path: application.properties </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">containers: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;- volumeMounts: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- name: config-volume </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;mountPath: /etc/app-config</span>
    </p>
    <ul>
      <li>
        Теперь app.properties будет доступен как /etc/app-config/application.properties
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Создание" ID="ID_837931341" CREATED="1755508818421" MODIFIED="1755508835681"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Создание ConfigMap </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">kubectl create configmap my-config --from-file=config.properties</span>&#xa0;&#xa0;# <span style="font-weight: bold;">1.</span>&#xa0;&#xa0;Из файла
    </p>
    <p>
      <span style="color: #0000c0;">kubectl create configmap my-config --from-file=./configs/</span>&#xa0;&#xa0;# <span style="font-weight: bold;">2.</span>&#xa0;Из директории
    </p>
    <p>
      <span style="color: #0000c0;">kubectl create configmap my-config --from-literal=key1=value1 --from-literal=key2=value2</span>&#xa0;&#xa0;# <span style="font-weight: bold;">3.</span>&#xa0;&#xa0;Из литералов (ключ-значение)
    </p>
    <p>
      <span style="font-weight: bold;">4.</span>&#xa0;Через YAML-манифест&#xa0;
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">apiVersion: v1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">kind: ConfigMap </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">metadata: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;name: my-config </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">data: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;app.properties: | </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;server.port=8080 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;logging.level=INFO </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;database.url: &quot;jdbc:mysql://db-host:3306/mydb&quot;</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
</node>
<node TEXT="Логирование" POSITION="bottom_or_right" ID="ID_639225853" CREATED="1787388078935" MODIFIED="1788171852567"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">kubectl logs &lt;pod_name&gt; -p</span>&#xa0;&#xa0;# Покажет логи предыдущего, упавшего контейнера до его перезапуска
    </p>
    <ul>
      <li>
        --previous (-p)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      Если контейнер падает мгновенно, выполнить команду, чтобы увидеть системные события K8s и код завершения (Exit Code)
    </p>
    <p>
      <span style="color: #0000c0;">kubectl describe pod &lt;pod_name&gt; </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Логирование</span>
    </p>
    <ul>
      <li>
        fluentd
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Масштабирование" FOLDED="true" POSITION="bottom_or_right" ID="ID_1097707495" CREATED="1752058124795" MODIFIED="1788169025126"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Масштабируеся два вида ресурсов</span>
    </p>
    <ul>
      <li>
        приложение в виде подов
      </li>
      <li>
        предоставленные ему вычислительные ресурсы в виде узлов
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Масштабирование</span>
    </p>
    <ul>
      <li>
        Горизонтальное (+/- подов) - для веб-сервисов, микросервисов, API
      </li>
      <li>
        Вертикальное (+/- CPU/RAM) - для монолитных приложений, баз данных, memory-intensive задач
      </li>
      <li>
        Иногда используется гибридный подход (VPA настраивает ресурсы подов, а HPA управляет их количеством)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">GKE Autopilot</span>&#xa0;- полностью управляемый режим работы Google Kubernetes Engine (GKE), где Google автоматически настраивает и управляет инфраструктурой кластера (<span style="font-weight: bold;">нодами</span>, масштабированием, обновлениями и безопасностью), позволяя пользователям сосредоточиться только на своих приложениях.
    </p>
  </body>
</html></richcontent>
<node TEXT="Вертикальное масштабирование" FOLDED="true" ID="ID_760235902" CREATED="1754391423903" MODIFIED="1754813640304"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Вертикальное масштабирование (Vertical Scaling)</span>&#xa0;- увеличение или уменьшение ресурсов (CPU, RAM) существующих подов
    </p>
    <ul>
      <li>
        Подходит для stateful-приложений (например, базы данных), которые сложно масштабировать горизонтально
      </li>
      <li>
        Улучшает утилизацию ресурсов
      </li>
      <li>
        Ограничено физическими ресурсами ноды
      </li>
      <li>
        Может требовать перезапуска пода (если VPA в режиме Recreate)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Resource Requests &amp; Limits - задаются в манифесте пода</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">resources: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;requests: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;cpu: &quot;100m&quot;&#xa0;&#xa0;# 0.1 CPU </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;memory: &quot;128Mi&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;limits: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;cpu: &quot;500m&quot;&#xa0;&#xa0;# 0.5 CPU </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;memory: &quot;512Mi&quot;</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">requests</span>&#xa0;- гарантированные ресурсы, которые контейнер точно получит
      </li>
      <li>
        <span style="font-weight: bold;">limits</span>&#xa0;- максимальные ресурсы, которые контейнер может использовать (CPU: 300m, Memory: 400Mi)
      </li>
      <li>
        Если контейнер превысит лимиты:

        <ul>
          <li>
            CPU - будет ограничен (throttling)
          </li>
          <li>
            Memory - может быть убит (OOMKilled)
          </li>
        </ul>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Vertical Pod Autoscaler (VPA)</span>&#xa0;- автоматически настраивает requests и limits на основе исторических данных
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">apiVersion: autoscaling.k8s.io/v1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">kind: VerticalPodAutoscaler </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">metadata: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;name: my-app-vpa </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">spec: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;targetRef: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;apiVersion: &quot;apps/v1&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;kind: Deployment </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;name: my-app </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;updatePolicy: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;updateMode: &quot;Auto&quot;&#xa0;&#xa0;# или &quot;Off&quot;/&quot;Initial&quot; </span>
    </p>
    <ul>
      <li>
        updateMode: Auto - автоматически изменяет ресурсы
      </li>
      <li>
        updateMode: Recreate - требует пересоздания пода
      </li>
    </ul>
  </body>
</html></richcontent>
