    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;&#xa0;&#xa0;spec: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;containers: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;- name: gitea </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;image: gitea/gitea:latest </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;imagePullPolicy: IfNotPresent </span>
    </p>
