<node TEXT="Ограничить исходящий трафик (egress)" ID="ID_140522379" CREATED="1752819645756" MODIFIED="1752820405754"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Ограничить исходящий трафик (egress)</span>
    </p>
