<node TEXT="скрипт 1" ID="ID_99522021" CREATED="1519112079819" MODIFIED="1519112079819"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1102; &#1095;&#1091;&#1090;&#1086;&#1095;&#1082;&#1091; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074; &#1085;&#1072; PowerShell ( &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1084;&#1086; &#1082; win 2008, PowerGUI)
    </p>
    <p>
      <b>C&#1087;&#1080;&#1089;&#1086;&#1082; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; / &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1086;&#1074;:</b>
    </p>
    <p>
      <font color="#0000c0">PS&gt; Get-QADUser | Get-Member </font>
    </p>
    <p>
      <font color="#0000c0">PS&gt; Get-QADComputer </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>C&#1087;&#1080;&#1089;&#1086;&#1082; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1077; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1083;&#1080;&#1089;&#1100; 3 &#1084;&#1077;&#1089;&#1103;&#1094;&#1072; &#1080; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1084; &#1074;&#1099;&#1074;&#1086;&#1076; &#1074; HTML-&#1092;&#1072;&#1081;&#1083;:</b>
    </p>
    <p>
      <font color="#0000c0">PS&gt; $last3months = (Get-Date).AddMonths(-3) </font>
    </p>
    <p>
      <font color="#0000c0">PS&gt; Get-QADUser -IncludedProperties LastLogon | where { $_.lastLogon -le $last3months} | Select DisplayName, LastLogon, AccountIsDisabled | ?{-not $_.AccountIsDisabled} | ConvertTo-Html | Out-File E:\report.html </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1076;&#1080;&#1084; &#1085;&#1086;&#1074;&#1091;&#1102; &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; &#1091;&#1095;&#1077;&#1090;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;:</b>
    </p>
    <p>
      <font color="#0000c0">PS&gt; New-QADUser -name 'user' -ParentContainer 'OU=test,DC=iamroot,DC=local' -UserPassword 'P@ssword'</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="скрипт 2" ID="ID_160752544" CREATED="1519112079820" MODIFIED="1519112079820"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1044;&#1083;&#1103; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1090;&#1072;&#1088;&#1099;&#1093; &#1072;&#1082;&#1082;&#1072;&#1091;&#1085;&#1090;&#1086;&#1074;:</b>
    </p>
    <p>
      <font color="#0000c0">Disable-StaleDomainComputerAccounts.ps1: </font>
    </p>
    <p>
      <font color="#0000c0">function Disable-StaleDomainComputerAccounts </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">{ #function begin </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># Use Directory Services object to attach to the domain #Leaving the ADSI statement empty = attach to your root domain </font>
    </p>
    <p>
      <font color="#0000c0">$searcher = new-object DirectoryServices.DirectorySearcher([ADSI]&quot;&quot;) </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># Filter down to computer accounts with computer running windows OS (so to not disable MacOS and other bullshit) </font>
    </p>
    <p>
      <font color="#0000c0">$searcher.filter = &quot;(&amp;(objectClass=computer)(!useraccountcontrol:1.2.840.113556.1.4.804:=67117056)(|(operatingSystem=Windows*)))&quot; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># Cache the results </font>
    </p>
    <p>
      <font color="#0000c0">$searcher.CacheResults = $true </font>
    </p>
    <p>
      <font color="#0000c0">$searcher.SearchScope = &#8220;Subtree&#8221; </font>
    </p>
    <p>
      <font color="#0000c0">$searcher.PageSize = 1000 </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># Find anything you can that matches the definition of being a computer object </font>
    </p>
    <p>
      <font color="#0000c0">$accounts = $searcher.FindAll() </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># Check to make sure we found some accounts </font>
    </p>
    <p>
      <font color="#0000c0">if($accounts.Count -gt 0) </font>
    </p>
    <p>
      <font color="#0000c0">{ </font>
    </p>
    <p>
      <font color="#0000c0">foreach($account in $accounts) </font>
    </p>
    <p>
      <font color="#0000c0">{ </font>
    </p>
    <p>
      <font color="#0000c0">if ($DCs -eq $account) {writ-host DC, skipping; continue} </font>
    </p>
    <p>
      <font color="#0000c0"># Property that contains the last password change in long integer format </font>
    </p>
    <p>
      <font color="#0000c0">$pwdlastset = $account.Properties[&quot;pwdlastset&quot;]; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># Convert the long integer to normal DateTime format </font>
    </p>
    <p>
      <font color="#0000c0">$lastchange = [datetime]::FromFileTimeUTC($pwdlastset[0]); </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># Determine the timespan between the two dates </font>
    </p>
    <p>
      <font color="#0000c0">$datediff = new-TimeSpan $lastchange $(Get-Date); </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">if ($datediff.Days -gt 50) </font>
    </p>
    <p>
      <font color="#0000c0">{ </font>
    </p>
    <p>
      <font color="#0000c0">#$account.Path </font>
    </p>
    <p>
      <font color="#0000c0">$ldapname = $account.path </font>
    </p>
    <p>
      <font color="#0000c0">$compadsi = [ADSI]$ldapname </font>
    </p>
    <p>
      <font color="#0000c0">if ($compadsi.psbase.invokeGet(&quot;AccountDisabled&quot;) -eq $false ) </font>
    </p>
    <p>
      <font color="#0000c0">{ </font>
    </p>
    <p>
      <font color="#0000c0">$compadsi.psbase.invokeSet(&quot;AccountDisabled&quot;,$true) </font>
    </p>
    <p>
      <font color="#0000c0">$compadsi.Setinfo() </font>
    </p>
    <p>
      <font color="#0000c0">$strInfoMessage = &quot;Disabled &quot; + ($compadsi.psbase.invokeGet(&quot;Name&quot;)) + &quot;, password was set &quot; + $datediff.Days + &quot; days ago.&quot; </font>
    </p>
    <p>
      <font color="#0000c0">$strLog += $strInfoMessage + &quot;`n&quot; </font>
    </p>
    <p>
      <font color="#0000c0">} </font>
    </p>
    <p>
      <font color="#0000c0">} #end of datediff.days </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">} # end of foreach account </font>
    </p>
    <p>
      <font color="#0000c0">} #end of accounts.count </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">if ($strLog) { </font>
    </p>
    <p>
      <font color="#0000c0">$strLog </font>
    </p>
    <p>
      <font color="#0000c0">$strLog = &quot;Stale Record disabled following accounts: `n&quot; + $strLog </font>
    </p>
    <p>
      <font color="#0000c0">$EventLog = new-object System.Diagnostics.EventLog('Application') </font>
    </p>
    <p>
      <font color="#0000c0">$EventLog.MachineName = &quot;.&quot; </font>
    </p>
    <p>
      <font color="#0000c0">$EventLog.Source = &quot;WMIInfo&quot; </font>
    </p>
    <p>
      <font color="#0000c0">$EventLog.WriteEntry($strLog,&quot;Information&quot;,10) </font>
    </p>
    <p>
      <font color="#0000c0">} </font>
    </p>
    <p>
      <font color="#0000c0">} #function end </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">Disable-StaleDomainComputerAccounts</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1042; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; if ($datediff.Days -gt 50) &#1084;&#1077;&#1085;&#1103;&#1081;&#1090;&#1077; 50 &#1085;&#1072; &#1085;&#1091;&#1078;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1076;&#1085;&#1077;&#1081;
    </p>
  </body>
</html></richcontent>
</node>
</node>
