      <b>&#1053;&#1072;&#1076;&#1077;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1091;&#1079;&#1083;&#1072;.</b>&#160; HA-&#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1099;, &#1090;&#1072;&#1082;&#1078;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090; &#1084;&#1077;&#1090;&#1086;&#1076;&#1099;, &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1084;&#1099;&#1077; &#1074; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; (&#1085;&#1077;&#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1085;&#1099;&#1093;) &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1093; &#1080; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1080;&#1085;&#1092;&#1088;&#1072;&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1077; &#1076;&#1083;&#1103; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1074;&#1099;&#1096;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072;&#1076;&#1105;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080;
    </p>
    <ul>
      <li>
        &#1056;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1080; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1102; &#1076;&#1080;&#1089;&#1082;&#1086;&#1074;: &#1086;&#1090;&#1082;&#1072;&#1079; &#1095;&#1072;&#1089;&#1090;&#1080; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; &#1076;&#1080;&#1089;&#1082;&#1086;&#1074; &#1085;&#1077; &#1087;&#1088;&#1080;&#1074;&#1086;&#1076;&#1080;&#1090; &#1082; &#1089;&#1073;&#1086;&#1103;&#1084; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1089;&#1084;. <a href="#ID_82780074">DRBD</a>
      </li>
      <li>
        &#1056;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1093; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081;: &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, &#1086;&#1090;&#1082;&#1072;&#1079; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072; &#1080;&#1083;&#1080; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1075;&#1086; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1085;&#1077; &#1087;&#1088;&#1080;&#1074;&#1086;&#1076;&#1103;&#1090; &#1082; &#1087;&#1086;&#1083;&#1085;&#1086;&#1084;&#1091; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1102; &#1086;&#1090; &#1089;&#1077;&#1090;&#1080;
      </li>
      <li>
        &#1056;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081; c&#1077;&#1090;&#1080; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; (<a href="#ID_1209291691">SAN</a>): &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, &#1089;&#1073;&#1086;&#1081; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072; &#1080;&#1083;&#1080; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1075;&#1086; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1085;&#1077; &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1091;&#1090; &#1082; &#1087;&#1086;&#1090;&#1077;&#1088;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074; &#1089; &#1093;&#1088;&#1072;&#1085;&#1080;&#1083;&#1080;&#1097;&#1077;&#1084;
      </li>
      <li>
        &#1048;&#1079;&#1073;&#1099;&#1090;&#1086;&#1095;&#1085;&#1099;&#1077; &#1089;&#1093;&#1077;&#1084;&#1099; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;, &#1082;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086;, &#1079;&#1072;&#1097;&#1080;&#1097;&#1105;&#1085;&#1085;&#1086;&#1075;&#1086; &#1048;&#1041;&#1055;, &#1080; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1091;&#1077;&#1084;&#1099;&#1077; &#1073;&#1083;&#1086;&#1082;&#1080; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103;: &#1086;&#1090;&#1082;&#1072;&#1079; &#1077;&#1076;&#1080;&#1085;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1074;&#1074;&#1086;&#1076;&#1072;, &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, UPS &#1080;&#1083;&#1080; &#1041;&#1055; &#1085;&#1077; &#1087;&#1088;&#1080;&#1074;&#1086;&#1076;&#1080;&#1090; &#1082; &#1082;&#1088;&#1080;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084;&#1091; &#1086;&#1090;&#1082;&#1072;&#1079;&#1091; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;.
      </li>
    </ul>
    <p>
      &#1044;&#1083;&#1103; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1086;&#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1080; &#1091;&#1079;&#1083;&#1086;&#1074; &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1085;&#1077;&#1087;&#1088;&#1077;&#1088;&#1099;&#1074;&#1085;&#1086;&#1075;&#1086; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; (&#171;&#1087;&#1091;&#1083;&#1100;&#1089;&#1072;&#187;, &#1072;&#1085;&#1075;&#1083;. heartbeat) &#1074;&#1086; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1081; &#1089;&#1077;&#1090;&#1080; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072; &#1086;&#1090; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1080;&#1079; &#1091;&#1079;&#1083;&#1086;&#1074;, &#1087;&#1086; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1102; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1077;&#1077; &#1055;&#1054; &#1089;&#1091;&#1076;&#1080;&#1090; &#1086; &#1085;&#1086;&#1088;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1088;&#1072;&#1073;&#1086;&#1090;&#1077; &#1089;&#1086;&#1089;&#1077;&#1076;&#1085;&#1080;&#1093; &#1091;&#1079;&#1083;&#1086;&#1074;
