<node TEXT="DRBD" ID="ID_82780074" CREATED="1543598980826" MODIFIED="1552206858317"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1279999390">RAID1</a>&#160; <a href="#ID_1574804007">LVM</a>&#160; <a href="#ID_1789224411">XFS</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1056;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; DRBD</b>&#160;(Distributed Replicated Block Device &#8212; &#171;&#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1105;&#1085;&#1085;&#1086;&#1077; &#1088;&#1077;&#1087;&#1083;&#1080;&#1094;&#1080;&#1088;&#1091;&#1077;&#1084;&#1086;&#1077; &#1073;&#1083;&#1086;&#1095;&#1085;&#1086;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086;&#187;) - &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1085;&#1072;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;, &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1102;&#1097;&#1072;&#1103; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102; (RAID1) &#1084;&#1077;&#1078;&#1076;&#1091; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; &#1073;&#1083;&#1086;&#1095;&#1085;&#1099;&#1084; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086;&#1084; &#1080; &#1091;&#1076;&#1072;&#1083;&#1105;&#1085;&#1085;&#1099;&#1084;.
    </p>
    <ul>
      <li>
        &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102; &#1074; &#1084;&#1072;&#1089;&#1096;&#1090;&#1072;&#1073;&#1077; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;
      </li>
      <li>
        &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1090; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1085;&#1072; &#1086;&#1073;&#1072; &#1091;&#1079;&#1083;&#1072;
      </li>
      <li>
        DRBD &#1084;&#1086;&#1078;&#1085;&#1086; &#1088;&#1072;&#1089;&#1089;&#1084;&#1072;&#1090;&#1088;&#1080;&#1074;&#1072;&#1090;&#1100; &#1082;&#1072;&#1082; &#1101;&#1082;&#1074;&#1080;&#1074;&#1072;&#1083;&#1077;&#1085;&#1090; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1075;&#1086; &#1076;&#1080;&#1089;&#1082;&#1086;&#1074;&#1086;&#1075;&#1086; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072; RAID1, &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1099;&#1081; &#1085;&#1080;&#1078;&#1077; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1057;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; DRBD &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086; &#1089; &#1060;&#1057;.
      </li>
      <li>
        DRBD &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; <b>&#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1102; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;</b>. &#1042; &#1101;&#1090;&#1086;&#1081; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1080; &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; &#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1080; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1076;&#1074;&#1091;&#1093; &#1091;&#1079;&#1083;&#1072;&#1093;, &#1080; &#1074;&#1089;&#1077; &#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1078;&#1076;&#1077;&#1085;&#1085;&#1099;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1073;&#1072; &#1091;&#1079;&#1083;&#1072;. &#1050;&#1086;&#1075;&#1076;&#1072; &#1086;&#1076;&#1080;&#1085; &#1080;&#1079; &#1091;&#1079;&#1083;&#1086;&#1074; &#1086;&#1082;&#1072;&#1078;&#1077;&#1090;&#1089;&#1103; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1077;&#1085; DRBD &#1087;&#1088;&#1077;&#1076;&#1086;&#1083;&#1078;&#1080;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091; &#1082;&#1072;&#1082; &#1076;&#1077;&#1075;&#1088;&#1072;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; RAID1. &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1086;&#1090;&#1082;&#1072;&#1079;&#1072; &#1074;&#1072;&#1084; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1087;&#1088;&#1080;&#1076;&#1077;&#1090;&#1089;&#1103; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100;. &#1050;&#1072;&#1082; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1091;&#1079;&#1077;&#1083; &#1074;&#1085;&#1086;&#1074;&#1100; &#1087;&#1086;&#1103;&#1074;&#1080;&#1090;&#1089;&#1103; &#1074; &#1089;&#1077;&#1090;&#1080;, DRBD &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102;
      </li>
      <li>
        &#1055;&#1086;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1080;&#1077; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1099;&#1093; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1085;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084; &#1085;&#1072; &#1054;&#1057; &#1089; &#1103;&#1076;&#1088;&#1086;&#1084; Linux
      </li>
      <li>
        &#1042;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; &#1074;&#1072;&#1085;&#1080;&#1083;&#1100;&#1085;&#1086;&#1077; &#1103;&#1076;&#1088;&#1086; Linux &#1089; 15 &#1076;&#1077;&#1082;&#1072;&#1073;&#1088;&#1103; 2009 &#1075;&#1086;&#1076;&#1072;
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Virtual IP" ID="ID_579593011" CREATED="1543599020660" MODIFIED="1791018862053"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_101266172">NLB Cluster</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Virtual IP (VIP)</b>&#xa0;- виртуальные IP-адреса. Существует возможность определить виртуальный IР-адрес, присвоить его активным серверам и настроить все ПО на использование этого адреса. Тогда, в случае отказа, IP-адрес будет подхвачен следующим сервером, и все клиенты продолжат работу.
    </p>
  </body>
</html></richcontent>
</node>
