        &#1053;&#1072;&#1073;&#1086;&#1088; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1080;&#1085;&#1092;. &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086;&#1081; &#1076;&#1083;&#1103; &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; RTP-&#1087;&#1072;&#1082;&#1077;&#1090;&#1072;
      </li>
      <li>
        &#1043;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1090;&#1086;&#1082; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; RTP-&#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072;&#1093;
      </li>
      <li>
        RTP &#1080;&#1085;&#1082;&#1072;&#1087;&#1089;&#1091;&#1083;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; UDP &#1080; &#1076;&#1072;&#1083;&#1077;&#1077; &#1074; IP-&#1087;&#1072;&#1082;&#1077;&#1090;. &#1050;&#1072;&#1082;&#1080;&#1084; &#1082;&#1086;&#1076;&#1077;&#1082;&#1086;&#1084; &#1079;&#1072;&#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1075;&#1086;&#1083;&#1086;&#1089;
      </li>
      <li>
        IP-&#1087;&#1072;&#1082;&#1077;&#1090; &#1080;&#1085;&#1082;&#1072;&#1087;&#1089;&#1091;&#1083;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; L2 &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;
      </li>
    </ol>
  </body>
</html></richcontent>
