<node TEXT="Преобразование аналогового сигнала" ID="ID_607501296" CREATED="1537271086731" MODIFIED="1538399459325"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      1. Sampling - &#1044;&#1080;&#1089;&#1082;&#1088;&#1077;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1074;&#1086;&#1083;&#1085;&#1099;
    </p>
    <p>
      2. Quantization (DSP, HMP) - &#1050;&#1074;&#1072;&#1085;&#1090;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; - &#1079;&#1072;&#1084;&#1077;&#1088; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1074; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;
    </p>
    <p>
      3. Encoding (DSP, HMP) - &#1050;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;. &#1050;&#1086;&#1076;&#1077;&#1082; - &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;. &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1086;&#1075;&#1086; &#1074; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1086;&#1081;
    </p>
    <p>
      4. Codec Compression - &#1057;&#1078;&#1072;&#1090;&#1080;&#1077;
    </p>
    <p>
      5. VoIP <a href="#ID_1754411606">Encapsulation</a>
    </p>
    <p>
      6. Transport Through IP Network (only UDP)
    </p>
    <p>
      7. VoIP Decapsulation
    </p>
    <p>
      8. Decoding (DSP, HMP)
    </p>
    <p>
      9. Modulation (DSP, HMP)
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1103;&#1094;&#1080;&#1103; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072; &#1089;&#1095;&#1077;&#1090; &#1076;&#1074;&#1091;&#1093; &#1090;&#1080;&#1087;&#1086;&#1074; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1074; </b>
    </p>
    <p>
      <b>DSP</b>&#160;(digital signal processor)&#160;- &#1076;&#1086;&#1088;&#1086;&#1075;&#1080;&#1077; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1095;&#1080;&#1087;&#1099; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089; &#1072;&#1091;&#1076;&#1080;&#1086;/&#1074;&#1080;&#1076;&#1077;&#1086; &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1084;. &#1057;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1080;&#1082;&#1088;&#1086;&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1086;&#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1086;&#1074; (&#1086;&#1073;&#1099;&#1095;&#1085;&#1086;, &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;).
    </p>
    <p>
      <b>HMP</b>&#160;(host media processing)&#160;- &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1074; CPU (Asterisk)
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="# Сигнализация" FOLDED="true" ID="ID_1888185219" CREATED="1537257391194" MODIFIED="1539169112123"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_632630431">&#1055;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1099; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103;</b>&#160;- <b>&#1058;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1072;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103;</b>&#160; - (signaling) &#1074; &#1090;&#1077;&#1083;&#1077;&#1082;&#1086;&#1084;&#1084;&#1091;&#1085;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;&#1093; &#8212; &#1090;&#1077;&#1093;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086; &#1076;&#1083;&#1103; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074; &#1076;&#1088;&#1091;&#1075; &#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084; &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; &#1080; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;, &#1089;&#1074;&#1103;&#1079;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;&#1084; &#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077;&#1081; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.
    </p>
