<node TEXT="Типы Сигнализации" ID="ID_40368134" CREATED="1537267279542" MODIFIED="1539168335951"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1058;&#1080;&#1087;&#1099; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1051;&#1080;&#1085;&#1077;&#1081;&#1085;&#1072;&#1103; (supervisory)</b>&#160;- &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1086;&#1073; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072;&#160;(&#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077;/&#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077;). &#1057;&#1098;&#1077;&#1084; &#1090;&#1088;&#1091;&#1073;&#1082;&#1080;
    </p>
    <ul>
      <li>
        <b>on-hook</b>&#160;- &#1058;&#1088;&#1091;&#1073;&#1082;&#1072; &#1085;&#1072; &#1082;&#1088;&#1102;&#1095;&#1082;&#1077;. &#1062;&#1077;&#1087;&#1100; &#1088;&#1072;&#1079;&#1086;&#1084;&#1082;&#1085;&#1091;&#1090;&#1072;
      </li>
      <li>
        <b>off-hook&#160;</b>- &#1058;&#1088;&#1091;&#1073;&#1082;&#1072; &#1087;&#1086;&#1076;&#1085;&#1103;&#1090;&#1072;
      </li>
      <li>
        <b>ringin</b>&#160;- &#1053;&#1072;&#1073;&#1088;&#1072;&#1083;&#1080; &#1085;&#1086;&#1084;&#1077;&#1088;, &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1080; &#1094;&#1080;&#1092;&#1088;&#1099; &#1085;&#1072; &#1040;&#1058;&#1057;. &#1040;&#1058;&#1057; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; (ringin) &#1086;&#1073; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1085;&#1072; &#1090;&#1077;&#1083;. &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;.
      </li>
    </ul>
    <p>
      <b>2. &#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1086;&#1074;&#1072;&#1103; (address)</b>&#160; - &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1094;&#1080;&#1092;&#1088;
    </p>
    <ul>
      <li>
        <b>pulse</b>&#160;- &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1085;&#1099;&#1081;. &#1063;&#1077;&#1090;&#1099;&#1088;&#1077; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1072; - &#1094;&#1080;&#1092;&#1088;&#1072; 4. &#1048;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1103; &#1084;&#1086;&#1075;&#1091;&#1090; &#1085;&#1072;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1088;&#1091;&#1075; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1072;, &#1086;&#1090;&#1089;&#1102;&#1076;&#1072; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1089; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1084;
      </li>
      <li>
        <b>DTMF</b>&#160;- Dual-Tone Multi-Frequency - &#1058;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1085;&#1072;&#1073;&#1086;&#1088;, &#1090;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#8212; &#1076;&#1074;&#1091;&#1093;&#1090;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1084;&#1085;&#1086;&#1075;&#1086;&#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1085;&#1099;&#1081; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1099;&#1081; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1081; &#1076;&#1083;&#1103; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072;
      </li>
    </ul>
    <p>
      &#1060;&#1086;&#1088;&#1084;&#1072;&#1090; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072;
