        <b>&#1050;&#1055;&#1042;</b>&#160;(&#1050;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100; &#1087;&#1086;&#1089;&#1099;&#1083;&#1082;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072;) - &#1076;&#1083;&#1080;&#1085;&#1085;&#1099;&#1077; &#1075;&#1091;&#1076;&#1082;&#1080;. &#1072;&#1082;&#1091;&#1089;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; (&#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1075;&#1091;&#1076;&#1082;&#1080;, &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1103;&#1102;&#1097;&#1080;&#1077;&#1089;&#1103; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; &#1088;&#1072;&#1079; &#1074; &#1087;&#1103;&#1090;&#1100; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090; &#1089;&#1083;&#1099;&#1096;&#1080;&#1090; &#1074; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1081; &#1090;&#1088;&#1091;&#1073;&#1082;&#1077; &#1087;&#1086;&#1089;&#1083;&#1077; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1076;&#1086; &#1086;&#1090;&#1074;&#1077;&#1090;&#1072; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;&#1086;&#1075;&#1086; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1080;&#1083;&#1080; &#1086;&#1090;&#1073;&#1086;&#1103;, &#1080; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1090; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1086; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1089;&#1077;&#1090;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1086;, &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;&#1099;&#1081; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090; &#1089;&#1074;&#1086;&#1073;&#1086;&#1076;&#1077;&#1085;. &#1042; &#160;&#1083;&#1080;&#1090;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1099;&#1081; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085; Ring-Back Tone &#1080;&#1083;&#1080; RBT. &#1053;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1099; &#1089;&#1074;&#1103;&#1079;&#1080;, &#1087;&#1088;&#1077;&#1076;&#1083;&#1072;&#1075;&#1072;&#1102;&#1090; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;&#1084; &#1091;&#1089;&#1083;&#1091;&#1075;&#1091; &#1079;&#1072;&#1084;&#1077;&#1085;&#1099; &#1050;&#1055;&#1042; &#1085;&#1072; &#1087;&#1077;&#1088;&#1089;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1084;&#1077;&#1083;&#1086;&#1076;&#1080;&#1102; &#1080;&#1083;&#1080; &#1076;&#1088;&#1091;&#1075;&#1091;&#1102; &#1079;&#1074;&#1091;&#1082;&#1086;&#1079;&#1072;&#1087;&#1080;&#1089;&#1100;
      </li>
    </ul>
