<node TEXT="Протоколы сигнализации" FOLDED="true" ID="ID_632630431" CREATED="1537259190382" MODIFIED="1572363012791"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_189378427">P2P</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>SIP</b>&#160;&#8212; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; (IETF) &#1089;&#1077;&#1072;&#1085;&#1089;&#1086;&#1074;&#1086;&#1075;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1074;&#1103;&#1079;&#1080;, &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1091; &#1075;&#1086;&#1083;&#1086;&#1089;&#1072;, &#1074;&#1080;&#1076;&#1077;&#1086;, &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084; &#1084;&#1075;&#1085;&#1086;&#1074;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1084;&#1077;&#1085;&#1072; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1080; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086;&#1081; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080;
    </p>
    <ul>
      <li>
        P2P - &#1088;&#1072;&#1073;&#1086;&#1090;&#1072; &#1073;&#1077;&#1079; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
      </li>
      <li>
        &#1059; Microsoft &#1089;&#1074;&#1086;&#1081; SIP, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1085;&#1086;&#1075;&#1080;&#1077; &#1074;&#1077;&#1085;&#1076;&#1086;&#1088;&#1099; &#1085;&#1077; &#1087;&#1086;&#1085;&#1080;&#1084;&#1072;&#1102;&#1090;
      </li>
    </ul>
    <p>
      <b>H.323</b>&#160;&#8212; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1072;&#1094;&#1080;&#1103; ITU-T, &#1089;&#1090;&#1077;&#1082; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074;, &#1073;&#1086;&#1083;&#1077;&#1077; &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1072;&#1085;&#1085;&#1099;&#1081; &#1082; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1084; &#1090;&#1088;&#1072;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1081; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1080;&#1080;, &#1095;&#1077;&#1084; SIP
    </p>
    <ul>
      <li>
        P2P - &#1088;&#1072;&#1073;&#1086;&#1090;&#1072; &#1073;&#1077;&#1079; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
      </li>
      <li>
        &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1085;&#1072; &#1040;&#1058;&#1057;. &#1054;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1085;&#1072; &#1096;&#1083;&#1102;&#1079;&#1077;
      </li>
    </ul>
    <p>
      <b>MGCP</b>&#160;&#8212; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; (IETF) &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1084;&#1077;&#1076;&#1080;&#1072;&#1096;&#1083;&#1102;&#1079;&#1072;&#1084;&#1080; (&#1079;&#1072;&#1084;&#1077;&#1085;&#1080;&#1083; SGCP). &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; Cisco.
    </p>
    <ul>
      <li>
        &#1072;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1072; &quot;&#1082;&#1083;&#1080;&#1077;&#1085;&#1090;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&quot;
      </li>
      <li>
        &#1087;&#1086;&#1087;&#1091;&#1083;&#1103;&#1088;&#1077;&#1085; &#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074;
      </li>
      <li>
        &#1074;&#1089;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072; Q.931 &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1085;&#1072; &#1040;&#1058;&#1057;, &#1096;&#1083;&#1102;&#1079; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1087;&#1077;&#1088;&#1077;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090; (&#1090;.&#1077;. &#1085;&#1072; &#1096;&#1083;&#1102;&#1079;&#1077; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100;)
      </li>
    </ul>
    <p>
      <b>Megaco/H.248</b>&#160;&#8212; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1084;&#1077;&#1076;&#1080;&#1072;&#1096;&#1083;&#1102;&#1079;&#1072;&#1084;&#1080;, &#1088;&#1072;&#1079;&#1074;&#1080;&#1090;&#1080;&#1077; MGCP.
    </p>
    <p>
      <b>SIGTRAN</b>&#160;&#8212; &#1085;&#1072;&#1073;&#1086;&#1088; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074; &#1090;&#1091;&#1085;&#1085;&#1077;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; PSTN-&#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1054;&#1050;&#1057;-7 &#1095;&#1077;&#1088;&#1077;&#1079; IP &#1085;&#1072; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1085;&#1099;&#1081; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088; (Softswitch).
    </p>
    <p>
      <b>SCTP</b>&#160;&#8212; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1076;&#1083;&#1103; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1081; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1082;&#1080; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1074; IP-&#1089;&#1077;&#1090;&#1103;&#1093;.
    </p>
    <p>
      <b>SCCP or &quot;Skinny&quot;</b>&#160;&#8212; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1072;&#1084;&#1080; (IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072;&#1084;&#1080; &#1080; &#1084;&#1077;&#1076;&#1080;&#1072;&#1096;&#1083;&#1102;&#1079;&#1072;&#1084;&#1080;) &#1074; &#1087;&#1088;&#1086;&#1076;&#1091;&#1082;&#1090;&#1072;&#1093; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080; Cisco. SCCP &#1073;&#1086;&#1083;&#1077;&#1077; &#1089;&#1090;&#1072;&#1073;&#1080;&#1083;&#1100;&#1085;&#1099;&#1081;, &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1072;, &#1085;&#1072; Asterisk &#1089;&#1083;&#1086;&#1078;&#1085;&#1077;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100;
    </p>
    <ul>
      <li>
        &#1072;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1072; &quot;&#1082;&#1083;&#1080;&#1077;&#1085;&#1090;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&quot;
      </li>
      <li>
        &#1087;&#1086;&#1087;&#1091;&#1083;&#1103;&#1088;&#1077;&#1085; &#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074;
      </li>
    </ul>
    <p>
      <b>Jingle</b>&#160;(&#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077; &#1082; XMPP / Jabber).
    </p>
    <p>
      <b>IAX2</b>&#160;&#8212; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1076;&#1083;&#1103; &#1086;&#1073;&#1084;&#1077;&#1085;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; IP-PBX Asterisk. &#1063;&#1077;&#1088;&#1077;&#1079; 4569 UDP-&#1087;&#1086;&#1088;&#1090; - &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1080; &#1084;&#1077;&#1076;&#1080;&#1072;&#1090;&#1088;&#1072;&#1092;&#1080;&#1082;. &#1042; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1084;, &#1076;&#1083;&#1103; &#1089;&#1074;&#1103;&#1079;&#1080; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1081; Asterisk &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1086;&#1073;&#1086;&#1081;
    </p>
    <p>
      <b>Unistim</b>&#160;&#8212; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1074; &#1087;&#1088;&#1086;&#1076;&#1091;&#1082;&#1090;&#1072;&#1093; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080; Nortel, Avaya.
    </p>
    <ul>
      <li>
        &#1072;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1072; &quot;&#1082;&#1083;&#1080;&#1077;&#1085;&#1090;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&quot;
      </li>
    </ul>
    <p>
      <b>DAHDI (&#1088;&#1072;&#1085;&#1077;&#1077; Zaptel)</b>&#160;&#8212;
    </p>
  </body>
