<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>H.323</b>&#160;&#8212; &#1053;&#1072;&#1073;&#1086;&#1088; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1086;&#1074; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1084;&#1077;&#1076;&#1080;&#1072;-&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086; &#1089;&#1077;&#1090;&#1103;&#1084; &#1089; &#1087;&#1072;&#1082;&#1077;&#1090;&#1085;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077;&#1081;. &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1083; &#1076;&#1086;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1077; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1077; &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1091;&#1089;&#1083;&#1091;&#1075; IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1080;&#1080;. &#1052;&#1085;&#1086;&#1075;&#1080;&#1077; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1080; &#1090;&#1077;&#1083;&#1077;&#1082;&#1086;&#1084;&#1084;&#1091;&#1085;&#1080;&#1082;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; (Avaya, Huawei, D-Link, Wildix) &#1080;&#1084;&#1077;&#1102;&#1090; &#1074; &#1089;&#1074;&#1086;&#1077;&#1081; &#1083;&#1080;&#1085;&#1077;&#1081;&#1082;&#1077; H.323 &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;.
    </p>
    <ul>
      <li>
        &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1087;&#1086; <b>&#1087;&#1086;&#1088;&#1090;&#1091; 1720 TCP &#1080; 1719 TCP</b>&#160;&#1076;&#1083;&#1103; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1086;&#1074; &#1085;&#1072; &#1075;&#1077;&#1081;&#1090;&#1082;&#1080;&#1087;&#1077;&#1088;&#1077;
      </li>
      <li>
        &#1072;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1072;&#160;<a href="#ID_189378427">P2P</a>&#160;- &#1088;&#1072;&#1073;&#1086;&#1090;&#1072; &#1073;&#1077;&#1079; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;
      </li>
      <li>
        &#1089;&#1086;&#1079;&#1076;&#1072;&#1085; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; <b>ISDN Q.931</b>&#160;(H.225 &#1089;&#1093;&#1086;&#1078; &#1089; &#1085;&#1080;&#1084;)
      </li>
    </ul>
    <p>
      <b>H.323 Gatekeeper</b>&#160;(&#1050;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1083;&#1077;&#1088; &#1079;&#1086;&#1085;&#1099; H.323, &#1055;&#1088;&#1080;&#1074;&#1088;&#1072;&#1090;&#1085;&#1080;&#1082;) &#8212; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1080;&#1083;&#1080; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1074; &#1089;&#1077;&#1090;&#1080; IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1080;&#1080;, &#1087;&#1086; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1091; H.323, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1074;&#1099;&#1089;&#1090;&#1091;&#1087;&#1072;&#1077;&#1090; &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1089;&#1074;&#1086;&#1077;&#1081; &#1079;&#1086;&#1085;&#1099;. &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;:
    </p>
    <ul>
      <li>
        &#1052;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103;
      </li>
      <li>
        &#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1086;&#1074;
      </li>
      <li>
        &#1050;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100; &#1087;&#1086;&#1083;&#1086;&#1089;&#1099; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1085;&#1080;&#1103; &#1084;&#1077;&#1078;&#1076;&#1091; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084;&#1080; &#1086;&#1092;&#1080;&#1089;&#1072;&#1084;&#1080; &#1080; &#1087;&#1083;&#1086;&#1097;&#1072;&#1076;&#1082;&#1072;&#1084;&#1080;
      </li>
      <li>
        &#1055;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;
      </li>
    </ul>
    <p>
      <b>MCU, Multipoint Control Unit </b>(&#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1084;&#1085;&#1086;&#1075;&#1086;&#1090;&#1086;&#1095;&#1077;&#1095;&#1085;&#1086;&#1081; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080;) &#8212; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1085;&#1086;-&#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1085;&#1086;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1086;&#1077; &#1076;&#1083;&#1103; &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1072;&#1091;&#1076;&#1080;&#1086;- &#1080; &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080; &#1074; &#1084;&#1085;&#1086;&#1075;&#1086;&#1090;&#1086;&#1095;&#1077;&#1095;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1084;&#1085;&#1086;&#1075;&#1086;&#1090;&#1086;&#1095;&#1077;&#1095;&#1085;&#1086;&#1081; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1089;&#1074;&#1103;&#1079;&#1100; &#1076;&#1074;&#1091;&#1093; &#1080;&#1083;&#1080; &#1073;&#1086;&#1083;&#1077;&#1077; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1080;&#1084;&#1077;&#1102;&#1097;&#1080;&#1093; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#8212; H.323- &#1080;&#1083;&#1080; SIP-&#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1099;. &#1053;&#1072;&#1088;&#1103;&#1076;&#1091; &#1089; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1072;&#1084;&#1080; &#1080; &#1096;&#1083;&#1102;&#1079;&#1072;&#1084;&#1080;, MCU &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1074; &#1079;&#1086;&#1085;&#1091; &#1089;&#1077;&#1090;&#1080; H.323 &#1080; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089; &#1087;&#1088;&#1080;&#1074;&#1088;&#1072;&#1090;&#1085;&#1080;&#1082;&#1086;&#1084;.
    </p>
    <ul>
      <li>
        &#1076;&#1086;&#1088;&#1086;&#1075;&#1086;&#1077; &#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; ($250K)
      </li>
      <li>
        &#1085;&#1072; &#1086;&#1076;&#1085;&#1086;&#1084; &#1101;&#1082;&#1088;&#1072;&#1085;&#1077; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1086;&#1082;&#1083;&#1072;&#1076;&#1095;&#1080;&#1082;&#1086;&#1074; (&#1086;&#1076;&#1080;&#1085; &#1080;&#1079; &#1085;&#1080;&#1093; &#1082;&#1088;&#1091;&#1087;&#1085;&#1099;&#1084; &#1087;&#1083;&#1072;&#1085;&#1086;&#1084;)
      </li>
    </ul>
    <p>
      <b>VAS&#160;(voice activated switching)</b>
    </p>
    <ul>
