<node TEXT="TDMoE" ID="ID_765591916" CREATED="1537959604697" MODIFIED="1537960728693"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>TDMoE</b>&#160;(Time Division Multiplexing over Ethernet) &#8211; &#1052;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1086;&#1090;&#1086;&#1082;&#1072; &#1089; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1084; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084; &#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077;&#1081; &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1077;&#1090;&#1080; Ethernet -&#160;&#160;&#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1084; &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074; E1, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1077; &#1082;&#1072;&#1076;&#1088;&#1099; &#1080;&#1076;&#1091;&#1090; &#1074; &#1089;&#1090;&#1088;&#1086;&#1075;&#1086; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1085;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1074; &#1089;&#1090;&#1088;&#1086;&#1075;&#1086; &#1086;&#1090;&#1074;&#1077;&#1076;&#1077;&#1085;&#1085;&#1099;&#1081; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1082;. &#1060;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;, &#1101;&#1090;&#1086; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080;&#1074;&#1099;&#1095;&#1085;&#1099;&#1084; &#1045;1 &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1084;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1097;&#1080;&#1084;&#1089;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; Ethernet
    </p>
    <ul>
      <li>
        TDMoE-&#1096;&#1083;&#1102;&#1079;&#1099; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077;
      </li>
      <li>
        &#1050;&#1072;&#1076;&#1088;&#1099; &#1089; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1084; &#1085;&#1077; &#1080;&#1084;&#1077;&#1102;&#1090; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;, &#1072; &#1080;&#1084;&#1077;&#1102;&#1090; &#1083;&#1080;&#1096;&#1100; MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;, &#1095;&#1090;&#1086; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1103; &#1090;&#1072;&#1082;&#1080;&#1093; &#1096;&#1083;&#1102;&#1079;&#1086;&#1074; &#1079;&#1072; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;&#1081; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; Asterisk. &#1064;&#1083;&#1102;&#1079; &#1080; Asterisk &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1099; &#1085;&#1072;&#1087;&#1088;&#1103;&#1084;&#1091;&#1102; &#1074; &#1086;&#1076;&#1080;&#1085; Ethernet-&#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;
      </li>
      <li>
        &#1082; &#1087;&#1086;&#1090;&#1086;&#1082;&#1091; &#1087;&#1088;&#1077;&#1076;&#1098;&#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1095;&#1088;&#1077;&#1079;&#1074;&#1099;&#1095;&#1072;&#1081;&#1085;&#1086; &#1089;&#1090;&#1088;&#1086;&#1075;&#1080;&#1077; &#1090;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1077; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1080; &#1076;&#1078;&#1080;&#1090;&#1090;&#1077;&#1088;&#1091;: &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; 1,5 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;
      </li>
      <li>
        &#1055;&#1088;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; TDMoE, &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1103;&#1103; &#1096;&#1080;&#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; PCI (PCI-Express) &#171;&#1079;&#1072;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103;&#187; &#1085;&#1072; Ethernet-&#1082;&#1072;&#1073;&#1077;&#1083;&#1100;, &#1092;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1103; &#1074;&#1099;&#1085;&#1077;&#1089;&#1090;&#1080; DAHDi-&#1087;&#1086;&#1088;&#1090;&#1099; &#1080;&#1079; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1085;&#1072; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1076;&#1086; 100 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1103; &#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; (&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1085;&#1086;&#1077; &#1083;&#1080;&#1096;&#1100; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100;&#1102; &#1089;&#1077;&#1090;&#1080; &#1080; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;)
      </li>
      <li>
        &#1064;&#1083;&#1102;&#1079;&#1099; TDMoE &#1076;&#1083;&#1103; Asterisk &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1085;&#1080;&#1079;&#1082;&#1086;&#1091;&#1088;&#1086;&#1074;&#1085;&#1077;&#1074;&#1099;&#1084;&#1080; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1084;&#1080;. &#1059;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1089; Asterisk &#1085;&#1072; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1093; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1086;&#1074; <b>DAHDi</b>
      </li>
      <li>
        &#1064;&#1083;&#1102;&#1079; TDMoE &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; &#1084;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;. &#1042; &#1073;&#1072;&#1079;&#1086;&#1074;&#1086;&#1081; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1083;&#1080;&#1096;&#1100; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1077;&#1075;&#1086; &#1052;&#1040;&#1057;-&#1072;&#1076;&#1088;&#1077;&#1089; &#1085;&#1072; Asterisk, &#1095;&#1090;&#1086;&#1073;&#1099; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1091;&#1074;&#1080;&#1076;&#1077;&#1083;&#1080; &#1076;&#1088;&#1091;&#1075; &#1076;&#1088;&#1091;&#1075;&#1072;
      </li>
      <li>
        &#1050; &#1096;&#1083;&#1102;&#1079;&#1091; TDMoE &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; (&#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1079;&#1083;&#1086;&#1084;&#1072;&#1090;&#1100;)
      </li>
      <li>
        &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; TDMoE-&#1087;&#1086;&#1088;&#1090;&#1086;&#1074; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1094;&#1077;&#1083;&#1080;&#1082;&#1086;&#1084; &#1080;&#1079; Asterisk. &#1053;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1074;&#1086;&#1081;&#1085;&#1072;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;: &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1088;&#1072;&#1079; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;, &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#8211; &#1085;&#1072; &#1096;&#1083;&#1102;&#1079;&#1077;, &#1074; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; VoIP-&#1096;&#1083;&#1102;&#1079;&#1086;&#1074;
      </li>
    </ul>
  </body>
</html></richcontent>
