<node TEXT="VoIP" ID="ID_690503955" CREATED="1537259000150" MODIFIED="1539169112914"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1058;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; VoIP</b>&#160;(Voice over IP) - &#1076;&#1083;&#1103; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1076;&#1074;&#1091;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1077;&#1075;&#1086; &#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;. &#1042;&#1089;&#1077; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1099; <b>&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1075;&#1086;&#1083;&#1086;&#1089;&#1072;</b>&#160;&#1095;&#1077;&#1088;&#1077;&#1079; IP, &#1074; &#1090;&#1086;&#1084; &#1095;&#1080;&#1089;&#1083;&#1077; &#1085;&#1077; &#1080;&#1084;&#1077;&#1102;&#1097;&#1080;&#1077; &#1085;&#1080;&#1082;&#1072;&#1082;&#1086;&#1075;&#1086; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103; &#1082; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1080;&#1080; &#1080; &#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1102; &#1083;&#1102;&#1076;&#1077;&#1081;.
    </p>
    <ul>
      <li>
        &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1079;&#1074;&#1091;&#1082;&#1072; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1093; IP-&#1074;&#1080;&#1076;&#1077;&#1086;&#1085;&#1072;&#1073;&#1083;&#1102;&#1076;&#1077;&#1085;&#1080;&#1103;, &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1093; &#1086;&#1087;&#1086;&#1074;&#1077;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1088;&#1080; &#1090;&#1088;&#1072;&#1085;&#1089;&#1083;&#1103;&#1094;&#1080;&#1080; &#1074;&#1077;&#1073;&#1080;&#1085;&#1072;&#1088;&#1086;&#1074;, &#1087;&#1088;&#1080; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077; &#1092;&#1080;&#1083;&#1100;&#1084;&#1086;&#1074; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1086;&#1085;&#1083;&#1072;&#1081;&#1085; &#1080; &#1090;. &#1087;.
      </li>
      <li>
        &#1084;&#1077;&#1090;&#1086;&#1076; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; - &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; UDP &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074;
      </li>
    </ul>
    <p>
      <b>Softswitch</b>&#160;&#8212; &#1101;&#1090;&#1086; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1077;&#1090;&#1100;&#1102; NGN, &#1087;&#1088;&#1080;&#1079;&#1074;&#1072;&#1085;&#1085;&#1086;&#1077; &#1086;&#1090;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080; &#1086;&#1090; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1080;, &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1077; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074; &#1080; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1084;&#1080; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1081;, &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1103; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1077; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1099;. <b>NGN</b>&#160;(next generation networks, new generation networks &#8212; &#1089;&#1077;&#1090;&#1080; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086;/&#1085;&#1086;&#1074;&#1086;&#1075;&#1086; &#1087;&#1086;&#1082;&#1086;&#1083;&#1077;&#1085;&#1080;&#1103;) &#8212; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1085;&#1099;&#1077; &#1089;&#1077;&#1090;&#1080; &#1089;&#1074;&#1103;&#1079;&#1080;, &#1103;&#1076;&#1088;&#1086;&#1084; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1086;&#1087;&#1086;&#1088;&#1085;&#1099;&#1077; IP-&#1089;&#1077;&#1090;&#1080;, &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1097;&#1080;&#1077; &#1087;&#1086;&#1083;&#1085;&#1091;&#1102; &#1080;&#1083;&#1080; &#1095;&#1072;&#1089;&#1090;&#1080;&#1095;&#1085;&#1091;&#1102; &#1080;&#1085;&#1090;&#1077;&#1075;&#1088;&#1072;&#1094;&#1080;&#1102; &#1091;&#1089;&#1083;&#1091;&#1075; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1088;&#1077;&#1095;&#1080;, &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1084;&#1077;&#1076;&#1080;&#1072;. &#1056;&#1077;&#1072;&#1083;&#1080;&#1079;&#1091;&#1077;&#1090; &#1087;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1082;&#1086;&#1085;&#1074;&#1077;&#1088;&#1075;&#1077;&#1085;&#1094;&#1080;&#1080; &#1091;&#1089;&#1083;&#1091;&#1075; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1089;&#1074;&#1103;&#1079;&#1080;.
    </p>
    <ul>
      <li>
