<node TEXT="Основные функции" ID="ID_1412774042" CREATED="1537356751733" MODIFIED="1539596621734"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>Auto Attendant</b>&#160;&#8212; &#1072;&#1074;&#1090;&#1086;&#1089;&#1077;&#1082;&#1088;&#1077;&#1090;&#1072;&#1088;&#1100;
    </p>
    <p>
      <b>Outbound Dialer</b>&#160;&#8212; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1076;&#1086;&#1079;&#1074;&#1086;&#1085;&#1072; &#1076;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072;
    </p>
    <p>
      <b>Call Blocking</b>&#160;&#8212; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1085;&#1077;&#1078;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;
    </p>
    <p>
      <b>Call Detail Records</b>&#160;&#8212; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1086; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;&#1093; &#1074; CDR-&#1092;&#1072;&#1081;&#1083; &#1080;&#1083;&#1080; &#1074; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
    </p>
    <p>
      <b>Call Forwarding</b>&#160;&#8212; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;
    </p>
    <p>
      <b>Call Pick-up</b>&#160;&#8212; &#1087;&#1077;&#1088;&#1077;&#1093;&#1074;&#1072;&#1090; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;
    </p>
    <p>
      <b>Call Queuing</b>&#160;&#8212; &#1087;&#1086;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100;
    </p>
    <p>
      <b>Call Transfer</b>&#160;&#8212; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;
    </p>
    <p>
      <b>Call Waiting</b>&#160;&#8212; &#1088;&#1077;&#1078;&#1080;&#1084; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; &#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1077;&#1089;&#1083;&#1080; &#1083;&#1080;&#1085;&#1080;&#1103; &#1079;&#1072;&#1085;&#1103;&#1090;&#1072;
    </p>
    <p>
      <b>Caller ID</b>&#160;&#8212; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072;
    </p>
    <p>
      <b>Conferencing</b>&#160;&#8212; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;-&#1089;&#1074;&#1103;&#1079;&#1100;
    </p>
    <p>
      <b>Conversation Recording</b>&#160;&#8212; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1086;&#1074;
    </p>
    <p>
      <b>Interactive Voice Response (IVR)</b>&#160;&#8212; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1099;&#1093; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1093; &#1084;&#1077;&#1085;&#1102;. &#1055;&#1088;&#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072;&#1093; &#1087;&#1086; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1084; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;&#1084; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1074;&#1099;&#1073;&#1086;&#1088; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1077;&#1084; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072;, &#1090;&#1077;&#1084; &#1089;&#1072;&#1084;&#1099;&#1084; &#1080;&#1079;&#1073;&#1072;&#1074;&#1083;&#1103;&#1103; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1086;&#1090; &#1088;&#1091;&#1090;&#1080;&#1085;&#1085;&#1086;&#1081; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099;.
    </p>
    <p>
      <b>Music On Hold</b>&#160;&#8212; &#1084;&#1091;&#1079;&#1099;&#1082;&#1072; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1103;
    </p>
    <p>
      <b>Protocol Bridging</b>&#160;&#8212; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1072;&#1103; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074; &#1089;&#1077;&#1090;&#1103;&#1093; &#1084;&#1077;&#1078;&#1076;&#1091; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084;&#1080; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072;&#1084;&#1080;
    </p>
    <p>
      <b>Voicemail System</b>&#160;&#8212; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1072;&#1103; &#1087;&#1086;&#1095;&#1090;&#1072;
    </p>
  </body>
</html></richcontent>
