<node TEXT="Дополнительные функции" ID="ID_577307400" CREATED="1537357066626" MODIFIED="1539785221829"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <!--
        body { font-family: SansSerif; font-size: 10pt; color: #000000; text-align: left }
        p { margin-top: 0 }
      -->
    

    <p type="text/css">
      <b>&#1044;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077;</b>
    </p>
    <p>
      <b>ACD Features</b>&#160;&#8212; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1103; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;; &#1087;&#1077;&#1085;&#1072;&#1083;&#1100;&#1090;&#1080;; &#1080;&#1083;&#1080; &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1089;&#1072;&#1084;&#1099;&#1081; &#1083;&#1077;&#1085;&#1080;&#1074;&#1099;&#1081;)
    </p>
    <p>
      <b>Advanced User Interface</b>&#160;&#8212; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1089; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103;&#1084;&#1080;: Find me, Follow Me, Unified Messaging, Call recordings, Voicemail .wav &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;&#1102; &#1080;&#1089;&#1090;&#1086;&#1088;&#1080;&#1080; &#1087;&#1077;&#1088;&#1089;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1083;&#1086;&#1075;&#1086;&#1074; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;
    </p>
    <p>
      <b>Analog and Digital T1 Ready</b>
    </p>
    <p>
      <b>Analog Phone Support</b>&#160;&#8212; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1099;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1087;&#1091;&#1090;&#1105;&#1084; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1096;&#1083;&#1102;&#1079;
    </p>
    <p>
      <b>ANI Routing</b>&#160;&#8212; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1086; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1080;&#1074;&#1096;&#1077;&#1084; &#1079;&#1074;&#1086;&#1085;&#1082;&#1077; &#8212; Automatic Number Identification (ANI), &#1095;&#1072;&#1097;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;, &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1080;&#1083; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082;, &#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;, &#1086;&#1089;&#1085;&#1086;&#1074;&#1099;&#1074;&#1072;&#1103;&#1089;&#1100; &#1085;&#1072; ANI
    </p>
    <p>
      <b>Announcement Interface</b>&#160;&#8212; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1087;&#1088;&#1080;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1081; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1087;&#1088;&#1080;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1087;&#1088;&#1080; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1084; &#1079;&#1074;&#1086;&#1085;&#1082;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1084; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1080; &#1076;&#1083;&#1103; &#1085;&#1077;&#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1075;&#1086; &#1080; &#1074;&#1099;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093;/&#1087;&#1088;&#1072;&#1079;&#1076;&#1085;&#1080;&#1095;&#1085;&#1099;&#1093; &#1076;&#1085;&#1077;&#1081;
    </p>
    <p>
