    </p>
    <p>
      <b>Intuitive VoIP Ready</b>&#160;&#8212; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;&#1084;, &#1085;&#1077;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086; &#1086;&#1090; &#1080;&#1093; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1074; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;. &#1042;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1099;&#1093; &#1083;&#1080;&#1085;&#1080;&#1081; &#1085;&#1072; &#1085;&#1077;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;
    </p>
    <p>
      <b>Least Cost Routing (LCR)</b>&#160;&#8212; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099;&#1093; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1087;&#1086; &#1082;&#1088;&#1080;&#1090;&#1077;&#1088;&#1080;&#1102; &#1085;&#1072;&#1080;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1081; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080;
    </p>
    <p>
      <b>Multiple Music on Hold</b>&#160;&#8212; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1086;&#1076;&#1085;&#1091; &#1082;&#1086;&#1084;&#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1102;, &#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1086;&#1074; &#1084;&#1091;&#1079;&#1099;&#1082;&#1080; &#1074; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1080;, &#1074;&#1087;&#1083;&#1086;&#1090;&#1100; &#1076;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1084;&#1091;&#1079;&#1099;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1073;&#1080;&#1073;&#1083;&#1080;&#1086;&#1090;&#1077;&#1082;&#1080; &#1080;&#1083;&#1080; &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074;&#1086;&#1075;&#1086; &#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;-&#1088;&#1072;&#1076;&#1080;&#1086;
    </p>
    <p>
      <b>Multivendor Phone Options</b>&#160;&#8212; &#1086;&#1087;&#1094;&#1080;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1080;&#1080;
    </p>
    <p>
      <b>NIS Routing</b>&#160;&#8212; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1081; &#1089;&#1083;&#1091;&#1078;&#1073;&#1099; (&#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; NIS)
    </p>
    <p>
      <b>On the Fly Recording</b>&#160;&#8212; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1072;
    </p>
    <p>
      <b>Operator Console</b>&#160;&#8212; &#1087;&#1091;&#1083;&#1100;&#1090; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;
    </p>
    <p>
      <b>Outbound Dial Map</b>&#160;&#8212; &#1074;&#1080;&#1079;&#1091;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      <b>Outlook Integration</b>&#160;&#8212; &#1080;&#1085;&#1090;&#1077;&#1075;&#1088;&#1072;&#1094;&#1080;&#1103; &#1089; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1084; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1084; Outlook
    </p>
    <p>
      <b>Overhead Paging</b>&#160;&#8212; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1072;&#1103; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1085;&#1080;&#1082;&#1086;&#1074; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099;, &#1080;&#1084;&#1077;&#1102;&#1097;&#1080;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102; &#1075;&#1088;&#1086;&#1084;&#1082;&#1086;&#1081; &#1089;&#1074;&#1103;&#1079;&#1080; (Hand free)
    </p>
    <p>
      <b>Powerful Reporting</b>&#160;&#8212; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1089;&#1073;&#1086;&#1088;&#1072; &#1086;&#1090;&#1095;&#1105;&#1090;&#1086;&#1074; &#1086; &#1089;&#1086;&#1074;&#1077;&#1088;&#1096;&#1080;&#1074;&#1096;&#1080;&#1093;&#1089;&#1103; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;&#1093;
    </p>
    <p>
      <b>PSTN or Digital Failover</b>&#160;&#8212; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1076;&#1091;&#1073;&#1083;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1099;: &#1085;&#1072; &#1085;&#1072;&#1079;&#1077;&#1084;&#1085;&#1091;&#1102; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1091;&#1102; &#1089;&#1074;&#1103;&#1079;&#1100; &#1080;&#1083;&#1080; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1099;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1099;
    </p>
    <p>
      <b>Remote Linked Servers</b>&#160;&#8212; &#1089;&#1074;&#1103;&#1079;&#1100; &#1089; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1084;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1084;&#1080;
    </p>
    <p>
      <b>Remote Phones</b>&#160;&#8212; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;
    </p>
    <p>
      <b>SMS Voicemail notification</b>&#160;&#8212; SMS &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1080; &#1085;&#1086;&#1074;&#1086;&#1075;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099;
    </p>
    <p>
      <b>Speed Dial Numbers</b>&#160;&#8212; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080; &#1087;&#1077;&#1088;&#1089;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1086;&#1082;&#1088;&#1072;&#1097;&#1105;&#1085;&#1085;&#1099;&#1093; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; &#1076;&#1083;&#1103; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;&#1075;&#1086; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072;
    </p>
    <p>
      <b>System Diagnositcs</b>&#160;&#8212; &#1076;&#1080;&#1072;&#1075;&#1085;&#1086;&#1089;&#1090;&#1080;&#1082;&#1072; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1072; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1080; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1093;
    </p>
    <p>
      <b>Time of Day Routing</b>&#160;&#8212; &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1089;&#1091;&#1090;&#1086;&#1082;
    </p>
    <p>
      <b>Unified Messaging</b>&#160;&#8212; &#1080;&#1085;&#1090;&#1077;&#1075;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; (&#1082;&#1086;&#1085;&#1094;&#1077;&#1087;&#1094;&#1080;&#1103; &#1089;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1080;&#1080;, &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1074;&#1089;&#1077; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1099;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;, &#1074;&#1099;&#1079;&#1086;&#1074;&#1099; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1085;&#1085;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099; &#1080; &#1092;&#1072;&#1082;&#1089;&#1080;&#1084;&#1080;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1074;&#1103;&#1079;&#1080; &#1089;&#1086;&#1089;&#1088;&#1077;&#1076;&#1086;&#1090;&#1086;&#1095;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1077;&#1076;&#1080;&#1085;&#1086;&#1084; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1085;&#1086;&#1084; &#1101;&#1082;&#1088;&#1072;&#1085;&#1077;)
    </p>
    <p>
      <b>Unlimited Voicemail Boxes</b>&#160;&#8212; &#1085;&#1077;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1103;&#1097;&#1080;&#1082;&#1086;&#1074; &#1076;&#1083;&#1103; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099;
    </p>
    <p>
      <b>Voicemail Blast Groups</b>&#160;&#8212; &#1077;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074;, &#1101;&#1090;&#1072; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1085;&#1091;&#1078;&#1085;&#1099;&#1093; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; &#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1080;&#1079; &#1085;&#1080;&#1093; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; &#1080; &#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1074;&#1089;&#1077;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1077;
    </p>
    <p>
      <b>Voicemail Bypass</b>&#160;&#8212; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1078;&#1080;&#1074;&#1086;&#1075;&#1086; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072; &#1074; &#1086;&#1073;&#1093;&#1086;&#1076; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099;
    </p>
    <p>
      <b>Voicemail Callback</b>&#160;&#8212; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; Caller ID &#1079;&#1074;&#1086;&#1085;&#1103;&#1097;&#1077;&#1075;&#1086; &#1080; &#1087;&#1077;&#1088;&#1077;&#1079;&#1074;&#1086;&#1085;&#1080;&#1090;&#1100; &#1077;&#1084;&#1091; &#1087;&#1088;&#1103;&#1084;&#1086; &#1080;&#1079; &#1088;&#1077;&#1078;&#1080;&#1084;&#1072; &#1087;&#1088;&#1086;&#1089;&#1083;&#1091;&#1096;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; Voice Mail
    </p>
    <p>
      <b>Voicemail to Email</b>&#160;&#8212; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1072; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1075;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1085;&#1085;&#1091;&#1102; &#1087;&#1086;&#1095;&#1090;&#1091;, VoiceMail to Email &#1080;&#1083;&#1080; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1072;&#1103; &#1087;&#1086;&#1095;&#1090;&#1072;- &#1087;&#1088;&#1080;&#1084;&#1077;&#1090; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1077; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1080; &#1087;&#1077;&#1088;&#1077;&#1096;&#1083;&#1077;&#1090; &#1077;&#1075;&#1086; &#1085;&#1072; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1081; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1084; IP-&#1040;&#1058;&#1057; &#1072;&#1076;&#1088;&#1077;&#1089; e-mail &#1074; &#1074;&#1080;&#1076;&#1077; &#1074;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; mp3-&#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      <b>Voicemail Web Access</b>&#160;&#8212; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; &#1074;&#1077;&#1073;-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
    <p>
      <b>VoIP Compression</b>&#160;&#8212; &#1093;&#1072;&#1088;&#1072;&#1082;&#1090;&#1077;&#1088;&#1080;&#1079;&#1091;&#1077;&#1090; &#1089;&#1078;&#1072;&#1090;&#1080;&#1077; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072; VoIP, &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1082;&#1086;&#1076;&#1077;&#1082;&#1072;
    </p>
    <p>
      <b>VoIP Ready</b>&#160;&#8212; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; &#1083;&#1102;&#1073;&#1086;&#1084;&#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1091; &#1080;&#1079; &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1093; VoIP-&#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074;, &#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1091;&#1090;&#1086;&#1095;&#1085;&#1103;&#1090;&#1100; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1083;&#1080; &#1086;&#1085; SIP-&#1079;&#1074;&#1086;&#1085;&#1082;&#1080;
    </p>
  </body>
</html></richcontent>
