    <p>
      <b>&#1042;&#1072;&#1088;&#1080;&#1072;&#1094;&#1080;&#1103; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; (&#1076;&#1078;&#1080;&#1090;&#1090;&#1077;&#1088;)&#160;&#160;(jitter - &#1076;&#1088;&#1086;&#1078;&#1072;&#1085;&#1080;&#1077;)</b>&#160; &#1080;&#1083;&#1080; &#1092;&#1072;&#1079;&#1086;&#1074;&#1086;&#1077; &#1076;&#1088;&#1086;&#1078;&#1072;&#1085;&#1080;&#1077; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1086;&#1075;&#1086; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; - &#1088;&#1072;&#1079;&#1085;&#1080;&#1094;&#1072; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1087;&#1088;&#1086;&#1093;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080; (&#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1091;&#1090;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086; &#1076;&#1086;&#1088;&#1086;&#1075;&#1077;)&#160;- &#1088;&#1072;&#1079;&#1085;&#1080;&#1094;&#1072; &#1074; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072;&#1093;
