    <p>
      <b>&#1055;&#1086;&#1090;&#1077;&#1088;&#1103; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;</b>. &#1055;&#1086;&#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1075;&#1076;&#1072; &#1087;&#1086;&#1083;&#1086;&#1089;&#1099; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086;. &#1045;&#1089;&#1083;&#1080; &#1073;&#1086;&#1083;&#1077;&#1077; 5% - &#1073;&#1091;&#1083;&#1100;&#1082;&#1072;&#1085;&#1080;&#1077;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1093;&#1086;&#1088;&#1086;&#1096;&#1080;&#1084; &#1082;&#1086;&#1076;&#1077;&#1082;&#1086;&#1084;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1082;&#1086;&#1084;&#1087;&#1077;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1090;&#1077;&#1088;&#1102; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;
