      <li>
        &#1072;&#1082;&#1091;&#1089;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1101;&#1093;&#1086; -&#8220;&#1079;&#1072;&#1074;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077;&#8221;, &#1080;&#1083;&#1080; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090; &#1051;&#1072;&#1088;&#1089;&#1077;&#1085;&#1072; - &#1082;&#1086;&#1075;&#1076;&#1072; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082; &#1080; &#1087;&#1088;&#1080;&#1077;&#1084;&#1085;&#1080;&#1082; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1088;&#1103;&#1076;&#1086;&#1084; &#1080; &#1079;&#1074;&#1091;&#1082; &#1093;&#1086;&#1076;&#1080;&#1090; &#1087;&#1086; &#1082;&#1088;&#1091;&#1075;&#1091;. &#1054;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077; &#1087;&#1088;&#1080; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1081;
