<node TEXT="MANGO OFFICE" ID="ID_1671543682" CREATED="1537512208613" MODIFIED="1537512836187"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      https://www.mango-office.ru/
    </p>
    <p>
      
    </p>
    <p>
      <b>&#171;&#1052;&#1072;&#1085;&#1075;&#1086; &#1058;&#1077;&#1083;&#1077;&#1082;&#1084;&#187; </b>&#8212; &#1088;&#1086;&#1089;&#1089;&#1080;&#1081;&#1089;&#1082;&#1072;&#1103; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1103;, &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1074; 2000 &#1075;&#1086;&#1076;&#1091;. &#1055;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1091;&#1089;&#1083;&#1091;&#1075;&#1080; &#1086;&#1073;&#1083;&#1072;&#1095;&#1085;&#1099;&#1093; &#1082;&#1086;&#1084;&#1084;&#1091;&#1085;&#1080;&#1082;&#1072;&#1094;&#1080;&#1081; &#1076;&#1083;&#1103; &#1073;&#1080;&#1079;&#1085;&#1077;&#1089;&#1072; &#1087;&#1086;&#1076; &#1090;&#1086;&#1088;&#1075;&#1086;&#1074;&#1086;&#1081; &#1084;&#1072;&#1088;&#1082;&#1086;&#1081; <b>MANGO OFFICE</b>. &#1054;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1073;&#1086;&#1083;&#1077;&#1077; 45,000 &#1087;&#1088;&#1077;&#1076;&#1087;&#1088;&#1080;&#1103;&#1090;&#1080;&#1081; &#1074; 55 &#1075;&#1086;&#1088;&#1086;&#1076;&#1072;&#1093; &#1056;&#1086;&#1089;&#1089;&#1080;&#1080; &#1080; &#1085;&#1072; &#1090;&#1077;&#1088;&#1088;&#1080;&#1090;&#1086;&#1088;&#1080;&#1080; &#1043;&#1077;&#1088;&#1084;&#1072;&#1085;&#1080;&#1080;. &#1064;&#1090;&#1072;&#1073;-&#1082;&#1074;&#1072;&#1088;&#1090;&#1080;&#1088;&#1072; &#171;&#1052;&#1072;&#1085;&#1075;&#1086; &#1058;&#1077;&#1083;&#1077;&#1082;&#1086;&#1084;&#187; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074; &#1052;&#1086;&#1089;&#1082;&#1074;&#1077;, &#1086;&#1092;&#1080;&#1089;&#1099; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1074; 22 &#1088;&#1086;&#1089;&#1089;&#1080;&#1081;&#1089;&#1082;&#1080;&#1093; &#1075;&#1086;&#1088;&#1086;&#1076;&#1072;&#1093;, &#1077;&#1074;&#1088;&#1086;&#1087;&#1077;&#1081;&#1089;&#1082;&#1080;&#1081; &#1086;&#1092;&#1080;&#1089; &#8212; &#1074; &#1041;&#1077;&#1088;&#1083;&#1080;&#1085;&#1077;.
    </p>
    <p>
      
    </p>
    <p>
      &#1051;&#1080;&#1076;&#1077;&#1088; &#1088;&#1086;&#1089;&#1089;&#1080;&#1081;&#1089;&#1082;&#1086;&#1075;&#1086; &#1088;&#1099;&#1085;&#1082;&#1072; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1040;&#1058;&#1057; (&#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#171;&#1058;&#1052;&#1058; &#1050;&#1086;&#1085;&#1089;&#1072;&#1083;&#1090;&#1080;&#1085;&#1075;&#187;)[1], &#1090;&#1072;&#1082;&#1078;&#1077; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; &#1095;&#1080;&#1089;&#1083;&#1086; &#1082;&#1088;&#1091;&#1087;&#1085;&#1077;&#1081;&#1096;&#1080;&#1093; &#1090;&#1077;&#1083;&#1077;&#1082;&#1086;&#1084;&#1084;&#1091;&#1085;&#1080;&#1082;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1093; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1081; &#1056;&#1086;&#1089;&#1089;&#1080;&#1080;[2] &#1080; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1086;&#1076;&#1085;&#1080;&#1084; &#1080;&#1079; &#1082;&#1088;&#1091;&#1087;&#1085;&#1077;&#1081;&#1096;&#1080;&#1093; &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1097;&#1080;&#1082;&#1086;&#1074; SaaS-&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1081;[3], &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1103; &#1074; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1086;&#1090;&#1088;&#1072;&#1089;&#1083;&#1077;&#1074;&#1086;&#1084; &#1088;&#1077;&#1081;&#1090;&#1080;&#1085;&#1075;&#1077; &#1086;&#1073;&#1083;&#1072;&#1095;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074; &#1074;&#1099;&#1089;&#1096;&#1091;&#1102; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1102; &#1089;&#1088;&#1077;&#1076;&#1080; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1081;, &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1093; &#1082;&#1086;&#1084;&#1084;&#1091;&#1085;&#1080;&#1082;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1077; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1099;.
    </p>
  </body>
</html></richcontent>
