<node TEXT="1. Подготовка" ID="ID_1517257071" CREATED="1538043626472" MODIFIED="1540459131020"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; SELINUX. </b>&#160;--&gt; reboot
    </p>
    <p>
      <font color="#0000c0">vi /etc/selinux/config</font><b>&#160;</b>
    </p>
    <p>
      <font color="#008000">SELINUX=disabled</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>2. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1091;</b>
    </p>
    <p>
      <font color="#0000c0">vi /etc/sysconfig/network-scripts/ifcfg-eth0</font>&#160;
    </p>
    <p>
      <font color="#008000">ONBOOT=yes</font>
    </p>
    <p>
      <font color="#0000c0">/etc/init.d/network restart</font>&#160;&#160;# ip-&#1072;&#1076;&#1088;&#1077;&#1089; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;
    </p>
    <p>
      <font color="#0000c0">ping &lt;ip-address&gt;</font>&#160;&#160;# &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1087;&#1080;&#1085;&#1075;&#1086;&#1084;
    </p>
    <p>
      
    </p>
    <p>
      <b>3. &#1054;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; + sqlite-devel, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; Asterisk 11 &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; SQLite3</b>
    </p>
    <p>
      <font color="#0000c0">yum update &#8211;y &amp;&amp; reboot</font>&#160;&#160;# &#1054;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103;
    </p>
    <p>
      <font color="#0000c0">yum install &#8211;y make wget openssl-devel ncurses-devel newt-devel libxml2-devel kernel-devel gcc gcc-c++ sqlite-devel </font>
    </p>
    <p>
      ??? yum install &#8211;y ntp sshd vsftpd xinetd tftp tftp-server &amp;&amp; ntpdate pool.ntp.org newt-devel&#160;kernel-devel&#160;libuuid-devel perl gcc&#160;gcc-c++&#160;make wget subversion libxml2-devel&#160;ncurses-devel openssl-devel&#160;vim-enhanced sqlite-devel
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#ff0000">??? &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1099; &#1074; &#1072;&#1074;&#1090;&#1086;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;</font></b>
    </p>
    <p>
      <font color="#0000c0">chkconfig ntpd on</font>&#160;&#160;# &#1057;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;
    </p>
    <p>
      <font color="#0000c0">chkconfig sshd on</font>&#160;&#160;#
    </p>
    <p>
      <font color="#0000c0">chkconfig vsftpd on</font>&#160;&#160;# sftp-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;
    </p>
    <p>
      <font color="#0000c0">chkconfig xinetd on</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="2. DAHDI" ID="ID_451665549" CREATED="1538043637941" MODIFIED="1540410115225"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; DAHDI</b>&#160;&#160;- &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1083;&#1072;&#1090; (<a href="#ID_1000991110">PRI</a>, <a href="#ID_5265467">FXS, FXO</a>, &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1099;&#1093; &#1080;&#1083;&#1080; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1099;&#1093; &#1082;&#1072;&#1088;&#1090; &#1087;&#1086; PCI &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091; &#1082; Asterisk &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1086;&#1084;&#1091; &#1085;&#1072; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;)
    </p>
    <ul>
      <li>
        &#1074; Asterisk 11, &#1077;&#1089;&#1083;&#1080; &#1087;&#1083;&#1072;&#1090; &#1085;&#1077;&#1090;, &#1090;&#1086; dahdi &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086;. &#1056;&#1077;&#1085;&#1077;&#1077; &#1090;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1083;&#1086;&#1089;&#1100; &#1076;&#1083;&#1103; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1081;.
      </li>
    </ul>
    <p>
      <b><font color="#ff0000">???. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1076;&#1086;&#1087;. &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1099; &#1103;&#1076;&#1088;&#1072;</font></b>
    </p>
    <p>
      <font color="#0000c0">uname &#8211;r</font>&#160;&#160;# &#1055;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1090;&#1086;&#1095;&#1085;&#1091;&#1102; &#1074;&#1077;&#1088;&#1089;&#1080;&#1102; &#1103;&#1076;&#1088;&#1072;
    </p>
    <p>
      <font size="1">2.6.32-358.2.1.el6.i686</font>
    </p>
    <p>
      <font color="#0000c0">yum install kernel-devel-`uname -r`</font>&#160;&#160;# &#1048;&#1083;&#1080;
    </p>
    <p>
      <font color="#0000c0">yum install &quot;kernel-devel-uname-r == $(uname -r)&quot;</font>&#160;&#160;# &#1048;&#1083;&#1080;
    </p>
    <p>
      <font color="#0000c0">yum install kernel-devel-2.6.32-358.2.1.el6.i686</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>2. C&#1082;&#1072;&#1095;&#1072;&#1090;&#1100; DAHDI &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;</b>
    </p>
    <p>
      <font color="#0000c0"># cd /usr/src/</font>
    </p>
    <p>
      <font color="#0000c0"># wget http://downloads.asterisk.org/pub/telephony/dahdi-linux-complete/dahdi-linux-complete_2.6.1.tar.gz</font>
    </p>
    <p>
      <font color="#0000c0"># tar zxvf dahdi-linux-complete_2.6.1.tar.gz</font>
    </p>
    <p>
      <font color="#0000c0"># cd dahdi-linux-complete-2.6.1+2.6.1</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>3. &#1057;&#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;</b>
    </p>
    <p>
      <font color="#0000c0"># make</font>
    </p>
    <p>
      <font color="#0000c0"># make install </font>
    </p>
    <p>
      <font color="#0000c0"># make config</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>4. &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; DAHDI.</b><font color="#ff0000">&#160; &#1045;&#1089;&#1083;&#1080; &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072; &#1085;&#1077;&#1090;, &#1079;&#1085;&#1072;&#1095;&#1080;&#1090; &#1087;&#1088;&#1086;&#1073;&#1091;&#1077;&#1084; &#1073;&#1086;&#1083;&#1077;&#1077; &#1089;&#1090;&#1072;&#1088;&#1091;&#1102; &#1074;&#1077;&#1088;&#1089;&#1080;&#1102; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1080;&#1082;&#1086;&#1074; </font>
    </p>
    <p>
      <font color="#0000c0"># /etc/init.d/dahdi start</font>
    </p>
    <p>
      <font color="#0000c0"># service dahdi start</font>
    </p>
    <p>
      <font color="#0000c0"># chkconfig dahdi on</font>&#160;&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074; &#1072;&#1074;&#1090;&#1086;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;
    </p>
    <p>
      <font color="#0000c0"># lsmod | grep dahdi</font>&#160;&#160;# &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085; &#1083;&#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; DAHDI &#1074; &#1103;&#1076;&#1088;&#1086; &#1054;&#1057;
    </p>
    <p>
      <font color="#0000c0"># chkconfig --list | grep dahdi </font>&#160;# &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;. &#1045;&#1089;&#1090;&#1100; &#1083;&#1080; &#1074; &#1072;&#1074;&#1090;&#1086;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="3. LibPRI" ID="ID_836706879" CREATED="1538043632367" MODIFIED="1538308545547"><richcontent TYPE="NOTE">
