<node TEXT="4. Asterisk" ID="ID_1538986444" CREATED="1538043644003" MODIFIED="1539173030179"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. C&#1082;&#1072;&#1095;&#1072;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; Asterisk</b>
    </p>
    <p>
      <font color="#0000c0">cd /usr/src/</font>
    </p>
    <p>
      <font color="#0000c0">wget http://downloads.asterisk.org/pub/telephony/certified-asterisk/releases/certified-asterisk-11.6-cert11.tar.gz</font>
    </p>
    <p>
      <font color="#0000c0">tar xvf certified-asterisk-11.6-cert11.tar.gz</font>
    </p>
    <p>
      <font color="#0000c0">cd cer*</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>2. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1077;&#1081; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072;.</b>&#160;&#1057; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1099; Menuselect &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1077; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1099; &#1076;&#1083;&#1103; Asterisk.
    </p>
    <p>
      <font color="#0000c0">./configure --libdir=/usr/lib64 &amp;&amp; make <b>menuselect</b>&#160;&amp;&amp; make &amp;&amp; make install&#160;</font>&#160;# &#160;<b>64bit CentOS</b>
    </p>
    <p>
      <font color="#0000c0">./configure &amp;&amp; make menuselect &amp;&amp; make &amp;&amp; make install</font>&#160;&#160;# <b>32bit CentOS</b>
    </p>
    <p>
      <font color="#0000c0">make samples</font><font color="#000000">&#160;&#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1085;&#1099;&#1077; &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;&#1099; &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; <b>/etc/asterisk</b>&#160;--&gt; &#1058;&#1072;&#1084; &#1078;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1087;&#1082;&#1091; <b>default</b>&#160;&#1080; &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1091;&#1076;&#1072; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1099;</font>
    </p>
    <p>
      <font color="#0000c0">make config</font>&#160;&#160;# /etc/init.d/
    </p>
    <p>
      
    </p>
    <p>
      /etc/init.d/asterisk start
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      -----------------------------------
    </p>
    <p>
      Optional: If you ran into errors you will want to clean the install directory before recompiling.
    </p>
    <p>
      make clean &amp;&amp; make distclean
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="5. Запуск" ID="ID_788123639" CREATED="1538308445674" MODIFIED="1539343084622"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1047;&#1072;&#1087;&#1091;&#1089;&#1082;</b>
    </p>
    <p>
      <font color="#0000c0"># chkconfig asterisk on</font>&#160;&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; Asterisk &#1074; &#1072;&#1074;&#1090;&#1086;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;
    </p>
    <p>
      <font color="#0000c0"># asterisk</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; Asterisk &#1074; &#1092;&#1086;&#1085;&#1077;
    </p>
    <p>
      <font color="#0000c0"># safe_asterisk</font>&#160;&#160;# &#1041;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1099;&#1081; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;. &#1045;&#1089;&#1083;&#1080; Asterisk &#1091;&#1087;&#1072;&#1076;&#1077;&#1090;, &#1090;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1072;&#1074;&#1090;. &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;
    </p>
    <p>
      <font color="#0000c0">&gt; core stop now</font>&#160;&#160;# &#1054;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      <a href="#ID_612352976"><b><font color="#000000">&#1050;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;</font></b></a>
    </p>
    <p>
      <font color="#0000c0"># asterisk &#8211;r</font>&#160;&#160;# &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080; Asterisk
    </p>
    <p>
      <font color="#0000c0"># asterisk -rx '&lt;&#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072;&gt;'</font>&#160; # &#1055;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1100; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100; Asterisk
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1076;&#1083;&#1103; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; Asterisk</b>
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-c</b>: &#1050;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1085;&#1077; &#1091;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084; &#1092;&#1086;&#1085;&#1086;&#1074;&#1086;&#1075;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; CLI &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100; (&#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1091;&#1084;&#1077;&#1074;&#1072;&#1077;&#1090; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; -f). Asterisk &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090; &#1087;&#1088;&#1080; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1080;&#1080; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-C</b>&#160;: &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; Asterisk, &#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-d</b>: &#1056;&#1077;&#1078;&#1080;&#1084; &#1086;&#1090;&#1083;&#1072;&#1076;&#1082;&#1080; (Debug)
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-f</b>: &#1053;&#1077; &#1091;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1074; &#1092;&#1086;&#1085;&#1086;&#1074;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-g</b>: &#1057;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; core, &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1085;&#1077;&#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1085;&#1086;&#1075;&#1086; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1077;&#1085;&#1080;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099;
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-h</b>: &#1042;&#1099;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100; (&#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1074;&#1089;&#1077;&#1093; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;).
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-i</b>: &#1055;&#1088;&#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077;, &#1080;&#1085;&#1080;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1083;&#1102;&#1095;&#1080; &#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; (crypto keys)
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-p</b>: &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; pseudo-realtime thread
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-q</b>: &#1056;&#1077;&#1078;&#1080;&#1084; &quot;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1103;&quot; (Quiet mode) &#1087;&#1086;&#1076;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074;&#1099;&#1074;&#1086;&#1076;&#1072; &#1074; stderr/stdin
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-v</b>: &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1076;&#1083;&#1103; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1086;&#1073;&#1098;&#1077;&#1084;&#1072; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1084;&#1086;&#1081; &#1086;&#1090;&#1083;&#1072;&#1076;&#1086;&#1095;&#1085;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;. &#1063;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1079;&#1072;&#1076;&#1072;&#1085;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; 'v' - &#1090;&#1077;&#1084; &#1073;&#1086;&#1083;&#1077;&#1077; &#1076;&#1077;&#1090;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103;.
    </p>
    <p>
      <b>&#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; &#1091;&#1078;&#1077; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;&#1085;&#1086;&#1084;&#1091; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; Asterisk</b>
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-r</b>: &#1057;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1077;&#1084;&#1089;&#1103; &#1089; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;&#1085;&#1099;&#1084; &#1074; &#1092;&#1086;&#1085;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084; Asterisk, &#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; CLI &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080;
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-x</b>: &#1042; &#1082;&#1086;&#1084;&#1073;&#1080;&#1085;&#1072;&#1094;&#1080;&#1080; &#1089; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1084; -r, &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; CLI Asterisk
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>-n</b>: &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1091; &#1094;&#1074;&#1077;&#1090;&#1085;&#1086;&#1075;&#1086; &#1074;&#1099;&#1074;&#1086;&#1076;&#1072; ANSI
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="6. Первоначальная настройка" ID="ID_977645334" CREATED="1538157703998" MODIFIED="1539698059271"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1074; (</b>&#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072; &#1087;&#1086; SIP-&#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091;)
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1074;</b>
    </p>
    <p>
      <font color="#0000c0">vi /etc/asterisk/<b>sip.conf</b></font>
    </p>
    <p>
      <font color="#008000"># &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072; </font>
    </p>
    <p>
      <font color="#008000">[general] </font>
    </p>
    <p>
      <font color="#008000">[xlite] </font>
    </p>
    <p>
      <font color="#008000">type=friend </font>
    </p>
    <p>
      <font color="#008000">host=dynamic </font>
    </p>
    <p>
      <font color="#008000">secret=111</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>2. &#1053;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1077;&#1083;. &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074;, &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081;.</b>&#160; <a href="#ID_1911092648">Dialplan</a>.
    </p>
    <p>
      <font color="#0000c0">vi /etc/asterisk/<b>extension.conf</b></font>&#160;&#160;#
    </p>
    <p>
      <font color="#008000"># &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072; </font>
    </p>
    <p>
      <font color="#008000">[general] </font>
    </p>
    <p>
      <font color="#008000">[globals] </font>
    </p>
    <p>
      <font color="#008000">[default] </font>
    </p>
    <p>
