      <font color="#0000c0">mysql -uroot &#8211;p(&#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1087;&#1088;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1077; MySQL(mariadb))</font>
