      <font color="#0000c0">firewall-cmd --reload</font>
    </p>
    <p>
      &#1059;&#1073;&#1077;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103;, &#1095;&#1090;&#1086; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1083;&#1080;&#1089;&#1100;:
    </p>
    <p>
      <font color="#0000c0">firewall-cmd --zone=public&#160;&#160;--list-all</font>
    </p>
    <p>
      <font size="1">public (default, active) </font>
    </p>
    <p>
      <font size="1">&#160;&#160;interfaces: eth0 </font>
    </p>
    <p>
      <font size="1">&#160;&#160;sources: </font>
    </p>
    <p>
      <font size="1">&#160;&#160;services: dhcpv6-client ssh </font>
    </p>
    <p>
      <font size="1">&#160;&#160;ports: 80/tcp 5061/tcp 4569/udp 5060/tcp 10000-20000/udp 5061/udp 5060/udp 5038/tcp </font>
    </p>
    <p>
      <font size="1">&#160;&#160;masquerade: no </font>
    </p>
    <p>
      <font size="1">&#160;&#160;forward-ports: </font>
    </p>
    <p>
      <font size="1">&#160;&#160;icmp-blocks: echo-reply echo-request </font>
    </p>
    <p>
      <font size="1">&#160;&#160;rich rules:</font>
    </p>
  </body>
</html></richcontent>
<node TEXT="Troubleshooting" ID="ID_998892850" CREATED="1540836710800" MODIFIED="1540837042977"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font size="2">[CC] format_mp3.c -&gt; format_mp3.o </font>
    </p>
    <p>
      <font size="2">format_mp3.c:39:24: fatal error: mp3/mpg123.h: No such file or directory </font>
    </p>
    <p>
      <font color="#0000c0" size="2">cd /usr/src/asterisk-*/ </font>
    </p>
    <p>
      <font color="#0000c0" size="2">contrib/scripts/get_mp3_source.sh</font>
    </p>
    <p>
      
    </p>
    <p>
      <font size="2">configure: error: *** termcap support not found </font>
    </p>
    <p>
      <font color="#0000c0" size="2">yum install libtermcap-devel</font>
    </p>
    <p>
      
    </p>
    <p>
      <font size="2">configure: *** XML documentation will not be available because the 'libxml2' development package is missing. </font>
    </p>
    <p>
      <font size="2">configure: *** Please run the 'configure' script with the '--disable-xmldoc' parameter option </font>
    </p>
    <p>
      <font size="2">configure: *** or install the 'libxml2' development package. </font>
    </p>
    <p>
      <font color="#0000c0" size="2">yum -y install libxml2-devel</font>
    </p>
    <p>
      
    </p>
    <p>
      <font size="2">Doxygen is not installed. Please install and re-run the configuration script. </font>
    </p>
    <p>
      <font color="#0000c0" size="2">yum -y install doxygen</font>
    </p>
    <p>
      
    </p>
    <p>
      <font size="2">configure: error: *** uuid support not found (this typically means the uuid development package is missing) </font>
    </p>
    <p>
      <font color="#0000c0" size="2">yum -y install libuuid-devel</font>
    </p>
    <p>
      
    </p>
    <p>
      <font size="2">Unable to connect to remote asterisk (does /var/run/asterisk/asterisk.ctl exist?) </font>
    </p>
    <p>
      <font color="#0000c0" size="2">/etc/selinux/config SELINUX=disabledreboot</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
