<node TEXT="Автоответчик" ID="ID_275729357" CREATED="1539599821556" MODIFIED="1540891830930"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_243007138">MixMonitor</a>&#160;&#160;&#160;<a href="#ID_710773895">&#1043;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1072;&#1103; &#1087;&#1086;&#1095;&#1090;&#1072;</a>&#160; &#160;<a href="#ID_1361614273">Audacity</a>&#160;&#160;
    </p>
    <ul>
      <li>
        <p>
          &#1055;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077; <b>Record</b>&#160;&#1086;&#1095;&#1077;&#1085;&#1100; &#1087;&#1086;&#1093;&#1086;&#1078;&#1077; &#1085;&#1072; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077; MixMonitor, &#1085;&#1086; &#1086;&#1085;&#1086; &#1087;&#1088;&#1080; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1074;&#1086;&#1089;&#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; beep, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1076;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1095;&#1080;&#1082;&#1072;
        </p>
      </li>
      <li>
        &#1053;&#1072;&#1081;&#1090;&#1080; &#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1081; &#1087;&#1072;&#1087;&#1082;&#1077; &#1086;&#1073;&#1097;&#1077;&#1075;&#1086; &#1093;&#1088;&#1072;&#1085;&#1080;&#1083;&#1080;&#1097;&#1072;, &#1083;&#1080;&#1073;&#1086; &#1087;&#1088;&#1086;&#1089;&#1083;&#1091;&#1096;&#1072;&#1090;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; <a href="#ID_1045179270">web-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;</a>
      </li>
    </ul>
    <p>
      <font color="#0000c0">$ mkdir /records/voicemail</font>&#160;&#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1076;&#1083;&#1103; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1072;&#1074;&#1090;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1095;&#1080;&#1082;&#1072;
    </p>
    <p>
      <font color="#0000c0">$ mkdir /var/lib/asterisk/moh/voicebox</font>&#160;&#160;# C&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1072;&#1074;&#1090;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1095;&#1080;&#1082;&#1072;
    </p>
    <p>
      <font color="#0000c0">&gt; file convert mymusic.wav mymusic.alaw</font>&#160;&#160;#&#160;&#1047;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1080; &#1087;&#1077;&#1088;&#1077;&#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1086;&#1088;&#1086;&#1078;&#1082;&#1091; WAV (8-bit mino) &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1084; &#1082;&#1086;&#1076;&#1077;&#1082;&#1086;&#1084; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; G.711 A-Law)
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">; /etc/asterisk/extensions.conf</font></b>
    </p>
    <p>
      <font color="#008000">exten =&gt; 1,1,Dial(SIP/2011,30,m&amp;t) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; 1,2,Goto(autoanswer,s,1)&#160;&#160;;</font>&#160;&#1045;&#1089;&#1083;&#1080; 2011 &#1085;&#1077; &#1086;&#1090;&#1074;&#1077;&#1090;&#1080;&#1083;/&#1089;&#1073;&#1088;&#1086;&#1089;&#1080;&#1083; &#1074;&#1099;&#1079;&#1086;&#1074;, &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;. &#1085;&#1072; &#1072;&#1074;&#1090;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1095;&#1080;&#1082;
    </p>
    <p>
      <b><font color="#008000">[autoanswer]</font></b>
    </p>
    <p>
      <font color="#008000">exten =&gt; s,1,Background(/var/lib/asterisk/moh/voicebox/my<b>music</b></font>&#160;&#160;; &#1073;&#1077;&#1079; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;. &#1055;&#1088;&#1080;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1072;&#1074;&#1090;.
    </p>
    <p>
      <font color="#008000">exten =&gt; s,2,Set(fname=${STRFTIME(${EPOCH},,%Y%m%d%H%M)}-${CALLERID(number)}-${EXTEN}) &#160;;</font>&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1080;&#1084;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072; &#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084;&#1086;&#1075;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#008000">exten =&gt; s,3,Record(/records/voicemail/${fname}.wav,0,15,X)</font>&#160;&#160;; &#1047;&#1072;&#1087;&#1080;&#1089;&#1100; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      <font color="#008000">exten =&gt; s,4,Hangup </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Безопасность" FOLDED="true" ID="ID_1682224788" CREATED="1537798148240" MODIFIED="1540030669404"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1079;&#1072;&#1097;&#1080;&#1090;&#1099; &#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1089;&#1103; &#1085;&#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103;&#1093;</b>
    </p>
    <ul>
      <li>
        &#1057;&#1077;&#1090;&#1077;&#1074;&#1072;&#1103; &#1079;&#1072;&#1097;&#1080;&#1090;&#1072; (<a href="#ID_1140070626">iptables</a>).
      </li>
      <li>
        &#1044;&#1080;&#1079;&#1072;&#1081;&#1085; &#1089;&#1077;&#1090;&#1080; (<a href="#ID_107215151">VLAN</a>&#160; + <a href="#ID_1863661389">VPN</a>). &#1058;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1086;&#1090;&#1076;&#1077;&#1083;&#1077;&#1085;&#1086; &#1086;&#1090; &#1087;&#1088;&#1086;&#1095;&#1077;&#1075;&#1086; &#1086;&#1073;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;. &#1044;&#1083;&#1103; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1081; &#1078;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; VPN (&#1054;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1074;&#1089;&#1077;&#1093; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1081; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080; &#1074; &#1086;&#1073;&#1097;&#1091;&#1102; VPN-&#1089;&#1077;&#1090;&#1100;). VPN &#1085;&#1077; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1094;&#1077;&#1083;&#1077;&#1089;&#1086;&#1086;&#1073;&#1088;&#1072;&#1079;&#1085;&#1086; &#1080;&#1079;-&#1079;&#1072; &#1091;&#1090;&#1103;&#1078;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1077;&#1090;&#1080;. &#1051;&#1091;&#1095;&#1096;&#1077; fail2ban+&#1085;&#1077;&#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; &#1087;&#1086;&#1088;&#1090;
      </li>
      <li>
        &#1040;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088; &#1083;&#1086;&#1075;&#1086;&#1074; (<a href="#ID_1662130783">fail2ban</a>). &#1053;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1089;&#1083;&#1077;&#1076;&#1080;&#1090;&#1100;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077; &#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &#1087;&#1086;&#1087;&#1099;&#1090;&#1086;&#1082; &#1087;&#1086;&#1076;&#1073;&#1086;&#1088;&#1072; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1081;, &#1092;&#1077;&#1081;&#1082;&#1086;&#1074;&#1099;&#1093; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1081;
      </li>
      <li>
        &#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; Linux
      </li>
      <li>
        &#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; Asterisk
      </li>
      <li>
        &#1047;&#1072;&#1097;&#1080;&#1090;&#1072; &#1087;&#1077;&#1088;&#1080;&#1092;&#1077;&#1088;&#1080;&#1081;&#1085;&#1099;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;. &#1064;&#1083;&#1102;&#1079;&#1099;, IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099;, &#1087;&#1088;&#1086;&#1095;&#1077;&#1077; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
      </li>
      <li>
        &#1047;&#1072;&#1097;&#1080;&#1090;&#1072; <a href="#ID_1911092648">&#1076;&#1080;&#1072;&#1083;&#1087;&#1083;&#1072;&#1085;&#1086;&#1084;</a>
      </li>
      <li>
        &#1058;&#1072;&#1082;&#1078;&#1077; &#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1084;&#1077;&#1090;&#1086;&#1076;&#1080;&#1095;&#1082;&#1080; &#1074; &#1073;&#1080;&#1073;&#1083;&#1080;&#1086;&#1090;&#1077;&#1082;&#1077;
      </li>
    </ul>
    <p>
      <b>&#1058;&#1080;&#1087;&#1086;&#1074;&#1099;&#1077; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080;</b>
