      </li>
      <li>
        &#1057;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1086;&#1083;&#1080; &#1080; &#1083;&#1086;&#1075;&#1080;&#1085;&#1099;
      </li>
      <li>
        &#1044;&#1080;&#1079;&#1072;&#1081;&#1085; &#1089;&#1077;&#1090;&#1080;. &#1045;&#1089;&#1083;&#1080; &#1074;&#1099;&#1074;&#1077;&#1096;&#1080;&#1074;&#1072;&#1077;&#1084; Asterisk &#1085;&#1072; &#1073;&#1077;&#1083;&#1099;&#1081; IP, &#1090;&#1086; &#1082; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1074;&#1076;&#1074;&#1086;&#1081;&#1085;&#1077; &#1089;&#1077;&#1088;&#1100;&#1077;&#1079;&#1085;&#1086;
      </li>
      <li>
        &#1054;&#1096;&#1080;&#1073;&#1082;&#1080; &#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;
      </li>
      <li>
        &#1054;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1103; &#1079;&#1072; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1086;&#1081; (&#1046;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1083;&#1086;&#1075;&#1080;, &#1075;&#1088;&#1072;&#1092;&#1080;&#1082;&#1080; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;)
