<node TEXT="1. Сетевой уровень. iptables" FOLDED="true" ID="ID_595530327" CREATED="1537801237623" MODIFIED="1539697670533"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1140070626">iptables</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;</b>
    </p>
    <ol>
      <li>
        &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1094;&#1077;&#1087;&#1086;&#1095;&#1082;&#1080; &#1080; &#1085;&#1072;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084; &#1080;&#1093; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1084;&#1080; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1084;&#1080;
      </li>
      <li>
        &#171;&#1047;&#1072;&#1075;&#1086;&#1085;&#1103;&#1077;&#1084;&#187; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1074; &#1101;&#1090;&#1080; &#1094;&#1077;&#1087;&#1086;&#1095;&#1082;&#1080;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1085;&#1077; &#1087;&#1086;&#1087;&#1072;&#1083; &#1085;&#1080; &#1074; &#1086;&#1076;&#1085;&#1091; &#1094;&#1077;&#1087;&#1086;&#1095;&#1082;&#1091; --&gt; &#1086;&#1085; &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1089;&#1103;
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      <b>&#1062;&#1077;&#1087;&#1086;&#1095;&#1082;&#1072; ADMIN.</b>&#160; &#1055;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1072; &#1076;&#1083;&#1103; &#1085;&#1072;&#1089;, &#1082;&#1072;&#1082; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1084;&#1099; &#1084;&#1086;&#1075;&#1083;&#1080; &#1080;&#1079; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1099;&#1093; &#1085;&#1072;&#1084;&#1080; &#1089;&#1077;&#1090;&#1077;&#1081; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1086; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1085;&#1099;&#1084; &#1087;&#1086;&#1088;&#1090;&#1072;&#1084; (SSH, Web).
    </p>
    <p>
      <b>&#1062;&#1077;&#1087;&#1086;&#1095;&#1082;&#1072; PHONES.</b>&#160;&#1047;&#1076;&#1077;&#1089;&#1100; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1085;&#1072;&#1096;&#1080;&#1093; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1074;
    </p>
    <p>
      <b>&#1062;&#1077;&#1087;&#1086;&#1095;&#1082;&#1072; SIP.</b>&#160;&#1047;&#1072;&#1076;&#1072;&#1077;&#1084; &#1082;&#1072;&#1082; &#1085;&#1072;&#1096;&#1080; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1077; &#1074; &#1094;&#1077;&#1087;&#1086;&#1095;&#1082;&#1077; PHONES, &#1090;&#1072;&#1082; &#1080; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1099;&#1074;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1080;&#1080;
    </p>
    <p>
      <b>&#1062;&#1077;&#1087;&#1086;&#1095;&#1082;&#1072; IAX2.</b>&#160;&#1047;&#1072;&#1076;&#1072;&#1077;&#1084; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; IAX2-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1090;&#1089;&#1103; &#1082; Asterisk
    </p>
    <p>
      
    </p>
    <p>
      &#1047;&#1072;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1090;&#1100; &#1094;&#1077;&#1087;&#1086;&#1095;&#1082;&#1080;
    </p>
    <p>
      1. &#1042;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090; --&gt; &#1054;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1072; &#1074; &#1094;&#1077;&#1087;&#1086;&#1095;&#1082;&#1077; INPUT (&#1075;&#1076;&#1077; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1086;&#1088;&#1090;&#1072;&#1084; SSH (22) &#1080; HTTP (80)). &#1058;.&#1077;. &#1079;&#1072;&#1075;&#1086;&#1085;&#1103;&#1077;&#1084; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1074; &#1094;&#1077;&#1087;&#1086;&#1095;&#1082;&#1091; ADMIN.
    </p>
    <p>
      
    </p>
    <p>
      service iptables restart
    </p>
    <p>
      
    </p>
    <p>
      service iptables save
    </p>
    <p>
      chkconfig iptables on
    </p>
  </body>
</html></richcontent>
