<node TEXT="вариант1" ID="ID_1445016442" CREATED="1539696441887" MODIFIED="1539697618636"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b># /etc/sysconfig/iptables (&#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082; &#1090;&#1072;&#1082; &#1089;&#1077;&#1073;&#1077;)</b></font>
    </p>
    <p>
      <font color="#008000">-A INPUT &#8211;m state --state ESTABLISHED,RELATED &#8211;j ACCEPT&#160; </font># &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1076;&#1083;&#1103; &#1091;&#1078;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081;. &#1058;.&#1077;. &#1077;&#1089;&#1083;&#1080; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1091;&#1078;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1083; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1089; &#1089;&#1072;&#1081;&#1090;&#1086;&#1084;, &#1090;&#1086; &#1086;&#1085; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089; &#1085;&#1080;&#1084; &#1086;&#1073;&#1084;&#1077;&#1085;&#1080;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;&#1084;&#1080;)
    </p>
    <p>
      <font color="#008000">-A INPUT &#8211;p icmp &#8211;j DROP&#160; </font># &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; <b>icmp</b>. &#1058;.&#1077;. &#1079;&#1072;&#1087;&#1088;&#1077;&#1097;&#1072;&#1077;&#1084; ping &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
    </p>
    <p>
      <font color="#008000">-A INPUT &#8211;i lo &#8211;j ACCEPT</font>&#160;&#160;# &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1089; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; <b>lo</b>.
    </p>
    <p>
      <font color="#008000">-A INPUT -s 192.168.0.0/24 -p tcp -m state --state NEW -m multiport --dports 137,138,139,445 -j ACCEPT</font>&#160;&#160;# &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100;&#160;&#160;&#1080;&#1079; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080; (192.168.0.0/24) &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;&#1084; &#1085;&#1072; &#1087;&#1086;&#1088;&#1090;&#1099; (&#1076;&#1083;&#1103; Samba).
    </p>
    <p>
      <font color="#008000">-A INPUT -s 192.168.0.0/24 -p tcp -m state --state NEW -m tcp --dport 22 -j ACCEPT</font>&#160;&#160;# &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1080;&#1079; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;&#160;&#160;(192.168.0.0/24) &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;&#1084; &#1085;&#1072; &#1087;&#1086;&#1088;&#1090; 22 (for SSH, Putty)
    </p>
    <p>
      <font color="#008000">-A INPUT -s 192.168.0.0/24 -p tcp -m state --state NEW -m tcp --dport 80 -j ACCEPT</font>&#160;&#160;# &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1085;&#1072;&#1096;&#1077;&#1084;&#1091; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1072; &#1080;&#1079; &#1085;&#1072;&#1096;&#1077;&#1081; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;
    </p>
    <p>
      <font color="#008000">-A INPUT -s 192.168.0.0/24 -p udp -m state --state NEW -m udp --dport 5090 -j ACCEPT</font>&#160;&#160;# &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086; &#1087;&#1086;&#1088;&#1090;&#1091; 5090 (&#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086;&#1088;&#1090; &#1089;&#1084;. <a href="#ID_1981279395">sip.conf</a>)
    </p>
    <p>
      <font color="#008000">-A INPUT -p udp -m state --state NEW -m udp --dport 10000:20000 -j ACCEPT</font>&#160;&#160;# &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1087;&#1088;&#1086;&#1093;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1091; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; 10000:20000 (&#1076;&#1083;&#1103; <a href="#ID_455814438">RTP</a>)
    </p>
    <p>
      <font color="#008000">-A INPUT &#8211;j REJECT --reject-with icmp-host-prohibited</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1074;&#1089;&#1077; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#008000">-A FORWARD &#8211;j REJECT --reject-with icmp-host-prohibited</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1074;&#1089;&#1077; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;
    </p>
  </body>
</html></richcontent>
</node>
</node>
