<node TEXT="sip.conf" ID="ID_1981279395" CREATED="1539689743902" MODIFIED="1539690527064"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><font color="#008000">; /etc/asterisk/sip.conf</font></b>
    </p>
    <p>
      <font color="#008000">alwaysauthreject=yes</font>&#160;&#160;; &#1047;&#1072;&#1097;&#1080;&#1090;&#1072; &#1086;&#1090; &#1072;&#1090;&#1072;&#1082; <a href="#ID_1999793967">Direcrory Harvest Attack </a>&quot;&#1055;&#1077;&#1088;&#1077;&#1073;&#1086;&#1088; &#1089;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072;&quot;, &#1084;&#1077;&#1096;&#1072;&#1077;&#1090; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1083;&#1086;&#1075;&#1080;&#1085;. &#1053;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1074;&#1088;&#1072;&#1075;&#1072; &quot;&#1045;&#1089;&#1090;&#1100; &#1083;&#1080; &#1090;&#1072;&#1082;&#1086;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;?&quot; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1090;&#1100; - &#1044;&#1072;
    </p>
    <p>
      <font color="#008000">allowguest=no</font>&#160;&#160;; &#1047;&#1072;&#1087;&#1088;&#1077;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1087;&#1088;&#1103;&#1084;&#1099;&#1093; SIP-&#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; (&#1076;&#1086;&#1079;&#1074;&#1086;&#1085; &#1087;&#1086; e-mail).
    </p>
    <p>
      <font color="#008000">bindaddr=192.168.0.1</font>&#160;&#160;; &#1053;&#1072; &#1082;&#1072;&#1082;&#1086;&#1084; &#1072;&#1076;&#1088;&#1077;&#1089;&#1077; &#1089;&#1083;&#1091;&#1096;&#1072;&#1090;&#1100; SIP &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#008000">bindport=5090</font>&#160;&#160;; &#1057;&#1084;&#1077;&#1085;&#1072; &#1087;&#1086;&#1088;&#1090;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1086;&#1088;&#1090; <b>5060</b>&#160; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1077;&#1085; &#1080;&#1079; <a href="#ID_1876193883">WAN</a>, &#1090;&#1086; &#1086;&#1085; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1089;&#1090;&#1072;&#1085;&#1077;&#1090; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1084; <a href="#ID_1935351867">BruteForce</a>-&#1072;&#1090;&#1072;&#1082;&#1080;
    </p>
    <p>
      <font color="#008000">call-limit=2</font>&#160;&#160;; &#1050;&#1086;&#1083;-&#1074;&#1086; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; &#1083;&#1080;&#1085;&#1080;&#1081; &#1076;&#1083;&#1103; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;, &#1090;&#1086; &#1074;&#1079;&#1083;&#1086;&#1084;&#1097;&#1080;&#1082; &#1089;&#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086; &#1087;&#1088;&#1086;&#1079;&#1074;&#1072;&#1085;&#1080;&#1074;&#1072;&#1090;&#1100; &#1089; &#1085;&#1077;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1095;&#1080;&#1089;&#1083;&#1072; &#1083;&#1080;&#1085;&#1080;&#1081;
    </p>
    <p>
      ; <b>&#1052;&#1072;&#1089;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1074; SIP.</b>&#160; &#1044;&#1077;&#1079;&#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1084; &#1074;&#1079;&#1083;&#1086;&#1084;&#1097;&#1080;&#1082;&#1086;&#1074; &#1086; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; &#1040;&#1058;&#1057;
    </p>
    <p>
