    </p>
    <p>
      <font color="#008000">secret=pass1</font>&#160;&#160;; &#1073;&#1086;&#1083;&#1077;&#1077; 15 &#1079;&#1085;&#1072;&#1082;&#1086;&#1074;, &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1089;&#1083;&#1086;&#1078;&#1085;&#1099;&#1081;
    </p>
    <p>
      <font color="#008000">context=from-closed</font>&#160;&#160;; &#1050;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;, &#1075;&#1076;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1080;&#1085;&#1090;&#1077;&#1083;&#1083;&#1077;&#1082;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;
