<node TEXT="Dialplan. Разделение на контексты" ID="ID_100858823" CREATED="1537889578908" MODIFIED="1539784425258"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1911092648">Dialplan</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1080;&#1072;&#1083;&#1087;&#1083;&#1072;&#1085;</b>&#160;- &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;. Asterisk &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1090; &#1074;&#1099;&#1079;&#1086;&#1074;&#1099; &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1090;&#1086;&#1075;&#1086;, &#1074; &#1082;&#1072;&#1082;&#1086;&#1084; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1077; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;. (&#1050;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1099; - &#1087;&#1086;&#1093;&#1086;&#1078;&#1080; &#1085;&#1072; <a href="#ID_107215151">VLAN</a>&#160; &#1074; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1077;). &#1058;.&#1077;. &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1089;&#1072;&#1076;&#1080;&#1090;&#1100; &#1074; &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; <b>&#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1099;</b>. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1080;&#1079; &#1101;&#1090;&#1080;&#1093; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1084;&#1077;&#1090;&#1100; &#1089;&#1074;&#1086;&#1080; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1087;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;.
    </p>
    <ul>
      <li>
        <b>&#1086;&#1093;&#1088;&#1072;&#1085;&#1085;&#1080;&#1082;&#1091; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1079;&#1074;&#1086;&#1085;&#1080;&#1090;&#1100; &#1085;&#1072; &#1084;&#1086;&#1073;&#1080;&#1083;&#1099;</b>, &#1087;&#1086; &#1084;&#1077;&#1078;&#1075;&#1086;&#1088;&#1086;&#1076;&#1091;, &#1074; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1089;&#1090;&#1088;&#1072;&#1085;&#1099;. &#1055;&#1086;&#1084;&#1077;&#1097;&#1072;&#1077;&#1084; &#1077;&#1075;&#1086; &#1080; &#1090;&#1072;&#1082;&#1080;&#1093; &#1078;&#1077; &#1076;&#1088;&#1091;&#1079;&#1077;&#1081; &#1074; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;
      </li>
    </ul>
    <p>
      <b>&#1056;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074; &#1085;&#1072; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1099;</b>
    </p>
    <p>
      <font color="#008000">[101] </font>
    </p>
    <p>
      <font color="#008000">context=from-it </font>
    </p>
    <p>
      <font color="#008000">[102] </font>
    </p>
    <p>
      <font color="#008000">context=from-buch </font>
    </p>
    <p>
      <font color="#008000">[103] </font>
    </p>
    <p>
      <font color="#008000">context=from-boss </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Dialplan. Разным абонентам - разные правила" ID="ID_345502703" CREATED="1537892539117" MODIFIED="1539784425297"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1911092648">Dialplan</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1056;&#1072;&#1079;&#1085;&#1099;&#1084; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;&#1084; - &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;</b>
    </p>
    <p>
      <font color="#008000"><b>[allow-all]</b></font>&#160;&#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;
    </p>
    <p>
      <font color="#008000">exten=&gt;_X.,1,Dial(SIP/operator/${EXTEN})</font>&#160;&#160;# &#1054;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072; &#1089;&#1074;&#1103;&#1079;&#1080;
    </p>
    <p>
      <font color="#008000">exten=&gt;_10X.,1,Dial(SIP/${EXTEN})</font>&#160;&#160;# &#1047;&#1074;&#1086;&#1085;&#1082;&#1080; &#1085;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1089; 10 - &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099;
    </p>
    <p>
      <font color="#008000"><b>[from-it]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">exten=&gt;_810.,1,Hangup()</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1084;&#1077;&#1078;&#1076;&#1091;&#1085;&#1072;&#1088;&#1086;&#1076;&#1085;&#1099;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;. Hangup - &#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1090;&#1088;&#1091;&#1073;&#1082;&#1091;
    </p>
    <p>
      <font color="#008000">exten=&gt;_.,1,GoTo(allow-all,${EXTEN},1)</font>&#160;&#160;# &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080; &#1085;&#1072; &#1074;&#1089;&#1077; &#1087;&#1088;&#1086;&#1095;&#1080;&#1077; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;. &#1055;&#1088;&#1086;&#1073;&#1088;&#1086;&#1089; (GoTo) &#1085;&#1072; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; allow-all
    </p>
    <p>
      <font color="#008000"><b>[from-buch]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">exten=&gt;_810.,1,Hangup()&#160; </font># &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1084;&#1077;&#1078;&#1076;&#1091;&#1085;&#1072;&#1088;&#1086;&#1076;&#1085;&#1099;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;
    </p>
    <p>
      <font color="#008000">exten=&gt;_89.,1,Hangup()</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1088;&#1077;&#1090; &#1085;&#1072; &#1084;&#1086;&#1073;. &#1090;&#1077;&#1083;. &#1074; &#1056;&#1060;<font color="#008000">&#160;</font>
    </p>
    <p>
      <font color="#008000">exten=&gt;_.,1,GoTo(allow-all,${EXTEN},1) </font>
    </p>
    <p>
      <font color="#008000"><b>[from-boss]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">exten=&gt;_.,1,GoTo(allow-all,${EXTEN},1)</font>&#160;&#160;# &#1052;&#1086;&#1078;&#1085;&#1086; &#1074;&#1089;&#1077;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Dialplan. Информирование о международных звонках" ID="ID_1945826768" CREATED="1537892688117" MODIFIED="1539691492473"><richcontent TYPE="NOTE">
