<node TEXT="Dialplan. Ограничение на право звонков по времени" ID="ID_1347830877" CREATED="1537893210369" MODIFIED="1539846938418"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1911092648">Dialplan</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1048;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077;. &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1087;&#1088;&#1072;&#1074;&#1086; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; &#1087;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;</b>
    </p>
    <p>
      <font color="#008000"><b>; /etc/asterisk/extensions.conf</b></font>
    </p>
    <p>
      <font color="#008000"><b>[from-it]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">exten=&gt;_810.,1,GoTo(mail-info,${EXTEN},1)</font>&#160;&#160;# &#1052;&#1077;&#1078;&#1076;&#1091;&#1085;&#1072;&#1088;&#1086;&#1076;&#1085;&#1099;&#1077; - &#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1085;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; + &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#008000">exten=&gt;_.,1,GotoIfTime(9:00-18:00|mon-fri|*|*?allow-all,${EXTEN},1)</font>&#160;&#160;# &#1055;&#1088;&#1086;&#1073;&#1088;&#1086;&#1089; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; &#1074; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103;
    </p>
    <p>
      <font color="#008000">exten=&gt;_.,n, Playback(zapret-zvonkov)</font>&#160;&#160;# &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1087;&#1086;&#1087;&#1072;&#1083;&#1080; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103;, &#1090;&#1086; &#1080;&#1075;&#1088;&#1072;&#1077;&#1090; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#008000"><b>[mail-info]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _X..,Playback(zapret-zvonkov) </font>
    </p>
    <p>
      <font color="#008000">same =&gt; n,System(echo ${EXTEN}&gt; mail -s &quot;8-10 ALARM!!!&quot; admin@ya.ru) </font>
    </p>
    <p>
      <font color="#008000">same =&gt; n,Hangup() </font>
    </p>
    <p>
      <font color="#008000"><b>[allow-all]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">exten=&gt;_X.,1,Dial(SIP/operator/${EXTEN}) </font>
    </p>
    <p>
      <font color="#008000">exten=&gt;_10X.,1,Dial(SIP/${EXTEN}) </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077;. &#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091; &quot;&#1056;&#1072;&#1073;&#1086;&#1095;&#1080;&#1081; &#1076;&#1077;&#1085;&#1100; &#1079;&#1072;&#1082;&#1086;&#1085;&#1095;&#1077;&#1085;. &#1054;&#1089;&#1090;&#1072;&#1074;&#1100;&#1090;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;&quot;</b>
    </p>
    <p>
      <b><font color="#008000">; /etc/asterisk/extensions.conf</font></b>
    </p>
    <p>
      <b><font color="#008000">[incoming]</font></b>
    </p>
    <p>
      <font color="#008000">exten =&gt; _X.,1,GotoIfTime(00:00-23:59|sat-sun|*|*?workinghours,s,1) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _X.,2,GotoIfTime(18:00-09:00|mon-fri|*|*?workinghours,s,1) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _X.,3,Goto(menu,s,1) </font>
    </p>
    <p>
      <b><font color="#008000">[workinghours]</font></b>
    </p>
    <p>
      <font color="#008000">exten =&gt; s,1,Background(/var/lib/asterisk/moh/worktime/workingtime) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; s,2,Set(fname=${STRFTIME(${EPOCH},,%Y%m%d%H%M)}-${CALLERID(number)}-${EXTEN}) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; s,3,Record(/var/www/html/voicemail/${fname}.wav,0,8,X) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; s,4,Hangup</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Защита динамических абонентов" ID="ID_1634303517" CREATED="1537893900524" MODIFIED="1539846940899"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1072;:</b>
    </p>
    <p>
      &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; IP. &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; permit/deny &#8211; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;
    </p>
    <p>
      <b>&#1056;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077;:</b>
    </p>
    <p>
      &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1074;&#1072;&#1077;&#1084; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080; &#1085;&#1072; &#1084;&#1077;&#1078;&#1076;&#1091;&#1085;&#1072;&#1088;&#1086;&#1076;&#1085;&#1099;&#1077; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;: &#1094;&#1077;&#1083;&#1080;&#1082;&#1086;&#1084; &#1080;&#1083;&#1080; &#1087;&#1086; <b>PIN-&#1082;&#1086;&#1076;&#1091;. &#1057; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;</b>
    </p>
  </body>
</html></richcontent>
</node>
</node>
