<node TEXT="Вход в SSH по сертификатам" ID="ID_1940978757" CREATED="1537894966235" MODIFIED="1546781440646"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1266911726">SSH (Unix)</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1043;&#1077;&#1085;&#1077;&#1088;&#1072;&#1094;&#1080;&#1103; &#1082;&#1083;&#1102;&#1095;&#1077;&#1081; SSH</b>
    </p>
    <p>
      
    </p>
    <p>
      1. <font color="#0000c0">ssh-keygen -t dsa</font>&#160;&#160;# &#1043;&#1077;&#1085;&#1077;&#1088;&#1072;&#1094;&#1080;&#1103; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072; (&#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; + &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1082;&#1083;&#1102;&#1095;).
    </p>
    <p>
      2.&#160;&#1054;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1082;&#1083;&#1102;&#1095;, &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1079;&#1072;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1085;&#1072; WS
    </p>
    <p>
      3. &#1055;&#1088;&#1072;&#1074;&#1080;&#1084; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;. &#1092;&#1072;&#1081;&#1083; <b>sshd.conf</b>:
    </p>
    <ul>
      <li>
        RSAAuthentication yes
      </li>
      <li>
        PubkeyAuthentication yes
      </li>
      <li>
        PasswordAuthentication no
      </li>
    </ul>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Ограничение доступа к Apache" ID="ID_1586391961" CREATED="1537895432990" MODIFIED="1584087694636"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_481917594">FreePBX</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; Apache</b>
    </p>
    <ul>
      <li>
        <b>&#1045;&#1089;&#1083;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084; FreePBX</b>&#160;&#160;(&#1072; FreePBX &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; <a href="#ID_31867895">LAMP</a>)
      </li>
      <li>
        &#1046;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; Apache &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; HTTPS
      </li>
    </ul>
    <p>
      <b>&#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;&#1074; Apache &#1074;&#1099;&#1074;&#1086;&#1076; &#1074;&#1077;&#1088;&#1089;&#1080;&#1081;</b>
    </p>
    <p>
      <font color="#008000">ServerSignature Off </font>
    </p>
    <p>
      <font color="#008000">ServerTokens Prod</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080;, &#1075;&#1076;&#1077; &#1083;&#1077;&#1078;&#1072;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; FreePBX &#1085;&#1091;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;:</b>
    </p>
    <p>
      <font color="#008000">&lt;Directory&gt; </font>
    </p>
    <p>
      <font color="#008000">Order Deny,Allow </font>
    </p>
    <p>
      <font color="#008000">Deny from all</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1080;&#1079; &#1074;&#1089;&#1077;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081;
    </p>
    <p>
      <font color="#008000">Allow from 192.168.10.0/24</font>&#160;&#160;# &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1080;&#1079; &#1085;&#1072;&#1096;&#1077;&#1081; &#1089;&#1077;&#1090;&#1080;
    </p>
    <p>
      <font color="#008000">&lt;Directory&gt;</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Asterisk Manager Interface" ID="ID_1349803512" CREATED="1537896598899" MODIFIED="1537897681016"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Asterisk Manager Interface (AMI)</b>&#160;- &#1076;&#1083;&#1103; &#1080;&#1085;&#1090;&#1077;&#1075;&#1088;&#1072;&#1094;&#1080;&#1080; Asterisk &#1089; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1084;&#1080; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1084;&#1080; (CRM).
    </p>
    <ul>
      <li>
        &#1089;&#1090;&#1072;&#1088;&#1072;&#1090;&#1100;&#1089;&#1103; &#1085;&#1077; &#1085;&#1072;&#1088;&#1072;&#1097;&#1080;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1083;-&#1074;&#1086; &#1091;&#1095;&#1077;&#1090;&#1085;&#1099;&#1093; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081;, &#1079;&#1072; &#1085;&#1080;&#1084;&#1080; &#1089;&#1083;&#1086;&#1078;&#1085;&#1086; &#1089;&#1083;&#1077;&#1076;&#1080;&#1090;&#1100;
      </li>
    </ul>
    <p>
      <b>&#1050;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100; &#1091;&#1095;&#1077;&#1090;&#1085;&#1099;&#1093; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; &#1080; ACL &#1074; /etc/asterisk/manager.conf</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>[general]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">enabled = yes </font>
    </p>
    <p>
      <font color="#008000">port = 5038 </font>
    </p>
    <p>
      <font color="#008000">bindaddr = 0.0.0.0 </font>
    </p>
    <p>
      <font color="#008000">displayconnects=no ;only effects 1.6+ </font>
    </p>
    <p>
      <font color="#008000">webenabled = yes </font>
    </p>
    <p>
      <font color="#008000">httptimeout = 60&#160;&#160; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>[admin]</b></font>&#160;&#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1072;&#1082;&#1082;&#1072;&#1091;&#1085;&#1090;
    </p>
    <p>
      <font color="#008000">secret = qefiSsDWOIq ;from pbx-onlime </font>
    </p>
    <p>
      <font color="#008000">;secret = aIsQQBKbJLLI ; orig </font>
    </p>
    <p>
      <font color="#008000">deny=0.0.0.0/0.0.0.0</font>&#160;&#160;# &#1057;&#1077;&#1090;&#1080;
    </p>
    <p>
      <font color="#008000">permit=127.0.0.1/255.255.255.0 </font>
    </p>
    <p>
      <font color="#008000">permit=109.173.118.12 </font>
    </p>
    <p>
      <font color="#008000">read = system,call,log,verbose,command,agent,user,config,command,dtmf,...........</font>&#160;&#160;# &#1055;&#1088;&#1072;&#1074;&#1072;
    </p>
    <p>
      <font color="#008000">write = system,call,log,verbose,command,agent,user,config,command,dtmf,........... </font>
    </p>
  </body>
</html></richcontent>
</node>
