<node TEXT="5. Защита телефонов и шлюзов" ID="ID_349408907" CREATED="1537801256939" MODIFIED="1539847691649"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <b>&#1054;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1096;&#1080;&#1074;&#1082;&#1080; IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1074;</b>. &#1054;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086; &#1074; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080;. &#1044;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; <a href="#ID_410438924">TFTP</a>-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; (&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1085;&#1072; TFTP-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;. &#1042; &#1086;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1072; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; &#1087;&#1091;&#1090;&#1100; &#1082; &#1085;&#1086;&#1074;&#1086;&#1081; &#1087;&#1088;&#1086;&#1096;&#1080;&#1074;&#1082;&#1077; --&gt; &#1074;&#1089;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1079;&#1072;&#1083;&#1100;&#1077;&#1090; &#1087;&#1088;&#1086;&#1096;&#1080;&#1074;&#1082;&#1091; &#1085;&#1072; &#1089;&#1077;&#1073;&#1103;)
      </li>
      <li>
        &#1064;&#1083;&#1102;&#1079; &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1072;&#1090;&#1100;<b>&#160;&#1079;&#1072; firewall </b>(&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1089;&#1077;&#1090;&#1077;&#1081;, &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;)
      </li>
      <li>
        &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; <b>&#1089;&#1083;&#1086;&#1078;&#1085;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;</b>&#160;&#1085;&#1072; IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;
      </li>
      <li>
        &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; Web-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1076;&#1083;&#1103; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1084;. &#1055;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1080;&#1079; Web-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1082;&#1072;&#1095;&#1072;&#1090;&#1100; (&#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; backup) &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083; (&#1089;&#1086; &#1074;&#1089;&#1077;&#1084;&#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;&#1084;&#1080;, IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1084;&#1080;, SIP extension)
      </li>
      <li>
        &#1058;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099; &#1074; <b>&#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; VLAN</b>
      </li>
      <li>
        <b>&#1057;&#1084;&#1077;&#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1085;&#1099;&#1093; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074;</b>. &#1053;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072;&#1093; &#1080; &#1096;&#1083;&#1102;&#1079;&#1072;&#1093; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1087;&#1086;&#1088;&#1090; SIP &#1089; 5060 &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1081; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081;. &#1069;&#1090;&#1086; &#1087;&#1086;&#1074;&#1099;&#1096;&#1072;&#1077;&#1090; &#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1100; &#1082; &#1089;&#1082;&#1072;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;&#1084;.
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
