<node TEXT="1. postfix" ID="ID_1690140488" CREATED="1539610583722" MODIFIED="1539620477948"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1845130465">Postfix</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; Postfix</b>
    </p>
    <p>
      <b>1. &#1047;&#1072;&#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082;&#160;</b>&#1086;&#1090; &#1080;&#1084;&#1077;&#1085;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1080; &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1091;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103; &#1086; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1077; (&#1089; &#1074;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;&#1084; &#1080;&#1079; &#1072;&#1091;&#1076;&#1080;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072;).
    </p>
    <p>
      <b>2.</b>&#160;Postfix &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085; &#1074; CentOS. &#1053;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090; SASL (Simple Authentication and Security Layer &#8212; &#1084;&#1077;&#1090;&#1086;&#1076; &#1076;&#1083;&#1103; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1074; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1099; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;). &#1069;&#1090;&#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086; Postfix &#1089;&#1084;&#1086;&#1075; &#1079;&#1072;&#1083;&#1086;&#1075;&#1080;&#1085;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; yandex.ru (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;)
    </p>
    <p>
      <font color="#0000c0">yum install cyrus-sasl-plain</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b># /etc/postfix/main.cf&#160;&#160;# &#1044;&#1086;&#1073;&#1080;&#1090;&#1100; &#1074; &#1082;&#1086;&#1085;&#1077;&#1094; &#1092;&#1072;&#1081;&#1083;&#1072;</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">smtp_sasl_auth_enable = yes </font>
    </p>
    <p>
      <font color="#008000">smtp_sasl_password_maps = hash:/etc/postfix/mailpasswd </font>
    </p>
    <p>
      <font color="#008000">smtp_sasl_security_options = noanonymous </font>
    </p>
    <p>
      <font color="#008000">smtp_sasl_type = cyrus </font>
    </p>
    <p>
      <font color="#008000">smtp_sasl_mechanism_filter = login </font>
    </p>
    <p>
      <font color="#008000">smtp_sender_dependent_authentification = yes </font>
    </p>
    <p>
      <font color="#008000">sender_dependent_relayhost_maps = hash:/etc/postfix/sender_relay </font>
    </p>
    <p>
      <font color="#008000">sender_canonical_maps = hash:/etc/postfix/canonical </font>
    </p>
    <p>
      <font color="#008000">smtp_generic_maps = hash:/etc/postfix/generic</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b># /etc/postfix/mailpasswd </b></font>
    </p>
    <p>
      <font color="#008000">[smtp.yandex.ru] mymail@yandex.ru:password</font>&#160;&#160;# &#1064;&#1072;&#1073;&#1083;&#1086;&#1085;. &#1059;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1103;&#1097;&#1080;&#1082;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000"># /etc/postfix/sender_relay</font></b>&#160;&#160;- &#1055;&#1088;&#1080;&#1074;&#1103;&#1079;&#1082;&#1072; &#1076;&#1086;&#1084;&#1077;&#1085;&#1086;&#1074; &#1080; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1093; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1077;&#1083;&#1077;&#1081; &#1082; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1084; &#1089;&#1083;&#1091;&#1078;&#1073;&#1072;&#1084;
    </p>
    <p>
      <font color="#008000">@yandex.ru [smtp.yandex.ru]</font>&#160;&#160;# &#1064;&#1072;&#1073;&#1083;&#1086;&#1085;
    </p>
    <p>
      <font color="#008000">mymail@yandex.ru [smtp.yandex.ru]</font>&#160;&#160;# &#1064;&#1072;&#1073;&#1083;&#1086;&#1085;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>#&#160;&#160;/etc/postfix/canonical</b></font>&#160;- &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074; &#1082;&#1086;&#1085;&#1094;&#1077;. &#1059;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;, &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1072;&#1082;&#1086;&#1081; &#1072;&#1082;&#1082;&#1072;&#1091;&#1085;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;
    </p>
    <p>
      <font color="#008000">@yandex.ru mymail@yandex.ru</font>&#160;&#160;# &#1064;&#1072;&#1073;&#1083;&#1086;&#1085;
    </p>
    <p>
      
    </p>
    <p>
      <b>postmap</b>&#160;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1082;&#1072;&#1088;&#1090;&#1099; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1093; &#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1099;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;. &#1058;&#1086;-&#1077;&#1089;&#1090;&#1100; postfix &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1085;&#1077; &#1089; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1084;&#1080; &#1092;&#1072;&#1081;&#1083;&#1072;&#1084;&#1080;, &#1072; &#1080;&#1093; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1082;&#1072;&#1088;&#1090;&#1072;&#1084;&#1080;. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091;, &#1089;&#1086;&#1079;&#1076;&#1072;&#1074; &#1092;&#1072;&#1081;&#1083; mailpasswd &#1084;&#1099; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084; &#1076;&#1083;&#1103; &#1085;&#1077;&#1075;&#1086; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; postmap &#1080; &#1101;&#1090;&#1086;&#1090; &#1092;&#1072;&#1081;&#1083; &#1087;&#1088;&#1077;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1091;&#1102; &#1082;&#1072;&#1088;&#1090;&#1091;. &#1045;&#1089;&#1083;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1074;&#1085;&#1077;&#1089;&#1077;&#1085;&#1099; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074; &#1082;&#1072;&#1082;&#1086;&#1081;-&#1083;&#1080;&#1073;&#1086; &#1092;&#1072;&#1081;&#1083;, &#1076;&#1083;&#1103; &#1085;&#1077;&#1075;&#1086; &#1089;&#1085;&#1086;&#1074;&#1072; &#1087;&#1088;&#1080;&#1076;&#1077;&#1090;&#1089;&#1103; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; postmap.
    </p>
    <p>
      <font color="#0000c0">postmap /etc/postfix/canonical </font>
    </p>
    <p>
      <font color="#0000c0">postmap /etc/postfix/sender_relay </font>
    </p>
    <p>
      <font color="#0000c0">postmap /etc/postfix/mailpasswd </font>
    </p>
    <p>
      <font color="#0000c0">postmap /etc/postfix/generic</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>3.</b>
    </p>
    <p>
      <font color="#0000c0">chkconfig saslauthd on </font>
    </p>
    <p>
      <font color="#0000c0">service saslauthd restart </font>
    </p>
    <p>
      <font color="#0000c0">chkconfig postfix on </font>
    </p>
    <p>
      <font color="#0000c0">service postfix restart</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>4. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; <a href="#ID_255144404">mail</a></b>
    </p>
    <p>
      <font color="#0000c0">yum install mailx</font>&#160;&#160;# &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1091; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; mail
    </p>
    <p>
      mail&#160;&lt;&#1103;&#1097;&#1080;&#1082;, &#1082;&#1091;&#1076;&#1072; &#1093;&#1086;&#1090;&#1080;&#1084; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086;&gt;
    </p>
    <p>
      Subject: some text --&gt;&#160;&#160;enter
    </p>
    <p>
      &lt;&#1090;&#1077;&#1083;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072;&gt; --&gt;&#160;&#160;enter
    </p>
    <p>
      . --&gt; enter
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">$ less /var/log/maillog</font>&#160;&#160;# &#1083;&#1086;&#1075;&#1080; Postfix, &#1077;&#1089;&#1083;&#1080; &#1085;&#1077; &#1079;&#1072;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1083;&#1086;
    </p>
    <p>
      <font color="#0000c0">$ </font><a href="#ID_1453020797">tail</a><font color="#0000c0">&#160;-fn0&#160;/var/log/maillog</font><font color="#000000">&#160;&#160;# &#1053;&#1072;&#1073;&#1083;&#1102;&#1076;&#1077;&#1085;&#1080;&#1077; &#1074; &#1086;&#1085;&#1083;&#1072;&#1081;&#1085;&#1077; &#1079;&#1072; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1099;&#1084; &#1092;&#1072;&#1081;&#1083;&#1072;, &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1072;&#1103; &#1089;&#1090;&#1072;&#1088;&#1099;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="2. sip, extensions, voicemail" ID="ID_924273558" CREATED="1539610593215" MODIFIED="1539789627500"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><font color="#008000">; /etc/asterisk/sip.conf</font></b>
    </p>
    <p>
      <b><font color="#008000">[2011]</font></b>
    </p>
    <p>
      <font color="#008000">mailbox=2011@default&#160;&#160;; &#1043;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082; &#1076;&#1083;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; </font>
    </p>
    <p>
      <font color="#008000">language=en </font>
    </p>
    <p>
      <b><font color="#008000">[900]</font></b>&#160;&#160;; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1089;&#1083;&#1091;&#1096;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1074;&#1086;&#1077;&#1081; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099;
    </p>
    <p>
      <font color="#008000">type=friend </font>
    </p>
    <p>
      <font color="#008000">host=dynamic </font>
    </p>
    <p>
      <font color="#008000">insecure=invite </font>
    </p>
    <p>
      <font color="#008000">username=900 </font>
    </p>
    <p>
      <font color="#008000">secret=pass1 </font>
    </p>
    <p>
      <font color="#008000">disallow=all </font>
    </p>
    <p>
      <font color="#008000">allow=alaw</font>
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">; /etc/asterisk/extensions.conf</font></b>
    </p>
    <p>
      <font color="#008000">exten =&gt; 900,1,VoiceMailMain() </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; 2011,1,Dial(SIP/2011,30,m&amp;t) </font>
    </p>
    <p>
