<node TEXT="Голосовое меню (IVR)" ID="ID_1590320518" CREATED="1539596491809" MODIFIED="1540891830968"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1361614273">Audacity</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Interactive Voice Response (IVR)</b>&#160;&#8212; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1099;&#1093; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1093; &#1084;&#1077;&#1085;&#1102;.
    </p>
    <p>
      
    </p>
    <p>
      1. &#1047;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1080; &#1087;&#1077;&#1088;&#1077;&#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1086;&#1088;&#1086;&#1078;&#1082;&#1091; WAV (8-bit mino) &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1084; &#1082;&#1086;&#1076;&#1077;&#1082;&#1086;&#1084; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; G.711 A-Law)
    </p>
    <p>
      <font color="#0000c0">&gt; file convert mymusic.wav mymusic.alaw</font>
    </p>
    <p>
      <font color="#0000c0">$ mkdir /var/lib/asterisk/moh/voicemail</font>&#160;&#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      2.
    </p>
    <p>
      <b><font color="#008000">; /etc/asterisk/extensions.conf</font></b>
    </p>
    <p>
      <b><font color="#008000">[incoming]</font></b>
    </p>
    <p>
      <font color="#008000">exten =&gt; _X.,1,Goto(menu,s,1) ;</font>&#160;&#1042;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1080;&#1079; &#1092;&#1072;&#1081;&#1083;&#1072; sip.conf &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1077;&#1090; &#1085;&#1072; &#1101;&#1090;&#1086;&#1090; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;. &#1055;&#1086;&#1089;&#1083;&#1077; &#1095;&#1077;&#1075;&#1086; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1087;&#1077;&#1088;&#1077;&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; Goto &#1085;&#1072; &#1082;&#1086;&#1090;&#1077;&#1082;&#1089;&#1090; menu
    </p>
    <p>
      <b><font color="#008000">[menu]</font></b>
    </p>
    <p>
      <font color="#008000">exten =&gt; s,1,Background(/var/lib/asterisk/moh/voicemail/voicemenu)&#160;</font>&#160;; &#1051;&#1086;&#1074;&#1080;&#1090;&#1089;&#1103; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1080;&#1079; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1072;
    </p>
    <p>
      incoming &#1080; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1086;&#1077; &#1087;&#1088;&#1080;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077;. &#1056;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;
    </p>
    <p>
      <font color="#008000">exten =&gt; 1,1,Dial(SIP/2011,,m)</font>&#160;&#160;; &#1055;&#1088;&#1080; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1080; 1, &#1080;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; 2011
    </p>
    <p>
      <font color="#008000">exten =&gt; 2,1,Dial(SIP/2012,,m)</font>&#160;&#160;; &#1055;&#1088;&#1080; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1080; 2, &#1080;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; 2012
    </p>
    <p>
      <font color="#008000">exten =&gt; s,n,Wait(5)</font>&#160;&#160;; &#1053;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1085;&#1072;&#1078;&#1072;&#1090;&#1086; --&gt; &#1095;&#1077;&#1088;&#1077;&#1079; 5 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076; --&gt;
    </p>
    <p>
      <font color="#008000">exten =&gt; s,n,Dial(SIP/2011&amp;SIP/2012,,m)</font>&#160;; &#1047;&#1074;&#1086;&#1085;&#1080;&#1090;&#1100; &#1086;&#1073;&#1086;&#1080;&#1084; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;&#1084;
    </p>
  </body>
</html></richcontent>
