        &#1052;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1088;&#1072;&#1097;&#1080;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1085;&#1086;&#1084;&#1077;&#1088;&#1085;&#1072;&#1103; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072; &#1089;&#1095;&#1077;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1081; &#1091;&#1078;&#1077; &#1082; Asterisk, &#1072; &#1085;&#1077; &#1082; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1081; &#1040;&#1058;&#1057;
      </li>
      <li>
        &#1063;&#1077;&#1088;&#1077;&#1079; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1085;&#1072;&#1096;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1077; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080; (&#1092;&#1080;&#1083;&#1080;&#1072;&#1083;&#1099;), &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1086;&#1074;, &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1086;&#1074;, &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1097;&#1080;&#1093; &#1080;&#1079; &#1076;&#1086;&#1084;&#1072;
      </li>
      <li>
        &#1052;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072; IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1080;&#1080;. &#1044;&#1083;&#1103; &#1089;&#1080;&#1085;&#1078;&#1077;&#1085;&#1080;&#1103; &#1079;&#1072;&#1090;&#1088;&#1072;&#1090; &#1085;&#1072; &#1089;&#1074;&#1103;&#1079;&#1100;. &#1044;&#1083;&#1103; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; 8-800.
      </li>
      <li>
        &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; Skype. &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1089; &#1089;&#1072;&#1081;&#1090;&#1072;
      </li>
    </ul>
    <p>
      <b>2. &#1047;&#1072;&#1084;&#1077;&#1085;&#1072; &#1040;&#1058;&#1057; &#1085;&#1072; &#1096;&#1083;&#1102;&#1079;&#1099;.</b>&#160;&#1058;.&#1077;. &#1040;&#1058;&#1057; &#1074;&#1099;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1072; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1082;&#1072; &#1080; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1099;&#1077; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099; &#1086;&#1089;&#1090;&#1072;&#1102;&#1090;&#1089;&#1103;. &#1042;&#1084;&#1077;&#1089;&#1090;&#1086; &#1089;&#1090;&#1072;&#1088;&#1086;&#1081; &#1040;&#1058;&#1057; &#1089;&#1090;&#1072;&#1074;&#1080;&#1084; &#1096;&#1083;&#1102;&#1079;&#1099; &#1076;&#1083;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1099;&#1093; &#1083;&#1080;&#1085;&#1080;&#1081; --&gt; &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1096;&#1083;&#1102;&#1079;&#1099; &#1082; Asterisk &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072;&#1084; <a href="#ID_765591916">TDMoE</a>&#160;(&#1073;&#1072;&#1085;&#1082;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;) &#1080;&#1083;&#1080; SIP (&#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1096;&#1083;&#1102;&#1079;&#1099;) --&gt; &#1082; &#1096;&#1083;&#1102;&#1079;&#1072;&#1084; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1099;&#1093; &#1090;&#1077;&#1083;. &#1083;&#1080;&#1085;&#1080;&#1081;
    </p>
    <ul>
      <li>
        &#1074;&#1089;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1080;&#1079; <b>&#1087;&#1091;&#1085;&#1082;&#1090;&#1072; 1</b>
