      </li>
    </ul>
    <p>
      <b>3. &#1047;&#1072;&#1084;&#1077;&#1085;&#1072; &#1040;&#1058;&#1057; &#1085;&#1072; IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099;.</b>&#160;&#1047;&#1072;&#1084;&#1077;&#1085;&#1072; &#1074;&#1089;&#1077;&#1075;&#1086;
