      </li>
      <li>
        &#1057;&#1087;&#1077;&#1094;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; <b>dtmfmode</b>&#160; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089;&#1086; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1086;&#1081; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;
      </li>
    </ul>
    <p>
      <font color="#0000c0">&gt; sip show registry</font>&#160;&#160;# &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080; Asterisk &#1085;&#1072; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      <b>register =&gt; sipuser[:secret[:authuser]]@host[:port][/extension]</b>
    </p>
    <ul>
      <li>
        <b>sipuser</b>&#160;- &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1085;&#1072; SIP &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;.
      </li>
      <li>
        <b>authuser</b>&#160;- &#1085;&#1077; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1076;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1085;&#1072; SIP &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;
      </li>
      <li>
        <b>secret</b>&#160;- &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;.
      </li>
      <li>
        <b>host</b>&#160;- &#1076;&#1086;&#1084;&#1077;&#1085; &#1080;&#1083;&#1080; ip &#1072;&#1076;&#1088;&#1077;&#1089; SIP &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
      </li>
      <li>
        <b>port</b>&#160;- &#1085;&#1072; &#1082;&#1072;&#1082;&#1086;&#1081; &#1087;&#1086;&#1088;&#1090; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1090;&#1100; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; host. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1079;&#1072;&#1076;&#1072;&#1085;&#1086;, &#1090;&#1086; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; - 5060
      </li>
      <li>
        <b>/extension</b>&#160;- &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1074; &#1076;&#1080;&#1072;&#1083;&#1087;&#1083;&#1072;&#1085;&#1077; Asterisk. Extension - &#1087;&#1086;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; SIP &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1082; &lt;contact&gt;. &#1069;&#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1084; SIP &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1077;&#1084;&#1091; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1089;&#1086;&#1074;&#1077;&#1088;&#1096;&#1080;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074; &#1074; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091; Asterisk. &#1047;&#1072;&#1076;&#1072;&#1081;&#1090;&#1077; &#1074; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1077; &#1090;&#1088;&#1072;&#1085;&#1082;&#1072; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1077; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077;, &#1076;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;: exten =&gt; _1234567,1,Queue(queuename), &#1075;&#1076;&#1077; 1234567 - extension. &#1045;&#1089;&#1083;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085; &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080;, &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; SIP &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1074;&#1077;&#1088;&#1086;&#1103;&#1090;&#1085;&#1077;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; sipuser &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1072; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072;.
      </li>
    </ul>
  </body>
