<node TEXT="Статистика звонков (CDR)" ID="ID_843530826" CREATED="1539460479155" MODIFIED="1552753822891"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_888808260">CEL</a>&#160;&#160;&#160;<a href="#ID_938739108">cdr.conf</a>&#160;&#160; <a href="#ID_403217901">CDR Reports</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Call Detail Record, CDR</b>&#160;- &#1087;&#1086;&#1076;&#1088;&#1086;&#1073;&#1085;&#1072;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1086;&#1073; &#1072;&#1082;&#1090;&#1077; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1080; (&#1079;&#1074;&#1086;&#1085;&#1082;&#1077;), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1073;&#1099;&#1083;&#1080; &#1087;&#1088;&#1086;&#1074;&#1077;&#1076;&#1077;&#1085;&#1099; &#1085;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1081; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080;. &#1058;&#1072;&#1082;&#1080;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1077;&#1089;&#1090;&#1100; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1091; &#1083;&#1102;&#1073;&#1086;&#1081; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1081; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1086;&#1081; &#1040;&#1058;&#1057;. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1086;&#1081; &#1040;&#1058;&#1057; &#1087;&#1088;&#1077;&#1076;&#1083;&#1072;&#1075;&#1072;&#1077;&#1090; &#1089;&#1074;&#1086;&#1080; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1099; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072; CDR.
    </p>
    <ul>
      <li>
        <b>Asterisk-cdr-viewer</b>&#160;- &#1042;&#1077;&#1073; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; Asterisk (Call Detail Recordings). &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;, &#1090;&#1072;&#1082;&#1078;&#1077;, &#1074; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080; <b>FreePBX</b>. &#1055;&#1088;&#1077;&#1082;&#1088;&#1072;&#1089;&#1085;&#1086;&#1077; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;, &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080; &#1080; &#1087;&#1088;&#1086;&#1089;&#1083;&#1091;&#1096;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081;.
      </li>
      <li>
        <b>Asterisk-CDR-Viewer-Mod</b>&#160;(&#1076;&#1077;&#1083;&#1072;&#1102;&#1090; &#1085;&#1072;&#1096;&#1080;)
      </li>
      <li>
