<node TEXT="Troubleshooting" FOLDED="true" ID="ID_498688576" CREATED="1519112080218" MODIFIED="1552753822302"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1054;&#1090;&#1083;&#1072;&#1076;&#1082;&#1072;</b>
    </p>
    <p>
      <font color="#0000c0"># asterisk &#8211;rvvvvv</font>&#160;&#160;# &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080; Asterisk &#1089; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077;&#1084; &#1086;&#1090;&#1083;&#1072;&#1076;&#1082;&#1080; 5
    </p>
    <p>
      <font color="#0000c0">&gt; core set verbose <b>5</b></font>&#160;&#160;# 5 &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1086;&#1090;&#1083;&#1072;&#1076;&#1086;&#1095;&#1085;&#1099;&#1093; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080;. <b>&#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;</b>&#160;- <b>off</b>&#160;&#160;&#1080;&#1083;&#1080; <b>0</b>
    </p>
    <p>
      <font color="#0000c0">&gt; logger mute</font>&#160;&#160;# &#1055;&#1072;&#1091;&#1079;&#1072; &#1085;&#1072; &#1074;&#1099;&#1074;&#1086;&#1076; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1074; CLI. &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; - &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1099;&#1081; &#1074;&#1074;&#1086;&#1076; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1086;&#1090;&#1083;&#1072;&#1076;&#1082;&#1080;</b>
    </p>
    <p>
      0. &#1042; &#1089;&#1077;&#1090;&#1080; &#1083;&#1080; &#1085;&#1072;&#1096; &#1087;&#1080;&#1088; &#1080; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; (&#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;)<br/><font color="#0000c0">&gt; sip show peers </font>
    </p>
    <p>
      <font color="#0000c0">&gt; core show peers</font>
    </p>
    <p>
      1. &#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; (&#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;)
    </p>
    <p>
      <font color="#0000c0">&gt; sip show registry</font>
    </p>
    <p>
      2. &#1043;&#1077;&#1085;&#1077;&#1088;&#1072;&#1094;&#1080;&#1103; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1089; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1075;&#1086; &#1084;&#1077;&#1089;&#1090;&#1072; &#1073;&#1077;&#1079; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1072;
    </p>
    <p>
      <font color="#0000c0">&gt; originate Local/2011@local application Echo</font>&#160;&#160;# &#1042;&#1099;&#1079;&#1086;&#1074; 2011 &#1089; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1072; local
    </p>
    <p>
      <font color="#0000c0">&gt; originate SIP/2011 application Echo</font>&#160;&#160;# &#1057;&#1083;&#1099;&#1096;&#1085;&#1086; &#1089;&#1072;&#1084;&#1086;&#1075;&#1086; &#1089;&#1077;&#1073;&#1103;
    </p>
    <p>
      <font color="#0000c0">&gt; originate SIP/2011 application Dial SIP/2012</font>&#160;&#160;# 2011 &#1087;&#1086;&#1079;&#1074;&#1086;&#1085;&#1080;&#1090; 2012
    </p>
    <p>
      <font color="#0000c0">&gt; originate SIP/2011 extension 2012@local</font>&#160;&#160;# &#1042;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; 2011 --&gt; &#1048;&#1076;&#1077;&#1090; &#1074; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; local &#1085;&#1072; 2012
    </p>
    <p>
      3. sip debug.
    </p>
    <p>
      <font color="#0000c0">&gt; sip set debug on</font>&#160;&#160;# <b>&#1053;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;</b>. &#1057;&#1083;&#1086;&#1078;&#1085;&#1086; &#1088;&#1072;&#1079;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;&#1093;
    </p>
    <p>
      <font color="#0000c0">&gt; sip set debug peer &lt;&#1087;&#1080;&#1088; &#1080;&#1083;&#1080; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&gt;</font>&#160;&#160;# &#1042;&#1082;&#1083;. &#1076;&#1077;&#1073;&#1072;&#1075; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1080;&#1088;&#1072;
    </p>
    <p>
      <font color="#0000c0">&gt; originate Local/&lt;&#1084;&#1086;&#1073;.&#1085;&#1086;&#1084;&#1077;&#1088;&gt;@local application Echo</font>&#160;&#160;# &#1047;&#1074;&#1086;&#1085;&#1086;&#1082; &#1085;&#1072; &#1084;&#1086;&#1073;.&#1085;&#1086;&#1084;&#1077;&#1088; &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;
    </p>
    <p>
      <font color="#0000c0">&gt; logger mute</font>&#160;&#160;# &#1055;&#1072;&#1091;&#1079;&#1080;&#1084; &#1074;&#1099;&#1074;&#1086;&#1076; &#1076;&#1077;&#1073;&#1072;&#1075;&#1072; &#1080; &#1088;&#1072;&#1079;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1077;&#1075;&#1086;
    </p>
    <p>
      4. &#1052;&#1086;&#1076;&#1091;&#1083;&#1080;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1077;&#1089;&#1083;&#1080; &#1085;&#1077;&#1090; &#1085;&#1080; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; SIP-&#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;. &#1058;.&#1077;.&#160;&#160; <font color="#0000c0">&gt; sip show peers</font>&#160;&#160;--&gt; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1079;&#1085;&#1072;&#1102; &#1087;&#1088;&#1086; sip.
    </p>
    <p>
      <font color="#0000c0">&gt; module show | load</font>&#160;&#160;# &#1055;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;
    </p>
    <p>
      <font color="#0000c0">&gt; module reload chan_sip.so</font>&#160;&#160;# &#1047;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;
    </p>
    <p>
      5. &#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; <a href="#ID_843530826">CDR</a>&#160;- &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1072; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;
    </p>
    <p>
      <font color="#0000c0"># tail /var/log/asterisk/cdr-csv/Master.csv</font>&#160;&#160;# &#1057;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1093;&#1074;&#1086;&#1089;&#1090; &#1083;&#1086;&#1075;&#1072;
    </p>
    <p>
      6. <a href="#ID_455814438">RTP</a>&#160;debug
    </p>
    <p>
      <font color="#0000c0">&gt; rtp set debug &lt;IP-&#1072;&#1076;&#1088;&#1077;&#1089;&gt;</font>&#160;# &#160;&#1042;&#1082;&#1083;.
    </p>
    <p>
      ------------------------------
    </p>
    <p>
      sip set debug
    </p>
    <p>
      dialplan show
    </p>
    <p>
      <font color="#0000c0"># chown asterisk:asterisk file1</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1084; &#1092;&#1072;&#1081;&#1083; &#1074;&#1086; &#1074;&#1083;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077; &#1085;&#1086;&#1074;&#1086;&#1084;&#1091; &#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102;<b>:</b>&#1043;&#1088;&#1091;&#1087;&#1087;&#1077;
    </p>
    <p>
      <font color="#0000c0">&gt; core restart now</font>&#160;&#160;# &#1055;&#1086;&#1083;&#1085;&#1099;&#1081; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082; Asterisk
    </p>
  </body>
</html></richcontent>
