      </li>
      <li>
        <b>&#1054;&#1076;&#1085;&#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1103;&#1103; &#1089;&#1083;&#1099;&#1096;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100;</b><br/><font color="#0000c0">&gt; rtp set debug ip &lt;ip-&#1072;&#1076;&#1088;&#1077;&#1089; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;&gt;</font>&#160;&#160;# &#160;--&gt; &#1048;&#1085;&#1080;&#1094;&#1080;&#1080;&#1088;&#1091;&#1077;&#1084; &#1074;&#1099;&#1079;&#1086;&#1074; &#1080; &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1095;&#1090;&#1086; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090;. &#1055;&#1088;&#1080;&#1095;&#1080;&#1085;&#1099;<br/>

        <ul>
          <li>
            &#1053;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085; FreePBX - &#1085;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1099; &#1083;&#1086;&#1082;. &#1089;&#1077;&#1090;&#1080; &#1087;&#1086;&#1076; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; SIP &#1076;&#1083;&#1103; NAT<br/>
          </li>
          <li>
            &#1053;&#1077;&#1074;&#1077;&#1088;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1099; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1076;&#1083;&#1103; &#1089;&#1072;&#1084;&#1086;&#1075;&#1086; &#1087;&#1080;&#1088;&#1072; (NAT yes, NAT no)<br/>
          </li>
          <li>
            &#1055;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099; &#1089; &#1087;&#1088;&#1086;&#1073;&#1088;&#1086;&#1089;&#1086;&#1084; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; (&#1077;&#1089;&#1083;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1079;&#1072; NAT)<br/>
          </li>
          <li>
            &#1054;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; &#1088;&#1077;&#1078;&#1077;&#1090; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;<br/>
          </li>
        </ul>
      </li>
      <li>
