      </li>
      <li>
        <b>&#1055;&#1088;&#1080; &#1089;&#1090;&#1099;&#1082;&#1086;&#1074;&#1082;&#1077; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1081; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1080;&#1090;. &#1055;&#1088;&#1080; &#1089;&#1085;&#1103;&#1090;&#1080;&#1080; &#1090;&#1088;&#1091;&#1073;&#1082;&#1080; &#1080;&#1076;&#1077;&#1090; &#1086;&#1090;&#1073;&#1086;&#1081;</b>. &#1044;&#1083;&#1103; &#1086;&#1090;&#1083;&#1072;&#1076;&#1082;&#1080; &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1086;&#1076;&#1080;&#1085; &#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1076;&#1077;&#1082; &#1085;&#1072; &#1079;&#1072;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1103;&#1093;. &#1045;&#1089;&#1083;&#1080; &#1079;&#1072;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1082;&#1086;&#1076;&#1077;&#1082;&#1080;
      </li>
      <li>
        <b>&#1053;&#1077;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103;</b>. &#1089;&#1084;. <a href="#ID_1054826873">default, min, max...expiry</a>
