      </li>
      <li>
        &#1052;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1082; MySQL &#1080;&#1083;&#1080; PosrgreSQL
      </li>
    </ul>
    <p>
      <b>&#1043;&#1076;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;?</b>
    </p>
    <ul>
      <li>
        &#1056;&#1077;&#1078;&#1080;&#1084; &quot;&#1085;&#1077; &#1073;&#1077;&#1089;&#1087;&#1086;&#1082;&#1086;&#1080;&#1090;&#1100;&quot; (DND). &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;
      </li>
      <li>
        &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1079;&#1074;&#1086;&#1085;&#1080;&#1083; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091;. &#1045;&#1089;&#1090;&#1100; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;, &#1085;&#1086; &#1079;&#1072; &#1085;&#1080;&#1084; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1089;&#1086;&#1090;&#1085;&#1103; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;. &#1042;&#1077;&#1076;&#1100; &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1086; &#1079;&#1085;&#1072;&#1090;&#1100; &#1082;&#1090;&#1086; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086; &#1079;&#1074;&#1086;&#1085;&#1080;&#1083;
      </li>
      <li>
        &#1063;&#1077;&#1088;&#1085;&#1099;&#1081; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; (blacklist)
      </li>
      <li>
        &#1055;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;&#1084;&#1080;/&#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1072;&#1084;&#1080;. &#1048;&#1084;&#1077;&#1077;&#1084; &#1076;&#1074;&#1072; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072; (&#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088; &#1080; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081;). &#1052;&#1077;&#1078;&#1076;&#1091; &#1085;&#1080;&#1084;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; &#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; (&#1074;&#1086;&#1090; &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1079;&#1076;&#1077;&#1089;&#1100; &#1087;&#1088;&#1080;&#1075;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; AstDB)
      </li>
      <li>
        &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1057;&#1059;&#1041;&#1044;
      </li>
    </ul>
    <p>
      <b>&#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; CLI Asterisk</b>
    </p>
    <p>
      <font color="#0000c0">&gt; database put &lt;family&gt; &lt;key&gt;&#160;&lt;value&gt;</font>&#160;&#160;; &#1055;&#1088;&#1080;&#1084;&#1077;&#1088;: database put mobile 2011 4993332211
    </p>
    <p>
      <font color="#0000c0">&gt; database get &lt;family&gt; &lt;key&gt;</font>&#160;&#160;; &#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      <font color="#0000c0">&gt; database show</font>&#160;&#160;; &#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1074;&#1089;&#1077;&#1081; &#1041;&#1044;
    </p>
    <p>
      <font color="#0000c0">&gt; database del &lt;family&gt; &lt;key&gt;</font>&#160;&#160;; &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082;&#1083;&#1102;&#1095; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#0000c0">&gt; database deltree &lt;family&gt;&#160; </font>; &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1089;&#1077;&#1084;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;
    </p>
    <p>
      <b>Dialplan</b>&#160;(/etc/asterisk/extensions.conf)
    </p>
    <p>
      <font color="#008000">Set(DB(family/key)=value)</font>&#160;&#160;; &#1055;&#1088;&#1080;&#1089;&#1074;&#1086;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#008000">Set(KEY=${DB(family/key)})</font>&#160;&#160;; &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#008000">Noop(${DB_DELETE(family/key)})</font>&#160;&#160;; &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082;&#1083;&#1102;&#1095; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#008000">Noop(${DBdeltree(family)})</font>&#160;&#160;; &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1089;&#1077;&#1084;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="Пример. Звонки на моб.номера абонентов" ID="ID_1488620892" CREATED="1540022037440" MODIFIED="1540036925716"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;/&#1084;&#1086;&#1076;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;</b>
    </p>
    <p>
      <font color="#0000c0">&gt; database put &lt;&#1089;&#1077;&#1084;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;&gt; &lt;&#1082;&#1083;&#1102;&#1095;&gt; &lt;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;&gt;</font>&#160;&#160;; &#1055;&#1088;&#1080;&#1084;&#1077;&#1088;: database put mobile 2011 4993332211
    </p>
    <p>
      <font color="#0000c0">&gt; database get &lt;&#1089;&#1077;&#1084;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;&gt; &lt;&#1082;&#1083;&#1102;&#1095;&gt;</font>&#160; &#160;; &#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      <font color="#0000c0">&gt; database show</font>&#160;&#160;; &#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072; &#1074;&#1089;&#1077;&#1081; &#1041;&#1044;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>; /etc/asterisk/extensions.conf</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _2XXX,n,Macro(dial-mobile,${EXTEN})</font>&#160;&#160;; &#1042;&#1099;&#1079;&#1074;&#1072;&#1090;&#1100; &#1084;&#1072;&#1082;&#1088;&#1086;&#1089; &#1076;&#1083;&#1103; &#1076;&#1086;&#1079;&#1074;&#1086;&#1085;&#1072; &#1087;&#1086; GSM, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1103; &#1077;&#1084;&#1091; SIP-&#1085;&#1086;&#1084;&#1077;&#1088; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1082;&#1072;&#1082; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;
    </p>
    <p>
      <font color="#008000"><b>[macro-dial-mobile]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">exten =&gt; 1,1(mobile),Set(MobNumber=${DB(mobile/${ARG1})})</font>&#160;&#160;; &#1042;&#1099;&#1090;&#1072;&#1097;&#1080;&#1090;&#1100; &#1080;&#1079; &#1041;&#1044; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1076;&#1083;&#1103; &#1085;&#1091;&#1078;&#1085;&#1086;&#1075;&#1086; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; ; &#1080; &#1087;&#1086;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1100; &#1074; &#1077;&#1075;&#1086; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; MobNumber
    </p>
    <p>
      <font color="#008000">exten =&gt; 1,n,Dial(Dongle/dongle0/${MobNumber},100,dmghHtT)</font>&#160;&#160;; &#1047;&#1074;&#1086;&#1085;&#1080;&#1090;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; GSM-&#1084;&#1086;&#1076;&#1077;&#1084;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Пример диалплана" ID="ID_1052702569" CREATED="1540027679354" MODIFIED="1540036976822"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>; /etc/asterisk/extensions.conf</b> </font>
    </p>
    <p>
      <font color="#008000"><b>[db]</b> </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; 00,1,Set(DB(DND/${CALLERID(num)})=yes)</font>&#160;&#160;; &#1055;&#1088;&#1080; &#1085;&#1072;&#1073;&#1086;&#1088;&#1077; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; 00 &#1074; &#1089;&#1077;&#1084;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086; &#1041;&#1044; DND &#1074; &#1082;&#1083;&#1102;&#1095; &quot;&#1085;&#1086;&#1084;&#1077;&#1088; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;&quot; &#1079;&#1072;&#1085;&#1086;&#1089;&#1080;&#1090;&#1089;&#1103; &quot;yes&quot;
    </p>
    <p>
      <font color="#008000">exten =&gt; 00,2,Hangup() </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; 01,1,Set(DB(DND/${CALLERID(num)})=no))</font>&#160;&#160;; &#1055;&#1088;&#1080; &#1085;&#1072;&#1073;&#1086;&#1088;&#1077; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; 01 &#1074; &#1089;&#1077;&#1084;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086; &#1041;&#1044; DND &#1074; &#1082;&#1083;&#1102;&#1095; &quot;&#1085;&#1086;&#1084;&#1077;&#1088; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;&quot; &#1079;&#1072;&#1085;&#1086;&#1089;&#1080;&#1090;&#1089;&#1103; &quot;no&quot;
    </p>
    <p>
      <font color="#008000">exten =&gt; 01,2,Hangup() </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">exten =&gt; _X.,1,Noop(Call from ${CALLERID(num)} for ${EXTEN})</font>&#160;&#160;; --&gt; Call from 2011 for 800
    </p>
    <p>
      <font color="#008000">exten =&gt; _X.,n,Set(dnd=${DB(DND/${EXTEN})})</font>&#160;&#160;;&#160;&#160;&#1055;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1080;&#1079; &#1041;&#1044;
    </p>
    <p>
      <font color="#008000">exten =&gt; _X.,n,Noop(DND status for ${EXTEN} is ${dnd})</font>&#160;&#160;; --&gt; DND status for 800 is yes
    </p>
    <p>
      <font color="#008000">exten =&gt; _X.,n,Hengup() </font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="ODBC+Asterisk" FOLDED="true" ID="ID_1995648729" CREATED="1540032155814" MODIFIED="1733228000946"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1515403107">ODBC</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Необходимо</b>
    </p>
    <ul>
      <li>
        Установка unixODBC
      </li>
      <li>
        Установка пакетов для СУБД (mysql odbc, postgresql odbc)
      </li>
      <li>
        Asterisk должен быть сконфигурирован с поддержкой ODBC
      </li>
    </ul>
    <p>
      <b>Основные конфигурационные файлы</b>
    </p>
    <ul>
      <li>
        /etc/odbcinst.ini - Драйвера для работы с СУБД
      </li>
      <li>
        /etc/odbc.ini - Подключения к БД
      </li>
      <li>
        /etc/asterisk/res_odbc.conf - Подключения к ODBC
      </li>
      <li>
        /etc/asterisk/func_odbc.conf - Описываются SQL-запросы (которые позже станут функциями диалплана), функция диалплана создается автоматически. Настройка БД со стороны Asterisk. Для работы функции func_odbc
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="Пример1. odbc_inst.ini" ID="ID_1775391978" CREATED="1540034560427" MODIFIED="1540037550220"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b># /etc/odbcinst.ini&#160;(Ubuntu 14)</b>&#160;</font>
    </p>
    <p>
      <font color="#008000"><b>[MySQL]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">Description = ODBC for MySQL </font>
    </p>
    <p>
      <font color="#008000">Driver =&#160;/usr/lib/x86_64-linux-gnu/odbc/libmyodbc.so </font>
    </p>
    <p>
      <font color="#008000">Setup = /usr/lib/x86_64-linux-gnu/odbc/libodbcmyS.so </font>
    </p>
    <p>
      <font color="#008000">FileUsage = 1 </font>
    </p>
    <p>
      <font color="#008000"><b>[PostgreSQL]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">Description = ODBC for PostgreSQL </font>
    </p>
    <p>
      <font color="#008000">Driver =&#160;/usr/lib/x86_64-linux-gnu/odbc/psqlodbca.so </font>
    </p>
    <p>
      <font color="#008000">Setup = /usr/lib/x86_64-linux-gnu/odbc/libodbcpsqlS.so </font>
    </p>
    <p>
      <font color="#008000">FileUsage = 1</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Пример1. odbc.ini" ID="ID_866093379" CREATED="1540034610295" MODIFIED="1540037567387"><richcontent TYPE="NOTE">
