<node TEXT="# sip.conf" FOLDED="true" ID="ID_830380089" CREATED="1538221436348" MODIFIED="1541425816295"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_173636370">SIP</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>sip.conf</b>&#160;- &#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1087;&#1080;&#1088;&#1086;&#1074; (username). &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1076;&#1083;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;, &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1086;&#1074; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1097;&#1080;&#1093; &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; SIP.
    </p>
    <ul>
