      <b>vmexten=8500</b>&#160;- &#1047;&#1072;&#1076;&#1072;&#1077;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1086;&#1095;&#1085;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088; &#1076;&#1080;&#1072;&#1083;&#1087;&#1083;&#1072;&#1085;&#1072; &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1103;&#1097;&#1080;&#1082;&#1091; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085; &#1074; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077; Message-Account &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; MWI NOTIFY. &#1053;&#1091;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;, &#1077;&#1089;&#1083;&#1080; SIP-&#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1091; Message-Account.
    </p>
  </body>
</html></richcontent>
