<node TEXT="# extensions.conf (Dialplan)" FOLDED="true" ID="ID_1911092648" CREATED="1537629019509" MODIFIED="1541425844457"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_100858823">Dialplan (&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1099;_&#1041;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1100;)</a>&#160;&#160;&#160;<a href="#ID_1631042923">&#1050;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>extensions.conf </b>- &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1087;&#1083;&#1072;&#1085;&#1072; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; (Dialplan). &#1054;&#1073;&#1098;&#1103;&#1074;&#1083;&#1103;&#1077;&#1084; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1099; &#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;. &#1053;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1077;&#1083;. &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074;, &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; &#1090;&#1088;&#1072;&#1085;&#1082;&#1086;&#1074;, &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081;.&#160;
    </p>
    <p>
      <b>Dialplan</b>&#160;- &#1087;&#1083;&#1072;&#1085; &#1085;&#1072;&#1073;&#1088;&#1072;. &#1103;&#1079;&#1099;&#1082; Asterisk'&#1072; &#1089; &#1087;&#1088;&#1086;&#1089;&#1090;&#1099;&#1084; &#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;&#1086;&#1084;. &#1053;&#1072;&#1073;&#1086;&#1088; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1090;&#1077; &#1080;&#1083;&#1080; &#1080;&#1085;&#1099;&#1077; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1080;.
    </p>
    <ul>
      <li>
        Dialplan &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1080; &#1085;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1077;
      </li>
      <li>
        <b>exten =&gt;</b>&#160;&#160;==&#160; <b>exten =</b>
      </li>
      <li>
        <b>exten =&gt; 2011,1,&lt;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077;()&gt;</b>&#160;&#160;; &#1055;&#1088;&#1080; &#1079;&#1074;&#1086;&#1085;&#1082;&#1077; &#1085;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &lt;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077;&gt;
      </li>
      <li>
        &#1080;&#1084;&#1077;&#1085;&#1072; &#1087;&#1080;&#1088;&#1086;&#1074; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1086;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1099;
      </li>
      <li>
        &#1080;&#1084;&#1077;&#1085;&#1072; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1081; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1086;&#1053;&#1077;&#1047;&#1072;&#1042;&#1080;&#1057;&#1080;&#1052;&#1099;
      </li>
    </ul>
    <p>
      <font color="#008000"><b>exten =&gt; number,priority,application([parameter[,parameter2...]]) </b></font>
    </p>
    <p>
      <b><font color="#008000">exten =&gt;_X.,1,Dial(SIP/operator/${EXTEN}) </font></b>
    </p>
    <ul>
      <li>
        <b>exten =&gt;</b>&#160;- &#1074;&#1074;&#1086;&#1076;&#1085;&#1086;&#1077; &#1089;&#1083;&#1086;&#1074;&#1086;
      </li>
      <li>
        <b>_X.</b>&#160;- &#1085;&#1086;&#1084;&#1077;&#1088; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;&#1072; - <a href="#ID_789612062">&#1096;&#1072;&#1073;&#1083;&#1086;&#1085;</a><br/>
      </li>
      <li>
        <b>1&#160;</b>- &#1055;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;
      </li>
      <li>
        <b>Dial(SIP/operator/${EXTEN})</b>&#160;- &#1042;&#1099;&#1079;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;. &#1063;&#1077;&#1088;&#1077;&#1079; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1102; SIP, &#1095;&#1077;&#1088;&#1077;&#1079; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072; (&#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077;) &#1079;&#1074;&#1086;&#1085;&#1080;&#1090;&#1089;&#1103; &#1085;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1087;&#1072;&#1083; &#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;.<br/>
      </li>
      <li>
        &#1042; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1072;&#1093; &#1087;&#1083;&#1072;&#1085;&#1072; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1077; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1074;&#1099;: <b>exten, include, ignorepat &#1080; switch</b><br/>
      </li>
    </ul>
    <p>
      <font color="#0000c0">&gt; dialplan show</font>&#160;&#160;# &#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; dialplan
    </p>
    <p>
      <font color="#0000c0">&gt; dialplan show&#160;2011@&lt;&#1050;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;-default&gt;</font>&#160;&#160;# &#1050;&#1091;&#1076;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1076;&#1086;&#1079;&#1074;&#1086;&#1085;&#1080;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1091;
    </p>
    <p>
      <font color="#0000c0">&gt; dialplan show&#160;&lt;&#1050;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&gt;</font>&#160; # &#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; dialplan &#1087;&#1086; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084;&#1091; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1091;
    </p>
    <p>
      <font color="#0000c0">&gt; dialplan reload&#160; </font># &#1055;&#1077;&#1088;&#1077;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;
    </p>
  </body>
</html></richcontent>
