<node TEXT="Пример1" ID="ID_714665136" CREATED="1539942409472" MODIFIED="1541426263945"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>[incoming] </b></font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _X.,1,<b>Answer</b>()</font>&#160;&#160;; &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1086; &#1082;&#1072;&#1085;&#1072;&#1083;&#1091; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1077;&#1090; &#1074;&#1099;&#1079;&#1086;&#1074;
    </p>
    <p>
      <font color="#008000">&#160;same =&gt; n,<b>NoOp</b>(INCOMING CALL from ${CALLERID(num)}) </font><font color="#000000">&#160;; &#1053;&#1077;&#1090; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1081;. &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;</font>
    </p>
    <p>
      <font color="#008000">&#160;same =&gt; n,<b>Verbose</b>(Call to MicroSip)</font>&#160;&#160;; &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1085;&#1072;&#1076;&#1087;&#1080;&#1089;&#1100; &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;
    </p>
    <p>
      <font color="#008000">&#160;same&#160;=&gt; n,<a href="#ID_243007138">MixMonitor</a>(record1.wav)</font>&#160;&#160;; &#1074;&#1082;&#1083;. &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;
    </p>
    <p>
      <font color="#008000">&#160;same&#160;=&gt; n,<b>Dial</b>(SIP/jitsi,10)</font>&#160;&#160;; &#1076;&#1086;&#1079;&#1074;&#1086;&#1085;. 10 - &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;
    </p>
    <p>
      <font color="#008000">&#160;same&#160;=&gt; n,<b>Voicemail</b>(2011@default,u)</font>&#160;&#160;; &#1055;&#1088;&#1080; &#1085;&#1077;&#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086;&#1084; &#1076;&#1086;&#1079;&#1074;&#1086;&#1085;&#1077; --&gt; &#1075;&#1086;&#1083;&#1086;&#1089;. &#1103;&#1097;&#1080;&#1082;. &#1074; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1077; default
    </p>
    <p>
      <font color="#008000">&#160;same&#160;=&gt; n,<b>Playback</b>(file1)</font>&#160;&#160;; &#1055;&#1088;&#1086;&#1080;&#1075;&#1088;&#1072;&#1090;&#1100; &#1079;&#1074;&#1091;&#1082;&#1086;&#1074;&#1086;&#1081; &#1092;&#1072;&#1081;&#1083;
    </p>
    <p>
      <font color="#008000">&#160;same&#160;=&gt; n,<b>Hangup</b>()</font>&#160;&#160;; &#1055;&#1088;&#1086;&#1074;&#1077;&#1089;&#1080;&#1090;&#1100; &#1090;&#1088;&#1091;&#1073;&#1082;&#1091;&#160;
    </p>
    <p>
      ..................................
    </p>
    <p>
      <font color="#008000"><b>[local]</b></font>&#160;&#160;; &#1048;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;. &#1044;&#1083;&#1103; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; <b>Answer() &#1085;&#1077; &#1085;&#1091;&#1078;&#1077;&#1085;</b><font color="#008000">&#160;</font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _7XXXXXXXXXX,1,Noop(Outgoing call)</font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _7XXXXXXXXXX,n,Dial(SIP/multifon/${EXTEN})</font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _20XX,1,Noop(Local &#1057;all ${EXTEN})</font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _20XX,n,Dial(SIP/${EXTEN})</font>&#160;&#160;; &#1044;&#1083;&#1103; &#1095;&#1077;&#1090;&#1099;&#1088;&#1077;&#1093;&#1079;&#1085;&#1072;&#1095;&#1085;&#1099;&#1093; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; &#1089; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1084; &#1087;&#1086; SIP &#1087;&#1086; &#1074;&#1085;. &#1085;&#1086;&#1084;&#1077;&#1088;&#1091;
    </p>
    <p>
      <font color="#008000">exten =&gt; <b>h</b>,1,Noop(Hangup)</font>&#160;&#160;# &#1057;&#1083;&#1091;&#1078;&#1077;&#1073;&#1085;&#1099;&#1081; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1087;&#1086;&#1095;&#1077;&#1084;&#1091; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1080;&#1083;&#1089;&#1103; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082;
    </p>
    <p>
      <font color="#008000">exten =&gt; <b>h</b>,n,Noop(${DIALSTATUS})</font>
    </p>
    <p>
      <font color="#008000"><b>include</b>&#160;=&gt; codes</font>&#160;&#160;# &#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1074;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; codes
    </p>
    <p>
      <font color="#008000">exten =&gt; 123,1,Goto(ivr,s,1)</font>&#160;&#160;; exten =&gt; 123,n,Goto(&#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;,&#1076;&#1086;&#1073;.&#1085;&#1086;&#1084;&#1077;&#1088;-&#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;,&#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;)
    </p>
    <p>
      
