    <p>
      &#160;&#160;&#160;&#160;<b>t:</b>&#160;(Timeout) &#8211; &#1058;&#1072;&#1081;&#1084;-&#1072;&#1091;&#1090;. &#1042;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1087;&#1088;&#1080; &#1085;&#1072;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1080; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1090;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090;&#1072;. &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1101;&#1090;&#1086;&#1075;&#1086; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;&#1072; &#1073;&#1091;&#1076;&#1091;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1099;, &#1077;&#1089;&#1083;&#1080; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090; &#1085;&#1077; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1077;&#1083; &#1085;&#1080;&#1082;&#1072;&#1082;&#1080;&#1093; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1081; &#1074; &#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082; &#1077;&#1084;&#1091; &#1073;&#1099;&#1083;&#1086; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1072;&#1085;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1080;&#1083;&#1080; &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1102; &#1090;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; WaitExten, &#1085;&#1072;&#1088;&#1080;&#1084;&#1077;&#1088;. &#1058;&#1072;&#1082;&#1078;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1073;&#1077;&#1079;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1102;&#10