<node TEXT="Пример 1" ID="ID_1133155682" CREATED="1539952167055" MODIFIED="1540895557448"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>; /etc/asterisk/extensions.conf </b></font>
    </p>
    <p>
      <font color="#008000"><b>[local]</b></font>&#160;&#160;; &#1048;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;. &#1044;&#1083;&#1103; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; <b>Answer() &#1085;&#1077; &#1085;&#1091;&#1078;&#1077;&#1085;</b><font color="#008000">&#160;</font>
    </p>
    <p>
      <font color="#008000"><b>include</b>&#160;=&gt; variables&#160; </font># &#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1074;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; variables
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>[variables]</b></font>&#160;&#160;; &#1056;&#1072;&#1073;&#1086;&#1090;&#1072; &#1089; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1084;&#1080;
    </p>
    <p>
      <font color="#008000">exten =&gt; 33,1,Set(Foo=${CALLERID(num)})</font>&#160;&#160;; &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#008000">exten =&gt; 33,n,Noop(${Foo})</font>&#160;&#160;; 2011
    </p>
    <p>
      <font color="#008000">&#160;same =&gt; n,Set(Foo=1234)</font>&#160;&#160;; &#1055;&#1077;&#1088;&#1077;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#008000">exten =&gt; 33,n,Set(F2=${Foo<b>:</b>2<b>:</b>1})</font>&#160;&#160;; &#1056;&#1072;&#1073;&#1086;&#1090;&#1072; &#1089;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;&#1086;&#1081;. &#1042;&#1079;&#1103;&#1090;&#1100; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1086;&#1090; 2-&#1075;&#1086; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072; &#1080; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; 1 &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;
    </p>
    <p>
      <font color="#008000">&#160;same =&gt; n,Noop(${F2})</font>&#160;&#160;;&#160;3
    </p>
    <p>
      <font color="#008000">&#160;same =&gt; n,Set(Result=$<b>[</b>${Foo}+2<b>]</b>)</font>&#160;&#160;; &#1040;&#1088;&#1080;&#1092;&#1084;&#1077;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      <font color="#008000">&#160;same =&gt; n,Noop(${Result})</font>&#160;&#160;; 1236
    </p>
    <p>
      
    </p>
    <p>
      <b>; &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1079;&#1085;&#1072;&#1077;&#1084; &#1082;&#1072;&#1082; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1085;&#1072;&#1073;&#1080;&#1088;&#1072;&#1090;&#1100; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1099;&#1077; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; (&#1089; 8, &#1089; 7, &#1089; +8, &#1089; +7, &#1073;&#1077;&#1079; 8 &#1080;&#1083;&#1080; 7) </b>
    </p>
    <p>
      <font color="#008000">exten =&gt; 10,1,Set(num=${EXTEN}2)</font>&#160;&#160;; 102
    </p>
    <p>
      <font color="#008000">exten =&gt; 10,n,Goto(local,${num},1)</font>&#160;&#160;; &#1055;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080; &#1085;&#1072; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; [local] &#1085;&#1086;&#1084;&#1077;&#1088; 102<font color="#008000">&#160;</font>
    </p>
  </body>
</html></richcontent>
