    <p>
      <font color="#008000"><b>[globals]</b></font>
    </p>
    <p>
      <font color="#008000"><b>[default]</b>&#160;&#160; </font>; &#1050;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1077; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072;. &#1054;&#1073;&#1083;&#1072;&#1076;&#1072;&#1090;&#1077;&#1083;&#1080; &#1101;&#1090;&#1086;&#1075;&#1086; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1080;&#1076;&#1077;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1074;&#1086;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;. <b>&#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;</b>, &#1074; <a href="#ID_830380089">sip.conf</a>&#160; &#1091; &#1074;&#1089;&#1077;&#1093; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1074; &#1073;&#1091;&#1076;&#1077;&#1090; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; <b>default. </b>&#1063;&#1090;&#1086;&#1073;&#1099; &#1101;&#1090;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100;, &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;. &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; '<b>context=local</b>&#160;&#1080;&#1083;&#1080; ld&#160;&#1080;&#1083;&#1080; intl'
    </p>
    <p>
