    </p>
    <p>
      <font color="#008000">exten =&gt; 2012,1,Dial(SIP/microsip) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; 2013,1,Dial(SIP/xlite)</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>[local]</b></font>&#160;&#160;; &#1050;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;. &#1052;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1085;&#1072; &#1075;&#1086;&#1088;&#1086;&#1076;&#1089;&#1082;&#1091;&#1102; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1091;&#1102; &#1089;&#1077;&#1090;&#1100;. &#1054;&#1073;&#1083;&#1072;&#1076;&#1072;&#1090;&#1077;&#1083;&#1080; local &#1074;&#1080;&#1076;&#1103;&#1090; + default
