    </p>
    <p>
      <font color="#008000">exten =&gt; _99[2-9]XX[2-9]XXXXXX,1,Dial(SIP/pstn/${EXTEN:1}) </font>
    </p>
    <p>
      <b><font color="#008000">[intl]</font></b>&#160;&#160;; &#1050;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;. &#1052;&#1077;&#1078;&#1076;&#1091;&#1085;&#1072;&#1088;&#1086;&#1076;&#1085;&#1099;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;. intl <b>&#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1074; &#1089;&#1077;&#1073;&#1103;</b>&#160;&#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; <b>ld</b>
    </p>
    <p>
      <font color="#008000">include =&gt; <b>ld</b></font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _9810.,1,Dial(SIP/pstn/${EXTEN:1}) </font>
