    <p>
      <b>AMD</b>&#160;- &#1042;&#1099;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1072;&#1074;&#1090;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1095;&#1080;&#1082;&#1072;
    </p>
    <p>
      <b>Answer</b>&#160;- &#1059;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1086; &#1082;&#1072;&#1085;&#1072;&#1083;&#1091; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1077;&#1090; &#1074;&#1099;&#1079;&#1086;&#1074;. &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1091;&#1102; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1091; &#1076;&#1083;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1074;&#1099;&#1079;&#1086;&#1074;. (&#1053;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1102;&#1090; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1086;&#1090;&#1074;&#1077;&#1090;&#1072; &#1082;&#1072;&#1085;&#1072;&#1083;&#1091;, &#1085;&#1086; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1081; &#1086;&#1090;&#1074;&#1077;&#1090; &#1085;&#1072; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1087;&#1077;&#1088;&#1077;&#1076; &#1090;&#1077;&#1084;, &#1082;&#1072;&#1082; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1082;&#1072;&#1082;&#1080;&#1077;-&#1083;&#1080;&#1073;&#1086; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103; &#1085;&#1072;&#1076; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1084;, &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1086;&#1095;&#1077;&#1085;&#1100; &#1093;&#1086;&#1088;&#1086;&#1096;&#1077;&#1081; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1086;&#1081;). Answer() &#1085;&#1077; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;.
    </p>
    <p>
      <b>AppendCDRUserField</b>&#160;- &#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074; &#1087;&#1086;&#1083;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; Call Detail Record
    </p>
    <p>
      <b>Authenticate</b>&#160;- &#1040;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1087;&#1086; &#1085;&#1072;&#1073;&#1088;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; &#1082;&#1086;&#1076;&#1091;. &#1087;&#1086;&#1087;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1079;&#1074;&#1086;&#1085;&#1103;&#1097;&#1077;&#1075;&#1086; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; PIN-&#1082;&#1086;&#1076;
    </p>
    <p>
      <b>Background</b>&#160;- &#1042;&#1086;&#1089;&#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090; &#1092;&#1072;&#1081;&#1083;, &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1103; &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1099; &#1090;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; (DTMF), &#1074; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; Playback()
    </p>
    <p>
      <b>BackgroundDetect</b>&#160;- &#1042;&#1086;&#1089;&#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090; &#1092;&#1072;&#1081;&#1083; &#1074; &#1092;&#1086;&#1085;&#1086;&#1074;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1080; &#1074;&#1099;&#1103;&#1074;&#1083;&#1103;&#1077;&#1090; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;
    </p>
    <p>
      <b>Busy</b>&#160;- &#1054;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1079;&#1072;&#1085;&#1103;&#1090;&#1086;&#1089;&#1090;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;
