<node TEXT="MixMonitor, Monitor" FOLDED="true" ID="ID_243007138" CREATED="1539077401200" MODIFIED="1540568856485"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1361614273">Audacity</a>&#160;&#160; 
    </p>
    <p>
      
    </p>
    <p>
      <b>MixMonitor</b>() - &#1047;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088; &#1087;&#1086; &#1082;&#1072;&#1085;&#1072;&#1083;&#1091; &#1074; &#1092;&#1086;&#1085;&#1086;&#1074;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077;, &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1085;&#1086; &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1103;&#1103; &#1086;&#1073;&#1072; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1072;
    </p>
    <ul>
      <li>
        &#1047;&#1074;&#1091;&#1082;&#1086;&#1074;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; <b>/var/spool/asterisk/monitor</b>
      </li>
      <li>
        <p>
          <b>Monitor</b>&#160;- &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1072; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1074; 2-&#1077; &#1076;&#1086;&#1088;&#1086;&#1078;&#1082;&#1080; (&#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090; &#1080; &#1079;&#1074;&#1086;&#1085;&#1103;&#1097;&#1080;&#1081;)
        </p>
      </li>
      <li>
        <p>
          <b>MixMonitor</b>&#160;- &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1072; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; (&#1086;&#1076;&#1085;&#1072; &#1086;&#1073;&#1097;&#1072;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;)
        </p>
      </li>
    </ul>
    <p>
      <b>&#1047;&#1072;&#1087;&#1080;&#1089;&#1100; &#1080;&#1079; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080;.</b>&#160; &#1042;&#1099;&#1073;&#1086;&#1088; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; Asterisk &#1087;&#1088;&#1077;&#1076;&#1083;&#1072;&#1075;&#1072;&#1077;&#1090; &#1089;&#1072;&#1084; &#1087;&#1086; Tab + &#1079;&#1072;&#1076;&#1072;&#1077;&#1084; &#1080;&#1084;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      <font color="#0000c0">&gt;&#160;&#160;mixmonitor start SIP/jitsi-00000005 rec1.wav</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;. </b>
    </p>
    <p>
      <b>${CALLERID(num)}</b>&#160;- &#1085;&#1086;&#1084;&#1077;&#1088; &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1079;&#1074;&#1086;&#1085;&#1080;&#1083;&#1080;. &#1054;&#1085; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085; &#1074; callerid &#1092;&#1072;&#1081;&#1083;&#1072; sip.conf
    </p>
    <p>
      <b>${EXTEN}</b>&#160;- &#1085;&#1072;&#1073;&#1088;&#1072;&#1085;&#1085;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>; /etc/asterisk/extensions.conf </b></font>
    </p>
    <p>
      <font color="#008000">exten =&gt; 772011,1,NoOp() ; &#1047;&#1072;&#1087;&#1080;&#1089;&#1100; &#1087;&#1088;&#1080; &#1079;&#1074;&#1086;&#1085;&#1082;&#1077; &#1085;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088; 772011</font>
    </p>
    <p>
      &#160;; &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102;. &#1048;&#1084;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072; - &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; (UNIX time)
    </p>
    <p>
      <font color="#008000">&#160;same =&gt; n,<b>Set</b>(<b>recfile</b>=${<b>EPOCH</b>})</font>&#160;
    </p>
    <p>
      <font color="#008000">&#160;same =&gt; n,MixMonitor(${recfile}_${CALLERID(num)}_${EXTEN}.wav)</font>
    </p>
    <p>
      <font color="#008000">&#160;same =&gt; n,Dial(SIP/jitsi)</font>
    </p>
  </body>
</html></richcontent>
