<node TEXT="Предоставить право записи абоненту" ID="ID_435865368" CREATED="1539344680066" MODIFIED="1539347017540"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100;&#160;&#160;&#1087;&#1088;&#1072;&#1074;&#1086; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1091;</b>&#160;(&#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1077; *1 &#1080;&#1083;&#1080; *3 &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1072;)
    </p>
    <ul>
      <li>
        &#1047;&#1072;&#1087;&#1080;&#1089;&#1100; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; <b>auto-&lt;unixtime&gt;-&lt;caller&gt;-&lt;&#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&gt;.wav</b>
      </li>
    </ul>
    <p>
      <font color="#008000"><b>; /etc/asterisk/features.conf</b></font>
    </p>
    <p>
      <font color="#008000">[featuremap]</font>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;; &#1054;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1091; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081;
    </p>
    <p>
      <font color="#008000">automon =&gt; *1</font>&#160;&#160;&#160;&#160;&#160;&#160;&#160;; &#1047;&#1072;&#1087;&#1080;&#1089;&#1100; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; 2-&#1093; &#1076;&#1086;&#1088;&#1086;&#1078;&#1077;&#1082; (&#1074; &#1076;&#1074;&#1072; &#1092;&#1072;&#1081;&#1083;&#1072;)
    </p>
    <p>
      <font color="#008000">automixmon =&gt; *3</font>&#160;&#160;; &#1047;&#1072;&#1087;&#1080;&#1089;&#1100; &#1079;&#1074;&#1086;&#1085;&#1103;&#1097;&#1077;&#1075;&#1086; &#1080; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1074; &#1086;&#1076;&#1080;&#1085; &#1092;&#1072;&#1081;&#1083;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>; /etc/asterisk/extensions.conf </b></font>
    </p>
    <p>
      <b>; wW</b>&#160;- &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1084; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;&#1084; Monitor
    </p>
    <p>
      <b>; xX</b>&#160;- &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1084; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;&#1084; MixMonitor
    </p>
    <p>
      <font color="#008000">exten =&gt; 2011,1,Dial(SIP/jitsi,<b>10</b>,<b>xXwW</b>)</font>&#160;&#160;; 10 - &#1089;&#1077;&#1082;. &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1078;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1074;&#1074;&#1086;&#1076;&#1072; &#1090;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; (&#1085;&#1072;&#1087;&#1088;. <b>*3</b>)
    </p>
  </body>
</html></richcontent>
</node>
</node>
</node>
</node>
<node TEXT="cdr.conf" ID="ID_938739108" CREATED="1538489855446" MODIFIED="1540891978015"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_843530826">&#1057;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1072; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; (CDR)</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>enable</b>&#160;- &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1083;&#1086;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; CDR
    </p>
    <p>
      <b>unanswered</b>&#160;- &#1073;&#1091;&#1076;&#1091;&#1090; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1072;&#1078;&#1077; &#1090;&#1077; CDR (&#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1086; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;&#1093;), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1077; &#1073;&#1099;&#1083;&#1080; &#1086;&#1090;&#1074;&#1077;&#1095;&#1077;&#1085;&#1099;. &#1058;.&#1077;. &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1090;&#1072;&#1097;&#1080;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1082;&#1090;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1074;&#1089;&#1077;&#1093; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1076; &#1101;&#1090;&#1080;&#1084; &#1074; &#1041;&#1044;
    </p>
    <p>
      <b>batch</b>&#160;- &#1088;&#1077;&#1075;&#1091;&#1083;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1085;&#1072;&#1088;&#1075;&#1091;&#1079;&#1082;&#1080; &#1041;&#1044; &lt;--&gt; Asterisk. &#1057;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1080;&#1083;&#1080; &#1096;&#1090;&#1091;&#1082; &#1085;&#1072;&#1082;&#1072;&#1087;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1080;&#1085;&#1092;. &#1086; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;&#1093; &#1087;&#1077;&#1088;&#1077;&#1076; &#1089;&#1082;&#1080;&#1076;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1080;&#1079; &#1073;&#1091;&#1092;&#1077;&#1088;&#1072; Asterisk &#1074; &#1041;&#1044;. &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1082;&#1080;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100; &#1089;&#1088;&#1072;&#1079;&#1091; &#1087;&#1086;&#1089;&#1083;&#1077; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1085;&#1080;&#1103; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1072;, &#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1082;&#1072;&#1087;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100;.
    </p>
    <p>
      <b>safeshutdown.&#160;</b>&#1045;&#1089;&#1083;&#1080; 'yes', &#1090;&#1086; Asterisk &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1091;&#1075;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1088;&#1080; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1077;&#1085;&#1080;&#1080; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1077;&#1089;&#1083;&#1080; &#1074; &#1073;&#1091;&#1092;&#1077;&#1088;&#1077; &#1086;&#1089;&#1090;&#1072;&#1083;&#1080;&#1089;&#1100; CDR
    </p>
    <p>
      
    </p>
    <p>
      <b>[csv] </b>
    </p>
    <p>
      <b>usegmtime=yes</b>&#160;&#160;&#1041;&#1077;&#1082;&#1077;&#1085;&#1076;&#1099; &#1076;&#1083;&#1103; &#1089;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; CDR
    </p>
  </body>
</html></richcontent>
</node>
