<node TEXT="ooh323.conf" ID="ID_140345613" CREATED="1538477360626" MODIFIED="1539177328889"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1898962387">H.323</a>
    </p>
    <ul>
      <li>
        &#1085;&#1077;&#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1084;&#1099;&#1081;, &#1088;&#1072;&#1079;&#1074;&#1080;&#1090;&#1080;&#1077; &#1086;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1083;&#1086;&#1089;&#1100;
      </li>
      <li>
        &#1087;&#1088;&#1077;&#1080;&#1084;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074; &#1087;&#1077;&#1088;&#1077;&#1076; sip &#1085;&#1077;&#1090;, &#1090;&#1072;&#1082;&#1078;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;
      </li>
      <li>
        Asterisk &#1080;&#1084;&#1077;&#1077;&#1090; <b>&#1076;&#1074;&#1077; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;</b>&#160;H.323
      </li>
    </ul>
    <p>
      <b>h323.conf</b>&#160;- &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; H.323 &#1074; &#1091;&#1089;&#1090;&#1072;&#1088;&#1077;&#1074;&#1096;&#1077;&#1081; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;. &#1086;&#1095;&#1077;&#1085;&#1100; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; (&#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090;&#1089;&#1103; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1074; &#1072;&#1076;&#1076;&#1086;&#1085;&#1072;&#1093;)
    </p>
    <p>
      <b>ooh323.conf</b>&#160;- &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; H.323 &#1074; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; Objective Oriented H.323.
    </p>
    <p>
      
    </p>
    <p>
      &gt; ooh323 show config
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">[general] </font>
    </p>
    <p>
      <font color="#008000">bindaddr=1.1.1.1</font>&#160;&#160;; &#1044;&#1086;&#1083;&#1078;&#1077;&#1085; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089; &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1084; &#1085;&#1072;&#1096;&#1080;&#1093; &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1093; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1074;
    </p>
    <p>
      <font color="#008000">gateway=yes</font>&#160;&#160;; &#1044;&#1083;&#1103; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080; &#1085;&#1072; &#1075;&#1077;&#1081;&#1090;&#1082;&#1080;&#1087;&#1077;&#1088;&#1077;
    </p>
    <p>
      <font color="#008000">disallow=all</font>&#160;&#160;; <a href="#ID_1509033950">&#1050;&#1086;&#1076;&#1077;&#1082;&#1080;</a>
    </p>
    <p>
      <font color="#008000">allow=alaw</font>
    </p>
  </body>
</html></richcontent>
</node>
