<node TEXT="Просмотр через web-интерфейс" ID="ID_1045179270" CREATED="1539588477281" MODIFIED="1539588909605"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; Apache</b>
    </p>
    <p>
      <font color="#0000c0">yum -y install httpd mod_ssl</font>&#160;&#160;# &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; Apache:
    </p>
    <p>
      <font color="#0000c0">chkconfig httpd on</font>&#160;&#160;# &#1055;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; Apache &#1074; &#1072;&#1074;&#1090;&#1086;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;:
    </p>
    <p>
      <font color="#0000c0">service httpd start</font>&#160;&#160;# &#1055;&#1091;&#1089;&#1082; Apache
    </p>
    <p>
      <font color="#0000c0">yum -y install php php-common php-gd php-mysql php-xml php-mbstring</font>&#160;&#160;# <b>&#160;&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; PHP</b>
    </p>
    <p>
      <font color="#0000c0">service httpd restart</font>&#160;&#160;# &#1055;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082; Apache --&gt; &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1095;&#1077;&#1088;&#1077;&#1079; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;
    </p>
    <p>
      <b>2. Apache-&#1092;&#1072;&#1081;&#1083;&#1099; /var/www/html</b>
    </p>
    <p>
      &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; 2 &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1088;&#1080;&#1080; &#1074; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1077; html &#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1090;&#1091;&#1076;&#1072; &#1092;&#1072;&#1081;&#1083; index.php (&#1074;&#1099;&#1073;&#1086;&#1088;&#1082;&#1072; &#1080; &#1074;&#1086;&#1089;&#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077;)
    </p>
    <p>
      <font color="#0000c0">mkdir /var/www/html/callrecords </font>
    </p>
    <p>
      <font color="#0000c0">mkdir /var/www/html/voicemail</font>
    </p>
    <p>
      <font color="#0000c0">vi /var/www/html/&lt;2-&#1072; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072;&gt;/<b>index.php</b></font>&#160;&#160;# &#1060;&#1072;&#1081;&#1083; &#1074; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1080;&#1079; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;
    </p>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">$file_list = glob(&quot;*.wav&quot;); </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1103;&#1085;&#1074;&#1072;&#1088;&#1103;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1092;&#1077;&#1074;&#1088;&#1072;&#1083;&#1103;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1084;&#1072;&#1088;&#1090;&#1072;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1072;&#1087;&#1088;&#1077;&#1083;&#1103;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1084;&#1072;&#1103;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1080;&#1102;&#1085;&#1103;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1080;&#1102;&#1083;&#1103;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1072;&#1074;&#1075;&#1091;&#1089;&#1090;&#1072;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1089;&#1077;&#1085;&#1090;&#1103;&#1073;&#1088;&#1103;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1086;&#1082;&#1090;&#1103;&#1073;&#1088;&#1103;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1085;&#1086;&#1103;&#1073;&#1088;&#1103;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$q[]=&quot;&#1076;&#1077;&#1082;&#1072;&#1073;&#1088;&#1103;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$dlina=count($file_list); </font>
    </p>
    <p>
      <font color="#008000">echo &quot;&#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; = &quot;.$dlina.&quot;&lt;br&gt;&quot;; </font>
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;form name=&quot;test&quot; method=&quot;post&quot; action=&quot;index.php&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#1042;&#1074;&#1077;&#1076;&#1080;&#1090;&#1077; &#1075;&#1086;&#1076; &#1084;&#1077;&#1089;&#1103;&#1094; &#1095;&#1080;&#1089;&#1083;&#1086;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; (20110228)&lt;input name=&quot;date&quot; type=&quot;text&quot; value=&quot;&lt;?php echo </font>
    </p>
    <p>
      <font color="#008000">$_POST['date']; ?&gt;&quot;size=&quot;10&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;input type=&quot;submit&quot; value=&quot;&#1054;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100;&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/form&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">if ($_POST['date']&lt;&gt;&quot;&quot;) { </font>
    </p>
    <p>
      <font color="#008000">$day=substr($_POST['date'], 6, 2); </font>
    </p>
    <p>
      <font color="#008000">$month=substr($_POST['date'], 4, 2); </font>
    </p>
    <p>
      <font color="#008000">$year=substr($_POST['date'], 0, 4); </font>
    </p>
    <p>
      <font color="#008000">echo &quot;&#1047;&#1074;&#1086;&#1085;&#1082;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1099;&#1077; &quot;.$day.&quot; &quot;.$q[$month].&quot; &quot;.$year.&quot;&lt;br&gt;&quot;; </font>
    </p>
    <p>
      <font color="#008000">$datelist=$_POST['date']; </font>
    </p>
    <p>
      <font color="#008000">echo &quot;&lt;pre&gt;&quot;; </font>
    </p>
    <p>
      <font color="#008000">for ($i=0;$i&lt;=count($file_list);$i++) </font>
    </p>
    <p>
      <font color="#008000">{ $ </font>
    </p>
    <p>
      <font color="#008000">day=substr($file_list[$i], 6, 2); </font>
    </p>
    <p>
      <font color="#008000">$month=substr($file_list[$i], 4, 2); </font>
    </p>
    <p>
      <font color="#008000">$year=substr($file_list[$i], 0, 4); </font>
    </p>
    <p>
      <font color="#008000">$time=substr($file_list[$i], 8, 4); </font>
    </p>
    <p>
      <font color="#008000">$napravlenie=substr($file_list[$i], 13, 20); </font>
    </p>
    <p>
      <font color="#008000">$timeq=$time[0].&quot;&quot;.$time[1].&quot;:&quot;.$time[2].&quot;&quot;.$time[3]; </font>
    </p>
    <p>
      <font color="#008000">$string=substr($file_list[$i], 0, strlen($datelist)); </font>
    </p>
    <p>
      <font color="#008000">if ($string==$datelist) echo &quot;&lt;a href=&quot;.$file_list[$i].&quot;&gt;&quot;.$day.&quot; &quot;.$q[$month].&quot; &quot;.$year.&quot; &#1074; &quot;.$timeq.&quot; </font>
    </p>
    <p>
      <font color="#008000">&quot;.$napravlenie.&quot;&lt;/a&gt;\n&quot;; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      <font color="#008000">echo &quot;&lt;/pre&gt;&quot;; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      <font color="#008000">?&gt;</font>
    </p>
    <p>
      <b>3. /etc/asterisk/extensions.conf</b>. &#1055;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1087;&#1091;&#1090;&#1080; &#1076;&#1083;&#1103; 3-&#1093; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081;
    </p>
    <p>
      <font color="#008000">exten =&gt; _X.,2,MixMonitor(/var/www/html/callrecords/${fname}.wav,b) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; s,2,MixMonitor(/var/www/html/callrecords/${fname}.wav) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; s,3,Record(/var/www/html/voicemail/${fname}.wav,0,15,X) </font>
    </p>
    <p>
      <b>4. &#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077;</b>
    </p>
    <p>
      http://&lt;IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&gt;/callrecords/
    </p>
    <p>
      http://&lt;IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&gt;/voicemail/
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Конференция" ID="ID_1445986552" CREATED="1537630427418" MODIFIED="1539773106760"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; <b>&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084; IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072;</b>. &#1051;&#1102;&#1073;&#1086;&#1081; SIP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1077;&#1097;&#1077; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1072; &#1074; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;
      </li>
      <li>
        <b>&#1050;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1089;-&#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1072;</b>. &#1053;&#1077;&#1082;&#1080;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1085;&#1080;&#1074; &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1087;&#1072;&#1089;&#1090;&#1100; &#1074; &#1101;&#1090;&#1091; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1091;. &#1055;&#1086;&#1076;&#1093;&#1086;&#1076;&#1080;&#1090; &#1076;&#1083;&#1103; &#1089;&#1086;&#1074;&#1077;&#1097;&#1072;&#1085;&#1080;&#1081;. &#1085;&#1077;&#1090; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086; &#1082;&#1086;&#1083;-&#1074;&#1091; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1086;&#1074;
      </li>
      <li>
        &#1047;&#1072;&#1087;&#1080;&#1089;&#1080; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1081; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1087;&#1086; &#1087;&#1091;&#1090;&#1080; <b>/var/spool/asterisk/confbridge</b>
      </li>
    </ul>
    <p>
      <font color="#0000c0">&gt; confbridge list primary</font>&#160;&#160;# &#1057;&#1086;&#1089;&#1090;&#1072;&#1074; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080; primary
    </p>
    <p>
      <font color="#0000c0">&gt; confbridge show profile bridge default_bridge</font>&#160;&#160;# &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>; /etc/asterisk/extensions.conf</b></font>&#160;- &#1077;&#1089;&#1083;&#1080; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &#1082;&#1088;&#1086;&#1084;&#1077; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; (&#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1099;), &#1090;&#1086; &#1089;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1076;&#1077;&#1092;&#1086;&#1083;&#1090;&#1085;&#1099;&#1077; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1099; &#1080;&#1079; confbridge.conf ([default_user], [default_bridge])
    </p>
    <p>
      <font color="#008000">exten =&gt; 7000,1,ConfBridge(&lt;&#1080;&#1084;&#1103;_&#1082;&#1086;&#1085;&#1092;.&gt;,myconfbridge,generaluser,menu)</font>
    </p>
    <p>
      &#160;&#160;&#160;&#160;; 7000 - &#1085;&#1086;&#1084;&#1077;&#1088; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072; (&#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1099;) &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1082; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080;
    </p>
    <p>
      &#160;&#160;&#160;&#160;; myconfbridge&#160;- &#1087;&#1088;&#1086;&#1092;&#1080;&#1083;&#1100; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080; (&#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; &#1080;&#1079; confbridge.conf)
    </p>
    <p>
      &#160;&#160;&#160;&#160;; generaluser - &#1087;&#1088;&#1086;&#1092;&#1080;&#1083;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; (&#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; &#1080;&#1079; confbridge.conf)
    </p>
    <p>
      &#160;&#160;&#160;&#160;; menu - &#1084;&#1077;&#1085;&#1102; (&#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; &#1080;&#1079; confbridge.conf)
    </p>
    <p>
      <font color="#008000">exten =&gt; 8000,1,ConfBridge(&lt;&#1080;&#1084;&#1103;_&#1082;&#1086;&#1085;&#1092;.&gt;,myconfbridge,adminuser,admin_menu)</font>&#160; &#160;; &#1076;&#1083;&#1103; &#1083;&#1080;&#1076;&#1077;&#1088;&#1072; &#1082;&#1086;&#1085;&#1092;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>; /etc/asterisk/confbridge.conf</b>&#160;</font>
    </p>
    <p>
      <b><font color="#008000">[myconfbridge]</font></b>&#160;&#160;; &#1055;&#1088;&#1086;&#1092;&#1080;&#1083;&#1100; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080;
    </p>
    <p>
      <font color="#008000">type=bridge</font>&#160;&#160;; &#1050;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1103;
    </p>
    <p>
      <font color="#008000">max_members=20</font>&#160;&#160;; &#1052;&#1072;&#1082;&#1089;. &#1082;&#1086;&#1083;-&#1074;&#1086; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1086;&#1074;
    </p>
    <p>
      <font color="#008000">mixing_interval=10</font>&#160;&#160;; &#1084;&#1089;. &#1044;&#1083;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;. &#1085;&#1072;&#1088;&#1077;&#1079;&#1082;&#1080; &#1079;&#1074;. &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074; &#1085;&#1072; &#1089;&#1077;&#1084;&#1087;&#1083;&#1099; &#1076;&#1083;&#1103; &#1080;&#1093; &#1089;&#1084;&#1077;&#1096;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#008000">internal_sample_rate=auto</font>&#160;&#160;; &#1042;&#1085;&#1091;&#1090;&#1088;. &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1072; &#1076;&#1080;&#1089;&#1082;&#1088;&#1077;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1076;&#1083;&#1103; &#1089;&#1084;&#1077;&#1096;. &#1079;&#1074;. &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074; &#1074; &#1082;&#1086;&#1085;&#1092;.
    </p>
    <p>
      <font color="#008000">record_conference=yes</font>&#160;&#160;; &#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;&#160;&#160;&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080;
    </p>
    <p>
      <b><font color="#008000">[generaluser]</font></b>&#160;&#160;; &#1055;&#1088;&#1086;&#1092;&#1080;&#1083;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
    </p>
    <p>
      <font color="#008000">type=user</font>
    </p>
    <p>
      <font color="#008000">music_on_hold_when_empty=yes</font>&#160;; &#1048;&#1075;&#1088;&#1072;&#1090;&#1100; &#1084;&#1091;&#1079;&#1099;&#1082;&#1091;, &#1087;&#1086;&#1082;&#1072; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1080; &#1086;&#1078;&#1080;&#1076;&#1072;&#1102;&#1090; &#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1082;&#1086;&#1085;&#1092;.
    </p>
    <p>
