<node TEXT="Парковка звонка" ID="ID_761684392" CREATED="1539351032445" MODIFIED="1540827005473"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Park Call</b>&#160;- &#1087;&#1072;&#1088;&#1082;&#1091;&#1077;&#1084; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082;, &#1080;&#1076;&#1077;&#1084; &#1082; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1091; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1074; &#1087;&#1077;&#1088;&#1077;&#1075;&#1086;&#1074;&#1086;&#1088;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1077;) &#1080; &#1079;&#1072;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1074;&#1099;&#1079;&#1086;&#1074; &#1085;&#1072; &#1089;&#1077;&#1073;&#1103;
    </p>
    <ul>
      <li>
        &#1076;&#1083;&#1103; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1072; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; <a href="#ID_739812787">&#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; (tT) &#1080; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1080;(kK)</a>
      </li>
    </ul>
    <p>
      <font color="#0000c0">&gt; features show</font>
    </p>
    <p>
      <font size="1">Call parking (Parking lot: default) </font>
    </p>
    <p>
      <font size="1">------------ </font>
    </p>
    <p>
      <font size="1">Parking extension&#160;&#160;&#160;&#160;&#160;:&#160;&#160;&#160;&#160;700&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;# ! &#1042;&#1072;&#1078;&#1085;&#1086;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; </font><font color="#0000c0" size="1">&gt; dialplan show</font>
    </p>
    <p>
      <font size="1">Parking context&#160;&#160;&#160;&#160;&#160;&#160;&#160;:&#160;&#160;&#160;&#160;&#160;&#160;parkedcalls&#160;&#160;# &#1050;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; </font>
    </p>
    <p>
      <font size="1">Parked call extensions:&#160;&#160;701-720&#160;&#160;&#160;&#160;&#160;&#160;&#160;# &#1071;&#1095;&#1077;&#1081;&#1082;&#1080; &#1076;&#1083;&#1103; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1080; </font>
    </p>
    <p>
      <font size="1">Parkingtime&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;:&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;45000 ms&#160;&#160;&#160;&#160;&#160;# &#1042;&#1088;&#1077;&#1084;&#1103; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1080; </font>
    </p>
    <p>
      <font size="1">Comeback to origin&#160;&#160;&#160;&#160;:&#160;&#160;&#160;yes&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;# &#1042;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072;&#1079;&#1072;&#1076; </font>
    </p>
    <p>
      <font size="1">Comeback context&#160;&#160;&#160;&#160;&#160;&#160;:&#160;&#160;parkedcallstimeout (comebacktoorigin=yes, not used)&#160;&#160;# &#1042;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100;&#1089;&#1103; &#1074; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; </font>
    </p>
    <p>
      <font size="1">Comeback dial time&#160;&#160;&#160;&#160;:&#160;&#160;&#160;&#160;30&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;# &#1042;&#1099;&#1079;&#1086;&#1074; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1090;&#1100;&#1089;&#1103; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; </font>
    </p>
    <p>
      <font size="1">MusicOnHold class&#160;&#160;&#160;&#160;&#160;:&#160;&#160;&#160;default </font>
    </p>
    <p>
      <font size="1">Enabled&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;:&#160;&#160;&#160;&#160;Yes </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>; /etc/asterisk/extensions.conf</b></font>
    </p>
    <p>
      <font color="#008000">exten =&gt; 2011,1,Dial(SIP/jitsi,kKtT) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; 700,1,Park() </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _7XX,1,ParkedCall(${EXTEN}) </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _XXX,hint,park:${EXTEN}@parkedcalls</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>; /etc/asterisk/features.conf</b></font>
    </p>
    <p>
      <font color="#008000"><b>[general]</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">parkext =&gt; 700</font>&#160;&#160;# &#1053;&#1086;&#1084;&#1091;&#1088;, &#1082;&#1091;&#1076;&#1072; &#1073;&#1091;&#1076;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1089;&#1086;&#1073;&#1077;&#1089;&#1077;&#1076;&#1085;&#1080;&#1082;&#1072;
    </p>
    <p>
      <font color="#008000">parkpos =&gt; 701-720</font>&#160;&#160;# &#1055;&#1072;&#1088;&#1082;&#1086;&#1074;&#1086;&#1095;&#1085;&#1099;&#1077; &#1089;&#1083;&#1086;&#1090;&#1099;
    </p>
    <p>
      <font color="#008000">parkingtime = 600</font>&#160;&#160;# &#1063;&#1077;&#1088;&#1077;&#1079; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1077;&#1082;. &#1087;&#1077;&#1088;&#1077;&#1074;&#1077;&#1076;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089;&#1086;&#1073;&#1077;&#1089;&#1077;&#1076;&#1085;&#1080;&#1082; &#1074;&#1077;&#1088;&#1085;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072;&#1079;&#1072;&#1076;
    </p>
    <p>
      <font color="#008000">context =&gt; parkedcalls</font>&#160;&#160;; &#1055;&#1088;&#1086;&#1097;&#1077; &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1085;&#1072; <b>default</b><font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; </font>
    </p>
    <p>
      <font color="#008000"><b>[featuremap]</b></font>&#160;&#160;; &#1054;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1091; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081;
    </p>
    <p>
      <font color="#008000">parkcall =&gt; #72</font>&#160;&#160;; &#1042;&#1099;&#1079;&#1086;&#1074; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      <font size="2"><b>100% &#1055;&#1077;&#1088;&#1077;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100; features.conf</b></font>
    </p>
    <p>
      <font color="#0000c0">&gt; core restart now</font>
    </p>
    <p>
      <font color="#0000c0">&gt; features reload</font>&#160;
    </p>
  </body>
</html></richcontent>
</node>
