    <ul>
      <li>
        &#1089;&#1083;&#1077;&#1087;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076; (<b>blind transfer</b>). &#1044;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088; &#1079;&#1074;&#1086;&#1085;&#1080;&#1090; &#1089;&#1077;&#1082;&#1088;&#1077;&#1090;&#1072;&#1088;&#1102; &#1080; &#1087;&#1088;&#1086;&#1089;&#1080;&#1090; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1100; &#1089; IT-&#1086;&#1090;&#1076;&#1077;&#1083;&#1086;&#1084; --&gt; &#1057;&#1077;&#1082;&#1088;&#1077;&#1090;&#1072;&#1088;&#1100; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1080;&#1090; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1085;&#1072; IP-&#1086;&#1090;&#1076;&#1077;&#1083;
      </li>
      <li>
        &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076; &#1089; &#1082;&#1086;&#1085;&#1089;&#1091;&#1083;&#1100;&#1090;&#1072;&#1094;&#1080;&#1077;&#1081; (<b>attended transfer</b>). &#1057;&#1077;&#1082;&#1088;&#1077;&#1090;&#1072;&#1088;&#1100; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1091; --&gt; &#1053;&#1072;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1072; &#1080; &#1091;&#1079;&#1085;&#1072;&#1077;&#1090; &#1073;&#1091;&#1076;&#1077;&#1090; &#1083;&#1080; &#1086;&#1085; &#1086;&#1073;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; --&gt; &#1055;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1080;&#1090; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1085;&#1072; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1072;
      </li>
    </ul>
    <p>
      <font color="#008000"><b>; /etc/asterisk/extensions.conf </b></font>
    </p>
    <p>
      <font color="#008000">exten =&gt; 2011,1,<a href="#ID_739812787">Dial</a>(SIP/jitsi,,<b>tT</b>)</font>&#160;&#160;; <b>tT</b>&#160;- &#1058;&#1088;&#1072;&#1085;&#1089;&#1092;&#1077;&#1088; (&#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>; /etc/asterisk/features.conf</b></font>
    </p>
    <p>
      <font color="#008000">[featuremap]</font>&#160;&#160;; &#1054;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1091; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081;
    </p>
    <p>
      <font color="#008000">; </font><font color="#ff0000">&#1057;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1084;&#1072;&#1083;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1076;&#1083;&#1103; &#1074;&#1074;&#1086;&#1076;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;</font>&#160; (&#1075;&#1076;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100;?)
    </p>
    <p>
