<node TEXT="# Первичная настройка FreePBX13" ID="ID_1296721958" CREATED="1540911933391" MODIFIED="1541428124120"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. &#1040;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1103;</b>. Admin \ System admin \ Activation
    </p>
    <ul>
      <li>
        &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1086;&#1073;&#1088;&#1077;&#1090;&#1077;&#1085;&#1080;&#1103; &#1082;&#1086;&#1084;&#1084;&#1077;&#1088;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;
      </li>
      <li>
        &#1087;&#1083;&#1072;&#1090;&#1085;&#1072;&#1103; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072;<br/>
      </li>
      <li>
        &#1080; &#1074;&#1086;&#1086;&#1097;&#1077;...<br/>
      </li>
    </ul>
    <p>
      <b>2. Admin \ System admin</b>
    </p>
    <ol>
      <li>
        Network settings (IP-&#1072;&#1076;&#1088;&#1077;&#1089;)
      </li>
      <li>
        DNS.<br/><b>127.0.0.1</b>&#160;&#160;# &#1042; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077;. DNS (&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1089;&#1077;&#1073;&#1077; (/etc/ hosts)<br/><b>8.8.8.8</b>&#160;&#160;# &#1043;&#1091;&#1075;&#1083; - &#1074; &#1082;&#1086;&#1085;&#1094;&#1077;
      </li>
      <li>
        Time Zone
      </li>
      <li>
        Power Options \ Reboot&#160;&#160;# &#1055;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072;
      </li>
      <li>
        Intrusion Detection - &#1079;&#1072;&#1085;&#1077;&#1089;&#1090;&#1080; &#1089;&#1074;&#1086;&#1081; e-mail &#1076;&#1083;&#1103; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1081; &#1086; &#1074;&#1090;&#1086;&#1088;&#1078;&#1077;&#1085;&#1080;&#1103;&#1093; &#1080; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;&#1093;
      </li>
    </ol>
    <p>
      <b>3. Settings&#160;\ Asterisk SIP Settings </b>
    </p>
    <ol>
      <li>
        Allow Anonymous Inbound SIP Calls --&gt; No<br/>
      </li>
      <li>
        Local Networks --&gt; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1089;&#1077;&#1090;&#1080;<br/>
      </li>
      <li>
        Codecs --&gt; ulaw,alaw,gsm,g726<br/>
      </li>
      <li>
        &#160;&#160;\ Chan SIP Settings \ NAT<br/>
      </li>
    </ol>
    <p>
      <b>4. Applications \ Extensions</b>&#160;- &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1074;&#1085;&#1091;&#1090;&#1088;. &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; (&#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; <b>&#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1087;&#1086;&#1088;&#1090;</b>)
    </p>
    <ol>
      <li>
        Type virtual &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1092;&#1072;&#1082;&#1089;&#1086;&#1074;<br/>
      </li>
      <li>
        Enable Find Me / Follow Me (&#1055;&#1077;&#1088;&#1077;&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1094;&#1080;&#1103;) --&gt; Yes<br/>
      </li>
    </ol>
    <p>
      <b>5. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1082;&#1072; &#1087;&#1086;&#1076;&#1082;&#1083;. &#1082; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1091;.</b>&#160;Connectivity \ <a href="#ID_1452359942">Tranks</a>&#160;\ + Add SIP (chan_sip) Trunk
    </p>
    <ol>
      <li>
        Outbound CallerID - &#1085;&#1086;&#1084;&#1077;&#1088; &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1073;&#1091;&#1076;&#1091;&#1090; &#1091;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1085;&#1072;&#1096;&#1080; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1091;<br/>
      </li>
      <li>
        &#160;&#160;\ sip Settings --&gt; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;<br/>
      </li>
      <li>
        &#160;&#160;\ sip Settings \ incoming \ Register String -- &#1073;&#1077;&#1088;&#1077;&#1084; &#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;<br/>
      </li>
    </ol>
    <p>
      <b>6. &#1052;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103;.&#160;Connectivity \ (<a href="#ID_353538112">Outbound Routes</a>&#160;- &#1048;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;) </b>
    </p>
    <ol>
      <li>
        Trunk Sequence for Matched Routes - &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;. &#1090;&#1088;&#1072;&#1085;&#1082;&#1086;&#1074; &#1076;&#1083;&#1103; &#1089;&#1086;&#1074;&#1087;. &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;<br/>
      </li>
      <li>
        \ Dial Patterns<br/>prepend - &#1095;&#1072;&#1089;&#1090;&#1100; &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1072; &#1082; &#1085;&#1086;&#1084;&#1077;&#1088;&#1091;. 8495<br/>prefix -<br/>match pattern - <a href="#ID_789612062">&#1096;&#1072;&#1073;&#1083;&#1086;&#1085;</a>&#160;&#1073;&#1077;&#1079; _<br/>CallerID<br/>
      </li>
    </ol>
    <p>
      <b>7. &#1052;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103;.&#160;&#160;Connectivity \&#160;&#160;(<a href="#ID_1530624676">Inbound Routes</a>&#160;- &#1042;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;)</b><br/>
    </p>
  </body>
</html></richcontent>
