<node TEXT="Регистрация SIP" ID="ID_1356026482" CREATED="1540545200568" MODIFIED="1540717250779"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_830380089">sip.conf</a>&#160;&#160; <a href="#ID_173636370">SIP</a>
    </p>
    <ol>
      <li>
        Settings \ Advanced settings \ SIP Channel Driver &gt; chan_sip
      </li>
      <li>
        Settings \ Asterisk SIP settings \ Seneral SIP Settings

        <ol>
          <li>
            Allow Anonymous Inbound SIP Calls &gt; No
          </li>
          <li>
            External Address &gt; (&#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100;)
          </li>
          <li>
            Local Networks &gt; (&#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100;)
          </li>
        </ol>
      </li>
      <li>
        Settings \ Asterisk SIP settings \ Chan SIP Settings

        <ol>
          <li>
            Allow SIP Guests &gt; No
          </li>
          <li>
            Bind Port &gt; 5060
          </li>
        </ol>
      </li>
      <li>
        <font color="#0000c0">/etc/init.d/asterisk restart</font>&#160;&#160;# &#1055;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082; asterisk
      </li>
    </ol>
  </body>
</html></richcontent>
</node>
<node TEXT="Шпионский канал" ID="ID_27698676" CREATED="1540585977478" MODIFIED="1540912158946"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1064;&#1087;&#1080;&#1086;&#1085;&#1089;&#1082;&#1080;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083;</b>&#160;- &#1082;&#1086;&#1075;&#1076;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082; &#1083;&#1102;&#1073;&#1086;&#1084;&#1091; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1091;
    </p>
    <p>
      
    </p>
    <p>
      Admin \ Feature Codes \ Core \ <b>ChanSpy</b>&#160;- &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1085;&#1099;&#1081; &#1082;&#1086;&#1076; <b>555</b>. &#1052;&#1086;&#1078;&#1077;&#1084; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1080;&#1079; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1093; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1086;&#1074; &#1080; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103; &#1084;&#1077;&#1078;&#1076;&#1091; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1072;&#1084;&#1080; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; * (&#1079;&#1074;&#1077;&#1079;&#1076;&#1086;&#1095;&#1082;&#1080;). &#1040; &#1077;&#1089;&#1083;&#1080; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1086;&#1074; &#1089;&#1086;&#1090;&#1085;&#1103;?
    </p>
    <p>
      
    </p>
    <p>
      Admin \ Config Edit \ Asterisk Custom Configuration Files
    </p>
    <p>
      <font color="#008000"><b>[from-internal-custom]&#160;&#160;; &#1050;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;</b>&#160; </font>
    </p>
    <p>
      <font color="#008000">exten =&gt; _000XX.,1,ChanSpy(SIP/${EXTEN:3},w)</font>&#160;&#160;; w - (whisper) &#1096;&#1077;&#1087;&#1086;&#1090; - &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1083;&#1091;&#1096;&#1072;&#1090;&#1100; &#1080; &#1087;&#1086;&#1076;&#1089;&#1090;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1091;
    </p>
    <p>
      <font color="#008000">exten =&gt; _000XX.,n,Hangup() </font>
    </p>
  </body>
</html></richcontent>
</node>
