<node TEXT="Backup &amp; Restore (Резервное копирование)" ID="ID_1850089243" CREATED="1540576679886" MODIFIED="1540720962638"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; Backup &amp; Restore - &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1077; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;. Admin \ Backup &amp; Restore</b>
    </p>
    <ul>
      <li>
        &#1044;&#1083;&#1103; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080;&#1103; (20 &#1095;&#1077;&#1083;.) &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1084; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; Full Backup
      </li>
    </ul>
    <p>
      <b>&#1057;&#1077;&#1082;&#1094;&#1080;&#1080; &#1076;&#1086;&#1087;. &#1084;&#1077;&#1085;&#1102;</b>
    </p>
    <ul>
      <li>
        <b>Backups</b>&#160;(&#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1088;&#1072;&#1079;&#1091;) -&#160;&#160;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1087;&#1086; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1084;&#1091; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1080;&#1093; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086;, &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1091; &#1080; &#1086;&#1073;&#1098;&#1077;&#1084; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;
      </li>
      <li>
        <b>Restore</b>&#160;- &#1076;&#1083;&#1103; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;
      </li>
      <li>
        <b>Servers</b>&#160;- &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1099; IP-&#1040;&#1058;&#1057; &#1080;&#1083;&#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1073;&#1072;&#1079; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1087;&#1086;&#1076;&#1074;&#1077;&#1088;&#1075;&#1085;&#1091;&#1090;&#1099; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1077; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
      </li>
      <li>
        <b>Templates</b>&#160;- &#1076;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;, &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1081; &#1080;&#1083;&#1080; &#1073;&#1072;&#1079; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1074; &#1073;&#1091;&#1076;&#1091;&#1097;&#1080;&#1081; &#1073;&#1101;&#1082;&#1072;&#1087;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;, &#1091;&#1078;&#1077; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1099;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1089;&#1074;&#1086;&#1080; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1099;
      </li>
    </ul>
    <p>
      <b>1. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. \ Servers</b>
    </p>
    <ul>
      <li>
        Email - &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1091;&#1102; &#1082;&#1086;&#1087;&#1080;&#1102; &#1085;&#1072; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1085;&#1085;&#1091;&#1102; &#1087;&#1086;&#1095;&#1090;&#1091; &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1074;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        FTP - &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1073;&#1101;&#1082;&#1072;&#1087; &#8211; &#1092;&#1072;&#1081;&#1083;&#1099; &#1085;&#1072; FTP &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;
      </li>
      <li>
        Local - &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083;&#1099; &#1073;&#1101;&#1082;&#1072;&#1087;&#1086;&#1074; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; <b>/var/spool/asterisk/backup</b>
      </li>
      <li>
        MySQL Server - &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1081; MySQL &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; Asterisk &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1087;&#1080;&#1080; &#1041;&#1044;
      </li>
      <li>
        SSH Server
      </li>
    </ul>
    <p>
      <b>2. &#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1082;&#1086;&#1087;&#1080;&#1080;. \ Backup \ New Backup</b>
    </p>
    <ol>
      <li>
        Backup Name - &#1080;&#1084;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1073;&#1101;&#1082;&#1072;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
      </li>
      <li>
