<node TEXT="Certificate Management" ID="ID_1133430205" CREATED="1540725094521" MODIFIED="1540728384759"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1009203346">SSL</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; Certificate Management</b>&#160;- &#1076;&#1083;&#1103;&#160;&#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072;&#1084;&#1080; SSL
    </p>
    <p>
      
    </p>
    <p>
      <b>Admin \ Certificate Management</b>
    </p>
    <p>
      1. Generate CSR.
    </p>
    <ul>
      <li>
        Name - &#1080;&#1084;&#1103; &#1076;&#1083;&#1103; &#1089;&#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; CSR &#1092;&#1072;&#1081;&#1083;&#1072;
      </li>
      <li>
        Common Name (Host Name) (CN) - &#1087;&#1086;&#1083;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;
      </li>
      <li>
        Organization Name (O) - &#1087;&#1086;&#1083;&#1085;&#1086;&#1077; &#1085;&#1072;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; (&#1091;&#1095;&#1088;&#1077;&#1076;.&#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;)
      </li>
      <li>
        Organization Unit (OU) - &#1085;&#1072;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; (&#1086;&#1090;&#1076;&#1077;&#1083;&#1072;)
      </li>
      <li>
        Country (C) - &#1082;&#1086;&#1076; &#1089;&#1090;&#1088;&#1072;&#1085;&#1099; &#1080;&#1079; &#1076;&#1074;&#1091;&#1093; &#1073;&#1091;&#1082;&#1074;. RU
      </li>
      <li>
        State/Province (ST) - &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1100; &#1080;&#1083;&#1080; &#1082;&#1088;&#1072;&#1081;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1074;&#1099; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1077;&#1089;&#1100;. &#1055;&#1091;&#1089;&#1090;&#1086;
      </li>
      <li>
        City or Locality (L) - &#1075;&#1086;&#1088;&#1086;&#1076;. Moscow
      </li>
    </ul>
    <p>
      CSR &#1092;&#1072;&#1081;&#1083; &#1089;&#1090;&#1072;&#1085;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1077;&#1085; &#1076;&#1083;&#1103; &#1089;&#1082;&#1072;&#1095;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074; &#1075;&#1083;&#1072;&#1074;&#1085;&#1086;&#1084; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;
    </p>
    <p>
      2. &#1044;&#1083;&#1103; &#1077;&#1075;&#1086; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080;, &#1085;&#1072;&#1078;&#1084;&#1080;&#1090;&#1077; &#1085;&#1072; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091; Download CSR
    </p>
    <p>
      3. &#1053;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1079;&#1072;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074; &#1094;&#1077;&#1085;&#1090;&#1088; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1080; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1082; &#1085;&#1077;&#1084;&#1091; &#1101;&#1090;&#1086;&#1090; &#1092;&#1072;&#1081;&#1083;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1095;&#1077;&#1075;&#1086; &#1074;&#1099; &#1089;&#1084;&#1086;&#1078;&#1077;&#1090;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1089;&#1074;&#1086;&#1081; SSL &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;.
    </p>
    <p>
      4. &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1083;&#1080; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090; &#1086;&#1090; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072; (CA) --&gt; &#1077;&#1075;&#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;. &#1053;&#1072;&#1078;&#1080;&#1084;&#1072;&#1077;&#1084; &#1085;&#1072; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091; New Certificate &#1080; &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; <b>Upload Certificate</b>
    </p>
    <ul>
      <li>
        Name - &#1080;&#1084;&#1103; &#1076;&#1083;&#1103; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072;
      </li>
      <li>
        Description - &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072;
      </li>
      <li>
        Passphrase - &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1091; &#1080; &#1075;&#1077;&#1085;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1074; &#1085;&#1072; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;
      </li>
      <li>
        CSR Reference - &#1089;&#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; CSR &#1092;&#1072;&#1081;&#1083; &#1085;&#1072; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1077;&#1084; &#1101;&#1090;&#1072;&#1087;&#1077;
      </li>
      <li>
        Certificate - &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072;
      </li>
      <li>
        Trusted Chain - &#1094;&#1077;&#1085;&#1090;&#1088; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; (CA), &#1087;&#1086;&#1084;&#1080;&#1084;&#1086; &#1089;&#1072;&#1084;&#1086;&#1075;&#1086; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074;&#1072;&#1084; &#1094;&#1077;&#1083;&#1099;&#1081; &#1085;&#1072;&#1073;&#1086;&#1088; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;. &#1054;&#1085;&#1080; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; Trusted Chain, &#1090;&#1086; &#1077;&#1089;&#1090;&#1100; &#1094;&#1077;&#1087;&#1086;&#1095;&#1082;&#1080; &#1076;&#1086;&#1074;&#1077;&#1088;&#1080;&#1103;. &#1055;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1086;&#1090;&#1082;&#1088;&#1086;&#1081;&#1090;&#1077; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1080;&#1079; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1080; &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1080;&#1093; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1074; &#1101;&#1090;&#1086; &#1087;&#1086;&#1083;&#1077;
      </li>
    </ul>
    <p>
      5. &#1055;&#1086; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1085;&#1080;&#1102; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082; &#1074;&#1099; &#1089;&#1084;&#1086;&#1078;&#1077;&#1090;&#1077; &#1091;&#1074;&#1080;&#1076;&#1077;&#1090;&#1100; &#1074;&#1072;&#1096; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090; &#1074; &#1086;&#1073;&#1097;&#1077;&#1084; &#1089;&#1087;&#1080;&#1089;&#1082;&#1077;. &#1042; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; &#1101;&#1082;&#1089;&#1087;&#1083;&#1091;&#1072;&#1090;&#1072;&#1094;&#1080;&#1080; &#1086;&#1085; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1077;&#1085; &#1076;&#1083;&#1103; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
    </p>
    <p>
      
    </p>
    <p>
      &#1042;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; <b>&#1073;&#1077;&#1089;&#1087;&#1083;&#1072;&#1090;&#1085;&#1086;&#1075;&#1086; SSL &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072; Let&#8217;s Encrypt</b>. &#1063;&#1090;&#1086;&#1073;&#1099; &#1074;&#1086;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1073;&#1077;&#1089;&#1087;&#1083;&#1072;&#1090;&#1085;&#1099;&#1084; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1084;, &#1091; &#1074;&#1072;&#1096;&#1077;&#1075;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1086; &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103;, &#1080; &#1086;&#1085;&#1086; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1088;&#1077;&#1079;&#1086;&#1083;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086; &#1077;&#1075;&#1086; IP &#8211; &#1072;&#1076;&#1088;&#1077;&#1089;&#1091;.
    </p>
    <p>
      &#1055;&#1086;&#1084;&#1080;&#1084;&#1086; &#1101;&#1090;&#1086;&#1075;&#1086;, &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1077; &#1093;&#1086;&#1089;&#1090;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1099; &#1074; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;&#1093; &#1092;&#1072;&#1077;&#1088;&#1074;&#1086;&#1083;&#1072;:
    </p>
    <p>
      1. outbound1.letsencrypt.org
    </p>
    <p>
      2. outbound2.letsencrypt.org
    </p>
    <p>
      3. mirror1.freepbx.org
    </p>
    <p>
      4. mirror2.freepbx.org
    </p>
  </body>
