<node TEXT="Config Edit" ID="ID_708162783" CREATED="1540728386556" MODIFIED="1540730079245"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; Configuration File Editor</b>
    </p>
    <p>
      &#1052;&#1086;&#1076;&#1091;&#1083;&#1100; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1086;&#1087;. (custom) &#1092;&#1072;&#1081;&#1083;&#1099; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077; &#8211; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1101;&#1090;&#1080; &#1092;&#1072;&#1081;&#1083;&#1099; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; CLI &#1080;&#1083;&#1080; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1080;&#1093; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;, &#1090;&#1072;&#1082;&#1080;&#1093; &#1082;&#1072;&#1082; WinSCP.
    </p>
    <ul>
      <li>
        Admin \ Config Edit
      </li>
      <li>
        &#1074; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1085;&#1086;&#1074;&#1099;&#1081; &#1092;&#1072;&#1081;&#1083;
      </li>
      <li>
        &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1075;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1077; &#1076;&#1083;&#1103; &#1088;&#1077;&#1076;., &#1072; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072; &#1085;&#1091;&#1078;&#1085;&#1099;&#1093; &#1074;&#1072;&#1084; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>Asterisk Custom Configuration Files</b>&#160;&#8211; &#1092;&#1072;&#1081;&#1083;&#1099; &#1084;&#1086;&#1078;&#1085;&#1086; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1074;&#1089;&#1077; Custom &#1092;&#1072;&#1081;&#1083;&#1099; &#1080;&#1079;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086; &#1087;&#1091;&#1089;&#1090;&#1099;&#1077;. &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1074;&#1077;&#1088;&#1096;&#1077;&#1085;&#1085;&#1086; &#1085;&#1086;&#1074;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099;.
    </p>
    <p>
      <b>Asterisk System Configuration Files</b>&#160;&#8211; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1084;&#1080; &#1080; &#1080;&#1093; <font color="#ff0000">&#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;</font>&#160;&#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077; (&#171;File is not writable&#187;)
    </p>
    <p>
      <b>&#1042;&#1072;&#1078;&#1085;&#1086;:</b>&#160;&#1044;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; custom &#1092;&#1072;&#1081;&#1083;&#1072; &#1074; &#1086;&#1088;&#1080;&#1075;&#1080;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1092;&#1072;&#1081;&#1083;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086; &#1074;&#1080;&#1076;&#1072;:
    </p>
    <p>
      <font color="#008000">include ***_custom.conf</font>
    </p>
    <p>
      &#1063;&#1077;&#1088;&#1077;&#1079; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1091;&#1102; &#1089;&#1090;&#1088;&#1086;&#1095;&#1082;&#1091; <font color="#ff0000">&#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;</font>, &#1085;&#1086;, &#1074; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1091;&#1078;&#1077; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090;. &#1045;&#1089;&#1083;&#1080; &#1078;&#1077; &#1074;&#1099; &#1089;&#1086;&#1079;&#1076;&#1072;&#1076;&#1080;&#1090;&#1077; &#1085;&#1086;&#1074;&#1099;&#1081; &#1092;&#1072;&#1081;&#1083;, &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080; + Add New File, &#1090;&#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1089;&#1105; &#1078;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; CLI &#1076;&#1083;&#1103; &#1077;&#1075;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103;. &#1050; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1091;, &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      test_newsettings_custom.conf, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074; &#1085;&#1091;&#1078;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; &#1074;&#1072;&#1089; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1081; .conf &#1092;&#1072;&#1081;&#1083; (&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1084; &#1092;&#1072;&#1081;&#1083;&#1086;&#1084;) &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1091;&#1102; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091;: include test_newsettings custom.conf
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Custom Destination" ID="ID_579438763" CREATED="1540729389758" MODIFIED="1540833010789"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1050;&#1072;&#1082; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1077;&#160;&#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1099;</b>, &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1099;&#1077; &#1074; &#1092;&#1072;&#1081;&#1083;&#1077; /etc/asterisk/extensions_custom.conf &#1074;
    </p>
    <p>
      FreePBX?
    </p>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; Custom Destinations. </b>&#1053;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;, &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;, &#1073;&#1091;&#1076;&#1091;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1073;&#1099;&#1083;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1099; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; &#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1084; &#1092;&#1072;&#1081;&#1083;&#1077;
    </p>
    <p>
      /var/asterisk/extensions_custom.conf, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1101;&#1090;&#1080; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1073;&#1091;&#1076;&#1091;&#1090; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074;&#1086; &#1074;&#1089;&#1077;&#1093; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1093;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077;, &#1090;&#1072;&#1082; &#1080;&#1083;&#1080; &#1080;&#1085;&#1072;&#1095;&#1077;, &#1091;&#1095;&#1072;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1074; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;, &#1090;&#1072;&#1082;&#1080;&#1093; &#1082;&#1072;&#1082;: IVR, Queues, Announcement &#1080; &#1087;&#1088;&#1086;&#1095;&#1080;&#1077;.
    </p>
    <p>
      <b>Admin \ Custom Destinations</b>
    </p>
    <p>
      Add Destination
    </p>
    <ol>
      <li>
        <b>Target</b>&#160;- &#1079;&#1076;&#1077;&#1089;&#1100; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1088;&#1072;&#1085;&#1077;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; [context],[exten],[priority]. &#1044;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1084;, &#1084;&#1099; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1083;&#1080; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;:

        <ul>
          <li>
            <font color="#008000"><b>[test_context]</b></font><br/><font color="#008000">exten =&gt; s,1,Answer()</font><br/><font color="#008000">exten =&gt; s,2,Playback(greetings)</font><br/><font color="#008000">exten =&gt; s,3,Voicemail(100)</font><br/><font color="#008000">exten =&gt; s,4,Hangup()</font>
          </li>
          <li>
            &#1058;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1074; &#1087;&#1086;&#1083;&#1077; Target &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1077;: <b>test_context,s,1</b>.
          </li>
        </ul>
      </li>
      <li>
        <b>Description</b>&#160;- &#1054;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1074;&#1085;&#1086;&#1074;&#1100; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1086;&#1075;&#1086; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        <b>Notes</b>&#160;- &#1041;&#1086;&#1083;&#1077;&#1077; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1086;&#1077; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077;, &#1076;&#1083;&#1103; &#1095;&#1077;&#1075;&#1086; &#1080; &#1087;&#1088;&#1080; &#1082;&#1072;&#1082;&#1080;&#1093; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103;&#1093; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        <b>Return</b>&#160;- &#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100; &#1083;&#1080; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1074; &#1088;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;, &#1090;.&#1077;. &#171;&#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#187;. &#1045;&#1089;&#1083;&#1080; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1086; Yes, &#1090;&#1086; &#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;&#1093; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081;. &#1045;&#1089;&#1083;&#1080; No - &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103;;
      </li>
    </ol>
    <p>
      &#1042;&#1072;&#1078;&#1085;&#1086;: &#1087;&#1088;&#1080; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1080; &#1086;&#1087;&#1094;&#1080;&#1080; Return &#1091;&#1076;&#1086;&#1089;&#1090;&#1086;&#1074;&#1077;&#1088;&#1100;&#1090;&#1077;&#1089;&#1100;, &#1095;&#1090;&#1086; &#1074;&#1072;&#1096; &#171;&#1082;&#1072;&#1089;&#1090;&#1086;&#1084;&#1085;&#1099;&#1081;&#187; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; &#1079;&#1072;&#1082;&#1072;&#1085;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1086;&#1081; Return
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Custom Extension" ID="ID_15109974" CREATED="1540730126468" MODIFIED="1540736130582"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; Custom Extension</b>
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1088;&#1080; &#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1080; &#1085;&#1077;&#1090;&#1088;&#1080;&#1074;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1079;&#1072;&#1076;&#1072;&#1095;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; FreePBX, &#1086;&#1087;&#1099;&#1090;&#1085;&#1099;&#1077; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1099; IP &#8211; &#1040;&#1058;&#1057; Asterisk &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1090; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1077; &#1076;&#1080;&#1072;&#1083;&#1087;&#1083;&#1072;&#1085;&#1099; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080; &#1074; &#1092;&#1072;&#1081;&#1083;&#1077; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; /etc/asterisk/extensions_custom.conf. &#1053;&#1086;, &#1082; &#1089;&#1086;&#1078;&#1072;&#1083;&#1077;&#1085;&#1080;&#1102;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086;&#1076;&#1086;&#1073;&#1085;&#1099;&#1093; &#1076;&#1080;&#1072;&#1083;&#1087;&#1083;&#1072;&#1085;&#1086;&#1074;, FreePBX &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1085;&#1072;&#1090;&#1100; &#1086; &#1080;&#1093; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080;. &#1057;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1077;&#1084;, &#1101;&#1090;&#1086; &#1095;&#1088;&#1077;&#1074;&#1072;&#1090;&#1086; &#1087;&#1077;&#1088;&#1077;&#1089;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1081; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1087;&#1086;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1091;&#1073;&#1083;&#1077;&#1081; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074;).
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>Admin \ Custom Extension</b>
    </p>
    <p>
      Add Extension
    </p>
    <ol>
      <li>
        Custom Extension - &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; &#1085;&#1086;&#1084;&#1077;&#1088;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1074;&#1072;&#1096;&#1077;&#1084; &#1076;&#1080;&#1072;&#1083;&#1087;&#1083;&#1072;&#1085;&#1077; &#1076;&#1083;&#1103; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1081;&#1096;&#1077;&#1075;&#1086; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1077;&#1075;&#1086; &#1080;&#1079; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082; FreePBX
      </li>
      <li>
        Description - &#1082;&#1088;&#1072;&#1090;&#1082;&#1086;&#1077; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1086;&#1075;&#1086; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;
