  <body>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; Sound Languages - </b>&#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1103;&#1079;&#1099;&#1082;&#1086;&#1074;&#1091;&#1102; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1091; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1093; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; &#1086;&#1087;&#1086;&#1074;&#1077;&#1097;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;. &#1057;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1086;&#1076;&#1080;&#1085; &#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1081; &#1103;&#1079;&#1099;&#1082; &#1086;&#1079;&#1074;&#1091;&#1095;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1081; &#1074; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077; &#1076;&#1086; &#1090;&#1077;&#1093; &#1087;&#1086;&#1088;, &#1087;&#1086;&#1082;&#1072; &#1086;&#1085; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085; &#1080;&#1085;&#1099;&#1084;&#1080; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;&#1084;&#1080; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;, &#1090;&#1072;&#1082;&#1080;&#1084;&#1080; &#1082;&#1072;&#1082;:
    </p>
    <ul>
      <li>
        &#1042;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; (Inbound Routes)
      </li>
      <li>
        &#1042;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1077; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; (Extensions
      </li>
      <li>
        &#1042; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077; Languages (&#1085;&#1077; &#1089;&#1090;&#1086;&#1080;&#1090; &#1087;&#1091;&#1090;&#1072;&#1090;&#1100; &#1089; Sound Languages).
      </li>
    </ul>
    <p>
      &#1052;&#1086;&#1076;&#1091;&#1083;&#1100; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1080;&#1083;&#1080; &#1091;&#1076;&#1072;&#1083;&#1103;&#1090;&#1100; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1103;&#1079;&#1099;&#1082;&#1086;&#1074;&#1099;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1089; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084;&#1080; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072;&#1084;&#1080; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;.
    </p>
    <p>
      &#1057;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1080;&#1084;&#1077;&#1077;&#1090; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1086; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1093; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1093; &#1086;&#1087;&#1086;&#1074;&#1077;&#1097;&#1077;&#1085;&#1080;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1099; &#1082;&#1072;&#1082; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; (core-sounds), &#1090;&#1072;&#1082; &#1080; &#1076;&#1083;&#1103; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; (extra-sounds).
    </p>
    <p>
      
    </p>
    <p>
      <b>Admin \ Sound Languages</b>
    </p>
    <p>
      1. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1103;&#1079;&#1099;&#1082;&#1072; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1093; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1093; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081;. &#1042;&#160;&#1074;&#1099;&#1087;&#1072;&#1076;&#1072;&#1102;&#1097;&#1077;&#1084; &#1086;&#1082;&#1085;&#1077; &#1089;&#1087;&#1088;&#1072;&#1074;&#1072; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; Global Language. &#1055;&#1086;&#1089;&#1083;&#1077; &#1095;&#1077;&#1075;&#1086;, &#1074;&#1089;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1077; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1085;&#1086;&#1084; &#1103;&#1079;&#1099;&#1082;&#1077;.
    </p>
    <p>
      2. &#1052;&#1086;&#1076;&#1091;&#1083;&#1100; &#1090;&#1072;&#1082;&#1078;&#1077; &#1076;&#1072;&#1105;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1081; &#1085;&#1072;&#1073;&#1086;&#1088; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1093; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1093; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081;. &#1044;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#8220;&#1103;&#1079;&#1099;&#1082;&#1086;&#1074;&#1086;&#1081; &#1082;&#1086;&#1076;&#8221; (Language Code), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081;, &#1074; &#1089;&#1074;&#1086;&#1102; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; &#1089;&#1086;&#1079;&#1076;&#1072;&#1089;&#1090; &#1085;&#1086;&#1074;&#1091;&#1102; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1102; &#1074; <b>/var/lib/asterisk/sounds</b>&#160;&#1089; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1084; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084;. &#1069;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1080;&#1090; &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1090;&#1100; &#1085;&#1086;&#1074;&#1099;&#1081; &#1085;&#1072;&#1073;&#1086;&#1088;
    </p>
    <p>
      &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; &#1074; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1093;.
    </p>
    <ol>
      <li>
        &#1042;&#1099;&#1087;&#1072;&#1076;&#1072;&#1102;&#1097;&#1077;&#1077; &#1084;&#1077;&#1085;&#1102; \ Custom Language &gt; Add Custom Languag
      </li>
      <li>
        &#1055;&#1088;&#1080;&#1089;&#1074;&#1086;&#1080;&#1090;&#1100; &#1085;&#1086;&#1074;&#1086;&#1084;&#1091; &#1085;&#1072;&#1073;&#1086;&#1088;&#1091; &#1082;&#1086;&#1076; (ru1) &#1080; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077;. &#1055;&#1086;&#1089;&#1083;&#1077; &#1095;&#1077;&#1075;&#1086;&#160;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1085;&#1086;&#1074;&#1099;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080;. &#1055;&#1088;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080;, &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1086;&#1087;&#1094;&#1080;&#1080; Convert To &#1084;&#1086;&#1078;&#1085;&#1086; &#1082;&#1086;&#1085;&#1074;&#1077;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1074; &#1085;&#1091;&#1078;&#1085;&#1099;&#1081; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;
      </li>
      <li>
        &#1053;&#1086;&#1074;&#1099;&#1081; &#1103;&#1079;&#1099;&#1082;&#1086;&#1074;&#1086;&#1081; &#1085;&#1072;&#1073;&#1086;&#1088; &#1087;&#1086;&#1103;&#1074;&#1080;&#1090;&#1089;&#1103; &#1074; &#1089;&#1087;&#1080;&#1089;&#1082;&#1077;. &#1040; &#1090;&#1072;&#1082;&#1078;&#1077;, &#1077;&#1075;&#1086; &#1090;&#1077;&#1087;&#1077;&#1088;&#1100; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;
      </li>
    </ol>
    <p>
      &#1044;&#1088;&#1091;&#1075;&#1086;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; &#1074; &#1085;&#1086;&#1074;&#1091;&#1102; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1102; &#8211; &#1101;&#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; System Recordings. &#1045;&#1089;&#1083;&#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;, &#1090;&#1086; &#1086;&#1085;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1074; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1102; &#8220;custom&#8221;, &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1085;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1086;&#1081; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; (&#1074; &#1085;&#1072;&#1096;&#1077;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; - ru1)
    </p>
