      </li>
      <li>
        &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;
      </li>
      <li>
        &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; Extensions.
      </li>
    </ul>
    <p>
      <b>Admin \ System Recordings &gt; Add Recording:</b>
    </p>
    <ul>
      <li>
        &#1048;&#1084;&#1103; &gt; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &gt; Browse
      </li>
      <li>
        &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1082;&#1086;&#1085;&#1074;&#1077;&#1088;&#1090;&#1072;&#1094;&#1080;&#1080; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1074; &#1085;&#1091;&#1078;&#1085;&#1099;&#1081; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; (Convert To)
      </li>
    </ul>
    <p>
      &#1063;&#1090;&#1086;&#1073;&#1099; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;, &#1074; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077; <b>Record Over Browser</b>&#160;(&#1077;&#1089;&#1083;&#1080; &#1077;&#1089;&#1090;&#1100;), &#1085;&#1072;&#1078;&#1080;&#1084;&#1072;&#1077;&#1084; &#1085;&#1072;
    </p>
    <p>
      &#1082;&#1088;&#1072;&#1089;&#1085;&#1091;&#1102; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091;. &#1057;&#1088;&#1072;&#1079;&#1091; &#1078;&#1077; &#1085;&#1072;&#1095;&#1085;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1087;&#1088;&#1086;&#1080;&#1079;&#1085;&#1077;&#1089;&#1080;&#1090;&#1077; &#1074; &#1084;&#1080;&#1082;&#1088;&#1086;&#1092;&#1086;&#1085; &#1079;&#1072;&#1088;&#1072;&#1085;&#1077;&#1077; &#1079;&#1072;&#1075;&#1086;&#1090;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1090;&#1077;&#1082;&#1089;&#1090;.
    </p>
    <p>
      &#1053;&#1072;&#1078;&#1084;&#1080;&#1090;&#1077; Save Recording. &#1047;&#1072;&#1076;&#1072;&#1081;&#1090;&#1077; &#1085;&#1086;&#1074;&#1086;&#1081; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1080;&#1084;&#1103; &#1080; &#1085;&#1072;&#1078;&#1084;&#1080;&#1090;&#1077; Save. &#1053;&#1086;&#1074;&#1072;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1089;&#1088;&#1072;&#1079;&#1091; &#1078;&#1077; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1089;&#1103; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;
    </p>
    <p>
      
    </p>
