<node TEXT="User Management" ID="ID_1657933930" CREATED="1540799846082" MODIFIED="1540802191815"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; User Management - </b>&#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1077;&#1081; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1074; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; FreePBX.
    </p>
    <p>
      &#1052;&#1077;&#1090;&#1086;&#1076; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1095;&#1077;&#1088;&#1077;&#1079; Microsoft Active Directory.
    </p>
    <p>
      1. &#1055;&#1088;&#1086;&#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1100; 389 &#1087;&#1086;&#1088;&#1090;&#1072; &#1074; AD &#1087;&#1086; &#1090;&#1088;&#1072;&#1085;&#1089;&#1087;&#1086;&#1088;&#1090;&#1091; TCP. &#1044;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086;, &#1089;&#1076;&#1077;&#1083;&#1072;&#1077;&#1084; telnet &#1074; cmd &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1099;
    </p>
    <ul>
      <li>
        telnet &lt;&#1072;&#1076;&#1088;&#1077;&#1089; AD&#8211;&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&gt; 389
      </li>
    </ul>
    <p>
      2. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; Base DN (&#1073;&#1072;&#1079;&#1099; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;). cmd &#1085;&#1072; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1077;:
    </p>
    <ul>
      <li>
        dsquery user -name Name<br/>dsquery user - &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1076;&#1083;&#1103; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;<br/>-name - &#1087;&#1086;&#1080;&#1089;&#1082; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;, &#1087;&#1086; &#1082;&#1088;&#1080;&#1090;&#1077;&#1088;&#1080;&#1102; &#1080;&#1084;&#1077;&#1085;&#1080; (&#1074; &#1085;&#1072;&#1096;&#1077;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; Name), &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1084;&#1072;&#1089;&#1082;&#1080;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#171;*Networks&#187;<br/>Name - &#1080;&#1084;&#1103;, &#1087;&#1086; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084;&#1091; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1084; &#1087;&#1086;&#1080;&#1089;&#1082;;
      </li>
    </ul>
    <p>
      &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1074;&#1077;&#1088;&#1085;&#1077;&#1090; &#1085;&#1072;&#1084; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; &#1074;&#1086;&#1090; &#1090;&#1072;&#1082;&#1086;&#1081; &#1074;&#1099;&#1074;&#1086;&#1076;:
    </p>
    <p>
      &quot;CN= Name,CN=Users,DC=name,DC=local&quot;*
    </p>
    <p>
      3. Admin \ User Management \ Settings \ Authentication Settings
    </p>
    <ul>
      <li>
        Authentication Engine &gt; Microsoft AD
      </li>
      <li>
        Remote Authentication IP Addresses - &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; IP &#8211; &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;, &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1072; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1072;&#1103; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1084;&#1077;&#1090;&#1086;&#1076;&#1086;&#1084; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; POST &#1085;&#1072; URL 192.168.1.129/admin/ajax.php?module=userman&amp;command=auth, &#1075;&#1076;&#1077; 192.168.1.129 &#8211; IP&#8211;&#1072;&#1076;&#1088;&#1077;&#1089; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; Asterisk (FreePBX)
      </li>
      <li>
        Synchronize - &#1082;&#1072;&#1082; &#1095;&#1072;&#1089;&#1090;&#1086; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089; AD
      </li>
      <li>
        Host - &#1080;&#1084;&#1103; &#1080;&#1083;&#1080; IP&#8211;&#1072;&#1076;&#1088;&#1077;&#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; AD
      </li>
      <li>
        Port - &#1087;&#1086;&#1088;&#1090;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1089;&#1083;&#1091;&#1096;&#1072;&#1077;&#1090; AD &gt; 389 &#1087;&#1086;&#1088;&#1090;
      </li>
      <li>
        Username - &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1077; &#1080;&#1084;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1074; AD
      </li>
      <li>
        Password - &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
      </li>
      <li>
        Domain - &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1095;&#1072;&#1089;&#1090;&#1100;
      </li>
      <li>
        Base DN - &#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1077;&#1084; &#1089;&#1102;&#1076;&#1072; Base DN, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1083;&#1080; &#1088;&#1072;&#1085;&#1077;&#1077; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; <b>dsquery</b>
      </li>
      <li>
        Status - &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; AD
      </li>
    </ul>
  </body>
</html></richcontent>
