    </p>
    <ul>
      <li>
        &#1042; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077; <b>System Recordings</b>&#160;&#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1080;&#1083;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1089;&#1072;&#1084;&#1080;&#1093; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1093; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081;. <b>&#1040;nnouncements</b>&#160;&#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1072;&#1090;&#1100; &#1086;&#1076;&#1085;&#1091; &#1080;&#1079; &#1101;&#1090;&#1080;&#1093; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081;
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; Announcements &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1077;&#1076;&#1074;&#1072;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1074; System Recordings
      </li>
    </ul>
    <p>
      <b>Applications \ Announcements &gt; Add</b>
    </p>
    <ul>
      <li>
        <b>Description</b>&#160;&#8211; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077;\&#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1089;&#1072;&#1084;&#1086;&#1075;&#1086; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        <b>Recording</b>&#160;&#8211; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1091;&#1102; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; System Recordings
      </li>
      <li>
        <b>Repeat</b>&#160;&#8211; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1077;&#1085;&#1080;&#1081; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1075;&#1086; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1080; &#1085;&#1072; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1072; &#1087;&#1072;&#1091;&#1079;&#1072; &#1084;&#1077;&#1078;&#1076;&#1091; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;, &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1087;&#1072;&#1091;&#1079;&#1091; &#1074; &#1089;&#1072;&#1084;&#1091; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;
      </li>
      <li>
        <b>Allow Skip</b>&#160;&#8211; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1103; &#1085;&#1072; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091; (&#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1086;, &#1077;&#1089;&#1083;&#1080; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#160;&#160;&#1095;&#1072;&#1089;&#1090;&#1086; &#1079;&#1074;&#1086;&#1085;&#1080;&#1090; &#1085;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;)
      </li>
      <li>
        <b>Return to IVR</b>&#160;&#8211; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1085;&#1072; IVR, &#1080;&#1075;&#1085;&#1086;&#1088;&#1080;&#1088;&#1091;&#1103; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1085;&#1086;&#1077; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1086;&#1087;&#1094;&#1080;&#1080; &#1085;&#1080;&#1078;&#1077;. &#1047;&#1074;&#1086;&#1085;&#1086;&#1082; &#1074;&#1077;&#1088;&#1085;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1081; IVR &#1074; &#1094;&#1077;&#1087;&#1086;&#1095;&#1082;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;
      </li>
      <li>
        <b>Don&#8217;t answer Channel</b>&#160;&#8211; &#1087;&#1086; &#1076;&#1077;&#1092;&#1086;&#1083;&#1090;&#1091; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089;&#1090;&#1086;&#1080;&#1090; &#171;No&#187;, &#1090;.&#1077; &#1086;&#1090;&#1074;&#1077;&#1090; &#1085;&#1072; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1080; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;. &#1045;&#1089;&#1083;&#1080; &#1089;&#1090;&#1086;&#1080;&#1090; &#171;Yes&#187;, &#1090;&#1086; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1086; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1091; &#1082;&#1072;&#1082; &#171;Early Media&#187;, &#1085;&#1086; &#1084;&#1085;&#1086;&#1075;&#1080;&#1077; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1099; &#1085;&#1077; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1090; &#1076;&#1072;&#1085;&#1085;&#1091;&#1102; &#1086;&#1087;&#1094;&#1080;&#1102;
      </li>
      <li>
        <b>Destination after Playback</b>&#160;&#8211; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1096;&#1072; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;
      </li>
    </ul>
  </body>
