<node TEXT="Call Flow Control" ID="ID_1657749589" CREATED="1540808387762" MODIFIED="1540896728374"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1309628818">Time Conditions</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Call Flow Control (Call Flow Toggle Control)</b>&#160;- &#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1087;&#1088;&#1086;&#1093;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;.
    </p>
    <p>
      &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1074; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1077; &#1095;&#1072;&#1089;&#1099;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1091; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; &#1085;&#1072; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1088;&#1080;&#1085;&#1075;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1091;, &#1072; &#1074; &#1085;&#1077;&#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1077; &#8211; &#1085;&#1072; IVR
    </p>
    <ul>
      <li>
        &#1057; &#1090;&#1072;&#1082;&#1086;&#1081; &#1079;&#1072;&#1076;&#1072;&#1095;&#1077;&#1081; &#1087;&#1086;&#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103; <b>Time Conditions</b>. &#1053;&#1086; &#1077;&#1089;&#1083;&#1080; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1103; &#1085;&#1077; &#1080;&#1084;&#1077;&#1077;&#1090; &#1095;&#1105;&#1090;&#1082;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;, &#1090;&#1086; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1091;&#1078;&#1077; &#1085;&#1077; &#1087;&#1086;&#1084;&#1086;&#1078;&#1077;&#1090;, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1086;&#1085; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1088;&#1077;&#1078;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1074; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103;. &#1057; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; Call Flow Control &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#8220;&#1090;&#1091;&#1084;&#1073;&#1083;&#1077;&#1088;&#8221; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074; &#1083;&#1102;&#1073;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080; &#1085;&#1091;&#1078;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;. &#1054;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1072; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1089;&#1103; &#1076;&#1086; &#1090;&#1077;&#1093; &#1087;&#1086;&#1088;, &#1087;&#1086;&#1082;&#1072; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1072; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1088;&#1077;&#1078;&#1080;&#1084;&#1086;&#1074; &#1074; Call Flow &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1085;&#1099; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1082;&#1086;&#1076;&#1099; (<a href="#ID_1020163258">feature code</a>). &#1057;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; 100 &#1082;&#1086;&#1076;&#1086;&#1074; (0-99), &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1080;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; Call Flow &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089; (0-99) &#1080; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1077;&#1075;&#1086; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; &#1082;&#1086;&#1076;&#1086;&#1084; -28. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1077;&#1089;&#1083;&#1080; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#8211; 1, &#1090;&#1086; feature code, &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1097;&#1080;&#1081; Call Flow &#1073;&#1091;&#1076;&#1077;&#1090; *281.
      </li>
    </ul>
    <p>
      <b>Applications \ Call Flow \ Add</b>
    </p>
    <ul>
      <li>
        <b>Call Flow Toggle Feature Code Index</b>&#160;&#8211; &#1048;&#1085;&#1076;&#1077;&#1082;&#1089; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; feature code &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; Call Flow &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089; *28. &#1048;&#1085;&#1076;&#1077;&#1082;&#1089; - &#1101;&#1090;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1103;&#1103; &#1095;&#1072;&#1089;&#1090;&#1100; &#1082;&#1086;&#1076;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1084;&#1077;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1086;&#1090; 0 &#1076;&#1086; 99. &#1045;&#1089;&#1083;&#1080; &#1074;&#1099; &#1074;&#1099;&#1073;&#1088;&#1072;&#1083;&#1080; 1 &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1072;, &#1090;&#1086; &#1082;&#1086;&#1076; &#1073;&#1091;&#1076;&#1077;&#1090; *281, &#1077;&#1089;&#1083;&#1080; 78, &#1090;&#1086; *2878
      </li>
      <li>
        <b>Description</b>&#160;&#8211; &#1054;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077;
      </li>
      <li>
        <b>Current Mode</b>&#160;&#8211; &#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;. &#1042;&#1099;&#1073;&#1086;&#1088; &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1077;&#1083;&#1103; Normal (Green/BLF off) &#1080;&#1083;&#1080; Override (Red/BLF on). &#1055;&#1086;&#1079;&#1076;&#1085;&#1077;&#1077; &#1101;&#1090;&#1080; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080; (&#1074; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077; &#1082; feature code&#8217;&#1091;) &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1088;&#1077;&#1078;&#1080;&#1084;&#1072;
      </li>
      <li>
        <b>Normal (Green/BLF off)</b>&#160;- &#1047;&#1074;&#1086;&#1085;&#1082;&#1080; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1087;&#1086; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086;&#1084;&#1091; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1102;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1077; &#1077;&#1089;&#1090;&#1100; BLF, &#1079;&#1072;&#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086;&#1076; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; feature code, &#1090;&#1086; &#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1083;&#1072;&#1084;&#1087;&#1086;&#1095;&#1082;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1075;&#1086;&#1088;&#1077;&#1090;&#1100; &#1079;&#1077;&#1083;&#1077;&#1085;&#1099;&#1084; &#1080;&#1083;&#1080; &#1085;&#1077; &#1075;&#1086;&#1088;&#1077;&#1090;&#1100; &#1074;&#1086;&#1086;&#1073;&#1097;&#1077;
      </li>
      <li>
        <b>Override (Red/BLF on)</b>&#160;&#8211; &#1069;&#1090;&#1072; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;, &#1075;&#1086;&#1074;&#1086;&#1088;&#1080;&#1090; &#1086; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1087;&#1086;-&#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091; (&#1085;&#1077;&#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086;&#1084;&#1091;) &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1102;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1077; &#1077;&#1089;&#1090;&#1100; BLF &#1079;&#1072;&#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086;&#1076; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; feature code, &#1090;&#1086; &#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1083;&#1072;&#1084;&#1087;&#1086;&#1095;&#1082;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1075;&#1086;&#1088;&#1077;&#1090;&#1100; &#1082;&#1088;&#1072;&#1089;&#1085;&#1099;&#1084;
      </li>
      <li>
        <b>Recording for Normal Mode</b>&#160;&#8211; &#1055;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1074; &#1085;&#1086;&#1088;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;, &#1089;&#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1075;&#1091;&#1076;&#1086;&#1082; (beep), &#1072; &#1079;&#1072;&#1090;&#1077;&#1084; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; feature code &#1076;&#1077;&#1072;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;. &#1042;&#1099; &#1084;&#1086;&#1078;&#1077;&#1090;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1077; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; <a href="#ID_1907810576">System Recordings</a>
      </li>
      <li>
        <b>Optional Password</b>&#160;&#8211; &#1054;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; feature code&#8217;&#1072;. &#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;, &#1078;&#1077;&#1083;&#1072;&#1102;&#1097;&#1080;&#1081; &#1074;&#1086;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082;&#1086;&#1076;&#1086;&#1084;, &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1085;&#1072; &#1089;&#1074;&#1086;&#1105;&#1084; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1077;
      </li>
      <li>
        <b>Normal Flow Destination</b>&#160;&#8211; &#1053;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1091;&#1076;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1077;&#1083;&#1100; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; Normal (Green/BLF off). &#1069;&#1090;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1083;&#1102;&#1073;&#1086;&#1077; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; PBX, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;, IVR, &#1088;&#1080;&#1085;&#1075; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072; &#1080; &#1090;&#1072;&#1082; &#1076;&#1072;&#1083;&#1077;&#1077;
      </li>
      <li>
        <b>Override Flow</b>&#160;&#8211; &#1069;&#1090;&#1086; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1091;&#1076;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074;&#1099;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1077;&#1083;&#1100; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; Override (Red/BLF on). &#1069;&#1090;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1083;&#1102;&#1073;&#1086;&#1077; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; PBX,&#1090;&#1072;&#1082;&#1086;&#1077; &#1082;&#1072;&#1082; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;, IVR, &#1088;&#1080;&#1085;&#1075; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072; &#1080; &#1090;&#1072;&#1082; &#1076;&#1072;&#1083;&#1077;&#1077;
      </li>
    </ul>
  </body>
</html></richcontent>
