<node TEXT="Callback" ID="ID_1615422235" CREATED="1540810278461" MODIFIED="1540810490691"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Callback - </b>&#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1075;&#1086; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1077;&#1085;&#1103;&#1077;&#1090; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1085;&#1072; &quot;&#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1077;&quot; - &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1086;&#1090; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1087;&#1091;&#1090;&#1105;&#1084; &#1089;&#1073;&#1088;&#1086;&#1089;&#1072; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1089;&#1103; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1084; &#1076;&#1083;&#1103; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;, &#1090;&#1086; &#1077;&#1089;&#1090;&#1100; IP - &#1040;&#1058;&#1057; &#1085;&#1072;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090; &#1085;&#1086;&#1084;&#1077;&#1088; &#1087;&#1086;&#1079;&#1074;&#1086;&#1085;&#1080;&#1074;&#1096;&#1077;&#1075;&#1086;.
    </p>
    <p>
      
    </p>
    <p>
      <b>Applications \ Callback&#160;&#160;&gt; Add Callback</b>
    </p>
    <ul>
      <li>
        &#1057;allback Description &#8211; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1074;&#1072;&#1096;&#1077;&#1075;&#1086; &#1082;&#1086;&#1083;&#1083;&#1073;&#1101;&#1082;&#1072;, &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1086; &#1077;&#1089;&#1083;&#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082;&#1086;&#1083;&#1083;&#1073;&#1101;&#1082;&#1086;&#1074; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1074;&#1072;&#1096;&#1077;&#1081; &#1040;&#1058;&#1057;
      </li>
      <li>
        Callback Number &#8211; &#1086;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1087;&#1086;&#1083;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1087;&#1091;&#1089;&#1090;&#1099;&#1084;, &#1090;&#1086; &#1040;&#1058;&#1057; &#1089;&#1086;&#1074;&#1077;&#1088;&#1096;&#1080;&#1090; &#1074;&#1099;&#1079;&#1086;&#1074; &#1087;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1091;, &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1076;&#1086; &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1088;&#1080;&#1096;&#1105;&#1083; &#1074;&#1099;&#1079;&#1086;&#1074;. &#1042; &#1080;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1040;&#1058;&#1057; &#1089;&#1086;&#1074;&#1077;&#1088;&#1096;&#1080;&#1090; &#1074;&#1099;&#1079;&#1086;&#1074; &#1087;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1091;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; &#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1087;&#1086;&#1083;&#1077;
      </li>
      <li>
        Delay Before Callback &#8211; &#1086;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1087;&#1086;&#1083;&#1077;, &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083; (&#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1072;&#1093;) &#1084;&#1077;&#1078;&#1076;&#1091; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1077;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1080; &#1089;&#1086;&#1074;&#1077;&#1088;&#1096;&#1077;&#1085;&#1080;&#1077;&#1084; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1089; &#1040;&#1058;&#1057;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083; &#1088;&#1072;&#1074;&#1077;&#1085; &#1085;&#1091;&#1083;&#1102;
      </li>
      <li>
        Destination after Callback &#8211; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;: &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074; &#1085;&#1072; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1084;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;/&#1088;&#1080;&#1085;&#1075;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1091;/IVR-&#1084;&#1077;&#1085;&#1102; &#1080; &#1090;&#1072;&#1082; &#1076;&#1072;&#1083;&#1077;&#1077;
      </li>
    </ul>
  </body>
</html></richcontent>
