  <body>
    <p>
      <b>Conferences - </b>&#1076;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1075;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; (&#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#8211;&#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1099;), &#1087;&#1088;&#1080; &#1079;&#1074;&#1086;&#1085;&#1082;&#1077; &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1086;&#1073;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080;
    </p>
    <ul>
      <li>
        &#1055;&#1086;&#1084;&#1080;&#1084;&#1086; &#1087;&#1088;&#1103;&#1084;&#1086;&#1075;&#1086; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072;, &#1089;&#1077;&#1082;&#1088;&#1077;&#1090;&#1072;&#1088;&#1100; &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1077;&#1088; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1085;&#1072;&#1087;&#1088;&#1103;&#1084;&#1091;&#1102; &#1074; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#8211;&#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1091;
      </li>
    </ul>
    <p>
      <b>Applications \ Conferences &gt; Add</b>
    </p>
    <ul>
      <li>
        <b>Conference Number</b>&#160;- &#1085;&#1086;&#1084;&#1077;&#1088; &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1082; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080;
      </li>
      <li>
        <b>Conference Name</b>&#160;- &#1080;&#1084;&#1103; &#1076;&#1083;&#1103; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#8211;&#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1099;. &#1048;&#1084;&#1077;&#1085;&#1072; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099; &#1076;&#1083;&#1103; &#1091;&#1076;&#1086;&#1073;&#1089;&#1090;&#1074;&#1072; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
      </li>
      <li>
        <b>User PIN</b>&#160;- &#1101;&#1090;&#1086; &#1085;&#1077;&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1087;&#1086;&#1083;&#1077;. &#1053;&#1072;&#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1074;&#1072;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080;. &#1055;&#1088;&#1080; &#1079;&#1074;&#1086;&#1085;&#1082;&#1077; &#1085;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1099;, &#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1096;&#1077;&#1085; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1086;&#1085; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; &#1085;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1084; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1077;. &#1044;&#1072;&#1085;&#1085;&#1099;&#1081; PIN &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103; &#1086;&#1090; PIN`a &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;
      </li>
      <li>
        <b>Admin PIN</b>&#160;- &#1087;&#1088;&#1080; &#1074;&#1074;&#1086;&#1076;&#1077; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1080;&#1085; &#8211; &#1082;&#1086;&#1076;&#1072;, &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1082;&#1072;&#1082; &#1083;&#1080;&#1076;&#1077;&#1088; &#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1077;
      </li>
      <li>
        <b>Join Message</b>&#160;- &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102; &#1087;&#1088;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1077;. &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077; <a href="#ID_1907810576">System Recordings</a>
      </li>
      <li>
        <b>Leader Wait</b>&#160;- &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1103; &#1085;&#1077; &#1085;&#1072;&#1095;&#1085;&#1077;&#1090;&#1089;&#1103; &#1076;&#1086; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082; &#1085;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1089;&#1103; &#1083;&#1080;&#1076;&#1077;&#1088; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1099; (&#1089; PIN &#8211; &#1082;&#1086;&#1076;&#1086;&#1084; &#1072;&#1076;&#1084;&#1080;&#1085;&#1072;)
      </li>
      <li>
        <b>Talker Optimization</b>&#160;- &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1075;&#1083;&#1091;&#1096;&#1080;&#1090;&#1100; &#1079;&#1074;&#1091;&#1082; &#1086;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1077; &#1075;&#1086;&#1074;&#1086;&#1088;&#1103;&#1090; &#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090;. &#1069;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1080;&#1079;&#1086;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1080;&#1077; &#1096;&#1091;&#1084;&#1099; &#1085;&#1072; &#1092;&#1086;&#1085;&#1077; &#1075;&#1086;&#1074;&#1086;&#1088;&#1103;&#1097;&#1077;&#1075;&#1086;
      </li>
      <li>
        <b>Talker Detection</b>&#160;- &#1087;&#1088;&#1080; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1072;, Asterisk &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1072;&#1085;&#1072;&#1083; &#1076;&#1086;&#1082;&#1083;&#1072;&#1076;&#1095;&#1080;&#1082;&#1072; &#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103; &#1074; AMI (Asterisk Managment Interface)
      </li>
      <li>
        <b>Quiet Mode</b>&#160;- &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084; &#1085;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1079;&#1074;&#1091;&#1082;&#1086;&#1074;&#1099;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1086;&#1090; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080;
      </li>
      <li>
        <b>User Count</b>&#160;- &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1103;&#1090;&#1100; &#1083;&#1080; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1074; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#8211;&#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1077; &#1087;&#1088;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1085;&#1086;&#1074;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
      </li>
      <li>
        <b>User Join/Leave</b>&#160;- &#1087;&#1088;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080;, &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1090;&#1100; &#1080;&#1084;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; (&#1087;&#1088;&#1086;&#1080;&#1079;&#1085;&#1077;&#1089;&#1090;&#1080; &#1077;&#1075;&#1086;). &#1044;&#1072;&#1083;&#1077;&#1077;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1090;&#1086;&#1075;&#1086; &#1082;&#1072;&#1082; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1083;&#1089;&#1103;, &#1077;&#1084;&#1091; &#1080; &#1087;&#1088;&#1086;&#1095;&#1080;&#1084; &#1076;&#1072;&#1083;&#1077;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1097;&#1080;&#1084;&#1089;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084; &#1073;&#1091;&#1076;&#1091;&#1090; &#1086;&#1079;&#1074;&#1091;&#1095;&#1077;&#1085;&#1099; &#1080;&#1084;&#1077;&#1085;&#1072; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1086;&#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1099;
      </li>
      <li>
        <b>Music on Hold</b>&#160;- &#1080;&#1075;&#1088;&#1072;&#1090;&#1100; &#1083;&#1080; &#1084;&#1091;&#1079;&#1099;&#1082;&#1091;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1080;&#1085; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;
      </li>
      <li>
        <b>Music on Hold Class</b>&#160;- &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1084;&#1091;&#1079;&#1099;&#1082;&#1091;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1087;&#1086;&#1082;&#1072; &#1086;&#1085;&#1080; &#1073;&#1091;&#1076;&#1091; &#1086;&#1078;&#1080;&#1076;&#1072;&#1090;&#1100; &#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1080;
      </li>
      <li>
