    <p>
      <b>4.</b>&#160;&#1055;&#1088;&#1080; &#1074;&#1099;&#1073;&#1086;&#1088;&#1077; &#1086;&#1076;&#1085;&#1086;&#1081; &#1080;&#1079; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090; &#1077;&#1089;&#1090;&#1100; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1077;&#1105; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;. &#1089;&#1084;. <a href="#ID_1256690325">Conferences</a>
    </p>
    <p>
      <b>5.</b>&#160;&#1042;&#1099;&#1073;&#1088;&#1072;&#1074; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1091; &#1080; &#1085;&#1072;&#1078;&#1072;&#1074; Invite Contact, &#1087;&#1086;&#1103;&#1074;&#1080;&#1083;&#1072;&#1089;&#1100; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1088;&#1080;&#1075;&#1083;&#1072;&#1096;&#1072;&#1090;&#1100; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1086;&#1074; &#1074; &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1102; &#1087;&#1088;&#1103;&#1084;&#1086; &#1080;&#1079; UCP &#1087;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1091; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072;. &#1069;&#1090;&#1086; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1082;&#1072;&#1082; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1077; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1099;, &#1079;&#1072;&#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1085;&#1072; IP-&#1040;&#1058;&#1057;, &#1090;&#1072;&#1082; &#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1077;.
