      <li>
        &#1048;&#1085;&#1086;&#1075;&#1076;&#1072;, &#1089;&#1077;&#1088;&#1074;&#1080;&#1089; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1075;&#1086; &#1084;&#1077;&#1085;&#1102; (IVR), &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1084; &#1072;&#1074;&#1090;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1095;&#1080;&#1082;&#1086;&#1084; &#1086; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1081; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088; &#1080;&#1083;&#1080; &#1076;&#1086;&#1078;&#1076;&#1072;&#1090;&#1100;&#1089;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1089; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1084; &#1080;&#1083;&#1080; &#1089;&#1077;&#1082;&#1088;&#1077;&#1090;&#1072;&#1088;&#1105;&#1084;. &#1058;&#1072;&#1082;&#1078;&#1077;, &#1082; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1103;&#1084; DISA &#1080; IVR &#1086;&#1090;&#1085;&#1086;&#1089;&#1103;&#1090;&#1