      </li>
      <li>
        <b>Caller ID</b>&#160;- &#1086;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;. &#1055;&#1088;&#1080; &#1089;&#1086;&#1074;&#1077;&#1088;&#1096;&#1077;&#1085;&#1080;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;, &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; CallerID. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1101;&#1090;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1075;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1076;&#1083;&#1103; &#1089;&#1073;&#1086;&#1088;&#1072; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080;. &#1060;&#1086;&#1088;&#1084;&#1072;&#1090; &#1074;&#1086;&#1076;&#1072; &#1090;&#1072;&#1082;&#1086;&#1074;: &quot;&#1048;&#1084;&#1103;&quot; &lt;123456789&gt;
