      <li>
        <b>Announcement</b>&#160;&#8211; &#1079;&#1074;&#1091;&#1082;&#1086;&#1074;&#1086;&#1077; &#1087;&#1088;&#1080;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1076;&#1083;&#1103; &#1087;&#1086;&#1087;&#1072;&#1074;&#1096;&#1080;&#1093; &#1074; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1102;. &#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#8211; &#171;&#1044;&#1086;&#1073;&#1088;&#1086; &#1087;&#1086;&#1078;&#1072;&#1083;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1102;. &#1053;&#1072;&#1073;&#1077;&#1088;&#1080;&#1090;&#1077; &#1087;&#1077;&#1088;&#1074;&#1099;&#1077; 3 &#1080;&#1083;&#1080; &#1073;&#1086;&#1083;&#1077;&#1077; &#1073;&#1091;&#1082;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1089;&#1103; &#1074; &#1080;&#1084;&#1077;&#1085;&#1080; &#1080;&#1083;&#1080; &#1092;&#1072;&#1084;&#1080;&#1083;&#1080;&#1080; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1080; &#1085;&#1072; &#1074;&#1072;&#1096;&#1077;&#1084; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1077;. &#1044;&#1083;&#1103; &#1087;&#1088;&#1086;&#1073;&#1077;&#1083;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1081;&#1090;&#1077; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1091; 1, &#1080; 0 &#1076;&#1083;&#1103; &#1074;&#1099;&#1093;&#1086;&#1076;&#1072; &#1080;&#1079; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080;.)&#187; &#1044;&#1072;&#1085;&#1085;&#1086;&#1077; &#1087;&#1088;&#1080;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1085;&#1072; &#1074;&#1072;&#1096;&#1077; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; <a href="#ID_1907810576">System Recordings</a>
      </li>
      <li>
        <b>Invalid Retries</b>&#160;&#8211; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086;&#1087;&#1099;&#1090;&#1086;&#1082; &#1085;&#1077;&#1091;&#1076;&#1072;&#1095;&#1085;&#1086;&#1075;&#1086; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072;/&#1074;&#1074;&#1086;&#1076;&#1072; &#1080;&#1084;&#1077;&#1085;&#1080; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;
      </li>
      <li>
        <b>Invalid Retry Recording</b>&#160;&#8211; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1080; &#1085;&#1077;&#1074;&#1077;&#1088;&#1085;&#1086;&#1075;&#1086; &#1080;&#1084;&#1077;&#1085;&#1080;.
      </li>
      <li>
        <b>Invalid Recording</b>&#160;&#8211; &#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1079;&#1074;&#1086;&#1085;&#1103;&#1097;&#1077;&#1084;&#1091; &#1087;&#1088;&#1080; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1080; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080; 0 &#1080;&#1083;&#1080; &#1077;&#1089;&#1083;&#1080; &#1082;&#1086;&#1085;&#1095;&#1080;&#1083;&#1080;&#1089;&#1100; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1080; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072;
      </li>
      <li>
        <b>Invalid Destination</b>&#160;&#8211; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;, &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1077;&#1089;&#1083;&#1080; &#1080;&#1089;&#1090;&#1077;&#1082;&#1083;&#1086; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086;&#1087;&#1099;&#1090;&#1086;&#1082; &#1080;&#1083;&#1080; &#1073;&#1099;&#1083; &#1085;&#1072;&#1078;&#1072;&#1090; 0. &#1044;&#1072;&#1085;&#1085;&#1086;&#1077; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1086;&#1090;&#1084;&#1077;&#1085;&#1077;&#1085;&#1086; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1077;&#1081; &#171;Return to IVR&#187;
      </li>
      <li>
        <b>Return to IVR</b>&#160;&#8211; Yes/No (&#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1080;&#1083;&#1080; &#1085;&#1077;&#1090; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; &#1085;&#1072; IVR, &#1087;&#1088;&#1080; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1080;, &#1077;&#1089;&#1083;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074; &#1087;&#1088;&#1080;&#1096;&#1077;&#1083; &#1089; IVR.) &#1045;&#1089;&#1083;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074; &#1087;&#1088;&#1080;&#1096;&#1077;&#1083; &#1089; IVR, &#1090;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1074; &#171;Yes&#187; &#1086;&#1090;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1083;&#1103; &#171;Invalid Destination&#187;
      </li>
      <li>
        <b>Announce Extension</b>&#160;&#8211; Yes/No &#8211; &#1054;&#1079;&#1074;&#1091;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100; &#1080;&#1083;&#1080; &#1085;&#1077; &#1086;&#1079;&#1074;&#1091;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100; &#1085;&#1086;&#1084;&#1077;&#1088; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;&#1072;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085; &#1074;&#1099;&#1079;&#1086;&#1074;. &#1044;&#1072;&#1085;&#1085;&#1072;&#1103; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1072; &#1076;&#1083;&#1103; &#1091;&#1090;&#1086;&#1095;&#1085;&#1077;&#1085;&#1080;&#1103; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;&#1086;&#1074; &#1087;&#1088;&#1080; &#1087;&#1088;&#1103;&#1084;&#1086;&#1084; &#1085;&#1072;&#1073;&#1086;&#1088;&#1077; &#1074; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1081;&#1096;&#1077;&#1084;
      </li>
    </ul>
    <p>
      &#1055;&#1088;&#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1085;&#1086;&#1074;&#1086;&#1081; &#1089;&#1091;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080; &#1074; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1102; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1074;&#1099;&#1087;&#1072;&#1076;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1084;&#1077;&#1085;&#1102;, &#1077;&#1089;&#1090;&#1100; &#1074;&#1099;&#1073;&#1086;&#1088; &#1080;&#1079; 3 &#1086;&#1087;&#1094;&#1080;&#1081;: All Users &#8211; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074;&#1089;&#1077;&#1093; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1093; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;&#1086;&#1074; &#1085;&#1072; &#1040;&#1058;&#1057;, Custom Entry (&#1076;&#1083;&#1103; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072;, &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1086; &#1076;&#1083;&#1103; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1103; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1089;&#1086;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072; &#1080;&#1083;&#1080; &#1082;&#1072;&#1082;&#1086;&#1075;&#1086;-&#1085;&#1080;&#1073;&#1091;&#1076;&#1100; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1075;&#1086; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1072;), Extension (&#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;&#1072;).
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1088;&#1080;&#1084;&#1077;&#1088; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;&#1072; &#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091;:</b>
    </p>
    <ul>
      <li>
        Name &#8211; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1072;&#1082;&#1080;&#1084; &#1078;&#1077;, &#1082;&#1072;&#1082; &#1080; &#1080;&#1084;&#1103; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;&#1072;. &#1050; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1091;, &#1077;&#1089;&#1083;&#1080; &#1080;&#1084;&#1103; Ivan, &#1090;&#1086; &#1076;&#1083;&#1103; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1087;&#1077;&#1088;&#1074;&#1099;&#1093; &#1090;&#1088;&#1105;&#1093; &#1073;&#1091;&#1082;&#1074; &#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072;&#1073;&#1088;&#1072;&#1090;&#1100; &#171;482&#187; &#1085;&#1072; &#1082;&#1083;&#1072;&#1074;&#1080;&#1072;&#1090;&#1091;&#1088;&#1077; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072;
      </li>
      <li>
        Name Announcement &#8211; &#1082;&#1072;&#1082;&#1086;&#1081; &#1079;&#1074;&#1091;&#1082;&#1086;&#1074;&#1086;&#1081; &#1092;&#1072;&#1081;&#1083; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1080; &#8211; &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1087;&#1088;&#1080;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1076;&#1083;&#1103; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1085;&#1085;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099;, &#1080;&#1084;&#1103; &#1080;&#1083;&#1080; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1072;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;
      </li>
      <li>
        Dial &#8211; &#1085;&#1086;&#1084;&#1077;&#1088; &#1076;&#1083;&#1103; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072;, &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1101;&#1090;&#1086; &#1090;&#1086;&#1090; &#1078;&#1077; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;. &#1054;&#1076;&#1085;&#1072;&#1082;&#1086;, &#1101;&#1090;&#1086; &#1087;&#1086;&#1083;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1086; &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1081; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;, &#1082;&#1072;&#1082; &#1074; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1077;, &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1086;&#1084; &#1074;&#1099;&#1096;&#1077; &#8211; &#1089; &#1075;&#1077;&#1085;&#1077;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1086;&#1084; &#1080; &#1077;&#1075;&#1086; &#1072;&#1089;&#1089;&#1080;&#1089;&#1090;&#1077;&#1085;&#1090;&#1086;&#1084;;
      </li>
    </ul>
  </body>
</html></richcontent>
