  <body>
    <p>
      <a href="#ID_38515031">FollowMe</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Follow Me - </b>&#1087;&#1086;&#1084;&#1086;&#1075;&#1072;&#1077;&#1090; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1090;&#1100; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; &#1085;&#1072; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;.
    </p>
    <ul>
      <li>
        &#1086;&#1073;&#1079;&#1074;&#1086;&#1085; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1086;&#1074; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080;
      </li>
      <li>
        &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1074;&#1099;&#1079;&#1086;&#1074; &#1084;&#1077;&#1078;&#1076;&#1091; &#1074;&#1089;&#1077;&#1084;&#1080; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;&#1084;&#1080;
      </li>
      <li>
        &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074; &#1085;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1079;&#1072;&#1085;&#1103;&#1090;
      </li>
      <li>
        &#1057; FreePBX 13 &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1085;&#1077;&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082; follow me Extension&#8217;&#1086;&#1074;. &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1101;&#1090;&#1086; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1091; Find Me/Follow Me &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; <a href="#ID_930605650">Extensions</a>
      </li>
      <li>
        &#1042; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; FreePBX 13+ &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; Follow Me &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072; &#1080; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1072; (enabled/disabled) &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082; follow me &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074;. &#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1080; &#1090;&#1072;&#1082;&#1078;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1080;&#1079;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1086;&#1076;&#1086;&#1074; (<a href="#ID_1020163258">Feature Codes</a>) UCP, REST Apps.
      </li>
    </ul>
    <p>
      <b>Applications \ Follow Me &gt; Edit</b>. &#1053;&#1086;&#1084;&#1077;&#1088;&#1072; &#1089;&#1102;&#1076;&#1072; &#1073;&#1091;&#1076;&#1091;&#1090; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082; &#1085;&#1072; Extensions&#8217;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1093;&#1086;&#1090;&#1103; &#1073;&#1099; &#1088;&#1072;&#1079; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1072; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; Follow Me
    </p>
    <ul>
      <li>
        <b>Group Number</b>&#160;- &#1085;&#1086;&#1084;&#1077;&#1088; Follow Me &#1075;&#1088;&#1091;&#1087;&#1087;&#1099;
      </li>
      <li>
        <b>Enable Follow Me</b>&#160;&#8211; Yes - &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; Extension &#1087;&#1086;&#1087;&#1072;&#1076;&#1077;&#1090; &#1074; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082;
      </li>
      <li>
        <b>Initial Ring Time</b>&#160;&#8211; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076; &#1073;&#1091;&#1076;&#1077;&#1090; &#1076;&#1083;&#1080;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1072; &#1076;&#1086;&#1079;&#1074;&#1086;&#1085;&#1072; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; Extension &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1095;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080; &#1074; follow-me list
      </li>
      <li>
        <b>Ring Strategy</b>&#160;&#8211; &#1089;&#1090;&#1088;&#1072;&#1090;&#1077;&#1075;&#1080;&#1103; &#1086;&#1073;&#1079;&#1074;&#1086;&#1085;&#1072;
      </li>
      <li>
        <b>Ring Time (max 60 sec)</b>&#160;&#8211; &#1089;&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076; &#1073;&#1091;&#1076;&#1077;&#1090; &#1076;&#1083;&#1080;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1072; &#1076;&#1086;&#1079;&#1074;&#1086;&#1085;&#1072; &#1085;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099; &#1095;&#1083;&#1077;&#1085;&#1086;&#1074; follow-me list&#8217;&#1072;
      </li>
      <li>
        <b>Follow-Me List</b>&#160;&#8211; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;/&#1072;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074;/&#1076;&#1086;&#1073;&#1072;&#1074;&#1086;&#1095;&#1085;&#1099;&#1093; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1072; &#1076;&#1086;&#1079;&#1074;&#1086;&#1085;&#1072; &#1087;&#1086; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1072;&#1090;&#1077;&#1075;&#1080;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082; &#1079;&#1072;&#1082;&#1086;&#1085;&#1095;&#1080;&#1090;&#1089;&#1103; Initial Ring Time
      </li>
      <li>
        <b>Announcement</b>&#160;- &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1084;&#1091; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1091;, &#1087;&#1088;&#1080; &#1079;&#1074;&#1086;&#1085;&#1082;&#1077; &#1085;&#1072; &#1076;&#1072;&#1085;&#1085;&#1091;&#1102; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091;
      </li>
      <li>
        <b>Play Music On Hold</b>&#160;- &#1077;&#1089;&#1083;&#1080; &#1079;&#1072;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#8220;Ring&#8221; &#1085;&#1072; &#1082;&#1072;&#1082;&#1091;&#1102;-&#1085;&#1080;&#1073;&#1091;&#1076;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1091;&#1102; &#1084;&#1091;&#1079;&#1099;&#1082;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1090;&#1086; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1083;&#1099;&#1096;&#1072;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1087;&#1086;&#1082;&#1072; &#1082;&#1090;&#1086;-&#1085;&#1080;&#1073;&#1091;&#1076;&#1100; &#1080;&#1079; follow-me list&#8217;&#1072; &#1077;&#1084;&#1091; &#1085;&#1077; &#1086;&#1090;&#1074;&#1077;&#1090;&#1080;&#1090;
      </li>
      <li>
        <b>CID Name Prefix</b>&#160;- &#1086;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1077; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, Tech_Sup
      </li>
      <li>
        <b>Alert Info</b>&#160;- &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1093;&#1072;&#1088;&#1072;&#1082;&#1090;&#1077;&#1088;&#1085;&#1099;&#1093; SIP-&#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;
      </li>
      <li>
        <b>Confirm Calls</b>&#160;&#8211; &#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1076;&#1086;&#1093;&#1086;&#1076;&#1080;&#1090;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1076;&#1086; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099;. &#1044;&#1072;&#1085;&#1085;&#1072;&#1103; &#1086;&#1087;&#1094;&#1080;&#1103; &#1087;&#1088;&#1086;&#1089;&#1080;&#1090; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1091;&#1102; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091; &#1085;&#1072;&#1073;&#1088;&#1072;&#1090;&#1100; 1, &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1095;&#1077;&#1084; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        <b>Remote Announce</b>&#160;&#8211; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1077;, &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1102;&#1097;&#1077;&#1081; &#1074;&#1099;&#1079;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1072; &#1086;&#1087;&#1094;&#1080;&#1103; Confirm Calls
      </li>
      <li>
        <b>Too-Late Announce</b>&#160;- &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1077;, &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1102;&#1097;&#1077;&#1081; &#1074;&#1099;&#1079;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1091;&#1078;&#1077; &#1073;&#1099;&#1083; &#1087;&#1088;&#1080;&#1085;&#1103;&#1090;, &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1095;&#1077;&#1084; &#1086;&#1085;&#1080; &#1085;&#1072;&#1073;&#1088;&#1072;&#1083;&#1080; 1
      </li>
      <li>
        <b>Change External CID Configuration</b>&#160;&#8211; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1080;&#1077; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1080;&#1083;&#1080; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080;&#1077;&#1084; Caller ID &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1093; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074;
      </li>
      <li>
        <b>Fixed CID Value</b>&#160;- &#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; Caller ID, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1074; Change External CID Configuration &#1073;&#1099;&#1083;&#1072; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1072; &#1086;&#1087;&#1094;&#1080;&#1103; Fixed CID Value. &#1055;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1045;164 &#1089; &#8220;+&#8221; &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077;
      </li>
      <li>
        <b>Destination if no answer</b>&#160;- &#1082;&#1091;&#1076;&#1072; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1085;&#1080;&#1082;&#1090;&#1086; &#1080;&#1079; follow-me list&#8217;&#1072; &#1085;&#1077; &#1089;&#1084;&#1086;&#1075; &#1087;&#1088;&#1080;&#1085;&#1103;&#1090;&#1100; &#1077;&#1075;&#1086;
      </li>
    </ul>
  </body>
</html></richcontent>
