<node TEXT="IVR (Голосовое меню)" ID="ID_67595828" CREATED="1540567942568" MODIFIED="1540889066498"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1590320518">IVR(Asterisk)</a>&#160;&#160; <a href="#ID_1907810576">System Recording</a><b>&#160;&#160; </b><a href="#ID_1361614273">Audacity</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>IVR - &#1080;&#1085;&#1090;&#1077;&#1088;&#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1077; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1084;&#1077;&#1085;&#1102; </b>
    </p>
    <ul>
      <li>
        &#1052;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1084;&#1077;&#1078;&#1076;&#1091; &#1076;&#1077;&#1087;&#1072;&#1088;&#1090;&#1072;&#1084;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080;, &#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1086;&#1074; &#1090;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072;, &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1084;&#1099;&#1093; &#1076;&#1086;&#1079;&#1074;&#1086;&#1085;&#1080;&#1074;&#1096;&#1080;&#1084;&#1089;&#1103; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1084;
      </li>
      <li>
        IVR &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091; &#1085;&#1072; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1082;&#1086;&#1083;&#1083; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091; &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1100;&#1089;&#1103; &#1089; &#1080;&#1085;&#1090;&#1077;&#1088;&#1077;&#1089;&#1091;&#1102;&#1097;&#1080;&#1084; &#1077;&#1075;&#1086; &#1086;&#1090;&#1076;&#1077;&#1083;&#1086;&#1084; &#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1074;&#1089;&#1102; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1091;&#1102; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102;, &#1084;&#1080;&#1085;&#1091;&#1103; &#1087;&#1077;&#1088;&#1074;&#1091;&#1102; &#1083;&#1080;&#1085;&#1080;&#1102; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;
      </li>
      <li>
        &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1088;&#1077;&#1082;&#1083;&#1072;&#1084;&#1085;&#1099;&#1093; &#1080; &#1084;&#1072;&#1088;&#1082;&#1077;&#1090;&#1080;&#1085;&#1075;&#1086;&#1074;&#1099;&#1093; &#1072;&#1082;&#1094;&#1080;&#1103;&#1093;, &#1074; &#1094;&#1077;&#1083;&#1103;&#1093; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;
      </li>
      <li>
        &#1055;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; <a href="#ID_1361614273">Audacity</a>
      </li>
    </ul>
    <p>
      <b>Applications \ IVR &gt; Add</b>
    </p>
    <ul>
      <li>
        <b>IVR Name</b>&#160;&#8211; &#1080;&#1084;&#1103; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1075;&#1086; &#1084;&#1077;&#1085;&#1102;
      </li>
      <li>
        IVR Description &#8211; &#1086;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;, &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077;
      </li>
      <li>
        <b>Announcement</b>&#160;&#8211; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1083;&#1099;&#1096;&#1072;&#1090;&#1100; &#1076;&#1086;&#1079;&#1074;&#1086;&#1085;&#1080;&#1074;&#1096;&#1080;&#1081;&#1089;&#1103;. &#1048;&#1084;&#1077;&#1085;&#1085;&#1086; &#1076;&#1072;&#1085;&#1085;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; (&#8220;&#1085;&#1072;&#1078;&#1084;&#1080;&#1090;&#1077; 1, &#1085;&#1072;&#1078;&#1084;&#1080;&#1090;&#1077; 2 &#1080; &#1090;.&#1076;.&#8221;)
      </li>
      <li>
        <b>Enable Direct Dial</b>&#160;&#8211; &#1076;&#1072;&#1085;&#1085;&#1072;&#1103; &#1086;&#1087;&#1094;&#1080;&#1103; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1091; &#1085;&#1072;&#1073;&#1088;&#1072;&#1090;&#1100; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1072; (&#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1077;&#1075;&#1086; &#1079;&#1085;&#1072;&#1077;&#1090;) &#1080; &#1085;&#1072;&#1087;&#1088;&#1103;&#1084;&#1091;&#1102; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1100;&#1089;&#1103; &#1089; &#1085;&#1080;&#1084;, &#1085;&#1077; &#1076;&#1086;&#1078;&#1080;&#1076;&#1072;&#1103;&#1089;&#1100;, &#1087;&#1086;&#1082;&#1072; &#1101;&#1090;&#1086; &#1087;&#1088;&#1077;&#1076;&#1083;&#1086;&#1078;&#1080;&#1090; IVR
      </li>
      <li>
        <b>Timeout</b>&#160;&#8211; &#1074;&#1088;&#1077;&#1084;&#1103;, &#1079;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1091; &#1087;&#1088;&#1077;&#1076;&#1083;&#1072;&#1075;&#1072;&#1102;&#1090; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1086;&#1087;&#1094;&#1080;&#1102; &#1087;&#1086;&#1089;&#1083;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;. &#1045;&#1089;&#1083;&#1080; &#1076;&#1072;&#1085;&#1085;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080;&#1089;&#1090;&#1077;&#1082;&#1083;&#1086;, &#1090;&#1086; IVR &#1086;&#1090;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1087;&#1086; timeout rules
      </li>
      <li>
