      </li>
      <li>
        <b>Append Announcement to Invalid</b>&#160;&#8211; &#1086;&#1087;&#1094;&#1080;&#1103;, &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1102;&#1097;&#1072;&#1103; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100; &#1083;&#1080; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; IVR &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1080;&#1089;&#1095;&#1077;&#1088;&#1087;&#1072;&#1083; &#1074;&#1089;&#1077; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1080; &#1074;&#1074;&#1086;&#1076;&#1072;
      </li>
      <li>
        <b>Return on Invalid</b>&#160;&#8211; &#1076;&#1072;&#1085;&#1085;&#1072;&#1103; &#1086;&#1087;&#1094;&#1080;&#1103; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1080;&#1088;&#1091;&#1077;&#1090; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090;&#1072; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1080;&#1089;&#1095;&#1077;&#1088;&#1087;&#1072;&#1074;&#1096;&#1077;&#1075;&#1086; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1080; &#1074;&#1074;&#1086;&#1076;&#1072;, &#1074; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1077; &#1084;&#1077;&#1085;&#1102; IVR &#1080;&#1079;, &#1090;&#1072;&#1082; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;&#1086;&#1075;&#1086; &#1087;&#1086;&#1076;&#1084;&#1077;&#1085;&#1102; (sub-IVR). &#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1077;&#1089;&#1083;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; IVR &#1073;&#1099;&#1083; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085; &#1082;&#1072;&#1082; sub-IVR &#1076;&#1083;&#1103; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1075;&#1086; &#1084;&#1077;&#1085;&#1102;
