      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1102; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074; &#1085;&#1077; &#1073;&#1099;&#1083; &#1089;&#1085;&#1103;&#1090; &#1089; &#8220;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1080;&#8221;, &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1083;&#1080;&#1073;&#1086; &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; &#8220;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1097;&#1080;&#1082;&#1091;&#8221;, &#1083;&#1080;&#1073;&#1086; &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1077; &#1076;&#1088;&#1091;&#1075;&#1086;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084;&#1086;&#1077; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#8211; IVR
      </li>
    </ol>
    <p>
      <b>Application \ Parking \ Parking Settings</b>
    </p>
    <p>
      <b>General Settings</b>
    </p>
    <ul>
      <li>
        <b>Parking Lot Extension</b>&#160;&#8211; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;, &#1087;&#1088;&#1080;&#1089;&#1074;&#1086;&#1077;&#1085;&#1085;&#1099;&#1081; &#8220;&#1089;&#1090;&#1086;&#1103;&#1085;&#1082;&#1077;&#8221;, &#1085;&#1086;&#1084;&#1077;&#1088; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1072; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1080;. &#1053;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1087;&#1077;&#1088;&#1077;&#1074;&#1077;&#1089;&#1090;&#1080; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1074;&#1099;&#1079;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1072;&#1090;&#1100;
      </li>
      <li>
        <b>Parking Lot Name</b>&#160;&#8211; &#1080;&#1084;&#1103; &#8220;&#1089;&#1090;&#1086;&#1103;&#1085;&#1082;&#1080;&#8221;
      </li>
      <li>
        <b>Parking Lot Starting Position</b>&#160;&#8211; &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1103; &#8220;&#1089;&#1090;&#1086;&#1103;&#1085;&#1082;&#1080;&#8221;, &#1085;&#1086;&#1084;&#1077;&#1088; &#1087;&#1077;&#1088;&#1074;&#1086;&#1075;&#1086; &#8220;&#1089;&#1083;&#1086;&#1090;&#1072;&#8221;. &#1042;&#1072;&#1078;&#1085;&#1086; &#1086;&#1090;&#1084;&#1077;&#1090;&#1080;&#1090;&#1100;, &#1095;&#1090;&#1086; &#1101;&#1090;&#1086;&#1090; &#1085;&#1086;&#1084;&#1077;&#1088; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089; Parking Lot
      </li>
      <li>
        <b>Extension Number of Slots</b>&#160;&#8211; &#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#8220;&#1089;&#1083;&#1086;&#1090;&#1086;&#1074;&#8221; &#1085;&#1072; &#8220;&#1089;&#1090;&#1086;&#1103;&#1085;&#1082;&#1077;&#8221; (&#1089;&#1074;&#1086;&#1073;&#1086;&#1076;&#1085;&#1099;&#1093; &#1084;&#1077;&#1089;&#1090;)
      </li>
      <li>
        <b>Parking Timeout (seconds)</b>&#160;&#8211; &#1074;&#1088;&#1077;&#1084;&#1103;, &#1074; &#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1074;&#1099;&#1079;&#1086;&#1074; &#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#8220;&#1089;&#1090;&#1086;&#1103;&#1085;&#1082;&#1077;&#8221;, &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1095;&#1077;&#1084; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; &#8220;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1097;&#1080;&#1082;&#1091;&#8221; &#1080;&#1083;&#1080; &#1087;&#1086; &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1084;&#1091; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102;
      </li>
      <li>
        <b>Parked Music Class</b>&#160;&#8211; &#1084;&#1091;&#1079;&#1099;&#1082;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1076;&#1086;&#1088;&#1086;&#1078;&#1082;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;&#1084; &#1087;&#1088;&#1080;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;
      </li>
      <li>
        <b>BLF (Busy Lamp Field) Capabilities</b>&#160;&#8211; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1080;&#1083;&#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102; &#1080;&#1085;&#1076;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1079;&#1072;&#1085;&#1103;&#1090;&#1086;&#1089;&#1090;&#1080; &#1083;&#1080;&#1085;&#1080;&#1080;
      </li>
      <li>
        <b>Find Slot</b>&#160;&#8211; &#1042; &#1082;&#1072;&#1082;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1074;&#1099;&#1079;&#1086;&#1074;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1084;&#1077;&#1089;&#1090;&#1072; &#1085;&#1072; &#1089;&#1090;&#1086;&#1103;&#1085;&#1082;&#1077;. First &#8211; &#1055;&#1077;&#1088;&#1074;&#1086;&#1077; &#1089;&#1074;&#1086;&#1073;&#1086;&#1076;&#1085;&#1086;&#1077; &#1084;&#1077;&#1089;&#1090;&#1086; &#1080;&#1083;&#1080; Next &#8211; &#1052;&#1077;&#1089;&#1090;&#1086;, &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1077; &#1079;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1084; &#1079;&#1072;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084; &#8220;&#1089;&#1083;&#1086;&#1090;&#1086;&#1084;&#8221;;
      </li>
    </ul>
    <p>
      <b>Returned Call Behavior. </b>&#1044;&#1072;&#1085;&#1085;&#1072;&#1103; &#1089;&#1077;&#1082;&#1094;&#1080;&#1103; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;, &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1102;&#1097;&#1080;&#1077; &#1079;&#1072; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1081;&#1096;&#1091;&#1102; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1091; &#1087;&#1088;&#1080;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &#1090;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090;&#1072;.
    </p>
    <ul>
      <li>
        <b>Pickup Courtesy Tone</b>&#160;&#8211; &#1082;&#1086;&#1084;&#1091; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1072;&#1090;&#1100; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1086; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1087;&#1088;&#1080;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1074;&#1099;&#1079;&#1086;&#1074; &#1087;&#1088;&#1080;&#1085;&#1103;&#1090;
      </li>
      <li>
        <b>Transfer Capability</b>&#160;&#8211; &#1082;&#1086;&#1084;&#1091; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1072; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084; <a href="#ID_40368134">DTMF</a>&#160;&#8211; &#1082;&#1086;&#1076;&#1086;&#1074;
      </li>
      <li>
        <b>Re-Parking Capability</b>&#160;&#8211; &#1082;&#1090;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074;
      </li>
      <li>
        <b>Parking Alert-Info</b>&#160;&#8211; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103;, &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1095;&#1077;&#1084; &#1074;&#1099;&#1079;&#1086;&#1074; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; &#8220;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1097;&#1080;&#1082;&#1091;&#8221; &#1080;&#1083;&#1080; &#1087;&#1086; &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1084;&#1091; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102;
      </li>
      <li>
        <b>CallerID Prepend</b>&#160;&#8211; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1087;&#1088;&#1080;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082;, &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1095;&#1077;&#1084; &#1074;&#1099;&#1079;&#1086;&#1074; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085; &#1087;&#1086; &#1087;&#1077;&#1088;&#1074;&#1086;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084;&#1091; &#1080;&#1083;&#1080; &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1084;&#1091; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1084;&#1086;&#1075;&#1072;&#1077;&#1090; &#1087;&#1086;&#1085;&#1103;&#1090;&#1100;, &#1086;&#1090;&#1082;&#1091;&#1076;&#1072; &#1086;&#1085; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1080;&#1083;. &#1058;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1079;&#1074;&#1086;&#1085;&#1086;&#1082;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1080; &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1102; &#1090;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090;&#1072;, &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1084;&#1077;&#1090;&#1100; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1100;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1080;&#1076;&#1085;&#1072; &#1085;&#1072; &#1101;&#1082;&#1088;&#1072;&#1085;&#1077; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072;
      </li>
      <li>
        <b>Auto CallerID Prepend</b>&#160;- &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082;, &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1102;&#1097;&#1080;&#1081;&#1089;&#1103; &#1089; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1080; &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1102; &#1090;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090;&#1072;. Slot &#8211;&#1085;&#1086;&#1084;&#1077;&#1088; &#8220;&#1089;&#1083;&#1086;&#1090;&#1072;&#8221;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1099;&#1083; &#1077;&#1084;&#1091; &#1087;&#1088;&#1080;&#1089;&#1074;&#1086;&#1077;&#1085;, Extension &#8211;&#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1077;&#1083; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1091;, Name &#8211; &#1048;&#1084;&#1103; Extension&#8217;&#1072; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1077;&#1083; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1091;, None &#8211; &#1053;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1086; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090;
      </li>
      <li>
        <b>Announcement</b>&#160;- &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;, &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1095;&#1077;&#1084; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085; &#1087;&#1086; &#1087;&#1077;&#1088;&#1074;&#1086;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084;&#1091; &#1080;&#1083;&#1080; &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1084;&#1091; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102;
      </li>
    </ul>
    <p>
      <b>Alternate Destination</b>
    </p>
    <ul>
      <li>
        <b>Come Back to Origin</b>&#160;- &#1086;&#1087;&#1094;&#1080;&#1103;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1072;&#1103; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100;, &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100; &#1083;&#1080; &#1087;&#1088;&#1080;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; &#1085;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1083;&#1086; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1091;, &#1090;&#1086; &#1077;&#1089;&#1090;&#1100; &#171;&#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1097;&#1080;&#1082;&#1091;&#187;
      </li>
      <li>
        <b>Destination</b>&#160;&#8211; &#1077;&#1089;&#1083;&#1080; &#1074; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1077;&#1084; &#1087;&#1091;&#1085;&#1082;&#1090;&#1077; &#1073;&#1099;&#1083;&#1086; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1086; No, &#1090;&#1086; &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1087;&#1086; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1086; &#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1086;&#1087;&#1094;&#1080;&#1080;, &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074; &#1089; &#1087;&#1072;&#1088;&#1082;&#1086;&#1074;&#1082;&#1080;
      </li>
    </ul>
    <p>
      
    </p>
