<node TEXT="Queues (Очереди)" FOLDED="true" ID="ID_839403620" CREATED="1540571944384" MODIFIED="1540891717099"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1809139509">&#1054;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; (Asterisk)</a>&#160;&#160; <a href="#ID_1894715021">Ring Group</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Queues (&#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;)</b>&#160;- &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1091;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; &#1080; &#1076;&#1072;&#1077;&#1090; &#1076;&#1086;&#1087;. &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;, &#1090;&#1072;&#1082;&#1086;&#1081; &#1082;&#1072;&#1082; &#1087;&#1088;&#1086;&#1075;&#1086;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1080;, &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1103;, &#1076;&#1072;&#1077;&#1090; &#1084;&#1077;&#1085;&#1102;, &#1087;&#1086; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084;&#1091; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1083;&#1072;&#1079;&#1080;&#1090;&#1100; &#1087;&#1086;&#1082;&#1072; &#1078;&#1076;&#1077;&#1096;&#1100;
    </p>
    <p>
      
    </p>
    <p>
      &#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1084;&#1080; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1084;&#1080; &#1095;&#1072;&#1089;&#1090;&#1103;&#1084;&#1080; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1077;&#1081; &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103;:
    </p>
    <ul>
      <li>
        <b>&#1042;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; (Callers)</b>&#160;- &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080;, &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084;&#1099;&#1077; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100;
      </li>
      <li>
        <b>&#1040;&#1075;&#1077;&#1085;&#1090;&#1099; (Agents)</b>&#160;- &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1099;, &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1102;&#1097;&#1080;&#1077; &#1085;&#1072; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080; &#1080;&#1079; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;
      </li>
      <li>
        <b>&#1057;&#1090;&#1072;&#1090;&#1080;&#1082;&#1072; (Static)</b>&#160;&#8211; &#1040;&#1075;&#1077;&#1085;&#1090; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1082;&#1080;&#1085;&#1091;&#1090;&#1100; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100;, &#1073;&#1091;&#1076;&#1091;&#1095;&#1080; &#1079;&#1072;&#1083;&#1086;&#1075;&#1080;&#1085;&#1077;&#1085;&#1099;&#1084;
      </li>
      <li>
        <b>&#1044;&#1080;&#1085;&#1072;&#1084;&#1080;&#1082;&#1072; (Dynamic)</b>&#160;- &#1040;&#1075;&#1077;&#1085;&#1090; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1080; &#1074;&#1099;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1080;&#1079; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; &#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;
      </li>
      <li>
        <b>&#1057;&#1090;&#1088;&#1072;&#1090;&#1077;&#1075;&#1080;&#1103; &#1047;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; (Ring Strategy)</b>&#160;- &#1089;&#1090;&#1088;&#1072;&#1090;&#1077;&#1075;&#1080;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;, &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1102;&#1097;&#1080;&#1093; &#1080;&#1079; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; &#1080; &#1080;&#1093; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1081;&#1096;&#1077;&#1075;&#1086; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1084;&#1077;&#1078;&#1076;&#1091; &#1040;&#1075;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080;
      </li>
      <li>
        <b>&#1052;&#1091;&#1079;&#1099;&#1082;&#1072; &#1085;&#1072; &#1091;&#1076;&#1077;&#1088;&#1078;&#1072;&#1085;&#1080;&#1080; (MoH)</b>&#160;- &#1084;&#1091;&#1079;&#1099;&#1082;&#1072; &#1080;&#1083;&#1080; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1090;&#1088;&#1091;&#1073;&#1082;&#1077; &#1091; &#1086;&#1078;&#1080;&#1076;&#1072;&#1102;&#1097;&#1080;&#1093; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074;
      </li>
      <li>
        <b>&#1054;&#1087;&#1086;&#1074;&#1077;&#1097;&#1077;&#1085;&#1080;&#1103; (Announcements)</b>&#160;- &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1086;&#1087;&#1086;&#1074;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1090;&#1088;&#1091;&#1073;&#1082;&#1077; &#1091; &#1095;&#1083;&#1077;&#1085;&#1086;&#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; (&#1040;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074; &#1080;&#1083;&#1080; &#1086;&#1078;&#1080;&#1076;&#1072;&#1102;&#1097;&#1080;&#1093; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074;). &#1057;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1086;&#1089;&#1090;&#1072;&#1083;&#1086;&#1089;&#1100;.
      </li>
    </ul>
    <p>
      <b>Applications \ Queues &gt; Add Queue</b>
    </p>
    <p>
      General Settings
    </p>
    <ul>
      <li>
        <b>Queue Number</b>&#160;- &#1085;&#1086;&#1084;&#1077;&#1088; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1072; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; &#1080;&#1083;&#1080; &#1040;&#1075;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080;, &#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086; &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1087;&#1072;&#1089;&#1090;&#1100; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100;
      </li>
      <li>
        <b>Queue Name</b>&#160;- &#1080;&#1084;&#1103; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;
      </li>
      <li>
        <b>Queue Password</b>&#160;- &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; &#1082;&#1072;&#1082;&#1080;&#1084;-&#1083;&#1080;&#1073;&#1086; &#1072;&#1075;&#1077;&#1085;&#1090;&#1072;&#1084;
      </li>
      <li>
        <b>Generate Device Hints</b>&#160;- &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1076;&#1089;&#1082;&#1072;&#1079;&#1082;&#1080; &#1080; &#1076;&#1072;&#1080;&#1083;&#1087;&#1083;&#1072;&#1085;&#1099; &#1076;&#1083;&#1103; &#1090;&#1077;&#1083;. &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074; &#1040;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074;
      </li>
      <li>
        <b>Call Confirm</b>&#160;- &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1040;&#1075;&#1077;&#1085;&#1090;&#1091; &#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1078;&#1076;&#1072;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074;, &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1095;&#1077;&#1084; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1077;&#1075;&#1086;
      </li>
      <li>
        <b>Call Confirm Announce</b>&#160;- &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1091;&#1089;&#1083;&#1099;&#1096;&#1080;&#1090; &#1040;&#1075;&#1077;&#1085;&#1090;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1076;&#1080;&#1090;, &#1095;&#1090;&#1086; &#1075;&#1086;&#1090;&#1086;&#1074; &#1087;&#1088;&#1080;&#1085;&#1103;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074; &#1080;&#1079; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;
      </li>
      <li>
        <b>CID Name Prefix</b>&#160;- &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089; &#1076;&#1083;&#1103; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1076;&#1089;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;, &#1086;&#1090;&#1082;&#1091;&#1076;&#1072; &#1087;&#1088;&#1080;&#1096;&#1105;&#1083; &#1074;&#1099;&#1079;&#1086;&#1074;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;: Tech_sup1: &lt;&#1085;&#1086;&#1084;&#1077;&#1088;&gt;
      </li>
      <li>
        <b>Wait Time Prefix</b>&#160;- &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;, &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081;, &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090; &#1086;&#1078;&#1080;&#1076;&#1072;&#1077;&#1090; &#1086;&#1090;&#1074;&#1077;&#1090;&#1072; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;
      </li>
      <li>
        <b>Alert Info</b>&#160;- &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1076;&#1083;&#1103; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; SIP &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;
      </li>
      <li>
        <b>Restrict Dynamic Agents</b>&#160;- &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; &#1074;&#1089;&#1077;&#1084;, &#1082;&#1088;&#1086;&#1084;&#1077; &#1040;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1093; &#1082;&#1072;&#1082; dynamic &#1074; Queue Agents
      </li>
      <li>
        <b>Agent Restrictions</b>&#160;- &#1089;&#1087;&#1077;&#1094;&#1080;&#1092;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1080; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1040;&#1075;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080;
      </li>
      <li>
        <b>Ring Strategy</b>&#160;- &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1089;&#1090;&#1088;&#1072;&#1090;&#1077;&#1075;&#1080;&#1081; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1080;&#1079; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1040;&#1075;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080;
      </li>
      <li>
        <b>Autofill</b>&#160;- &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;, &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1040;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074;
      </li>
      <li>
        <b>Skip Busy Agents</b>&#160;- &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1086;&#1073;&#1093;&#1086;&#1076;&#1072; &#1079;&#1072;&#1085;&#1103;&#1090;&#1099;&#1093; &#1040;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074;
      </li>
      <li>
        <b>Queue Weight</b>&#160;- &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;. &#1053;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;, &#1077;&#1089;&#1083;&#1080; &#1040;&#1075;&#1077;&#1085;&#1090; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1084; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1103;&#1084;
      </li>
      <li>
        <b>Music on Hold Class</b>&#160;- &#1084;&#1091;&#1079;&#1099;&#1082;&#1072; &#1085;&#1072; &#1091;&#1076;&#1077;&#1088;&#1078;&#1072;&#1085;&#1080;&#1080;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; <a href="#ID_1907810576">System Recordings</a>
      </li>
      <li>
        <b>Join Announcement</b>&#160;- &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1095;&#1077;&#1084; &#1074;&#1099;&#1079;&#1086;&#1074; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1077;&#1090; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100;
      </li>
      <li>
        <b>Call Recording</b>&#160;- &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; &#1080; &#1080;&#1093; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1072;
      </li>
      <li>
        <b>Mark calls answered elsewhere</b>&#160;- &#1087;&#1086;&#1084;&#1077;&#1095;&#1072;&#1077;&#1090; &#1085;&#1077; &#1086;&#1090;&#1074;&#1077;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074;&#1099;&#1079;&#1086;&#1074;&#1099;
      </li>
      <li>
        <b>Fail Over Destination</b>&#160;- &#1082;&#1091;&#1076;&#1072; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; &#1087;&#1077;&#1088;&#1077;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1072;, &#1080;&#1089;&#1090;&#1077;&#1082;&#1083;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103;
      </li>
    </ul>
    <p>
      &#1042;&#1086; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1077; <b>Queue Agents</b>&#160;&#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1080;&#1083;&#1080; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1040;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1079;&#1074;&#1086;&#1085;&#1082;&#1080; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;
    </p>
    <p>
      &#1042;&#1086; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1077; <b>Timing&amp;Agent Options</b>&#160;&#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1103; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;, &#1090;&#1072;&#1081;&#1084;-&#1072;&#1091;&#1090;&#1099; &#1040;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1074;&#1088;&#1077;&#1084;&#1103; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1086;&#1081; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1080; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1072; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1040;&#1075;&#1077;&#1085;&#1090;&#1091;, &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076; &#1090;&#1077;&#1084;, &#1082;&#1072;&#1082; &#1040;&#1075;&#1077;&#1085;&#1090; &#1086;&#1090;&#1074;&#1077;&#1090;&#1080;&#1090; &#1085;&#1072; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082;
    </p>
    <p>
      &#1042;&#1082;&#1083;&#1072;&#1076;&#1082;&#1072; <b>Capacity Options</b>&#160; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;, &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103; &#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1077;&#1085;&#1080;&#1103; &#1083;&#1080;&#1084;&#1080;&#1090;&#1072; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074;
    </p>
    <p>
      &#1042;&#1086; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1077; <b>Caller Announcements</b>&#160;&#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076;&#1080;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1091;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1084;&#1080;&#1085;&#1091;&#1090; &#1077;&#1084;&#1091; &#1086;&#1089;&#1090;&#1072;&#1083;&#1086;&#1089;&#1100; &#1078;&#1076;&#1072;&#1090;&#1100;: &#8220;&#1054;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; &#1086;&#1090;&#1074;&#1077;&#1090;&#1080;&#1090; &#1042;&#1072;&#1084; &#1095;&#1077;&#1088;&#1077;&#1079; 5/4/3/2 &#1084;&#1080;&#1085;&#1091;&#1090;&#8221;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1086;&#1078;&#1080;&#1076;&#1072;&#1102;&#1097;&#1077;&#1084;&#1091; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1091; &#1077;&#1075;&#1086; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1080; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;
    </p>
    <p>
      &#1042;&#1082;&#1083;&#1072;&#1076;&#1082;&#1072; <b>Advanced Options</b>&#160; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1072; &#1076;&#1083;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;
    </p>
    <p>
      <b>Reset Queue Stats</b>&#160;&#1089;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1074;&#1089;&#1102; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;
    </p>
    <p>
      <b>Other Options</b>&#160;&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1080; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; &#1076;&#1083;&#1103; &#1082;&#1088;&#1086;&#1089;&#1089;&#1087;&#1083;&#1072;&#1090;&#1092;&#1086;&#1088;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; &#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1081;, &#1090;&#1072;&#1082;&#1080;&#1093;
    </p>
    <p>
      &#1082;&#1072;&#1082; iSimphony
    </p>
  </body>
