    <p>
      &#1055;&#1088;&#1080; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1075;&#1086; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072; &#1085;&#1072; &#1088;&#1080;&#1085;&#1075;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1091; Managers, &#1082; &#1085;&#1086;&#1084;&#1077;&#1088;&#1091; &#1079;&#1074;&#1086;&#1085;&#1103;&#1097;&#1077;&#1075;&#1086; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1081; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089; &#8220;9&#8221;, &#1090;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1074;&#1089;&#1077; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1080; &#1080;&#1079; &#1088;&#1080;&#1085;&#1075;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1099;, &#1089;&#1084;&#1086;&#1075;&#1091;&#1090; &#1086;&#1095;&#1077;&#1085;&#1100; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1089;&#1088;&#1072;&#1079;&#1091; &#1074;&#1099;&#1079;&#1074;&#1072;&#1090;&#1100; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1079;&#1072;&#1085;&#1086;&#1074;&#1086;
