<node TEXT="Time Conditions" ID="ID_1309628818" CREATED="1540896352403" MODIFIED="1540897537793"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_869248871">Time Groups</a>&#160;&#160; <a href="#ID_1657749589">Call Flow Control</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Time Conditions</b>&#160;- &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1087;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;. &#1055;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1080;&#1079; &#1089;&#1077;&#1073;&#1103; &#1085;&#1072;&#1073;&#1086;&#1088; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1099; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; (Time Group).
    </p>
    <ul>
      <li>
        &#1042; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1076;&#1074;&#1072; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103;: &#1087;&#1077;&#1088;&#1074;&#1086;&#1077; &#8211; &#1077;&#1089;&#1083;&#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; Time Group, &#1072; &#1074;&#1090;&#1086;&#1088;&#1086;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1085;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103;
      </li>
      <li>
        Time Conditions &#1095;&#1072;&#1097;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090;<b>&#160; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1074; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080;</b>, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1076;&#1083;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1089; 10:00 &#1076;&#1086; 19:00 &#1085;&#1072; &#1089;&#1077;&#1082;&#1088;&#1077;&#1090;&#1072;&#1088;&#1103;, &#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1080; &#1087;&#1086; &#1074;&#1099;&#1093;&#1086;&#1076;&#1085;&#1099;&#1084;, &#1074;&#1099;&#1079;&#1086;&#1074;&#1099; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1079;&#1072;&#1088;&#1072;&#1085;&#1077;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1086;&#1077; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1091; <b>Time Conditions</b>&#160;&#1089;&#1090;&#1086;&#1080;&#1090; &#1085;&#1072;&#1095;&#1072;&#1090;&#1100; &#1089; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; Time Groups
      </li>
    </ul>
    <p>
      <b>Applications \ Time Conditions &gt; Add Time Condition</b>&#160;(&#1076;&#1086;&#1073;&#1080;&#1090;&#1100; &#1085;&#1086;&#1074;&#1086;&#1077; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1087;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;)
    </p>
    <ul>
      <li>
        <b>Time Condition Name</b>&#160;- &#1091;&#1082;&#1072;&#1078;&#1080;&#1090;&#1077; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#171;Work Hours&#187; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1080; &#171;Holidays&#187; &#1076;&#1083;&#1103; &#1074;&#1099;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093;
      </li>
      <li>
        <b>Override Code Pin</b>&#160;- &#1074; FreePBX13 &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; Feature Code, &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1101;&#1090;&#1086; *27. &#1057; &#1077;&#1075;&#1086; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1084;&#1086;&#1078;&#1085;&#1086; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100; Time Conditions. Override Code Pin &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; &#1087;&#1080;&#1085;-&#1082;&#1086;&#1076;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1096;&#1077;&#1085; &#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1087;&#1099;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1101;&#1090;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077;
      </li>
      <li>
        Invert BLF Hint - &#1044;&#1072;/&#1053;&#1077;&#1090; - &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1080;&#1079; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; &#1082;&#1086;&#1085;&#1076;&#1080;&#1094;&#1080;&#1081;, &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; BLF &#1093;&#1080;&#1085;&#1090; (hint). &#1057;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;, &#1085;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1084; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1077; &#1089; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1086;&#1081; BLF &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; Time Conditions. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;, (Invert BLF Hint = No) &#8211; &#1101;&#1090;&#1086; &#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; Time Condition &#1085;&#1077; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090;, &#1090;&#1086; &#1074; BLF &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; &#171;INUSE&#187;, &#1072; &#1101;&#1090;&#1086; &#1082;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086;, &#1082;&#1088;&#1072;&#1089;&#1085;&#1072;&#1103; &#1083;&#1072;&#1084;&#1087;&#1086;&#1095;&#1082;&#1072;. &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; Time Condition &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090; &#1089; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1081;, &#1090;&#1086; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; &#171;NOT_INUSE&#187;, &#1072; &#1101;&#1090;&#1086;, &#1082;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086; &#1079;&#1077;&#1083;&#1077;&#1085;&#1072;&#1103; &#1083;&#1072;&#1084;&#1087;&#1086;&#1095;&#1082;&#1072;. &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; Invert BLF Hint = Yes, &#1090;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1077; &#1074;&#1099;&#1096;&#1077; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077;
      </li>
      <li>
        <b>Change Override</b>&#160;- &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1074;&#1099;&#1087;&#1072;&#1076;&#1072;&#1102;&#1097;&#1077;&#1084; &#1084;&#1077;&#1085;&#1102;. &#1045;&#1089;&#1083;&#1080; &#1101;&#1090;&#1086; &#1085;&#1086;&#1074;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1077;&#1097;&#1105; &#1085;&#1077; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1086;, &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; &#1073;&#1091;&#1076;&#1077;&#1090; &#1053;&#1045;&#1048;&#1047;&#1042;&#1045;&#1057;&#1058;&#1053;&#1054;. &#1042; &#1080;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1074;&#1099; &#1091;&#1074;&#1080;&#1076;&#1080;&#1090;&#1077; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;

        <ul>
          <li>
            Unchanged - &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;
          </li>
          <li>
            Reset Override - &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1090; &#1083;&#1102;&#1073;&#1086;&#1081; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1086;&#1090;&#1084;&#1077;&#1095;&#1077;&#1085;
          </li>
          <li>
            Temporary Matched / Unmatched - &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1087;&#1086;&#1082;&#1072; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1082; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1085;&#1077; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1090;
          </li>
          <li>
            Permanent Matched / Unmatched - &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1091;&#1102; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1087;&#1086;&#1082;&#1072; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1072;
          </li>
        </ul>
      </li>
      <li>
        <b>Time Group</b>&#160;- &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1086;&#1090;&#1084;&#1077;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1082;, &#1076;&#1085;&#1080; &#1085;&#1077;&#1076;&#1077;&#1083;&#1080; &#1080; &#1084;&#1077;&#1089;&#1103;&#1094;&#1099;. &#1048;&#1084;&#1077;&#1085;&#1085;&#1086; &#1085;&#1072; &#1073;&#1072;&#1079;&#1077; Time Group &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1074; Time Condition
      </li>
      <li>
        <b>Destination non-matches</b>&#160;- &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074; &#1085;&#1077; &#1087;&#1086;&#1087;&#1072;&#1083; &#1087;&#1086;&#1076; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;, &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074; Time Group
      </li>
    </ul>
  </body>
</html></richcontent>
