    </p>
    <ol>
      <li>
        &#1055;&#1086;&#1089;&#1077;&#1090;&#1080;&#1090;&#1077;&#1083;&#1080; &#1074;&#1074;&#1086;&#1076;&#1103;&#1090; &#1089;&#1074;&#1086;&#1081; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088; &#1076;&#1083;&#1103; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1089; &#1085;&#1091;&#1078;&#1085;&#1086;&#1081; &#1074;&#1072;&#1084; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100;&#1102; &#1080;&#1083;&#1080; &#1088;&#1080;&#1085;&#1075;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1081;
      </li>
      <li>
        &#1069;&#1090;&#1086;&#1090; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089; &#1076;&#1083;&#1103; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1080;&#1090; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100;, &#1095;&#1090;&#1086; &#1074;&#1099;&#1079;&#1086;&#1074; &#1080;&#1076;&#1077;&#1090; &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1089; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1075;&#1086; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;. &#1058;&#1072;&#1082; &#1078;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072;, &#1076;&#1083;&#1103; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1074;&#1077;&#1088;&#1096;&#1080;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074;.
      </li>
      <li>
