      </li>
      <li>
        <b>Icon</b>&#160;- &#1074;&#1099;&#1073;&#1086;&#1088; &#1080;&#1082;&#1086;&#1085;&#1082;&#1080; &#1080;&#1079; &#1087;&#1088;&#1077;&#1076;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1099;&#1093;
      </li>
      <li>
        <b>Valid Message</b>&#160;- &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1074;&#1099;&#1089;&#1074;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;&#1084; &#1085;&#1072;&#1073;&#1086;&#1088;&#1077;
