  </head>
  <body>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; Firewall</b>&#160;(&#1089; FreePBX 13)<b>&#160;- </b>&#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1091;&#1102; &#1085;&#1080;&#1079;&#1082;&#1086;&#1091;&#1088;&#1086;&#1074;&#1085;&#1077;&#1074;&#1091;&#1102; &#1079;&#1072;&#1097;&#1080;&#1090;&#1091; IP-&#1040;&#1058;&#1057;. &#1054;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1080; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1077;&#1090; &#1072;&#1090;&#1072;&#1082;&#1080;, &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1103; &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1085;&#1099;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1085;&#1077;&#1087;&#1088;&#1077;&#1088;&#1099;&#1074;&#1085;&#1086; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1080;&#1088;&#1091;&#1077;&#1090; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;, &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1103; &#1080; &#1079;&#1072;&#1082;&#1088;&#1099;&#1074;&#1072;&#1103; &#1087;&#1086;&#1088;&#1090;&#1099; &#1076;&#1083;&#1103; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1093; &#1090;&#1088;&#1072;&#1085;&#1082;&#1086;&#1074;.
    </p>
    <p>
      
    </p>
    <p>
      <b>Connectivity \ Firewall</b>
    </p>
    <p>
      <b>1. &#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;:</b>&#160;&#1085;&#1072;&#1078;&#1072;&#1090;&#1100; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091; Enable Firewall.
    </p>
    <ul>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1085;&#1080;&#1082;&#1072;&#1082;&#1080;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1077;&#1097;&#1105; &#1085;&#1077; &#1079;&#1072;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1085;&#1099;, &#1080;&#1093; &#1085;&#1091;&#1078;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100;
      </li>
      <li>
        &#1052;&#1086;&#1076;&#1091;&#1083;&#1100; &#1089;&#1086;&#1086;&#1073;&#1097;&#1072;&#1077;&#1090; &#1095;&#1090;&#1086; IP-&#1072;&#1076;&#1088;&#1077;&#1089;, &#1087;&#1086;&#1076; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1084;&#1099; &#1079;&#1072;&#1096;&#1083;&#1080; &#1085;&#1072; IP-&#1040;&#1058;&#1057; &#1085;&#1077; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1095;&#1083;&#1077;&#1085;&#1086;&#1084; &#8220;&#1079;&#1086;&#1085;&#1099; &#1076;&#1086;&#1074;&#1077;&#1088;&#1080;&#1103;&#8221; (Trusted Zone) &#1080; &#1087;&#1088;&#1077;&#1076;&#1083;&#1072;&#1075;&#1072;&#1077;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1077;&#1075;&#1086; &#1076;&#1083;&#1103; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1099;&#1093; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1086;&#1082;
      </li>
    </ul>
    <p>
      <b>&#1047;&#1086;&#1085;&#1099;.</b>&#160;&#1042;&#1089;&#1077; &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1102;&#1097;&#1080;&#1077; &#1085;&#1072; VoIP-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1089;&#1095;&#1080;&#1090;&#1072;&#1102;&#1090;&#1089;&#1103; &#1095;&#1072;&#1089;&#1090;&#1100;&#1102; &#1079;&#1086;&#1085;&#1099;. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;, &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1102;&#1097;&#1080;&#1077; &#1085;&#1072; &#1085;&#1077;&#1075;&#1086; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1072;&#1090; &#1082; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1077;. &#1057;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1077; &#1079;&#1086;&#1085;&#1099; &#1076;&#1077;&#1083;&#1103;&#1090;&#1089;&#1103; &#1085;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1077;:
    </p>
    <ul>
      <li>
        <b>Reject</b>&#160;- &#1074;&#1089;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1086;&#1090;&#1085;&#1086;&#1089;&#1103;&#1097;&#1080;&#1077;&#1089;&#1103; &#1082; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1077;, &#1079;&#1072;&#1087;&#1088;&#1077;&#1097;&#1077;&#1085;&#1099;. &#1069;&#1090;&#1072;&#160;&#1079;&#1086;&#1085;&#1072; &#1087;&#1086;-&#1087;&#1088;&#1077;&#1078;&#1085;&#1077;&#1084;&#1091; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; RTP &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;, &#1085;&#1086; &#1085;&#1080;&#1082;&#1072;&#1082;&#1080;&#1077; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1087;&#1086;&#1088;&#1090;&#1099; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1085;&#1077; &#1087;&#1088;&#1086;&#1089;&#1083;&#1091;&#1096;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103;. &#1058;&#1088;&#1072;&#1092;&#1080;&#1082; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; Responsive Firewall
      </li>
      <li>
        <b>External</b>&#160;- &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; https &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1080; UCP &#1087;&#1086;&#1088;&#1090;&#1091;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085;&#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1099;. &#1058;&#1088;&#1072;&#1092;&#1080;&#1082; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099; &#1084;&#1086;&#1078;&#1077;&#1090; &#1090;&#1072;&#1082;&#1078;&#1077; &#1073;&#1099;&#1090;&#1100; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; Responsive Firewall
      </li>
      <li>
        Other - &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1076;&#1086;&#1074;&#1077;&#1088;&#1077;&#1085;&#1085;&#1099;&#1093; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1089;&#1077;&#1090;&#1103;&#1093;, &#1080;&#1083;&#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1103;&#1093;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; UCP, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1085;&#1077;&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; SIP &#1080; IAX
      </li>
      <li>
        <b>Internal</b>&#160;- &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1103;&#1093;, &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082;&#1086; &#1074;&#1089;&#1077;&#1084; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1072;&#1084; IP-&#1040;&#1058;&#1057;
      </li>
      <li>
        <b>Trusted</b>&#160;- &#1074;&#1089;&#1077; &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1099;. &#1055;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1077;&#1089;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1086;&#1090; &#1076;&#1086;&#1074;&#1077;&#1088;&#1077;&#1085;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099;. &#1048;&#1084;&#1077;&#1085;&#1085;&#1086; &#1089;&#1102;&#1076;&#1072; &#1085;&#1072;&#1084; &#1087;&#1088;&#1077;&#1076;&#1083;&#1086;&#1078;&#1072;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1085;&#1072;&#1096; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1074;&#1086;&#1084; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;
      </li>
    </ul>
    <p>
      <b>2. &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1085;&#1072;&#1096; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1074; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1076;&#1086;&#1074;&#1077;&#1088;&#1077;&#1085;&#1085;&#1099;&#1093;</b>: &#1053;&#1072;&#1078;&#1072;&#1090;&#1100; You can add the host automatically. &#1045;&#1089;&#1083;&#1080; &#1085;&#1072;&#1076;&#1087;&#1080;&#1089;&#1080; &#1085;&#1077;&#1090;, &#1079;&#1085;&#1072;&#1095;&#1080;&#1090; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1091;&#1078;&#1077; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;
    </p>
    <p>
      &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100;, &#1095;&#1090;&#1086; &#1072;&#1076;&#1088;&#1077;&#1089; (&#1080;&#1083;&#1080; &#1089;&#1077;&#1090;&#1100;) &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1099; &#1074; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1076;&#1086;&#1074;&#1077;&#1088;&#1077;&#1085;&#1085;&#1099;&#1093; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077; Networks
    </p>
    <p>
      <b>3. Connectivity \ Firewall \ Responsive Firewall - </b>&#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1105;&#1085;&#1085;&#1099;&#1093; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1086;&#1074; &#1080; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1077;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1099;&#1077; &#1072;&#1090;&#1072;&#1082;&#1080;. &#1058;&#1072;&#1082;&#1080;&#1084;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;&#1084;&#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; SIP
    </p>
    <p>
      &#1080;&#1083;&#1080; IAX, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1080;&#1083;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072;. &#1050;&#1086;&#1075;&#1076;&#1072; Responsive &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;, &#1090;&#1086; &#1083;&#1102;&#1073;&#1086;&#1081; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1086;&#1090; &#1093;&#1086;&#1089;&#1090;&#1072; &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1080;&#1090; &#1095;&#1077;&#1088;&#1077;&#1079; Firewall, &#1077;&#1089;&#1083;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1090;&#1072;&#1082;&#1080;&#1093; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;, &#1093;&#1086;&#1089;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1074;&#1096;&#1080;&#1081; &#1080;&#1093; &#1085;&#1077; &#1087;&#1088;&#1086;&#1096;&#1105;&#1083; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1091;&#1102; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1102;, &#1090;&#1086; &#1074;&#1077;&#1089;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1086;&#1090; &#1101;&#1090;&#1086;&#1075;&#1086; &#1093;&#1086;&#1089;&#1090;&#1072; &#1089;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1080;&#1081; &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1082; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; (60 &#1089;&#1077;&#1082;). &#1045;&#1089;&#1083;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1093;&#1086;&#1089;&#1090; &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1078;&#1072;&#1077;&#1090; &#1089;&#1083;&#1072;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1089; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1084; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080; &#1080; &#1073;&#1077;&#1079;&#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086; &#1087;&#1099;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072;&#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;, &#1090;&#1086; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1091;&#1078;&#1077; &#1077;&#1075;&#1086; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1085;&#1072; 24 &#1095;&#1072;&#1089;&#1072;. &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1077;&#1089;&#1083;&#1080; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085; fail2ban, &#1090;&#1086; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1077;&#1097;&#1105; &#1080; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090; &#1086; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1080;.
    </p>
    <ol>
      <li>
        Enable - &#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; Responsive
      </li>
      <li>
        &#1059;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100;, &#1076;&#1083;&#1103; &#1082;&#1072;&#1082;&#1080;&#1093; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;
      </li>
    </ol>
    <p>
      <b>4. </b>&#1048;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1077; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1080;&#1083;&#1080; &#1076;&#1072;&#1078;&#1077; &#1094;&#1077;&#1083;&#1099;&#1077; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1088;&#1086;&#1103;&#1074;&#1083;&#1103;&#1083;&#1080; &#1087;&#1086;&#1076;&#1086;&#1079;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1091;&#1102; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1089;&#1090;&#1100; &#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1080;&#1084;&#1077;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; IP-&#1040;&#1058;&#1057; &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074; <b>Blacklists</b>
    </p>
    <p>
      <b>5. Safe Mode</b>&#160;(&#1085;&#1077; &#1091;&#1074;&#1080;&#1076;&#1077;&#1083;!!!).&#160;&#1044;&#1072;&#1085;&#1085;&#1099;&#1081; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; IP&#1040;&#1058;&#1057; &#1077;&#1089;&#1083;&#1080; &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1086; &#1073;&#1099;&#1083;&#1072; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1072; &#1085;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1072;&#1103; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1088;&#1080;&#1074;&#1077;&#1083;&#1072; &#1082; &#1087;&#1086;&#1090;&#1077;&#1088;&#1077; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;, &#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080; &#1091; &#1074;&#1072;&#1089; &#1085;&#1077;&#1090;.
    </p>
    <p>
      &#1055;&#1088;&#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; Firewall, Safe Mode &#1091;&#1078;&#1077; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1077;&#1085;, &#1085;&#1086; <b>&#1095;&#1090;&#1086;&#1073;&#1099; &#1077;&#1075;&#1086; &#1072;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1076;&#1074;&#1072;&#1078;&#1076;&#1099; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091;</b>.
    </p>
    <p>
      &#1057;&#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082; &#1086;&#1076;&#1080;&#1085; &#1088;&#1072;&#1079;, &#1076;&#1086;&#1078;&#1076;&#1072;&#1090;&#1100;&#1089;&#1103;, &#1087;&#1086;&#1082;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1089;&#1103;, &#1072; &#1079;&#1072;&#1090;&#1077;&#1084; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1080; &#1074;&#1090;&#1086;&#1088;&#1091;&#1102; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;. &#1055;&#1086;&#1089;&#1083;&#1077; &#1095;&#1077;&#1075;&#1086;, &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1086;&#1090;&#1083;&#1086;&#1078;&#1080;&#1090; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083; Firewall&#8217;&#1072;, &#1072; &#1074;&#1099; &#1089;&#1084;&#1086;&#1078;&#1077;&#1090;&#1077; &#1089;&#1087;&#1086;&#1082;&#1086;&#1081;&#1085;&#1086; &#1091;&#1073;&#1088;&#1072;&#1090;&#1100; &#1090;&#1091; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;, &#1080;&#1079;-&#1079;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1087;&#1086;&#1090;&#1077;&#1088;&#1103;&#1083;&#1080; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;.
    </p>
    <p>
      &#1054; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074; Safe Mode, &#1073;&#1091;&#1076;&#1077;&#1090; &#1075;&#1086;&#1074;&#1086;&#1088;&#1080;&#1090;&#1100; &#1086;&#1075;&#1088;&#1086;&#1084;&#1085;&#1086;&#1077; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074; &#1089;&#1072;&#1084;&#1086;&#1084; &#1074;&#1077;&#1088;&#1093;&#1091; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1080;&#1089;&#1095;&#1077;&#1079;&#1085;&#1077;&#1090; &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1103;&#1090;&#1100; &#1084;&#1080;&#1085;&#1091;&#1090;, &#1090;&#1086;&#1075;&#1076;&#1072; &#1078;&#1077; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1103;&#1090;&#1089;&#1103; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; Firewall
    </p>
  </body>
</html></richcontent>
</node>
