  <body>
    <p>
      <a href="#ID_789612062">&#1064;&#1072;&#1073;&#1083;&#1086;&#1085;, &#1084;&#1072;&#1089;&#1082;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; (Asterisk)</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; Outbound Routes (&#1048;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;)</b>
    </p>
    <p>
      <b>Connectivity \ Outbound Routes &gt; Add</b>
    </p>
    <p>
      <b>Route Settings</b>
    </p>
    <ul>
      <li>
        <b>Route Name</b>&#160;- &#1080;&#1084;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;. &#1056;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1084; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1091; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072; &#8211; &#1101;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1073;&#1099;&#1089;&#1090;&#1088;&#1077;&#1077; &#1086;&#1088;&#1080;&#1077;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1093; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1093;
      </li>
      <li>
        <b>Route CID</b>&#160;- &#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1087;&#1086;&#1083;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; CallerID &#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;, &#1090;.&#1077; &#1085;&#1086;&#1084;&#1077;&#1088; &#1079;&#1074;&#1086;&#1085;&#1103;&#1097;&#1077;&#1075;&#1086;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1099; &#1073;&#1091;&#1076;&#1077;&#1084; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1074; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;. &#1044;&#1072;&#1085;&#1085;&#1099;&#1081; CID &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1084;&#1077;&#1085;&#1077;&#1077; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1085;&#1099;&#1084;, &#1095;&#1077;&#1084; CID &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1081; &#1085;&#1072; SIP &#8211; &#1090;&#1088;&#1072;&#1085;&#1082;&#1077; &#1080; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;&#1093; Ring Group, Follow Me
      </li>
      <li>
        <b>Override Extension</b>&#160;- Yes/No: &#1045;&#1089;&#1083;&#1080; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; Yes, &#1090;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1081; &#1074; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072;&#1093; &#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;&#1072; Outbound CID &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1075;&#1085;&#1086;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;
      </li>
      <li>
        <b>Route Password</b>&#160;- &#1076;&#1072;&#1085;&#1085;&#1072;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1090;&#1100; &#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1079;&#1074;&#1086;&#1085;&#1080;&#1090;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;. &#1069;&#1090;&#1086; &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1072;&#1103; &#1086;&#1087;&#1094;&#1080;&#1103;, &#1087;&#1088;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091;&#1085;&#1072;&#1088;. &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;&#1093;
      </li>
      <li>
        <b>Route Type</b>&#160;- &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1090;&#1080;&#1087; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;: &#1040;&#1074;&#1072;&#1088;&#1080;&#1081;&#1085;&#1099;&#1081; (Emergency) &#1080;&#1083;&#1080; &#1050;&#1086;&#1088;&#1087;&#1086;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; (Intra-Company)
      </li>
      <li>
        <b>Music On Hold</b>&#160;- &#1084;&#1091;&#1079;&#1099;&#1082;&#1072; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1103; &#1085;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1077;. &#1044;&#1083;&#1103; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1082;&#1072;&#1082;&#1086;&#1077;-&#1083;&#1080;&#1073;&#1086; &#1079;&#1074;&#1091;&#1082;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1088;&#1086;&#1076;&#1085;&#1086;&#1084; &#1076;&#1083;&#1103; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1103;&#1079;&#1099;&#1082;&#1077;
      </li>
      <li>
        <b>Time Group</b>&#160;- &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1086;&#1090;&#1084;&#1077;&#1095;&#1077;&#1085;&#1086;, &#1090;&#1086; &#1101;&#1090;&#1086;&#1090; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1077; &#1074; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;&#1093; Time Group &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;
      </li>
      <li>
        <b>Route Position</b>&#160;- &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1085;&#1086;&#1089;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1077;&#1075;&#1086; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1080;. &#1042; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1087;&#1091;&#1085;&#1082;&#1090;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1102; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072; &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093;
      </li>
      <li>
        <b>Trunk Sequence for Matched Routes</b>&#160;- &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; SIP-&#1090;&#1088;&#1072;&#1085;&#1082;&#1086;&#1074; &#1076;&#1083;&#1103; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; &#1074; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1090;&#1088;&#1072;&#1085;&#1082; &#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;, &#1074;&#1099;&#1079;&#1086;&#1074; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085; &#1074;&#1086; &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#1080; &#1090;&#1072;&#1082; &#1076;&#1072;&#1083;&#1077;&#1077;
      </li>
      <li>
        <b>Optional Destination on Congestion</b>&#160;- &#1077;&#1089;&#1083;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1077; &#1085;&#1077;&#1088;&#1072;&#1073;&#1086;&#1090;&#1086;&#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1080; SIP-&#1090;&#1088;&#1072;&#1085;&#1082;&#1086;&#1074;, &#1090;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1085;&#1072; &#1079;&#1074;&#1091;&#1082;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#171;&#1042; &#1085;&#1072;&#1089;&#1090;&#1086;&#1103;&#1097;&#1077;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1074;&#1089;&#1077; &#1083;&#1080;&#1085;&#1080;&#1080; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;. &#1054;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1077;&#1089;&#1100; &#1074; &#1090;&#1077;&#1093;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1091;&#187;
      </li>
    </ul>
    <p>
      <b>Dial Patterns (&#1064;&#1072;&#1073;&#1083;&#1086;&#1085; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072;)&#160;</b>- &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072;. &#160;&#160;&#1059;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1085;&#1072;&#1073;&#1086;&#1088; &#1094;&#1080;&#1092;&#1088;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074; &#1074; &#1085;&#1091;&#1078;&#1085;&#1099;&#1081; SIP-&#1090;&#1088;&#1072;&#1085;&#1082;. &#1045;&#1089;&#1083;&#1080; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090;, &#1090;&#1086; &#1074;&#1099;&#1079;&#1086;&#1074; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; SIP-&#1090;&#1088;&#1072;&#1085;&#1082; &#1074; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;. &#1064;&#1072;&#1073;&#1083;&#1086;&#1085; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1080;&#1084;&#1077;&#1077;&#1090; 4 &#1087;&#1086;&#1083;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;:
    </p>
    <p style="text-align: center">
      <b>(prepend) prefix | [ match pattern / &#1057;allerID ]</b>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        <b>Prepend</b>&#160;- &#1101;&#1090;&#1072; &#1095;&#1072;&#1089;&#1090;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1072; &#1082; &#1085;&#1086;&#1084;&#1077;&#1088;&#1091;, &#1087;&#1077;&#1088;&#1077;&#1076; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1086;&#1081; &#1074; SIP &#8211; &#1090;&#1088;&#1072;&#1085;&#1082; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1103; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1072;
      </li>
      <li>
        <b>Prefix</b>&#160;- &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089; &#8211; &#1095;&#1072;&#1089;&#1090;&#1100; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1072;
      </li>
      <li>
        <b>Match Pattern</b>&#160;- &#1085;&#1072;&#1073;&#1088;&#1072;&#1085;&#1085;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088;. Asterisk &#1080;&#1097;&#1077;&#1090; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1103; &#1087;&#1086;&#1083;&#1077; Prefix &#1080; Match Pattern
      </li>
      <li>
        <b>CallerID</b>&#160;- &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1080;&#1085;&#1080;&#1094;&#1080;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1089; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; CallerID. &#1042; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1087;&#1086;&#1083;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1099;
      </li>
    </ul>
  </body>
</html></richcontent>
