    <p>
      <b>FOP2</b>&#160;(Flash Operator Panel 2) &#8212; &#1101;&#1090;&#1086; &#1087;&#1072;&#1085;&#1077;&#1083;&#1100; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;&#1084;&#1080; &#1076;&#1083;&#1103; IP-&#1040;&#1058;&#1057; Asterisk, &#1088;&#1072;&#1073;&#1086;&#1090;&#1072; &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084; &#1074;&#1077;&#1073;-&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;. FOP2 &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1088;&#1072;&#1079;&#1085;&#1086;&#1086;&#1073;&#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103; &#1085;&#1072;&#1076; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1099;&#1084;&#1080; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1072;&#1084;&#1080;, &#1082;&#1072;&#1082; &#1085;&#1072;&#1076; &#1089;&#1074;&#1086;&#1080;&#1084;&#1080;, &#1090;&#1072;&#1082; &#1080; &#1085;&#1072;&#1076; &#1095;&#1091;&#1078;&#1080;&#1084;&#1080; (&#1087;&#1088;&#1080; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1080; &#1087;&#1088;&#1080;&#1074;&#1077;&#1083;&#1077;&#1075;&#1080;&#1081;), &#1095;&#1090;&#1086; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090; &#1101;&#1090;&#1091; &#1087;&#1072;&#1085;&#1077;&#1083;&#1100; &#1091;&#1076;&#1086;&#1073;&#1085;&#1086;&#1081; &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074; &#1082;&#1086;&#1083;&#1083;-&#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1093; &#1089;&#1091;&#1087;&#1077;&#1088;&#1074;&#1072;&#1081;&#1079;&#1077;&#1088;&#1072;&#1084;&#1080; &#1080; &#1074; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1103;&#1093; &#1089;&#1077;&#1082;&#1088;&#1077;&#1090;&#1072;&#1088;&#1103;&#1084;&#1080;.
    </p>
    <ul>
      <li>
        &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1074;&#1080;&#1076;&#1077;&#1090;&#1100; &#1080; &#1087;&#1086;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1076;&#1077;&#1090;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; real-time &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1091; &#1074;&#1072;&#1096;&#1077;&#1081; &#1040;&#1058;&#1057;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1082;&#1090;&#1086; &#1089; &#1082;&#1077;&#1084; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1077;&#1090;, &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1078;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074;, &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1074;&#1099;&#1079;&#1086;&#1074;&#1086;&#1074; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; &#1080;&#1083;&#1080; &#1085;&#1072; &#1091;&#1076;&#1077;&#1088;&#1078;&#1072;&#1085;&#1080;&#1080; &#1080; &#1090;&#1072;&#1082; &#1076;&#1072;&#1083;&#1077;&#1077;
      </li>
      <li>
        &#1087;&#1088;&#1077;&#1076;&#1083;&#1072;&#1075;&#1072;&#1077;&#1090; &#1087;&#1086;&#1083;&#1085;&#1086;&#1094;&#1077;&#1085;&#1085;&#1099;&#1081; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077;, &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1090;&#1100; &#1074;&#1099;&#1079;&#1086;&#1074; &#1080; &#1087;&#1088;&#1080;&#1077;&#1084; &#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1074;, &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1077;&#1088;, &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076; &#1085;&#1072; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1099;&#1081; &#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1072;, &#1072; &#1076;&#1083;&#1103; &#1089;&#1091;&#1087;&#1077;&#1088;&#1074;&#1080;&#1079;&#1086;&#1088;&#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099; &#1086;&#1087;&#1094;&#1080;&#1080; &#1087;&#1088;&#1086;&#1089;&#1083;&#1091;&#1096;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; (&#1096;&#1087;&#1080;&#1086;&#1085;&#1089;&#1082;&#1080;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083;) &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;&#1086;&#1074; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1074; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1080; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080; &#1087;&#1086; &#1079;&#1074;&#1086;&#1085;&#1082;&#1072;&#1084;
      </li>
    </ul>
    <p>
      
    </p>
    <ul>
      <li>
        &#1042; &#1073;&#1077;&#1089;&#1087;&#1083;&#1072;&#1090;&#1085;&#1086;&#1081; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1074;&#1099; &#1084;&#1086;&#1078;&#1077;&#1090;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1091;&#1084; &#1089; &#1087;&#1103;&#1090;&#1085;&#1072;&#1076;&#1094;&#1072;&#1090;&#1100;&#1102; &#1089;&#1091;&#1097;&#1085;&#1086;&#1089;&#1090;&#1103;&#1084;&#1080; (&#1101;&#1082;&#1089;&#1090;&#1077;&#1085;&#1096;&#1077;&#1085;&#1099;, &#1082;&#1086;&#1085;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094; - &#1088;&#1091;&#1084;&#1099;, &#1090;&#1088;&#1072;&#1085;&#1082;&#1080; &#1080; &#1090;&#1072;&#1082; &#1076;&#1072;&#1083;&#1077;&#1077;). &#1042; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; &#1087;&#1088;&#1086;&#1076;&#1091;&#1082;&#1090;&#1072; &#1080;&#1093; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090; &#171;&#1082;&#1085;&#1086;&#1087;&#1082;&#1072;&#1084;&#1080;&#187;
      </li>
