      </li>
    </ul>
    <p>
      <b>DECT-&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;:</b>&#160;&#1044;&#1083;&#1103; &#1087;&#1086;&#1082;&#1088;&#1099;&#1090;&#1080;&#1103; &#1087;&#1088;&#1080;&#1076;&#1087;&#1088;&#1080;&#1103;&#1090;&#1080;&#1103; &#1094;&#1077;&#1083;&#1080;&#1082;&#1086;&#1084;. &#1057;&#1086;&#1089;&#1090;&#1086;&#1080;&#1090; &#1080;&#1079;: &#1041;&#1072;&#1079;&#1086;&#1074;&#1099;&#1077; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080;; &#1050;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1083;&#1077;&#1088;&#1099;; &#1056;&#1077;&#1087;&#1080;&#1090;&#1077;&#1088;&#1099;. &#1041;&#1072;&#1079;&#1086;&#1074;&#1099;&#1077; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1086;&#1073;&#1086;&#1081; &#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1083;&#1077;&#1088;&#1072; (&#1086;&#1095;&#1077;&#1085;&#1100; &#1076;&#1086;&#1088;&#1086;&#1075;&#1086;&#1081;)
    </p>
    <ul>
      <li>
        KIRK. &#1044;&#1086;&#1088;&#1086;&#1075;&#1086;. &#1044;&#1083;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1087;&#1086;&#1082;&#1088;&#1099;&#1090;&#1080;&#1081;
      </li>
      <li>
        Aastra. &#1044;&#1077;&#1096;&#1077;&#1074;&#1083;&#1077;. &#1044;&#1083;&#1103; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1087;&#1086;&#1082;&#1088;&#1099;&#1090;&#1080;&#1081;. &#1041;&#1072;&#1079;&#1086;&#1074;&#1072;&#1103; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1103; &#1084;&#1086;&#1078;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1082;&#1072;&#1082; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1083;&#1077;&#1088;&#1072;, &#1090;&#1072;&#1082; &#1080; &#1073;&#1072;&#1079;&#1086;&#1074;&#1086;&#1081; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080;
      </li>
      <li>
        RTX. &#1044;&#1077;&#1096;&#1077;&#1074;&#1086; - &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1077; &#1087;&#1086;&#1082;&#1088;&#1099;&#1090;&#1080;&#1077; &#1080; &#1084;&#1072;&#1083;&#1086;&#1077; &#1082;&#1086;&#1083;-&#1074;&#1086; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074; (&#1076;&#1077;&#1096;&#1077;&#1074;&#1099;&#1077; &#1073;&#1072;&#1079;&#1086;&#1074;&#1099;&#1077; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080;, &#1085;&#1086; &#1076;&#1086;&#1088;&#1086;&#1075;&#1080;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1088;&#1072;&#1076;&#1080;&#1086;&#1090;&#1088;&#1091;&#1073;&#1082;&#1080; RTX). &#1054;&#1095;&#1077;&#1085;&#1100; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1076;&#1083;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1075;&#1086; &#1089;&#1082;&#1083;&#1072;&#1076;&#1072;
      </li>
    </ul>
    <p>
      <b>DECT-&#1088;&#1072;&#1076;&#1080;&#1086;&#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080;&#160;(&#1076;&#1086; 100 &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1086;&#1074;)</b>
    </p>
