<node TEXT="Компоненты регистрации" FOLDED="true" ID="ID_1682642127" CREATED="1538386102737" MODIFIED="1552638919379"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_349408907">&#1047;&#1072;&#1097;&#1080;&#1090;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1074; &#1080; &#1096;&#1083;&#1102;&#1079;&#1086;&#1074; </a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077;</b>&#160;- <a href="#ID_1327437000">PoE</a>, &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077; &#1086;&#1090; &#1089;&#1077;&#1090;&#1080; (220V), &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1095;&#1085;&#1086;&#1077; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103;
    </p>
    <ul>
      <li>
        PoE - 35$ &#1085;&#1072; &#1087;&#1086;&#1088;&#1090;
      </li>
      <li>
        &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088; + &#1041;&#1055; &#1082; &#1090;&#1077;&#1083;. - 30$ &#1085;&#1072; &#1087;&#1086;&#1088;&#1090;. &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; &#1077;&#1097;&#1077; &#1085;&#1091;&#1078;&#1085;&#1072; &#1076;&#1086;&#1087;. &#1088;&#1086;&#1079;&#1077;&#1090;&#1082;&#1072;
      </li>
      <li>
        &#1076;&#1086;&#1073;. &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103; - 70-100$ &#1085;&#1072; &#1087;&#1086;&#1088;&#1090;
      </li>
    </ul>
    <p>
      <b>IP &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;</b>. <a href="#ID_1597419282">&#1055;&#1086;&#1088;&#1090;&#1099; VLAN</a>. &#1050;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1099; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1090;:
    </p>
    <ul>
      <li>
        access port - &#1086;&#1076;&#1080;&#1085; VLAN
      </li>
      <li>
        access port - &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; VLAN (&#1087;&#1088;&#1086;&#1087;&#1088;&#1080;&#1077;&#1090;&#1072;&#1088;&#1085;&#1099;&#1081; Cisco &#1080; &#1076;&#1088;.)
      </li>
      <li>
        trunk port
      </li>
      <li>
        &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; DHCP. &#1045;&#1089;&#1083;&#1080; tftp-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1080; (&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084;), &#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084; <a href="#ID_890882405">DHCP Relay</a>. DHTPD (<a href="#ID_1220315205">&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;</a>&#160; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;)

        <ul>
          <li>
            IP-&#1072;&#1076;&#1088;&#1077;&#1089;
          </li>
          <li>
            &#1052;&#1072;&#1089;&#1082;&#1072; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1080;
          </li>
          <li>
            Default gateway
          </li>
          <li>
            <b>&#1054;&#1087;&#1094;&#1080;&#1103; 150</b>&#160;- &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1084; (Cisco) &#1076;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1103; &#1082; <b>&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1081;</b>&#160;(&#1086;&#1073;&#1099;&#1095;&#1085;&#1086; tftp-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;)
          </li>
          <li>
            <b>&#1054;&#1087;&#1094;&#1080;&#1103; 66</b>&#160;- &#1072;&#1085;&#1072;&#1083;&#1086;&#1075; &#1086;&#1087;&#1094;&#1080;&#1080; 150 &#1076;&#1083;&#1103; &#1090;&#1077;&#1083;. (Alcatel, Grandstream, Snom)
          </li>
          <li>
            NTP
          </li>
          <li>
            DNS
          </li>
          <li>
            SIP Proxy
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <b>&#1060;&#1072;&#1081;&#1083;&#1099; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;, &#1055;&#1054;</b>&#160;
    </p>
    <ul>
      <li>
        &#1095;&#1077;&#1088;&#1077;&#1079; <a href="#ID_410438924">TFTP</a>-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;. &#1062;&#1077;&#1085;&#1090;&#1088;&#1072;&#1083;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;, &#1084;&#1072;&#1089;&#1089;&#1086;&#1074;&#1086;. &#1058;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085; &#1079;&#1072;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1077;&#1090; &#1092;&#1072;&#1081;&#1083; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; --&gt; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;. &#1045;&#1089;&#1083;&#1080; &#1089;&#1086;&#1090;&#1085;&#1080; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1074;, &#1090;&#1086; &#1090;&#1086;&#1083;&#1086;&#1075;&#1086; &#1101;&#1090;&#1086;&#1090; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;.
      </li>
      <li>
        &#1095;&#1077;&#1088;&#1077;&#1079; Web-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;. &#1042;&#1074;&#1086;&#1076;&#1080;&#1084; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077;. &#1051;&#1086;&#1075;&#1080;&#1085;, &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; --&gt; &#1080;&#1085;&#1076;&#1080;&#1074;&#1080;&#1076;&#1091;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072;. &#1059;&#1076;&#1086;&#1073;&#1085;&#1086; &#1082;&#1086;&#1075;&#1076;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1074; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1072; 10 &#1096;&#1090;.
      </li>
    </ul>
    <p>
      <b>&#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1085;&#1072; IP PBX (&#1085;&#1072; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1081; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080;)</b>&#160;
    </p>
  </body>
</html></richcontent>
