<node TEXT="Заправка" ID="ID_1397260865" CREATED="1519112079688" MODIFIED="1519112079688"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      1. &#1060;&#1086;&#1090;&#1086;&#1073;&#1072;&#1088;&#1072;&#1073;&#1072;&#1085; <b>&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1091;&#1073;&#1080;&#1088;&#1072;&#1090;&#1100; &#1074; &#1090;&#1077;&#1084;&#1085;&#1099;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090;</b>&#160;(&#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1079;&#1072;&#1089;&#1074;&#1077;&#1090;&#1080;&#1090;&#1100;).
    </p>
    <p>
      2. &#1042;&#1072;&#1083; &#1079;&#1072;&#1088;&#1103;&#1076;&#1072; &#1087;&#1086;&#1076;&#1094;&#1077;&#1087;&#1083;&#1103;&#1077;&#1084; &#1079;&#1072; &#1084;&#1077;&#1090;. &#1089;&#1090;&#1077;&#1088;&#1078;&#1077;&#1085;&#1100; (&#1085;&#1077; &#1079;&#1072; &#1088;&#1077;&#1079;&#1080;&#1085;&#1091;).
    </p>
    <p>
