        &#1057;&#1087;&#1077;&#1082;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1077; &#1090;&#1077;&#1089;&#1090;-&#1082;&#1072;&#1088;&#1090;&#1099; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; <b>&#1089;&#1087;&#1077;&#1082;&#1090;&#1088;&#1086;&#1092;&#1086;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1072;</b>&#160;(&#1087;&#1077;&#1088;&#1077;&#1076; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077;&#1084; &#1087;&#1088;&#1086;&#1090;&#1077;&#1088;&#1077;&#1090;&#1100; &#1073;&#1077;&#1083;&#1099;&#1081; &#1101;&#1090;&#1072;&#1083;&#1086;&#1085; &#1080;&#1079;&#1086;&#1087;&#1088;&#1086;&#1087;&#1080;&#1083;&#1086;&#1074;&#1099;&#1084; &#1089;&#1087;&#1080;&#1088;&#1090;&#1086;&#1084;). &#1062;&#1077;&#1083;&#1100;: &#1042;&#1099;&#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1100; LAB-&#1082;&#1086;&#1086;&#1088;&#1076;&#1080;&#1085;&#1072;&#1090;&#1099; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1080;&#1079; &#1086;&#1073;&#1088;&#1072;&#1079;&#1094;&#1086;&#1074; &#1080; &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1080;&#1093; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1074;&#1096;&#1080;&#1084;&#1089;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1086;&#1084;. &#1057;&#1087;&#1077;&#1082;&#1090;&#1088;&#1086;&#1092;&#1086;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088; &#1080;&#1079;&#1084;&#1077;&#1088;&#1103;&#1077;&#1090; &#1089;&#1087;&#1077;&#1082;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1101;&#1085;&#1077;&#1088;&#1075;&#1080;&#1080; &#1089;&#1074;&#1077;&#1090;&#1086;&#1074;&#1099;&#1093; &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074;.
      </li>
      <li>
        &#1058;&#1077;&#1089;&#1090;-&#1082;&#1072;&#1088;&#1090;&#1091; &#1079;&#1072;&#1078;&#1080;&#1084;&#1072;&#1077;&#1084; &#1074; <b>&#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1083;&#1072;&#1085;&#1096;&#1077;&#1090; (&#1089; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1083;&#1080;&#1085;&#1077;&#1081;&#1082;&#1086;&#1081;)</b>. &#1054;&#1095;&#1077;&#1085;&#1100; &#1074;&#1072;&#1078;&#1085;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1088;&#1080; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1086;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1083;&#1080;&#1085;&#1077;&#1081;&#1082;&#1080; &#1073;&#1099;&#1083;&#1086; &#1089;&#1074;&#1086;&#1073;&#1086;&#1076;&#1085;&#1086;&#1077; &#1084;&#1077;&#1089;&#1090;&#1086; (&#1073;&#1077;&#1083;&#1086;&#1077;) &#1089; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1088;&#1086;&#1085;&#1099; &#1087;&#1072;&#1083;&#1080;&#1090;&#1088;&#1099; &#1076;&#1083;&#1103; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1086;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1072;.
      </li>
      <li>
        &#1046;&#1084;&#1077;&#1084; <b>Calibrate</b>.
      </li>
      <li>
        &#1050;&#1083;&#1072;&#1076;&#1077;&#1084; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088; &#1085;&#1072; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1091;&#1102; &#1083;&#1080;&#1085;&#1077;&#1081;&#1082;&#1091; &#1080; &#1087;&#1088;&#1086;&#1075;&#1086;&#1085;&#1103;&#1077;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1085;&#1086; &#1074;&#1089;&#1102; &#1090;&#1077;&#1089;&#1090;-&#1082;&#1072;&#1088;&#1090;&#1091;.
      </li>
      <li>
        <b>&#1042;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086;&#1077; &#1086;&#1089;&#1074;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077;</b>&#160;(Standsrt/CIE Illuminant D50). &#1045;&#1089;&#1083;&#1080; &#1084;&#1099; &#1079;&#1085;&#1072;&#1077;&#1084;, &#1087;&#1088;&#1080; &#1082;&#1072;&#1082;&#1080;&#1093; &#1086;&#1089;&#1074;&#1077;&#1097;&#1077;&#1085;&#1080;&#1080; &#1079;&#1072;&#1082;&#1072;&#1079;&#1095;&#1080;&#1082; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1089;&#1089;&#1084;&#1072;&#1090;&#1088;&#1080;&#1074;&#1072;&#1090;&#1100; &#1086;&#1090;&#1087;&#1077;&#1095;&#1072;&#1090;&#1082;&#1080;, &#1084;&#1099; &#1084;&#1086;&#1078;&#1077;&#1084; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; &#1089;&#1087;&#1077;&#1082;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1101;&#1085;&#1077;&#1088;&#1075;&#1080;&#1080; &#1092;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1087;&#1072;&#1076;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1089;&#1074;&#1077;&#1090;&#1072;. Ambient light &gt; Measure. &#1053;&#1072; &#1089;&#1087;&#1077;&#1082;&#1090;&#1088;&#1086;&#1092;&#1086;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088; &#1085;&#1072;&#1076;&#1077;&#1074;&#1072;&#1077;&#1084; &#1085;&#1072;&#1089;&#1072;&#1076;&#1082;&#1091; &#1076;&#1083;&#1103; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1089;&#1074;&#1077;&#1090;&#1072; (&#1089;&#1085;&#1080;&#1084;&#1072;&#1077;&#1084; &#1082;&#1088;&#1099;&#1096;&#1082;&#1091;), &#1085;&#1072;&#1078;&#1080;&#1084;&#1072;&#1077;&#1084; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091; &#1085;&#1072; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1077;. Save as...
      </li>
      <li>
        Keep Measurement &gt; &#1044;&#1072;&#1083;&#1077;&#1077; &gt; Profile Settings &gt;

        <ol>
          <li>
            Perceptual &gt; Colorful
          </li>
          <li>
            Tables &gt; Size AtoB (&#1096;&#1072;&#1075; &#1080;&#1085;&#1090;&#1077;&#1088;&#1087;&#1086;&#1083;&#1103;&#1094;&#1080;&#1080;) &gt; Large&gt;
          </li>
          <li>
