          </li>
          <li>
            Granelarity&gt; 16bit
          </li>
          <li>
            Smoothress &gt; (50 &#1076;&#1083;&#1103; &#1082;&#1088;&#1091;&#1090;&#1099;&#1093; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1086;&#1074;, 75 &#1076;&#1083;&#1103; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1093;)
          </li>
          <li>
            Chromatic adaptation &gt; (&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; Bradford, &#1088;&#1072;&#1079;&#1085;&#1080;&#1094;&#1099; &#1089; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;&#1080; &#1085;&#1080;&#1082;&#1072;&#1082;&#1086;&#1081;)
          </li>
          <li>
            ICC profile version &gt; version 2
          </li>
          <li>
            Profile White Point &gt; Default
          </li>
        </ol>
      </li>
      <li>
        &#1044;&#1072;&#1083;&#1077;&#1077;, &#1076;&#1072;&#1077;&#1084; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1091; @&#1055;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;_&#1041;&#1091;&#1084;&#1072;&#1075;&#1072;
      </li>
      <li>
        Include CxF data - V, &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1086; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1077;, &#1095;&#1090;&#1086; &#1077;&#1089;&#1083;&#1080; &#1074;&#1072;&#1084; &#1087;&#1086;&#1085;&#1072;&#1076;&#1086;&#1073;&#1080;&#1090;&#1089;&#1103; &#1089;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1086;&#1089;&#1074;&#1077;&#1090;&#1080;&#1090;&#1077;&#1083;&#1100;, &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1079;&#1072;&#1085;&#1086;&#1074;&#1086; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1090;&#1077;&#1089;&#1090;-&#1082;&#1072;&#1088;&#1090;&#1091; &#1080; &#1079;&#1072;&#1085;&#1086;&#1074;&#1086; &#1077;&#1077; &#1080;&#1079;&#1084;&#1077;&#1088;&#1103;&#1090;&#1100;, &#1053;&#1091;&#1078;&#1085;&#1086; &#1079;&#1072;&#1082;&#1080;&#1085;&#1091;&#1090;&#1100; &#1089;&#1072;&#1084; &#1087;&#1088;&#1086;&#1092;&#1072;&#1081;&#1083; &#1085;&#1072; &#1089;&#1090;&#1072;&#1076;&#1080;&#1080; Measurement &#1080; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1089;&#1074;&#1077;&#1090; (&#1080;&#1083;&#1080; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1080;&#1079; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072;).
      </li>
      <li>
