  <head>
    
  </head>
  <body>
    <ol>
      <li>
        &#1054;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1084; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; &#1074; Photoshop.
      </li>
      <li>
        Ctrl+P
      </li>
      <li>
        Color Handling &gt; Photoshop Manages Colors, Printer Profile &gt; &#1085;&#1072;&#1096; &#1087;&#1088;&#1086;&#1092;&#1072;&#1081;&#1083;. (&#1058;.&#1077;. &#1084;&#1099; &#1089;&#1086;&#1074;&#1084;&#1077;&#1097;&#1072;&#1077;&#1084; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; <b>Convert to Profile</b>&#160;&#1089; &#1087;&#1077;&#1095;&#1072;&#1090;&#1100;&#1102;)
      </li>
      <li>
        Rendering Intent:

        <ul>
          <li>
            Perceptual (&#1076;&#1086;&#1084;&#1072;&#1096;&#1085;&#1080;&#1077; (&#1090;.&#1077;. &#1086;&#1092;&#1080;&#1089;&#1085;&#1099;&#1077;) &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072;, &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103; &#1085;&#1080;&#1079;&#1082;&#1086;&#1081; &#1086;&#1089;&#1074;&#1077;&#1097;&#1077;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080; - 400-600 &#1051;&#1102;&#1082;&#1089;&#1086;&#1074;)
          </li>
          <li>
            Saturation (&#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1077; &#1087;&#1086;&#1083;&#1085;&#1086;&#1075;&#1086; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1103; &#1089; Perceptual)
          </li>
          <li>
            Relative Colormetric (&#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072; - &#1074;&#1099;&#1089;&#1086;&#1082;&#1072;&#1103; &#1086;&#1089;&#1074;&#1077;&#1097;&#1077;&#1085;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1087;&#1091;&#1083;&#1100;&#1090; &#1087;&#1077;&#1095;&#1072;&#1090;&#1085;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1099;, &#1085;&#1072; &#1091;&#1083;&#1080;&#1094;&#1077; (&#1085;&#1072;&#1088;&#1091;&#1078;&#1085;&#1072;&#1103; &#1088;&#1077;&#1082;&#1083;&#1072;&#1084;&#1072;) - 2000 &#1051;&#1102;&#1082;&#1089;&#1086;&#1074; (&#1085;&#1072; &#1091;&#1083;&#1080;&#1094;&#1077; &#1074; &#1087;&#1072;&#1089;&#1084;&#1091;&#1088;&#1085;&#1099;&#1081; &#1076;&#1077;&#1085;&#1100;).
          </li>
          <li>
            Abslolute Colormetric (&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1072; &#1094;&#1074;&#1077;&#1090;&#1086;&#1087;&#1088;&#1086;&#1073; &#1087;&#1086;&#1083;&#1080;&#1075;&#1088;&#1072;&#1092;&#1080;&#1089;&#1090;&#1072;&#1084;&#1080;)
          </li>
        </ul>
      </li>
      <li>
        &#1053;&#1077;&#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; <b>&#1094;&#1074;&#1077;&#1090;&#1086;&#1074;&#1099;&#1093; &#1086;&#1093;&#1074;&#1072;&#1090;&#1086;&#1074; (&#1062;&#1054;)</b>&#160;&#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1062;&#1054; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1072;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1091; <b>ColorThink</b>.

        <ol>
          <li>
            &#160;&#1047;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084; &#1085;&#1072;&#1096;&#1077; &#1090;&#1077;&#1089;&#1090;&#1086;&#1074;&#1086;&#1077; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;. &#1054;&#1073;&#1083;&#1072;&#1082;&#1086; &#1090;&#1086;&#1095;&#1077;&#1082; - &#1094;&#1074;&#1077;&#1090;&#1086;&#1074;&#1086;&#1081; &#1086;&#1093;&#1074;&#1072;&#1090; &#1090;&#1077;&#1089;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1080;&#1079;&#1086;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;.
