          <li>
            &#1047;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084; &#1062;&#1054; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1072; (&#1090;.&#1077;. &#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086;&#1092;&#1072;&#1081;&#1083; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1072;).
          </li>
          <li>
            &#1063;&#1072;&#1089;&#1090;&#1100; &#1090;&#1086;&#1095;&#1077;&#1082; &#1062;&#1054; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1099;&#1081;&#1090;&#1080; &#1080;&#1079; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1080; &#1062;&#1054; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1072;. &#1058;.&#1077;. &#1085;&#1077; &#1074;&#1086;&#1096;&#1077;&#1076;&#1096;&#1080;&#1084; &#1090;&#1086;&#1095;&#1082;&#1072;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100; &#1079;&#1072;&#1084;&#1077;&#1085;&#1091; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1086;&#1093;&#1074;&#1072;&#1090;&#1072; (<b>gamut mapping</b>). &#1045;&#1089;&#1083;&#1080; &#1086;&#1093;&#1074;&#1072;&#1090; &#1086;&#1095;&#1077;&#1085;&#1100; &#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1080;&#1081; &#1101;&#1090;&#1086; &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1090; &#1082; &#1090;&#1086;&#1084;&#1091; &#1095;&#1090;&#1086; &#1088;&#1072;&#1079;&#1074;&#1072;&#1083;&#1103;&#1090;&#1089;&#1103; &#1089;&#1086;&#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103; &#1084;&#1077;&#1078;&#1076;&#1091; &#1103;&#1088;&#1082;&#1086;&#1089;&#1090;&#1103;&#1084;&#1080; &#1080; &#1094;&#1074;&#1077;&#1090;&#1085;&#1086;&#1089;&#1090;&#1103;&#1084;&#1080; &#1074; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1080;.
          </li>
        </ol>
      </li>
      <li>
        &#1055;&#1088;&#1086;&#1092;&#1072;&#1081;&#1083; &#1087;&#1077;&#1095;&#1072;&#1090;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1085;&#1077;&#1089;&#1077;&#1090; &#1074; &#1089;&#1077;&#1073;&#1077; 6 &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1103;. Color Ful (I1Profiler) &#1089;&#1072;&#1084;&#1099;&#1081; &#1083;&#1091;&#1095;&#1096;&#1080;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; gamut mapping. &#1055;&#1086;&#1083;&#1079;&#1091;&#1085;&#1082;&#1080; &#1090;&#1088;&#1086;&#1075;&#1072;&#1090;&#1100; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086;. &#1042; Photoshop &gt; Edit &gt; Convert to Profile &gt; &#1042;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086;&#1092;&#1072;&#1081;&#1083; &gt; &#1048;&#1075;&#1088;&#1072;&#1077;&#1084; &#1095;&#1077;&#1082;-&#1073;&#1086;&#1082;&#1089;&#1086;&#1084; Preview
