      </li>
      <li>
        &#1058;&#1077;&#1093;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1094;&#1074;&#1077;&#1090;&#1086;&#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1094;&#1080;&#1103;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1085;&#1072;&#1084; &#1085;&#1077; &#1085;&#1088;&#1072;&#1074;&#1080;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082;&#1086;&#1081;-&#1090;&#1086; &#1094;&#1074;&#1077;&#1090;. &#1052;&#1099; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; CTRL+U, &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1094;&#1074;&#1077;&#1090;, &#1090;&#1099;&#1082;&#1072;&#1077;&#1084;&#1089;&#1103; &#1085;&#1072; &#1094;&#1074;&#1077;&#1090; &#1074; &#1082;&#1072;&#1088;&#1090;&#1080;&#1085;&#1082;&#1077; &#1080; &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1094;&#1074;&#1077;&#1090;.
      </li>
      <li>
        &#1063;&#1090;&#1086;&#1073;&#1099; &#1074; Photoshop &#1091;&#1074;&#1080;&#1076;&#1077;&#1090;&#1100; <b>&#1094;&#1074;&#1077;&#1090;&#1072; &#1074;&#1099;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1079;&#1072; &#1079;&#1086;&#1085;&#1091;</b>&#160;&#1062;&#1054; &#1085;&#1091;&#1078;&#1085;&#1086; &#1085;&#1072;&#1078;&#1072;&#1090;&#1100; Ctrl+Shift+Y (View &gt; Gamut Warning). &#1042;&#1085;&#1077;&#1075;&#1072;&#1084;&#1091;&#1090;&#1085;&#1099;&#1077; &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1080; &#1086;&#1082;&#1088;&#1072;&#1089;&#1080;&#1083;&#1080;&#1089;&#1100; &#1089;&#1077;&#1088;&#1099;&#1084;.
