      &#1045;&#1089;&#1083;&#1080; &#1089;&#1090;&#1088;&#1091;&#1081;&#1085;&#1099;&#1077; &#1095;&#1077;&#1088;&#1085;&#1080;&#1083;&#1072; &#1085;&#1072; &#1074;&#1086;&#1076;&#1077;, &#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1086;&#1078;&#1076;&#1072;&#1090;&#1100; 20 &#1084;&#1080;&#1085;&#1091;&#1090; (&#1076;&#1072;&#1090;&#1100; &#1074;&#1099;&#1089;&#1086;&#1093;&#1085;&#1091;&#1090;&#1100; &#1095;&#1077;&#1088;&#1085;&#1080;&#1083;&#1072;&#1084;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1085;&#1080; &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1083;&#1080;&#1074;&#1072;&#1083;&#1080;&#1089;&#1100;), 12 &#1095;&#1072;&#1089;&#1086;&#1074; &#1076;&#1083;&#1103; &#1090;&#1077;&#1089;&#1090;-&#1082;&#1072;&#1088;&#1090;&#1099;.
    </p>
    <ul>
      <li>
        &#1057;&#1077;&#1088;&#1099;&#1081; &#1082;&#1083;&#1080;&#1085; (&#1073;&#1077;&#1079; &#1087;&#1072;&#1088;&#1072;&#1079;&#1080;&#1090;&#1085;&#1099;&#1093; &#1087;&#1086;&#1076;&#1094;&#1074;&#1077;&#1090;&#1086;&#1082; &#1085;&#1072; &#1074;&#1089;&#1077;&#1081; &#1089;&#1074;&#1086;&#1077;&#1081; &#1087;&#1088;&#1086;&#1090;&#1103;&#1078;&#1077;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080;). &#1053;&#1077; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1076;&#1088;&#1086;&#1073;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1093;&#1088;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1087;&#1086;&#1083;&#1086;&#1089;&#1099;.
      </li>
      <li>
        &#1051;&#1080;&#1094;&#1086; &#1061;&#1072;&#1082;&#1072;&#1084;&#1072;&#1076;&#1099; &#1073;&#1077;&#1079; &#1079;&#1077;&#1083;&#1077;&#1085;&#1099;&#1093; &#1087;&#1103;&#1090;&#1077;&#1085;
      </li>
      <li>
        &#1051;&#1077;&#1074;&#1099;&#1077; &#1095;&#1077;&#1088;&#1085;&#1080;&#1083;&#1072; &#1089;&#1082;&#1072;&#1079;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1085;&#1077; &#1085;&#1072; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1086;&#1090;&#1087;&#1077;&#1095;&#1072;&#1090;&#1082;&#1072;, &#1072; &#1085;&#1072; &#1077;&#1075;&#1086; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1077;&#1084;&#1086;&#1089;&#1090;&#1080; (&#1082;&#1088;&#1072;&#1089;&#1082;&#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &quot;&#1091;&#1074;&#1103;&#1085;&#1091;&#1090;&#1100;&quot; &#1079;&#1072; &#1076;&#1074;&#1077; &#1085;&#1077;&#1076;&#1077;&#1083;&#1080;).
      </li>
      <li>
        RIP&#160;(Raster Image Processor, &#171;&#1088;&#1072;&#1089;&#1090;&#1088;&#1086;&#1074;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;&#187;, &#171;&#1056;&#1048;&#1055;&#187;) &#8212; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072;, &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1102;&#1097;&#1072;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1080;&#1079; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1074; &#1092;&#1086;&#1088;&#1084;&#1091;, &#1087;&#1086;&#1085;&#1103;&#1090;&#1085;&#1091;&#1102; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1091;. &#1069;&#1090;&#1080; &#1087;&#1077;&#1088;&#1077;&#1074;&#1077;&#1076;&#1077;&#1085;&#1085;&#1099;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1075;&#1086;&#1074;&#1086;&#1088;&#1103;&#1090; &#1074;&#1072;&#1096;&#1077;&#1084;&#1091; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1091;, &#1082;&#1072;&#1082; &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1090;&#1086;&#1095;&#1082;&#1080; &#1095;&#1077;&#1088;&#1085;&#1080;&#1083; &#1085;&#1072; &#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1077;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1074;&#1086;&#1089;&#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1080; &#1086;&#1088;&#1080;&#1075;&#1080;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;. &#1041;&#1086;&#1083;&#1100;&#1096;&#1080;&#1085;&#1089;&#1090;&#1074;&#1086; &#1056;&#1048;&#1055;&#1086;&#1074;, &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;&#1093; &#1089;&#1077;&#1075;&#1086;&#1076;&#1085;&#1103; &#1085;&#1072; &#1088;&#1099;&#1085;&#1082;&#1077;, &#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1099;&#1074;&#1072;&#1090;&#1100; &#1088;&#1072;&#1089;&#1090;&#1088;&#1086;&#1074;&#1091;&#1102;, &#1074;&#1077;&#1082;&#1090;&#1086;&#1088;&#1085;&#1091;&#1102; &#1080; &#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1091;&#1102; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102;.RIP &#1085;&#1091;&#1078;&#1077;&#1085; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1085;&#1077; &#1091;&#1076;&#1072;&#1083;&#1086;&#1089;&#1100; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1085;&#1086;&#1094;&#1077;&#1085;&#1085;&#1091;&#1102; ICC &#1093;&#1072;&#1088;&#1072;&#1082;&#1090;&#1077;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102; &#1087;&#1077;&#1095;&#1072;&#1090;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; (&#1090;.&#1077;. &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1072; &#1083;&#1077;&#1074;&#1086;&#1081; &#1073;&#1091;&#1084;&#1072;&#1075;&#1077; &#1083;&#1077;&#1074;&#1086;&#1081; &#1082;&#1088;&#1072;&#1089;&#1082;&#1086;&#1081; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103;).
      </li>
      <li>
        <b>&#1051;&#1072;&#1079;&#1077;&#1088;&#1085;&#1099;&#1077; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1099; &#1085;&#1077; &#1082;&#1072;&#1083;&#1080;&#1073;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103;</b>&#160;(&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1090;&#1086;&#1087;&#1086;&#1074;&#1099;&#1093; &#1095;&#1090;&#1086;-&#1090;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100;&#1089;&#1103;), &#1090;.&#1077;. &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1080;&#1089;&#1090;&#1099; &#1085;&#1077; &#1073;&#1077;&#1088;&#1091;&#1090;&#1089;&#1103;. &#1053;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1089;&#1103;.
