        &#1044;&#1083;&#1103; &#1101;&#1082;&#1086;&#1085;&#1086;&#1084;&#1080;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1080;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100;&#1089;&#1103; &#1082; <b>&#1073;&#1091;&#1084;&#1072;&#1075;&#1077;</b>&#160;Canon &#1080; HP. <b>&#1050;&#1088;&#1086;&#1084;&#1077; Lomond.</b>
      </li>
      <li>
        &#1057;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1080;&#1089;&#1090; &#1074; &#1052;&#1086;&#1089;&#1082;&#1074;&#1077;: &#1043;&#1077;&#1088;&#1084;&#1072;&#1085; 9166301478
