    <p>
      <b>&#1057;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;</b>:
    </p>
    <p>
      <b>Cmdlet</b>&#160;(&#1043;&#1083;&#1072;&#1075;&#1086;&#1083;-&#1057;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077;)&#160;<b>-&#1050;&#1083;&#1102;&#1095;</b>&#160;&lt;&#1086;&#1073;&#1098;&#1077;&#1082;&#1090; &#1082;&#1083;&#1102;&#1095;&#1072;&gt;&#160;&#1055;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; ( <b>|</b>&#160;) <b>Cmdlet </b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">Get-PSSnapin -Registered</font>&#160;# &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1082;&#1072;&#1082;&#1080;&#1077; <b>&#1085;&#1072;&#1073;&#1086;&#1088;&#1099; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1083;&#1077;&#1090;&#1086;&#1074; &#1079;&#1072;&#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1099;</b>&#160;&#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1081; &#1089;&#1077;&#1089;&#1089;&#1080;&#1080;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#000000"><b>&#1056;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1086;&#1074;&#1072;&#1085;&#1086;:</b></font>
    </p>
    <p>
      <font color="#0000c0"><b>Get-Help&#160;(&#1080;&#1083;&#1080; man) New-Mailbox -Examples</b></font><font color="#000000">&#160;# &#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100; &#1087;&#1086; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1083;&#1077;&#1090;&#1091; New-Mailbox &#1074; &#1074;&#1080;&#1076;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1086;&#1074;</font>
    </p>
    <p>
      <font color="#0000c0">Get-ExchangeServer -Identity &lt;MyExServer&gt; | Format-List</font>&#160;# &#1076;&#1072;&#1090;&#1100; &#1080;&#1085;&#1092;&#1086;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084; Ex &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; | &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; - &#1074;&#1099;&#1074;&#1086;&#1076; &#1089;&#1087;&#1080;&#1089;&#1082;&#1086;&#1084;
    </p>
    <p>
      <font color="#0000c0">Get-ExchangeServer -Identity &lt;MyExServer&gt; | Format-Table FQDN -Autosize </font># &#1076;&#1072;&#1090;&#1100; &#1080;&#1085;&#1092;&#1086;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084; Ex &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; | &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; - &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;, &#1089;&#1090;&#1086;&#1083;&#1073;&#1077;&#1094; FQDN, &#1072;&#1074;&#1090;&#1086;&#1087;&#1086;&#1076;&#1073;&#1086;&#1088; &#1096;&#1080;&#1088;&#1080;&#1085;&#1099;
    </p>
    <p>
      <b>&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1099;</b>
    </p>
    <p>
      <font color="#0000c0">Get-Mailbox -Server &lt;&#1050;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1081;&#1057;&#1077;&#1088;&#1074;&#1077;&#1088;&gt;</font>&#160;# &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1091;&#1077;&#1084; &#1074;&#1099;&#1076;&#1072;&#1095;&#1091; &#1103;&#1097;&#1080;&#1082;&#1086;&#1074; &#1087;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;, &#1073;&#1086;&#1083;&#1077;&#1077; &#1073;&#1099;&#1089;&#1090;&#1088;&#1072;&#1103; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103;
    </p>
    <p>
      <font color="#0000c0">Get-Mailbox | Where-Object {$_.ServerName -like &quot;&#1050;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1081;&#1057;&#1077;&#1088;&#1074;&#1077;&#1088;&quot;}</font>&#160; - &#1090;&#1086;&#1078;&#1077; &#1089;&#1072;&#1084;&#1086;&#1077;, &#1085;&#1086; &#1087;&#1086;-&#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091;, &#1073;&#1086;&#1083;&#1077;&#1077; &#1084;&#1077;&#1076;&#1083;&#1077;&#1085;&#1085;&#1072;&#1103; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103;, &#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089; &#1082;&#1091;&#1095;&#1077;&#1081; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1080;&#1081;. -like (&#1095;&#1091;&#1074;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072; &#1082; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1091;) -ilike (&#1085;&#1077; &#1095;&#1091;&#1074;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072; &#1082; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1091;)
    </p>
    <p>
      <font color="#0000c0">Clean-MailboxDatabase &quot;MyDB&quot;</font>&#160;- &#1091;&#1089;&#1082;&#1086;&#1088;&#1103;&#1077;&#1090; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; &#1072;&#1088;&#1093;&#1080;&#1074;&#1085;&#1099;&#1093; &#1103;&#1097;&#1080;&#1082;&#1086;&#1074; &#1074; <i>Recipient Configuration\ Disconnected Mailbox </i>
    </p>
    <p>
      <font color="#0000c0">Get-Queue</font>&#160;- &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; &#1087;&#1080;&#1089;&#1077;&#1084;
