<node TEXT="Case 5 (WSB)" ID="ID_1791739554" CREATED="1519112080302" MODIFIED="1539967390606"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Windows Server Backup</b>&#160;(&#1041;&#1101;&#1082;&#1072;&#1087;&#1080;&#1084; &#1073;&#1072;&#1079;&#1091; Mailbox)
    </p>
    <ol>
      <li>
        Dismounted MyDB &gt; &#1089;&#1088;&#1072;&#1079;&#1091; Mounted MyDB - &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1077; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1087;&#1086;&#1087;&#1072;&#1083;&#1086; &#1074; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1077; &#1083;&#1086;&#1075;&#1080;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1074; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1084; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1084; &#1083;&#1086;&#1075;&#1077;.<br/>&#1042;&#1089;&#1077; &#1073;&#1101;&#1082;&#1072;&#1087;&#1080;&#1090;&#1089;&#1103; &#1087;&#1086; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; VSS, &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1081; &#1083;&#1086;&#1075; &#1074; &#1073;&#1101;&#1082;&#1072;&#1087; &#1085;&#1077; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090;.
      </li>
      <li>
        WSB &gt; Backup Once... &gt; Different options &gt; Custom &gt; Add Items (&#1075;&#1086;&#1074;&#1086;&#1088;&#1080;&#1084; &#1095;&#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1073;&#1101;&#1082;&#1072;&#1087;&#1080;&#1090;&#1100; &#1076;&#1080;&#1089;&#1082; &#1094;&#1077;&#1083;&#1080;&#1082;&#1086;&#1084; &#1075;&#1076;&#1077; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1073;&#1072;&#1079;&#1072;, &#1074; &#1087;&#1088;&#1086;&#1090;&#1086;&#1074;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; WSB &#1085;&#1077; &#1087;&#1086;&#1081;&#1084;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1086;&#1085; &#1073;&#1101;&#1082;&#1072;&#1087;&#1080;&#1090; Exchange) &gt; Advanced Settings\ VSS Settings\&#160;VSS full Backup (&#1077;&#1089;&#1083;&#1080; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; Full, &#1090;&#1086; &#1085;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1086;&#1095;&#1080;&#1097;&#1077;&#1085;&#1099; &#1083;&#1086;&#1075;&#1080;)
      </li>
    </ol>
    <p>
      &#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;:
    </p>
    <ol>
      <li>
        &#1055;&#1077;&#1088;&#1077;&#1076; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084; &#1073;&#1072;&#1079;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1094;&#1077;&#1083;&#1080;&#1082;&#1086;&#1084; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1072;, &#1083;&#1080;&#1073;&#1086; &#1074; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1093; &#1073;&#1072;&#1079;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1089;&#1090;&#1086;&#1103;&#1090;&#1100; &#1075;&#1072;&#1083;&#1082;&#1072;, &#1095;&#1090;&#1086; &#1086;&#1085;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1072;. ExMC &gt; Organization Configuration\ Mailbox\ DataBase Management\ MyDB &gt; Properties\ Maintenance\ This database can be overwritten by a restore
      </li>
      <li>
        WSB &gt; Recovery &gt; &#1042;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1073;&#1101;&#1082;&#1072;&#1087; &gt; <b>Applications</b>&#160;(&#1045;&#1089;&#1083;&#1080; &#1082;&#1085;&#1086;&#1087;&#1082;&#1072; &#1089;&#1077;&#1088;&#1072;&#1103;, &#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1080;&#1090; &#1073;&#1101;&#1082;&#1072;&#1087;&#1080;&#1083;&#1080; &#1085;&#1077; &#1076;&#1080;&#1089;&#1082; &#1094;&#1077;&#1083;&#1080;&#1082;&#1086;&#1084;, &#1080; WSB &#1085;&#1077; &#1087;&#1086;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1095;&#1090;&#1086; &#1090;&#1072;&#1084; Exchange) &gt;
      </li>
      <li>
        <b>Do not perform a roll-forward recovery or the application database</b>&#160;(&#1076;&#1083;&#1103; &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1085;&#1086;&#1081; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1073;&#1072;&#1079;&#1099; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1077; &#1083;&#1086;&#1075;&#1080; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1072;&#1085;&#1099; - &#1089;&#1090;&#1072;&#1074;&#1080;&#1084; &#1075;&#1072;&#1083;&#1082;&#1091; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1080;&#1075;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1077; &#1083;&#1086;&#1075;&#1080;, &#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1077;&#1097;&#1077; &#1085;&#1072;&#1082;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; -&#1076;&#1083;&#1103; &#1080;&#1085;&#1082;&#1088;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1073;&#1101;&#1082;&#1072;&#1087;&#1086;&#1074;).&#160;<br/>&#1041;&#1077;&#1079; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1103; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1086;&#1075;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1075;&#1086; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1083;&#1086;&#1075;&#1072; &#1073;&#1072;&#1079;&