    </ul>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1091; &#1085;&#1072;&#1089; &#1074; &#1089;&#1077;&#1090;&#1080; &#1077;&#1089;&#1090;&#1100; AD RMS &#1084;&#1099; &#1084;&#1086;&#1078;&#1077;&#1084; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; <b>Exchange </b>&#1085;&#1072; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1089;&#1074;&#1103;&#1079;&#1100; &#1089; RMS. &#1050;&#1086;&#1075;&#1076;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1087;&#1080;&#1100;&#1089;&#1084;&#1086;, &#1086;&#1085; &#1084;&#1086;&#1078;&#1077;&#1090; &#1077;&#1075;&#1086; &#1079;&#1072;&#1097;&#1080;&#1090;&#1080;&#1090;&#1100;:
    </p>
    <ul>
      <li>
        &#1089;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; <b>&#1082;&#1090;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1086;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100;</b>, &#1072; &#1082;&#1090;&#1086; &#1085;&#1077;&#1090;
      </li>
      <li>
        &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; <b>&#1089;&#1088;&#1086;&#1082; &#1078;&#1080;&#1079;&#1085;&#1080; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072; </b>- &#1095;&#1077;&#1088;&#1077;&#1079; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1081; &#1089;&#1088;&#1086;&#1082; &#1077;&#1075;&#1086; &#1085;&#1080;&#1082;&#1090;&#1086; &#1085;&#1077; &#1087;&#1088;&#1086;&#1095;&#1080;&#1090;&#1072;&#1077;&#1090;
      </li>
      <li>
        <b>&#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1085;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1089;&#1099;&#1083;&#1072;&#1090;&#1100; &#1080; &#1087;&#1077;&#1095;&#1072;&#1090;&#1072;&#1090;&#1100;</b>&#160; (&#1087;&#1088;&#1080;&#1085;&#1090;&#1089;&#1082;&#1088;&#1080;&#1085;&#1099;, &#1085;&#1086;&#1078;&#1085;&#1080;&#1094;&#1099;, &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090;) &gt; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1092;&#1086;&#1090;&#1086;&#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090; (&#1085;&#1091; &#1080;&#1083;&#1080; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1085;&#1072; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1077;, &#1072; &#1087;&#1088;&#1080;&#1085;&#1090;&#1089;&#1082;&#1088;&#1080;&#1085; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1085;&#1072; &#1093;&#1086;&#1089;&#1090;&#1086;&#1074;&#1086;&#1081;)
      </li>
      <li>
        &#1077;&#1089;&#1083;&#1080; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1079;&#1072;&#1097;&#1080;&#1097;&#1077;&#1085;&#1085;&#1086;&#1077; <b>RMS &#1091;&#1096;&#1083;&#1086; &#1079;&#1072; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1099; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;</b>&#160; &gt; &#1083;&#1102;&#1073;&#1086;&#1081; &#1082;&#1090;&#1086; &#1086;&#1090;&#1082;&#1088;&#1086;&#1077;&#1090; &#1101;&#1090;&#1086;&#160;&#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082; RMS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &gt; &#1045;&#1089;&#1083;&#1080; RMS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1089;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080; &#1085;&#1077; &#1086;&#1087;&#1091;&#1073;&#1083;&#1080;&#1082;&#1086;&#1074;&#1072;&#1085;, &#1090;&#1086; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1100; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;
      </li>
      <li>
        <b>&#1091;&#1084;&#1077;&#1077;&#1090; &#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; &#1083;&#1077;&#1090;&#1091;</b>. &#1045;&#1089;&#1083;&#1080; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1089; &#1087;&#1086;&#1084;&#1077;&#1090;&#1082;&#1086;&#1081; &#1074;&#1072;&#1078;&#1085;&#1086; &#1080;&#1083;&#1080; <a href="#ID_583574348">&#1050;&#1083;&#1072;&#1089;&#1089;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1077;&#1081;</a>&#160;&quot;&#1055;&#1088;&#1080;&#1082;&#1072;&#1079; &#1087;&#1086; &#1087;&#1088;&#1077;&#1076;&#1087;&#1088;&#1080;&#1103;&#1090;&#1080;&#1102;&quot;, &#1090;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1089; &#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; RMS (Exchange &#1073;&#1091;&#1076;&#1091;&#1077;&#1090; &#1089;&#1072;&#1084; &#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;)
      </li>
    </ul>
