<node TEXT="Роли" ID="ID_1488417291" CREATED="1519112080304" MODIFIED="1519112080304"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Exchange &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;&#1085;&#1086;, &#1088;&#1086;&#1083;&#1103;&#1084;&#1080;. <b>&#1042;&#1089;&#1077;&#1075;&#1086; 5 &#1088;&#1086;&#1083;&#1077;&#1081;</b>. &#1045;&#1089;&#1090;&#1100; <b>&#1075;&#1083;&#1072;&#1074;&#1085;&#1099;&#1077; &#1088;&#1086;&#1083;&#1080;</b>,&#160;&#160;&#1073;&#1077;&#1079; &#1085;&#1080;&#1093; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; Exchange &#1085;&#1080;&#1095;&#1090;&#1086;&#1078;&#1085;&#1072;.
    </p>
    <ul>
      <li>
        <b>Mailbox Server</b>. &#1054;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1073;&#1072;&#1079; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1075;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. &#1042; ES2010 &#1077;&#1089;&#1090;&#1100; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; 2&#1093; &#1074;&#1080;&#1076;&#1086;&#1074;:

        <ul>
          <li>
            &#1075;&#1076;&#1077; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1077; &#1103;&#1097;&#1080;&#1082;&#1080;
          </li>
          <li>
            &#1075;&#1076;&#1077; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1086;&#1073;&#1097;&#1080;&#1077; &#1087;&#1072;&#1087;&#1082;&#1080;
          </li>
        </ul>
      </li>
      <li>
        <b>Client Access Server</b>. &#1055;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1074;&#1089;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; (&#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; ES2010). &#1040;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1091;&#1077;&#1090; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; &#1080; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; Mailbox &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;.
      </li>
      <li>
        <b>Hub Transport Server</b>. &#1054;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102; &#1087;&#1086;&#1095;&#1090;&#1099; (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; - &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;, &#1087;&#1086; &#1078;&#1077;&#1083;&#1072;&#1085;&#1080;&#1102; - &#1079;&#1072; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1084;&#1080; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;). &#1053;&#1080; &#1086;&#1076;&#1085;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1085;&#1077; &#1091;&#1081;&#1076;&#1077;&#1090; &#1080; &#1085;&#1077; &#1087;&#1088;&#1080;&#1081;&#1076;&#1077;&#1090; &#1073;&#1077;&#1079; &#1101;&#1090;&#1086;&#1081; &#1088;&#1086;&#1083;&#1080;. &#1044;&#1086;&#1083;&#1078;&#1077;&#1085; &#1080;&#1084;&#1077;&#1090;&#1100; &#1093;&#1086;&#1090;&#1100; &#1086;&#1076;&#1080;&#1085; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088; &#1087;&#1088;&#1080;&#1077;&#1084;&#1072; (&#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1083;&#1091;&#1096;&#1072;&#1083; 25 &#1087;&#1086;&#1088;&#1090;).
      </li>
    </ul>
    <p>
      <b>&#1054;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1088;&#1086;&#1083;&#1080;:</b>
    </p>
    <ul>
      <li>
        <b>Edge Transport Server</b>.&#160;&#160;&#1042;&#1089;&#1077;&#1075;&#1076;&#1072; &#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1089;&#1103; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086; &#1086;&#1090; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1088;&#1086;&#1083;&#1077;&#1081; Exchange. &#1069;&#1090;&#1072; &#1088;&#1086;&#1083;&#1100; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; AD. &#1057;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1083;&#1089;&#1103; &#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1074;&#1099;&#1085;&#1077;&#1089;&#1090;&#1080; &#1072;&#1085;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1089;&#1085;&#1099;&#1081; &#1080; &#1072;&#1085;&#1090;&#1080;&#1089;&#1087;&#1072;&#1084; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083; &#1074; &quot;&#1076;&#1077;&#1084;&#1080;&#1083;&#1080;&#1090;&#1072;&#1088;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1085;&#1091;&#1102;&quot; &#1079;&#1086;&#1085;&#1091;. &#1047;&#1072;&#1076;&#1072;&#1095;&#1080;:

        <ul>
          <li>
            &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1087;&#1086;&#1095;&#1090;&#1091; &#1080;&#1079; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1072;
          </li>
          <li>
            &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1091;&#1077;&#1090; &#1077;&#1077; &#1085;&#1072; &#1089;&#1087;&#1072;&#1084;
          </li>
          <li>
            &#1092;&#1080;&#1083;&#1100;&#1088;&#1091;&#1077;&#1090; &#1085;&#1072; &#1074;&#1080;&#1088;&#1091;&#1089;&#1099; (&#1087;&#1088;&#1080; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1080; &#1072;&#1085;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1089;&#1072;)
          </li>
          <li>
            <b>&#1087;&#1088;&#1086;&#1082;&#1080;&#1076;&#1099;&#1074;&#1072;&#1077;&#1090;</b>&#160;&#1074;&#1085;&#1091;&#1090;&#1088;&#1100; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1085;&#1072; <b>Hub Transport Server</b>, &#1090;.&#1077;. Client Access Server &#1085;&#1077; &#1091;&#1095;&#1072;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090;.
          </li>
          <li>
            &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1072;&#1083;&#1072;&#1090;&#1100; &#1095;&#1083;&#1077;&#1085;&#1086;&#1084; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072; &#1080; &#1087;&#1088;&#1080;&#1076;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077;&#1075;&#1086; 3 &#1087;&#1086;&#1088;&#1090;&#1072; &#1074;&#1086; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1102;&#1102; &#1089;&#1077;&#1090;&#1100;:

            <ul>
              <li>
                25 - &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1087;&#1086;&#1090;&#1099;
              </li>
              <li>
                53 - &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1080;&#1084;&#1077;&#1085;
              </li>
              <li>
                50636 - &#1076;&#1083;&#1103; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1089; Hub transport Server
              </li>
            </ul>
          </li>
        </ul>
      </li>
      <li>
        <b>Unified Messaging Server</b>. &#1076;&#1083;&#1103; &#1080;&#1085;&#1090;&#1077;&#1075;&#1088;&#1072;&#1094;&#1080;&#1080; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1080;&#1080; &#1080; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1057; &#1088;&#1091;&#1089;&#1089;&#1082;&#1080;&#1084; &#1103;&#1079;&#1099;&#1082;&#1086;&#1084; &#1085;&#1077; &#1086;&#1095;&#1077;&#1085;&#1100; &#1076;&#1088;&#1091;&#1075;&#1080;&#1078;&#1090; :)
      </li>
    </ul>
  </body>
</html></richcontent>
