<node TEXT="Транспортные правила" FOLDED="true" ID="ID_1234832068" CREATED="1519112080305" MODIFIED="1519112080305"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1042; Exchange (&#1091; Hub Transport Servers) &#1077;&#1089;&#1090;&#1100; <b>&#1090;&#1088;&#1072;&#1085;&#1089;&#1087;&#1086;&#1088;&#1090;&#1085;&#1099;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;</b>. &#1069;&#1090;&#1086; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; &#1084;&#1086;&#1076;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1074; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; &#1080;&#1093; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1086;&#1090; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091;.
    </p>
    <ul>
      <li>
        &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;
      </li>
      <li>
        &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; <b>&#1074;&#1089;&#1077;&#1084;&#1080;</b>&#160; Hub Transport Servers &#1074; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; Exchange
      </li>
      <li>
        &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1090;&#1088;&#1072;&#1085;&#1089;&#1087;&#1086;&#1088;&#1090;&#1085;&#1099;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1085;&#1072; Edge (<b>&#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084;&#1091; Edge</b>)
      </li>
      <li>
        &#1058;&#1055; &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; ExMC\ OrganizationConf\ Hub Transport\ Transport Rules (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; - &#1080;&#1093; &#1085;&#1077;&#1090;)
      </li>
      <li>
        &#1052;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1058;&#1055;, &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1077;&#1077; &#1083;&#1102;&#1073;&#1099;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082; (&#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1087;&#1080;&#1081;).
      </li>
    </ul>
    <p>
      <b>&#1058;&#1088;&#1072;&#1085;&#1089;&#1087;&#1086;&#1088;&#1090;&#1085;&#1086;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086; &#1089;&#1086;&#1089;&#1090;&#1086;&#1080;&#1090; &#1080;&#1079; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;:</b>
    </p>
    <ul>
      <li>
        <b>&#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; (condition)</b>&#160;- &#1082;&#1072;&#1082;&#1072;&#1103; &#1087;&#1086;&#1095;&#1090;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1076; &#1101;&#1090;&#1086; &#1090;&#1088;&#1072;&#1085;&#1089;&#1087;&#1086;&#1088;&#1090;&#1085;&#1086;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086;. &#1054;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; - &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1077; &#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100;. &#1045;&#1089;&#1083;&#1080; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; &#1085;&#1077; &#1079;&#1072;&#1076;&#1072;&#1085;&#1086;, &#1090;&#1086; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086; &#1074;&#1089;&#1077;&#1084;
      </li>
      <li>
        <b>&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077;&#160;(actions)</b>&#160; - &#1095;&#1090;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1089; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1086;&#1087;&#1072;&#1083;&#1080; &#1087;&#1086;&#1076; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; &#1090;&#1088;&#1072;&#1085;&#1089;&#1087;&#1086;&#1088;&#1090;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;. &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100;, &#1087;&#1077;&#1088;&#1077;&#1089;&#1083;&#1072;&#1090;&#1100;, &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1090;&#1077;&#1084;&#1091;, &#1087;&#1086;&#1085;&#1080;&#1079;&#1080;&#1090;&#1100; &#1088;&#1077;&#1081;&#1090;&#1080;&#1085;&#1075;, &#1079;&#1072;&#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1080; &#1090;.&#1076;.
      </li>
      <li>
        <b>&#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103;</b>&#160;-&#160;
      </li>
    </ul>
    <p>
      
    </p>
  </body>
