    <p>
      <b>&#1050;&#1086;&#1084;&#1084;&#1091;&#1085;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074; &#1087;&#1086;&#1095;&#1090;&#1099;</b>
    </p>
    <ol>
      <li>
        &#1057;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1087;&#1077;&#1088;&#1077;&#1076; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1086;&#1081; &#1087;&#1080;&#1089;&#1084;&#1072;, &#1074;&#1099;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1080;&#1079; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1103; &#1080;&#1084;&#1103; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; gmail.com)
      </li>
      <li>
        &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; DNS-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1080; &#1080;&#1097;&#1077;&#1090; <b>&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1090;&#1080;&#1087;&#1072; &#1052;&#1061;</b>&#160;(mail exchange)
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1085;&#1077; &#1085;&#1072;&#1081;&#1076;&#1077;&#1085;&#1072;, &#1090;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1095;&#1090;&#1086; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1085;&#1077; &#1085;&#1072;&#1081;&#1076;&#1077;&#1085;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1085;&#1072;&#1081;&#1076;&#1077;&#1085;&#1072;, &#1090;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1090; &#1085;&#1072; A-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; (<b>MX-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1085;&#1072; A-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100;</b>), &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;, &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1102;&#1097;&#1077;&#1084;&#1091; &#1079;&#1072; &#1087;&#1088;&#1080;&#1077;&#1084; &#1087;&#1080;&#1089;&#1077;&#1084; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072; (&#1085;&#1072;&#1087;&#1088;. gmail.com).
      </li>
      <li>
        &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;:

        <ol>
          <li>
            <b>TCP-&#1089;&#1077;&#1089;&#1089;&#1080;&#1102;</b>&#160;(&#1085;&#1072; 25 &#1087;&#1086;&#1088;&#1090;) --&gt;
          </li>
          <li>
            <b>SMTP-&#1089;&#1077;&#1089;&#1089;&#1080;&#1102;</b>&#160;(7 &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100;)
          </li>
        </ol>
      </li>
    </ol>
    <p>
      <b>&#1054;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1072; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072;:</b>
    </p>
    <ol>
      <li>
        &#1055;&#1080;&#1089;&#1100;&#1084;&#1086; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090; &#1074; &#1087;&#1072;&#1087;&#1082;&#1091; <b>&#1048;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077;</b>&#160;&#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;
      </li>
      <li>
        <b>&#1053;&#1072; Mailbox</b>&#160;&#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090; <b>Microsoft Exchange Mail Submission service - </b>&#1086;&#1087;&#1086;&#1074;&#1077;&#1097;&#1072;&#1077;&#1090; Hub Transport, &#1095;&#1090;&#1086; &#1077;&#1089;&#1090;&#1100; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1085;&#1072; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1082;&#1091;.
      </li>
      <li>
        &#1053;&#1072; <b>Hub Transport</b>&#160;&#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090; <b>Store Driver </b>- &#1079;&#1072;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1080;&#1079; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1103;&#1097;&#1080;&#1082;&#1072; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1042; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1084; &#1103;&#1097;&#1080;&#1082;&#1077; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1089;&#1103; &#1080;&#1079; &#1048;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1074; &#1054;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077;.
      </li>
      <li>
        &#1055;&#1086;&#1082;&#1072; Hub Transport &#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1082; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1077; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; <b>Submission queue</b>&#160;&#160;(&#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; <font color="#0000c0">Get-Queue</font>). &#1069;&#1090;&#1086; &#1073;&#1072;&#1079;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; (&#1076;&#1074;&#1080;&#1078;&#1077;&#1085;&#1080;&#1077; FIFO). &#1057; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100;&#1102; &#1091;&#1076;&#1086;&#1073;&#1085;&#1077;&#1081; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; Toolbox\ <b>Queue Viewer</b>
      </li>
      <li>
        &#1050;&#1072;&#1082; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1086;&#1076;&#1086;&#1096;&#1083;&#1072; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072;, <b>&#1085;&#1072; Hub Transport</b>&#160;&#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090; <b>Categorizer</b>&#160;(&#1050;&#1072;&#1090;&#1077;&#1075;&#1086;&#1088;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;) - &#1073;&#1077;&#1088;&#1077;&#1090; &#1087;&#1086;-&#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086;, &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090; &#1076;&#1083;&#1103; &#1082;&#1086;&#1075;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; (&#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1080;&#1083;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1081; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;), &#1082;&#1072;&#1082; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100;, &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1074;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103;. &#1050;&#1072;&#1082; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085;&#1086; &#1080; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;, &#1090;&#1086; <b>&#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; SMTP &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1080; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103;</b>.
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; <b>SMTP &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;</b>&#160;&#1085;&#1077; &#1091;&#1076;&#1072;&#1083;&#1086;&#1089;&#1100;, &#1090;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081;, &#1095;&#1077;&#1088;&#1077;&#1079; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; -&gt; <b>&#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1072;&#1103; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1082;&#1072;</b>.
      </li>
    </ol>
  </body>
</html></richcontent>
