<node TEXT="Message Records Management" ID="ID_781223529" CREATED="1519112080306" MODIFIED="1519112080306"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1053;&#1091;&#1078;&#1085;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072; &#1089;&#1072;&#1084;&#1080; &#1084;&#1086;&#1075;&#1083;&#1080; &#1091;&#1076;&#1072;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103;, &#1087;&#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1072;&#1083;&#1080;&#1089;&#1100; &#1074; &#1072;&#1088;&#1093;&#1080;&#1074;&#1085;&#1099;&#1081; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082;.</b>
    </p>
    <p>
      
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; <b>MRM </b>v2 (<b>Message Records Management</b>&#160;- &#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1099;&#1084; &#1103;&#1097;&#1080;&#1082;&#1072;).
    </p>
    <p>
      <b>&#1058;&#1101;&#1075;&#1080;</b>&#160;(3&#1093; &#1074;&#1080;&#1076;&#1086;&#1074;). &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1090;&#1101;&#1075; &#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090; &#1080; &#1095;&#1090;&#1086; &#1089; &#1085;&#1080;&#1084; &#1087;&#1086;&#1090;&#1086;&#1084; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100;.
    </p>
    <ul>
      <li>
        <b>&#1058;&#1101;&#1075; &#1087;&#1072;&#1087;&#1082;&#1080;</b>&#160;- &#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1087;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1077; &#1074; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1081; &#1087;&#1072;&#1087;&#1082;&#1077;, &#1075;&#1086;&#1074;&#1086;&#1088;&#1080;&#1090; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090; &#1074; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1081; &#1087;&#1072;&#1087;&#1082;&#1077;. &#1051;&#1080;&#1073;&#1086; &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; &#1042;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077;, &#1083;&#1080;&#1073;&#1086; &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; &#1054;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077;, &#1083;&#1080;&#1073;&#1086; &#1074; &#1050;&#1086;&#1088;&#1079;&#1080;&#1085;&#1077;
      </li>
      <li>
        <b>&#1058;&#1101;&#1075; &#1103;&#1097;&#1080;&#1082;&#1072;</b>&#160;- &#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1087;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;&#1072; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1087;&#1072;&#1087;&#1086;&#1082; &#1103;&#1097;&#1080;&#1082;&#1072;, &#1076;&#1083;&#1103; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1085;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1099; &#1087;&#1077;&#1088;&#1089;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1090;&#1101;&#1075;&#1080; (&#1090;&#1101;&#1075;&#1080; &#1087;&#1072;&#1087;&#1082;&#1080;)
      </li>
      <li>
        <b>&#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1081; &#1090;&#1101;&#1075;</b>&#160;- &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1081; &#1090;&#1101;&#1075; &#1085;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1085;&#1080; &#1082; &#1095;&#1077;&#1084;&#1091;. &#1069;&#1090;&#1086; &#1090;&#1086;&#1090; &#1090;&#1077;&#1075;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1085;&#1072; &#1087;&#1072;&#1087;&#1082;&#1091;.
      </li>
    </ul>
    <p>
      <b>&#1063;&#1090;&#1086;&#1073;&#1099; &#1090;&#1101;&#1075;&#1080; &#1085;&#1072;&#1095;&#1072;&#1083;&#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100;</b>&#160;- &#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; <b>&#1055;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091; &#1090;&#1101;&#1075;&#1086;&#1074; (Tag Policy)</b>. &#1055;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091; &#1090;&#1101;&#1075;&#1086;&#1074; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1082; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084;&#1091; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1084;&#1091; &#1103;&#1097;&#1080;&#1082;&#1091;.
    </p>
    <ul>
      <li>
        &#1076;&#1086; Ex2010 (&#1073;&#1077;&#1079; SP1) - &#1074;&#1089;&#1077; &#1090;&#1101;&#1075;&#1080; &#1080; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091; &#1090;&#1101;&#1075;&#1086;&#1074; &#1087;&#1088;&#1080;&#1076;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; <b>&#1095;&#1077;&#1088;&#1077;&#1079; Shell</b>
      </li>
      <li>
        &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; <b>Ex2010SP1</b>&#160;- &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1074; <b>GUI</b>. ExMC\ OrgConf\ Mailbox\ <b>Retention Policy Tags</b>
      </li>
    </ul>
    <p>
      <b>&#1056;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1077;&#1084;</b>. &#1057;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; &#1080; &#1090;&#1101;&#1075;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1073;&#1080;&#1090;&#1100;.
    </p>
    <p>
      <b>1.1 &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1090;&#1101;&#1075; &quot;&#1050;&#1086;&#1088;&#1079;&#1080;&#1085;&#1072;&#160;(&#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1072; &#1082;&#1086;&#1085;&#1079;&#1080;&#1085;&#1099; - 7 &#1076;&#1085;&#1077;&#1081;)&quot;. </b>ExMC\ OrgConf\ Mailbox\ Retention Policy Tags
    </p>
    <p>
      New Retention Policy Tag &gt; Tag Type: <b>Deleted Item</b>&#160;&gt; Age limit for retention: <b>7</b>&#160;&gt; Action to take when the age limit is reached: <b>Permanently Delete</b>&#160;&gt; Finish
    </p>
    <p>
      <b>1.2 &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1090;&#1101;&#1075; &quot;&#1071;&#1097;&#1080;&#1082; (30 &#1076;&#1085;&#1077;&#1081; &#1080; &#1074; &#1072;&#1088;&#1093;&#1080;&#1074;)&quot;</b>
    </p>
    <p>
      New Retention Policy Tag &gt; Tag Type: <b>All other folders in the mailbox</b>&#160;&gt; Age limit for retention: <b>30</b>&#160;&gt; Action to take when the age limit is reached: <b>Move to Archive</b>&#160;&gt; Finish
    </p>
    <p>
      <b>1.3 &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1090;&#1101;&#1075; &quot;&#1053;&#1077; &#1091;&#1076;&#1072;&#1083;&#1103;&#1090;&#1100;&quot;</b>. &#1053;&#1077; &#1091;&#1076;&#1072;&#1083;&#1103;&#1090;&#1100; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1085;&#1085;&#1099;&#1077; &#1087;&#1072;&#1087;&#1082;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
    </p>
    <p>
      New Retention Policy Tag &gt; Tag Type: <b>Personal Folder</b>&#160;&gt; Age limit for retention: <b>24855</b>&#160;&gt; Action to take when the age limit is reached: <b>Move to Archive</b>&#160;&gt; Finish
    </p>
    <p>
      <b>2. &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102; &#1072;&#1088;&#1093;&#1080;&#1074;&#1085;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082;.</b>&#160;ExMC\ RecipientConf\ Mailbox\ MyUser &gt; Enable Archive \ Create a local archive\ Select a specific mailbox database rather than having one selected automatically
    </p>
    <p>
      <b>3. &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1085;&#1086;&#1074;&#1091;&#1102; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091;.</b>&#160;ExMC\ OrgConf\ Mailbox\ <b>Retention Policies</b>&#160;&gt; New Retention Policy... &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1090;&#1101;&#1075;&#1080; &#1080; &#1103;&#1097;&#1080;&#1082;.
    </p>
    <p>
      <b>4. &#1063;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072; &#1086;&#1090;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1083;&#1072; &#1089;&#1088;&#1072;&#1079;&#1091;</b>&#160;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; &#1095;&#1077;&#1088;&#1077;&#1079; Shell: <font color="#0000c0">Start-ManagedFolderAssistant -Identity &lt;&#1048;&#1084;&#1103;&#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&gt; </font>
    </p>
    <p>
      <font color="#000000"><b>5. &#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;</b>&#160;&#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; <b>&#1095;&#1077;&#1088;&#1077;&#1079; OWA</b>&#160;&#1084;&#1086;&#1078;&#1077;&#1090; &#1076;&#1083;&#1103; &#1087;&#1072;&#1087;&#1082;&#1080; (&#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1085;&#1086;&#1077; &#1084;&#1077;&#1085;&#1102;) <b>&#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091;</b>. </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#ff0000">&#1063;&#1090;&#1086;&#1073;&#1099; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1083;&#1086;&#1089;&#1100; &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; &#1085;&#1091;&#1078;&#1085;&#1086; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; (&#1082;&#1086;&#1089;&#1090;&#1099;&#1083;&#1100;) &#1089; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077;&#1084; &#1077;&#1075;&#1086; &#1088;&#1072;&#1079; &#1074; &#1076;&#1077;&#1085;&#1100;. </font>
    </p>
    <p>
      <font color="#ff0000">Get-Mailbox | Set-Mailbox -RetentionPolicy (&#1073;&#1083;&#1072;-&#1073;&#1083;&#1072;-&#1073;&#1083;&#1072; - &#1085;&#1077;&#1087;&#1086;&#1085;&#1103;&#1090;&#1085;&#1086;????)</font>
