  <head>
    
  </head>
  <body>
    <p>
      1. &#1044;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1087;&#1080;&#1089;&#1082;&#1080; <b>&#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; </b>&#1074; DNS &#1085;&#1080;&#1082;&#1072;&#1082;&#1080;&#1077; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077; &#1074;&#1085;&#1086;&#1089;&#1103;&#1090;&#1089;&#1103;.
    </p>
    <p>
      2. &#1045;&#1089;&#1083;&#1080; &#1093;&#1086;&#1090;&#1080;&#1084; &#1085;&#1086;&#1088;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086; &#1087;&#1080;&#1089;&#1072;&#1090;&#1100;, &#1090;&#1086; <b>&#1074;&#1085;&#1086;&#1089;&#1080;&#1084; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074; DNS (&#1074;&#1085;&#1077;&#1096;&#1085;&#1102;&#1102; &#1079;&#1086;&#1085;&#1091;)</b>
    </p>
    <ol>
      <li>
        <b>&#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; MX-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100;</b>&#160;&#1074;&#1086; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1079;&#1086;&#1085;&#1077;. &#1054;&#1085;&#1072; &#1075;&#1086;&#1074;&#1086;&#1088;&#1080;&#1090; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1084;, &#1095;&#1090;&#1086; &#1077;&#1089;&#1083;&#1080; &#1086;&#1085;&#1080; &#1093;&#1086;&#1090;&#1103;&#1090; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1087;&#1086;&#1095;&#1090;&#1091; &#1085;&#1072; &#1082;&#1072;&#1082;&#1086;&#1081;-&#1090;&#1086; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1076;&#1086;&#1084;&#1077;&#1085; - &#1082;&#1091;&#1076;&#1072; &#1077;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1082;&#1080;&#1076;&#1072;&#1090;&#1100;:

        <ol>
          <li>
            <b>&#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1090;&#1080;&#1087;&#1072; A</b>&#160; &#1085;&#1072; IP &#1072;&#1076;&#1088;&#1077;&#1089; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
          </li>
          <li>
            <b>&#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; MX &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;</b>&#160; &#1085;&#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1095;&#1090;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;
          </li>
          <li>
            &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084;:

            <ul>
              <li>
                <font color="#0000c0">nslookup </font>
              </li>
              <li>
                <font color="#0000c0">set q=mx </font><font color="#000000"># &#1074;&#1099;&#1074;&#1086;&#1076; MX-&#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; </font>
              </li>
              <li>
                <font color="#0000c0">MyDomain.com</font>
              </li>
            </ul>
          </li>
        </ol>
      </li>
      <li>
        <b>&#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; PTR-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100;&#160;(&#1086;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;)</b>. &#1050;&#1086;&#1075;&#1076;&#1072; IP &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1080;&#1084;&#1103;. &#1069;&#1090;&#1072; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1085;&#1091;&#1078;&#1085;&#1072; &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1095;&#1090;&#1091; &#1086;&#1090; &#1085;&#1072;&#1089; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1080; &#1073;&#1077;&#1079; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;. &#1054;&#1076;&#1085;&#1072; &#1080;&#1079; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1086;&#1082; &#1085;&#1072; &#1072;&#1085;&#1090;&#1080;&#1089;&#1087;&#1072;&#1084; &#1079;&#1072;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1077; PTR-&#1079;&#1072;&#1087;&#1080;&#1089;&#1080;. &#1044;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; <b>&#1087;&#1080;&#1096;&#1077;&#1084; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1091; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &quot;&#1055;&#1088;&#1086;&#1096;&#1091; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; PTR IP &lt;&#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; &#1085;&#1072;&#1096; IP&gt; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1080;&#1084;&#1103; &lt;mail.MyDomain.com&gt;&quot;</b>
      </li>
      <li>
        <b>&#1053;&#1091;&#1078;&#1085;&#1072; SPF-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; (Sender Policy Framework) (&#1086;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;)</b>. &#1045;&#1089;&#1090;&#1100; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1072; - &#1083;&#1102;&#1073;&#1086;&#1081; &#1078;&#1077;&#1083;&#1072;&#1102;&#1097;&#1080;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1086;&#1090; &#1080;&#1084;&#1077;&#1085;&#1080; &#1083;&#1102;&#1073;&#1086;&#1075;&#1086; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091;, &#1077;&#1089;&#1083;&#1080; &#1084;&#1099; &#1085;&#1077; &#1093;&#1086;&#1090;&#1080;&#1084;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1082;&#1090;&#1086;-&#1090;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1083; &#1087;&#1086;&#1095;&#1090;&#1091; &#1086;&#1090; &#1080;&#1084;&#1077;&#1085;&#1080; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;, &#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; SPF-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; (&#1082;&#1072;&#1082; &#1084;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084;). SPF-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1076;&#1086;&#1073;&#1072;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1089;&#1074;&#1086;&#1102; &#1074;&#1085;&#1077;&#1096;&#1102;&#1102; &#1079;&#1086;&#1085;&#1091;. SPF-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1075;&#1086;&#1074;&#1086;&#1088;&#1080;&#1090; &#1086; &#1090;&#1086;&#1084;, &#1082;&#1090;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1088;&#1072;&#1089;&#1089;&#1099;&#1083;&#1072;&#1090;&#1100; &#1087;&#1086;&#1095;&#1090;&#1091; &#1086;&#1090; &#1080;&#1084;&#1077;&#1085;&#1080; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;. &#1055;&#1088;&#1080;&#1085;&#1080;&#1084;&#1102;&#1097;&#1072;&#1103; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1072; &#1087;&#1086;&#1083;&#1077;&#1079;&#1077;&#1090; &#1074; DNS, &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1080;&#1090; SPF-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1077;&#1089;&#1083;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1088;&#1072;&#1079;&#1085;&#1086;&#1095;&#1090;&#1077;&#1085;&#1080;&#1103;, &#1090;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1080;&#1085;&#1103;&#1090;&#1086;.
      </li>
