<node TEXT="Топологии" ID="ID_1296102654" CREATED="1519112080308" MODIFIED="1519112080308"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Small Organization.</b>&#160;&#1057;&#1072;&#1084;&#1072;&#1103; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1077;&#1085;&#1085;&#1072;&#1103; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103;. &#1042;&#1089;&#1105; &#1086;&#1076;&#1085;&#1086;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;, &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1103; &#1072;&#1085;&#1090;&#1080;&#1089;&#1087;&#1072;&#1084;:
    </p>
    <ul>
      <li>
        Mailbox Server
      </li>
      <li>
        Client Access Server
      </li>
      <li>
        Hub Transport Server
      </li>
    </ul>
    <p>
      <b>Medium-Size Organization. &#1051;&#1080;&#1073;&#1086; 2 &#1083;&#1080;&#1073;&#1086; 4 &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. </b>
    </p>
    <p>
      <b>2 &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;: </b>
    </p>
    <ul>
      <li>
        &#1087;&#1086;&#1083;&#1085;&#1099;&#1081; &#1085;&#1072;&#1073;&#1086;&#1088; &#1088;&#1086;&#1083;&#1077;&#1081; &#1085;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;. &#1047;&#1072; &#1089;&#1095;&#1077;&#1090; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1085;&#1086;&#1075;&#1086; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1097;&#1080;&#1082;&#1072; &#1080; &#1089;&#1083;&#1091;&#1078;&#1073; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; Windows &#1080; Exchange &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1091;&#1102; &#1089;&#1093;&#1077;&#1084;&#1091;
      </li>
      <li>
        &#1088;&#1077;&#1076;&#1082;&#1086; &#1074; &#1044;&#1052;&#1047; (&#1076;&#1077;&#1084;&#1080;&#1083;&#1080;&#1090;&#1072;&#1088;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1077;) &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; Edge Transport Server. &#1056;&#1086;&#1076;&#1085;&#1086;&#1081; &#1072;&#1085;&#1090;&#1080;&#1089;&#1087;&#1072;&#1084; &#1091; Edge &#1076;&#1077;&#1088;&#1100;&#1084;&#1086;&#1074;&#1099;&#1081; &#1080; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; Microsoft Forefront Protection &#1080;&#1083;&#1080; ORF, &#1050;&#1072;&#1089;&#1087;&#1077;&#1088;&#1089;&#1082;&#1080;&#1081; - &#1072; &#1101;&#1090;&#1086; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1099;
      </li>
      <li>
        &#1079;&#1072;&#1095;&#1072;&#1089;&#1090;&#1091;&#1102; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1089;&#1090;&#1086;&#1080;&#1090; <b>Exchange</b>&#160;&#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077; + &#1089;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080; (&#1074; &#1044;&#1052;&#1047;) <b>Sendmail</b>&#160;(&#1088;&#1077;&#1083;&#1101;&#1081; - &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1091;&#1077;&#1090; &#1085;&#1072; &#1089;&#1087;&#1072;&#1084;)
      </li>
    </ul>
    <p>
      <b>Large Organization</b>
    </p>
    <ul>
      <li>
        2 &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1089; Mailbox Server (&#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077;) + 1 &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; Client Access + 1 &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; Hub Transport
      </li>
    </ul>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
