    </p>
    <p>
      
    </p>
    <p>
      &#1047;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; &#1080;&#1079; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1089; &#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1080;&#1074;&#1072;:
    </p>
    <p>
      <font color="#0000c0">Setup.com /PrepareLegacy ExchangePermissions </font><font color="#000000"># &#1045;&#1089;&#1083;&#1080; &#1074; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; Exchange 2003 </font>
    </p>
    <p>
      <font color="#0000c0">Setup.com /PrepareSchema </font><font color="#000000"># &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1085;&#1072;&#1073;&#1086;&#1088; &#1085;&#1086;&#1074;&#1099;&#1093; &#1082;&#1083;&#1072;&#1089;&#1089;&#1086;&#1074; &#1080; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1086;&#1074; &#1074; AD </font>
    </p>
    <p>
      <font color="#0000c0">Setup.com /PrepareAD /OrganizationName: &quot;MyOrganization&quot; </font><font color="#000000"># &#1074; AD &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103;: </font><font color="#ff0000">&#1060;&#1072;&#1081;&#1083;&#1099; &#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1077;&#1090;, &#1085;&#1086; &#1079;&#1072;&#1090;&#1077;&#1084; &#1074;&#1099;&#1076;&#1072;&#1077;&#1090; &#1086;&#1096;&#1080;&#1073;&#1082;&#1091; The specified value Contoso.com is not a valid organization name.</font>
    </p>
    <ul>
