        <font color="#000000">OU &#1089; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; Microsoft Exchange Security Group</font>
      </li>
      <li>
        <font color="#000000">&#1075;&#1088;&#1091;&#1087;&#1087;&#1099;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; Exchange</font>
      </li>
      <li>
        &#1074; Configuration &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1077;&#1090;&#1082;&#1072;, &#1082;&#1091;&#1076;&#1072; &#1087;&#1086;&#1084;&#1077;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1077;&#1092;&#1086;&#1083;&#1090;&#1085;&#1099;&#1081; config &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;
      </li>
    </ul>
    <p>
      <b>&#1045;&#1089;&#1083;&#1080; &#1091; &#1085;&#1072;&#1089; 1 &#1076;&#1086;&#1084;&#1077;&#1085; &#1080; &#1087;&#1088;&#1072;&#1074;&#1072; Enterprise admin, &#1090;&#1086; &#1085;&#1072; &#1101;&#1090;&#1086;&#1084; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103;.</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1045;&#1089;&#1083;&#1080; &#1076;&#1086;&#1084;&#1077;&#1085;&#1086;&#1074; &#1084;&#1085;&#1086;&#1075;&#1086;</b>&#160;&#1080; &#1084;&#1099; &#1085;&#1077; Enterprise admin, &#1090;&#1086; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; &#1074; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1076;&#1086;&#1084;&#1077;&#1085;&#1077;, &#1075;&#1076;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1080; Exchange: <font color="#0000c0">Setup.com /PrepareDomain</font>
