  <body>
    <p>
      <b>Edge Transport Server</b>.&#160;&#160;&#1042;&#1089;&#1077;&#1075;&#1076;&#1072; &#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1089;&#1103; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086; &#1086;&#1090; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1088;&#1086;&#1083;&#1077;&#1081; Exchange. &#1069;&#1090;&#1072; &#1088;&#1086;&#1083;&#1100; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; AD.
    </p>
    <ol>
      <li>
        &#1041;&#1077;&#1088;&#1077;&#1084; <b>&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1085;&#1077; &#1103;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081;&#1089;&#1103; &#1095;&#1083;&#1077;&#1085;&#1086;&#1084; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;</b>. &#1042; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1077;.
      </li>
      <li>
        &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1080;&#1084;&#1077;&#1090;&#1100; <b>DNS &#1089;&#1091;&#1092;&#1092;&#1080;&#1082;&#1089;</b>&#160;(&#1080;&#1084;&#1103; AD), &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; MyDomain.com. &#1044;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1086;&#1088;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1083;&#1086; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1080;&#1084;&#1077;&#1085;.
      </li>
      <li>
        &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; <b>&#1088;&#1086;&#1083;&#1100; AD LDS</b>&#160;(&#1083;&#1077;&#1075;&#1082;&#1086;&#1074;&#1077;&#1089;&#1085;&#1072;&#1103; &#1089;&#1083;&#1091;&#1078;&#1073;&#1072; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;). &#1047;&#1076;&#1077;&#1089;&#1100; Edge &#1073;&#1091;&#1076;&#1077;&#1090; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1089;&#1074;&#1086;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;. &#1041;&#1091;&#1076;&#1091;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1099; 3 &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1072;:

        <ul>
          <li>
            Schema information
          </li>
          <li>
            Configuration information
          </li>
          <li>
            Recipient information
          </li>
        </ul>
      </li>
      <li>
        Edge &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1086;&#1076;&#1080;&#1085; &#1089;&#1072;&#1081;&#1090; AD, &#1085;&#1086; &#1085;&#1072; &#1086;&#1076;&#1080;&#1085; &#1089;&#1072;&#1081;&#1090; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1091;&#1075;&#1086;&#1076;&#1085;&#1086; Edge (&#1076;&#1083;&#1103; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1080;). &#1055;&#1088;&#1080; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1080;, &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;:

        <ul>
          <li>
            &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1099; &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1082;&#1080; &#1087;&#1086;&#1095;&#1090;&#1099;
          </li>
          <li>
            &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1077;&#1084;&#1099;&#1093; &#1076;&#1086;&#1084;&#1077;&#1085;&#1086;&#1074;
          </li>
          <li>
            &#1085;&#1072; Edge &#1087;&#1086;&#1076;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1103;&#1093;.
          </li>
        </ul>
      </li>
      <li>
        <font color="#0000c0">Get-SendConnector</font><font color="#000000">&#160;&gt; </font><font color="#0000c0">Get-AcceptedDomain</font>, &#1091; &#1085;&#1072;&#1089; &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1085;&#1072; Edge &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080;, &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1077;&#1084;&#1099;&#1093; &#1076;&#1086;&#1084;&#1077;&#1085;&#1086;&#1074;.
      </li>
      <li>
        Edge &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1085;&#1072; &#1089;&#1072;&#1081;&#1090; AD:<br/>

        <ol>
          <li>
            <font color="#0000c0">New-EdgeSubscription -FileName &lt;C:\1.xml&gt;</font>&#160;# &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084; &#1092;&#1072;&#1081;&#1083; &#1087;&#1088;&#1080;&#1075;&#1088;&#1072;&#1096;&#1077;&#1085;&#1080;&#1103;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1074;&#1099;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085;&#1072; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1086;&#1073; Edge<br/>
          </li>
          <li>
            &#1087;&#1077;&#1088;&#1077;&#1085;&#1086;&#1089;&#1080;&#1084; &#1092;&#1072;&#1081;&#1083; &#1087;&#1088;&#1080;&#1075;&#1083;&#1072;&#1096;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1086;&#1076;&#1080;&#1085; &#1080;&#1079; Hub Transport &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074; &#1090;&#1086;&#1075;&#1086; &#1089;&#1072;&#1081;&#1090;&#1072; AD, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1084; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100; Edge.
          </li>
          <li>
            Ex Server\ ExMC\ Organization Configuration\ Hub Transport\ Edge Subscription &gt; New Edge Subscription &gt; Active Directory site\ Browse\ &lt;&#1089;&#1072;&#1081;&#1090;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1082;&#1072;&gt; &gt; Subscription file\ Browse &lt;&#1092;&#1072;&#1081;&#1083; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1082;&#1080; &#1087;&#1088;&#1080;&#1075;&#1083;&#1072;&#1096;&#1077;&#1085;&#1080;&#1077;&gt; &gt; New &gt; Finish
          </li>
          <li>
            &#1042; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1087;&#1086;&#1081;&#1090;&#1080; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103;.
          </li>
          <li>
            <font color="#0000c0">Get-SendConnector</font><font color="#000000">&#160;&gt; </font><font color="#0000c0">Get-AcceptedDomain</font><font color="#000000">&#160;# </font><font color="#ff0000">&#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1080;&#1085;&#1092;&#1072;, &#1091; &#1084;&#1077;&#1085;&#1103; &#1086;&#1085;&#1072; &#1085;&#1077; &#1074;&#1099;&#1096;&#1083;&#1072;&#160;&#160;:( </font>
          </li>
        </ol>
      </li>
      <li>
        Hub Transport &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090; &#1074; &#1086;&#1076;&#1085;&#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1077;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1085;&#1072; Edge. &#1053;&#1072; Edge &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1077;&#1084;&#1086;&#1075;&#1086; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;.<br/>&#1059;&#1089;&#1082;&#1086;&#1088;&#1080;&#1090;&#1100; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102;: ExServer &gt; <font color="#0000c0">Start-EdgeSynchronization</font>&#160;- <font color="#ff0000">&#1085;&#1077;&#1075;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1086;&#1090;&#1074;&#1077;&#1090; (&#1085;&#1077;&#1090; &#1089;&#1074;&#1103;&#1079;&#1080;), &#1085;&#1091;&#1078;&#1085;&#1086; &#1090;&#1088;&#1072;&#1073;&#1083;&#1096;&#1091;&#1090;&#1080;&#1090;&#1100;</font>
      </li>
      <li>
        <font color="#0000c0">Get-EdgeSyncServiceConfig</font>&#160;| fl # &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; edge (&#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; Ex)
      </li>
      <li>
        
      </li>
      <li>
        
      </li>
      <li>
        
      </li>
      <li>
        C&#1077;&#1088;&#1074;&#1077;&#1088; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1080;&#1084;&#1077;&#1090;&#1100; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1090;&#1100; &#1080;&#1084;&#1077;&#1085;&#1072; &#1074; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1080; &#1089;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080;. &#1053;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084; Edge &#1085;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1075;&#1086; DNS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
      </li>
    </ol>
    <p>
      <b>&#1054;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1084; &#1074;&#1089;&#1077;&#1075;&#1086; 3 &#1087;&#1086;&#1088;&#1090;&#1072; &#1074;&#1086; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1102;&#1102; &#1089;&#1077;&#1090;&#1100; &#1080; 2 &#1085;&#1072;&#1088;&#1091;&#1078;&#1091;:</b>
    </p>
    <ul>
      <li>
        <b>25 (tcp)</b>&#160;- &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1087;&#1086;&#1095;&#1090;&#1099;
      </li>
      <li>
        <b>53 (tcp\udp) </b>- &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1080;&#1084;&#1077;&#1085;
      </li>
      <li>
        50636 - &#1076;&#1083;&#1103; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1089; Hub transport Server. &#1054;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1086;&#1076;&#1085;&#1086;&#1084; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; - &#1085;&#1072;&#1088;&#1091;&#1078;&#1091; &#1080;&#1079; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;
      </li>
