  <body>
    <p>
      <b>&#1056;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1080; Mailbox. DAG</b>&#160;(<b>Database Availability Group)</b>.
    </p>
    <ol>
      <li>
        ExMC\ Organization Configuration\ Mailbox\ Database Availability Group &gt; <b>New Database Availability Group...</b>
      </li>
      <li>
        <b>Witness Server</b>, <b>Witness Directory</b>&#160;- &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080; &#1087;&#1072;&#1087;&#1082;&#1072;, &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1090;&#1088;&#1077;&#1090;&#1100;&#1080;&#1084; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1084;, &#1089;&#1074;&#1080;&#1076;&#1077;&#1090;&#1077;&#1083;&#1077;&#1084; (&#1076;&#1083;&#1103; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1084;&#1072;&#1096;&#1080;&#1085;) - &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; DC &gt; C:\Witness
      </li>
      <li>
        &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; <b>Exchange Trusted Subsystem</b>&#160;&#1074; <b>Local Administrators groups</b>&#160;&#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;, &#1103;&#1074;&#1083;&#1103;&#1102;&#1097;&#1077;&#1084;&#1089;&#1103; &#1089;&#1074;&#1080;&#1076;&#1077;&#1090;&#1077;&#1083;&#1077;&#1084; (<font color="#ff0000">&#1085;&#1077; &#1079;&#1072;&#1073;&#1099;&#1074;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086; &#1101;&#1090;&#1086;</font>).
      </li>
      <li>
        &#1053;&#1091;&#1078;&#1085;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1083;&#1091;&#1078;&#1077;&#1073;&#1085;&#1099;&#1081; IP (&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1084;&#1080; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; DAG). &#1047;&#1072;&#1093;&#1086;&#1076;&#1080;&#1084; &#1074; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; DAG\ IP Addresses &gt; &#1079;&#1072;&#1076;&#1072;&#1077;&#1084; &#1083;&#1102;&#1073;&#1086;&#1081; &#1089;&#1074;&#1086;&#1073;&#1086;&#1076;&#1085;&#1099;&#1081; IP
      </li>
      <li>
        &#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; DAG. MyDAG &gt; Manage Database Availability Group Membership &gt; Add
      </li>
      <li>
        <b>&#1042;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084;</b>&#160;&#1082;&#1072;&#1082;&#1091;&#1102; <b>DB Mailbox</b>&#160;&#1073;&#1091;&#1076;&#1077;&#1084; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1080;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;. ExMC\ Organization Configuration\ Mailbox\ Database Management\ MyDB &gt; Add Mailbox Database Copy... &#1050;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1080;&#1079;&#1091;&#1077;&#1090; &#1073;&#1072;&#1079;&#1091; &#1087;&#1086; &#1090;&#1077;&#1084; &#1078;&#1077; &#1087;&#1091;&#1090;&#1103;&#1084; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, D:\Base)
      </li>
      <li>
        <b>&#1055;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1086;&#1087;&#1080;&#1103;&#1084;&#1080;</b>&#160; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; ExMC\ Organization Configuration\ Mailbox\ Database Management\ MyDB\ Database Copies
