<node TEXT="Развертывание CAS Array" ID="ID_203344120" CREATED="1519112080310" MODIFIED="1519112080310" LINK="#ID_1872960476"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; client access array &#1076;&#1083;&#1103; mail.contoso.com (FQDN), EXMC &gt;:
    </p>
    <ol>
      <li>
        &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; CAS (Client Access Server) &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1087;&#1072;&#1083;&#1080; &#1074;&#1089;&#1077; CAS &#1074; &#1085;&#1072;&#1096;&#1077;&#1084; &#1089;&#1072;&#1081;&#1090;&#1077;:<br/><font color="#0000c0">New-ClientAccessArray -FQDN &lt;&#1048;&#1084;&#1103;&#1052;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;-mail.contoso.com&gt; -Site &quot;&#1057;&#1072;&#1081;&#1090;&#1042;&#1050;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084;&#1054;&#1085;&#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; - &#1073;&#1077;&#1088;&#1077;&#1084; &#1080;&#1079; ADSS&quot; -Name &quot;mail.contoso.com&quot;</font><br/>
      </li>
      <li>
        <font color="#000000">&#1055;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1101;&#1090;&#1086;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1076;&#1083;&#1103; Mailbox DB:</font><br/><font color="#0000c0">Set-MailboxDatabase &quot;MyDB&quot; -RpcClientAccessServer &quot;mail.contoso.com&quot;</font>
      </li>
      <li>
        <font color="#000000">&#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; </font><font color="#0000c0">Get-MailboxDatabase &quot;MyDB&quot; | fl *rpc*</font>
      </li>
      <li>
        &#1048;&#1084;&#1103; <b>mail.contoso.com</b>&#160;&#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; <b>IP &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1097;&#1080;&#1082;&#1072;</b>, &#1072; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1097;&#1080;&#1082; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1084;&#1077;&#1078;&#1076;&#1091; CAS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1084;&#1080;.
