<node TEXT="Troubleshooting" FOLDED="true" ID="ID_1998075558" CREATED="1519112080310" MODIFIED="1526376251531"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. &#1054;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; (&#1087;&#1088;&#1086;&#1075;&#1088;&#1077;&#1074;).</b>
    </p>
    <ol>
      <li>
        &#1053;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1087;&#1086;&#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1099;, &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;&#1099;&#1077; Microsoft Excange... &#1077;&#1089;&#1083;&#1080; &#1095;&#1072;&#1089;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1086;&#1074; &#1085;&#1077; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;&#1086;, &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1077; &#1093;&#1074;&#1072;&#1090;&#1072;&#1077;&#1090; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;
      </li>
      <li>
        <b>Exchange Management Shell</b>&#160;&gt; <font color="#0000c0">Test-ServiceHealth</font>&#160;&gt; &#1055;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;&#1085;&#1099;&#1077; &#1089;&#1083;&#1091;&#1078;&#1073;&#1099; &#1089;&#1086; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1072;&#1084;&#1080; &gt; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1074;&#1089;&#1077; &#1089;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; <b>RequiredServicesRunning: True</b>
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; <b>RequiredServicesRunning: False</b>&#160;&gt; C&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1074; ServiceNotRunning &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1085;&#1077;&#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;&#1085;&#1086;&#1081; &#1089;&#1083;&#1091;&#1078;&#1073;&#1099; &gt; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; &#1077;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; EMS (Exchange Management Shell) &gt;<br/><font color="#0000c0">Start-Service &lt;MSExchangeProtectedServiceHost&gt; </font>
      </li>
    </ol>
    <p>
      <b>2. &#1055;&#1088;&#1080;&#1089;&#1090;&#1077;&#1075;&#1085;&#1077;&#1084; &#1088;&#1077;&#1084;&#1085;&#1080;.</b>
    </p>
    <ol>
      <li>
        &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1074; AD &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; <b>test</b>&#160;&gt;
      </li>
      <li>
        &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; <b>test</b>&#160;&#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082; &gt; EMS &gt; <font color="#0000c0">Enable-Mailbox test</font>
      </li>
      <li>
        <font color="#0000c0">Get-Mailbox test</font>&#160;- &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1103;&#1097;&#1080;&#1082;&#1072; <b>test</b>
      </li>
      <li>
        &#1047;&#1072;&#1093;&#1086;&#1076;&#1080;&#1084; &#1085;&#1072; Outlook Web App (OWA): IE &gt; <font color="#0000c0">https://MyExServer.contoso.com/owa</font>

        <ol>
          <li>
            &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; Inbox - <b>Mailbox &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;</b>
          </li>
          <li>
            &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1089;&#1072;&#1084;&#1080; &#1089;&#1077;&#1073;&#1077;, &#1076;&#1086;&#1096;&#1083;&#1086; - <b>Hub Transport &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;</b>
          </li>
        </ol>
      </li>
    </ol>
    <p>
      <b>3. &#1045;&#1089;&#1083;&#1080; &#1095;&#1090;&#1086;-&#1090;&#1086; &#1087;&#1086;&#1096;&#1083;&#1086; &#1085;&#1077; &#1090;&#1072;&#1082; </b>(&#1089; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1086;&#1081; &#1080;&#1083;&#1080; &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;), &#1090;&#1086; &#1085;&#1072; &#1076;&#1080;&#1089;&#1082;&#1077; &#1077;&#1089;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; C:\ExchangeSetupLogs\<b>ExchangeSetup.log</b>&#160;- &#1087;&#1086;&#1080;&#1089;&#1082; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; &#1087;&#1086;&#1080;&#1089;&#1082; &#1087;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; [ERROR].
    </p>
    <p>
      
