    </p>
    <ul>
      <li>
        Ex2007 100GB - &#1085;&#1077;&#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103;, 200GB - DB &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077;
      </li>
      <li>
        Ex2010 1TB - &#1085;&#1077;&#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103;,&#160;2TB - DB &#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077;
      </li>
    </ul>
    <p>
      <b>&#1057;&#1087;&#1086;&#1089;&#1086;&#1073;&#1099; &#1091;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1085;&#1080;&#1103; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072; DB:</b>
    </p>
    <ol>
      <li>
        &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1095;&#1072;&#1089;&#1090;&#1100; &#1103;&#1097;&#1080;&#1082;&#1086;&#1074; &#1087;&#1077;&#1088;&#1077;&#1085;&#1086;&#1089;&#1080;&#1090;&#1100; &#1074;&#1086; &#1074;&#1085;&#1086;&#1074;&#1100; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1099;&#1077; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
      </li>
      <li>
        &#1089;&#1090;&#1072;&#1088;&#1072;&#1103; &#1073;&#1072;&#1079;&#1072; &#1091;&#1084;&#1077;&#1085;&#1100;&#1096;&#1080;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1086;&#1092;&#1092;&#1083;&#1072;&#1081;&#1085;&#1086;&#1074;&#1086;&#1081; &#1076;&#1077;&#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072;&#1094;&#1080;&#1080;. &#1054;&#1092;&#1092;&#1083;&#1072;&#1081;&#1085;&#1086;&#1074;&#1072;&#1103; &#1076;&#1077;&#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072;&#1094;&#1080;&#1103; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1073;&#1072;&#1079;&#1072; &#1088;&#1072;&#1079;&#1084;&#1086;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1072; (Dismount). &#1053;&#1077;&#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1084;&#1072;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1072;. <b>&#1051;&#1091;&#1095;&#1096;&#1077;</b>:

        <ol>
          <li>
            &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1077;&#1097;&#1077; &#1086;&#1076;&#1085;&#1091; &#1085;&#1086;&#1074;&#1091;&#1102; DB
          </li>
          <li>
            &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1100; &#1103;&#1097;&#1080;&#1082;&#1080; &#1090;&#1091;&#1076;&#1072;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1083;&#1080;&#1096;&#1085;&#1077;&#1077; &#1089;&#1074;&#1086;&#1073;&#1086;&#1076;&#1085;&#1086;&#1077; &#1084;&#1077;&#1089;&#1090;&#1086; &#1074;&#1099;&#1082;&#1080;&#1076;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;. &#1055;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1085;&#1077; &#1079;&#1072;&#1073;&#1099;&#1074;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086; &#1082;&#1086;&#1083;&#1094;&#1077;&#1074;&#1086;&#1077; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1093; &#1083;&#1086;&#1075;&#1086;&#1074;.<br/><b>&#1055;&#1088;&#1080;&#1084;&#1077;&#1088;. </b>&#1053;&#1091;&#1078;&#1085;&#1086; &#1080;&#1079; &#1073;&#1072;&#1079;&#1099; &#1040; (&#1075;&#1076;&#1077; 800&#1043;&#1041;) &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1100; &#1103;&#1097;&#1080;&#1082;&#1080; &#1085;&#1072; 400&#1043;&#1041; &#1074; &#1087;&#1091;&#1089;&#1090;&#1091;&#1102; &#1073;&#1072;&#1079;&#1091; &#1041;. &#1055;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1089;&#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1084;&#1085;&#1086;&#1075;&#1086; &#1083;&#1086;&#1075;&#1086;&#1074; &#1080; &#1087;&#1086;&#1090;&#1086;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1073;&#1101;&#1082;&#1072;&#1087;&#1080;&#1090;&#1100;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1101;&#1090;&#1080; &#1083;&#1086;&#1075;&#1080; &#1089;&#1090;&#1077;&#1088;&#1083;&#1080;&#1089;&#1100;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1090;&#1072;&#1082;. &#1042;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1086;&#1073;&#1077; &#1073;&#1072;&#1079;&#1099; &#1085;&#1072; <b>Enable circular logging</b>&#160;(Properties) &gt; &#1055;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1072;&#1077;&#1084; &#1074;&#1089;&#1077; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1077; &#1103;&#1097;&#1080;&#1082;&#1080; &gt; &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; Enable circular logging.
          </li>
          <li>
            &#1091;&#1073;&#1080;&#1074;&#1072;&#1077;&#1084; &#1086;&#1088;&#1080;&#1075;&#1080;&#1085;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; DB
          </li>
        </ol>
      </li>
    </ol>
    <p>
      <b>&#1041;&#1072;&#1079;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; (&lt;MyDB&gt;.edb) &#1080; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1077; &#1083;&#1086;&#1075;&#1080; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1076;&#1080;&#1089;&#1082;&#1072;&#1093;&#160;&#160;&#1080;&#1083;&#1080; &#1085;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; <a href="#ID_395924678">LUN&#1072;&#1093;</a></b>. &#1042;&#1086;&#1079;&#1088;&#1072;&#1089;&#1090;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1085;&#1086; &#1085;&#1077; &#1101;&#1090;&#1086; &#1075;&#1083;&#1072;&#1074;&#1085;&#1086;&#1077;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1093;&#1086;&#1090;&#1080;&#1084; &#1087;&#1086;&#1090;&#1077;&#1088;&#1103;&#1090;&#1100; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1079;&#1072; &#1089;&#1091;&#1090;&#1082;&#1080;, &#1090;&#1086; &#1088;&#1072;&#1079;&#1085;&#1086;&#1089;&#1080;&#1084; &#1085;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1076;&#1080;&#1089;&#1082;&#1080; &#1076;&#1083;&#1103; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1073;&#1101;&#1082;&#1072;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; (&#1087;&#1088;&#1080; &#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1080;). (<a href="#ID_701469946">&#1089;&#1084;. Backup DB</a>)
    </p>
    <p>
      
    </p>
    <p>
      Enable background database maintenance (24 x 7ESE scanning). &#1055;&#1086;&#1103;&#1074;&#1080;&#1083;&#1086;&#1089;&#1100; &#1074; Ex2010. <b>&#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1088;&#1072;&#1089;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1085;&#1077; &#1086;&#1090;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;</b>. Ex &#1089;&#1072;&#1084; &#1088;&#1077;&#1096;&#1072;&#1077;&#1090; &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1076;&#1077;&#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072;&#1094;&#1080;&#1102;. &#1040; &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1101;&#1090;&#1086; &#1090;&#1086;&#1088;&#1084;&#1086;&#1079;&#1085;&#1072;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1072;, &#1090;&#1086; &#1075;&#1072;&#1083;&#1082;&#1091; &#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1085;&#1103;&#1090;&#1100; &#1080; <b>&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;</b>&#160; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; <b>Maintenance Schedule</b>&#160;&#1089; &#1085;&#1091;&#1078;&#1085;&#1099;&#1084;&#1080; &#1085;&#1072;&#1084; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;.
    </p>
  </body>
</html></richcontent>
