      </li>
      <li>
        &#1054;&#1085;&#1083;&#1072;&#1081;&#1085;&#1086;&#1074;&#1072;&#1103; - &#1082;&#1086;&#1075;&#1076;&#1072; &#1073;&#1072;&#1079;&#1072; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;. &#1053;&#1077; &#1089;&#1078;&#1080;&#1084;&#1072;&#1077;&#1090; &#1073;&#1072;&#1079;&#1091;. &#1055;&#1088;&#1086;&#1073;&#1077;&#1075;&#1072;&#1077;&#1090; &#1087;&#1086; &#1073;&#1072;&#1079;&#1077; &#1080; &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1090; &#1082;&#1072;&#1082;&#1080;&#1077; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072; &#1080; &#1103;&#1097;&#1080;&#1082;&#1080; &#1073;&#1099;&#1083;&#1080; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1099; &#1080; &#1089;&#1088;&#1086;&#1082; &#1080;&#1093; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074; &#1073;&#1072;&#1079;&#1077; &#1080;&#1089;&#1090;&#1077;&#1082;. &#1048; &#1087;&#1086;&#1089;&#1083;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077;. &#1052;&#1077;&#1089;&#1090;&#1086; &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1085;&#1077; &#1086;&#1089;&#1074;&#1086;&#1073;&#1086;&#1078;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103;.
      </li>
      <li>
        <b>Enable background database maintenance (24 x 7ESE scanning)</b>. &#1055;&#1086;&#1103;&#1074;&#1080;&#1083;&#1086;&#1089;&#1100; &#1074; Ex2010. <b>&#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1088;&#1072;&#1089;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1085;&#1077; &#1086;&#1090;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;</b>. Ex &#1089;&#1072;&#1084; &#1088;&#1077;&#1096;&#1072;&#1077;&#1090; &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1076;&#1077;&#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072;&#1094;&#1080;&#1102;. &#1040; &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1101;&#1090;&#1086; &#1090;&#1086;&#1088;&#1084;&#1086;&#1079;&#1085;&#1072;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1072;, &#1090;&#1086; &#1075;&#1072;&#1083;&#1082;&#1091; &#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1085;&#1103;&#1090;&#1100; &#1080; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; <b>Maintenance Schedule</b>&#160;&#1089; &#1085;&#1091;&#1078;&#1085;&#1099;&#1084;&#1080; &#1085;&#1072;&#1084; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;.
      </li>
      <li>
        <b>Don't mount this database at startup</b>&#160;- &#1077;&#1089;&#1083;&#1080; &#1075;&#1072;&#1083;&#1082;&#1080; &#1085;&#1077;&#1090;, &#1090;&#1086; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1085;&#1077; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1084;&#1086;&#1085;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;.
      </li>
      <li>
        <b>This database can be overwitten by a restore</b>&#160;(&#1079;&#1072;&#1097;&#1080;&#1090;&#1072; &#1086;&#1090; &#1076;&#1091;&#1088;&#1072;&#1082;&#1072;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1086; &#1080;&#1079; &#1073;&#1101;&#1082;&#1072;&#1087;&#1072; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1091;&#1102; &#1073;&#1072;&#1079;&#1091;). &#1043;&#1072;&#1083;&#1082;&#1072; &#1089;&#1085;&#1103;&#1090;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1074;&#1089;&#1077; &#1078;&#1077; &#1093;&#1086;&#1090;&#1080;&#1084; &#1073;&#1072;&#1079;&#1091; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100;, &#1090;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076; &#1101;&#1090;&#1080;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1077;&#1077; &#1086;&#1090;&#1084;&#1086;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; (&#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;).
      </li>
      <li>
        <b>Enable circular loggin.</b>&#160;&#1042;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1083;&#1094;&#1077;&#1074;&#1086;&#1075;&#1086; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1093; &#1083;&#1086;&#1075;&#1086;&#1074;. &#1045;&#1089;&#1083;&#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1072;, &#1090;&#1086; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1084;&#1086;&#1078;&#1085;&#1086; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1075;&#1086; &#1073;&#1101;&#1082;&#1072;&#1087;&#1072;. &#1053;&#1091;&#1078;&#1085;&#1086; &#1080;&#1079; &#1073;&#1072;&#1079;&#1099; &#1040; (&#1075;&#1076;&#1077; 800&#1043;&#1041;) &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1100; &#1103;&#1097;&#1080;&#1082;&#1080; &#1085;&#1072; 400&#1043;&#1041; &#1074; &#1087;&#1091;&#1089;&#1090;&#1091;&#1102; &#1073;&#1072;&#1079;&#1091; &#1041;. &#1055;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1089;&#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1084;&#1085;&#1086;&#1075;&#1086; &#1083;&#1086;&#1075;&#1086;&#1074; &#1080; &#1087;&#1086;&#1090;&#1086;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1073;&#1101;&#1082;&#1072;&#1087;&#1080;&#1090;&#1100;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1101;&#1090;&#1080; &#1083;&#1086;&#1075;&#1080; &#1089;&#1090;&#1077;&#1088;&#1083;&#1080;&#1089;&#1100;. &#1053;&#1091;&#1078;&#1085;&#1086; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1090;&#1072;&#1082; &gt; &#1042;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1086;&#1073;&#1077; &#1073;&#1072;&#1079;&#1099; &#1085;&#1072; Enable circular logging &gt; &#1055;&#1077;&#1088;&#10