        &#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1080; &#1085;&#1077; &#1079;&#1085;&#1072;&#1102;&#1090; &#1075;&#1076;&#1077; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1087;&#1072;&#1087;&#1082;&#1080;
      </li>
    </ul>
    <p>
      &#1055;&#1072;&#1087;&#1082;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1089; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099; &#1080; &#1073;&#1077;&#1079; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; &#1087;&#1086;&#1095;&#1090;&#1099;. <b>&#1057; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099;</b>&#160;- &#1091; &#1085;&#1077;&#1077; &#1087;&#1086;&#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1101;&#1083;. &#1072;&#1076;&#1088;&#1077;&#1089;. &#1055;&#1088;&#1080; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1077; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072; &#1085;&#1072; &#1101;&#1083;.&#1072;&#1076;&#1088;&#1077;&#1089; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1074;&#1084;&#1077;&#1089;&#1090;&#1077; &#1089; &#1074;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;&#1084; &#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1086;&#1073;&#1097;&#1077;&#1081; &#1087;&#1072;&#1087;&#1082;&#1077;. <b><i>MyFolder &gt; Mail Enable</i></b>.
    </p>
    <p>
      
    </p>
    <p>
      <b>Public Folder Management Console.</b><font color="#0000c0">&#160;<b>Get-PublicFolderDatabase</b></font>
    </p>
    <p>
      &#160;&#160;&#160;&#1044;&#1083;&#1103; &#1091;&#1076;&#1086;&#1073;&#1089;&#1090;&#1074;&#1072; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1074; Ex2010 &#1087;&#1086;&#1103;&#1074;&#1080;&#1083;&#1072;&#1089;&#1100; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; <b>Public Folder Management Console</b>&#160;(&#1074; Toolbox). &#1054;&#1085;&#1072; &#1073;&#1099;&#1083;&#1072; &#1080; &#1076;&#1086; &#1101;&#1090;&#1086;&#1075;&#1086;, &#1085;&#1086; &#1088;&#1072;&#1085;&#1100;&#1096;&#1077; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1073;&#1099;&#1083;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; &#1085;&#1077;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077;. &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; MyFolder\ Properties\ Permissions\ Add...
    </p>
    <p>
      &#160;&#160;&#160;Microsoft &#1087;&#1099;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100;&#1089;&#1103; &#1086;&#1090; &#1086;&#1073;&#1097;&#1080;&#1093; &#1087;&#1072;&#1087;&#1086;&#1082;. DB &#1086;&#1073;&#1097;&#1080;&#1093; &#1087;&#1072;&#1087;&#1086;&#1082; &#1085;&#1077; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1086;&#1073;&#1080;&#1077; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1080; <b>&#1084;&#1086;&#1078;&#1085;&#1086; &#1088;&#1077;&#1087;&#1083;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#160;&#160;&#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1077; &#1086;&#1073;&#1097;&#1080;&#1077; &#1087;&#1072;&#1087;&#1082;&#1080;</b>&#160; &#1084;&#1077;&#1078;&#1076;&#1091; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1084;&#1080; mailbox &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1084;&#1080; (MyFolder\ Properties\ Replication). &#1050;&#1083;&#1080;&#1077;&#1085;&#1090;&#1099; &#1085;&#1077; &#1079;&#1085;&#1072;&#1102;&#1090; &#1075;&#1076;&#1077; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1087;&#1072;&#1087;&#1082;&#1080;.
    </p>
    <p>
      &#1059;&#1079;&#1085;&#1072;&#1090;&#1100; &#1075;&#1076;&#1077; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1087;&#1072;&#1087;&#1082;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1077; <b>Replication.</b>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>Troubleshooting </b>
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; <b>&#1087;&#1088;&#1080; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1077; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1091; &#1074;&#1099;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080;</b>&#160;(&#1087;&#1088;&#1080; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1080; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080; Apply). &#1063;&#1090;&#1086;&#1073;&#1099; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &gt; &#1079;&#1072;&#1093;&#1086;&#1076;&#1080;&#1084; &#1085;&#1072; &#1079;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1091; Permissions &gt; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1084; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; Administrator &gt; Apply &gt; &#1080; &#1079;&#1072;&#1085;&#1086;&#1074;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; Administrator (&#1082;&#1072;&#1082; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1072;-owner)
    </p>
  </body>
</html></richcontent>
