<node TEXT="Hub Transport" ID="ID_1534347586" CREATED="1519112080312" MODIFIED="1519112080312"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Send Connectors, &#1050;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080;</b>&#160;- &#1085;&#1091;&#1078;&#1077;&#1085; &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1082;&#1080; &#1087;&#1086;&#1095;&#1090;&#1099; &#1079;&#1072; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1099; &#1085;&#1072;&#1096;&#1077;&#1081; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;. &#1042; &#1090;.&#1095;. &#1085;&#1072; Edge, &#1074; Internet. &#1042;&#1085;&#1091;&#1090;&#1088;&#1080; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1099; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1099;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; Send Connectors.</b>
    </p>
    <ol>
      <li>
        <i>ExMC\ Organization Configuration\ Hub Transport &gt; New Send Connectors</i>&#160;&gt; &#1048;&#1084;&#1103; &gt; &#1055;&#1088;&#1077;&#1076;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1077;&#1084;&#1086;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;\ Custom &gt;
      </li>
      <li>
        <b>Add\ Adress space</b>&#160;(&#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;, &#1076;&#1083;&#1103; &#1082;&#1072;&#1082;&#1080;&#1093; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1093; &#1076;&#1086;&#1084;&#1077;&#1085;&#1086;&#1074; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;). &#1052;&#1086;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1080;&#1084;&#1077;&#1085;&#1085;&#1086;, &#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1079;&#1074;&#1105;&#1079;&#1076;&#1086;&#1095;&#1082;&#1091; <b>( *&#160;)</b>&#160;- &#1074;&#1089;&#1077; &#1082;&#1088;&#1086;&#1084;&#1077; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086;.<br/>&#1043;&#1072;&#1083;&#1082;&#1072; <b>Scoped send connector</b>&#160;- &#1077;&#1089;&#1083;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;, &#1090;&#1086; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1082;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089; &#1089;&#1072;&#1081;&#1090;&#1072;, &#1075;&#1076;&#1077; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; Hub Transport (&#1092;&#1080;&#1083;&#1080;&#1072;&#1083;&#1099; &#1086;&#1073;&#1083;&#1086;&#1084;&#1103;&#1090;&#1089;&#1103;) &gt;
      </li>
      <li>
        <b>Network setting.</b>&#160;&#1042;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1082;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1090;&#1100; &#1087;&#1091;&#1085;&#1082;&#1090; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; &#1087;&#1080;&#1089;&#1077;&#1084;: <b>Use domain name system (DNS) &quot;MX&quot; records to route mail automatically</b>&#160;- &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; DNS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;. Route mail through the following smart hosts - &#1103;&#1074;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1080; &#1074;&#1089;&#1103; &#1087;&#1086;&#1095;&#1090;&#1072; &#1080;&#1076;&#1077;&#1090; &#1090;&#1091;&#1076;&#1072;.<br/>Use the External DNS Lookup settings on the transport server - &#1073;&#1077;&#1079; &#1075;&#1072;&#1083;&#1082;&#1080; DNS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1073;&#1077;&#1088;&#1091;&#1090;&#1089;&#1103; &#1080;&#1079; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1075;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103;, &#1085;&#1086; &#1101;&#1090;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1084;&#1086;&#1075;&#1091;&#1090; &#1080; &#1085;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1090;&#1100; MX (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1085;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; Internet). &#1045;&#1089;&#1083;&#1080; &#1089;&#1090;&#1072;&#1074;&#1080;&#1084; &#1075;&#1072;&#1083;&#1082;&#1091;, &#1090;&#1086; &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; DNS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074; &#1076;&#1083;&#1103; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1103; MX &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; (&#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1090;&#1089;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; Exchange).
      </li>
      <li>
        <b>Source Server.</b>&#160;&#1059;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;, &#1085;&#1072; &#1082;&#1072;&#1082;&#1086;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1089;&#1088;&#1072;&#1079;&#1091; &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; Hub Transport.
      </li>
    </ol>
  </body>
</html></richcontent>
</node>
