<node TEXT="Hub Transport" ID="ID_1712376265" CREATED="1519112080313" MODIFIED="1519112080313"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Receive Connectors</b>&#160;- Hub Transport Server &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1080;&#1084;&#1077;&#1090;&#1100; &#1093;&#1086;&#1090;&#1100; &#1086;&#1076;&#1080;&#1085; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088; &#1087;&#1088;&#1080;&#1077;&#1084;&#1072; (&#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1083;&#1091;&#1096;&#1072;&#1083; 25 &#1087;&#1086;&#1088;&#1090;). &#1055;&#1088;&#1080; &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1080;&#1080; &#1087;&#1086;&#1095;&#1090;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;.
    </p>
    <ul>
      <li>
        &#1055;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1099;. ExMS &gt; <font color="#0000c0">Get-ReceiveConnector -Server &lt;MyExServer&gt;</font><font color="#000000">&#160;# &#1073;&#1077;&#1079; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1093; &#1076;&#1074;&#1091;&#1093; &#1089;&#1083;&#1086;&#1074; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090; &#1074;&#1089;&#1077;</font>
      </li>
      <li>
        &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; 2 &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1072; (Default - 25 &#1087;&#1086;&#1088;&#1090;, Client - 587 &#1087;&#1086;&#1088;&#1090; (&#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; SMTP)).
      </li>
    </ul>
    <p>
      <b>Properties Recieve Connectors</b>
    </p>
    <p>
      <b>General.</b>
    </p>
    <ul>
      <li>
        <b>Protocol logging level</b>: &#1045;&#1089;&#1083;&#1080; &#1089;&#1090;&#1072;&#1074;&#1080;&#1084; &#1074; &#1087;&#1086;&#1076;&#1088;&#1086;&#1073;&#1085;&#1099;&#1081;, &#1090;&#1086; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1084; &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; TXT &#1083;&#1086;&#1075;&#1080;&#1085;, &#1082;&#1091;&#1076;&#1072; &#1087;&#1080;&#1096;&#1091;&#1090;&#1089;&#1103; &#1074;&#1089;&#1077; SMTP &#1089;&#1077;&#1089;&#1089;&#1080;&#1080;.
      </li>
      <li>
        <b>&#1059;&#1082;&#1072;&#1079;&#1072;&#1085;&#1086; &#1080;&#1084;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;</b>, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1086;&#1085; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1077;&#1089;&#1083;&#1080; &#1082;&#1090;&#1086;-&#1090;&#1086; &#1089; &#1085;&#1080;&#1084; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090; SMTP.&#160; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;.
      </li>
      <li>
        <b>&#1052;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072;</b>, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085;&#1086; &#1087;&#1086; &#1101;&#1090;&#1086;&#1084;&#1091; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1091;.
      </li>
    </ul>
    <p>
      <b>Network</b>. <b>&#1053;&#1072; &#1082;&#1072;&#1082;&#1080;&#1077; IP &#1080; &#1087;&#1086;&#1088;&#1090;&#1099;</b>&#160; &#1075;&#1086;&#1090;&#1086;&#1074;&#1099; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1080; <b>&#1089; &#1082;&#1072;&#1082;&#1080;&#1093; IP &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;</b>&#160; &#1075;&#1086;&#1090;&#1086;&#1074;&#1099; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100;.
    </p>
    <p>
      <b>Authentication</b>. &#1050;&#1072;&#1082;&#1080;&#1077; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1099; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;.
    </p>
    <p>
      <b>Permission Group</b>. &#1043;&#1088;&#1091;&#1087;&#1087;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1095;&#1090;&#1091; &#1087;&#1086; &#1101;&#1090;&#1086;&#1084;&#1091; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1091;.
    </p>
  </body>
</html></richcontent>
