  <body>
    <p>
      <b>Recipients (&#1055;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1080;), type mailbox</b>&#160;- &#1101;&#1090;&#1086; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099;, &#1091; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1077;&#1089;&#1090;&#1100; &#1072;&#1076;&#1088;&#1077;&#1089; &#1101;&#1083;. &#1087;&#1086;&#1095;&#1090;&#1099;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1080; &#1086;&#1090; &#1080;&#1084;&#1077;&#1085;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100;.
    </p>
    <ul>
      <li>
        <b>Mailbox Enable User</b>&#160;- &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1089; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1084; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1084; &#1103;&#1097;&#1080;&#1082;&#1086;&#1084;.

        <ul>
          <li>
            <b>User mailbox</b>. &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; AD Account, Mailbox (&#1074; DB),&#160;&#160;&#1072;&#1076;&#1088;&#1077;&#1089; &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; GAL (Global Address List)
          </li>
          <li>
            <b>Room Mailbox</b>&#160;- &#1090;&#1080;&#1087;- &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1085;&#1099;&#1081; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082; (&#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1091;). &#1055;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085; &#1076;&#1083;&#1103; &#1073;&#1088;&#1086;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1082;&#1086;&#1084;&#1085;&#1072;&#1090;&#1099; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1087;&#1077;&#1088;&#1077;&#1075;&#1086;&#1074;&#1086;&#1088;&#1082;&#1080;). &#1053;&#1077; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1099; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1055;&#1086;&#1076; &#1103;&#1097;&#1080;&#1082; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1091;&#1095;&#1077;&#1090;&#1082;&#1072; &#1074; AD (disabled) &#1080; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082;. &#1040;&#1076;&#1088;&#1077;&#1089; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; GAL
          </li>
          <li>
            <b>Equipment Mailbox</b>&#160;- &#1090;&#1080;&#1087;- &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1085;&#1099;&#1081; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082; (&#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;). &#1055;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085; &#1076;&#1083;&#1103; &#1073;&#1088;&#1086;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1052;&#1060;&#1059;). &#1053;&#1077; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1099; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1055;&#1086;&#1076; &#1103;&#1097;&#1080;&#1082; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1091;&#1095;&#1077;&#1090;&#1082;&#1072; &#1074; AD (disabled) &#1080; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#160;&#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082;. &#1040;&#1076;&#1088;&#1077;&#1089; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; GAL
          </li>
          <li>
            <b>Linked Mailbox</b>&#160;- &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1091;&#1095;&#1077;&#1090;&#1085;&#1086;&#1081; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080;, &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1081;&#1089;&#1103; &#1074; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084; &#1051;&#1077;&#1089;&#1091;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; <b>&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1085;&#1086;&#1075;&#1086; &#1083;&#1077;&#1089;&#1072;</b>.
          </li>
        </ul>
      </li>
      <li>
        <b>Mail Enable User</b>&#160;- &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1089; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1086;&#1081; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1099;. &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; AD Account, Non-mailbox, External-email. &#1054;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; GAL. <b>&#1050;&#1086;&#1075;&#1076;&#1072; &#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1077;&#1089;&#1090;&#1100; &#1089;&#1074;&#1086;&#1081; &#1103;&#1097;&#1080;&#1082; &#1085;&#1072; yandex.ru</b>.

        <ul>
          <li>
            &#1040;&#1076;&#1084;&#1080;&#1085; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1091; &#1087;&#1086;&#1095;&#1090;&#1099; &#1080; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1076;&#1083;&#1103; &#1091;&#1095;&#1077;&#1090;&#1085;&#1086;&#1081; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1081; &#1101;&#1083;.&#1072;&#1076;&#1088;&#1077;&#1089;.
          </li>
          <li>
            &#1044;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1103;&#1097;&#1080;&#1082;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; &#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;. &#1055;&#1086;&#1095;&#1090;&#1072; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1089;&#1103; &#1079;&#1072; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1084;&#1080; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;.
          </li>
        </ul>
      </li>
      <li>
        <b>Mail Contact</b>&#160;- &#1101;&#1090;&#1086; &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; &#1095;&#1077;&#1084; &#1074;&#1080;&#1079;&#1080;&#1090;&#1085;&#1072;&#1103; &#1082;&#1072;&#1088;&#1090;&#1086;&#1095;&#1082;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; Ex (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1082;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090; &#1089; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084;&#1080; &#1082;&#1086;&#1085;&#1090;&#1072;&#1082;&#1090;&#1072;&#1084;&#1080;). Non-AD account, Mail contact, GAL (&#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103;).
      </li>
      <li>
        <b>Distribution Groups</b>&#160;- &#1101;&#1090;&#1086; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072; &#1074; AD &#1091; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1077;&#1089;&#1090;&#1100; &#1101;&#1083;. &#1072;&#1076;&#1088;&#1077;&#1089;, &#1095;&#1083;&#1077;&#1085;&#1099;. &#1044;&#1083;&#1103; &#1089;&#1072;&#1084;&#1086;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1103;&#1097;&#1080;&#1082; &#1085;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103;.

        <ul>
          <li>
            <b>Static</b>&#160;(Classic) - &#1101;&#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1080;&#1084; &#1084;&#1099; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; &#1080; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; &#1082;&#1090;&#1086; &#1074; &#1085;&#1077;&#1077; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090;. &#1055;&#1086;&#1082;&#1072; &#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082; &#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1077;, &#1086;&#1085; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;.
          </li>
          <li>
            <b>Dynamic</b>&#160;- &#1084;&#1099; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103; (&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1099;) &#1074;&#1093;&#1086;&#1076;&#1072; &#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091;.
          </li>
        </ul>
      </li>
    </ul>
  </body>
</html></richcontent>
