        &#1057;&#1086;&#1079;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1077; &#1103;&#1097;&#1080;&#1082;&#1080; &#1076;&#1083;&#1103; &#1091;&#1095;&#1077;&#1090;&#1086;&#1082;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1074; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084; &#1083;&#1077;&#1089;&#1091;.
