<node TEXT="Создание нового ящика" ID="ID_964712162" CREATED="1519112080314" MODIFIED="1519112080314"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      ExMC\ Recipient Configuration\ Maibox &gt; New Mailbox &gt; &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; <a href="#ID_1498503427">&#1090;&#1080;&#1087; mailbox</a>&#160;&gt; Specify the OU rather than usinga default one (&#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; OU &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1073;&#1077;&#1088;&#1091;&#1090;&#1089;&#1103; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;) &gt; Browse &gt; Users &gt; &#1074;&#1074;&#1086;&#1076;&#1080;&#1084; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &gt;<br/><b>Specify the mailbox database rather than using a database automatically selected</b>&#160;(&#1045;&#1089;&#1083;&#1080; &#1103;&#1074;&#1085;&#1086; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1074; &#1082;&#1072;&#1082;&#1086;&#1081; &#1073;&#1072;&#1079;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1103;&#1097;&#1080;&#1082;&#1080;, &#1090;&#1086; &#1087;&#1088;&#1086;&#1080;&#1079;&#1086;&#1081;&#1076;&#1077;&#1090; &#1088;&#1072;&#1074;&#1085;&#1086;&#1084;&#1077;&#1088;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1085;&#1077; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1093; &#1103;&#1097;&#1080;&#1082; &#1084;&#1077;&#1078;&#1076;&#1091; &#1073;&#1072;&#1079;&#1072;&#1084;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;) &gt;
    </p>
    <p>
      <b>Retention policy</b>&#160;- &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1077;&#1084; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;&#1072; &#1074; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1084; &#1103;&#1097;&#1080;&#1082;&#1077; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072; &#1080; &#1095;&#1090;&#1086; &#1089; &#1085;&#1080;&#1084;&#1080; &#1087;&#1086;&#1090;&#1086;&#1084; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100;).
    </p>
    <p>
      <b>Exchange ActiveSync mailbox policy</b>&#160;- &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080; &#1087;&#1088;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1084;&#1091; &#1103;&#1097;&#1080;&#1082;&#1091; &#1089; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;.
    </p>
    <p>
      &gt; <b>Archive Setting</b>&#160;&gt; &#1055;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082; &#1074;&#1089;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1088;&#1072;&#1079;&#1088;&#1072;&#1089;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080; &#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082; &#1074;&#1099;&#1085;&#1091;&#1078;&#1076;&#1077;&#1085; &#1077;&#1075;&#1086; &#1095;&#1080;&#1089;&#1090;&#1080;&#1090;&#1100;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1077; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;, &#1090;&#1086; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1077;&#1085;&#1080;&#1077; &#1082;&#1074;&#1086;&#1090;&#1099;.
    </p>
    <ul>
      <li>
        &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1074; PST &#1092;&#1072;&#1081;&#1083; &#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1082; Outlook (<b>&#1085;&#1077; &#1076;&#1072;&#1083;&#1072;&#1090;&#1100; &#1090;&#1072;&#1082;</b>).

        <ul>
          <li>
            &#1053;&#1086; PST &#1092;&#1072;&#1081;&#1083;&#1099; &#1085;&#1077; &#1085;&#1072;&#1076;&#1077;&#1078;&#1085;&#1099; (&#1086;&#1085;&#1080; &#1089;&#1099;&#1087;&#1103;&#1090;&#1089;&#1103; &#1082;&#1086;&#1075;&#1076;&#1072; &#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1103;&#1090;&#1089;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084;&#1080;)
          </li>
          <li>
            PST-&#1092;&#1072;&#1081;&#1083;&#1099; &#1085;&#1080;&#1082;&#1072;&#1082; &#1085;&#1077; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1084;
          </li>
        </ul>
      </li>
      <li>
        &#1072;&#1088;&#1093;&#1080;&#1074;&#1085;&#1072;&#1103; &#1089;&#1083;&#1091;&#1078;&#1073;&#1072; &#1087;&#1088;&#1077;&#1076;&#1083;&#1072;&#1075;&#1072;&#1077;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1077;&#1097;&#1077; &#1086;&#1076;&#1080;&#1085; &#1103;&#1097;&#1080;&#1082;, &#1072; &#1089;&#1090;&#1072;&#1088;&#1099;&#1081; &#1079;&#1072;&#1075;&#1086;&#1085;&#1103;&#1077;&#1084; &#1074; &#1072;&#1088;&#1093;&#1080;&#1074;. &#1050;&#1083;&#1080;&#1077;&#1085;&#1090;&#1099; <b>Outlook 2007 (&#1089; &#1087;&#1072;&#1090;&#1095;&#1077;&#1084;), Outlook 2010, Outlook Web Access</b>

        <ul>
          <li>
            create local archive - &#1085;&#1072; &#1073;&#1072;&#1079;&#1077; &#1085;&#1072; &#1085;&#1072;&#1096;&#1080;&#1093; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1093;
          </li>
          <li>
            create a remote hosted archive - &#1074; &#1086;&#1073;&#1083;&#1072;&#1082;&#1077;
          </li>
          <li>
            &#1072;&#1088;&#1093;&#1080;&#1074;&#1085;&#1099;&#1077; &#1103;&#1097;&#1080;&#1082;&#1080; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1086;&#1085;&#1083;&#1072;&#1081;&#1085;&#1077; (&#1085;&#1080;&#1082;&#1072;&#1082;&#1086;&#1075;&#1086; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080; &#1086;&#1092;&#1092;&#1083;&#1072;&#1081;&#1085; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;)
          </li>
          <li>
            &#1091; &#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082;&#1072; &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1074;&#1077;&#1090;&#1074;&#1100;. &#1042; &#1072;&#1088;&#1093;&#1080;&#1074;&#1085;&#1086;&#1084; &#1103;&#1097;&#1080;&#1082;&#1077; &#1087;&#1091;&#1089;&#1090;&#1086;, &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082;&#1086;&#1088;&#1079;&#1080;&#1085;&#1072;. &#1045;&#1089;&#1090;&#1100; <b>2 &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1072; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086;&#1095;&#1090;&#1099; &#1074; &#1072;&#1088;&#1093;&#1080;&#1074;&#1085;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082;.</b>

            <ul>
              <li>
                &#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1089;&#1072;&#1084; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090; &#1087;&#1072;&#1087;&#1082;&#1080; &#1080; &#1087;&#1077;&#1088;&#1077;&#1090;&#1072;&#1089;&#1082;&#1080;&#1074;&#1072;&#1077;&#1090; &#1090;&#1091;&#1076;&#1072; &#1087;&#1086;&#1095;&#1090;&#1091;.
              </li>
              <li>
                &#1040;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; &#1089;&#1090;&#1072;&#1088;&#1096;&#1077; 60 &#1076;&#1085;&#1077;&#1081;, &#1090;&#1086; &#1086;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1072;&#1088;&#1093;&#1080;&#1074;&#1085;&#1099;&#1081; &#1103;&#1097;&#1080;&#1082; (&#1089; &#1072;&#1074;&#1090;. &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077;&#1084; &#1087;&#1072;&#1087;&#1086;&#1082;)
              </li>
            </ul>
          </li>
        </ul>
      </li>
    </ul>
    <p>
      &#1089;&#1084;. <a href="#ID_1534347586">&#1040;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1103;&#1097;&#1080;&#1082;&#1086;&#1074; &#1087;&#1086; &#1080;&#1084;&#1077;&#1085;&#1072;&#1084; AD.</a>
    </p>
  </body>
