<node TEXT="Edge Transport" FOLDED="true" ID="ID_1134598353" CREATED="1519112080315" MODIFIED="1519112080315"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Edge Transport Server</b>.&#160;&#160;&#1042;&#1089;&#1077;&#1075;&#1076;&#1072; &#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1089;&#1103; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086; &#1086;&#1090; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1088;&#1086;&#1083;&#1077;&#1081; Exchange. &#1069;&#1090;&#1072; &#1088;&#1086;&#1083;&#1100; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; AD. &#1057;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1083;&#1089;&#1103; &#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1074;&#1099;&#1085;&#1077;&#1089;&#1090;&#1080; &#1072;&#1085;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1089;&#1085;&#1099;&#1081; &#1080; &#1072;&#1085;&#1090;&#1080;&#1089;&#1087;&#1072;&#1084; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083; &#1074; &quot;&#1076;&#1077;&#1084;&#1080;&#1083;&#1080;&#1090;&#1072;&#1088;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1085;&#1091;&#1102;&quot; &#1079;&#1086;&#1085;&#1091;.
    </p>
    <p>
      Edge &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;. Edge &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; SMTP &#1089;&#1077;&#1089;&#1089;&#1080;&#1081; &#1086;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074; &#1074; &#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1077; &#1080;&#1083;&#1080; POP3 &#1086;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1050;&#1083;&#1080;&#1077;&#1085;&#1090; &#1089;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; CAS
    </p>
    <ul>
      <li>
        &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1087;&#1086;&#1095;&#1090;&#1091; &#1080; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1091;&#1077;&#1090; &#1077;&#1077; &#1085;&#1072; &#1089;&#1087;&#1072;&#1084;
      </li>
      <li>
        &#1092;&#1080;&#1083;&#1100;&#1088;&#1091;&#1077;&#1090; &#1085;&#1072; &#1074;&#1080;&#1088;&#1091;&#1089;&#1099; (&#1087;&#1088;&#1080; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1080; &#1072;&#1085;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1089;&#1072;)
      </li>
      <li>
        &#1072;&#1085;&#1090;&#1080;&#1089;&#1087;&#1072;&#1084; &#1091; Edge &#1076;&#1077;&#1088;&#1100;&#1084;&#1086;&#1074;&#1099;&#1081; &#1080; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; Microsoft Forefront Protection &#1080;&#1083;&#1080; ORF, &#1050;&#1072;&#1089;&#1087;&#1077;&#1088;&#1089;&#1082;&#1080;&#1081; - &#1072; &#1101;&#1090;&#1086; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1099;
      </li>
      <li>
        &#1079;&#1072;&#1095;&#1072;&#1089;&#1090;&#1091;&#1102; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1089;&#1090;&#1086;&#1080;&#1090; <b>Exchange</b>&#160;&#1074; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1077; + &#1089;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080; (&#1074; &#1044;&#1052;&#1047;) <b>Sendmail</b>&#160;(&#1088;&#1077;&#1083;&#1101;&#1081; - &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1091;&#1077;&#1090; &#1085;&#1072; &#1089;&#1087;&#1072;&#1084;)
      </li>
    </ul>
    <p>
      &#1041;&#1077;&#1088;&#1077;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1085;&#1077; &#1103;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081;&#1089;&#1103; &#1095;&#1083;&#1077;&#1085;&#1086;&#1084; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1080;&#1084;&#1077;&#1090;&#1100; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1090;&#1100; &#1080;&#1084;&#1077;&#1085;&#1072; &#1074; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1080; &#1089;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080;. &#1053;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084; Edge &#1085;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1075;&#1086; DNS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
    </p>
  </body>
</html></richcontent>
