<node TEXT="порядок обработки почты" ID="ID_1574521563" CREATED="1519112080315" MODIFIED="1519112080315"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Connection&#160;Filtering </b>(&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1085;&#1072; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081;)
    </p>
    <ol>
      <li>
        <b>IP Allow List</b>&#160;- &#1101;&#1090;&#1072; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1089;&#1072;&#1084;&#1086;&#1081; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081;. &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; IP &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1080; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1077;&#1081; &#1082;&#1086;&#1084;&#1091; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1086; &#1074;&#1089;&#1105;. &#1053;&#1080;&#1082;&#1072;&#1082;&#1080;&#1077; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1080; &#1085;&#1077; &#1076;&#1077;&#1083;&#1072;&#1102;&#1090;&#1089;&#1103;. &#1055;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085; &#1076;&#1083;&#1103; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;&#1075;&#1086; &#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;. <i>ExMC\ Edge Transport\ Anti-spam\ IP Allow List</i>
      </li>
      <li>
        <b>IP Block List</b>&#160;- &#1079;&#1072;&#1085;&#1086;&#1089;&#1080;&#1090;&#1089;&#1103; &#1090;&#1072;&#1082;&#1078;&#1077; &#1088;&#1091;&#1082;&#1072;&#1084;&#1080;. &#1041;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072; &#1074;&#1088;&#1077;&#1084;&#1103;.
      </li>
      <li>
        <b>RBL</b>, Realtime Blocking List - <b>&#1089;&#1077;&#1088;&#1074;&#1080;&#1089;</b>, &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081; &#1080;&#1085;&#1092;. &#1086; &#1089;&#1087;&#1072;&#1084;&#1077;&#1088;&#1089;&#1082;&#1080;&#1093; IP &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1093;. <i>ExMC\ Edge Transport\ Anti-spam\ IP Block List Providers.</i>

        <ol>
          <li>
            ( - ) &#1091; RBL &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074; &#1085;&#1077; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1072;&#1082;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103;.
          </li>
          <li>
            ( - ) &#1082;&#1072;&#1082; &#1082;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1099; &#1090;&#1072;&#1082; &#1080; &#1084;&#1099; &#1084;&#1086;&#1078;&#1077;&#1084; &quot;&#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1086;&quot; &#1087;&#1086;&#1087;&#1072;&#1089;&#1090;&#1100; &#1074; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; RBL &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1077; <font color="#0000c0">www.dnsbl.info</font>
          </li>
          <li>
            ( + ) &#1077;&#1089;&#1090;&#1100; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1081;
          </li>
        </ol>
      </li>
      <li>
        <b>Sender Fitering</b>&#160;- &#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1087;&#1086; &#1054;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1077;&#1083;&#1102; (&#1087;&#1086;&#1083;&#1077; From) - &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1075;&#1086; e-mail, &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;. &#1042; Action &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1077; &#1077;&#1089;&#1090;&#1100; &#1088;&#1072;&#1076;&#1080;&#1086; &#1082;&#1085;&#1086;&#1087;&#1082;&#1072; &#1076;&#1083;&#1103; &#1088;&#1077;&#1076;&#1078;&#1101;&#1082;&#1090;&#1080;&#1085;&#1075;&#1072; &#1083;&#1080;&#1073;&#1086; <b>Stamp message with blocked sender and continue processing</b>&#160;(&#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1081; &#1091;&#1095;&#1077;&#1090; &#1088;&#1077;&#1081;&#1090;&#1080;&#1085;&#1075;&#1072; SCL)
      </li>
      <li>
        <b>Recipient Filtering</b>&#160;- &#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1087;&#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1102; (&#1087;&#1086;&#1083;&#1077; To) -&#160;
      </li>
      <li>
        <b>Sender ID</b>&#160;- <b>&#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; SPF-&#1079;&#1072;&#1087;&#1080;&#1089;&#1080; (Sender Policy Framework)</b>&#160;- &#1085;&#1077; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072;&#1097;&#1080;&#1090;&#1086;&#1081; &#1086;&#1090; &#1089;&#1087;&#1072;&#1084;&#1072;. &#1055;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1090; &#1080;&#1084;&#1077;&#1085;&#1080; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072; &#1085;&#1080;&#1082;&#1090;&#1086; &#1085;&#1077; &#1088;&#1072;&#1089;&#1089;&#1099;&#1083;&#1072;&#1083; &#1089;&#1087;&#1072;&#1084;. &#1042;&#1086;<br/>&#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1077; Action (-all) &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1086;&#1076;&#1080;&#1085; &#1080;&#1079; 3&#1093; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1086;&#1074; &#1076;&#1083;&#1103; &#1085;&#1077;&#1087;&#1088;&#1086;&#1096;&#1077;&#1076;&#1096;&#1080;&#1093; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1091;:

        <ul>
          <li>
            Reject message - &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1085;&#1077; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1087;&#1099;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1091; NDR (non-delivery reports)
          </li>
          <li>
            Delete massage - &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1090;&#1091;&#1090; &#1078;&#1077; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103;, NDR &#1085;&#1077; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103;
          </li>
          <li>
            Stamp message with Sender ID result and continue processing
          </li>
        </ul>
      </li>
      <li>
        <b>Content Filtering</b>&#160;- &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1087;&#1086; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;&#1091; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072;. &#1053;&#1077; &#1086;&#1095;&#1077;&#1085;&#1100; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089; &#1088;&#1091;&#1089;&#1089;&#1082;&#1080;&#1084; &#1089;&#1087;&#1072;&#1084;&#1086;&#1084;. &#1056;&#1077;&#1081;&#1090;&#1080;&#1085;&#1075; SCL (Spam confidence levels). &#1054;&#1090; 1(&#1085;&#1086;&#1088;&#1084;&#1072;) &#1076;&#1086; 9(&#1089;&#1087;&#1072;&#1084;).
      </li>
      <li>
        <font color="#0000c0">Get-OrganizationConfig | fl *scl*</font>&#160;- &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; SCL, &#1074;&#1099;&#1096;&#1077; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1102;&#1090; &#1074; Junk &#1082; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102;.
      </li>
    </ol>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Рекомендации" ID="ID_491287302" CREATED="1519112080315" MODIFIED="1519112080315"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1047;&#1072;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1091; &#1072;&#1085;&#1086;&#1085;&#1080;&#1084;&#1085;&#1099;&#1093; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1087;&#1086;&#1095;&#1090;&#1091; &#1086;&#1090; &#1080;&#1084;&#1077;&#1085;&#1080; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;.</b>
    </p>
    <p>
      <font color="#0000c0">Get-ReceiveConnector &#8220;My Internet Receive Connector&#8221; | Get-ADPermission -user &#8220;NT AUTHORITY\Anonymous Logon&#8221; | where {$_.ExtendedRights -like &#8220;ms-exch-smtp-accept-authoritative-domain-sender&#8221;} | Remove-ADPermission</font>
    </p>
    <p>
      (You need to change the &#8220;My Internet Receive Connector&#8221; part in the above syntax)
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1089;&#1090;&#1100; RBL &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;.</b>&#160; <i>C:\ Program Files\ Microsoft\ Exchange Server\ V14\ Scripts\ <b>get-AntispamTopRBLProviders.ps1</b></i>. &#1047;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; &#1087;&#1086;&#1089;&#1083;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; RBL &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074;. &#1057;&#1090;&#1088;&#1086;&#1080;&#1090;&#1089;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1080;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1089;&#1090;&#1100; &#1090;&#1086;&#1075;&#1086; &#1080;&#1083;&#1080; &#1080;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;.
    </p>
    <p>
      &#1059;&#1076;&#1072;&#1083;&#1103;&#1077;&#1084; &#1085;&#1077;&#1085;&#1091;&#1078;&#1085;&#1099;&#1077; &#1080;&#1079; Edge Transport.
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Troubleshooting" FOLDED="true" ID="ID_1229672450" CREATED="1519112080316" MODIFIED="1700789248721"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <b>Все письма, которые попадают в Hub Transport, возвращаются с ошибкой Failover.</b>&nbsp;На диске должно быть больше 4 ГБ свободного места
      </li>
      <li>
        <b>проблемы с GAL</b>. ExMS &gt; <font color="#0000c0">Get-GlobalAddreddList |&nbsp;Update-GlobalAddressList</font>
      </li>
      <li>
        <b>Если письма снаружи не проходят</b>, то нужно в настройках приемного коннектора (Server Configuration\ Hub Transport\ Receive Connectors\ &lt;DefaultOrNo&gt;Permission Groups) поставить галку Anonimous users
      </li>
      <li>
        Если письма копятся в Draft, то не работает служба <b>Microsoft Exchange Mail Submission service</b>
      </li>
      <li>
        если от нас <b>перестала проходить почта</b>, то скорее всего мы попали в RBL, Realtime Blocking List - список RBL провайдера. Проверить можно на сервисе <font color="#0000c0">www.dnsbl.info</font>
      </li>
      <li>
        <b>Отмонтированная база не удаляется.</b>&nbsp;&nbsp;Остались прикрепленные ящики. Перекрепить все <b>сразу.</b><br/><font color="#0000c0">Get-Mailbox -Database &lt;ИмяУдаляемойDB&gt; | Set-Mailbox -Database &lt;ИмяДругойDB&gt;</font>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      -----------------------------------------
    </p>
    <ol>
      <li>
        Проверка свободного места
      </li>
      <li>
        Проверка Event Log
      </li>
      <li>
        Проверка доставки через telnet
      </li>
      <li>
        Проверка разрешения имен DNS
      </li>
      <li>
        Проверка ADDS
      </li>
      <li>
        Проверка настроек коннекторов приема
      </li>
    </ol>
  </body>
</html></richcontent>
<node TEXT="# Рекомендации" FOLDED="true" ID="ID_1076198192" CREATED="1519112080315" MODIFIED="1700091808739"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        Очень тяжелый и поэтому лучше развертывать <b>на железо</b>&nbsp;(не на виртуалку), поскольку всё равно придется всё на виртуалке выкрутить под него.
      </li>
      <li>
        <b>Jetstress</b>&nbsp;- утилита эмулирующаяя нагрузку БД почтовых ящиков без установки Exchange Server
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="Скрипт создания эл.ящиков по списку" ID="ID_1852215420" CREATED="1519112080316" MODIFIED="1539967442774"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1082;&#1088;&#1080;&#1087;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1101;&#1083;.&#1103;&#1097;&#1080;&#1082;&#1086;&#1074; &#1087;&#1086; &#1089;&#1087;&#1080;&#1089;&#1082;&#1091;. (<font color="#ff0000">&#1085;&#1077; &#1079;&#1072;&#1082;&#1086;&#1085;&#1095;&#1077;&#1085;</font>)</b>
    </p>
    <ol>
      <li>
        &#1047;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; PowerShell_ISE
      </li>
      <li>
        <font color="#000000">&#1057;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1082;&#1072;&#1082;&#1080;&#1077; &#1085;&#1072;&#1073;&#1086;&#1088;&#1099; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1083;&#1077;&#1090;&#1086;&#1074; &#1079;&#1072;&#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1099; &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1081; &#1089;&#1077;&#1089;&#1089;&#1080;&#1080;. </font><font color="#0000c0">Get-PSSnapin -Registered</font>
      </li>
      <li>
        &#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1103;&#1077;&#1084; &#1085;&#1091;&#1078;&#1085;&#1099;&#1081; &#1085;&#1072;&#1073;&#1086;&#1088; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1083;&#1077;&#1090;&#1086;&#1074; <font color="#0000c0">Add-PSSnapin &quot;Microsoft.Exchange.Management.PowerShell.E2010&quot;</font>
      </li>
      <li>
        <font color="#0000c0">man New-Mailbox -Examples</font>&#160;&gt; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1077;&#1084; &#1074; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1086;&#1088;
      </li>
    </ol>
    <p>
      <font color="#008000">$mailboxes = 1..10 </font># &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1082;&#1083;&#1072;&#1076;&#1077;&#1084; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1080;&#1079; 10 &#1095;&#1080;&#1089;&#1077;&#1083; (mailbox &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1077; &#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;)
    </p>
    <p>
      <font color="#008000">$password = Read-Host &quot;Enter password&quot; -AsSecureString</font>&#160;# &#1089;&#1090;&#1088;&#1086;&#1095;&#1082;&#1091; &#1089; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1084; &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1072;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1076; &#1094;&#1080;&#1082;&#1083;&#1086;&#1084;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1074;&#1089;&#1077; &#1103;&#1097;&#1080;&#1082;&#1080; &#1073;&#1099;&#1083;&#1080; &#1089; &#1086;&#1076;&#1085;&#1080;&#1084; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1084;<br/><font color="#008000">Foreach ($mailbox in $mailboxes) </font># &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; &#1094;&#1080;&#1082;&#1083;, &#1085;&#1072; &#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1088;&#1072;&#1079; (&#1089; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1085;&#1080;&#1103;&#1084;&#1080; &#1089;&#1083;&#1086;&#1074;&#1072; Mailbox &#1082;&#1072;&#1082;&#1072;&#1103;-&#1090;&#1086; &#1093;&#1088;&#1077;&#1085;&#1100;, &#1084;&#1086;&#1078;&#1077;&#1090; &#1090;&#1072;&#1082; &#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1086; &#1074; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;&#1093;):<font color="#008000"><br color="#008000"/>{<br color="#008000"/>New-Mailbox -UserPrincipalName chris$mailbox@contoso.com -Alias chris$mailbox -OrganizationalUnit Users -Password $password -FirstName Chris$mailbox -LastName Ashton$mailbox -name chris$mailbox</font><font color="#000000">&#160;# &#1074;&#1079;&#1103;&#1090;&#1100; &#1080; &#1089;&#1083;&#1077;&#1075;&#1076;&#1072; &#1087;&#1086;&#1076;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1086; &#1080;&#1079; &quot;Example 1&quot;, </font><font color="#ff0000">&#1085;&#1086; &#1082;&#1072;&#1082; &#1080;&#1079; &#1050;&#1088;&#1080;&#1089;&#1072; &#1089;&#1088;&#1072;&#1079;&#1091; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1080;&#1084;&#1077;&#1085;&#1072; &#1085;&#1077; &#1103;&#1089;&#1085;&#1086;</font><font color="#008000"><br color="#008000"/>}</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Автоматическое создание ящиков по именам AD" ID="ID_647636608" CREATED="1519112080316" MODIFIED="1519112080316"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1040;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1103;&#1097;&#1080;&#1082;&#1086;&#1074; &#1087;&#1086; &#1080;&#1084;&#1077;&#1085;&#1072;&#1084; AD.</b>
    </p>
    <ol>
      <li>
        <i>ExMC\ Organization Configuration\ Hub Transport\ Accepted Domains</i>
      </li>
      <li>
        &#1055;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1085;&#1072;&#1096;&#1080; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099; &#1076;&#1086;&#1084;&#1077;&#1085;&#1099; New Accepted Domain &gt; &#1059;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1086;&#1076;&#1080;&#1085; &#1080;&#1079; &#1090;&#1088;&#1077;&#1093; &#1074;&#1080;&#1076;&#1086;&#1074; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;:

        <ul>
          <li>
            Authoritative Domain. &#1044;&#1086;&#1084;&#1077;&#1085;, &#1079;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072;&#1096;&#1072; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; Exchange.
          </li>
          <li>
            Internal Relay Domain. &#1055;&#1086;&#1080;&#1089;&#1082;&#1072;&#1083; &#1091; &#1089;&#1077;&#1073;&#1103;, &#1085;&#1077; &#1085;&#1072;&#1096;&#1077;&#1083; &gt; &#1087;&#1077;&#1088;&#1077;&#1082;&#1080;&#1085;&#1091;&#1083; &#1082;&#1091;&#1076;&#1072;-&#1090;&#1086;.
          </li>
          <li>
            External Relay Domain. &#1053;&#1077; &#1080;&#1097;&#1072; &#1091; &#1089;&#1077;&#1073;&#1103; &#1087;&#1077;&#1088;&#1077;&#1082;&#1080;&#1076;&#1099;&#1074;&#1072;&#1077;&#1090; &#1087;&#1086;&#1095;&#1090;&#1091; &#1074; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1076;&#1086;&#1084;&#1077;&#1085;.
          </li>
        </ul>
      </li>
      <li>
        &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1074;&#1089;&#1077;&#1084; &#1073;&#1091;&#1076;&#1077;&#1090; &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1085;&#1086; &#1085;&#1086;&#1074;&#1086;&#1084;&#1091; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1084;&#1091; &#1076;&#1086;&#1084;&#1077;&#1085;&#1091;. &#1047;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1072; E-mail Address Policies. &#1051;&#1102;&#1073;&#1072;&#1103;, &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1072;&#1103; &#1085;&#1072;&#1084;&#1080; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072;, &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1085;&#1077;&#1081; Default Policy. Default Policy &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1090;&#1077; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1080;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; &#1085;&#1077; &#1086;&#1090;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090;.<br/>&gt; New E-mail Address Policy &gt;<br/><b>Select the recipient container wher you want to apply the filter</b>&#160;- &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1085;&#1072; &#1082;&#1086;&#1075;&#1086; &#1087;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072;.<br/><b>Include these recipient types</b>&#160;- &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1090;&#1080;&#1087; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &gt; Users with Exchange mailbox &gt; Next<br/>&gt; &#1085;&#1077; &#1079;&#1072;&#1073;&#1099;&#1074;&#1072;&#1077;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; <b>Custom Attributes &#1076;&#1083;&#1103; </b>&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080; &gt;<br/>&gt; &#1082;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084; &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1101;&#1083;. &#1072;&#1076;&#1088;&#1077;&#1089;? &#1045;&#1089;&#1090;&#1100; 2 &#1087;&#1091;&#1090;&#1080;<br/>
      </li>
      <li>
