      <li>
        &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1100; &#1087;&#1086;&#1095;&#1090;&#1091; - <b>&#1084;&#1086;&#1078;&#1085;&#1086;&#160;&#1079;&#1072;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;</b>, &#1085;&#1086; &#1101;&#1090;&#1086; <b>&#1085;&#1077; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;</b>
