        &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1088;&#1072;&#1090;&#1100;&#1089;&#1103; &#1080;&#1079; AD
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">dpkg -l &lt;MyPacket*&gt;</font>&#160;&#160;# &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;. <b>ii</b>-&#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085; &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;, <b>un</b>-&#1085;&#1077; &#1091;&#1089;&#1090;.
    </p>
    <p>
      <font color="#0000c0">apt-get install dovecot-imapd dovecot-pop3d</font>&#160;&#160;# &#1080;&#1085;&#1089;&#1090;&#1072;&#1083;&#1083;&#1080;&#1088;&#1091;&#1077;&#1084;
    </p>
  </body>
</html></richcontent>
