<node TEXT="Виртуальный хостинг (Postfix+Dovecot)" FOLDED="true" ID="ID_1359432172" CREATED="1519112080317" MODIFIED="1570734460688"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1845130465">Postfix</a>&#160;&#160;&#160;<a href="#ID_1577319547">Dovecot</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081;&#160;&#160;&#1093;&#1086;&#1089;&#1090;&#1080;&#1085;&#1075; </b>(&#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1076;&#1086;&#1084;&#1077;&#1085;&#1099; &#1080; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1080;)
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1087;&#1086;&#1095;&#1090;&#1091; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1091; &#1085;&#1077;&#1075;&#1086; &#1085;&#1077;&#1090;.
      </li>
      <li>
        &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      0. <font color="#0000c0">vi /etc/postfix/mail.cf</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; &#1089;&#1084;. <a href="#ID_767054682">main.cf</a>
    </p>
    <p>
      1. <font color="#0000c0"># echo <b>unix.unix.ru</b>&#160;&gt; /etc/postfix/<b>vhosts</b></font>&#160;// &#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1084; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1076;&#1086;&#1084;&#1077;&#1085;. &#1054;&#1073;&#1098;&#1103;&#1089;&#1085;&#1103;&#1077;&#1084; postfix&#1091; &#1082;&#1072;&#1082;&#1080;&#1077; &#1076;&#1086;&#1084;&#1077;&#1085;&#1099; &#1086;&#1085; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;
    </p>
    <p>
      2. <font color="#0000c0"># useradd -u 5000 -m <b>vmail</b></font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1074;&#1080;&#1088;&#1090;. &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1095;&#1090;&#1099; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;. &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; <b>vmail</b>&#160; (&#1073;&#1072;&#1079;&#1072; &#1076;&#1083;&#1103; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1085;&#1099;&#1093; &#1103;&#1097;&#1080;&#1082;&#1086;&#1074;)
    </p>
    <p>
      3. <font color="#0000c0"># mkdir ~vmail/<b>unix.unix.ru</b></font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1076;&#1083;&#1103; &#1074;&#1080;&#1088;&#1090;. &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;, &#1074; &#1085;&#1077;&#1084; &#1073;&#1091;&#1076;&#1091;&#1090; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;.
    </p>
    <p>
      4. <font color="#0000c0"># mkdir ~vmail/unix.unix.ru/info</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; info (&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1080; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086;)
    </p>
    <p>
      5. <font color="#0000c0"># chown -R vmail:vmail ~vmail/</font>&#160;// &#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1072; &#1085;&#1072;&#160;&#160;&#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086; &#1074;&#1080;&#1088;&#1090;. &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; (vmail)
    </p>
    <p>
      6. <font color="#0000c0"># vi /etc/dovecot/<b>dovecot.conf</b></font>&#160;// &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; &#1092;&#1072;&#1081;&#1083; (&#1089;&#1084;. <a href="#ID_1577319547">Dovecot</a>). &#1055;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; Dovcot &#1075;&#1076;&#1077; &#1103;&#1097;&#1080;&#1082; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1080; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;
    </p>
    <p>
      7.1 <font color="#0000c0"># /etc/init.d/<b>postfix restart</b></font>
    </p>
    <p>
      7.2 <font color="#0000c0"># /etc/init.d/<b>dovecot restart</b></font><br/>
    </p>
    <p>
      8.1 <font color="#0000c0"># adddovecotuser info@unix.unix.ru</font>&#160;// &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1074; &#1092;&#1072;&#1081;&#1083;&#160;/etc/postfix/<b>vmaps</b>&#160;(&#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084; <b>&#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1099; <a href="#ID_11976961">adddovecotuser</a>&#160;&#1080; <a href="#ID_1571349784">mkdovecotpasswd</a></b>). &#1082;&#1072;&#1082;&#1080;&#1093; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1074; &#1082;&#1072;&#1082;&#1080;&#1093; &#1089;&#1083;&#1091;&#1095;&#1072;&#1103;&#1093; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1082;&#1072;&#1082;&#1080;&#1077; &#1103;&#1097;&#1080;&#1082;&#1080; &#1076;&#1083;&#1103; &#1085;&#1080;&#1093; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;
    </p>
    <p>
      8.2 <font color="#0000c0"># mkdovecotpasswd info@unix.unix.ru pass1</font>&#160;// &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1086;&#1103;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103; &#1093;&#1077;&#1096; &#1074; <b>/etc/dovecot/passwd</b>
    </p>
  </body>
</html></richcontent>
<node TEXT="main.cf" ID="ID_547027808" CREATED="1519112080318" MODIFIED="1519112080318" LINK="#ID_767054682"/>
<node TEXT="dovecot.conf0" ID="ID_821214008" CREATED="1519112080318" MODIFIED="1519112080318"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>/etc/dovecot/dovecot.conf (&#1085;&#1072; &#1089;&#1072;&#1081;&#1090;&#1077; ubuntu)</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">auth_mechanisms = plain cram-md5 </font>
    </p>
    <p>
      <font color="#008000">auth_verbose = yes </font>
    </p>
    <p>
      <font color="#008000">base_dir = /var/run/dovecot/ </font>
    </p>
    <p>
      <font color="#008000">info_log_path = /var/log/dovecot.info </font>
    </p>
    <p>
