<node TEXT="скрипт adddovecotuser" ID="ID_11976961" CREATED="1519112080319" MODIFIED="1519112080319"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1089;&#1082;&#1088;&#1080;&#1087;&#1090; &#1076;&#1083;&#1103; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1076;&#1083;&#1103; dovecot (&#1090;&#1077;&#1086;&#1088;&#1077;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081;) </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>/usr/local/sbin/adddovecotuser</b>&#160;// &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1072;&#1077;&#1084; &#1074; sbin, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>echo&#160;&#160;&quot;$1&quot; &gt; /tmp/user </b></font>
    </p>
    <p>
      <font color="#008000"><b>user=`cat /tmp/user | cut -f1 -d &quot;@&quot;` </b></font>
    </p>
    <p>
      <font color="#008000"><b>domain=`cat /tmp/user | cut -f2 -d &quot;@&quot;` </b></font>
    </p>
    <p>
      <font color="#008000"><b>echo &quot;$user@$domain::5000:5000::/home/vmail/$domain/:/bin/false&quot; &gt;&gt; /etc/dovecot/users </b></font>
    </p>
    <p>
      <font color="#008000"><b>/usr/bin/maildirmake.dovecot /home/vmail/$domain/$user 5000:5000 </b></font>
    </p>
    <p>
      <font color="#008000"><b>echo $1 $domain/$user/ &gt;&gt; /etc/postfix/vmaps </b></font>
    </p>
    <p>
      <font color="#008000"><b>postmap /etc/postfix/vmaps </b></font>
    </p>
    <p>
      <font color="#008000"><b>postfix reload</b></font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        &#1085;&#1072; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1085;&#1091;&#1078;&#1085;&#1086; &#1073;&#1088;&#1072;&#1090;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; <a href="#ID_1844571578">LDAP</a>&#160; &#1089; AD
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="скрипт mkdovecotpasswd" ID="ID_1571349784" CREATED="1519112080319" MODIFIED="1570734477916"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1089;&#1082;&#1088;&#1080;&#1087;&#1090; &#1076;&#1083;&#1103; &#1079;&#1072;&#1076;&#1072;&#1085;&#1080;&#1103; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>/usr/local/sbin/mkdovecotpasswd</b>&#160;// &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1072;&#1077;&#1084; &#1074; sbin, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;
    </p>
    <p>
      
    </p>
    <p>
      # &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1084; &#1093;&#1077;&#1096;, &#1076;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1074; &#1092;&#1072;&#1081;&#1083;
    </p>
    <p>
      <font color="#008000"><b>mkpasswd --hash=md5 $2 &gt; /tmp/hash</b></font>
    </p>
    <p>
      <font color="#008000"><b>echo &quot;$1:`cat /tmp/hash`&quot; &gt;&gt; /etc/dovecot/passwd</b></font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Проверка работы сервера" ID="ID_1169975061" CREATED="1519112080319" MODIFIED="1519112080319"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. &#1058;&#1077;&#1089;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; postfix</b>
    </p>
    <p>
      <font color="#0000c0"># nc localhost 25</font>
    </p>
    <p>
      <font color="#008000"><b>helo localhost </b></font>
    </p>
    <p>
      <font color="#008000"><b>mail from: &lt;root@localhost&gt;</b></font>&#160;// &#1091;&#1075;&#1083;&#1086;&#1074;&#1099;&#1077; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;
    </p>
    <p>
      <font color="#008000"><b>rcpt to: &lt;info@unix.unix.ru&gt; </b></font>
    </p>
    <p>
      <font color="#008000"><b>data </b></font>
    </p>
    <p>
      <font color="#008000"><b>Hello world! </b></font>
    </p>
    <p>
      <font color="#008000"><b>. </b></font>
    </p>
    <p>
      <b><font color="#008000">quit</font></b>
    </p>
    <p>
      <font color="#0000c0"># tree ~vmail/</font>&#160;// &#1074; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1077; new &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1086;&#1103;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103; &#1092;&#1072;&#1081;&#1083; (&#1101;&#1090;&#1086; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086;)
    </p>
    <p>
      
    </p>
    <p>
      <b>2. &#1058;&#1077;&#1089;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; dovecot</b>
    </p>
    <p>
      <font color="#0000c0"># lsof -i tcp:110</font>&#160;// &#1082;&#1090;&#1086; &#1089;&#1083;&#1091;&#1096;&#1072;&#1077;&#1090; 110 &#1087;&#1086;&#1088;&#1090;, &#1077;&#1089;&#1083;&#1080; dovecot &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1090;&#1086; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1084; &#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1083;&#1086;&#1075;&#1080; cd <b>/var/log/dovecot</b>&#160;&#1080; <b>/var/log/dovecot.info</b>
    </p>
    <p>
      <font color="#0000c0"># nc localhost 110</font><b>&#160;// </b>&#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; pop3
    </p>
    <p>
      <font color="#008000"><b>user info@unix.unix.ru </b></font>
    </p>
    <p>
      <font color="#008000"><b>pass &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;</b></font>&#160;// &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1091;&#1077;&#1084;&#1089;&#1103;
    </p>
    <p>
      <font color="#008000"><b>list </b></font>// &#1087;&#1080;&#1089;&#1100;&#1084;&#1072;<font color="#0000c0">&#160;</font>
    </p>
    <p>
      <font color="#008000"><b>retr 1 </b></font>// &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1087;&#1080;&#1089;&#1100;&#1084;&#1072; 1
    </p>
    <p>
      <font color="#008000"><b>dele 1 </b></font>// &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1087;&#1080;&#1089;&#1100;&#1084;&#1086; 1 (&#1086;&#1090;&#1084;&#1077;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1103;)
    </p>
    <p>
      <font color="#008000"><b>quit </b></font>// &#1074;&#1099;&#1081;&#1090;&#1080;, &#1087;&#1080;&#1089;&#1100;&#1084;&#1072; (&#1086;&#1090;&#1084;&#1077;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1085;&#1072; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077;) &#1091;&#1076;&#1072;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103;
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Postfix+Антивирус (ClamAV)" ID="ID_1953416746" CREATED="1519112080319" MODIFIED="1519112080319"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;.&#160;<a href="#ID_1845130465">Postfix</a>&#160;&#160;&#160;<a href="#ID_1209538949">ClamAV</a>&#160;&#160; <a href="#ID_767054682">/etc/postfix/main.cf</a>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">1.1 # apt-get install <b>clamsmtp</b>&#160;</font>// &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; clamav &#1089; postfix
    </p>
    <p>
      <font color="#0000c0">1.2 # freshclam </font>// &#1086;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1080;&#1075;&#1085;&#1072;&#1090;&#1091;&#1088;&#1099;
    </p>
    <p>
      <font color="#0000c0">2. # vi /etc/postfix/<b>main.cf</b>&#160;</font>// &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1074; &#1092;&#1072;&#1081;&#1083;
    </p>
    <p>
      <font color="#008000"><b>content_filter = scan:127.0.0.1:10026 </b></font>
    </p>
    <p>
      <font color="#008000"><b>receive_override_options = no_address_mappings&#160;&#160;</b></font>
    </p>
    <p>
      <font color="#0000c0">3. # vi /etc/postfix/<b>master.cf</b></font>&#160;// &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1074; &#1092;&#1072;&#1081;&#1083;
    </p>
    <p>
      <font color="#008000"><b># AV scan filter (used by content_filter) </b></font>
    </p>
    <p>
      <font color="#008000"><b>scan&#160;&#160;&#160;&#160;&#160;&#160;unix&#160;&#160;-&#160;&#160;&#160;&#160;&#160;&#160;&#160;-&#160;&#160;&#160;&#160;&#160;&#160;&#160;n&#160;&#160;&#160;&#160;&#160;&#160;&#160;-&#160;&#160;&#160;&#160;&#160;&#160;&#160;16&#160;&#160;&#160;&#160;&#160;&#160;smtp </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-o smtp_send_xforward_command=yes </b></font>
    </p>
    <p>
      <font color="#008000"><b># For injecting mail back into postfix from the filter </b></font>
    </p>
    <p>
      <font color="#008000"><b>127.0.0.1:10025 inet&#160;&#160;n -&#160;&#160;&#160;&#160;&#160;&#160;&#160;n&#160;&#160;&#160;&#160;&#160;&#160;&#160;-&#160;&#160;&#160;&#160;&#160;&#160;&#160;16&#160;&#160;&#160;&#160;&#160;&#160;smtpd </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-o content_filter= </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-o receive_override_options=no_unknown_recipient_checks,no_header_body_checks </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-o smtpd_helo_restrictions= </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-o smtpd_client_restrictions= </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-o smtpd_sender_restrictions= </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-o smtpd_recipient_restrictions=permit_mynetworks,reject </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-o mynetworks_style=host </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;-o smtpd_authorized_xforward_hosts=127.0.0.0/8</b></font>
    </p>
    <p>
      <font color="#0000c0">4.1 # /etc/init.d/postfix restart </font>
    </p>
    <p>
      <font color="#0000c0">4.2 # /etc/init.d/clamsmtp restart </font>
    </p>
    <p>
      <font color="#0000c0">4.3 # /etc/init.d/clamav-daemon restart</font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      https://help.ubuntu.com/community/PostfixVirtualMailBoxClamSmtpHowto
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># grep -i virus /var/log/mail.log</font>&#160;// &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1083;&#1086;&#1075; &#1087;&#1086; &#1074;&#1080;&#1088;&#1091;&#1089;&#1072;&#1084; &#1074; &#1087;&#1086;&#1095;&#1090;&#1077;
    </p>
  </body>
</html></richcontent>
