    <p>
      <b>Microsoft Forefront Threat Management Gateway</b>&#160;(<b>Forefront TMG</b>; &#1088;&#1072;&#1085;&#1077;&#1077; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1081; &#1082;&#1072;&#1082; <b>Microsoft Internet Security and Acceleration Server (ISA Server)</b>) &#8212; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1076;&#1083;&#1103; &#1079;&#1072;&#1097;&#1080;&#1090;&#1099; &#1089;&#1077;&#1090;&#1080; &#1086;&#1090; &#1072;&#1090;&#1072;&#1082; &#1080;&#1079;&#1074;&#1085;&#1077;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;-&#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#171;&#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1072;&#1084; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086; &#1080; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1072;&#1084;&#1080; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1072;, &#1085;&#1077; &#1073;&#1077;&#1089;&#1087;&#1086;&#1082;&#1086;&#1103;&#1089;&#1100; &#1086; &#1074;&#1088;&#1077;&#1076;&#1086;&#1085;&#1086;&#1089;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072;&#1093; &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1091;&#1075;&#1088;&#1086;&#1079;&#1072;&#1093;&#187;
    </p>
    <p>
      
    </p>
    <p>
      9 &#1089;&#1077;&#1085;&#1090;&#1103;&#1073;&#1088;&#1103; 2012 Microsoft &#1086;&#1073;&#1098;&#1103;&#1074;&#1080;&#1083;&#1072; &#1086; <font color="#ff0000">&#1087;&#1088;&#1077;&#1082;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1080; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1081;&#1096;&#1077;&#1075;&#1086; &#1088;&#1072;&#1079;&#1074;&#1080;&#1090;&#1080;&#1103;</font>&#160; Forefront TMG. &#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1072;&#1103; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; &#1073;&#1099;&#1083;&#1072; &#1087;&#1088;&#1077;&#1082;&#1088;&#1072;&#1097;&#1077;&#1085;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; 14 &#1072;&#1087;&#1088;&#1077;&#1083;&#1103; 2015 &#1075;&#1086;&#1076;&#1072;, &#1072; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1085;&#1072;&#1103; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; &#1079;&#1072;&#1082;&#1086;&#1085;&#1095;&#1080;&#1090;&#1089;&#1103; 14 &#1072;&#1087;&#1088;&#1077;&#1083;&#1103; 2020 &#1075;&#1086;&#1076;&#1072;. &#1055;&#1088;&#1086;&#1076;&#1091;&#1082;&#1090; &#1085;&#1077; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1077;&#1085; &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1086;&#1073;&#1088;&#1077;&#1090;&#1077;&#1085;&#1080;&#1103; &#1089; 1 &#1076;&#1077;&#1082;&#1072;&#1073;&#1088;&#1103; 2012 &#1075;&#1086;&#1076;&#1072;[2].
    </p>
  </body>
