<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#ff0000">open proxy !!!</font>
    </p>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1340817715">open relay</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Open proxy</b>&#160;(&#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;) --&gt; <b><font color="#ff0000">&#1087;&#1077;&#1088;&#1077;&#1088;&#1072;&#1089;&#1093;&#1086;&#1076; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; --&gt; &#1089;&#1091;&#1076; --&gt; &#1073;&#1072;&#1085;&#1082;&#1088;&#1086;&#1090;&#1089;&#1090;&#1074;&#1086;</font></b>
    </p>
    <ul>
      <li>
        &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1086;&#1090; &#1083;&#1102;&#1073;&#1099;&#1093; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1074; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1077;
