    </p>
    <p>
      4. &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1092;&#1072;&#1077;&#1088;&#1074;&#1086;&#1083;&#1083; &#1080; &#1091;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1077;&#1075;&#1086; &#1080;&#1079; &#1072;&#1074;&#1090;&#1086;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080;
    </p>
    <p>
      <font color="#0000c0"># service iptables stop </font>
    </p>
    <p>
      <font color="#0000c0"># chkconfig iptables off </font>
    </p>
    <p>
      5. &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084; &#1088;&#1103;&#1076; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1081;, &#1076;&#1083;&#1103; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1080;&#1084;&#1077;&#1085;&#1080; CentOS (&#1080;&#1084;&#1103; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1072;):
