      cd /opt/1C/v8.3/x86_64/
    </p>
    <p>
      &#160;./webinst -apache22 -wsdir pub1 -dir /var/www/pub1 -connStr 'Srvr=&quot;&#1080;&#1084;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; 1&#1057;&quot;;Ref=&quot;&#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1074;&#1072;&#1096;&#1077;&#1081; &#1073;&#1072;&#1079;&#1099; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; 1&#1057;&quot;' -confPath /etc/httpd/conf/httpd.conf
