      &#1055;&#1086;&#1089;&#1083;&#1077; &#1101;&#1090;&#1086; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084; &#1089;&#1072;&#1084; Linux (&#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; reboot), &#1095;&#1090;&#1086;&#1073;&#1099; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; SELINUX &#1074;&#1089;&#1090;&#1091;&#1087;&#1080;&#1083;&#1080; &#1074; &#1089;&#1080;&#1083;&#1091;
    </p>
    <p>
      *&#1045;&#1089;&#1083;&#1080; &#1087;&#1088;&#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1077; web &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1091;&#1075;&#1072;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1102;, &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; nethasp.ini. &#1044;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1086; &#1087;&#1091;&#1090;&#1080; /opt/1C/v8.3/x86_64/ &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1087;&#1082;&#1091; conf &#1080; &#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1090;&#1091;&#1076;&#1072; &#1092;&#1072;&#1081;&#1083; nethasp.ini &#1089; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1077;&#1084; &#1085;&#1072; &#1084;&#1077;&#1085;&#1077;&#1076;&#1078;&#1077;&#1088; &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1087;&#1086;&#1076; Windows. &#1060;&#1072;&#1081;&#1083; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1079;&#1103;&#1090;&#1100; &#1080;&#1079; 1&#1057;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1072; &#1087;&#1086;&#1076; Windows
    </p>
    <p>
      &#1042;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077;! &#1044;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1073;&#1072;&#1079;&#1072; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1083;&#1072; &#1095;&#1077;&#1088;&#1077;&#1079; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1076;&#1083;&#1103; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1081; &#1073;&#1072;&#1079;&#1099; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#171;&#1074;&#1099;&#1076;&#1072;&#1095;&#1072; &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084;&#187;. &#1048;&#1085;&#1072;&#1095;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1090;&#1086;&#1085;&#1082;&#1080;&#1081; &#1080;&#1083;&#1080; &#1090;&#1086;&#1083;&#1089;&#1090;&#1099;&#1081; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;.
    </p>
