      <li>
        &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; <b>&#1053;&#1086;&#1084;&#1077;&#1088;&#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;&#1055;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1097;&#1080;&#1082;&#1072;</b>&#160;(&#1058;&#1080;&#1087;: &#1057;&#1090;&#1088;&#1086;&#1082;&#1072;)
      </li>
      <li>
        &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; <b>&#1044;&#1072;&#1090;&#1072;&#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;&#1055;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1097;&#1080;&#1082;&#1072;</b>&#160; (&#1058;&#1080;&#1087;: &#1044;&#1072;&#1090;&#1072;)
      </li>
      <li>
        1. &#1055;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1103; &gt; <b>&#1057;&#1087;&#1086;&#1089;&#1086;&#1073;&#1099;&#1054;&#1087;&#1083;&#1072;&#1090;&#1099;</b>&#160;\ &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; &gt; &#1053;&#1072;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077;, &#1041;&#1077;&#1079;&#1085;&#1072;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077;, &#1069;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1085;&#1085;&#1099;&#1077;&#1044;&#1077;&#1085;&#1100;&#1075;&#1080;<br/>2. &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; <b>&#1057;&#1087;&#1086;&#1089;&#1086;&#1073;&#1054;&#1087;&#1083;&#1072;&#1090;&#1099;</b>&#160;(&#1058;&#1080;&#1087;: &#1055;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1077;&#1057;&#1089;&#1099;&#1083;&#1082;&#1072;.&#1057;&#1087;&#1086;&#1089;&#1086;&#1073;&#1099;&#1054;&#1087;&#1083;&#1072;&#1090;&#1099;)
