      </li>
    </ul>
    <p>
      2. &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &gt; &#1055;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1077;&#1044;&#1077;&#1085;&#1077;&#1078;&#1085;&#1099;&#1093;&#1057;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074; \ &#1060;&#1086;&#1088;&#1084;&#1099; &gt; &#1060;&#1086;&#1088;&#1084;&#1072;&#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072; - <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1092;&#1086;&#1088;&#1084;&#1099;</b>
    </p>
    <ul>
      <li>
        &#1057;&#1075;&#1088;&#1091;&#1087;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1053;&#1086;&#1084;&#1077;&#1088; &#1089; &#1044;&#1072;&#1090;&#1086;&#1081;. <b>&#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1043;&#1088;&#1091;&#1087;&#1087;&#1072;&#1053;&#1086;&#1084;&#1077;&#1088;&#1044;&#1072;&#1090;&#1072;</b>&#160;(&#1043;&#1088;&#1091;&#1087;&#1087;&#1072; &#1086;&#1073;&#1099;&#1095;&#1085;&#1072;&#1103; &#1073;&#1077;&#1079; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;; &#1043;&#1088;&#1091;&#1087;&#1087;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;: &#1075;&#1086;&#1088;&#1080;&#1079;&#1086;&#1085;&#1090;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103;)
      </li>
      <li>
        <b>&#1057;&#1087;&#1086;&#1089;&#1086;&#1073;&#1054;&#1087;&#1083;&#1072;&#1090;&#1099;</b>&#160;(&#1042;&#1080;&#1076;:&#1055;&#1086;&#1083;&#1077; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1077;&#1083;&#1103;; &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; \ &#1057;&#1087;&#1080;&#1089;&#1086;&#1082;&#1042;&#1099;&#1073;&#1086;&#1088;&#1072; &gt; &#1047;&#1072;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100;; &#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086;&#1050;&#1086;&#1083;&#1086;&#1085;&#1086;&#1082;:1). &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;&#1043;&#1088;&#1091;&#1087;&#1087;&#1099; \ &#1054;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; &gt; &#1057;&#1080;&#1083;&#1100;&#1085;&#1086;&#1077; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077;
      </li>
    </ul>
    <p>
      3. &#1053;&#1086;&#1084;&#1077;&#1088; &#1087;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1097;&#1080;&#1082;&#1080; &#1080; &#1086;&#1087;&#1083;&#1072;&#1090;&#1072; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1073;&#1077;&#1079;&#1085;&#1072;&#1083;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1087;&#1083;&#1072;&#1090;&#1077;&#1078;&#1072;
    </p>
    <ul>
      <li>
        &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &gt; &#1055;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1077;&#1044;&#1077;&#1085;&#1077;&#1078;&#1085;&#1099;&#1093;&#1057;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074; \ &#1060;&#1086;&#1088;&#1084;&#1099; &gt; &#1060;&#1086;&#1088;&#1084;&#1072;&#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072; \ &#1060;&#1086;&#1088;&#1084;&#1072; (&#1082;&#1086;&#1088;&#1085;&#1077;&#1074;&#1072;&#1103;) \ <b>&#1057;&#1087;&#1086;&#1089;&#1086;&#1073;&#1054;&#1087;&#1083;&#1072;&#1090;&#1099;</b>&#160;\ &#1057;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103; &gt; <b>&#1055;&#1088;&#1080;&#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080;</b>&#160;
      </li>
      <li>
