      </li>
      <li>
        &#1060;&#1086;&#1088;&#1084;&#1072; \ &#1050;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1088; \ &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; \ &#1057;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103; (&#1055;&#1088;&#1080;&#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080;) &gt; <b>&#1050;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1055;&#1088;&#1080;&#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080;</b>&#160;&#160;- &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; <b>&#1087;&#1086;&#1089;&#1083;&#1077; &#1074;&#1089;&#1090;&#1072;&#1074;&#1082;&#1080;</b>&#160;&#1085;&#1080;&#1078;&#1077;&#1089;&#1090;&#1086;&#1103;&#1097;&#1077;&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;
      </li>
