  <body>
    <p>
      <b>&#1055;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1077; &#1090;&#1086;&#1074;&#1072;&#1088;&#1086;&#1074; - </b>&#1072;&#1085;&#1072;&#1083;&#1086;&#1075; &#1073;&#1091;&#1084;&#1072;&#1078;&#1085;&#1086;&#1081; <b>&#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1085;&#1086;&#1081; &#1085;&#1072;&#1082;&#1083;&#1072;&#1076;&#1085;&#1086;&#1081;</b>
    </p>
    <p>
      1. &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &gt; &#1055;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1077;&#1058;&#1086;&#1074;&#1072;&#1088;&#1086;&#1074;
    </p>
    <ul>
      <li>
        &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; <b>&#1050;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;</b>&#160;(&#1058;&#1080;&#1087; \ &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1057;&#1089;&#1099;&#1083;&#1082;&#1072;.&#1050;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1099;)
      </li>
      <li>
        &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; <b>&#1044;&#1086;&#1075;&#1086;&#1074;&#1086;&#1088;&#1050;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1072;</b>&#160;(&#1058;&#1080;&#1087;: &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1057;&#1089;&#1099;&#1083;&#1082;&#1072;.&#1044;&#1086;&#1075;&#1086;&#1074;&#1086;&#1088;&#1099;&#1050;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074;)
      </li>
      <li>
        &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; <b>&#1044;&#1086;&#1075;&#1086;&#1074;&#1086;&#1088;&#1050;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1072;</b>&#160;\ &#1055;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; \ <b>&#1057;&#1074;&#1103;&#1079;&#1080; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1074;&#1099;&#1073;&#1086;&#1088;&#1072;</b>&#160;(&#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089;&#1074;&#1103;&#1079;&#1100; &#1084;&#1077;&#1078;&#1076;&#1091; &#1088;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1072;&#1084;&#1080; - &#1054;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100; &#1074; &#1092;&#1086;&#1088;&#1084;&#1077; &#1076;&#1086;&#1075;&#1086;&#1074;&#1086;&#1088;&#1099; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1072;) --&gt; &#1050;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090; (&#1048;&#1084;&#1103;: &#1054;&#1090;&#1073;&#1086;&#1088;.&#1042;&#1083;&#1072;&#1076;&#1077;&#1083;&#1077;&#1094;)
      </li>
      <li>
        <b>&#1058;&#1072;&#1073;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077; &#1095;&#1072;&#1089;&#1090;&#1080;</b>&#160; &gt; &#1058;&#1086;&#1074;&#1072;&#1088;&#1099; &gt; &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt;

        <ul>
          <li>
            &#1053;&#1086;&#1084;&#1077;&#1085;&#1082;&#1083;&#1072;&#1090;&#1091;&#1088;&#1072; (&#1058;&#1080;&#1087;: &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1057;&#1089;&#1099;&#1083;&#1082;&#1072;.&#1053;&#1086;&#1084;&#1077;&#1085;&#1082;&#1083;&#1072;&#1090;&#1091;&#1088;&#1072;)
          </li>
          <li>
            &#1062;&#1077;&#1085;&#1072; (&#1058;&#1080;&#1087;:&#1063;&#1080;&#1089;&#1083;&#1086;; &#1044;&#1083;&#1080;&#1085;&#1072;:15; &#1058;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;:2; &#1053;&#1077;&#1086;&#1090;&#1088;&#1080;&#1094;.)
          </li>
          <li>
            &#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; (&#1058;&#1080;&#1087;:&#1063;&#1080;&#1089;&#1083;&#1086;; &#1044;&#1083;&#1080;&#1085;&#1072;:15; &#1058;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;:3; &#1053;&#1077;&#1086;&#1090;&#1088;&#1080;&#1094;.)
          </li>
          <li>
            &#1057;&#1091;&#1084;&#1084;&#1072; (&#1058;&#1080;&#1087;:&#1063;&#1080;&#1089;&#1083;&#1086;; &#1044;&#1083;&#1080;&#1085;&#1072;:15; &#1058;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;:2; &#1053;&#1077;&#1086;&#1090;&#1088;&#1080;&#1094;.)
          </li>
        </ul>
      </li>
    </ul>
    <p>
      2. &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &gt; &#1055;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1077;&#1058;&#1086;&#1074;&#1072;&#1088;&#1086;&#1074; \ &#1060;&#1086;&#1088;&#1084;&#1099; &gt; &#1060;&#1086;&#1088;&#1084;&#1072;&#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072; - <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1092;&#1086;&#1088;&#1084;&#1099;</b>
    </p>
    <ul>
      <li>
        &#1057;&#1075;&#1088;&#1091;&#1087;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1053;&#1086;&#1084;&#1077;&#1088; &#1089; &#1044;&#1072;&#1090;&#1086;&#1081;. <b>&#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1043;&#1088;&#1091;&#1087;&#1087;&#1072;&#1053;&#1086;&#1084;&#1077;&#1088;&#1044;&#1072;&#1090;&#1072;</b>&#160;(&#1043;&#1088;&#1091;&#1087;&#1087;&#1072; &#1086;&#1073;&#1099;&#1095;&#1085;&#1072;&#1103; &#1073;&#1077;&#1079; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;; &#1043;&#1088;&#1091;&#1087;&#1087;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;: &#1075;&#1086;&#1088;&#1080;&#1079;&#1086;&#1085;&#1090;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103;)
      </li>
      <li>
        <b>&#1048;&#1090;&#1086;&#1075;&#1086;&#1074;&#1072;&#1103; &#1089;&#1091;&#1084;&#1084;&#1072;</b>. &#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1058;&#1086;&#1074;&#1072;&#1088;&#1099; \ &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; \ <b>&#1055;&#1086;&#1076;&#1074;&#1072;&#1083;</b>; &lt;&#1083;&#1102;&#1073;&#1072;&#1103; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1103;&gt; / &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; / &#1058;&#1077;&#1082;&#1089;&#1090;&#1055;&#1086;&#1076;&#1074;&#1072;&#1083;&#1072; &gt; <b>&#1048;&#1058;&#1054;&#1043;&#1054;</b>; &#160;&#1058;&#1086;&#1074;&#1072;&#1088;&#1099;&#1057;&#1091;&#1084;&#1084;&#1072; \ &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; \ &#1055;&#1091;&#1090;&#1100;&#1050;&#1044;&#1072;&#1085;&#1085;&#1099;&#1084;&#1055;&#1086;&#1076;&#1074;&#1072;&#1083;&#1072; \ &#1054;&#1073;&#1098;&#1077;&#1082;&#1090; \ &#1058;&#1086;&#1074;&#1072;&#1088;&#1099; \ <b>&#1048;&#1090;&#1086;&#1075;&#1057;&#1091;&#1084;&#1084;&#1072;</b>
      </li>
      <li>
        <b>&#1056;&#1072;&#1089;&#1095;&#1077;&#1090; &#1089;&#1091;&#1084;&#1084;&#1099; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1080;</b>. &#1060;&#1086;&#1088;&#1084;&#1072;(&#1082;&#1086;&#1088;&#1085;&#1077;&#1074;&#1072;&#1103;) \ &#1058;&#1086;&#1074;&#1072;&#1088;&#1062;&#1077;&#1085;&#1072; \ &#1057;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103; &gt; &#1055;&#1088;&#1080;&#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080;
      </li>
      <li>
        &#1056;&#1072;&#1089;&#1095;&#1077;&#1090; &#1089;&#1091;&#1084;&#1084;&#1099; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1080;. &#1060;&#1086;&#1088;&#1084;&#1072;(&#1082;&#1086;&#1088;&#1085;&#1077;&#1074;&#1072;&#1103;) \ &#1058;&#1086;&#1074;&#1072;&#1088;&#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; \ &#1057;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103; &gt; &#1055;&#1088;&#1080;&#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080;
      </li>
    </ul>
    <p>
      <font color="#008000">&amp;&#1053;&#1072;&#1050;&#1083;&#1080;&#1077;&#1085;&#1090;&#1077; </font>
    </p>
    <p>
      <font color="#008000">&#1055;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1072; <b>&#1058;&#1086;&#1074;&#1072;&#1088;&#1099;&#1062;&#1077;&#1085;&#1072;&#1055;&#1088;&#1080;&#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080;</b>(&#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;.&#1058;&#1086;&#1074;&#1072;&#1088;&#1099;.&#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077;.&#1057;&#1091;&#1084;&#1084;&#1072; = &#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;.&#1058;&#1086;&#1074;&#1072;&#1088;&#1099;.&#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077;.&#1062;&#1077;&#1085;&#1072; * &#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;.&#1058;&#1086;&#1074;&#1072;&#1088;&#1099;.&#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077;.&#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086;; </font>
    </p>
    <p>
      <font color="#008000">&#1050;&#1086;&#1085;&#1077;&#1094;&#1055;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1099; </font>
    </p>
    <p>
      
