    <p>
      <font color="#008000">&#1055;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1072; <b>&#1058;&#1086;&#1074;&#1072;&#1088;&#1099;&#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086;&#1055;&#1088;&#1080;&#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080;</b>(&#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077; = &#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;.&#1058;&#1086;&#1074;&#1072;&#1088;&#1099;.&#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077;; </font>&#160;// &#1057;&#1089;&#1099;&#1083;&#1082;&#1072;. &#1047;&#1072;&#1076;&#1072;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077;.&#1057;&#1091;&#1084;&#1084;&#1072; = &#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077;.&#1062;&#1077;&#1085;&#1072; * &#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077;.&#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086;;&#160; </font>// &#1040;&#1085;&#1072;&#1083;&#1086;&#1075; &#1074;&#1077;&#1088;&#1093;&#1085;&#1077;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1099;
    </p>
    <p>
      <font color="#008000">&#1050;&#1086;&#1085;&#1077;&#1094;&#1055;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1099;</font>
    </p>
    <p>
      3. &#1054;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100; &#1089;&#1091;&#1084;&#1084;&#1091; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1085;&#1072;&#1082;&#1083;&#1072;&#1076;&#1085;&#1086;&#1081; &#1074; &#1089;&#1087;&#1080;&#1089;&#1082;&#1077;.
    </p>
    <ul>
      <li>
        &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; \&#160;&#160;&#1055;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1077;&#1058;&#1086;&#1074;&#1072;&#1088;&#1086;&#1074; \ &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; &#1057;&#1091;&#1084;&#1084;&#1072;&#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;
      </li>
      <li>
        &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; \&#160;&#160;&#1055;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1077;&#1058;&#1086;&#1074;&#1072;&#1088;&#1086;&#1074; \ &#1055;&#1088;&#1086;&#1095;&#1077;&#1077; \ &#1052;&#1086;&#1076;&#1091;&#1083;&#1100; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;<br/>&#1058;&#1077;&#1082;&#1089;&#1090; \ &#1055;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1099; &#1080; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &gt; &#1055;&#1077;&#1088;&#1077;&#1076;&#1047;&#1072;&#1087;&#1080;&#1089;&#1100;&#1102;
      </li>
