    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#1057;&#1091;&#1084;&#1084;&#1072;&#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072; = &#1058;&#1086;&#1074;&#1072;&#1088;&#1099;.&#1048;&#1090;&#1086;&#1075;(&quot;&#1057;&#1091;&#1084;&#1084;&#1072;&quot;); </font>
