      </li>
      <li>
        &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; <b>&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081;</b>&#160; (&#1058;&#1080;&#1087;: &#1041;&#1091;&#1083;&#1077;&#1074;&#1086;)
