      <li>
        &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; <b>&#1050;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1081;</b>&#160;(&#1058;&#1080;&#1087;: &#1057;&#1090;&#1088;&#1086;&#1082;&#1072;, &#1053;&#1077;&#1086;&#1075;&#1088;.)
      </li>
      <li>
        <b>&#1058;&#1072;&#1073;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077; &#1095;&#1072;&#1089;&#1090;&#1080; &gt;</b>&#160;<b>&#1058;&#1086;&#1074;&#1072;&#1088;&#1099;</b>&#160;&gt; &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt;

        <ul>
          <li>
            &#1053;&#1086;&#1084;&#1077;&#1085;&#1082;&#1083;&#1072;&#1090;&#1091;&#1088;&#1072; (&#1058;&#1080;&#1087;: &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1057;&#1089;&#1099;&#1083;&#1082;&#1072;.&#1053;&#1086;&#1084;&#1077;&#1085;&#1082;&#1083;&#1072;&#1090;&#1091;&#1088;&#1072;)
