            &#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; (&#1058;&#1080;&#1087;:&#1063;&#1080;&#1089;&#1083;&#1086;; &#1044;&#1083;&#1080;&#1085;&#1072;:15; &#1058;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;:3; &#1053;&#1077;&#1086;&#1090;&#1088;&#1080;&#1094;.)
          </li>
