        <ul>
          <li>
            &#1053;&#1086;&#1084;&#1077;&#1085;&#1082;&#1083;&#1072;&#1090;&#1091;&#1088;&#1072; (&#1058;&#1080;&#1087;: &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1057;&#1089;&#1099;&#1083;&#1082;&#1072;.&#1053;&#1086;&#1084;&#1077;&#1085;&#1082;&#1083;&#1072;&#1090;&#1091;&#1088;&#1072;)
          </li>
          <li>
            &#1057;&#1091;&#1084;&#1084;&#1072; (&#1058;&#1080;&#1087;:&#1063;&#1080;&#1089;&#1083;&#1086;; &#1044;&#1083;&#1080;&#1085;&#1072;:15; &#1058;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;:2; &#1053;&#1077;&#1086;&#1090;&#1088;&#1080;&#1094;.)
