    <p>
      2. &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &gt; &#1056;&#1072;&#1089;&#1093;&#1086;&#1076;&#1085;&#1072;&#1103;&#1053;&#1072;&#1082;&#1083;&#1072;&#1076;&#1085;&#1072;&#1103; \ &#1060;&#1086;&#1088;&#1084;&#1099; &gt; &#1060;&#1086;&#1088;&#1084;&#1072;&#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072; - <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1092;&#1086;&#1088;&#1084;&#1099;</b>
    </p>
    <ul>
      <li>
        <b>&#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1079;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1091;</b>. &#1060;&#1086;&#1088;&#1084;&#1072; \ &#1057;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; (&#1090;&#1080;&#1087; &#1089; &#1079;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1072;&#1084;&#1080;) \ &#1057;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; (&#1079;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080;).<br/>&#1060;&#1086;&#1088;&#1084;&#1072; \ &#1057;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &gt;&#160;&#1043;&#1088;&#1091;&#1087;&#1087;&#1072;-&#1057;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; &gt; &#1043;&#1088;&#1091;&#1087;&#1087;&#1072;&#1055;&#1088;&#1086;&#1095;&#1077;&#1077;. &#1055;&#1077;&#1088;&#1077;&#1090;&#1072;&#1089;&#1082;&#1080;&#1074;&#1072;&#1077;&#1084; &#1090;&#1091;&#1076;&#1072; &#1088;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090; &quot;<b>&#1050;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1081;</b>&quot; (&#1052;&#1085;&#1086;&#1075;&#1086;&#1089;&#1090;&#1088;&#1086;&#1095;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;:&#1044;&#1072;)
      </li>
      <li>
        &#1057;&#1075;&#1088;&#1091;&#1087;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1053;&#1086;&#1084;&#1077;&#1088; &#1089; &#1044;&#1072;&#1090;&#1086;&#1081;. <b>&#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1043;&#1088;&#1091;&#1087;&#1087;&#1072;&#1053;&#1086;&#1084;&#1077;&#1088;&#1044;&#1072;&#1090;&#1072;</b>&#160;(&#1043;&#1088;&#1091;&#1087;&#1087;&#1072; &#1086;&#1073;&#1099;&#1095;&#1085;&#1072;&#1103; &#1073;&#1077;&#1079; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;; &#1043;&#1088;&#1091;&#1087;&#1087;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;: &#1075;&#1086;&#1088;&#1080;&#1079;&#1086;&#1085;&#1090;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103;)
      </li>
      <li>
        <b>&#1048;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1082;</b>&#160;&#1085;&#1072; &#1092;&#1086;&#1088;&#1084;&#1077;. &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; \ &#1047;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1082; --&gt; &#1042;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1084;&#1099;&#1081;
      </li>
      <li>
        <b>&#1042;&#160;&#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077; &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1100; &#1076;&#1074;&#1077; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1080; &#1087;&#1086; &#1074;&#1077;&#1088;&#1090;&#1080;&#1082;&#1072;&#1083;&#1080;</b>&#160;&gt; &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1043;&#1088;&#1091;&#1087;&#1087;&#1072; - &#1043;&#1088;&#1091;&#1087;&#1087;&#1072; &#1082;&#1086;&#1083;&#1086;&#1085;&#1086;&#1082; &gt; &#1087;&#1077;&#1088;&#1077;&#1090;&#1072;&#1089;&#1082;&#1080;&#1074;&#1072;&#1077;&#1084; &#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1084;&#1099;&#1077; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1080;. &#1062;&#1077;&#1085;&#1072; &#1080; &#1057;&#1091;&#1084;&#1084;&#1072;; &#1057;&#1090;&#1072;&#1074;&#1082;&#1072; &#1053;&#1044;&#1057; &#1080; &#1057;&#1091;&#1084;&#1084;&#1072; &#1053;&#1044;&#1057;
      </li>
      <li>
        <b>&#1048;&#1090;&#1086;&#1075;&#1086;&#1074;&#1072;&#1103; &#1089;&#1091;&#1084;&#1084;&#1072;</b>. &#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1058;&#1086;&#1074;&#1072;&#1088;&#1099; \ &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; \ <b>&#1055;&#1086;&#1076;&#1074;&#1072;&#1083;</b>; &lt;&#1083;&#1102;&#1073;&#1072;&#1103; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1103;&gt; / &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; / &#1058;&#1077;&#1082;&#1089;&#1090;&#1055;&#1086;&#1076;&#1074;&#1072;&#1083;&#1072; &gt; <b>&#1048;&#1058;&#1054;&#1043;&#1054;</b>; &#160;&#1058;&#1086;&#1074;&#1072;&#1088;&#1099;&#1057;&#1091;&#1084;&#1084;&#1072; \ &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; \ &#1055;&#1091;&#1090;&#1100;&#1050;&#1044;&#1072;&#1085;&#1085;&#1099;&#1084;&#1055;&#1086;&#1076;&#1074;&#1072;&#1083;&#1072; \ &#1054;&#1073;&#1098;&#1077;&#1082;&#1090; \ &#1058;&#1086;&#1074;&#1072;&#1088;&#1099; \ <b>&#1048;&#1090;&#1086;&#1075;&#1057;&#1091;&#1084;&#1084;&#1072;</b>
      </li>
      <li>
        &#1055;&#1088;&#1080; &#1074;&#1099;&#1073;&#1086;&#1088;&#1077; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1072; &#1074;&#1080;&#1076;&#1077;&#1090;&#1100; <b>&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1097;&#1080;&#1093;</b>&#160;(&#1085;&#1077; &#1059;&#1074;&#1086;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093;).<br/>1. &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; \ &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; \ &#1057;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082; \ &#1055;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; \ &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1074;&#1099;&#1073;&#1086;&#1088;&#1072; &gt; &#1054;&#1090;&#1073;&#1086;&#1088;.&#1056;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;:&#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1057;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1080; &gt; &#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1097;&#1080;&#1077;<br/>2. &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1092;&#1086;&#1088;&#1084;&#1091;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &#1074;&#1080;&#1076;&#1085;&#1086; &#1080;&#1077;&#1088;&#1072;&#1088;&#1093;&#1080;&#1081;: &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1080; \ &#1057;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1080; \ &#1060;&#1086;&#1088;&#1084;&#1099; &gt; &#1058;&#1080;&#1087;:&#1060;&#1086;&#1088;&#1084;&#1072; &#1074;&#1099;&#1073;&#1086;&#1088;&#1072; &#1089;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072; (&#1053;&#1045; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1084; &#1092;&#1086;&#1088;&#1084;&#1091; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081;); &#1048;&#1084;&#1103;:<b>&#1060;&#1086;&#1088;&#1084;&#1072;&#1042;&#1099;&#1073;&#1086;&#1088;&#1072;&#1041;&#1077;&#1079;&#1043;&#1088;&#1091;&#1087;&#1087;</b>&#160;&gt; &#160;<b>&#1060;&#1086;&#1088;&#1084;&#1072;</b>&#160;(&#1082;&#1086;&#1088;&#1085;&#1077;&#1074;&#1072;&#1103;) \ &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; \ &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; \ &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; \ &#1054;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; &gt; <b>&#1057;&#1087;&#1080;&#1089;&#1086;&#1082;</b><br/>3. &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; \ &#1057;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082; \ &#1055;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; \ &#1060;&#1086;&#1088;&#1084;&#1072; &#1074;&#1099;&#1073;&#1086;&#1088;&#1072; &gt; <b>&#1060;&#1086;&#1088;&#1084;&#1072;&#1042;&#1099;&#1073;&#1086;&#1088;&#1072;&#1041;&#1077;&#1079;&#1043;&#1088;&#1091;&#1087;&#1087;</b>
      </li>
      <li>
        <b>&#1042; &#1090;&#1086;&#1074;&#1072;&#1088;&#1072;&#1093; &#1074;&#1080;&#1076;&#1080;&#1084; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1090;&#1086;&#1074;&#1072;&#1088;&#1099;</b>, &#1074; &#1091;&#1089;&#1083;&#1091;&#1075;&#1072;&#1093; - &#1091;&#1089;&#1083;&#1091;&#1075;&#1080;. &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &gt; &#1056;&#1072;&#1089;&#1093;&#1086;&#1076;&#1085;&#1072;&#1103;&#1053;&#1072;&#1082;&#1083;&#1072;&#1076;&#1085;&#1072;&#1103; \ &#1058;&#1072;&#1073;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077; &#1095;&#1072;&#1089;&#1090;&#1080; \ <b>&#1058;&#1086;&#1074;&#1072;&#1088;&#1099;</b>&#160;\ &#1053;&#1086;&#1084;&#1077;&#1085;&#1082;&#1083;&#1072;&#1090;&#1091;&#1088;&#1072; \ &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; \ &#1055;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; \ &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1074;&#1099;&#1073;&#1086;&#1088;&#1072; &gt; <b>&#1054;&#1090;&#1073;&#1086;&#1088;.&#1059;&#1089;&#1083;&#1091;&#1075;&#1072; (&#1041;&#1091;&#1083;&#1077;&#1074;&#1086;.&#1051;&#1086;&#1078;&#1100;)</b>
      </li>
      <li>
        <b>&#1047;&#1072;&#1087;&#1088;&#1077;&#1090; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;</b>&#160;&#1082;&#1086;&#1083;&#1086;&#1085;&#1086;&#1082; &#1057;&#1091;&#1084;&#1084;&#1072;, &#1057;&#1091;&#1084;&#1084;&#1072; &#1053;&#1044;&#1057;, &#1042;&#1089;&#1077;&#1075;&#1086;. &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &gt; <b>&#1058;&#1086;&#1083;&#1100;&#1082;&#1086;&#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;</b>
      </li>
      <li>
        &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1082;&#1086;&#1083;&#1086;&#1085;&#1082;&#1091; &quot;<b>&#1057;&#1091;&#1084;&#1084;&#1072;</b>&quot; &#1074; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1056;&#1072;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1085;&#1072;&#1082;&#1083;&#1072;&#1076;&#1085;&#1099;&#1093;. &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; \ &#1056;&#1072;&#1089;&#1093;&#1086;&#1076;&#1085;&#1072;&#1103;&#1053;&#1072;&#1082;&#1083;&#1072;&#1076;&#1085;&#1072;&#1103; \ &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; &#1057;&#1091;&#1084;&#1084;&#1072; (&#1058;&#1080;&#1087;:&#1063;&#1080;&#1089;&#1083;&#1086;; &#1044;&#1083;&#1080;&#1085;&#1072;:15; &#1058;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;:2; &#1053;&#1077;&#1086;&#1090;&#1088;&#1080;&#1094;.)<br/>1. &#1044;&#1083;&#1103; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1089;&#1091;&#1084;&#1084;&#1099; &#1087;&#1080;&#1096;&#1077;&#1084; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1095;&#1080;&#1082; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103;: &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; \ &#1056;&#1072;&#1089;&#1093;&#1086;&#1076;&#1085;&#1072;&#1103;&#1053;&#1072;&#1082;&#1083;&#1072;&#1076;&#1085;&#1072;&#1103; \ &#1055;&#1088;&#1086;&#1095;&#1077;&#1077; \ &#1052;&#1086;&#1076;&#1091;&#1083;&#1100; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072; &gt;&#160;&#1055;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1099; &#1080; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &gt; <b>&#1055;&#1077;&#1088;&#1077;&#1076;&#1047;&#1072;&#1087;&#1080;&#1089;&#1100;&#1102;.</b>&#160; &#1055;&#1086;&#1089;&#1083;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1087;&#1088;&#1086;&#1074;&#1077;&#1089;&#1090;&#1080; &#1074;&#1089;&#1077; &#1091;&#1095;&#1077;&#1090;&#1085;&#1099;&#1077; &#1076;&#1086;&#1082;&#1091;&#1084;&#10