    </p>
    <p>
      3. &#1054;&#1073;&#1097;&#1080;&#1077; \ &#1055;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; \ &#1055;&#1088;&#1086;&#1095;&#1077;&#1077; &gt; &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1095;&#1080;&#1085;&#1077;&#1085;&#1085;&#1091;&#1102; &#1087;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091; &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1080;, &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;, &#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1099;, &#1054;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080;, &#1050;&#1086;&#1085;&#1089;&#1090;&#1072;&#1085;&#1090;&#1099;
    </p>
    <p>
      4. &#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; (&#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;, &#1082;&#1086;&#1085;&#1089;&#1090;&#1072;&#1085;&#1090;&#1099;, &#1089;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1080;) &#1074; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1095;&#1077;&#1088;&#1077;&#1079; &#1055;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1080;&#1083;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1072;&#1084;&#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; (&#1079;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1072; &#1055;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;). &#1058;&#1072;&#1082;&#1078;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; &lt;&#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1082;&#1086;&#1085;&#1092;.&gt; \ &#1044;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; \ &#1055;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;
    </p>
    <ul>
      <li>
        &#1055;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; \ &#1047;&#1072;&#1082;&#1091;&#1087;&#1082;&#1080; \ &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1080; \ &#1057;&#1086;&#1089;&#1090;&#1072;&#1074; \ &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1080; (&#1053;&#1086;&#1084;&#1077;&#1085;&#1082;&#1083;&#1072;&#1090;&#1091;&#1088;&#1072;, &#1050;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1099;, &#1044;&#1086;&#1075;&#1086;&#1074;&#1086;&#1088;&#1099;&#1050;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074;)
      </li>
      <li>
        &#1050;&#1086;&#1085;&#1089;&#1090;&#1072;&#1085;&#1090;&#1099; \ &#1053;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077;&#1054;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;, &#1048;&#1053;&#1053;, &#1044;&#1072;&#1090;&#1072;&#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080;, &#1043;&#1077;&#1085;&#1077;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081;&#1044;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;, &#1042;&#1072;&#1083;&#1102;&#1090;&#1085;&#1099;&#1081;&#1059;&#1095;&#1077;&#1090; \ &#1044;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; \ &#1055;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &gt; &#1055;&#1088;&#1086;&#1095;&#1077;&#1077;\&#1050;&#1086;&#1085;&#1089;&#1090;&#1072;&#1085;&#1090;&#1099;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      &#1057;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; <b>&#1080;&#1082;&#1086;&#1085;&#1082;&#1091; &#1074; &#1075;&#1083;&#1072;&#1074;&#1085;&#1086;&#1084; &#1084;&#1077;&#1085;&#1102;</b>. &#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1087;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; \ &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; \ &#1050;&#1072;&#1088;&#1090;&#1080;&#1085;&#1082;&#1072;
    </p>
  </body>
