    <p>
      &#1050;&#1090;&#1086;, <b>&#1085;&#1072; &#1082;&#1072;&#1082;&#1091;&#1102; &#1076;&#1072;&#1090;&#1091;</b>, &#1074; &#1082;&#1072;&#1082;&#1086;&#1084; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1083;?<br/>1. &#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1099; &#1089;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1081; &gt; <b>&#1057;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1080;&#1055;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1081;</b>&#160;(&#1055;&#1077;&#1088;&#1080;&#1086;&#1076;&#1080;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;:&#1042; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1076;&#1085;&#1103;)<br/>2.&#160;&#160;&#160;&#1055;&#1086;&#1076;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; \ &#1055;&#1088;&#1086;&#1095;&#1077;&#1077; \ &#1056;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1099; (&#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1086; &#1088;&#1072;&#1085;&#1077;&#1077;)<br/>3. &#160;&#160;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077; \ <b>&#1048;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103;</b>&#160;&gt; &#1057;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082; (&#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1057;&#1089;&#1099;&#1083;&#1082;&#1072;.&#1057;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1080;)<br/>4. &#160;&#160;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077; \ <b>&#1056;&#1077;&#1089;&#1091;&#1088;&#1089;&#1099;</b>&#160;&gt; &#1055;&#1086;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; (&#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1057;&#1089;&#1099;&#1083;&#1082;&#1072;.&#1055;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103;)<br/>5. &#160;&#160;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077; \ <b>&#1056;&#1077;&#1089;&#1091;&#1088;&#1089;&#1099;</b>&#160;&gt; &#1054;&#1082;&#1083;&#1072;&#1076; (&#1058;&#1080;&#1087;: &#1063;&#1080;&#1089;&#1083;&#1086;; &#1044;&#1083;&#1080;&#1085;&#1072;:15; &#1058;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;:2; &#1053;&#1077;&#1086;&#1090;&#1088;&#1080;&#1094;.)
    </p>
    <p>
      &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &gt; &#1050;&#1072;&#1076;&#1088;&#1086;&#1074;&#1099;&#1081;&#1055;&#1088;&#1080;&#1082;&#1072;&#1079;
    </p>
    <ul>
