      </li>
      <li>
        &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; \ &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; &#1055;&#1086;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; (&#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1057;&#1089;&#1099;&#1083;&#1082;&#1072;.&#1055;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103;)<br/>
      </li>
      <li>
        &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; \ &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; &#1054;&#1082;&#1083;&#1072;&#1076; (&#1058;&#1080;&#1087;: &#1063;&#1080;&#1089;&#1083;&#1086;; &#1044;&#1083;&#1080;&#1085;&#1072;:15; &#1058;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;:2; &#1053;&#1077;&#1086;&#1090;&#1088;&#1080;&#1094;.)<br/>
      </li>
      <li>
        &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; \ &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; &gt; &#1044;&#1072;&#1090;&#1072;&#1055;&#1088;&#1080;&#1077;&#1084;&#1072; (&#1058;&#1080;&#1087;:&#1044;&#1072;&#1090;&#1072;)<br/>
