    </p>
    <p>
      8.2, 8.3 (&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084;&#1099;&#1077; &#1092;&#1086;&#1088;&#1084;&#1099;)
    </p>
    <ul>
      <li>
        &#1060;&#1086;&#1088;&#1084;&#1072; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1080; &#1085;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1077; &#1080; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;
      </li>
      <li>
        &#1060;&#1086;&#1088;&#1084;&#1072; &#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089; &#1087;&#1088;&#1080;&#1082;&#1083;&#1072;&#1076;&#1085;&#1099;&#1084;&#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;&#1084;&#1080;. &#1055;&#1088;&#1080;&#1082;&#1083;&#1072;&#1076;&#1085;&#1099;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1080; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1081;
      </li>
      <li>
        &#1054;&#1073;&#1099;&#1095;&#1085;&#1099;&#1077; &#1092;&#1086;&#1088;&#1084;&#1099; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; &#1090;&#1086;&#1083;&#1089;&#1090;&#1099;&#1081; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;
      </li>
      <li>
        <b>&#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1092;&#1086;&#1088;&#1084;</b>&#160; &#1082;&#1072;&#1082; &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1090;&#1086;&#1088;, &#1090;&#1072;&#1082; &#1080; &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1083;&#1072;&#1090;&#1092;&#1086;&#1088;&#1084;&#1091; \ &#1045;&#1097;&#1077; \ &#1048;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1092;&#1086;&#1088;&#1084;&#1091; (&#1045;&#1097;&#1077; &#1091;&#1089;&#1090;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; - &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1084; &#1092;&#1086;&#1088;&#1084;&#1091; &#1074; &#1087;&#1077;&#1088;&#1074;&#1086;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077;). &#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1083;&#1072;&#1090;&#1092;&#1086;&#1088;&#1084;&#1091; &#1085;&#1077; &#1074;&#1085;&#1086;&#1089;&#1103;&#1090;&#1089;&#1103; &#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1090;&#1086;&#1088;
      </li>
    </ul>
    <p>
      <b>&#1057;&#1086;&#1089;&#1090;&#1072;&#1074;:</b>
    </p>
    <ul>
      <li>
        <b>&#1076;&#1077;&#1088;&#1077;&#1074;&#1086; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;</b>&#160;(&#1076;&#1077;&#1088;&#1077;&#1074;&#1086; &#1092;&#1086;&#1088;&#1084;&#1099;). &#1074; &#1076;&#1077;&#1088;&#1077;&#1074;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; <b>&#1076;&#1083;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080;</b>&#160;&#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; <b>&#1087;&#1072;&#1087;&#1082;&#1080;</b>&#160;&#1080; &#1087;&#1086;&#1076;&#1087;&#1072;&#1087;&#1082;&#1080;
      </li>
      <li>
        &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1081; &#1074;&#1080;&#1076; &#1092;&#1086;&#1088;&#1084;&#1099; (&#1079;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080; <b>&#1060;&#1086;&#1088;&#1084;&#1072;</b>, <b>&#1052;&#1086;&#1076;&#1091;&#1083;&#1100;</b>)
      </li>
      <li>
        <b>&#1074; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1093;</b>&#160; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1099; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1099; &#1089;&#1074;&#1103;&#1079;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089; <b>&#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103;&#1084;&#1080;</b>&#160; (&#1082;&#1086;&#1076;)
      </li>
    </ul>
    <p>
      <b>&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084;&#1099;&#1077; &#1092;&#1086;&#1088;&#1084;&#1099;:</b>
    </p>
    <ul>
      <li>
        <b>&#1082;&#1088;&#1072;&#1089;&#1085;&#1086;&#1077; &#1087;&#1086;&#1076;&#1095;&#1077;&#1088;&#1082;&#1080;&#1074;&#1072;&#1085;&#1080;&#1077;</b>&#160;- &#1087;&#1086;&#1083;&#1077; &#1092;&#1086;&#1088;&#1084;&#1099; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1076;&#1083;&#1103; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;. <b>&lt;&#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&gt;</b>&#160; \ &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; \ &#1056;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099; \ &#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; \ &#1055;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; \ &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;
