    </p>
    <ol>
      <li>
        &#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; \ &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1080; \ &lt;&#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&gt; \ &#1060;&#1086;&#1088;&#1084;&#1099; --&gt; &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; (&#1058;&#1080;&#1087;: &#1060;&#1086;&#1088;&#1084;&#1072; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072; &#1089;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072;) --&gt; &#1044;&#1072;&#1083;&#1077;&#1077; (&#1056;&#1077;&#1076;&#1072;&#1082;&#1090;&#1086;&#1088; &#1060;&#1086;&#1088;&#1084;&#1099;)
      </li>
      <li>
        &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; \ &#1043;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; \ &#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; \ &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; \ &#1044;&#1086;&#1075;&#1086;&#1074;&#1086;&#1088;&#1099; &#1082;&#1086;&#1085;&#1090;&#1088;&#1072;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074; \ &#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;.&#1057;&#1087;&#1080;&#1089;&#1086;&#1082;.&#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077;&#1044;&#1072;&#1085;&#1085;&#1099;&#1077;.&#1057;&#1089;&#1099;&#1083;&#1082;&#1072; --&gt; &#1087;&#1077;&#1088;&#1077;&#1090;&#1072;&#1097;&#1080;&#1090;&#1100; &#1085;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1091;&#1102; &#1087;&#1072;&#1085;&#1077;&#1083;&#1100;
      </li>
    </ol>
    <ul>
      <li>
        &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1080;&#1093; &#1075;&#1088;&#1091;&#1087;&#1087;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; (&#1086;&#1073;&#1099;&#1095;&#1085;&#1072;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072; &#1073;&#1077;&#1079; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;)
      </li>
    </ul>
    <p>
      <b>&#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1079;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080;</b>
    </p>
    <ol>
      <li>
        &#1060;&#1086;&#1088;&#1084;&#1072; &gt; &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1043;&#1088;&#1091;&#1087;&#1087;&#1072; - &#1057;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;<b>&#1099;</b>. &#1042; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1091;&#1102; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1043;&#1088;&#1091;&#1087;&#1087;&#1072; - &#1057;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;<b>&#1072;</b>
      </li>
      <li>
        &#1055;&#1077;&#1088;&#1077;&#1090;&#1072;&#1097;&#1080;&#1090;&#1100; &#1074; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1077; &#1088;&#1077;&#1082;&#1074;&#1080;&#1079;&#1080;&#1090;&#1099;
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      <b>&#1059;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077; &#1092;&#1086;&#1088;&#1084;</b>
    </p>
    <p>
      &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1092;&#1086;&#1088;&#1084;&#1091;, &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1091;&#1102; &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; <font color="#ff0000">&#1085;&#1077;&#1083;&#1100;&#1079;&#1103;</font>&#160;- &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1095;&#1080;&#1089;&#1090;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1077; &#1057;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1080; \ &lt;&#1057;&#1087;&#1088;&#1072;&#1074;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&gt; \ &#1060;&#1086;&#1088;&#1084;&#1099; \ <b>&#1060;&#1086;&#1088;&#1084;&#1099; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072;</b>
    </p>
  </body>
