        &#1087;&#1086;&#1076;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1086;&#1095;&#1085;&#1099;&#1077; &#1079;&#1085;&#1072;&#1082;&#1080;&#160;- &#1101;&#1090;&#1086; <b>RegExp</b>
      </li>
      <li>
        <b>&#1087;&#1088;&#1086;&#1090;&#1103;&#1075;&#1080;&#1074;&#1072;&#1085;&#1080;&#1077; &#1083;&#1080;&#1085;&#1080;&#1080; &#1089; Shift</b>&#160;&#1076;&#1077;&#1083;&#1072;&#1077;&#1090; &#1077;&#1077; &#1089;&#1090;&#1088;&#1086;&#1075;&#1086; &#1074;&#1077;&#1088;&#1090;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1080;&#1083;&#1080; &#1075;&#1086;&#1088;&#1080;&#1079;&#1086;&#1085;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>&#1043;&#1086;&#1088;&#1103;&#1095;&#1080;&#1077; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1080;</b>
    </p>
    <p>
      Ctrl+A &gt; F9&#160;&#160;// &#1054;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074;&#1089;&#1077; &#1087;&#1086;&#1083;&#1103; (&#1092;&#1086;&#1088;&#1084;&#1091;&#1083;&#1099; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;&#1093;, &#1087;&#1077;&#1088;&#1077;&#1082;&#1088;&#1077;&#1089;&#1090;&#1085;&#1099;&#1077; &#1089;&#1089;&#1099;&#1083;&#1082;&#1080;)
    </p>
    <p>
