      <li>
        &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1079;&#1072;&#1087;&#1072;&#1089; 30-40% &#1085;&#1072; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077; &#1080; &#1085;&#1072; &#1087;&#1080;&#1082;&#1086;&#1074;&#1099;&#1077; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1078;&#1077;&#1082;&#1090;&#1086;&#1088;&#1086;&#1074; &#1085;&#1072; &#1087;&#1077;&#1088;&#1080;&#1084;&#1077;&#1090;&#1088;&#1077;)
      </li>
      <li>
        <b>&#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103;</b>&#160;&#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1088;&#1072;&#1089;&#1095;&#1077;&#1090; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1089;&#1077;&#1090;&#1080; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103; &#1080;&#1079;: &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; 40&#1052;&#1073;&#1080;&#1090;/&#1089; &#1076;&#1083;&#1103; Fast Ethernet; &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; 400&#1052;&#1073;&#1080;&#1090;/&#1089; &#1076;&#1083;&#1103; Gigabit Ethernet
      </li>
