    <p>
      <b>&#1047;&#1086;&#1085;&#1085;&#1086;&#1077; &#1082;&#1072;&#1073;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;. &#1054;&#1087;&#1090;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1077;&#1090;&#1100;</b>
    </p>
    <ul>
      <li>
        &#1047;&#1050; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1091;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1085;&#1080;&#1103; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1080;&#1085;&#1092;&#1088;&#1072;&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1099; &#1080; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1076;&#1086; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;
      </li>
      <li>
        &#1047;&#1050; &#1101;&#1090;&#1086; &#1082;&#1086;&#1075;&#1076;&#1072; &#1083;&#1080;&#1085;&#1082;&#1080; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1093; &#1084;&#1077;&#1089;&#1090; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074;&#1084;&#1077;&#1089;&#1090;&#1077;&#160;&#160;&#1074; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088; &#1080; &#1086;&#1076;&#1085;&#1080;&#1084; &#1096;&#1085;&#1091;&#1088;&#1082;&#1086;&#1084; &#1074; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1091;&#1102;
      </li>
      <li>
        &#1079;&#1072; &#1089;&#1095;&#1077;&#1090; &#1047;&#1050; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1090;&#1100; &#1089;&#1091;&#1084;&#1084;&#1072;&#1088;&#1085;&#1091;&#1102; &#1076;&#1083;&#1080;&#1085;&#1091; &#1076;&#1086; &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1084;&#1077;&#1088;&#1099; &#1087;&#1086; &#1084;&#1077;&#1076;&#1085;&#1086;&#1084;&#1091; &#1082;&#1072;&#1073;&#1077;&#1083;&#1102; &#1076;&#1086; 200&#1084;, &#1080; &#1089;&#1101;&#1082;&#1086;&#1085;&#1086;&#1084;&#1080;&#1090;&#1100; &#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1080;&#1085;&#1092;&#1088;&#1072;&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1077;
      </li>
    </ul>
    <p>
      <b>&#1040;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;. &#1042;&#1099;&#1073;&#1086;&#1088; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072;. &#1040;&#1075;&#1088;&#1077;&#1075;&#1072;&#1094;&#1080;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;. &#1056;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1072;&#1094;&#1080;&#1080;</b>
    </p>
    <ul>
      <li>
        &#1087;&#1088;&#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1083;-&#1074;&#1072; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; &#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1079;&#1072;&#1087;&#1072;&#1089; &#1074; 20-30%
      </li>
      <li>
        &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1072;&#1075;&#1088;&#1077;&#1075;&#1072;&#1094;&#1080;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;
      </li>
      <li>
        &#1076;&#1083;&#1103; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103; &#1082;&#1072;&#1084;&#1077;&#1088; &#1087;&#1086; PoE &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1073;&#1102;&#1076;&#1078;&#1077;&#1090; PoE (&#1086;&#1085; &#1087;&#1086;&#1095;&#1090;&#1080; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; &#1095;&#1077;&#1084; &#1089;&#1091;&#1084;&#1084;&#1072; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1077;&#1081; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074;). &#1041;&#1102;&#1076;&#1078;&#1077;&#1090; PoE - &#1093;&#1072;&#1088;&#1072;&#1082;&#1090;&#1077;&#1088;&#1080;&#1089;&#1090;&#1080;&#1082;&#1072; - &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1091;&#1084;&#1084;&#1072;&#1088;&#1085;&#1072;&#1103; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1086;&#1085;&#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1074;&#1099;&#1076;&#1072;&#1090;&#1100;
      </li>
      <li>
        &#1076;&#1083;&#1103; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099; &#1089;&#1076;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1077; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080;: &#1091;&#1087;&#1072;&#1088;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; WEB, IEEE 802.1p (QoS) - &#1086;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086; &#1074;&#1072;&#1078;&#1085;&#1086; &#1076;&#1083;&#1103; &#1087;&#1086;&#1074;&#1086;&#1088;&#1086;&#1090;&#1085;&#1099;&#1093; &#1082;&#1072;&#1084;&#1077;&#1088; &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1086;&#1088;&#1077;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1091;&#1087;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1077;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;; IEEE 802.1Q VLAN; SSH/SSL &#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
      </li>
      <li>
        &#1040;&#1075;&#1088;&#1077;&#1075;&#1072;&#1094;&#1080;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;. &#1086;&#1073;&#1098;&#1077;&#1076;. &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1087;&#1072;&#1088;&#1072;&#1083;&#1083;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1089;&#1074;&#1103;&#1079;&#1080; &#1074; &#1086;&#1076;&#1080;&#1085; &#1083;&#1086;&#1075;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1076;&#1083;&#1103; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1085;&#1086;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080; &#1085;&#1072;&#1076;&#1077;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; (802.3ad)
      </li>
    </ul>
    <p>
      <b>&#1057;&#1077;&#1090;&#1100; &#1085;&#1072; &#1087;&#1077;&#1088;&#1080;&#1084;&#1077;&#1090;&#1088;&#1077;. &#1056;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1072;&#1094;&#1080;&#1080;. &#1055;&#1088;&#1080; &#1087;&#1088;&#1086;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1089;&#1077;&#1090;&#1080; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086; &#1089;&#1074;&#1103;&#1079;&#1080; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103;:</b>
