    <p>
      <b>&#1042;&#1080;&#1076;&#1077;&#1086;&#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088; (Digital Video Recorder, DVR, &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1086;&#1081; &#1074;&#1080;&#1076;&#1077;&#1086;&#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;)</b>&#160; &#8212; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1086;&#1077; &#1076;&#1083;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080;, &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1080; &#1074;&#1086;&#1089;&#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1103; &#1074;&#1080;&#1076;&#1077;&#1086;&#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;.
    </p>
    <ul>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1074;&#1093;&#1086;&#1076; &#1086;&#1076;&#1080;&#1085;, &#1090;&#1086; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1084;&#1077;&#1088; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; <b>&#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;</b>. &#1045;&#1089;&#1083;&#1080; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077; &#1082;&#1072;&#1084;&#1077;&#1088; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; <a href="#ID_1327437000">PoE</a>, &#1090;&#1086; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1101;&#1090;&#1091; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102;
      </li>
      <li>
        &#1042;&#1080;&#1076;&#1077;&#1086;&#1088;&#1080;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#160; <a href="#ID_1035809543">SFP</a>&#160;&#1087;&#1086;&#1088;&#1090;&#1091; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072; (&#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1095;&#1077;&#1088;&#1077;&#1079; &#1101;&#1090;&#1080; &#1087;&#1086;&#1088;&#1090;&#1099; &#1085;&#1077; &#1088;&#1077;&#1078;&#1091;&#1090;&#1089;&#1103; &#1074;&#1080;&#1076;&#1077;&#1086;&#1087;&#1086;&#1090;&#1086;&#1082;&#1080; &#1080;&#160;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089;&#1082;&#1074;&#1086;&#1079;&#1085;&#1099;&#1084; &#1087;&#1091;&#1090;&#1077;&#1084; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;)&#160;
