<node TEXT="NVR" ID="ID_1681945503" CREATED="1519112080263" MODIFIED="1519112080263"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>NVR</b>&#160;(Network Video Recorder, &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1074;&#1080;&#1076;&#1077;&#1086;&#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;) &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1099; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1074; IP-&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1093; &#1074;&#1080;&#1076;&#1077;&#1086;&#1085;&#1072;&#1073;&#1083;&#1102;&#1076;&#1077;&#1085;&#1080;&#1103;. &#1042; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1093; DVR, NVR &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1102;&#1090; &#1074;&#1080;&#1076;&#1077;&#1086;&#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1091;&#1078;&#1077; &#1074; &#1089;&#1078;&#1072;&#1090;&#1086;&#1084; &#1074;&#1080;&#1076;&#1077; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080; Ethernet. &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1090;&#1100; &#1089; IP-&#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1084;&#1077;&#1088; &#1080;&#1083;&#1080; &#1089; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1099;&#1093; &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1084;&#1077;&#1088;, &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084;&#1099;&#1093; &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1072;&#1076;&#1072;&#1087;&#1090;&#1077;&#1088;&#1099; (&#1090;&#1080;&#1087;&#1072;: &#171;&#1082;&#1086;&#1084;&#1087;&#1086;&#1079;&#1080;&#1090;&#1085;&#1099;&#1081; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#8212; Ethernet&#187;).
    </p>
    <ul>
      <li>
        ( + ) &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076; &#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1074;&#1080;&#1076;&#1077;&#1086;&#1076;&#1072;&#1085;&#1085;&#1099;&#1084; &#1087;&#1086; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080; &#1080;&#1083;&#1080; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090; (&#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1089;&#1086;&#1092;&#1090;, web-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;, &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1099;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;)
      </li>
      <li>
        ( + ) &#1083;&#1077;&#1075;&#1082;&#1086; &#1085;&#1072;&#1088;&#1072;&#1097;&#1080;&#1074;&#1072;&#1077;&#1084;&#1072;&#1103; &#1072;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1072;
      </li>
      <li>
        ( + ) &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080; &#1074; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086;&#1084; &#1084;&#1077;&#1089;&#1090;&#1077;
      </li>
      <li>
        ( - ) &#1074;&#1099;&#1089;&#1086;&#1082;&#1072;&#1103; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1085;&#1072; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1089;&#1077;&#1090;&#1100;
      </li>
    </ul>
    <p>
      &#1058;&#1080;&#1087;&#1080;&#1095;&#1085;&#1099;&#1077; &#1093;&#1072;&#1088;&#1072;&#1082;&#1090;&#1077;&#1088;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080;:
    </p>
    <ul>
      <li>
        &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; (IP &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1084;&#1077;&#1088;): 4/8/16/20/32/40/64
      </li>
      <li>
        &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; HDD: 2/4/6/8/12/16 (&#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; RAID)
      </li>
      <li>
        &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1084;&#1099;&#1077; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1099; &#1074;&#1080;&#1076;&#1077;&#1086;&#1089;&#1078;&#1072;&#1090;&#1080;&#1103;: MJPEG, MPEG4, H.264 &#1080; &#1076;&#1088;
      </li>
      <li>
        &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077; &#1072;&#1091;&#1076;&#1080;&#1086;/&#1074;&#1080;&#1076;&#1077;&#1086; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1074; &#1076;&#1083;&#1103; &#1074;&#1099;&#1074;&#1086;&#1076;&#1072; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1089; &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1084;&#1077;&#1088; &#1085;&#1072; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084;&#1099;&#1081; &#1074;&#1080;&#1076;&#1077;&#1086;&#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;
      </li>
    </ul>
    <p>
      <b>&#1042;&#1086;&#1087;&#1088;&#1086;&#1089;&#1099; &#1082; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102;</b>
    </p>
    <p>
