<node TEXT="Zabbix сервер" ID="ID_41757770" CREATED="1544454490697" MODIFIED="1553610183253"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        &#1054;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; <b><font color="#0000c0">&#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1099;</font></b>
      </li>
    </ul>
    <p>
      <b>AlertScriptsPath=</b>/usr/local/share/zabbix/alertscripts. &#1056;&#1072;&#1079;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074; &#1086;&#1087;&#1086;&#1074;&#1077;&#1097;&#1077;&#1085;&#1080;&#1081; (&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1081; &#1087;&#1088;&#1080; &#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1103;&#1094;&#1080;&#1080; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; datadir)
    </p>
    <p>
      <b>AllowRoot=</b>0. &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086;&#1076; &#8220;root&#8221;. &#1045;&#1089;&#1083;&#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1086; &#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079; &#1087;&#1086;&#1076; &#8220;root&#8221;, &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1086;&#1087;&#1088;&#1086;&#1073;&#1091;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#8220;zabbix&#8221;. &#1053;&#1077; &#1080;&#1084;&#1077;&#1077;&#1090; &#1089;&#1084;&#1099;&#1089;&#1083;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1076; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;. 0 - &#1085;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1086;; 1 - &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1086;
    </p>
    <p>
      <b>CacheSize</b>=8&#1052;. 128K-8G. &#1056;&#1072;&#1079;&#1084;&#1077;&#1088; &#1082;&#1101;&#1096;&#1072; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;, &#1074; &#1073;&#1072;&#1081;&#1090;&#1072;&#1093;. &#1056;&#1072;&#1079;&#1084;&#1077;&#1088; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1091;&#1079;&#1083;&#1086;&#1074; &#1089;&#1077;&#1090;&#1080;, &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080; &#1090;&#1088;&#1080;&#1075;&#1075;&#1077;&#1088;&#1086;&#1074;
    </p>
    <p>
      <b>CacheUpdateFrequency. </b>1-3600.&#160;&#1050;&#1072;&#1082; &#1095;&#1072;&#1089;&#1090;&#1086; Zabbix &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1091; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1082;&#1101;&#1096;&#1072; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;, &#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1072;&#1093;. &#1057;&#1084;&#1086;&#1090;&#1088;&#1080;&#1090;&#1077; &#1090;&#1072;&#1082;&#1078;&#1077; &#1086;&#1087;&#1094;&#1080;&#1080; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1093; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081;.
    </p>
    <p>
      <b>DBHost. </b>&#1048;&#1084;&#1103; &#1093;&#1086;&#1089;&#1090;&#1072; &#1041;&#1044;. &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; localhost &#1080;&#1083;&#1080; &#1087;&#1091;&#1089;&#1090;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1076;&#1083;&#1103; MySQL, &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1086;&#1082;&#1077;&#1090;. &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; PostgreSQL &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1080; &#1087;&#1091;&#1089;&#1090;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1077;&#1076;&#1077;&#1085;&#1072; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1082;&#1077;&#1090;.
    </p>
    <p>
      <b><font color="#0000c0">DBName.</font></b>&#160;&#1048;&#1084;&#1103; &#1041;&#1044;.
