<node TEXT="Настройка" ID="ID_1301959945" CREATED="1543748779513" MODIFIED="1543750851027"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; SNMP &#1090;&#1088;&#1072;&#1087;&#1086;&#1074;</b>
    </p>
    <p>
      <i>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; \ &#1059;&#1079;&#1083;&#1099; &#1089;&#1077;&#1090;&#1080; \ &#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; \ <b>&#1050;&#1083;&#1102;&#1095;</b>&#160;&gt;</i>&#160;&#1086;&#1076;&#1080;&#1085; &#1080;&#1079; &#1082;&#1083;&#1102;&#1095;&#1077;&#1081; SNMP &#1090;&#1088;&#1072;&#1087;&#1086;&#1074;:
    </p>
    <ul>
      <li>
        <b>snmptrap[&#1088;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1086;&#1077; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;]</b>&#160;&#160;&#1054;&#1090;&#1083;&#1086;&#1074; &#1074;&#1089;&#1077;&#1093; SNMP &#1090;&#1088;&#1072;&#1087;&#1086;&#1074; , &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1102;&#1090; &#1089; &#1088;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1099;&#1084; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;&#1084;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1084; &#1074; &#1087;&#1086;&#1083;&#1077; &#1088;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1086;&#1077; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;. &#1045;&#1089;&#1083;&#1080; &#1088;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1086;&#1077; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1086;, &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074;&#1089;&#1077; &#1090;&#1088;&#1072;&#1087;&#1099;. &#1069;&#1090;&#1086;&#1090; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082; SNMP &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&#1084;
      </li>
      <li>
        <b>snmptrap.fallback&#160; </b>&#1054;&#1090;&#1083;&#1086;&#1074; &#1074;&#1089;&#1077;&#1093; SNMP &#1090;&#1088;&#1072;&#1087;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1077; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1102;&#1090; &#1085;&#1080; &#1089; &#1086;&#1076;&#1085;&#1080;&#1084; &#1080;&#1079; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; snmptrap[] &#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;. &#1069;&#1090;&#1086;&#1090; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082; SNMP &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&#1084;.
      </li>
    </ul>
    <p>
      <i>\ &#1058;&#1080;&#1087; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &gt; '&#1046;&#1091;&#1088;&#1085;&#1072;&#1083; (&#1083;&#1086;&#1075;)'</i>
    </p>
    <p>
      
    </p>
    <p>
      <b>2. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;&#1080;&#1085;&#1075;&#1072; SNMP &#1090;&#1088;&#1072;&#1087;&#1086;&#1074;</b>
    </p>
    <p>
      <b>2.1 &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;/&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;.</b>&#160;&#1044;&#1083;&#1103; &#1095;&#1090;&#1077;&#1085;&#1080;&#1103; &#1090;&#1088;&#1072;&#1087;&#1086;&#1074;, Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080;&#1083;&#1080; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1099; &#1085;&#1072; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; SNMP &#1090;&#1088;&#1072;&#1087;&#1087;&#1077;&#1088;&#1072; &#1080; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1079;&#1085;&#1072;&#1090;&#1100; &#1072;&#1073;&#1089;&#1086;&#1083;&#1102;&#1090;&#1085;&#1099;&#1081; &#1087;&#1091;&#1090;&#1100; &#1082; &#1092;&#1072;&#1081;&#1083;&#1091; &#1089; &#1090;&#1088;&#1072;&#1087;&#1072;&#1084;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; SNMPTT &#1080;&#1083;&#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1103; &#1090;&#1088;&#1072;&#1087;&#1086;&#1074; Perl
    </p>
    <p>
      <font color="#008000"><b># zabbix_server.conf &#1080;&#1083;&#1080; zabbix_proxy.conf</b> </font>
    </p>
    <p>
      <font color="#008000">StartSNMPTrapper=1 </font>
    </p>
    <p>
      <font color="#008000">SNMPTrapperFile=[&#1060;&#1040;&#1049;&#1051; &#1057; &#1058;&#1056;&#1040;&#1055;&#1040;&#1052;&#1048;]</font>
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; systemd &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; PrivateTmp, &#1101;&#1090;&#1086;&#1090; &#1092;&#1072;&#1081;&#1083; &#1074;&#1088;&#1103;&#1076; &#1083;&#1080; &#1079;&#1072;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1074; /tmp.
    </p>
    <p>
      <b>2.2 &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; SNMPTT.</b>snmptrapd &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1085;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; SNMPTT.
    </p>
    <p>
      &#1055;&#1088;&#1080; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; SNMPTT &#1085;&#1072; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1088;&#1072;&#1087;&#1086;&#1074;, &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1090;&#1077; SNMPTT &#1085;&#1072; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1101;&#1090;&#1080;&#1093; &#1090;&#1088;&#1072;&#1087;&#1086;&#1074;:
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1090;&#1088;&#1072;&#1087;&#1086;&#1074; &#1074; &#1092;&#1072;&#1081;&#1083; &#1089; &#1090;&#1088;&#1072;&#1087;&#1072;&#1084;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; Zabbix &#1073;&#1091;&#1076;&#1077;&#1090; &#1095;&#1080;&#1090;&#1072;&#1090;&#1100;:
    </p>
    <p>
      &#160;&#160;&#160;&#160;log_enable = 1
    </p>
    <p>
      &#160;&#160;&#160;&#160;log_file = [&#1060;&#1040;&#1049;&#1051; &#1057; &#1058;&#1056;&#1040;&#1055;&#1040;&#1052;&#1048;]
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#1079;&#1072;&#1076;&#1072;&#1081;&#1090;&#1077; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;/&#1076;&#1072;&#1090;&#1099;:
    </p>
    <p>
      &#160;&#160;&#160;&#160;date_time_format = %H:%M:%S %Y/%m/%d = [&#1060;&#1054;&#1056;&#1052;&#1040;&#1058; &#1042;&#1056;&#1045;&#1052;&#1045;&#1053;&#1048;]
    </p>
    <p>
      &#1054;&#1090;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1090;&#1088;&#1072;&#1087;&#1099;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1085;&#1080; &#1088;&#1072;&#1089;&#1087;&#1086;&#1079;&#1085;&#1072;&#1074;&#1072;&#1083;&#1080;&#1089;&#1100; Zabbix'&#1086;&#1084; (&#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1077; snmptt.conf):
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#1050;&#1072;&#1078;&#1076;&#1072;&#1103; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1103; FORMAT &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089; &#8220;ZBXTRAP [&#1072;&#1076;&#1088;&#1077;&#1089;]&#8221;, &#1075;&#1076;&#1077; [&#1072;&#1076;&#1088;&#1077;&#1089;] &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1088;&#1072;&#1074;&#1085;&#1080;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089; IP &#1080; DNS &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1084;&#1080; &#1091; SNMP &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1074; &#1074; Zabbix. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;:
    </p>
    <p>
      &#160;&#160;&#160;&#160;EVENT coldStart .1.3.6.1.6.3.1.1.5.1 &#8220;Status Events&#8221; Normal
    </p>
    <p>
      &#160;&#160;&#160;&#160;FORMAT ZBXTRAP $aA Device reinitialized (coldStart)
    </p>
    <p>
      &#1053;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1081;&#1090;&#1077; &#1085;&#1077;&#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1077; &#1090;&#1088;&#1072;&#1087;&#1099; - Zabbix &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1093; &#1085;&#1077; &#1088;&#1072;&#1089;&#1087;&#1086;&#1079;&#1085;&#1072;&#1090;&#1100;. &#1053;&#1077;&#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1077; &#1090;&#1088;&#1072;&#1087;&#1099; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085;&#1099;, &#1077;&#1089;&#1083;&#1080; &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1086;&#1073;&#1097;&#1077;&#1077; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1077; &#1074; snmptt.conf:
    </p>
    <p>
      EVENT general .* &#8220;General event&#8221; Normal
    </p>
    <p>
      <b>2.3 &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1103; Perl &#1090;&#1088;&#1072;&#1087;&#1086;&#1074;</b>
    </p>
    <ul>
      <li>
        &#1058;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;: Perl, Net-SNMP &#1089;&#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1089; --enable-embedded-perl (&#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; Net-SNMP 5.4)
      </li>
    </ul>
    <p>
      &#1055;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1100; &#1090;&#1088;&#1072;&#1087;&#1086;&#1074; Perl (&#1080;&#1097;&#1080;&#1090;&#1077; &#1074; misc/snmptrap/zabbix_trap_receiver.pl) &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1090;&#1088;&#1072;&#1087;&#1086;&#1074; &#1074; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1085;&#1072;&#1087;&#1088;&#1103;&#1084;&#1091;&#1102; &#1089; snmptrapd. &#1044;&#1083;&#1103; &#1077;&#1075;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;:
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#1076;&#1086;&#1073;&#1072;&#1074;&#1100;&#1090;&#1077; perl &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; &#1074; &#1092;&#1072;&#1081;&#1083; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; snmptrapd (snmptrapd.conf), &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;:
    </p>
    <p>
      &#160;&#160;&#160;&#160;perl do &quot;[&#1055;&#1054;&#1051;&#1053;&#1067;&#1049; &#1055;&#1059;&#1058;&#1068; &#1050; &#1057;&#1050;&#1056;&#1048;&#1055;&#1058;&#1059; &#1055;&#1054;&#1051;&#1059;&#1063;&#1040;&#1058;&#1045;&#1051;&#1071; PERL]&quot;;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1090;&#1077; &#1089;&#1072;&#1084; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1100;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;:
    </p>
    <p>
      &#160;&#160;&#160;&#160;$SNMPTrapperFile = '[&#1060;&#1040;&#1049;&#1051; &#1057; &#1058;&#1056;&#1040;&#1055;&#1040;&#1052;&#1048;]';
    </p>
    <p>
      &#160;&#160;&#160;&#160;$DateTimeFormat = '[&#1060;&#1054;&#1056;&#1052;&#1040;&#1058; &#1044;&#1040;&#1058;&#1067;/&#1042;&#1056;&#1045;&#1052;&#1045;&#1053;&#1048;]';
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1080;&#1084;&#1103; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072; &#1085;&#1077; &#1079;&#1072;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1086; &#1074; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1080;, snmptrapd &#1086;&#1090;&#1082;&#1072;&#1078;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080; &#1085;&#1072;&#1087;&#1086;&#1076;&#1086;&#1073;&#1080;&#1077; &#1101;&#1090;&#1080;&#1093;:
    </p>
    <p>
      Regexp modifiers &quot;/l&quot; and &quot;/a&quot; are mutually exclusive at (eval 2) line 1, at end of line
    </p>
    <p>
      Regexp modifier &quot;/l&quot; may not appear twice at (eval 2) line 1, at end of line
    </p>
    <p>
      <b>2.4 &#1060;&#1086;&#1088;&#1084;&#1072;&#1090; SNMP &#1090;&#1088;&#1072;&#1087;&#1072;. </b>&#1042;&#1089;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1080; &#1090;&#1088;&#1072;&#1087;&#1086;&#1074; perl &#1080; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; SNMPTT &#1090;&#1088;&#1072;&#1087;&#1086;&#1074; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1088;&#1072;&#1087; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;:
    </p>
    <p>
      [&#1096;&#1090;&#1072;&#1084;&#1087; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;] [&#1090;&#1088;&#1072;&#1087;, &#1095;&#1072;&#1089;&#1090;&#1100; 1] ZBXTRAP [&#1072;&#1076;&#1088;&#1077;&#1089;] [&#1090;&#1088;&#1072;&#1087;, &#1095;&#1072;&#1089;&#1090;&#1100; 2]
    </p>
    <p>
      &#160;&#160;&#160;&#160;[&#1096;&#1090;&#1072;&#1084;&#1087; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;] - &#1096;&#1090;&#1072;&#1084;&#1087; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1081; &#1074; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1090;&#1080;&#1087;&#1072; '&#1046;&#1091;&#1088;&#1085;&#1072;&#1083; (&#1083;&#1086;&#1075;)'
    </p>
    <p>
      &#160;&#160;&#160;&#160;ZBXTRAP - &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1082;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1089; &#1101;&#1090;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1085;&#1072;&#1095;&#1072;&#1083;&#1089;&#1103; &#1085;&#1086;&#1074;&#1099;&#1081; &#1090;&#1088;&#1072;&#1087;
    </p>
    <p>
      &#160;&#160;&#160;&#160;[&#1072;&#1076;&#1088;&#1077;&#1089;] - IP &#1072;&#1076;&#1088;&#1077;&#1089;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1081; &#1076;&#1083;&#1103; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072; &#1091;&#1079;&#1083;&#1072; &#1089;&#1077;&#1090;&#1080; &#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1087;&#1072;
    </p>
    <p>
      &#8220;ZBXTRAP&#8221; &#1080; &#8220;[&#1072;&#1076;&#1088;&#1077;&#1089;]&#8221; &#1087;&#1088;&#1080; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1077; &#1086;&#1090;&#1088;&#1077;&#1079;&#1072;&#1102;&#1090;&#1089;&#1103; &#1080;&#1079; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;. &#1045;&#1089;&#1083;&#1080; &#1090;&#1088;&#1072;&#1087; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082;-&#1090;&#1086; &#1080;&#1085;&#1072;&#1095;&#1077;, Zabbix &#1084;&#1086;&#1078;&#1077;&#1090; &#1088;&#1072;&#1079;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100; &#1090;&#1072;&#1082;&#1080;&#1077; &#1090;&#1088;&#1072;&#1087;&#1099; &#1085;&#1077;&#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1085;&#1099;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;.
    </p>
    <p>
      <b>3. &#1058;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1082; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077;. </b>
    </p>
    <p>
      &#1060;&#1072;&#1081;&#1083;&#1086;&#1074;&#1072;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;. &#1048;&#1079;-&#1079;&#1072; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1092;&#1072;&#1081;&#1083;&#1072; &#1089; &#1090;&#1088;&#1072;&#1087;&#1072;&#1084;&#1080;, Zabbix'&#1091; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1072;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1089; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1086;&#1081; inode &#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086; &#1095;&#1090;&#1086;&#1073;&#1099; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083;&#1099; (&#1101;&#1090;&#1072; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1073;&#1077;&#1088;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; stat())
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="SSH agent" ID="ID_1415972766" CREATED="1543762793210" MODIFIED="1766135973144"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1179994498">SSH</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      В Zabbix SSH-проверки выполняются <span style="font-weight: bold;">без установки агента</span>&#xa0;на целевой хост. Вместо этого Zabbix-сервер (или прокси, если поддерживает SSH) устанавливает SSH-соединение и выполняет команды напрямую
    </p>
    <ul>
      <li>
        Команды выполняются <span style="font-weight: bold;">в одной сессии</span>, но <span style="font-weight: bold;">без сохранения состояния</span>&#xa0;между строками (каждая команда - новый shell, если не использовать &amp;&amp; или явный shell-скрипт)
      </li>
      <li>
        Убедитесь, что у пользователя zabbix есть права на чтение приватного ключа
      </li>
      <li>
        Если используется прокси - он тоже должен поддерживать SSH и иметь настроенные ключи
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Методы аутентификации</span>
    </p>
    <p>
      <span style="font-weight: bold;">1. Парольная аутентификация&#xa0;</span>
    </p>
    <ul>
      <li>
        Не требует дополнительной настройки ключей
      </li>
      <li>
        Указывается имя пользователя и пароль в настройках элемента
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">2. Аутентификация по SSH-ключу&#xa0;</span>
    </p>
    <p>
      Укажите расположение ключей в файле конфигурации сервера:&#xa0;
    </p>
    <p>
      # /etc/zabbix/zabbix_server.conf
    </p>
    <p>
      <span style="color: #008000;">SSHKeyLocation=/var/lib/zabbix/.ssh</span>
    </p>
    <p>
      Расположение домашней директории пользователя zabbix зависит от ОС:
    </p>
    <ul>
      <li>
        /var/lib/zabbix (RHEL, CentOS)
      </li>
      <li>
        /usr/lib/zabbix или /var/run/zabbix (Debian/Ubuntu)
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">sudo -u zabbix ssh-keygen -t rsa</span>&#xa0;&#xa0;# Сгенерируйте ключи от имени пользователя zabbix
    </p>
    <p>
      <span style="color: #0000c0;">sudo -u zabbix ssh-copy-id root@10.10.10.10</span>&#xa0;&#xa0;# Скопируйте публичный ключ на целевой хост
    </p>
    <p>
      <span style="color: #0000c0;">sudo -u zabbix ssh root@10.10.10.10</span>&#xa0;&#xa0;# Проверьте подключение
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Настройка элемента данных (Item)</span>
    </p>
    <ul>
      <li>
        Тип элемента: SSH агент
      </li>
      <li>
        Ключ: <span style="color: #008000;">ssh.run[&lt;описание&gt;,&lt;IP&gt;,&lt;порт&gt;,&lt;кодировка&gt;]</span>

        <ul>
          <li>
            Порт по умолчанию - 22, независимо от настроек интерфейса узла
          </li>
        </ul>
      </li>
      <li>
        Метод аутентификации: Пароль или Публичный ключ
      </li>
      <li>
        Имя пользователя: учётная запись на удалённом хосте
      </li>
      <li>
        При использовании ключей:

        <ul>
          <li>
            Укажите имена файлов публичного и приватного ключей (без полного пути - только имена, например id_rsa.pub, id_rsa)
          </li>
          <li>
            Если ключ защищён парольной фразой - укажите её, иначе оставьте поле пустым
          </li>
        </ul>
      </li>
      <li>
        Выполняемый скрипт:<br/><span style="color: #0000c0;">date +%s</span><br color="#0000c0" style="color: #0000c0;"/><span style="color: #0000c0;">ps auxww | grep nginx | wc -l</span><br color="#0000c0" style="color: #0000c0;"/><span style="color: #0000c0;">systemctl is-active mysql</span><br/>Результат возвращается как <span style="font-weight: bold;">многострочное значение</span>
      </li>
    </ul>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Telnet checks" ID="ID_1702152930" CREATED="1543769741042" MODIFIED="1767434041542"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_479737011">Telnet</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Telnet проверки</b>&#xa0;выполняются без какого-либо агента
    </p>
    <ul>
      <li>
        Действующие команды для выполнения должны быть размещены в поле <b>Выполняемый скрипт</b>&#xa0;при настройке элемента данных
      </li>
      <li>
        Можно выполнять <b>несколько команд одну за другой</b>, размещая каждую на новой строке. В этом случае результирующее значение также будет отформатировано как многострочное
      </li>
      <li>
        Поддерживаемые символы, которыми строка может заканчиваться:$, #, &gt;, %.Строка telnet с запросом, которая заканчивается одним из этих символов, <b>будет удалена</b>&#xa0;из возвращаемого значения, но только для первой команды из списка команд, то есть только в начале telnet сессии.
      </li>
    </ul>
    <p>
      <b>Ключ</b>
    </p>
    <p>
      <b>telnet.run[&lt;уникальное короткое описание&gt;,&lt;ip&gt;,&lt;порт&gt;,&lt;кодировка&gt;]</b>&#xa0;&#xa0;Выполнение команды на удаленном устройстве с использованием telnet соединения
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Zabbix agent" FOLDED="true" ID="ID_771039532" CREATED="1543219985514" MODIFIED="1768468534703"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1705507945">Узлы с Linux (пассивная проверка)</a>&#xa0;&#xa0;<a href="#ID_262959741">Узлы с Linux (активная проверка)</a>&#xa0; <a href="#ID_902966155">пример (passive)</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Zabbix Agent</span>&#xa0;поддерживает два режима сбора метрик - <span style="font-weight: bold;">пассивные</span>&#xa0;и <span style="font-weight: bold;">активные</span>&#xa0;проверки. Оба типа могут использоваться одновременно на одном агенте
    </p>
    <ul>
      <li>
        Можно добавлять <span style="font-weight: bold;">свои метрики</span>&#xa0;через конф.файл (<span style="color: #008000;">UserParameter=...</span>)
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Пассивные проверки</span><span style="font-weight: normal;">&#xa0;- При пассивной проверке сервер отправляет запрос (например, system.cpu.load), а агент возвращает значение</span>
    </p>
    <ul>
      <li>
        Использовать если у вас централизованная инфраструктура без ограничений на входящие подключения
      </li>
      <li>
        <span style="font-weight: bold;">Принцип работы:</span>&#xa0;сервер Zabbix (или прокси) инициирует соединение и запрашивает данные с агента
      </li>
      <li>
        <span style="font-weight: bold;">Агент принимает</span>&#xa0;подключения на порту <span style="font-weight: bold;">10050/TCP</span>
      </li>
      <li>
        <span style="font-weight: bold;">Конфигурация:</span>&#xa0;указать Server (IP или DNS-имя сервера/прокси, с которого разрешены запросы)
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Активные проверки</span><span style="font-weight: normal;">&#xa0;- Агент периодически соединяется с сервером, получает список активных элементов данных и отправляет их значения. Поддерживается гибкое расписание и параллельное выполнение проверок</span>
    </p>
    <ul>
      <li>
        Использовать при мониторинге хостов за NAT, в облаках или когда нужно снизить нагрузку на сервер
      </li>
      <li>
        <span style="font-weight: bold;">Принцип работы:</span>&#xa0;агент сам подключается к серверу Zabbix/прокси и отправляет метрики
      </li>
      <li>
        Агент инициирует соединение на порт <span style="font-weight: bold;">10051/TCP</span>&#xa0;сервера/прокси
      </li>
      <li>
        <span style="font-weight: bold;">Конфигурация:</span>&#xa0;указать параметр ServerActive - список IP/DNS серверов или прокси, у которых агент будет получать список активных проверок
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Конфигурация Zabbix Agent 2 (пример) </span>
    </p>
    <p>
      <span style="color: #0000c0;">/etc/zabbix/zabbix_agent2.conf</span>&#xa0;&#xa0;# Linux
    </p>
    <p>
      <span style="color: #0000c0;">C:\Program Files\Zabbix Agent 2\zabbix_agent2.conf</span>&#xa0;&#xa0;# Windows
    </p>
    <p>
      # <span style="font-weight: bold;">Пассивные проверки:</span>&#xa0;с каких серверов разрешено принимать запросы
    </p>
    <p>
      <span style="color: #008000;">Server=127.0.0.1,192.168.1.10</span>
    </p>
    <p>
      # <span style="font-weight: bold;">Активные проверки:</span>&#xa0;куда отправлять данные
    </p>
    <p>
      <span style="color: #008000;">ServerActive=192.168.1.10</span>
    </p>
    <p>
      # <span style="font-weight: bold;">Имя узла</span>, как он будет отображаться в Zabbix. Имя Hostname должно <span style="font-weight: bold;">точно совпадать</span>&#xa0;с именем узла в веб-интерфейсе Zabbix, иначе активные проверки не будут работать
    </p>
    <p>
      <span style="color: #008000;">Hostname=web-server-01 </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">zabbix-agent</span>&#xa0;и <span style="font-weight: bold;">zabbix-agent2</span>&#xa0;&#xa0;используют <span style="color: #ff0000;">один порт</span>&#xa0;<span style="font-weight: bold;">10050</span>, поэтому нужно использовать только <span style="font-weight: bold;">один из агентов</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="Ключи для Windows" ID="ID_1973809466" CREATED="1543845347276" MODIFIED="1767607744432"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>eventlog[name,&lt;regexp&gt;,&lt;severity&gt;,&lt;source&gt;,&lt;eventid&gt;,&lt;maxlines&gt;,&lt;mode&gt;]</b>&#xa0;&#xa0;(for Windows)Мониторинг журнала событий. Возвращает журнал
    </p>
    <p>
      <b>net.if.list</b>&#xa0;&#xa0;(for Windows) Список сет. интерфейсов (включая тип, состояние, IPv4 адресс, описание). Возвр. текст
    </p>
    <p>
      <b>perf_counter[counter,&lt;interval&gt;]</b>&#xa0;&#xa0;(for Windows)&#xa0;Значение любого счетчика производительности Windows. Возвр. целое число, дробное число, строку или текст (в зависимости от запроса)
    </p>
    <p>
      <b>proc_info[process,&lt;attribute&gt;,&lt;type&gt;]</b>&#xa0;&#xa0;(for Windows)&#xa0;Различная информация о указанном процессе(ах). Возвр. число с плавающей точкой
    </p>
    <p>
      <b>service.discovery</b>&#xa0;&#xa0;Список служб Windows. Используется низкоуровневым обнаружением. Объект <a href="#ID_844733533">JSON</a>
    </p>
    <p>
      <b>service.info[service,&lt;param&gt;]</b>&#xa0;&#xa0;(for Windows)&#xa0;Информация о службе. Возвр. число с параметром как состояние, запуска; строка - с параметром как отображаемое имя, пусть, пользователь; текст - с параметром как описание; В частности для состояния: 0 - запущено, 1 - приостановлено, 2 - выполнение запуска, 3 - выполнение приостановки, 4 - выполнение продолжения, 5 - выполнение остановки, 6 - остановлено, 7 - неизвестно, 255 - отсутствие службы; В частности для запуска: 0 - автоматический, 1 - автоматический отложенный, 2 - вручную, 3 - отключен, 4 - неизвестно
    </p>
    <p>
      <b>services[&lt;type&gt;,&lt;state&gt;,&lt;exclude&gt;]</b>&#xa0;&#xa0;(for Windows) Список служб. Возвр. 0 если список пуст; текст - список служб разделенных переводом строки
    </p>
    <p>
      <b>vm.vmemory.size[&lt;type&gt;]</b>&#xa0;&#xa0;(for Windows) Размер виртуального пространства в байтах или в процентах от общего размера. Возвр. целое число для байт; число с плавающей точкой для процентов
    </p>
    <p>
      <b>wmi.get[&lt;namespace&gt;,&lt;query&gt;]</b>&#xa0;&#xa0;(for Windows) Выполнение запроса WMI и получение первого выбранного объекта. Возвр. целое число, число с плавающей точкой или текст (в зависимости от запроса)
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Ключи мониторинга" ID="ID_80685677" CREATED="1767607756569" MODIFIED="1767607787840"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        Параметры, отмеченные <b>угловыми скобками &lt; &gt;</b>, необязательны.
      </li>
    </ul>
    <p>
      <b>agent.hostname</b>&#xa0;&#xa0;Имя хоста агента. Возвр. строку
    </p>
    <p>
      <b>agent.ping</b>&#xa0;&#xa0;Проверка доступности агента. Ничего не возвращает - недоступен; 1 - доступен
    </p>
    <p>
      <b>agent.version</b>&#xa0;&#xa0;Версия Zabbix агента. Возвр. строку
    </p>
    <p>
      <b>kernel.maxfiles</b>&#xa0;&#xa0;Макс. кол-во открытых файлов поддерживаемое ОС. Возвр. целое число
    </p>
    <p>
      <b>kernel.maxproc</b>&#xa0;&#xa0;Макс. кол-во процессов поддерживаемое ОС. Возвр. целое число
    </p>
    <p>
      <b>log[file,&lt;regexp&gt;,&lt;encoding&gt;,&lt;maxlines&gt;,&lt;mode&gt;,&lt;output&gt;,&lt;maxdelay&gt;]</b>&#xa0;&#xa0;&#xa0;Мониторинг файлов журналов логов. Возвр. лог
    </p>
    <p>
      <b>log.count[file,&lt;regexp&gt;,&lt;encoding&gt;,&lt;maxproclines&gt;,&lt;mode&gt;,&lt;maxdelay&gt;]</b>&#xa0;&#xa0;&#xa0;Кол-во совпадающих строк в мониторинге файлов журналов. Возвр. целое число
    </p>
    <p>
      <b>logrt[file_regexp,&lt;regexp&gt;,&lt;encoding&gt;,&lt;maxlines&gt;,&lt;mode&gt;,&lt;output&gt;,&lt;maxdelay&gt;,&lt;options&gt;]</b>&#xa0;&#xa0;&#xa0;Мониторинг файлов журналов с поддержкой ротации. Возвр. лог
    </p>
    <p>
      <b>logrt.count[file_regexp,&lt;regexp&gt;,&lt;encoding&gt;,&lt;maxproclines&gt;,&lt;mode&gt;,&lt;maxdelay&gt;,&lt;options&gt;]</b>&#xa0;&#xa0;&#xa0;Кол-во совп. строк в мониторинге файлов журналов с подд. ротации журналов. Возвр. целое число
    </p>
    <p>
      <b>net.dns[&lt;ip&gt;,name,&lt;type&gt;,&lt;timeout&gt;,&lt;count&gt;,&lt;protocol&gt;]</b>&#xa0;&#xa0;Проверка доступности DNS сервиса. Возвр. 0 - DNS недоступен; 1 - DNS доступен
    </p>
    <p>
      <b>net.dns.record[&lt;ip&gt;,name,&lt;type&gt;,&lt;timeout&gt;,&lt;count&gt;,&lt;protocol&gt;]</b>&#xa0;&#xa0;Выполнение DNS запроса. Возвр. строку символов с требуемым типом информации
    </p>
    <p>
      <b>net.if.collisions[if]</b>&#xa0;&#xa0;Кол-во коллизий out-of-window. Возвр. целое число
    </p>
    <p>
      <b>net.if.discovery</b>&#xa0;&#xa0;Объект <a href="#ID_844733533">JSON</a>. Список сет. интерфейсов. Используется низкоуровневым обнаружением
    </p>
    <p>
      <b>net.if.in[if,&lt;mode&gt;]</b>&#xa0;&#xa0;Статистика входящего трафика сет. интерфейса. Возв. целое число
    </p>
    <p>
      <b>net.if.out[if,&lt;mode&gt;]</b>&#xa0;&#xa0;Статистика исх. трафика на сет. интерфейсе. Возвр. число
    </p>
    <p>
      <b>net.if.total[if,&lt;mode&gt;]</b>&#xa0;&#xa0;Суммарная статистика вх. и ис. трафика на сет. интерфейсе. Возвр. целочисл. значение
    </p>
    <p>
      <b>net.tcp.listen[port]</b>&#xa0;&#xa0;Проверяется находится ли требуемый TCP порт в состоянии LISTEN. Возвр. 0 - если он не в состоянии LISTEN; 1 - он в состоянии LISTEN
    </p>
    <p>
      <b>net.tcp.port[&lt;ip&gt;,port]</b>&#xa0;&#xa0;Проверяет есть ли возможность создать TCP соединение к определенному порту. Возвр. 0 - не возможно подключиться; 1 - можно подключиться
    </p>
    <p>
      <b>net.tcp.service[service,&lt;ip&gt;,&lt;port&gt;]</b>&#xa0;&#xa0;Проверяется запущен ли сервис и принимает ли TCP соединения. Возвр. 0 - если сервис недоступен; 1 - сервис запущен
    </p>
    <p>
      <b>net.tcp.service.perf[service,&lt;ip&gt;,&lt;port&gt;]</b>&#xa0;&#xa0;Проверяется производительность TCP сервиса. Возвр. 0 - сервис недоступен; секунды - кол-во секунд потраченных в процессе подключения к сервису
    </p>
    <p>
      <b>net.udp.listen[port]</b>&#xa0;&#xa0;Проверяется находится ли требуемый UDP порт в состоянии LISTEN. Возвр. 0 - если он не в состоянии LISTEN; 1 - он в состоянии LISTEN
    </p>
    <p>
      <b>net.udp.service[service,&lt;ip&gt;,&lt;port&gt;]</b>&#xa0;&#xa0;Проверяется запущен ли сервис и принимает ли UDP запросы. Возвр. 0 - если сервис недоступен; 1 - сервис запущен
    </p>
    <p>
      <b>net.udp.service.perf[service,&lt;ip&gt;,&lt;port&gt;]</b>&#xa0;&#xa0;Проверяется производительность UDP сервиса. Возвр. 0 - сервис недоступен; секунды - кол-во секунд потраченных в процессе подключения к сервису
    </p>
    <p>
      <b>proc.cpu.util[&lt;name&gt;,&lt;user&gt;,&lt;type&gt;,&lt;cmdline&gt;,&lt;mode&gt;,&lt;zone&gt;]</b>&#xa0;&#xa0;Использование CPU процесса в процентах. Возвр. число с плавающей точкой
    </p>
    <p>
      <b>proc.mem[&lt;name&gt;,&lt;user&gt;,&lt;mode&gt;,&lt;cmdline&gt;,&lt;memtype&gt;]</b>&#xa0;&#xa0;Память используемая процессом в байтах. Возвр. целое число
    </p>
    <p>
      <b>proc.num[&lt;name&gt;,&lt;user&gt;,&lt;state&gt;,&lt;cmdline&gt;]</b>&#xa0;&#xa0;Кол-во процессов. Возвр. число
    </p>
    <p>
      <b>sensor[device,sensor,&lt;mode&gt;]</b>&#xa0;&#xa0;Чтение аппаратного сенсора. Возвр. число с плавающей точкой
    </p>
    <p>
      <b>system.boottime</b>&#xa0;&#xa0;Время загрузки системы. Возвр. целое число (Unix timestamp)
    </p>
    <p>
      <b>system.cpu.discovery</b>&#xa0;&#xa0;Список найденных CPU/CPU ядер. Используется низкоуровневым обнаружением. Возвр. объект JSON
    </p>
    <p>
      <b>system.cpu.intr</b>&#xa0;&#xa0;Прерывания устройства. Возвр. целое число
    </p>
    <p>
      <b>system.cpu.load[&lt;cpu&gt;,&lt;mode&gt;]</b>&#xa0;&#xa0;Загрузка ЦПУ. Возвр. дробное значение
    </p>
    <p>
      <b>system.cpu.num[&lt;type&gt;]</b>&#xa0;&#xa0;Кол-во CPU. Возвр. целое число
    </p>
    <p>
      <b>system.cpu.switches</b>&#xa0;&#xa0;Кол-во переключений контекста. Возвр. целое число
    </p>
    <p>
      <b>system.cpu.util[&lt;cpu&gt;,&lt;type&gt;,&lt;mode&gt;]</b>&#xa0;&#xa0;Утилизация CPU в процентах. Возвр. число с плавающей точкой
    </p>
    <p>
      <b>system.hostname[&lt;type&gt;]</b>&#xa0;&#xa0;Имя узла сети системы. Возвр. строку
    </p>
    <p>
      <b>system.hw.chassis[&lt;info&gt;]</b>&#xa0;&#xa0;&#xa0;&#xa0;Информация о шасси. Возвр. строку
    </p>
    <p>
      <b>system.hw.cpu[&lt;cpu&gt;,&lt;info&gt;]</b>&#xa0;&#xa0;Информация о ЦПУ. Возвр. строку или число
    </p>
    <p>
      <b>system.hw.devices[&lt;type&gt;]</b>&#xa0;&#xa0;Список PCI и USB устройств. Возвр. текст
    </p>
    <p>
      <b>system.hw.macaddr[&lt;interface&gt;,&lt;format&gt;]</b>&#xa0;&#xa0;Список MAC адресов. Возвр. строку
    </p>
    <p>
      <b>system.localtime[&lt;type&gt;]</b>&#xa0;&#xa0;Системное время. Возвр. целое число с типом как utc; строка - с типом как local
    </p>
    <p>
      <b>system.run[command,&lt;mode&gt;]</b>&#xa0;&#xa0;Выполнение заданной команды на узле сети. Возвр. текстовый результат команды; 1 - при наличии режима nowait (вне зависимости от результата команды)
    </p>
    <p>
      <b>system.stat[resource,&lt;type&gt;]</b>&#xa0;&#xa0;Статистика системы. Возвр. целое число или дробное
    </p>
    <p>
      <b>system.sw.arch</b>&#xa0;&#xa0;Информация об архитектуре ПО. Возвр. строку
    </p>
    <p>
      <b>system.sw.os[&lt;info&gt;]</b>&#xa0;&#xa0;&#xa0;&#xa0;Информация об ОС. Возвр. строку
    </p>
    <p>
      <b>system.sw.packages[&lt;package&gt;,&lt;manager&gt;,&lt;format&gt;]</b>&#xa0;&#xa0;Список установленных пакетов. Возвр. текст
    </p>
    <p>
      <b>system.swap.in[&lt;device&gt;,&lt;type&gt;]</b>&#xa0;&#xa0;Статистика swap in (с устройства в память). Возвр. число
    </p>
    <p>
      <b>system.swap.out[&lt;device&gt;,&lt;type&gt;]</b>&#xa0;&#xa0;Статистика swap out (из памяти на устройство). Возвр. число
    </p>
    <p>
      <b>system.swap.size[&lt;device&gt;,&lt;type&gt;]</b>&#xa0;&#xa0;Размер файла подкачки в байтах или в процентах от всего размера. Возвр. целое число для байт; дробное для процентов
    </p>
    <p>
      <b>system.uname</b>&#xa0;&#xa0;Идентификация системы. Возвр. строку
    </p>
    <p>
      <b>system.uptime</b>&#xa0;&#xa0;Системное время в секундах. Возвр. число
    </p>
    <p>
      <b>system.users.num</b>&#xa0;&#xa0;Кол-во пользователей в системе. Возвр. число
    </p>
    <p>
      <b>vfs.dev.read[&lt;device&gt;,&lt;type&gt;,&lt;mode&gt;]</b>&#xa0;&#xa0;Статистика чтения диска. Возвр. целое число в режиме секторов, операций, байт; число с плавающей точкой в режиме sps, ops, bps
    </p>
    <p>
      <b>vfs.dev.write[&lt;device&gt;,&lt;type&gt;,&lt;mode&gt;]</b>&#xa0;&#xa0;Статистика записи на диск. Возвр. целое число в режиме секторов, операции, байт; число с плавающей точкой в sps, ops, bps
    </p>
    <p>
      <b>vfs.dir.count[dir,&lt;regex_incl&gt;,&lt;regex_excl&gt;,&lt;types_incl&gt;,&lt;types_excl&gt;,&lt;max_depth&gt;,&lt;min_size&gt;,&lt;max_size&gt;,&lt;min_age&gt;,&lt;max_age&gt;]</b>&#xa0;&#xa0;Кол-во записей в директории, рекурсивно. Возвр. целое число
    </p>
    <p>
      <b>vfs.dir.size[dir,&lt;regex_incl&gt;,&lt;regex_excl&gt;,&lt;mode&gt;,&lt;max_depth&gt;]</b>&#xa0;&#xa0;Размер директории (в байтах). Возвр. целое число
    </p>
    <p>
      <b>vfs.file.cksum[file]</b>&#xa0;&#xa0;Контрольная сумма файла, вычисляется алгоритмом UNIX cksum. Возвр. целое число
    </p>
    <p>
      <b>vfs.file.contents[file,&lt;encoding&gt;]</b>&#xa0;&#xa0;Получение содержимого файла. Возвр. текст
    </p>
    <p>
      <b>vfs.file.exists[file]</b>&#xa0;&#xa0;Проверка существования файла. Возвр. 0 - файл не найден; 1 - обычный файл или ссылка (жеская или символическая) на существующий обычный файл
    </p>
    <p>
      <b>vfs.file.md5sum[file]</b>&#xa0;&#xa0;Сумма MD5 файла. Возвр. символьную строку (MD5 хеш файла)
    </p>
    <p>
      <b>vfs.file.regexp[file,regexp,&lt;encoding&gt;,&lt;start line&gt;,&lt;end line&gt;,&lt;output&gt;]</b>&#xa0;&#xa0;Поиск строки в файле. Возвр. строка содержащая совпадающую строку, или как определено в дополнительном параметре output
    </p>
    <p>
      <b>vfs.file.regmatch[file,regexp,&lt;encoding&gt;,&lt;start line&gt;,&lt;end line&gt;]</b>&#xa0;&#xa0;Поиск строки в файле. Возвр. 0 - совпадений не найдено; 1 - найдено
    </p>
    <p>
      <b>vfs.file.size[file]</b>&#xa0;&#xa0;Размер файла (в байтах). Возвр. целое число
    </p>
    <p>
      <b>vfs.file.time[file,&lt;mode&gt;]</b>&#xa0;&#xa0;Информация времени файла. Возвр. целое число (Unix timestamp)
    </p>
    <p>
      <b>vfs.fs.discovery</b>&#xa0;&#xa0;Список примонтированных файловых систем. Используется низкоуровневым обнаружением. Возвр. JSON объект. Макрос {#FSDRIVETYPE} поддерживается в Windows начиная с Zabbix агента версии 3.0.
    </p>
    <p>
      <b>vfs.fs.inode[fs,&lt;mode&gt;]</b>&#xa0;&#xa0;Кол-во inode в процентах. Возвр. целое число для количества; дробное - для процентов
    </p>
    <p>
      <b>vfs.fs.size[fs,&lt;mode&gt;]</b>&#xa0;&#xa0;Размер дискового пространства в байтах или процентах от общего. Возвр. целое число в байтах; число с плавающей точкой в процентах
    </p>
    <p>
      <b>vm.memory.size[&lt;mode&gt;]</b>&#xa0;&#xa0;Размер памяти в байтах или в процентах от общей. Возвр. целое число в байтах; целое с плавающей точкой для процетнов
    </p>
    <p>
      <b>web.page.get[host,&lt;path&gt;,&lt;port&gt;]</b>&#xa0;&#xa0;Получение содержимого веб-страницы. Возвр. исходный код веб-страницы в виде текста
    </p>
    <p>
      <b>web.page.perf[host,&lt;path&gt;,&lt;port&gt;]</b>&#xa0;&#xa0;Полное время загрузки веб-страницы (в секундах). Возвр. число с плавающей точкой
    </p>
    <p>
      <b>web.page.regexp[host,&lt;path&gt;,&lt;port&gt;,regexp,&lt;length&gt;,&lt;output&gt;]</b>&#xa0;&#xa0;Поиск строки на веб-странице. Возвр. подходящую строку, или как определено в дополнительном параметре output
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Zabbix internal checks" ID="ID_270812077" CREATED="1543220390467" MODIFIED="1767434162885"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Внутренние проверки</b>&#xa0;&#xa0;позволяют наблюдать за внутренним процессами Zabbix (Zabbix сервер, Zabbix прокси)
    </p>
    <ul>
      <li>
        Внутренние проверки обрабатываются сервером или прокси
      </li>
      <li>
        Тип элемента данных: <b>Zabbix внутренний</b>
      </li>
      <li>
        Внутренние проверки обрабатываются <b>Zabbix поллерами</b>
      </li>
      <li>
        Параметры без угловых скобок являются константами - например, <b>'host' и 'available' в zabbix[host,&lt;тип&gt;,available]</b>. Используйте их в ключе элемента данных без изменения (как есть).
      </li>
    </ul>
    <p>
      <b>zabbix[boottime]</b>&#xa0;&#xa0;Время запуска Zabbix сервера, Unix timestamp.
    </p>
    <p>
      <b>zabbix[history]</b>&#xa0;&#xa0;Кол-во значений записанных в таблице HISTORY.
    </p>
    <p>
      <b>zabbix[history_log]</b>&#xa0;&#xa0;Кол-во значений записанных в таблице HISTORY_LOG.
    </p>
    <p>
      <b>zabbix[history_str]</b>&#xa0;&#xa0;Кол-во значений записанных в таблице HISTORY_STR.
    </p>
    <p>
      <b>zabbix[history_text]</b>&#xa0;&#xa0;Кол-во значений записанных в таблице HISTORY_TEXT.
    </p>
    <p>
      <b>zabbix[history_uint]</b>&#xa0;&#xa0;Кол-во значений записанных в таблице HISTORY_UINT.
    </p>
    <p>
      <b>zabbix[host,,items]</b>&#xa0;&#xa0;Кол-во активированных элементов данных у узла сети.
    </p>
    <p>
      <b>zabbix[host,,items_unsupported]</b>&#xa0;&#xa0;Кол-во неподдерживаемых элементов данных у узла сети.
    </p>
    <p>
      <b>zabbix[host,,maintenance]</b>&#xa0;&#xa0;Получение текущего состояния обслуживания узла сети.
    </p>
    <p>
      <b>zabbix[host,discovery,interfaces]</b>&#xa0;&#xa0;Возвращается <a href="#ID_844733533">JSON</a>&#xa0;объект, описывающий сетевые интерфейсы хоста, добавленного в Zabbix. Может быть использовано LLD правилом.
    </p>
    <p>
      <b>zabbix[host,&lt;type&gt;,available]</b>&#xa0;&#xa0;Получение доступности определенного типа проверок на узле сети. Значение этого элемента данных соответствует иконкам доступности в списке узлов сети. Допустимые типы: agent, snmp, ipmi, jmx.
    </p>
    <p>
      <b>zabbix[hosts]</b>&#xa0;&#xa0;Кол-во наблюдаемых узлов сети
    </p>
    <p>
      <b>zabbix[items]</b>&#xa0;&#xa0;Кол-во элементов данных в базе данных Zabbix.
    </p>
    <p>
      <b>zabbix[items_unsupported]</b>&#xa0;&#xa0;Кол-во неподдерживаемых элементов данных в базе данных Zabbix.
    </p>
    <p>
      <b>zabbix[java,,&lt;param&gt;]</b>&#xa0;&#xa0;Возвращает информацию относящуюся к Zabbix Java gateway. Допустимые параметры: ping, version.
    </p>
    <p>
      <b>zabbix[process,&lt;type&gt;,&lt;mode&gt;,&lt;state&gt;]</b>&#xa0;&#xa0;Время конкретного процесса Zabbix или группы процессов (задаётся &lt;типом&gt; и &lt;режимом&gt;) проведённое в &lt;состоянии&gt; в процентах.
    </p>
    <p>
      <b>zabbix[proxy,&lt;name&gt;,&lt;param&gt;]</b>&#xa0;&#xa0;Время последнего доступа к прокси. Имя - имя прокси. Параметр - lastaccess. Unix timestamp.
    </p>
    <p>
      <b>zabbix[proxy_history]</b>&#xa0;&#xa0;Кол-во элементов данных в истории прокси, которые еще не были отправлены на сервер
    </p>
    <p>
      <b>zabbix[queue,&lt;from&gt;,&lt;to&gt;]</b>&#xa0;&#xa0;Кол-во элементов данных в очереди, которые задерживаются от и до секунд, включительно.
    </p>
    <p>
      <b>zabbix[rcache,&lt;cache&gt;,&lt;mode&gt;]</b>&#xa0;&#xa0;Статистика конфигурационного кэша. Кэш - буфер (режимы: pfree, total, used, free).
    </p>
    <p>
      <b>zabbix[requiredperformance]</b>&#xa0;&#xa0;Требуемая производительность Zabbix сервера, в ожидаемом Кол-во новых значений в секунду.
    </p>
    <p>
      <b>zabbix[trends]</b>&#xa0;&#xa0;Кол-во значений записанных в таблице TRENDS.
    </p>
    <p>
      <b>zabbix[trends_uint]</b>&#xa0;&#xa0;Кол-во значений записанных в таблице TRENDS_UINT.
    </p>
    <p>
      <b>zabbix[triggers]</b>&#xa0;&#xa0;Кол-во триггеров в базе данных Zabbix.
    </p>
    <p>
      <b>zabbix[uptime]</b>&#xa0;&#xa0;Время работы процесса Zabbix сервера в секундах.
    </p>
    <p>
      <b>zabbix[vcache,buffer,&lt;mode&gt;]</b>&#xa0;&#xa0;Статистика кэша значений. Допустимые значения: total, free, pfree, used и pused.
    </p>
    <p>
      <b>zabbix[vcache,cache,&lt;parameter&gt;]</b>&#xa0;&#xa0;Эффективность кэша значений. Допустимые параметры: requests, hits и misses.
    </p>
    <p>
      <b>zabbix[vmware,buffer,&lt;mode&gt;]</b>&#xa0;&#xa0;Статистика VMware кэша. Возможные режимы: total, free, pfree, used и pused.
    </p>
    <p>
      <b>zabbix[wcache,&lt;cache&gt;,&lt;mode&gt;]</b>&#xa0;&#xa0;Статистика кэша данных. Кэш - одно из значений (режимы: all, float, uint, str, log, text), history (режимы: pfree, total, used, free), trends (режимы: pfree, total, used, free), text (режимы: pfree, total, used, free).
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Zabbix trapper" FOLDED="true" ID="ID_770323623" CREATED="1543773084780" MODIFIED="1766047837088"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Trapper items</span>&#xa0;- <span style="font-weight: normal;">принимают входящие данные от внешних источников, вместо того чтобы активно их запрашивать</span>
    </p>
    <ul>
      <li>
        Подходят для <span style="font-weight: bold;">асинхронных событий</span>&#xa0;(ошибки, билды, деплои и т.п.)
      </li>
      <li>
        Не создают нагрузки на сервер (нет опроса по расписанию)
      </li>
      <li>
        Гибкая интеграция с внешними системами и скриптами
      </li>
      <li>
        Возможность отправки данных с хостов, недоступных для прямого опроса
      </li>
      <li>
        <span style="font-weight: bold;">zabbix_sender</span>&#xa0;может отправлять несколько значений за один вызов (через файл или stdin)
      </li>
      <li>
        Trapper-элементы <span style="font-weight: bold;">не работают с активными агентами</span>&#xa0;- они используют отдельный протокол и порт
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Требования к использованию. </span>Чтобы использовать траппер-элемент, необходимо:
    </p>
    <ol>
      <li>
        <span style="font-weight: bold;">Создать</span>&#xa0;элемент данных типа &quot;Zabbix trapper&quot; в конфигурации узла сети (хоста) в веб-интерфейсе Zabbix
      </li>
      <li>
        <span style="font-weight: bold;">Отправлять</span>&#xa0;данные в Zabbix с использованием утилиты <span style="font-weight: bold;">zabbix_sender</span>, Zabbix API или другого совместимого инструмента
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Настройка элемента данных</span>
    </p>
    <p>
      При создании элемента-траппера в веб-интерфейсе Zabbix укажите следующие параметры:
    </p>
    <ul>
      <li>
        Тип: Zabbix trapper
      </li>
      <li>
        Ключ: Уникальный идентификатор, по которому будут распознаваться входящие данные (например, custom.log.errors)
      </li>
      <li>
        Тип информации: Должен соответствовать формату передаваемых данных: числовой (unsigned/signed float/integer), текст, лог и т.д.

        <ul>
          <li>
            Разрешённые хосты: (Опционально) Список IP-адресов, с которых разрешено принимать данные. Указывается через запятую. Если поле пусто - ограничений нет
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Имя хоста</span>, указанное при отправке данных, должно <span style="font-weight: bold;">точно совпадать</span>&#xa0;с техническим именем хоста (host name), заданным в Zabbix (не с &quot;видимым именем&quot; / visible name)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Отправка данных</span>
    </p>
    <p>
      <span style="color: #0000c0;">zabbix_sender -z 192.168.1.10 -s &quot;web-server-01&quot; -k errors.last_hour -o 17</span>
    </p>
    <ul>
      <li>
        -z - IP-адрес (или DNS-имя) Zabbix-сервера или Zabbix-proxy
      </li>
      <li>
        -p - порт сервера (по умолчанию 10051)
      </li>
      <li>
        -s - техническое имя хоста, зарегистрированного в Zabbix
      </li>
      <li>
        -k - ключ элемента-траппера
      </li>
      <li>
        -o - отправляемое значение
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Просмотр полученных данных </span>
    </p>
    <p>
      Мониторинг &gt; Последние данные &gt; Выберите нужный хост &gt; найдите ваш элемент по ключу
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Установка на наблюдаемом хосте</span>
    </p>
    <p>
      <span style="color: #0000c0;">apt install zabbix-sender</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="Пример" ID="ID_795408063" CREATED="1766045248366" MODIFIED="1766049955229"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">1. Создать траппер</span>
    </p>
    <ol>
      <li>
        Data collection &gt; Hosts &gt; Items (agent_simple) &gt; Create item
      </li>
      <li>
        <span style="font-weight: bold;">&gt; Item</span><br/>Name: Zabbix trap receiver<br/>Type: Zabbix trapper<br/>Key: trap<br/>Type of information: Text<br/>
      </li>
      <li>
        <span style="font-weight: bold;">&gt; Tags</span><br/>component:zabbix trapper
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. На наблюдаемом сервере (установка, отправка информации)</span>
    </p>
    <p>
      <span style="color: #0000c0;">apt install zabbix-sender</span>&#xa0;&#xa0;# Установить пакет с Zabbix sender
    </p>
    <p>
      <span style="color: #0000c0;">zabbix_sender -z 192.168.1.77 -s &quot;agent_simple&quot; -k trap -o &quot;Test trapper&quot;</span>&#xa0;&#xa0;# Отправить информацию
    </p>
    <ul>
      <li>
        -z - IP-адрес сервера Zabbix
      </li>
      <li>
        -s - имя узла сети, которому принадлежит элемент данных
      </li>
      <li>
        -k - ключ элемента данных, на который отправляются данные
      </li>
      <li>
        -o - значение элемента данных
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. Проверка получения данных на zabbix-сервере</span>
    </p>
    <p>
      Monitoring &gt; Hosts &gt; Latest data (agent_simple)
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Агрегированные проверки" FOLDED="true" ID="ID_1665319401" CREATED="1543220426169" MODIFIED="1765800044131"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>В агрегированных проверках</b>&#xa0;Zabbix сервер собирает совокупную информацию из элементов данных, выполняя прямые запросы в базу данных.
    </p>
    <ul>
      <li>
        Агрегированные проверки <b>не требуют агента</b>&#xa0;на наблюдаемом узле сети
      </li>
      <li>
        Если результатом агрегации будет число с плавающей точкой, оно будет обрезано до целого числа, в случае если типом информации агрегированного элемента данных указан Числовой (целое положительное)
      </li>
      <li>
        Все элементы данных, на которые имеется ссылка из ключа агрегированного элемента данных, должны существовать и собирать данные. В вычисления добавляются только активированные элементы данных у активированных узлов сети
      </li>
      <li>
        Ключ агрегированного элемента данных необходимо обновлять вручную, если будет изменен ключ элемента данных на который агрегированный элемент данных ссылается.
      </li>
    </ul>
    <p>
      <b>Синтаксис ключа агрегированного элемента данных: </b>
    </p>
    <p>
      функция_группировки[&quot;группа узлов сети&quot;,&quot;ключ элемента данных&quot;,функция_элемента_данных,период_времени]
    </p>
    <p>
      
    </p>
    <p>
      <b>Функций группировки</b>
    </p>
    <p>
      <b>grpavg</b>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Среднее значение
    </p>
    <p>
      <b>grpmax</b>&#xa0;&#xa0;&#xa0;&#xa0;Максимальное значение
    </p>
    <p>
      <b>grpmin</b>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Минимальное значение
    </p>
    <p>
      <b>grpsum</b>&#xa0;&#xa0;&#xa0;&#xa0;Сумма значений
    </p>
    <p>
      
    </p>
    <p>
      Поддерживаемые функции элементов данных (<b>функция_элемента_данных</b>):
    </p>
    <p>
      <b>avg</b>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Среднее значение
    </p>
    <p>
      <b>count</b>&#xa0;&#xa0;Количество значений
    </p>
    <p>
      <b>last</b>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Последнее значение
    </p>
    <p>
      <b>max</b>&#xa0;&#xa0;&#xa0;&#xa0;Максимальное значение
    </p>
    <p>
      <b>min</b>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Минимальное значение
    </p>
    <p>
      <b>sum</b>&#xa0;&#xa0;&#xa0;&#xa0;Сумма значений
    </p>
    <p>
      
    </p>
    <p>
      Параметр <b>период_времени</b>&#xa0;задает период времени последних собранных значений. Для удобства вы можете использовать поддерживаемые символы единиц измерения, например '5m' (минут) вместо '300' (секунд) или '1d' (день) вместо '86400' (секунд). Параметр период_времени игнорируется сервером в случае, если третий параметр (функция элемента данных) - last и его можно не указывать:
    </p>
    <p>
      
    </p>
    <p>
      <b>Агрегированный элемент данных может стать неподдерживамым, если:</b>
    </p>
    <ul>
      <li>
        Не найдено ни одного элемента данных, на которые он ссылается (что может произойти, если ключ элемента данных некорректный, элементы данных не существуют или все добавленные группы некорректны)
      </li>
      <li>
        Отсутствуют данные для вычисления функции
      </li>
    </ul>
  </body>
</html></richcontent>
