<node TEXT="Журналирование (Сервер, Прокси)" ID="ID_20306793" CREATED="1542184732986" MODIFIED="1543497049972"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1046;&#1091;&#1088;&#1085;&#1072;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; (&#1057;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1055;&#1088;&#1086;&#1082;&#1089;&#1080;)</b>. &#1044;&#1083;&#1103; &#1055;&#1088;&#1086;&#1082;&#1089;&#1080; &#1084;&#1077;&#1085;&#1103;&#1077;&#1084; 'server' &#1085;&#1072; 'proxy'
    </p>
    <ul>
      <li>
        &#1044;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1085;&#1072; &#1074;&#1089;&#1077; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1099;, &#1077;&#1089;&#1083;&#1080; &#1094;&#1077;&#1083;&#1100; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1072;
      </li>
      <li>
        &#1055;&#1088;&#1086;&#1082;&#1089;&#1080; - &#1077;&#1089;&#1083;&#1080; &#1074; &#1088;&#1086;&#1083;&#1080; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1074;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084;&#1072;&#1103; &#1084;&#1072;&#1096;&#1080;&#1085;&#1072;, &#1083;&#1091;&#1095;&#1096;&#1077; &#1079;&#1072;&#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;, &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1074; syslog &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1091; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1074; &#1089;&#1077;&#1090;&#1080;
      </li>
    </ul>
    <p>
      <b>log_level_increase[=&lt;&#1094;&#1077;&#1083;&#1100;&gt;]</b>&#160;- &#1059;&#1074;&#1077;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
    </p>
    <p>
      <b>log_level_decrease[=&lt;&#1094;&#1077;&#1083;&#1100;&gt;]</b>&#160;- &#1059;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1085;&#1080;&#1077; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
    </p>
    <ul>
      <li>
        pid - &#1048;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; (1 &#1076;&#1086; 65535)
      </li>
      <li>
        &#1090;&#1080;&#1087; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; - &#1042;&#1089;&#1077; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1099; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1090;&#1080;&#1087;&#1072; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, poller)
      </li>
      <li>
        &#1090;&#1080;&#1087; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072;,N - &#1058;&#1080;&#1087; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1080; &#1085;&#1086;&#1084;&#1077;&#1088; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, poller,3)
      </li>
    </ul>
    <p>
      <b>&#1055;&#1088;&#1080;&#1084;&#1077;&#1088;&#1099;</b>
    </p>
    <p>
      <font color="#0000c0">zabbix_<b>server</b>&#160;-c /usr/local/etc/zabbix_<b>server</b>.conf -R log_level_increase</font>&#160;&#160;# &#1059;&#1074;&#1077;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1078;&#1091;&#1088;&#1085;. &#1087;&#1086; &#1074;&#1089;&#1077;&#1084; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072;&#1084;
    </p>
    <p>
      <font color="#0000c0">zabbix_server -c /usr/local/etc/zabbix_server.conf -R log_level_increase=poller,2</font>&#160;&#160;# &#1059;&#1074;&#1077;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1078;&#1091;&#1088;&#1085;. &#1091; &#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1087;&#1086;&#1083;&#1083;&#1077;&#1088;&#1072;
    </p>
    <p>
      <font color="#0000c0">zabbix_server -c /usr/local/etc/zabbix_server.conf -R log_level_increase=1234</font>&#160;&#160;# &#1059;&#1074;&#1077;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1078;&#1091;&#1088;&#1085;. &#1091;&#160;&#160;&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1089; PID 1234
    </p>
    <p>
      <font color="#0000c0">zabbix_server -c /usr/local/etc/zabbix_server.conf -R log_level_decrease=&quot;http poller&quot;</font>&#160;&#160;# &#1059;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1085;&#1080;&#1077; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1078;&#1091;&#1088;&#1085;. &#1087;&#1086; &#1074;&#1089;&#1077;&#1084; http &#1087;&#1086;&#1083;&#1083;&#1077;&#1088; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072;&#1084;
    </p>
  </body>
</html></richcontent>
</node>
