        &#1090;&#1080;&#1087; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072;,N - &#1090;&#1080;&#1087; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1080; &#1085;&#1086;&#1084;&#1077;&#1088; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, listener,3)
