<node TEXT="1. Подготовка CentOS7 к установке" ID="ID_996351937" CREATED="1542713651780" MODIFIED="1553613989042"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100;, &#1083;&#1080;&#1073;&#1086; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; firewall:</b>
    </p>
    <p>
      <font color="#0000c0">systemctl stop firewalld </font>
    </p>
    <p>
      <font color="#0000c0">systemctl disable firewalld</font>
    </p>
    <p>
      <b>2. &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081; nginx. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; nginx</b>
    </p>
    <p>
      <font color="#0000c0">rpm -Uvh http://nginx.org/packages/centos/7/noarch/RPMS/nginx-release-centos-7-0.el7.ngx.noarch.rpm </font>
    </p>
    <p>
      <font color="#0000c0">yum -y install nginx</font>
    </p>
    <p>
      <font color="#0000c0">systemctl start nginx</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; nginx
    </p>
    <p>
      <font color="#0000c0">systemctl enable nginx</font>&#160;&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074; &#1072;&#1074;&#1090;&#1086;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091; --&gt; &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1074;&#1074;&#1077;&#1076;&#1103; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077;
    </p>
    <p>
      <b>3. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; php-fpm</b>&#160;(FastCGI Process Manager, &#1084;&#1077;&#1085;&#1077;&#1076;&#1078;&#1077;&#1088; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1074; FastCGI)
    </p>
    <p>
      <font color="#0000c0">yum -y install epel-release</font>&#160;&#160;# &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081;
    </p>
    <p>
      <font color="#0000c0">rpm -Uhv http://rpms.remirepo.net/enterprise/remi-release-7.rpm</font>&#160;&#160;# &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081;
    </p>
    <p>
      <font color="#0000c0">yum -y install yum-utils</font>&#160;&#160;# &#1044;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; yum-config-manager
    </p>
    <p>
      <font color="#0000c0">yum-config-manager --enable remi-php71</font>&#160;&#160;# &#1040;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081;
    </p>
    <p>
      <font color="#0000c0">yum -y install php71 php-fpm php-cli php-mysql php-gd php-ldap php-odbc php-pdo php-pecl-memcache php-pear php-xml php-xmlrpc php-mbstring php-snmp php-soap php-bcmath</font>&#160;&#160;# &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; php 7.1 &#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;
    </p>
    <p>
      <font color="#0000c0">systemctl start php-fpm</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; php-fpm
    </p>
    <p>
      <font color="#0000c0">systemctl enable php-fpm</font>&#160;&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; php-fpm &#1074; &#1072;&#1074;&#1090;&#1086;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;
    </p>
    <p>
      <font color="#0000c0">netstat -tulpn</font>&#160;&#160;# &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; --&gt; &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1083;&#1089;&#1103; &#1085;&#1072; &#1087;&#1086;&#1088;&#1090;&#1091; 9000 --&gt; &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1077;&#1075;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; unix &#1089;&#1086;&#1082;&#1077;&#1090;
    </p>
    <p>
      <font color="#0000c0">vim /etc/php-fpm.d/www.conf&#160;</font>
    </p>
    <p>
      <font color="#008000">; listen = 127.0.0.1:9000 </font>
    </p>
    <p>
      <font color="#008000">listen = /var/run/php-fpm/php-fpm.sock </font>
    </p>
    <p>
      <font color="#008000">listen.mode = 0660 </font>
    </p>
    <p>
      <font color="#008000">listen.owner = nginx </font>
    </p>
    <p>
      <font color="#008000">listen.group = nginx </font>
    </p>
    <p>
      <font color="#008000">user = nginx </font>
    </p>
    <p>
      <font color="#008000">group = nginx</font>
    </p>
    <p>
      <font color="#0000c0">systemctl restart php-fpm</font>&#160;&#160;# &#1055;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; php-fpm
    </p>
    <p>
      <font color="#0000c0">ls -l /var/run/php-fpm/php-fpm.sock</font>&#160;&#160;# &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1089;&#1090;&#1072;&#1088;&#1090;&#1086;&#1074;&#1072;&#1083; &#1083;&#1080; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1081; &#1089;&#1086;&#1082;&#1077;&#1090;.
    </p>
    <p>
      <b>4. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; MariaDB. </b>
    </p>
    <p>
      <font color="#0000c0">vim /etc/yum.repos.d/mariadb.repo</font>&#160;&#160;# &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081;
    </p>
    <p>
      <font color="#008000"># MariaDB 10.3 CentOS repository list - created 2018-10-04 12:10 UTC </font>
    </p>
    <p>
      <font color="#008000"># http://downloads.mariadb.org/mariadb/repositories/ </font>
    </p>
    <p>
      <font color="#008000">[mariadb] </font>
    </p>
    <p>
      <font color="#008000">name = MariaDB </font>
    </p>
    <p>
      <font color="#008000">baseurl = http://yum.mariadb.org/10.3/centos7-amd64 </font>
    </p>
    <p>
      <font color="#008000">gpgkey=https://yum.mariadb.org/RPM-GPG-KEY-MariaDB </font>
    </p>
    <p>
      <font color="#008000">gpgcheck=1</font>
    </p>
    <p>
      <font color="#0000c0">yum -y install MariaDB-server MariaDB-client</font>&#160;&#160;# &#1059;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1102;&#1102; &#1074;&#1077;&#1088;&#1089;&#1080;&#1102; mariadb &#1085;&#1072; centos.
    </p>
    <p>
      <font color="#0000c0">systemctl start mariadb</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; mariadb
    </p>
    <p>
      <font color="#0000c0">systemctl enable mariadb</font>&#160;&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; mariadb &#1074; &#1072;&#1074;&#1090;&#1086;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;
    </p>
    <p>
      <font color="#0000c0">/usr/bin/mysql_secure_installation</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;. &#1047;&#1072;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; root. &#1054;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1087;&#1086;-&#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;.
    </p>
    <p>
      <b>5. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; MariaDB. &#1055;&#1088;&#1080;&#1074;&#1077;&#1089;&#1090;&#1080; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075; mariadb &#1082; &#1074;&#1080;&#1076;&#1091;.</b>&#160;&#1047;&#1076;&#1077;&#1089;&#1100; &#1079;&#1072;&#1076;&#1072;&#1085;&#1099; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1074;&#1072;&#1078;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1087;&#1086; innodb, &#1074; &#1095;&#1072;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1077; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1082;&#1072;&#1078;&#1076;&#1091;&#1102; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1074; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1084; &#1092;&#1072;&#1081;&#1083;&#1077;, &#1079;&#1072;&#1076;&#1072;&#1085; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1080; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1073;&#1080;&#1085;&#1072;&#1088;&#1085;&#1099;&#1093; &#1083;&#1086;&#1075;&#1086;&#1074; &#1080; &#1077;&#1097;&#1077; &#1087;&#1072;&#1088;&#1091; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1103;&#1074;&#1085;&#1086; &#1073;&#1091;&#1076;&#1091;&#1090; &#1082; &#1084;&#1077;&#1089;&#1090;&#1091; (innodb_buffer_pool_size, innodb_buffer_pool_instances &#1080; innodb_flush_log_at_trx_commit)
    </p>
    <p>
      <font color="#0000c0">vim /etc/my.cnf.d/server.cnf</font>
    </p>
    <p>
      <font color="#008000">[client] </font>
    </p>
    <p>
      <font color="#008000">port&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;= 3306 </font>
    </p>
    <p>
      <font color="#008000">socket&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;= /var/lib/mysql/mysql.sock </font>
    </p>
    <p>
      <font color="#008000">default-character-set=utf8 </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">[mysqld] </font>
    </p>
    <p>
      <font color="#008000">character_set_server=utf8 </font>
    </p>
    <p>
      <font color="#008000">collation-server=utf8_bin </font>
    </p>
    <p>
      <font color="#008000">init_connect=&quot;SET NAMES utf8 collate utf8_bin&quot; </font>
    </p>
    <p>
      <font color="#008000">port&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;= 3306 </font>
    </p>
    <p>
      <font color="#008000">socket&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;= /var/lib/mysql/mysql.sock </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">innodb_file_per_table=1 </font>
    </p>
    <p>
      <font color="#008000">innodb_buffer_pool_size = 768M&#160; </font># &#1042;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;! &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; &#1074; 2 &#1088;&#1072;&#1079;&#1072; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; &#1086;&#1073;&#1098;&#1077;&#1084;&#1072; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <p>
      <font color="#008000">innodb_buffer_pool_instances=1</font>&#160;&#160;# &#1059;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; 1 &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; GB innodb_buffer_pool_size
    </p>
    <p>
      <font color="#008000">innodb_flush_log_at_trx_commit = 0 </font>
    </p>
    <p>
      <font color="#008000">innodb_log_file_size = 512M </font>
    </p>
    <p>
      <font color="#008000">innodb_log_files_in_group = 3 </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">[server] </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">[galera] </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">[embedded] </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">[mariadb] </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">[mariadb-10.3]</font>
    </p>
    <p>
      <font color="#0000c0">systemctl restart mariadb</font>&#160;&#160;# &#1055;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077; mariadb
    </p>
    <p>
      <font color="#0000c0">systemctl status mariadb.service</font>&#160;&#160;# &#1057;&#1090;&#1072;&#1090;&#1091;&#1089; mariadb
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="2. Установка сервера Zabbix 4.0 в CentOS7" ID="ID_1132660356" CREATED="1542719343066" MODIFIED="1553614053888"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081;</b>
    </p>
    <p>
      <font color="#0000c0">rpm -Uvh https://repo.zabbix.com/zabbix/4.0/rhel/7/x86_64/zabbix-release-4.0-1.el7.noarch.rpm</font>
    </p>
    <p>
      <b>2. &#1040;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081;</b>&#160;&#1086;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; rpm &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077;, &#1075;&#1076;&#1077; &#1074;&#1099; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1077; &#1074;&#1077;&#1073;-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; Zabbix
    </p>
    <p>
      <font color="#0000c0">yum-config-manager --enable rhel-7-server-optional-rpms</font>
    </p>
    <p>
      <b>3. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;/&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;/&#1074;&#1077;&#1073;-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;</b>
    </p>
    <p>
      <font color="#0000c0">yum install zabbix-server-mysql zabbix-web-mysql </font>
    </p>
    <p>
      <font color="#0000c0">yum install zabbix-proxy-mysql</font>&#160;&#160;#&#160;&#160;&#1044;&#1083;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; Zabbix &#1087;&#1088;&#1086;&#1082;&#1089;&#1080; &#1089; MySQL:
    </p>
    <p>
      <b>4.&#160;C&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1041;&#1044;, &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; zabbix &#1080; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1073;&#1072;&#1079;&#1091;.</b>
    </p>
    <p>
      <font color="#0000c0">mysql -uroot -p</font>&#160;&#160;# --&gt; Enter password:
    </p>
    <p>
      <font color="#0000c0">&gt; create database zabbix character set utf8 collate utf8_bin; </font>
    </p>
    <p>
      <font color="#0000c0">&gt; grant all privileges on zabbix.* to zabbix@localhost identified by 'Pa$$w0rd'; </font>
    </p>
    <p>
      <font color="#0000c0">&gt; exit</font>
    </p>
    <p>
      <font color="#0000c0">zcat /usr/share/doc/zabbix-server-mysql*/create.sql.gz | mysql -uzabbix -p zabbix</font>
    </p>
    <p>
      <b>5.</b>&#160;<font color="#0000c0">vim /etc/zabbix/zabbix_server.conf</font>&#160;&#160;# &#1060;&#1072;&#1081;&#1083; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1079;&#1072;&#1073;&#1073;&#1080;&#1082;&#1089;. &#1055;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; &#1041;&#1044;, &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; ipv6 &#1080; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1074;&#1072;&#1077;&#1084; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; timeout. &#1048;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;, &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1085;&#1077; &#1090;&#1088;&#1086;&#1075;&#1072;&#1090;&#1100;:
    </p>
    <p>
      <font color="#008000">DBHost=localhost </font>
    </p>
    <p>
      <font color="#008000">DBName=zabbix </font>
    </p>
    <p>
      <font color="#008000">DBUser=zabbix </font>
    </p>
    <p>
      <font color="#008000">DBPassword=Pa$$w0rd </font>
    </p>
    <p>
      <font color="#008000">ListenIP=0.0.0.0 </font>
    </p>
    <p>
      <font color="#008000">Timeout=10&#160;&#160;#&#160;&#160;&#1054;</font>&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1074;&#1088;&#1077;&#1084;&#1103; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1103; &#1086;&#1090;&#1074;&#1077;&#1090;&#1072; &#1086;&#1090; &#1072;&#1075;&#1077;&#1085;&#1090;&#1072;, snmp &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1080;&#1083;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1080;. &#1048;&#1085;&#1086;&#1075;&#1076;&#1072; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086;&#1075;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074; 4 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1099; &#1073;&#1099;&#1074;&#1072;&#1077;&#1090; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086;
    </p>
    <p>
      <b>6. &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; zabbix &#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074; &#1072;&#1074;&#1090;&#1086;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;</b>
    </p>
    <p>
      <font color="#0000c0">systemctl start zabbix-server</font>
    </p>
    <p>
      <font color="#0000c0">systemctl enable zabbix-server</font>
    </p>
    <p>
      <b>7. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1083;&#1086;&#1075; &#1092;&#1072;&#1081;&#1083; &#1085;&#1072; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082;.</b>
    </p>
    <p>
      <font color="#0000c0">cat /var/log/zabbix/zabbix_server.log</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="3. Настройка SELinux и Nginx" ID="ID_973238391" CREATED="1542788465989" MODIFIED="1553614053921"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1473215926">SELinux</a>
    </p>
    <p>
      
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; SELinux, &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1084; &#1086;&#1096;&#1080;&#1073;&#1082;&#1091;. cannot start preprocessing service: Cannot bind socket to &quot;/var/run/zabbix/zabbix_server_preprocessing.sock&quot;: [13] Permission denied.
    </p>
    <p>
      <b>1. &#1057;&#1090;&#1072;&#1074;&#1080;&#1084; &#1087;&#1072;&#1082;&#1077;&#1090; policycoreutils-python, &#1089;&#1082;&#1072;&#1095;&#1080;&#1074;&#1072;&#1077;&#1084; &#1075;&#1086;&#1090;&#1086;&#1074;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1076;&#1083;&#1103; SELinux &#1080; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &#1077;&#1075;&#1086;.</b>
    </p>
    <p>
      <font color="#0000c0">yum install policycoreutils-python</font>
    </p>
    <p>
      <font color="#0000c0">cd ~</font>
    </p>
    <p>
      <font color="#0000c0">curl https://support.zabbix.com/secure/attachment/53320/zabbix_server_add.te &gt; zabbix_server_add.te </font>
    </p>
    <p>
      <font color="#0000c0">checkmodule -M -m -o zabbix_server_add.mod zabbix_server_add.te </font>
    </p>
    <p>
      <font color="#0000c0">semodule_package -m zabbix_server_add.mod -o zabbix_server_add.pp </font>
    </p>
    <p>
      <font color="#0000c0">semodule -i zabbix_server_add.pp</font>
    </p>
    <p>
      <font color="#0000c0">systemctl restart zabbix-server</font>&#160;&#160;# &#1055;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; zabbix-server. &#1045;&#1089;&#1083;&#1080; &#1079;&#1072;&#1074;&#1080;&#1089; &#1091;&#1073;&#1080;&#1090;&#1100; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100;.
    </p>
    <p>
      &#1057;&#1085;&#1086;&#1074;&#1072; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1081;&#1090;&#1077; log &#1092;&#1072;&#1081;&#1083;. &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082; &#1073;&#1099;&#1090;&#1100; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086;
    </p>
    <p>
      <b>2. &#1057;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075; nginx &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; web-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; zabbix.</b>&#160; &#1045;&#1089;&#1083;&#1080; &#1091; &#1074;&#1072;&#1089; nginx &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1085;&#1072; &#1090;&#1086;&#1084; &#1078;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;, &#1075;&#1076;&#1077; &#1089;&#1072;&#1084; zabbix, &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1093;&#1086;&#1089;&#1090;&#1086;&#1074; &#1085;&#1077;&#1090; &#1080; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090;, &#1090;&#1086; &#1087;&#1088;&#1072;&#1074;&#1100;&#1090;&#1077; &#1089;&#1088;&#1072;&#1079;&#1091; &#1076;&#1077;&#1092;&#1086;&#1083;&#1090;&#1085;&#1099;&#1081;
    </p>
    <p>
      <font color="#008000"><b># /etc/nginx/conf.d/default.conf</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">server { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;listen&#160;&#160;&#160;&#160;&#160;&#160;&#160;80; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;server_name&#160;&#160;localhost; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;root /usr/share/zabbix; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;location / { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;index index.php index.html index.htm; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;location ~ \.php$ { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;fastcgi_pass unix:/var/run/php-fpm/php-fpm.sock; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;fastcgi_index index.php; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;fastcgi_param SCRIPT_FILENAME&#160;&#160;$document_root$fastcgi_script_name; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;include fastcgi_params; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;fastcgi_param PHP_VALUE &quot; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;max_execution_time = 300 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;memory_limit = 128M </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;post_max_size = 16M </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;upload_max_filesize = 2M </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;max_input_time = 300 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;date.timezone = Europe/Moscow </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;always_populate_raw_post_data = -1 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&quot;; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;fastcgi_buffers 8 256k; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;fastcgi_buffer_size 128k; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;fastcgi_intercept_errors on; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;fastcgi_busy_buffers_size 256k; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;fastcgi_temp_file_write_size 256k; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;} </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
    <p>
      <b>3. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075; &#1085;&#1072; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; &#1080; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; nginx.</b>
    </p>
    <p>
      <font color="#0000c0">nginx -t </font>
    </p>
    <p>
      <font color="#0000c0">nginx -s reload</font>
    </p>
    <p>
      <b>4. &#1048;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1087;&#1088;&#1072;&#1074;&#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1085;&#1072; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1072;&#1087;&#1082;&#1080;. &#1053;&#1072;&#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1100; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1072; nginx. </b>&#1069;&#1090;&#1086;&#1090; &#1096;&#1072;&#1075; &#1085;&#1091;&#1078;&#1085;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1076;&#1077;&#1083;&#1099;&#1074;&#1072;&#1090;&#1100; <b>&#1087;&#1086;&#1089;&#1083;&#1077; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; php &#1080;&#1083;&#1080; zabbix</b>. &#1057;&#1074;&#1103;&#1079;&#1072;&#1085;&#1086; &#1089; &#1090;&#1077;&#1084;, &#1095;&#1090;&#1086; &#1087;&#1086;-&#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; zabbix &#1080;&#1076;&#1077;&#1090; &#1074; &#1082;&#1086;&#1084;&#1087;&#1083;&#1077;&#1082;&#1090;&#1077; &#1089; apache &#1080; &#1088;&#1072;&#1089;&#1089;&#1095;&#1080;&#1090;&#1072;&#1085; &#1085;&#1072; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091; &#1089; &#1085;&#1080;&#1084;. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1087;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1080;&#1083;&#1080; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;, &#1086;&#1085; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090; &#1077;&#1075;&#1086; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1077;&#1084; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; /etc/zabbix/web.
    </p>
    <p>
      <font color="#0000c0">chown -R nginx:nginx /var/lib/php/session </font>
    </p>
    <p>
      <font color="#0000c0">chown -R nginx:nginx /etc/zabbix/web</font>
    </p>
    <p>
      <b>5. &#1044;&#1072;&#1090;&#1100; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1103; SELinux &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1079;&#1072;&#1073;&#1073;&#1080;&#1082;&#1089;&#1072; &#1089; web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084; &#1080; &#1073;&#1072;&#1079;&#1086;&#1081; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.</b>
    </p>
    <p>
      <font color="#0000c0">setsebool -P httpd_can_connect_zabbix on </font>
    </p>
    <p>
      <font color="#0000c0">setsebool -P httpd_can_network_connect_db on</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
