<node TEXT="1. Установка демонов" FOLDED="true" ID="ID_660256040" CREATED="1542364672104" MODIFIED="1542888260365"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1076;&#1077;&#1084;&#1086;&#1085;&#1086;&#1074; Zabbix. Zabbix + PHP + MySQL + Apache</b>
    </p>
    <p>
      <b>&#1053;&#1077;&#1090;, &#1074;&#1089;&#1077; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1074; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;&#1094;&#1080;&#1080; &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1095;&#1080;&#1082; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077; &#1079;&#1072;&#1093;&#1086;&#1090;&#1077;&#1083; &#1080; &#1087;&#1088;&#1080; &#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1103;&#1094;&#1080;&#1080; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1083;&#1086;&#1089;&#1100; &#1075;&#1091;&#1075;&#1083;&#1080;&#1090;&#1100; &#1082;&#1072;&#1078;&#1076;&#1091;&#1102; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080;. &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;&#1094;&#1080;&#1103; &#1087;&#1086; &#1080;&#1085;&#1089;&#1090;&#1072;&#1083;&#1083;&#1103;&#1094;&#1080;&#1080; &#1080;&#1079; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1082;&#1086;&#1076;&#1086;&#1074; &#1089;&#1076;&#1077;&#1083;&#1072;&#1085;&#1072; &#1085;&#1072; &quot;&#1086;&#1090;&#1098;&#1077;&#1073;&#1080;&#1089;&#1100;&quot;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1047;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1077; &#1072;&#1088;&#1093;&#1080;&#1074; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1082;&#1086;&#1076;&#1086;&#1074; &#1080; &#1088;&#1072;&#1089;&#1087;&#1072;&#1082;&#1086;&#1074;&#1072;&#1090;&#1100;</b>
    </p>
    <p>
      <font color="#0000c0">tar zxvf zabbix-&lt;&#1085;&#1086;&#1084;&#1077;&#1088; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080;&gt;.tar.gz</font>
    </p>
    <p>
      <b>2.1 &#1057;&#1086;&#1079;&#1076;&#1072;&#1081;&#1090;&#1077; &#1072;&#1082;&#1082;&#1072;&#1091;&#1085;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1072;&#1097;&#1077;&#1075;&#1086; &#1082; &#1075;&#1088;&#1091;&#1087;&#1087;&#1077;, &#8220;zabbix&#8221;)</b>
    </p>
    <p>
      RHEL
    </p>
    <p>
      <font color="#0000c0">groupadd --system zabbix </font>
    </p>
    <p>
      <font color="#0000c0">useradd --system -g zabbix -d /usr/lib/zabbix -s /sbin/nologin -c &quot;Zabbix Monitoring System&quot; zabbix </font>
    </p>
    <p>
      Debian
    </p>
    <p>
      <font color="#0000c0">addgroup --system --quiet zabbix </font>
    </p>
    <p>
      <font color="#0000c0">adduser --quiet --system --disabled-login --ingroup zabbix --home /var/lib/zabbix --no-create-home zabbix </font>
    </p>
    <p>
      <b>2.2 Zabbix &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072;&#1084; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1086;&#1084;&#1072;&#1096;&#1085;&#1072;&#1103; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1103;.</b>&#160; &#1054;&#1076;&#1085;&#1072;&#1082;&#1086;, &#1077;&#1089;&#1083;&#1080; &#1074;&#1099; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1077; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084;&#1091; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077; &#1076;&#1086;&#1084;&#1072;&#1096;&#1085;&#1077;&#1081; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1077; &#1091;&#1095;&#1077;&#1090;&#1085;&#1099;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; mysql &#1074; $HOME/.my.cnf)
    </p>
    <p>
      RHEL
    </p>
    <p>
      <font color="#0000c0">mkdir -m u=rwx,g=rwx,o= -p /usr/lib/zabbix </font>
    </p>
    <p>
      <font color="#0000c0">chown zabbix:zabbix /usr/lib/zabbix</font>
    </p>
    <p>
      Debian
    </p>
    <p>
      <font color="#0000c0">mkdir -m u=rwx,g=rwx,o= -p /var/lib/zabbix </font>
    </p>
    <p>
      <font color="#0000c0">chown zabbix:zabbix /var/lib/zabbix</font>
    </p>
    <p>
      <b>3. &#1057;&#1086;&#1079;&#1076;&#1072;&#1081;&#1090;&#1077; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; Zabbix</b>
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1041;&#1044; Zabbix proxy &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1089;&#1093;&#1077;&#1084;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1074; &#1090;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1082;&#1072;&#1082; &#1076;&#1083;&#1103; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1087;&#1086;&#1084;&#1080;&#1084;&#1086; &#1089;&#1093;&#1077;&#1084;&#1099; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1090;&#1072;&#1082;&#1078;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1085;&#1072;&#1073;&#1086;&#1088; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.
    </p>
    <p>
      3.1 &#1057;&#1090;&#1072;&#1074;&#1080;&#1084; <a href="#ID_1113700437">&#1057;&#1059;&#1041;&#1044; MySQL </a>
    </p>
    <p>
      3.2 MySQL (5.7, 8 - &#1088;&#1091;&#1075;&#1072;&#1083;&#1072;&#1089;&#1100; &#1085;&#1072; grant)
    </p>
    <p>
      <font color="#0000c0">mysql -uroot -p&lt;&#1087;&#1072;&#1088;&#1086;&#1083;&#1100;&gt; </font>
    </p>
    <p>
      <font color="#0000c0">mysql&gt; create database zabbix character set utf8 collate utf8_bin; </font>
    </p>
    <p>
      <font color="#0000c0">mysql&gt; grant all privileges on zabbix.* to zabbix@localhost identified by '&lt;&#1087;&#1072;&#1088;&#1086;&#1083;&#1100;&gt;'; </font>
    </p>
    <p>
      <font color="#0000c0">mysql&gt; quit; </font>
    </p>
    <p>
      <font color="#0000c0">cd /usr/src/zabbix-&lt;&#1074;&#1077;&#1088;&#1089;&#1080;&#1103;&gt;/database/mysql </font>
    </p>
    <p>
      <font color="#0000c0">mysql -uzabbix -p&lt;&#1087;&#1072;&#1088;&#1086;&#1083;&#1100;&gt; zabbix &lt; schema.sql </font>
    </p>
    <p>
      # &#1054;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1077;&#1089;&#1100; &#1079;&#1076;&#1077;&#1089;&#1100;, &#1077;&#1089;&#1083;&#1080; &#1074;&#1099; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1077; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1076;&#1083;&#1103; Zabbix &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;
    </p>
    <p>
      <font color="#0000c0">mysql -uzabbix -p&lt;&#1087;&#1072;&#1088;&#1086;&#1083;&#1100;&gt; zabbix &lt; images.sql </font>
    </p>
    <p>
      <font color="#0000c0">mysql -uzabbix -p&lt;&#1087;&#1072;&#1088;&#1086;&#1083;&#1100;&gt; zabbix &lt; data.sql </font>
    </p>
    <p>
      <font color="#0000c0">yum -y install gcc</font>&#160;<font color="#0000c0">mysql-devel libxml2-devel.x86_64 net-snmp-devel net-snmp libevent-devel libcurl-devel</font>
    </p>
    <p>
      <b>4. &#1057;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1081; &#1082;&#1086;&#1076;. </b>&#1055;&#1088;&#1080; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1076;&#1072; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1080;&#1083;&#1080; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;, &#1074;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1081; &#1090;&#1080;&#1087; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;. &#1058;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1080;&#1085; &#1090;&#1080;&#1087; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1089;&#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1074; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1080;&#1083;&#1080; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080; &#1077;&#1076;&#1080;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;.
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072; &#1074;&#1089;&#1077;&#1093; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;&#1093; &#1086;&#1087;&#1094;&#1080;&#1081; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;, &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077; &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; &#1089; &#1080;&#1079;&#1074;&#1083;&#1077;&#1095;&#1077;&#1085;&#1085;&#1099;&#1084; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1084; &#1082;&#1086;&#1076;&#1086;&#1084; Zabbix:
    </p>
    <p>
      <font color="#0000c0">./configure --help </font>
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1082;&#1086;&#1076;&#1086;&#1074; &#1076;&#1083;&#1103; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1080; &#1072;&#1075;&#1077;&#1085;&#1090;&#1072;, &#1074;&#1099; &#1084;&#1086;&#1078;&#1077;&#1090;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1085;&#1077;&#1095;&#1090;&#1086; &#1074;&#1088;&#1086;&#1076;&#1077;:
    </p>
    <p>
      <font color="#0000c0">./configure --enable-server --enable-agent --with-mysql --enable-ipv6 --with-net-snmp --with-libcurl --with-libxml2 --with-libpcre</font>
    </p>
    <p>
      <b>5. &#1057;&#1086;&#1073;&#1077;&#1088;&#1080;&#1090;&#1077; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1077; &#1074;&#1089;&#1105;.</b>&#160; &#1055;&#1088;&#1072;&#1074;&#1072; 'root' &#1080;&#1083;&#1080; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; sudo. &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1088;&#1072;&#1089;&#1082;&#1080;&#1076;&#1072;&#1077;&#1090; &#1092;&#1072;&#1081;&#1083;&#1099; &#1087;&#1086; &#1087;&#1072;&#1087;&#1082;&#1072;&#1084;
    </p>
    <ul>
      <li>
        &#1048;&#1089;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1076;&#1077;&#1084;&#1086;&#1085;&#1086;&#1074; (zabbix_server, zabbix_agentd, zabbix_proxy) &#1074; <b>/usr/local/sbin</b>
      </li>
      <li>
        &#1048;&#1089;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; (zabbix_get, zabbix_sender) &#1074; <b>/usr/local/bin</b>.
      </li>
    </ul>
    <p>
      <font color="#0000c0">make install</font>
    </p>
    <p>
      <b>6. &#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1090;&#1077; &#1080; &#1086;&#1090;&#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;</b>&#160; (<font color="#ff0000">&#1074;&#1086;&#1090; &#1090;&#1072;&#1082;&#1072;&#1103; &#1087;&#1088;&#1086;&#1089;&#1090;&#1072;&#1103; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1072;&#1094;&#1080;&#1103; &#1086;&#1090; &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1095;&#1080;&#1082;&#1086;&#1074;</font>)
    </p>
    <p>
      6.1 &#1054;&#1090;&#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1092;&#1072;&#1081;&#1083; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; <b>Zabbix &#1072;&#1075;&#1077;&#1085;&#1090;&#1072;</b>&#160;/usr/local/etc/zabbix_agentd.conf. &#1057;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1101;&#1090;&#1086;&#1090; &#1092;&#1072;&#1081;&#1083; &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1093;&#1086;&#1089;&#1090;&#1072; &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085; zabbix_agentd. &#1042; &#1092;&#1072;&#1081;&#1083;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; IP &#1072;&#1076;&#1088;&#1077;&#1089; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1089; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1093;&#1086;&#1089;&#1090;&#1086;&#1074; &#1073;&#1091;&#1076;&#1091;&#1090; &#1086;&#1090;&#1082;&#1083;&#1086;&#1085;&#1077;&#1085;&#1099;.
    </p>
    <p>
      6.2 &#1054;&#1090;&#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1092;&#1072;&#1081;&#1083; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; <b>Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;</b>&#160;/usr/local/etc/zabbix_server.conf. &#1059;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1080;&#1084;&#1103; &#1041;&#1044;, &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; (&#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;).
    </p>
    <p>
      6.3 &#1054;&#1090;&#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1092;&#1072;&#1081;&#1083; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; <b>Zabbix &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;</b>&#160;/usr/local/etc/zabbix_proxy.conf. &#1059;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; IP &#1072;&#1076;&#1088;&#1077;&#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1080; &#1080;&#1084;&#1103; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080; (&#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;), &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1080;&#1084;&#1103; &#1041;&#1044;, &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; (&#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;).
    </p>
    <p>
      &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1074; SQLite &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085; &#1087;&#1091;&#1090;&#1100; &#1082; &#1092;&#1072;&#1081;&#1083;&#1091; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1041;&#1044; &#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1102;&#1090;&#1089;&#1103;.
    </p>
    <p>
      <b>7 &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077; &#1076;&#1077;&#1084;&#1086;&#1085;&#1099;</b>
    </p>
    <p>
      <font color="#0000c0">zabbix_server</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077; zabbix_server &#1085;&#1072; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. &#1059;&#1076;&#1086;&#1089;&#1090;&#1086;&#1074;&#1077;&#1088;&#1100;&#1090;&#1077;&#1089;&#1100;, &#1095;&#1090;&#1086; &#1074; &#1074;&#1072;&#1096;&#1077;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1086; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; 36&#1052;&#1041; (&#1080;&#1083;&#1080; &#1085;&#1077;&#1084;&#1085;&#1086;&#1075;&#1080;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;) &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084;&#1086;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;, &#1074; &#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#8220;Cannot allocate shared memory for &lt;type of cache&gt;.&#8221; &#1074; &#1092;&#1072;&#1081;&#1083;&#1077; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
    </p>
    <p>
      <font color="#0000c0">zabbix_agentd</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077; zabbix_agentd &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; &#1085;&#1072;&#1073;&#1083;&#1102;&#1076;&#1072;&#1077;&#1084;&#1099;&#1093; &#1084;&#1072;&#1096;&#1080;&#1085;&#1072;&#1093;. &#1059;&#1073;&#1077;&#1076;&#1080;&#1090;&#1077;&#1089;&#1100;, &#1095;&#1090;&#1086; &#1074;&#1072;&#1096;&#1072; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1074;&#1099;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; 2 &#1052;&#1041; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084;&#1086;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; (shared memory), &#1080;&#1085;&#1072;&#1095;&#1077; &#1072;&#1075;&#1077;&#1085;&#1090; &#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1077; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100;&#1089;&#1103; --&gt; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#8220;Cannot allocate shared memory for collector.&#8221; &#1074; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1077; &#1072;&#1075;&#1077;&#1085;&#1090;&#1072;
    </p>
    <p>
      <font color="#0000c0">zabbix_proxy</font>&#160;&#160;# &#1045;&#1089;&#1083;&#1080; &#1074;&#1099; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1083;&#1080; Zabbix &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;, &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1077; zabbix_proxy
    </p>
  </body>
</html></richcontent>
