<node TEXT="2. Установка web-интерфейса" ID="ID_776615413" CREATED="1542364743944" MODIFIED="1553614078731"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1074;&#1077;&#1073;-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; Zabbix </b>
    </p>
    <p>
      <b>0. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; PHP (&#1089; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1084;&#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1084;&#1080;) &#1080; Apache.</b>
    </p>
    <p>
      <font color="#0000c0">yum -y install httpd php&#160;php-gd php-bcmath php-ctype php-xml php-xmlreader php-xmlwriter php-session php-net-socket php-mbstring php-gettext php-ldap php-mysqli</font>
    </p>
    <ul>
      <li>
        php-net-socket &#1044;&#1083;&#1103; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074;.
      </li>
      <li>
        php-gettext &#1044;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1086;&#1074;.
      </li>
      <li>
        php-ldap &#1058;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086;, &#1077;&#1089;&#1083;&#1080; &#1074; &#1074;&#1077;&#1073;-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; LDAP &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;
      </li>
      <li>
        php-mysqli&#160;&#160;&#1058;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; MySQL &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1073;&#1072;&#1079;&#1099; &#1076;&#1083;&#1103; Zabbix.
      </li>
    </ul>
    <p>
      <b>1. &#1050;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; PHP &#1074; &#1087;&#1072;&#1087;&#1082;&#1091; HTML &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.</b>
    </p>
    <p>
      &#1054;&#1073;&#1097;&#1077;&#1087;&#1088;&#1080;&#1085;&#1103;&#1090;&#1099;&#1077; &#1084;&#1077;&#1089;&#1090;&#1072; &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1103; &#1087;&#1072;&#1087;&#1082;&#1080; HTML &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1076;&#1083;&#1103; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; Apache &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1090;:
    </p>
    <ul>
      <li>
        /var/www/html (Debian, Ubuntu, Fedora, RHEL, CentOS)
      </li>
      <li>
        /usr/local/apache2/htdocs (&#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1088;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1077; Apache &#1080;&#1079; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1082;&#1086;&#1076;&#1086;&#1074;)
      </li>
      <li>
        /srv/www/htdocs (OpenSUSE, SLES)
      </li>
    </ul>
    <p>
      <font color="#0000c0">mkdir html/zabbix </font>
    </p>
    <p>
      <font color="#0000c0">cd zabbix </font>
    </p>
    <p>
      <font color="#0000c0">cp -a /usr/src/zabbix-4.0.1/frontends/php/* . </font>
    </p>
    <p>
      <font color="#0000c0">html/zabbix/locale/make_mo.sh</font>&#160;&#160;# &#1045;&#1089;&#1083;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1077; &#1080;&#1079; SVN &#1080; &#1087;&#1083;&#1072;&#1085;&#1080;&#1088;&#1091;&#1077;&#1090;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1083;&#1102;&#1073;&#1086;&#1081; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1103;&#1079;&#1099;&#1082; &#1082;&#1088;&#1086;&#1084;&#1077; &#1072;&#1085;&#1075;&#1083;. (&#1089;&#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083;&#1099; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1086;&#1074;). &#1058;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; <b>msgfmt</b>&#160;&#1080;&#1079; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072; gettext.
    </p>
    <p>
      <b>2. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1074;&#1077;&#1073;-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;</b>
    </p>
    <p>
      2.1 &#1054;&#1090;&#1082;&#1088;&#1086;&#1081;&#1090;&#1077; URL Zabbix: http://&lt;ip_&#1080;&#1083;&#1080;_&#1080;&#1084;&#1103;_&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&gt;/zabbix, &#1074; &#1074;&#1072;&#1096;&#1077;&#1084; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077;.
    </p>
    <p>
      2.2 &#1059;&#1073;&#1077;&#1076;&#1080;&#1090;&#1077;&#1089;&#1100;, &#1095;&#1090;&#1086; &#1074;&#1089;&#1077; &#1090;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1082; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1085;&#1086;&#1084;&#1091; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1077;&#1085;&#1080;&#1102; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1099;.
    </p>
    <p>
      <font color="#008000"><b>; /etc/php.ini</b></font>&#160;&#160;&#1042;&#1085;&#1077;&#1089;&#1090;&#1080; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1084;&#1099;&#1077; &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1074; &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;.
    </p>
    <p>
      <font color="#008000">date.timezone = Europe/Moscow </font>
    </p>
    <p>
      <font color="#008000">post_max_size = 16M </font>
    </p>
    <p>
      <font color="#008000">max_execution_time = 300 </font>
    </p>
    <p>
      <font color="#008000">max_input_time = 300 </font>
    </p>
    <p>
      <font color="#0000c0">systemctl reload httpd</font>&#160;&#160;# &#1055;&#1077;&#1088;&#1077;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; Apache
    </p>
    <ul>
      <li>
        &#1059;&#1082;&#1072;&#1078;&#1080;&#1090;&#1077; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; &#1073;&#1072;&#1079;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;. &#1041;&#1072;&#1079;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; Zabbix &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1091;&#1078;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1072;.
      </li>
      <li>
        &#1042;&#1074;&#1086;&#1076; &#1080;&#1084;&#1077;&#1085;&#1080; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1086;&#1087;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1077;&#1085;, &#1086;&#1076;&#1085;&#1072;&#1082;&#1086;, &#1077;&#1089;&#1083;&#1080; &#1079;&#1072;&#1076;&#1072;&#1085;, &#1086;&#1085;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1087;&#1086;&#1083;&#1086;&#1089;&#1077; &#1084;&#1077;&#1085;&#1102; &#1080; &#1074; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072;&#1093; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;.
      </li>
      <li>
        &#1057;&#1082;&#1072;&#1095;&#1072;&#1081;&#1090;&#1077; &#1092;&#1072;&#1081;&#1083; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1080; &#1087;&#1086;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1077; &#1077;&#1075;&#1086; &#1074; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; conf/.
      </li>
      <li>
        &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1080;&#1084;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; <b>Admin</b>, &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; <b>zabbix</b>
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="3. Установка Java gateway" ID="ID_921398267" CREATED="1542364790815" MODIFIED="1553614078700"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_735406297">Java gateway</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; Java gateway</b>
    </p>
    <p>
      
    </p>
    <p>
      &#1053;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; Java gateway &#1090;&#1086;&#1083;&#1100;&#1082;&#1086;, &#1077;&#1089;&#1083;&#1080; &#1074;&#1099; &#1093;&#1086;&#1090;&#1080;&#1090;&#1077; &#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;&#1080;&#1090;&#1100; JMX &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103;. Java gateway &#1083;&#1077;&#1075;&#1082;&#1086;&#1074;&#1077;&#1089;&#1085;&#1099;&#1081; &#1080; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1103; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.
    </p>
    <p>
      
    </p>
    <p>
      &#1063;&#1090;&#1086;&#1073;&#1099; &#1089;&#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; Java gateway, &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077; ./configure &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; &#1089; --enable-java &#1086;&#1087;&#1094;&#1080;&#1077;&#1081;. &#1062;&#1077;&#1083;&#1077;&#1089;&#1086;&#1086;&#1073;&#1088;&#1072;&#1079;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1086;&#1087;&#1094;&#1080;&#1102; --prefix &#1076;&#1083;&#1103; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1091;&#1090;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1089; /usr/local &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1087;&#1088;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1077; Java gateway &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1086; &#1094;&#1077;&#1083;&#1086;&#1077; &#1076;&#1077;&#1088;&#1077;&#1074;&#1086; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1081;, &#1085;&#1077; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1086;&#1076;&#1080;&#1085; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1099;&#1081; &#1092;&#1072;&#1081;&#1083;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">yum -y install java-1.8.0-openjdk-devel.x86_64 java-1.8.0-openjdk-devel-debug.x86_64 </font>
    </p>
    <p>
      <font color="#0000c0">cd /usr/src/zabbix-&lt;&#1074;&#1077;&#1088;&#1089;&#1080;&#1103;&gt; </font>
    </p>
    <p>
      <font color="#0000c0">./configure --enable-java --prefix=$PREFIX </font>
    </p>
    <p>
      <font color="#0000c0">make </font>
    </p>
    <p>
      <font color="#0000c0">make install</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="4. Настройка Zabbix Frontend" ID="ID_189338160" CREATED="1542800425608" MODIFIED="1553603778160"><richcontent TYPE="NOTE">
<html>
