  </head>
  <body>
    <p>
      <b>1. &#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1091;&#1095;&#1077;&#1090;&#1085;&#1086;&#1081; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1080; &#1089;&#1084;&#1077;&#1085;&#1072; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;</b>
    </p>
    <p>
      &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1085;&#1086;&#1074;&#1091;&#1102; &#1091;&#1095;&#1077;&#1090;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1089; &#1087;&#1088;&#1072;&#1074;&#1072;&#1084;&#1080; &#1089;&#1091;&#1087;&#1077;&#1088;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1072; &#1072;&#1076;&#1084;&#1080;&#1085;&#1072; &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100;
    </p>
    <p>
      Administration\Users&gt;Create user.
    </p>
    <ul>
      <li>
        &#1071;&#1079;&#1099;&#1082; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
      </li>
