<node TEXT="Get" ID="ID_1381521551" CREATED="1542193039405" MODIFIED="1545033061226"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Zabbix get</b>&#160;- &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; Zabbix &#1072;&#1075;&#1077;&#1085;&#1090;&#1091; &#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; &#1086;&#1090; &#1085;&#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1077;&#1084;&#1091;&#1102; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102;.
    </p>
    <ul>
      <li>
        &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1083;&#1103; &#1076;&#1080;&#1072;&#1075;&#1085;&#1086;&#1089;&#1090;&#1080;&#1082;&#1080; Zabbix &#1072;&#1075;&#1077;&#1085;&#1090;&#1086;&#1074;
      </li>
    </ul>
    <p>
      <b>&#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077; Zabbix get. </b>
    </p>
    <p>
      <font color="#0000c0">cd bin </font>
    </p>
    <p>
      <font color="#0000c0">./zabbix_get -s 127.0.0.1 -p 10050 -k &quot;system.cpu.load[all,avg1]&quot;&#160; </font># &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;. &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; CPU &#1086;&#1090; &#1072;&#1075;&#1077;&#1085;&#1090;&#1072;
    </p>
    <p>
      <font color="#0000c0">./zabbix_get -s 192.168.1.1 -p 10050 -k &quot;web.page.regexp[www.zabbix.com,,,USA: ([a-zA-Z0-9.-]+),,\1]&quot;</font>&#160; &#160;# &#1055;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; &#1089; &#1074;&#1077;&#1073; &#1089;&#1072;&#1081;&#1090;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;:
    </p>
    <p>
      <b>-s --host &lt;&#1080;&#1084;&#1103; &#1093;&#1086;&#1089;&#1090;&#1072; &#1080;&#1083;&#1080; IP&gt;</b>&#160;- &#1059;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1080;&#1084;&#1103; &#1093;&#1086;&#1089;&#1090;&#1072; &#1080;&#1083;&#1080; IP &#1072;&#1076;&#1088;&#1077;&#1089; &#1093;&#1086;&#1089;&#1090;&#1072;
    </p>
    <p>
      <b>-p --port &lt;&#1085;&#1086;&#1084;&#1077;&#1088; &#1087;&#1086;&#1088;&#1090;&#1072;&gt;</b>&#160;-&#160;&#1059;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1085;&#1086;&#1084;&#1077;&#1088; &#1087;&#1086;&#1088;&#1090;&#1072; &#1072;&#1075;&#1077;&#1085;&#1090;&#1072;, &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1085;&#1072; &#1091;&#1079;&#1083;&#1077; &#1089;&#1077;&#1090;&#1080;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 10050
    </p>
    <p>
      <b>-I --source-address &lt;IP &#1072;&#1076;&#1088;&#1077;&#1089;&gt;</b>&#160;- &#1059;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; IP &#1072;&#1076;&#1088;&#1077;&#1089; &#1076;&#1083;&#1103; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1075;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      <b>-k --key</b>&#160;&lt;&#1082;&#1083;&#1102;&#1095; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;&gt; - &#1059;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1082;&#1083;&#1102;&#1095; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1085;&#1072;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086;
    </p>
    <p>
      <b>-h --help</b>&#160;-&#160;&#1042;&#1099;&#1074;&#1086;&#1076; &#1101;&#1090;&#1086;&#1075;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080;
    </p>
    <p>
      <b>-V --version</b>&#160;- &#1042;&#1099;&#1074;&#1086;&#1076; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      <b>Zabbix get &#1074; Windows</b>
    </p>
    <p>
      <font color="#0000c0">zabbix_get.exe [&#1086;&#1087;&#1094;&#1080;&#1080;]</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Sender" ID="ID_1652285135" CREATED="1542193046429" MODIFIED="1542193903744"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Zabbix sender</b>&#160;- &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1072; &#1076;&#1083;&#1103; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1086; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1076;&#1083;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1081; &#1080;&#1093; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080;.
    </p>
    <ul>
      <li>
        &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1076;&#1086;&#1083;&#1075;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1099;&#1093; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072;&#1093; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076;&#1080;&#1095;&#1085;&#1086;&#1081; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1086; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080;
      </li>
      <li>
        &#1063;&#1090;&#1086;&#1073;&#1099; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1099; &#1085;&#1072;&#1087;&#1088;&#1103;&#1084;&#1091;&#1102; &#1085;&#1072; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080;&#1083;&#1080; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1090;&#1080;&#1087; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; <b>&#1090;&#1088;&#1072;&#1087;&#1087;&#1077;&#1088;</b>
      </li>
      <li>
        &#1047;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1079;&#1072; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1080;&#1081; &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1082; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;, &#1073;&#1091;&#1076;&#1091;&#1090; &#1085;&#1072;&#1082;&#1072;&#1087;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1084; &#1089;&#1090;&#1077;&#1082;&#1077; &#1080; &#1079;&#1072;&#1090;&#1077;&#1084; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1079;&#1072; &#1086;&#1076;&#1085;&#1086; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;. &#1044;&#1072;&#1085;&#1085;&#1099;&#1077;, &#1087;&#1088;&#1080;&#1096;&#1077;&#1076;&#1096;&#1080;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; &#1084;&#1077;&#1085;&#1077;&#1077;, &#1095;&#1077;&#1084; 0,2 &#1089;&#1077;&#1082; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1077;&#1075;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072;&#1082;&#1072;&#1087;&#1083;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1084; &#1089;&#1090;&#1077;&#1082;&#1077;, &#1085;&#1086; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080;&#1093; &#1085;&#1072;&#1082;&#1086;&#1087;&#1083;&#1077;&#1085;&#1080;&#1103; &#1076;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1074;&#1089;&#1077; &#1078;&#1077; 1 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1072;
      </li>
    </ul>
    <p>
      <b>&#1054;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1072; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; Zabbix sender:</b>
    </p>
    <p>
      <font color="#0000c0">cd bin </font>
    </p>
    <p>
      <font color="#0000c0">./zabbix_sender -z zabbix -s &quot;Linux DB3&quot; -k db.connections -o 43</font>
    </p>
    <p>
      &#1075;&#1076;&#1077;:
    </p>
    <p>
      &#160;&#160;&#160;&#160;z - &#1093;&#1086;&#1089;&#1090; Zabbix &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; (&#1090;&#1072;&#1082;&#1078;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; IP &#1072;&#1076;&#1088;&#1077;&#1089;)
    </p>
    <p>
