<node TEXT="Состав" ID="ID_1978378708" CREATED="1553359196925" MODIFIED="1553359319702"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>halt</b>&#160;&#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; shutdown &#1089; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1084; -h, &#1077;&#1089;&#1083;&#1080; &#1090;&#1077;&#1082;&#1091;&#1097;&#1081; &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1085;&#1077; 0, &#1079;&#1072;&#1090;&#1077;&#1084; &#1086;&#1085; &#1086;&#1090;&#1076;&#1072;&#1077;&#1090; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1103;&#1076;&#1088;&#1091; &#1085;&#1072; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1053;&#1086; &#1089;&#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1074; &#1092;&#1072;&#1081;&#1083; /var/log/wtmp &#1095;&#1090;&#1086; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103;.
    </p>
    <p>
      <b>init</b>&#160;- &#1084;&#1072;&#1090;&#1077;&#1088;&#1080;&#1085;&#1089;&#1082;&#1080;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093;. &#1054;&#1085; &#1089;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1080;&#1079; /etc/inittab, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1075;&#1086;&#1074;&#1086;&#1088;&#1103;&#1090;, &#1082;&#1072;&#1082;&#1080;&#1077; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1099; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1080; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; gettys.
    </p>
    <p>
      <b>killall5</b>&#160;&#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1074;&#1089;&#1077;&#1084; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072;&#1084;, &#1079;&#1072; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1088;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1074; -- &#1090;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084; &#1086;&#1085; &#1085;&#1077; &#1091;&#1073;&#1100;&#1077;&#1090; &#1096;&#1077;&#1083;&#1083;, &#1074;&#1099;&#1079;&#1074;&#1072;&#1074;&#1096;&#1080;&#1081; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;.
    </p>
    <p>
      <b>last</b>&#160;&#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;, &#1082;&#1072;&#1082;&#1080;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1099; (&#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1099;) &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077;, &#1087;&#1088;&#1086;&#1089;&#1084;&#1072;&#1090;&#1088;&#1080;&#1074;&#1072;&#1103; &#1092;&#1072;&#1081;&#1083; /var/log/wtmp. &#1054;&#1085; &#1090;&#1072;&#1082;&#1078;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1080; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077;&#1081; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;.
    </p>
    <p>
      <b>lastb</b>&#160;&#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; &#1074;&#1093;&#1086;&#1076;&#1072; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091;, &#1086;&#1090;&#1084;&#1077;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074; /var/log/btmp.
    </p>
    <p>
      <b>mesg</b>&#160;&#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1080;&#1088;&#1091;&#1077;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084;&#1080; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1085;&#1072; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;.
    </p>
    <p>
      <b>pidof</b>&#160;&#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; PID &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;.as noted in the last runlevel record i
    </p>
    <p>
      <b>poweroff</b>&#160;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090; &#1103;&#1076;&#1088;&#1091; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1085;&#1072; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1080; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1072;. &#1057;&#1084;&#1086;&#1090;&#1088;&#1080; halt.
    </p>
    <p>
      <b>reboot</b>&#160;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090; &#1103;&#1076;&#1088;&#1091; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1085;&#1072; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1057;&#1084;&#1086;&#1090;&#1088;&#1080; halt.
    </p>
    <p>
      <b>runlevel</b>&#160;&#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1080;&#1081; &#1080; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1091;&#1088;&#1086;&#1074;&#1085;&#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;, &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1081; &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085; &#1074; /var/run/utmp.
    </p>
    <p>
      <b>shutdown</b>&#160;&#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091;, &#1086;&#1090;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1074;&#1089;&#1077;&#1084; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072;&#1084; &#1080; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1103;&#1077;&#1090; &#1074;&#1089;&#1077;&#1093; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1099;&#1093; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;.
    </p>
    <p>
      <b>sulogin</b>&#160;&#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1082; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077; &#1089;&#1091;&#1087;&#1077;&#1088;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1077; init, &#1082;&#1086;&#1075;&#1076;&#1072; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077;.
    </p>
    <p>
      <b>telinit</b>&#160;&#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090; init &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1089;&#1084;&#1077;&#1085;&#1099; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;.
    </p>
    <p>
      <b>utmpdump</b>&#160;&#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; login-&#1092;&#1072;&#1081;&#1083;&#1072; &#1074; &#1091;&#1076;&#1086;&#1073;&#1086;&#1095;&#1080;&#1090;&#1072;&#1077;&#1084;&#1086;&#1084; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077;.
    </p>
    <p>
      <b>wall</b>&#160;&#1087;&#1080;&#1096;&#1077;&#1090; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1074;&#1089;&#1077;&#1084; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1099;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084;.
    </p>
  </body>
</html></richcontent>
