<node TEXT="Безопасность" FOLDED="true" ID="ID_513318168" CREATED="1744886403451" MODIFIED="1744886408847">
<node TEXT="Генератор паролей" ID="ID_629792281" CREATED="1744886421604" MODIFIED="1744887038892"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;"># Генератор паролей с кодом Python </span>
    </p>
    <p>
      <span style="font-weight: bold;"># 12 символов по умолчанию. Если нужно другое, добавляем аргумент</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">mpass() { </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;if [ $1 ]; then </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;length=$1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;else </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;length=12 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;fi </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;_hash=`python3 -c &quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import os,base64 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">exec('print(base64.b64encode(os.urandom(64))[:${length}].decode(\'utf-8\'))') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&quot;` </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;echo $_hash | xclip -selection clipboard </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;echo &quot;new password copied to the system clipboard&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">}</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Бесконечный цикл" POSITION="bottom_or_right" ID="ID_578599234" CREATED="1519112080046" MODIFIED="1776324525142"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <b><span style="font-family: Lucida Console;">true</span></b><span style="font-weight: normal; font-family: Lucida Console;">&#xa0;или </span><b><span style="font-family: Lucida Console;">:</span>&#xa0;&#xa0;-</b>&#xa0;ничего не делает, возвращает истину, полезна для организации вечных циклов
      </li>
    </ul>
    <p>
      <b># Спит бесконечность по 1сек.</b>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">echo $0&#xa0;&#xa0;# </span><span style="font-family: Lucida Console;">выводит название себя </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">while :; do </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;sleep 1&#xa0; </span><span style="font-family: Lucida Console;"># спать 1 сек. </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">done </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console;"># аналогично </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">while true; do </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;sleep 1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">done </span>
    </p>
    <p>
      
    </p>
    <p>
      <b># Цикл вывода даты на экран</b>
    </p>
    <p>
      <span style="font-weight: normal; color: #0000c0; font-family: Lucida Console;">while :; do date; done</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">while :; do </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;date</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">done </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Нагрузка</span>
    </p>
    <p>
      <span style="color: #0000c0;">while true; do true; done &amp;</span>&#xa0;&#xa0;#&#xa0;&#xa0;Нагружаетодно логическое ядро на 100%
    </p>
    <p>
      <span style="color: #0000c0;">while true; do echo $[1+1] &gt; /dev/null; done &amp; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">kill %1</span>&#xa0;&#xa0;# Для остановки после тестов
    </p>
    <p>
      <span style="color: #0000c0;">kill $!</span>&#xa0;или <span style="color: #0000c0;">kill -9 $!</span>&#xa0;&#xa0;# <span style="font-weight: bold;">$!</span>&#xa0;хранит PID последнего запущенного фонового процесса
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">pkill -f &quot;while true&quot;</span>&#xa0;&#xa0;# Или, если задание не в текущей сессии:
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Чтобы нагрузить все ядра</span>
    </p>
    <p>
      <span style="color: #0000c0;">stress --cpu $(nproc) --timeout 60s</span>
    </p>
    <p>
      или
    </p>
    <p>
      запустите цикл в фоне несколько раз вручную.
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Генерация нагрузки (стресс-тест)</span>
    </p>
    <p>
      <span style="color: #0000c0;">yes &gt; /dev/null</span>&#xa0;&#xa0;# Загружает одно ядро CPU на 100%
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Взаимодействие с пользователем" FOLDED="true" ID="ID_960084916" CREATED="1731244661532" MODIFIED="1744110281691"><richcontent TYPE="NOTE">
<html>
