<node TEXT="Нормализует поле месяца в строке" ID="ID_603470464" CREATED="1742138993437" MODIFIED="1742139075623"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;"># Нормализует поле месяца в строке с датой в трехсимвольное</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">monthNumToName() { </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;# Присвоить переменной 'month’ соответствующее значение. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;case $1 in </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;1 ) month=&quot;Jan&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;2 ) month=&quot;Feb&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;3 ) month=&quot;Mar&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;4 ) month=&quot;Apr&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;5 ) month=&quot;May&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;6 ) month=&quot;Jun&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;7 ) month=&quot;Jul&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;8 ) month=&quot;Aug&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;9 ) month=&quot;Sep&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;10) month=&quot;Oct&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;11) month=&quot;Nov&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;12) month=&quot;Dec&quot; ;; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;* ) echo &quot;$0: Unknown month value $1&quot; &gt;&amp;2 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;exit 1&#xa0;&#xa0;# если месяц не распознан, скрипт завершается с ошибкой </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;esac </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;return 0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">}</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
