<node TEXT="журналирование из скрипта" ID="ID_51860604" CREATED="1780646447019" MODIFIED="1780646506045"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>запись в журнал из скрипта</b>
    </p>
    <p>
      <span style="color: #008000;">#! /bin/sh </span>
    </p>
    <p>
      <span style="color: #008000;">logger -p auth.info -t $0 &quot;$@&quot;</span>&#xa0;# пишем в лог из скрипта, (-p) - подсистема и уровень значимости; (-t) имя ПО, которая пишет в логи и текст сообщения
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="лог удалений" ID="ID_1624109911" CREATED="1743589782380" MODIFIED="1743589866563"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;"># журналирует все операции удаления файлов с флагом -s </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">removelog=&quot;/var/log/remove.log&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;"># проверить, чтобы аргументы были указаны, если нет, вывод сообщения </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">if [ $# -eq 0 ]; then </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;echo &quot;Usage: $0 [-s] list of files or directories&quot; &gt;&amp;2 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;exit 1 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">fi </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;"># есть -s есть - свдигаем маску аргументов, чтобы -s не попала в лог и в ключи команды rm </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">if [ &quot;$1&quot; = &quot;-s&quot; ]; then </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;shift </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;echo &quot;$(date): ${USER}: $@&quot; &gt;&gt; $removelog </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">fi </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">/bin/rm &quot;$@&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">exit&#xa0;&#xa0;0</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Пользователи" FOLDED="true" ID="ID_1805606002" CREATED="1744104872021" MODIFIED="1775928000398">
<node TEXT="Проверка root / нет" ID="ID_1098962790" CREATED="1744104891989" MODIFIED="1775576698627"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1511212789">Сравнение - (( )), [[ ]]</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console; font-weight: bold;"># Проверить ID запускающего</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">if [ &quot;$UID&quot; -eq 0 ]; then </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;echo &quot;You are running this script as root.&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">else </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;echo &quot;You are running this script as a regular user.&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">fi </span>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">$UID</span>&#xa0;- Переменная, содержащая ваш текущий ID
      </li>
      <li>
        <span style="font-weight: bold;">-eq</span>&#xa0;- EQuals (равно)
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Проверка и создание" ID="ID_1448993420" CREATED="1775928013989" MODIFIED="1775931375986"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">#!/bin/bash </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Проверить, что передан ровно один аргумент </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">if [ $# -ne 1 ]; then </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;echo &quot;Usage: ./onboard.sh &lt;username&gt;&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;exit 1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">fi </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Сохранить имя пользователя в переменную </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">USER_NAME=&quot;$1&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Проверить существование пользователя (вывод скрыт) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">if id &quot;$USER_NAME&quot; &amp;&gt;/dev/null; then </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;echo &quot;User $USER_NAME already exists&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;exit 1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">fi </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">echo &quot;Creating user $USER_NAME...&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Создать пользователя с домашней папкой (-m) и оболочкой bash (-s) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">sudo useradd -m -s /bin/bash &quot;$USER_NAME&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">echo &quot;Setting up work directory...&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Создать рабочую директорию </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">sudo mkdir /home/&quot;$USER_NAME&quot;/work </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Назначить владельцем пользователя и его группу </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">sudo chown &quot;$USER_NAME&quot;:&quot;$USER_NAME&quot; /home/&quot;$USER_NAME&quot;/work </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">echo &quot;User setup complete.&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Добавить запись в журнал с меткой времени </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">echo &quot;[$(date)] User $USER_NAME created.&quot; &gt;&gt; ~/project/onboard.log </span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
