<node TEXT="Резервное копирование" FOLDED="true" ID="ID_322069585" CREATED="1547894372984" MODIFIED="1717000743459">
<node TEXT="Бекап логов" POSITION="bottom_or_right" ID="ID_1125547829" CREATED="1776589815025" MODIFIED="1776598160392"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">#!/bin/bash </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">REPORT_FILE=&quot;report.txt&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">LOG_FILES=( </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&quot;/home/labex/project/logs/app1.log&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&quot;/home/labex/project/logs/db.log&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&quot;/home/labex/project/logs/auth.log&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cleanup() { </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;echo &quot;Cleaning up...&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;# В реальном скрипте вы могли бы вывести содержимое отчета перед его удалением </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;if [ -f &quot;$REPORT_FILE&quot; ]; then </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;cat &quot;$REPORT_FILE&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;rm -f &quot;$REPORT_FILE&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;fi </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">} </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">trap cleanup EXIT </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Инициализация отчета </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">touch &quot;$REPORT_FILE&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">archive_log() { </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;local file_path=&quot;$1&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;local new_name=&quot;${file_path/.log/.backup}&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;if [ -f &quot;$file_path&quot; ]; then </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;cp &quot;$file_path&quot; &quot;$new_name&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;echo &quot;Backed up: $file_path -&gt; $new_name&quot; &gt;&gt; &quot;$REPORT_FILE&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;else </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;echo &quot;File not found: $file_path&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;fi </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">} </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># --- Основной цикл --- </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">echo &quot;Starting Log Backup...&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">for log in &quot;${LOG_FILES[@]}&quot;; do </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;archive_log &quot;$log&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">done </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">echo &quot;Backup process finished.&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># -----------------</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Резервное копирование файлов" ID="ID_442707302" CREATED="1530793833696" MODIFIED="1614398000062"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1056;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1077; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;. </b>&#1050;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1080; &#1087;&#1077;&#1088;&#1077;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1089; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1084; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077;&#1084;
    </p>
    <p>
      <font color="#008000">#!/bin/bash </font>
    </p>
    <p>
      <font color="#008000">suffix=BACKUP--$(date +%Y%m%d-%H%M) </font>
    </p>
    <p>
      <font color="#008000">for script in *.log; do </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;newname=&quot;$script.$suffix&quot; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Copying $script to $newname...&quot; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;cp $script $newname </font>
    </p>
    <p>
      <font color="#008000">done </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1047;&#1072;&#1073;&#1101;&#1082;&#1072;&#1087;&#1080;&#1090;&#1100; passwd</b>
    </p>
    <p>
      <font color="#008000">#!/bin/bash </font>
    </p>
    <p>
      <font color="#008000">cp -au /etc/passwd /tmp/passwd.backup </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">#!/bin/bash </font>
    </p>
    <p>
      <font color="#008000">cksum_passwd=$(cksum /etc/passwd | awk '{print $1}') </font>
    </p>
    <p>
      <font color="#008000">if [ ! -f /tmp/passwd.backup ] || [ $cksum_passwd != $(cksum /tmp/passwd.backup | awk '{print $1}') ]; then </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;cp -a /etc/passwd /tmp/passwd.backup </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo 'OK. Backup created (updated).' </font>
    </p>
    <p>
      <font color="#008000">fi</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Скрипт с аргументами" ID="ID_1614276992" CREATED="1547894180847" MODIFIED="1776598162248"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ol>
      <li>
        Выражение в первом условном операторе проверяет, получила ли программа аргумент ($1).
      </li>
      <li>
        Если - нет, оно завершает работу программы, предоставляя пользователю небольшое сообщение об ошибке
      </li>
      <li>
        Резервное копирование
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">#!/bin/bash </span>
    </p>
    <p>
      <span style="color: #008000;">if [ -z &quot;$1&quot; ]; then </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;echo используйте: $0 каталог </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;exit </span>
    </p>
    <p>
      <span style="color: #008000;">fi</span>
    </p>
    <p>
      <span style="color: #008000;">SRCD=$1&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;</span>#SRCD - SouRCe Directory - исходный каталог
    </p>
    <p>
      <span style="color: #008000;">TGTD=&quot;/var/backups/&quot;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;</span>#TGTD - TarGeT Directory - конечный каталог
    </p>
    <p>
      <span style="color: #008000;">OF=home-$(date +%Y%m%d).tgz&#xa0;&#xa0;</span>#OF - Output File - выходной файл
    </p>
    <p>
      <span style="color: #008000;">tar -cZf $TGTD$OF $SRCD</span>
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Сайты" ID="ID_811949696" CREATED="1759666221469" MODIFIED="1776326846994"><richcontent TYPE="NOTE">
