  </head>
  <body>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Проверяем, отвечает ли сервис на localhost:8000 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">#!/bin/bash </span>
