    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">if curl -s --head http://localhost:8000 | grep &quot;200 OK&quot; &gt; /dev/null; then </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;echo &quot;Service Status: UP&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">else </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;echo &quot;Service Status: DOWN&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">fi </span>
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
