<node TEXT="Аппаратная часть" FOLDED="true" ID="ID_1593529052" CREATED="1587547997615" MODIFIED="1787664749517"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_452391215">Аппаратная часть</a>&#xa0;&#xa0;<a href="#ID_1734575070">lshw</a>&#xa0; <a href="#ID_865302932">dmidecode</a>&#xa0; <a href="#ID_1535282607">NFS-server</a>&#xa0;&#xa0;<a href="#ID_1320145061">udev</a>&#xa0;&#xa0;<a href="#ID_1279369409">/dev</a>&#xa0;&#xa0;<a href="#ID_1643006858">MAJOR и MINOR</a>
    </p>
    <ul>
      <li>
        /dev
      </li>
      <li>
        /etc/udev
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">cat /proc/devices</span>&#xa0;&#xa0;# Сконфигурированные и загруженные, <b>character</b>&#xa0;и <b>block</b>&#xa0;устройства
    </p>
    <p>
      <span style="color: #0000c0;">cat /sys/devices/virtual/dmi/id/board_{vendor,name,version}</span>&#xa0;&#xa0;# Модель <b>материнской</b>&#xa0;карты
    </p>
    <p>
      <span style="color: #0000c0;">lshw -short</span>&#xa0;&#xa0;# Компактная информация
    </p>
    <p>
      <span style="color: #0000c0;">lshw&#xa0;&#xa0;-businfo</span>&#xa0;&#xa0;# Outputs the device list showing bus information, detailing SCSI, USB, IDE and PCI addresses
    </p>
    <p>
      
    </p>
    <p>
      <b>CPU</b>
    </p>
    <p>
      <span style="color: #0000c0;">lscpu </span>
    </p>
    <p>
      <span style="color: #0000c0;">cat </span><span style="color: #0000c0; font-weight: bold;">/proc/cpuinfo</span>
    </p>
    <p>
      <span style="color: #0000c0;">watch -n.1 &quot;grep \&quot;^[c]pu MHz\&quot; /proc/cpuinfo&quot;</span>&#xa0;&#xa0;# Отслеживать частоту всех ядер
    </p>
    <p>
      <span style="color: #0000c0;">cpuinfo </span>
    </p>
    <p>
      <span style="color: #0000c0;">uname -a </span>
    </p>
    <p>
      <span style="color: #0000c0;">nproc</span>&#xa0;&#xa0;# Число ядер
    </p>
    <p>
      /sys/devices/system/cpu
    </p>
    <p>
      
    </p>
    <p>
      <b>RAM</b>
    </p>
    <p>
      <span style="color: #0000c0;">dmidecode --type memory</span>&#xa0;&#xa0;# RAM&#xa0;с подробностями по слотам и плашкам
    </p>
    <p>
      <span style="color: #0000c0;">cat </span><span style="font-weight: bold; color: #0000c0;">/proc/meminfo</span>
    </p>
    <p>
      <a href="#ID_963917846">SWAP (подкачка)</a>&#xa0;- виртуальная память
    </p>
    <p>
      <span style="color: #0000c0;">lsmem</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Шины</b>&#xa0;
    </p>
    <p>
      <span style="color: #0000c0;">ls /proc/bus</span>&#xa0;&#xa0;# Список шин, распознанных ядром Linux
    </p>
    <p>
      <span style="color: #0000c0;">lsusb</span>&#xa0;&#xa0;# Исследовать шину usb
    </p>
    <p>
      <span style="color: #0000c0;">lspci </span>&#xa0;# Вывести информацию о PCI-шинах
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Сеть</span>
    </p>
    <p>
      <span style="color: #0000c0;">lspci | grep -i ethernet</span>
    </p>
    <p>
      <span style="color: #0000c0;">udevadm info -q property -p /sys/class/net/enp0s3 </span>
    </p>
    <p>
      <span style="color: #0000c0;">lshw -c network -businfo</span>&#xa0;&#xa0;#&#xa0;&#xa0;Инфо о сетевых интерфейсах системы и шинах (например, PCI)
    </p>
    <p>
      
    </p>
    <p>
      <b>Запросы прерываний</b>
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/interrupts</span>&#xa0;&#xa0;# Список идентификаторов запросов прерываний
    </p>
    <p>
      <span style="color: #0000c0;">dmesg</span>&#xa0;&#xa0;# прерывания, резервируемы для устройств в процессе загрузки сестемы
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/ioports</span>&#xa0;&#xa0;#<b>&#xa0;Порты ввода-вывода</b>&#xa0;устройств системы
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/dma</span>&#xa0;&#xa0;# Используемые в данный момент каналы прямого доступа к памяти (<b>DMA</b>) для устройств ISA
    </p>
    <p>
      
    </p>
    <p>
      <b>Диски</b>
    </p>
    <p>
      <span style="color: #0000c0;">udevadm info --query=all --name=/dev/sda | grep ID_SERIAL</span>&#xa0;&#xa0;# Вывести серийные номера
    </p>
    <p>
      
    </p>
    <p>
      <b>Дисплей</b>
    </p>
    <p>
      <span style="color: #0000c0;">Xorg -configure</span>&#xa0;&#xa0;# Информация об окружении дисплея
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="Диски" FOLDED="true" ID="ID_381461091" CREATED="1519112079880" MODIFIED="1781853878682"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1279369409">/dev</a>&#xa0;&#xa0;partprobe&#xa0;&#xa0;<a href="#ID_365050488">dd</a>&#xa0; <a href="#ID_27345436">ddrescue</a>&#xa0;&#xa0;<a href="#ID_1574804007">LVM</a>&#xa0;&#xa0;<a href="#ID_244779432">lsof</a>&#xa0; <a href="#ID_1144517713">RAID</a>&#xa0;&#xa0;<a href="#ID_1535282607">NFS-server</a>&#xa0; <a href="#ID_575878190">Квоты</a>&#xa0;&#xa0;<a href="#ID_1266420936">debugfs</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>Инфо</b>
    </p>
    <p>
      <span style="color: #0000c0;">udevadm info --query=all --name=/dev/sda | grep ID_SERIAL</span>&#xa0;&#xa0;# Вывести <span style="font-weight: bold;">серийные номера</span>
    </p>
    <p>
      <span style="color: #0000c0;">grep . /sys/block/*/device/model </span>
    </p>
    <p>
      <span style="color: #0000c0;">lsblk</span>&#xa0;-f&#xa0;# Блочные устройства с указанием файловых систем, меток, UUID и точек монтирования
    </p>
    <ul>
      <li>
        <b>-a</b>&#xa0;- все блочные устройства в нашей системе
      </li>
      <li>
        FSTYPE - тип файловой системы (например, ext4, xfs, vfat, swap)
      </li>
      <li>
        LABEL - метка тома (если задана)
      </li>
      <li>
        UUID - уникальный идентификатор файловой системы
      </li>
      <li>
        MOUNTPOINT - точка монтирования (если раздел смонтирован)
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">lsblk -o +MODEL,SERIAL</span>&#xa0;# + модель и <span style="font-weight: bold;">серийный номер</span>
    </p>
    <p>
      <span style="color: #0000c0;">parted -l&#xa0;</span>&#xa0;#&#xa0;&#xa0;Информация о разделах
    </p>
    <p>
      <span style="color: #0000c0;">fdisk -l /dev/sda*</span>&#xa0;&#xa0;# Информация о дисках. Если устройство не указано, будут показаны все <span style="font-weight: normal;">разделы</span>&#xa0;&#xa0;из /proc/partitions
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/partitions</span>&#xa0;&#xa0;# Разделы диска (по мнению ядра)
    </p>
    <p>
      <span style="color: #0000c0;">blkid&#xa0; </span># Список блочных устройств, их UUID, тип файловой системы и метаданные
    </p>
    <p>
      <span style="color: #0000c0;">blkid -o list</span>&#xa0;&#xa0;# В виде списка
    </p>
    <p>
      <span style="color: #0000c0;">ls -l /dev/disk/by-uuid/</span>&#xa0;&#xa0;# Узнать длинные имена устройств
    </p>
    <p>
      <span style="color: #0000c0;">geom disk list</span>&#xa0;&#xa0;# <span style="color: #ff0000;">FreeBSD</span>. Список дисков
    </p>
    <p>
      <span style="color: #0000c0;">ls -l /dev/sd*</span>&#xa0;&#xa0;# Устройства, подключенные к SATA-контроллеру. sd<b>a</b>-1й HDD, sd<b>b</b>-2й HDD ..., sda<b>5</b>&#xa0;- 1й лог. раздел на HDD
    </p>
    <p>
      <span style="color: #0000c0;">ls /dev/hd*</span>&#xa0;и <span style="color: #0000c0;">ls /dev/sd*</span>&#xa0;и <span style="color: #0000c0;">ls /dev/sd*</span>&#xa0;и <span style="color: #0000c0;">ls /dev/vd* </span>&#xa0;# Вывод списка имен дисков
    </p>
    <p>
      <span style="color: #0000c0;">smartctl -a /dev/sd<b>a</b></span>&#xa0;&#xa0;# Вся SMART инф. о дисках. dev/sd<b>b</b>&#xa0;- 2-й диск
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/scsi/scsi&#xa0; </span># Обнаружение дисковых устройств SCSI (или SATA)
    </p>
    <p>
      <span style="color: #0000c0;">file -sL /dev/sdb1</span>&#xa0;или <span style="color: #0000c0;">blkid&#xa0;[/dev/sda1]</span>&#xa0;или <span style="color: #0000c0;">lsblk -f </span>&#xa0;# Узнать<b>&#xa0;файловую систему </b>раздела, <b>UUID</b>, серийный номер
    </p>
    <p>
      <span style="color: #0000c0;">tune2fs -l /dev/sda2</span>&#xa0;&#xa0;# Информация суперблока файловой системы, в т.ч. <b>UUID</b>
    </p>
    <p>
      <span style="color: #0000c0;">mount | column -t</span>&#xa0;&#xa0;# Список устройств и их точек монтирования
    </p>
    <p>
      <span style="color: #0000c0;">findmnt </span>&#xa0;# Аналог mount со связями
    </p>
    <p>
      <span style="color: #0000c0;">df -hT</span>&#xa0;&#xa0;# disk free, список всех FS, <b>-h</b>&#xa0;(human-readable), <b>-T</b>&#xa0;(тип FS), дисковое пространство может расти до 110%
    </p>
    <p>
      <span style="color: #0000c0;">df -hTt ext4</span>&#xa0;&#xa0;# список дисков ext4
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/mounts</span>&#xa0;&#xa0;# инфо о смонтированных устройствах
    </p>
    <p>
      <span style="color: #0000c0;">dd if=/dev/sda of=/dev/null bs=16M count=64</span>&#xa0;&#xa0;# Определяем скорость чтения диска
    </p>
    <p>
      <span style="color: #0000c0;">du -sh * | sort -hr</span>&#xa0;&#xa0;# Размер каталогов (в MB и GB) по убыванию
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node FOLDED="true" ID="ID_1762530044" CREATED="1590644177303" MODIFIED="1780401263854"><richcontent TYPE="NODE">

<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#000000">LVM</font>
    </p>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1574804007">LVM</a>&#xa0;&#xa0;<a href="#ID_1531600597">mdadm</a>&#xa0;&#xa0;<a href="#ID_1144517713">RAID</a>&#xa0;
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        \dev\&lt;VG&gt;\&lt;LV&gt;
      </li>
      <li>
        KDE Partition Manager (<span style="font-weight: bold;">partitionmanager</span>) - графический инструмент с полной поддержкой LVM
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Проверка и установка</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvs</span>&#xa0;&#xa0;# Вывести список физических томов (PV)
    </p>
    <p>
      <span style="color: #0000c0;">apt install lvm2</span>&#xa0;&#xa0;# Установить утилиты LVM
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Безопасное удаление LVM</span>&#xa0;(перед удалением пакета)
    </p>
    <p>
      <span style="color: #0000c0;">umount /mnt/data&#xa0; </span># Отмонтировать логический том (LV)
    </p>
    <p>
      <span style="color: #0000c0;">lvremove /dev/vg_name/lv_name</span>&#xa0;&#xa0;# Удалить логический том (LV)
    </p>
    <p>
      <span style="color: #0000c0;">vgremove vg_name</span>&#xa0;&#xa0;# Удалить группу томов (VG)
    </p>
    <p>
      <span style="color: #0000c0;">pvremove /dev/sdX</span>&#xa0;&#xa0;# Удалить физический том (PV)
    </p>
    <p>
      <span style="color: #0000c0;">apt purge lvm2 &amp;&amp; apt autoremove</span>&#xa0;&#xa0;# Полностью удалить пакет lvm2 и его зависимости
    </p>
    <p>
      reboot
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Траблшутинг и восстановление</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvscan -d</span>&#xa0;&#xa0;# Сканировать диски на наличие PV с выводом отладочной информации
    </p>
    <p>
      <span style="color: #0000c0;">vgscan</span>&#xa0;&#xa0;# Поиск и создание кэша групп томов (VG)
    </p>
    <p>
      <span style="color: #0000c0;">lvscan</span>&#xa0;&#xa0;# Поиск логических томов (LV) в системе
    </p>
    <p>
      <span style="color: #0000c0;">lvchange -ay /dev/vg_name/lv_name</span>&#xa0;&#xa0;# Активировать отключенный логический том (LV)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Восстановление метаданных (бэкапы лежат в /etc/lvm/backup/)</span>
    </p>
    <p>
      <span style="color: #0000c0;">vgcfgrestore --file &lt;file&gt; &lt;vg_name&gt;</span>&#xa0;&#xa0;# Восстановить структуру VG из файла
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate --uuid &lt;UUID&gt; --restorefile &lt;file&gt;</span>&#xa0;&#xa0;# Восстановить PV по UUID из файла бэкапа
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Аварийные команды</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvremove --force &lt;lv_path&gt;</span>&#xa0;&#xa0;# Принудительно удалить поврежденный LV
    </p>
    <p>
      <span style="color: #0000c0;">pvmove --abort</span>&#xa0;&#xa0;# Прервать зависшую или сбойную миграцию данных между PV
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="1. PV" FOLDED="true" ID="ID_1327775325" CREATED="1727794897456" MODIFIED="1780483175659"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Проверка физических томов&#xa0;(PV)</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvs</span>&#xa0;&#xa0;# Краткий список PV, их размеров и свободных PE
    </p>
    <p>
      <span style="color: #0000c0;">pvscan</span>&#xa0;&#xa0;# Поиск PV на дисках и обновление кэша LVM
    </p>
    <p>
      <span style="color: #0000c0;">pvdisplay /dev/sda2</span>&#xa0;&#xa0;# Подробная информация о конкретном PV. <a href="#ID_171915992">Вывод</a>
    </p>
    <p>
      <span style="color: #0000c0;">lvmdiskscan</span>&#xa0;&#xa0;# Список всех блочных устройств, пригодных для LVM
    </p>
    <p>
      <span style="color: #0000c0;">file -s /dev/vdb1</span>&#xa0;&#xa0;# Проверка сигнатуры файловой системы / метаданных LVM
    </p>
    <p>
      <span style="color: #0000c0;">dd if=/dev/vdb1 of=/tmp/vdb1 bs=1M count=1</span>&#xa0;&#xa0;# Дамп первого мегабайта устройства для анализа
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Управление физическими томами (PV)</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/sdb /dev/sdc1</span>&#xa0;&#xa0;# Инициализация устройств (дисков или разделов) как PV
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/sd[e-g]</span>&#xa0;&#xa0;# Массовое создание PV (для /dev/sde, /dev/sdf, /dev/sdg)
    </p>
    <p>
      <span style="color: #0000c0;">pvremove /dev/sde</span>&#xa0;&#xa0;# Удаление метаданных LVM с устройства (деинициализация)
    </p>
    <p>
      <span style="color: #0000c0;">pvresize /dev/sde1</span>&#xa0;&#xa0;# Расширение/уменьшение PV вслед за изменением размера раздела
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Управление аллокацией (выделением места)</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvchange -xn /dev/sdd</span>&#xa0;&#xa0;# Запретить выделение новых экстентов на этом PV
    </p>
    <p>
      <span style="color: #0000c0;">pvchange -xy /dev/sdd</span>&#xa0;&#xa0;# Разрешить выделение экстентов (возврат по умолчанию)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Миграция данных</span>&#xa0;(выполнять перед pvremove)
    </p>
    <p>
      <span style="color: #0000c0;">pvmove /dev/sdf</span>&#xa0;&#xa0;# Переместить данные с sdf на другие свободные PV в той же VG
    </p>
    <p>
      <span style="color: #0000c0;">pvmove /dev/sdf /dev/sdg</span>&#xa0;&#xa0;# Переместить данные строго с sdf на целевой диск sdg
    </p>
    <p>
      <span style="color: #0000c0;">pvmove --abort</span>&#xa0;&#xa0;# Прервать аварийную или зависшую миграцию данных
    </p>
  </body>
</html></richcontent>
<node TEXT="pvdisplay (параметры)" ID="ID_171915992" CREATED="1780483020606" MODIFIED="1780483136050"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Параметры в выводе команды pvdisplay
    </p>
    <ul>
      <li>
        PV Name - путь к устройству (имя физического диска/раздела)
      </li>
      <li>
        VG Name - имя группы томов, в которую включен этот диск
      </li>
      <li>
        PV Size - общий физический размер диска
      </li>
      <li>
        Allocatable - доступность для записи. Если yes, на нем можно создавать логические тома
      </li>
      <li>
        PE Size - размер одного физического экстента (блока). Равен 0, пока диск вне VG
      </li>
      <li>
        Total PE - общее количество экстентов на диске
      </li>
      <li>
        Free PE - количество неиспользуемых экстентов
      </li>
      <li>
        Allocated PE - количество экстентов, уже занятых логическими томами
      </li>
      <li>
        PV UUID - уникальный идентификатор физического тома
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="2. VG" FOLDED="true" ID="ID_454430628" CREATED="1727794908837" MODIFIED="1780482817359"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Проверка групп томов (VG)</span>
    </p>
    <p>
      <span style="color: #0000c0;">vgs</span>&#xa0;&#xa0;# Краткий список всех VG (размер, свободное место, статус)
    </p>
    <p>
      <span style="color: #0000c0;">vgscan</span>&#xa0;&#xa0;# Поиск VG на дисках и принудительное обновление кэша LVM
    </p>
    <p>
      <span style="color: #0000c0;">vgdisplay &lt;vg_name&gt;</span>&#xa0;&#xa0;# Подробная информация о VG (размер экстентов, лимиты)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Управление группами томов</span>
    </p>
    <p>
      <span style="color: #0000c0;">vgcreate vg42 /dev/sd[e-f]</span>&#xa0;&#xa0;# Создать VG 'vg42' из указанных физических томов (PV)
    </p>
    <p>
      <span style="color: #0000c0;">vgextend vg1&#xa0;/dev/sdg</span>&#xa0;&#xa0;# Расширить VG 'vg1', добавив новый PV '/dev/sdg'
    </p>
    <p>
      <span style="color: #0000c0;">vgreduce vg1&#xa0;/dev/sdg</span>&#xa0;&#xa0;# Удалить пустой PV '/dev/sdg' из VG 'vg1'
    </p>
    <p>
      <span style="color: #0000c0;">vgremove vg42</span>&#xa0;&#xa0;# Полностью удалить VG (все входящие PV станут свободными)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Объединение и разделение VG</span>
    </p>
    <p>
      <span style="color: #0000c0;">vgmerge vg1 vg2</span>&#xa0;&#xa0;# Объединить vg2 в vg1 (vg2 должна быть неактивна)
    </p>
    <p>
      <span style="color: #0000c0;">vgsplit vg1 vg2 /dev/sdg</span>&#xa0;&#xa0;# Переместить PV '/dev/sdg' из vg1 во вновь создаваемую vg2
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Изменение параметров и статуса VG</span>
    </p>
    <p>
      <span style="color: #0000c0;">vgchange -ay vg1</span>&#xa0;&#xa0;# Активировать VG (сделать логические тома доступными, флаг &quot;a&quot;)
    </p>
    <p>
      <span style="color: #0000c0;">vgchange -an vg1</span>&#xa0;&#xa0;# Деактивировать VG (отключить видимость логических томов)
    </p>
    <p>
      <span style="color: #0000c0;">vgchange -xn vg1</span>&#xa0;&#xa0;# Запретить изменение размера VG (заблокировать экспорт/расширение)
    </p>
    <p>
      <span style="color: #0000c0;">vgchange -xy vg1</span>&#xa0;&#xa0;# Разрешить изменение размера VG (возврат по умолчанию)
    </p>
    <p>
      <span style="color: #0000c0;">vgchange -l 16 -p 8 vg1</span>&#xa0;&#xa0;# Ограничить vg1: макс. 16 логических томов и макс. 8 PV
    </p>
  </body>
</html></richcontent>
<node TEXT="vgdisplay (параметры)" ID="ID_1265217809" CREATED="1780483229676" MODIFIED="1780483363053"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Параметры в выводе команды vgdisplay
    </p>
    <ul>
      <li>
        VG Name - уникальное имя группы томов
      </li>
      <li>
        Format - формат метаданных LVM (обычно lvm2)
      </li>
      <li>
        Metadata Areas - количество областей хранения метаданных (равно числу дисков в VG)
      </li>
      <li>
        VG Access - режим доступа к группе (обычно read/write)
      </li>
      <li>
        VG Status - текущий статус группы (например, resizable)
      </li>
      <li>
        MAX LV / Cur LV - максимально возможное и текущее количество логических томов
      </li>
      <li>
        Max PV / Cur PV - максимально возможное и текущее количество физических дисков
      </li>
      <li>
        VG Size - общий суммарный объем группы томов
      </li>
      <li>
        PE Size - размер одного физического экстента (базового блока данных)
      </li>
      <li>
        Total PE - общее количество экстентов в группе
      </li>
      <li>
        Alloc PE / Size - занятое пространство: количество экстентов и их общий объем
      </li>
      <li>
        Free PE / Size - свободное пространство: количество экстентов и доступный объем
      </li>
      <li>
        VG UUID - уникальный идентификатор группы томов
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="3. LV" ID="ID_862498580" CREATED="1727794915284" MODIFIED="1780483542432"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <span style="font-weight: bold;">-n</span>&#xa0;- имя логического тома
      </li>
      <li>
        <span style="font-weight: bold;">-L</span>&#xa0;- фиксированный размер тома в абсолютных единицах

        <ul>
          <li>
            10G - гигабайты
          </li>
          <li>
            500M - мегабайты)
          </li>
        </ul>
      </li>
      <li>
        <span style="font-weight: bold;">-l</span>&#xa0;- размер в количестве экстентов (например, 6) или в процентах от объема

        <ul>
          <li>
            100%FREE - для заполнения всего свободного места
          </li>
        </ul>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Проверка логических томов (LV)</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvs -a</span>&#xa0;&#xa0;# Краткий статус всех LV
    </p>
    <p>
      <span style="color: #0000c0;">lvscan</span>&#xa0;&#xa0;# Поиск LV в системе и проверка их активности
    </p>
    <p>
      <span style="color: #0000c0;">lvdisplay vg0/lv0</span>&#xa0;&#xa0;# Полная информация о конкретном LV
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Создание и изменение (LV)</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvchange -ay vg0/lv0</span>&#xa0;&#xa0;# Активировать указанный LV (вывести в online)
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 5G vg0</span>&#xa0;&#xa0;# Создать LV на 5 ГБ (имя по умолчанию: lvol0)
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 200M -n lv1 vg0</span>&#xa0;&#xa0;# Создать LV с именем lv1 на 200 МБ
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -l 10%VG -n lv2 vg0</span>&#xa0;&#xa0;# Создать LV размером 10% от общего объема VG
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -l 100%FREE -n lv3 vg0</span>&#xa0;&#xa0;# Создать LV на все оставшееся свободное место
    </p>
    <p>
      <span style="color: #0000c0;">lvrename vg0/old_name vg0/new_name</span>&#xa0;&#xa0;# Переименовать LV
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Увеличение размера (LV)</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -L +100M vg0/lv0</span>&#xa0;&#xa0;# Добавить 100 МБ к текущему размеру
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -L 500M vg0/lv0</span>&#xa0;&#xa0;# Расширить строго до 500 МБ
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -l +100%FREE vg0/lv0</span>&#xa0;&#xa0;# Отдать логическому тому все свободное место VG
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -r -L +1G vg0/lv0</span>&#xa0;&#xa0;# Увеличить LV на 1 ГБ и автоматически расширить файловую систему (-r)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Уменьшение размера (LV)</span>
    </p>
    <ul>
      <li>
        Перед уменьшением LV обязательно нужно сначала сжать файловую систему, иначе данные будут уничтожены
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">lvreduce -r -L -1G vg0/lv0</span>&#xa0;&#xa0;# Безопасно уменьшить LV на 1 ГБ и автоматически сжать файловую систему (-r работает для ext4 и XFS)
    </p>
    <p>
      <span style="color: #0000c0;">lvreduce -r -L 5G vg0/lv0</span>&#xa0;&#xa0;# Безопасно уменьшить строго до 5G с автоматическим сжатием ФС.
    </p>
    <p>
      <span style="color: #0000c0;">lvreduce -f -L 2G vg0/lv0</span>&#xa0;&#xa0;# Принудительно (-f) обрезать LV без трогания ФС (опасно, используйте только для пустых томов или сырых данных)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Снапшоты и восстановление</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -s -n snap1 -L 5G vg0/lv0</span>&#xa0;&#xa0;# Создать снапшот snap1 размером 5 ГБ для lv0
    </p>
    <p>
      <span style="color: #0000c0;">lvconvert --merge vg0/snap1</span>&#xa0;&#xa0;# Откатить состояние lv0 к снапшоту (удалит снапшот после слияния)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Удаление томов</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvremove vg0/lv1 vg0/lv2</span>&#xa0;&#xa0;# Удалить один или несколько исправных томов
    </p>
    <p>
      <span style="color: #0000c0;">lvremove -f vg0/lv0</span>&#xa0;&#xa0;# Принудительно удалить LV (включая занятые или поврежденные)
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Задачи" FOLDED="true" ID="ID_232629257" CREATED="1780477448207" MODIFIED="1781941129637">
<node TEXT="пример 1" POSITION="bottom_or_right" ID="ID_1075180910" CREATED="1728037186197" MODIFIED="1780475865343"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">1. Просмотр и подготовка дисков</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvs</span>&#xa0;&#xa0;# Посмотреть физические тома (PV)
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/sdc</span>&#xa0;&#xa0;# Инициализировать диск для LVM
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Управление группами томов</span>
    </p>
    <p>
      <span style="color: #0000c0;">vgs</span>&#xa0;&#xa0;# Посмотреть группы томов (VG)
    </p>
    <p>
      <span style="color: #0000c0;">vgcreate vg_data /dev/sdc</span>&#xa0;&#xa0;# Создать группу томов &quot;vg_data&quot;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. Управление логическими томами</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvs</span>&#xa0;&#xa0;# Посмотреть логические тома (LV)
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 500M -n lv_test vg_data</span>&#xa0;&#xa0;# Создать том 500МБ с именем &quot;lv_test&quot;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">4. Файловая система и монтирование</span>
    </p>
    <p>
      <span style="color: #0000c0;">mkfs.ext4 /dev/vg_data/lv_test</span>&#xa0;&#xa0;# Создать файловую систему ext4
    </p>
    <p>
      <span style="color: #0000c0;">mkdir -p /mnt/test</span>&#xa0;&#xa0;# Создать директорию (лучше в /mnt, ключ -p защитит от ошибок)
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/vg_data/lv_test /mnt/test/</span>&#xa0;&#xa0;# Смонтировать том
    </p>
    <p>
      <span style="color: #0000c0;">df -hT /mnt/test</span>&#xa0;&#xa0;# Проверить место и тип файловой системы целевой папки
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">5. Автомонтирование</span>
    </p>
    <p>
      <span style="color: #0000c0;">echo &quot;/dev/vg_data/lv_test /mnt/test ext4 defaults 0 0&quot; &gt;&gt; /etc/fstab</span>&#xa0;&#xa0;# Добавить в автозагрузку
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="пример 2" POSITION="bottom_or_right" ID="ID_1900983419" CREATED="1728037147460" MODIFIED="1780476208160"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">1. Подготовка диска</span>
    </p>
    <p>
      <span style="color: #0000c0;">lsblk</span>&#xa0;&#xa0;# Посмотреть список дисков и разделов
    </p>
    <p>
      <span style="color: #0000c0;">fdisk /dev/vdb</span>&#xa0;&#xa0;# Разметка: g (GPT) -&gt; n (новый) -&gt; w (записать)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Создание LVM </span><span style="font-weight: bold; font-family: Lucida Console;">(PV -&gt; VG -&gt; LV)</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/vdb1</span>&#xa0;&#xa0;# Инициализировать раздел для LVM
    </p>
    <p>
      <span style="color: #0000c0;">vgcreate vg_data /dev/vdb1</span>&#xa0;&#xa0;# Создать группу
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 5G -n lv_data vg_data</span>&#xa0;&#xa0;# Создать логический том 5ГБ с именем lv_data
    </p>
    <p>
      <span style="color: #0000c0;">lvs</span>&#xa0;&#xa0;# Проверить результат (краткий аналог lvdisplay)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. Файловая система и монтирование</span>
    </p>
    <p>
      <span style="color: #0000c0;">mkfs.ext4 /dev/vg_data/lv_data</span>&#xa0;&#xa0;# Создать файловую систему ext4
    </p>
    <p>
      <span style="color: #0000c0;">mkdir -p /mnt/data</span>&#xa0;&#xa0;# Создать директорию монтирования
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/vg_data/lv_data /mnt/data</span>&#xa0;&#xa0;# Смонтировать том
    </p>
    <p>
      <span style="color: #0000c0;">df -hT /mnt/data</span>&#xa0;&#xa0;# Проверить статус конкретной точки монтирования
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">4. Автозагрузка</span>
    </p>
    <p>
      <span style="color: #0000c0;">echo &quot;/dev/vg_data/lv_data /mnt/data ext4 defaults 0 0&quot; &gt;&gt; /etc/fstab</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Снимки LVM" POSITION="bottom_or_right" ID="ID_1687587585" CREATED="1728033944190" MODIFIED="1788245437798"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1831805729">CoW и RoW</a>&#xa0; <a href="#ID_370580937">Резервное копирование (linux)</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">LVM Snapshot (снимок)</span>&#xa0;- временная, мгновенная копия логического тома (LV), фиксирующая его состояние на момент создания. Используется для безопасного резервного копирования «на лету» и тестирования изменений без остановки сервисов
    </p>
    <ul>
      <li>
        Снапшоты - это временные сущности. Удаляйте их сразу после завершения бэкапа
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Архитектура и технологии: CoW vs RoW. </span>В LVM логика работы снимков зависит от типа исходного тома:
    </p>
    <p>
      <span style="font-weight: bold;">Толстые тома (Thick Volumes)</span>&#xa0;- Механизм CoW (Copy-on-Write)
    </p>
    <ul>
      <li>
        При создании снимок почти не занимает места. Когда данные меняются в оригинальном томе, старые блоки сначала копируются в пространство снапшота, и только потом перезаписываются
      </li>
      <li>
        Минусы: Падение производительности диска на запись (двойная операция ввода-вывода). Снапшот требует фиксированного размера (-L) и безвозвратно ломается при заполнении на 100%
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Тонкие тома (Thin Volumes)</span>&#xa0;- Механизм RoW (Redirect-on-Write)
    </p>
    <ul>
      <li>
        Новые изменения записываются в новые свободные блоки Thin-пула. Оригинальные блоки не перемещаются, а снимок просто ссылается на них
      </li>
      <li>
        Скорость записи не падает. Снапшоты не требуют указания размера при создании и делят общую память пула. Можно создавать цепочки снимков
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Команды</span>
    </p>
    <p>
      <span style="font-weight: bold;">Подготовка и создание</span>
    </p>
    <p>
      <span style="color: #0000c0;">vgs</span>&#xa0;&#xa0;# Проверить свободное место в VG (столбец VFree)
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 10G -s -n web-snap DEMO/web-lv</span>&#xa0;&#xa0;# Снапшот для Thick тома (размер 10G обязателен)
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -s -n thin-snap DEMO/thin-lv</span>&#xa0;&#xa0;# Снапшот для Thin тома (размер не указывается)
    </p>
    <p>
      <span style="font-weight: bold;">Мониторинг и контроль</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvs</span>&#xa0;&#xa0;# Проверка статуса (столбец Data% или Allocated to snapshot)
    </p>
    <ul>
      <li>
        Если CoW-снимок заполнится на 100%, он перейдет в статус INACTIVE и <span style="color: #ff0000;">данные будут потеряны</span>
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Использование (Выборочное восстановление)</span>
    </p>
    <p>
      Снапшот можно примонтировать как обычный диск для копирования отдельных файлов:
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/DEMO/web-snap /mnt/backup</span>&#xa0;&#xa0;# Для ext4
    </p>
    <p>
      <span style="color: #0000c0;">mount -o nouuid /dev/DEMO/web-snap /mnt/backup</span>&#xa0;&#xa0;# Для XFS (игнорирование дубликата UUID)
    </p>
    <p>
      # ...выполнение бэкапа/копирования...
    </p>
    <p>
      <span style="color: #0000c0;">umount /mnt/backup</span>
    </p>
    <p>
      <span style="font-weight: bold;">Полный откат</span>
    </p>
    <p>
      Возврат оригинального тома к состоянию на момент снимка:
    </p>
    <p>
      <span style="color: #0000c0;">umount /dev/DEMO/web-lv</span>&#xa0;&#xa0;# Отмонтировать оригинальный том
    </p>
    <p>
      <span style="color: #0000c0;">lvconvert --merge /dev/DEMO/web-snap</span>&#xa0;&#xa0;# Запуск
    </p>
    <ul>
      <li>
        Если оригинальный том занят (например, корень /), слияние отложится и автоматически выполнится при следующей загрузке системы. После завершения снимок удаляется сам.
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Удалить снапшот. Все изменения остаются на основном томе, а нагрузка на диск пропадает</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvremove -f DEMO/web-snap</span>&#xa0;&#xa0;# Удаление ненужного снимка
    </p>
    <p>
      
    </p>
    <p>
      ------------------------------
    </p>
    <p>
      <span style="font-weight: bold;">3. Защита от переполнения (Авторасширение) </span>
    </p>
    <ul>
      <li>
        Для работы авторасширения в Volume Group (vgs) обязательно должно оставаться свободное пространство.
      </li>
    </ul>
    <p>
      Чтобы CoW-снапшот не сломался во время долгого бэкапа, настройте автоматическое увеличение его размера в файле <span style="font-weight: bold;">/etc/lvm/lvm.conf</span>:
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">activation { </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;snapshot_autoextend_threshold = 80&#xa0;&#xa0;&#xa0;# Расширять, когда снапшот заполнен на 80% </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;snapshot_autoextend_percent = 20&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Увеличивать размер на 20% от текущего </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">}</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Замена диска" POSITION="bottom_or_right" ID="ID_672867448" CREATED="1778849528931" MODIFIED="1780474979594"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Замена диска sdc на sdd</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Подготовка нового диска и расширение группы</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/sdd</span>&#xa0;&#xa0;# Инициализируем новый диск для LVM
    </p>
    <p>
      <span style="color: #0000c0;">vgextend gr1 /dev/sdd</span>&#xa0;&#xa0;# Добавляем новый диск в группу gr1
    </p>
    <p>
      &#xa0;&#xa0;
    </p>
    <p>
      <span style="font-weight: bold;">2. Перенос данных и удаление старого диска</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvmove /dev/sdc /dev/sdd</span>&#xa0;&#xa0;# Переносим данные со sdc на sdd (работает на лету)
    </p>
    <p>
      <span style="color: #0000c0;">vgreduce gr1 /dev/sdc</span>&#xa0;&#xa0;# Удаляем старый диск sdc из группы gr1
    </p>
    <p>
      <span style="color: #0000c0;">pvremove /dev/sdc</span>&#xa0;&#xa0;# Полностью очищаем LVM-метку с диска sdc
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Зеркалирование (mirroring)" POSITION="bottom_or_right" ID="ID_465979231" CREATED="1728039018154" MODIFIED="1780473125390"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1144517713">RAID</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Зеркалирование RAID1 (Рекомендуемый способ)</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/sdb /dev/sdc</span>&#xa0;&#xa0;# 1. Создать физические тома (PV)
    </p>
    <p>
      <span style="color: #0000c0;">vgcreate vg33 /dev/sdb /dev/sdc</span>&#xa0;&#xa0;# 2. Создать группу томов (VG)
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 5G --type raid1 -n lvmir vg33</span>&#xa0;&#xa0;# 3. Создать зеркальный логический том (LV RAID1)
    </p>
    <p>
      <span style="color: #0000c0;">lvs -a -o +devices</span>&#xa0;&#xa0;# 4. Проверить статус синхронизации (столбец Cpy%Sync)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Классическое зеркало (Устаревший метод с логом)</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/sdb /dev/sdc /dev/sdd</span>&#xa0;&#xa0;# 1. Инициализировать 3 диска (2 под данные + 1 под журнал)
    </p>
    <p>
      <span style="color: #0000c0;">vgcreate vg33 /dev/sdb /dev/sdc /dev/sdd</span>&#xa0;&#xa0;# 2. Объединить их в группу
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 300M -m 1 -n lvmir vg33</span>&#xa0;&#xa0;# 3. Создать зеркало с одной копией (-m 1)
    </p>
    <p>
      <span style="color: #0000c0;">lvs -a -o +devices</span>&#xa0;&#xa0;# 4. Проверить распределение данных и журнала по дискам
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. Создание ФС и монтирование</span>
    </p>
    <p>
      <span style="color: #0000c0;">mkfs.ext4 /dev/vg33/lvmir</span>&#xa0;&#xa0;# 1. Создать файловую систему ext4
    </p>
    <p>
      <span style="color: #0000c0;">mkdir -p /mnt/data &amp;&amp; mount /dev/vg33/lvmir /mnt/data</span>&#xa0;&#xa0;&#xa0;# 2. Создать точку монтирования и примонтировать
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Полезные команды для проверки</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvs</span>&#xa0;&#xa0;# проверка свободного места на физических дисках.
    </p>
    <p>
      <span style="color: #0000c0;">vgs</span>&#xa0;&#xa0;# краткий статус группы томов.
    </p>
    <p>
      <span style="color: #0000c0;">lvs</span>&#xa0;&#xa0;# отслеживание процента синхронизации зеркала (Copy%).
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Изменение размера PV" POSITION="bottom_or_right" ID="ID_988279528" CREATED="1728038923498" MODIFIED="1780475030165"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Изменение размера физического тома</b>
    </p>
    <p>
      
    </p>
    <p>
      1. Проверить текущий размер раздела и PV
    </p>
    <p>
      <span style="color: #0000c0;">lsblk /dev/sde1 &amp;&amp; pvs /dev/sde1</span>
    </p>
    <p>
      
    </p>
    <p>
      2. Расширить раздел диска до максимального размера без удаления
    </p>
    <p>
      <span style="color: #0000c0;">parted /dev/sde resizepart 1 100%</span>
    </p>
    <ul>
      <li>
        Альтернатива: <span style="color: #0000c0;">growpart /dev/sde 1</span>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      3. Обновить таблицу разделов в ядре OS
    </p>
    <p>
      <span style="color: #0000c0;">partx -u /dev/sde1</span>
    </p>
    <p>
      
    </p>
    <p>
      4. Увеличить размер физического тома LVM
    </p>
    <p>
      <span style="color: #0000c0;">pvresize /dev/sde1</span>
    </p>
    <p>
      
    </p>
    <p>
      5. Проверить итоговый размер раздела и PV
    </p>
    <p>
      <span style="color: #0000c0;">lsblk /dev/sde1 &amp;&amp; pvs /dev/sde1</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Расширение LV" POSITION="bottom_or_right" ID="ID_1056416109" CREATED="1728039360465" MODIFIED="1780473655617"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Создание и расширение тома LVM</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Подготовка дисков и создание VG</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/sdb1 /dev/sdc</span>&#xa0;&#xa0;# Инициализировать раздел и диск
    </p>
    <p>
      <span style="color: #0000c0;">vgcreate vg2 /dev/sdb1 /dev/sdc</span>&#xa0;&#xa0;# Создать группу томов vg2
    </p>
    <p>
      <span style="color: #0000c0;">vgs vg2</span>&#xa0;&#xa0;# Проверить размер и состав VG
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Создание тома и файловой системы</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 200M -n lvol0 vg2</span>&#xa0;&#xa0;# Создать логический том на 200 Мегабайт
    </p>
    <p>
      <span style="color: #0000c0;">mkfs.ext4 /dev/vg2/lvol0</span>&#xa0;&#xa0;# Создать ФС ext4
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. Монтирование</span>
    </p>
    <p>
      <span style="color: #0000c0;">mkdir -p /home/resizetest</span>
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/vg2/lvol0 /home/resizetest</span>&#xa0;&#xa0;# Смонтировать
    </p>
    <p>
      <span style="color: #0000c0;">df -h /home/resizetest</span>&#xa0;&#xa0;# Проверить текущий размер ФС
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">4. РАСШИРЕНИЕ (Два способа на выбор)</span>
    </p>
    <p>
      <span style="font-weight: bold;">Способ А:</span>&#xa0;Одной командой (Рекомендуемый)
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -L +100M -r /dev/vg2/lvol0</span>&#xa0;&#xa0;# Флаг -r автоматически расширит и ФС ext4 онлайн
    </p>
    <p>
      <span style="font-weight: bold;">Способ Б:</span>&#xa0;Классический (В два шага, если забыли флаг -r)
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -L +100M /dev/vg2/lvol0</span>&#xa0;&#xa0;# Увеличить сам том (+100M обязательно с буквой M)
    </p>
    <p>
      <span style="color: #0000c0;">resize2fs /dev/vg2/lvol0</span>&#xa0;&#xa0;# Расширить ФС ext4 (работает «на лету» без отмонтирования)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">5. Проверка результата</span>
    </p>
    <p>
      <span style="color: #0000c0;">df -h /home/resizetest</span>&#xa0;&#xa0;# Теперь размер ФС обновился
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Полезные лайфхаки для lvextend</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -l +100%FREE -r /dev/vg2/lvol0</span>&#xa0;&#xa0;# Расширить том на всё оставшееся свободное место в группе
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -L 5G -r /dev/vg2/lvol0</span>&#xa0;&#xa0;# Увеличить размер до конкретного значения (например, сделать ровно 5 Гигабайт вместо добавления)
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Создать VG" POSITION="bottom_or_right" ID="ID_159130399" CREATED="1728039100345" MODIFIED="1780477473288"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Создать группу томов, содержащую все пространство дискового устройства и раздел с другого дискового устройства</b>
    </p>
    <p>
      
    </p>
    <p>
      1. Поиск целевых дисков (например, /dev/sdb и /dev/sdc)
    </p>
    <p>
      <span style="color: #0000c0;">lsblk</span>&#xa0;&#xa0;# Вывести структуру всех блочных устройств (нагляднее, чем fdisk -l)
    </p>
    <p>
      
    </p>
    <p>
      2. Создание раздела /dev/sdc1 на весь диск
    </p>
    <p>
      <span style="color: #0000c0;">printf &quot;n\np\n1\n\n\nw\n&quot; | fdisk /dev/sdc</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">printf</span>&#xa0;... - &quot;n\np\n1\n\n\nw\n&quot; - автоматизирует интерактивный диалог с утилитой fdisk, чтобы не вводить команды вручную
      </li>
      <li>
        <span style="font-weight: bold;">n</span>&#xa0;- создать новый раздел (new)
      </li>
      <li>
        <span style="font-weight: bold;">p</span>&#xa0;- выбрать тип раздела «основной» (primary)
      </li>
      <li>
        <span style="font-weight: bold;">1</span>&#xa0;- присвоить разделу номер 1
      </li>
      <li>
        <span style="font-weight: bold;">\n</span>&#xa0;(пустая строка) - согласиться с первым сектором по умолчанию
      </li>
      <li>
        <span style="font-weight: bold;">\n</span>&#xa0;(пустая строка) - согласиться с последним сектором по умолчанию (занять весь диск)
      </li>
      <li>
        <span style="font-weight: bold;">w</span>&#xa0;- записать изменения на диск и выйти (write)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      3. Инициализация PV и создание VG в одну строку
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/sdb /dev/sdc1 &amp;&amp; vgcreate VG42 /dev/sdb /dev/sdc1</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Создание, расширение LV" POSITION="bottom_or_right" ID="ID_1372033352" CREATED="1728037307509" MODIFIED="1782118329020"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">ЧАСТЬ 1: Создание, форматирование (ext4), монтирование и копирование</span>
    </p>
    <p>
      1. Создать малый (200M) и большой (600M) логические тома
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 200M -n LVsmall VG42 </span>
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 600M -n LVbig VG42</span>
    </p>
    <p>
      2. Проверить пути к устройствам (все ссылки ведут на один блочный девайс)
    </p>
    <p>
      <span style="color: #0000c0;">ls -l /dev/VG42/LVsmall /dev/mapper/VG42-LVsmall /dev/dm-2</span>
    </p>
    <p>
      3. Создать файловую систему ext4 на обоих томах
    </p>
    <p>
      <span style="color: #0000c0;">mkfs.ext4 /dev/VG42/LVsmall </span>
    </p>
    <p>
      <span style="color: #0000c0;">mkfs.ext4 /dev/VG42/LVbig</span>
    </p>
    <p>
      4. Создать точки монтирования и примонтировать тома
    </p>
    <p>
      <span style="color: #0000c0;">mkdir -p /srv/LVsmall /srv/LVbig </span>
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/VG42/LVsmall /srv/LVsmall </span>
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/VG42/LVbig /srv/LVbig</span>
    </p>
    <p>
      5. Скопировать тестовые данные
    </p>
    <p>
      <span style="color: #0000c0;">cp -r /etc /srv/LVsmall/ </span>
    </p>
    <p>
      <span style="color: #0000c0;">cp -r /var/log /srv/LVbig/</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">ЧАСТЬ 2: Расширение малого тома на 50% (ext4 онлайн)</span>
    </p>
    <p>
      <span style="font-weight: bold;">ВАРИАНТ А:</span>&#xa0;Увеличить НА 50% от СОБСТВЕННОГО размера тома (добавит +100МБ)
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -l +50%LV -r /dev/VG42/LVsmall</span>
    </p>
    <ul>
      <li>
        -r - автоматически применяет resize2fs для ext4 «на лету» без размонтирования
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">ВАРИАНТ Б:</span>&#xa0;Увеличить НА 50% от ВСЕГО СВОБОДНОГО места в группе VG42
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -l +50%FREE -r /dev/VG42/LVsmall</span>
    </p>
    <p>
      <span style="color: #0000c0;">df -h /srv/LVsmall</span>&#xa0;&#xa0;# Проверить новый размер файловой системы ext4
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Перенос данных между физ. дисками" POSITION="bottom_or_right" ID="ID_1420417821" CREATED="1728063074086" MODIFIED="1780476963435"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1152059558">GNU Screen</a><span style="font-weight: normal;">&#xa0;&#xa0;</span><a href="#ID_713952887">tmux</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Онлайн-перенос данных на другой диск (без простоя)</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Шаг 1. Подготовка исходного диска (для контекста)</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/vdb1</span>&#xa0;&#xa0;# Создать первый PV
    </p>
    <p>
      <span style="color: #0000c0;">vgcreate vg_data /dev/vdb1</span>&#xa0;&#xa0;# Создать группу томов vg_data
    </p>
    <p>
      <span style="color: #0000c0;">lvcreate -L 5G -n lv_data vg_data</span>&#xa0;&#xa0;# Создать логический том lv_data
    </p>
    <p>
      <span style="color: #0000c0;">mkfs.ext4 /dev/vg_data/lv_data</span>&#xa0;&#xa0;# Создать файловую систему
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/vg_data/lv_data /mnt/data</span>&#xa0;&#xa0;# Смонтировать
    </p>
    <p>
      <span style="color: #0000c0;">touch /mnt/data/testfile</span>&#xa0;&#xa0;# Создать тестовый файл
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Шаг 2. Подключение нового диска и перенос (Online)</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/vdb2</span>&#xa0;&#xa0;# 1. Инициализировать НОВЫЙ диск
    </p>
    <p>
      <span style="color: #0000c0;">vgextend vg_data /dev/vdb2</span>&#xa0;&#xa0;# 2. Добавить новый диск в текущую VG
    </p>
    <p>
      <span style="color: #0000c0;">lvs -a -o +devices</span>&#xa0;&#xa0;# 3. Проверить, где лежат данные (будет vdb1)
    </p>
    <p>
      <span style="color: #0000c0;">tmux</span>&#xa0;&#xa0;# 4. Запустить tmux (защита от обрыва связи)
    </p>
    <p>
      <span style="color: #0000c0;">pvmove /dev/vdb1 /dev/vdb2</span>&#xa0;&#xa0;# 5. Фоновый перенос данных со старого на новый
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Шаг 3. Отключение старого диска</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvs -a -o +devices</span>&#xa0;&#xa0;# 1. Убедиться, что данные теперь на vdb2
    </p>
    <p>
      <span style="color: #0000c0;">vgreduce vg_data /dev/vdb1</span>&#xa0;&#xa0;# 2. Исключить старый диск из группы томов
    </p>
    <p>
      <span style="color: #0000c0;">pvremove /dev/vdb1</span>&#xa0;&#xa0;# 3. Полностью удалить метку LVM со старого диска
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Перенос дисков между разными серверами" POSITION="bottom_or_right" ID="ID_140956139" CREATED="1728113750645" MODIFIED="1780476636920"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Перенос дисков LVM между серверами</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. На старом сервере (Отключение)</span>
    </p>
    <p>
      <span style="color: #0000c0;">umount /mnt/data</span>&#xa0;&#xa0;# 1. Размонтировать том
    </p>
    <p>
      <span style="color: #0000c0;">vgchange -an vg_data</span>&#xa0;&#xa0;# 2. Деактивировать группу томов
    </p>
    <ul>
      <li>
        -an (--activate n) - Деактивировать (no). Скрывает тома из ОС и блокирует любые изменения в них
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">vgexport vg_data</span>&#xa0;&#xa0;# 3. Экспортировать VG (готовит к переносу)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Физически переставьте диски в новый сервер</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. На новом сервере (Подключение)</span>
    </p>
    <p>
      <span style="color: #0000c0;">apt update &amp;&amp; apt install -y lvm2</span>&#xa0;&#xa0;# 1. Установить утилиты LVM
    </p>
    <p>
      <span style="color: #0000c0;">pvscan &amp;&amp; vgscan</span>&#xa0;&#xa0;# 2. Найти новые подключенные диски
    </p>
    <p>
      <span style="color: #0000c0;">vgimport vg_data</span>&#xa0;&#xa0;# 3. Импортировать группу томов
    </p>
    <p>
      <span style="color: #0000c0;">vgchange -ay vg_data</span>&#xa0;&#xa0;# 4. Активировать группу томов
    </p>
    <ul>
      <li>
        -ay (--activate y) - Активировать (yes). Делает группу томов и все её логические тома видимыми для ОС. Появляются файлы устройств в /dev/vg_name/, и диски становятся готовы к монтированию
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">mkdir -p /mnt/data</span>&#xa0;&#xa0;# 5. Создать папку для монтирования
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/vg_data/lv_data /mnt/data</span>&#xa0;&#xa0;# 6. Смонтировать том
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Перенос инф. с неисправного диска на новый" POSITION="bottom_or_right" ID="ID_1536100210" CREATED="1728119428479" MODIFIED="1780477373512"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Восстановление LVM при отказе диска (/dev/sda1)</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Диагностика неисправности</span>
    </p>
    <p>
      <span style="color: #0000c0;">vgs</span>&#xa0;&#xa0;# Покажет ошибку: &quot;Volume group vg01 is missing PV...&quot;
    </p>
    <p>
      <span style="color: #0000c0;">pvs -a</span>&#xa0;&#xa0;# На месте /dev/sda1 будет имя [unknown] и его UUID. Скопируйте UUID поврежденного диска, например: 1a2b3c-4d5e...
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Замена диска и восстановление метаданных</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate --uuid &quot;ВАШ_UUID&quot; --restorefile /etc/lvm/archive/vg01_00000.vg /dev/sdc1</span>&#xa0;&#xa0;# Подменяет старый UUID на новом диске /dev/sdc1 с восстановлением разметки
    </p>
    <p>
      <span style="color: #0000c0;">vgcfgrestore vg01</span>&#xa0;&#xa0;# Восстанавливает структуру группы томов vg01
    </p>
    <p>
      <span style="color: #0000c0;">vgchange -ay vg01</span>&#xa0;&#xa0;# Активирует восстановленную группу томов
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. Проверка и исправление файловой системы</span>
    </p>
    <p>
      <span style="color: #0000c0;">lvs -a -o +devices</span>&#xa0;&#xa0;# Проверяем, что lv_data и lv_backup снова в строю
    </p>
    <p>
      <span style="color: #0000c0;">fsck -y /dev/vg01/lv_data</span>&#xa0;&#xa0;# Обязательно проверяем ФС (могли быть битые блоки)
    </p>
    <p>
      <span style="color: #0000c0;">fsck -y /dev/vg01/lv_backup</span>&#xa0;&#xa0;# Проверяем второй логический том
    </p>
    <p>
      <span style="color: #0000c0;">mount -a</span>&#xa0;&#xa0;# Монтируем всё обратно
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Увеличить LV на лету (без размонтирования)" POSITION="bottom_or_right" ID="ID_322242512" CREATED="1778844548395" MODIFIED="1780477534396"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Увеличение тома онлайн (без размонтирования)</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Подготовка и добавление нового диска в группу</span>
    </p>
    <p>
      <span style="color: #0000c0;">pvcreate /dev/sdk</span>&#xa0;&#xa0;# Инициализировать новый диск (PV)
    </p>
    <p>
      <span style="color: #0000c0;">vgextend vg533 /dev/sdk</span>&#xa0;&#xa0;# Расширить группу томов (VG) за счет нового диска
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. СПОСОБ А:</span>&#xa0;Классический (В два шага)
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -L +10G /dev/vg533/lv_root</span>&#xa0;&#xa0;# Увеличить логический том (LV) НА 10 Гигабайт
    </p>
    <p>
      <span style="color: #0000c0;">resize2fs /dev/vg533/lv_root</span>&#xa0;&#xa0;# Расширить файловую систему ext4 «на лету»
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. СПОСОБ Б:</span>&#xa0;Одной командой (Рекомендуемый)
    </p>
    <p>
      <span style="color: #0000c0;">lvextend -L +10G -r /dev/vg533/lv_root</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">-r</span>&#xa0;- автоматически запустит resize2fs сразу после расширения тома
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">4. Проверка результата</span>
    </p>
    <p>
      <span style="color: #0000c0;">df -h /</span>&#xa0;&#xa0;# Убедиться, что свободное место на корне увеличилось
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Удаление PV" POSITION="bottom_or_right" ID="ID_569999464" CREATED="1780483864251" MODIFIED="1780484056774"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Удаление физического тома (PV)</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Перенос данных:</span>&#xa0;Перед удалением диска переместите с него занятые экстенты на другие доступные PV в этой же группе томов. В VG должно быть достаточно свободного места на других дисках
    </p>
    <p>
      <span style="color: #0000c0;">pvmove /dev/sdb</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Исключение из группы:</span>&#xa0;Удалите пустой физический том из группы томов (VG)
    </p>
    <p>
      <span style="color: #0000c0;">vgreduce vg01 /dev/sdb</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. Очистка сигнатур:</span>&#xa0;Удалите разметку LVM с физического устройства
    </p>
    <p>
      <span style="color: #0000c0;">pvremove /dev/sdb</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Уменьшение LV" POSITION="bottom_or_right" ID="ID_442070507" CREATED="1778843635176" MODIFIED="1782118327820"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Уменьшение тома ext4 (Относительный размер)</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">umount /disk1</span>&#xa0;&#xa0;# 1. Обязательное <span style="font-weight: bold;">размонтирование</span>&#xa0;(ext4 нельзя уменьшать онлайн)
    </p>
    <p>
      <span style="color: #0000c0;">e2fsck -f /dev/gr1/lv1</span>&#xa0;&#xa0;# 2. Обязательная <span style="font-weight: bold;">проверка</span>&#xa0;файловой системы перед изменением размера
    </p>
    <p>
      <span style="color: #0000c0;">resize2fs /dev/gr1/lv1 8G</span>&#xa0;&#xa0;# 3. <span style="font-weight: bold;">Уменьшить ФС</span>&#xa0;на 2 Гигабайта (сначала вычисляем новый размер). Если текущий размер был 10G, то пишем финальный размер: 8G
    </p>
    <ul>
      <li>
        Утилита resize2fs <span style="color: #ff0000;">не понимает знак минус</span>&#xa0;(команда resize2fs /dev/gr1/lv1 -2G завершится ошибкой). Ей всегда нужно передавать конечный объем (например, 8G). Поэтому, если вы используете в lvreduce -L -2G, вам приходится вручную вычитать эти 2 ГБ из текущего размера ФС и указывать получившуюся цифру в resize2fs
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">lvreduce -L -2G /dev/gr1/lv1</span>&#xa0;&#xa0;# 4. <span style="font-weight: bold;">Уменьшить логический том</span>&#xa0;на 2 Гигабайта от текущего
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/gr1/lv1 /disk1</span>&#xa0;&#xa0;# 5. <span style="font-weight: bold;">Вернуть в работу</span>&#xa0;и проверить
    </p>
    <p>
      <span style="color: #0000c0;">df -h /disk1</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
</node>
<node TEXT="NTFS" ID="ID_1959167025" CREATED="1758709439419" MODIFIED="1758709451331"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Подключение NTFS раздела</b>
    </p>
    <p>
      1. Создаем раздел --&gt; Выставляем тип раздела NTFS (7)
    </p>
    <p>
      2. <span style="color: #0000c0;">mkfs.ntfs -f /dev/sdb2</span>&#xa0;&#xa0;# создать ФС NTFS быстро (-f - не забивать нулями)
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="RAID" FOLDED="true" ID="ID_1522592494" CREATED="1519112079882" MODIFIED="1728040305108"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1144517713">RAID</a>&#xa0; <a href="#ID_1531600597">mdadm</a>&#xa0;&#xa0;<a href="#ID_228503920">GPT</a>&#xa0;&#xa0;<a href="#ID_1762530044">LVM</a>
    </p>
    <ul>
      <li>
        можно использовать <b>md</b>&#xa0;(RAID 5,6)&#xa0;или <b>LVM</b>&#xa0;или <b>ZFS/Btrfs</b>&#xa0;&#xa0;(или другой файловой системы со встроенными функциями управления томами и поддержки RAID)
      </li>
      <li>
        <span style="color: #ff0000;">FreeBSD</span>&#xa0;- <b>geom</b>&#xa0;и <b>GVinum</b>
      </li>
    </ul>
    <p>
      <b>Инфо</b>
    </p>
    <p>
      <span style="color: #0000c0;">fdisk -l</span>&#xa0;&#xa0;# Проверить корректность подключения дисков
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/mdstat</span>&#xa0;&#xa0;# Текущее <b>состояние</b>&#xa0;драйвера md, RAID-массивов в системе. Если будет идти пересборка, то мы это увидим
    </p>
    <p>
      <span style="color: #0000c0;">mdadm --detail /dev/md0</span>&#xa0;&#xa0;# Информация о виртуальном устройстве дискового массива RAID
    </p>
    <p>
      
    </p>
    <p>
      <b>Создать</b>
    </p>
    <p>
      <span style="color: #0000c0;">mdadm -C(--create) /dev/md0 -l(--level)5 -n(--raid-devices=)3 -x(--spare-devices=)1 /dev/sda[5-8]&#xa0;&#xa0;#</span>&#xa0;&#xa0;<b>Создать</b>&#xa0;&#xa0;программный RAID 5 md0. количество дисков 3, 1 - запасной. Можно создать программный RAID (0, 1, 4, 5, 6, 10, <a href="#ID_1531600597">multipath</a>)
    </p>
    <p>
      <span style="color: #0000c0;">mdadm --create /dev/md0 --level=1 --raid-devices=2 /dev/sdb1 /dev/sdc1</span>&#xa0;&#xa0;#&#xa0; <b>Создать</b>&#xa0;дисковый массив RAID 1 для зеркалирования данных на двух дисках
    </p>
    <p>
      <span style="color: #0000c0;">mdadm /dev/md0 --add /dev/sdd1 --fail /dev/sdb1 --remove /dev/sdb1</span>&#xa0;&#xa0;# Заменить раздел с вышедшего из строя HDD на раздел с нового HDD в рамках дискового массива RAID
    </p>
    <p>
      
    </p>
    <p>
      <b>Создание программного массива RAID 5</b>
    </p>
    <p>
      <span style="color: #0000c0;">fdisk -l</span>&#xa0;&#xa0;# Проверить корректность подключения дисков
    </p>
    <p>
      <span style="color: #0000c0;">fdisk /dev/sdd</span>&#xa0;&#xa0;# n &gt; p &gt; 1 &gt; t &gt; 1 &gt; fd &gt; w. Создать раздел типа fd на каждом из подключенных дисков. Тип раздела fd позволяет задействовать технологию автоматического обнаружения разделов дисковых массивов RAID в Linux (Linux RAID autodetect)
    </p>
    <p>
      <span style="color: #0000c0;">fdisk -l&#xa0;| grep raid</span>&#xa0;&#xa0;# Проверить корректность создания разделов на дисках.
    </p>
    <p>
      <span style="color: #0000c0;">mdadm --create /dev/md0 --chunk=64 --level=5 --raid-devices=3 /dev/sdb1 /dev/sdc1 /dev/sdd1</span>&#xa0;&#xa0;# Пример для теста. Обычно, нужно создать таблицу разделов RAID в рамках файла <b>/etc/raidtab</b>
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/mdstat</span>&#xa0;&#xa0;# Текущее <b>состояние</b>&#xa0;устройств из состава дискового RAID-массива в системе.
    </p>
    <p>
      <span style="color: #0000c0;">mdadm --detail /dev/md0</span>&#xa0;&#xa0;# Информация о виртуальном устройстве дискового массива RAID
    </p>
    <p>
      <span style="color: #0000c0;">mdadm --stop /dev/md0</span>&#xa0;&#xa0;# Деактивировать программный дисковый массив RAID
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="Замена диска (lsi)" ID="ID_1502486871" CREATED="1667218004366" MODIFIED="1667218518221"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Замена диска в raid-массиве, собранном на контроллере lsi</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>Диагностика</b>
    </p>
    <p>
      *Примечание. Везде, где “#” - подставляется номер массива/контроллера. Так же можно использовать ключевое слово all для просмотра информации со всех контроллеров (если установлено больше 1 контроллера).
    </p>
    <p>
      <font color="#0000c0">megacli -AdpAllinfo -a#</font>&nbsp;&nbsp;# Просмотр сведений о конфигурации контроллера
    </p>
    <p>
      <font color="#0000c0">megacli -EncInfo -a# </font>&nbsp;# Просмотреть &quot;id&quot; контроллера. Осуществляется просмотр не совсем ID контроллера, просто по-другому перевести не получается. У контроллеров id в системе это как правило 0, 1, 2 (если их больше одного) и т.д. Но чтобы работать с конкретным диском необходимо указывать enclosure id
    </p>
    <p>
      <font color="#0000c0">megacli -AdpBbuCmd -a#</font>&nbsp;&nbsp;# Просмотреть информацию о батарейке на контроллере
    </p>
    <p>
      <font color="#0000c0">megacli -PDGetNum -a#</font>&nbsp;&nbsp;# Просмотр количества дисков на контроллере
    </p>
    <p>
      <font color="#0000c0">megacli -ldinfo -l# -a#</font>&nbsp;&nbsp;# Просмотр сведений о логическом массиве (raid)
    </p>
    <p>
      <font color="#0000c0">megacli -pdlist -a#</font>&nbsp;&nbsp;# Просмотр сведений о физических дисках:
    </p>
    <p>
      <font color="#0000c0">megacli -pdgetmissing -a#</font>&nbsp;&nbsp;# Просмотр сведений об отсутствующих физических устройствах
    </p>
    <p>
      
    </p>
    <p>
      <b>Алгоритм замены диска в сбойном рейде</b>
    </p>
    <p>
      0) Проверить не включена ли функция autorebuild. Если включена – ОТКЛЮЧИТЬ!
    </p>
    <p>
      1) Определить сбойный диск
    </p>
    <p>
      2) Перевести диск в offline
    </p>
    <p>
      3) Отметить диск как missing
    </p>
    <p>
      4) Изъять сбойный диск
    </p>
    <p>
      5) Установить новый диск
    </p>
    <p>
      6) Перевести новый диск в состояние good
    </p>
    <p>
      7) Установить новый диск на место старого (replace missing)
    </p>
    <p>
      8) Запустить процесс rebuild на новом диске
    </p>
    <p>
      
    </p>
    <p>
      <b>Замена сбойного диска в сервере. </b>Ситуация: вышел из строя диск в рейде.
    </p>
    <p>
      Диагностика: На сервере будет мигать лампочка ошибки на салазке с диском + будет мерзко орать сигнализация контроллера.
    </p>
    <p>
      <font color="#0000c0">megacli -pdlist -a#</font>&nbsp;&nbsp;# Смотрим состояние жестких дисков
    </p>
    <p>
      <font color="#0000c0">megacli -PDList -aAll | egrep &quot;Enclosure Device ID:|Slot Number:|Inquiry Data:|Error:|Firmware state:| DiskGroup&quot;</font>&nbsp;&nbsp;# Отфильтровать вывод. Нашли мы диск, в нашем примере это диск в слоте №3. Так же нам нужно запомнить число &quot;Enclosure Device ID: 252&quot;
    </p>
    <p>
      <font color="#0000c0">megacli -pdoffline -physdrv[252:3] -a0</font>&nbsp;&nbsp;# Переводим диск в режим offline:
    </p>
    <p>
      <font color="#0000c0">megacli -pdmarkmissing -physdrv[252:3] -a0</font>&nbsp;&nbsp;# Помечаем диск как отсутствующий. На этом шаге будьте очень внимательны и не отметьте отсутствующим живой и рабочий диск!
    </p>
    <p>
      <font color="#0000c0">megacli -pdgetmissing -a0</font>&nbsp;&nbsp;# Проверить, что контроллер действительно отметил диск
    </p>
    <p>
      Можно вытаскивать диск из сервера и устанавливать новый.
    </p>
    <p>
      <font color="#0000c0">megacli -pdmakegood -physdrv[252:3] -a0</font>&nbsp;&nbsp;# Новый диск будет в статусе offline. Необходимо перевести его в статус unconfigured good
    </p>
    <p>
      <font color="#0000c0">megacli -pdreplacemissing -physdrv[#:#] -array# -row# -a#</font>&nbsp;&nbsp;# Если диск успешно перешел в статус good, заменяем им отсутствующий диск. Значения -array# -row# берем из вывода команды megacli -pdgetmissing -a0
    </p>
    <p>
      <font color="#0000c0">megacli -pdreplacemissing -physdrv[252:3] -array0 -row4 -a0</font>&nbsp;&nbsp;# Новый диск заменит отсутствующий и перейдет в статус offline снова
    </p>
    <p>
      <font color="#0000c0">megacli -pdrbld -start -physdrv[252:3] -a0</font>&nbsp;&nbsp;# Запускаем rebuild
    </p>
    <p>
      <font color="#0000c0">megacli -pdrbld -showprog -physdrv[252:3] -a0</font>&nbsp;&nbsp;# Проверять статус ребилда
    </p>
    <p>
      <font color="#0000c0">watch -d megacli -pdrbld -showprog -physdrv[252:3] -a0</font>&nbsp;&nbsp;# Или можно повесить все это на watch
    </p>
    <p>
      <font color="#0000c0">megacli -ldinfo -l0 -a0</font>&nbsp;&nbsp;# После завершения ребилда массив должен автоматически перейти в статус Optimal
    </p>
    <p>
      
    </p>
    <p>
      <b>Так же стоит обратить внимание</b>, что если в сервере используется <b>raid6</b>, то при &quot;вылете&quot; одного диска массив перейдет в статус <font color="#ff0000">Partially Degraded</font>&nbsp;(частично деградирован), т.е. вылетел 1 диск.
    </p>
    <p>
      Если же вылетят 2 диска (для raid6 это максимально допустимый предел), то массив перейдет в статус <font color="#ff0000">Degraded</font>. Это может служить отдельным маркером о количестве сбойных дисков в массиве.
    </p>
    <p>
      
    </p>
    <p>
      <b>Вспомогательные команды</b>
    </p>
    <p>
      <font color="#0000c0">megacli -AdpSetProp AlarmSilence -a#</font>&nbsp;&nbsp;# Временное отключение сигнализации
    </p>
    <p>
      <font color="#0000c0">megacli -AdpSetProp AlarmDsbl -a#</font>&nbsp;&nbsp;# Постоянное отключение сигнализации
    </p>
    <p>
      <font color="#0000c0">megacli -AdpSetProp AlarmEnbl -a#</font>&nbsp;&nbsp;# Включение сигнализации
    </p>
    <p>
      <font color="#0000c0">megacli -PdLocate -start -PhysDrv [#:#] -a#</font>&nbsp;&nbsp;# Идентификация диска (заставит мигать лампочку на сервере):
    </p>
    <p>
      <font color="#0000c0">megacli -PdLocate -stop -PhysDrv [#:#] -a#</font>&nbsp;&nbsp;# Остановить идентификацию диска
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="SCSI" ID="ID_1038347137" CREATED="1742467376454" MODIFIED="1758708895813"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1256933852">SCSI</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      Получения информации о <span style="font-weight: bold;">Host</span>, <span style="font-weight: bold;">Channel</span>, <span style="font-weight: bold;">ID</span>&#xa0;и <span style="font-weight: bold;">LUN</span>&#xa0;для SCSI диска
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">lsscsi &#xa0;</span># Информация об устройствах SCSI
    </p>
    <p>
      <span style="font-family: Lucida Console;">[0:0:0:0]&#xa0;&#xa0;&#xa0;&#xa0;disk&#xa0;&#xa0;&#xa0;&#xa0;ATA&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;ST500DM002-1BD142&#xa0;&#xa0;CC43&#xa0;&#xa0;/dev/sda </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">[1:0:0:0]&#xa0;&#xa0;&#xa0;&#xa0;cd/dvd&#xa0;&#xa0;HL-DT-ST DVD-ROM GDR8164B 0C06&#xa0;&#xa0;/dev/sr0</span>
    </p>
    <ul>
      <li>
        [H:C:I:L] - Host, Channel, ID, LUN
      </li>
      <li>
        H - Host (адаптер SCSI)
      </li>
      <li>
        C - Channel (канал)
      </li>
      <li>
        I - ID (идентификатор устройства)
      </li>
      <li>
        L - LUN (логический номер устройства)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/scsi/scsi</span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Attached devices: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Host: scsi0 Channel: 00 Id: 00 Lun: 00 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">&#xa0;&#xa0;Vendor: ATA&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Model: ST500DM002-1BD142 Rev: CC43 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">&#xa0;&#xa0;Type:&#xa0;&#xa0;&#xa0;Direct-Access&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;ANSI SCSI revision: 05 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Host: scsi1 Channel: 00 Id: 00 Lun: 00 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">&#xa0;&#xa0;Vendor: HL-DT-ST Model: DVD-ROM GDR8164B&#xa0;&#xa0;Rev: 0C06 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">&#xa0;&#xa0;Type:&#xa0;&#xa0;&#xa0;CD-ROM&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;ANSI SCSI revision: 05</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">ls -l /dev/disk/by-path</span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">lrwxrwxrwx 1 root root&#xa0;&#xa0;9 Oct&#xa0;&#xa0;1 12:34 pci-0000:00:1f.2-ata-1 -&gt; ../../sda </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">lrwxrwxrwx 1 root root 10 Oct&#xa0;&#xa0;1 12:34 pci-0000:00:1f.2-ata-1-part1 -&gt; ../../sda1</span>
    </p>
    <ul>
      <li>
        Здесь путь включает информацию о PCI шине и порте, что может быть полезно для идентификации устройства.
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">sg_map</span>&#xa0;&#xa0;# отображает SCSI устройства и их соответствующие устройства в `/dev`.
    </p>
    <p>
      <span style="font-family: Lucida Console;">/dev/sg0&#xa0;&#xa0;/dev/sda </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">/dev/sg1&#xa0;&#xa0;/dev/sr0</span>
    </p>
    <ul>
      <li>
        /dev/sg0 и /dev/sg1 - SCSI generic устройства, которые соответствуют /dev/sda и /dev/sr0
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">dmesg | grep -i scsi</span>&#xa0;&#xa0;# может показать информацию о SCSI устройствах, обнаруженных при
    </p>
    <p>
      <span style="font-family: Lucida Console;">[&#xa0;&#xa0;&#xa0;&#xa0;1.234567] scsi 0:0:0:0: Direct-Access ATA ST500DM002-1BD142 CC43 PQ: 0 ANSI: 5</span>
    </p>
    <ul>
      <li>
        Здесь указаны Host, Channel, ID и LUN
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">udevadm info --query=all --name=/dev/sda</span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">P: /devices/pci0000:00/0000:00:1f.2/ata1/host0/target0:0:0/0:0:0:0/block/sda </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">N: sda </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">S: disk/by-id/ata-ST500DM002-1BD142_ABCDEFG </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">S: disk/by-path/pci-0000:00:1f.2-ata-1</span>
    </p>
    <ul>
      <li>
        путь включает информацию о Host, Channel, ID и LUN
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="SWAP (подкачка)" ID="ID_963917846" CREATED="1532338568173" MODIFIED="1780556781562"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1827249997">swap</a>&#xa0;&#xa0;<a href="#ID_802133627">/etc/fstab</a>&#xa0; <a href="#ID_197604312">Память (задачи)</a>&#xa0; <a href="#ID_428157141">swappiness</a>&#xa0;
    </p>
    <ul>
      <li>
        Области подкачки должны инициализироваться с помощью команды <b>mkswap</b>, получающей в качестве аргумента имя накопителя, на котором располагается том подкачки
      </li>
      <li>
        Вы можете самостоятельно назначить накопитель в качестве инструмента подкачки с помощью команды <span style="color: #0000c0;">swapon накопитель</span>. Однако в большинстве случаев предпочтительнее, чтобы эта функция автоматически выполнялась на этапе загрузки
      </li>
      <li>
        <span style="font-weight: bold;">swappiness</span>&#xa0;контролирует баланс между RAM и swap
      </li>
    </ul>
    <p>
      <b>SWAP - раздел подкачки</b>
    </p>
    <p>
      <span style="color: #0000c0;">swapon -s&#xa0; </span># Просмотреть текущую конфигурацию (моментальный снимок разделов) подкачки
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/swaps</span>
    </p>
    <p>
      <span style="color: #0000c0;">fdisk /dev/sda</span>&#xa0;&#xa0;# Создать обычный раздел с требуемым размером.
    </p>
    <p>
      <span style="color: #0000c0;">vim <b>/etc/fstab</b></span>&#xa0;&#xa0;# Настроить раздел подкачки
    </p>
    <p>
      <span style="color: #008000;">/dev/sdX1 swap swap sw 0 0&#xa0;&#xa0;# </span>
    </p>
    <p>
      <span style="color: #0000c0;">mkswap /dev/sdX1</span>&#xa0;&#xa0;# Создать (отформатировать) раздел подкачки
    </p>
    <p>
      <span style="color: #0000c0;">swapon -v /dev/sdX1</span>&#xa0;&#xa0;# Включить раздел подкачки
    </p>
    <p>
      <span style="color: #0000c0;">swapoff /dev/sdX1</span>&#xa0;&#xa0;# Отключить раздел подкачки
    </p>
    <p>
      
    </p>
    <p>
      <b>SWAP - файл&#xa0;подкачки</b>
    </p>
    <p>
      <span style="color: #0000c0;">fallocate -l&#xa0;1G /swapfile</span>&#xa0;&#xa0;# Создание файла размером 1 ГБ
    </p>
    <p>
      <span style="color: #0000c0;">chmod 0600 /swapfile</span>&#xa0;&#xa0;# Установка прав доступа
    </p>
    <p>
      <span style="color: #0000c0;">mkswap /swapfile</span>&#xa0;&#xa0;# Форматирование файла как swap
    </p>
    <p>
      <span style="color: #0000c0;">swapon /swapfile</span>&#xa0;&#xa0;# Активация swap-файла
    </p>
    <p>
      <span style="color: #0000c0;">free</span>&#xa0;&#xa0;# Проверить
    </p>
    <p>
      <span style="color: #0000c0;">vmstat&#xa0;&#xa0;1</span>&#xa0;&#xa0;# Статистика виртуальной памяти
    </p>
    <p>
      swap: si — swap in (чтение из файла подкачки)
    </p>
    <p>
      swap: so — swap out (запись в файл подкачки)
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/fstab</span>&#xa0;&#xa0;# Сделать изменения постоянными
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">/swapfile none swap sw 0 0</span>
    </p>
    <p>
      <span style="color: #0000c0;">swapoff /swapfile</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Отключение</span>&#xa0;swap
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Удаление swap-файла</span>
    </p>
    <p>
      <span style="color: #0000c0;">swapoff /swapfile </span>
    </p>
    <p>
      <span style="color: #0000c0;">rm /swapfile </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">----------- </span>
    </p>
    <p>
      <span style="color: #0000c0;">free</span>&#xa0;&#xa0;# доступный раздел swap подкачки
    </p>
    <p>
      
    </p>
    <p>
      На серверах рекомендуется оставлять небольшой swap и регулировать его агрессивность через sysctl vm.swappiness=10.
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="1. Разметка дисков" FOLDED="true" ID="ID_1246468150" CREATED="1555667132737" MODIFIED="1791974337493"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1658149090">fdisk</a>&#xa0;&#xa0;parted &#xa0;<a href="#ID_1742397638">Разметка</a>&#xa0; <a href="#ID_1196874437">MBR</a>&#xa0;&#xa0;<a href="#ID_228503920">GPT</a>&#xa0; <a href="#ID_1574804007">LVM</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>Разметка дисков</b>
    </p>
    <ul>
      <li>
        <span style="color: #0000c0; font-weight: bold;">wipefs</span><span style="color: #0000c0;">&#xa0;-a /dev/sdb</span>&#xa0;&#xa0;# Удалить сигнатуры файловых систем, таблицы разделов и метаданные RAID с указанного блочного устройства
      </li>
      <li>
        <b>fdisk</b>&#xa0;(ранее без поддержки GPT и соотв. только для дисков &lt; 2 ТБ, <span style="font-weight: bold;">gdisk</span>&#xa0;- &gt; 2 ТБ)<br/>
      </li>
      <li>
        <b>parted</b>&#xa0;- для работы не только с дисковыми разделами, но и с <b>файловыми системами</b>

        <ul>
          <li>
            Разметка диска
          </li>
          <li>
            Создание на разделах файловых систем
          </li>
          <li>
            Проверка целостности, удаление, перемещение, копирование и изменение размера существующих разделов
          </li>
          <li>
            В отличие от fdisk, в parted не предусмотрено специальной команды для записи изменений. Все действия выполняются <b><span style="color: #ff0000;">в реальном времени</span></b>, без откладывания
          </li>
        </ul>
      </li>
      <li>
        <b>GParted</b><span style="font-weight: normal;">&#xa0;(пакет gparted)&#xa0;- граф. версия + позволяет задавать размеры разделов</span>
      </li>
      <li>
        <span style="font-weight: bold;">KDE Partition Manager </span>(пакет partitionmanager) - в т.ч. полнофункционально работает с LVM
      </li>
      <li>
        <b>gpart</b>&#xa0;- <span style="color: #ff0000;">FreeBSD</span>
      </li>
      <li>
        <b>cfdisk</b>&#xa0;- псевдографическая утилита для работы с разделами диска
      </li>
      <li>
        <span style="color: #0000c0;">partprobe</span>&#xa0;&#xa0;# Обновить информацию обо всех дисках без перезагрузки
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Инфо</span>
    </p>
    <p>
      <span style="color: #0000c0;">lsblk -a&#xa0;/dev/sda</span>&#xa0;&#xa0;# Cписок дисков и их <span style="font-weight: bold;">разделов </span>
    </p>
    <p>
      <span style="color: #0000c0;">blkid -o list&#xa0;</span>&#xa0;# UUID, LABEL, TYPE файловой системы
    </p>
    <p>
      <span style="color: #0000c0;">blkid -p /dev/sda1</span>&#xa0;&#xa0;# Детальная информация
    </p>
    <p>
      <span style="color: #0000c0;">parted -l&#xa0;</span>&#xa0;#&#xa0;&#xa0;Информация о разделах
    </p>
    <p>
      <span style="color: #0000c0;">fdisk -l /dev/sda </span>&#xa0;# <span style="font-weight: normal;">Разделы</span>&#xa0;из /proc/partitions
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/partitions</span>&#xa0;&#xa0;# Разделы диска (по мнению ядра)
    </p>
    <p>
      
    </p>
    <p>
      <b>Операции с разделами</b>
    </p>
    <p>
      <span style="font-weight: normal; color: #0000c0;">fdisk -l</span><span style="font-weight: normal;">&#xa0;&#xa0;# Список устройств и разделов </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #0000c0;">fdisk -l имя_диска</span><span style="font-weight: normal;">&#xa0;&#xa0;&#xa0;# Список разделов на одном диске</span>
    </p>
    <p>
      <b><span style="color: #0000c0;">fdisk</span></b><span style="color: #0000c0;">&#xa0;имя_диска</span>&#xa0;&#xa0;# Управление разделами
    </p>
    <p>
      &#xa0; <span style="color: #0000c0; font-weight: bold;">m</span>&#xa0;&#xa0;help
    </p>
    <p>
      &#xa0; <b><span style="color: #0000c0;">g</span></b>&#xa0;&#xa0;&#xa0;создать таблицу разделов GPT
    </p>
    <p>
      <b>&#xa0; <span style="color: #0000c0;">n</span></b>&#xa0;&#xa0;&#xa0;добавить новый раздел
    </p>
    <p>
      <b>&#xa0; <span style="color: #0000c0;">d</span></b>&#xa0;&#xa0;&#xa0;удалить раздел
    </p>
    <p>
      <b>&#xa0; <span style="color: #0000c0;">p</span></b>&#xa0;&#xa0;&#xa0;<span style="font-weight: bold;">показать</span>&#xa0;существующую таблицу разделов
    </p>
    <p>
      <b>&#xa0; <span style="color: #0000c0;">t</span>&#xa0;</b>&#xa0;&#xa0;изменить метку типа раздела
    </p>
    <p>
      <b>&#xa0; <span style="color: #0000c0;">w</span></b>&#xa0;&#xa0;сохранить изменения и выйти
    </p>
    <p>
      <b>&#xa0; <span style="color: #0000c0;">q</span></b>&#xa0;&#xa0;&#xa0;выйти без сохранения изменений
    </p>
    <p>
      
    </p>
    <p>
      <b><span style="color: #0000c0;">parted </span></b>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;help команда</span>&#xa0;- помощь по команде
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;select /dev/sd<b>X</b></span>&#xa0;&#xa0;# <span style="font-weight: bold;">Смена</span>&#xa0;&#xa0;диска
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">print</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Список</span>&#xa0;&#xa0;разделов диска
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">mklabel</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать</span>&#xa0;&#xa0;новую пустую <span style="font-weight: bold;">таблицу</span>&#xa0;разделов --&gt; указать тип таблицы разделов. если объем диска &lt;&#xa0;&#xa0;2TB - тип: msdos. Иначе - gpt
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">mkpart primary ext4 0 100%</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать</span>&#xa0;&#xa0;первичный <span style="font-weight: bold;">раздел</span>, который занимает весь объем жесткого диска. Либо mkpart и далее выбираем параметры. Размер (например, start 1G, end 20G или end конечное = -1)
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;resizeepart</span>&#xa0;&#xa0;# <b>Изменить размер раздела.</b>&#xa0;&#xa0;Будет предложено указать размер раздела, который вы хотите изменить. Введите его номер. После этого вам будет предложено установить новую конечную точку для этого раздела. Помните, что по умолчанию единицы находятся в МБ
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">rm &lt;номер_раздела&gt;</span>&#xa0;&#xa0;&#xa0;# <b>Удалить раздел</b>
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">rescue</span>&#xa0;&#xa0;# <b>Восстановить потерянный раздел.</b>&#xa0;&#xa0;Если раздел найден в диапазоне между начальной и конечной точками, он попытается восстановить его
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">set 2 &lt;флаг раздела&gt; on</span>&#xa0;&#xa0;&#xa0;# <b>Изменить флаг раздела.</b>&#xa0;&#xa0;Поддерживаемые флаги: boot, root, swap, hidden, raid, lvm, lba, legacy_boot, irst, esp, palo
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">print</span>&#xa0;&#xa0;# Вывести таблицу разделов
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;unit единицы</span>&#xa0;&#xa0;# Установка единиц измерения (s, MiB,GiB, MB, GB)
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">quit </span>
    </p>
    <h6>
      <span style="font-weight: bold;">parted в неинтерактивном режиме</span>
    </h6>
    <p>
      <span style="color: #0000c0;">parted --script /dev/sda mklabel gpt </span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">--script</span>&#xa0;- команда выполняется в автоматическом (неинтерактивном) режиме, без запросов подтверждения
      </li>
      <li>
        <span style="font-weight: bold;">/dev/sda</span>&#xa0;- диск, с которым производится работа
      </li>
      <li>
        <span style="font-weight: bold;">mklabel gpt</span>&#xa0;- создаёт новую таблицу разделов GPT (GUID Partition Table) на диске, стирая все предыдущие данные о разделах
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">parted --script /dev/sda mkpart primary 1 40% </span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">mkpart primary</span>&#xa0;- создаёт первичный раздел (в GPT все разделы равнозначны, но синтаксис primary остался для совместимости)
      </li>
      <li>
        <span style="font-weight: bold;">1 40%</span>&#xa0;- указывает начальную (1MiB) - стандартный отступ для выравнивания в GPT и конечную (40% от размера диска) позиции раздела
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">parted --script /dev/sda mkpart primary 40% 70% </span>
    </p>
    <p>
      <span style="color: #0000c0;">parted --script /dev/sda mkpart primary 70% 100% </span>
    </p>
    <p>
      <span style="color: #0000c0;">parted --script /dev/sda print </span>
    </p>
  </body>
</html></richcontent>
<font BOLD="false"/>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="Установить метки разделов" ID="ID_1622217579" CREATED="1758709269004" MODIFIED="1758709280559"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Установить метки разделов</b>
    </p>
    <p>
      <span style="color: #0000c0;">e2label /dev/___ &lt;метка&gt;</span>&#xa0;&#xa0;# ext2/ext3/ext4
    </p>
    <p>
      <span style="color: #0000c0;">reiserfstune -l &lt;метка&gt; /dev/___</span>&#xa0;&#xa0;# ReiserFS
    </p>
    <p>
      <span style="color: #0000c0;">jfs_tune -L &lt;метка&gt; /dev/___</span>&#xa0;&#xa0;# JFS
    </p>
    <p>
      <span style="color: #0000c0;">xfs_admin -L &lt;label&gt; /dev/___</span>&#xa0;&#xa0;# XFS
    </p>
    <p>
      <span style="color: #0000c0;">ntfslabel /dev/___ &lt;метка&gt;</span>&#xa0;&#xa0;# NTFS
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="2. Форматирование (файловая система)" ID="ID_125951154" CREATED="1589401247832" MODIFIED="1780399297307"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_298479763">Типы файловых систем</a>&#xa0; <a href="#ID_368045672">fsck</a>&#xa0; <a href="#ID_1698791367">Диагностика ФС</a>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        <b>/proc/filesystems</b>&#xa0;- список поддерживаемых файловых систем
      </li>
      <li>
        <b>/etc/filesystems</b>&#xa0;- Список авт. определенных ФС (на случай использования mount без параметра -t
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>Узнать&#xa0;файловую систему раздела</b>
    </p>
    <p>
      <span style="color: #0000c0;">fstype /dev/sdb1 </span>
    </p>
    <p>
      <span style="color: #0000c0;">blkid</span>&#xa0;&#xa0;&#xa0;# + узнать UUID
    </p>
    <p>
      <span style="color: #0000c0;">lsblk -f</span>
    </p>
    <p>
      <span style="color: #0000c0;">file -sL /dev/sdb1 </span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Инфо</b>
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/filesystems | grep -v nodev</span>&#xa0;&#xa0;# Загруженные драйвера файловых систем
    </p>
    <p>
      <span style="color: #0000c0;">cat /etc/filesystems</span>&#xa0;&#xa0;# Список автоматически определенных ФС (на случай использования mount без параметра -t)
    </p>
    <p>
      <span style="color: #0000c0;">df -T</span>&#xa0;&#xa0;# Разделы с указанием ФС
    </p>
    <p>
      <span style="color: #0000c0;">ls /sbin/mk*</span>&#xa0;&#xa0;# Cписок файловых систем, поддерживаемых в системе
    </p>
    <p>
      
    </p>
    <p>
      <b>Синтаксис </b>
    </p>
    <p>
      <span style="color: #0000c0;">mkfs -t [filesystem] -L [label] device </span>
    </p>
    <p>
      <span style="color: #0000c0;">mkfs.[filesystem] -L [label] device</span>
    </p>
    <p>
      <span style="color: #0000c0;">mkfs.ext4 -L Test /dev/sdb1</span>&#xa0;&#xa0;# Cоздать ФС ext4 с меткой тома «Test» в директории /dev/sdb1
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">fsck /dev/sdb1</span>&#xa0;&#xa0;# Выполнить проверку ФС
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/vda2 /tmp/sysroot</span>&#xa0;&#xa0;# Примонтировать и посмотреть файлы
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="3. Монтирование" FOLDED="true" ID="ID_924945041" CREATED="1519112079881" MODIFIED="1780397039221"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1079191969">mount</a>&#xa0; <a href="#ID_802133627">/etc/fstab</a>&#xa0;&#xa0;<a href="#ID_1832050794">.mount (systemd)</a>&#xa0;&#xa0;<a href="#ID_1698791367">Диагностика ФС</a>&#xa0; <a href="#ID_1279369409">/dev</a>&#xa0; <a href="#ID_708696887">Автомонтирование</a>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        <b>Точка монтирования</b>&#xa0;- директория, из которой будет доступна ФС
      </li>
      <li>
        <b>Монтирование файловой системы</b>&#xa0;- делает ее доступной для использования посредством специально созданной директории
      </li>
      <li>
        Если смонтировать ФС в директорию, в которой <b>уже содержатся файлы</b>, то уже имеющиеся файлы будут скрыты до момента отмонтирования ФС
      </li>
      <li>
        <b>/proc/filesystems</b>&#xa0;- список поддерживаемых файловых систем
      </li>
      <li>
        <b>/etc/filesystems</b>&#xa0;- список авт. определенных ФС (на случай использования mount без параметра -t
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>Инфо. Список смонтированных ФС</b>
    </p>
    <p>
      <span style="color: #0000c0;">df -hT</span>&#xa0;&#xa0;# Cписок смонтированных ФС, -h&#xa0;(human-readable), -T&#xa0;(тип ФС)
    </p>
    <p>
      <span style="color: #0000c0;">mount | column -t</span>&#xa0;&#xa0;# Список устройств и их точек монтирования
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/mounts</span>&#xa0;&#xa0;# Инфо о смонтированных устройствах. Представляется ядром
    </p>
    <p>
      <span style="color: #0000c0;">cat /etc/mtab</span>&#xa0;&#xa0;# Предоставляется утилитой mount
    </p>
    <p>
      <span style="color: #0000c0;">findmnt </span>&#xa0;# Аналог mount со связями
    </p>
    <p>
      
    </p>
    <p>
      <b>Монтировать/Отмонтировать</b>
    </p>
    <ul>
      <li>
        временное монтирование с помощью <span style="font-weight: bold;">mount</span>
      </li>
      <li>
        постоянное (автоматическое) монтирование с помощью <a href="#ID_167085322">/etc/fstab</a>
      </li>
      <li>
        монтирование с помощью <a href="#ID_161890769">systemd</a>
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">mkdir /backups</span>&#xa0;&#xa0;# Создать точку монтирования /backups
    </p>
    <p style="text-align: center">
      <span style="color: #0000c0; font-family: Lucida Console;">mount /dev/устройство точка_монтирования</span>
    </p>
    <p>
      <span style="color: #0000c0;">mount -t ext4 /dev/sdb1 /home/test1/</span>&#xa0;&#xa0;# Монтировать ФС в директрию. <b>-t&#xa0;&#xa0;(тип ФС)</b>&#xa0;не обязателен, mount автоматичеси идентифицирует ФС&#xa0;
    </p>
    <p>
      <span style="color: #0000c0;">mount /dev/scd0 /mnt/cdrom</span>&#xa0;&#xa0;# Монтирование CDROM
    </p>
    <p>
      <span style="color: #0000c0;">mount -t cd9660 /dev/acd0 /mnt</span>&#xa0;&#xa0;# Монтирование <b>CD/DVD</b>&#xa0;носителя. <b>cd9660</b>-имя драйвера ФС. <b>/dev/acd0</b>&#xa0;&#xa0;- файл устройства. <b>/mnt</b>&#xa0;&#xa0;- папка для содержимого устройства
    </p>
    <p>
      <span style="color: #0000c0;">mount <b>-а</b>&#xa0;-t nfs</span>&#xa0;&#xa0;# Чтобы изменения вступили в силу немедленно (без перезагрузки)
    </p>
    <p>
      <span style="color: #0000c0;">umount /dev/устройство</span>&#xa0;&#xa0;или&#xa0; <span style="color: #0000c0;">umount точка_монтирования</span>&#xa0;&#xa0;#&#xa0;<b>Отмонтировать</b>&#xa0;ФС
    </p>
    <p>
      <span style="color: #0000c0;">umount -l /mount/point</span>&#xa0;&#xa0;# Если процессы критичны и их нельзя убивать. отмонтирует файловую систему, но реальное освобождение произойдёт, когда все процессы перестанут её использовать
    </p>
    <p>
      <span style="color: #0000c0;">fuser -mu точка_монтирования</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Процессы, которые читают или пишут</span>&#xa0;в любые файлы внутри точки монтирования
    </p>
    <p>
      
    </p>
    <p>
      <b>FreeBSD</b>
    </p>
    <p>
      <span style="color: #0000c0;">mount_msdosfs /dev/da0s1&#xa0;/mnt&#xa0;&#xa0;#</span>&#xa0;монт. <b>USB-накопителя (FAT32)</b>&#xa0;без кондировки&#xa0;&#xa0;
    </p>
    <p>
      <span style="color: #0000c0;">mount_msdosfs -W koi2dos /dev/da0s1&#xa0;/mnt</span>&#xa0;&#xa0;# монт. USB-накопителя (FAT32). Если ругается на отсутствие файла msdosfs_iconv&#xa0;&#xa0;то <b>ставим iconv</b>&#xa0;&#xa0;(отвечает за конвертацию между кодировками текста)
    </p>
    <p>
      &#xa0;&#xa0; <span style="color: #0000c0;">rehash</span>&#xa0;&#xa0;# после установки пакетов, для повторного сканирования PATH. (Необходимо только если используете csh)
    </p>
    <p>
      <span style="color: #0000c0;">mount_ntfs -c KOI8-R /dev/da0s1 /mnt</span>&#xa0;&#xa0;# монтирование USB-накопителя (NTFS)
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
