    <p>
      <span style="font-family: Lucida Console; color: #0000c0;">chmod </span><span style="font-family: Lucida Console; color: #ff0000;">4</span><span style="font-family: Lucida Console; color: #0000c0;">555 file</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# -r-</span><span style="font-family: Lucida Console; color: #ff0000;">s</span><span style="font-family: Lucida Console;">r-xr-x (SUID) # </span><span style="font-family: Lucida Console; color: #0000c0;">chmod u+</span><span style="font-family: Lucida Console; color: #ff0000;">s</span><span style="font-family: Lucida Console; color: #0000c0;">&#xa0;file</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #0000c0;">chmod </span><span style="font-family: Lucida Console; color: #ff0000;">2</span><span style="font-family: Lucida Console; color: #0000c0;">555 file</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# -r-xr-</span><span style="font-family: Lucida Console; color: #ff0000;">s</span><span style="font-family: Lucida Console;">r-x (SGID) # </span><span style="font-family: Lucida Console; color: #0000c0;">chmod g+</span><span style="font-family: Lucida Console; color: #ff0000;">s</span><span style="font-family: Lucida Console; color: #0000c0;">&#xa0;&#xa0;file</span>
