<node TEXT="/usr/local/bin/mediawiki_backup.sh" ID="ID_699203088" CREATED="1738775257266" MODIFIED="1739349614890"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">vim /usr/local/bin/mediawiki_backup.sh</span>&#xa0;&#xa0;# скрипт создания и копирования бэкапов на vm-01
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">#!/bin/bash </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Использовать для отладки скрипта </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># set -euxo pipefail </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Переменные </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">backup_server='10.128.0.21' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">backup_directory='/backup/daily' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">scp_user='s___' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">archive_directory='/var/www/mediawiki' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">archive_name=&quot;/backup/mediawiki_backup-$(date +&quot;%Y%m%d&quot;).tgz&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Функция архивирования </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">create_archive() { </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;tar -czf &quot;$archive_name&quot; -C &quot;$archive_directory&quot; . </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;chown &quot;$scp_user&quot;:&quot;$scp_user&quot; &quot;$archive_name&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">} </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Функция копирования архива на другой сервер через SCP </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">scp_archive() { </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;sudo -u&quot;$scp_user&quot; scp &quot;$archive_name&quot; $scp_user@$backup_server:$backup_directory </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">} </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Вызвать функцию архивации </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">create_archive </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Проверить доступность хранилища </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">if ping -c1 -W5 &quot;$backup_server&quot; &amp;&gt; /dev/null </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">then </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;echo &quot;Сервер $backup_server доступен.&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">else </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;echo &quot;Сервер $backup_server недоступен.&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;exit 1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">fi </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Вызвать функцию копирования архива в хранилище </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">scp_archive </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Удалить файл архива на рабочем сервере </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">rm &quot;$archive_name&quot;</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="/etc/systemd/system/backup.service" ID="ID_161885722" CREATED="1738775266357" MODIFIED="1782031594487"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      служба для запуска скриптов на vm-01
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/systemd/system/backup.service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Unit] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=Running the script mediawiki_backup.sh by timer. </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=network.target </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Service] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Type=oneshot </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecStart=/usr/local/bin/mediawiki_backup.sh </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Install] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WantedBy=multi-user.target</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="/etc/systemd/system/backup.timer" ID="ID_685606891" CREATED="1738775273386" MODIFIED="1782031575916"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      таймер для запуска службы ночью на vm-01
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/systemd/system/backup.timer </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Unit] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=Backup and copy timer </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Timer] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># daily </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">OnCalendar=*-*-* 00:01:00 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># minutely for tests </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># OnCalendar=*-*-* *:*:00 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Install] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WantedBy=timers.target</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="/usr/local/bin/mediawiki_dump.sh" ID="ID_1231910519" CREATED="1738775281453" MODIFIED="1739349631256"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">vim /usr/local/bin/mediawiki_dump.sh</span>&#xa0;&#xa0;# скрипт создания и копирования дампов на db-01
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">#!/bin/bash </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Использовать для отладки скрипта </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">set -euxo pipefail </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Переменные </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">backup_server='10.128.0.21' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">backup_directory='/backup/daily' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">scp_user='s___' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">db_name='my_wiki' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">dump_name=&quot;/backup/my_wiki-$(date +&quot;%Y%m%d&quot;).dump&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Функция выгрузки дампа </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">create_dump() { </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;pg_dump -U wikiuser -Fc &quot;$db_name&quot; &gt; &quot;$dump_name&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;chown &quot;$scp_user&quot;:&quot;$scp_user&quot; &quot;$dump_name&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">} </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Функция копированда дампа на другой сервер через SCP </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">scp_dump() { </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;sudo -u&quot;$scp_user&quot; scp &quot;$dump_name&quot; $scp_user@$backup_server:$backup_directory </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">} </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Вызвать функцию выгрузки дампа </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">create_dump </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Проверить доступность хранилища </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">if ping -c1 -W5 &quot;$backup_server&quot; &amp;&gt; /dev/null </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">then </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;echo &quot;Сервер $backup_server доступен.&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">else </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;echo &quot;Сервер $backup_server недоступен.&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;exit 1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">fi </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Вызвать функцию копирования дампа в хранилище </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">scp_dump </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Удалить файл дампа на рабочем сервере </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">rm &quot;$dump_name&quot;</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="/etc/systemd/system/dump.service" ID="ID_1524821871" CREATED="1738775289204" MODIFIED="1782031640185"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      служба для запуска скриптов на db-01
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/systemd/system/dump.service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Unit] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=Running the script mediawiki_dump.sh by timer. </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=network.target </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Service] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Type=oneshot </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecStart=/usr/local/bin/mediawiki_dump.sh </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Install] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WantedBy=multi-user.target </span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="/etc/systemd/system/dump.timer" ID="ID_1089382476" CREATED="1738775297731" MODIFIED="1738775726037"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      службы для запуска скриптов ночью на db-01
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/systemd/system/dump.timer </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Unit] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=Dump and copy timer </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Timer] </span>
    </p>
