      <span style="color: #008000; font-family: Lucida Console;">WantedBy=timers.target </span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Ротация бэкапов" ID="ID_1663024524" CREATED="1738934972352" MODIFIED="1738935235303"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-family: Lucida Console; color: #0000c0;">vim /usr/local/bin/rotation_backup_mediawiki.sh</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">#!/bin/bash </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Ротация в каталоге /backup. 7 ежедневных + 7 еженедельных + 6 ежемесячных </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Переменные </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">DAILY_DIR=&quot;/backup/daily&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">WEEKLY_DIR=&quot;/backup/weekly&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">MONTHLY_DIR=&quot;/backup/monthly&quot; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Раскидываем файлы в каталоге daily </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">for file in &quot;$DAILY_DIR&quot;/*; do </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;# Получить дату модификации файла </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;MOD_DATE=$(date -r &quot;$file&quot; +%u) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;MOD_DATE_OF_MONTH=$(date -r &quot;$file&quot; +%d) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;# Если дата модификации файла - понедельник (1), то копировать файл в каталог weekly </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;if [ &quot;$MOD_DATE&quot; -eq 1 ]; then </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;cp &quot;$file&quot; &quot;$WEEKLY_DIR&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;fi </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;# Если дата модификации файла - 28 число, то копировать файл в каталог monthly </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;if [ &quot;$MOD_DATE_OF_MONTH&quot; -eq 28 ]; then </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;cp &quot;$file&quot; &quot;$MONTHLY_DIR&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;fi </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">done </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Удалить старые архивы </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">find &quot;$DAILY_DIR&quot; -type f -mtime +7 -exec rm {} \; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">find &quot;$WEEKLY_DIR&quot; -type f -mtime +31 -exec rm {} \; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">find &quot;$MONTHLY_DIR&quot; -type f -mtime +186 -exec rm {} \; </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #0000c0;">crontab -e</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">0 2 * * * /usr/local/bin/rotation_backup_mediawiki.sh &gt; /dev/null 2&gt;&amp;1</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
</node>
<node TEXT="Сеть" FOLDED="true" ID="ID_1375496626" CREATED="1519112079892" MODIFIED="1788436230953"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_441851360">ip</a>&#xa0; <a href="#ID_1140070626">iptables</a>&#xa0; <a href="#ID_1671350392">ufw</a>&#xa0; <a href="#ID_1118806911">netplan</a>&#xa0; <a href="#ID_1487204159">route</a>&#xa0; <a href="#ID_1381186386">arp</a>&#xa0; <a href="#ID_1852167368">ping</a>&#xa0; <a href="#ID_1045382812">netstat</a>&#xa0; <a href="#ID_1618830210">ss</a>&#xa0; <a href="#ID_565127013">nmap</a>&#xa0; <a href="#ID_1962375635">NetworkManager</a>&#xa0; <a href="#ID_185592585">systemd-networkd</a>&#xa0; <a href="#ID_1535282607">NFS-сервер</a>&#xa0; <a href="#ID_762231132">Диагностика(сеть)</a>&#xa0;&#xa0;<a href="#ID_592807672">Network namespace</a>&#xa0; <a href="#ID_1582375529">Проброс портов</a>&#xa0; <a href="#ID_1719273993">Настройка Wi-Fi</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Пакеты сетевых утилит</span>:
    </p>
    <ul>
      <li>
        net-tools - старый
      </li>
      <li>
        iproute2 - новый
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Применение настроек:</span>&#xa0;Используйте NetworkManager или systemd-networkd (в зависимости от дистрибутива):
    </p>
    <p>
      <span style="color: #0000c0;">systemctl restart NetworkManager</span>&#xa0;&#xa0;# для Ubuntu/RHEL с GUI/десктопов
    </p>
    <p>
      <span style="color: #0000c0;">netplan apply</span>&#xa0;&#xa0;# для современной Ubuntu Server
    </p>
    <p>
      или
    </p>
    <p>
      i<span style="color: #0000c0;">fdown интерфейс</span>
    </p>
    <p>
      <span style="color: #0000c0;">ifup интерфейс</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Мониторинг портов и соединений</span>
    </p>
    <p>
      <span style="color: #0000c0;">ss -tulpan</span>&#xa0;&#xa0;# Аналог netstat. Показывает сокеты (TCP, UDP, процессы, порты в цифрах)
    </p>
    <p>
      <span style="color: #0000c0;">netstat -tulpan</span>&#xa0;&#xa0;# Инфо о <span style="font-weight: bold;">портах (локально)</span>
    </p>
    <p>
      <span style="color: #0000c0;">lsof -i :80</span>&#xa0;&#xa0;# Показывает, какой процесс занял конкретный порт (работает для :80, TCP или UDP)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Проверка удаленных портов (Скан)</span>
    </p>
    <p>
      <span style="color: #0000c0;">nc -zv example.com 443</span>&#xa0;&#xa0;# Самый быстрый способ проверить, открыт ли порт на удаленном сервере
    </p>
    <p>
      <span style="color: #0000c0;">nmap -p 443 target.host</span>&#xa0;&#xa0;# Сканирование конкретного порта
    </p>
    <p>
      <span style="color: #0000c0;">nmap -p- localhost</span>&#xa0;&#xa0;# Для сканирования всех портов локально
    </p>
    <p>
      <span style="color: #0000c0;">curl -v telnet://example.com:443</span>&#xa0;&#xa0;# Рабочая альтернатива утилите telnet
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Интерфейсы и Маршрутизация</span>
    </p>
    <p>
      <span style="color: #0000c0;">ip a</span>&#xa0;&#xa0;# Сетевые интерфейсы и их IP-адреса
    </p>
    <p>
      <span style="color: #0000c0;">ip r</span>&#xa0;&#xa0;# Таблица маршрутизации (замена старым <span style="color: #0000c0;">route -n</span>&#xa0;и <span style="color: #0000c0;">netstat -rn</span>)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Анализ и Расчет сети</span>
    </p>
    <p>
      <span style="color: #0000c0;">tcpdump -nvvv -i any</span>&#xa0;&#xa0;# Захват сетевого трафика
    </p>
    <ul>
      <li>
        -i any слушает все интерфейсы (вместо только локального lo)
      </li>
      <li>
        -nvvv дает максимальную детальность без резолва имен
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">ipcalc 192.168.1.1/24</span>&#xa0;&#xa0;# Расчет подсети (работает одинаково синтаксически, состав вывода зависит от версии утилиты в дистрибутиве)
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="DHCP" FOLDED="true" ID="ID_5823529" CREATED="1519112079893" MODIFIED="1751368883517"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_567091282">DHCP</a>&#xa0; <a href="#ID_1844571578">LDAP</a>
    </p>
    <p>
      
    </p>
    <p>
      При увеличении количества машин и при физической невозможности больше сопровождать вручную, тогда запускаем <b>LDAP сервер</b>&#xa0;и подцепляем все к нему
    </p>
    <ul>
      <li>
        После этого вся информация хранится в LDAP-сервере
      </li>
      <li>
        для любого хоста информация берется из LDAP-сервера
      </li>
      <li>
        <b>Клиент</b>&#xa0;протокола DHCP не имеет конфигурации и хранит файл состояний для каждого соединения в каталогах <b>/var/lib/dhcp</b>&#xa0;или <b>/var/lib/dholient</b>
      </li>
      <li>
        <span style="color: #0000c0;">man 5 dhcpd.conf</span>&#xa0;&#xa0;# Описание с примером
      </li>
      <li>
        Новые объекты аренды добавляются в конец файла <b>dhcpd.leases </b>(вручную не редактировать, можно только удалить для очистки)
      </li>
      <li>
        Клиенты - dhcpcd, dhclient, pump
      </li>
    </ul>
    <p>
      CentOS -&#xa0;dhcp
    </p>
    <p>
      Deblan и Ubuntu - ics-dhcp-server
    </p>
    <p>
      FreeBSD - ics-dhcp43-server
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      -----------
    </p>
    <p>
      DHCP client
    </p>
    <p>
      dhclient
    </p>
    <p>
      dhcpcd
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="case1" ID="ID_1792362546" CREATED="1726933606492" MODIFIED="1726933804484"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">apt-get install isc-dhcp-server</font>
    </p>
    <p>
      <font color="#0000c0">cat /etc/default/isc-dhcp-server</font>
    </p>
    <p>
      <font color="#008000">INTERFACESv4=&quot;eth0&quot;</font>&nbsp;&nbsp;# Указать используемый сетевой интерфейс
    </p>
    <p>
      <font color="#0000c0">cat /etc/netplan/&lt;какой-то файл . yaml&gt;</font>
    </p>
    <p>
      <font color="#008000">network: </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;ethernets: </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;eth0: </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;dhcp4: false </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;addresses: [192.168.1.1/24] </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;nameservers: </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;addresses: [&lt;IP-адрес DNS сервера&gt;] </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;version: 2 </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">cat /etc/dhcp/dhcpd.conf</font>
    </p>
    <p>
      <font color="#008000">option domain-name &quot;my-practicum&quot;;&nbsp;&nbsp;</font># Устанавливает доменное имя для сети&nbsp;
    </p>
    <p>
      <font color="#008000">option domain-name-servers &lt;IP-адрес DNS сервера&gt;;&nbsp;&nbsp;</font># Указывает DNS-сервер для клиентов DHCP
    </p>
    <p>
      <font color="#008000">default-lease-time 600;&nbsp;&nbsp;</font># Время аренды в секундах для IP-адреса
    </p>
    <p>
      <font color="#008000">max-lease-time 7200;&nbsp;&nbsp;</font># Максимальная продолжительность
    </p>
    <p>
      <font color="#008000">ddns-update-style none;&nbsp;&nbsp;</font># Метод обновления динамического DNS
    </p>
    <p>
      <font color="#008000">authoritative;&nbsp;&nbsp;</font># Этот DHCP-сервер авторитетен и может выдавать IP-адреса в сети
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">subnet 192.168.1.0 netmask 255.255.255.0 {&nbsp;&nbsp;</font>#&nbsp;&nbsp;Начало описания конфигурации подсети
    </p>
    <p>
      <font color="#008000">&nbsp;range 192.168.1.15 192.168.1.200;&nbsp;&nbsp;</font># Диапазон IP-адресов, который DHCP-сервер может выделять клиентам в этой подсети
    </p>
    <p>
      <font color="#008000">&nbsp;option domain-name-servers &lt;IP-адрес DNS сервера&gt;;&nbsp;&nbsp;</font># Устанавливает DNS-сервер для данной подсети
    </p>
    <p>
      <font color="#008000">&nbsp;option domain-name &quot;my-practicum&quot;;&nbsp; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;option routers 192.168.1.10;&nbsp;&nbsp;</font># Задаёт IP-адрес шлюза для этой подсети
    </p>
    <p>
      <font color="#008000">&nbsp;option subnet-mask 255.255.255.0;&nbsp;&nbsp;</font># Маска подсети для нашей сети
    </p>
    <p>
      <font color="#008000">&nbsp;option broadcast-address 192.168.1.255;&nbsp;&nbsp;</font># Широковещательный адрес для неё
    </p>
    <p>
      <font color="#008000">&nbsp;default-lease-time 600; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;max-lease-time 7200; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;}</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">systemctl restart isc-dhcp-server</font>&nbsp;&nbsp;# Перезапустить службу
    </p>
    <p>
      <font color="#0000c0">systemctl status isc-dhcp-server</font>&nbsp;&nbsp;# Проверить статус
    </p>
    <p>
      
    </p>
    <p>
      <b>Проверка</b>
    </p>
    <ul>
      <li>
        настройте адаптер внутри этой сети на получение IP-адреса по DHCP
      </li>
      <li>
        сетевой адаптер получит IP-адрес из заданного на сервере диапазона, и в том числе дополнительные параметры вроде DNS-сервера
      </li>
      <li>
        <font color="#0000c0">dhcp-lease-list</font>&nbsp;&nbsp;# Посмотреть выданные сервером IP-адреса
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="1. Установка" ID="ID_1662735065" CREATED="1519112079893" MODIFIED="1726928390931"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0"><b>1. # dpkg -reconfigure debconf&nbsp;&nbsp;#</b></font>&nbsp;переконфигурируем, количество задаваемых вопросов при установке пакетов
    </p>
    <p>
      <font color="#0000c0"><b>2.1 # apt-get install dhcp3-server</b></font>&nbsp;&nbsp;# установка v3 DHCP-сервера Ubuntu
    </p>
    <p>
      <font color="#0000c0"># yum install dhcp</font>&nbsp;&nbsp;# Инсталляция
    </p>
    <p>
      <font color="#0000c0"># /etc/init.d/dhcpd start</font>&nbsp;&nbsp;# Пуск
    </p>
    <p>
      <font color="#0000c0"># chkconfig dhcpd on</font>&nbsp;&nbsp;# Добавить в автозагрузку
    </p>
    <p>
      
    </p>
    <p>
      <font face="SansSerif"><b>Файлы конфигурации dhcp-сервера:</b>&nbsp; </font>
    </p>
    <ul>
      <li>
        <font face="SansSerif">/etc/default/<b>dhcp</b>&nbsp;</font>
      </li>
      <li>
        <font face="SansSerif">/etc/<b>dhcpd.conf</b>&nbsp;(возможный адрес /etc/dhcp3/dhcpd.conf)</font>
      </li>
    </ul>
    <p>
      <font color="#0000c0"><b>3.</b>&nbsp;# vi /etc/default/<b>dhcp3-server</b></font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;<b>INTERFACES=&quot;eth1&quot;</b>&nbsp;&nbsp;#</font>&nbsp;&nbsp;указываем интерфейс. делаем чтобы DHCP сервер привязывался к eth1 (внутренний интерфейс)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"><b>4.</b>&nbsp;# vi /etc/dhcp3/<b>dhcpd.conf</b></font>
    </p>
    <p>
      ???&nbsp;&nbsp;# сделать чтобы адреса раздавались из динамического пула
    </p>
    <p>
      <font color="#008000"><b>option domain-name &quot;d4.class.us&quot;;</b></font>&nbsp;&nbsp;# доменное имя
    </p>
    <p>
      <font color="#008000">option domain-name-servers 10.10.<b>4</b>.1;&nbsp;&nbsp;#</font>&nbsp;сервер имен
    </p>
    <p>
      <font color="#008000"><b>default-lease-time 600;</b>&nbsp;&nbsp;#</font>&nbsp;время аренды IP адреса (по умолчанию). Рекомендуется 600 сек.
    </p>
    <p>
      <font color="#008000"><b>max-lease-time 259200;</b>&nbsp;&nbsp;#</font>&nbsp;макс. время аренды (используется клиентом если нет связи с сервером). При завершении времени адреса берутся из <a href="#ID_1184089881">APIPA</a>&nbsp;(169.254.X.Y.)
    </p>
    <p>
      <font color="#008000"><b>option routers 10.10.4.1; </b></font>
    </p>
    <p>
      <font color="#008000"><b>authoritative;&nbsp;&nbsp;#</b></font><b>&nbsp;</b>данный DHCP сервер является самым главным в сети. Если сервер на авторитетный, то он перед выдачей будет проверять адрес на занятость, т.е. будет тупить. <b>Ставить обязательно</b>
    </p>
    <p>
      <font color="#008000"><b>subnet 10.10.4.0 netmask 255.255.255.0&nbsp;{</b></font>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <b><font color="#008000">range 10.10.4.200 10.10.4.210;</font></b>&nbsp;&nbsp;#выдавать дин. адреса из диапазона. <b>Однако дин. IP адреса это не всегда здорово</b>. Например, если кто-то накачал объем, а адрес потом сменился. С кого спрашивать?
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"><b>5. # /etc/init.d/dhcp3-server start</b></font>&nbsp;&nbsp;# запуск DHCP сервера
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">$ netstat -lpn --inet</font>&nbsp;&nbsp;# проверяем порт udp 0.0.0.0:67 (есть\нет)
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">$ less /var/log/syslog</font>&nbsp;&nbsp;# если сервер не стартовал, смотрим лог
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#0000c0">6. # /etc/init.d/dncp3-server force-reload</font></b>&nbsp;&nbsp;# перезапуск сервера (если были внесены изменения)
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node ID="ID_886189275" CREATED="1519112079894" MODIFIED="1726933857583"><richcontent TYPE="NODE">

<html>
  <head>
    
  </head>
  <body>
    <p>
      1. <font color="#ff0000">FreeBSD.</font>&#160;&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072;
    </p>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0"><b>0. # pkg_add -r isc-dhcp31-server </b></font>// <font color="#ff0000">FreeBSD</font>. Ставим
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#0000c0">1. # vi rc.conf</font>&nbsp;// вешаем DHCP на адаптер внутренней сети</b>
    </p>
    <p>
      <font color="#008000">dhcpd_enable=&quot;yes&quot; </font>
    </p>
    <p>
      <font color="#008000">dhcpd_iface=&quot;em1&quot; </font>
    </p>
    <p>
      <font color="#0000c0"># less /usr/local/etc/dhcpd.conf.sample</font><font color="#008000">&nbsp;</font>// можно посмотреть образец конфига
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"><b>2. # vi /usr/local/etc/dhcpd.conf</b></font>
    </p>
    <p>
      <font color="#008000"># Определение глобальных настроек </font>
    </p>
    <p>
      <font color="#008000">ddns-update-style none; </font>
    </p>
    <p>
      <font color="#008000">option domain-name &quot;a.com&quot;; </font>
    </p>
    <p>
      <font color="#008000">option domain-name-servers 10.10.14.1; </font>
    </p>
    <p>
      <font color="#008000">default-lease-time 604800; </font>
    </p>
    <p>
      <font color="#008000">max-lease-time 864001; </font>
    </p>
    <p>
      <font color="#008000"># </font>
    </p>
    <p>
      <font color="#008000"># Здесь указана подсеть адресов для выдачи клиентам, DNS сервера, NETBIOS сервера </font>
    </p>
    <p>
      <font color="#008000"># доменное имя, широковещательный адрес, и диапазон выдаваемых адресов. </font>
    </p>
    <p>
      <font color="#008000">subnet 10.10.14.0 netmask 255.255.255.0 { </font>
    </p>
    <p>
      <font color="#008000">#option netbios-name-servers 10.10.14.1; </font>
    </p>
    <p>
      <font color="#008000">option broadcast-address 10.10.14.255; </font>
    </p>
    <p>
      <font color="#008000">option routers 10.10.14.1; </font>
    </p>
    <p>
      <font color="#008000">range 10.10.14.5 10.10.14.10; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># укажем пустую декларацию для сети </font>
    </p>
    <p>
      <font color="#008000">subnet 192.168.1.0 netmask 255.255.255.0 { </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"><b>3. # /usr/local/etc/rc.d/isc-dhcpd start</b></font>&nbsp;// запуск DHCP-сервера
    </p>
    <p>
      <font color="#0000c0"><b>4. # pgrep -l dhcpd</b></font>&nbsp;// проверка запуска
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Пример для IP-телефонии" ID="ID_1220315205" CREATED="1538392146379" MODIFIED="1726933857191"><richcontent TYPE="NOTE">
