<node TEXT="3. Проверка" ID="ID_1653342141" CREATED="1519112079897" MODIFIED="1648440568854"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Проверка </b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">named-checkconf named.conf.local</font>&nbsp;&nbsp;# Проверить конф. файл на наличие ошибок
    </p>
    <p>
      <font color="#0000c0">named-checkconf</font>&nbsp;&nbsp;#&nbsp;<font color="#ff0000">FreeBSD</font>. Проверить named.conf на наличие ошибок
    </p>
    <p>
      <font color="#0000c0">named-checkconf -z</font>&nbsp;&nbsp;# Проверка на выполение операций которые bind проделает при старте (при загрузке зоны). Проверка не только основного конф. файла, но и файлов зон.
    </p>
    <p>
      &nbsp;&nbsp; <i><b>zone d4.class.us/IN: loading from master file /etc/bind/d4.class.us.zone failed: file not found</b></i><b>&nbsp;</b>// т.е нужно создать файл описания зоны <b>/etc/bind/d4.class.us.zone </b>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="5. Пуск, управление" ID="ID_1318312460" CREATED="1519112079898" MODIFIED="1648439738093"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_739657727">rndc</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Проверка </b>
    </p>
    <p>
      <font color="#0000c0"># named-checkconf -z&nbsp;</font>// Проверка на выполение операций которые bind проделает при старте (при загрузке зоны)
    </p>
    <p>
      <font color="#0000c0"># rndc reconfig</font>&nbsp;// перечитать конф. файлы <b>только новых зон, </b>дать bind указания прочитать зону и конфигурационные файлы
    </p>
    <p>
      <font color="#0000c0"># rndc reload &lt;d4.class.us&gt;</font>&nbsp;// когда зон много, то перегружать целесообразно только конкретную, но можно и все (<font color="#0000c0"># rndc reload</font>)
    </p>
    <p>
      <font color="#0000c0"># host c1</font>&nbsp;// проверяем как все прошло. &nbsp;<b>Если не сработало</b>, пробуем <font color="#0000c0"># rndc reload </font>
    </p>
    <p>
      <font color="#0000c0"># host -la d4.class.us | less</font>&nbsp;// просмотр созданной зоны
    </p>
    <p>
      
    </p>
    <p>
      <b>Пуск. Проверка. <font color="#ff0000">FreeBSD</font></b>
    </p>
    <p>
      <font color="#0000c0"># /etc/rc.d/named start </font>
    </p>
    <p>
      <font color="#0000c0"># host c14</font>&nbsp;// проверка прямой зоны
    </p>
    <p>
      <font color="#0000c0"># host 192.168.1.114</font>&nbsp;// проверка обратной зоны
    </p>
    <p>
      <font color="#0000c0"># host u14.any.com</font>&nbsp;// проверяем домен
    </p>
    <p>
      <font color="#0000c0"># host a.com</font>&nbsp;// проверяем внутр. домен
    </p>
    <p>
      <font color="#0000c0"># host c15</font>&nbsp;--&gt; <font color="#0000c0"># host &lt;IP slave&gt;</font>&nbsp;--&gt; <font color="#0000c0"># ls /var/hamed/etc/namedb/slave/</font>&nbsp;// проверка slave сервера. если все норм, то должен появиться файл
    </p>
    <p>
      <font color="#0000c0">rndc reload&nbsp;&nbsp;# </font>&nbsp;<b>Перезагрузить</b>&nbsp;измененную конфигурацию Bind сервера
    </p>
    <p>
      <font color="#0000c0">rndc reload webmaster.us</font>&nbsp;&nbsp;# Применить измененную конф. конкретной доменной зоны
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="6. Опции" ID="ID_420476709" CREATED="1519112079898" MODIFIED="1583908059793"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      /etc/bind/<b>named.conf.options</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>directory &quot;/var/cache/bind&quot;;</b></font>&#160;// &#1077;&#1089;&#1083;&#1080; &#1087;&#1091;&#1090;&#1100; &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081;, &#1090;&#1086; &#1086;&#1085; &#1089;&#1095;&#1080;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1101;&#1090;&#1086;&#1075;&#1086; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1091;&#1090;&#1100; &#1072;&#1073;&#1089;&#1086;&#1083;&#1102;&#1090;&#1085;&#1099;&#1081; - &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1073;&#1077;&#1079; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1081;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>listen-on {127.0.0.1; 10.10.4.1; };</b></font>&#160;// &#1076;&#1083;&#1103; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; &#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1089;&#1083;&#1091;&#1096;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100;, &#1090;&#1086; &#1073;&#1091;&#1076;&#1091;&#1090; &#1089;&#1083;&#1091;&#1096;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074;&#1089;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">listen-on-v6 { none; };</font></b>&#160;// &#1086;&#1090;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090; &#1074;&#1089;&#1077;&#1075;&#1086;, &#1090;.&#1077;. &#1085;&#1077; &#1089;&#1083;&#1091;&#1096;&#1072;&#1077;&#1084;
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">forwarders { 192.168.1.254; };</font></b>&#160;// &#1085;&#1072;&#1096; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1077;&#1082;&#1091;&#1088;&#1089;&#1080;&#1074;&#1085;&#1099;&#1084; &#1089; &#1090;&#1086;&#1095;&#1082;&#1080; &#1079;&#1088;&#1077;&#1085;&#1080;&#1103; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1073;&#1091;&#1076;&#1077;&#1090; &#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072; &#1079;&#1072;&#1076;&#1072;&#1085;&#1080;&#1103;. &#1057;&#1090;&#1072;&#1074;&#1080;&#1084; &#1089;&#1102;&#1076;&#1072; DNS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1099; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># named-checkconf</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1085;&#1072; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080;
    </p>
    <p>
      <font color="#0000c0"># service bind9 restart</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082; DNS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Вторичная зона" ID="ID_1951086242" CREATED="1519112079898" MODIFIED="1648439760195"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Создать вторичную зону (тип SLAVE)</b>:
    </p>
    <p>
      1. <font color="#0000c0"># vi /etc/bind/<b>named.conf.local</b></font><b>&nbsp;</b>
    </p>
    <ul>
      <li>
        не нужно затирать то, что есть в файле. MASTER и SLAVE зоны могут сосуществовать параллельно
      </li>
      <li>
        сервер<font color="#ff0000">&nbsp;не может одновремено быть</font>&nbsp;&nbsp;и MASTER и SLAVE для конкретной зоны
      </li>
    </ul>
    <p>
      <font color="#008000">zone &quot;d6.class.us&quot; { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;type slave; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;masters { 192.168.1.106; }; </font>// указываем источники инф. откуда будет браться информация. Их может быть несколько
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <font color="#008000">file &quot;d6.class.us.zone&quot;;</font>&nbsp;&nbsp;// после каждого обновления зоны записывать к себе в файл, который будет считываться при старте сервера, а потом будет считывать с MASTERa. Очень рекомендуется для быстрого поднятия сервера. Путь берется из директивы файла /etc/bind/named.conf.option (options {
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;directory &quot;<b>/var/cache/bind</b>&quot;;)
    </p>
    <p>
      <font color="#008000">};</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">2. # named-checkconf</font>&nbsp;// Проверка
    </p>
    <p>
      <font color="#0000c0">3. rndc reconfig</font>&nbsp;&nbsp;# Переконфигурация
    </p>
    <p>
      <font color="#0000c0">4. # host c6.d6.class.us </font>
    </p>
    <p>
      <font color="#0000c0">5. # ls /var/cache/bind/ </font>// Смотрим что появилось в каталоге. Должен появиться файл d6.class.us.zone
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#ff0000"><b>FreeBSD</b></font><b>. Создать вторичную зону (тип SLAVE):</b>
    </p>
    <p>
      <font color="#008000"># внутренний домен - соседская зона (slave сервер). <b>Файл создвать не нужно</b>, будет создан автоматически при подключении</font>
    </p>
    <p>
      <font color="#008000">zone &quot;u15.any.com&quot; { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;type slave; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;file &quot;slave/db.u15.any.com&quot;; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;masters { 192.168.1.115; }; </font>
    </p>
    <p>
      <font color="#008000">}; </font>
    </p>
    <p>
      
    </p>
    <p>
      ------------------------------------------
    </p>
    <p>
      <b>SLAVE</b>
    </p>
    <p>
      directory &quot;/any/path&quot;{
    </p>
    <p>
      &nbsp;&nbsp;sistem-on{
    </p>
    <p>
      &nbsp;&nbsp;&lt;IP-адрес&gt;<br/>
    </p>
    <p>
      &nbsp;&nbsp;}
    </p>
    <p>
      }
    </p>
    <p>
      
    </p>
    <p>
      конфиг зоны
    </p>
    <p>
      <font color="#008000">zone &quot;d0.ru&quot; { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;type slave; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;file &quot;d0.ru&quot; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;masters {IP-адрес MASTER'a;}; </font>
    </p>
    <p>
      <font color="#008000">};</font>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Зона обратного преобразования" ID="ID_1961422650" CREATED="1519112079898" MODIFIED="1648439771826"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1.168.192.in-addr.arpa - название зоны</b>
    </p>
    <p>
      <font color="#0000c0"><b>1. vi /etc/bind/named.conf.local</b></font>
    </p>
    <p>
      <font color="#008000">zone &quot;1.168.192.in-addr.arpa&quot; { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;type master; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;file &quot;/etc/bind/1.168.192.in-addr.arpa.zone&quot;; </font>
    </p>
    <p>
      <font color="#008000">}; </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>2.&nbsp;Создать файл</b>&nbsp;/etc/bind/<b>1.168.192.in-addr.arpa.zone</b>&nbsp;&nbsp;// можно скопировать /etc/bind/d4.class.us.zone с переименованием
    </p>
    <ul>
      <li>
        MX запись никогда не прописывается - не имеет смысла
      </li>
    </ul>
    <p>
      <font color="#008000">$TTL&nbsp;&nbsp;&nbsp;&nbsp;30 </font>
    </p>
    <p>
      <font color="#008000">$ORIGIN 1.168.192.in-addr.arpa. </font>
    </p>
    <p>
      <font color="#008000">@&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;SOA&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c4.d4.class.us. root.d4.class.us.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;(&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2017061701&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1h&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;10m&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1d&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;30&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;NS&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c4.d4.class.us.</font>&nbsp;&nbsp;&nbsp;//&nbsp;&nbsp;( ) изпользуются для разбиения логической строчки на несколько физических кусков
    </p>
    <p>
      <font color="#008000">110&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c0.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">111&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c1.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">112&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c2.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">113&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c3.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">114&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c4.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">115&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c5.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">116&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c6.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">117&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c7.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">118&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c8.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">119&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c9.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">120&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c10.d4.class.us. </font>
    </p>
    <p>
      <font color="#008000">121&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c11.d4.class.us.</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>3. <font color="#0000c0"># named-checkconf -z</font>&nbsp;// Проверка </b>
    </p>
    <p>
      <b>4. <font color="#0000c0">rndc reconfig</font>&nbsp;</b>
    </p>
    <p>
      <b>5. <font color="#0000c0"># host 192.168.1.111</font></b>&nbsp;// &nbsp;// проверяем как все прошло. &nbsp;<b>Если не сработало</b>, пробуем <font color="#0000c0"># rndc reload </font>
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#ff0000">FreeBSD</font></b>
    </p>
    <p>
      <font color="#0000c0"><b>1.1 vi /var/named/etc/namedb/named.conf</b></font>
    </p>
    <p>
      <font color="#008000"># зона обратного преобразования 1.168.192.in-addr.arpa - название зоны </font>
    </p>
    <p>
      <font color="#008000">zone &quot;1.168.192.IN-ADDR.ARPA&quot; { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;type master; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;file &quot;master/db.db.1.168.192&quot;; </font>
    </p>
    <p>
      <font color="#008000">}; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>1.2 # зона обратного преобразования для внутренней сети</b>&nbsp;</font>
    </p>
    <p>
      <font color="#008000">zone &quot;14.10.10.IN-ADDR.ARPA&quot; { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;type master; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;file &quot;master/db.14.10.10&quot;; </font>
    </p>
    <p>
      <font color="#008000">}; </font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>2.1&nbsp;Создать файл</b>&nbsp;/var/named/etc/namedb/master/<b>db.1.168.192</b>
    </p>
    <p>
      <font color="#008000">$ORIGIN . </font>
    </p>
    <p>
      <font color="#008000">$TTL&nbsp;&nbsp;&nbsp;&nbsp;60&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; 1 minute </font>
    </p>
    <p>
      <font color="#008000">1.168.192.IN-ADDR.ARPA&nbsp;&nbsp;IN SOA&nbsp;&nbsp;c14.u14.any.com.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;root.1.168.192.in-addr.arpa. ( </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2017080801&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; serial </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;64800&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; refresh (18 hours) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1200&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; retry (20 minutes) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1209600&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; expire (2 weeks) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;10&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; minimum (10 sec) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;NS&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c14.u14.any.com. </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;MX&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1 c14.u14.any.com. </font>
    </p>
    <p>
      <font color="#008000">$ORIGIN 1.168.192.IN-ADDR.ARPA. </font>
    </p>
    <p>
      <font color="#008000">110&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c10.u10.any.com. </font>
    </p>
    <p>
      <font color="#008000">111&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c11.u11.any.com. </font>
    </p>
    <p>
      <font color="#008000">112&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c12.u12.any.com. </font>
    </p>
    <p>
      <font color="#008000">113&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c13.u13.any.com. </font>
    </p>
    <p>
      <font color="#008000">114&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c14.u14.any.com. </font>
    </p>
    <p>
      <font color="#008000">115&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c15.u15.any.com. </font>
    </p>
    <p>
      <font color="#008000">2&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;winxp.u15.any.com.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>2.2&nbsp;Создать файл</b>&nbsp;/var/named/etc/namedb/master/<b>db.14.10.10 (для внутренней сети) </b>
    </p>
    <p>
      <font color="#008000">$ORIGIN . </font>
    </p>
    <p>
      <font color="#008000">$TTL&nbsp;&nbsp;&nbsp;&nbsp;60&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; 1 minute </font>
    </p>
    <p>
      <font color="#008000">14.10.10.IN-ADDR.ARPA&nbsp;&nbsp;&nbsp;IN SOA&nbsp;&nbsp;c14.a.com. root.14.10.10.in-addr.arpa. ( </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2017080801&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; serial </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;64800&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; refresh (18 hours) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;190&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; retry (9 minutes) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1209600&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; expire (2 weeks) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;60&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; minimum (1 minute) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;) </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;NS&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c14.a.com. </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;MX&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1 c14.a.com. </font>
    </p>
    <p>
      <font color="#008000">$ORIGIN 14.10.10.IN-ADDR.ARPA. </font>
    </p>
    <p>
      <font color="#008000">1&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;c14.a.com. </font>
    </p>
    <p>
      <font color="#008000">2&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;winxp.a.com.</font>
    </p>
  </body>
</html></richcontent>
