<node TEXT="Конф.файл" FOLDED="true" ID="ID_1133357365" CREATED="1648039012743" MODIFIED="1777989857969">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        /etc/bind/named.conf, /etc/named.conf, /var/named/named.conf
      </li>
      <li>
        named.conf читается за один проход
      </li>
      <li>
        /etc/bind/named.conf.options - глобальные настройки сервера
      </li>
      <li>
        /etc/bind/named.conf.local - настройки локальных зон DNS
      </li>
    </ul>
    <p>
      <b>Синтаксис</b>:
    </p>
    <ul>
      <li>
        каждая инструкция <b>заканчивается ;</b>
      </li>
      <li>
        <span style="color: #000000;">/* многострочный <b>комментарий</b>&#xa0;*/ </span>
      </li>
      <li>
        <span style="color: #000000;">// Весь текст до конца строки является <b>комментарием</b>&#xa0;</span>
      </li>
      <li>
        <span style="color: #000000;"># Весь текст до конца строки является <b>комментарием</b></span>
      </li>
      <li>
        <b>;</b>&#xa0;<b>комментарий</b>&#xa0;в файлах зон
      </li>
      <li>
        в файлах зон не должно быть пустых строк, комментируем их
      </li>
    </ul>
    <p>
      <b>Инструкции</b>
    </p>
    <ul>
      <li>
        <b><span style="color: #000000;">include</span></b>&#xa0;Подключает внешний файл -- <span style="color: #008000;">include &quot; путь &quot; ;</span>
      </li>
      <li>
        <b>options</b>&#xa0;Задает глобальные параметры конфигурации сервера имен, а также установки по умолчанию
      </li>
      <li>
        <b>acl</b>&#xa0;Формирует списки управления доступом
      </li>
      <li>
        <b>key</b>&#xa0;Определяет параметры аутентификации
      </li>
      <li>
        <b>trusted-keys</b>&#xa0;Задает заранее установленные ключи шифрования
      </li>
      <li>
        <b>server</b>&#xa0;Задает параметры сервера
      </li>
      <li>
        <b>masters</b>&#xa0;Определяет список главных серверов для тупиковых и подчиненных зон
      </li>
      <li>
        <b>logging</b>&#xa0;Устанавливает категории журнальных сообщений и каналы их распространения
      </li>
      <li>
        <b>statistics-channels</b>&#xa0;Выводит текущую статистику в виде ХМL-файла. Просмотр через браузер
      </li>
      <li>
        <b>zone</b>&#xa0;Определяет зону записей о ресурсах
      </li>
      <li>
        <b>controls</b>&#xa0;Определяет, как утилита rndc будет управлять сервером имен named
      </li>
      <li>
        <b>view</b>&#xa0;Определяет представление данных зоны
      </li>
      <li>
        <b>lwres</b>&#xa0;Конфигурирует сервер имен named в качестве упрощенного распознавателя
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">named-checkconf </span>&#xa0;# <b>Проверить</b>&#xa0;конф. файлы на ошибки
    </p>
    <p>
      <span style="color: #0000c0;">systemctl reload bind9</span>&#xa0;&#xa0;# <b>Перечитать</b>&#xa0;конф. файлы и зоны
    </p>
    <p>
      <span style="color: #0000c0;">rndc reload</span>&#xa0;&#xa0;#&#xa0;<b>Перечитать</b>&#xa0;зоны
    </p>
    <p>
      <span style="color: #0000c0;">rndc reload example.com</span>&#xa0;&#xa0;#&#xa0;<b>Перечитать</b>&#xa0;конкретную зону
    </p>
    <p>
      <span style="color: #0000c0;">systemctl restart bind9</span>&#xa0;&#xa0;# <b>Перезапустить</b>&#xa0;службу
    </p>
  </body>
</html></richcontent>
<node TEXT="case1" ID="ID_916412264" CREATED="1726838226102" MODIFIED="1726990662797"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">cat /etc/bind/<b>named.conf.options</b></font>
    </p>
    <p>
      <font color="#008000" face="SansSerif">options { </font>
    </p>
    <p>
      <font color="#008000" face="SansSerif">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;directory &quot;/var/cache/bind&quot;;</font><font face="SansSerif">&nbsp;&nbsp;&nbsp;# Каталоги для кэша и вр. файлов </font>
    </p>
    <p>
      <font color="#008000" face="SansSerif">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;forwarders {&nbsp; </font><font face="SansSerif"># &nbsp;IP-адреса DNS-серверов, к которым будут направляться DNS-запросы, которые локальный сервер не смог разрешить самостоятельно </font>
    </p>
    <p>
      <font color="#008000" face="SansSerif">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;8.8.8.8; </font>
    </p>
    <p>
      <font color="#008000" face="SansSerif">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;8.8.4.4; </font>
    </p>
    <p>
      <font color="#008000" face="SansSerif">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;}; </font>
    </p>
    <p>
      <font color="#008000" face="SansSerif">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;allow-query { any; };&nbsp;&nbsp;#</font><font color="#000000" face="SansSerif">&nbsp;Для разрешения запросов от любых IP-адресов (не только локальных) <b>или</b>&nbsp; </font>
    </p>
    <p>
      <font color="#000000" face="SansSerif">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </font><font color="#008000" face="SansSerif">&nbsp;allow-recursion { any; };</font><font color="#000000" face="SansSerif">&nbsp;&nbsp;# Что позволит выполнять рекурсивные запросы для всех сетей</font>
    </p>
    <p>
      <font color="#008000" face="SansSerif">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;dnssec-validation auto; </font><font face="SansSerif">&nbsp;&nbsp;# Будет ли BIND автоматически проверять подпись <a href="#ID_1780208751">DNSSEC</a>&nbsp;для полученных записей. auto - BIND будет использовать DNSSEC-подписи, если они есть</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">cat /etc/bind/<b>named.conf.local</b></font>
    </p>
    <p>
      <font color="#008000">zone &quot;my-practicum&quot; {&nbsp; </font># Зона с именем
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;type master;&nbsp; </font># master - авторитетный сервер
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;file &quot;/etc/bind/<b>db.my-practicum</b>&quot;; </font>
    </p>
    <p>
      <font color="#008000">}; </font>
    </p>
    <p>
      <font color="#008000">zone &quot;0.168.192.in-addr.arpa&quot; {&nbsp; </font># Зона обратного поиска для IP-адресов подсети 192.168.0.0/24
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;type master; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;file &quot;/etc/bind/<b>db.192</b>&quot;; </font>
    </p>
    <p>
      <font color="#008000">}; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">cat /etc/bind/<b>db.my-practicum</b></font>
    </p>
    <p>
      <font face="Monospaced">$TTL&nbsp;&nbsp;&nbsp;&nbsp;604800 </font>
    </p>
    <p>
      <font face="Monospaced">@&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;IN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;SOA&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;my-practicum. root.my-practicum. ( </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; Serial </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;604800&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; Refresh </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;86400&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; Retry </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2419200&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; Expire </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;604800 )&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; Negative Cache TTL </font>
    </p>
    <p>
      <font face="Monospaced">; </font>
    </p>
    <p>
      <font face="Monospaced">@&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;IN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;NS&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;my-practicum. </font>
    </p>
    <p>
      <font face="Monospaced">@&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;IN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;A&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;10.10.1.105 </font>
    </p>
    <p>
      <font face="Monospaced">@&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;IN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;AAAA&nbsp;&nbsp;&nbsp;&nbsp;::1 </font>
    </p>
    <p>
      <font face="Monospaced">ns&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;IN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;A&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;10.10.1.105 </font>
    </p>
    <p>
      <font face="Monospaced">client1&nbsp;&nbsp;&nbsp;IN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;A&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;192.168.0.106</font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">cat /etc/bind/<b>db.192</b></font>
    </p>
    <p>
      <font face="Monospaced">$TTL&nbsp;&nbsp;&nbsp;&nbsp;604800 </font>
    </p>
    <p>
      <font face="Monospaced">@&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;IN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;SOA&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;my-practicum. root.my-practicum. ( </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; Serial </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;604800&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; Refresh </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;86400&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; Retry </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2419200&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; Expire </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;604800 )&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;; Negative Cache TTL </font>
    </p>
    <p>
      <font face="Monospaced">; </font>
    </p>
    <p>
      <font face="Monospaced">@&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;IN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;NS&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;my-practicum. </font>
    </p>
    <p>
      <font face="Monospaced">106&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;IN&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;PTR&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;client1</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="options" ID="ID_378857292" CREATED="1648040480131" MODIFIED="1648101932832">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>options { </b></font>
    </p>
    <p>
      <font color="#008000"><b>&nbsp;&nbsp;параметр; </b></font>
    </p>
    <p>
      <font color="#008000"><b>&nbsp;&nbsp;параметр; </b></font>
    </p>
    <p>
      <font color="#008000"><b>} ;</b></font>
    </p>
    <p>
      
    </p>
    <p>
      <b>ПАРАМЕТРЫ</b>
    </p>
    <p>
      <b>Местоположение файлов</b>
    </p>
    <p>
      directory &quot;путь&quot; ;&nbsp;&nbsp;[каталог запуска сервера]
    </p>
    <p>
      key-directory &quot;путь&quot; ;&nbsp;&nbsp;[совпадает с параметром directory,&nbsp;&nbsp;определяет место хранения криптографического ключа]
    </p>
    <p>
      <b>Идентификация сервера имен.</b>&nbsp;Эти параметры позволяют скрывать истинные значения.
    </p>
    <p>
      version &quot;строка&quot; [реальный номер версии сервера]
    </p>
    <p>
      hostname &quot;строка&quot; [реальное имя сервера]
    </p>
    <p>
      server-id &quot;строка&quot; [реальный номер версии сервера]
    </p>
    <p>
      <b>Синхронизация зон</b>
    </p>
    <p>
      notify yes | master-only | explicit | no; [yes]&nbsp;&nbsp;# только к главным серверам
    </p>
    <p>
      also-notify id_адреса_серверов; [пусто]&nbsp;&nbsp;# только к главным серверам
    </p>
    <p>
      allow-notify список_соответствующих_адресов; [пусто]&nbsp;&nbsp;# только к подчиненным серверам
    </p>
    <p>
      <b>Рекурсия запросов</b>
    </p>
    <p>
      recursion yes | no; [yes]
    </p>
    <p>
      allow-recursion {список_ соответствия_ адресов}; [все хосты]
    </p>
    <p>
      <b>Использование кеширующей памяти</b>
    </p>
    <p>
      recursive- clients число; [1000]
    </p>
    <p>
      max-cache-size число; [неограничено]
    </p>
    <p>
      <b>Использование IP-nopтa</b>
    </p>
    <p>
      use-v4-udp-ports [range начало конец]; [range 1024 65535]
    </p>
    <p>
      use-vб-udp-ports [range начало конец ]; [range 1024 65535]
    </p>
    <p>
      avoid-v4-udp-ports [список_ портов]; [пусто]
    </p>
    <p>
      avoid-v6-udp-ports [список_ портов]; [пусто]
    </p>
    <p>
      query-source-v4 v4-адрес [порт]; [любой] #ВНИМАНИЕ, не используйте порт
    </p>
    <p>
      query-source-v6 v6-адрес [порт]; [любой] #ВНИМАНИЕ, не используйте порт
    </p>
    <p>
      <b>Использование переадресации</b>
    </p>
    <p>
      forwarders {iр_ адрес; iр_ адрес; ...);&nbsp;&nbsp;[nустой список]
    </p>
    <p>
      forward only | first;&nbsp;&nbsp;[first]
    </p>
    <p>
      <b>Разрешения</b>
    </p>
    <p>
      allow-query {список_соответствия_адресов}; [ все хосты]
    </p>
    <p>
      allow-query-cache {список_соответствия_адресов}; [все хосты]
    </p>
    <p>
      allow-transfer {список_соответствия_адресов}; [все хосты]
    </p>
    <p>
      allow-update {список_соответствия_адресов}; [нет]
    </p>
    <p>
      Ыackhole { список_соответствия_адресов}; [нет]
    </p>
    <p>
      <b>Размеры пакетов</b>
    </p>
    <p>
      edns-udp-size номер; [4096]
    </p>
    <p>
      max-udp-size номер; [4096]
    </p>
    <p>
      <b>Управление спецификациями DNSSEC</b>
    </p>
    <p>
      dnssec-enaЫe yes | no; [yes]
    </p>
    <p>
      dns sec-validation yes | no; [yes]
    </p>
    <p>
      dnssec-must-be-secure домен yes | no; [нет]
    </p>
    <p>
      <b>Статистика</b>
    </p>
    <p>
      zone-statistics yes | no&nbsp;&nbsp;[no]
    </p>
    <p>
      <b>Настройка производительности</b>
    </p>
    <p>
      clieпts-per-query целое_число; [10]&nbsp;&nbsp;# Количество клиентов, ожидающих один и тот же запрос
    </p>
    <p>
      max-clients-per-query целое_число; [100]&nbsp;&nbsp;# Максимально допустимое количество клиентов до отказа сервера
    </p>
    <p>
      datasize целое_число; [неограничено]&nbsp;&nbsp;# Максимальное количество памяти, которое может использовать сервер
    </p>
    <p>
      files целое_число; [неограничено]&nbsp;&nbsp;# Максимальное количество одновременно открытых файлов
    </p>
    <p>
      lame-ttl целое_число; [10min]&nbsp;&nbsp;# Период времени до кеширования сбойного сервера
    </p>
    <p>
      max-acache-size целое_число; [ ]&nbsp;&nbsp;# Размер кеша для дополнительных данных
    </p>
    <p>
      max-cache-size целое_число; [ ]&nbsp;&nbsp;# Максимальный размер памяти для кешированных ответов
    </p>
    <p>
      max-cache-ttl целое_число; [1week]&nbsp;&nbsp;# Максимальный период TTL для кеширования позитивных данных
    </p>
    <p>
      max-journal-size целое_число; [ ]&nbsp;&nbsp;# Максимальный размер файла для журнала транзакций
    </p>
    <p>
      max-ncache-ttl целое_число; [3hrs]&nbsp;&nbsp;# Максимальный период TTL для кеширования негативных данных
    </p>
    <p>
      tcp-clieпts целое_число; [100]&nbsp;&nbsp;# Максимально допустимое количество ТСР-клиентов
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="acl" ID="ID_1952157471" CREATED="1648099679493" MODIFIED="1726838913000">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>acl имя_списка { </b></font>
    </p>
    <p>
      <font color="#008000"><b>&nbsp;&nbsp;список_соответствия_адресов </b></font>
    </p>
    <p>
      <font color="#008000"><b>};</b></font>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        Инструкция acl должна быть <b>самой первой</b>&nbsp;в файле named.conf
      </li>
      <li>
        Cтандартные списки соответствий:

        <ul>
          <li>
            any - всем хостам
          </li>
          <li>
            localnets - всем хостам локальной сети. Сети определяются адресами интерфейсов компьютера с учетом сетевых масок
          </li>
          <li>
            localhost - самому компьютеру
          </li>
          <li>
            none - ни одному хосту.
          </li>
        </ul>
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="key (TSIG)" ID="ID_807502166" CREATED="1648101936033" MODIFIED="1726838912665">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><span style="color: #008000;">key идентификатор_ключа { </span></b>
    </p>
    <p>
      <b><span style="color: #008000;">&#xa0;&#xa0;algorithm строка; </span></b>
    </p>
    <p>
      <b><span style="color: #008000;">&#xa0;&#xa0;secret строка; </span></b>
    </p>
    <p>
      <b><span style="color: #008000;">};</span></b>
    </p>
    <ul>
      <li>
        определяет именованный ключ шифрования (т.е. пароль), используемый для аутентификации соединения между двумя серверами, например между главным и подчиненным серверами при передаче зоны или между сервером и процессом rndc, который им управляет
      </li>
      <li>
        идентификатор ключа должен быть определен до того, как встретится ссылка на ключ
      </li>
      <li>
        Чтобы связать ключ с конкретным сервером, включите идентификатор ключа в список keys соответствующей инструкции <b>server</b>
      </li>
      <li>
        Секретная информация не должна храниться в файле, доступном для внешнего мира. Для включения его в файл named.conf следует использовать инструкцию <b>include</b>
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="server" ID="ID_201958704" CREATED="1648102566719" MODIFIED="1726838912489">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><font color="#008000">server iр-адрес { </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;bogus yes | no; [нет]</font></b>&nbsp;&nbsp;&nbsp;# Если да, демон named не посылает ему запросы
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;provide-ixfr: yes | no; [да]&nbsp;&nbsp;# Если да, </font></b>Сервер имен BIND, являющийся главным сервером динамически обновляемой зоны, выполняет инкрементные передачи зон
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;request-ixfr yes | no; [да]</font>&nbsp;&nbsp;# </b>Подчиненный сервер запрашивает инкрементные передачи зон от главного сервера
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;keys {идентификатор_ ключа; идентификатор ключа; ...}; [нет]</font></b>&nbsp;&nbsp;&nbsp;# Задаются идентификаторы ключей, которые ранее были определены в инструкции key для использования в сигнатурах транзакций TSIG
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;transfer-source iр-адрес [порт]; [ближайший интерфейс]</font></b>&nbsp;&nbsp;&nbsp;# Атрибуты необходим ы только тогда, когда система имеет несколько интерфейсов и IР-адрес удаленного сервера указан в списке allow­transfer
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;transfer-source-v6 iрv6-адрес [порт]; [ближайший интерфейс] </font></b>
    </p>
    <p>
      <b><font color="#008000">};</font></b>
    </p>
    <ul>
      <li>
        named способен общаться с серверами, которые не используют последнюю версию пакета BIND или просто неправильно сконфигурированы. Инструкция server сообщает демону характеристики удаленных серверов
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="masters" ID="ID_300944883" CREATED="1648103741103" MODIFIED="1726838912312">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><font color="#008000">&nbsp;masters имя [iр-адрес [port iр-порт] [key ключ]; ...]</font></b>
    </p>
    <ul>
      <li>
        Затем это имя можно использовать в разделе masters и нструкций zone вместо повторения IР-адресов и ключей
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="statistics-channels" ID="ID_1372475285" CREATED="1648105284792" MODIFIED="1726838912134">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><font color="#008000">statistics-channels { </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;inet(ip-адрес | *) port порт# allow {список_соответствия_адресов}; </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;... </font></b>
    </p>
    <p>
      <b><font color="#008000">}</font></b>
    </p>
    <ul>
      <li>
        для ограничения IP-адресов с которых возможен просмотр
      </li>
      <li>
        <b>По умолчанию</b>&nbsp;IР-адреса заданы значением <b>any</b>, а порт - значением <b>80</b>
      </li>
      <li>
        Для использования каналов сбора статистики демон named следует компилировать с поддержкой библиотеки <b>libxml2</b>
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="zone" FOLDED="true" ID="ID_314738231" CREATED="1648105692730" MODIFIED="1726838911969">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        Сообщает демону named о зонах, для которых он <b>авторитетен</b>, и задает параметры управления каждой зоной
      </li>
      <li>
        <b>типы зон:</b>

        <ul>
          <li>
            master
          </li>
          <li>
            slave
          </li>
          <li>
            hint - подсказки - имена и адреса корневых серверов (серверы корневого домена (&quot;.&quot;)), участвующих в инициализации DNS-поиска
          </li>
          <li>
            forward
          </li>
          <li>
            stub - используется только в системе BIND
          </li>
          <li>
            delegation-only - применяется для прекращения использования записей с шаблонными символами в зонах верхнего уровня при извещении служб регистратора
          </li>
        </ul>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="Главный сервер зоны" ID="ID_41977652" CREATED="1648107087538" MODIFIED="1726838212416">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Конфигурирование главного сервера зоны </b>
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">zone &quot;имя_домена&quot; { </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;type master; </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;file &quot;путь &quot;;&nbsp; </font></b># На диске в текстовом файле, доступном для редактирования
    </p>
    <p>
      <b><font color="#008000">};</font></b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">allow-query {список_ соответствия_адресов}; [все хосты] </font>
    </p>
    <p>
      <font color="#008000">allow-transfer {список_соответствия_ адресов}; [все хосты]</font>
    </p>
    <p>
      <font color="#008000">allow-update {список_ соответствия_ адресов}; [ни один]</font>&nbsp;&nbsp;# Только для главных зон. Если для зоны поддерживаются динамические обновления, должен содержаться список хостов, от которых разрешено принимать данные
    </p>
    <p>
      <font color="#008000">zone-statistics yes | no; [нет]</font>&nbsp;&nbsp;# Отслеживать статистику запросов-ответов, например точное число и общий процент отсылок, рекурсивных и ошибочных запросов.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Подчиненный сервер зоны" ID="ID_1034403066" CREATED="1648107138738" MODIFIED="1648110694362">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Конфигурирование подчиненного сервера зоны </b>
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">zone &quot;имя_домена&quot; { </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;type slave; </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;file &quot;путь&quot;;</font></b>&nbsp;&nbsp;# Путь до реплицированной базы данных
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;masters {iр_адрес [port iр_порт] [key имя_ключа]; ... };&nbsp; </font></b># Отсюда можно загружать БД зоны
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;allow-query { список_ соответствия_адресов); [все хосты] </font></b>
    </p>
    <p>
      <b><font color="#008000">}; </font></b>
    </p>
    <ul>
      <li>
        Подчиненные серверы обычно хранят полную копию базы данных зоны
      </li>
      <li>
        файл реплицированной базы данных <b>не редактируется</b>&nbsp;- управляется демоном named
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="&quot;подсказки&quot; корневых серверов" ID="ID_351719740" CREATED="1648110089908" MODIFIED="1648110716322">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><font color="#008000">zone &quot;.&quot; { </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;type hint; </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;file &quot;путь&quot;; </font></b>
    </p>
    <p>
      <b><font color="#008000">};</font></b>
    </p>
    <ul>
      <li>
        Подсказки &quot; - это набор DN S-записей, в которых перечислены серверы корневого домена ( &quot; . &quot; ) . Они нужны для того, чтобы демон named знал, откуда начинать поиск доменов. Не имея &quot; подсказок&quot;, демон знал бы только о тех доменах, которые сам обслуживает, а также об их поддоменах
      </li>
      <li>
        Файл &quot; подсказок&quot; чаще всего называется <b>root.cache&nbsp;(named.ca)</b>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">dig @f.root-servers.net . ns &gt; root.cache</font>&nbsp;&nbsp;# Сгенерировать файл подсказок
    </p>
    <p>
      <font color="#0000c0">dig . ns &gt; root.cache</font>&nbsp;&nbsp;# Получить список корневых серверов от кеша локального сервера имен
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="задание зоны переадресации" ID="ID_345026549" CREATED="1648110717472" MODIFIED="1648110854436">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Зона типа forward переопределяет глобальные параметры переадресаци и демона named (с начала опрашиваем корневой сервер, а потом следуем по цепочке отсылок) для конкретного домена
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">zone &quot;имя_домена &quot; { </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;type forward </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;forward only | first; </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;forwarders { iр_адрес; iр_адрес; ...} </font></b>
    </p>
    <p>
      <b><font color="#008000">};</font></b>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        Создавать такую зону имеет смысл , если у организации имеется деловой партнер и нужно направлять трафик непосредственно его серверам имен в обход стандартного пути распространения запросов.
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="controls (для rndc)" ID="ID_1981535968" CREATED="1648110866496" MODIFIED="1726838911755">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><font color="#008000">controls { </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;inet iр_адрес port порт allow { список_ соответствия_ адресов } &nbsp;&nbsp;keys {список_ключей}; </font></b>
    </p>
    <p>
      <b><font color="#008000">}</font></b>
    </p>
    <ul>
      <li>
        может запускать и останавливать демон, выводить отчет о его состоянии, переводить демон в режим отладки
      </li>
      <li>
        <b>port</b>&nbsp;по умолчанию <b>953</b>
      </li>
      <li>
        команда rndc не сможет управлять работой демона named <b>без ключа</b>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">rndc-confgen</font>&nbsp;- позволяет сгенерировать ключ аутентификации
    </p>
    <p>
      <b>Первый способ</b>&nbsp;- заставить обе стороны загрузить ключ из общего конфигурационного файла (/etc/rndc.key) или поместить ключ в два разных файла (/etc/rndc.conf для rndc и /etc/named.conf для named).
    </p>
    <p>
      <b>Второй способ</b>&nbsp;&nbsp;если демон named и команда rndc запускаются на разных компьютерах.
    </p>
    <p>
      <font color="#0000c0">rndc-confgen -а</font>&nbsp;&nbsp;&nbsp;# задает ключи для доступа к локальному хосту
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="view" ID="ID_1988640366" CREATED="1648437972584" MODIFIED="1648439062026">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><font color="#008000">view имя_представления { </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;match-clients {список_соответствия_адресов};&nbsp;&nbsp;[все хосты] </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;match-destinations {список_соответствия_адресов};&nbsp;&nbsp;[все хосты] </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;match-recursive-only yes | no;&nbsp;&nbsp;[нет] </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;параметр_представления; </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;инструкция_zопе; ...&nbsp; </font></b>
    </p>
    <p>
      <b><font color="#008000">}</font></b>
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Средства защиты сервера BIND" ID="ID_879735598" CREATED="1648441489010" MODIFIED="1648442768955">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      
    </p>
    <ul>
      <li>
        <b>Параметр</b>&nbsp;Инструкии&nbsp;&nbsp;# Что определяет
      </li>
      <li>
        <b>acl</b>&nbsp;Разные&nbsp;&nbsp;# Списки управления доступом
      </li>
      <li>
        <b>allow-query</b>&nbsp;options, zone&nbsp;&nbsp;# Кто может посылать запросы зоне или серверу
      </li>
      <li>
        <b>allow-recursion</b>&nbsp;options&nbsp;&nbsp;# Кто может посылать рекурсивные запросы
      </li>
      <li>
        <b>allow-transfer</b>&nbsp;options, zone&nbsp;&nbsp;# Кто может запрашивать передачи зон
      </li>
      <li>
        <b>allow-update</b>&nbsp;zone&nbsp;&nbsp;# Кто может выполнять динамические обновления
      </li>
      <li>
        <b>Ыackhole</b>&nbsp;options&nbsp;&nbsp;# Какие серверы нужно полностью игнорировать
      </li>
      <li>
        <b>bogus</b>&nbsp;server&nbsp;&nbsp;# Какие серверы никогда нельзя опрашивать
      </li>
      <li>
        <b>update-policy</b>&nbsp;zone&nbsp;&nbsp;# Какие обновления разрешены
      </li>
    </ul>
    <p>
      ---------------
    </p>
    <p>
      chroot
    </p>
    <p>
      TSIG и TKEY
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Troubleshooting" ID="ID_1502615358" CREATED="1649227415585" MODIFIED="1649230463747">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">cat /etc/naded.conf</font>&nbsp;&nbsp;# Конфигурация через инструкцию <b>logging</b>. Каналы, ведущие в систему Syslog, подвергаются дополнительной фильтрации в соответствии с правилами, установленными в файле /etc/syslog.conf.
    </p>
    <p>
      rndc querylog&nbsp;&nbsp;# включает и отключает регистрацию запросов
    </p>
    <p>
      
    </p>
    <p>
      управляющая программа
    </p>
    <p>
      <font color="#0000c0">named -d2</font>&nbsp;&nbsp;# Включить отладку. По умолчанию отладочная информация записывается в файл named.run
    </p>
    <p>
      <font color="#0000c0">rndc trace</font>&nbsp;&nbsp;#&nbsp;&nbsp;+1 к уровню отладки
    </p>
    <p>
      <font color="#0000c0">rndc notrace</font>&nbsp;&nbsp;# Отключить отладку
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="NSSwitch (Name Service Switch)" ID="ID_1872763437" CREATED="1649969762147" MODIFIED="1751448731734">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_954260516">SSO</a>&#xa0;&#xa0;<a href="#ID_1630509280"><span style="color: #ff0000;">NSS(???)</span></a>
    </p>
    <p>
      
    </p>
    <p>
      <b>NSSwitch (Name Service Switch)</b>&#xa0;- средство в ОС Unix для конфигурации разрешения имён, например, доменных или имён пользователей.
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">cat /etc/nsswitch.conf</span>&#xa0;&#xa0;# Сначала запросить локальные файлы (files), потом привязаться к службе каталогов с помощью демона sssd (sss)
    </p>
    <p>
      <span style="color: #008000;">passwd: files sss </span>
    </p>
    <p>
      <span style="color: #008000;">group: files sss </span>
    </p>
    <p>
      <span style="color: #008000;">shadow: files sss </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">getent passwd</span>&#xa0;&#xa0;# Проверить конфигурацию
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="systemd-resolved" ID="ID_1582188882" CREATED="1741163089201" MODIFIED="1751449527926"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1209440117">systemd</a>&#xa0; <a href="#ID_297828223">resolvectl</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">cat /etc/systemd/</span><span style="color: #0000c0; font-weight: bold;">resolved.conf</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Основной конфигурационный файл</span>. Здесь можно настроить глобальные параметры, такие как DNS-серверы, доменные суффиксы, DNSSEC
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Resolve] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">DNS=8.8.8.8 8.8.4.4 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Domains=example.com </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">DNSSEC=yes</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Конфигурация сетевых интерфейсов:</span>
    </p>
    <p>
      Файлы конфигурации systemd-networkd (например, <span style="font-weight: bold;">/etc/systemd/network/50-wireless.network</span>) могут содержать настройки DNS для конкретных интерфейсов.
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Network] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">DNS=1.1.1.1 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Domains=example.org</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Файл состояния </span>
    </p>
    <p>
      <span style="color: #0000c0;">cat /run/systemd/resolve/</span><span style="color: #0000c0; font-weight: bold;">stub-resolv.conf</span>
    </p>
    <ul>
      <li>
        Динамически генерируемый файл конфигурации DNS, используемый systemd-resolved для перенаправления DNS-запросов локальных программ во внутренний DNS-заглушку (stub resolver)
      </li>
      <li>
        Обычно он символически ссылается на <span style="font-weight: bold;">/etc/resolv.conf</span>
      </li>
      <li>
        содержит информацию о локальном DNS-резолвере (127.0.0.53) и используется для перенаправления DNS-запросов в systemd-resolved
      </li>
    </ul>
    <p>
      <span style="color: #008000;">nameserver 127.0.0.53 </span>
    </p>
    <ul>
      <li>
        DNS-запросы должны отправляться на локальный адрес 127.0.0.53, где работает systemd-resolved
      </li>
      <li>
        Это не классический DNS-сервер (типа 8.8.8.8), а <span style="font-weight: bold;">заглушка</span>, которая перенаправляет запросы на реальные DNS-серверы, настроенные в системе
      </li>
    </ul>
    <p>
      <span style="color: #008000;">options edns0 trust-ad</span>
    </p>
    <ul>
      <li>
        edns0 - включает поддержку расширений DNS (EDNS), что улучшает совместимость с современными DNS-серверами
      </li>
      <li>
        trust-ad - означает, что система доверяет флагу DNSSEC AD (Authenticated Data) в ответах DNS. Если DNS-сервер поддерживает DNSSEC и подписывает записи, система будет считать их достоверными
      </li>
    </ul>
    <p>
      <span style="color: #008000;">search .</span>
    </p>
    <ul>
      <li>
        Определяет домен для автоматического дополнения имён (например, если ввести ping host, система попробует host.)
      </li>
      <li>
        корневая зона (.) означает <span style="font-weight: bold;">отсутствие автоматического дополнения</span>
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Как это работает</span>
    </p>
    <p>
      1. Программа (например, браузер) делает DNS-запрос
    </p>
    <p>
      2. Запрос идёт на 127.0.0.53 (systemd-resolved)
    </p>
    <p>
      3. systemd-resolved перенаправляет его на реальные DNS-серверы (из настроек NetworkManager, DHCP или прописанные вручную).
    </p>
    <p>
      4. Если включён DNSSEC, система проверяет подписи
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Unbound" FOLDED="true" ID="ID_598726169" CREATED="1726833958072" MODIFIED="1751448731311"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1312726952">BIND</a>&#xa0;&#xa0;<a href="#ID_694292915">Задачи (DNS)</a>&#xa0;&#xa0;<a href="#ID_1956438165">DNS-сервер</a>&#xa0;&#xa0;<a href="#ID_1143233258">DNS</a>&#xa0;&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>Unbound</b>&#xa0;- высокопроизводительный, рекурсивный и кэширующий DNS-сервер. Упрощенная настройка.
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>Запретить systemd-resolved слушать 53 порт</b>
    </p>
    <p>
      <span style="color: #0000c0;">cat /etc/systemd/resolved.conf</span>
    </p>
    <p>
      <span style="color: #008000;">DNSStubListener=no</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemd-resolved.service</span>&#xa0;&#xa0;# Перезапустить службу
    </p>
    <p>
      <span style="color: #0000c0;">ss -tulpn | grep :53</span>&#xa0;&#xa0;# Убедиться, что 53 порт свободен
    </p>
  </body>
</html></richcontent>
<node TEXT="Конф.файл" ID="ID_1712815515" CREATED="1727004226584" MODIFIED="1727005143124"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">cat /etc/unbound/unbound.conf.d/main.conf</font>
    </p>
    <p>
      <font color="#008000">server:</font>&nbsp;&nbsp;# Указывает на начало секции настроек сервера
    </p>
    <p>
      <font color="#008000">port: 53</font>&nbsp;&nbsp;# Порт, на котором сервер Unbound слушает DNS-запросы
    </p>
    <p>
      <font color="#008000">verbosity: 0&nbsp;</font>&nbsp;# Уровень подробности логирования. 0 говорит о том, что оно отключено или минимально
    </p>
    <p>
      <font color="#008000">num-threads: 2</font>&nbsp;&nbsp;# количество потоков, которые будут использоваться для обработки DNS-запросов. Желательно выставлять это значение по количеству ядер, если в сети много клиентов. Если же сеть небольшая, достаточно значения 1.
    </p>
    <p>
      <font color="#008000">outgoing-range: 512</font>&nbsp;&nbsp;# Максимальный порт для исходящих соединений. Если при запросе в кэше не окажется записи, сервер отправит запрос к внешним DNS, используя один из портов этого диапазона
    </p>
    <p>
      <font color="#008000">num-queries-per-thread: 1024</font>&nbsp;&nbsp;# Максимальное количество DNS-запросов, обрабатываемых каждым потоком
    </p>
    <p>
      <font color="#008000">msg-cache-size: 16m</font>&nbsp;&nbsp;# Размер кэша для хранения ответов на DNS-запросы
    </p>
    <p>
      <font color="#008000">rrset-cache-size: 32m</font>&nbsp;&nbsp;# Размер кэша для хранения ресурсных записей DNS
    </p>
    <p>
      <font color="#008000">cache-max-ttl: 0</font>&nbsp;&nbsp;# Время жизни в секундах записей в кэше. использовать TTL, указанное в ответах от авторитетных DNS-серверов
    </p>
    <p>
      <font color="#008000">infra-host-ttl: 60</font>&nbsp;&nbsp;# Время жизни в секундах информации о хосте в кэше
    </p>
    <p>
      <font color="#008000">infra-lame-ttl: 120</font>&nbsp;&nbsp;# Время жизни в секундах информации о неудачных запросах
    </p>
    <p>
      <font color="#008000">interface: 0.0.0.0</font>&nbsp;&nbsp;#&nbsp;&nbsp;Интерфейс, на котором Unbound прослушивает входящие DNS-запросы
    </p>
    <p>
      <font color="#008000">outgoing-interface: 10.10.0.79</font>&nbsp;&nbsp;# 10.12.0.196 устанавливает исходящий интерфейс для отправки запросов
    </p>
    <p>
      <font color="#008000">access-control: 127.0.0.0/8 allow</font>&nbsp;&nbsp;# 10.11.1.46/32 управление доступом к серверу. Формат записи следующий: access-control: &lt;подсеть&gt; &lt;правило&gt;. allow означает, что с определённой подсети разрешены запросы к серверу.
    </p>
    <p>
      <font color="#008000">do-ip4: yes</font>&nbsp;&nbsp;# Включает поддержку IPv4
    </p>
    <p>
      <font color="#008000">do-ip6: no</font>&nbsp;&nbsp;# Отключает поддержку IPv6
    </p>
    <p>
      <font color="#008000">do-udp: ye</font>s&nbsp;&nbsp;# Включает использование UDP для DNS-запросов
    </p>
    <p>
      <font color="#008000">do-tcp: yes</font>&nbsp;&nbsp;# Включает использование TCP для DNS-запросов
    </p>
    <p>
      <font color="#008000">username: unbound</font>&nbsp;&nbsp;# Имя пользователя, от имени которого запустится Unbound
    </p>
    <p>
      <font color="#008000">directory: &quot;/etc/unbound&quot;&nbsp;</font>&nbsp;# Директория, где хранятся файлы конфигурации Unbound
    </p>
    <p>
      <font color="#008000">logfile: &quot;/var/log/unbound.log&quot;</font>&nbsp;&nbsp;# Путь к файлу журнала, в который будут записываться логи
    </p>
    <p>
      <font color="#008000">use-syslog: n</font>o&nbsp;&nbsp;# Отключает отправку логов в системный журнал — syslog
    </p>
    <p>
      <font color="#008000">hide-version: yes</font>&nbsp;&nbsp;# Скрывает версию Unbound из передаваемых заголовков
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Диагностика" ID="ID_889670107" CREATED="1569873049866" MODIFIED="1744451594874"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_533849154">nslookup</a><b>&#xa0;&#xa0;</b><a href="#ID_1085586999">host</a>&#xa0;&#xa0;<a href="#ID_287623591">dig</a>&#xa0;&#xa0;<a href="#ID_1852167368">ping</a>&#xa0; <a href="#ID_297828223">resolvectl</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>Проверка зоны DNS</b>
    </p>
    <p>
      <span style="color: #0000c0;">ssh &lt;support&gt;@ns-сервер</span>&#xa0;&#xa0;# Зайти на DNS-сервер
    </p>
    <p>
      <span style="color: #0000c0;">cat /var/named/master.auto/e/x/example.com</span>&#xa0;&#xa0;# Просмотреть в соотв. зоне DNS (файл) ресурсные записи домена
    </p>
    <ul>
      <li>
        example.com&#xa0;&#xa0;сюда&#xa0;&#xa0;&#xa0;# <span style="color: #ff0000;">руками не дописывать</span>
      </li>
      <li>
        example.com_tmp&#xa0;&#xa0;# если ошибок нет, то в теч. 10-15 минут (обновление каждую 15 минуту) он перезаписывается в основной файл зон&#xa0;
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">named-checkzone example.com /var/named/master.auto/e/x/example.com_tmp</span>&#xa0;&#xa0;# Узнать где ошибка
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">dig</span>&#xa0;&#xa0;# Корневые сервера
    </p>
    <p>
      <span style="color: #0000c0;">dig .ru</span>&#xa0;&#xa0;# DNS-сервера, отвечающие за зону .ru
    </p>
    <p>
      <span style="color: #0000c0;">host -a example.com 8.8.8.8</span>&#xa0;&#xa0;# Запросить все записи у определенного DNS-сервера
    </p>
    <p>
      <span style="color: #0000c0;">nslookup -type=any example.com 8.8.8.8</span>
    </p>
    <p>
      <span style="color: #0000c0;">dig @8.8.8.8 example.com any </span>
    </p>
    <p>
      <span style="color: #0000c0;">resolvectl query example.com --type=NS</span>&#xa0;&#xa0;# Можно просматривать только конкретные записи
    </p>
    <p>
      <span style="color: #0000c0;">whois example.com</span>&#xa0;&#xa0;# Информация о домене
    </p>
    <p>
      <span style="color: #0000c0;">whois IP-адрес</span>&#xa0;&#xa0;# Информация о IP-адресе
    </p>
    <p>
      <span style="color: #0000c0;">ping example.com</span>&#xa0;&#xa0;# Проверить доступность домена и его IP-адреса
    </p>
    <p>
      <span style="color: #0000c0;">traceroute example.com</span>&#xa0;&#xa0;# Отследить маршрут пакетов до указанного домена
    </p>
    <p>
      <span style="color: #0000c0;">curl -v example.com</span>&#xa0;&#xa0;# Статус соединения и запросы
    </p>
    <p>
      <span style="color: #0000c0;">resolvectl dns enp0s3 </span>&#xa0;# Просмотр текущих DNS-серверов для интерфейса enp0s3
    </p>
    <p>
      systemd-resolv-re
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Рекомендации" ID="ID_1494123086" CREATED="1519112079899" MODIFIED="1751448724330"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <b>/etc/hosts.allow&#xa0;--&gt; </b><span style="color: #008000;">ALL : PARANOID : RFC931 20 : deny</span>&#xa0;&#xa0;// <b>отключить</b>&#xa0;&#xa0;(#). Режим позволяет защититься от атак с подменой IP адреса, НО <b>некорректно работают реверсные DNS запросы</b>
      </li>
      <li>
        <b>Slave-сервер</b>&#xa0;должен находиться в другом здании, в другой подсети, в сети другого провайдера
      </li>
      <li>
        <b>PowerDNS</b>&#xa0;- высокопроизводительный DNS-сервер
      </li>
    </ul>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
</node>
<node TEXT="MAC" ID="ID_909233923" CREATED="1519112079901" MODIFIED="1777377159151"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_80931231">MAC</a>&#xa0; <a href="#ID_1665435259">ARP</a>&#xa0; <a href="#ID_441851360">ip</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">tcpdump -ne arp -v</span>&#xa0;&#xa0;# Просмотреть ARP-трафик
    </p>
    <p>
      
    </p>
    <p>
      <b>узнать MAC-адрес оборудования</b>
    </p>
    <p>
      <span style="color: #0000c0;">ifconfig -a | grep HWaddr</span>&#xa0;&#xa0;# Linux
    </p>
    <p>
      <span style="color: #0000c0;">ifconfig eth0 | grep HWaddr | awk '{print $5}</span>&#xa0;&#xa0;# Linux. определить текущий MAC-адрес сет. инт.
    </p>
    <p>
      <span style="color: #0000c0;">ip link show eth0</span>
    </p>
    <p>
      <span style="color: #0000c0;">ifconfig | grep ether</span>&#xa0;&#xa0;# <span style="color: #ff0000;">FreeBSD</span>
    </p>
    <p>
      <span style="color: #0000c0;">ifconfig | grep lladdr</span>&#xa0;&#xa0;# <span style="color: #ff0000;">OpenBSD</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Смена MAC-адреса</b>
    </p>
    <p>
      <span style="color: #0000c0;">ifconfig ethl down </span>
    </p>
    <p>
      <span style="color: #0000c0;">ifconfig eth1 hw ether xx:xx:xx:xx:xx:xx </span>
    </p>
    <p>
      <span style="color: #0000c0;">ifconfig ethl up </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">ip link set eth0 down &amp;&amp; ip link set eth0 up</span>&#xa0;&#xa0;&#xa0;# <span style="font-weight: bold;">Если MAC-адрес отсутствует</span>, попробуйте <span style="font-weight: bold;">перезагрузить интерфейс</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>ARP-таблица</b>
    </p>
    <p>
      <span style="color: #0000c0;">arp -an</span>&#xa0;&#xa0;# Кэш ARP. какие MAC адреса знает наша система, записи живут 30 секунд
    </p>
    <p>
      <span style="color: #0000c0;">arp -s 10.10.10.2 &lt;MAC-адрес&gt;</span>&#xa0;&#xa0;# Добавить узел, и связать IP и MAC - адреса. Так можно отключиться от любого из сети
    </p>
    <p>
      <span style="color: #0000c0;">arp -d&#xa0;&lt;IP-адрес&gt;</span>&#xa0;&#xa0;# Удалить запись из ARP-таблицы
    </p>
    <p>
      <span style="color: #0000c0;">ip neigh flush dev &lt;имя сетевого адаптера&gt;</span>&#xa0;&#xa0;# Очистить ARP-таблицу
    </p>
    <p>
      ------------------
    </p>
    <p>
      <span style="color: #0000c0;">arp</span>&#xa0;&#xa0;# ARP
    </p>
    <p>
      <span style="color: #0000c0;">ip neigh</span>&#xa0;&#xa0;# Показать таблицу ARP, NDP. <span style="color: #ff0000;">show - ??? </span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="VLAN" ID="ID_1237637036" CREATED="1706504013398" MODIFIED="1743778029445"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_107215151">VLAN</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">rpm -q vconfig</span>&#xa0;&#xa0;# Убедиться, что vconfig установлен
    </p>
    <p>
      <span style="color: #0000c0;">cat ifcfg-enp0s10</span>&#xa0;&#xa0;# Конфигурация parent-интерфейса
    </p>
    <p>
      <span style="color: #008000;">ONBOOT=yes </span>
    </p>
    <p>
      <span style="color: #008000;">BOOTPROTO=none </span>
    </p>
    <p>
      <span style="color: #008000;">DEVICE=enp0s10 </span>
    </p>
    <p>
      <span style="color: #008000;">NM_CONTROLLED=no</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">cat ifcfg-enp0s10.2</span>&#xa0;&#xa0;#&#xa0;&#xa0;Конфигурация vlan-интерфейса
    </p>
    <p>
      <span style="color: #008000;">ONBOOT=yes </span>
    </p>
    <p>
      <span style="color: #008000;">VLAN=yes </span>
    </p>
    <p>
      <span style="color: #008000;">BOOTPROTO=static </span>
    </p>
    <p>
      <span style="color: #008000;">TYPE=Ethernet </span>
    </p>
    <p>
      <span style="color: #008000;">DEVICE=enp0s10.2 </span>
    </p>
    <p>
      <span style="color: #008000;">NM_CONTROLLED=no </span>
    </p>
    <p>
      <span style="color: #008000;">IPADDR=172.16.2.1 </span>
    </p>
    <p>
      <span style="color: #008000;">PREFIX=24 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">ip link</span>&#xa0;&#xa0;# Проверка
    </p>
  </body>
</html></richcontent>
</node>
