<node TEXT="PoPToP в Linux" ID="ID_91427051" CREATED="1519112079901" MODIFIED="1519112079901"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      1. <font color="#0000c0"># apt-get install pptpd</font>&#160;&#160;// &#1089;&#1090;&#1072;&#1074;&#1080;&#1084; &#1087;&#1072;&#1082;&#1077;&#1090;
    </p>
    <p>
      2. <font color="#0000c0"># /etc/init.d/pptpd stop&#160;</font>// &#1086;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1076;&#1077;&#1084;&#1086;&#1085;
    </p>
    <p>
      3. <font color="#0000c0"># vi /etc/<b>pptpd.conf</b></font>&#160;// &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075; &#1092;&#1072;&#1081;&#1083;. # &#1087;&#1080;&#1096;&#1077;&#1084; &#1074; &#1082;&#1086;&#1085;&#1094;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      <font color="#008000"><b>localip 172.16.1.1 # &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; </b></font>
    </p>
    <p>
      <font color="#008000"><b>remoteip 172.16.1.2-254 // &#1073;&#1091;&#1076;&#1091;&#1090; &#1086;&#1090;&#1076;&#1072;&#1085;&#1099;</b></font>
    </p>
    <p>
      4.<font color="#0000c0">&#160;# vi /etc/ppp/<b>pptpd-options</b></font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084; <b>&#1086;&#1087;&#1094;&#1080;&#1080; &#1076;&#1083;&#1103; &#1076;&#1077;&#1084;&#1086;&#1085;&#1072; pppd</b>
    </p>
    <p>
      <b><font color="#008000">auth</font></b>&#160;# &#1087;&#1080;&#1096;&#1077;&#1084; &#1085;&#1072;&#1076; &#1089;&#1090;&#1088;&#1086;&#1082;&#1086;&#1081; &quot;# Authentication&quot; - &#1090;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; Windows &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089; &#1090;&#1077;&#1084;&#1080; &#1082;&#1090;&#1086; &#1087;&#1088;&#1077;&#1076;&#1083;&#1086;&#1078;&#1080;&#1090; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;
    </p>
    <p>
      5. <font color="#0000c0"># vi /etc/ppp/chap-secrets</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1091;&#1102; &#1080;&#1085;&#1092;. &#1086; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;&#1093;. chap - Challenge Handshake Authentication Protocol
    </p>
    <p>
      <b><font color="#008000">user3&#160;&#160;&#160;pptpd&#160;&#160;&#160;3&#160;&#160;&#160;&quot;*&quot;</font></b>&#160; // &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; user3 &#1089; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1084; 3 &#1080; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1084; pptpd
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node ID="ID_827942707" CREATED="1519112079901" MODIFIED="1583308801864"><richcontent TYPE="NODE">

<html>
  <head>
    
  </head>
  <body>
    <p>
      poptop &#1074; <font color="#ff0000">FreeBSD</font>
    </p>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>VPN-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;</b>
    </p>
    <p>
      1.1 <font color="#0000c0"># pkg_add -r poptop</font>&#160;// FreeBSD. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;
    </p>
    <p>
      1.2 <font color="#0000c0"># rehash</font>
    </p>
    <p>
      2. <font color="#0000c0"># vi /etc/pf.conf </font>// &#1095;&#1090;&#1086;&#1073;&#1099; &#1095;&#1077;&#1088;&#1077;&#1079; VPN &#1084;&#1086;&#1078;&#1085;&#1086; &#1073;&#1099;&#1083;&#1086; &#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1074; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;
    </p>
    <p>
      <font color="#008000"># &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1084; &#1074;&#1099;&#1093;&#1086;&#1076; &#1080;&#1079; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1081; &#1089;&#1077;&#1090;&#1080; &#1074; &#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090; </font>
    </p>
    <p>
      <font color="#008000"># nat on $ext_if from $int_if:network to any -&gt; ($ext_if) </font>
    </p>
    <p>
      <font color="#008000">nat on $ext_if from <b>10.10.14.0/16</b>&#160;to any -&gt; ($ext_if) </font>
    </p>
    <p>
      <font color="#0000c0">3. # vi /etc/ppp/<b>ppp.conf</b></font>&#160;// &#1086;&#1089;&#1085;. &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;. &#1076;&#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1074; &#1082;&#1086;&#1085;&#1077;&#1094; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;
    </p>
    <p>
      <font color="#008000">pptp: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;set ifaddr 10.10.14.1 10.10.14.100-10.10.14.200 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;enable mschapv2 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;set timeout 0 </font>
    </p>
    <p>
      4. <font color="#0000c0"># vi /usr/local/etc/<b>pptpd.conf</b></font>&#160;// &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;. &#1092;&#1072;&#1081;&#1083;.
    </p>
    <p>
      <font color="#008000">noipparam </font>
    </p>
    <p>
      5.1 <font color="#0000c0"># vi /etc/ppp/<b>ppp.secret</b></font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1081; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;
    </p>
    <p>
      <font color="#008000">user1&#160;&#160;&#160;1234 </font>
    </p>
    <p>
      <font color="#008000">user2&#160;&#160;&#160;1234 </font>
    </p>
    <p>
      5.2 <font color="#0000c0"># chmod 600 /etc/ppp/<b>ppp.secret </b></font>// &#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &#1087;&#1088;&#1072;&#1074;&#1072;, &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; root &#1084;&#1086;&#1075; &#1074;&#1080;&#1076;&#1077;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1080;
    </p>
    <p>
      6. <font color="#0000c0"># vi /etc/rc.conf</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <p>
      <font color="#008000">pptpd_enable=&quot;YES&quot;</font>
    </p>
    <p>
      7. <font color="#0000c0"># /usr/local/etc/rc.d/pptpd start </font>// &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;
    </p>
    <p>
      8. <font color="#0000c0"># pgrep -l pptpd</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
    <p>
      9. &#1087;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; VPN-&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; --&gt; <font color="#0000c0"># ifconfig</font>&#160;// &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; tun0
    </p>
    <p>
      
    </p>
    <p>
      <b>VPN-&#1082;&#1083;&#1080;&#1077;&#1085;&#1090; </b>
    </p>
    <p>
      1.1 <font color="#0000c0"># pkg_add -r poptop</font>&#160;// FreeBSD. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;
    </p>
    <p>
      1.2 <font color="#0000c0"># rehash </font>
    </p>
    <p>
      <font color="#0000c0">2. # vi /etc/ppp/<b>ppp.conf</b></font>&#160;// &#1086;&#1089;&#1085;. &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;. &#1076;&#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1074; &#1082;&#1086;&#1085;&#1077;&#1094; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;
    </p>
    <p>
      <font color="#008000">pptpclient:</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;set authname user1 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;set authkey 1234 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;set timeout 0 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;set ifaddr 0 0 # &#1072;&#1076;&#1077;&#1088;&#1089;&#1072; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084;&#1099;&#1077; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1072;&#1084;&#1080; (0 0 - &#1072;&#1076;&#1077;&#1088;&#1089;&#1072; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;)</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;accept mschapv2 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;add default HISADDR # &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1072;&#1076;&#1088;&#1077;&#1089; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1086;&#1081; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099; VPN-&#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103;, &#1082;&#1072;&#1082; &#1096;&#1083;&#1102;&#1079; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;alias enable yes</font>
    </p>
    <p>
      3. <font color="#0000c0"># pptp 192.168.1.114 pptpclient 2&gt; /dev/null</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;. &#1042; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1086;&#1103;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1086;&#1074;&#1099;&#1081; tun-&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Troubleshooting" ID="ID_986336978" CREATED="1519112079902" MODIFIED="1583308854370"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1055;&#1088;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082; VPN &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1089;&#1083;&#1077;&#1090;&#1072;&#1077;&#1090; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; (&#1096;&#1083;&#1102;&#1079;)
    </p>
    <p>
      <font color="#0000c0"># netstat -rn -f inet </font>// &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1096;&#1083;&#1102;&#1079;
    </p>
    <p>
      <font color="#0000c0"># route delete default; route add default 192.168.1.254 </font>// &#1087;&#1088;&#1072;&#1074;&#1080;&#1084;
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
