    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1093;&#1077;&#1084;&#1099; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;:</b>
    </p>
    <ul>
      <li>
        <b>basic</b>&#160;-&#160;&#1083;&#1086;&#1075;&#1080;&#1085; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; <b>&#1074; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1086;&#1084; &#1074;&#1080;&#1076;&#1077;</b>, &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; - &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1086;&#1084; &#1074;&#1080;&#1076;&#1077; (&#1079;&#1072;&#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1084; <a href="#ID_1698941296">base64</a>&#160; - binary-to-text, &#1087;&#1088;&#1080; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; <b>&#1053;&#1045; &#1096;&#1080;&#1092;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;</b>). <b>(+)</b>&#160;&#1055;&#1088;&#1086;&#1089;&#1090;&#1072;&#1103;, &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1089;&#1077;&#1084;&#1080; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;&#1084;&#1080;. &#1042; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1077; &#1084;&#1086;&#1078;&#1077;&#1084; &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1082;&#1090;&#1086;, &#1089; &#1082;&#1072;&#1082;&#1086;&#1075;&#1086; IP &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1083;&#1089;&#1103;. <b>(-) </b>&#1085;&#1077;&#1090; &#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;.
      </li>
      <li>
        <b>Digest</b>&#160;- &#1086;&#1085;&#1072; &#1078;&#1077; &#1076;&#1072;&#1081;&#1076;&#1078;&#1077;&#1090; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;. <b>&#1063;&#1091;&#1090;&#1100;</b>&#160; &#1079;&#1072;&#1097;&#1080;&#1097;&#1077;&#1085;&#1085;&#1077;&#1081; basic
      </li>
      <li>
        <b>NTLM</b>&#160;- &#1087;&#1077;&#1088;&#1074;&#1072;&#1103; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1072; Microsoft &#1082; SSO (single-sign-on) &#1077;&#1076;&#1080;&#1085;&#1086;&#1075;&#1086; &#1074;&#1093;&#1086;&#1076;&#1072; &#1076;&#1083;&#1103; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1074; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;
      </li>
      <li>
        <b>negotiate</b>&#160;(aka SPNEGO) - &#1086;&#1085;&#1072; &#1078;&#1077; Kerberos SPN generation - &#1074;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1072; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; Microsoft SSO
      </li>
    </ul>
    <p>
      &#1044;&#1083;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; auth_param.
    </p>
    <p>
      <b>auth_param &#1089;&#1093;&#1077;&#1084;&#1072; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; [&#1086;&#1087;&#1094;&#1080;&#1080;]</b>
    </p>
    <ul>
      <li>
        &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#171;<b>&#1089;&#1093;&#1077;&#1084;&#1072;</b>&#187; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1089;&#1093;&#1077;&#1084;&#1091; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;: ntlm, digest &#1080;&#1083;&#1080; basic
      </li>
      <li>
        &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1099;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1074; &#1089;&#1087;&#1080;&#1089;&#1082;&#1077; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1072; &#1089;&#1093;&#1077;&#1084;&#1072; basic, &#1073;&#1091;&#1076;&#1091;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1077;&#1077;, &#1085;&#1077;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086; &#1086;&#1090; &#1090;&#1086;&#1075;&#1086;, &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1083;&#1080; proxy &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1089;&#1093;&#1077;&#1084;&#1099; &#1080;&#1083;&#1080; &#1085;&#1077;&#1090;. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; <b>&#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1103; &#1089;&#1093;&#1077;&#1084; &#1080;&#1084;&#1077;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;</b>.
      </li>
