<node TEXT="Ограничение ширины канала" ID="ID_53522117" CREATED="1519112080246" MODIFIED="1519112080246"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083; - &#1101;&#1090;&#1086; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; (delay_pools)
      </li>
    </ul>
    <p>
      &#1044;&#1083;&#1103; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1081; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1091;&#1102;&#1097;&#1072;&#1103; <b>&#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; (delay pools)</b>. &#1052;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; <b>&#1085;&#1072; &#1074;&#1077;&#1089;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;</b>&#160; &#1089; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1099; &#1080;&#1083;&#1080; &#1074;&#1077;&#1089;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1040; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100; <b>&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;</b>, &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1087;&#1086;&#1087;&#1099;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1082;&#1072;&#1095;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083;&#1099; <b>&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1090;&#1080;&#1087;&#1072;</b>&#160;&#1080;&#1083;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1084; ftp.
    </p>
    <p>
      
    </p>
    <p>
      1. &#1055;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; delay_pools&#160;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; <b>&#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1077;&#1081;</b>.
    </p>
    <p>
      <font color="#008000"><b>delay_pools 2</b></font>&#160;// &#1076;&#1083;&#1103; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1076;&#1074;&#1091;&#1093; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1077;&#1081;
    </p>
    <p>
      2. &#1045;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; &#1073;&#1099;&#1074;&#1072;&#1102;&#1090; <b>&#1090;&#1088;&#1077;&#1093; &#1082;&#1083;&#1072;&#1089;&#1089;&#1086;&#1074;</b>:
    </p>
    <p>
      <b>1-&#1075;&#1086; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072;</b>, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1099; &#1076;&#1083;&#1103; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; <b>&#1074;&#1089;&#1077;&#1084; acl</b>, &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1084; &#1082; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080;
    </p>
    <p>
      <b>2-&#1075;&#1086; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072;</b>, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1086;&#1077; &#1080; &#1080;&#1085;&#1076;&#1080;&#1074;&#1080;&#1076;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <b>3-&#1075;&#1086; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072;</b>, &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; &#1089;&#1077;&#1090;&#1080; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072; &#1042;, &#1079;&#1072;&#1090;&#1077;&#1084; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1077;&#1081; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072; &#1057; &#1080; &#1077;&#1097;&#1077; &#1086;&#1076;&#1085;&#1086; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;.
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103;, &#1082; &#1082;&#1072;&#1082;&#1086;&#1084;&#1091; &#1082;&#1083;&#1072;&#1089;&#1089;&#1091; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; <b>delay_class</b>:
    </p>
    <p>
      <b><font color="#008000">delay_class 1 1</font></b>&#160;// &#1055;&#1077;&#1088;&#1074;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1085;&#1086;&#1084;&#1077;&#1088; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080;, &#1074;&#1090;&#1086;&#1088;&#1086;&#1077; &#8212; &#1077;&#1077; &#1082;&#1083;&#1072;&#1089;&#1089;.
    </p>
    <p>
      <b><font color="#008000">delay_class 2 1</font></b>
    </p>
    <p>
      3. <b>&#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103;</b>. &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; <font color="#008000"><b>delay_parameters</b></font>.
    </p>
    <ul>
      <li>
        &#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1086;&#1087;&#1094;&#1080;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; delay_parameters &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080;: &#1087;&#1077;&#1088;&#1074;&#1086;&#1075;&#1086; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072; - &#1086;&#1076;&#1080;&#1085; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;; &#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072; - &#1076;&#1074;&#1072; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072;; &#1090;&#1088;&#1077;&#1090;&#1100;&#1077;&#1075;&#1086; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072; - &#1090;&#1088;&#1080; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072;
      </li>
      <li>
        &#1055;&#1088;&#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1080; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1076;&#1074;&#1072; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1084; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1077;: <b>&#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100;</b>&#160;&#1080; <b>&#1086;&#1073;&#1098;&#1077;&#1084; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; - &#1074; &#1073;&#1072;&#1081;&#1090;&#1072;&#1093;</b>.
      </li>
    </ul>
    <p>
      <b><font color="#008000">delay_parameters 1 800/64000</font></b>&#160;// &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; 1-&#1075;&#1086; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072;. &#1043;&#1076;&#1077; 1 - &#1085;&#1086;&#1084;&#1077;&#1088; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080;.
    </p>
    <p>
      &#1063;&#1080;&#1089;&#1083;&#1086; <b>&quot;-1&quot;</b>&#160;&#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1085;&#1077;&#1090; &#1085;&#1080;&#1082;&#1072;&#1082;&#1080;&#1093; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1081;
    </p>
    <p>
      <b><font color="#008000">delay_parameters 1 64000/64000 4000/4000</font></b>&#160;// &#1076;&#1083;&#1103; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; 2-&#1075;&#1086; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072;, &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1076;&#1074;&#1077; &#1087;&#1072;&#1088;&#1099; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;: &#1076;&#1083;&#1103; &#1089;&#1077;&#1090;&#1080; &#1080; &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1099;. &#1054;&#1073;&#1097;&#1077;&#1077; &#1086;&#1075;&#1088;. &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1081; &#1089;&#1077;&#1090;&#1080; 64&#1050;B/s, &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1086;&#1075;&#1088;. &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1099; 4&#1050;B/s
    </p>
    <p>
      4. <b>&#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;</b>&#160;<font color="#008000"><b>delay_access</b></font>. &#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090;, &#1082;&#1072;&#1082;&#1080;&#1077; acl &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1099;.
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1086;&#1075;&#1088;. &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1080; &#1089;&#1082;&#1072;&#1095;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1084;&#1077;&#1076;&#1080;&#1081;&#1085;&#1099;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1076;&#1086; 400B/s:
    </p>
    <p>
      <b><font color="#008000">acl media urlpath_regex -i \.mpg$ \.avi$ \.mp3$</font></b>&#160;// &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084; acl, &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1084;&#1077;&#1076;&#1080;&#1081;&#1085;&#1099;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;
    </p>
    <p>
      <b><font color="#008000">delay_pools 1</font></b>&#160;// &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080;
    </p>
    <p>
      <b><font color="#008000">delay_class 1 1 </font></b>
    </p>
    <p>
      <b><font color="#008000">delay_parameters 1 400/400 </font></b>
    </p>
    <p>
      <b><font color="#008000">delay_access 1 allow media</font></b>&#160;// &#1086;&#1073;&#1103;&#1079;. &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1086;&#1084;&#1077;&#1088; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080;, &#1082; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1087;&#1086;&#1076;&#1082;&#1083;. acl
    </p>
    <p>
      <b><font color="#008000">delay_access 1 deny all</font></b>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="transparent proxy" ID="ID_1722450888" CREATED="1519112080246" MODIFIED="1519112080246"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1056;&#1077;&#1078;&#1080;&#1084; &#1087;&#1088;&#1086;&#1079;&#1088;&#1072;&#1095;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. </b>&#1042; &#1089;&#1086;&#1095;&#1077;&#1090;&#1072;&#1085;&#1080;&#1080; &#1089; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084;&#1080; &#1084;&#1077;&#1078;&#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1084;&#1080; &#1101;&#1082;&#1088;&#1072;&#1085;&#1072;&#1084;&#1080; &#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;&#1084;&#1080; squid &#1084;&#1086;&#1078;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; <b>&#1087;&#1088;&#1086;&#1079;&#1088;&#1072;&#1095;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080; (transparent proxy)</b>.
    </p>
    <ul>
      <li>
        &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088; &#1074;&#1084;&#1077;&#1089;&#1090;&#1086; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1088;&#1072;&#1079;&#1091; &#1087;&#1077;&#1088;&#1077;&#1089;&#1099;&#1083;&#1072;&#1090;&#1100; HTTP-&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; HTTP-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1074; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1077;, &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1080;&#1093; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;
      </li>
      <li>
        &#1055;&#1088;&#1086;&#1082;&#1089;&#1080;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; (&#1089; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1081; &#1086;&#1090;&#1076;&#1072;&#1095;&#1077;&#1081; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1075;&#1086; &#1080;&#1079; &#1082;&#1077;&#1096;&#1072;), &#1101;&#1090;&#1086; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1080;&#1074;&#1096;&#1077;&#1084;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102;, &#1076;&#1083;&#1103; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1086;&#1085;&#1086; &#1074;&#1099;&#1075;&#1083;&#1103;&#1076;&#1080;&#1090; &#1082;&#1072;&#1082; &#171;&#1086;&#1090;&#1074;&#1077;&#1090;&#187; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;, &#1082; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084;&#1091; &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;&#1072;&#1083;&#1089;&#1103; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;
      </li>
      <li>
        &#1055;&#1088;&#1080; &#1090;&#1072;&#1082;&#1086;&#1084; &#1087;&#1086;&#1076;&#1093;&#1086;&#1076;&#1077; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1085;&#1077; &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1085;&#1072;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1087;&#1088;&#1086;&#1079;&#1088;&#1072;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1101;&#1090;&#1086; &#1080; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1091;&#1084;&#1077;&#1074;&#1072;&#1077;&#1090;
      </li>
      <li>
        (-) &#1088;&#1072;&#1073;&#1086;&#1090;&#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; HTTP
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="squid.conf" FOLDED="true" ID="ID_1041463773" CREATED="1519112080247" MODIFIED="1552641575473"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      /etc/squid/<b>squid.conf&#160;</b>- &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1092;&#1072;&#1081;&#1083;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">netstat -nlpa | grep squid&#160;&#160;#</font>&#160;&#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1082;&#1091;&#1076;&#1072; &quot;&#1090;&#1086;&#1088;&#1095;&#1080;&#1090;&quot; squid. &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&#1093;
    </p>
    <p>
      <font color="#0000c0">lsof -i tcp:3128</font>&#160;&#160;#
    </p>
    <p>
      <b>&#160;&#160;<font size="4">&#160;*</font></b>:3128 (LISTEN)&#160;&#160;# <b><font size="4">*</font></b>&#160;- &#1087;&#1088;&#1080;&#1094;&#1077;&#1087;&#1080;&#1083;&#1089;&#1103; &#1082;&#1086; &#1074;&#1089;&#1077;&#1084; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&#1084; (<a href="#ID_285576397"><font color="#ff0000"><b>open proxy</b></font></a>)
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1085;&#1077;&#1085;&#1091;&#1078;&#1085;&#1099;&#1077; &#1085;&#1072;&#1084; &#1087;&#1086;&#1088;&#1090;&#1099;</b>&#160; (&#1074; FreeBSD &#1080;&#1093; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;):
    </p>
    <p>
      <font color="#008000"><b>http_port 10.10.4.1:3128</b></font>&#160;&#160;# &#1087;&#1086;&#1088;&#1090; 3128 &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1086; &#1074;&#1085;&#1091;&#1090;&#1088;. &#1089;&#1077;&#1090;&#1100; (eth1:&lt;&#1087;&#1086;&#1088;&#1090;&gt;), &#1090;.&#1077;. &#1089;&#1083;&#1091;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
    <p>
      <font color="#008000"><b>icp_port 0</b></font>&#160;&#160;# &#1087;&#1086;&#1088;&#1090; 3130 &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1089;&#1083;&#1077; &#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;&#1072;:</b>
    </p>
    <p>
      <font color="#0000c0">squid -k p</font>&#160;&#160;# &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1086;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;
    </p>
    <p>
      <font color="#0000c0">squid -k &#1089;&#160;&#160;#</font><font color="#000000">&#160;&#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1085;&#1072;&#1083;&#1077;&#1090;&#1091;</font>
    </p>
    <p>
      <font color="#0000c0">squid -k r&#160;&#160;#</font>&#160;&#1087;&#1077;&#1088;&#1077;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">lsof -i tcp:3128</font>&#160;&#160;# &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084;
    </p>
  </body>
</html></richcontent>
<node TEXT="1. Огр. доступа к домену" ID="ID_325158824" CREATED="1519112080247" MODIFIED="1519112080247"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1076;&#1086;&#1089;&#1091;&#1087; &#1082; &#1076;&#1086;&#1084;&#1077;&#1085;&#1091;, &#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072; &#1074; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1077; &#1095;&#1072;&#1089;&#1099;, &#1082;&#1088;&#1086;&#1084;&#1077; &#1084;&#1072;&#1096;&#1080;&#1085;&#1099; &#1072;&#1076;&#1084;&#1080;&#1085;&#1072;.</b>
    </p>
    <p>
      
    </p>
    <p>
      1. <font color="#0000c0"># vi /etc/squid/squid.conf</font>
    </p>
    <p>
      2. &#1053;&#1072;&#1093;&#1086;&#1076;&#1080;&#1084; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; INSERT YOUR OWN RULE(S) ... --&gt; &#1074;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1089;&#1088;&#1072;&#1079;&#1091; &#1079;&#1072; &#1085;&#1077;&#1081;:
    </p>
    <p>
      <font color="#008000"><b>http_access allow myhost </b></font>
    </p>
    <p>
      <font color="#008000"><b>http_access deny rambler </b></font>
    </p>
    <p>
      <font color="#008000"><b>http_access allow mynet wt </b></font>
    </p>
    <p>
      <font color="#008000"><b>http_access deny all</b>&#160;</font>
    </p>
    <p>
      3. &#1063;&#1091;&#1090;&#1100; &#1074;&#1099;&#1096;&#1077;, &#1075;&#1076;&#1077; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; ACL --&gt; &#1074;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1089;&#1088;&#1072;&#1079;&#1091; &#1079;&#1072; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1084;&#1080; acl: --&gt; Save
    </p>
    <p>
      <font color="#008000"><b>acl myhost src &#1042;&#1040;&#1064;_&#1042;&#1053;&#1045;&#1064;&#1053;&#1048;&#1049;_IP_&#1040;&#1044;&#1056;&#1045;&#1057;</b></font>&#160; // 192/168.1.104<font color="#008000"><b>&#160;</b></font>
    </p>
    <p>
      <font color="#008000"><b>acl mynet src IP_&#1040;&#1044;&#1056;&#1045;&#1057;_&#1042;&#1040;&#1064;&#1045;&#1049;_&#1057;&#1045;&#1058;&#1048;</b></font>&#160; // 192.168.1.0/24
    </p>
    <p>
      <font color="#008000"><b>acl rambler dstdomain .rambler.ru </b></font>// &#1079;&#1072;&#1087;&#1088;&#1077;&#1090; &#1085;&#1072; .rambler
    </p>
    <p>
      <font color="#008000"><b>acl wt time 10:00-17:0</b></font>0 // &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103;
    </p>
    <p>
      4. <font color="#0000c0"># squid -k &#1089;</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0"># squid -k p // &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;</font>
    </p>
    <p>
      5. <font color="#0000c0"># squid -k re</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      6. <font color="#0000c0"># date</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1074;&#1088;&#1077;&#1084;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1095;&#1090;&#1086; &#1089;&#1090;&#1072;&#1074;&#1080;&#1084; &#1052;&#1086;&#1089;&#1082;&#1086;&#1074;&#1089;&#1082;&#1086;&#1077; <font color="#0000c0"># cp /usr/share/zoneinfo/Europe/Moscow /etc/localtime</font>
    </p>
    <p>
      7. <font color="#0000c0"># links -http-proxy c4 -dump ya.ru</font>&#160;// &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1084; &#1080;&#1076;&#1077;&#1084; &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080; (-http-proxy) &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1072; &#1089;4 &#1085;&#1077; &#1079;&#1072;&#1093;&#1086;&#1076;&#1103; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; (-dump). &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1086;&#1090;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091; --&gt; &#1055;&#1088;&#1086;&#1073;&#1091;&#1077;&#1084; &#1074;&#1084;&#1077;&#1089;&#1090;&#1086; &#1089;4 &#1087;&#1086;&#1076;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; IP &#1072;&#1076;&#1088;&#1077;&#1089; --&gt; &#1045;&#1089;&#1083;&#1080; &#1089;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1083;&#1086;, &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1082;&#1072;&#1082; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103; DNS
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="2. Аутент. польз. (по схеме basic)" ID="ID_1209319819" CREATED="1519112080247" MODIFIED="1519112080247"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># &#1040;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; (&#1087;&#1086; &#1089;&#1093;&#1077;&#1084;&#1077; basic) &#1087;&#1088;&#1080; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1077; &#1079;&#1072;&#1081;&#1090;&#1080; &#1085;&#1072; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;</b>
    </p>
    <p>
      1. <font color="#0000c0"># vi /etc/squid/squid.conf</font>
    </p>
    <p>
      2. &#1053;&#1072;&#1093;&#1086;&#1076;&#1080;&#1084; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; <b>INSERT YOUR OWN RULE(S)</b>&#160;... --&gt; &#1074;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1089;&#1088;&#1072;&#1079;&#1091; &#1079;&#1072; &#1085;&#1077;&#1081;:
    </p>
    <p>
      <b><font color="#008000">http_access allow ya passwd </font></b>
    </p>
    <p>
      <b><font color="#008000">http_access deny ya </font></b>
    </p>
    <p>
      <b># &#1073;&#1099;&#1083;&#1080; &#1088;&#1072;&#1085;&#1077;&#1077; (&#1089;&#1084;. &#1086;&#1075;&#1088;. &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1076;&#1086;&#1084;&#1077;&#1085;&#1091;)</b>
    </p>
    <p>
      <font color="#008000"><b>http_access allow myhost </b></font>
    </p>
    <p>
      <font color="#008000"><b>http_access deny rambler </b></font>
    </p>
    <p>
      <font color="#008000"><b>http_access allow mynet wt </b></font>
    </p>
    <p>
      <font color="#008000"><b>http_access deny all</b>&#160; </font>
    </p>
    <p>
      3. &#1053;&#1072;&#1093;&#1086;&#1076;&#1080;&#1084; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; <b>auth_param basic program&#160;&lt;uncomment...&gt;</b>&#160;--&gt; &#1055;&#1088;&#1072;&#1074;&#1080;&#1084;
    </p>
    <p>
      # <b>ncsa_auth</b>&#160;- &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1076;&#1083;&#1103; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;. &#1087;&#1086;&#1083;&#1100;&#1079;. &#1087;&#1086; &#1089;&#1093;&#1077;&#1084;&#1077; basic. <b>passwd</b>&#160;- &#1080;&#1084;&#1077;&#1085;&#1072; &#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1080; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; ncsa_auth
    </p>
    <p>
      <font color="#008000"><b>auth_param basic program /usr/lib/squid/ncsa_auth /etc/squid/passwd</b></font>
    </p>
    <p>
      4. &#1063;&#1091;&#1090;&#1100; &#1074;&#1099;&#1096;&#1077;, &#1075;&#1076;&#1077; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; ACL --&gt; <b>&#1074;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1089;&#1088;&#1072;&#1079;&#1091; &#1079;&#1072; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1084;&#1080; acl</b>: --&gt; <b>Save</b>
    </p>
    <p>
      <b># &#1073;&#1099;&#1083;&#1080; &#1088;&#1072;&#1085;&#1077;&#1077; (&#1089;&#1084;. &#1086;&#1075;&#1088;. &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1076;&#1086;&#1084;&#1077;&#1085;&#1091;) --&gt; &#1074;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1079;&#1072; &#1085;&#1080;&#1084;&#1080;</b>
    </p>
    <p>
      <font color="#008000"><b>acl myhost src &#1042;&#1040;&#1064;_&#1042;&#1053;&#1045;&#1064;&#1053;&#1048;&#1049;_IP_&#1040;&#1044;&#1056;&#1045;&#1057;</b></font>&#160; // 192/168.1.104<font color="#008000"><b>&#160;</b></font>
    </p>
    <p>
      <font color="#008000"><b>acl mynet src IP_&#1040;&#1044;&#1056;&#1045;&#1057;_&#1042;&#1040;&#1064;&#1045;&#1049;_&#1057;&#1045;&#1058;&#1048;</b></font>&#160; // 192.168.1.0/24
    </p>
    <p>
      <font color="#008000"><b>acl rambler dstdomain .rambler.ru </b></font>// &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; .rambler
    </p>
    <p>
      <font color="#008000"><b>acl wt time 10:00-17:0</b></font>0 // &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103;
    </p>
    <p>
      -------------------------------------------------------------------------
    </p>
    <p>
      <font color="#008000"><b>acl passwd proxy_auth REQUIRED&#160;</b></font>// &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1087;&#1086;&#1083;&#1100;&#1079;.
    </p>
    <p>
      <font color="#008000"><b>acl ya dstdomain .ya.ru .yandex.ru</b></font>&#160;// &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      5. <font color="#0000c0"># htpasswd -c /etc/squid/passwd user3</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1080; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; &#1092;&#1072;&#1081;&#1083; <b>/etc/squid/passwd</b>&#160;&#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1086;&#1081; <b>htpasswd</b>&#160;(&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1089;&#1103; &#1074;&#1084;&#1077;&#1089;&#1090;&#1077; &#1089; WEB &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084; Apache)
    </p>
    <p>
      6. <font color="#0000c0"># squid -k &#1089;</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0"># squid -k p</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0"># squid -k r (&#1080;&#1083;&#1080; re)</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      7. <font color="#0000c0"># links -http-proxy c4 ya.ru</font>&#160;// &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1084; &#1080;&#1076;&#1077;&#1084; &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080; (-http-proxy) &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1072; &#1089;4. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1086;&#1090;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091; --&gt; &#1055;&#1088;&#1086;&#1073;&#1091;&#1077;&#1084; &#1074;&#1084;&#1077;&#1089;&#1090;&#1086; &#1089;4 &#1087;&#1086;&#1076;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; IP &#1072;&#1076;&#1088;&#1077;&#1089; --&gt; &#1045;&#1089;&#1083;&#1080; &#1089;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1083;&#1086;, &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1082;&#1072;&#1082; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103; DNS (/etc/hosts &#1080; &#1090;.&#1076;.)
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="3.0 Огр. ширины канала" ID="ID_657624708" CREATED="1519112080247" MODIFIED="1519112080247"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1054;&#1076;&#1085;&#1086;&#1082;&#1083;&#1072;&#1089;&#1089;&#1085;&#1080;&#1082;&#1080; &#1080; VK = 1000B/s; Youtube = 1000B/s (PC) &#1080; 10000B/s (all mynet)
    </p>
    <p>
      <font color="#0000c0"># vi /etc/squid/squid.conf </font>
    </p>
    <p>
      <font color="#0000c0"># vi /usr/local/etc/squid/squid.conf </font>// <font color="#ff0000">FreeBSD</font>
    </p>
    <p>
      <font color="#008000"><b>acl ok dstdomain .odnoklassniki.ru</b></font>
    </p>
    <p>
      <font color="#008000"><b>acl vk dstdomain .vi.com </b></font>
    </p>
    <p>
      <font color="#008000"><b>acl tube dstdom_regex -i tube </b></font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>delay_pools 2</b>&#160;</font>// &#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1091;&#1102;&#1090;&#1089;&#1103; 2&#1077; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">delay_class 1 2</font></b>&#160;// &#1076;&#1083;&#1103; 1-&#1081; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; - 2-&#1081; &#1082;&#1083;&#1072;&#1089;&#1089;
    </p>
    <p>
      <b><font color="#008000">delay_class 2 2</font></b>&#160;// &#1076;&#1083;&#1103; 2-&#1081; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; - 2-&#1081; &#1082;&#1083;&#1072;&#1089;&#1089;
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">delay_parameters 1 -1/-1 1000/1000</font></b>&#160;// &#1076;&#1083;&#1103; 1-&#1081; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; &#1085;&#1077;&#1090; &#1086;&#1075;&#1088;. (<b>&#1089;&#1082;&#1086;&#1088;.&#1074;&#1090;&#1077;&#1082;&#1072;&#1085;&#1080;&#1103;/&#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1074; &#1073;&#1072;&#1081;&#1090;&#1072;&#1093;</b>) &#1076;&#1083;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099;, &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1083;&#1103; PC
    </p>
    <p>
      <b><font color="#008000">delay_parameters 2 10000/1000 1000/1000</font></b>&#160;// &#1076;&#1083;&#1103; 2-&#1081; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; 10KB/s &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1081; &#1089;&#1077;&#1090;&#1080; (<b>&#1089;&#1082;&#1086;&#1088;.&#1074;&#1090;&#1077;&#1082;&#1072;&#1085;&#1080;&#1103;/&#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1074; &#1073;&#1072;&#1081;&#1090;&#1072;&#1093;</b>)
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">delay_access 1 allow ok</font></b>&#160;// 1-&#1103; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1072; &#1076;&#1083;&#1103; acl ok
    </p>
    <p>
      <b><font color="#008000">delay_access 1 allow vk</font></b>&#160;// 1-&#1103; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;lq&#1077;&#1088;&#1078;&#1082;&#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1072; &#1076;&#1083;&#1103; acl vk
    </p>
    <p>
      <b><font color="#008000">delay_access 1 deny all</font></b>&#160;// &#1087;&#1088;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1095;&#1090;&#1086;&#1073;&#1099; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1085;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1083;&#1072;&#1089;&#1100; &#1082; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;&#1084;
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">delay_access 2 allow tube</font></b>&#160;// 2-&#1103; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1078;&#1077;&#1088;&#1078;&#1082;&#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1072; &#1076;&#1083;&#1103; acl tube
    </p>
    <p>
      <b><font color="#008000">delay_access 2 deny all </font></b>
    </p>
    <p>
      
    </p>
    <p>
      &#160;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0"># squid -k &#1089;</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0"># squid -k p</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0"># squid -k r (&#1080;&#1083;&#1080; re)</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="3.1 Огр. канала" ID="ID_817290369" CREATED="1519112080248" MODIFIED="1519112080248"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1044;&#1083;&#1103; &#1086;&#1090;&#1089;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &quot;&#1074;&#1088;&#1077;&#1076;&#1085;&#1086;&#1075;&#1086;&quot; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1087;&#1088;&#1086;&#1073;&#1086;&#1074;&#1072;&#1090;&#1100; &#1086;&#1090;&#1088;&#1091;&#1073;&#1080;&#1090;&#1100; (&#1079;&#1072;&#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;) &#1074;&#1089;&#1077; &#1087;&#1086;&#1088;&#1090;&#1099; &#1082;&#1088;&#1086;&#1084;&#1077;:
    </p>
    <p>
      <font color="#0000c0"># vi /etc/squid/squid.conf </font>
    </p>
    <p>
      <font color="#008000"><b>acl Safe_ports port 80&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;# http </b></font>
    </p>
    <p>
      <font color="#008000"><b>acl Safe_ports port 443&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;# https</b></font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="3.2 Огр. ширины канала" ID="ID_405066598" CREATED="1519112080248" MODIFIED="1519112080248"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1090;&#1100; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1089;&#1082;&#1072;&#1095;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1084;&#1072;&#1090;&#1077;&#1088;&#1080;&#1072;&#1083;&#1086;&#1074; &#1089; &#1089;&#1072;&#1081;&#1090;&#1072; odnoklassniki.ru &#1076;&#1086; 40 &#1073;&#1072;&#1081;&#1090; &#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1091;
    </p>
    <p>
      1.<font color="#0000c0">&#160;# vi /etc/squid/squid.conf&#160;&#160;--&gt; </font>&#1042; &#1082;&#1086;&#1085;&#1077;&#1094; &#1092;&#1072;&#1081;&#1083;&#1072; &#1074;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084;:
    </p>
    <p>
      <font color="#008000"><b>acl odnoklassniki dstdomain .odnoklassniki.ru</b></font>&#160;# &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; acl odnoklassniki
    </p>
    <p>
      <font color="#008000"><b>delay_pools 1</b></font>&#160;# &#1086;&#1076;&#1085;&#1072; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080;
    </p>
    <p>
      <font color="#008000"><b>delay_class 1 1</b></font>&#160;# &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; 1-&#1075;&#1086; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072;
    </p>
    <p>
      <font color="#008000"><b>delay_parameters 1 40/40 </b></font># &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#008000"><b>delay_access 1 allow odnoklassniki </b></font># &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1084; &#1076;&#1083;&#1103; acl odn... &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; 1
    </p>
    <p>
      <font color="#008000"><b>delay_access 1 deny all </b></font># &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1079;&#1072;&#1087;&#1088;&#1077;&#1097;&#1072;&#1077;&#1084;
    </p>
    <p>
      2. <font color="#0000c0"># squid -k &#1089;</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0"># squid -k p</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0"># squid -k r (&#1080;&#1083;&#1080; re)</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      3. <font color="#0000c0"># links -http-proxy c4 odnoklassniki.ru</font>&#160;// &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1084; &#1080;&#1076;&#1077;&#1084; &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080; (-http-proxy) &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1072; &#1089;4. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1086;&#1090;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091; --&gt; &#1055;&#1088;&#1086;&#1073;&#1091;&#1077;&#1084; &#1074;&#1084;&#1077;&#1089;&#1090;&#1086; &#1089;4 &#1087;&#1086;&#1076;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; IP &#1072;&#1076;&#1088;&#1077;&#1089; --&gt; &#1045;&#1089;&#1083;&#1080; &#1089;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1083;&#1086;, &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1082;&#1072;&#1082; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103; DNS (/etc/hosts &#1080; &#1090;.&#1076;.)
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="4. прозрачный прокси" ID="ID_800244027" CREATED="1519112080248" MODIFIED="1519112080248"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">1. # vi /etc/squid/squid.conf </font>
    </p>
    <p>
      <font color="#008000">http_port 3128 transparent</font>&#160;// &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1089;&#1083;&#1086;&#1074;&#1086; transparent. &#1045;&#1089;&#1083;&#1080; &#1087;&#1088;&#1080;&#1083;&#1077;&#1090;&#1080;&#1090; &#1087;&#1072;&#1082;&#1077;&#1090; HTTP, &#1079;&#1072;&#1075;&#1083;&#1103;&#1085;&#1080; &#1074; &#1077;&#1075;&#1086; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1082; &#1080; &#1087;&#1088;&#1080;&#1085;&#1077;&#1089;&#1080; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091; &#1090;&#1086;, &#1095;&#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086;
    </p>
    <p>
      <font color="#008000">acl mynet src 192.168.1.0/24 10.10.0.0/16</font>&#160;// &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1074;&#1085;&#1091;&#1090;&#1088;. &#1089;&#1077;&#1090;&#1100;
    </p>
    <p>
      2. <font color="#0000c0"># squid -k &#1089;</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0"># squid -k p</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0"># squid -k r (&#1080;&#1083;&#1080; re)</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      3. &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090;&#1085;&#1099;&#1081; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;
    </p>
    <p>
      <font color="#0000c0"># <a href="#ID_1140070626">iptables</a>&#160;-t nat -I PREROUTING -p tcp --dport 80 -i lan&#160;-j DNAT --to 10.10.4.1:3128</font>&#160;// &#1077;&#1089;&#1083;&#1080; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; tcp &#1080; &#1087;&#1086;&#1088;&#1090; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; 80 &#1080; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; lan, &#1090;&#1086; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; ...
    </p>
  </body>
</html></richcontent>
</node>
</node>
