      &#1095;&#1090;&#1086;&#1073;&#1099; &#1091; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; &#1087;&#1088;&#1080; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1080;&#1080; &#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &#1088;&#1091;&#1075;&#1072;&#1085;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1099;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1087;&#1092;&#1089;&#1077;&#1085;&#1089;&#1086;&#1084; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090; &#1080; &#1074;&#1085;&#1077;&#1076;&#1088;&#1080;&#1090;&#1100; &#1077;&#1075;&#1086; &#1074; &#1094;&#1077;&#1085;&#1090;&#1088; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1074; &#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084; &#1040;&#1044; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091; &#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
