<node TEXT="Команды" ID="ID_1477009303" CREATED="1751368800670" MODIFIED="1751611311417"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Инфо</b>
    </p>
    <p>
      <span style="color: #0000c0;">ip&#xa0;a</span>&#xa0;&#xa0;# IP-адреса. scope global dynamic (это DHCP)
    </p>
    <p>
      <span style="color: #0000c0;">ip -4 a</span>&#xa0;&#xa0;# IP-адреса IPv4&#xa0;&#xa0;
    </p>
    <p>
      <span style="color: #0000c0;">ip r</span>&#xa0;&#xa0;# gateway (шлюз, default)
    </p>
    <p>
      <span style="color: #0000c0;">ifconfig&#xa0;-a</span>&#xa0;&#xa0;# Все интерфейсы, в т.ч. неактивные
    </p>
    <p>
      <span style="color: #0000c0;">ip&#xa0;link show dev eth0</span>&#xa0;&#xa0;# MAC-адрес интерфейса
    </p>
    <p>
      <span style="color: #0000c0;">ip link&#xa0;show</span>&#xa0;&#xa0;# MAC-адреса всех интерфейсов. Флаг &lt;LOWER-UP&gt; - карта подключена к сети
    </p>
    <p>
      <span style="color: #0000c0;">ip n</span>&#xa0;&#xa0;# ARP таблица
    </p>
    <p>
      <span style="color: #0000c0;">netstat -a --inet</span>&#xa0;&#xa0;# Активные сетевые сокеты
    </p>
    <p>
      <span style="color: #0000c0;">tcpdump -D </span>&#xa0;# Доступные интерфейсы (которые можно прослушивать при помощи опции -i)
    </p>
    <p>
      <span style="color: #0000c0;">ip -s link show</span>&#xa0;&#xa0;# Статистика по сетевым интерфейсам
    </p>
    <p>
      <span style="color: #0000c0;">ip -s address show</span>&#xa0;&#xa0;# Статистика по IP-адресам на каждом интерфейсе
    </p>
    <p>
      <span style="color: #0000c0;">cat /sys/class/net/&lt;interface&gt;/speed</span>&#xa0;&#xa0;# Просмотр максимальной скорости интерфейса
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">DHCP</span>
    </p>
    <p>
      <span style="color: #0000c0;">cat /var/lib/dhcp/</span><span style="color: #0000c0; font-weight: bold;">dhclient.leases</span>&#xa0;&#xa0;# История полученных через DHCP IP-адресов
    </p>
    <p>
      <span style="color: #0000c0;">dhclient -r &lt;интерфейс&gt;</span>&#xa0;&#xa0;# Освободить текущий IP
    </p>
    <p>
      <span style="color: #0000c0;">dhclient -v &lt;интерфейс&gt;</span>&#xa0;&#xa0;# Запросить новый
    </p>
    <p>
      <span style="color: #0000c0;">dhclient -d &lt;интерфейс&gt;</span>&#xa0;&#xa0;# Запустит DHCP-запрос в режиме отладки
    </p>
    <p>
      <span style="color: #0000c0;">tcpdump -i &lt;интерфейс&gt; port 67 or port 68 -v</span>&#xa0;&#xa0;# Мониторинг DHCP-трафика
    </p>
    <p>
      <span style="color: #0000c0;">journalctl -u systemd-networkd | grep &quot;DHCP&quot;</span>&#xa0;&#xa0;# Проверка системного кэша systemd-networkd
    </p>
    <p>
      <span style="color: #0000c0;">systemctl restart systemd-networkd</span>&#xa0;&#xa0;# Очистка кэша
    </p>
    <p>
      
    </p>
    <p>
      <b>Включить интерфейс</b>
    </p>
    <p>
      <span style="color: #0000c0;">ip addr add 10.0.11.122/24 dev enp4s0</span>&#xa0;&#xa0;# Назначить IP-адрес на интерфейс
    </p>
    <p>
      <span style="color: #0000c0;">ifconfig eth1 192.168.1.10/24</span>&#xa0;
    </p>
    <p>
      <span style="color: #0000c0;">ip route add default via 10.0.11.1 </span><span style="color: #ff0000;">dev enp4s0 (???)</span>&#xa0;&#xa0;# Добавить маршрут по умолчанию
    </p>
    <p>
      <span style="color: #0000c0;">ip -6 route add default via 2001:db8:0:abcd::1</span>
    </p>
    <p>
      <span style="color: #0000c0;">ip link set enp4s0 up</span>&#xa0;&#xa0;# Запустить интерфейс
    </p>
    <p>
      
    </p>
    <p>
      <b>Выключить интерфейc</b>
    </p>
    <p>
      <span style="color: #0000c0;">ip route del default </span>
    </p>
    <p>
      <span style="color: #0000c0;">ip addr del &lt;IP-адрес&gt;dev &lt;интерфейс&gt;</span>&#xa0;&#xa0;# Ручное удаление (временно, до перезагрузки)
    </p>
    <p>
      <span style="color: #0000c0;">ip link set enp4s0 downcat </span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Маршрутизация</b>
    </p>
    <p>
      <span style="color: #0000c0;">echo 1 &gt;&#xa0;&#xa0;/proc/sys/net/ipv4/ip_forward</span>&#xa0;&#xa0;# Стать маршрутизатором до перезагрузки
    </p>
    <p>
      <span style="color: #0000c0;">route add default gw 192.168.1.254</span>&#xa0;&#xa0;# &#xa0;Добавить шлюз по умочанию (в <span style="color: #ff0000;">FreeBSD</span>&#xa0;&#xa0;gw не нужно)
    </p>
    <p>
      <span style="color: #0000c0;">route add -host 10.5.11.252 gw 192.168.1.1</span>&#xa0;// маршрут к хосту
    </p>
    <p>
      <span style="color: #0000c0;">route add 172.16.2.251/32 10.10.109.51</span>&#xa0;// добавить маршрут (возможно только <span style="color: #ff0000;">FreeBSD</span>)
    </p>
    <p>
      <span style="color: #0000c0;">ip route add default via 192.168.1.254</span>&#xa0;&#xa0;# Добавить шлюз по умолчанию
    </p>
    <p>
      <span style="color: #0000c0;">route del default</span>&#xa0;// удалить шлюз по умолчанию
    </p>
    <p>
      <span style="color: #0000c0;">route -n</span>&#xa0;// вывод таблицы маршрутизации
    </p>
    <p>
      <span style="color: #0000c0;">netstat&#xa0;-rn</span>&#xa0;// вывод таблицы маршрутизации
    </p>
    <p>
      <span style="color: #0000c0;">ip route del default</span>&#xa0;// удалить маршрут default
    </p>
    <p>
      
    </p>
    <p>
      <b>DNS </b>
    </p>
    <p>
      <span style="color: #0000c0;">resolvectl status</span>&#xa0;&#xa0;# Посмотреть текущие DNS-серверы
    </p>
    <p>
      <span style="color: #0000c0;">vi /etc/hosts # </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;127.0.0.1&#xa0;&#xa0;&#xa0;localhost </span>// возможно ничего и не нужно менять
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;192.168.1.104&#xa0;&#xa0;&#xa0;c4.class.us&#xa0;&#xa0;&#xa0;c4 </span>// возможно ничего и не нужно менять
    </p>
    <p>
      <span style="color: #0000c0;">vi /etc/resolv.conf </span># <span style="color: #ff0000;">c U12.4</span>&#xa0;настраивается&#xa0;через файл <b>/etc/network/interfaces</b>
    </p>
    <p>
      &#xa0;&#xa0; <span style="color: #008000;">nameserver&#xa0;&#xa0;&#xa0;127.0.0.1 </span>
    </p>
    <p>
      &#xa0;&#xa0; <span style="color: #008000;">search contoso.com</span>&#xa0;# добавляет суффиксы DNS
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>Параметры сетевого интерфейса (скорость связи,&#xa0;&#xa0;дуплекс)</b>
    </p>
    <p>
      <span style="color: #0000c0;">ethtool &lt;интерфейс&gt;</span>&#xa0;&#xa0;# Запросить параметры
    </p>
    <p>
      <span style="color: #0000c0;">mii-tool &lt;интерфейс&gt;</span>
    </p>
    <p>
      <span style="color: #0000c0;">ethtool -s eth0 speed 100 duplex full</span>&#xa0;&#xa0;# Перевести интерфейс в fullduplex и 100 Мбит/с
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Настройка (Ubuntu)" ID="ID_413865506" CREATED="1519112079892" MODIFIED="1751606655919"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1118806911">netplan</a>&#xa0; <a href="#ID_1582188882">systemd-resolved</a>&#xa0;&#xa0;<a href="#ID_1962375635">NetworkManager</a>&#xa0; <a href="#ID_1642398281">YAML</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">renderer&#xa0;- Netplan автоматически выбирает рендерер на основе установленного ПО</span>
    </p>
    <ol>
      <li>
        <span style="font-weight: bold;">для серверов</span>&#xa0;- networkd (минимум ресурсов)
      </li>
      <li>
        <span style="font-weight: bold;">для ноутбуков/десктопов</span>&#xa0;- NetworkManager (Wi-Fi, VPN, удобство)
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Настройка (CentOS)" ID="ID_1452325526" CREATED="1546176053567" MODIFIED="1751368805312"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Настроить доступ к интернету&#xa0;&#xa0;(CentOS)</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>/etc/sysconfig/</b>
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <b>network</b>&#xa0;- имя компьютера, стандартный маршрут, имя домена DNS
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <b>network-scripts/ifcfg-&lt;IntName&gt;</b>&#xa0;- IP-адрес, маска
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <b>network-scripts/route-ifname</b>&#xa0;- аргументы <b>ip route</b>
    </p>
    <p>
      
    </p>
    <p>
      -----------------------------------
    </p>
    <p>
      <span style="color: #0000c0;">vi /etc/sysconfig/network</span>
    </p>
    <p>
      <span style="color: #008000;">NETWORКING=yes </span>
    </p>
    <p>
      <span style="color: #008000;">NETWORKING_IPVб=no </span>
    </p>
    <p>
      <span style="color: #008000;">HOSTNAМE=host.centos.com </span>
    </p>
    <p>
      <span style="color: #008000;">DOМAINNAМE=centos.com</span>&#xa0;&#xa0;&#xa0;# Необязательно
    </p>
    <p>
      <span style="color: #008000;">GATEWAY=192.168.1.254</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Сменить интерфейс (CentOS)</b>&#xa0;&#xa0;вручную или <a href="#ID_1962375635">nmcli&amp;nmtui</a>
    </p>
    <p>
      <b><span style="color: #0000c0;">vi /etc/sysconfig/network-scripts/ifcfg-enp0s3</span></b><span style="color: #0000c0;">&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000;">BOOTPROTO=none</span>&#xa0;&#xa0;# DHCP - нет <span style="color: #ff0000;">или =static(???)</span>
    </p>
    <p>
      <span style="color: #008000;">IPADDR=192.168.1.80 </span>
    </p>
    <p>
      <span style="color: #008000;">PREFIX=24</span>&#xa0;&#xa0;# Маска <span style="color: #ff0000;">или NETMASK=255.255.255.0 (???)</span>
    </p>
    <p>
      <span style="color: #008000;">GATEWAY=192.168.1.254 </span>
    </p>
    <p>
      <span style="color: #008000;">DNS1=192.168.1.254 </span>
    </p>
    <p>
      <span style="color: #008000;">DNS2=8.8.8.8</span>
    </p>
    <p>
      <br/>
      
    </p>
    <p>
      <b>Настройка на основе DHCP </b>
    </p>
    <p>
      <span style="color: #008000;">DEVICE=&lt;IntName&gt;</span>&#xa0;&#xa0;# eth0&#xa0;или enp0s3
    </p>
    <p>
      <span style="color: #008000;">BOOTPROTO=dhcp </span>
    </p>
    <p>
      <span style="color: #008000;">ONBOOT=yes </span>
    </p>
    <p>
      <br/>
      <span style="color: #0000c0;">systemctl restart network</span>&#xa0;&#xa0;# Перечитать сетевые настройки или<br/><br/>
    </p>
    <ol>
      <li>
        <span style="color: #0000c0;">ip a</span>&#xa0;&#xa0;или&#xa0; <span style="color: #0000c0;">ifconfig</span>&#xa0;&#xa0;# ip-интерфейсы
      </li>
      <li>
        <span style="color: #0000c0;">ip r</span>&#xa0;&#xa0;# Посмотреть gateway (шлюз)
      </li>
      <li>
        <span style="color: #0000c0;">ifup enp0s3</span>&#xa0;&#xa0;или&#xa0; <span style="color: #0000c0;">dhclient eth0&#xa0; </span># Разовое получение адреса (до завершения сеанса) у DHCP-сервера
      </li>
      <li>
        <b><span style="color: #008000;">/etc/sysconfig/network-scripts/ifcfg-enp0s3</span></b>&#xa0;&#xa0;# Получать адрес во время загрузки<br color="#008000" style="color: #008000;"/><span style="color: #008000;">ONBOOT=yes</span>
      </li>
      <li>
        <span style="color: #0000c0;">/etc/init.d/network restart</span>&#xa0;&#xa0;или <span style="color: #0000c0;">service network restart</span>&#xa0;&#xa0;# перезапуск службы
      </li>
      <li>
        <span style="color: #0000c0;">ping &lt;ip&gt;</span>&#xa0;&#xa0;# Проверка пингом
      </li>
    </ol>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node ID="ID_1097649137" CREATED="1519112079893" MODIFIED="1728463181413"><richcontent TYPE="NODE">

<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#000000">&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; (FreeBSD)</font>
    </p>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Инфо</b>
    </p>
    <p>
      <span style="color: #0000c0;">sockstat</span>&#xa0;&#xa0;# Поверка открытых портов
    </p>
    <p>
      
    </p>
    <p>
      <b><span style="color: #0000c0;"># ee /etc/hosts</span></b>
    </p>
    <p>
      <span style="color: #008000;">127.0.0.1&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;localhost&#xa0;&#xa0;&#xa0;localhost.any.com</span>
    </p>
    <p>
      <span style="color: #008000;">192.168.1.114&#xa0;&#xa0;&#xa0;c114.any.com&#xa0;&#xa0;&#xa0;c114</span>
    </p>
    <p>
      
    </p>
    <p>
      <b><span style="color: #0000c0;"># ee /etc/rc.conf</span>&#xa0;// стат. адрес, шлюз</b>
    </p>
    <p>
      <span style="color: #008000;">hostname=&quot;c114.any.com&quot;</span>
    </p>
    <p>
      <span style="color: #008000;">ifconfig_lo0=&quot;inet 127.0.0.1&quot;</span>&#xa0;# default loopback
    </p>
    <p>
      <span style="color: #008000;">ifconfig_em0=&quot;inet 192.168.1.114 netmask 255.255.255.0&quot; </span>
    </p>
    <p>
      <span style="color: #008000;">ifconfig_le0=&quot;inet 10.10.114.254 netmask 255.255.255.0&quot;</span>&#xa0;# inside
    </p>
    <p>
      <span style="color: #008000;">defaultrouter=&quot;192.168.1.254&quot; </span># gateway
    </p>
    <p>
      &#xa0;&#xa0; <b>или</b>&#xa0;
    </p>
    <p>
      <span style="color: #008000;">ifconfig_em0=&quot;DHCP&quot;</span>&#xa0;# все сетевые настройки берутся <b>с DHCP-сервера, если нужно!!!</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>Вручную (до перезагрузки)</b>
    </p>
    <p>
      <span style="color: #0000c0;"># ifconfig em0 inet 192.168.1.114 netmask 255.255.255.0 </span>
    </p>
    <p>
      <span style="color: #0000c0;"># route delete default; route add default 192.168.1.254 </span>
    </p>
    <p>
      
    </p>
    <p>
      <b><span style="color: #0000c0;"># ee /etc/resolv.conf</span>&#xa0;// DNS</b>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;domain any.com </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;nameserver 192.168.1.254 </span>//gateway или роутер
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;nameserver 8.8.8.8 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;"># /etc/rc.d/netif restart</span>&#xa0;// применяем скрипт (<b>перезагрузка сети</b>), если не помогло то <span style="color: #0000c0;"># reboot </span>
    </p>
    <p>
      <span style="color: #0000c0;"># /etc/rc.d/routing restart</span>&#xa0;// для поднятия маршрутов
    </p>
    <p>
      <span style="color: #0000c0;"># /etc/rc.d/hostname start</span>&#xa0;//
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">$ ping ya.ru </span>
    </p>
    <p>
      <span style="color: #0000c0;"># netstat -rn</span>&#xa0;// -r - routing table, -n - не преобраз. IP адреса в DNS имена
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Настройка Wi-Fi" ID="ID_1719273993" CREATED="1519112079893" MODIFIED="1776260602913"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1515473697">Wi-Fi</a>&#xa0; <a href="#ID_1962375635">NetworkManager</a>&#xa0;&#xa0;<a href="#ID_1665089832">snap</a>&#xa0;&#xa0;<a href="#ID_1478065537">iw</a>&#xa0;&#xa0;<a href="#ID_358757940">netplan (Wi-Fi подключение)</a>&#xa0;
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">NetworkManager</span>&#xa0;(Wi-Fi, VPN и др.)
      </li>
      <li>
        <b>NDISwrapper</b>&#xa0;- программный продукт, позволяющий использовать драйверы беспроводных устройств WiFi, предназначенные для ОС Microsoft Windows, в ОС Linux. Аналогичная программа для <span style="color: #ff0000;">FreeBSD</span>&#xa0;называется <b>NDISulator</b>. NDISwrapper включает в себя модуль ядра и утилиту для управления драйверами.
      </li>
      <li>
        <b>hostapd</b>&#xa0;- демон пользовательского пространства, позволяющая сетевой карте выступать в качестве точки доступа и сервера аутентификации.
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">apt install wireless-tools</span>&#xa0;&#xa0;# Установить пакет в Ubuntu
    </p>
    <p>
      <span style="color: #0000c0;">snap install wireless-tools</span>&#xa0;&#xa0;# Установить пакет в (RHEL 9,8,7) через <b>snap</b>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">iwconfig wlan0 essid &quot;Моя_сеть&quot; key s:mypassword</span>&#xa0;&#xa0;# Назначить SSID и пароль
    </p>
    <p>
      <span style="color: #0000c0;">iwlist</span>&#xa0;&#xa0;# Список доступных точек доступа к беспроводной сети
    </p>
    <p>
      <span style="color: #0000c0;">iwlist wlan0 scan</span>&#xa0;&#xa0;# <span style="color: #ff0000;">???</span>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        ifconfig&#xa0;- конфигурирование интерфейса беспроводной сети
      </li>
      <li>
        iwconfig - настройка параметров беспроводного соединения
      </li>
      <li>
        wpa_supplicant - аутентификация в беспроводной сети (или проводной сети 802.1x)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>Поиск драйверов</b>
    </p>
    <p>
      <span style="color: #0000c0;">lspci | grep -i wireless</span>&#xa0;&#xa0;# Ищем устройство, далее ищем драйвер на сайте производителя
    </p>
    <p>
      если драйвер на linux не нашли<b>...</b>
    </p>
    <p>
      <b>ndiswrapper</b>&#xa0;- http://ndiswrapper.sourceforge.net - пакет для установки <b>Windows</b>&#xa0;Wi-Fi драйверов на <b>Linux </b>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal;">--------------- </span>
    </p>
    <p>
      iwconfig wlp2s0 mode monitor&#xa0;&#xa0;# Переключиться в режим монитор. Перед этим выключить интерфейс (<span style="color: #0000c0;">ifconfig wlp2s0 down</span>)
    </p>
    <p>
      
    </p>
    <p>
      aircrack - перевод карты в режим мониторинга и не только
    </p>
    <p>
      airmon-ng&#xa0;&#xa0;# Список беспроводных интерфейсов
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
</node>
<node TEXT="Сетевой суперсервер (inetd)" FOLDED="true" ID="ID_187879647" CREATED="1519112079893" MODIFIED="1728300561550"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_510106601">/etc/hosts.allow</a>
    </p>
    <p>
      
    </p>
    <p>
      Настройка сетевого суперсервера <b>inetd</b>&#xa0;&#xa0;(<span style="color: #ff0000;">FreeBSD</span>)
    </p>
    <p>
      1. <span style="color: #0000c0;">#&#xa0;vi /etc/rc.conf</span>&#xa0;// разрешить запуск inetd
    </p>
    <p>
      <span style="color: #008000;">inetd_enable=&quot;YES&quot; </span>
    </p>
    <p>
      2. <span style="color: #0000c0;"># vi /etc/inetd.conf </span>// раскомментировать строку
    </p>
    <p>
      <span style="color: #008000;">telnet stream tcp nowait root /usr/libexec/telnetd telnetd</span>
    </p>
    <p>
      3. <span style="color: #0000c0;"># /etc/rc.d/inetd start</span>&#xa0;// запустить inetd
    </p>
    <p>
      4.&#xa0;<span style="color: #0000c0;"># sockstat -4 | grep :23</span>&#xa0;// поверить, что порт 23 открыт на прослушивание:
    </p>
    <p>
      5.1 C:\&gt; telnet 192.168.1.114 // Проверка работоспособности telnet-сервера.
    </p>
    <p>
      5.2 <span style="color: #0000c0;"># vi /etc/hosts.allow</span>&#xa0;// Проверка ограничения доступа к сервису при помощи tcpd
    </p>
    <p>
      <span style="color: #008000;">telnetd: IP1 : allow </span># IP1 - откуда<span style="color: #008000;">&#xa0;&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000;">telnetd : ALL : deny </span># первой строкой
    </p>
    <p>
      5.3 C:\&gt; telnet 192.168.1.114
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
