    <p>
      <a href="#ID_575466038">Мониторинг</a>&#xa0; <a href="#ID_762231132">Диагностика (сеть)</a>&#xa0;&#xa0;<a href="#ID_702415289">sos report</a>&#xa0;&#xa0;<a href="#ID_1940847259">strace</a>&#xa0;&#xa0;dmesg &#xa0;<a href="#ID_1429760730">форк-бомба</a>&#xa0; <a href="#ID_1137058503">OOM killer</a>&#xa0; <a href="#ID_244779432">lsof</a>&#xa0;&#xa0;<a href="#ID_664200592">fuser</a>&#xa0;&#xa0;<a href="#ID_1834961192">ldd</a><span style="font-weight: bold;">&#xa0;</span>&#xa0;<a href="#ID_866665722">gdb</a>&#xa0;
    </p>
