<node ID="ID_1122112879" CREATED="1519112079904" MODIFIED="1586513300601"><richcontent TYPE="NODE">

<html>
  <head>
    
  </head>
  <body>
    <p>
      /rc.conf (<font color="#ff0000">FreeBSD</font>)
    </p>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0"># ee /etc/rc.conf</font>
    </p>
    <p>
      <font color="#008000">font8x14=&quot;cp866-8x14&quot;</font>&#160;# cirilic (4 lines)
    </p>
    <p>
      <font color="#008000">font8x16=&quot;cp866b-8x16&quot;</font>
    </p>
    <p>
      <font color="#008000">font8x8=&quot;cp866-8x8&quot;</font>
    </p>
    <p>
      <font color="#008000">scrnmap=&quot;koi8-r2cp866&quot;</font>&#160;# &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1087;&#1088;&#1080; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1080;
    </p>
    <p>
      <font color="#008000">keymap=&quot;ru.koi8-r&quot;</font>&#160;# keyboard layout
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">keyrate=&quot;fast&quot;</font>&#160;# keyboard speed
    </p>
    <p>
      <font color="#008000">linux_enable=&quot;YES&quot;</font>&#160;# &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; &#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1089; Linux. &#1042; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1077; compat &#1084;&#1086;&#1078;&#1085;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1083;&#1080;&#1085;&#1091;&#1082;&#1089;&#1086;&#1074;&#1099;&#1077; &#1073;&#1080;&#1085;&#1072;&#1088;&#1085;&#1080;&#1082;&#1080; &#1076;&#1083;&#1103; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;, &#1085;&#1072;&#1087;&#1080;&#1089;. &#1087;&#1086;&#1076; &#1083;&#1080;&#1085;&#1091;&#1082;&#1089;
    </p>
    <p>
      <font color="#008000">mousechar_start=&quot;3&quot;</font>&#160;# &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; 3&#1093;-&#1082;&#1085;&#1086;&#1087;&#1086;&#1095;&#1085;&#1086;&#1081; &#1084;&#1099;&#1096;&#1080;
    </p>
    <p>
      <font color="#008000">saver=&quot;daemon&quot;</font>&#160;# <b>screensaver daemon with forks</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">gateway_enable=&quot;YES&quot;</font>&#160;# &#1101;&#1090;&#1072; &#1084;&#1072;&#1096;&#1080;&#1085;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1096;&#1083;&#1102;&#1079;&#1086;&#1084;
    </p>
    <p>
      <font color="#008000">sshd_enable=&quot;YES&quot;</font>&#160;# &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; SSH &#1076;&#1077;&#1084;&#1086;&#1085;&#1072; &#1076;&#1083;&#1103; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#008000">ifconfig_lo0=&quot;inet 127.0.0.1&quot;</font>&#160;# default loopback
    </p>
    <p>
      <font color="#008000">ifconfig_em0=&quot;inet 192.168.1.114 netmask 255.255.255.0&quot;</font>
    </p>
    <p>
      <font color="#008000">ifconfig_le0=&quot;inet 10.10.114.254 netmask 255.255.255.0&quot;</font>&#160;# &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081;
    </p>
    <p>
      <font color="#008000">defaultrouter=&quot;192.168.1.254&quot; </font># gateway
    </p>
    <p>
      <font color="#008000">hostname=&quot;c14.any.com&quot;</font>&#160;# computer name
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"># apache22_enable=&quot;YES&quot; </font>
    </p>
    <p>
      <font color="#008000"># inetd_enable=&quot;YES&quot; # </font>&#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082; &#1089;&#1091;&#1087;&#1077;&#1088;&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; inetd
    </p>
    <p>
      <font color="#008000"># ftpd_enable=&quot;YES&quot; # </font>&#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082; FTP-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># /etc/rc.d/netif restart</font>&#160;// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; (<b>&#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1089;&#1077;&#1090;&#1080;</b>), &#1077;&#1089;&#1083;&#1080; &#1085;&#1077; &#1087;&#1086;&#1084;&#1086;&#1075;&#1083;&#1086; &#1090;&#1086; <font color="#0000c0"># reboot</font>
    </p>
  </body>
</html></richcontent>
