    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">service port/protocol [aliases]</font>
    </p>
    <ul>
      <li>
        service &#1079;&#1072;&#1076;&#1072;&#1077;&#1090; &#1080;&#1084;&#1103; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1072;
      </li>
      <li>
        port &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1085;&#1086;&#1084;&#1077;&#1088; &#1087;&#1086;&#1088;&#1090;&#1072;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1086;&#1075;&#1086; &#1101;&#1090;&#1080;&#1084; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1086;&#1084;
