      </li>
      <li>
        mark - &#1082;&#1072;&#1090;&#1077;&#1075;&#1086;&#1088;&#1080;&#1103; &#1080;&#1089;&#1087;. &#1076;&#1077;&#1084;&#1086;&#1085;&#1086;&#1084; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072; (&#1082;&#1086;&#1075;&#1076;&#1072; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090;)
      </li>
      <li>
