      </li>
      <li>
        syslog - &#1082;&#1072;&#1090;&#1077;&#1075;&#1086;&#1088;&#1080;&#1103; &#1080;&#1089;&#1087;. &#1076;&#1077;&#1084;&#1086;&#1085;&#1086;&#1084; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072; (&#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1076;&#1077;&#1084;&#1086;&#1085;&#1072; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072;)
      </li>
      <li>
