<node TEXT="Рекомендации" ID="ID_958061025" CREATED="1533729347619" MODIFIED="1533729395924"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        &#1076;&#1077;&#1084;&#1086;&#1085; syslogd &#1074; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077; &#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1080;&#1074;&#1086;&#1074; Linux &#1086;&#1090;&#1082;&#1072;&#1078;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1086;&#1090; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1085; &#1085;&#1077; &#1073;&#1099;&#1083; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085; &#1089; &#1092;&#1083;&#1072;&#1075;&#1086;&#1084; -r.
      </li>
      <li>
        &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1076;&#1077;&#1084;&#1086;&#1085; &#1090;&#1072;&#1082;&#1078;&#1077; &#1086;&#1090;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1099;&#1089;&#1090;&#1091;&#1087;&#1072;&#1090;&#1100; &#1074; &#1088;&#1086;&#1083;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1075;&#1086; &#1076;&#1080;&#1089;&#1087;&#1077;&#1090;&#1095;&#1077;&#1088;&#1072; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081;: &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1102;&#1097;&#1080;&#1077; &#1086;&#1090; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1075;&#1086; &#1091;&#1079;&#1083;&#1072;, &#1085;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1089;&#1083;&#1072;&#1085;&#1099; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1091;&#1079;&#1077;&#1083;. &#1060;&#1083;&#1072;&#1075; -h &#1086;&#1090;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090; &#1090;&#1072;&#1082;&#1086;&#1077; &#1087;&#1086;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1101;&#1090;&#1080; &#1086;&#1087;&#1094;&#1080;&#1080; &#1073;&#1099;&#1083;&#1080; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1099;, &#1084;&#1086;&#1076;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084; &#1089;&#1094;&#1077;&#1085;&#1072;&#1088;&#1080;&#1081; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; syslog. &#1042; RHEL &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; syslog &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1086;&#1090;&#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074; /etc/sysconfig/syslog
      </li>
