    </p>
    <p>
      /proc/sys/net/ipv4&#160; <b>conf/default/rp_filter</b>&#160;&#160;&#1042;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072; &#1082; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1092;&#1072;&#1081;&#1083;&#1091;. &#1069;&#1090;&#1086;&#1090; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084; &#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103; &#1080;&#1084;&#1080;&#1090;&#1072;&#1094;&#1080;&#1080; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081; &#1074;&#1099;&#1085;&#1091;&#1078;&#1076;&#1072;&#1077;&#1090; &#1103;&#1076;&#1088;&#1086; &#1085;&#1077; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1103; &#1085;&#1072; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1087;&#1086; &quot;&#1053;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1099;&#1084;&#8221; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1084;
    </p>
    <p>
      /proc/sys/net/ipv4&#160;&#160;<b>icmp_echo_ignore_all</b>&#160;&#160;&#1047;&#1072;&#1076;&#1072;&#1077;&#1090; &#1080;&#1075;&#1085;&#1086;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; ICMP-&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1088;&#1072;&#1074;&#1077;&#1085; 1
    </p>
    <p>
      /proc/sys/net/ipv4&#160;&#160;<b>icmp_echo_ignore_broadcasts</b>&#160;&#160;&#1047;&#1072;&#1076;&#1072;&#1077;&#1090; &#1080;&#1075;&#1085;&#1086;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1074;&#1077;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; ICMP-&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1088;&#1072;&#1074;&#1077;&#1085; 1. &#1055;&#1088;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1074;&#1086; &#1074;&#1089;&#1077;&#1093; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1103;&#1093; &#1094;&#1077;&#1083;&#1077;&#1089;&#1086;&#1086;&#1073;&#1088;&#1072;&#1079;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1101;&#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1074;&#1085;&#1099;&#1084; 1
    </p>
    <p>
      /proc/sys/net/ipv4&#160; <b>ip_forward</b>&#160;&#160;&#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; IP-&#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1088;&#1072;&#1074;&#1077;&#1085; 1. &#1045;&#1089;&#1083;&#1080; &#1078;&#1077; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088; Linux &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;, &#1101;&#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1088;&#1072;&#1074;&#1085;&#1099;&#1084; 1
    </p>
    <p>
      /proc/sys/net/ipv4&#160; <b>ip_local_port_range</b>&#160;&#160;&#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074;, &#1074;&#1099;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084;&#1099;&#1081; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;. &#1044;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086; &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1074;&#1099;&#1089;&#1080;&#1090;&#1100; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1080;&#1085;&#1080;&#1094;&#1080;&#1080;&#1088;&#1091;&#1102;&#1090; &#1084;&#1085;&#1086;&#1075;&#1086; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081;, &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1080;&#1090;&#1100; &#1076;&#1086; 1024-65000
    </p>
    <p>
      /proc/sys/net/ipv4&#160; <b>tcp_fin_timeout</b>&#160;&#160;&#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1103; (&#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1072;&#1093;) &#1079;&#1072;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072; FIN.
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086; &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1074;&#1099;&#1089;&#1080;&#1090;&#1100; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074;, &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1080;&#1090; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1086;&#1073;&#1098;&#1077;&#1084; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;, &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1073;&#1086;&#1083;&#1077;&#1077; &#1085;&#1080;&#1079;&#1082;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; (&#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1072; 20)
    </p>
    <p>
      /proc/sys/net/ipv4&#160; <b>tcp_syncookies</b>&#160;&#160;&#1047;&#1072;&#1097;&#1080;&#1097;&#1072;&#1077;&#1090; &#1086;&#1090; &#1072;&#1090;&#1072;&#1082; &#1074;&#1086;&#1083;&#1085;&#1086;&#1074;&#1086;&#1075;&#1086; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; SYN. &#1069;&#1090;&#1086;&#1090; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1080; &#1087;&#1086;&#1076;&#1086;&#1079;&#1088;&#1077;&#1085;&#1080;&#1103; &#1086; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1080; &#1072;&#1090;&#1072;&#1082; &#1086;&#1090;&#1082;&#1072;&#1079;&#1072; &#1086;&#1090; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; (DOS).
    </p>
  </body>
</html></richcontent>
</node>
</node>
</node>
<node TEXT="Локализация" ID="ID_766609125" CREATED="1519112079912" MODIFIED="1742032337038"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">locale -a</span>&#xa0;&#xa0;# зыковые и региональные настройки доступные для использования в текущей системе
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/locale.gen</span>&#xa0;&#xa0;# Раскомментировать строку ru_RU.UTF-8 UTF-8
    </p>
    <p>
      <span style="color: #0000c0;">locale-gen</span>&#xa0;&#xa0;# Сгенерировать файлы локализации.
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #ff0000;">FreeBSD</span>
    </p>
    <p>
      <span style="color: #0000c0;"># ee /etc/rc.conf</span>
    </p>
    <p>
      <span style="color: #008000;">font8x14=&quot;cp866-8x14&quot;</span>&#xa0;# cirilic (4 lines)
    </p>
    <p>
      <span style="color: #008000;">font8x16=&quot;cp866b-8x16&quot;</span>
    </p>
    <p>
      <span style="color: #008000;">font8x8=&quot;cp866-8x8&quot;</span>
    </p>
    <p>
      <span style="color: #008000;">scrnmap=&quot;koi8-r2cp866&quot;</span>&#xa0;# преобразование кодировки при отображении
    </p>
    <p>
      <span style="color: #008000;">keymap=&quot;ru.koi8-r&quot;</span>&#xa0;# keyboard layout
    </p>
    <p>
      <span style="color: #0000c0;"># setenv LANG ru_RU.KOI8-R</span>&#xa0;// устанавливаем язык на котором работают приложения
    </p>
    <p>
      <span style="color: #0000c0;">$ LANG=ru_RU.UTF-8</span>&#xa0;// меняем текущее значение переменной на текущую сессию
    </p>
    <p>
      <span style="color: #0000c0;"># pw usermod root -L russian</span>&#xa0;// язык будет автоматически цепляться при загрузке. ссылка на логин класс прописывается в <b>/etc/master.passwd </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>Перекодировка имен файлов в текущей директории. Ф</b>айлы с битой кодировкой будут перекодированы, а файлы с ascii-символами изменений не претерпят. Чтобы осуществить правильное перекодирование нужно знать две кодировки. Если вы встретили такие символы в примонтированном media-носителе или смонтированном разделе Windows, не спешите ничего перекодировать. Возможно, вы просто указали неправильные опции монтирования.
    </p>
    <p>
      <span style="color: #0000c0;">convmv -f&lt;кодировка&gt; -tutf8 *</span>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Мониторинг системы" FOLDED="true" ID="ID_575466038" CREATED="1519112079912" MODIFIED="1791116632713"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1150979754"><span style="font-size: 10pt;">PSI</span></a><span style="font-size: 10pt;">&#xa0; <a href="#ID_780527781">while (bash)</a>&#xa0; </span><a href="#ID_340865204">top</a>&#xa0; <a href="#ID_1088619634">htop</a>&#xa0;&#xa0;<a href="#ID_722456128">ps</a>&#xa0;&#xa0;<a href="#ID_805358430">vmstat</a>&#xa0; <a href="#ID_698021239">free</a>&#xa0;&#xa0;<a href="#ID_1045382812">netstat</a><span style="color: #0000c0;">&#xa0; </span><a href="#ID_1453020797">tail</a>&#xa0;&#xa0;<a href="#ID_877681376">sysstat</a>&#xa0;&#xa0;<a href="#ID_309241748">iostat</a>&#xa0;&#xa0;<a href="#ID_1923317447">sar</a>&#xa0; <a href="#ID_171503298">systemctl</a>&#xa0;&#xa0;<a href="#ID_244779432">lsof</a>&#xa0;&#xa0;<a href="#ID_1845006519">Диагностика</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Общее состояние и нагрузка</span>
    </p>
    <p>
      <span style="color: #0000c0;">uptime</span>&#xa0;&#xa0;# Время работы, число пользователей, load average. Load average (средняя нагрузка):
    </p>
    <ul>
      <li>
        На одноядерной системе:

        <ul>
          <li>
            ≈ 0 - простой
          </li>
          <li>
            ≈ 1 - 100% загрузка без очереди
          </li>
          <li>
            &gt; 1 - есть очередь процессов
          </li>
        </ul>
      </li>
      <li>
        На N-ядерной системе: делить значение на N.
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">cat /proc/loadavg</span>&#xa0;&#xa0;# Текущая средняя нагрузка (1/5/15 мин)
    </p>
    <p>
      <span style="color: #0000c0;">w</span>&#xa0;&#xa0;# Активные пользователи + load average
    </p>
    <p>
      <span style="color: #0000c0;">htop</span>&#xa0;&#xa0;# Интерактивный монитор процессов (лучше top)
    </p>
    <p>
      <span style="color: #0000c0;">top</span>&#xa0;&#xa0;# Стандартный монитор процессов (M - сортировка по памяти)
    </p>
    <p>
      <span style="color: #0000c0;">systemd-cgtop</span>&#xa0;&#xa0;# Интерактивный мониторинг потребления ресурсов (CPU, Memory, I/O) группами в реальном времени
    </p>
    <p>
      <span style="color: #0000c0;">nmon</span>&#xa0;&#xa0;# Комплексный мониторинг (CPU, память, диск, сеть)
    </p>
    <p>
      <span style="color: #0000c0;">sar 1 3</span>&#xa0;&#xa0;# Статистика подсистем (требует пакет sysstat).&#xa0;&#xa0;Трижды с интервалом в 1 секунду
    </p>
    <p>
      <span style="color: #0000c0;">vmstat 2 5</span>&#xa0;&#xa0;# Общая статистика (процессы, память, своп, I/O, CPU). 5 раз с интервалом 2 сек
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Память</span>
    </p>
    <p>
      <span style="color: #0000c0;">free -m -s 1</span>&#xa0;&#xa0;# Объём RAM/Swap в MB с обновлением раз в секунду
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/meminfo</span>&#xa0;&#xa0;# Подробная информация о памяти
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/buddyinfo</span>&#xa0;&#xa0;# Фрагментация памяти в ядре
    </p>
    <p>
      pmap &lt;PID&gt;&#xa0;&#xa0;# Распределение памяти конкретного процесса
    </p>
    <p>
      <span style="color: #0000c0;">vmstat -s</span>&#xa0;&#xa0;# Подробная статистика по виртуальной памяти
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Процессы</span>
    </p>
    <p>
      <span style="color: #0000c0;">ps auxwwf</span>&#xa0;&#xa0;# Дерево процессов всех пользователей (полные команды)
    </p>
    <p>
      <span style="color: #0000c0;">ps -u &lt;UID&gt; -o pid= | xargs kill -9</span>&#xa0;&#xa0;&#xa0;# Убить процессы по UID
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Выполнение команды с периодичностью:</span>
    </p>
    <p>
      <span style="color: #0000c0;">watch -n1 -d 'du -h file0'</span>&#xa0;&#xa0;# Слежение за размером файла с подсветкой изменений
    </p>
    <p>
      <span style="color: #0000c0;">while sleep 1; do uptime &gt;&gt; log.txt; done</span>&#xa0;&#xa0;# <b>Запись</b>&#xa0;лога в файл
    </p>
    <p>
      <span style="color: #0000c0;">while sleep 1; do clear; iostat -d /dev/sda; done </span>
    </p>
    <p>
      <span style="color: #0000c0;">while true; do uptime 2&gt;&amp;1 | tee -a log.txt; sleep 2; done </span>
    </p>
    <p>
      <span style="color: #0000c0;">time sleep 5</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Измерить&#xa0;&#xa0;время</span>&#xa0;выполнения команды
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Файловые системы и диски</span>
    </p>
    <p>
      <span style="color: #0000c0;">df -hT</span>&#xa0;&#xa0;# Свободное место на всех ФС (с типами)
    </p>
    <p>
      <span style="color: #0000c0;">du -sch /home/*</span>&#xa0;&#xa0;# Размер каталогов в /home с итогом
    </p>
    <p>
      <span style="color: #0000c0;">du -s /* | sort -n</span>&#xa0;&#xa0;# Размер корневых каталогов по возрастанию
    </p>
    <p>
      <span style="color: #0000c0;">du -d 1 /usr/share/</span>&#xa0;&#xa0;# Размер подкаталогов на глубине 1
    </p>
    <p>
      <span style="color: #0000c0;">iotop</span>&#xa0;&#xa0;# Дисковая активность по процессам (требует root)
    </p>
    <p>
      <span style="color: #0000c0;">iostat -xk 1</span>&#xa0;&#xa0;# Подробная статистика дисковых операций. Частота обновления 1 сек.
    </p>
    <p>
      <span style="color: #0000c0;">smartctl -a /dev/sda</span>&#xa0;&#xa0;# SMART-данные диска (включая reallocated sectors)
    </p>
    <p>
      <span style="color: #0000c0;">lsof +D /var/log/</span>&#xa0;&#xa0;# Процессы, использующие файлы в каталоге
    </p>
    <p>
      <span style="color: #0000c0;">lsof /path/to/file</span>&#xa0;&#xa0;# Какой процесс открыл файл
    </p>
    <p>
      <span style="color: #0000c0;">lsof -c ssh</span>&#xa0;&#xa0;# Файлы, открытые процессами с именем ssh
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Сеть</span>
    </p>
    <p>
      <span style="color: #0000c0;">netstat -i</span>&#xa0;&#xa0;# Статистика по сетевым интерфейсам
    </p>
    <p>
      <span style="color: #0000c0;">netstat -s &gt; /tmp/report</span>&#xa0;&#xa0;# Подготовка отчета&#xa0;для руководства&#xa0;&#xa0;&#xa0;:)
    </p>
    <p>
      <span style="color: #0000c0;">ip -s link show</span>&#xa0;&#xa0;# Статистика (ошибки, пакеты) по интерфейсам
    </p>
    <p>
      <span style="color: #0000c0;">ip -s address show</span>&#xa0;&#xa0;# Статистика по IP-адресам
    </p>
    <p>
      <span style="color: #0000c0;">ip route show</span>&#xa0;&#xa0;# Таблица маршрутизации
    </p>
    <p>
      <span style="color: #0000c0;">ss -tuln</span>&#xa0;&#xa0;# Современная замена netstat для сокетов (быстрее)
    </p>
    <p>
      <span style="color: #0000c0;">iftop</span>&#xa0;&#xa0;# live-мониторинг трафика по соединениям (как top для сети)
    </p>
    <p>
      <span style="color: #0000c0;">nethogs</span>&#xa0;&#xa0;# группирует трафик по процессам (полезно при неизвестном источнике нагрузки)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Логирование и журналы</span>
    </p>
    <p>
      <span style="color: #0000c0;">tail -f /var/log/syslog &amp;</span>&#xa0;&#xa0;# Слежение за логом в фоне
    </p>
    <p>
      <span style="color: #0000c0;">journalctl -f</span>&#xa0;&#xa0;# Онлайн-просмотр журналов systemd
    </p>
    <p>
      <span style="color: #0000c0;">last -a</span>&#xa0;&#xa0;# История входов (данные из /var/log/wtmp)
    </p>
    <p>
      <span style="color: #0000c0;">lastlog</span>&#xa0;&#xa0;# Последний вход каждого пользователя
    </p>
    <p>
      Журналы пакетного менеджера: <span style="font-weight: bold;">/var/log/dpkg.log</span>&#xa0;- все действия apt, dpkg и т.п.
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Управление сервисами (systemd)</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl list-unit-files --type=service</span>&#xa0;&#xa0;# Все сервисы (включён/отключён)
    </p>
    <p>
      <span style="color: #0000c0;">systemctl status &lt;service&gt;</span>&#xa0;&#xa0;# Состояние конкретного сервиса
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Память" FOLDED="true" ID="ID_197604312" CREATED="1722861642678" MODIFIED="1779692602599"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_768518816">Память</a>&#xa0;&#xa0;<a href="#ID_963917846">SWAP (подкачка)</a>&#xa0;&#xa0;<a href="#ID_1137058503">OOM killer</a>&#xa0; <a href="#ID_1442872263">RAM</a>&#xa0;&#xa0;<a href="#ID_1941889320">xclip</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">free -m -s1</span>&#xa0;&#xa0;# <b>Память</b>&#xa0;RAM и Swap. s1-обновлять ежесекундно, -m - MB
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/meminfo</span>&#xa0;&#xa0;# инфо о памяти
    </p>
    <p>
      <span style="color: #0000c0;">lsmem</span>
    </p>
    <p>
      <span style="color: #0000c0;">top</span>&#xa0;&#xa0;# Нажать М - сортировка по используемой памяти
    </p>
    <p>
      <span style="color: #0000c0;">htop</span>
    </p>
    <p>
      <span style="color: #0000c0;">ps aux</span>
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/buddyinfo</span>&#xa0;&#xa0;# Информация о фрагментации памяти в ядре Linux
    </p>
    <p>
      <span style="color: #0000c0;">pmap &lt;PID&gt;</span>&#xa0;&#xa0;# Использование памяти процессом
    </p>
    <p>
      <span style="color: #0000c0;">vmstat</span>&#xa0;&#xa0;# Статистика виртуальной памяти
    </p>
    <p>
      <span style="color: #0000c0;">vmstat&#xa0;&#xa0;1</span>&#xa0;&#xa0;# Статистика использования памяти с обновлением каждую секунду
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/&lt;PID&gt;/status</span>&#xa0;&#xa0;# Посмотреть
    </p>
    <p>
      <span style="color: #0000c0;">sar</span>&#xa0;&#xa0;# Мониторинг памяти
    </p>
    <ul>
      <li>
        -B: paging statistics
      </li>
      <li>
        -r: memory utilization
      </li>
      <li>
        -R memory statistics
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Смотрим VMA</span>
    </p>
    <p>
      <span style="color: #0000c0;">pmap -x &lt;PID&gt;</span>
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/&lt;PID&gt;/maps</span>&#xa0;&#xa0;# Кратко
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/&lt;PID&gt;/smaps</span>&#xa0;&#xa0;# Подробно
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">echo 3 &gt; /proc/sys/vm/drop_caches</span>&#xa0;&#xa0;# Принудительная <span style="font-weight: bold;">очистка кэша&#xa0;оперативной памяти</span>&#xa0;(включая системный кэш страниц, записи каталогов (dentries) и индексные дескрипторы (inodes))
    </p>
    <p>
      уровни очистки:
    </p>
    <ul>
      <li>
        echo <span style="font-weight: bold;">1</span>&#xa0;&gt; ... - освобождает pagecache (кэш страниц, где хранятся файлы, прочитанные с диска)
      </li>
      <li>
        echo <span style="font-weight: bold;">2</span>&#xa0;&gt; ... - освобождает dentries и inodes (метаданные файловой системы: структуры каталогов и информацию о файлах)
      </li>
      <li>
        echo <span style="font-weight: bold;">3</span>&#xa0;&gt; ... - совмещает оба действия и полностью очищает все виды кэша и метаданных
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      --------------
    </p>
    <p>
      numactl
    </p>
    <p>
      vmtouch - сколько страниц в Page Cache
    </p>
    <p>
      mincore - системный вызов позволяет посмотреть находятся ли страницы файла в Page Cache
    </p>
    <p>
      
    </p>
    <p>
      Память процесса (сегменты):
    </p>
    <p>
      stack
    </p>
    <p>
      mmap
    </p>
    <p>
      heap
    </p>
    <p>
      bss
    </p>
    <p>
      init data
    </p>
    <p>
      text
    </p>
  </body>
</html></richcontent>
<node TEXT="Huge Pages (Huge Tables)" FOLDED="true" ID="ID_1721328375" CREATED="1744533509384" MODIFIED="1744534654093"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Huge Pages (также Huge Tables или HugeTLB)</span>&#xa0;- механизм, позволяющий использовать страницы памяти большого размера (обычно 2 МБ или 1 ГБ вместо стандартных 4 КБ). Это снижает нагрузку на <span style="font-weight: bold;">TLB (Translation Lookaside Buffer)</span>&#xa0;и уменьшает количество page faults, что может значительно ускорить работу приложений с большим объемом памяти.
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Почему Huge Pages не включены по умолчанию?</span>
    </p>
    <p>
      <span style="font-weight: bold;">1. Ограниченность ресурсов</span>
    </p>
    <ul>
      <li>
        Huge Pages резервируются в физической памяти заранее и <span style="font-weight: bold;">не могут быть swapped</span>&#xa0;(выгружены на диск)
      </li>
      <li>
        Если системе не хватает памяти, это может привести к неэффективному использованию RAM
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">2. Фрагментация памяти</span>
    </p>
    <ul>
      <li>
        Большие страницы требуют непрерывных блоков физической памяти
      </li>
      <li>
        После долгой работы системы может не хватить непрерывных областей для выделения Huge Pages
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">3. Не все приложения выигрывают</span>
    </p>
    <ul>
      <li>
        Обычные приложения (веб-серверы, CLI-утилиты) не всегда получают преимущество
      </li>
      <li>
        Huge Pages полезны в основном <span style="font-weight: bold;">для СУБД</span>&#xa0;(Oracle, PostgreSQL, MySQL), <span style="font-weight: bold;">виртуализации</span>&#xa0;(KVM, QEMU) и высокопроизводительных вычислений (HPC)
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">4. Сложность настройки</span>
    </p>
    <ul>
      <li>
        Требует ручной конфигурации (например, через sysctl или echo в /proc/sys/vm/nr_hugepages)
      </li>
      <li>
        Некоторые приложения (например, Java) требуют явного указания использования Huge Pages (-XX:+UseLargePages)
      </li>
    </ul>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="Когда использовать" ID="ID_1235906409" CREATED="1744534616837" MODIFIED="1744534642452"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Когда использовать Huge Pages? </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Базы данных (Oracle, PostgreSQL, MySQL, MongoDB)</span>
    </p>
    <ul>
      <li>
        Уменьшают накладные расходы на управление памятью, ускоряют выполнение запросов
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">2. Виртуализация (KVM, QEMU)</span>
    </p>
    <ul>
      <li>
        Гостевые ОС работают быстрее, так как уменьшается количество TLB misses
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">3. Высокопроизводительные вычисления (HPC, научные расчеты)</span>
    </p>
    <ul>
      <li>
        &#xa0;Приложения, работающие с большими массивами данных (например, моделирование, машинное обучение).
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">4. Серверы с большим объемом RAM</span>
    </p>
    <ul>
      <li>
        Если система имеет 64+ ГБ ОЗУ, Huge Pages могут значительно улучшить производительность
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Настройка" ID="ID_1490194558" CREATED="1744534623700" MODIFIED="1744534985558"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Как включить Huge Pages? </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Проверить текущие настройки</span>
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/meminfo | grep Huge&#xa0;&#xa0;# </span>Вывод:
    </p>
    <p>
      <span style="font-family: Lucida Console;">HugePages_Total:&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">HugePages_Free:&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">HugePages_Rsvd:&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">HugePages_Surp:&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Hugepagesize:&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;2048 kB</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Выделить Huge Pages (например, 1024 страницы по 2 МБ)</span>
    </p>
    <p>
      <span style="color: #0000c0;">echo 1024 &gt; /proc/sys/vm/nr_hugepages</span>
    </p>
    <p>
      <span style="color: #0000c0;">sysctl vm.nr_hugepages=1024</span>&#xa0;&#xa0;# Или через sysctl
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. Закрепить настройки (в /etc/sysctl.conf`)</span>
    </p>
    <p>
      <span style="color: #0000c0;">echo &quot;vm.nr_hugepages = 1024&quot; &gt;&gt; /etc/sysctl.conf </span>
    </p>
    <p>
      <span style="color: #0000c0;">sysctl -p</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">4. Настроить приложение (например, PostgreSQL)</span>
    </p>
    <p>
      <span style="color: #0000c0;">vim postgresql.conf</span>
    </p>
    <p>
      <span style="color: #008000;">huge_pages = on</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="OOM killer" ID="ID_1137058503" CREATED="1743083660095" MODIFIED="1756055918119"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Когда в системе не хватает памяти (<span style="font-weight: bold;">Out of Memory, OOM</span>), ядро активирует механизм <span style="font-weight: bold;">OOM killer</span>&#xa0;(<span style="font-weight: bold;">Out-of-Memory Killer</span>), который принудительно завершает процессы, чтобы освободить память и предотвратить крах системы
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Как работает OOM killer?</span>
    </p>
    <p>
      1. Система исчерпывает память
    </p>
    <ul>
      <li>
        Когда свободной памяти (RAM + swap) почти не остаётся, ядро пытается освободить её через кеши и буферы
      </li>
      <li>
        Если это не помогает, срабатывает OOM killer
      </li>
    </ul>
    <p>
      2. Выбор жертвы
    </p>
    <ul>
      <li>
        OOM killer оценивает процессы по &quot;плохости&quot; (<span style="font-weight: bold;">badness score</span>) и убивает самый &quot;плохой&quot;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Как вычисляется &quot;плохость&quot; (badness score) процесса? </span>Ядро использует эвристику, учитывая:&#xa0;
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">Потребление памяти</span>&#xa0;- чем больше памяти использует процесс, тем выше его шансы быть убитым
      </li>
      <li>
        <span style="font-weight: bold;">Приоритет</span>&#xa0;(oom_score_adj и oom_adj) - чем выше значение (до +1000), тем вероятнее, что процесс будет выбран

        <ul>
          <li>
            Значения можно настроить через <span style="font-weight: bold;">/proc/&lt;pid&gt;/oom_score_adj</span>
          </li>
          <li>
            -1000 (никогда не убивать)
          </li>
          <li>
            +1000 (убить в первую очередь)
          </li>
        </ul>
      </li>
      <li>
        Время работы - долгоживущие процессы имеют меньший шанс быть убитыми
      </li>
      <li>
        Привилегии - root-процессы имеют небольшой &quot;бонус&quot; к выживанию
      </li>
      <li>
        Количество дочерних процессов - если процесс породил много потомков, он более &quot;опасен&quot;
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">cat /proc/&lt;pid&gt;/oom_score</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Проверить</span>&#xa0;oom_score процесса
    </p>
    <p>
      <span style="color: #0000c0;">echo -1000 &gt; /proc/&lt;pid&gt;/oom_score_adj</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Запретить</span>&#xa0;убивать процесс
    </p>
    <p>
      <span style="color: #0000c0;">echo 1000 &gt; /proc/&lt;pid&gt;/oom_score_adj</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Принудительно убить</span>&#xa0;процесс при OOM
    </p>
    <p>
      <span style="color: #0000c0;">choom -p &lt;pid&gt; -n -1000</span>&#xa0;&#xa0;# Максимально повысить приоритет (защиту) процесса
    </p>
    <p>
      <span style="color: #0000c0;">sysctl vm.oom-kill = 0</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Отключить OOM killer </span>(не рекомендуется!). Лучше увеличить swap или оптимизировать память
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Логи</span>
    </p>
    <p>
      <span style="color: #0000c0;">dmesg | grep -i &quot;oom&quot; </span>
    </p>
    <p>
      <span style="color: #0000c0;">journalctl -k --grep=&quot;oom&quot;</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Ограничение памяти процесса" ID="ID_838122503" CREATED="1742477258084" MODIFIED="1742478987473"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1937502333"><span style="font-weight: normal;">ulimit</span></a>&#xa0; <a href="#ID_1876019531">cgroups</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. ulimit&#xa0;позволяет ограничить ресурсы для текущей сессии</span>
    </p>
    <p>
      <span style="color: #0000c0;">ulimit -v &lt;лимит_в_КБ&gt;</span>&#xa0;&#xa0;# Ограничить макс. объем виртуальной памяти для текущей сессии
    </p>
    <p>
      <span style="color: #0000c0;">ulimit -m &lt;лимит_в_КБ&gt;</span>&#xa0;&#xa0;# Ограничить макс. объем резидентной памяти (RSS)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Использование cgroups&#xa0;(Control Groups)</span>
    </p>
    <p>
      <span style="color: #0000c0;">apt install cgroup-tools</span>
    </p>
    <p>
      <span style="color: #0000c0;">cgcreate -g memory:/mygroup</span>&#xa0;&#xa0;# Создайте новую группу
    </p>
    <p>
      <span style="color: #0000c0;">echo &lt;лимит_в_байтах&gt; | sudo tee /sys/fs/cgroup/memory/mygroup/memory.limit_in_bytes</span>&#xa0;&#xa0;# Установите лимит памяти
    </p>
    <p>
      <span style="color: #0000c0;">cgexec -g memory:mygroup &lt;команда&gt;</span>&#xa0;&#xa0;# Добавьте процесс в группу
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">3. Использование systemd</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl edit &lt;имя_службы&gt;</span>&#xa0;&#xa0;# Создайте юнит-файл
    </p>
    <p>
      <span style="color: #008000;">[Service] </span>
    </p>
    <p>
      <span style="color: #008000;">MemoryMax=500M </span>
    </p>
    <p>
      <span style="color: #008000;">MemoryHigh=400M </span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl daemon-reload</span>&#xa0;&#xa0;# Перезагрузите конфигурацию
    </p>
    <p>
      <span style="color: #0000c0;">systemctl restart &lt;имя_службы&gt;</span>&#xa0;&#xa0;# Перезапустите службу
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">4. Использование docker (если процесс запущен в контейнере)</span>
    </p>
    <ul>
      <li>
        <span style="color: #0000c0;">docker run -it --memory=&quot;500m&quot; &lt;образ&gt;</span>&#xa0;&#xa0;# Запустите контейнер с ограничением памяти
      </li>
      <li>
        Укажите лимит в docker-compose:
      </li>
    </ul>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">services: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;myservice: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;image: &lt;образ&gt; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;mem_limit: 500m</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">5. Использование prlimit</span>. prlimit позволяет изменять лимиты для уже запущенных процессов.
    </p>
    <p>
      <span style="color: #0000c0;">prlimit --pid &lt;PID&gt; --as=&lt;лимит_в_байтах&gt;</span>&#xa0;&#xa0;# Установите лимит памяти для процесса
    </p>
    <p>
      <span style="color: #0000c0;">prlimit --pid 1234 --as=500000000</span>&#xa0;&#xa0;# Ограничение до 500 МБ
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Процессы" FOLDED="true" ID="ID_1681815893" CREATED="1519112079912" MODIFIED="1778493974559"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_531194892">Процессы</a>&#xa0;&#xa0;<a href="#ID_340865204">top</a>&#xa0;&#xa0;<a href="#ID_722456128">ps</a>&#xa0;&#xa0;pstree &#xa0;<a href="#ID_1940847259">strace</a>&#xa0;&#xa0;<a href="#ID_805358430">vmstat</a>&#xa0;&#xa0;pgrep&#xa0;&#xa0;<a href="#ID_67360912">kill</a>&#xa0;&#xa0;<a href="#ID_1041392387">killall</a>&#xa0; <a href="#ID_921809145">/proc</a>&#xa0;&#xa0;<a href="#ID_157323599">Задания</a>&#xa0; <a href="#ID_171503298">systemctl</a>&#xa0;&#xa0;<a href="#ID_1877491690">Файловые дескрипторы</a>&#xa0;&#xa0;<a href="#ID_157323599">Фоновые просессы</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">top -u &lt;user&gt;</span>&#xa0;&#xa0;# Процессы конкретного пользователя
    </p>
    <p>
      <span style="color: #0000c0;">top -p &lt;PID&gt;</span>&#xa0;&#xa0;# Процесс с конкретным PID
    </p>
    <p>
      <span style="color: #0000c0;">htop&#xa0; </span># Процессы
    </p>
    <p>
      <span style="color: #0000c0;">ps auxww</span>&#xa0;&#xa0;# au + процессы, отсоединённые от терминала
    </p>
    <p>
      <span style="color: #0000c0;">ps lax</span>&#xa0;&#xa0;# доп. тех. информация. Выполняется быстрее, чем команда ps аuх, так как не сопоставляет идентификаторы процессов с именами пользователей
    </p>
    <p>
      <span style="color: #0000c0;">ps fax </span>&#xa0;# Дерево процессов (что позволяет увидеть порождение процесса и родительский процесс)
    </p>
    <p>
      <span style="color: #0000c0;">pstree -up</span>&#xa0;&#xa0;# Дерево процессов. <b>-u</b>&#xa0;&#xa0;имя юзера запустившего процесс. <b>-p</b>&#xa0;&#xa0;PID каждого процесса
    </p>
    <p>
      <span style="color: #0000c0;">ps aux | awk '{print $1}' | sort | uniq -c | sort -n | tail -f</span>&#xa0;&#xa0;# Число процессов в разбивке по пользователям
    </p>
    <p>
      <span style="color: #0000c0;">ps -C &lt;ИмяПроцесса&gt;</span>&#xa0;&#xa0;&#xa0;# Информация о процессе по его имени
    </p>
    <p>
      <span style="color: #0000c0;">ps -p &lt;PID&gt; -o pid,ppid,cmd</span>&#xa0;&#xa0;# Делали процесса
    </p>
    <p>
      <span style="color: #0000c0;">pgrep &lt;процесс&gt;</span>&#xa0;&#xa0;# Проверка на запуск определенного процесса
    </p>
    <p>
      <span style="color: #0000c0;">pgrep -f http.server</span>&#xa0;&#xa0;# Поиск PID процесса по имени
    </p>
    <p>
      <span style="color: #0000c0;">pgrep -l -G &lt;группа&gt;</span>&#xa0;&#xa0;# процессы в расширенной форме (<b>-l</b>), принадлежащие группе (<b>-G</b>)
    </p>
    <p>
      <span style="color: #0000c0;">pgrep -v -u &lt;пользователь&gt;</span>&#xa0;&#xa0;# процессы не принадлежащие (<b>-v</b>) пользователю (<b>-u</b>)
    </p>
    <p>
      <span style="color: #0000c0;">pgrep -a ssh</span>&#xa0;&#xa0;# PID и командная строка всех процессов, чьё имя содержит ssh
    </p>
    <p>
      <span style="color: #0000c0;">lsof -p &lt;PID&gt; |&#xa0;&#xa0;less</span>&#xa0;&#xa0;# Посмотреть с какими файлами работает процесс. <b>-с</b>&#xa0;- по пользователю
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">echo $$ $PPID</span>&#xa0;&#xa0;# Идентификатор используемого процесса командной оболочки и идентификатор соответствующего <b>родительского</b>&#xa0;процесса
    </p>
    <p>
      <span style="color: #0000c0;">pidof имя_программы</span>&#xa0;&#xa0;# PID процессов, запущенных <span style="font-weight: bold;">программой</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl list-unit-files --type service&#xa0; </span># Все сервисы (активированные и нет)<span style="color: #0000c0;">&#xa0; </span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl status crond.service -l</span>&#xa0;&#xa0;# Статус с ошибками
    </p>
    <p>
      <span style="color: #0000c0;">ulimit -n</span>&#xa0;&#xa0;# максимально возможное число процессов (файловых дескрипторов)
    </p>
    <p>
      <span style="color: #0000c0;">cat /proc/&lt;PID&gt;/environ</span>&#xa0;&#xa0;# Переменное окружение процесса
    </p>
    <p>
      <span style="color: #0000c0;">init &lt;<a href="#ID_1629982510">УровеньЗапуска</a>&gt; </span># меняем уровень запуска на лету
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Найти процесс, занимающий порт/память</span>
    </p>
    <p>
      Порт:
    </p>
    <p>
      <span style="color: #0000c0;">lsof -i :80 </span>
    </p>
    <p>
      <span style="color: #0000c0;">ss -tlnp | grep :80 </span>
    </p>
    <p>
      <span style="color: #0000c0;">fuser 80/tcp.</span>
    </p>
    <p>
      Память (кроме top, htop):
    </p>
    <p>
      <span style="color: #0000c0;">ps aux --sort=-%mem | head</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Завершить процессы</b>
    </p>
    <p>
      <span style="color: #0000c0;">pkill &lt;процесс&gt;&#xa0; </span># Завершить процесс <span style="font-weight: bold;">по имени</span>
    </p>
    <p>
      <span style="color: #0000c0;">killall &lt;процесс&gt;&#xa0; </span># Завершить процесс по имени
    </p>
    <p>
      <span style="color: #0000c0;">pkill -u &lt;user&gt;</span>&#xa0;&#xa0;# Завершить процессы <span style="font-weight: bold;">пользователя</span>
    </p>
    <p>
      <span style="color: #0000c0;">killall -u &lt;user&gt;&#xa0; </span># Завершить процессы пользователя
    </p>
    <p>
      <span style="color: #0000c0;">pkill -u &lt;user&gt; &lt;процесс&gt;</span><span style="font-weight: normal;">&#xa0;&#xa0;# Завершить процессы по имени, принадлежащие текущему пользователю</span>
    </p>
    <p>
      <span style="color: #0000c0;">ps -elf (или aux) | grep &lt;user&gt; | grep -v grep&#xa0;&#xa0;| awk '{print $4}' | xargs kill -9</span>
    </p>
    <p>
      <span style="color: #0000c0;">ps aux | grep 158912 | grep -v grep | awk '{print $2}' | xargs kill -9</span>&#xa0;&#xa0;# Завершить процессы пользователя
    </p>
    <p>
      <span style="color: #0000c0;">ps -u 158912 -o pid= | xargs kill -9</span>
    </p>
    <p>
      <span style="color: #0000c0;">fuser -m <b>-k</b>&#xa0;-u /srv/project/</span>&#xa0;&#xa0;# Завершить все процессы, работающие с директорией
    </p>
    <p>
      <span style="color: #0000c0;">top</span>&#xa0;--&gt; <b>k</b>&#xa0;- # Завершить процесс. Программа запрашивает у вас код процесса и сигнал
    </p>
    <p>
      <span style="color: #0000c0;">kill $(ps -A -ostat,ppid | awk '/[zZ]/ &amp;&amp; !a[$2]++ {print $2}')</span>&#xa0;&#xa0;# Завершить<b>&#xa0;</b><span style="font-weight: bold;">зомби-процессы</span><span style="font-weight: normal;">, т.е. завершить родительский процесс. Перед удалением проверить, нет ли у родителя живых дочерних процессов</span>
    </p>
    <p>
      <span style="color: #ff0000;">killall<b>5</b></span>&#xa0;&#xa0;# Завершить работу всех пользовательских процессов
    </p>
    <p>
      <span style="color: #0000c0; font-weight: bold;">timeout 5</span><span style="color: #0000c0;">&#xa0;openssl s_client -connect k8s.io:443</span>&#xa0;&#xa0;# Принудительное завершение команды по таймауту. Команда завершится через 5 секунд
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Запустить процесс в фоне и отвязать от терминала</span>
    </p>
    <p>
      <span style="color: #0000c0;">nohup команда &amp;</span>&#xa0;&#xa0;# Запускает в фоне и игнорирует SIGHUP
    </p>
    <p>
      Если уже запущен: Ctrl+Z, затем <span style="color: #0000c0;">bg</span>, потом <span style="color: #0000c0;">disown</span>
    </p>
    <p>
      
    </p>
    <p>
      <b>Диагностика</b>
    </p>
    <p>
      top, ps, pstack, strace
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="Сигналы" ID="ID_171056892" CREATED="1519112079912" MODIFIED="1778495350487"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1019007000">Сигналы</a>&#xa0;&#xa0;<a href="#ID_67360912">kill</a>&#xa0; <a href="#ID_921746639">Обработка сигналов (bash)</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">kill -l</span>&#xa0;&#xa0;# список сигналов для данной версии ядра
    </p>
    <p>
      <span style="color: #0000c0;">kill -L</span>&#xa0;&#xa0;# list all signal names in a &#xa0;<a href="#ID_185870371">nice</a>&#xa0;&#xa0;table
    </p>
    <p>
      <span style="color: #0000c0;">kill -KILL &lt;PID&gt;</span>&#xa0;или <span style="color: #0000c0;">kill -9 &lt;PID&gt;</span>&#xa0;&#xa0;#&#xa0;<b>сигнал 9</b>, <span style="color: #ff0000;">не использовать</span>&#xa0;(потеря несохр. данных)
    </p>
    <p>
      <span style="color: #0000c0;">kill -TERM &lt;PID&gt;</span>&#xa0;или <span style="color: #0000c0;">kill -15 &lt;PID&gt;</span>&#xa0;&#xa0;# Использовать сигнал <b>15 (TERM)</b><span style="font-weight: normal;">&#xa0;&#xa0;- по умолчанию</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">kill -STOP 2222</span>&#xa0;&#xa0;# сигнал 19, остановка процесса (PID 2222)
    </p>
    <p>
      <span style="color: #0000c0;">kill -CONT 2222</span>&#xa0;&#xa0;# сигнал 18, продолжить процесс (PID 2222)
    </p>
    <p>
      <span style="color: #0000c0;">kill -HUP 1173</span>&#xa0;&#xa0;# перечитать конф. файл. Аналог например, <span style="color: #0000c0;"># service asterisk reload </span>
    </p>
    <p>
      <span style="color: #0000c0;">killall -HUP inetd&#xa0;&#xa0;</span>#&#xa0;для демонов - перечитать конф. файл
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Потоки" ID="ID_1820992947" CREATED="1579278453612" MODIFIED="1778410883239"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_284304038">Потоки</a>&#xa0; <a href="#ID_1877491690">Файловые дескрипторы</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">ps -T -p &lt;pid&gt;</span>&#xa0;&#xa0;# Посмотреть все потоки процесса с pid. В колонке SPID отображается идентификатор потока, а в CMD его имя.
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">top -H</span>&#xa0;&#xa0;#&#xa0;&#xa0;Включить отображение потоков. H - вкл/выкл.&#xa0;показ потоков во время выполнения. Threads.
    </p>
    <p>
      <span style="color: #0000c0;">top -H -p &lt;pid&gt;</span>&#xa0;&#xa0;# Посмотреть только потоки нужного процесса
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">htop</span>&#xa0;&#xa0;# Просмотр потоков в виде дерева отдельно для каждого процесса
    </p>
    <ol>
      <li>
        <b>F2</b>&#xa0;- Меню
      </li>
      <li>
        Setup \ Display Options \ <b>Three view</b>&#xa0;и <b>Show custom thread names</b>
      </li>
      <li>
        <b>F10</b>&#xa0;- Cохранить настройки
      </li>
    </ol>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
</node>
<node TEXT="Юниты systemd" FOLDED="true" ID="ID_407747048" CREATED="1543580705101" MODIFIED="1779281541227"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1209440117">systemd</a>&#xa0; <a href="#ID_477514214">systemd (юниты)</a>&#xa0; <a href="#ID_171503298">systemctl</a>&#xa0; <a href="#ID_140307459">Удаление сервисов</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Unit-файл</span>&#xa0;- конф. документ, который сообщает systemd, как управлять процессом (службой). Представляет собой текстовый файл в формате INI с секциями и парами имя_параметра = значение
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">cat /etc/systemd/system/название.service</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Unit] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=Понятное описание службы </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=network.target </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Before=another.service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Requires=dbus.socket </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Wants=redis.service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Conflicts=alternative-service.service </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Service] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Type=simple </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WorkingDirectory=/work/www/myapp/current </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">User=myapp </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Group=myapp </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Environment=RACK_ENV=production </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">PIDFile=/work/www/myapp/shared/tmp/pids/service.pid </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">OOMScoreAdjust=-100 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecStart=/usr/bin/my-app --run </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecStop=/usr/bin/my-app --stop </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecReload=/bin/kill -HUP $MAINPID </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">TimeoutSec=300 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Restart=on-failure </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Install] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WantedBy=multi-user.target </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">RequiredBy=graphical.target </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Alias=my-app-shortcut.service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Also=helper-service.service </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold; color: #0000c0;">Секция [Unit]</span>&#xa0;- Метаданные службы, порядок загрузки и зависимости. Директивы After/Before управляют только порядком запуска, но не зависимостями при остановке.
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">Description</span>&#xa0;- Текстовое описание юнита. Отображается в логах и при вызове systemctl status
      </li>
      <li>
        <span style="font-weight: bold;">After</span>&#xa0;- Запускать текущую службу после указанных юнитов. Можно указывать несколько раз
      </li>
      <li>
        <span style="font-weight: bold;">Before</span>&#xa0;- Запускать текущую службу перед указанными юнитами
      </li>
      <li>
        <span style="font-weight: bold;">Requires</span>&#xa0;- Жёсткая зависимость. Если указанный юнит не запущен или упал - текущая служба тоже не запустится или остановится. Если юнит есть в Requires, но не указан в After - оба сервиса запустятся параллельно
      </li>
      <li>
        <span style="font-weight: bold;">Wants</span>&#xa0;- Мягкая зависимость. Systemd попытается запустить указанный юнит, но провал зависимости не повлияет на текущую службу
      </li>
      <li>
        <span style="font-weight: bold;">Conflicts</span>&#xa0;- Несовместимость. При запуске текущей службы указанный юнит будет автоматически остановлен, и наоборот
      </li>
    </ul>
    <p>
      <span style="font-weight: bold; color: #0000c0;">Секция [Service]</span>&#xa0;- Ключевые настройки управления процессом
    </p>
    <p>
      Тип запуска (<span style="font-weight: bold;">Type</span>)
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">simple</span>&#xa0;(по умолчанию) - Служба считается запущенной сразу после старта основного процесса. Процесс не должен разветвляться. Не используйте, если другие службы зависят от очерёдности запуска данной службы
      </li>
      <li>
        <span style="font-weight: bold;">forking</span>&#xa0;- Процесс разветвляется (уходит в фон), родительский процесс завершается. Используется для классических демонов. Рекомендуется указывать PIDFile= для отслеживания основного процесса
      </li>
      <li>
        <span style="font-weight: bold;">oneshot</span>&#xa0;- Для одноразовых скриптов. Systemd ждёт полного завершения процесса перед переходом к следующим юнитам
      </li>
      <li>
        <span style="font-weight: bold;">notify</span>&#xa0;- Процесс сам сообщает systemd о готовности через специальный сокет
      </li>
    </ul>
    <p>
      Остальные параметры
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">ExecStart</span>&#xa0;- Полный путь к исполняемому файлу и его аргументы для запуска службы. Systemd требует указания полного пути
      </li>
      <li>
        <span style="font-weight: bold;">ExecStop</span>&#xa0;- Команда для корректной остановки службы. Если параметр опущен - systemd завершит процесс сигналом SIGTERM
      </li>
      <li>
        <span style="font-weight: bold;">ExecReload</span>&#xa0;- Команда для перезагрузки конфигурации службы без её полной остановки
      </li>
      <li>
        <span style="font-weight: bold;">WorkingDirectory</span>&#xa0;- Рабочий каталог процесса - становится текущим перед выполнением стартовых команд
      </li>
      <li>
        <span style="font-weight: bold;">User</span>&#xa0;/ <span style="font-weight: bold;">Group</span>&#xa0;- Пользователь и группа, от имени которых запускается служба
      </li>
      <li>
        <span style="font-weight: bold;">Environment</span>&#xa0;- Переменные окружения для процесса
      </li>
      <li>
        <span style="font-weight: bold;">PIDFile</span>&#xa0;- Путь к PID-файлу. Используется совместно с Type=forking для отслеживания основного процесса
      </li>
      <li>
        <span style="font-weight: bold;">OOMScoreAdjust</span>&#xa0;- Влияние на вероятность завершения процесса механизмом OOM при нехватке памяти. Диапазон: от -1000 (полный запрет, как у sshd) до 1000. Значение -100 заметно снижает вероятность
      </li>
      <li>
        <span style="font-weight: bold;">TimeoutSec</span>&#xa0;- Таймаут в секундах - сколько ждать выполнения команд старта и остановки
      </li>
      <li>
        <span style="font-weight: bold;">Restart</span>&#xa0;- Условие автоматического перезапуска службы
      </li>
    </ul>
    <p>
      Значения <span style="font-weight: bold;">Restart</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">always</span>&#xa0;- Перезапускать всегда, даже при успешном завершении
      </li>
      <li>
        <span style="font-weight: bold;">on-failure</span>&#xa0;- Перезапуск при ненулевом коде выхода, получении сигнала (кроме SIGTERM при штатной <span style="font-weight: normal;">остановке</span>), таймауте, core dump и других сбоях
      </li>
      <li>
        <span style="font-weight: bold;">on-abnormal</span>&#xa0;- Перезапуск при сигналах, таймауте и core dump, но не при ненулевом коде выхода
      </li>
      <li>
        <span style="font-weight: bold;">no</span>&#xa0;- Автоматический перезапуск отключён
      </li>
    </ul>
    <p>
      <span style="font-weight: bold; color: #0000c0;">Секция [Install]</span><span style="font-weight: bold;">&#xa0;&#xa0;- </span>Инструкции для команды systemctl enable. Определяют поведение юнита при автозагрузке системы
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">WantedBy</span>&#xa0;- Создаёт мягкую зависимость. Служба запускается при переходе системы в <a href="#ID_448165966">указанное состояние</a>. multi-user.target - многопользовательский режим без графики (аналог runlevel 3)
      </li>
      <li>
        <span style="font-weight: bold;">RequiredBy</span>&#xa0;- Создаёт жёсткую зависимость. Указанный таргет не запустится, если текущая служба завершится с ошибкой
      </li>
      <li>
        <span style="font-weight: bold;">Alias</span>&#xa0;- Альтернативное имя службы для управления через systemctl
      </li>
      <li>
        <span style="font-weight: bold;">Also</span>&#xa0;- Список сопутствующих юнитов, которые включаются или отключаются одновременно с данным
      </li>
    </ul>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT=".mount" FOLDED="true" POSITION="bottom_or_right" ID="ID_1212076481" CREATED="1780397973048" MODIFIED="1780398976656"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1832050794">.mount (systemd)</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Структура файла .mount</span><span style="font-weight: normal;">&#xa0;- Конфигурация состоит из </span><span style="font-weight: bold;">трех основных секций</span><span style="font-weight: normal;">:</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">[Unit]</span>&#xa0;- Содержит общую информацию и зависимости
    </p>
    <ul>
      <li>
        Description= - понятное описание точки монтирования
      </li>
      <li>
        Before=, After= - порядок запуска относительно других служб
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">[Mount]</span>&#xa0;(Обязательная) - Определяет параметры самой файловой системы
    </p>
    <ul>
      <li>
        What= - что монтируем (путь к устройству /dev/sdb1, UUID устройства UUID=..., сетевой ресурс или имя удаленного хоста)
      </li>
      <li>
        Where= - куда монтируем (абсолютный путь к директории)
      </li>
      <li>
        Type= - тип файловой системы (например, ext4, xfs, nfs4, vfat)
      </li>
      <li>
        Options= - опции монтирования через запятую (например, defaults,noatime,rw)
      </li>
      <li>
        LazyUnmount= - принимать логическое значение (true/false). Принудительно отмонтирует занятый ресурс, как только он освободится
      </li>
      <li>
        TimeoutSec= - время ожидания завершения операции монтирования перед тем, как зафиксировать сбой
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">[Install]</span>&#xa0;- Определяет условия активации при загрузке системы
    </p>
    <ul>
      <li>
        WantedBy=multi-user.target - стандартное значение для монтирования при обычной загрузке системы
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Команды</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl --force --all edit имя_юнита.mount</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать</span>&#xa0;&#xa0;юнит
    </p>
    <p>
      <span style="color: #0000c0;">systemctl daemon-reload</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Перезагрузить</span>&#xa0;конфигурацию systemd (выполнять всегда после создания/изменения юнита)
    </p>
    <p>
      <span style="color: #0000c0;">systemctl </span><span style="color: #0000c0; font-weight: bold;">start</span><span style="color: #0000c0;">&#xa0;&#xa0;имя_юнита.mount</span>&#xa0;&#xa0;# Смонтировать <span style="font-weight: bold;">вручную</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl </span><span style="color: #0000c0; font-weight: bold;">stop</span><span style="color: #0000c0;">&#xa0;&#xa0;имя_юнита.mount</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Размонтировать</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl </span><span style="color: #0000c0; font-weight: bold;">enable</span><span style="color: #0000c0;">&#xa0;&#xa0;имя_юнита.mount</span>&#xa0;&#xa0;# Включить автоматическое монтирование <span style="font-weight: bold;">при загрузке</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl </span><span style="color: #0000c0; font-weight: bold;">status</span><span style="color: #0000c0;">&#xa0;&#xa0;имя_юнита.mount</span>&#xa0;&#xa0;# Проверить <span style="font-weight: bold;">статус</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="пример" ID="ID_784639712" CREATED="1780398128321" MODIFIED="1780398212207"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Юнит для автоматического монтирования <span style="font-weight: bold;">дополнительного диска в папку /mnt/storage</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">vi /etc/systemd/system/mnt-storage.mount</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Unit] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=Дополнительный диск для хранения данных </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=network.target </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Mount] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">What=/dev/disk/by-uuid/12345678-abcd-ef01-2345-6789abcdef01 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Where=/mnt/storage </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Type=ext4 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Options=defaults,noatime </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">TimeoutSec=30 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Install] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WantedBy=multi-user.target</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT=".service" FOLDED="true" POSITION="bottom_or_right" ID="ID_741466490" CREATED="1553361777669" MODIFIED="1779279329689"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <span style="font-weight: bold;">включение</span>&#xa0;службы <span style="font-weight: bold;">создает символические ссылки</span>&#xa0;в соответствующих каталогах конфигурации systemd (например, <span style="font-weight: bold;">/etc/systemd/system/multi-user.target.wants/</span>), которые указывают на файл юнита службы. Отключение службы удаляет эти ссылки
      </li>
      <li>
        Юнит представляет из себя текстовый файл в каталоге <b>/etc/systemd/system/</b>:<br/><span style="color: #008000;">[Название] </span><br/><span style="color: #008000;">имя_переменной = значение</span>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">cat /etc/systemd/system/myunit.service</span>
    </p>
    <p>
      <b><span style="color: #008000; font-family: Lucida Console;">[Unit]&#xa0; </span><span style="font-family: Lucida Console;">#&#xa0;&#xa0;Содержит общую информацию о юните</span></b>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=MyUnit</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;#&#xa0;удобочитаемое имя юнита </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=syslog.target&#xa0; </span><span style="font-family: Lucida Console;"># После чего загружать наш юнит </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=network.target </span><span style="font-family: Lucida Console;"># После инициализации сети</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=nginx.service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=mysql.service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Requires=mysql.service</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Для запуска сервиса необходим запущенный mysql </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Wants=redis.service</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;#&#xa0;Для запуска сервиса желателен запущенный redis. Если сервис есть в Requires, но нет в After, то наш сервис будет запущен параллельно с требуемым сервисом </span>
    </p>
    <p>
      
    </p>
    <p>
      <b><span style="color: #008000; font-family: Lucida Console;">[Service]&#xa0;</span><span style="font-family: Lucida Console;">&#xa0;# Определяет поведение службы</span></b>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Type=simple</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Тип сервиса. Команда </span><span style="font-family: Lucida Console; color: #008000;">ExecStart</span><span style="font-family: Lucida Console;">&#xa0;является основным процессом. (по умолчанию) systemd предполагает, что служба будет запущена незамедлительно. Процесс при этом не должен разветвляться. Не используйте этот тип, если другие службы зависят от очередности при запуске данной службы</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Type=forking</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Тип сервиса.systemd предполагает, что служба запускается однократно и процесс разветвляется с завершением родительского процесса. Данный тип используется для запуска классических демонов. </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">PIDFile=/work/www/myunit/shared/tmp/pids/service.pid&#xa0;</span><span style="font-family: Lucida Console;">&#xa0;# Определить PIDFile=, чтобы systemd могла отслеживать основной процесс </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WorkingDirectory=/work/www/myunit/current</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Рабочий каталог, он становится текущим перед запуском стартап команд </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">User=myunit</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;#&#xa0;Пользователь и группа, под которым надо стартовать сервис </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Group=myunit</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Environment=RACK_ENV=production</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;#&#xa0;Переменные окружения </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">OOMScoreAdjust=-100</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Запрет на убийство сервиса вследствие нехватки памяти и срабатывания механизма OOM: -1000 полный запрет (такой у sshd стоит), -100 понизим вероятность. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;"># Команды на старт/стоп и перезапуск сервиса. systemd настаивает, чтобы команда указывала на конкретный исполняемый файл. Надо указывать полный путь </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecStart=/usr/local/bin/bundle exec service -C /work/www/myunit/shared/config/service.rb --daemon </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecStop=/usr/local/bin/bundle exec service -S /work/www/myunit/shared/tmp/pids/service.state stop </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecReload=/usr/local/bin/bundle exec service -S /work/www/myunit/shared/tmp/pids/service.state restart </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">TimeoutSec=300</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Таймаут в секундах, сколько ждать system отработки старт/стоп команд </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Restart=always</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Сервис перезапускается всегда, даже при успешном завершении </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">Restart=on-failure</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Перезапуск только при: ненулевом коде выхода, получении сигнала (кроме SIGTERM при остановке), таймауте, core dump и других сбоях</span>
    </p>
    <p>
      
    </p>
    <p>
      <b><span style="color: #008000; font-family: Lucida Console;">[Install]&#xa0;</span><span style="font-family: Lucida Console;">&#xa0;# В каком уровне запуска должен стартовать сервис</span></b>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WantedBy=multi-user.target</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Уровень запуска. multi-user.target или runlevel3.target соответствует нашему привычному runlevel=3 «Многопользовательский режим без графики. Пользователи, как правило, входят в систему при помощи множества консолей или через сеть» </span>
    </p>
  </body>
</html></richcontent>
<node TEXT="ping" FOLDED="true" POSITION="bottom_or_right" ID="ID_1085359326" CREATED="1730370241891" MODIFIED="1765734879298"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Создание юнита ping</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">sudo vim <a href="#ID_1581612046">/etc/systemd/system/</a></span><a href="#ID_1581612046"><span style="color: #0000c0; font-weight: bold;">test.service</span></a>&#xa0;&#xa0;# <b>юнит1&#xa0;- Выполняет команду ping </b>
    </p>
    <p>
      <span style="color: #0000c0;">journalctl -u test.service</span>&#xa0;&#xa0;# Посмотреть лог на предмет ошибок. -f - аналог <span style="color: #0000c0;">tail -f</span>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">sudo vim <a href="#ID_830628726">/etc/systemd/system/</a></span><a href="#ID_830628726"><span style="color: #0000c0; font-weight: bold;">test.timer&#xa0;</span></a>&#xa0;# <b>юнит2 - Запускает юнит1 (test.service) по расписанию.</b><span style="font-weight: normal;">&#xa0;Название </span><span style="font-weight: normal; color: #ff0000;">должно</span><span style="font-weight: normal;">&#xa0;соответствовать названию сервиса </span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl enable </span><span style="color: #0000c0; font-weight: bold;">test.timer</span>&#xa0;&#xa0;# Добавить таймер в автозагрузку
    </p>
  </body>
</html></richcontent>
<node TEXT="/etc/systemd/system/test.service" ID="ID_1581612046" CREATED="1738771004191" MODIFIED="1765734891354"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">sudo vim /etc/systemd/system/test<b>.service</b></span>&#xa0;&#xa0;# <b>юнит1&#xa0;- Выполняет команду ping</b>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Unit]</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=Ping server service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=network.target</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Если сеть не будет работать, скрипт не выполнится </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #008000; font-family: Lucida Console;">[Service]</span><span style="color: #008000; font-weight: normal; font-family: Lucida Console;">&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Type=oneshot</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Тип запуска сервиса - oneshot для однократного запуска </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecStart=/bin/ping -c4 ya.ru</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Запускаем команду ping</span><span style="color: #008000; font-family: Lucida Console;">&#xa0;</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #008000; font-family: Lucida Console;">[Install]</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WantedBy=multi-user.target</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Уровень запуска - многопользовательский режим без графики</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="/etc/systemd/system/test.timer" ID="ID_830628726" CREATED="1738771006305" MODIFIED="1765734896536"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_109866290"><span style="color: #0000c0;">&lt;юнит&gt;.timer</span></a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">sudo vim /etc/systemd/system/test<b>.timer</b></span>&#xa0;&#xa0;# <b>юнит2 - Запускает юнит1 (test.service) по расписанию.</b><span style="font-weight: normal;">&#xa0;Название </span><span style="font-weight: normal; color: #ff0000;">должно</span><span style="font-weight: normal;">&#xa0;соответствовать названию сервиса</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #008000; font-family: Lucida Console;">[Unit]</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=Ping timer</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #008000; font-family: Lucida Console;">[Timer]</span><span style="color: #008000; font-weight: normal; font-family: Lucida Console;">&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">OnCalendar=*-*-* *:*:00</span><span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;# Каждую минуту </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #008000; font-family: Lucida Console;">[Install]</span><span style="color: #008000; font-weight: normal; font-family: Lucida Console;">&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WantedBy=timers.target</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="логирование" POSITION="bottom_or_right" ID="ID_1094973351" CREATED="1765734662515" MODIFIED="1765735083592"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">записывает временную метку в файл журнала каждые несколько секунд</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">sudo vim /etc/systemd/system/mytest.service</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Unit] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=My Test Service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=network.target </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Service] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Type=simple </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecStart=/bin/bash -c 'while true; do echo &quot;$(date): My Test Service is running.&quot; &gt;&gt; /tmp/mytest.log; sleep 5; done' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">ExecStop=/bin/bash -c 'echo &quot;$(date): My Test Service stopped.&quot; &gt;&gt; /tmp/mytest.log' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Restart=on-failure </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Install] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WantedBy=multi-user.target</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="мониторинг" POSITION="bottom_or_right" ID="ID_458671066" CREATED="1767693492418" MODIFIED="1767694269977"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      # etc/systemd/system/<span style="font-weight: bold;">monitoring.service</span>&#xa0;
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">[Unit] </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">Description=Example monitoring service </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">Wants=monitoring.timer </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">[Service] </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Тип запуска сервиса - oneshot, то есть один запуск</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">Type=oneshot </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Запускаем команду free </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">ExecStart=/usr/bin/free </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">[Install] </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">WantedBy=multi-user.target </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      # etc/systemd/system/<span style="font-weight: bold;">monitoring.timer</span>&#xa0;
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">[Unit] </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">Description=Example monitoring timer </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">Requires=monitoring.service </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">[Timer] </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Этот таймер запускает сервис monitoring.service </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">Unit=monitoring.service </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Каждую минуту </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">OnCalendar=*-*-* *:*:00 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">[Install] </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">WantedBy=timers.target</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Команды" ID="ID_996851527" CREATED="1780388435142" MODIFIED="1780389309741"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">systemctl daemon-reload</span>&#xa0;&#xa0;# Для применения изменений в конф. файлах
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Управление состоянием</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl start &lt;name&gt;</span>&#xa0;&#xa0;# запустить службу
    </p>
    <p>
      <span style="color: #0000c0;">systemctl stop &lt;name&gt;</span>&#xa0;&#xa0;# остановить службу
    </p>
    <p>
      <span style="color: #0000c0;">systemctl restart &lt;name&gt;</span>&#xa0;&#xa0;# перезапустить службу
    </p>
    <p>
      <span style="color: #0000c0;">systemctl reload &lt;name&gt;</span>&#xa0;&#xa0;# перечитать конфиг приложения без остановки. Требует наличия директивы ExecReload= в файле юнита
    </p>
    <p>
      <span style="color: #0000c0;">systemctl reload-or-restart имя_юнита</span>&#xa0;&#xa0;# Безопасный перезапуск: пытается выполнить reload, но если он не поддерживается приложением, автоматически делает restart
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">systemctl status &lt;name&gt;</span>&#xa0;&#xa0;# проверить статус и увидеть последние логи
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Управление автозапуском</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl enable &lt;name&gt;</span>&#xa0;&#xa0;# включить автозапуск при старте системы. Создает симлинки в каталогах конфигурации systemd (например, /etc/systemd/system/multi-user.target.wants/), указывающие на файл юнита
    </p>
    <p>
      <span style="color: #0000c0;">systemctl enable --now имя_юнита</span>&#xa0;&#xa0;# Комбинированная команда: включает автозапуск и сразу запускает юнит (аналог enable + start)
    </p>
    <p>
      <span style="color: #0000c0;">systemctl disable &lt;name&gt;</span>&#xa0;&#xa0;# отключить автозапуск. Удаляет символические ссылки
    </p>
    <p>
      <span style="color: #0000c0;">systemctl disable --now имя_юнита</span>&#xa0;&#xa0;# Комбинированная команда: отключает автозапуск и сразу останавливает юнит (аналог disable + stop)
    </p>
    <p>
      <span style="color: #0000c0;">systemctl mask &lt;name&gt;</span>&#xa0;&#xa0;# полностью заблокировать службу (ее нельзя будет запустить даже вручную)
    </p>
    <p>
      <span style="color: #0000c0;">systemctl unmask &lt;name&gt;</span>&#xa0;&#xa0;# снять блокировку
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Мониторинг списка служб</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl list-units --type=service</span>&#xa0;&#xa0;# показать все активные службы
    </p>
    <p>
      <span style="color: #0000c0;">systemctl list-unit-files --type=service</span>&#xa0;&#xa0;# показать состояние автозапуска всех служб
    </p>
    <p>
      <span style="color: #0000c0;">systemctl --failed</span>&#xa0;&#xa0;# показать только сломавшиеся службы
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Просмотр логов (journalctl)</span><span style="font-weight: normal;">&#xa0;- Systemd агрегирует логи всех служб в собственную утилиту</span>
    </p>
    <p>
      <span style="color: #0000c0;">journalctl -u &lt;name&gt;.service</span>&#xa0;&#xa0;# логи конкретной службы
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">-f</span>&#xa0;&#xa0;# вывод новых логов в реальном времени (аналог tail -f)
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">journalctl -u &lt;name&gt;.service --since &quot;1 hour ago&quot;</span>&#xa0;&#xa0;# логи за последний час
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Маскирование служб" POSITION="bottom_or_right" ID="ID_785721738" CREATED="1765737757783" MODIFIED="1765738783438"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Маскирование и размаскирование служб в systemd</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Маскирование (mask)</span>&#xa0;- механизм systemd, который <span style="font-weight: bold;">полностью блокирует</span>&#xa0;возможность запуска службы: ни вручную (systemctl start), ни автоматически (через зависимости или WantedBy)
    </p>
    <ul>
      <li>
        Чтобы <span style="font-weight: bold;">запретить</span>&#xa0;запуск ненужного или потенциально опасного сервиса (например, atd, cups, bluetooth)
      </li>
      <li>
        Для служб, установленных <span style="font-weight: bold;">пакетным менеджером</span>&#xa0;(их файлы находятся в /usr/lib/systemd/system)
      </li>
      <li>
        <span style="font-weight: bold;">Нельзя замаскировать службу</span>, если в /etc/systemd/system/ уже существует <span style="font-weight: bold;">обычный файл</span>&#xa0;(не ссылка) с таким именем
      </li>
      <li>
        используйте mask для системных служб, которые вы <span style="font-weight: bold;">точно не хотите видеть запущенными</span>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Маскирование</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl </span><span style="color: #0000c0; font-weight: bold;">mask</span><span style="color: #0000c0;">&#xa0;&lt;service&gt;.service</span>&#xa0;&#xa0;# Создаёт <span style="font-weight: bold;">символическую ссылку</span>:
    </p>
    <p>
      <span style="font-family: Lucida Console;">/etc/systemd/system/&lt;service&gt;.service --&gt; /dev/null</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Размаскирование</span>&#xa0;- Чтобы восстановить службу:
    </p>
    <p>
      <span style="color: #0000c0;">systemctl </span><span style="color: #0000c0; font-weight: bold;">unmask</span><span style="color: #0000c0;">&#xa0;&lt;service&gt;.service&#xa0;&#xa0;# </span>Удаляет символическую ссылку на /dev/null, восстанавливая доступ к оригинальному юниту (если он существует)
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT=".timer" FOLDED="true" POSITION="bottom_or_right" ID="ID_109866290" CREATED="1730375050217" MODIFIED="1781264652154"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_975572889">Задания по расписанию</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">systemd.timer</span>&#xa0;- встроенный в систему systemd механизм планирования задач в Linux, который запускает службы (<span style="font-weight: bold;">.service</span>) по расписанию или при наступлении определенных событий
    </p>
    <ul>
      <li>
        Таймеры могут быть двух типов: <span style="font-weight: bold;">событийные</span>&#xa0;и <span style="font-weight: bold;">автономные</span>. Первые активируются по событию, а вторые выполняются периодически
      </li>
      <li>
        название должно соответствовать названию сервиса, тогда не нужно будет прописывать директиву Unit
      </li>
      <li>
        Можно использовать алиасы, как и в cron: <span style="font-weight: bold;">hourly</span>, <span style="font-weight: bold;">daily</span>, <span style="font-weight: bold;">monthly</span>&#xa0;и другие
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">man systemd.timer </span>
    </p>
    <p>
      <span style="color: #0000c0;">man systemd.time </span>
    </p>
    <p>
      <span style="color: #0000c0;">man systemd-system.conf </span>
    </p>
    <p>
      <span style="color: #0000c0;">man systemd-analyze </span>
    </p>
    <p>
      <span style="color: #0000c0;">man tzselect</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/systemd/system/test<b>.timer</b></span>&#xa0;&#xa0;# <b>юнит2 - Запускает службу по расписанию.</b><span style="font-weight: normal;">&#xa0;Название должно соответствовать названию сервиса</span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000; font-family: Lucida Console;">[Unit]</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=Ping timer</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #008000; font-family: Lucida Console;">[Timer]</span><span style="color: #008000; font-weight: normal; font-family: Lucida Console;">&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Unit=&lt;name&gt;.service</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Если название таймера соответствует названию сервиса, то строка не обязательна </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">OnBootSec=30m</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Пример </span><span style="font-weight: bold; font-family: Lucida Console;">событийного</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;таймера - со стартом через некоторое время после запуска системы </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">OnCalendar=*-*-* *:*:00</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Каждую минуту </span>
    </p>
    <ul>
      <li>
        <span style="font-family: Lucida Console;">DOW YYYY-MM-DD HH:MM:SS </span>
      </li>
      <li>
        <span style="font-family: Lucida Console;">DOW — от англ. day of week, то есть день недели </span>
      </li>
      <li>
        <span style="font-family: Lucida Console;">YYYY — year, год </span>
      </li>
      <li>
        <span style="font-family: Lucida Console;">MM — month, месяц </span>
      </li>
      <li>
        <span style="font-family: Lucida Console;">DD — day, день </span>
      </li>
      <li>
        <span style="font-family: Lucida Console;">HH — hour, час </span>
      </li>
      <li>
        <span style="font-family: Lucida Console;">MM — minutes, минуты </span>
      </li>
      <li>
        <span style="font-family: Lucida Console;">SS — seconds, секунды </span>
      </li>
      <li>
        <span style="font-family: Lucida Console;">Значения указываются с помощью </span><span style="font-weight: bold; font-family: Lucida Console;">*</span><span style="font-family: Lucida Console;">&#xa0;и перечисляются через </span><span style="font-weight: bold; font-family: Lucida Console;">запятую</span>
      </li>
      <li>
        <span style="font-weight: bold; font-family: Lucida Console;">..</span><span style="font-family: Lucida Console;">&#xa0;- диапазоны разделяются двумя точками </span>
      </li>
      <li>
        <span style="font-family: Lucida Console;">~ (Знак тильды ) - поможет указать количество интервалов от конца диапазона </span>
      </li>
      <li>
        <span style="font-family: Lucida Console;">/ (косая черта) - модификатор </span>
      </li>
    </ul>
    <p>
      <span style="font-family: Lucida Console;">*:*:00&#xa0;- каждую минуту </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">*-*-2,4,8 *:00:00&#xa0;- каждый час 2, 4 и 8 числа </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Mon *-*~7/1&#xa0;- последний понедельник месяца </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #008000; font-family: Lucida Console;">[Install]</span><span style="color: #008000; font-weight: normal; font-family: Lucida Console;">&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">WantedBy=timers.target</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Необходимая часть .timer для правильной работы таймера в systemd</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">systemctl list-timers</span>&#xa0;&#xa0;# Запущенные таймеры
    </p>
    <p>
      <span style="color: #0000c0;">systemd-analyze calendar &quot;*-*-2,4,8 *:00:00&quot;</span>&#xa0;&#xa0;# Проверить корректность конструкции таймера
    </p>
    <p>
      <span style="color: #0000c0;">systemd-analyze timespan 1.5h </span>
    </p>
    <p>
      <span style="color: #0000c0;">systemd-analyze timestamp 01:00:30.9999</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="timestamp" ID="ID_236199680" CREATED="1730381178285" MODIFIED="1779269508294"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Запуск сервиса раз в полтора часа, начиная с часа ночи</span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">[Timer] </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">OnCalendar=01:00 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">OnUnitActiveSec=1.5h </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console;">Алиасы (и их эквиваленты в нормализованной форме) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">minutely&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;→ *-*-* *:*:00 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">hourly&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;→ *-*-* *:00:00 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">daily&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;→ *-*-* 00:00:00 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">monthly&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;→ *-*-01 00:00:00 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">weekly&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;→ Mon *-*-* 00:00:00 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">yearly&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;→ *-01-01 00:00:00 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">quarterly&#xa0;&#xa0;&#xa0;&#xa0;→ *-01,04,07,10-01 00:00:00</span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">semiannually → *-01,07-01 00:00:00 </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console;">*-*~01 — Первый день с конца каждого месяца (он-же последний день месяца). </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">*-05~05 — 27-e мая каждого года (31-5). </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Mon *-12~07/1 — Последний понедельник декабря. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Mon *-12-01/3 — Третий понедельник декабря.</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="точность до секунды" ID="ID_480494547" CREATED="1781264258434" MODIFIED="1781264490961"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Само по себе указание секунд в OnCalendar <span style="color: #ff0000;">не гарантирует точный запуск секунда в секунду</span>.
    </p>
    <ul>
      <li>
        Причина в параметре <span style="font-weight: bold;">AccuracySec</span>
      </li>
      <li>
        По умолчанию AccuracySec равен <span style="font-weight: bold;">одной минуте</span>
      </li>
      <li>
        Система имеет право задержать таймер на срок до 60 секунд
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Сделать запуск абсолютно точным:</span>
    </p>
    <ul>
      <li>
        В секцию [Timer] добавляют параметр AccuracySec=1us (1 микросекунда).
      </li>
    </ul>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Timer] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">OnCalendar=*-*-* *:*:00 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console; font-weight: bold;">AccuracySec=1us</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Unit=my_service.service</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Зависимости" POSITION="bottom_or_right" ID="ID_1329562349" CREATED="1722444769150" MODIFIED="1765734451490"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Зависимости и порядок запуска в systemd-юнитах</span>
    </p>
    <ul>
      <li>
        <span style="color: #008000;">Requires=</span>&#xa0;используйте только когда без зависимости сервис действительно <span style="font-weight: bold;">не может работать</span>
      </li>
      <li>
        <span style="color: #008000;">After=another.service</span>&#xa0;почти всегда <span style="font-weight: bold;">следует указывать</span>&#xa0;вместе с Requires= или Wants=, иначе порядок не будет иметь смысла
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Порядок запуска: Before / After</span>
    </p>
    <ul>
      <li>
        Эти директивы <span style="font-weight: bold;">не создают зависимости</span>, а лишь указывают, <span style="font-weight: bold;">в каком порядке запускать юниты</span>, если они оба активны
      </li>
      <li>
        <span style="color: #008000; font-weight: bold;">After</span><span style="color: #008000;">=another.service</span>&#xa0;- текущий юнит запускается <span style="font-weight: bold;">после</span>&#xa0;another.service
      </li>
      <li>
        <span style="color: #008000; font-weight: bold;">Before</span><span style="color: #008000;">=some.service - </span>текущий юнит запускается <span style="font-weight: bold;">до</span>&#xa0;some.service
      </li>
      <li>
        если another.service не запускается (например, не включён), systemd всё равно может запустить текущий юнит - After не означает «запустить another.service»
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Зависимости по состоянию: Wants / Requires</span>
    </p>
    <ul>
      <li>
        Эти директивы указывают, что нужно активировать другие юниты, и определяют поведение при сбое
      </li>
      <li>
        <span style="color: #008000; font-weight: bold;">Wants</span><span style="color: #008000;">=optional.service</span>&#xa0;&#xa0;# Рекомендуется использовать по умолчанию
      </li>
      <li>
        systemd <span style="font-weight: bold;">попытается</span>&#xa0;запустить optional.service, но:

        <ol>
          <li>
            если он не существует или не запустится - <span style="font-weight: bold;">это не ошибка</span>
          </li>
          <li>
            основной юнит продолжит работу
          </li>
        </ol>
      </li>
      <li>
        <span style="color: #008000; font-weight: bold;">Requires=</span><span style="color: #008000;">another.service</span>&#xa0;&#xa0;# systemd <span style="font-weight: bold;">обязательно запускает</span>&#xa0;another.service
      </li>
      <li>
        Если another.service <span style="font-weight: bold;">не запустится успешно</span>, основной юнит:

        <ol>
          <li>
            не будет запущен
          </li>
          <li>
            будет помечен как failed
          </li>
          <li>
            Если зависимость <span style="font-weight: bold;">падает во время работы</span>, основной юнит останавливается
          </li>
        </ol>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Комбинированный пример</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">[Unit] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Description=My Example Service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Requires=another.service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Wants=optional.service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">After=another.service </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Before=some.service </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console;">Директива&#xa0;| Создаёт зависимость | Требует успешного&#xa0;запуска | Влияет на порядок | </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">----------|---------------------|---------------------------|-------------------| </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Wants=&#xa0;&#xa0;&#xa0;&#xa0;| Да (мягкая)&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Нет&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Нет&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Requires=&#xa0;| Да (жёсткая)&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Да&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Нет&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">After=&#xa0;&#xa0;&#xa0;&#xa0;| Нет&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Нет&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Да&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Before=&#xa0;&#xa0;&#xa0;| Нет&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Нет&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Да&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| </span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Команды" ID="ID_165821996" CREATED="1779270161789" MODIFIED="1780388552372"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_171503298">systemctl</a>&#xa0; <a href="#ID_21448030">journalctl</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Просмотр списков юнитов</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl</span>&#xa0;&#xa0;# Показывает только активные юниты
    </p>
    <p>
      <span style="color: #0000c0;">systemctl -a</span>&#xa0;&#xa0;# Выводит все загруженные юниты
    </p>
    <p>
      <span style="color: #0000c0;">systemctl --type=тип</span>&#xa0;&#xa0;# Фильтрует по типу (например: service, timer, socket)
    </p>
    <p>
      <span style="color: #0000c0;">systemctl --state=статус</span>&#xa0;&#xa0;# Фильтрует по состоянию (например: failed, running)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Вывод содержимого и статуса</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl status имя</span>&#xa0;&#xa0;# Показывает текущий статус и последние логи
    </p>
    <p>
      <span style="color: #0000c0;">systemctl cat имя</span>&#xa0;&#xa0;# Выводит исходный текст файла конфигурации
    </p>
    <p>
      <span style="color: #0000c0;">systemctl show имя</span>&#xa0;&#xa0;# Отображает все внутренние параметры юнита
    </p>
    <p>
      <span style="color: #0000c0;">systemctl list-dependencies имя</span>&#xa0;&#xa0;# Выводит дерево зависимостей юнита
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Редактирование и создание</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl edit имя</span>&#xa0;&#xa0;# Создаёт drop-in файл для переопределения отдельных параметров
    </p>
    <p>
      <span style="color: #0000c0;">systemctl edit --full имя</span>&#xa0;&#xa0;# Копирует оригинальный юнит для полного редактирования
    </p>
    <p>
      <span style="color: #0000c0;">systemctl edit --full --force имя</span>&#xa0;&#xa0;# Создаёт новый юнит с нуля
    </p>
    <p>
      <span style="color: #0000c0;">systemctl daemon-reload</span>&#xa0;&#xa0;# Перезагружает конфигурацию systemd после ручного редактирования файлов
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Вывод текущего состояния (Состояние в оперативной памяти)</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl list-units --type=service</span>&#xa0;&#xa0;# Список только активных и загруженных сервисов в данный момент
    </p>
    <ul>
      <li>
        Состояния

        <ul>
          <li>
            enabled (запускается при загрузке)
          </li>
          <li>
            disabled (не запускается при загрузке)
          </li>
          <li>
            static (не может быть включена напрямую, но может быть запущена другим юнитом)
          </li>
          <li>
            masked (запрещено запускать)
          </li>
        </ul>
      </li>
      <li>
        <span style="font-weight: bold;">--all</span>&#xa0;- Абсолютно все сервисы, которые systemd видит в памяти, включая неактивные, упавшие, мертвые или ожидающие запуска
      </li>
      <li>
        <span style="font-weight: bold;">--state=</span><span style="font-weight: bold; color: #ff0000;">failed</span>&#xa0;- Фильтр для вывода только тех юнитов, которые завершились с ошибкой
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Вывод состояния файлов на диске (Статический статус)</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl list-unit-files --type=service</span>&#xa0;&#xa0;# Список всех установленных в системе файлов сервисов и статус их автозапуска (enabled, disabled, static, masked). Показывает состояние файлов на диске, даже если сам сервис никогда не запускался в текущей сессии
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">--no-pager</span>&#xa0;- Отключает утилиту постраничного просмотра (обычно это less). Весь текст выводится в консоль единым потоком
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Управление конфигурацией systemd</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl daemon-reload</span>&#xa0;&#xa0;# Перечитать конф. файлы всех юнитов с диска. Выполняется обязательно после любого изменения или создания файлов *.service, *.timer, *.socket и др.
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Мониторинг и проверка статуса (Диагностика)</span>
    </p>
    <p>
      <span style="color: #0000c0;">systemctl status имя_юнита</span>&#xa0;&#xa0;# Показать подробный статус юнита, его дерево процессов (cgroups) и последние строки логов
    </p>
    <p>
      <span style="color: #0000c0;">systemctl is-active имя_юнита</span>&#xa0;&#xa0;# Быстрая проверка: активен ли юнит в данный момент (возвращает active или inactive). Удобно для скриптов
    </p>
    <p>
      <span style="color: #0000c0;">systemctl is-enabled имя_юнита</span>&#xa0;&#xa0;# Быстрая проверка: включен ли автозапуск юнита (возвращает enabled или disabled)
    </p>
    <p>
      <span style="color: #0000c0;">systemctl is-failed имя_юнита</span>&#xa0;&#xa0;# Быстрая проверка: завершился ли юнит с ошибкой (возвращает failed или active/inactive)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Работа с логами</span>
    </p>
    <p>
      <span style="color: #0000c0;">journalctl -u имя_юнита</span>&#xa0;&#xa0;# Показать все системные логи для конкретного юнита
    </p>
    <ul>
      <li>
        -f - Вывод логов юнита в реальном времени (режим «слежения», аналог tail -f)
      </li>
      <li>
        -n 50 - Показать только последние 50 строк логов юнита
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
