<node TEXT="Файловая система" ID="ID_1412734557" CREATED="1742125342561" MODIFIED="1780399460314"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_657599818"><span style="font-family: SansSerif; font-size: 10pt;">Файловая система</span></a><span style="font-family: SansSerif; font-size: 10pt;">&#xa0; </span><a href="#ID_125951154">Форматирование (задачи)</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Утилиты ФС (ext4)</span>
    </p>
    <ul>
      <li>
        tune2fs: настройка параметров
      </li>
      <li>
        dumpe2fs: структура ФС
      </li>
      <li>
        e2fsck: проверка целостности
      </li>
      <li>
        resize2fs: изменение размера
      </li>
      <li>
        e4defrag: дефрагментация
      </li>
      <li>
        debugfs: отладка
      </li>
      <li>
        e2image: бэкап метаданных
      </li>
      <li>
        df -hi: свободное место и inode
      </li>
      <li>
        du -sh: размер каталога
      </li>
      <li>
        lsblk: блочные устройства
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Ядро" FOLDED="true" ID="ID_586114057" CREATED="1519112079913" MODIFIED="1757954284296"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_93164426">sysctl</a>&#xa0;&#xa0;<a href="#ID_450248788">Ядро (Linux)</a>&#xa0;&#xa0;<a href="#ID_1532210282">/boot</a>&#xa0;&#xa0;<a href="#ID_1623920792">dmesg</a>&#xa0;&#xa0;netconsole&#xa0;&#xa0;kdump&#xa0;&#xa0;dracut &#xa0;<a href="#ID_19448099">initramfs</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Linux</b>
    </p>
    <p>
      <span style="color: #0000c0;">apt install </span><span style="color: #0000c0; font-weight: bold;">kmod</span>&#xa0;&#xa0;&#xa0;# Пакет <span style="font-weight: bold;">kmod</span>&#xa0;(Kernel Module Tools) - набор утилит для управления модулями ядра Linux
    </p>
    <ul>
      <li>
        &#xa0;Загрузка/выгрузка модулей (modprobe, insmod, rmmod, lsmod)
      </li>
      <li>
        Управление зависимостями модулей (автоматическая загрузка необходимых зависимостей)
      </li>
      <li>
        Работа с образами модулей (depmod для генерации зависимостей)
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">uname -r</span>&#xa0;&#xa0;# Версия ядра
    </p>
    <p>
      <span style="color: #0000c0;">lsmod</span>&#xa0;&#xa0;# Загруженные в настоящий момент модули ядра
    </p>
    <p>
      <span style="color: #0000c0;">modprobe -l</span>&#xa0;&#xa0;# Доступные модули ядра
    </p>
    <p>
      <span style="color: #0000c0;">modprobe &lt;модуль&gt;</span>&#xa0;&#xa0;# Загрузить (деликатно) модуль в ядро
    </p>
    <p>
      <span style="color: #0000c0;">modprobe -r &lt;модуль&gt;</span>&#xa0;&#xa0;# Выгрузить (деликатно) модуль из ядра
    </p>
    <p>
      <span style="color: #0000c0;">modinfo &lt;модуль&gt;</span>&#xa0;&#xa0;# информация о модуле ядра
    </p>
    <p>
      <span style="color: #0000c0;">cat /etc/modules</span>&#xa0;&#xa0;# модули, которые будут загружены в ядро автоматически
    </p>
    <p>
      rmmod - удаление модуля ядра
    </p>
    <p>
      insmod - установка модуля ядра
    </p>
    <p>
      <span style="color: #0000c0;">dmesg | less</span>&#xa0;&#xa0;# Сообщения, выводимые при загрузке ядра ОС. <span style="color: #0000c0;">-T</span>&#xa0;- указывать дату и вреия. Кольцевой буфер соообщений ядра ограничен по размеру, и старые сообщения <b>перезаписываются</b>&#xa0;новыми
    </p>
    <p>
      <span style="color: #0000c0;">dmesg | grep -i &quot;error\|fail&quot;</span>&#xa0;&#xa0;# Искать error, fail
    </p>
    <p>
      <span style="color: #0000c0;">journalctl -k</span>&#xa0;или <span style="color: #0000c0;">journalctl --dmesg </span>
    </p>
    <p>
      <span style="color: #0000c0;">unmkinitramfs -v /boot/initrd.img-&lt;версия ядра&gt; &lt;каталог&gt;</span>&#xa0;# Распаковать образ initrd, если нужно )
    </p>
    <p>
      
    </p>
    <p>
      <b><span style="color: #ff0000;">FreeBSD</span></b>
    </p>
    <p>
      <span style="color: #0000c0;">kldstat</span>&#xa0;&#xa0;# список закруженных модулей ядра
    </p>
    <p>
      <span style="color: #0000c0;">kldload&#xa0;snd_ich</span>&#xa0;&#xa0;# загрузка модуля ядра (snd_ich - драйвер звук.карты)
    </p>
    <p>
      <span style="color: #0000c0;">kldunload snd_ich&#xa0;&#xa0;#</span>&#xa0;выгрузка модуля ядра
    </p>
    <p>
      <span style="color: #0000c0;">kldconfig -r</span>&#xa0;&#xa0;# размещение модулей ядра
    </p>
    <p>
      <span style="color: #0000c0;">echo 'snd_ich_load=&quot;YES&quot;' &gt;&gt; <b>/boot/loader.conf</b></span>&#xa0;&#xa0;&#xa0;# <b>автоматическая</b>&#xa0;&#xa0;загрузка модуля ядра при загрузке системы
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">sysctl -a | more</span>&#xa0;&#xa0;# просмотр преременных ядра и их значений
    </p>
    <p>
      <span style="color: #0000c0;">sysctl -w kern.hostname=&quot;c4.any.com&quot;</span>&#xa0;&#xa0;# изменение значений преременных (на тек. сеанс)
    </p>
    <p>
      <span style="color: #0000c0;">vi /etc/<b>sysctl.conf</b>&#xa0;&#xa0;#</span>&#xa0;для сменa параментров ядра при каждой загрузке системы<br align="-webkit-auto" style="font-variant: normal; letter-spacing: normal; line-height: normal; text-indent: 0px; text-transform: none; white-space: normal; word-spacing: 0px;"/>
    </p>
  </body>
</html></richcontent>
