<node TEXT="Конфигурирование ядра Linux" FOLDED="true" ID="ID_741800951" CREATED="1534326203746" MODIFIED="1744794575491"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_93164426">sysctl</a>&#xa0;&#xa0;<a href="#ID_472056184">/proc/sys</a>&#xa0; <a href="#ID_837258504">Конфигурирование</a>
    </p>
    <ul>
      <li>
        <b>/рrос/sys</b>&#xa0;- файлы позволяют просматривать и динамически изменять значения параметров ядра<br align="-webkit-auto" style="font-variant: normal; letter-spacing: normal; line-height: normal; text-indent: 0px; text-transform: none; white-space: normal; word-spacing: 0px;"/>
      </li>
      <li>
        Большинство дистрибутивов инсталлируют исходные файлы ядра в каталог <b>/usr/src</b><br align="-webkit-auto" style="font-variant: normal; letter-spacing: normal; line-height: normal; text-indent: 0px; text-transform: none; white-space: normal; word-spacing: 0px;"/>
      </li>
    </ul>
    <p>
      <b>Изменить максимальное число файлов</b>, которые одновременно могут быть открыты в системе
    </p>
    <p>
      <span style="color: #0000c0;">cat /рrос/sys/fs/file-max</span>&#xa0;&#xa0;# --&gt; 97870
    </p>
    <p>
      <span style="color: #0000c0;">echo 30000 &gt; /proc/sys/fs/file-max</span>&#xa0;&#xa0;# Изменения не сохраняются при перезагрузке
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="Повторное создание ядра" ID="ID_1406229832" CREATED="1534332307680" MODIFIED="1638304758436"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      0. &#1048;&#1085;&#1089;&#1090;&#1072;&#1083;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1082;&#1086;&#1076;&#1086;&#1074;
    </p>
    <p>
      1.&#1057;&#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; <b>&#1092;&#1072;&#1081;&#1083; .config</b>&#160;(&#1074;&#1099;&#1073;&#1086;&#1088; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1086;&#1074; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074; &#1076;&#1083;&#1103; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1082; &#1103;&#1076;&#1088;&#1091;)
    </p>
    <p>
      make xconfig&#160;&#160;# &#1076;&#1083;&#1103; KDE
    </p>
    <p>
      make gconfig&#160;&#160;# &#1077;&#1089;&#1083;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085; GNOME
    </p>
    <p>
      <font color="#0000c0">make menuconfig</font>&#160;&#160;# &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1077;&#1090; &#1075;&#1088;&#1072;&#1092;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1099;
    </p>
    <p>
      make config&#160;&#160;# &#1089;&#1072;&#1084;&#1099;&#1081; &#1090;&#1088;&#1091;&#1076;&#1086;&#1077;&#1084;&#1082;&#1080;&#1081; &#1087;&#1091;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">make oldconfig</font>&#160;&#160;# &#1055;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1085;&#1086;&#1089;&#1077; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086; &#1103;&#1076;&#1088;&#1072; &#1074; &#1085;&#1086;&#1074;&#1091;&#1102; &#1074;&#1077;&#1088;&#1089;&#1080;&#1102; &#1103;&#1076;&#1088;&#1072; (&#1080;&#1083;&#1080; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1091;&#1102; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091;) &#1076;&#1083;&#1103; &#1089;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1088;&#1072;&#1085;&#1077;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1074;&#1096;&#1077;&#1075;&#1086;&#1089;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072; .config &#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1090;&#1077;&#1093; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1083;&#1080;&#1089;&#1100; &#1080;&#1083;&#1080; &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1085;&#1086;&#1074;&#1099;&#1084;&#1080;.
    </p>
    <p>
      2.
    </p>
    <p>
      <font color="#0000c0">make clean </font>
    </p>
    <p>
      <font color="#0000c0">make </font>
    </p>
    <p>
      <font color="#0000c0">make modules_install</font>
    </p>
    <p>
      3.
    </p>
    <p>
      &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; arch/i386/boot/bzImage &#1087;&#1086;&#1076; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; /boot/vmlinuz;
    </p>
    <p>
      &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; arch/i386/boot/System.map &#1087;&#1086;&#1076; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; /boot/System.map;
    </p>
    <p>
      &#1086;&#1090;&#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; /etc/lilo.conf (LILO) &#1080;&#1083;&#1080; /boot/grub/grub.conf
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1072; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; Linux</b>
    </p>
    <p>
      &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#8220;&#1079;&#1072;&#1087;&#1083;&#1072;&#1090;&#1099;&#8221; &#1076;&#1083;&#1103; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1081; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; &#1103;&#1076;&#1088;&#1072;
    </p>
    <p>
      <font color="#0000c0">cd &#1087;&#1091;&#1090;&#1100;_&#1082;_&#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1084;_&#1090;&#1077;&#1082;&#1089;&#1090;&#1072;&#1084;_&#1103;&#1076;&#1088;&#1072;; patch -p1 &lt; &#1092;&#1072;&#1081;&#1083;_&#1079;&#1072;&#1087;&#1083;&#1072;&#1090;&#1099;</font>
    </p>
  </body>
