<node TEXT="Загружаемые модули ядра" ID="ID_652053027" CREATED="1534332410150" MODIFIED="1638307387675"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        &#1087;&#1086;&#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1099; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074; &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1099; &#1103;&#1076;&#1088;&#1072; &#1085;&#1077;&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1074; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1069;&#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1086;&#1073;&#1083;&#1077;&#1075;&#1095;&#1072;&#1077;&#1090; &#1080;&#1085;&#1089;&#1090;&#1072;&#1083;&#1083;&#1103;&#1094;&#1080;&#1102; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1086;&#1074;, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1099;&#1081; &#1082;&#1086;&#1076; &#1103;&#1076;&#1088;&#1072; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100;. &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1091;&#1084;&#1077;&#1085;&#1100;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1103;&#1076;&#1088;&#1072;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1085;&#1077;&#1085;&#1091;&#1078;&#1085;&#1099;&#1077; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1099; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1085;&#1077; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1102;&#1090;&#1089;&#1103;
      </li>
      <li>
        &#1085;&#1077; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1102;&#1090; &#1089;&#1090;&#1086;&#1087;&#1088;&#1086;&#1094;&#1077;&#1085;&#1090;&#1085;&#1091;&#1102; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1100;. &#1055;&#1088;&#1080; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1080; &#1074;&#1099;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1088;&#1080;&#1089;&#1082; &#1085;&#1072;&#1088;&#1091;&#1096;&#1080;&#1090;&#1100; &#1088;&#1072;&#1073;&#1086;&#1090;&#1086;&#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1100; &#1103;&#1076;&#1088;&#1072;. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1074;&#1086; &#1080;&#1079;&#1073;&#1077;&#1078;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072;&#1088;&#1091;&#1096;&#1077;&#1085;&#1080;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1081;&#1090;&#1077; &#1085;&#1077;&#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1077;&#1085;&#1085;&#1099;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;
      </li>
      <li>
        &#1047;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084;&#1099;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1074; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1077; <b>/lib/modules/&#1074;&#1077;&#1088;&#1089;&#1080;&#1103;</b>
      </li>
      <li>
        <p>
          &#1055;&#1086;&#1089;&#1083;&#1077; &#1090;&#1086;&#1075;&#1086; &#1082;&#1072;&#1082; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085; &#1082; &#1103;&#1076;&#1088;&#1091;, &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1077;&#1075;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1086; &#1103;&#1074;&#1085;&#1086;&#1084;&#1091; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1091; &#1080;&#1083;&#1080; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;
        </p>
      </li>
      <li>
        &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; <b>modprobe</b>&#160; &#1087;&#1086;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1090;&#1072;&#1082;&#1078;&#1077; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1080; install &#1080; remove. &#1057; &#1080;&#1093; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1097;&#1077;&#1084;&#1091; &#1103;&#1076;&#1088;&#1091; &#1080;&#1083;&#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090; &#1085;&#1077;&#1075;&#1086;.
      </li>
    </ul>
    <p>
      <font color="#0000c0"># insmod /&#1087;&#1091;&#1090;&#1100;/&#1082;&#1091;&#1076;&#1072;/&#1084;&#1086;&#1076;&#1091;&#1083;&#1100;.k&#1086;</font>&#160;&#160;# &#1047;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1103;&#1076;&#1088;&#1072;
    </p>
    <p>
      <font color="#0000c0"># insmod /&#1087;&#1091;&#1090;&#1100;/&#1082;&#1091;&#1076;&#1072;/&#1084;&#1086;&#1076;&#1091;&#1083;&#1100;.k&#1086; io=0xXXX irq=X</font>&#160;&#160;# &#1047;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084;&#1099;&#1084; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1084; &#1103;&#1076;&#1088;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1090;&#1072;&#1082;&#1078;&#1077; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;. &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;.
    </p>
    <p>
      <font color="#0000c0"># rmmod &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;</font>&#160;&#160;# &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;. rmmod &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100;, &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1077;&#1089;&#1083;&#1080; &#1095;&#1080;&#1089;&#1083;&#1086; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1093; &#1089;&#1089;&#1099;&#1083;&#1086;&#1082; &#1085;&#1072; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; (&#1101;&#1090;&#1086; &#1095;&#1080;&#1089;&#1083;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1086; &#1074; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1077; Used by (&#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;) &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1072; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; <font color="#0000c0">lsmod</font>) &#1088;&#1072;&#1074;&#1085;&#1086; 0.
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1086;&#1083;&#1091;&#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;&#160;&#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; <b>modprobe</b>&#160;(&#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1086;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; insmod)&#160;&#160;&#1080; &#1088;&#1072;&#1089;&#1087;&#1086;&#1079;&#1085;&#1072;&#1077;&#1090; &#1084;&#1077;&#1078;&#1084;&#1086;&#1076;&#1091;&#1083;&#1100;&#1085;&#1099;&#1077; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080;, &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;, &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1099; &#1080;&#1085;&#1089;&#1090;&#1072;&#1083;&#1083;&#1103;&#1094;&#1080;&#1080; &#1080; &#1074;&#1099;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080;. &#1069;&#1090;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1087;&#1088;&#1086;&#1089;&#1084;&#1072;&#1090;&#1088;&#1080;&#1074;&#1072;&#1077;&#1090; &#1092;&#1072;&#1081;&#1083; <b>/etc/modprobe.conf</b>, &#1095;&#1090;&#1086;&#1073;&#1099; &#1091;&#1079;&#1085;&#1072;&#1090;&#1100; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086;
    </p>
    <p>
      &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;.
    </p>
    <p>
      <font color="#0000c0">modprobe -&#1089;</font>&#160;&#160;# &#1044;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; <b>/etc/modprobe.conf</b>, &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1081; &#1090;&#1077;&#1082;. &#1082;&#1086;&#1085;&#1092;. &#1103;&#1076;&#1088;&#1072;
    </p>
    <p>
      &#1048;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1080; <b>path</b>&#160; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090; &#1085;&#1072; &#1090;&#1086;, &#1075;&#1076;&#1077; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1084;&#1086;&#1076;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1080;&#1083;&#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1090;&#1080;&#1087;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; &#1074; &#1085;&#1077;&#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1093; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072;&#1093;.
    </p>
    <p>
      &#1048;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1103; <b>alias</b>&#160; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1082;&#1091; &#1089;&#1090;&#1072;&#1088;&#1096;&#1080;&#1093; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; &#1073;&#1083;&#1086;&#1095;&#1085;&#1099;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;, &#1089;&#1090;&#1072;&#1088;&#1096;&#1080;&#1093; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1100;&#1085;&#1099;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;, &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;, &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074; &#1080; &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1093; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074; &#1082; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1084; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1084;.
    </p>
    <p>
      &#1057;&#1090;&#1088;&#1086;&#1082;&#1080; &#1089; &#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1099;&#1084; &#1089;&#1083;&#1086;&#1074;&#1086;&#1084; <b>options</b>&#160; &#1085;&#1077; &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;, &#1085;&#1086; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1080;&#1093; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;. &#1054;&#1085;&#1080; &#1079;&#1072;&#1076;&#1072;&#1102;&#1090; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1099;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1102; &#1087;&#1088;&#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077;
    </p>
  </body>
</html></richcontent>
