<node TEXT="pkg (BSD)" FOLDED="true" ID="ID_1290839266" CREATED="1519112079891" MODIFIED="1749201954053"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">pkg which&#xa0;/usl/local/sbin/httpd</span>&#xa0;&#xa0;# Узнать, какому пакету принадлежит файл
    </p>
    <p>
      <span style="color: #0000c0;"># pkg install &lt;program&gt;</span>&#xa0;// установка пакетов
    </p>
    <p>
      
    </p>
    <p>
      <b>Бинарные пакеты</b>
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_info</span>&#xa0;// список доп. установленных пакетов
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_info -Lx soft1 | more</span>&#xa0;// содержимое пакета, (<b>-x</b>&#xa0;- название содержит)
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_info -rx soft1</span>&#xa0;// пакеты, необходимые данному
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_info -W file1</span>&#xa0;// пакет, которому принадлежит файл
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_info -Rx soft1</span>&#xa0;// пакеты, зависящие от данного
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_add /usr/ports/packages/All/soft1.tbz</span>&#xa0;// установить заранее скачанный пакет
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_add -r soft1</span>&#xa0;// установить пакет с ftp-сервера
    </p>
    <p>
      <span style="color: #0000c0;"># rehash</span>&#xa0;// обновление переменных окружения
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_delete -x soft1</span>&#xa0;// удалить ПО, (<b>-x</b>&#xa0;- название содержит)
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_delete -x '.*' </span>// удалить все доп. ПО
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_delete -fx soft1</span>&#xa0;// принудительно удалить ПО, например с неудаляемыми зависимостями
    </p>
    <p>
      <span style="color: #0000c0;"># pkg_delete -rx soft1</span>&#xa0;// удалить пакет с учетом зависимостей
    </p>
    <p>
      <span style="color: #0000c0;"># rehash</span>&#xa0;// после установки пакетов, для повторного сканирования PATH. (Необходимо только если используете csh)
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="Репозитории" ID="ID_734886202" CREATED="1547190357659" MODIFIED="1614542109302"><richcontent TYPE="NOTE">
<html>
  <head>
    
