      <font color="#0000c0"># setenv PACKAGESITE ftp://ftp-archive.freebsd.org/pub/FreeBSD-Archive/ports/i386/packages-8.1-release/Latest/</font>&#160;// &#1047;&#1072;&#1076;&#1072;&#1105;&#1084; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; <b>PACKAGESITE</b>, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081; &#1076;&#1083;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; FreeBSD (&#1075;&#1083;&#1072;&#1074;&#1085;&#1099;&#1081; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081; &#1079;&#1072;&#1076;&#1072;&#1105;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; <b>PACKAGEROOT</b>)
    </p>
    <p>
      &#160;&#160; <font color="#0000c0"># pkg_add -r soft1</font>&#160;// &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072;
    </p>
  </body>
</html></richcontent>
