<node TEXT="fc" ID="ID_556825136" CREATED="1530639361389" MODIFIED="1585464948743"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1484625192">history</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>fc</b>&#160;- &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1072;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1087;&#1088;&#1077;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072; &#1076;&#1083;&#1103; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072; &#1088;&#1072;&#1085;&#1077;&#1077; &#1074;&#1074;&#1077;&#1076;&#1077;&#1085;&#1085;&#1099;&#1093; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1080;&#1093; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;. &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; fc, &#1095;&#1090;&#1086;&#1073;&#1099; &#1079;&#1072;&#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1074; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1086;&#1088;&#1077;. fc&#160;&#160;- &#1087;&#1086; &#1089;&#1074;&#1086;&#1077;&#1084;&#1091; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1102; &#1074;&#1086; &#1084;&#1085;&#1086;&#1075;&#1086;&#1084; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1072; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1102; &#1082;&#1086;&#1084;&#1073;&#1080;&#1085;&#1072;&#1094;&#1080;&#1080; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096; &lt;Ctrl+P&gt;, &#1085;&#1086; &#1074;&#1084;&#1077;&#1089;&#1090;&#1086; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1074; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1091;&#1102; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; &#1086;&#1085;&#1072; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1074; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1086;&#1088;
    </p>
    <ul>
      <li>
        &#1044;&#1086;&#1073;&#1072;&#1074;&#1100;&#1090;&#1077; &#1074; &#1089;&#1074;&#1086;&#1081; &#1092;&#1072;&#1081;&#1083; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1103;, &#1087;&#1086;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1077; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1085;&#1099;&#1081; &#1092;&#1072;&#1081;&#1083; &#1074; &#1087;&#1088;&#1080;&#1077;&#1084;&#1083;&#1077;&#1084;&#1099;&#1081; &#1076;&#1083;&#1103; &#1074;&#1072;&#1089; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, ~/bin &#1080;&#1083;&#1080; /usr/local/bin), &#1089;&#1076;&#1077;&#1083;&#1072;&#1081;&#1090;&#1077; &#1092;&#1072;&#1081;&#1083; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1099;&#1084;, &#1080; &#1074;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1077; &#1085;&#1072;&#1089;&#1090;&#1086;&#1103;&#1097;&#1080;&#1081; &#1089;&#1094;&#1077;&#1085;&#1072;&#1088;&#1080;&#1081;
      </li>
      <li>
        &#1040;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1072; history
      </li>
    </ul>
    <p>
      <b>&#1057;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;</b>
    </p>
    <p>
      <font color="#0000c0">fc [-e &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1086;&#1088;] [-lnr] [first] [last]</font>&#160; &#160;# first, last - &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1089;&#1090;&#1088;&#1086;&#1082;
    </p>
    <p>
      <font color="#0000c0">fc -s [pat=rep] [command]</font>
    </p>
    <p>
      &#1095;&#1090;&#1086; &#1090;&#1072;&#1082;&#1086;&#1077; <font color="#0000c0">[pat=rep]</font>&#160;- &#1093;&#1088;&#1077;&#1085; &#1088;&#1072;&#1079;&#1073;&#1077;&#1088;&#1077;&#1096;&#1100;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1080;&#1093; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#160;</b>
    </p>
    <p>
      <font color="#0000c0">fc -l&#160; </font># &#1055;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;
