      &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; - KOI8-R
    </p>
    <p>
      &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072; - windows-1251
