<node TEXT="lzma" ID="ID_889862208" CREATED="1519112079936" MODIFIED="1519112079936"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>lzma</b>&#160;(Lempel-Ziv-Markov chain-Algorithm) - &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1089;&#1078;&#1072;&#1090;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1072; &#1076;&#1083;&#1103; &#1089;&#1078;&#1072;&#1090;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080;&#1079; LZMA SDK, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089; &#1092;&#1072;&#1081;&#1083;&#1072;&#1084;&#1080;, &#1080;&#1084;&#1077;&#1102;&#1097;&#1080;&#1084;&#1080; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1080; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077; .lzma.
    </p>
    <p>
      
    </p>
    <p>
      <b>LZMA2</b>&#160;&#8212; &#1085;&#1086;&#1074;&#1072;&#1103; &#1074;&#1077;&#1088;&#1089;&#1080;&#1103; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084;&#1072; LZMA. XZ &#8212; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1072; &#1076;&#1083;&#1103; &#1072;&#1088;&#1093;&#1080;&#1074;&#1086;&#1074;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1081; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1089;&#1078;&#1072;&#1090;&#1080;&#1103; LZMA2 &#1080; &#1087;&#1088;&#1080;&#1079;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1079;&#1072;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1072; lzma. &#1050;&#1072;&#1082; &#1080; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1099; gzip &#1080; bzip2, &#1086;&#1085; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1086;&#1084; &#1076;&#1083;&#1103; &#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072;, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1077;&#1075;&#1086; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090; &#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1085;&#1086; &#1089; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1084; tar.
    </p>
    <p>
      &#160;&#160; <b>XZ</b>&#160;- &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1072; &#1076;&#1083;&#1103; &#1072;&#1088;&#1093;&#1080;&#1074;&#1086;&#1074;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1081; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1089;&#1078;&#1072;&#1090;&#1080;&#1103; LZMA2 &#1080; &#1087;&#1088;&#1080;&#1079;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1079;&#1072;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1072; lzma. &#1050;&#1072;&#1082; &#1080; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1099; <a href="#ID_282356379">gzip</a>&#160;&#1080; <a href="#ID_1212898759">bzip2</a>, &#1086;&#1085; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1086;&#1084; &#1076;&#1083;&#1103; &#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072;, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1077;&#1075;&#1086; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090; &#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1085;&#1086; &#1089; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1084; <a href="#ID_808302690">tar</a>.
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="MNO" FOLDED="true" ID="ID_1967815575" CREATED="1519112079937" MODIFIED="1660012623770">
