  </head>
  <body>
    <p>
      <span style="color: #0000c0;">md5sum MyFile.txt</span>&#xa0;&#xa0;# Контрольная сумма файла в *nix
    </p>
    <p>
      <span style="color: #0000c0;">echo -n Welcome | md5sum</span>&#xa0;&#xa0;# MD5 hash строки
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="mdadm" FOLDED="true" ID="ID_1531600597" CREATED="1519112079937" MODIFIED="1778853126955"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1522592494">RAID (Задачи)</a>&#xa0; <a href="#ID_1144517713">RAID</a>&#xa0;&#xa0;<a href="#ID_1574804007">LVM</a>&#xa0;&#xa0;<a href="#ID_1762530044">LVM (задачи)</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>md</b>&#xa0;( multiple disks driver) - драйвер нескольких дисков
    </p>
    <p>
      <b>mdadm</b>&#xa0;- утилита для управления программными RAID-массивами. Предыдущая система <b><span style="color: #ff0000;">raidtools</span></b><span style="color: #ff0000;">&#xa0;больше не используется</span>
    </p>
    <ul>
      <li>
        служит, например, для объединения нескольких физ. дисков в один логический
      </li>
      <li>
        все делает ядро, а mdadm умеет ему объяснить
      </li>
      <li>
        <b>multipath</b>&#xa0;- когда подключаем напрямую дисковую полку с 2я контроллерами к компьютеру через 2а интерфейса и нужно объяснить OC что это одна дисковая полка
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">cat /proc/mdstat</span>&#xa0;&#xa0;# текущее <b>состояние</b>&#xa0;драйвера md, RAID-массивов в системе. для обновления состояния можно искользовать <span style="color: #0000c0;">watch &lt;команда&gt;</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">mdadm /dev/md0 -f /dev/sda7</span>&#xa0;&#xa0;#&#xa0;<b>1.</b>&#xa0;Объявить диск 7 в RAID md0 - сбойный
    </p>
    <p>
      <span style="color: #0000c0;">mdadm /dev/md0 -r /dev/sda7</span>&#xa0;&#xa0;#&#xa0;<b>2.</b>&#xa0;Удалить сбойный диск из конфигурации RAID
    </p>
    <p>
      <span style="color: #0000c0;">mdadm /dev/md0 -a /dev/sda7</span>&#xa0;&#xa0;#&#xa0;<b>3.</b>&#xa0;После вставки в корзину исправного диска, добавить его в массив
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">mdadm -C(--create) /dev/md0 -l(--level)5 -n(--raid-devices=)3 -x(--spare-devices=)1 /dev/sda[5-8]</span>&#xa0;&#xa0;#&#xa0;&#xa0;создать программный RAID 5 md0. количество дисков 3, 1 - запасной. Можно создать программный RAID (0, 1, 4, 5, 6, 10, <a href="#ID_1531600597">multipath</a>)
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">mdadm -As /dev/md0</span>&#xa0;&#xa0;# Активировать массив с помощью <b>/etc/mdadm.conf</b>
    </p>
    <p>
      <span style="color: #0000c0;">mdadm -S /dev/md0</span>&#xa0;&#xa0;# Остановить массив вручную
    </p>
  </body>
</html></richcontent>
<node TEXT="lab1" ID="ID_1081850927" CREATED="1703092501638" MODIFIED="1703092587706"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">mdadm --zero-superblock $dev_list</font>&nbsp;&nbsp;# Подготовка к созданию, “занулить суперблок”
    </p>
    <p>
      <font color="#0000c0">mdadm --create $raiddev -l $level -n $numdev $dev_list</font>&nbsp;&nbsp;# Создание массива
    </p>
    <p>
      <font color="#0000c0">mdadm -S $raiddev</font>&nbsp;&nbsp;# Остановка массива
    </p>
    <p>
      <font color="#0000c0">mdadm --detail $raiddev</font>&nbsp;&nbsp;# Информация о массиве
    </p>
    <p>
      <font color="#0000c0">mdadm --examine --scan</font>&nbsp;&nbsp;# Генерация данных для конфигурационного файла
    </p>
    <p>
      <font color="#0000c0">mdadm --detail --scan</font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">cat /proc/mdstat</font>&nbsp;&nbsp;# Информация о массиве
    </p>
    <p>
      <font color="#0000c0">echo (check|idle) &gt; /sys/block/md${N}/device/action</font>&nbsp;&nbsp;# Запуск/остановка проверки
    </p>
    <p>
      <font color="#0000c0">grep . /proc/sys/dev/raid/speed_limit_m*</font>&nbsp;&nbsp;# Изменение ограничений скорости ребилда
    </p>
    <p>
      /proc/sys/dev/raid/speed_limit_max:200000
    </p>
    <p>
      /proc/sys/dev/raid/speed_limit_min:1000
    </p>
    <p>
      <font color="#0000c0">echo 10000 &gt; /proc/sys/dev/raid/speed_limit_min</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Мониторинг" ID="ID_625296389" CREATED="1532257099074" MODIFIED="1547725237657"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; mdadm &#1080;&#1084;&#1077;&#1077;&#1090; &#1088;&#1077;&#1078;&#1080;&#1084; -monitor, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1086;&#1085;&#1072; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1086; &#1082;&#1072;&#1082; &#1076;&#1077;&#1084;&#1086;&#1085; &#1080; &#1089;&#1086;&#1086;&#1073;&#1097;&#1072;&#1077;&#1090; &#1087;&#1086; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1085;&#1085;&#1086;&#1081; &#1087;&#1086;&#1095;&#1090;&#1077; &#1086; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1072;&#1093;, &#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1096;&#1080;&#1093; &#1074; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1077; RAID.
    </p>
    <p>
      &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;
    </p>
    <ul>
      <li>
        &#1076;&#1086;&#1073;&#1072;&#1074;&#1100;&#1090;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; MAILADDR &#1074; &#1089;&#1074;&#1086;&#1081; &#1092;&#1072;&#1081;&#1083; mdadm.conf, &#1095;&#1090;&#1086;&#1073;&#1099; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1090;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084;&#1091; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1087;&#1088;&#1077;&#1076;&#1091;&#1087;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1090;&#1077; &#1076;&#1077;&#1084;&#1086;&#1085; &#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;&#1072; &#1090;&#1072;&#1082;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1085; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1083;&#1089;&#1103; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080;.
      </li>
    </ul>
    <p>
      <font color="#0000c0">ubuntu$ sudo update-rc.d mdadm enable </font>
    </p>
    <p>
      <font color="#0000c0">redhat$ sudo chkconfig mdmonitor on</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Конфигурирование" ID="ID_1909085280" CREATED="1532330652841" MODIFIED="1703092599265"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Конфигурировние</b>. Формально, команда mdadm не требует наличия файла конфигурации, но если он есть, она его использует (<b>/etc/mdadm.conf</b>).
    </p>
    <ul>
      <li>
        Рекомендуется использовать файл конфигурации. Он документирует конфигурацию системы RAID стандартным образом
      </li>
      <li>
        В качестве альтернативы использованию файла конфигурации можно задавать конфигурацию в командной строке при каждой активации массива
      </li>
      <li>
        Создав файл mdadm.conf, <b>распечатайте его и передайте на сервер</b>. Если что-то произойдет, восстановить компоненты массива RAID бывает сложно
      </li>
    </ul>
    <p>
      <font color="#0000c0">sh -с 'echo DEVICE /dev/sdb1 /dev/sdc1 /dev/sdd1 &gt; /etc/mdadm.conf'&nbsp;&nbsp;# 1</font>
    </p>
    <p>
      <font color="#0000c0">sh -c 'mdadm --detail --scan &gt;&gt; /etc/mdadm.conf'&nbsp;&nbsp;# 2</font>
    </p>
    <p>
      <font color="#0000c0">mdadm --detail --scan</font>&nbsp;&nbsp;# 3. Записать текущие настройки системы RAID в файл конфигурации
    </p>
    <p>
      <font color="#0000c0">cat /etc/mdadm.conf&nbsp;&nbsp;# 4</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">mdadm -As /dev/md0</font>&nbsp;&nbsp;# Активировать массив с помощью <b>/etc/mdadm.conf</b>
    </p>
    <p>
      <font color="#0000c0">mdadm -S /dev/md0</font>&nbsp;&nbsp;# Остановить массив вручную
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="mii-tool" ID="ID_335150978" CREATED="1744281735798" MODIFIED="1744282344508"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1623404230">ethtool</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">mii-tool</span>&#xa0;- для управления и диагностики сетевых интерфейсов на уровне Physical Layer. Она позволяет просматривать и настраивать параметры автосогласования (autonegotiation), скорости дуплекса и другие низкоуровневые настройки Ethernet-адаптеров
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Основное назначение</span>
    </p>
    <ul>
      <li>
        Проверка состояния соединения (link status)
      </li>
      <li>
        Управление автосогласованием (autonegotiation)
      </li>
      <li>
        Принудительная установка скорости (10/100 Мбит/с) и дуплекса (half/full)
      </li>
      <li>
        Диагностика проблем с физическим подключением
      </li>
      <li>
        Для гигабитных и современных адаптеров используйте ethtool
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">mii-tool eth0</span>&#xa0;&#xa0;# Проверить состояние интерфейса
    </p>
    <ul>
      <li>
        link ok - соединение установлено
      </li>
      <li>
        no link - возможно, кабель не подключен или поврежден. Также проверьте дуплекс и настройки автосогласования
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">mii-tool -v</span>&#xa0;&#xa0;# Просмотр всех интерфейсов
    </p>
    <p>
      <span style="color: #0000c0;">mii-tool -F 100baseTx-FD eth0</span>&#xa0;&#xa0;# Принудительное отключение автосогласования
    </p>
    <ul>
      <li>
        100baseTx-FD - 100 Мбит/с, full-duplex
      </li>
      <li>
        10baseT-HD - 10 Мбит/с, half-duplex
      </li>
      <li>
        1000baseT-FD - гигабит, если поддерживается
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">mii-tool -r eth0</span>&#xa0;&#xa0;# Включение автосогласования
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="mkfifo" ID="ID_1469823230" CREATED="1776605360006" MODIFIED="1776606118241"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_993067695">FIFO/named pipe</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">mkfifo</span>&#xa0;- для создания специальных файлов типа *named pipe* (FIFO - First In, First Out). Используется для межпроцессного взаимодействия (IPC) через файловую систему
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Синтаксис</span>
    </p>
    <p>
      <span style="color: #0000c0; font-family: Lucida Console;">mkfifo [ОПЦИИ] ИМЯ_КАНАЛА...</span>
    </p>
    <ul>
      <li>
        -m, --mode=РЕЖИМ - Права доступа (как в chmod). По умолчанию: 0666 &amp; ~umask
      </li>
      <li>
        -Z - Задать контекст SELinux (если ядро/политика поддерживают)
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Принцип работы</span>
    </p>
    <ul>
      <li>
        Файл появляется в ФС, но <span style="font-weight: bold;">данные не пишутся на диск</span>&#xa0;- передаются напрямую между процессами в памяти ядра
      </li>
      <li>
        open() на чтение или запись <span style="font-weight: bold;">блокируется</span>, пока канал не откроется с противоположной стороны
      </li>
      <li>
        После закрытия всех дескрипторов данные удаляются
      </li>
      <li>
        Тип файла:<span style="font-weight: bold;">p</span>&#xa0;(проверяется через <span style="color: #0000c0;">stat -c %F</span>&#xa0;или <span style="color: #0000c0;">ls -l</span>).
      </li>
      <li>
        <span style="font-weight: bold;">Буфер</span>: размер кольцевого буфера ядра обычно ~<span style="font-weight: bold;">64 КБ</span>. При превышении писатель блокируется, пока читатель не освободит место
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Примеры</span>
    </p>
    <p>
      <span style="color: #0000c0;">mkfifo /tmp/app_pipe</span>&#xa0;&#xa0;# Базовое создание
    </p>
    <p>
      <span style="color: #0000c0;">mkfifo -m 0660 /var/run/monitor.fifo</span>&#xa0;&#xa0;# С явными правами
    </p>
    <p>
      # Типичный сценарий: producer → consumer
    </p>
    <p>
      <span style="color: #0000c0;">mkfifo /tmp/pipe</span>
    </p>
    <p>
      <span style="color: #0000c0;">producer &gt; /tmp/pipe &amp;</span>&#xa0;&#xa0;&#xa0;# процесс-писатель
    </p>
    <p>
      <span style="color: #0000c0;">consumer &lt; /tmp/pipe</span>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# процесс-читатель
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Связанные команды:</span>
    </p>
    <p>
      pipe (| - анонимный канал), tee, tail -f, inotifywait, stdbuf, socat
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="mknod" ID="ID_463597007" CREATED="1742284039916" MODIFIED="1742285555452"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1320145061">udev</a>&#xa0;&#xa0;<a href="#ID_1715541797">character device</a>&#xa0;&#xa0;<a href="#ID_983336457">block device</a>&#xa0;&#xa0;<a href="#ID_993067695">FIFO/named pipe</a>&#xa0; <a href="#ID_1643006858">MAJOR и MINOR</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">mknod</span>&#xa0;- для создания специальных файлов устройств, таких как символьные (character) и блочные (block) устройства
    </p>
    <p>
      <span style="font-weight: bold;">Используется:</span>
    </p>
    <ul>
      <li>
        Современные системы обычно автоматически создают файлы устройств с помощью менеджера устройств (udev), поэтому ручное использование mknod требуется редко
      </li>
      <li>
        При разработке драйверов или настройке системы
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">mknod [опции] имя_файла тип_файла [мажорное_число] [минорное_число]</span>
    </p>
    <ul>
      <li>
        b - блочное устройство (block device).
      </li>
      <li>
        c или u - символьное устройство (character device).
      </li>
      <li>
        p - именованный канал (FIFO, pipe). В этом случае мажорное и минорное числа не указываются.
      </li>
      <li>
        мажорное_число - число, определяющее тип устройства (драйвер).
      </li>
      <li>
        минорное_число - число, определяющее конкретное устройство в рамках одного драйвера
      </li>
      <li>
        -m или --mode - задаёт права доступа к создаваемому файлу
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">mknod /dev/my_char_device </span><span style="color: #0000c0; font-weight: bold;">c</span><span style="color: #0000c0;">&#xa0;&#xa0;240 0</span>&#xa0;&#xa0;# Создание <span style="font-weight: bold;">символьного</span>&#xa0;&#xa0;устройства
    </p>
    <p>
      <span style="color: #0000c0;">mknod /dev/my_block_device </span><span style="color: #0000c0; font-weight: bold;">b</span><span style="color: #0000c0;">&#xa0;&#xa0;8 1</span>&#xa0;&#xa0;#&#xa0;&#xa0;Создание <span style="font-weight: bold;">блочного</span>&#xa0;&#xa0;устройства
    </p>
    <p>
      <span style="color: #0000c0;">mknod my_fifo </span><span style="color: #0000c0; font-weight: bold;">p</span>&#xa0;&#xa0;#&#xa0;&#xa0;Создание <span style="font-weight: bold;">именованного канала</span>&#xa0;(FIFO):<br/><span style="color: #0000c0;">mknod </span><span style="color: #0000c0; font-weight: bold;">-m 666</span><span style="color: #0000c0;">&#xa0;/dev/my_char_device c 240 0</span>&#xa0;&#xa0;# Установка <span style="font-weight: bold;">прав</span>&#xa0;доступа
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="mock" ID="ID_1979914380" CREATED="1774429734990" MODIFIED="1774432085663"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_375209045">rpmbuild</a>&#xa0;&#xa0;<a href="#ID_173765775">Сборка RPM-пакетов</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">mock</span>&#xa0;- Инструмент для безопасной и воспроизводимой сборки RPM-пакетов в изолированном окружении (chroot). Гарантирует чистоту сборки: устанавливает только явно указанные в .spec зависимости (`BuildRequires`), исключая влияние пакетов хост-системы
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Настройка прав доступа. </span>По умолчанию mock требует root. Для работы от обычного пользователя:
    </p>
    <p>
      <span style="color: #0000c0;">sudo usermod -a -G mock $USER</span>&#xa0;&#xa0;# Добавить пользователя в группу mock
    </p>
    <p>
      <span style="color: #0000c0;">newgrp mock </span>&#xa0;# Применить изменения группы (или перезайти)
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Конфигурация</span>
    </p>
    <ul>
      <li>
        Глобальные конфиги: /etc/mock/
      </li>
      <li>
        Конфиги окружений (chroot): /etc/mock/*.cfg (например, rocky-8-x86_64.cfg)
      </li>
      <li>
        Пользовательские настройки: ~/.config/mock.cfg
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Пример ~/.config/mock.cfg</span>
    </p>
    <p>
      # Использовать кэш пакетов для ускорения сборок
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">config_opts['plugin_conf']['package_cache_enable'] = True</span>
    </p>
    <p>
      # Пробросить переменные окружения (например, http_proxy)
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">config_opts['environment']['http_proxy'] = 'http://proxy.local:3128'</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Основные команды&#xa0;</span>
    </p>
    <p>
      <span style="color: #0000c0;">mock -r &lt;config&gt; package.spec</span>&#xa0;&#xa0;# Сборка пакета в указанном окружении
    </p>
    <p>
      <span style="color: #0000c0;">mock --rebuild package.src.rpm</span>&#xa0;&#xa0;# Пересборка из исходного SRPM
    </p>
    <p>
      <span style="color: #0000c0;">mock --shell &lt;config&gt;</span>&#xa0;&#xa0;# Войти в shell изолированного окружения (для отладки)
    </p>
    <p>
      <span style="color: #0000c0;">mock --clean &lt;config&gt;</span>&#xa0;&#xa0;# Очистить chroot окружение
    </p>
    <p>
      <span style="color: #0000c0;">mock --scrub=all</span>&#xa0;&#xa0;# Полная очистка кэша и всех chroot
    </p>
    <p>
      <span style="color: #0000c0;">mock --resultdir=/path</span>&#xa0;&#xa0;# Указать папку для сохранения результатов
    </p>
    <p>
      <span style="color: #0000c0;">mock --enable-plugin=ccache</span>&#xa0;&#xa0;# Включить плагин кэширования компиляции
    </p>
    <p>
      <span style="color: #0000c0;">less ~/mock-results/*.log</span>&#xa0;&#xa0;# Просмотр логов последней сборки
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Примеры использования</span>
    </p>
    <p>
      <span style="color: #0000c0;">mock -r rocky-9-x86_64 ~/rpmbuild/SPECS/app.spec</span>&#xa0;&#xa0;# Сборка для Rocky Linux 9
    </p>
    <p>
      <span style="color: #0000c0;">mock -r fedora-38-x86_64 --enable-plugin=ccache --resultdir=$PWD ./app.spec</span>&#xa0;&#xa0;# Сборка с использованием кэша и сохранением в текущую папку
    </p>
    <p>
      <span style="color: #0000c0;">mock -r alma-8-x86_64 --shell</span>&#xa0;&#xa0;# Отладка: вход в окружение для ручной проверки
    </p>
    <ul>
      <li>
        Внутри окружения доступны: --install, --copyin, --copyout
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Работа с плагинами</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">ccache</span>&#xa0;- кэширование объектов компиляции (ускоряет повторные сборки)
      </li>
      <li>
        <span style="font-weight: bold;">package_cache</span>&#xa0;- общий кэш скачанных RPM для всех chroot
      </li>
      <li>
        <span style="font-weight: bold;">tmpfs</span>&#xa0;- сборка в оперативной памяти (требует много RAM, но очень быстрая)
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="more" ID="ID_1750078121" CREATED="1519112079937" MODIFIED="1589970162649"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>more</b>&#160;# &#1087;&#1077;&#1081;&#1076;&#1078;&#1077;&#1088; - &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1075;&#1086; &#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1099;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1074; &#1054;&#1057; &#1085;&#1072; Unix (&#1077;&#1089;&#1090;&#1100; &#1080; &#1074; Windows). &#1057;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1083;&#1089;&#1103; &#1076;&#1083;&#1103; &#1087;&#1077;&#1095;&#1072;&#1090;&#1085;&#1099;&#1093; &#1084;&#1072;&#1096;&#1080;&#1085;&#1086;&#1082; &#1080; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1086;&#1074;.
    </p>
    <ul>
      <li>
        &#1087;&#1086;&#1076; &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1077;&#1081; BSD
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>Space</b>&#160;- &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076; &#1085;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1091;&#1102; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091;
    </p>
    <p>
      <b>Enter</b>&#160;- &#1089;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077; &#1074;&#1085;&#1080;&#1079; &#1085;&#1072; &#1086;&#1076;&#1085;&#1091; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091;
    </p>
    <p>
      <b>q</b>&#160;- &#1074;&#1099;&#1093;&#1086;&#1076;
    </p>
    <p>
      <b>v</b>&#160;- &#1087;&#1088;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076; &#1082; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; <a href="#ID_1595226177">vi</a>
    </p>
    <p>
      <b>h</b>&#160;- help
    </p>
    <p>
      <b>/</b>&#160;- &#1087;&#1086;&#1080;&#1089;&#1082; (&#1089;&#1074;&#1077;&#1088;&#1093;&#1091; &#1074;&#1085;&#1080;&#1079;) --&gt; n (next)
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;
    </p>
    <p>
      &#1050;&#1088;&#1086;&#1084;&#1077; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096; &#1087;&#1088;&#1086;&#1073;&#1077;&#1083;&#1072; &#1080; &#171;Enter&#187;, &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1087;&#1072;&#1091;&#1079;&#1099; &#1077;&#1097;&#1105; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1080; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1082;&#1072;&#1082; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1077; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1072; &#171;&#1042;&#187; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1090;&#1077;&#1082;&#1089;&#1090; &#1085;&#1072; &#1086;&#1076;&#1080;&#1085; &#1101;&#1082;&#1088;&#1072;&#1085; &#1085;&#1072;&#1079;&#1072;&#1076;). &#1042;&#1099;&#1081;&#1090;&#1080; &#1080;&#1079; &#1088;&#1077;&#1078;&#1080;&#1084;&#1072; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1080; &#171;Q&#187;. &#1054;&#1073;&#1086; &#1074;&#1089;&#1077;&#1093; &#1086;&#1087;&#1094;&#1080;&#1103;&#1093; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; more &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100; &#1085;&#1072; &#1089;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077; man.
    </p>
    <p>
      
    </p>
    <p>
      &#1089;&#1084;. <a href="#ID_1232049678">less</a>
