<node TEXT="Окна (вкладки)" ID="ID_1965889676" CREATED="1578219849712" MODIFIED="1630706229677"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Prefix &#1089; - <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100;</b>&#160;&#1085;&#1086;&#1074;&#1086;&#1077; &#1086;&#1082;&#1085;&#1086;
    </p>
    <p>
      Prefix A - &#1055;&#1077;&#1088;&#1077;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1090;&#1100;&#160;&#1090;&#1077;&#1082;&#1091;&#1097;&#1091;&#1102; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1091;
    </p>
    <p>
      &#160;&#1088;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1086;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1080;. &#1044;&#1083;&#1103; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1077;&#1089;&#1089;&#1080;&#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1099; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;
    </p>
    <p>
      <font color="#0000c0">exit</font>&#160;&#1080;&#1083;&#1080; Ctrl+d&#160;# &#1047;&#1072;&#1082;&#1088;&#1099;&#1090;&#1100; &#1086;&#1082;&#1085;&#1086;
    </p>
    <p>
      Prefix k - <b>&#1059;&#1073;&#1080;&#1090;&#1100;</b>&#160;&#1086;&#1082;&#1085;&#1086;
    </p>
    <p>
      Prefix d - &#1054;&#1090;&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1100;&#1089;&#1103; (detach) &#1086;&#1090; &#1089;&#1082;&#1088;&#1080;&#1085;&#1089;&#1077;&#1089;&#1089;&#1080;&#1080;
    </p>
    <p>
      Prefix z - &#1054;&#1090;&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1100; (suspend) &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1091;&#1102; &#1089;&#1077;&#1089;&#1089;&#1080;&#1102; &#1080; &#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1077;&#1077; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;&#1085;&#1086;&#1081; &#1082;&#1072;&#1082; &#1092;&#1086;&#1085;&#1086;&#1074;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;
    </p>
    <p>
      Prefix \ - &#1047;&#1072;&#1082;&#1088;&#1099;&#1090;&#1100; screen &#1089;&#1077;&#1089;&#1089;&#1080;&#1102; &#1089;&#1086; &#1074;&#1089;&#1077;&#1084;&#1080; &#1086;&#1082;&#1085;&#1072;&#1084;&#1080;
    </p>
    <p>
      Prefix ? - help &#1087;&#1086; screen &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072;&#1084;, &#1076;&#1083;&#1103; &#1074;&#1099;&#1093;&#1086;&#1076;&#1072; &#1087;&#1088;&#1086;&#1073;&#1077;&#1083; &#1080;&#1083;&#1080; Enter
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1084;&#1091;&#1078;&#1076;&#1091; &#1086;&#1082;&#1085;&#1072;&#1084;&#1080;</b>
    </p>
    <p>
      Prefix &#1085;&#1086;&#1084;&#1077;&#1088;_&#1086;&#1082;&#1085;&#1072;
    </p>
    <p>
      Prefix [n|p &#1080;&#1083;&#1080; space|Backspace] - n - next, p - previous
    </p>
    <p>
      Prefix Prefix - &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1077;&#1077; &#1086;&#1082;&#1085;&#1086;
    </p>
    <p>
      Prefix &#8220; (Shift+' ) - &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; &#1086;&#1082;&#1086;&#1085;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086; &#1085;&#1077;&#1084;&#1091; &#1089;&#1090;&#1088;&#1077;&#1083;&#1082;&#1072;&#1084;&#1080; &#1080; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; (Enter)
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      Prefix &#1057; - &#1054;&#1095;&#1080;&#1089;&#1090;&#1080;&#1090;&#1100; &#1101;&#1082;&#1088;&#1072;&#1085; &#1086;&#1082;&#1085;&#1072;
    </p>
    <p>
      Prefix H -&#160;&#160;&#1055;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1086;&#1082;&#1085;&#1072; &#1074; &#1092;&#1072;&#1081;&#1083; screenlog
