<node TEXT="Перемещение по экрану" ID="ID_890951815" CREATED="1578145681756" MODIFIED="1584955282478"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1086;&#1082;&#1088;&#1091;&#1090;&#1082;&#1072; &#1074; Screen</b>
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        <b>Prefix Esc (&#1080;&#1083;&#1080; [ )</b>&#160;- &#1087;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084; &#1087;&#1088;&#1086;&#1082;&#1088;&#1091;&#1090;&#1082;&#1080; - &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1074;&#1099;&#1074;&#1086;&#1076;&#1091; screen, &#1088;&#1077;&#1078;&#1080;&#1084; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;, &#1089;&#1090;&#1088;&#1077;&#1083;&#1082;&#1080;, <b>PgUp/PgDn</b>. &#1042;&#1099;&#1093;&#1086;&#1076; - <b>q (&#1080;&#1083;&#1080; Esc)</b>
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086; &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1088;&#1086;&#1082;&#1088;&#1091;&#1090;&#1082;&#1072; &#1079;&#1072;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1083;&#1072; &#1074; &#1087;&#1088;&#1080;&#1074;&#1099;&#1095;&#1085;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1074; &#1092;&#1072;&#1081;&#1083;&#1077; <b>.screenrc</b>&#160; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; <b>termcapinfo</b>
      </li>
      <li>
        <b>Prefix+a</b>&#160;- &#1087;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080; <b>&#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;</b>. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076; &#1073;&#1077;&#1079; &#1089;&#1082;&#1088;&#1080;&#1085;&#1072; &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1101;&#1090;&#1086; Ctrl+a (&#1085;&#1086; &#1079;&#1076;&#1077;&#1089;&#1100; &#1101;&#1090;&#1086; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;)
      </li>
    </ul>
    <p>
      <b>&#1042; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;/&#1089;&#1082;&#1088;&#1086;&#1083;&#1083;&#1080;&#1085;&#1075;&#1072;:</b>
    </p>
    <p>
      <b>q</b>&#160;&#1080;&#1083;&#1080; <b>2Enter</b>&#160;- &#1074;&#1099;&#1093;&#1086;&#1076; &#1080;&#1079; &#1088;&#1077;&#1078;&#1080;&#1084;&#1072; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074; &#1085;&#1086;&#1088;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;
    </p>
    <p>
      0 - &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076; &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;
    </p>
    <p>
      $ - &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076; &#1074; &#1082;&#1086;&#1085;&#1077;&#1094; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;
    </p>
    <p>
      Ctrl+b - &#1085;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091; &#1074;&#1074;&#1077;&#1088;&#1093;
    </p>
    <p>
      Ctrl+f - &#1085;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091; &#1074;&#1085;&#1080;&#1079;
    </p>
    <p>
      Ctrl+d - &#1085;&#1072; &#1087;&#1086;&#1083; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &#1074;&#1085;&#1080;&#1079;
    </p>
    <p>
      Ctrl+u - &#1085;&#1072; &#1087;&#1086;&#1083; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &#1074;&#1074;&#1077;&#1088;&#1093;
    </p>
    <p>
      j / k / h / l - &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      g/G - &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1086;/&#1082;&#1086;&#1085;&#1077;&#1094; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      Space - &#1087;&#1077;&#1088;&#1074;&#1086;&#1077; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1077; - &#1085;&#1072;&#1095;&#1072;&#1083;&#1086; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103;, &#1074;&#1090;&#1086;&#1088;&#1086;&#1077; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1077; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1103; &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1077;&#1090; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1077; &#1074; &#1073;&#1091;&#1092;&#1077;&#1088; &#1086;&#1073;&#1084;&#1077;&#1085;&#1072; screen
    </p>
    <p>
      Ctrl+] - &#1074;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1073;&#1091;&#1092;&#1077;&#1088;&#1072; screen
    </p>
    <p>
      &#1050;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; &#1085;&#1077;&#1082;&#1080;&#1081; &quot;&#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081;&quot; &#1073;&#1091;&#1092;&#1077;&#1088; screen, &#1072; &#1085;&#1077; &#1074; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1083;&#1080;&#1087;&#1073;&#1086;&#1088;&#1076; &#1074;&#1072;&#1096;&#1077;&#1081; OS.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1080;&#1089;&#1082;</b>
    </p>
    <p>
      /, ? - &#1087;&#1086;&#1080;&#1089;&#1082; (&#1089;&#1074;&#1077;&#1088;&#1093;&#1091; / &#1089;&#1085;&#1080;&#1079;&#1091;) --&gt; n\N - &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1081;\&#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1080;&#1081;&#160;&#160;&#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;
    </p>
    <p>
      &#160;&#160;-i - &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1086;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072;
    </p>
  </body>
