<node TEXT="Разделение окна (регионы)" ID="ID_1026651101" CREATED="1578259961454" MODIFIED="1603137059972"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1056;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1086;&#1082;&#1085;&#1072; (&#1088;&#1077;&#1075;&#1080;&#1086;&#1085;&#1099;)</b>
    </p>
    <ul>
      <li>
        &#1056;&#1077;&#1075;&#1080;&#1086;&#1085;&#1099; &#1087;&#1086;&#1089;&#1083;&#1077; &#1086;&#1090;&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1086;&#1090; &#1089;&#1077;&#1089;&#1089;&#1080;&#1080; <b>&#1085;&#1077; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103;</b>
      </li>
      <li>
        <b>&#1044;&#1083;&#1103; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103;</b>&#160; <b>Prefix :&#160;<font color="#0000c0">&#160;layout save default</font></b>
      </li>
    </ul>
    <ol>
      <li>
        Prefix S - &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1087;&#1086; &#1075;&#1086;&#1088;&#1080;&#1079;&#1086;&#1085;&#1090;&#1072;&#1083;&#1080;<br/>Prefix | (pipe) - &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1087;&#1086; &#1074;&#1077;&#1088;&#1090;&#1080;&#1082;&#1072;&#1083;&#1080;
      </li>
      <li>
        Prefix Tab - &#1087;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080; &#1082; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1081; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1080; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        Prefix &#1089; - &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1085;&#1086;&#1074;&#1086;&#1077; &#1086;&#1082;&#1085;&#1086; &#1074; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1081; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1080; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103;<br/>
      </li>
      <li>
        Prefix &lt;&#1085;&#1086;&#1084;&#1077;&#1088; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080;&gt; - &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1079;&#1080;&#1090;&#1100; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1091;<br/>
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      Prefix X (Previx :remove) - &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1077; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; (&#1090;&#1091; &#1079;&#1086;&#1085;&#1091;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1089;&#1077;&#1081;&#1095;&#1072;&#1089; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088;)
    </p>
    <p>
      Prefix Q - &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1074;&#1089;&#1077; &#1086;&#1082;&#1085;&#1072; &#1080; &#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100;<b>&#160; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1077; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072;</b>&#160; (&#1085;&#1086;&#1088;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;) <b>Ptefix :</b><br/><font color="#ff0000">resize +N&#160;&#160;&#160;&#160;&#160;&#160;&#160;increase current region by N </font>
    </p>
    <p>
      <font color="#ff0000">resize -N&#160;&#160;&#160;&#160;&#160;&#160;&#160;decrease current region by N </font>
    </p>
    <p>
      <font color="#ff0000">resize N&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;set current region to N </font>
    </p>
    <p>
      resize 20%&#160;&#160;&#160;&#160;&#160;&#160;set current region to 20% of original size
    </p>
    <p>
      resize +20%&#160;&#160;&#160;&#160;&#160;increase current region by 20%
    </p>
    <p>
      <b>resize -b =&#160;&#160;&#160;&#160;&#160;make all windows equally</b>
    </p>
    <p>
      <font color="#ff0000">resize max&#160;&#160;&#160;&#160;&#160;&#160;maximize current region </font>
    </p>
    <p>
      <font color="#ff0000">resize min&#160;&#160;&#160;&#160;&#160;&#160;minimize current region</font>
    </p>
  </body>
</html></richcontent>
