</node>
<node TEXT="Сессии" ID="ID_1671311241" CREATED="1578258045762" MODIFIED="1651512652155"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">screen&nbsp; </font># Чистый запуск
    </p>
    <p>
      <font color="#0000c0">screen -[ls|list]</font>&nbsp;&nbsp;#&nbsp;Найти запущенные screen-сессии
    </p>
    <p>
      <font color="#0000c0">screen &lt;команда&gt;</font>&nbsp;&nbsp;# Запуск сессии с выполнением команды
    </p>
    <p>
      <font color="#0000c0">screen -S &lt;имя&gt;</font>&nbsp;&nbsp;# <b>Создать</b>&nbsp;&nbsp;сессию с указанным именем<br/><font color="#0000c0">screen -S &lt;имя&gt; &lt;команда&gt;</font>&nbsp;&nbsp;# Создать сессию с указанным именем и выполнить команду
    </p>
    <p>
      <font color="#0000c0">screen <b>-dmS</b>&nbsp;&lt;имя_скрина&gt; &lt;команда&gt;</font>&nbsp;&nbsp;# Запуск скрина в свернутом виде. <b>-d</b>&nbsp;- свернуть, <b>-m</b>&nbsp;- создать, <b>-S</b>&nbsp;- именовать. <b>Prefix&nbsp;a d</b>&nbsp;- Отсоединиться от <b>sub-screen</b>
    </p>
    <p>
      <b>Prefix :</b>, <font color="#0000c0">sessionname</font>&nbsp;&nbsp;# <b>Переименовать</b>&nbsp;текущую сессию<br/>
    </p>
    <p>
      <font color="#0000c0">screen -r</font>&nbsp;&nbsp;# <b>Соединиться (restore)</b>&nbsp;с открытой скринсессией
    </p>
    <p>
      <font color="#0000c0">screen -r &lt;имя_скрина&gt;</font>&nbsp;&nbsp;&nbsp;# Вернуться к скрину команды
    </p>
    <p>
      <font color="#0000c0">screen -x &lt;имя_скрина&gt;</font>&nbsp;&nbsp;#&nbsp;Вернуться к развернутому в ином терминале скрину
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">screen -SX &lt;имя_сессии&gt; <b>quit</b></font>&nbsp;&nbsp;# <b>Убить</b>&nbsp;сессию. -X = Execute command, -S session PID to execute on
    </p>
    <p>
      <font color="#0000c0">screen -X -S SCREENID kill </font>
    </p>
    <p>
      <font color="#0000c0">screen -S SCREENNAME -p 0 -X quit</font>
    </p>
    <p>
      <font color="#0000c0">screen -wipe</font>&nbsp;&nbsp;# Для сессий в статуве Dead
    </p>
    <p>
      
    </p>
    <p>
      <b>Prefix d</b>&nbsp;- Отсоединиться (detach) от скринсессии
    </p>
    <p>
      <b>Prefix&nbsp;a d</b>&nbsp;- Отсоединиться от <b>sub-screen</b>
    </p>
    <p>
      <b>Prefix z</b>&nbsp;- Отсоединить (suspend) консольную сессию и оставить ее запущенной как фоновый процесс
    </p>
    <p>
      <b>Prefix <font color="#ff0000">\</font></b>&nbsp;или <b><font color="#ff0000">k</font></b>- Убить screen сессию со всеми окнами
    </p>
    <p>
      <b>Prefix :quit</b>&nbsp;- Убить сессию со всеми окнами
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      --------------------------------------
    </p>
    <p>
      Prefix x&nbsp;&nbsp;lock session&nbsp;&nbsp;Enter user password to unlock
    </p>
    <p>
      CTRL+a c will create a new 'tab' in the outer screen session.
    </p>
    <p>
      CTRL+a a c will create a new 'tab' in the session 1 deeper than the previous
    </p>
    <p>
      CTRL+a a a c creates a new tab in the session 1 deeper than the previous
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
