      </li>
      <li>
        &#1054;&#1076;&#1080;&#1085; &#1089;&#1090;&#1072;&#1088;&#1090;&#1091;&#1077;&#1090; <font color="#0000c0">screen</font>. &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1097;&#1080;&#1081;&#1089;&#1103; &#1089;&#1090;&#1072;&#1088;&#1090;&#1091;&#1077;&#1090; <font color="#0000c0">screen -x</font>
      </li>
      <li>
        &#1054;&#1073;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1079;&#1072;&#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077; <b>&#1087;&#1086;&#1076; &#1086;&#1076;&#1085;&#1080;&#1084; &#1080; &#1090;&#1077;&#1084; &#1078;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;</b>
      </li>
    </ol>
  </body>
</html></richcontent>
