      &#1063;&#1090;&#1086;&#1073;&#1099; &#1074; &#1086;&#1082;&#1085;&#1077; &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1085;&#1086; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1083;&#1072;&#1089;&#1100; &#1082;&#1080;&#1088;&#1080;&#1083;&#1083;&#1080;&#1094;&#1072;
