      </li>
      <li>
        &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; <b>PC - &#1082;&#1086;&#1088;&#1087;&#1086;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080;</b>&#160;&gt; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1082;&#1083;&#1102;&#1095; &gt; &#1072;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1077;&#1075;&#1086; &#1074; Microsoft. &#1057;&#1082;&#1088;&#1080;&#1087;&#1090;:<br/><font color="#0000c0">cscript C:\Windows\System32\slmgr.vbs -ipk</font>
      </li>
      <li>
        <b>&quot;&#1085;&#1072;&#1091;&#1095;&#1080;&#1090;&#1100;&quot; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1101;&#1090;&#1086;&#1084;&#1091; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;</b>. &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; <b>SRV (Service Location)</b>. &#1050;&#1086;&#1075;&#1076;&#1072; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;, &#1077;&#1089;&#1083;&#1080; &#1074; DNS-&#1089;&#1083;&#1091;&#1078;&#1073;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1072; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1077;&#1081; &#1087;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1091; &#1086;&#1090; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; &gt; &#1047;&#1072;&#1087;&#1080;&#1089;&#1100; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077;. &#1045;&#1089;&#1083;&#1080; DNS &#1076;&#1080;&#1085;&#1072;&#1084;. &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1102; &#1085;&#1077; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &gt; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1088;&#1091;&#1082;&#1072;&#1084;&#1080; (&#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; SRV-&#1079;&#1072;&#1087;&#1080;&#1089;&#1080;) &#1083;&#1080;&#1073;&#1086; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1085;&#1072; &#1087;&#1088;&#1103;&#1084;&#1091;&#1102; &#1084;&#1086;&#1076;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1102; &#1088;&#1077;&#1077;&#1089;&#1090;&#1088;&#1072;, &#1090;.&#1077;. &#1085;&#1072; &#1085;&#1072;&#1096;&#1080;&#1093; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;&#1093; &#1074;&#1085;&#1086;&#1089;&#1080;&#1090;&#1100; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074; &#1088;&#1077;&#1077;&#1089;&#1090;,&#160;&#1103;&#1074;&#1085;&#1086; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1103; &#1087;&#1091;&#1090;&#1100; &#1076;&#1083;&#1103; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080;.
      </li>
      <li>
        &#1050;&#1072;&#1078;&#1076;&#1099;&#1077; <b>180 &#1076;&#1085;&#1077;&#1081; &#1087;&#1077;&#1088;&#1077;&#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1103;</b>. KMS &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1090;&#1086;&#1088; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1084;&#1085;&#1086;&#1075;&#1080;&#1084;&#1080; &#1072;&#1085;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1089;&#1072;&#1084;&#1080; &#1082;&#1072;&#1082; &#1074;&#1080;&#1088;&#1091;&#1089;. &#1042;&#160;&#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1077; &#1077;&#1089;&#1090;&#1100; &#1086;&#1085;&#1083;&#1072;&#1081;&#1085;-&#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1099; KMS-&#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080;
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; <b>HTTP-&#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;</b>, &#1085;&#1086; &#1087;&#1086;&#1088;&#1090; &#1085;&#1077;&#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; (<b>TCP port 1688</b>)
      </li>
    </ol>
