<node TEXT="AD DS" ID="ID_84000591" CREATED="1519112079756" MODIFIED="1519112079756"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>AD DS Database</b>&#160;- &#1089;&#1076;&#1077;&#1083;&#1072;&#1085; &#1076;&#1083;&#1103; &#1086;&#1087;&#1088;&#1080;&#1084;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;.
    </p>
    <ul>
      <li>
        <b>Domain Partition</b>&#160;- &#1073;&#1072;&#1079;&#1072; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080;. &#1047;&#1076;&#1077;&#1089;&#1100; &#1093;&#1088;&#1072;&#1085;. &#1080;&#1085;&#1092;. &#1086;&#1073; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;&#1093; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;. &#1056;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1084;/&#1091; DC &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1080; &#1090;&#1086;&#1075;&#1086; &#1078;&#1077; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;.
      </li>
      <li>
        <b>Configuration Partition</b>&#160;- &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1089;&#1103; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1072;&#1103; &#1080;&#1085;&#1092;. &#1086;&#1073; &#1080;&#1085;&#1092;&#1088;&#1072;&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1077; (&#1092;&#1086;&#1088;&#1077;&#1089;&#1090;, &#1083;&#1077;&#1074;, &#1076;&#1086;&#1084;&#1077;&#1085;). &#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074;&#1085;&#1086;&#1089;&#1103;&#1090;&#1089;&#1103; &#1088;&#1077;&#1076;&#1082;&#1086;. &#1056;&#1077;&#1087;&#1083;&#1080;&#1094;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1074;&#1089;&#1077; DC &#1083;&#1077;&#1089;&#1072;.
      </li>
      <li>
        <b>Schema Partition</b>&#160;- &#1079;&#1076;&#1077;&#1089;&#1100; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1089;&#1103; &#1089;&#1093;&#1077;&#1084;&#1072; AD. &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1086;&#1074; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074; - &#1082;&#1083;&#1072;&#1089;&#1089;&#1099;. &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074; - &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099;. &#1057;&#1074;&#1103;&#1079;&#1100; &#1082;&#1083;&#1072;&#1089;&#1089;&#1086;&#1074; &#1080; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1086;&#1074;. &#1048;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074;&#1085;&#1086;&#1089;&#1103;&#1090;&#1089;&#1103; &#1088;&#1077;&#1076;&#1082;&#1086;. &#1056;&#1077;&#1087;&#1083;&#1080;&#1094;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1074;&#1089;&#1077; DC &#1083;&#1077;&#1089;&#1072;.
      </li>
      <li>
        <b>Application Partition</b>&#160;- &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1103;&#1077;&#1084;&#1099;&#1081; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1089;&#1074;&#1086;&#1080; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1099; &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103; &#1080; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1100; &#1080;&#1079; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;. &#1048;&#1084;&#1077;&#1077;&#1090; &#1076;&#1074;&#1072; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1072; - Domen DNS Zones, Forest DNS Zones.
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
