  <body>
    <p>
      <b>&#1054;&#1095;&#1077;&#1088;&#1077;&#1076;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103;</b>
    </p>
    <ul>
      <li>
        &#1077;&#1089;&#1083;&#1080; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; <b>&#1085;&#1077; &#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1086;&#1088;&#1077;&#1095;&#1072;&#1090;</b>&#160;&#1076;&#1088;&#1091;&#1075; &#1076;&#1088;&#1091;&#1075;&#1091;, &#1090;&#1086; &#1086;&#1085;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1074;&#1089;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1099; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1084;
      </li>
      <li>
        <b>&#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077;</b>&#160;&#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; <b>&#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1089;&#1080;&#1083;&#1100;&#1085;&#1077;&#1077;</b>&#160;&#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093;.
      </li>
      <li>
        &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; PC <b>&#1089;&#1080;&#1083;&#1100;&#1085;&#1077;&#1077;</b>&#160;&#160;(&#1079;&#1072; &#1088;&#1077;&#1076;&#1082;&#1080;&#1084; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084;)&#160;&#160;&#1082;&#1086;&#1085;&#1092;-&#1080;&#1080; User, &#1087;&#1088;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1077; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072;.
      </li>
      <li>
        <b>&#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; GPO:</b>

        <ol>
          <li>
            &#1051;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; GPO (Local GPOs)
          </li>
          <li>
            &#1057;&#1072;&#1081;&#1090; (Site-level GPOs)
          </li>
          <li>
            &#1044;&#1086;&#1084;&#1077;&#1085; (Domain GPOs)
          </li>
          <li>
            &#1055;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;. 1-&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; (OU GPOs)
          </li>
          <li>
            &#1055;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;. 2-&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; (OU GPOs)
          </li>
          <li>
            &#1055;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;. 3-&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; (OU GPOs)
          </li>
          <li>
            &#160;... &#1077;&#1089;&#1083;&#1080; &#1085;&#1072; &#1086;&#1076;&#1085;&#1086;&#1084; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1082;&#1086; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;, &#1090;&#1086; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; (1 - &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1081;)
          </li>
        </ol>
      </li>
      <li>
        &#1090;.&#1077;. <b>&#1074;&#1099;&#1089;&#1096;&#1080;&#1081; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090; &#1091; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1081; (&#1073;&#1083;&#1080;&#1078;&#1072;&#1081;&#1096;&#1077;&#1081; &#1082; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1091;) &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080;</b>&#160;(&#1074; &#1085;&#1072;&#1096;&#1077;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1091; OU 3-&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103;).
      </li>
      <li>
        &#1077;&#1089;&#1083;&#1080; &#1085;&#1072; <b>&#1086;&#1076;&#1080;&#1085; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; 2 &#1082;&#1086;&#1085;&#1092;&#1083;&#1080;&#1082;&#1090;&#1085;&#1099;&#1093; GPO</b>, &#1090;&#1086; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1085;&#1086;&#1089;&#1090;&#1100; <b>&#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1072;&#1076;&#1084;&#1080;&#1085;</b>&#160;&#1074; <font color="#0000c0">gpmc</font>. &#1055;&#1086;&#1088;&#1103;&#1076;&#1082;&#1086;&#1074;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088; &quot;1&quot; &#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1072; &#1074; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1102;&#1102; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100;.
      </li>
      <li>
        <b>&#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1103;&#1103;</b>&#160;&#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1085;&#1072;&#1103; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072; &#1080;&#1084;&#1077;&#1077;&#1090; <b>&#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;</b>
      </li>
    </ul>
    <p>
      &#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1077; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; (&#1095;&#1077;&#1084; &#1076;&#1072;&#1083;&#1100;&#1096;&#1077; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072;, &#1090;&#1077;&#1084; &#1086;&#1085;&#1072; &#1089;&#1080;&#1083;&#1100;&#1085;&#1077;&#1077;):
    </p>
    <ol>
      <li>
        <b>Local GP</b>&#160;- &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072; &#1089;&#1072;&#1084;&#1086;&#1075;&#1086; &#1055;&#1050;. &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1086; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1088;&#1077;&#1077;&#1089;&#1090;&#1088;&#1072;.
      </li>
      <li>
        <b>Site Policy</b>&#160;- Site &#1101;&#1090;&#1086; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; DC, &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086; &#1090;&#1077;&#1088;&#1088;&#1080;&#1090;&#1086;&#1088;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084;&#1091; &#1087;&#1088;&#1080;&#1079;&#1085;&#1072;&#1082;&#1091;. &#1047;&#1072;&#1087;&#1088;&#1077;&#1097;&#1077;&#1085;&#1086; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1088;&#1077;&#1077;&#1089;&#1090;&#1088;&#1072;.
      </li>
      <li>
        <b>Domain Policy</b>
      </li>
      <li>
        <b>Policy OU - </b>&#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1086; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1088;&#1077;&#1077;&#1089;&#1090;&#1088;&#1072;.
      </li>
      <li>
        <b>Enforce GP</b>&#160;- &#1087;&#1088;&#1080;&#1085;&#1091;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103;. &#1051;&#1091;&#1095;&#1096;&#1077; &#1090;&#1072;&#1082; &#1085;&#1077; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100;. Enforced &#1076;&#1077;&#1084;&#1077;&#1085;&#1072; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1085;&#1077;&#1077; Enforced OU
      </li>
      <li>
        <b>Loopback Policy processing </b>- &#1087;&#1088;&#1080; &#1074;&#1093;&#1086;&#1076;&#1077; &#1085;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1055;&#1050; &#1076;&#1083;&#1103; &#1102;&#1079;&#1077;&#1088;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1102;&#1079;&#1077;&#1088;&#1089;&#1082;&#1072;&#1103; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1072;&#1103; &#1074; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1077; PC
      </li>
    </ol>
  </body>
