<node TEXT="Корректировка порядка обработки" ID="ID_36173875" CREATED="1519112079759" MODIFIED="1519112079759"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1050;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1099;&#1093; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;. </b>
    </p>
    <ol>
      <li>
        <b>Block Inheritance (&#1041;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1053;&#1072;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;)</b>. &#1052;&#1086;&#1078;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; &#1044;&#1086;&#1084;&#1077;&#1085;, &#1055;&#1086;&#1076;&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; (OU). <b>&#1053;&#1072; &#1089;&#1072;&#1081;&#1090; - &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;</b>. &#1041;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080;, &#1087;&#1088;&#1080;&#1096;&#1077;&#1076;&#1096;&#1080;&#1077; &#1089;&#1074;&#1077;&#1088;&#1093;&#1091;. &#1055;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072;, &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1072;&#1103; &#1085;&#1072; &#1089;&#1072;&#1084; &#1079;&#1072;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088; &#1080; &#1085;&#1080;&#1078;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103;. &#1055;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; <b>&#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; gPOptions</b>&#160;&#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1085;&#1099;&#1093; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074; &#1074; <font color="#0033cc">adsiedit</font>&#160;(0 &#1080;&#1083;&#1080; &lt;Not Set&gt; - &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1085;&#1077;&#1090;).<br/>
      </li>
      <li>
        <b>Enforced</b>&#160;- &#1079;&#1072;&#1087;&#1088;&#1077;&#1090; &#1085;&#1072; &#1087;&#1077;&#1088;&#1077;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077;. GPO &#1089; &#1101;&#1090;&#1086;&#1081; &#1086;&#1087;&#1094;&#1080;&#1077;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085; <b>&#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1084; (&#1090;.&#1077;. &#1091; &#1085;&#1077;&#1075;&#1086; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;, &#1076;&#1072;&#1078;&#1077; &#1082; &#1041;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1077; &#1053;&#1072;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;)</b>. &#1055;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; <b>&#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; gPlink</b>-&#1092;&#1083;&#1072;&#1075;&#160;&#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1085;&#1099;&#1093; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1086;&#1074; &#1074; <font color="#0033cc">adsiedit.</font><font color="#000000">&#160;&#1053;&#1077; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1079;&#1083;&#1086;&#1091;&#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1083;&#1103;&#1090;&#1100;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1079;&#1072;&#1087;&#1091;&#1090;&#1072;&#1090;&#1100;&#1089;&#1103;. Domain Enfoced &#1074;&#1072;&#1078;&#1085;&#1077;&#1077; OU Enforced.&#160;&#160;&#1043;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1099;&#1077; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080;, &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1102;&#1097;&#1080;&#1077; &#1079;&#1072; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1101;&#1085;&#1092;&#1086;&#1088;&#1089;&#1103;&#1090;.</font>
      </li>
      <li>
        &#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; GP&#160;&#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; <b>&#1075;&#1088;&#1091;&#1087;&#1087; Active Directory (Security Filtering)</b>

        <ul>
          <li>
            &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1083;&#1102;&#1076;&#1077;&#1081; &#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; AD, &#1072;<i>&#160; <font color="#0033cc">gpmc</font>&#160;&#160;&gt; GPO &gt; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072; &gt; Scope &gt; Security Filtering</i>&#160;&#160;- &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1084; &#1074;&#1089;&#1077;&#1093; &#1102;&#1079;&#1077;&#1088;&#1086;&#1074; &#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1085;&#1072;&#1096;&#1091; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; &#1080;&#1079; AD
          </li>
          <li>
            Active Directory (&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080;, &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077; &#1087;&#1086;&#1084;&#1086;&#1075;&#1091;&#1090;)
          </li>
        </ul>
      </li>
      <li>
        &#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; GP&#160;&#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; <b>&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074; WMI (WMI Filtering)</b>&#160;(&#1082;&#1088;&#1091;&#1090;&#1072;&#1103; &#1074;&#1077;&#1097;&#1100;). &#1057;&#1082;&#1088;&#1080;&#1087;&#1090;, &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1099;&#1081; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1090;&#1100; &#1085;&#1077;&#1082;&#1080;&#1081; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;. &#1050; &#1083;&#1102;&#1073;&#1086;&#1084;&#1091; GPO &#1084;&#1086;&#1078;&#1085;&#1086; &quot;&#1087;&#1088;&#1080;&#1082;&#1088;&#1091;&#1090;&#1080;&#1090;&#1100;&quot; WMI-&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;. &#1054;&#1073;&#1098;&#1077;&#1082;&#1090;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1074; &#1090;&#1072;&#1082;&#1086;&#1081; GPO (&#1089; WMI-&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1084;), &#1087;&#1077;&#1088;&#1077;&#1076; &#1090;&#1077;&#1084; &#1082;&#1072;&#1082; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1085;&#1072; &#1089;&#1077;&#1073;&#1103; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; &#1080;&#1079; &#1101;&#1090;&#1086;&#1075;&#1086; GPO, &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1089;&#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1087;&#1088;&#1086;&#1081;&#1090;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; WMI-&#1092;&#1080;&#1083;&#1100;&#1090;&#1088; (&#1090;.&#1077;. &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &quot;&#1087;&#1088;&#1080;&#1082;&#1088;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081;&quot; &#1082; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; GPO, <b>WMI-&#1089;&#1082;&#1088;&#1080;&#1087;&#1090;</b>). &#1048; &#1077;&#1089;&#1083;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; WMI-&#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072; &#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1089;&#1103; &#1087;&#1086;&#1085;&#1103;&#1090;&#1085;&#1086;, &#1095;&#1090;&#1086; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1074;&#1089;&#1077;&#1084;, &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1099;&#1084; &#1074; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1077;, &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103;&#1084;, &#1090;&#1086; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; &#1080;&#1079; &#1101;&#1090;&#1086;&#1075;&#1086; GPO &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103;.
      </li>
      <li>
        <b>Disable GPOs</b>. &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1073;&#1077;&#1079; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1103;, &#1085;&#1072; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080;&#1083;&#1080; &#1076;&#1083;&#1103; &#1101;&#1082;&#1089;&#1087;&#1077;&#1088;&#1080;&#1084;&#1077;&#1085;&#1090;&#1072;.
      </li>
      <li>
        <p>
          <b>Loopback Policy processing (LPP) </b>- &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1085;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; PC &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1099;&#1077; GP, &#1090;.&#1077;. &#1087;&#1088;&#1080; &#1074;&#1093;&#1086;&#1076;&#1077; &#1085;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; PC &#1076;&#1083;&#1103; &#1102;&#1079;&#1077;&#1088;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1102;&#1079;&#1077;&#1088;&#1089;&#1082;&#1072;&#1103; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1072;&#1103; &#1074; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1077; PC. &#1058;.&#1077;. PC &#1079;&#1072;&#1084;&#1099;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1089;&#1077;&#1073;&#1103;.
        </p>
        <ul>
          <li>
            <b>merge mode</b>&#160;(&#1089;&#1083;&#1080;&#1103;&#1085;&#1080;&#1077; - &#1084;&#1103;&#1075;&#1082;&#1080;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;) - PC &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1072; &#1087;&#1086;&#1073;&#1077;&#1078;&#1076;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1080; &#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1085;&#1086;&#1074;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1085;&#1092;&#1083;&#1080;&#1082;&#1090;&#1072;, &#1077;&#1083;&#1089;&#1080; &#1082;&#1086;&#1085;&#1092;&#1083;&#1080;&#1082;&#1090;&#1072; &#1085;&#1077;&#1090;, &#1090;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1085;&#1072;&#1082;&#1072;&#1087;&#1083;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103;
          </li>
          <li>
            <b>replace mode</b>&#160;(&#1078;&#1077;&#1089;&#1090;&#1082;&#1080;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;) - &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090; &#1091; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; PC, &#1076;&#1072;&#1078;&#1077; &#1077;&#1089;&#1083;&#1080; &#1085;&#1077;&#1090; &#1082;&#1086;&#1085;&#1092;&#1083;&#1080;&#1082;&#1090;&#1072;. &#1055;&#1086;&#1083;&#1085;&#1072;&#1103; &#1079;&#1072;&#1084;&#1077;&#1085;&#1072; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080;.
          </li>
        </ul>
        <p>
          &#1045;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; <b>&#1087;&#1086;&#1074;&#1099;&#1089;&#1080;&#1090;&#1100; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082; PC</b>&#160;&#160;&#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;, &#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086;: <i>Administrative Tools &gt; <b>Group Policy Management</b>&#160;(gpmc.msc)&gt; Comp.conf &gt; Policies &gt; Adm.Temp &gt; System &gt; Group Policy &gt; <b>User GP loopback processing mode</b>&#160;&gt; Enable &gt; ... </i>
        </p>
        <p>
          &#1059;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; PC &#1089; &#1086;&#1073;&#1097;&#1080;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1086;&#1084; &#1076;&#1083;&#1103; &#1077;&#1076;&#1080;&#1085;&#1086;&#1086;&#1073;&#1088;&#1072;&#1079;&#1080;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082; &#1074;&#1085;&#1077; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;.
        </p>
      </li>
    </ol>
  </body>
</html></richcontent>
<font BOLD="false"/>
