<node TEXT="GPO=GPT+GPC" ID="ID_1721488638" CREATED="1519112079760" MODIFIED="1519112079760"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1051;&#1102;&#1073;&#1086;&#1081; &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1099;&#1081; GPO&#160;(Group Policy Object, &#1054;&#1073;&#1098;&#1077;&#1082;&#1090; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080;) &#1089;&#1086;&#1089;&#1090;&#1086;&#1080;&#1090; &#1080;&#1079; GPT&#160;&#1080; GPC. </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>GPT</b>&#160;- <b>Group Policy Template</b>&#160;(&#1064;&#1072;&#1073;&#1083;&#1086;&#1085; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080;). &quot;&#1055;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1089;&#1090;&#1074;&#1086;&quot; GPO &#1074; <b>&#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077;.</b>&#160;&#1050;&#1072;&#1082; &#1073;&#1099; <b>&quot;&#1061;&#1088;&#1072;&#1085;&#1080;&#1083;&#1080;&#1097;&#1077; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&quot;</b>
    </p>
    <ul>
      <li>
        HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\Group Policy\History - &#1084;&#1077;&#1089;&#1090;&#1086; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; <b>Version (&#1074; &#1092;&#1072;&#1081;&#1083;&#1077; GPT.ini) GPO</b>
      </li>
      <li>
        HKEY_CURRENT_USER\SOFTWARE\Microsoft\Windows\CurrentVersion\Group Policy\History - &#1084;&#1077;&#1089;&#1090;&#1086; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; <b>Version (&#1074; &#1092;&#1072;&#1081;&#1083;&#1077; GPT.ini)&#160;GPO</b>
      </li>
      <li>
        <b>GPT</b>&#160;- &#1101;&#1090;&#1086; <b>&#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1087;&#1072;&#1087;&#1082;&#1072;</b>&#160;&#1074; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1084; &#1084;&#1077;&#1089;&#1090;&#1077; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072; <b>Sysvol (&#1077;&#1089;&#1090;&#1100; &#1074; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; DC)</b>, &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090; &#1086;&#1076;&#1085;&#1086;&#1084; GPO
      </li>
      <li>
        <b>&#1074; SYSVOL</b>&#160;&#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1099;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;:

        <ul>
          <li>
            &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;
          </li>
          <li>
            &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1099;
          </li>
          <li>
            &#1072;&#1085;&#1086;&#1085;&#1089;&#1099; &#1086;&#1087;&#1091;&#1073;&#1083;&#1080;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1055;&#1054;
          </li>
        </ul>
      </li>
      <li>
        &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1074;&#1085;&#1086;&#1089;&#1103;&#1090;&#1089;&#1103; &#1074; Template &#1088;&#1077;&#1087;&#1083;&#1080;&#1094;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1089; DC &#1085;&#1072; DC &#1085;&#1077; &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; AD, &#1072; <b>&#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; FRS (File Replication Service)</b>&#160;&#160;(&#1076;&#1086; WS2008), &#1089; WS2008 &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1081;&#1090; &#1085;&#1072; <b>DFS-R</b>&#160;(&#1073;&#1086;&#1083;&#1077;&#1077; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1072;&#1103; &#1088;&#1077;&#1087;&#1083;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;)
      </li>
    </ul>
    <p>
      <b>GPC&#160;- Group Policy Container</b>&#160;(&#1050;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080;). &quot;&#1055;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1089;&#1090;&#1074;&#1086;&quot; GPO &#1074; <b>Active Directory</b>. &#1050;&#1072;&#1082; &#1073;&#1099; &quot;<b>&#1061;&#1088;&#1072;&#1085;&#1080;&#1083;&#1080;&#1097;&#1077; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1086;&#1074;&quot;.</b>
    </p>
    <ul>
      <li>
        GPC &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1089;&#1103; &#1074; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1077; AD Users and Computers\Domen\System\Policies\&#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088; &#1074; &#1074;&#1080;&#1076;&#1077; GUID
      </li>
      <li>
        &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; &#1086;&#1073;&#1079;&#1086;&#1088;&#1072; GPC - adsiedit (&#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;)
      </li>
      <li>
        &#1042; GPT &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090;&#1089;&#1103;:

        <ul>
          <li>
            GUID &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080;
          </li>
          <li>
            &#1085;&#1086;&#1084;&#1077;&#1088; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080;
          </li>
          <li>
            &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; PC, &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
          </li>
        </ul>
      </li>
    </ul>
  </body>
</html></richcontent>
