<node TEXT="Административные шаблоны" ID="ID_1537275760" CREATED="1519112079761" MODIFIED="1519112079761"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Administrative Templates</b>&#160;(ADMX-&#1085;&#1086;&#1074;&#1099;&#1081; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;, ADM-&#1089;&#1090;&#1072;&#1088;&#1099;&#1081; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;)
    </p>
    <ul>
      <li>
