      </li>
      <li>
        <font color="#0000cc">gpupdate /force</font>&#160;- &#1087;&#1086;&#1083;&#1085;&#1086;&#1077; &#1087;&#1088;&#1080;&#1085;&#1091;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1099;&#1093; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;. &#1057;&#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &#1085;&#1072; DC, &#1087;&#1086;&#1090;&#1086;&#1084; &#1085;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1077;. &#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;, &#1090;.&#1077;. &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1085;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; PC. &#1047;&#1072;&#1087;&#1091;&#1089;&#1082; &#1089; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1084; /force - &#1073;&#1077;&#1089;&#1089;&#1084;&#1099;&#1089;&#1083;&#1077;&#1085;&#1077;&#1085;, &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1086;&#1083;&#1100;&#1096;&#1077; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103;. &#1047;&#1072;&#1095;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1082;&#1072;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100; &#1074;&#1089;&#1102; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091;, &#1077;&#1089;&#1083;&#1080; &#1074;&#1077;&#1088;&#1089;&#1080;&#1103; &#1085;&#1077; &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1083;&#1072;&#1089;&#1100;? &#1040; &#1092;&#1086;&#1088;&#1089;&#1086;&#1084; &#1084;&#1099; &#1079;&#1072;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1101;&#1090;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100;.
      </li>
      <li>
        <b>Resultant Set of Policy (RSoP)</b>&#160;- &#1095;&#1077;&#1088;&#1077;&#1079; <font color="#0000c0">mmc</font>&#160;&#1080;&#1083;&#1080; <font color="#0000c0">rsop.msc. <i>mmc</i></font><i>&#160;&gt; Add &gt; <b>Resultant Set of Policy</b>&#160;&gt;&#160;... &gt; &#1082;&#1052;&#1077;&#1085;&#1102; &gt; Generate RSoP Data</i>&#160;... - &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1093; GP&#160;&#160;&#1085;&#1072; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; PC.<font color="#0000c0">&#160;</font><font color="#000000">A&#1085;&#1072;&#1083;&#1086;&#1075;</font>&#160; <font color="#0000c0">gpmc.msc</font>, &#1085;&#1086; &#1085;&#1077; &#1090;&#1072;&#1082; &#1091;&#1076;&#1086;&#1073;&#1085;&#1086; &#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100;, &#1079;&#1072;&#1090;&#1086; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1087;&#1086;&#1076; &#1088;&#1091;&#1082;&#1086;&#1081; - &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1072; &#1076;&#1086;&#1087;. &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1085;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1081; PC)
      </li>
      <li>
        <b>RSoP &#1085;&#1072; DC</b>&#160;- &#1095;&#1077;&#1088;&#1077;&#1079; <font color="#0000c0">gpmc.msc</font>
      </li>
      <li>
        <font color="#0000c0">GPResult&#160;/r </font>- &#1076;&#1083;&#1103; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082; &#1080; &#1076;&#1080;&#1072;&#1075;&#1085;&#1086;&#1089;&#1090;&#1080;&#1082;&#1080; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1099;&#1093; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082; &#1085;&#1072; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1084; PC &#1080; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. <b>/V</b>&#160;&#1080; <b>/Z</b>&#160;- &#1076;&#1083;&#1103; &#1073;&#1086;&#1083;&#1077;&#1077; &#1087;&#1086;&#1076;&#1088;&#1086;&#1073;&#1085;&#1099;&#1093; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;
      </li>
      <li>
        <font color="#0000c0">gpme.msc</font>&#160;- Group Policy Management Editor. C &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072; &#1089;&#1083;&#1086;&#1074; &#1091;&#1076;&#1086;&#1073;&#1085;&#1086; &#1080;&#1089;&#1082;&#1072;&#1090;&#1100; &#1086;&#1087;&#1094;&#1080;&#1080;.
      </li>
      <li>
        <font color="#0000c0">whoami /groups</font>&#160;- &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1075;&#1088;&#1091;&#1087;&#1087; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, <font color="#0000c0">whoami /all</font>&#160;- &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1086;&#1073;&#1097;&#1077;&#1081; &#1080;&#1085;&#1092;&#1099; &#1087;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102;
      </li>
    </ul>
  </body>
