<node TEXT="Troubleshooting" ID="ID_1821410028" CREATED="1519112079743" MODIFIED="1519112079743"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1077;&#1088;&#1077;&#1093;&#1074;&#1072;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1087;&#1072;&#1087;&#1082;&#1072;&#1084;.</b>
    </p>
    <p>
      &#1040;&#1076;&#1084;&#1080;&#1085; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1089;&#1090;&#1072;&#1090;&#1100; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1077;&#1084; (Owner) &#1080;&#1083;&#1080; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1100; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1077;&#1084; &#1085;&#1086;&#1074;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. <i>Folder\ Properties\Security\Advanced\Owner\Edit\&lt;NewUser&gt; </i>
    </p>
    <p>
      
    </p>
    <p>
