<node TEXT="AppLocker" ID="ID_203747672" CREATED="1519112079744" MODIFIED="1519112079744"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1053;&#1072;&#1073;&#1086;&#1088; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1090; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1082; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1084; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103;&#1084;. &#1087;&#1086;&#1103;&#1074;&#1080;&#1083;&#1089;&#1103; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; Windows 7. &#1087;&#1086; &#1089;&#1091;&#1090;&#1080; &#1101;&#1090;&#1086; <b>&#1091;&#1089;&#1086;&#1074;&#1077;&#1088;&#1096;&#1077;&#1085;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; SRP</b>, &#1085;&#1086; &#1073;&#1077;&#1079; Network zones. &#1048;&#1084;&#1077;&#1077;&#1090;&#1088;&#1089;&#1103; &#1090;&#1072;&#1088;&#1075;&#1077;&#1090;&#1080;&#1085;&#1075; &#1085;&#1072; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099;. &#1053;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; <b>WS2008R2+W7e</b>
    </p>
    <ul>
      <li>
        &#1079;&#1072;&#1087;&#1091;&#1089;&#1082; &#1080;&#1079; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1084;&#1077;&#1089;&#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        &#1085;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099;, &#1085;&#1086; &#1080; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1099; &#1080; DLLs
      </li>
      <li>
        &#1080;&#1085;&#1089;&#1090;&#1072;&#1083;&#1083;&#1103;&#1094;&#1080;&#1103;&#160;&#160;&#1089; &#1080;&#1089;&#1087;. &#1101;&#1083;. &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1080;. &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082; &#1080;&#1083;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1089;&#1086;&#1092;&#1090;&#1072; &#1086;&#1090; Microsoft
      </li>
      <li>
        <i>MyGPO\ CompConf\ WindowsSettings\ SecuritySettings\ ApplicationControlPolicies\&#160;&#160;Applocker</i>
      </li>
      <li>
        &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1084;&#1072;&#1096;&#1080;&#1085;&#1077; &#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102;
      </li>
      <li>
        &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1086;&#1077; &#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1086;&#1077;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;. &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        <b>&#1086;&#1073;&#1093;&#1086;&#1076;</b>&#160;&#1095;&#1077;&#1088;&#1077;&#1079; Regserv32 &#1080; &#1076;&#1088;. (<a href="https://habrahabr.ru/company/inoventica/blog/282373/">https://habrahabr.ru/company/inoventica/blog/282373/</a>)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>&#1059;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103;:</b>
    </p>
    <ul>
      <li>
        &#1057;&#1083;&#1091;&#1078;&#1073;&#1099; &gt; <b>Application Identity</b>&#160; &gt; Automatic
      </li>
    </ul>
  </body>
</html></richcontent>
