<node TEXT="BSoD" ID="ID_680080822" CREATED="1519112079842" MODIFIED="1548928994379"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1080;&#1085;&#1080;&#1081; &#1101;&#1082;&#1088;&#1072;&#1085; &#1089;&#1084;&#1077;&#1088;&#1090;&#1080; (Blue Screen of Death, Blue Screen of Doom, BSoD)</b>&#160; - &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1086; &#1082;&#1088;&#1080;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1081; &#1086;&#1096;&#1080;&#1073;&#1082;&#1077; &#1074; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1093; Microsoft Windows. &#1057;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1090;&#1088;&#1080; &#1074;&#1080;&#1076;&#1072; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; BSOD: &#1076;&#1083;&#1103; &#1089;&#1077;&#1084;&#1077;&#1081;&#1089;&#1090;&#1074; Windows 3.x, Windows 9x &#1089; Windows NT &#1080; Windows CE.
    </p>
    <p>
      
    </p>
    <p>
      &#1045;&#1089;&#1090;&#1100; &#1090;&#1072;&#1082; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;&#1099;&#1077; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; live-cd, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1077;&#1089;&#1090;&#1100; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; <b>BlueScreenView</b>. &#1045;&#1089;&#1083;&#1080; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1077;&#1096;&#1100; &#1074; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;, &#1090;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1076;&#1072;&#1084;&#1087; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;. &#1072; &#1076;&#1072;&#1083;&#1100;&#1096;&#1077; &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1096;&#1100;, &#1095;&#1090;&#1086; &#1074;&#1099;&#1076;&#1072;&#1105;&#1090; &#1086;&#1096;&#1080;&#1073;&#1082;&#1091;.
    </p>
    <ul>
      <li>
        &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; <b>nvsys</b>, &#1090;&#1086; &#1076;&#1077;&#1083;&#1086; &#1074; &#1076;&#1077;&#1083;&#1086; &#1074; &#1076;&#1088;&#1086;&#1074;&#1072;&#1093;, &#1089;&#1082;&#1086;&#1088;&#1077;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1088;&#1090;&#1072;
      </li>
      <li>
        &#1077;&#1089;&#1083;&#1080; &#1082;&#1072;&#1082;&#1086;&#1081; &#1085;&#1080;&#1073;&#1091;&#1076;&#1100; <b>ntoskernel</b>&#160;&#1090;&#1086;, &#1083;&#1080;&#1073;&#1086; &#1046;&#1044;, &#1083;&#1080;&#1073;&#1086; &#1084;&#1072;&#1090;&#1077;&#1088;&#1080;&#1085;&#1082;&#1072;/&#1041;&#1055;
      </li>
      <li>
        &#1087;&#1086;&#1082;&#1072; &#1074;&#1080;&#1085;&#1076;&#1072; &#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1080;&#1082;, &#1089;&#1085;&#1080;&#1084;&#1072;&#1077;&#1096;&#1100; &#1082;&#1088;&#1099;&#1096;&#1082;&#1091; &#1080; &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1096; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077; &#1087;&#1099;&#1083;&#1080;, &#1074;&#1079;&#1076;&#1091;&#1090;&#1099;&#1093; &#1082;&#1086;&#1085;&#1076;&#1105;&#1088;&#1086;&#1074;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1080;&#1085;&#1095;&#1077;&#1089;&#1090;&#1077;&#1088;</b>. &#1054;&#1096;&#1080;&#1073;&#1082;&#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1072;&#1090;&#1100; &#1080;&#1079;-&#1079;&#1072; &#1087;&#1083;&#1086;&#1093;&#1086;&#1075;&#1086; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;&#1081;, &#1082;&#1086;&#1085;&#1090;&#1072;&#1082;&#1090;&#1086;&#1074;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1093; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1085;&#1080;&#1082;&#1086;&#1074;, &#1091;&#1076;&#1083;&#1080;&#1085;&#1080;&#1090;&#1077;&#1083;&#1077;&#1081; &#1080; &#1090;.&#1076;., &#1085;&#1077;&#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1076;&#1080;&#1089;&#1082;&#1072; &#1089; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1084; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1083;&#1077;&#1088;&#1086;&#1084; SATA/&#1056;&#1040;&#1058;&#1040; &#1085;&#1072; &#1084;&#1072;&#1090;&#1077;&#1088;&#1080;&#1085;&#1089;&#1082;&#1086;&#1081; &#1087;&#1083;&#1072;&#1090;&#1077; &#1080; &#1090;.&#1076;.
    </p>
    <p>
      
    </p>
    <p>
      <b>sfc /scannow</b>&#160;&#160;- &#1087;&#1088;&#1086;&#1075;&#1085;&#1072;&#1090;&#1100; &#1090;&#1077;&#1089;&#1090; &#1085;&#1072; &#1094;&#1077;&#1083;&#1086;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;
