<node TEXT="RODC" ID="ID_395510959" CREATED="1519112079803" MODIFIED="1539967634003"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Read-Only Domain Controller</b>, &#1088;&#1072;&#1085;&#1077;&#1077; &#1074;&#1088;&#1086;&#1076;&#1077; BDC (Backup Domain Controller). &#1052;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1100; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072; (&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1081; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;). RODC &#1085;&#1077; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1080; DC, &#1086;&#1085; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085; &#1076;&#1083;&#1103; &#1086;&#1087;&#1090;&#1080;&#1084;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1084;&#1077;&#1078;&#1076;&#1091; &#1092;&#1080;&#1083;&#1080;&#1072;&#1083;&#1086;&#1084; &#1080; &#1075;&#1086;&#1083;&#1086;&#1074;&#1085;&#1099;&#1084; &#1086;&#1092;&#1080;&#1089;&#1086;&#1084;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1072; &#1074;&#1099;&#1089;&#1086;&#1082;&#1072;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1085;&#1086;&#1094;&#1077;&#1085;&#1085;&#1099;&#1081; DC &#1074; &#1092;&#1080;&#1083;&#1080;&#1072;&#1083;&#1077;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1074;&#1103;&#1079;&#1080; &#1089; DC &#1075;&#1086;&#1083;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086; &#1086;&#1092;&#1080;&#1089;&#1072;, &#1090;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1080;, &#1095;&#1100;&#1080; &#1091;&#1095;&#1077;&#1090;&#1082;&#1080; &#1077;&#1097;&#1077; &#1085;&#1077; &#1079;&#1072;&#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1099; &#1085;&#1077; &#1089;&#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1088;&#1086;&#1081;&#1090;&#1080; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1102;. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1085;&#1091;&#1078;&#1085;&#1086; &#1075;&#1088;&#1072;&#1084;&#1086;&#1090;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1077;&#1076;&#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1058;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;:</b>
    </p>
    <ul>
      <li>
        &#1051;&#1077;&#1089;, &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1081; &#1085;&#1072; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; WS2003
      </li>
      <li>
        DC WS2008 &#1080;&#1083;&#1080; WS2008R2 &#1093;&#1086;&#1090;&#1103; &#1073;&#1099; &#1086;&#1076;&#1080;&#1085; &#1074; &#1076;&#1086;&#1084;&#1077;&#1085;&#1077;
      </li>
      <li>
        &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1082;&#1080; &#1083;&#1077;&#1089;&#1072; <font color="#0000c0">ADPrep.exe /RODCPrep</font>
      </li>
      <li>
        RODC server &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1086;&#1084; Workgroup. &#1053;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1103;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1086;&#1084; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;.
      </li>
    </ul>
    <p>
      <b>&#1056;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; 1. </b>MS &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090; &#1088;&#1072;&#1079;&#1074;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100; &#1074; &#1089;&#1088;&#1077;&#1076;&#1077; CORE. &#1055;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1080;&#1076;&#1077;&#1090; &#1087;&#1086; &#1079;&#1072;&#1088;&#1072;&#1085;&#1077;&#1077; &#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;&#1084;&#1091; &#1092;&#1072;&#1081;&#1083;&#1091; &#1086;&#1090;&#1074;&#1077;&#1090;&#1086;&#1074;.
    </p>
    <ol>
      <li>
        &#1055;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1082;&#1072; &#1092;&#1072;&#1081;&#1083;&#1072; &#1086;&#1090;&#1074;&#1077;&#1090;&#1086;&#1074;: <i>DCPromo &gt; RODC &gt; Delegation of RODC Inst. and Adm. (&#1083;&#1091;&#1095;&#1096;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091;, &#1072; &#1085;&#1077; &#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082;&#1072;) &gt; Export mode &gt; <b>&#1057;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1077;&#1084; &#1092;&#1072;&#1081;&#1083; &#1086;&#1090;&#1074;&#1077;&#1090;&#1086;&#1074;</b>&#160; &gt; &#1054;&#1090;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1091;</i>
      </li>
      <li>
        &#1055;&#1088;&#1086;&#1089;&#1084;&#1072;&#1090;&#1088;&#1080;&#1074;&#1072;&#1077;&#1084; &#1092;&#1072;&#1081;&#1083; &#1086;&#1090;&#1074;&#1077;&#1090;&#1086;&#1074;, &#1077;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; - &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;.
      </li>
      <li>
        RODC &#1083;&#1077;&#1075;&#1082;&#1086; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089; DC, &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1087;&#1072;&#1088;&#1086;&#1083;&#1080; &#1089;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103;
      </li>
    </ol>
    <p>
      <b>&#1056;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; 2. &#1042;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;.</b>
    </p>
    <ol>
      <li>
        &#1042;&#1099;&#1074;&#1086;&#1076;&#1080;&#1084; &#1073;&#1091;&#1076;&#1091;&#1097;&#1080;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; RODC <b>&#1080;&#1079; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;</b>
      </li>
      <li>
        &#1053;&#1072; DC &#1080;&#1079; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072; PC<b>&#160;&#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1084;</b>&#160;&#1073;&#1091;&#1076;&#1091;&#1097;&#1080;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; RODC
      </li>
      <li>
        <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1087;&#1088;&#1077;&#1076;&#1074;&#1072;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1091;&#1102; &#1091;&#1095;&#1077;&#1090;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; RODC</b>&#160;&#1085;&#1072; <b>DC</b>. <i>ADUC\ MyDomain\ DomainControllers\ Pre-create RODC account &gt; Next &gt; My current logged on credentials &gt; Next &gt; Computer Name &lt;&#1080;&#1084;&#1103; &#1073;&#1091;&#1076;&#1091;&#1097;&#1077;&#1075;&#1086; RODC&gt; Next &gt; DNS server + Global catalog &gt; Next &gt; Group or user &lt;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1084; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;, &#1075;&#1088;&#1091;&#1087;&#1087;&#1091;&gt; &gt;&#160;Next</i>
      </li>
      <li>
        <i><b>&#1053;&#1072; &#1092;&#1080;&#1083;&#1080;&#1072;&#1083;&#1100;&#1089;&#1082;&#1086;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; DCPromo</b>. &#1047;&#1072;&#1093;&#1086;&#1076;&#1080;&#1084; &#1087;&#1086;&#1076; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1084; &gt; dcpromo &gt; 2Next &gt; Existing forest\ Add a domain controller to an existing domain &gt; Next &gt; Type the name of any domain...MyDomain &gt; Alternate credentials &lt;&#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1072;&#1076;&#1084;&#1080;&#1085; &#1080;&#1079; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072; &#1080;&#1083;&#1080; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072;&gt; 2Next...</i>
      </li>
      <li>
        <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1085;&#1072; DC &#1092;&#1080;&#1083;&#1080;&#1072;&#1083;.</b>&#160;&#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; (Global, Security) &#1074; ADUC. &#1050;&#1080;&#1076;&#1072;&#1077;&#1084; &#1090;&#1091;&#1076;&#1072; &#1102;&#1079;&#1077;&#1088;&#1086;&#1074; &#1080; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1099;.
      </li>
      <li>
        &#1053;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084; RODC &#1085;&#1072; DC. ADUC\ MyDomain\ DomainControllers\&#160;&lt;MyRODCServer&gt;\ Properties\ Password Replication Policy &gt; Add &gt; <b>Allow passwords for the account to replicate to this RODC</b>&#160;&gt; &lt;&#1088;&#1072;&#1085;&#1077;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1072;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072;&gt;&#160;
      </li>
    </ol>
    <p>
