<node TEXT="Distributed Cache" ID="ID_637051391" CREATED="1519112079803" MODIFIED="1570734599969"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Distributed Cache</b>&#160;- &#1082;&#1086;&#1075;&#1076;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1085;&#1077;&#1090; &#1074; &#1092;&#1080;&#1083;&#1080;&#1072;&#1083;&#1077;, &#1082;&#1101;&#1096; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080;.
    </p>
    <ol>
      <li>
        <b>&#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1091;&#1077;&#1084; DC</b>. &#1059;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; (&#1075;&#1086;&#1083;&#1086;&#1074;&#1085;&#1086;&#1084;, &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; DC) &#1088;&#1086;&#1083;&#1077;&#1074;&#1091;&#1102; &#1089;&#1083;&#1091;&#1078;&#1073;&#1091;. Server Manager\ Roles\ File Services\ Add Role Services\ <b>BranchCache for network files</b>.
      </li>
      <li>
        C &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; <b>&#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1099; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;</b>&#160;(&#1093;&#1077;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072;&#1096;&#1080; &#1092;&#1072;&#1081;&#1083;&#1099; &#1074; &#1086;&#1073;&#1097;&#1080;&#1093; &#1087;&#1072;&#1087;&#1082;&#1072;&#1093;) &#1076;&#1083;&#1103; BranchCache. <font color="#0000c0"><i>gpedit.msc &gt;</i></font><i>&#160;CompConf\ AdmTemp\ Network\ Lanman Server\ Hash Publication for BranchCache &gt; Enable &gt; Allow hash publication only for shared folders on which BranchCache is enabled</i>.
      </li>
      <li>
        <b>&#1048;&#1084;&#1080;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &quot;&#1084;&#1086;&#1082;&#1088;&#1091;&#1102; &#1074;&#1077;&#1088;&#1077;&#1074;&#1082;&#1091;&quot;, &#1090;.&#1077;. &#1084;&#1077;&#1076;&#1083;&#1077;&#1085;&#1085;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;. &#1044;&#1083;&#1103; &#1094;&#1077;&#1083;&#1077;&#1081; &#1083;&#1072;&#1073;&#1099;.</b>&#160;<font color="#0000c0"><i>gpedit.msc &gt;</i></font><i>&#160;CompConf\ WindowsSettings\ Policy-based QoS (quality of service - &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;) &gt; Specify Outbound Throttle Rate (&#1087;&#1086;&#1083;&#1086;&#1089;&#1072; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1085;&#1080;&#1103;) 100KBps &gt; Next &gt; &lt;&#1052;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1085;&#1072; &#1082;&#1072;&#1082;&#1080;&#1077; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090;&gt; &gt; All application &gt;&#160;&#160;&lt;&#1085;&#1072; &#1082;&#1072;&#1082;&#1080;&#1077; IP &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1090;&#1100;&gt; &gt; Any+Any &gt; &lt;&#1053;&#1072; &#1082;&#1072;&#1082;&#1086;&#1081; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;?&gt; &gt; Any+Any &gt; Finish</i>
      </li>
      <li>
        &#1042; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1093; &#1087;&#1072;&#1087;&#1082;&#1080; (&#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;)&#160;&#1072;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; Properties\ Sharing\ <i>Advanced Sharing\ Caching &gt; <b>Enable BranchCache</b></i>
      </li>
      <li>
        <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; (&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084; GP)</b>&#160; &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; BranchCache &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;. <i>GPM\ MyGPO\ Edit\ CompConf\ Policies\ AdmTemp\ Network\ BranchCache\</i>

        <ul>
          <li>
            <i>Turn on BranchCache &gt; Enabled </i>
          </li>
          <li>
            <i>Set BranchCache Distributed Cache mode &gt; Enabled </i>
          </li>
          <li>
            <i>Configure BranchCache for network files &gt; Enabled, &lt;&#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1091; &#1074; &#1084;&#1080;&#1083;&#1080;&#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1072;&#1093;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1095;&#1077;&#1075;&#1086; &#1085;&#1072;&#1095;&#1085;&#1077;&#1090; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; BranchCache&gt;</i>
          </li>
        </ul>
      </li>
      <li>
        &#1055;&#1088;&#1086;&#1076;&#1086;&#1083;&#1078;&#1072;&#1077;&#1084; <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; (&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084; GP)</b>. &#1053;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; <b>Firewall</b>: <i>GPM\ MyGPO\ Edit\ CompConf\ Policies\ WindowsSettings\ SecuritySettings\ Windows Firewall with Advanced Security\</i>

        <ul>
          <li>
            <i>Inbound Rules\ New Rules &gt; Predefined &gt; BranchCache-Content Retrieval (Uses HTTP) &gt; 2Next &gt; Allow the connection &gt; Finish</i>
          </li>
          <li>
            <i>Inbound Rules\ New Rules &gt; Predefined &gt; BranchCache-Peer Descovery (Uses WSD) &gt; 2Next &gt; Allow the connection &gt; Finish. </i>&#1058;.&#1077;. &#1082;&#1090;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1099;&#1089;&#1090;&#1091;&#1087;&#1072;&#1090;&#1100; &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.
          </li>
        </ul>
      </li>
      <li>
        <b>&#1055;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1072;</b>&#160;&#1085;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1077;:

        <ol>
          <li>
            cmd &gt; <font color="#0000c0">netsh branchcache show status all</font>
          </li>
          <li>
            <font color="#0000c0">perfmon</font>&#160;&gt; &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1075;&#1088;&#1072;&#1092;&#1080;&#1082; &gt; add &gt; BranchCache(all) &gt;&#160;Change graph type\Report
          </li>
        </ol>
      </li>
    </ol>
  </body>
</html></richcontent>
</node>
