<node TEXT="Отключение телеметрии в W 7, 8, 8.1" ID="ID_1946306355" CREATED="1519112079841" MODIFIED="1545077772754"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Windows 7, Windows 8, 8.1
    </p>
    <ol>
      <li>
        Control Panel -&gt; &#1062;&#1077;&#1085;&#1090;&#1088; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; -&gt; &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; -&gt; &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1091;&#1083;&#1091;&#1095;&#1096;&#1077;&#1085;&#1080;&#1103; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1055;&#1054; -&gt; No
      </li>
      <li>
        &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1079;&#1072;&#1076;&#1072;&#1095; &#1087;&#1083;&#1072;&#1085;&#1080;&#1088;&#1086;&#1074;&#1097;&#1080;&#1082;&#1072;: Control Panel -&gt; Adm. tools -&gt; Task Scheduler -&gt; Microsoft -&gt; Windows:

        <ul>
          <li>
            -&gt;&#160;Application Experience (AITAgent, ProgramDataUpdater &#1080; Microsoft Compatibility Appraiser)
          </li>
          <li>
            -&gt; Customer Experience Improvement Program (Consolidator, KernelCEIPTask, UsbCEIP)
          </li>
          <li>
            -&gt; Autochk (Proxy)
          </li>
        </ul>
      </li>
      <li>
        &#1086;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084; &#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1089;&#1083;&#1091;&#1078;&#1073;&#1099;:

        <ul>
          <li>
            Diagnostics Tracking Service
          </li>
          <li>
            Connected User Experiences and Telemetry (&#171;&#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1080; &#1090;&#1077;&#1083;&#1077;&#1084;&#1077;&#1090;&#1088;&#1080;&#1103;&#187;)
          </li>
        </ul>
      </li>
      <li>
        &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; Windows; &#1059;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077; &#1095;&#1072;&#1089;&#1090;&#1080; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081;: cmd (&#1086;&#1090; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;)

        <ul>
          <li>
            <font color="#0033cc">wusa /uninstall /kb:3068708 /quiet /norestart </font>
          </li>
          <li>
            <font color="#0033cc">wusa /uninstall /kb:3022345 /quiet /norestart </font>
          </li>
          <li>
