      <b>Roaming profile</b>&#160;(&#1055;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1072;&#1077;&#1084;&#1099;&#1081; &#1087;&#1088;&#1086;&#1092;&#1080;&#1083;&#1100;) - &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; Microsoft, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084;, &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; &#1082; &#1076;&#1086;&#1084;&#1077;&#1085;&#1091; Windows Server, &#1087;&#1088;&#1080; &#1074;&#1093;&#1086;&#1076;&#1077; &#1074; &#1054;&#1057; &#1089; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; PC &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1089;&#1074;&#1086;&#1077;&#1084;&#1091; &#1087;&#1088;&#1086;&#1092;&#1080;&#1083;&#1102;.
    </p>
    <ul>
      <li>
        &#1086;&#1095;&#1077;&#1085;&#1100; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1077;&#1084;&#1082;&#1072;&#1103; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103;
      </li>
      <li>
        &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; GP, &#1090;&#1086;&#1075;&#1076;&#1072; &#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090;. &#1084;&#1086;&#1078;&#1077;&#1084; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100;, &#1095;&#1090;&#1086; &#1087;&#1072;&#1087;&#1082;&#1091; &#1052;&#1086;&#1080; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; - &#1088;&#1077;&#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1090;&#1100;, &#1072; &#1087;&#1072;&#1087;&#1082;&#1091; &#1052;&#1086;&#1080; &#1088;&#1080;&#1089;&#1091;&#1085;&#1082;&#1080; &#1080; &#1052;&#1086;&#1080; &#1074;&#1080;&#1076;&#1077;&#1086; - &#1085;&#1077; &#1088;&#1077;&#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1090;&#1100;. &#1044;&#1083;&#1103; &#1090;&#1072;&#1082;&#1080;&#1093; &#1087;&#1072;&#1087;&#1086;&#1082; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084; &#1086;&#1092;&#1092;&#1083;&#1072;&#1081;&#1085;&#1086;&#1074;&#1099;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;.&#160;
      </li>
    </ul>
    <ol>
      <li>
        User &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1080;&#1090; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;. &#1085;&#1072; &#1089;&#1074;&#1086;&#1077;&#1084; &#1088;&#1072;&#1073;. &#1084;&#1077;&#1089;&#1090;&#1077;
      </li>
      <li>
