<node TEXT="Properties" ID="ID_671581041" CREATED="1519112079750" MODIFIED="1519112079750"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>General.</b>
    </p>
    <ul>
      <li>
        IPv4 Router &gt; LAN and demand-dial routing
      </li>
      <li>
        IPv6 Router &gt; LAN and demand-dial routing
      </li>
      <li>
        IPv4 Remote access server
      </li>
      <li>
        IPv6 Remote access server
      </li>
    </ul>
    <p>
      <b>Security.</b>&#160;&#1047;&#1076;&#1077;&#1089;&#1100; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1099; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099;.
    </p>
    <ul>
      <li>
        <b>Authentication provider</b>. &#1050;&#1090;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100;&#1089;&#1103; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1077;&#1081;

        <ul>
          <li>
            RADIUS Authentication. &#1053;&#1072; &#1082;&#1086;&#1075;&#1086;-&#1090;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1073;&#1091;&#1076;&#1077;&#1084;.
          </li>
          <li>
            <u>Windows Authentication</u>. &#1051;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; (&#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; Network Policy Server (NPS))
          </li>
        </ul>
      </li>
      <li>
        <b>Authentication Methods</b>. &#1055;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1099;&#1081; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;. &#1045;&#1089;&#1083;&#1080; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090; &#1085;&#1077; &#1087;&#1088;&#1077;&#1076;&#1098;&#1103;&#1074;&#1080;&#1090; &#1086;&#1090;&#1084;&#1077;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; &#1079;&#1076;&#1077;&#1089;&#1100; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074;, &#1090;&#1086; &#1086;&#1085; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1087;&#1091;&#1097;&#1077;&#1085;.

        <ul>
          <li>
            &#1057;HAP (&#1086;&#1089;&#1083;&#1072;&#1073;&#1083;&#1077;&#1085;&#1085;&#1086;&#1077; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1077; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;) &#1080; PAP (&#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1084; &#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1084;) - &#1085;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1102;&#1090;&#1089;&#1103;
          </li>
          <li>
            EAP+MS-CHAP v2+ (&#1085;&#1077; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;) Allow machine certificate authentication for IKEv2 (&#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1086;&#1074;&#1072;&#1083;&#1082;&#1072; IPv6 IPSec)
          </li>
        </ul>
      </li>
      <li>
        <b>Accounting provider.</b>&#160;&#1050;&#1091;&#1076;&#1072; &#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1083;&#1086;&#1075;&#1080;. None or RADIUS Accounting or <u>Windows Accounting</u>.
      </li>
    </ul>
    <p>
      <b>IPv4</b>
    </p>
    <ul>
      <li>
        Enable IPv4 Forwarding
      </li>
      <li>
        Dynamic Host Configuration Protocol (DHCP)
      </li>
      <li>
        Enable broadcast name resolution
      </li>
      <li>
        Adapter - &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1089; &#1082;&#1072;&#1082;&#1086;&#1075;&#1086; &#1072;&#1076;&#1072;&#1087;&#1090;&#1077;&#1088;&#1072; &#1073;&#1091;&#1076;&#1091;&#1090; &#1073;&#1088;&#1072;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; DHCP, DNS, WINS
      </li>
    </ul>
    <p>
      <b>IPv6</b>
    </p>
    <ul>
      <li>
        Enable IPv6 Forwarding
      </li>
      <li>
        Enable Default Route Advertisement
      </li>
      <li>
        IPv6 prefix: fd00:9:9:9::
      </li>
      <li>
        Adapter - Allow RAS to select adapter
      </li>
    </ul>
    <p>
      IKEv2
    </p>
    <p>
      PPP
    </p>
    <p>
      Logging
    </p>
  </body>
</html></richcontent>
</node>
