      <li>
        &#1042;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;. RRAS\ IPv4\ General &gt; New Routing Protocol\ <b>RIP Version 2 for Internet Protocol</b>&#160;(&#1089;&#1084;. <a href="#ID_1820022197">&#1055;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1099;</a>), <font color="#ff0000">RIP &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1083;&#1103; &#1090;&#1077;&#1089;&#1090;&#1086;&#1074;</font>&#160;- &#1074; &#1088;&#1072;&#1073;&#1086;&#1090;&#1077; &#1053;&#1045; &#1048;&#1057;&#1055;&#1054;&#1051;&#1068;&#1047;&#1054;&#1042;&#1040;&#1058;&#1068;
      </li>
      <li>
        &#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1074; RIP &#1085;&#1072;&#1096;&#1080; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;. RIP &gt; New Interface
      </li>
      <li>
        &#1053;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;. General\<br/>Outgoing packet protocol\ RIP v2 multicast &gt;<br/>Incoming packet protocol\ RIPv2 only
      </li>
      <li>
