<node TEXT="NPS?????" FOLDED="true" ID="ID_606842196" CREATED="1519112079750" MODIFIED="1519112079750"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Network Policy Server (NPS).</b>
    </p>
    <ul>
      <li>
        &#1041;&#1077;&#1079; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1089;&#1083;&#1091;&#1078;&#1073;&#1099; &#1077;&#1089;&#1090;&#1100; <b>&#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1072;&#1103; &#1074;&#1077;&#1088;&#1089;&#1080;&#1103; NPS</b>, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; RRAS (Remote Access Logging &amp; Policies &gt; Launch NPS)
      </li>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1089;&#1083;&#1091;&#1078;&#1073;&#1099; &#1078;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1084;&#1072;&#1096;&#1080;&#1085;&#1091;&#160;&#160;&#160;.
      </li>
      <li>
        RADIUS Clients - &#1090;&#1077; &#1093;&#1086;&#1089;&#1090;&#1099; &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103; &#1080; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1101;&#1090;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077;.
      </li>
    </ul>
    <p>
      3 &#1090;&#1080;&#1087;&#1072; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;:
    </p>
    <ul>
      <li>
        <b>Connection Request Policies</b>&#160;- &#1075;&#1076;&#1077; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;
      </li>
      <li>
        <b>Network Policies</b>&#160;- &#1082;&#1072;&#1082; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086;&#1089;&#1103;
      </li>
      <li>
        <b>Health Policies</b>&#160;- &#1082;&#1072;&#1082; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1090;&#1100; &#1082;&#1088;&#1080;&#1090;&#1077;&#1088;&#1080;&#1080;, &#1087;&#1086;&#1076;&#1093;&#1086;&#1076;&#1080;&#1090; &#1086;&#1085; &#1074; &#1085;&#1072;&#1096;&#1091; &#1089;&#1077;&#1090;&#1100; &#1080;&#1083;&#1080; &#1085;&#1077;&#1090;.
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <font color="#ff0000">&#1055;&#1086; RADIUS &#1086;&#1073;&#1098;&#1103;&#1089;&#1085;&#1077;&#1085;&#1080;&#1077; &#1091; &#1050;&#1072;&#1088;&#1084;&#1072;&#1085;&#1086;&#1074;&#1072; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1055;&#1055;&#1062;.&#1087;&#1086;&#1082;&#1072; &#1085;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;. &#1063;&#1091;&#1090;&#1086;&#1082; &#1088;&#1072;&#1079;&#1086;&#1073;&#1088;&#1072;&#1083;&#1089;&#1103; &#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1085;&#1077; &#1089;&#1084;&#1086;&#1075;</font>
    </p>
    <p>
      &#1053;&#1072; &#1088;&#1072;&#1076;&#1080;&#1091;&#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;
    </p>
    <ol>
      <li>
        <b>&#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; RADIUS Clients</b>&#160;&gt; New..., Advanced\ Additional Options &gt; Access-Request messages must contain the Message-Authenticator attribute (Enabled).
      </li>
    </ol>
    <p>
      &#1053;&#1072; &#1088;&#1072;&#1076;&#1080;&#1091;&#1089; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1077;
    </p>
    <ol>
      <li>
        <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1088;&#1077;&#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1072; RADIUS &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;</b>. Policies\ Connection Request Policies\ &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1084; Microsoft RRAS Policy;<br/>Properties\ Use Windows authentication for all users\ Properties\ Conditions (&#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074;&#1089;&#1077; &#1076;&#1085;&#1080;, &#1074;&#1089;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103;)<br/>
      </li>
      <li>
        \Settings \ Authentication\ Authentication requests on this server&gt; New\ &gt; Specify Conditions\ Tunnel Type\ PPTP
      </li>
      <li>
        <b>&#1050;&#1072;&#1082; &#1086;&#1076;&#1080;&#1085; RADIUS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1079;&#1072;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1090;&#1100; &#1091; &#1076;&#1088;&#1091;&#1075;&#1086;&#1075;&#1086; RADIUS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;.</b>&#160;&#1076;&#1083;&#1103; PPTP &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1080;&#1084;&#1077;&#1085;&#1072;. Authentication\ Forward requests to the following remote RADIUS&#160;server group for authentication &gt; New
      </li>
    </ol>
  </body>
</html></richcontent>
