<node TEXT="Remote Assistance" ID="ID_163089494" CREATED="1519112079751" MODIFIED="1525115567002" VSHIFT_QUANTITY="0.75 pt"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>RDP (Remote Desktop Protocol)</b>&#160;- &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1091;&#1076;&#1072;&#1083;&#1105;&#1085;&#1085;&#1086;&#1075;&#1086; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1075;&#1086; &#1089;&#1090;&#1086;&#1083;&#1072;.
    </p>
    <p>
      
    </p>
    <p>
      <b>Remote Assistance</b>&#160;- &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1087;&#1086; &#1087;&#1088;&#1080;&#1075;&#1083;&#1072;&#1096;&#1077;&#1085;&#1080;&#1102;, <font color="#0000c0">msra</font>. <font color="#000000">&#160;<i>&#1055;&#1091;&#1089;&#1082; &gt; </i></font><i>&#1055;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &gt; &#1054;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1077; &gt; &#1059;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086;&#1084;&#1086;&#1097;&#1085;&#1080;&#1082; Windows.</i>
    </p>
    <ul>
      <li>
        &#1053;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1077; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1074; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1093; PC &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086;&#1084;&#1086;&#1097;&#1085;&#1080;&#1082;
      </li>
      <li>
        &#1040;&#1076;&#1084;&#1080;&#1085; &#1074;&#1089;&#1077; &#1074;&#1080;&#1076;&#1080;&#1090;, &#1085;&#1086; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090;.
      </li>
      <li>
        &#1045;&#1089;&#1090;&#1100; &#1095;&#1072;&#1090;
      </li>
      <li>
        &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; <b>&#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;</b>
      </li>
    </ul>
  </body>
