<node TEXT="DirectAccess" FOLDED="true" ID="ID_1569125652" CREATED="1519112079751" MODIFIED="1525115626372"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1072;&#1084;&#1099;&#1081; &#1089;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1081;</b>&#160; (&#1085;&#1072; 2012 &#1075;&#1086;&#1076;) &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1072;&#1084; &#1082;&#1086;&#1088;&#1087;&#1086;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;. &#1058;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; &#1087;&#1086;&#1103;&#1074;&#1080;&#1083;&#1072;&#1089;&#1100; &#1074; WS2008R2&#160;&#160;(W7e), &#1085;&#1091;&#1078;&#1085;&#1072; IPv6 &#1089;&#1077;&#1090;&#1100;.
    </p>
    <ul>
      <li>
        &#1082;&#1072;&#1082; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1099; &#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1089;&#1077;&#1090;&#1080;, &#1090;&#1072;&#1082; &#1080; &#1072;&#1076;&#1084;&#1080;&#1085;&#1099; &#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;&#1084;
      </li>
      <li>
        &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; VPN &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103;. &#1055;&#1088;&#1086;&#1097;&#1077; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1095;&#1077;&#1084; VPN
      </li>
      <li>
        &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; &#1089;&#1074;&#1086;&#1080; &#1082;&#1086;&#1088;&#1088;&#1087;&#1086;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1077; &#1083;&#1086;&#1075;&#1080;&#1085; &#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;. &#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1087;&#1086;&#1083;&#1085;&#1086;&#1094;&#1077;&#1085;&#1085;&#1099;&#1084; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1086;&#1084; &#1082;&#1086;&#1088;&#1087;&#1086;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;
      </li>
      <li>
        &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; <b>IPv6 &#1080; IPSec</b>&#160;(&#1089;&#1086;&#1082;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1077; &#1086;&#1090; IP Security) &#8212; &#1085;&#1072;&#1073;&#1086;&#1088; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074; &#1076;&#1083;&#1103; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &#1079;&#1072;&#1097;&#1080;&#1090;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1099;&#1093; &#1087;&#1086; &#1084;&#1077;&#1078;&#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1084;&#1091; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; IP. &#1055;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1090;&#1100; &#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1076;&#1083;&#1080;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080; (&#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1102;), &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1091; &#1094;&#1077;&#1083;&#1086;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080;/&#1080;&#1083;&#1080; &#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; IP-&#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;. IPsec &#1090;&#1072;&#1082;&#1078;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1074; &#1089;&#1077;&#1073;&#1103; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1099; &#1076;&#1083;&#1103; &#1079;&#1072;&#1097;&#1080;&#1097;&#1105;&#1085;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1084;&#1077;&#1085;&#1072; &#1082;&#1083;&#1102;&#1095;&#1072;&#1084;&#1080; &#1074; &#1089;&#1077;&#1090;&#1080; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;.
      </li>
    </ul>
    <p>
      &#1055;&#1086;&#1083;&#1085;&#1086;&#1094;&#1077;&#1085;&#1085;&#1072;&#1103; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084; <b>IPv6.</b>&#160;&#1053;&#1086; &#1085;&#1077; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; IPv6. &#1055;&#1088;&#1080;&#1076;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1090;&#1091;&#1085;&#1085;&#1077;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;, &#1090;.&#1077;. &#1080;&#1085;&#1082;&#1072;&#1087;&#1089;&#1091;&#1083;&#1103;&#1094;&#1080;&#1102; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; IPv6 &#1074; IPv4. &#1045;&#1089;&#1090;&#1100; 3 &#1088;&#1072;&#1079;&#1085;&#1086;&#1074;&#1080;&#1076;&#1085;&#1086;&#1089;&#1090;&#1080; &#1085;&#1072; Microsoft-&#1087;&#1083;&#1072;&#1090;&#1092;&#1086;&#1088;&#1084;&#1072;&#1093;.
    </p>
    <ul>
      <li>
        <b>6to4</b>&#160;- &#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; IPv6-&#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1095;&#1077;&#1088;&#1077;&#1079; IPv4-&#1089;&#1077;&#1090;&#1080; &#1080; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1102;&#1097;&#1080;&#1081; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1076;&#1074;&#1091;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1080;&#1093; &#1090;&#1091;&#1085;&#1085;&#1077;&#1083;&#1077;&#1081;. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1086;&#1095;&#1077;&#1085;&#1100; &#1085;&#1077;&#1087;&#1088;&#1086;&#1089;&#1090;&#1072;.
      </li>
      <li>
        <b>ISATAP</b>&#160;- <b>Intra-Site Automatic Tunnel Addressing Protocol</b>&#160;&#8212; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080;&#1089;&#1072;&#1081;&#1090;&#1086;&#1074;&#1086;&#1081; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1094;&#1080;&#1080; &#1090;&#1091;&#1085;&#1085;&#1077;&#1083;&#1077;&#1081;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1077;&#1090;&#1103;&#1084;&#1080; IPv6 &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1077;&#1090;&#1080; IPv4. &#1047;&#1072;&#1090;&#1086;&#1095;&#1077;&#1085; &#1087;&#1086;&#1076; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080;&#1082;&#1086;&#1088;&#1087;&#1086;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1091;&#1102; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102;
      </li>
      <li>
        <b>Teredo</b>&#160;- &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; IPv6 &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1077;&#1090;&#1080; IPv4, &#1074; &#1095;&#1072;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;, &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1097;&#1080;&#1077; &#1087;&#1086; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; NAT, &#1087;&#1091;&#1090;&#1105;&#1084; &#1080;&#1093; &#1080;&#1085;&#1082;&#1072;&#1087;&#1089;&#1091;&#1083;&#1103;&#1094;&#1080;&#1080; &#1074; UDP-&#1076;&#1072;&#1090;&#1072;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;.
      </li>
    </ul>
    <p>
      <b>Troubleshooting</b>
    </p>
    <ul>
      <li>
        &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1084;&#1072;&#1089;&#1090;&#1077;&#1088;&#1072; &#1083;&#1077;&#1075;&#1082;&#1086;
      </li>
      <li>
        &#1086;&#1089;&#1085;&#1086;&#1074;&#1099;&#1085;&#1077; &#1089;&#1083;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089; &#1090;&#1091;&#1085;&#1085;&#1077;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; IPv6 &#1074; IPv4
      </li>
    </ul>
  </body>
</html></richcontent>
