        &#1054;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1072; &#1087;&#1072;&#1087;&#1082;&#1072; &#1076;&#1083;&#1103; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103;. &#1040;&#1076;&#1084;&#1080;&#1085; (&#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081; &#1084;&#1080;&#1075;&#1088;&#1072;&#1094;&#1080;&#1077;&#1081;) - &#1086;&#1076;&#1080;&#1085; &#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082;, &#1072;&#1076;&#1084;&#1080;&#1085; (&#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;) - &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082;.
      </li>
    </ul>
