          <li>
            &#1055;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1080;&#1090;&#1100; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1091;&#1102; &#1095;&#1072;&#1089;&#1090;&#1100; DCPs (Data collection packages)
          </li>
          <li>
            &#1056;&#1072;&#1079;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1100; DCPs&#160;(msi) &#1085;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1077; &#1084;&#1072;&#1096;&#1080;&#1085;&#1099; (&#1085;&#1072; 1-2 &#1085;&#1077;&#1076;&#1077;&#1083;&#1080;):

            <ul>
              <li>
                &#1095;&#1077;&#1088;&#1077;&#1079; GPO
              </li>
              <li>
                &#1095;&#1077;&#1088;&#1077;&#1079; System Center Configerftion Manager
              </li>
              <li>
                &#1095;&#1077;&#1088;&#1077;&#1079; &#1072;&#1085;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1089;&#1085;&#1099;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;
              </li>
            </ul>
