      <b>&#1050;&#1072;&#1082; &#1085;&#1072; &#1085;&#1086;&#1090;&#1073;&#1091;&#1082; &#1089; Windows 7 Starter &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; Windows 7 Ultimate? </b>&#1053;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1085;&#1072;&#1076;&#1086; &#1089;&#1082;&#1072;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100;, Windows 7 Starter (&#1082;&#1072;&#1082; &#1074;&#1087;&#1088;&#1086;&#1095;&#1077;&#1084; &#1080; &#1083;&#1102;&#1073;&#1091;&#1102; &#1076;&#1088;&#1091;&#1075;&#1091;&#1102; &#1074;&#1077;&#1088;&#1089;&#1080;&#1102;) &#1080;&#1076;&#1091;&#1097;&#1080;&#1081; &#1089; &#1074;&#1072;&#1096;&#1080;&#1084; &#1085;&#1086;&#1091;&#1090;&#1073;&#1091;&#1082;&#1086;&#1084; &#1080;&#1083;&#1080; &#1085;&#1072;&#1089;&#1090;&#1086;&#1083;&#1100;&#1085;&#1099;&#1084; &#1055;&#1050; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1076;&#1086; Windows 7 Ultimate. &#1044;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1074;&#1072;&#1084; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1074;&#1086;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1086;&#1092;&#1080;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1086;&#1081; (<b>Windows Anytime Upgrade</b>) &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;-&#1087;&#1086;&#1074;&#1099;&#1096;&#1077;&#1085;&#1080;&#1103; &#1090;&#1080;&#1087;&#1072; &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1080;-&#1074;&#1077;&#1088;&#1089;&#1080;&#1080; Windows 7. <b>&#1055;&#1091;&#1089;&#1082; &gt;&#160;&#1087;&#1086;&#1080;&#1089;&#1082; &gt; Windows Anytime Upgrade &gt; </b>&#1042;&#1074;&#1077;&#1089;&#1090;&#1080; &#1082;&#1083;&#1102;&#1095; Windows 7 Ultimate OEM:SLP &#1074;&#1072;&#1096;&#1077;&#1075;&#1086; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1103;&#160;(&#1089;&#1084;. &#1074; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1077;). &#1069;&#1090;&#1086; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1083;&#1077;&#1075;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1072;, &#1085;&#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1072;&#1103; &#1090;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084; Windows 7 Ultimate &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1077; &#1083;&#1077;&#1075;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1058;&#1088;&#1077;&#1093;&#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1085;&#1099;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; OEM OFF-LINE &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080; Windows 7</b>
    </p>
    <ul>
      <li>
        &#1042; Windows 7 &#1082;&#1072;&#1082; &#1080; &#1074; Windows Vista &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1054;&#1060;&#1048;&#1062;&#1048;&#1040;&#1051;&#1068;&#1053;&#1040;&#1071; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1090;&#1088;&#1077;&#1093;-&#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1085;&#1086;&#1081; OEM OFF-LINE &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080; - &#1089;&#1076;&#1077;&#1083;&#1072;&#1085;&#1086; &#1101;&#1090;&#1086; &#1076;&#1083;&#1103; &#1082;&#1088;&#1091;&#1087;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1077;&#1081; &#1087;&#1077;&#1088;&#1089;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1055;&#1050; &#1090;&#1072;&#1082;&#1080;&#1093; &#1082;&#1072;&#1082;: DELL, HP, LENOVO, FSC, SONY &#1080;.&#1090;.&#1076;.
      </li>
      <li>
        &#1057;&#1086;&#1095;&#1077;&#1090;&#1072;&#1085;&#1080;&#1077; &#1090;&#1088;&#1077;&#1093; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1093; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1099; OEM OFF-LINE &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080; &#1076;&#1072;&#1077;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1072;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; Windows 7 &#1073;&#1077;&#1079; &#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1072;.
      </li>
      <li>
        &#160;SLIC &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;, &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090; &#1080; &#1085;&#1086;&#1084;&#1077;&#1088; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1086;&#1090; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1103;
