      </li>
      <li>
        <b>OEM Certificate</b>&#160;(&#1092;&#1072;&#1081;&#1083; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; XML &#1089; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077;&#1084; *.xrm-ms) - &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; OEM'&#1085;&#1099;&#1081; &#1092;&#1072;&#1081;&#1083;-&#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;. &#1042;&#1099;&#1076;&#1072;&#1105;&#1090;&#1089;&#1103; &#1092;&#1080;&#1088;&#1084;&#1086;&#1081; Microsoft &#1082;&#1072;&#1078;&#1076;&#1086;&#1084;&#1091; &#1082;&#1088;&#1091;&#1087;&#1085;&#1086;&#1084;&#1091; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1102; &#1055;&#1050;. &#1069;&#1090;&#1086; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1103; &#1090;&#1072;&#1073;&#1083;&#1080;&#1095;&#1082;&#1072; &#1089; &#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077;&#1084; &#1086; &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1086;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080; &#1054;&#1057;. &#1069;&#1090;&#1072; &#1090;&#1072;&#1073;&#1083;&#1080;&#1095;&#1082;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1075;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1072; &#1074; &#1054;&#1057;
      </li>
      <li>
        <b>OEM SLP</b>&#160;(System-Locked Pre-Installation). &#1057;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; 25&#8209;&#1079;&#1085;&#1072;&#1095;&#1085;&#1099;&#1081; OEM SLP &#1082;&#1083;&#1102;&#1095;-&#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;&#1081; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082;&#1088;&#1091;&#1087;&#1085;&#1099;&#1084; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1103;&#1084; &#1078;&#1077;&#1083;&#1077;&#1079;&#1072;. &#1069;&#1090;&#1086; &#1082;&#1086;&#1076;, &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1072;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;. &#1047;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1074;&#1080;&#1076;&#1072; (&#1088;&#1077;&#1076;&#1072;&#1082;&#1094;&#1080;&#1080;) &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1085;&#1086;&#1081; &#1054;&#1057; (&#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103;, &#1087;&#1088;&#1086;&#1092;&#1077;&#1089;&#1089;&#1080;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103;, &#1076;&#1086;&#1084;&#1072;&#1096;&#1085;&#1103;&#1103; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1085;&#1072;&#1103;, &#1076;&#1086;&#1084;&#1072;&#1096;&#1085;&#1103;&#1103; &#1073;&#1072;&#1079;&#1086;&#1074;&#1072;&#1103;, &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103;) &#1080; &#1086;&#1090; &#1077;&#1077; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080;
