    <ul>
      <li>
        <b>Volume Activation Management Tool (VAMT)</b>&#160;(&#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090; Windows Automated Installation Kit (WAIK)) - &#1076;&#1083;&#1103; <b>MAK Proxy &#1080; KMS &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080;</b>. &#1050; &#1101;&#1090;&#1086;&#1084;&#1091; Proxy &#1073;&#1091;&#1076;&#1091;&#1090; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1099;, Proxy &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1087;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1080;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1074; Microsoft, &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1100; &#1086;&#1090; Microsoft &#1082;&#1083;&#1102;&#1095;&#1080; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080; &#1080; &#1088;&#1072;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1080;&#1093; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080; &#1074;&#1086; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1081; &#1089;&#1077;&#1090;&#1080;. <b>&#1056;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1091;&#1076;&#1086;&#1073;&#1085;&#1086; &#1076;&#1086; 25 &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074;&#160;&#1080;&#1083;&#1080; 5 &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074;. &#1044;&#1086;&#1088;&#1086;&#1075;&#1086; &#1076;&#1083;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1082;&#1072; PC.</b>
      </li>
    </ul>
    <p>
      <b>&#1056;&#1077;&#1081;&#1090;&#1080;&#1085;&#1075; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1074;&#1099;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085; &#1087;&#1086; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1080; &#1089; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1084; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1082;&#1086;&#1084;&#1087;&#1072;:</b>
    </p>
    <p>
      BIOS=&#187;MBR=&#187;bootmgr(linux grub)=&#187;Windows(linux)
    </p>
    <p>
      &#1083;&#1091;&#1095;&#1096;&#1080;&#1084; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1090;&#1086;&#1088;&#1086;&#1084; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1090; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1101;&#1084;&#1091;&#1083;&#1080;&#1088;&#1077;&#1090; slic &#1088;&#1072;&#1085;&#1100;&#1096;&#1077;:
