      14 &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072;/&#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077; &#1083;&#1086;&#1075;&#1086;&#1090;&#1080;&#1087;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1050;&#1052;&#1057; &#8211; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1103;</b>
    </p>
    <p>
      &#1042;&#1099;&#1073;&#1086;&#1088; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080;, &#1095;&#1072;&#1089;&#1086;&#1074;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099; &#1080; &#1089;&#1072;&#1084;&#1072; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1103;.
    </p>
    <p>
      &#1040;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1103; &#1087;&#1086; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1091;:
    </p>
    <p>
      &#1040;&#1082;&#1090;&#1080;&#1074;&#1072;&#1090;&#1086;&#1088; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086;&#1073; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080; &#1087;&#1086; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1091; (&#1086;&#1085; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1072;&#1084; &#1079;&#1074;&#1086;&#1085;&#1080;&#1090;&#1100;)
