<node TEXT="Troubleshooting" ID="ID_1558704215" CREATED="1519112079822" MODIFIED="1542993925510"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>MAK (Multiple Activation Key) Activation</b>
    </p>
    <ol>
      <li>
        &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1089;&#1074;&#1103;&#1079;&#1100; &#1089; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;
      </li>
      <li>
        &#1079;&#1074;&#1086;&#1085;&#1086;&#1082; &#1074; Microsoft
      </li>
    </ol>
    <p>
      <b>KMS (Key Management Server) Activation</b>.
    </p>
    <ol>
      <li>
        &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; <b>SRV (Service Location)-&#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1074; DNS</b>. &#1044;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1083;&#1080; &#1086;&#1085;&#1072; &#1076;&#1083;&#1103; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074;? &#1055;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086; &#1083;&#1080; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1072;?
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; HTTP-&#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;, &#1085;&#1086; &#1087;&#1086;&#1088;&#1090; &#1085;&#1077;&#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; (TCP port 1688). &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1090; &#1083;&#1080; <b>Firewall</b>&#160; &#1087;&#1088;&#1086;&#1093;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;.
      </li>
      <li>
        &#1045;&#1089;&#1090;&#1100; &#1083;&#1080; <b>&#1089;&#1074;&#1103;&#1079;&#1100; &#1089; KMS-&#1093;&#1086;&#1089;&#1090;&#1086;&#1084;</b>?
      </li>
      <li>
        Windows <b>Application event&#160;log</b>&#160;- &#1082;&#1086;&#1074;&#1099;&#1088;&#1103;&#1077;&#1084; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;.
      </li>
    </ol>
  </body>
</html></richcontent>
</node>
