<node TEXT="Как откатить/повысить редакцию W7" ID="ID_565288879" CREATED="1542911086277" MODIFIED="1542911470281"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1562161008">&#1056;&#1077;&#1076;&#1072;&#1082;&#1094;&#1080;&#1080;</a>
    </p>
    <p>
      
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1085;&#1072; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1099; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;, &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1097;&#1080;&#1077; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1076;&#1080;&#1089;&#1082;&#1080; (Deamon tools,Alcohol_120%,&#1080; &#1090;.&#1087;.,&#1082;&#1088;&#1086;&#1084;&#1077; UltraISO 9.) &#1083;&#1091;&#1095;&#1096;&#1077; &#1080;&#1093; &#1089;&#1085;&#1077;&#1089;&#1090;&#1080; &#1076;&#1086; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;, &#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;, &#1072; &#1090;&#1072;&#1082; &#1078;&#1077;, &#1080; &#1072;&#1085;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1089;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;
    </p>
    <p>
      &#1055;&#1088;&#1080; &#1101;&#1090;&#1086;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1077; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; (&#1086;&#1090;&#1082;&#1072;&#1090;&#1072;), &#1086;&#1095;&#1077;&#1085;&#1100; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1083;&#1072; &#1089;&#1077;&#1073;&#1103; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; UltraISO 9., &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1076;&#1080;&#1089;&#1082;, &#1080; &#1089;&#1084;&#1086;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1086;&#1073;&#1088;&#1072;&#1079; W7.
    </p>
    <p>
      regedit \ HKEY_LOCAL_MACHINE\Software\Microsoft\Windows NT\Current Version
    </p>
    <ol>
      <li>
        &#1050;&#1083;&#1102;&#1095; EditionID &gt; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100;. &#1042; &#1087;&#1086;&#1083;&#1077; &quot;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;&quot; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1090;&#1086;&#1081; &#1088;&#1077;&#1076;&#1072;&#1082;&#1094;&#1080;&#1080; &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1084;&#1099; &#1093;&#1086;&#1090;&#1080;&#1084; &#1087;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080;(&#1086;&#1090;&#1082;&#1072;&#1090;&#1080;&#1090;&#1089;&#1103;). &#1042;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;. &quot;EditionID&quot; - Enterprise, Ultimate, Professional, HomePremium, HomeBasic, Starter (x86 only)
      </li>
      <li>
        &#1050;&#1083;&#1102;&#1095; ProductName &gt; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100;. &#1042;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;. &quot;ProductName&quot; - Enterprise, Ultimate, Professional, Home Premium, Home Basic, Starter (x86 only)
      </li>
    </ol>
    <p>
      &#1044;&#1072;&#1083;&#1077;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1091;&#1102; &#1088;&#1077;&#1076;&#1072;&#1082;&#1094;&#1080;&#1102; W7, &#1055;&#1056;&#1071;&#1052;&#1054; &#1048;&#1047; &#1057;&#1048;&#1057;&#1058;&#1045;&#1052;&#1067;.
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1072; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1076;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1076;&#1080;&#1089;&#1082;&#1072; UltraISO 9., &#1080; &#1086;&#1073;&#1088;&#1072;&#1079; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; W7 (*.iso) &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1085;&#1099;&#1081; &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1084; &#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1077; (&#1092;&#1083;&#1077;&#1096;&#1082;&#1077;, &#1078;-&#1076;&#1080;&#1089;&#1082;&#1077;).
    </p>
    <p>
      &#1047;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1091;, &#1084;&#1086;&#1085;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1076;&#1080;&#1089;&#1082;, &#1087;&#1086;&#1084;&#1077;&#1097;&#1072;&#1077;&#1084; &#1090;&#1091;&#1076;&#1072; &#1086;&#1073;&#1088;&#1072;&#1079; W7 (*.iso), &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1091;.
    </p>
    <p>
      &#1042;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1088;&#1072;&#1079; &#1087;&#1077;&#1088;&#1077;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1089;&#1103;.
    </p>
    <p>
      &#1055;&#1086;&#1089;&#1083;&#1077; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1085;&#1080;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1099;, &#1074;&#1089;&#1077; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;, &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;, &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1086;&#1089;&#1090;&#1072;&#1085;&#1091;&#1090;&#1089;&#1103; &#1085;&#1072; &#1089;&#1074;&#1086;&#1080;&#1093; &#1084;&#1077;&#1089;&#1090;&#1072;&#1093;.
    </p>
    <p>
      &#1042;&#1074;&#1086;&#1076;&#1080;&#1084; &#1080;&#1084;&#1077;&#1102;&#1097;&#1080;&#1081;&#1089;&#1103; &#1082;&#1083;&#1102;&#1095;, &#1072;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1077;&#1084;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084; &#1074;&#1089;&#1077; &#1085;&#1091;&#1078;&#1085;&#1099;&#1077; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1086;&#1090; &#1052;&#1057;.
    </p>
  </body>
</html></richcontent>
