<node TEXT="Модели" FOLDED="true" ID="ID_909140985" CREATED="1519112079822" MODIFIED="1519112079822">
<node TEXT="LTI" FOLDED="true" ID="ID_1195210013" CREATED="1519112079822" MODIFIED="1519112079822"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Lite-Touch Deployment, LTI</b>
    </p>
    <ul>
      <li>
        &#1091;&#1089;&#1082;&#1086;&#1088;&#1077;&#1085;&#1085;&#1086;&#1077; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1093; &#1084;&#1077;&#1089;&#1090; &#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; <b>MDT</b>.
      </li>
      <li>
        &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; 500 PC
      </li>
      <li>
        &#1076;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072; &#1086;&#1090;&#1074;&#1077;&#1090;&#1086;&#1074; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084; <b>Windows System Image Manager (Windows SIM,</b>&#160;&#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090; <b>WAIK</b>)
      </li>
      <li>
        &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1080;&#1077; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; &#1079;&#1072;&#1076;&#1072;&#1095;, <b>&#1074; MDT &#1077;&#1089;&#1090;&#1100; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1099;</b>&#160;&#1086;&#1089;&#1085;&#1086;&#1074;&#1099;&#1093; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080;&#1081; &#1079;&#1072;&#1076;&#1072;&#1095;.
      </li>
      <li>
        &#1085;&#1072; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1084; &#1084;&#1077;&#1089;&#1090;&#1077; (&#1095;&#1080;&#1089;&#1090;&#1086;&#1084;) &#1087;&#1077;&#1088;&#1074;&#1086;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1089;&#1090;&#1103; &#1089; &#1076;&#1080;&#1089;&#1082;&#1072; Lite-Touch Installation. &#1053;&#1072;&#1088;&#1077;&#1079;&#1072;&#1090;&#1100; &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072; WDS
      </li>
    </ul>
    <ol>
      <li>
        MAP + ACT - &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1074; &#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100;
      </li>
      <li>
        Install WDS &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;
      </li>
      <li>
        Install MDT
      </li>
      <li>
        &#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1086;&#1095;&#1085;&#1099;&#1093; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;
      </li>
      <li>
        &#1042; MDT &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1077; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1086;&#1095;&#1085;&#1099;&#1081; &#1080;&#1084;&#1080;&#1076;&#1078; &#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1077; &#1074; WDS
      </li>
      <li>
        &#1057;&#1090;&#1072;&#1088;&#1090;&#1091;&#1077;&#1090;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1077; PC.
      </li>
    </ol>
  </body>
</html></richcontent>
<node TEXT="Компоненты" ID="ID_216687657" CREATED="1519112079823" MODIFIED="1543347230881"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1077; &#1088;&#1086;&#1083;&#1080;</b>
    </p>
    <ul>
      <li>
        <b>Build server</b>. &#1047;&#1076;&#1077;&#1089;&#1100; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1086;&#1073;&#1088;&#1072;&#1079;&#1099; &#1083;&#1080;&#1073;&#1086; &#1084;&#1072;&#1090;&#1077;&#1088;&#1080;&#1072;&#1083;&#1099; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1082;&#1080; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1093; &#1084;&#1077;&#1089;&#1090;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1099;, &#1103;&#1079;&#1099;&#1082;&#1086;&#1074;&#1099;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099;, &#1089;&#1077;&#1088;&#1074;&#1080;&#1089; &#1087;&#1072;&#1082;&#1080;, &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        <b>Data server</b>. &#1044;&#1083;&#1103; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1089;&#1085;&#1103;&#1090;&#1099;&#1093; &#1089; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1086;&#1075;&#1086; PC. <b>&#1044;&#1072;&#1085;&#1085;&#1099;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1083;&#1091;&#1095;&#1096;&#1077; &#1085;&#1077; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;</b>.
      </li>
      <li>
        <b>Application installation server.</b>&#160;&#1055;&#1054; &#1085;&#1077; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1074; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074; &#1086;&#1073;&#1088;&#1072;&#1079;&#1072;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1086;&#1073;&#1086;&#1081;&#1090;&#1080;&#1089;&#1100; &#1090;&#1086;&#1085;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;. &#1040; &#1055;&#1054; &#1088;&#1072;&#1079;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1100; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086; &#1080; &#1087;&#1088;&#1080; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1088;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; LTI &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1082;&#1072;&#1082;&#1086;&#1077; &#1055;&#1054; &#1073;&#1091;&#1076;&#1077;&#1090; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1086; &#1085;&#1072; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1077; &#1084;&#1077;&#1089;&#1090;&#1086; &#1087;&#1086; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1085;&#1080;&#1080; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1054;&#1057;.
      </li>
      <li>
        <b>Microsoft Windows Deployment Services (WDS)</b>.
      </li>
      <li>
        <b>Database server</b>. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1076;&#1083;&#1103; &#1073;&#1072;&#1079; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; ACT, MDT &#1080; &#1076;&#1088;.
      </li>
    </ul>
    <p>
      &#1055;&#1086;&#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1082;&#1072;&#1095;&#1072;&#1090;&#1100; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; <b>Microsoft Deployment Toolkit (MDT)</b>&#160;(&#1087;&#1086;&#1076;&#1073;&#1086;&#1088;&#1082;&#1072; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1086;&#1074;,&#1087;&#1086;&#1076;&#1073;&#1086;&#1088;&#1082;&#1072; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074;, &#1087;&#1086;&#1076;&#1073;&#1086;&#1088;&#1082;&#1072; &#1084;&#1072;&#1089;&#1090;&#1077;&#1088;&#1086;&#1074;):
    </p>
    <ul>
      <li>
        Configure ConfigMgr Integration - &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1085;&#1086;&#1081; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099;
      </li>
      <li>
        Deployment Workbench - &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1077; &#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086; &#1076;&#1083;&#1103; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; MDT
      </li>
      <li>
        Remove WDS PXE Filter - &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086;&#1089;&#1083;&#1091;&#1096;&#1082;&#1091; PXE, &#1082;&#1086;&#1075;&#1076;&#1072; &#1088;&#1072;&#1079;&#1085;&#1086;&#1089;&#1080;&#1084; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083; &#1085;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;.
      </li>
    </ul>
    <p>
      <b>&#1058;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086; &#1089;&#1086;&#1092;&#1090;&#1091;:</b>
    </p>
    <ul>
      <li>
        Microsoft Management Console (<a href="#ID_775961878">MMC</a>) 3.0
      </li>
      <li>
        Microsoft .NET Framework 2.0 &#1080;&#1083;&#1080; &#1074;&#1099;&#1096;&#1077;
      </li>
      <li>
        Windows PowerShell 2.0
      </li>
      <li>
        Windows Automated Installation Kit (Windows AIK) 2.0. &#1044;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089; &#1086;&#1073;&#1088;&#1072;&#1079;&#1072;&#1084;&#1080; &#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1084;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080;
      </li>
    </ul>
    <p>
      <b>&#1058;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086; &#1078;&#1077;&#1083;&#1077;&#1079;&#1091; &#1076;&#1083;&#1103; MDT: </b>
    </p>
    <ul>
      <li>
        CPU 1.4 GHz
      </li>
      <li>
        512 MB
      </li>
      <li>
        DNS
      </li>
      <li>
        DHCP
      </li>
    </ul>
  </body>
</html></richcontent>
