        &#1087;&#1088;&#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1079;&#1085;&#1072;&#1082; $ &#1076;&#1077;&#1083;&#1072;&#1077;&#1090; &#1087;&#1072;&#1087;&#1082;&#1091; &#1089;&#1082;&#1088;&#1099;&#1090;&#1086;&#1081;
      </li>
