<node TEXT="ZTI" FOLDED="true" ID="ID_258365645" CREATED="1519112079823" MODIFIED="1556476855289"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Zero Touch Deployment (Zero Touch Installation, ZTI).</b>&#160;
    </p>
    <ul>
      <li>
        upgrage &#1085;&#1077; &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1085;
      </li>
      <li>
        <b>&#1086;&#1090; 20</b>&#160;&#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1093; &#1084;&#1077;&#1089;&#1090;
      </li>
      <li>
        &#1087;&#1086;&#1083;&#1085;&#1072;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103;
      </li>
      <li>
        &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1084; &#1087;&#1088;&#1077;&#1076;&#1087;&#1088;&#1080;&#1103;&#1090;&#1080;&#1080; &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;<b>&#160;&#1086;&#1090; 6 &#1084;&#1077;&#1089;</b>.
      </li>
      <li>
        <b>&#1074;&#1099;&#1089;&#1086;&#1082;&#1072;&#1103; &#1082;&#1074;&#1072;&#1083;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1072;&#1076;&#1084;&#1080;&#1085;&#1086;&#1074;</b>
      </li>
      <li>
        &#1057;&#1073;&#1077;&#1088;&#1073;&#1072;&#1085;&#1082;
      </li>
    </ul>
    <ol>
      <li>
        <b>System Center Configuration Manager&#160;(SCCM)</b>. <font color="#ff0000">&#1055;&#1088;&#1080;&#1086;&#1073;&#1088;&#1077;&#1090;&#1077;&#1085;&#1080;&#1077;</font><font color="#000000">&#160; &gt; &#1048;&#1085;&#1089;&#1090;&#1072;&#1083;&#1083;&#1103;&#1094;&#1080;&#1103; .</font>
      </li>
      <li>
        <b>Microsoft Deployment Toolkit (MDT)</b>&#160;- &#1087;&#1086;&#1076;&#1073;&#1086;&#1088;&#1082;&#1072; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074; &#1080; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1086;&#1074;.

        <ol>
          <li>
            &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; MDT. MDT &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084; &#1085;&#1072; &#1090;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1077;, &#1075;&#1076;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1072; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100; SCCM (&#1085;&#1077; &#1073;&#1072;&#1079;&#1099;).&#1048;&#1085;&#1090;&#1077;&#1075;&#1088;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1080; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1103;&#1077;&#1090; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083; &#1086;&#1085; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1099;&#1081;.
          </li>
          <li>
            &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1075;&#1088;&#1072;&#1094;&#1080;&#1102; MDT &#1080; SCCM &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &quot;Configure ConfigMgr Integration&quot;
          </li>
        </ol>
      </li>
      <li>
        <b>&#1076;&#1083;&#1103; multicast-&#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103;</b>&#160;&#1086;&#1073;&#1088;&#1072;&#1079;&#1072; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080; &#1085;&#1091;&#1078;&#1077;&#1085; <b>Windows Deployment Services&#160;(WDS)</b>. &#1058;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; <b>multicast-&#1088;&#1072;&#1089;&#1089;&#1099;&#1083;&#1086;&#1082;</b>
      </li>
      <li>
        &#1053;&#1077;&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084; &#1101;&#1083;&#1077;&#1084;&#1077;&#1090;&#1086;&#1084; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; <b>Active Directory</b>. &#1053;&#1086; AD&#160;&#1087;&#1086;&#1074;&#1099;&#1096;&#1072;&#1077;&#1090; &#1091;&#1076;&#1086;&#1073;&#1089;&#1090;&#1074;&#1086;. &#1053;&#1072; &#1085;&#1086;&#1074;&#1099;&#1093; PC &#1072;&#1075;&#1077;&#1085;&#1090;&#1099; SCCM &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; AD &#1089;&#1084;&#1086;&#1075;&#1091;&#1090; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1085;&#1072;&#1081;&#1090;&#1080; &#1089;&#1074;&#1086;&#1081; SCCM-&#1084;&#1077;&#1085;&#1077;&#1076;&#1078;&#1084;&#1077;&#1085;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1080;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100;.
      </li>
      <li>
        &#1046;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; <b>Windows Automated Installation Kit&#160;(WAIK)</b>
      </li>
    </ol>
  </body>
</html></richcontent>
<node TEXT="Компоненты" ID="ID_1385954051" CREATED="1519112079823" MODIFIED="1519112079823"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1077; &#1088;&#1086;&#1083;&#1080;</b>
    </p>
    <ul>
      <li>
        <b>Build server</b>. &#1047;&#1076;&#1077;&#1089;&#1100; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1086;&#1073;&#1088;&#1072;&#1079;&#1099; &#1083;&#1080;&#1073;&#1086; &#1084;&#1072;&#1090;&#1077;&#1088;&#1080;&#1072;&#1083;&#1099; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1082;&#1080; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1093; &#1084;&#1077;&#1089;&#1090;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1099;, &#1103;&#1079;&#1099;&#1082;&#1086;&#1074;&#1099;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099;, &#1089;&#1077;&#1088;&#1074;&#1080;&#1089; &#1087;&#1072;&#1082;&#1080;, &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        <b>Data server</b>. &#1044;&#1083;&#1103; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1089;&#1085;&#1103;&#1090;&#1099;&#1093; &#1089; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1086;&#1075;&#1086; PC. <b>&#1044;&#1072;&#1085;&#1085;&#1099;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1083;&#1091;&#1095;&#1096;&#1077; &#1085;&#1077; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;</b>.
      </li>
      <li>
        <b>Application installation server.</b>&#160;&#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1076;&#1083;&#1103; &#1055;&#1054;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1089;&#1103; &#1085;&#1072; &#1088;&#1072;&#1073;.&#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080;.
      </li>
      <li>
        <b>WDS server</b>&#160;- &#1076;&#1083;&#1103; multicast &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1082;&#1080;..
      </li>
      <li>
        <b>Database server</b>. &#1054;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;. SCCM &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1090;&#1072;&#1084; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090; &#1089;&#1074;&#1086;&#1102; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;. &#1053;&#1091;&#1078;&#1077;&#1085; &#1087;&#1086;&#1083;&#1085;&#1086;&#1094;&#1077;&#1085;&#1085;&#1099;&#1081; SQL-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; (Standard &#1080;&#1083;&#1080; Enterprise)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      &#1055;&#1086;&#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1082;&#1072;&#1095;&#1072;&#1090;&#1100; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; <b>Microsoft Deployment Toolkit (MDT)</b>&#160;(&#1087;&#1086;&#1076;&#1073;&#1086;&#1088;&#1082;&#1072; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1086;&#1074;,&#1087;&#1086;&#1076;&#1073;&#1086;&#1088;&#1082;&#1072; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074;, &#1087;&#1086;&#1076;&#1073;&#1086;&#1088;&#1082;&#1072; &#1084;&#1072;&#1089;&#1090;&#1077;&#1088;&#1086;&#1074;):
    </p>
    <ul>
      <li>
        Configure ConfigMgr Integration - &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1085;&#1086;&#1077;&#1081; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099;
      </li>
      <li>
        Deployment Workbench - &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1077; &#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086; &#1076;&#1083;&#1103; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; MDT
      </li>
      <li>
        Remove WDS PXE Filter - &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086;&#1089;&#1083;&#1091;&#1096;&#1082;&#1091; PXE, &#1082;&#1086;&#1075;&#1076;&#1072; &#1088;&#1072;&#1079;&#1085;&#1086;&#1089;&#1080;&#1084; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083; &#1085;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;.
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Настройка" ID="ID_1692951813" CREATED="1519112079824" MODIFIED="1519112079824"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ol>
      <li>
        <b>System Center Configuration Manager&#160;(SCCM)</b>. <font color="#ff0000">&#1055;&#1088;&#1080;&#1086;&#1073;&#1088;&#1077;&#1090;&#1077;&#1085;&#1080;&#1077;</font><font color="#000000">&#160; &gt; &#1048;&#1085;&#1089;&#1090;&#1072;&#1083;&#1083;&#1103;&#1094;&#1080;&#1103;.</font>
      </li>
      <li>
        <b>Microsoft Deployment Toolkit (MDT)</b>&#160;- &#1087;&#1086;&#1076;&#1073;&#1086;&#1088;&#1082;&#1072; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074; &#1080; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1086;&#1074;.

        <ol>
          <li>
            &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; MDT. MDT &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084; &#1085;&#1072; &#1090;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1077;, &#1075;&#1076;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1072; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100; SCCM (&#1085;&#1077; &#1073;&#1072;&#1079;&#1099;).&#1048;&#1085;&#1090;&#1077;&#1075;&#1088;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1080; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1103;&#1077;&#1090; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083; &#1086;&#1085; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1099;&#1081;.
          </li>
          <li>
            &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1075;&#1088;&#1072;&#1094;&#1080;&#1102; MDT &#1080; SCCM &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &quot;Configure ConfigMgr Integration&quot;
          </li>
        </ol>
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084; <b>&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1091;&#1102; &#1088;&#1086;&#1083;&#1100; SCCM (PXE Server Point).</b>
      </li>
      <li>
        <b>&#1076;&#1083;&#1103; multicast-&#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103;</b>&#160;&#1086;&#1073;&#1088;&#1072;&#1079;&#1072; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080; &#1085;&#1091;&#1078;&#1077;&#1085; <b>Windows Deployment Services&#160;(WDS)</b>. &#1058;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; <b>multicast-&#1088;&#1072;&#1089;&#1089;&#1099;&#1083;&#1086;&#1082;</b>
      </li>
      <li>
        &#1053;&#1077;&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084; &#1101;&#1083;&#1077;&#1084;&#1077;&#1090;&#1086;&#1084; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; <b>Active Directory</b>. &#1053;&#1086; AD&#160;&#1087;&#1086;&#1074;&#1099;&#1096;&#1072;&#1077;&#1090; &#1091;&#1076;&#1086;&#1073;&#1089;&#1090;&#1074;&#1086;. &#1053;&#1072; &#1085;&#1086;&#1074;&#1099;&#1093; PC &#1072;&#1075;&#1077;&#1085;&#1090;&#1099; SCCM &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; AD &#1089;&#1084;&#1086;&#1075;&#1091;&#1090; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1085;&#1072;&#1081;&#1090;&#1080; &#1089;&#1074;&#1086;&#1081; SCCM-&#1084;&#1077;&#1085;&#1077;&#1076;&#1078;&#1084;&#1077;&#1085;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1080;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100;.
      </li>
      <li>
        &#1046;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; <b>Windows Automated Installation Kit&#160;(WAIK)</b>
      </li>
      <li>
        &#1055;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1080;&#1090;&#1100; &#1086;&#1073;&#1088;&#1072;&#1079;&#1099;. &#1042;&#1089;&#1077; &#1086;&#1092;&#1086;&#1088;&#1084;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1074;&#1080;&#1076;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;. &#1069;&#1090;&#1080; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1073;&#1091;&#1076;&#1091;&#1090; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1076;&#1086; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074;.
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1081; &#1076;&#1088;&#1091;&#1075; &#1079;&#1072; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; <b>&#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; &#1079;&#1072;&#1076;&#1072;&#1095; (Advertisement</b>&#160;- &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1072;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1076;&#1072;&#1095;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1090; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1099;&#1077; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103; &#1085;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1077;).&#160;&#1044;&#1083;&#1103; &#1079;&#1072;&#1076;&#1072;&#1095;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; Advertisement (&#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1079;&#1072;&#1076;&#1072;&#1095;&#1091; &#1074; &#1089;&#1077;&#1090;&#1100;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1077;&#1077; &#1091;&#1074;&#1080;&#1076;&#1077;&#1083;&#1080; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1099; - &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1099; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1102;&#1090; &#1079;&#1072;&#1076;&#1072;&#1095;&#1080; &#1085;&#1072; management-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1080; &#1091;&#1074;&#1080;&#1076;&#1103;&#1090; <b>Advertisement</b>&#160;(&#1085;&#1072;&#1087;&#1088;. &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;)).
      </li>
      <li>
        <b>&#1050;&#1086;&#1083;&#1083;&#1077;&#1082;&#1094;&#1080;&#1103;</b>&#160;- &#1054;&#1090;&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1087;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1084; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;&#1084; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1086;&#1074;, &#1076;&#1083;&#1103; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1087;&#1088;&#1086;&#1072;&#1076;&#1074;&#1077;&#1088;&#1090;&#1072;&#1081;&#1079;&#1077;&#1085;&#1085;&#1099;&#1077; &#1079;&#1072;&#1076;&#1072;&#1095;&#1080;. &#1053;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074; &#1084;&#1099; &#1089;&#1072;&#1084;&#1080;, &#1073;&#1077;&#1079; AD, &#1084;&#1086;&#1078;&#1077;&#1084; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1090;&#1100; &#1085;&#1072;&#1096;&#1080;&#1093; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074;.
