  </head>
  <body>
    <p>
      <b>System Center Configuration Manager. &#1055;&#1072;&#1082;&#1077;&#1090;&#1099; &#1080; &#1086;&#1073;&#1088;&#1072;&#1079;&#1099; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1076;&#1083;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; &#1079;&#1072;&#1076;&#1072;&#1095; (Task Sequence)</b>&#160;
    </p>
    <ol>
      <li>
        &#1047;&#1072;&#1079;&#1075;&#1088;&#1091;&#1079;&#1086;&#1095;&#1085;&#1099;&#1081; &#1086;&#1073;&#1088;&#1072;&#1079; (<b>Boot image</b>) &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080;.
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1085;&#1072; &#1084;&#1080;&#1075;&#1088;&#1072;&#1094;&#1080;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1090;&#1086; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090; (<b>USMT package</b>). &#1053;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090; &#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1077;&#1075;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1074; <b>Task Sequence</b>&#160;(&#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1076;&#1072;&#1095;).
      </li>
      <li>
        &#1060;&#1072;&#1081;&#1083;&#1099; Microsoft Deployment (ImageX, DISM). &#1053;&#1091;&#1078;&#1085;&#1086; &#1086;&#1092;&#1086;&#1088;&#1084;&#1080;&#1090;&#1100; &#1074; &#1074;&#1080;&#1076;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;
      </li>
      <li>
        &#1054;&#1073;&#1088;&#1072;&#1079; OS (<b>OS image</b>). &#1058;&#1086;&#1083;&#1089;&#1090;&#1099;&#1077; &#1080; &#1075;&#1080;&#1073;&#1088;&#1080;&#1076;&#1085;&#1099;&#1077; &#1086;&#1073;&#1088;&#1072;&#1079;&#1099; &#1085;&#1072;&#1084; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;, &#1084;&#1099; &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1090;&#1086;&#1085;&#1082;&#1080;&#1077;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1074;&#1079;&#1103;&#1090;&#1100; &#1089; &#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1080;&#1074;&#1072; <b>Install.wim</b>&#160;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1077;&#1075;&#1086;.&#160;&#1053;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1072;&#1103; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; &#1085;&#1072; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084; &#1088;&#1072;&#1073;.&#1084;&#1077;&#1089;&#1090;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; &#1079;&#1072;&#1076;&#1072;&#1095;
      </li>
      <li>
        &#1044;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1072; (<b>Device Driver packages</b>)
      </li>
      <li>
        <b>Sysprep files package</b>.
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1072;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1076;&#1072;&#1095;.</b>
