          </li>
          <li>
            &#1057;&#1084;&#1080;&#1075;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084; USMT. &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1086;&#1077;&#1093;&#1072;&#1083;&#1080; &#1085;&#1072; &#1090;&#1086;&#1095;&#1082;&#1091; &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1095;&#1085;&#1086;&#1075;&#1086; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1080; &#1090;&#1072;&#1084; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1083;&#1080;&#1089;&#1100;.
          </li>
          <li>
            <p>
              &#1056;&#1072;&#1079;&#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1086;&#1073;&#1088;&#1072;&#1079; OS. &#1054;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; &#1086;&#1073;&#1088;&#1072;&#1079;&#1072; &#1085;&#1072; &#1085;&#1086;&#1074;&#1086;&#1084; PC.
            </p>
          </li>
          <li>
            &#1057;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1072;&#1084;&#1091; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091; (&#1051;&#1086;&#1075;&#1080;&#1085; &#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;, &#1082;&#1083;&#1102;&#1095; &#1087;&#1088;&#1086;&#1076;&#1091;&#1082;&#1090;&#1072;, &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1103;, &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1092;&#1080;&#1083;&#1103;)
          </li>
          <li>
            &#1053;&#1072;&#1082;&#1088;&#1091;&#1090;&#1080;&#1090;&#1100; &#1076;&#1086;&#1087;. &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1072;. &#1053;&#1072;&#1082;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1072;.
          </li>
          <li>
            &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1084;&#1086;&#1077; &#1055;&#1054;.
          </li>
          <li>
            &#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;. &#1055;&#1088;&#1080;&#1074;&#1083;&#1077;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1072;&#1082;&#1077;&#1090; USMT. &#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089; &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1095;&#1085;&#1086;&#1075;&#1086; &#1093;&#1088;&#1072;&#1085;&#1080;&#1083;&#1080;&#1097;&#1072; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;&#1084; &#1088;&#1072;&#1073;.&#1084;&#1077;&#1089;&#1090;&#1077;.
          </li>
        </ol>
      </li>
      <li>
        &#1057;&#1076;&#1077;&#1083;&#1072;&#1083;&#1080; Advertisment
      </li>
      <li>
        &#1058;.&#1077;. &#1085;&#1072;&#1084; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1075;&#1086;&#1090;&#1086;&#1074;&#1080;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1086;&#1090;&#1074;&#1077;&#1090;&#1086;&#1074; &#1080; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1086;&#1073;&#1088;&#1072;&#1079;.
      </li>
      <li>
        &#1058;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1082; &#1072;&#1076;&#1084;&#1080;&#1085;&#1091;.

        <ol>
