      </li>
      <li>
        <b>Task sequences:</b>&#160;&#1055;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1079;&#1072;&#1076;&#1072;&#1095; &#1076;&#1083;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1093; &#1084;&#1077;&#1089;&#1090;.
      </li>
      <li>
        <b>Scalability:</b>&#160;&#1052;&#1072;&#1089;&#1096;&#1090;&#1072;&#1073;&#1080;&#1088;&#1091;&#1077;&#1084;&#1086;&#1089;&#1090;&#1100; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1057;&#1084;&#1086;&#1078;&#1077;&#1084; &#1083;&#1080; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1090;&#1100; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1100;. &#1044;&#1086;&#1089;&#1090;&#1080;&#1075;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1077;&#1081; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1099;&#1093; &#1082;&#1083;&#1072;&#1089;&#1090;&#1077;&#1088;&#1086;&#1074; &#1083;&#1080;&#1073;&#1086; &#1076;&#1091;&#1073;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1089;&#1083;&#1091;&#1078;&#1073; &#1080; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1074; (&#1090;&#1077; &#1078;&#1077; &#1089;&#1072;&#1084;&#1099; Distribution Points)
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
