        &#1086;&#1073;&#1088;&#1072;&#1079; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; <b>&#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;</b>&#160;&#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; <b>Windows Automated Installation Kit</b>&#160;(WAIK)
      </li>
      <li>
        &#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1072;&#1088;&#1093;&#1080;&#1074;&#1072;&#1090;&#1086;&#1088;&#1072;&#1084;&#1080;
      </li>
      <li>
        &#1074; WIM-&#1092;&#1072;&#1081;&#1083;&#1077; &#1077;&#1089;&#1090;&#1100; &#1074;&#1089;&#1077; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1099;, &#1087;&#1088;&#1080; &#1074;&#1099;&#1073;&#1086;&#1088;&#1077; &#1082;&#1083;&#1102;&#1095;&#1072; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1099;.
      </li>
      <li>
        &#1087;&#1086; &#1089;&#1091;&#1090;&#1080;: &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1089;&#1077;&#1075;&#1086; 2 &#1086;&#1073;&#1088;&#1072;&#1079;&#1072;: 64-&#1073;&#1080;&#1090;&#1072;, 32-&#1073;&#1080;&#1090;&#1072;
      </li>
      <li>
        &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1085;&#1086;&#1089;&#1080;&#1090;&#1100; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1073;&#1077;&#1079; &#1088;&#1072;&#1079;&#1074;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084; <b>ImageX</b>&#160; - &#1101;&#1090;&#1086; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1084;&#1080; &#1092;&#1072;&#1081;&#1083;&#1072;&#1084;&#1080; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074; Windows&#174; (WIM)
      </li>
      <li>
        <i><b>ISO\sources\Boot.wim</b></i>&#160;- &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1086;&#1095;&#1085;&#1099;&#1081;; <i><b>ISO\sources\Install.wim</b></i>&#160;- &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1086;&#1095;&#1085;&#1099;&#1081; &#1085;&#1072; &#1076;&#1080;&#1089;&#1082;&#1077; &#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1080;&#1074;&#1072;
