<node TEXT="Windows PE" ID="ID_1391102490" CREATED="1519112079826" MODIFIED="1519112079826"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Windows Preinstallation Environment (WinPE)</b>&#160;- c&#1088;&#1077;&#1076;&#1072; &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; Windows - &#1086;&#1073;&#1083;&#1077;&#1075;&#1095;&#1105;&#1085;&#1085;&#1072;&#1103; &#1074;&#1077;&#1088;&#1089;&#1080;&#1103; &#1054;&#1057; Windows, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089; &#1082;&#1086;&#1084;&#1087;&#1072;&#1082;&#1090;-&#1076;&#1080;&#1089;&#1082;&#1086;&#1074;, usb &#1080;&#1083;&#1080; &#1078;&#1077; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080;.
    </p>
    <ul>
      <li>
        &#1087;&#1088;&#1080;&#1096;&#1083;&#1072; &#1085;&#1072; &#1089;&#1084;&#1077;&#1085;&#1091; &#1088;&#1072;&#1085;&#1077;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1074;&#1096;&#1077;&#1081;&#1089;&#1103; <b>MS-DOS</b>
      </li>
      <li>
        &#1087;&#1088;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1077; &#1089; &#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1080;&#1074;&#1072;:

        <ol>
          <li>
            &#1057; &#1073;&#1086;&#1083;&#1074;&#1072;&#1085;&#1082;&#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072;&#1075;&#1091;&#1079;&#1086;&#1095;&#1085;&#1099;&#1081; WIM-&#1086;&#1073;&#1088;&#1072;&#1079; &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; BOOT.WIM (&#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085; &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; SOURCE)
          </li>
          <li>
            &#1042; BOOT.WIM &#1089;&#1090;&#1072;&#1088;&#1090;&#1091;&#1077;&#1090; WinPE. WinPE &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; SETUP.EXE (&#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085; &#1074; &#1082;&#1086;&#1088;&#1085;&#1077; &#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1080;&#1074;&#1072;)
          </li>
          <li>
            SETUP.EXE &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1074;&#1089;&#1077; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077;.
          </li>
        </ol>
      </li>
      <li>
