        <ol>
          <li>
            <b>OOBE</b>&#160;- &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1095;&#1080;&#1089;&#1090;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; (<b>Generalize</b>&#160;- &#1089;&#1073;&#1088;&#1086;&#1089; SID, &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1086;&#1074;, &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1088;. &#1080;&#1085;&#1092;. &#1086;&#1090;&#1085;&#1086;&#1089;&#1103;&#1097;&#1077;&#1081;&#1089;&#1103; &#1082; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; &#1055;&#1050;)
          </li>
          <li>
            <b>enter Audit mode</b>&#160;- &#1076;&#1083;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1093; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;
          </li>
        </ol>
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; sysprep &#1085;&#1077;&#1090; &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; &#1087;.2 (&#1085;&#1072;&#1087;&#1088;. Windows XP), &#1090;&#1086;&#1075;&#1076;&#1072; &#1073;&#1077;&#1088;&#1077;&#1084; &#1092;&#1072;&#1081;&#1083;&#1099; &#1080;&#1079; &#1086;&#1073;&#1088;&#1072;&#1079;&#1072;, <font color="#0033cc">SUPPORT\TOOLS\DEPLOY.CAB\</font>&#160; <b>sysprep.exe</b>&#160;<b>setupcl.exe</b>
      </li>
    </ol>
  </body>
</html></richcontent>
