<node TEXT="при помощи утилиты sysprep" ID="ID_1476997483" CREATED="1519112079828" MODIFIED="1519112079828"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1086;&#1095;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1088;&#1072;&#1079;&#1072; (&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; &#1091;&#1090;&#1080;&#1083;&#1080;&#1090;&#1091; <a href="#ID_251185339">sysprep</a>)</b>
    </p>
    <ol>
      <li>
        &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1085;&#1072; &#1090;&#1080;&#1087;&#1086;&#1074;&#1086;&#1081; PC OC ( &#1089; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;).
      </li>
      <li>
        &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1055;&#1054;
      </li>
      <li>
        &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1074; &#1082;&#1086;&#1088;&#1085;&#1077; &#1076;&#1080;&#1089;&#1082;&#1072; &#1087;&#1072;&#1087;&#1082;&#1091; SYSPREP &#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1090;&#1091;&#1076;&#1072; Sysprep.exe &#1080; Setupcl.exe. &#1055;&#1072;&#1087;&#1082;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1072;
      </li>
      <li>
        &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; SYSPREP <a href="#ID_1446309411">&#1092;&#1072;&#1081;&#1083; &#1086;&#1090;&#1074;&#1077;&#1090;&#1086;&#1074;</a>&#160;(&#1095;&#1090;&#1086;&#1073;&#1099; &#1091;&#1089;&#1082;&#1086;&#1088;&#1080;&#1090;&#1100; &#1074;&#1088;&#1077;&#1084;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080;) &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; Setupmgr.exe
      </li>
      <li>
        &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; sysprep.exe. &#1045;&#1089;&#1083;&#1080; &#1087;&#1088;&#1077;&#1076;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077; &#1085;&#1077; PnP-&#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074; (&#1091;&#1089;&#1090;&#1072;&#1088;&#1077;&#1074;&#1096;&#1077;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;), &#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1083;&#1102;&#1095; <font color="#0000c0">-pnp</font>. &#1069;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1080;&#1090; &#1086;&#1073;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080;&#1090;&#1100; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;, &#1085;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1090;&#1100; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1076;&#1086; 20 &#1084;&#1080;&#1085;.
      </li>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1077;&#1085;&#1080;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1087;&#1077;&#1088;&#1077;&#1085;&#1077;&#1089;&#1090;&#1080; HDD &#1074; &#1085;&#1086;&#1074;&#1099;&#1081; PC. &#1047;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100;.
      </li>
    </ol>
  </body>
</html></richcontent>
