<node TEXT="Soft" ID="ID_1948897835" CREATED="1519112079828" MODIFIED="1519112079828"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <a href="#ID_251185339">sysprep</a>
      </li>
      <li>
        <b>Windows Setup</b>&#160;(setup.exe)&#160;- &#1076;&#1083;&#1103; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; &#1082;&#1086;&#1088;&#1087;&#1086;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1088;&#1072;&#1079;&#1072;. &#1058;.&#1077;. &#1096;&#1090;&#1072;&#1090;&#1085;&#1099;&#1081; &#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1080;&#1074; &#1084;&#1086;&#1078;&#1077;&#1084; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1085;&#1077;&#1096;&#1090;&#1072;&#1090;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1088;&#1072;&#1079;&#1072;.

        <ol>
          <li>
            &#1075;&#1086;&#1090;&#1086;&#1074;&#1080;&#1084; &#1085;&#1072;&#1096; WIM-&#1086;&#1073;&#1088;&#1072;&#1079;
          </li>
          <li>
            &#1087;&#1077;&#1088;&#1077;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1099;&#1074;&#1072;&#1077;&#1084; &#1077;&#1075;&#1086; &#1074; INSTALL.WIM
          </li>
          <li>
            &#1084;&#1086;&#1076;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1091;&#1077;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079; &#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1076;&#1080;&#1089;&#1082;&#1072;. &#1057;&#1085;&#1080;&#1084;&#1072;&#1077;&#1084; ISO&#1096;&#1085;&#1080;&#1082; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; rar &#1080;&#1083;&#1080; 7zip &gt; &#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1074; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074; ISO&#1096;&#1085;&#1080;&#1082;&#1072; &#1092;&#1072;&#1081;&#1083; INSTALL.WIN &#1085;&#1072; &#1085;&#1072;&#1096;.
          </li>
          <li>
            &#1073;&#1086;&#1083;&#1074;&#1072;&#1085;&#1082;&#1091; &#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1088;&#1077;&#1079;&#1072;&#1077;&#1084;
          </li>
        </ol>
      </li>
      <li>
        <b>Windows Automated Installation Kit</b>&#160;(WAIK)

        <ul>
          <li>
            Windows System Image Manager (<b>Windows SIM</b>) - &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1086;&#1088; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1086;&#1090;&#1074;&#1077;&#1090;&#1086;&#1074;
          </li>
          <li>
            Windows Preinstallation Environment (<b>Windows PE</b>). Windows PE (&#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090; WAIK) - &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1082;&#1080; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074; &#1085;&#1086;&#1074;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;, &#1076;&#1083;&#1103; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1093; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;, &#1076;&#1083;&#1103; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080;&#1084;&#1077;&#1102;&#1097;&#1077;&#1075;&#1086;&#1089;&#1103; &#1086;&#1073;&#1088;&#1072;&#1079;&#1072; &#1085;&#1072; &#1085;&#1086;&#1074;&#1091;&#1102; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091; (&#1086;&#1076;&#1085;&#1091; &#1080;&#1083;&#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086;). &#1042; &#1077;&#1075;&#1086; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; COPYPE.CMD, &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1072;&#1103; &#1076;&#1083;&#1103; WinPE &#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1072; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1080; &#1087;&#1072;&#1087;&#1086;&#1082;.
          </li>
          <li>
            <b>ImageX</b>&#160;- &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1086;&#1073;&#1088;&#1072;&#1079;&#1072; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1075;&#1086; PC. &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1072; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; <b>&#1089; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1086;&#1084;</b>&#160; WIM-&#1092;&#1072;&#1081;&#1083;&#1072;&#1084;&#1072;. &#1053;&#1077; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; WinPE
          </li>
          <li>
            <b>User State Migration Tool (USMT)</b>&#160;- &#1082;&#1086;&#1088;&#1087;&#1086;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1072;&#1103; &#1074;&#1077;&#1088;&#1089;&#1080;&#1103; &#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072; &#1087;&#1077;&#1088;&#1077;&#1085;&#1086;&#1089;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
          </li>
        </ul>
      </li>
      <li>
        <b>Deployment Image Servicing and Management</b>&#160;(DISM) - &#1076;&#1083;&#1103; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074; <b>&#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1072;</b>&#160;WIM-&#1092;&#1072;&#1081;&#1083;&#1072;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1072; &#1074; &#1093;&#1088;&#1072;&#1085;&#1080;&#1083;&#1080;&#1097;&#1077; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1086;&#1074;.
      </li>
      <li>
        <a href="#ID_131102748">Diskpart</a>&#160;- &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1084;&#1077;&#1085;&#1090; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089; &#1076;&#1080;&#1089;&#1082;&#1072;&#1084;&#1080;, &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1072;&#1084;&#1080; &#1080; &#1090;&#1086;&#1084;&#1072;&#1084;&#1080; (Disk manager &#1073;&#1077;&#1079; GUI). &#1042;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; WinPE.
      </li>
      <li>
        <b>Windows Deployment Services</b>&#160;(WDS). &#1076;&#1083;&#1103; &#1088;&#1072;&#1079;&#1074;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080;, &#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080;. &#1060;&#1086;&#1088;&#1084;&#1072;&#1090; WIM &#1088;&#1086;&#1076;&#1085;&#1086;&#1081; &#1076;&#1083;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; WDS.
      </li>
      <li>
        <b>Virtual Hard Disk</b>&#160;(VHD)
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Создание USB загрузочного диска" ID="ID_1159756767" CREATED="1531478906441" MODIFIED="1784619017000"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_131102748">diskpart</a>&#xa0; <a href="#ID_357201137">USB</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Создание USB загрузочного диска</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>Способ 1 </b>
    </p>
    <p>
      <b>Win10</b>&#xa0;
    </p>
    <p>
      Скачать с сайта Microsoft <b>MediaCreationTool</b>&#xa0;&#xa0;--&gt; Click...
    </p>
    <p>
      
    </p>
    <p>
      <b>2 Способ</b>
    </p>
    <p>
      <b>1. cmd</b>(as adm) --&gt;
    </p>
    <p>
      <b><span style="color: #0000c0;">&gt; diskpart</span></b>
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&gt; list disk</span>&#xa0;&#xa0;# Отобразить диски
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">&gt; select disk 1</span>&#xa0;&#xa0;# Выбор флеш-накопителя
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <span style="color: #0000c0;">&gt; clean&#xa0; </span># Очистить от информации выбранный диск
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <span style="color: #0000c0;">&gt; create partition primary</span>&#xa0;&#xa0;# Создать основной раздел
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <span style="color: #0000c0;">&gt; select partition 1</span>&#xa0;&#xa0;# Выбрать созданный раздел
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0; <span style="color: #0000c0;">&gt; active</span>&#xa0;&#xa0;# Присвоить признак активности раздела (для загрузки системы)
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0; <span style="color: #0000c0;">&gt; format fs=ntfs quick</span>&#xa0;&#xa0;# Создать файловую систему NTFS (быстрое форматирование)
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0; <span style="color: #0000c0;">&gt; assign</span>&#xa0;&#xa0;# Присвоить букву
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">&gt; list vol</span>&#xa0;&#xa0;# Посмотреть список логических дисков (томов)
    </p>
    <p>
      &#xa0; <span style="color: #0000c0;">&gt; exit</span>
    </p>
    <p>
      <span style="color: #0000c0;">&gt; E:\boot\<b>bootsect</b>&#xa0;/nt60 &lt;d:-flash disk&gt;</span>&#xa0;&#xa0;# Записать IPL2 в загрузочную область. bootsect - программа с дистрибутивного диска для <b>создания загрузочной записи</b>
    </p>
    <p>
      2. Cкопировать все файлы с дистрибутивного диска на флеш-накопитель
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Сценарии" FOLDED="true" ID="ID_1931073545" CREATED="1519112079828" MODIFIED="1519112079828">
<node TEXT="Сценарий 1" ID="ID_1083437760" CREATED="1519112079828" MODIFIED="1519112079828"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1-2 PC &#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1103; (&#1076;&#1080;&#1089;&#1090;&#1088;. &#1076;&#1080;&#1089;&#1082;)</b>
    </p>
    <ol>
      <li>
