<node TEXT="diskpart" ID="ID_131102748" CREATED="1519112079813" MODIFIED="1543047776032"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1159756767">&#1055;&#1088;&#1080;&#1084;&#1077;&#1088;1</a>&#160; <a href="#ID_1742397638">&#1056;&#1072;&#1079;&#1084;&#1077;&#1090;&#1082;&#1072; &#1076;&#1080;&#1089;&#1082;&#1086;&#1074;</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>DISKPART</b>&#160;- &#1088;&#1072;&#1073;&#1086;&#1090;&#1072; &#1089; &#1076;&#1080;&#1089;&#1082;&#1072;&#1084;&#1080;
    </p>
    <ul>
      <li>
        &#1077;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1072; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100; &#1087;&#1086; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1077; --&gt; &#1074;&#1074;&#1086;&#1076;&#1080;&#1084; &#1087;&#1077;&#1088;&#1077;&#1076; &#1085;&#1077;&#1081; <b>help</b>&#160;
      </li>
    </ul>
    <p>
      <font color="#0000cc">list</font>&#160;- &#1074;&#1099;&#1074;&#1086;&#1076; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;
    </p>
    <p>
      <font color="#0000cc">select</font>&#160;- &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1092;&#1086;&#1082;&#1091;&#1089;&#1072; &#1085;&#1072; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; (<font color="#0000cc">select disk 0</font>)
    </p>
    <p>
      <font color="#0000c0">clean</font>&#160;-&#160;&#1054;&#1095;&#1080;&#1089;&#1090;&#1080;&#1090;&#1100; &#1086;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1085;&#1099;&#1081; &#1076;&#1080;&#1089;&#1082;
    </p>
    <p>
