      <font color="#0000c0">&gt; wmic [&#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;] &lt; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &gt; </font>
    </p>
