    </p>
  </body>
</html></richcontent>
<node TEXT="FreeBSD" FOLDED="true" ID="ID_1388135225" CREATED="1519112079871" MODIFIED="1583907381504"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      FreeBSD &#1073;&#1099;&#1083; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085; Apple &#1076;&#1083;&#1103; OS Macintosh (&#1103;&#1076;&#1088;&#1086; &#1086;&#1076;&#1085;&#1086; &#1080; &#1090;&#1086; &#1078;&#1077;)
    </p>
    <ul>
      <li>
        &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074; &#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;
      </li>
      <li>
        &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1093; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1081; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1088;&#1077;&#1076;&#1082;&#1086; (&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1077; &#1095;&#1077;&#1084; &#1074; Linux &#1082;&#1086;&#1083;-&#1074;&#1086; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1086;&#1074;, &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;, &#1089;&#1083;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;). &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; &#1077;&#1089;&#1090;&#1100; PcBCD &#1080; DesktopBSD - &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1090; (&#1074;&#1086;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1074;&#1096;&#1080;&#1089;&#1100; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1097;&#1082;&#1086;&#1084;) &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;, &#1086;&#1076;&#1085;&#1072;&#1082;&#1086; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1091; &#1089; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1072;&#1084;&#1080; &#1101;&#1090;&#1086; &#1085;&#1077; &#1088;&#1072;&#1096;&#1072;&#1077;&#1090; (&#1086;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086; &#1089; &#1085;&#1086;&#1074;&#1099;&#1084;&#1099; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1084;&#1080;).
      </li>
      <li>
        source based OS (&#1082;&#1072;&#1082; Gentoo) - &#1090;.&#1077;. &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1077; &#1080;&#1079; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1076;&#1072;
      </li>
      <li>
        &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074;, &#1089;&#1089;&#1099;&#1083;&#1086;&#1082; &#1085;&#1072; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1099;&#1081; &#1082;&#1086;&#1076;&#1080; &#1080; &#1089;&#1094;&#1077;&#1085;&#1072;&#1088;&#1080;&#1081; &#1089;&#1073;&#1086;&#1088;&#1082;&#1080;. &#1044;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080; &#1074; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1089; &#1085;&#1091;&#1078;&#1085;&#1099;&#1084; &#1087;&#1086;&#1088;&#1090;&#1086;&#1084; (&#1074;&#1086;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1074;&#1096;&#1080;&#1089;&#1100; &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1084;) --&gt; &#1085;&#1072;&#1073;&#1088;&#1072;&#1090;&#1100; &#1086;&#1076;&#1085;&#1091; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1080; &#1076;&#1086;&#1078;&#1076;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086;&#1082;&#1072; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1089;&#1082;&#1072;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1089;&#1086;&#1073;&#1077;&#1088;&#1077;&#1090;&#1089;&#1103; &#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1089;&#1103;. &#1048;&#1083;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1091;&#1078;&#1077; &#1089;&#1086;&#1073;&#1088;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1072;&#1082;&#1077;&#1090;&#1085;&#1099;&#1081; &#1084;&#1077;&#1085;&#1077;&#1076;&#1078;&#1077;&#1088;
      </li>
      <li>
        &#1084;&#1086;&#1085;&#1086;&#1083;&#1080;&#1090;&#1085;&#1086;&#1077; &#1103;&#1076;&#1088;&#1086; &#1089; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1086;&#1081; &#1087;&#1086;&#1076;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084;&#1099;&#1093; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;
      </li>
      <li>
        &#1085;&#1077;&#1076;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1084;&#1086; &#1089;&#1080;&#1083;&#1100;&#1085;&#1086; &#1086;&#1090;&#1089;&#1090;&#1072;&#1083; &#1086;&#1090; Linux (&#1087;&#1086; &#1084;&#1085;&#1077;&#1085;&#1080;&#1102; &#1089;&#1087;&#1077;&#1094;. mail.ru - 2014 &#1075;.)
      </li>
    </ul>
    <p>
      1993 - FreeBSD 1.0
    </p>
    <p>
      1995 - FreeBSD 2.0
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        WhatsApp
      </li>
      <li>
        &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1099;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1099; &#1071;&#1085;&#1076;&#1077;&#1082;&#1089;
      </li>
      <li>
        &#1103;&#1076;&#1088;&#1086; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1086;&#1089;&#1085;&#1086;&#1074;&#1086;&#1081; &#1076;&#1083;&#1103; ORBIS OS (Playstation 4)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      &#1043;&#1088;&#1072;&#1092;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1089;&#1090;&#1101;&#1082; &#1080;&#1079; &#1103;&#1076;&#1088;&#1072; Linux 3.8
    </p>
    <p>
      Nvidia &#1074;&#1099;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077; &#1076;&#1083;&#1103; FreeBSD (&#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1091;&#1088;&#1077;&#1079;&#1072;&#1085;, &#1074; &#1089;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1080; &#1089; Linux)
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1081; Linux &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; - <b>Linuxulator</b>
    </p>
    <p>
      
    </p>
    <p>
      Life cycle (&#1089;&#1088;&#1086;&#1082; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080;) - 2 &#1075;&#1086;&#1076;&#1072;. &#1057;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;&#1084;&#1080; &#1087;&#1077;&#1088;&#1077;&#1089;&#1090;&#1072;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; (&#1087;&#1077;&#1088;&#1077;&#1089;&#1090;&#1072;&#1102;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1087;&#1086;&#1088;&#1090;&#1099; &#1080; &#1087;&#1072;&#1082;&#1077;&#1090;&#1085;&#1099;&#1081; &#1084;&#1077;&#1085;&#1077;&#1076;&#1078;&#1077;&#1088;), &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1080; &#1086;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1091; &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;. &#1061;&#1086;&#1090;&#1103; &#1089;&#1072;&#1084; FreeBSD &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100;.
    </p>
  </body>
</html></richcontent>
