<node TEXT="Виды сортировок" ID="ID_886281671" CREATED="1519112080411" MODIFIED="1519112080411"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>bubble sort (&#1087;&#1091;&#1079;&#1099;&#1088;&#1100;&#1082;&#1086;&#1074;&#1072;&#1103; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;)</b>&#160;-&#160;&#160;&#1086;&#1096;&#1080;&#1073;&#1082;&#1080; &#1080;&#1089;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1087;&#1086;&#1087;&#1072;&#1088;&#1085;&#1086;
    </p>
    <ul>
      <li>
        (n-1) - &#1079;&#1072;&#1090;&#1088;&#1072;&#1090;&#1099;
      </li>
    </ul>
    <p>
      <b>&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1082;&#1072; &#1074;&#1099;&#1073;&#1086;&#1088;&#1086;&#1084; (Selection Sort)</b>&#160;- &#1074;&#1099;&#1073;&#1086;&#1088; &#1085;&#1072;&#1080;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1075;&#1086; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;, &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1085;&#1072;&#1080;&#1084;&#1077;&#1085;&#1100;&#1096;&#1080;&#1081; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1083;&#1077;&#1074;&#1099;&#1081; &#1082;&#1088;&#1072;&#1081; &#1085;&#1077;&#1086;&#1090;&#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;
    </p>
    <ul>
      <li>
        (n-1)+(n-2)+...+1 = n(n-1)/2 = (n^2-n)/2 = n^2 / 2 - n/2 = <a href="#ID_665420258">O(n^2)</a>- &#1079;&#1072;&#1090;&#1088;&#1072;&#1090;&#1099;
      </li>
    </ul>
    <p>
      <b>&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1074;&#1089;&#1090;&#1072;&#1074;&#1082;&#1086;&#1081; (Insert Sort)</b>&#160; - &#1073;&#1077;&#1088;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1091; &#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1086;&#1090;&#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1089;&#1083;&#1077;&#1074;&#1072; (&#1087;&#1088;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1089;&#1076;&#1074;&#1080;&#1075;&#1072;&#1077;&#1084; &#1077;&#1075;&#1086;)
    </p>
    <ul>
      <li>
        <a href="#ID_665420258">O(n^2)</a>- &#1079;&#1072;&#1090;&#1088;&#1072;&#1090;&#1099;
      </li>
    </ul>
    <p>
      <b>&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1089;&#1083;&#1080;&#1103;&#1085;&#1080;&#1077;&#1084; (Merge Sort) </b>
    </p>
    <ul>
      <li>
        &#1083;&#1086;&#1075;&#1072;&#1088;&#1080;&#1092;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        <b>O(n log n)</b>&#160;- &#1074;&#1077;&#1088;&#1093;&#1085;&#1080;&#1081; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;
      </li>
    </ul>
    <p>
      <b>&#1041;&#1099;&#1089;&#1090;&#1088;&#1072;&#1103; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;</b>, &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1061;&#1086;&#1072;&#1088;&#1072; <b>(quicksort), qsort</b>&#160;(&#1087;&#1086; &#1080;&#1084;&#1077;&#1085;&#1080; &#1074; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086;&#1081; &#1073;&#1080;&#1073;&#1083;&#1080;&#1086;&#1090;&#1077;&#1082;&#1077; &#1103;&#1079;&#1099;&#1082;&#1072; &#1057;&#1080;) &#8212; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1081; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080;, &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085;&#1085;&#1099;&#1081; &#1074; 1960 &#1075;&#1086;&#1076;&#1091;. &#1054;&#1076;&#1080;&#1085; &#1080;&#1079; &#1089;&#1072;&#1084;&#1099;&#1093; &#1073;&#1099;&#1089;&#1090;&#1088;&#1099;&#1093; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1093; &#1091;&#1085;&#1080;&#1074;&#1077;&#1088;&#1089;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084;&#1086;&#1074; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;
    </p>
    <ul>
      <li>
        &#1074; &#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1084; <b>O( n log n )</b>&#160;&#1086;&#1073;&#1084;&#1077;&#1085;&#1086;&#1074; &#1087;&#1088;&#1080; &#1091;&#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1095;&#1077;&#1085;&#1080;&#1080; n &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;
      </li>
    </ul>
    <p>
      <b>&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1087;&#1086;&#1076;&#1089;&#1095;&#1077;&#1090;&#1086;&#1084; (Counting sort)</b>&#160; - &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#1095;&#1080;&#1089;&#1077;&#1083; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;&#1086;&#1075;&#1086; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072; (&#1089;&#1087;&#1080;&#1089;&#1082;&#1072;) &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1089;&#1095;&#1105;&#1090;&#1072; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1102;&#1097;&#1080;&#1093; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;.
    </p>
    <ul>
      <li>
        &#1094;&#1077;&#1083;&#1077;&#1089;&#1086;&#1086;&#1073;&#1088;&#1072;&#1079;&#1085;&#1086; &#1083;&#1080;&#1096;&#1100; &#1082;&#1086;&#1075;&#1076;&#1072; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;&#1099;&#1077; &#1095;&#1080;&#1089;&#1083;&#1072; &#1080;&#1084;&#1077;&#1102;&#1090; (&#1080;&#1083;&#1080; &#1080;&#1093; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1079;&#1080;&#1090;&#1100; &#1074;) &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1099;&#1093; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1084;&#1072;&#1083; &#1087;&#1086; &#1089;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1102; &#1089; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;&#1099;&#1084; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1086;&#1084;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1084;&#1080;&#1083;&#1083;&#1080;&#1086;&#1085; &#1085;&#1072;&#1090;&#1091;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1095;&#1080;&#1089;&#1077;&#1083; &#1084;&#1077;&#1085;&#1100;&#1096;&#1080;&#1093; 1000
      </li>
    </ul>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="O (O большое)" ID="ID_665420258" CREATED="1519112080411" MODIFIED="1519112080411"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_682909033">&#937; (&#1054;&#1084;&#1077;&#1075;&#1072;)</a>
    </p>
    <p>
      
    </p>
    <p>
      O&#160;&#160;- &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1097;&#1080;&#1082;&#1072;&#1084;&#1080; &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1074;&#1077;&#1088;&#1093;&#1085;&#1102;&#1102; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091; &#1095;&#1077;&#1075;&#1086;-&#1090;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1075;&#1086;&#160;
    </p>
    <ul>
      <li>
        &#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1086;&#1087;&#1086;&#1083;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; - <b>&#937; (&#1054;&#1084;&#1077;&#1075;&#1072;)</b>&#160;- &#1085;&#1080;&#1078;&#1085;&#1103;&#1103; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;
