    <p>
      <b>O(n)</b>&#160;- &#1083;&#1080;&#1085;&#1077;&#1081;&#1085;&#1099;&#1081; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; (&#1083;&#1080;&#1085;&#1077;&#1081;&#1085;&#1099;&#1081; &#1087;&#1086;&#1080;&#1089;&#1082; &#1074; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1084; &#1089;&#1087;&#1088;&#1072;&#1074;&#1086;&#1095;&#1085;&#1080;&#1082;&#1077;)
