<node TEXT="Принципы фон Неймана" ID="ID_1177824597" CREATED="1519112080416" MODIFIED="1541755932334"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087;&#1099; &#1092;&#1086;&#1085; &#1053;&#1077;&#1081;&#1084;&#1072;&#1085;&#1072;</b>
    </p>
    <p>
      <b>&#160;&#160;&#160;&#160;&#1055;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1086;&#1076;&#1085;&#1086;&#1088;&#1086;&#1076;&#1085;&#1086;&#1089;&#1090;&#1080; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;. </b>&#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1081; &#1080; &#1090;&#1086;&#1081; &#1078;&#1077; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077; &#1074; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1085;&#1077;&#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1080;&#1084;&#1099;. &#1056;&#1072;&#1089;&#1087;&#1086;&#1079;&#1085;&#1072;&#1090;&#1100; &#1080;&#1093; &#1084;&#1086;&#1078;&#1085;&#1086; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1086; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1091; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;; &#1090;&#1086; &#1077;&#1089;&#1090;&#1100; &#1086;&#1076;&#1085;&#1086; &#1080; &#1090;&#1086; &#1078;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074; &#1103;&#1095;&#1077;&#1081;&#1082;&#1077; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1080; &#1082;&#1072;&#1082; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;, &#1080; &#1082;&#1072;&#1082; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072;, &#1080; &#1082;&#1072;&#1082; &#1072;&#1076;&#1088;&#1077;&#1089; &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1083;&#1080;&#1096;&#1100; &#1086;&#1090; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1072; &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1103; &#1082; &#1085;&#1077;&#1084;&#1091;. &#1069;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1085;&#1072;&#1076; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072;&#1084;&#1080; &#1090;&#1077; &#1078;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080;, &#1095;&#1090;&#1086; &#1080; &#1085;&#1072;&#1076; &#1095;&#1080;&#1089;&#1083;&#1072;&#1084;&#1080;, &#1080;, &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;, &#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090; &#1088;&#1103;&#1076; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1077;&#1081;
    </p>
    <p>
      <b>&#160;&#160;&#160;&#160;&#1055;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1072;&#1076;&#1088;&#1077;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080;. </b>&#1057;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1085;&#1086; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1072;&#1103; &#1087;&#1072;&#1084;&#1103;&#1090;&#1100; &#1089;&#1086;&#1089;&#1090;&#1086;&#1080;&#1090; &#1080;&#1079; &#1087;&#1088;&#1086;&#1085;&#1091;&#1084;&#1077;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1093; &#1103;&#1095;&#1077;&#1077;&#1082;, &#1087;&#1088;&#1080;&#1095;&#1105;&#1084; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1091; &#1074; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1083;&#1100;&#1085;&#1099;&#1081; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1083;&#1102;&#1073;&#1072;&#1103; &#1103;&#1095;&#1077;&#1081;&#1082;&#1072;. &#1044;&#1074;&#1086;&#1080;&#1095;&#1085;&#1099;&#1077; &#1082;&#1086;&#1076;&#1099; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076; &#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1077;&#1076;&#1080;&#1085;&#1080;&#1094;&#1099; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;, &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;&#1099;&#1077; &#1089;&#1083;&#1086;&#1074;&#1072;&#1084;&#1080;, &#1080; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1074; &#1103;&#1095;&#1077;&#1081;&#1082;&#1072;&#1093; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;, &#1072; &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1085;&#1080;&#1084; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1085;&#1086;&#1084;&#1077;&#1088;&#1072; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1093; &#1103;&#1095;&#1077;&#1077;&#1082; &#8212; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;.
    </p>
    <p>
      &#160;&#160;&#160; <b>&#1055;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1085;&#1086;&#1075;&#1086; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;. </b>&#1042;&#1089;&#1077; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1085;&#1085;&#1099;&#1077; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084;&#1086;&#1084; &#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1103; &#1079;&#1072;&#1076;&#1072;&#1095;&#1080;, &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1099; &#1074; &#1074;&#1080;&#1076;&#1077; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;, &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1097;&#1077;&#1081; &#1080;&#1079; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1093; &#1089;&#1083;&#1086;&#1074; &#8212; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;. &#1050;&#1072;&#1078;&#1076;&#1072;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1087;&#1088;&#1077;&#1076;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1102; &#1080;&#1079; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1081;, &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1091;&#1077;&#1084;&#1099;&#1093; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1086;&#1081;. &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1074; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1103;&#1095;&#1077;&#1081;&#1082;&#1072;&#1093; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1099; &#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1074; &#1077;&#1089;&#1090;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1081; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080;, &#1090;&#1086; &#1077;&#1089;&#1090;&#1100; &#1074; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1080;&#1093; &#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1074; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1077;. &#1055;&#1088;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080;, &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;, &#1101;&#1090;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1072;. &#1056;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1086;&#1073; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1080; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1072; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;&#1089;&#1103; &#1083;&#1080;&#1073;&#1086; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1086;&#1074; &#1087;&#1088;&#1077;&#1076;&#1096;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1093; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1081;, &#1083;&#1080;&#1073;&#1086; &#1073;&#1077;&#1079;&#1091;&#1089;&#1083;&#1086;&#1074;&#1085;&#1086;.
    </p>
    <p>
      <b>&#160;&#160;&#160;&#160;&#1055;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1076;&#1074;&#1086;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;</b>. &#1042;&#1089;&#1103;&#160;&#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103;, &#1082;&#1072;&#1082; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;, &#1090;&#1072;&#1082; &#1080; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;, &#1082;&#1086;&#1076;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1076;&#1074;&#1086;&#1080;&#1095;&#1085;&#1099;&#1084;&#1080; &#1094;&#1080;&#1092;&#1088;&#1072;&#1084;&#1080; 0 &#1080; 1. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1090;&#1080;&#1087; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1076;&#1074;&#1086;&#1080;&#1095;&#1085;&#1086;&#1081; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1080; &#1080;&#1084;&#1077;&#1077;&#1090; &#1089;&#1074;&#1086;&#1081; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;. &#1055;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1073;&#1080;&#1090;&#1086;&#1074; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077;, &#1080;&#1084;&#1077;&#1102;&#1097;&#1072;&#1103; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089;&#1084;&#1099;&#1089;&#1083;, &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1083;&#1077;&#1084;. &#1042; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1074;&#1099;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090; &#1087;&#1086;&#1083;&#1077; &#1079;&#1085;&#1072;&#1082;&#1072; &#1080; &#1087;&#1086;&#1083;&#1077; &#1079;&#1085;&#1072;&#1095;&#1072;&#1097;&#1080;&#1093; &#1088;&#1072;&#1079;&#1088;&#1103;&#1076;&#1086;&#1074;. &#1042; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1074; &#1087;&#1088;&#1086;&#1089;&#1090;&#1077;&#1081;&#1096;&#1077;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1076;&#1074;&#1072; &#1087;&#1086;&#1083;&#1103;: &#1087;&#1086;&#1083;&#1077; &#1082;&#1086;&#1076;&#1072; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080; &#1080; &#1087;&#1086;&#1083;&#1077; &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;.
