      <li>
        &#1057;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; 2-&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; (&#1075;&#1076;&#1077; &#1079;&#1085;&#1072;&#1095;. &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072; &#1085;&#1080;&#1078;&#1085;&#1077;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; = 1)<br/><b>11001100=</b>128+64+8+4<b>=204</b>
      </li>
    </ol>
    <p>
      <b>1.1 &#1048;&#1079; &#1076;&#1077;&#1089;&#1103;&#1090;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1074; &#1076;&#1074;&#1086;&#1080;&#1095;&#1085;&#1086;&#1077; &#1087;&#1086; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077; - 204</b>. &#1062;&#1080;&#1089;&#1083;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1088;&#1072;&#1079;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1087;&#1086; &#1103;&#1095;&#1077;&#1081;&#1082;&#1072;&#1084;
