<node TEXT="CSS" FOLDED="true" ID="ID_1249951512" CREATED="1519112080445" MODIFIED="1587570707290"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>CSS (Cascading Stlyle Sheets)</b>&#160;- &#1082;&#1072;&#1089;&#1082;&#1072;&#1076;&#1085;&#1099;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1089;&#1090;&#1080;&#1083;&#1077;&#1081; (&#1076;&#1083;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1075;&#1086; &#1086;&#1092;&#1086;&#1088;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103;). &#1053;&#1072;&#1073;&#1086;&#1088; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081;&#1089;&#1103; &#1074;&#1086; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1084; &#1092;&#1072;&#1081;&#1083;&#1077;.
    </p>
    <ul>
      <li>
        &#1055;&#1088;&#1077;&#1080;&#1084;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; &#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1103;, &#1086;&#1092;&#1086;&#1088;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1075;&#1086; &#1074;&#1080;&#1076;&#1072; &#1074;&#1077;&#1073;-&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;, &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1103;&#1079;&#1099;&#1082;&#1086;&#1074; &#1088;&#1072;&#1079;&#1084;&#1077;&#1090;&#1082;&#1080; HTML &#1080; XHTML, &#1085;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1090;&#1072;&#1082;&#1078;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1082; &#1083;&#1102;&#1073;&#1099;&#1084; XML-&#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;&#1084;
      </li>
      <li>
        &#1085;&#1077; &#1074;&#1086; &#1074;&#1089;&#1077;&#1093; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;&#1093; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;
      </li>
      <li>
        &#1078;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; css &#1074;&#1099;&#1085;&#1086;&#1089;&#1080;&#1090;&#1100; &#1074; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1092;&#1072;&#1081;&#1083;
      </li>
      <li>
        &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1073;&#1083;&#1086;&#1082; &#1089;&#1086;&#1089;&#1090;&#1086;&#1080;&#1090; &#1080;&#1079; &#1089;&#1077;&#1083;&#1077;&#1082;&#1090;&#1086;&#1088;&#1072; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; (&#1089;&#1090;&#1080;&#1083;&#1080;)

        <p>
          <font color="#008000"><b>&#1089;&#1077;&#1083;&#1077;&#1082;&#1090;&#1086;&#1088; { &#1080;&#1084;&#1103;_&#1089;&#1090;&#1080;&#1083;&#1103;1: &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;1, &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;2; ... }</b></font>
        </p>
        <ul>
          <li>
            <b>&#1057;&#1077;&#1083;&#1077;&#1082;&#1090;&#1086;&#1088;</b>&#160;&#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090;, &#1091;&#160;&#1082;&#1072;&#1082;&#1080;&#1093; HTML-&#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &lt;p&gt;) &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;.
          </li>
          <li>
            <b>&#1057;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;, &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; -</b>&#160;&#1079;&#1072;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1092;&#1080;&#1075;&#1091;&#1088;&#1085;&#1099;&#1093; &#1089;&#1082;&#1086;&#1073;&#1086;&#1082;. &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1080; &#1087;&#1086; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102; (&#1096;&#1088;&#1080;&#1092;&#1090;, &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;, &#1094;&#1074;&#1077;&#1090; &#1090;&#1077;&#1082;&#1089;&#1090;&#1072;). &#1050;&#1072;&#1078;&#1076;&#1086;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086; &#1089;&#1086;&#1089;&#1090;&#1086;&#1080;&#1090; &#1080;&#1079; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; (color: black;)
          </li>
        </ul>
      </li>
      <li>
        <font color="#008000">/* &#1050;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1081; */</font>
      </li>
    </ul>
  </body>
