<node TEXT="CSS препроцессоры" ID="ID_1937113047" CREATED="1536430831888" MODIFIED="1587561726765"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>CSS &#1087;&#1088;&#1077;&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088; (CSS preprocessor)</b>&#160; - &#1101;&#1090;&#1086; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1080;&#1084;&#1077;&#1077;&#1090; &#1089;&#1074;&#1086;&#1081; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089; (syntax), &#1085;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1080;&#1079; &#1085;&#1077;&#1075;&#1086; CSS &#1082;&#1086;&#1076; . &#1057;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1088;&#1077;&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1086;&#1074;. &#1041;&#1086;&#1083;&#1100;&#1096;&#1080;&#1085;&#1089;&#1090;&#1074;&#1086; &#1080;&#1079; &#1085;&#1080;&#1093; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1103;&#1077;&#1090; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083; &#1095;&#1080;&#1089;&#1090;&#1086;&#1075;&#1086; CSS, &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1103; &#1090;&#1072;&#1082;&#1080;&#1077; &#1086;&#1087;&#1094;&#1080;&#1080; &#1082;&#1072;&#1082;: &#1087;&#1088;&#1080;&#1084;&#1077;&#1089;&#1080;, &#1074;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1099;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;, &#1089;&#1077;&#1083;&#1077;&#1082;&#1090;&#1086;&#1088;&#1099; &#1085;&#1072;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080; &#1076;&#1088;. &#1069;&#1090;&#1080; &#1086;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080; &#1086;&#1073;&#1083;&#1077;&#1075;&#1095;&#1072;&#1102;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091; &#1089; CSS: &#1091;&#1087;&#1088;&#1086;&#1097;&#1072;&#1102;&#1090; &#1095;&#1090;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1076;&#1072; &#1080; &#1077;&#1075;&#1086; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1081;&#1096;&#1091;&#1102; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1091;.
    </p>
    <p>
      
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; CSS &#1087;&#1088;&#1077;&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1072; &#1085;&#1091;&#1078;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; CSS &#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1103;&#1090;&#1086;&#1088; &#1085;&#1072; &#1074;&#1072;&#1096; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; (server).
    </p>
    <ul>
      <li>
        &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; css &#1082;&#1086;&#1076;&#1072; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;&#1093;
      </li>
      <li>
        ( - ) &#1059;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1080; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1086;&#1076;&#1080;&#1085; &#1080; &#1090;&#1086;&#1090; &#1078;&#1077; &#1087;&#1088;&#1077;&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;
      </li>
      <li>
        ( - ) &#1057;&#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; CSS &#1082;&#1086;&#1076; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1072;, &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;
      </li>
      <li>
        &#1091;&#1089;&#1083;&#1086;&#1078;&#1085;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1075;&#1086; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1088;&#1077;&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1099;</b>
    </p>
    <ul>
      <li>
        Sass (&#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085; &#1085;&#1072; Ruby)
      </li>
      <li>
        Less (&#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085; &#1085;&#1072; JavaScript)
      </li>
      <li>
        stylus (&#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085; &#1085;&#1072; JavaScript)
      </li>
    </ul>
  </body>
</html></richcontent>
