<node TEXT="SaSS" ID="ID_1858098657" CREATED="1519112080446" MODIFIED="1519112080446"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Sass (Syntactically Awesome Stylesheets)</b>&#160;&#8212; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;, &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1074; Haml. Sass &#8212; &#1101;&#1090;&#1086; &#1084;&#1077;&#1090;&#1072;&#1103;&#1079;&#1099;&#1082; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; CSS, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1072;&#1073;&#1089;&#1090;&#1088;&#1072;&#1082;&#1094;&#1080;&#1080; CSS &#1082;&#1086;&#1076;&#1072; &#1080; &#1091;&#1087;&#1088;&#1086;&#1097;&#1077;&#1085;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1082;&#1072;&#1089;&#1082;&#1072;&#1076;&#1085;&#1099;&#1093; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1089;&#1090;&#1080;&#1083;&#1077;&#1081;.
    </p>
    <ul>
      <li>
        &#1071;&#1079;&#1099;&#1082; Sass &#1080;&#1084;&#1077;&#1077;&#1090; &#1076;&#1074;&#1072; &#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;&#1072;:

        <ul>
          <li>
            sass &#8212; &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077;&#1084; &#1092;&#1080;&#1075;&#1091;&#1088;&#1085;&#1099;&#1093; &#1089;&#1082;&#1086;&#1073;&#1086;&#1082;, &#1074; &#1085;&#1105;&#1084; &#1074;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1099;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1099; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1086;&#1090;&#1089;&#1090;&#1091;&#1087;&#1086;&#1074;;
          </li>
          <li>
