      <b>&#1062;&#1074;&#1077;&#1090; &#1090;&#1077;&#1082;&#1089;&#1090;&#1072; </b><font color="#008000">&lt;h1 style=&quot;color:blue;&quot;&gt;This is a heading&lt;/h1&gt; </font>
    </p>
    <p>
      <b>&#1064;&#1088;&#1080;&#1092;&#1090; </b><font color="#008000">&lt;h1 style=&quot;font-family:verdana;&quot;&gt;This is a heading&lt;/h1&gt;</font>
    </p>
    <p>
      <b>&#1056;&#1072;&#1079;&#1084;&#1077;&#1088; &#1090;&#1077;&#1082;&#1089;&#1090;&#1072; </b>
    </p>
    <p>
      <font color="#008000">&lt;h1 style=&quot;font-size:<b>300%</b>;&quot;&gt;This is a heading&lt;/h1&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;p style=&quot;font-size:<b>16px</b>;&quot;&gt;This is a paragraph.&lt;/p&gt; </font>
    </p>
    <p>
      <b>&#1042;&#1099;&#1088;&#1072;&#1074;&#1085;&#1080;&#1074;&#1072;&#1085;&#1080;&#1077; &#1090;&#1077;&#1082;&#1089;&#1090;&#1072; </b><font color="#008000">&lt;h1 style=&quot;text-align:center;&quot;&gt;Centered Heading&lt;/h1&gt;</font>
    </p>
    <p>
      <b>&#1056;&#1072;&#1084;&#1082;&#1072; &#1074;&#1086;&#1082;&#1088;&#1091;&#1075; &#1090;&#1077;&#1082;&#1089;&#1090;&#1072; </b>
    </p>
    <p>
      <font color="#008000">p { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;border: 1px solid powderblue; </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
    <p>
      <b>&#1043;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &#1080; &#1086;&#1090;&#1089;&#1090;&#1091;&#1087;&#1099; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;: margin</b>&#160;(&#1089;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080;)<b>, padding</b>&#160;(&#1074;&#1085;&#1091;&#1090;&#1088;&#1080;)
    </p>
    <p>
      <font color="#008000">p { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;padding: 30px; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;margin: 50px;&#160; </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
    <p>
      
    </p>
    <p>
      --------------------------------------------------------------------
    </p>
    <p>
      <b>width, height</b>&#160;- &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1099; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; (&#1073;&#1083;&#1086;&#1095;&#1085;&#1086;&#1075;&#1086;)
    </p>
    <p>
      <b>display, visibility</b>&#160;- &#1088;&#1077;&#1078;&#1080;&#1084; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;. &#1057;&#1082;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100; &#1080;&#1083;&#1080; &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;
    </p>
    <p>
      <b>top, left, right, bottom</b>&#160;- &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;. &#1057;&#1076;&#1074;&#1080;&#1075; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;
    </p>
  </body>
</html></richcontent>
