    </p>
    <p>
      1. &#1057;&#1087;&#1077;&#1094;&#1080;&#1092;&#1080;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100; - &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1077; &#1073;&#1072;&#1083;&#1083;&#1086;&#1074; &#1074;&#1077;&#1089;&#1072;
    </p>
    <ul>
      <li>
        id - 100 &#1073;&#1072;&#1083;&#1083;&#1086;&#1074;
      </li>
      <li>
        &#1082;&#1083;&#1072;&#1089;&#1089;&#1099; &#1080; &#1087;&#1089;&#1077;&#1074;&#1076;&#1086;&#1082;&#1083;&#1072;&#1089;&#1089;&#1099; - 10 &#1073;&#1072;&#1083;&#1083;&#1086;&#1074;
      </li>
      <li>
        &#1090;&#1101;&#1075;&#1080; &#1080; &#1087;&#1089;&#1077;&#1074;&#1076;&#1086;&#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; - 1 &#1073;&#1072;&#1083;&#1083;
      </li>
      <li>
        ul.info ol+li --&gt; 13 &#1073;&#1072;&#1083;&#1083;&#1086;&#1074;
      </li>
      <li>
        li.red.level --&gt; 21 &#1073;&#1072;&#1083;&#1083;
      </li>
    </ul>
    <p>
      2. &#1042;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089;&#1090;&#1080;&#1083;&#1100;: &#1089;&#1087;&#1077;&#1094;&#1080;&#1092;&#1080;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100; = 1000
    </p>
    <p>
      3. &#1056;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077; &#1074; &#1082;&#1086;&#1076;&#1077;: &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1081; &#1089;&#1090;&#1080;&#1083;&#1100;
    </p>
    <p>
      4. .inone {display: none !important}
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="# Разные стили для абзацев" ID="ID_1893962413" CREATED="1587560769117" MODIFIED="1587575868464"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1429856809">&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; id</a>&#160;&#160;<a href="#ID_501885516">&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; class</a>
    </p>
    <p>
      
    </p>
    <p>
