    </p>
    <ul>
      <li>
        &#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; <b>id</b>&#160;<font color="#ff0000"><b>&#1076;&#1083;&#1103; &#1091;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093;</b></font>, &#1076;&#1083;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; - &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; <b>class</b>
      </li>
    </ul>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; id</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
          <p>
            <font color="#0000c0">vim index.html</font>
          </p>
          <p>
            <font color="#008000">&lt;p <b>id=&quot;mark1&quot;</b>&gt;My second paragraph!&lt;/p&gt; </font>
          </p>
          <p>
            
          </p>
          <p>
            <font color="#0000c0">vim style.css</font>
          </p>
          <p>
            <font color="#008000"><b>#mark1</b>&#160;{ </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;font-size: 18px; </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;font-weight: bold; </font>
          </p>
          <p>
            <font color="#008000">}</font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; class</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
          <p>
            <font color="#0000c0">vim index.html</font>
          </p>
          <p>
            <font color="#008000">&lt;p <b>class=&quot;mark&quot;</b>&gt;My first paragraph!&lt;/p&gt; </font>
          </p>
          <p>
            <font color="#008000">&lt;p&#160;<b>class=&quot;mark&quot;</b>&gt;My second paragraph!&lt;/p&gt; </font>
          </p>
          <p>
            
          </p>
          <p>
            <font color="#0000c0">vim style.css</font>
          </p>
          <p>
            <font color="#008000"><b>.mark</b>&#160;{ </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;font-size: 18px; </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;font-weight: bold; </font>
          </p>
          <p>
            <font color="#008000">}</font>
          </p>
        </td>
      </tr>
    </table>
    <p>
      
    </p>
    <p>
      <b>&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099; class + id</b>
    </p>
    <p>
      <font color="#0000c0">vim index.html</font>
    </p>
    <p>
      <font color="#008000">&lt;p <b>class=&quot;mark&quot; id=&quot;one&quot;</b>&gt;My first paragraph!&lt;/p&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;p <b>class=&quot;mark&quot; id=&quot;two&quot;</b>&gt;My second paragraph!&lt;/p&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">vim style.css</font>
    </p>
    <p>
      <font color="#008000"><b>.mark {</b>font-size: 18px;<b>}</b>&#160;</font>
    </p>
    <p>
      <font color="#008000"><b>#one&#160;{</b>color: red;<b>}</b>&#160;</font>
    </p>
    <p>
      <font color="#008000"><b>#two {</b>color: green;<b>}</b></font>
    </p>
  </body>
</html></richcontent>
</node>
