        padding-left px, in, cm, % &#1047;&#1072;&#1076;&#1072;&#1077;&#1090; &#1086;&#1090;&#1089;&#1090;&#1091;&#1087; &#1084;&#1077;&#1078;&#1076;&#1091; &#1083;&#1077;&#1074;&#1086;&#1081; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1072; &#1080;&#160;&#1077;&#1075;&#1086; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1099;&#1084;
      </li>
      <li>
        padding-right px, in, cm, % &#1047;&#1072;&#1076;&#1072;&#1077;&#1090; &#1086;&#1090;&#1089;&#1090;&#1091;&#1087; &#1084;&#1077;&#1078;&#1076;&#1091; &#1087;&#1088;&#1072;&#1074;&#1086;&#1081; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1072; &#1080;&#160;&#1077;&#1075;&#1086; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1099;&#1084;
      </li>
      <li>
        padding-top px, in, cm, % &#1047;&#1072;&#1076;&#1072;&#1077;&#1090; &#1086;&#1090;&#1089;&#1090;&#1091;&#1087; &#1084;&#1077;&#1078;&#1076;&#1091; &#1074;&#1077;&#1088;&#1093;&#1085;&#1077;&#1081; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1072; &#1080;&#160;&#1077;&#1075;&#1086; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1099;&#1084;
