      <b>&#1055;&#1086;&#1079;&#1080;&#1094;&#1080;&#1086;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; </b>
    </p>
    <ul>
      <li>
        <b>position: static</b>&#160;- &#1086;&#1073;&#1099;&#1095;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        <b>position: relative</b>&#160;- &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1084;&#1077;&#1089;&#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077; (&#1089;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077;)
      </li>
      <li>
        <b>position: absolute</b>&#160;- &#1077;&#1089;&#1083;&#1080; &#1088;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100; relative, absolute &#1080;&#1083;&#1080; fixed - &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1088;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1103;, &#1080;&#1085;&#1072;&#1095;&#1077; - &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072; (&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;)
      </li>
      <li>
        <b>position: fixed</b>&#160;- &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1086;&#1082;&#1085;&#1072; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;
      </li>
      <li>
        <b>top/right/bottom/left</b>&#160;- &#1086;&#1090;&#1089;&#1090;&#1091;&#1087;&#1099;, &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1086;&#1090;&#1088;&#1080;&#1094;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084;&#1080;
      </li>
    </ul>
  </body>
</html></richcontent>
