<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1080;&#1084;&#1074;&#1086;&#1083;-&#1084;&#1085;&#1077;&#1084;&#1086;&#1085;&#1080;&#1082;&#1072;</b>&#160; (entity) &#8212; &#1101;&#1090;&#1086; &#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1103; SGML, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1089;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083; &#1080;&#1079; &#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074; &#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072;. &#1042; HTML &#1087;&#1088;&#1077;&#1076;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1089;&#1087;&#1077;&#1094;&#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1074;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1105;&#1085;&#1085;&#1099;&#1081; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083; &#1074; &#1088;&#1072;&#1079;&#1084;&#1077;&#1090;&#1082;&#1091;, &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1105;&#1085;&#1085;&#1091;&#1102; &#1089;&#1089;&#1099;&#1083;&#1082;&#1091;-&#1084;&#1085;&#1077;&#1084;&#1086;&#1085;&#1080;&#1082;&#1091; &#1074; HTML-&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1091;.
    </p>
    <p>
      
    </p>
    <p>
      1. &#1057;&#1080;&#1084;&#1074;&#1086;&#1083;&#1099;-&#1084;&#1085;&#1077;&#1084;&#1086;&#1085;&#1080;&#1082;&#1080;&#160;&#160;&#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1079;&#1072;&#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1099; &#1074; &#1074;&#1080;&#1076;&#1077; <b>&amp;entity</b>;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;:
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#171;&amp;agrave;&#187; &#8594; &#171;&#224;&#187;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#171;&amp;alpha;&#187; &#8594; &#171;&#945;&#187;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#171;&amp;lt;&#187; &#8594; &#171;&lt;&#187;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#171;&amp;gt;&#187; &#8594; &#171;&gt;&#187;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#171;&amp;nbsp;&#187; &#8594; &#171; &#187; (&#1085;&#1077;&#1088;&#1072;&#1079;&#1088;&#1099;&#1074;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1073;&#1077;&#1083;)
    </p>
    <p>
      
    </p>
    <p>
      2. &#1042;&#1089;&#1077; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1099; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1090;&#1072;&#1082;&#1078;&#1077; &#1079;&#1072;&#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1099; <b>&#1074; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1086;&#1084; &#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1080;</b>&#160;&#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1082;&#1086;&#1076;&#1072; Unicode
    </p>
    <ul>
      <li>
        &#1076;&#1077;&#1089;&#1103;&#1090;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; (&amp;#DD;)
      </li>
      <li>
        &#1096;&#1077;&#1089;&#1090;&#1085;&#1072;&#1076;&#1094;&#1072;&#1090;&#1077;&#1088;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; (&amp;#xHHHH;)
      </li>
    </ul>
    <p>
      &#160;&#160;&#160;&#160;&#171;&amp;#224;&#187; = &#171;&amp;#xE0;&#187; &#8594; &#171;&#224;&#187;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#171;&amp;#945;&#187; = &#171;&amp;#x3B1;&#187; &#8594; &#171;&#945;&#187;
    </p>
  </body>
</html></richcontent>
