<node TEXT="в CSS" ID="ID_678616653" CREATED="1587562807792" MODIFIED="1587562850186"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">vim style.css</font>
    </p>
    <p>
      <font color="#008000">&lt;h1 <b>id=&quot;myHeader&quot;</b>&gt;My Header&lt;/h1&gt;</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">vim style.css</font>
    </p>
    <p>
      <font color="#008000"><b>#myHeader</b>&#160;{ </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;font-size: 18px; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;text-align: center; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;font-weight: bold; </font>
    </p>
    <p>
