    <p>
      <b>spellcheck</b>&#160;&#160;&#1059;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1091; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1090;&#1100; &#1080;&#1083;&#1080; &#1085;&#1077;&#1090; &#1087;&#1088;&#1072;&#1074;&#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1080; &#1075;&#1088;&#1072;&#1084;&#1084;&#1072;&#1090;&#1080;&#1082;&#1091; &#1074; &#1090;&#1077;&#1082;&#1089;&#1090;&#1077;. &#1055;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1084;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;: true/false.
    </p>
    <p>
      <b>style</b>&#160;&#160;&#1059;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1085;&#1072; &#1082;&#1086;&#1076; CSS, &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1084;&#1091;&#1102; &#1076;&#1083;&#1103; &#1086;&#1092;&#1086;&#1088;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;. &#1055;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1084;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;: &#1082;&#1086;&#1076; CSS.
    </p>
    <p>
      <b>tabindex</b>&#160;&#160;&#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1072; &#1082; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1091; &#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1080; TAB.
