    <p>
      <b>xml:lang</b>&#160;&#160;&#1069;&#1090;&#1086;&#1090; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; &#1087;&#1086; &#1089;&#1074;&#1086;&#1077;&#1084;&#1091; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1102; &#1087;&#1086;&#1093;&#1086;&#1078; &#1085;&#1072; lang, &#1085;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; XHTML-&#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;&#1093; &#1080; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1103;&#1079;&#1099;&#1082; &#1074;&#1089;&#1077;&#1075;&#1086; &#1090;&#1077;&#1082;&#1089;&#1090;&#1072; &#1080;&#1083;&#1080; &#1077;&#1075;&#1086; &#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072;.
