    <p>
      <b>&#1058;&#1077;&#1075;&#1080; &#1074;&#1077;&#1088;&#1093;&#1085;&#1077;&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103;. </b>
    </p>
    <ul>
      <li>
        &#1057;&#1086;&#1075;&#1083;&#1072;&#1089;&#1085;&#1086; HTML5 &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100;: &lt;html&gt; (&#1085;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;.), &lt;body&gt; (&#1085;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;.), &#1080; &lt;head&gt;
      </li>
    </ul>
    <p>
      <b><font color="#008000">html</font></b>&#160;- &#1086;&#1073;&#1077;&#1088;&#1090;&#1082;&#1072;. &#1050;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1075;&#1086; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;. &#1054;&#1073;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1074;&#1077;&#1089;&#1100; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;
    </p>
    <p>
      <b><font color="#008000">head</font></b>&#160;- &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1082; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081; &#1074;&#1089;&#1087;&#1086;&#1084;&#1086;&#1075;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1091;&#1102; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102;, &#1080;&#1085;&#1092;. &#1076;&#1083;&#1103; &#1073;&#1086;&#1090;&#1086;&#1074;, &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1089;&#1090;&#1080;&#1083;&#1077;&#1081;, &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074;. &#1053;&#1077; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103;
    </p>
    <ul>
      <li>
        <font color="#008000"><b>&lt;title&gt;</b></font>&#160;- &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1077; &#1086;&#1082;&#1085;&#1072; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;. &#1054;&#1095;&#1077;&#1085;&#1100; &#1074;&#1072;&#1078;&#1077;&#1085; &#1076;&#1083;&#1103; &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;. &lt;title&gt;&#160;&#160;&#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1090;&#1077;&#1082;&#1089;&#1090;&#1072; &#1074; &#1083;&#1077;&#1074;&#1086;&#1084; &#1074;&#1077;&#1088;&#1093;&#1085;&#1077;&#1084; &#1091;&#1075;&#1083;&#1091; &#1086;&#1082;&#1085;&#1072; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1085;&#1072; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1077;. &#1058;&#1072;&#1082;&#1072;&#1103; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072; &#1089;&#1086;&#1086;&#1073;&#1097;&#1072;&#1077;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1072;&#1081;&#1090;&#1072; &#1080; &#1076;&#1088;&#1091;&#1075;&#1091;&#1102; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1095;&#1080;&#1082;.
      </li>
      <li>
        <font color="#008000"><b>&lt;meta&gt;</b></font>&#160;- &#1080;&#1085;&#1092;. &#1076;&#1083;&#1103; user-agent-&#1086;&#1074; (&#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1099;, &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1099;&#1077; &#1073;&#1086;&#1090;&#1099;). &lt;meta&gt;&#160;&#160;&#1052;&#1077;&#1090;&#1072;&#1090;&#1077;&#1075;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1086;&#1081; &#1076;&#1083;&#1103; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1074; &#1080; &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;
      </li>
      <li>
        <font color="#008000"><b>&lt;link rel=&quot;stylesheet&quot; href=&quot;./style.css&quot;&gt;</b></font>&#160;- &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1076;&#1086;&#1087;. &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1074;. CSS. &#1058;&#1072;&#1082;&#1078;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; Favicon (Favicon (FAVorite ICON &#8212; &#171;&#1079;&#1085;&#1072;&#1095;&#1086;&#1082; &#1076;&#1083;&#1103; &#1080;&#1079;&#1073;&#1088;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086;&#187;) &#8212; &#1079;&#1085;&#1072;&#1095;&#1086;&#1082; &#1074;&#1077;&#1073;-&#1089;&#1072;&#1081;&#1090;&#1072; &#1080;&#1083;&#1080; &#1074;&#1077;&#1073;-&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;. &#1054;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1084; &#1074;&#1086; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1077; &#1087;&#1077;&#1088;&#1077;&#1076; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1082;&#1072;&#1088;&#1090;&#1080;&#1085;&#1082;&#1080; &#1088;&#1103;&#1076;&#1086;&#1084; &#1089; &#1079;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1086;&#1081;, &#1074;&#1086; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1072;&#1093; &#1080; &#1074; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;&#1093; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;.)
      </li>
      <li>
        <font color="#008000"><b>&lt;script src=&quot;./jquery.js&quot;&gt;&lt;/script&gt;</b></font>&#160;- &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074;&#160;<a href="#ID_794988334">JavaScript</a>, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1082;&#1091; (charset), &#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; &#1073;&#1099;&#1083; &#1074; &#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1082;&#1077;, &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; - &#1074; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081;
      </li>
      <li>
        <font color="#008000"><b>&lt;base&gt;</b></font>&#160;&#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1086;&#1083;&#1085;&#1086;&#1075;&#1086; &#1073;&#1072;&#1079;&#1086;&#1074;&#1086;&#1075;&#1086; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;. &#1058;&#1077;&#1075; &lt;base&gt; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085; &#1076;&#1083;&#1103; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1072;&#1076;&#1088;&#1077;&#1089;. &#1042;&#1090;&#1086;&#1088;&#1086;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1090;&#1077;&#1075;&#1072; &lt;base&gt; &#8212; &#1079;&#1072;&#1076;&#1072;&#1085;&#1080;&#1077; &#1094;&#1077;&#1083;&#1077;&#1074;&#1086;&#1075;&#1086; &#1086;&#1082;&#1085;&#1072; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1089;&#1089;&#1099;&#1083;&#1086;&#1082; &#1085;&#1072; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1081; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;.
      </li>
      <li>
        <b><font color="#008000">&lt;style&gt;</font></b>&#160;(&#1089;&#1084;. <a href="#ID_1458782307">&#1057;&#1090;&#1080;&#1083;&#1080;</a>) -&#160;&#160;&#1076;&#1083;&#1103; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1080;&#1085;&#1092;. &#1086; &#1089;&#1090;&#1080;&#1083;&#1077; &#1076;&#1083;&#1103; &#1086;&#1076;&#1085;&#1086;&#1081; HTML-&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;<br/><font color="#008000">&lt;style&gt;<br color="#008000"/>&#160;&#160;&#160;body {background-color: powderblue;}<br color="#008000"/>&#160;&#160;&#160;h1 {color: red;}<br color="#008000"/>&#160;&#160;&#160;p {color: blue;}<br color="#008000"/>&#160;&lt;/style&gt;</font>
      </li>
    </ul>
    <p>
      <b><font color="#008000">body</font></b>&#160;- &#1090;&#1077;&#1083;&#1086; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;. &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1074;&#1080;&#1076;&#1080;&#1084;&#1091;&#1102; &#1095;&#1072;&#1089;&#1090;&#1100; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;
    </p>
  </body>
</html></richcontent>
<node TEXT="&lt;head&gt;" ID="ID_1819997998" CREATED="1546102825084" MODIFIED="1587120245513"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&lt;head&gt;</b>. &#1053;&#1077; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1086;&#1082;&#1085;&#1077; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;, &#1079;&#1072; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1090;&#1077;&#1075;&#1072; <b>&lt;title&gt;</b>, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1074;&#1077;&#1073;-&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;!DOCTYPE html&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;html&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;head&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;<b>&lt;title&gt;</b>&#1042;&#1099;&#1074;&#1086;&#1076; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074;&#1086; &#1074;&#1082;&#1083;&#1072;&#1076;&#1082;&#1077;<b>&lt;/title&gt;</b></font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;<b>&lt;meta</b>&#160;charset=&quot;UTF-8&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;/head&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;body&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;p&gt;The HTML head element contains meta data.&lt;/p&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;p&gt;Meta data is data about the HTML document.&lt;/p&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;/body&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/html&gt;</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="&lt;meta&gt;" ID="ID_1467006965" CREATED="1548500500006" MODIFIED="1587120618740"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>&lt;meta&gt;</b></font>&#160;- &#1080;&#1085;&#1092;. &#1076;&#1083;&#1103; user-agent-&#1086;&#1074; (&#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1099;, &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1099;&#1077; &#1073;&#1086;&#1090;&#1099;). &lt;meta&gt;&#160;&#160;&#1052;&#1077;&#1090;&#1072;&#1090;&#1077;&#1075;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1086;&#1081; &#1076;&#1083;&#1103; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1074; &#1080; &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084;&#1099; &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1102;&#1090;&#1089;&#1103; &#1082; &#1084;&#1077;&#1090;&#1072;&#1090;&#1077;&#1075;&#1072;&#1084; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1103; &#1089;&#1072;&#1081;&#1090;&#1072;, &#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1099;&#1093; &#1089;&#1083;&#1086;&#1074; &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;. &#1061;&#1086;&#1090;&#1103; &#1090;&#1077;&#1075; &lt;meta&gt; &#1074;&#1089;&#1077;&#1075;&#1086; &#1086;&#1076;&#1080;&#1085;, &#1086;&#1085; &#1080;&#1084;&#1077;&#1077;&#1090; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1086;&#1074;, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1082; &#1085;&#1077;&#1084;&#1091; &#1080; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086;
    </p>
    <ul>
      <li>
        <font color="#008000">&lt;meta charset=&quot;UTF-8&quot;&gt;</font>&#160;- &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1085;&#1072;&#1073;&#1086;&#1088; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074;
      </li>
      <li>
        <font color="#008000"><b>&lt;meta name=&quot;description&quot; content=&quot;&#1057;&#1072;&#1081;&#1090; &#1086;&#1073; HTML &#1080; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1080; &#1089;&#1072;&#1081;&#1090;&#1086;&#1074;&quot;&gt;</b></font>&#160; - &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1082;&#1088;&#1072;&#1090;&#1082;&#1086;&#1077; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;. &#1054;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1085;&#1077; &#1074;&#1080;&#1076;&#1085;&#1086; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077;, &#1085;&#1086; &#1077;&#1075;&#1086; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090; &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1072;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;
      </li>
      <li>
        <font color="#008000">&lt;meta name=&quot;keywords&quot; content=&quot;HTML, CSS, XML, JavaScript&quot;&gt;</font>&#160;- &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1099;&#1077; &#1089;&#1083;&#1086;&#1074;&#1072; &#1076;&#1083;&#1103; &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;
      </li>
      <li>
        <font color="#008000">&lt;meta name=&quot;author&quot; content=&quot;John Doe&quot;&gt;</font>&#160;- &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1072;&#1074;&#1090;&#1086;&#1088;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;
      </li>
      <li>
        <font color="#008000">&lt;meta http-equiv&gt;=&quot;Content-Type&quot; content=&quot;text/html; charset=utf-8&quot;&gt;</font>&#160;- &#1087;&#1077;&#1088;&#1077;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1088;&#1080;&#1096;&#1083;&#1080; &#1086;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
      </li>
      <li>
        <font color="#008000">&lt;meta http-equiv=&quot;refresh&quot; content=&quot;30&quot;&gt;</font>&#160;- &#1054;&#1073;&#1085;&#1086;&#1074;&#1083;&#1103;&#1090;&#1100; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090; &#1082;&#1072;&#1078;&#1076;&#1099;&#1077; 30 &#1089;&#1077;&#1082;.
      </li>
      <li>
        <font color="#008000">&lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;</font>&#160;- HTML5, &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1101;&#1082;&#1088;&#1072;&#1085;&#1086;&#1084;, &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;. <b>width=device-width</b>&#160; &#1079;&#1072;&#1076;&#1072;&#1077;&#1090; &#1096;&#1080;&#1088;&#1080;&#1085;&#1091; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1100; &#1079;&#1072; &#1096;&#1080;&#1088;&#1080;&#1085;&#1086;&#1081; &#1101;&#1082;&#1088;&#1072;&#1085;&#1072; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; (&#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;). <b>initial-scale=1.0</b>&#160; &#1079;&#1072;&#1076;&#1072;&#1077;&#1090; &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1084;&#1072;&#1089;&#1096;&#1090;&#1072;&#1073;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1084;. (&#1089;&#1084;. <a href="#ID_1705055492">Responsive Web Design</a>)
      </li>
    </ul>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
</node>
<node TEXT="Верстка" ID="ID_775564757" CREATED="1548504047042" MODIFIED="1551101234443"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>HTML Layout (HTML5) </b>
    </p>
    <p>
      
    </p>
    <p>
      Semantic Elements&#160;&#160;&#160;&#160;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&lt;header&gt; - Defines a header for a document or a section
    </p>
    <p>
      &#160;&#160;&#160;&#160;&lt;nav&gt; - Defines a container for navigation links
    </p>
    <p>
      &#160;&#160;&#160;&#160;&lt;section&gt; - Defines a section in a document
    </p>
    <p>
      &#160;&#160;&#160;&#160;&lt;article&gt; - Defines an independent self-contained article
    </p>
    <p>
      &#160;&#160;&#160;&#160;&lt;aside&gt; - Defines content aside from the content (like a sidebar)
    </p>
    <p>
      &#160;&#160;&#160;&#160;&lt;footer&gt; - Defines a footer for a document or a section
    </p>
    <p>
      &#160;&#160;&#160;&#160;&lt;details&gt; - Defines additional details
    </p>
    <p>
      &#160;&#160;&#160;&#160;&lt;summary&gt; - Defines a heading for the &lt;details&gt; element
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;!DOCTYPE html&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;html lang=&quot;en&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;head&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;title&gt;CSS Template&lt;/title&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;meta charset=&quot;utf-8&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;style&gt; </font>
    </p>
    <p>
      <font color="#008000">* { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;box-sizing: border-box; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">body { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;font-family: Arial, Helvetica, sans-serif; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">/* Style the header */ </font>
    </p>
    <p>
      <font color="#008000">header { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;background-color: #666; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;padding: 30px; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;text-align: center; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;font-size: 35px; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;color: white; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">/* Create two columns/boxes that floats next to each other */ </font>
    </p>
    <p>
      <font color="#008000">nav { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;float: left; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;width: 30%; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;height: 300px; /* only for demonstration, should be removed */ </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;background: #ccc; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;padding: 20px; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">/* Style the list inside the menu */ </font>
    </p>
    <p>
      <font color="#008000">nav ul { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;list-style-type: none; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;padding: 0; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">article { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;float: left; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;padding: 20px; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;width: 70%; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;background-color: #f1f1f1; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;height: 300px; /* only for demonstration, should be removed */ </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">/* Clear floats after the columns */ </font>
    </p>
    <p>
      <font color="#008000">section:after { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;content: &quot;&quot;; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;display: table; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;clear: both; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">/* Style the footer */ </font>
    </p>
    <p>
      <font color="#008000">footer { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;background-color: #777; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;padding: 10px; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;text-align: center; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;color: white; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">/* Responsive layout - makes the two columns/boxes stack on top of each other instead of next to each other, on small screens */ </font>
    </p>
    <p>
      <font color="#008000">@media (max-width: 600px) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;nav, article { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;width: 100%; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;height: auto; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;} </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      <font color="#008000">&lt;/style&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/head&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;body&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;h2&gt;CSS Layout Float&lt;/h2&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;p&gt;In this example, we have created a header, two columns/boxes and a footer. On smaller screens, the columns will stack on top of each other.&lt;/p&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;p&gt;Resize the browser window to see the responsive effect (you will learn more about this in our next chapter - HTML Responsive.)&lt;/p&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;header&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;h2&gt;Cities&lt;/h2&gt; </font>
    </p>
    <p>
