<node TEXT="Цитирование" ID="ID_1889741293" CREATED="1548396021710" MODIFIED="1549014757474"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1058;&#1077;&#1075; &lt;q&gt;</b>&#160;&#1076;&#1083;&#1103; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1074; &#1090;&#1077;&#1082;&#1089;&#1090;&#1077; &#1094;&#1080;&#1090;&#1072;&#1090;. &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1072; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077; &#1074; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1072;&#1093;
    </p>
    <p>
      <font color="#008000">&lt;p&gt;&#1058;&#1077;&#1082;&#1089;&#1090; &lt;q&gt;&#1058;&#1077;&#1082;&#1089;&#1090; &#1074; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1072;&#1093;&lt;/q&gt;&lt;/p&gt;</font>&#160; &#160;# &#1058;&#1077;&#1082;&#1089;&#1090; <b>&quot;&#1058;&#1077;&#1082;&#1089;&#1090; &#1074; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1072;&#1093;&quot;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1058;&#1077;&#1075; &lt;blockquote&gt;</b>&#160;-&#160;&#160;&#1076;&#1083;&#1103; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; <b>&#1076;&#1083;&#1080;&#1085;&#1085;&#1099;&#1093; &#1094;&#1080;&#1090;&#1072;&#1090;</b>&#160;&#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;. &#1058;&#1077;&#1082;&#1089;&#1090;, &#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1101;&#1090;&#1080;&#1084; &#1090;&#1077;&#1075;&#1086;&#1084;, &#1090;&#1088;&#1072;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; &#1074;&#1099;&#1088;&#1086;&#1074;&#1085;&#1077;&#1085;&#1085;&#1099;&#1081; &#1073;&#1083;&#1086;&#1082; &#1089; &#1086;&#1090;&#1089;&#1090;&#1091;&#1087;&#1072;&#1084;&#1080; &#1089;&#1083;&#1077;&#1074;&#1072; &#1080; &#1089;&#1087;&#1088;&#1072;&#1074;&#1072; (&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; &#1087;&#1086; 40 &#1087;&#1080;&#1082;&#1089;&#1077;&#1083;&#1086;&#1074;), &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1089; &#1086;&#1090;&#1073;&#1080;&#1074;&#1082;&#1086;&#1081; &#1089;&#1074;&#1077;&#1088;&#1093;&#1091; &#1080; &#1089;&#1085;&#1080;&#1079;&#1091;. &#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099; cite - &#1072;&#1076;&#1088;&#1077;&#1089;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1085;&#1072; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082; &#1094;&#1080;&#1090;&#1072;&#1090;&#1099;
    </p>
    <p>
      <font color="#008000">&lt;blockquote cite=&quot;URL&quot;&gt;&#1058;&#1077;&#1082;&#1089;&#1090;&lt;/blockquote&gt;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1058;&#1077;&#1075; &lt;abbr&gt;</b>&#160;&#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; <b>&#1072;&#1073;&#1073;&#1088;&#1077;&#1074;&#1080;&#1072;&#1090;&#1091;&#1088;&#1086;&#1081;</b>. &#1057; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1072; <b>title</b>&#160; &#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1072;&#1089;&#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1082;&#1072; &#1089;&#1086;&#1082;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1086;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1072;&#1073;&#1073;&#1088;&#1077;&#1074;&#1080;&#1072;&#1090;&#1091;&#1088;&#1091; &#1090;&#1077;&#1084; &#1083;&#1102;&#1076;&#1103;&#1084;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1089; &#1085;&#1077;&#1081; &#1085;&#1077; &#1079;&#1085;&#1072;&#1082;&#1086;&#1084;&#1099;. &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1099;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1080;&#1088;&#1091;&#1102;&#1090; &#1087;&#1086;&#1083;&#1085;&#1086;&#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1099;&#1081; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090; &#1089;&#1086;&#1082;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1095;&#1090;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1083;&#1103; &#1087;&#1086;&#1074;&#1099;&#1096;&#1077;&#1085;&#1080;&#1103; &#1088;&#1077;&#1081;&#1090;&#1080;&#1085;&#1075;&#1072; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;.
    </p>
    <p>
      <font color="#008000">&lt;p&gt;The &lt;<b>abbr</b>&#160;title=&quot;World Health Organization&quot;&gt;WHO&lt;/abbr&gt; was founded in 1948.&lt;/p&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1058;&#1077;&#1075; &lt;address&gt;</b>&#160;&#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1086;&#1073; &#1072;&#1074;&#1090;&#1086;&#1088;&#1077; &#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1074; &#1089;&#1077;&#1073;&#1103; &#1083;&#1102;&#1073;&#1099;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; HTML &#1074;&#1088;&#1086;&#1076;&#1077; &#1089;&#1089;&#1099;&#1083;&#1086;&#1082;, &#1090;&#1077;&#1082;&#1089;&#1090;&#1072;, &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1081; &#1080; &#1090;.&#1076;. &#1055;&#1083;&#1072;&#1085;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1099;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1073;&#1091;&#1076;&#1091;&#1090; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086; &#1090;&#1077;&#1075;&#1072; &#1076;&#1083;&#1103; &#1089;&#1073;&#1086;&#1088;&#1072; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1086;&#1073; &#1072;&#1074;&#1090;&#1086;&#1088;&#1072;&#1093; &#1089;&#1072;&#1081;&#1090;&#1086;&#1074;.
    </p>
    <p>
