    </p>
    <p>
      
    </p>
    <p>
      <b>&#1058;&#1077;&#1075; &lt;button&gt;</b>&#160;&#160;- &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090; &#1085;&#1072; &#1074;&#1077;&#1073;-&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080;
    </p>
    <ul>
      <li>
        &#1085;&#1072;&#1087;&#1086;&#1084;&#1080;&#1085;&#1072;&#1077;&#1090; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084;&#1099;&#1081; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1090;&#1077;&#1075;&#1072; <b>&lt;input&gt;</b>&#160;(&#1089; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1086;&#1084; type=&quot;button | reset | submit&quot;). &#1042; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; &#1101;&#1090;&#1086;&#1075;&#1086; &#1090;&#1077;&#1075;&#1072;, &lt;button&gt; &#1087;&#1088;&#1077;&#1076;&#1083;&#1072;&#1075;&#1072;&#1077;&#1090; <b>&#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080;</b>&#160;&#1087;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1102; &#1082;&#1085;&#1086;&#1087;&#1086;&#1082;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1085;&#1072; &#1087;&#1086;&#1076;&#1086;&#1073;&#1085;&#1086;&#1081; &#1082;&#1085;&#1086;&#1087;&#1082;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1072;&#1090;&#1100; &#1083;&#1102;&#1073;&#1099;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; HTML, &#1074; &#1090;&#1086;&#1084; &#1095;&#1080;&#1089;&#1083;&#1077; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; &#1089;&#1090;&#1080;&#1083;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1074;&#1080;&#1076; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080; &#1087;&#1091;&#1090;&#1077;&#1084; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1096;&#1088;&#1080;&#1092;&#1090;&#1072;, &#1094;&#1074;&#1077;&#1090;&#1072; &#1092;&#1086;&#1085;&#1072;, &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1086;&#1074; &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;
      </li>
    </ul>
    <p>
      <font color="#008000"><b>&lt;button &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099;&gt;</b>&#1053;&#1072;&#1076;&#1087;&#1080;&#1089;&#1100; &#1085;&#1072; &#1082;&#1085;&#1086;&#1087;&#1082;&#1077;<b>&lt;/button&gt; </b></font>
    </p>
    <p>
      <font color="#008000"><b>&lt;button type=&quot;button&quot; onclick=&quot;alert('Hello World!')&quot;&gt;</b>Click Me!<b>&lt;/button&gt;</b></font>
    </p>
    <p>
      
    </p>
    <p style="text-align: left">
      <b><u>&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099;</u></b>
    </p>
    <p>
      <b>accesskey</b>&#160;- &#1044;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;&#1084; &#1092;&#1086;&#1088;&#1084;&#1099; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1075;&#1086;&#1088;&#1103;&#1095;&#1080;&#1093; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;.
    </p>
    <p>
      <b>autofocus</b>&#160;- &#1059;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1082;&#1085;&#1086;&#1087;&#1082;&#1072; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; &#1092;&#1086;&#1082;&#1091;&#1089; &#1087;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;.
    </p>
    <p>
      <b>disabled</b>&#160;- &#1041;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1080; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;.
    </p>
    <p>
      <b>form</b>&#160;- &#1057;&#1074;&#1103;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1086;&#1073;&#1086;&#1081; &#1092;&#1086;&#1088;&#1084;&#1091; &#1080; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091;.
    </p>
    <p>
      <b>formaction</b>&#160;- &#1047;&#1072;&#1076;&#1072;&#1105;&#1090; &#1072;&#1076;&#1088;&#1077;&#1089;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1077;&#1088;&#1077;&#1089;&#1099;&#1083;&#1072;&#1102;&#1090;&#1089;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1092;&#1086;&#1088;&#1084;&#1099; &#1087;&#1088;&#1080; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1080; &#1085;&#1072; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091;.
    </p>
    <p>
      <b>formenctype</b>&#160;- &#1057;&#1087;&#1086;&#1089;&#1086;&#1073; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1092;&#1086;&#1088;&#1084;&#1099;.
    </p>
    <p>
      <b>formmethod</b>&#160;- &#1059;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1084;&#1077;&#1090;&#1086;&#1076; &#1087;&#1077;&#1088;&#1077;&#1089;&#1099;&#1083;&#1082;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1092;&#1086;&#1088;&#1084;&#1099;.
    </p>
    <p>
      <b>formnovalidate</b>&#160;- &#1054;&#1090;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1091; &#1092;&#1086;&#1088;&#1084;&#1099; &#1085;&#1072; &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1085;&#1086;&#1089;&#1090;&#1100;.
    </p>
    <p>
      <b>formtarget</b>&#160;- &#1054;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1092;&#1086;&#1088;&#1084;&#1099; &#1074; &#1085;&#1086;&#1074;&#1086;&#1084; &#1086;&#1082;&#1085;&#1077; &#1080;&#1083;&#1080; &#1092;&#1088;&#1077;&#1081;&#1084;&#1077;.
    </p>
    <p>
      <b>name</b>&#160;- &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1091;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080;.
    </p>
    <p>
      <b>type</b>&#160;- &#1058;&#1080;&#1087; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080; &#8212; &#1086;&#1073;&#1099;&#1095;&#1085;&#1072;&#1103;, &#1076;&#1083;&#1103; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1092;&#1086;&#1088;&#1084;&#1099; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080;&#1083;&#1080; &#1076;&#1083;&#1103; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080; &#1092;&#1086;&#1088;&#1084;&#1099;.
    </p>
    <p>
      <b>value</b>&#160;- &#1047;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1086; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080;&#1083;&#1080; &#1087;&#1088;&#1086;&#1095;&#1080;&#1090;&#1072;&#1085;&#1086; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074;.
    </p>
  </body>
