    <p>
      
    </p>
    <p>
      <b>&#1042;&#1077;&#1073;-&#1092;&#1086;&#1088;&#1084;&#1072;</b>&#160;(web-form, web-&#1092;&#1086;&#1088;&#1084;&#1072;) - <b>&#1058;&#1077;&#1075; &lt;form&gt;</b>&#160; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1092;&#1086;&#1088;&#1084;&#1091; &#1085;&#1072; &#1074;&#1077;&#1073;-&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;. &#1060;&#1086;&#1088;&#1084;&#1072; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1072; &#1076;&#1083;&#1103; &#1086;&#1073;&#1084;&#1077;&#1085;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; &#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084;.
    </p>
    <ul>
      <li>
        &#1044;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1083;&#1102;&#1073;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1092;&#1086;&#1088;&#1084;, &#1085;&#1086; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1072; <b>&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1085;&#1072; &#1092;&#1086;&#1088;&#1084;&#1072;</b>
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1092;&#1086;&#1088;&#1084;&#1099; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082;&#1085;&#1086;&#1087;&#1082;&#1072; <b>Submit</b>, &#1090;&#1086;&#1075;&#1086; &#1078;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1076;&#1086;&#1073;&#1080;&#1090;&#1100;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1085;&#1072;&#1078;&#1072;&#1090;&#1100; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1091; <b>Enter</b>&#160;&#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1092;&#1086;&#1088;&#1084;&#1099;. &#1045;&#1089;&#1083;&#1080; &#1082;&#1085;&#1086;&#1087;&#1082;&#1072; Submit &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1074; &#1092;&#1086;&#1088;&#1084;&#1077;, &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1072; Enter &#1080;&#1084;&#1080;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1077;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;.
      </li>
    </ul>
    <p>
      <b>&#1063;&#1072;&#1089;&#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1077; html-&#1092;&#1086;&#1088;&#1084;&#1099;</b>:
    </p>
    <ul>
      <li>
        &#1060;&#1086;&#1088;&#1084;&#1072; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1081; &#1089;&#1074;&#1103;&#1079;&#1080;
      </li>
      <li>
