    <p>
      <b>height and width</b>&#160;- &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090; &#1074;&#1099;&#1089;&#1086;&#1090;&#1091; &#1080; &#1096;&#1080;&#1088;&#1080;&#1085;&#1091; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &lt;input type=&quot;image&quot;&gt;. &#1042;&#1089;&#1077;&#1075;&#1076;&#1072; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1081;&#1090;&#1077; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1081;. &#1045;&#1089;&#1083;&#1080; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1085;&#1077; &#1079;&#1085;&#1072;&#1077;&#1090; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;, &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1084;&#1077;&#1088;&#1094;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1081;.
    </p>
    <p>
      <font color="#008000">&lt;input type=&quot;image&quot; src=&quot;img_submit.gif&quot; alt=&quot;Submit&quot; width=&quot;48&quot; height=&quot;48&quot;&gt; </font>
    </p>
    <p>
      <b>list</b>&#160;- &#1089;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &lt;datalist&gt;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081; &#1087;&#1088;&#1077;&#1076;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1076;&#1083;&#1103; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &lt;input&gt;.
    </p>
    <p>
      <font color="#008000">&lt;input <b>list=</b>&quot;browsers&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;datalist id=&quot;browsers&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;option value=&quot;Internet Explorer&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;option value=&quot;Firefox&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;option value=&quot;Chrome&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;option value=&quot;Opera&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;option value=&quot;Safari&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/datalist&gt; </font>
    </p>
    <p>
      <b>min and max</b>&#160;- &#1079;&#1072;&#1076;&#1072;&#1102;&#1090; &#1084;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1080; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1076;&#1083;&#1103; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &lt;input&gt;. &#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099; min &#1080; max &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1089;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084;&#1080; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1074;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;: number, range, date, datetime-local, month, time &#1080; week.
    </p>
    <p>
      <font color="#008000">Enter a date before 1980-01-01: </font>
    </p>
    <p>
      <font color="#008000">&lt;input type=&quot;date&quot; name=&quot;bday&quot; <b>max=</b>&quot;1979-12-31&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">Enter a date after 2000-01-01: </font>
    </p>
    <p>
      <font color="#008000">&lt;input type=&quot;date&quot; name=&quot;bday&quot; <b>min=</b>&quot;2000-01-02&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">Quantity (between 1 and 5): </font>
    </p>
    <p>
      <font color="#008000">&lt;input type=&quot;number&quot; name=&quot;quantity&quot; <b>min=</b>&quot;1&quot; <b>max=</b>&quot;5&quot;&gt;</font>
    </p>
    <p>
      <b>multiple</b>&#160;- &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1086; &#1074;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1073;&#1086;&#1083;&#1077;&#1077; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1077; &lt;input&gt;.
    </p>
    <p>
      &#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084;&#1080; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1074;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;: email &#1080; file.
    </p>
    <p>
      <font color="#008000">Select images: &lt;input type=&quot;file&quot; name=&quot;img&quot; multiple&gt;</font>
    </p>
    <p>
      <b>pattern (regexp)</b>&#160;- &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1088;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1086;&#1077; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;, &#1076;&#1083;&#1103; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090;&#1089;&#1103; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &lt;input&gt;.
    </p>
    <p>
      &#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084;&#1080; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1074;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;: text, search, url, tel, email &#1080; password. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1081;&#1090;&#1077; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; title &#1076;&#1083;&#1103; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1103; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1072;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1084;&#1086;&#1095;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102;.
    </p>
    <p>
      <font color="#008000">Country code: &lt;input type=&quot;text&quot; name=&quot;country_code&quot; <b>pattern=</b>&quot;[A-Za-z]{3}&quot; title=&quot;Three letter country code&quot;&gt;</font>
    </p>
    <p>
      <b>placeholder</b>&#160;- &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1087;&#1086;&#1076;&#1089;&#1082;&#1072;&#1079;&#1082;&#1091;, &#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1102;&#1097;&#1091;&#1102; &#1086;&#1078;&#1080;&#1076;&#1072;&#1077;&#1084;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1083;&#1103; &#1074;&#1074;&#1086;&#1076;&#1072; (&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1080;&#1083;&#1080; &#1082;&#1088;&#1072;&#1090;&#1082;&#1086;&#1077; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1072;). &#1055;&#1086;&#1076;&#1089;&#1082;&#1072;&#1079;&#1082;&#1072; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1087;&#1086;&#1083;&#1077; &#1074;&#1074;&#1086;&#1076;&#1072; &#1087;&#1077;&#1088;&#1077;&#1076; &#1074;&#1074;&#1086;&#1076;&#1086;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;. &#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;-&#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084;&#1080; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1074;&#1074;&#1086;&#1076;&#1072;: text, search, url, tel, email, &#1080; password
    </p>
    <p>
      <font color="#008000">&lt;input type=&quot;text&quot; name=&quot;fname&quot; <b>placeholder=</b>&quot;First name&quot;&gt;</font>
    </p>
    <p>
      <b>required</b>&#160;- &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1083;&#1077; &#1074;&#1074;&#1086;&#1076;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1099; &#1087;&#1077;&#1088;&#1077;&#1076; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1086;&#1081; &#1092;&#1086;&#1088;&#1084;&#1099;. &#1054;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084;&#1080; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1074;&#1074;&#1086;&#1076;&#1072;: text, search, url, tel, email, password, date pickers, number, checkbox, radio, &#1080; file.
    </p>
    <p>
      <font color="#008000">Username: &lt;input type=&quot;text&quot; name=&quot;usrname&quot; required&gt;</font>
    </p>
    <p>
      step - &#1079;&#1072;&#1076;&#1072;&#1077;&#1090; &#1076;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1084;&#1099;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083;&#1099; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1074; &#1076;&#1083;&#1103; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &lt;input&gt;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;: &#1077;&#1089;&#1083;&#1080; Step=&quot;3&quot;, &#1095;&#1080;&#1089;&#1083;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; -3, 0, 3, 6, &#1080; &#1090;. &#1076;. &#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; step &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074;&#1084;&#1077;&#1089;&#1090;&#1077; &#1089; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1072;&#1084;&#1080; max &#1080; min &#1076;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1072; &#1076;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1084;&#1099;&#1093; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;. &#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; step &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1089;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084;&#1080; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1074;&#1093;&#1086;&#1076;&#1085;&#1099;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;: number, range, date, datetime-local, month, time &#1080; week.
    </p>
    <p>
      <font color="#008000">&lt;input type=&quot;number&quot; name=&quot;points&quot; <b>step=</b>&quot;3&quot;&gt;</font>
    </p>
  </body>
</html></richcontent>
