<node TEXT="Переключатель зависимый (type=&quot;radio&quot;)" ID="ID_1680411605" CREATED="1549183460567" MODIFIED="1549484748571"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Radio, &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1077;&#1083;&#1080; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1099;&#1077;, &#1088;&#1072;&#1076;&#1080;&#1086;&#1082;&#1085;&#1086;&#1087;&#1082;&#1080; -</b>&#160; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1086;&#1076;&#1080;&#1085; &#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1081; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090; &#1080;&#1079; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1087;&#1088;&#1077;&#1076;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1099;&#1093;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;</b>
    </p>
    <p>
      <font color="#008000">&lt;input type=&quot;radio&quot; name=&quot;&#1080;&#1084;&#1103;&quot; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099;&gt; </font>
