    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;form&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160; <b>&lt;input type=&quot;radio&quot;</b>&#160;name=&quot;gender&quot; value=&quot;male&quot; <b>checked</b>&gt; Male&lt;br&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160; <b>&lt;input type=&quot;radio&quot;</b>&#160;name=&quot;gender&quot; value=&quot;female&quot;&gt; Female&lt;br&gt; </font>
