<node TEXT="&lt;output&gt;" ID="ID_800767819" CREATED="1549191295745" MODIFIED="1549191415525"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1100; &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103;, &#1087;&#1088;&#1077;&#1080;&#1084;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074;.
    </p>
    <ul>
      <li>
        HTML5
      </li>
    </ul>
    <p>
      <font color="#008000">&lt;form action=&quot;/action_page.php&quot; </font>
    </p>
    <p>
      <font color="#008000"><b>oninput=&quot;x.value=parseInt(a.value)+parseInt(b.value)&quot;&gt;</b>&#160; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;0 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;input type=&quot;range&quot; id=&quot;a&quot; name=&quot;a&quot; value=&quot;50&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;100 + </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;input type=&quot;number&quot; id=&quot;b&quot; name=&quot;b&quot; value=&quot;50&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;= </font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&lt;output name=&quot;x&quot; for=&quot;a b&quot;&gt;&lt;/output&gt;</b>&#160; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;br&gt;&lt;br&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;input type=&quot;submit&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/form&gt;</font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099;</b>
