      cols - &#1064;&#1080;&#1088;&#1080;&#1085;&#1072; &#1087;&#1086;&#1083;&#1103; &#1074; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072;&#1093;.
    </p>
    <p>
      disabled - &#1041;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1080; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;.
    </p>
    <p>
      form - &#1057;&#1074;&#1103;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1086;&#1077; &#1087;&#1086;&#1083;&#1077; &#1089; &#1092;&#1086;&#1088;&#1084;&#1086;&#1081; &#1087;&#1086; &#1077;&#1105; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1091;.
    </p>
    <p>
      maxlength - &#1052;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1074;&#1074;&#1077;&#1076;&#1077;&#1085;&#1085;&#1099;&#1093; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074;.
    </p>
    <p>
      name - &#1048;&#1084;&#1103; &#1087;&#1086;&#1083;&#1103;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1086; &#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1095;&#1080;&#1082; &#1092;&#1086;&#1088;&#1084;&#1099; &#1084;&#1086;&#1075; &#1077;&#1075;&#1086; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;.
    </p>
    <p>
      placeholder - &#1059;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1079;&#1072;&#1084;&#1077;&#1097;&#1072;&#1102;&#1097;&#1080;&#1081;&#1089;&#1103; &#1090;&#1077;&#1082;&#1089;&#1090;.
    </p>
    <p>
      readonly - &#1059;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1083;&#1077; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1079;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;.
    </p>
    <p>
      required - &#1054;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1076;&#1083;&#1103; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1083;&#1077;.
    </p>
    <p>
      rows - &#1042;&#1099;&#1089;&#1086;&#1090;&#1072; &#1087;&#1086;&#1083;&#1103; &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072;&#1093; &#1090;&#1077;&#1082;&#1089;&#1090;&#1072;.
    </p>
    <p>
      tabindex - &#1055;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1072; &#1084;&#1077;&#1078;&#1076;&#1091; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080; &#1087;&#1088;&#1080; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1080; &#1085;&#1072; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1091; Tab.
    </p>
    <p>
      wrap - &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1087;&#1077;&#1088;&#1077;&#1085;&#1086;&#1089;&#1072; &#1089;&#1090;&#1088;&#1086;&#1082;
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Фреймы" FOLDED="true" ID="ID_370927504" CREATED="1536760141383" MODIFIED="1744533668685"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_245807679">&lt;iframe&gt;</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>HTML frames</b>&#xa0;- возможность загрузить в одном окне браузера несколько страниц.
    </p>
    <ul>
      <li>
        Используется в Wi-Fi роутерах (web-морда)
      </li>
      <li>
        вид как у Windows Explorer (слева дерево, справа файлы, сверху меню)
      </li>
      <li>
        каждому фрейму можно задать имя
      </li>
      <li>
        один фрейм может ссылаться на другой фрейм с помощью указания target
      </li>
      <li>
        видно только <b>URL основной страницы</b>
      </li>
      <li>
        DOCTYPE, скрывается URL и title, плохо поддерживается поисковыми ботами
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="iframe" ID="ID_245807679" CREATED="1548490441407" MODIFIED="1548491895343"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>iframe</b>&#160;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1074;&#1077;&#1073;-&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &#1074; &#1074;&#1077;&#1073;-&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;
    </p>
    <ul>
      <li>
        &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1079;&#1080;&#1090;&#1100; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1075;&#1086; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;. &#1058;.&#1077;. &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1095;&#1091;&#1078;&#1086;&#1077; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091;
      </li>
    </ul>
    <p>
      <font color="#008000">&lt;iframe src=&quot;URL&quot;&gt;&lt;/iframe&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;iframe height=&quot;300px&quot; width=&quot;100%&quot; src=&quot;demo_iframe.htm&quot; name=&quot;iframe_a&quot;&gt;&lt;/iframe&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;p&gt;&lt;a href=&quot;https://www.w3schools.com&quot; target=&quot;iframe_a&quot;&gt;W3Schools.com&lt;/a&gt;&lt;/p&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;p&gt;When the target of a link matches the name of an iframe, the link will open in the iframe.&lt;/p&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;iframe src=&quot;demo_iframe.htm&quot; height=&quot;200&quot; width=&quot;300&quot;&gt;&lt;/iframe&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;iframe src=&quot;demo_iframe.htm&quot; style=&quot;height:200px;width:300px;&quot;&gt;&lt;/iframe&gt;</font>&#160;&#160;# CSS
    </p>
    <p>
      <font color="#008000">&lt;iframe src=&quot;demo_iframe.htm&quot; style=&quot;border:none;&quot;&gt;&lt;/iframe&gt;</font>&#160;&#160;# &#1059;&#1073;&#1088;&#1072;&#1090;&#1100; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;
    </p>
    <p>
      <font color="#008000">&lt;iframe src=&quot;demo_iframe.htm&quot; style=&quot;border:2px solid red;&quot;&gt;&lt;/iframe&gt;</font>&#160;&#160;# &#1048;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;
    </p>
  </body>
</html></richcontent>
</node>
