<node TEXT="Switches" ID="ID_325369966" CREATED="1519112080454" MODIFIED="1519112080454"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Switches - &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1077;&#1083;&#1080;</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>switch (expression) </b></font>
    </p>
    <p>
      <font color="#008000"><b>{ </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;case i: </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;// do this </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;break; </b></font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;case j: </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;// do that </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;break; </b></font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;default: </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;// do this other thing </b></font>
    </p>
    <p>
