<node TEXT="# Пример кода" ID="ID_1735779691" CREATED="1519112080455" MODIFIED="1548492815585"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>&lt;script&gt; </b></font>
    </p>
    <p>
      <font color="#008000"><b>&#160;&#160;&#160;&#160;&#1090;&#1077;&#1082;&#1089;&#1090; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072; </b></font>
    </p>
    <p>
      <font color="#008000"><b>&lt;/script&gt;</b></font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">/** </font>
    </p>
    <p>
      <font color="#008000">&#160;* </font>&#1050;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1081;<font color="#008000">&#160;</font>
    </p>
    <p>
      <font color="#008000">&#160;* </font>&#1074; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086;
    </p>
    <p>
      <font color="#008000">&#160;* </font>&#1089;&#1090;&#1088;&#1086;&#1082;<font color="#008000">&#160;</font>
    </p>
    <p>
      <font color="#008000">&#160;*/ </font>
    </p>
    <p>
      <font color="#008000">//</font>&#160;&#1054;&#1076;&#1085;&#1086;&#1089;&#1090;&#1088;&#1086;&#1095;&#1085;&#1099;&#1081; &#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1081;<font color="#008000">&#160; </font>
    </p>
    <p>
      <font color="#008000">'use strict';&#160;&#160;</font>// &#1076;&#1083;&#1103; &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1085;&#1086;&#1081; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; JS
    </p>
    <p>
      <font color="#008000">var str; </font>// &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1103;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102;
    </p>
    <p>
      <font color="#008000">var str = &quot;A string&quot;; </font>// &#1086;&#1073;&#1098;&#1103;&#1074;&#1080;&#1090;&#1100; &#1080; &#1080;&#1085;&#1080;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102;, &#1077;&#1089;&#1083;&#1080; <b>&#1073;&#1077;&#1079; 'var'</b>&#160;- <b>&#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; </b>
    </p>
    <p>
      <font color="#008000">var alsoString = 'A string'; </font>// camelCase, &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1080; &#1085;&#1077; &#1080;&#1084;&#1077;&#1102;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">var x; </font>
    </p>
    <p>
      <font color="#008000">x = 2; </font>
    </p>
    <p>
      <font color="#008000">console.log(x); </font>
    </p>
    <p>
      <font color="#008000">x;</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">console.log(str == alsoString); </font>// &#1074;&#1099;&#1074;&#1086;&#1076; &#1085;&#1072; &#1101;&#1082;&#1088;&#1072;&#1085; (&#1085;&#1077; &#1091;&#1074;&#1077;&#1088;&#1077;&#1085;). == &#1101;&#1090;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086;&#1077; &#1089;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1086;&#1090;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1090;&#1080;&#1087;&#1099;
    </p>
    <p>
      <font color="#008000">console.log(str === alsoString); </font>// &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1082;&#1072;&#1082; == &#1074; Python
    </p>
    <p>
      <font color="#008000">console.log(str != alsoString); </font>
    </p>
    <p>
      <font color="#008000">console.log(str !== alsoString); </font>// &#1085;&#1077; &#1088;&#1072;&#1074;&#1085;&#1086;
    </p>
    <p>
      <font color="#008000">console.log(typeof(str), typeof alsoString);&#160; </font>// &#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1090;&#1080;&#1087; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081;
    </p>
    <p>
      <font color="#008000">console.error(&quot;Some error&quot;, 1, 2, 3, 4); </font>// &#1074;&#1099;&#1074;&#1086;&#1076; &#1085;&#1072; &#1101;&#1082;&#1088;&#1072;&#1085; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">var num1 = 1; </font>
    </p>
    <p>
      <font color="#008000">var num2 = 2.0; </font>
    </p>
    <p>
      <font color="#008000">console.log(num1 * num2); </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>// Objects: &#1087;&#1086;&#1093;&#1086;&#1078; &#1085;&#1072; dict &#1074; Python</b>
    </p>
    <p>
      <font color="#008000">var obj = {}; </font>
    </p>
    <p>
      <font color="#008000">obj['key'] = 13 </font>
    </p>
    <p>
