    </p>
    <p>
      
    </p>
    <p>
      <b>// &#1089;&#1087;&#1080;&#1089;&#1082;&#1080;. </b>&#1069;&#1090;&#1086; &#1085;&#1077; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; - &#1101;&#1090;&#1086; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;
    </p>
    <p>
      <font color="#008000">var list = [1, 2, 3]; </font>
    </p>
    <p>
      <font color="#008000">list.push(4);</font>&#160;// &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082;
    </p>
    <p>
      <font color="#008000">list </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>// Copy objects</b><font color="#008000">&#160;</font>
    </p>
    <p>
