      </li>
      <li>
        &#1088;&#1072;&#1079;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1100; &#1074; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1072;&#1093; &#1090;&#1077;&#1075;&#1086;&#1074;. JavaScript &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1099;&#1079;&#1074;&#1072;&#1085; &#1087;&#1088;&#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1084; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1080;
