<node TEXT="Пример кода" ID="ID_610284174" CREATED="1519112080456" MODIFIED="1519112080456"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000">'use strict'; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">var x = 1 === 1 ? 'true' : 'false'; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">var flag = true; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>if</b>&#160;(!flag) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;console.log('if'); </font>
    </p>
    <p>
      <font color="#008000">} else if ((flag &amp;&amp; 1 &lt; 2)&#160;&#160;|| (5 &lt; 3)) { </font>// || - or, &amp;&amp; - and.
    </p>
    <p>
      &#160;&#160;&#160;&#160;console.log('elseif');
    </p>
    <p>
      <font color="#008000">} else { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160; </font>&#160;// do nothing.
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">var <b>ternary</b>&#160;= 40 &gt; 13 ? 'yes' : 'no'; </font>
    </p>
    <p>
      <font color="#008000">console.log(ternary); </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">var value = '123'; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>switch</b>&#160;(value) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;case '321': </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;console.log('1'); </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;break; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;case '123': </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;console.log('2'); </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;break; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;default: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;console.log('other'); </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;break; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>// &#1048;&#1090;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080;</b>
    </p>
    <p>
      <font color="#008000">var i = 42; </font>
    </p>
    <p>
      <font color="#008000">console.log(i++); </font>// shows 42
    </p>
    <p>
      <font color="#008000">console.log(i); </font>// shows 43
    </p>
    <p>
      <font color="#008000">i = 42; </font>
    </p>
    <p>
      <font color="#008000">console.log(++i); </font>// shows 43
    </p>
    <p>
      <font color="#008000">console.log(i); </font>// shows 43
    </p>
    <p>
      <font color="#008000">for (var j = 0; j &lt; 10; j++) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;for (var i = 0; i &lt; 10; i++) { </font>// ++i, i++
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;console.log(i); </font>
