    </p>
    <p>
      <font color="#0000c0">perldoc perlsyn</font>&nbsp;&nbsp;# Синтаксис Perl
    </p>
    <p>
      <font color="#0000c0">perldoc perldata</font>&nbsp;&nbsp;# Типы данных используемых в Perl. SCALAR, ARRAY, HASH
    </p>
    <p>
      <font color="#0000c0">perldoc perlvar</font>&nbsp;&nbsp;# Специальные переменные
    </p>
    <p>
      <font color="#0000c0">perldoc perlop</font>&nbsp;&nbsp;# Операции поддерживающие Perl с типами данных
    </p>
    <p>
      <font color="#0000c0">perldoc perlsub</font>&nbsp;&nbsp;# Объявление и использование пользовательских подпрограмм
    </p>
    <p>
      <font color="#0000c0">perldoc perlfunc</font>&nbsp;&nbsp;# Описание встроенных функций
    </p>
    <p>
      <font color="#0000c0">perldoc perldebtut</font>&nbsp;&nbsp;# Отдадка
    </p>
  </body>
</html></richcontent>
