<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;"># Пример комплексного использования</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import logging </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Настройка </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">logging.basicConfig( </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;level=logging.DEBUG, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;format='%(asctime)s - %(name)s - %(levelname)s - %(message)s', </span>
    </p>
