<node TEXT="turtle" POSITION="bottom_or_right" ID="ID_1178217709" CREATED="1741598872350" MODIFIED="1741599618965"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      import turtle&#xa0;&#xa0;# Загружает модуль в память
    </p>
    <p>
      turtle.showturtle()&#xa0;&#xa0;# Показать черепаху
    </p>
