      turtle.forward(200)&#xa0;&#xa0;# Переместить черепаху вперед на 200 пикселов
    </p>
    <p>
      turtle.right (угол)&#xa0;&#xa0;# Повернуть черепаху в указанном направлении на нужный угол
    </p>
    <p>
      turtle.setheading(90)&#xa0;&#xa0;# Установить угловое направление
    </p>
    <p>
      turtle.heading()&#xa0;&#xa0;# Вывести угловое направление
    </p>
    <p>
      turtle.penup()&#xa0;&#xa0;# Поднять перо
    </p>
    <p>
      turtle.pendown()&#xa0;&#xa0;# Опустить перо
    </p>
    <p>
      ...
    </p>
  </body>
</html></richcontent>
