<node TEXT="Базы данных" FOLDED="true" POSITION="bottom_or_right" ID="ID_1370734613" CREATED="1683620546806" MODIFIED="1746619502505"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_227203876">SQLite3</a>&#xa0;&#xa0; <a href="#ID_980063778">PostgreSQL</a>&#xa0;&#xa0;<a href="#ID_1886763756">MySQL</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">SQLite3</span>&#xa0;- для небольших проектов, мобильных приложений, тестирования
    </p>
    <p>
      <span style="font-weight: bold;">PostgreSQL</span>&#xa0;- для сложных проектов, где важна надежность и расширяемость
    </p>
    <p>
      <span style="font-weight: bold;">MySQL</span>&#xa0;- для веб-приложений, где важна производительность и простота
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">ORM: SQLAlchemy</span>&#xa0;- Для работы с разными СУБД через единый интерфейс
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">ORM</span>&#xa0;- Object-Relational Mapping (Объектно-реляционное отображение)
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="ORM: SQLAlchemy" ID="ID_112938778" CREATED="1746619212226" MODIFIED="1746619473394"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">ORM - Object-Relational Mapping (Объектно-реляционное отображение): SQLAlchemy</span>
    </p>
    <ul>
      <li>
        Для работы с разными СУБД через единый интерфейс
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">from sqlalchemy import create_engine, Column, Integer, String </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">from sqlalchemy.ext.declarative import declarative_base </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">from sqlalchemy.orm import sessionmaker </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Подключение (пример для PostgreSQL) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">engine = create_engine('postgresql://user:password@localhost/testdb') </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">Base = declarative_base() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Определение модели </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">class User(Base): </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;__tablename__ = 'users' </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;id = Column(Integer, primary_key=True) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;name = Column(String) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;age = Column(Integer) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Создание таблиц </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">Base.metadata.create_all(engine) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Создание сессии </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">Session = sessionmaker(bind=engine) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">session = Session() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Добавление данных </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">new_user = User(name='Alice', age=25) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">session.add(new_user) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">session.commit() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Запрос данных </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">for user in session.query(User).filter(User.age &gt; 20): </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;print(user.name, user.age) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">session.close()</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Работа с SQLite3" ID="ID_674529521" CREATED="1746617955087" MODIFIED="1746955701117"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_259583810">with...as</a>&#xa0; <a href="#ID_227203876">SQLite3</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">import sqlite3 </span>
    </p>
    <p>
      
    </p>
    <p>
      # Подключение к базе (создаст файл, если его нет)
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">conn = sqlite3.connect('example.db') </span>
    </p>
    <ul>
      <li>
        sqlite3.connect(r'C:\Users\Имя_пoльзoвaтeля\temp\example.db') - указание пути в Windows
      </li>
    </ul>
    <p>
      # Создание курсора
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor = conn.cursor() </span>
    </p>
    <p>
      
    </p>
    <p>
      # Создание таблицы
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor.execute('''CREATE TABLE IF NOT EXISTS users </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;(id INTEGER PRIMARY KEY, name TEXT, age INTEGER)''') </span>
    </p>
    <p>
      
    </p>
    <p>
      # Вставка данных
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor.execute(&quot;INSERT INTO users (name, age) VALUES (?, ?)&quot;, ('Alice', 25)) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor.execute(&quot;INSERT INTO users (name, age) VALUES (?, ?)&quot;, ('Bob', 30)) </span>
    </p>
    <ul>
      <li>
        VALUES (?, ?) - для безопасной подстановки параметров в SQL-запрос. Это защищает от SQL-инъекций и корректно экранирует данные
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      # Сохранение изменений
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">conn.commit() </span>
    </p>
    <p>
      
    </p>
    <p>
      # Выборка данных
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor.execute(&quot;SELECT * FROM users&quot;) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">for row in cursor.fetchall(): </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;print(row) </span>
    </p>
    <p>
      
    </p>
    <p>
      # Закрытие соединения
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">conn.close()</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Соединение с базой данных с использованием контекстного менеджера</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import sqlite3 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">with sqlite3.connect('my_database.db') as conn: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;cursor = conn.cursor() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;# Выполнение SQL-запросов </span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Работа с PostgreSQL" ID="ID_613162085" CREATED="1746617960463" MODIFIED="1746620909910"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_980063778">PostgreSQL</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Работа через psycopg2</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">import psycopg2 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Подключение</span>&#xa0;
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">conn = psycopg2.connect( </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;dbname=&quot;testdb&quot;, </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;user=&quot;postgres&quot;, </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;password=&quot;password&quot;, </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;host=&quot;localhost&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor = conn.cursor() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Создание таблицы</span>&#xa0;
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor.execute(&quot;&quot;&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;CREATE TABLE IF NOT EXISTS users ( </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;id SERIAL PRIMARY KEY, </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;name VARCHAR(50), </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;age INTEGER </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&quot;&quot;&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Вставка данных</span>&#xa0;
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor.execute( </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&quot;INSERT INTO users (name, age) VALUES (%s, %s)&quot;, </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;('Alice', 25) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Пакетная вставка</span>&#xa0;
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">data = [('Bob', 30), ('Charlie', 35)] </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor.executemany( </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&quot;INSERT INTO users (name, age) VALUES (%s, %s)&quot;, </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;data </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">conn.commit() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Выборка с параметрами</span><span style="font-family: Lucida Console; color: #008000;">&#xa0;</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor.execute(&quot;SELECT * FROM users WHERE age &gt; %s&quot;, (26,)) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">for record in cursor: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;print(record) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Закрытие соединения </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">cursor.close() </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">conn.close()</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Работа с MySQL" ID="ID_942272219" CREATED="1746617971943" MODIFIED="1746621020144"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1886763756">MySQL</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Работа через mysql-connector-python</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Альтернативные драйверы для MySQL</span>
    </p>
    <ul>
      <li>
        PyMySQL - чистый Python-драйвер
      </li>
      <li>
        MySQLdb - популярный, но не поддерживает Python 3
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import mysql.connector </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Подключение</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">conn = mysql.connector.connect( </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;host=&quot;localhost&quot;, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;user=&quot;root&quot;, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;password=&quot;password&quot;, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;database=&quot;testdb&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">cursor = conn.cursor() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Создание таблицы</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">cursor.execute(&quot;&quot;&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;CREATE TABLE IF NOT EXISTS users ( </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;id INT AUTO_INCREMENT PRIMARY KEY, </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;name VARCHAR(50), </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;age INT </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&quot;&quot;&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Вставка данных</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">insert_query = &quot;INSERT INTO users (name, age) VALUES (%s, %s)&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">cursor.execute(insert_query, ('Alice', 25)) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Пакетная вставка</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">data = [('Bob', 30), ('Charlie', 35)] </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">cursor.executemany(insert_query, data) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">conn.commit() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Выборка данных</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">cursor.execute(&quot;SELECT * FROM users&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">for row in cursor: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;print(row) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Использование словаря для результатов</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">cursor = conn.cursor(dictionary=True) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">cursor.execute(&quot;SELECT * FROM users WHERE age &gt; %s&quot;, (26,)) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">for row in cursor: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;print(row['name'], row['age']) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Закрытие соединения</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">cursor.close() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">conn.close()</span>
    </p>
  </body>
</html></richcontent>
</node>
