<node TEXT="Apache-IP и время (парсинг строки)" POSITION="bottom_or_right" ID="ID_1302592937" CREATED="1743421316470" MODIFIED="1745605893072"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import re </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">line = '127.0.0.1 - rj [13/Nov/2024:12:23:30 -0000] &quot;GET HTTP/1.0&quot; 200' </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">m = re.search(r'(?P&lt;IP&gt;\d+\.\d+\.\d+\.\d+)', line) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(m.group('IP')) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">m = re.search(r'(?P&lt;Time&gt;\d{2}/\w{3}/\d{4}:\d{2}:\d{2}:\d{2})', line)</span><span style="font-family: Lucida Console;">&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(m.group('Time'))</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #0000c0;">./script.py</span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">127.0.0.1 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">13/Nov/2024:12:23:30 </span>
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Apache - парсим файл" POSITION="bottom_or_right" ID="ID_1672782148" CREATED="1743425871649" MODIFIED="1743426687688"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;"># GET запросы без подключения re</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">with open('access_log', 'r') as f: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;for line in f: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;if '&quot;GET HTTP/1.0&quot;' in line:</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;# Проверяем GET-запрос</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;ip = line.split()[0]</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# IP всегда первый элемент</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;print(ip) </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># re и несколько условий</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">import re </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">with open('access_log', 'r', encoding='utf-8') as f: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;for line in f: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;match = re.search( </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;r'^(?P&lt;IP&gt;\d+\.\d+\.\d+\.\d+)'&#xa0; </span><span style="font-family: Lucida Console;"># IP в начале строки</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;r' - \w+'&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0; </span><span style="font-family: Lucida Console;"># Пользователь</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;r' \[.*\]'&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0; </span><span style="font-family: Lucida Console;"># Время (любое)</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;r' &quot;GET HTTP/1\.0&quot; \d+$',&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0; </span><span style="font-family: Lucida Console;"># Запрос и статус</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;line </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;if match: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;print(match.group('IP')) </span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="CSV-файл" POSITION="bottom_or_right" ID="ID_1588717768" CREATED="1745605484361" MODIFIED="1745606427588"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_709789847">CSV</a>&#xa0;&#xa0;<a href="#ID_1771242868">S.split(символ)</a>&#xa0; <a href="#ID_478935421">Работа с файлами</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">cat test_scores.csv</span>&#xa0;&#xa0;# Файл, с которым работаем
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">1,2,3,4,5 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">6,7,8,9,10 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">11,12,13,14,15 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">16,17,18,19,20 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">21,22,23,24,25 </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Среднее значение по строкам</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">def main(): </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;with open('test_scores.csv', 'r') as csv_file:&#xa0;&#xa0;# файл закроется автоматически </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;lines = csv_file.readlines()&#xa0;&#xa0;# читаем все строки </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;# Обработка данных (уже после закрытия файла) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;for line in lines: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;tokens = line.split(',') </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;total = sum(float(token) for token in tokens) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;average = total / len(tokens) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;print(f'Средний: {average}') </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">if __name__ == '__main__': </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;main()</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># То же самое для понимания</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">def main(): </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;# Открыть файл. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;csv_file = open('test_scores.csv', 'r') </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;# Прочитать строки файла в список. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;lines = csv_file.readlines() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;# Закрыть файл. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;csv_file.close() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;# Обработать строки. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;for line in lines: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Получить результаты. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;tokens = line.split(',') </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Подсчитать общее количество баллов. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;total = 0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;for token in tokens: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;total += float(token) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Вычислить средний балл результатов. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;average = total / len(tokens) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;print(f'Cpeдний: {average}') </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;"># Исполнить главную функцию. </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">if __name__ == '__main__': </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;main()</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">./script.py</span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Средний: 3.0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Средний: 8.0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Средний: 13.0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Средний: 18.0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">Средний: 23.0</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="JSON-подсчет значений" FOLDED="true" POSITION="bottom_or_right" ID="ID_1801434165" CREATED="1769079597131" MODIFIED="1769080456963"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_844733533">JSON</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import json </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import os </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">def count(): </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&quot;&quot;&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;Calculate the number of courses and users in the JSON file. </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;JSON file is located at ~/project/user_study.json </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;Returns: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;count_user(int): Total number of users. </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;count_course(int): Total number of courses. </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&quot;&quot;&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;file_path = os.path.expanduser('~/project/user_study.json') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;with open(file_path, 'r', encoding='utf-8') as f: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;data = json.load(f) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;users = set() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;courses = set() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;for entry in data: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;users.add(entry['user_id']) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;courses.add(entry['course']) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;count_user = len(users) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;count_course = len(courses) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;return count_user, count_course </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">То же с комментариями</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import json&#xa0;&#xa0;# Импорт модуля для работы с JSON </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import os&#xa0;&#xa0;# Импорт модуля для работы с путями файловой системы </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">def count(): </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;file_path = os.path.expanduser('~/project/user_study.json')&#xa0;&#xa0;# Получение полного пути к файлу </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;with open(file_path, 'r', encoding='utf-8') as f:&#xa0;&#xa0;# Открытие файла с указанием кодировки </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;data = json.load(f)&#xa0;&#xa0;# Загрузка JSON-данных в Python-объект </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;users = set()&#xa0;&#xa0;# Множество для уникальных ID пользователей </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;courses = set()&#xa0;&#xa0;# Множество для уникальных названий курсов </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;for entry in data:&#xa0;&#xa0;# Итерация по всем записям в данных </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;users.add(entry['user_id'])&#xa0;&#xa0;# Добавление ID пользователя в множество </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;courses.add(entry['course'])&#xa0;&#xa0;# Добавление названия курса в множество </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;count_user = len(users)&#xa0;&#xa0;# Подсчёт уникальных пользователей </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;count_course = len(courses)&#xa0;&#xa0;# Подсчёт уникальных курсов </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;return count_user, count_course&#xa0;&#xa0;# Возврат результатов как кортежа</span>
    </p>
  </body>
</html></richcontent>
