<node TEXT="Поиск вхождения подстроки в строку" ID="ID_1565936378" CREATED="1519112080464" MODIFIED="1745605897861"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># Найти и вывести все вхождения подстроки в строку</b>, включая накладывающиеся. Например, для строки 'ABABA' и подстроки 'ABA' ответ должен быть 0, 2:
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">string = input() </span>
    </p>
    <p>
      <span style="color: #008000;">substring = input() </span>
    </p>
    <p>
      <span style="color: #008000;">pos = string.find(substring) </span>
    </p>
    <p>
      <span style="color: #008000;">while pos != -1: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;print(pos) </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;pos = string.find(substring, pos + 1)</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Поиск с выдачей номера строки" ID="ID_429368245" CREATED="1521812219804" MODIFIED="1743153626133"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_381313576">re</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b># Поиск с выдачей номера строки</b>
    </p>
    <p>
      <span style="color: #008000;">import re&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000;">text = 'My name is Django' </span>
    </p>
    <p>
      <span style="color: #008000;">match = re.search('Django', text) </span>
