<node TEXT="Фильтр лог-файла. DEBUG" POSITION="bottom_or_right" ID="ID_1323201462" CREATED="1732370255603" MODIFIED="1743418215537"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_478935421">Работа с файлами</a>&#xa0; <a href="#ID_259583810">with</a>&#xa0;&#xa0;<a href="#ID_1018078533">yield</a>&#xa0; <a href="#ID_381313576">re</a>&#xa0;&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Обработка больших файлов (построчная загрузка). Фильтр файла по слову &quot;DEBUG&quot;</span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">import re </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">def process_log_file(filename):</span><span style="font-weight: normal;">&#xa0;&#xa0;# Генератор, который читает файл лога построчно и обрабатывает каждую строку </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;with open(filename, 'r', encoding='utf-8') as log_file: </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;for line in log_file: </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;if re.search(r'^[0-9]{4}-[0-9]{2}-[0-9]{2} 10:15:[4][0-9] DEBUG:', line) or \ </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;re.search(r'^[0-9]{4}-[0-9]{2}-[0-9]{2} 10:15:50 DEBUG:', line): </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;yield line </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">if __name__ == '__main__': </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;log_filename = 'log.txt' </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;output_filename = 'new_log.txt'</span><span style="font-weight: normal;">&#xa0;&#xa0;# Новое имя файла </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;with open(output_filename, 'w', encoding='utf-8') as output_file: </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;for line in process_log_file(log_filename): </span>
    </p>
    <p>
      <span style="font-weight: normal; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;output_file.write(line)</span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Обработка больших файлов (построчная загрузка). Фильтр файла по слову &quot;DEBUG&quot;</span>
    </p>
    <p>
      <span style="color: #008000;">import re </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">def read_log_data(filename):</span>&#xa0;&#xa0;# Генератор читает данные из лог-файла построчно
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;with open(filename, 'r', encoding='utf-8') as f: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;for line in f: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;yield line </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">def write_processed_log(filename, processed_data):</span>&#xa0;&#xa0;# Функция записывает обработанные данные в лог-файл
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;with open(filename, 'w', encoding='utf-8') as f: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;f.writelines(processed_data) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">def process_log(input_filename, output_filename):</span>&#xa0;&#xa0;# Функция обрабатывает данные из лог-файла
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;log_data = read_log_data(input_filename) </span>
    </p>
    <p>
      
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;# Обработка данных: извлечение только строк с уровнем &quot;DEBUG&quot; в промежутке времени с 10:15:40 до 10:15:50
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;processed_data = [ </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;line for line in log_data if re.search(r'^[0-9]{4}-[0-9]{2}-[0-9]{2} 10:15:(4[0-9]|50) DEBUG:', line) </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;] </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;write_processed_log(output_filename, processed_data) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">if __name__ == '__main__': </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;log_filename = 'log.txt'</span>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Имя входного лог-файла
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;new_log_filename = 'new_log.txt'</span>&#xa0;&#xa0;# Имя выходного лог-файла
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;process_log(log_filename, new_log_filename)</span>&#xa0;&#xa0;# Вызов функции обработки лога
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Фильтр файла по слову &quot;DEBUG&quot;. Загрузка в память всего файла (не рекомендуется)</span>
    </p>
    <p>
      <span style="color: #008000;">import re</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">def read_log_data(filename):</span>&#xa0;&#xa0;# Функция читает данные из лог-файла и возвращает список строк
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <span style="color: #008000;">with open(filename, 'r', encoding='utf-8') as f:</span>&#xa0;&#xa0;# Открывается файл filename <span style="font-weight: bold;">для чтения</span>&#xa0;текста с указанным кодированием (utf-8). Файл связывается с переменной f в контексте with, который автоматически закроет файл после завершения работы
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0; <span style="color: #008000;">data = f.readlines()</span>&#xa0;&#xa0;# Данные из файла считываются и сохраняются в переменную data в виде списка строк
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <span style="color: #008000;">return data</span>&#xa0;&#xa0;# Список строк возвращается после чтения данных из файла
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">def write_processed_log(filename, processed_data):</span>&#xa0;&#xa0;#&#xa0;&#xa0;Функция записывает обработанные данные в лог-файл
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <span style="color: #008000;">with open(filename, 'w', encoding='utf-8') as f:</span>&#xa0;&#xa0;# Открывается файл filename <span style="font-weight: bold;">для записи</span>&#xa0;текста с указанным кодированием (utf-8). Файл связывается с переменной f в контексте with, который автоматически закроет файл после завершения работы
    </p>
    <p>
      &#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0; <span style="color: #008000;">f.writelines(processed_data)</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">def process_log(filename):</span>&#xa0;&#xa0;# Основная функция, которая обрабатывает данные из лог-файла
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <span style="color: #008000;">log_data = read_log_data(filename)</span>
    </p>
    <p>
      &#xa0;&#xa0;&#xa0; <span style="color: #008000;">processed_data = []</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Извлечение</span>&#xa0;только строк с уровнем &quot;DEBUG&quot; в промежутке времени с 10:15:40 до 10:15:50
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;for line in log_data: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;if re.search(r'^[0-9]{4}-[0-9]{2}-[0-9]{2} 10:15:[4][0-9] DEBUG:', line) or \ </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;re.search(r'^[0-9]{4}-[0-9]{2}-[0-9]{2} 10:15:50 DEBUG:', line): </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;processed_data.append(line) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;write_processed_log(filename, processed_data)</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">if __name__ == '__main__': </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;log_filename = 'log.txt'</span>&#xa0;&#xa0;# Имя лог-файла
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;process_log(log_filename)</span>&#xa0;&#xa0;# Вызов функции обработки лога
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Выборка из файла" POSITION="bottom_or_right" ID="ID_228128678" CREATED="1519112080464" MODIFIED="1746694096311"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#xa0;<a href="#ID_381313576">re</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b># вывести слова длиннее 15 символов</b>
    </p>
    <p>
      <span style="color: #008000;">import sys </span>
    </p>
    <p>
      <span style="color: #008000;">fin = open('litc-win.txt', encoding='cp1251') </span>
    </p>
    <p>
      <span style="color: #008000;">for line in fin: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;s = line.split()[1] </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;if len(s) &gt; 15: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;print(s) </span>
    </p>
    <p>
      
    </p>
    <p>
      <b># вывести слова с двумя буквами 'ш'</b>
    </p>
    <p>
      <span style="color: #008000;">import sys</span>
    </p>
    <p>
      <span style="color: #008000;">fin = open('litc-win.txt', encoding='cp1251')</span>
    </p>
    <p>
      <span style="color: #008000;">for line in fin:</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;s = line.split()[1]</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;if s.count('ш') == 2:</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;print(s)</span>
    </p>
  </body>
</html></richcontent>
</node>
