<node TEXT="Перехват сигнала" ID="ID_1198015507" CREATED="1743082331985" MODIFIED="1743082550260"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import signal </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import time </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">def handler(signum, frame): </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;print(f&quot;Получен сигнал {signum}, завершение...&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;exit(0) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Назначаем обработчики </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">signal.signal(signal.SIGINT, handler)&#xa0;&#xa0;</span><span style="font-family: Lucida Console;"># Ctrl+C</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">signal.signal(signal.SIGTERM, handler) </span><span style="font-family: Lucida Console;"># kill</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Скрипт запущен (PID: {os.getpid()}). Ожидание сигнала...&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">while True: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;time.sleep(1)</span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
