<node TEXT="Сортировка выбором (квадратичная)" ID="ID_754657191" CREATED="1519112080460" MODIFIED="1519112080460"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1074;&#1099;&#1073;&#1086;&#1088;&#1086;&#1084; &#1084;&#1072;&#1089;&#1082;&#1080;&#1084;&#1091;&#1084;&#1072; (&#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1074;&#1099;&#1073;&#1086;&#1088;&#1086;&#1084;). &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072; (&#1076;&#1083;&#1103; &#1086;&#1090;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084;&#1086;&#1074;). &#1042; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#160;&#160;<a href="#ID_918861488">a.sort()</a>&#160;. &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1095;&#1080;&#1089;&#1077;&#1083;, &#1089;&#1090;&#1088;&#1086;&#1082; &#1080; &#1074;&#1086;&#1086;&#1073;&#1097;&#1077;</b>
    </p>
    <p>
      <font color="#008000">for i in range (n-1): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;max_a = 0</font>&#160;# &#1085;&#1072;&#1081;&#1090;&#1080; &#1084;&#1077;&#1089;&#1090;&#1086; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1091;&#1084;&#1072; &#1080;&#1079; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1089; 0 &#1087;&#1086; n-1-i &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;for j in range(1, n-i): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;if a[j] &gt; a[max_a]: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;max_a = j </font>
    </p>
    <p>
      <font color="#008000">a[max_a], a[n-1-i] = a[n-1-i], a[max_a]</font>&#160;# &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1084;&#1077;&#1089;&#1090;&#1072;&#1084;&#1080; &#1085;&#1072;&#1081;&#1076;&#1077;&#1085;&#1085;&#1099;&#1081; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1091;&#1084; &#1089; n-1-i &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1084;&#160;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Сортировка вставкой (квадратичная)" ID="ID_1809488835" CREATED="1519112080460" MODIFIED="1519112080460"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1074;&#1089;&#1090;&#1072;&#1074;&#1082;&#1086;&#1081; (&#1080;&#1085;&#1086;&#1075;&#1076;&#1072; &#1083;&#1091;&#1095;&#1096;&#1077; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1086;&#1081; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080;)</b>
    </p>
    <p>
      <font color="#008000">a = [2, 4, 3, 5, 2, 7, 1]</font>&#160;# &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;
    </p>
    <p>
      <font color="#008000">n&#160;&#160;= len(a) </font># n - &#1076;&#1083;&#1080;&#1085;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;
    </p>
    <p>
      <font color="#008000">for i in range(1, n):</font>&#160;# &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1081; &#1094;&#1080;&#1082;&#1083;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#008000">while i &gt; 0 and a[i] &lt; a[i - 1]:</font>&#160;# i &#1095;&#1080;&#1089;&#1083;&#1086; &#1089;&#1088;&#1072;&#1074;&#1085;&#1080;&#1074;&#1072;&#1077;&#1084; &#1089; &#1095;&#1080;&#1089;&#1083;&#1086;&#1084; &#1089;&#1083;&#1077;&#1074;&#1072;. &#1080;&#1076;&#1077;&#1084; &#1089;&#1087;&#1088;&#1072;&#1074;&#1072; - &#1085;&#1072;&#1083;&#1077;&#1074;&#1086;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;a[i], a[i - 1] = a[i - 1], a[i]</font>&#160; # &#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &#1084;&#1077;&#1089;&#1090;&#1072;&#1084;&#1080;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;i -= 1</font>&#160;# &#1080;&#1085;&#1072;&#1095;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1088;&#1072;&#1074;&#1085;&#1080;&#1074;&#1072;&#1090;&#1100; &#1086;&#1076;&#1085;&#1080; &#1080; &#1090;&#1077; &#1078;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;
    </p>
    <p>
      <font color="#008000">print(a)</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Сортировка пузырьком (квадратичная)" ID="ID_1597606624" CREATED="1519112080460" MODIFIED="1778593863827"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># Пузырьковая сортировка. Сортируем по возрастанию</b>
    </p>
    <p>
      <span style="color: #008000;">a = [3, 5, 6, 8, 17, -1] </span>
    </p>
    <p>
      <span style="color: #008000;">n = len(a) </span>
    </p>
    <p>
      <span style="color: #008000;">for i in range(n): </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;for j in range(n - 1): </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;if a[j + 1] &lt; a[j]: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;a[j], a[j + 1] = a[j + 1], a[j] </span>
    </p>
    <p>
      <span style="color: #008000;">print(a) </span>
    </p>
    <p>
      
    </p>
    <p>
      <b># Пузырьковая сортировка. Сортируем по убыванию </b>
    </p>
    <p>
      <span style="color: #008000;">a = [3, 5, 6, 8, 17, -1] </span>
    </p>
    <p>
      <span style="color: #008000;">n = len(a) </span>
    </p>
    <p>
      <span style="color: #008000;">for i in range(n): </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;for j in range(n - 1): </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;if a[j + 1] </span><b><span style="color: #008000; font-size: medium;">&gt;</span><span style="color: #008000;">&#xa0;</span></b><span style="color: #008000;">a[j]: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;a[j], a[j + 1] = a[j + 1], a[j] </span>
    </p>
    <p>
      <span style="color: #008000;">print(a)</span>
    </p>
    <p>
      
    </p>
    <p>
      <b># Пузырьковая сортировка. Сортируем по длине строки </b>
    </p>
    <p>
      <span style="color: #008000;">a = [&quot;c&quot;, &quot;bb&quot;, &quot;aaa&quot;]</span>
    </p>
    <p>
      <span style="color: #008000;">n = len(a)</span>
    </p>
    <p>
      <span style="color: #008000;">for i in range(n):</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;for j in range(n - 1):</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;if <b>len</b>(a[j + 1]) </span><b><span style="color: #008000; font-size: medium;">&gt;</span><span style="color: #008000;">&#xa0;len(</span></b><span style="color: #008000;">a[j]):</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;a[j], a[j + 1] = a[j + 1], a[j] </span>
    </p>
    <p>
      <span style="color: #008000;">print(a)</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Странная сортировка (самая простая)" ID="ID_306145860" CREATED="1519112080460" MODIFIED="1519112080460"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># &#1057;&#1090;&#1088;&#1072;&#1085;&#1085;&#1072;&#1103; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; (&#1085;&#1077;&#1086;&#1073;&#1098;&#1103;&#1089;&#1085;&#1080;&#1084;&#1099;&#1081; &#1087;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099;)</b>. &#1055;&#1077;&#1088;&#1077;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1089;&#1086;&#1089;&#1077;&#1076;&#1085;&#1080;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;
    </p>
    <p>
      <font color="#008000">a = [2, 7,12, 6, -1] </font>
    </p>
    <p>
      <font color="#008000">n = len(a) </font>
    </p>
    <p>
      <font color="#008000">for i in range(n): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;for j in range(n): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;if a[i] &lt; a[j]: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;a[i], a[j] = a[j], a[i] </font>
    </p>
    <p>
      <font color="#008000">print(a) </font>
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1057;&#1090;&#1088;&#1072;&#1085;&#1085;&#1072;&#1103; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; </b>
    </p>
    <p>
      <font color="#008000">def my_sort(a):</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;for i in range(len(a)):</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;for j in range(len(a)):</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;if a[i] &lt; a[j]:</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;a[i], a[j] = a[j], a[i] </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;return a </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">a = list(map(int, input().split())) </font>
    </p>
    <p>
      <font color="#008000">print(my_sort(a))</font>
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1057;&#1090;&#1088;&#1072;&#1085;&#1085;&#1072;&#1103; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;. &#1055;&#1086; &#1072;&#1083;&#1092;&#1072;&#1074;&#1080;&#1090;&#1091;</b>
    </p>
    <p>
      <font color="#008000">def my_sort(a):</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;for i in range(len(a)):</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;for j in range(len(a)):</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;if a[i] &lt; a[j]:</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;a[i], a[j] = a[j], a[i] </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;return a </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">a = input().split() </font>
    </p>
    <p>
      <font color="#008000">print(my_sort(a))</font>
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1057;&#1090;&#1088;&#1072;&#1085;&#1085;&#1072;&#1103; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;. &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; &#1087;&#1086; &#1082;&#1083;&#1102;&#1095;&#1091; (&#1079;&#1076;&#1077;&#1089;&#1100; - len)</b>
    </p>
    <p>
      <font color="#008000">def my_sort(a, key):</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;for i in range(len(a)):</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;for j in range(len(a)):</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;if key(a[i]) &lt; key(a[j]):</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;a[i], a[j] = a[j], a[i] </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;return a </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">a = input().split() </font>
    </p>
    <p>
      <font color="#008000">print(my_sort(a, len)) </font>
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1057;&#1090;&#1088;&#1072;&#1085;&#1085;&#1072;&#1103; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;. &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1087;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1081; &#1094;&#1080;&#1092;&#1088;&#1077;</b>
    </p>
    <p>
      <font color="#008000">def my_sort(a, key): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;for i in range(len(a)): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;for j in range(len(a)): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;if key(a[i]) &lt; key(a[j]): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;a[i], a[j] = a[j], a[i] </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;return a </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">def last(x):</font>&#160;# &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1077;&#1081; last = lambda x: x % 10
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;return x % 10 </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">a = list(map(int, input().split())) </font>
    </p>
    <p>
      <font color="#008000">print(my_sort(a, last))</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Сумма чисел числа n" ID="ID_1290964926" CREATED="1519112080461" MODIFIED="1519112080461"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># &#1057;&#1091;&#1084;&#1084;&#1072; &#1095;&#1080;&#1089;&#1077;&#1083; &#1095;&#1080;&#1089;&#1083;&#1072; n</b>
    </p>
    <p>
      <font color="#008000">def digit_sum():</font>&#160;# &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;return sum(map(int, str(n)))</font>&#160;# &#1073;&#1077;&#1088;&#1077;&#1084; &#1095;&#1080;&#1089;&#1083;&#1086; n --&gt; &#1087;&#1088;&#1077;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1084; &#1077;&#1075;&#1086; &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; --&gt; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; map(&#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1084; int()) &#1087;&#1088;&#1077;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1084; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1077;&#1075;&#1086; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083; &#1074; &#1095;&#1080;&#1089;&#1083;&#1086; --&gt; &#1073;&#1077;&#1088;&#1077;&#1084; &#1089;&#1091;&#1084;&#1084;&#1091; &#1095;&#1080;&#1089;&#1077;&#1083; &#1074; &#1089;&#1087;&#1080;&#1089;&#1082;&#1077;
    </p>
  </body>
</html></richcontent>
</node>
