<node TEXT="переставить два слова" ID="ID_702566883" CREATED="1743417692646" MODIFIED="1743417706470"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># Переставить два слова</b>
    </p>
    <p>
      <span style="color: #008000;">s = input() </span>
    </p>
    <p>
      <span style="color: #008000;">first_word = s[:s.find(' ')] </span>
    </p>
    <p>
      <span style="color: #008000;">second_word = s[s.find(' ') + 1:] </span>
    </p>
    <p>
      <span style="color: #008000;">print(second_word + ' ' + first_word)</span>
    </p>
  </body>
