<node TEXT="Счетчики" FOLDED="true" ID="ID_181605564" CREATED="1519112080461" MODIFIED="1746432651029"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_987536092">enumerate()</a>
    </p>
    <p>
      
    </p>
    <p>
      <b># Счетчик через обновление переменной</b>
    </p>
    <p>
      <span style="color: #008000;">sequence = [1, 2, 7, 19] </span>
    </p>
    <p>
      <b><span style="color: #008000;">idx = 0</span></b><span style="color: #008000;">&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000;">for item in sequence: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;print(idx) </span>
    </p>
    <p>
      <b><span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;idx += 1</span></b><span style="color: #008000;">&#xa0;</span>
    </p>
    <p>
      <b>===ИЛИ без инициализации отдельной переменной===</b>
    </p>
    <p>
      <span style="color: #008000;">sequence = [1, 2, 7, 19] </span>
    </p>
    <p>
      <span style="color: #008000;">for idx, item in <b>enumerate</b>(sequence, start=1): </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;print(idx) </span>
    </p>
  </body>
</html></richcontent>
