<node TEXT="Букв в слове" ID="ID_1720603438" CREATED="1519112080461" MODIFIED="1519112080461"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_475043201">dict.get()</a>
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1055;&#1086;&#1089;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1073;&#1091;&#1082;&#1074; &#1074; &#1089;&#1083;&#1086;&#1074;&#1077;</b>
    </p>
    <p>
      <font color="#008000">s = input() </font>
    </p>
    <p>
      <font color="#008000">letters = dict() </font>
    </p>
    <p>
      <font color="#008000">for c in s: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;if c in letters: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;letters[c] += 1 </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;else: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;letters[c] = 1 </font>
    </p>
    <p>
      <font color="#008000">for c in sorted(letters):&#160; </font># &#1050;&#1080;&#1088;&#1080;&#1083;&#1083;&#1080;&#1094;&#1091; &#1085;&#1077; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;print(c, letters[c]) </font>
    </p>
    <p>
      <font color="#008000">====================&#1048;&#1051;&#1048;==================== </font>
    </p>
    <p>
      <font color="#008000">s = input() </font>
    </p>
    <p>
      <font color="#008000">letters = dict() </font>
    </p>
    <p>
      <font color="#008000">for c in s: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;letters[c] = <b>letters.get(c, 0)</b>&#160;+ 1&#160; </font># get(&#1082;&#1083;&#1102;&#1095;, &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; - &#1077;&#1089;&#1083;&#1080; &#1090;&#1072;&#1082;&#1086;&#1075;&#1086; &#1082;&#1083;&#1102;&#1095;&#1072; &#1085;&#1077;&#1090;)
    </p>
    <p>
      <font color="#008000">for c in sorted(letters):&#160; </font># &#1050;&#1080;&#1088;&#1080;&#1083;&#1083;&#1080;&#1094;&#1091; &#1085;&#1077; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;print(c, letters[c]) </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Кол-во разл. эл. списка, моножества" ID="ID_1465583495" CREATED="1520969207367" MODIFIED="1521449778632"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># &#1047;&#1072;&#1076;&#1072;&#1095;&#1072; &#171;&#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;&#187; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072;</b>
    </p>
    <p>
      # &#1044;&#1072;&#1085; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082;, &#1091;&#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086; &#1085;&#1077;&#1091;&#1073;&#1099;&#1074;&#1072;&#1085;&#1080;&#1102; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1074; &#1085;&#1077;&#1084;. &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1077;, &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1085;&#1077;&#1084; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;.
    </p>
    <p>
      <font color="#008000">a = [int(i) for i in input().split()] </font>
    </p>
    <p>
      <font color="#008000">num_distinct = 1 </font>
    </p>
    <p>
      <font color="#008000">for i in range(0, len(a) - 1): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;if a[i] != a[i + 1]: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;num_distinct += 1 </font>
    </p>
    <p>
      <font color="#008000">print(num_distinct) </font>
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1047;&#1072;&#1076;&#1072;&#1095;&#1072; &#171;&#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1095;&#1080;&#1089;&#1077;&#1083; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1072;&#187;</b>
    </p>
    <p>
      # &#1044;&#1072;&#1085; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1095;&#1080;&#1089;&#1077;&#1083;. &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1077;, &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1085;&#1077;&#1084; &#1074;&#1089;&#1090;&#1088;&#1077;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1095;&#1080;&#1089;&#1077;&#1083;.
    </p>
    <p>
      <font color="#008000">print(len(set(input().split())))</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Уникальные элементы списка" ID="ID_125834062" CREATED="1520970363397" MODIFIED="1520970509700"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b># &#1047;&#1072;&#1076;&#1072;&#1095;&#1072; &#171;&#1059;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;&#187; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072;</b>
    </p>
    <p>
      # &#1044;&#1072;&#1085; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082;. &#1042;&#1099;&#1074;&#1077;&#1076;&#1080;&#1090;&#1077; &#1090;&#1077; &#1077;&#1075;&#1086; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1074;&#1089;&#1090;&#1088;&#1077;&#1095;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1089;&#1087;&#1080;&#1089;&#1082;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1080;&#1085; &#1088;&#1072;&#1079;. &#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1074; &#1090;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1086;&#1085;&#1080; &#1074;&#1089;&#1090;&#1088;&#1077;&#1095;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1089;&#1087;&#1080;&#1089;&#1082;&#1077;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">a = [int(s) for s in input().split()] </font>
    </p>
    <p>
      <font color="#008000">for i in range(len(a)): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;for j in range(len(a)): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;if i != j and a[i] == a[j]: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;break </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;else: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;print(a[i], end=' ')</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Тестирование кода" FOLDED="true" POSITION="bottom_or_right" ID="ID_903849180" CREATED="1519112080514" MODIFIED="1767442173644"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1925529384">Исключения</a>&#xa0; <a href="#ID_1650590570">Тестирование</a>&#xa0; <a href="#ID_1772965409">Цикломатическая сложность</a>&#xa0; <a href="#ID_1524257013">IPython</a>&#xa0;&#xa0;<a href="#ID_1940847259">strace</a>&#xa0;&#xa0;<a href="#ID_706313475">pylint</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Линтеры (linters)</span>, для автоматической проверки кода на соответствие PEP 8 и выявления потенциальных ошибок. Многие IDE имеют встроенную поддержку linters.
    </p>
    <p>
      - pylint
    </p>
    <p>
      - flake8 (легковесный)
    </p>
    <p>
      - black (форматирование, без анализа)
    </p>
    <p>
      - mypy (проверка типов)
    </p>
    <p>
      - pycodestyle
    </p>
    <p>
      - autopep8 - автоматическое приведение к PEP8
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">pip install mccabe </span>
    </p>
    <p>
      <span style="color: #0000c0;">python -m mccabe --min 5 mccabe.pu</span>&#xa0;&#xa0;# определить цикломатическую сложность скрипта
    </p>
    <p>
      
    </p>
    <p>
      Создание точки останова и переход к отладчику Python (pdb)
    </p>
    <p>
      <span style="color: #008000;">import pdb;pdb.set_trace()</span>
    </p>
    <p>
      
    </p>
    <p>
      Создание точки останова и переход к отладчику Python на основе IPython (ipdb)
    </p>
    <p>
      <span style="color: #008000;">import ipdb;ipdb.set_trace() </span>
    </p>
    <p>
      
    </p>
    <p>
      Замер скорости выполнения с помощью магической функции timeit в IPython3
    </p>
    <p>
      <span style="font-family: Lucida Console;">In [1]: </span><span style="font-family: Lucida Console; color: #008000;">def f(x):</span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;...:&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;</span><span style="font-family: Lucida Console; color: #008000;">return x*x</span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;...: </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console;">In [2]: </span><span style="font-family: Lucida Console; color: #008000;">%timeit for x in range(100): f(x)</span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">19 µs ± 90.2 ns per loop (mean ± std. dev. of 7 runs, 100000 loops each</span>)
    </p>
  </body>
</html></richcontent>
<node TEXT="autopep8" POSITION="bottom_or_right" ID="ID_1400427574" CREATED="1519112080515" MODIFIED="1765023813968"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      утилита <b>autopep8 - </b>позволяет автоматически приводить код к виду, соответствующему PEP 8 (https://pypi.python.org/pypi/autopep8)
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">pip3 install autopep8 </span>
    </p>
    <p>
      <span style="color: #0000c0;">autopep8 --in-place ~/project/unformatted_code.py</span>&#xa0;&#xa0;# Исправить файл
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="doctest" ID="ID_906055979" CREATED="1519112080515" MODIFIED="1745483247359"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>doctest</b>&#xa0;- проверяет на правильность примеры в комментариях
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">def factorial(n): # 1 * 2 * 3 * ... * n </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&quot;&quot;&quot;calculates mathematical function n! </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&gt;&gt;&gt; factorial(5) </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;120 </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&gt;&gt;&gt; factorial(0) </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;1 </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&quot;&quot;&quot; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;result = 1 </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;for i in range(2, n +1): </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;result *= i </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;return result </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">if __name__ == &quot;__main__&quot;: </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;import doctest </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;doctest.testmod()&#xa0;&#xa0;&#xa0;&#xa0; </span>
    </p>
  </body>
</html></richcontent>
</node>
