<node TEXT="Копирование" ID="ID_1117486669" CREATED="1746694120068" MODIFIED="1778595766758"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_815005342">pathlib</a>&#xa0; <a href="#ID_1679558529">shutil</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Копирование файла</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">with open('source.txt', 'r') as source, open('destination.txt', 'w') as dest: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;content = source.read() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;dest.write(content) </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Скопировать spam.txt в каталог /tmp/delicious</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import shutil </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from pathlib import Path </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Определяем исходный файл и место назначения&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">source_file = Path('/tmp/spam.txt') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">destination_dir = Path('/tmp/delicious') </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Копируем файл&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">shutil.copy(source_file, destination_dir) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Copied '{source_file}' to '{destination_dir}'&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Также можно переименовать файл во время копирования </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">shutil.copy('/tmp/eggs.txt', '/tmp/delicious/eggs2.txt') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(&quot;Copied and renamed 'eggs.txt' to 'eggs2.txt'&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Копируем всё дерево каталогов целиком (вместе со всеми вложенными файлами и папками) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">shutil.copytree('/tmp/bacon', '/tmp/bacon_backup') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(&quot;Copied directory '/tmp/bacon' to '/tmp/bacon_backup'&quot;) </span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Обход" ID="ID_1122796205" CREATED="1778596760879" MODIFIED="1778596765865"/>
<node TEXT="Переименование, перемещение" ID="ID_1788118104" CREATED="1744708448368" MODIFIED="1778596223266"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_531023388">модуль os</a>&#xa0; <a href="#ID_815005342">pathlib</a>&#xa0; <a href="#ID_1679558529">shutil</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">import os </span>
    </p>
    <p>
      <span style="color: #008000;">rename('tmp.txt', 'coffee.txt') </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Перемещение и переименование файлов</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import shutil </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from pathlib import Path </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Создаем целевую директорию, если она еще не существует </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Path('/tmp/eggs').mkdir(parents=True, exist_ok=True) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Перемещаем файл в директорию (только если исходный файл существует) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">bacon_source = Path('/tmp/bacon.txt') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">if bacon_source.exists(): </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;shutil.move('/tmp/bacon.txt', '/tmp/eggs') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;print(&quot;Moved '/tmp/bacon.txt' to '/tmp/eggs'&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">else: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;print(&quot;'/tmp/bacon.txt' not found (may have been moved already)&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Перемещаем и переименовываем файл </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Сначала пересоздадим файл для перемещения </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Path('/tmp/bacon.txt').touch() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">shutil.move('/tmp/bacon.txt', '/tmp/eggs/new_bacon.txt') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(&quot;Moved and renamed '/tmp/bacon.txt' to '/tmp/eggs/new_bacon.txt'&quot;)</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Перенаправить вывод в файл" FOLDED="true" ID="ID_241355014" CREATED="1746346084336" MODIFIED="1746346151186"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_54308608">subpocess</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Перенаправление вывода в файл</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">with open(&quot;output.txt&quot;, &quot;w&quot;) as f: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;subprocess.run([&quot;ls&quot;, &quot;-l&quot;], stdout=f)</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="Стандартный поток ввода.вывода" POSITION="bottom_or_right" ID="ID_676336328" CREATED="1519112080464" MODIFIED="1746693975283"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1877491690">Перенаправление потоков (Unix)</a>
    </p>
    <p>
      В модуле sys имеются два объекта для работы с входными (sys.stdin) и выходными (sys.stdout) потоками
    </p>
    <p>
      
    </p>
    <p>
      <b># Стандартный поток вывода. Весь ввод с клавиатуры направлять в файл </b>
    </p>
    <p>
      <span style="color: #008000;">import sys </span>
    </p>
    <p>
      <span style="color: #008000;">sys.stdout = open(&quot;a.txt&quot;, &quot;w&quot;)</span>&#xa0;# w - write - открыть для записи
    </p>
    <p>
      <span style="color: #008000;">s = input() </span>
    </p>
    <p>
      <span style="color: #008000;">print(s)</span>
    </p>
    <p>
      
    </p>
    <p>
      <b># Стандартный поток ввода </b>
    </p>
    <p>
      <span style="color: #008000;">import sys </span>
    </p>
    <p>
      <span style="color: #008000;">sys.stdin = open(&quot;a.txt&quot;, &quot;r&quot;)</span>&#xa0;# r - read - прочитать, можно r&#xa0;&#xa0;не указывать (a.txt)
    </p>
    <p>
      <span style="color: #008000;">s = input() </span>
    </p>
    <p>
      <span style="color: #008000;">print(s)</span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Пути" ID="ID_1898847200" CREATED="1778592032019" MODIFIED="1778596760013"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_815005342"><span style="font-weight: normal;">pathlib</span></a><span style="font-weight: normal;">&#xa0;</span>&#xa0;<a href="#ID_531023388">os</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Создать новый каталог</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from pathlib import Path </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Получение текущего рабочего каталога </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">cwd = Path.cwd() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Определение пути для новых вложенных каталогов </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">new_dirs = cwd / 'delicious' / 'walnut' / 'waffles' </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Создание каталогов, включая любые отсутствующие родительские </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">new_dirs.mkdir(parents=True, exist_ok=True) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Successfully created: {new_dirs}&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Абсолютный путь</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from pathlib import Path </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Проверка, являются ли пути абсолютными </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Path('/') is absolute: {Path('/').</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">is_absolute()</span><span style="color: #008000; font-family: Lucida Console;">}&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Path('..') is absolute: {Path('..').</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">is_absolute()</span><span style="color: #008000; font-family: Lucida Console;">}&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Приведение относительного пути к его абсолютному виду</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from pathlib import Path </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># '..' ссылается на родительский каталог текущего рабочего каталога </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">resolved_path = Path('..').</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">resolve()</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Current working directory: {Path.cwd()}&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Resolved path of '..': {resolved_path}&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Проверка существования путей</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from pathlib import Path </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Path('.') exists: {Path('.')</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">.exists()</span><span style="color: #008000; font-family: Lucida Console;">}&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Path('setup.py') exists: {Path('setup.py')</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">.exists()</span><span style="color: #008000; font-family: Lucida Console;">}&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Path('nonexistentfile') exists: {Path('nonexistentfile')</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">.exists()</span><span style="color: #008000; font-family: Lucida Console;">}&quot;)</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Список файлов" ID="ID_746228944" CREATED="1746345172907" MODIFIED="1778597564539"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_815005342">pathlib</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Получить список файлов</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">from pathlib import Path </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">files = list(Path(&quot;.&quot;).iterdir()) </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Вывод содержимого каталога (не посещает подкаталоги)</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">from pathlib import Path </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">print(&quot;Contents of '/usr/bin':&quot;) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">count = 0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">for f in Path('/usr/bin').iterdir(): </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;if count &lt; 5: # Выводим первые 5 элементов, чтобы вывод был коротким </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;print(f) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;count += 1 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;else: </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;break </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Пройти по всему дереву каталогов, посещая все подкаталоги и файлы</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from pathlib import Path </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">p = Path('/usr/bin') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Walking directory tree for: {p}&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">for i in p.rglob('*'): </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;print(i) </span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Удалить файл" ID="ID_319001016" CREATED="1744708273875" MODIFIED="1778596419000"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_531023388">os</a>&#xa0; <a href="#ID_815005342">pathlib</a>&#xa0; <a href="#ID_1679558529">shutil</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">import os </span>
    </p>
    <p>
      <span style="color: #008000;">remove('coffee.txt') </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Удаление файлов и папок</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from pathlib import Path </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import shutil </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Создаем файл для удаления </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">file_to_delete = Path('/tmp/deleteme.txt') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">file_to_delete.touch() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Created '{file_to_delete}'&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Удаляем файл </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">file_to_delete.unlink() </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Deleted '{file_to_delete}'&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Создаем директорию для удаления </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">dir_to_delete = Path('/tmp/temp_dir') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">dir_to_delete.mkdir(exist_ok=True) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># rmdir() работает только с пустыми директориями </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">dir_to_delete.</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">rmdir()</span><span style="color: #008000; font-family: Lucida Console;">&#xa0; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(f&quot;Deleted empty directory '{dir_to_delete}'&quot;) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Используем shutil.rmtree() для удаления директории и всего её содержимого </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Примечание: это вызовет ошибку, если директория не существует, что допустимо для данного примера </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">if Path('/tmp/bacon_backup').exists(): </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;shutil</span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">.rmtree</span><span style="color: #008000; font-family: Lucida Console;">('/tmp/bacon_backup') </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;print(&quot;Deleted directory '/tmp/bacon_backup' and all its contents&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">else: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;print(&quot;Directory '/tmp/bacon_backup' does not exist (may have been deleted already)&quot;) </span>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Числа" FOLDED="true" ID="ID_778965745" CREATED="1519112080461" MODIFIED="1743515136527"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1518826001">int()</a>&#xa0;&#xa0;<a href="#ID_659664483"><span style="font-weight: normal;">float()</span></a><span style="font-weight: normal;">&#xa0;&#xa0;<a href="#ID_40531883">Арифметические операторы</a>&#xa0; <a href="#ID_541949936">print()</a></span>&#xa0;&#xa0;<a href="#ID_596515155">модуль math</a>&#xa0; <a href="#ID_682518870">модуль random</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(int(36.6))</span>&#xa0;&#xa0;# 36
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(float(36.6))</span>&#xa0;&#xa0;# 36.6
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(2 + 2)</span>&#xa0;&#xa0;# 4
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Арифметические операции после чтения с клавиатуры</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">a = int(input()) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">b = int(input()) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">sum = a + b </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(sum) </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Использовать модуль math</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import math</span>&#xa0;&#xa0;# Подключить математическую библиотеку
    </p>
    <p>
      <span style="color: #008000;">print(math.ceil(36.6))</span>&#xa0;&#xa0;# 37. Округлить число до ближайшего целого числа вверх
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;"># Случайное число</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">import random </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">print(random.randint(1, 100))</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="Сумма последовательности чисел" ID="ID_820898206" CREATED="1519112080462" MODIFIED="1521030653631"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_808580166">range()</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1044;&#1072;&#1085;&#1086; 10 &#1094;&#1077;&#1083;&#1099;&#1093; &#1095;&#1080;&#1089;&#1077;&#1083;. &#1042;&#1099;&#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1077; &#1080;&#1093; &#1089;&#1091;&#1084;&#1084;&#1091;</b>
    </p>
    <p>
      <font color="#008000">sum = 0 </font>
    </p>
    <p>
      <font color="#008000">for i in range(10): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;number = int(input()) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;sum += number </font>
    </p>
    <p>
      <font color="#008000">print(sum)</font>
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1057;&#1091;&#1084;&#1084;&#1072; N &#1095;&#1080;&#1089;&#1077;&#1083;. # &#1044;&#1072;&#1085;&#1086; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1095;&#1080;&#1089;&#1077;&#1083;. &#1042;&#1099;&#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1077; &#1080;&#1093; &#1089;&#1091;&#1084;&#1084;&#1091;</b>
    </p>
    <p>
      <font color="#008000">n = int(input()) </font>
    </p>
    <p>
      <font color="#008000">sum = 0 </font>
    </p>
    <p>
      <font color="#008000">for i in range(n): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;sum += int(input()) </font>
    </p>
    <p>
      <font color="#008000">print(sum)</font>
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1057;&#1091;&#1084;&#1084;&#1072; &#1095;&#1080;&#1089;&#1077;&#1083; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080;</b>
    </p>
    <p>
      <font color="#008000">result = 0 </font>
    </p>
    <p>
      <font color="#008000">for i in range(10): </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;result += i </font>
    </p>
    <p>
      <font color="#008000">print(result)</font>&#160;# 45
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1057;&#1091;&#1084;&#1084;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080;</b>. &#1047;&#1072;&#1082;&#1072;&#1085;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1091;&#1083;&#1077;&#1084;
    </p>
    <p>
      <font color="#008000">now = int(input()) </font>
    </p>
    <p>
      <font color="#008000">sumSeq = now </font>
    </p>
    <p>
      <font color="#008000">while now != 0: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;now = int(input()) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;sumSeq += now </font>
    </p>
    <p>
      <font color="#008000">print(sumSeq)</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
