      <li>
        &#1082;&#1086;&#1076; &#1087;&#1086;&#1089;&#1083;&#1077; yield (&#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; __exit__)
