    </p>
    <p>
      
    </p>
    <p>
      <b>print('11' +&#160;'22')</b>&#160;# &#1089;&#1082;&#1083;&#1077;&#1080;&#1090;&#1100; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1086;&#1073;&#1086;&#1081; (<b>&#1082;&#1086;&#1085;&#1082;&#1072;&#1090;&#1077;&#1085;&#1072;&#1094;&#1080;&#1103;</b>)
    </p>
  </body>
