<node TEXT="Модуль числа" ID="ID_1173081798" CREATED="1519112080462" MODIFIED="1521530735570"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_481724523">abs() </a>
    </p>
    <p>
      
    </p>
    <p>
      <b># &#1052;&#1086;&#1076;&#1091;&#1083;&#1100; &#1095;&#1080;&#1089;&#1083;&#1072;</b>
    </p>
    <p>
      <font color="#008000">x = int(input()) </font>
    </p>
    <p>
      <font color="#008000">if x &lt; 0: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;x = -x </font>
    </p>
    <p>
      <font color="#008000">print(x) </font>
    </p>
    <p>
      <b>=========&#1048;&#1051;&#1048;=========</b>
    </p>
    <p>
      <font color="#008000">x = int(input()) </font>
    </p>
    <p>
      <font color="#008000">if x &gt;= 0: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;print(x) </font>
    </p>
    <p>
      <font color="#008000"><b>else</b>: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;print(-x) </font>
    </p>
    <p>
      <b>=========&#1048;&#1051;&#1048;========= </b>
    </p>
    <p>
      &#1044;&#1083;&#1103; &#1087;&#1086;&#1076;&#1089;&#1095;&#1077;&#1090;&#1072; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1095;&#1080;&#1089;&#1083;&#1072; &#1074; &#1055;&#1080;&#1090;&#1086;&#1085;&#1077; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; <a href="#ID_481724523">abs()</a>, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1080;&#1079;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1086;&#1090; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1088;&#1072;&#1079; &#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1087;&#1086;&#1076;&#1089;&#1095;&#1077;&#1090; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Комплексные числа (complex)" ID="ID_1905708512" CREATED="1519112080476" MODIFIED="1765122467195"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_492629542">Комплексное число</a>&#xa0;&#xa0;complex()
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">num = 14 + 1j </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(type(num))&#xa0; </span><span style="font-family: Lucida Console;"># &lt;class 'complex'&gt; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(num)&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0; </span><span style="font-family: Lucida Console;"># (14+1j)</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(num.real)&#xa0;&#xa0; </span><span style="font-family: Lucida Console;"># 14.0 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">print(num.imag)&#xa0;&#xa0; </span><span style="font-family: Lucida Console;"># 1.0 </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">c2 = complex(5, -2)</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">print(f&quot;\nComplex number c2: {c2}&quot;)</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Complex number c2: (5-2j) </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">print(f&quot;Real part of c2: {c2.real}&quot;)</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Real part of c2: 5.0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">print(f&quot;Imaginary part of c2: {c2.imag}&quot;)</span><span style="font-family: Lucida Console;">&#xa0;# Imaginary part of c2: -2.0 </span>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Округление" ID="ID_1468659519" CREATED="1519112080505" MODIFIED="1765121320865"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_461049841">Встроенный метод decimal</a>&#xa0; <a href="#ID_1016274447">round()</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>Способы округления</b>
    </p>
    <ul>
      <li>
        для операций с деньгами использовать тип данных Decimal
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b><span style="color: #008000;">int</span></b><span style="color: #008000;">()&#xa0; </span># <b>1. Отбрасывание</b>&#xa0;части после точки
    </p>
    <p>
      <b><span style="color: #008000;">round</span></b><span style="color: #008000;">(x, n)&#xa0; </span><b># 2.</b>&#xa0;Округляет число x до n знаков после точки <b>в сторону ближайшего четного числа </b>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">import <b>math</b></span>
    </p>
    <p>
      <span style="color: #008000;">print(<b>math.floor</b>())&#xa0; </span><b># 3.</b>&#xa0;округление <b>вниз. </b>floor(1.5) == 1, floor(-1.5) == -2
    </p>
    <p>
      <span style="color: #008000;">print(<b>math.ceil</b>())&#xa0; </span><b># 4.</b>&#xa0;округление <b>вверх.</b>&#xa0;ceil(1.5) == 2, ceil(-1.5) == -1
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&gt; print(<b>'{0:.2f}'.format(0.1)</b>)</span>&#xa0;&#xa0;# --&gt; 0.10. <b>5.</b>&#xa0;вывод с точностью (<b>классическое&#xa0;&#xa0;округление</b>)&#xa0;&#xa0;до 2 знака
    </p>
    <p>
      
    </p>
    <p>
      <b>abs</b>(x)&#xa0;&#xa0;# Модуль числа (абсолютная величина). abs(-5) == 5
    </p>
    <p>
      
    </p>
    <p>
      <b># Округление вверх</b>
    </p>
    <p>
      <span style="color: #008000;">a = int(input()) </span>
    </p>
    <p>
      <span style="color: #008000;">b = int(input()) </span>
    </p>
    <p>
      <span style="color: #008000;">print((a + b - 1) // b) </span>
    </p>
  </body>
</html></richcontent>
</node>
