<node TEXT="Debian 9.0 (PHP+PHP-FPM)" ID="ID_1587510430" CREATED="1548592993982" MODIFIED="1550474755081"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_203776548">FPM</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Use PHP Scripts</b>
    </p>
    <p>
      Configure Apache2 to use PHP scripts.
    </p>
    <p>
      [1]&#160;&#160;&#160;&#160;&#160;Install PHP.
    </p>
    <p>
      <font color="#0000c0">apt -y install php php-cgi libapache2-mod-php php-common php-pear php-mbstring </font>
    </p>
    <p>
      <font color="#0000c0">apt install php-mysql</font>&#160;&#160;# &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; <b>php-mysql</b>&#160; (&#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; php&lt;&#1074;&#1077;&#1088;&#1089;&#1080;&#1103;&gt;-mysql)
    </p>
    <p>
      [2]&#160;&#160;&#160;&#160;&#160;Configure Apache2.
    </p>
    <p>
      <font color="#0000c0">a2enconf php7.0-cgi</font>
    </p>
    <p>
      <font color="#0000c0">systemctl restart apache2</font>
    </p>
    <p>
      [3]&#160;&#160;&#160;&#160;&#160;Create a PHP test page and access to it from any clients with web browser. It's OK if following page is shown.
    </p>
    <p>
      <font color="#0000c0">vi /var/www/html/index.php</font>
    </p>
    <p>
      <font color="#008000">&lt;?php phpinfo(); ?&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>PHP-FPM</b>
    </p>
    <p>
      [1]&#160;&#160;&#160;&#160;&#160;Install PHP-FPM.
    </p>
    <p>
      <font color="#0000c0">apt -y install php-fpm</font>
    </p>
    <p>
      [2]&#160;&#160;&#160;&#160;&#160;Configure Apache httpd.
    </p>
    <p>
      <font color="#0000c0">vi /etc/php/7.0/fpm/pool.d/www.conf</font>
    </p>
    <p>
      <font color="#008000">listen = 127.0.0.1:9000</font>&#160;&#160;# line 36: change
    </p>
    <p>
      <font color="#0000c0">vi /etc/apache2/sites-enabled/000-default.conf</font>
    </p>
    <p>
      <font color="#008000"># add into &lt;VirtualHost&gt; - &lt;/VirtualHost&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;FilesMatch &quot;\.php$&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;SetHandler &quot;proxy:fcgi://127.0.0.1:9000/&quot; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;/FilesMatch&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/VirtualHost&gt; </font>
    </p>
    <p>
      <font color="#0000c0">a2enconf php7.0-fpm </font>
    </p>
    <p>
      <font color="#0000c0">a2enmod proxy_fcgi </font>
    </p>
    <p>
      <font color="#0000c0">systemctl restart php7.0-fpm apache2</font>
    </p>
    <p>
      [3] <font color="#0000c0">vi /var/www/html/index.php</font>&#160;&#160;# &#1057;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1080;.
    </p>
    <p>
      <font color="#008000">&lt;?php phpinfo(); ?&gt;</font>
    </p>
    <p>
      &#1080;&#1083;&#1080; <font color="#0000c0">echo '&lt;?php phpinfo(); ?&gt;' &gt; /var/www/html/info.php </font>
    </p>
    <p>
      &#1042; Server API &#1074;&#1080;&#1076;&#1080;&#1084; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; FPM/FastCGI
    </p>
  </body>
</html></richcontent>
</node>
<node ID="ID_251390863" CREATED="1579911841536" MODIFIED="1582205394391"><richcontent TYPE="NODE">

<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#000000">&#1052;&#1091;&#1083;&#1100;&#1090;&#1080;&#1074;&#1077;&#1088;&#1089;&#1080;&#1086;&#1085;&#1085;&#1086;&#1089;&#1090;&#1100; PHP (&#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; &#1085;&#1091;&#1078;&#1085;&#1099;&#1093; &#1074;&#1077;&#1088;&#1089;&#1080;&#1081; &#1085;&#1072; localhost)</font>
    </p>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      1. &#1059;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; PHP --&gt; &#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1089;&#1103; &#1089;&#1090;&#1072;&#1088;&#1072;&#1103;
    </p>
    <p>
      2. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1083;&#1072;&#1075;&#1080;&#1085; yum-plugin-replace
    </p>
    <p>
      <font color="#0000c0">rpm -Uvh http://mirror.webtatic.com/yum/el6/latest.rpm</font>&#160;
    </p>
    <p>
      <font color="#0000c0">yum install yum-plugin-replace</font>
    </p>
    <p>
      3. &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; webtatic.com, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1083; &#1082;&#1086;&#1085;&#1092;&#1083;&#1080;&#1082;&#1090; &#1074;&#1077;&#1088;&#1089;&#1080;&#1081; PHP
    </p>
    <p>
      <font color="#0000c0">vi /etc/yum.repos.d/<b>webtatic</b>.repo</font>
    </p>
    <p>
      <font color="#008000">enable=0</font>
    </p>
    <p>
      4. &#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081;, &#1080;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1073;&#1091;&#1076;&#1077;&#1084; &#1073;&#1088;&#1072;&#1090;&#1100; &#1085;&#1091;&#1078;&#1085;&#1091;&#1102; &#1074;&#1077;&#1088;&#1089;&#1080;&#1102; PHP
    </p>
    <p>
      <font color="#0000c0">vi /etc/yum.repos.d/<b>remi-php73</b>.repo </font>
    </p>
    <p>
      <font color="#008000">enable=1</font>
    </p>
    <p>
      <font color="#0000c0">yum replace php --replace-with=php</font>&#160;&#160;# &#1057;&#1090;&#1072;&#1074;&#1080;&#1084; &#1074;&#1077;&#1088;&#1089;&#1080;&#1102; PHP
    </p>
    <p>
      5. &#1045;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">rpm -ivh http://rpms.famillecollet.com/enterprise/remi-release-7.rpm</font>&#160;&#160;# &#1088;&#1077;&#1087;&#1086;&#1079;&#1080;&#1090;&#1086;&#1088;&#1080;&#1081; &#1076;&#1083;&#1103; &#1085;&#1086;&#1074;&#1086;&#1075;&#1086; PHP
    </p>
    <p>
      <font color="#0000c0">vim /etc/yum.repos.d/remi-php73.repo</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
