<node TEXT="Запись в файл" FOLDED="true" ID="ID_1577764912" CREATED="1549352868974" MODIFIED="1549449902449"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>file_put_contents()</b>&#160;- &#1047;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1074; &#1092;&#1072;&#1081;&#1083;
    </p>
    <ul>
      <li>
        FILE_APPEND - &#1092;&#1083;&#1072;&#1075;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1092;&#1072;&#1081;&#1083; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1080;&#1096;&#1077;&#1090;&#1089;&#1103;. &#1040; &#1090;&#1072;&#1082; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1074; &#1082;&#1086;&#1085;&#1077;&#1094; &#1092;&#1072;&#1081;&#1083;&#1072;
      </li>
      <li>
        &quot;\n&quot; - &#1089;&#1080;&#1084;&#1074;&#1086;&#1083; &#1087;&#1077;&#1088;&#1077;&#1085;&#1086;&#1089;&#1072; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;. &#1050;&#1072;&#1078;&#1076;&#1072;&#1103; &#1085;&#1086;&#1074;&#1072;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1090;&#1077;&#1087;&#1077;&#1088;&#1100; &#1089; &#1085;&#1086;&#1074;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1095;&#1082;&#1080;
      </li>
    </ul>
    <p>
      f<b>ile_exists()&#160;- </b>&#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072;. &#1048;&#1085;&#1072;&#1095;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1087;&#1088;&#1077;&#1090;&#1072;&#1090;&#1086;&#1088; &#1074;&#1099;&#1076;&#1072;&#1089;&#1090; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1086;&#1073; &#1086;&#1096;&#1080;&#1073;&#1082;&#1077;
    </p>
    <p>
      <b>file_get_contents()</b>&#160;- &#1089;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p style="text-align: center">
      <b>Troubleshooting</b>
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1092;&#1072;&#1081;&#1083; &#1085;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; - &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; &#1074; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091; <a href="#ID_1473215926">SELinux</a>&#160; &#1080; <a href="#ID_1089875239">&#1055;&#1088;&#1072;&#1074; &#1076;&#1086;&#1089;&#1091;&#1087;&#1072;</a>&#160;&#1082; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1091;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      ---------------------------------------------------------------------------------------
    </p>
    <p>
