    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;$text1 = !empty($_POST['text1']) ? $_POST['text1'] : null; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;$text2 = !empty($_POST['text2']) ? $_POST['text2'] : null; </font>
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;form action=&quot;?&quot; method=&quot;post&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;input name=&quot;text1&quot; type=&quot;text&quot; value=&quot;&lt;?php echo htmlspecialchars($text1) ?&gt;&quot;/&gt;&lt;br /&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;textarea name=&quot;text2&quot; cols=&quot;40&quot; rows=&quot;10&quot;&gt;&lt;?php echo htmlspecialchars($text2); ?&gt;&lt;/textarea&gt;&lt;br /&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;input name=&quot;ok&quot; type=&quot;submit&quot; /&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/form&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;if(!empty($_POST['ok'])) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;{ </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;if(!$text1) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo '&#1058;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1086;&#1077; &#1087;&#1086;&#1083;&#1077; &#1085;&#1077; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1086;.'; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;elseif(!$text2) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo '&#1058;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1072;&#1103; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1100; &#1085;&#1077; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1072;.'; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;else</font>&#160;// &#1047;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1074; &#1092;&#1072;&#1081;&#1083;, &#1079;&#1072;&#1082;&#1072;&#1085;&#1095;&#1080;&#1074;&#1072;&#1103; &#1082;&#1072;&#1078;&#1076;&#1091;&#1102; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1084; &#1087;&#1077;&#1088;&#1077;&#1085;&#1086;&#1089;&#1072; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;<b>file_put_contents</b>('text.txt', $text2 .&quot;\n&quot;, FILE_APPEND); </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;} </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;else </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;{ </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo '&#1053;&#1072;&#1087;&#1080;&#1096;&#1080;&#1090;&#1077; &#1095;&#1090;&#1086;-&#1085;&#1080;&#1073;&#1091;&#1076;&#1100;'; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;} </font>
    </p>
    <p>
      
    </p>
    <p>
      // &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072; &#1080; &#1077;&#1089;&#1083;&#1080; &#1077;&#1089;&#1090;&#1100; - &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1084; &#1077;&#1075;&#1086; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1074; &#1087;&#1086;&#1090;&#1086;&#1082;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;if(<b>file_exists</b>('text.txt')) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo nl2br(htmlspecialchars(<b>file_get_contents</b>('text.txt'))); </font>
    </p>
  </body>
</html></richcontent>
</node>
