<node TEXT="Composer" ID="ID_1824343910" CREATED="1657719090807" MODIFIED="1658052432771">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Composer</b>&nbsp;(команды берем с сайта)
    </p>
    <ul>
      <li>
        Composer - пакетный менеджер для PHP
      </li>
      <li>
        composer.json - файл конфигурации в проекте с ссылками на зависимости
      </li>
    </ul>
    <p>
      <b>Установка</b>
    </p>
    <p>
      <font color="#0000c0">php -r &quot;copy('https://getcomposer.org/installer', 'composer-setup.php');&quot;</font>&nbsp;&nbsp;# Загрузить в текущий каталог
    </p>
    <p>
      <font color="#0000c0">php -r &quot;if (hash_file('sha384', 'composer-setup.php') === '55ce33d7678c5a611085589f1f3ddf8b3c52d662cd01d4ba75c0ee0459970c2200a51f492d557530c71c15d8dba01eae') { echo 'Installer verified'; } else { echo 'Installer corrupt'; unlink('composer-setup.php'); } echo PHP_EOL;&quot;</font>&nbsp;&nbsp;# Проверить
    </p>
    <p>
      <font color="#0000c0">php composer-setup.php</font>&nbsp;&nbsp;# Запустить инсталляцию
    </p>
    <p>
      <font color="#0000c0">php -r &quot;unlink('composer-setup.php');&quot;</font>&nbsp;&nbsp;# Удалить инсталлятор
    </p>
    <p>
      <font color="#0000c0">mv <b>composer.phar</b>&nbsp;/usr/local/bin/composer</font>&nbsp;&nbsp;# Чтобы скрипт работал глобально, перемещаем в соотв. каталог
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">composer install</font>&nbsp;&nbsp;# Установка зависимостей проекта
    </p>
  </body>
</html></richcontent>
</node>
