<node TEXT="$GLOBALS" ID="ID_711790860" CREATED="1548590614774" MODIFIED="1548781793538"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>$GLOBALS</b>&#160;&#8212; &#1057;&#1089;&#1099;&#1083;&#1082;&#1080; &#1085;&#1072; &#1074;&#1089;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1080; &#1074;&#1080;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080;
    </p>
    <ul>
      <li>
        &#1040;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; (<b>array</b>), &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081; &#1089;&#1089;&#1099;&#1083;&#1082;&#1080; &#1085;&#1072; &#1074;&#1089;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077;, &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1074; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1080; &#1074;&#1080;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072;
      </li>
      <li>
        <b>&#1048;&#1084;&#1077;&#1085;&#1072; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093;</b>&#160; &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; <b>&#1082;&#1083;&#1102;&#1095;&#1072;&#1084;&#1080;</b>&#160; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;.
      </li>
    </ul>
    <p>
      <font color="#008000">$x = 5; </font>
    </p>
    <p>
      <font color="#008000">$y = 10; </font>
    </p>
    <p>
      <font color="#008000">function test() { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;<b>$GLOBALS['y']</b>&#160;= <b>$GLOBALS['x']</b>&#160;+ <b>$GLOBALS['y']</b>; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      <font color="#008000">test(); </font>
    </p>
    <p>
      <font color="#008000">echo $y;&#160; </font>// --&gt; 15
    </p>
  </body>
</html></richcontent>
