  </head>
  <body>
    <p>
      <b>&#1055;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; $_SERVER</b>&#160; - &#1101;&#1090;&#1086; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102;, &#1090;&#1072;&#1082;&#1091;&#1102; &#1082;&#1072;&#1082; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1080;, &#1087;&#1091;&#1090;&#1080; &#1080; &#1084;&#1077;&#1089;&#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074;. &#1047;&#1072;&#1087;&#1080;&#1089;&#1080; &#1074; &#1101;&#1090;&#1086;&#1084; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084;. &#1053;&#1077;&#1090; &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1080;, &#1095;&#1090;&#1086; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090; &#1083;&#1102;&#1073;&#1091;&#1102; &#1080;&#1079; &#1085;&#1080;&#1093;; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1080;&#1079; &#1085;&#1080;&#1093; &#1080;&#1083;&#1080; &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077;, &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1077; &#1079;&#1076;&#1077;&#1089;&#1100;.
    </p>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      
    </table>
    <p>
      <font color="#008000">echo $_SERVER['SERVER_NAME'];</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>'PHP_SELF'</b>&#160; &#1048;&#1084;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1089;&#1077;&#1081;&#1095;&#1072;&#1089; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103;, &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1082;&#1086;&#1088;&#1085;&#1103; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;.
    </p>
    <p>
      <b>'argv'</b>&#160;&#160; &#1052;&#1072;&#1089;&#1089;&#1080;&#1074; &#1072;&#1075;&#1088;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1091;
    </p>
    <p>
      <b>'argc'</b>&#160; &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1091; (&#1077;&#1089;&#1083;&#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1077;&#1076;&#1077;&#1085; &#1074; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077;).
    </p>
    <p>
      <b>'GATEWAY_INTERFACE'</b>&#160; &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1091;&#1102; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084; &#1074;&#1077;&#1088;&#1089;&#1080;&#1102; &#1089;&#1087;&#1077;&#1094;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; CGI
    </p>
    <p>
      <b>'SERVER_ADDR'</b>&#160; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;.
    </p>
    <p>
      <b>'SERVER_NAME'</b>&#160; &#1048;&#1084;&#1103; &#1093;&#1086;&#1089;&#1090;&#1072;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;. &#1042; Apache 2 &#1074;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; UseCanonicalName = On &#1080; ServerName. &#1042; &#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1101;&#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1086;&#1090;&#1088;&#1072;&#1079;&#1080;&#1090; &#1080;&#1084;&#1103; &#1093;&#1086;&#1089;&#1090;&#1072;, &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1084;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1086;&#1076;&#1076;&#1077;&#1083;&#1072;&#1085;&#1086;
    </p>
    <p>
      <b>'SERVER_SOFTWARE'</b>&#160; &#1057;&#1090;&#1088;&#1086;&#1082;&#1072; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1072;&#1103; &#1074; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072;&#1093;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1086;&#1090;&#1074;&#1077;&#1090; &#1085;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;
    </p>
    <p>
      <b>'SERVER_PROTOCOL'</b>&#160; &#1048;&#1084;&#1103; &#1080; &#1074;&#1077;&#1088;&#1089;&#1080;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072;, &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1099;&#1083;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1096;&#1077;&#1085;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072;;
    </p>
    <p>
      <b>'REQUEST_METHOD'</b>&#160; &#1050;&#1072;&#1082;&#1086;&#1081; &#1084;&#1077;&#1090;&#1086;&#1076; &#1073;&#1099;&#1083; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085; &#1076;&#1083;&#1103; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;; &#1082; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1091; 'GET', 'HEAD', 'POST', 'PUT'
    </p>
    <p>
      <b>'REQUEST_TIME'</b>&#160; &#1042;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1084;&#1077;&#1090;&#1082;&#1072; &#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;
    </p>
    <p>
      <b>'REQUEST_TIME_FLOAT'</b>&#160; &#1042;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1084;&#1077;&#1090;&#1082;&#1072; &#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1089; &#1090;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1076;&#1086; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1077;&#1082;&#1091;&#1085;&#1076;
    </p>
    <p>
      <b>'QUERY_STRING'</b>&#160; &#1057;&#1090;&#1088;&#1086;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1077;&#1089;&#1090;&#1100;, &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1073;&#1099;&#1083;&#1072; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072;.
    </p>
    <p>
      <b>'DOCUMENT_ROOT'</b>&#160; &#1044;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1103; &#1082;&#1086;&#1088;&#1085;&#1103; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;, &#1074; &#1090;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1080; &#1090;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1072; &#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1084; &#1092;&#1072;&#1081;&#1083;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <p>
      <b>'HTTP_ACCEPT'</b>&#160; &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; Accept: &#1080;&#1079; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1077;&#1089;&#1090;&#1100;.
    </p>
    <p>
      <b>'HTTP_ACCEPT_CHARSET'</b>&#160; &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; Accept-Charset: &#1080;&#1079; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1077;&#1089;&#1090;&#1100;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;: 'iso-8859-1,*,utf-8'.
    </p>
    <p>
      <b>'HTTP_ACCEPT_ENCODING'</b>&#160; &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; Accept-Encoding: &#1080;&#1079; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1077;&#1089;&#1090;&#1100;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;: 'gzip'.
    </p>
    <p>
      <b>'HTTP_ACCEPT_LANGUAGE'</b>&#160; &#1057;&#1086;&#1076;. &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; Accept-Language: &#1080;&#1079; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1077;&#1089;&#1090;&#1100;
    </p>
    <p>
      <b>'HTTP_CONNECTION'</b>&#160; &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; Connection: &#1080;&#1079; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1077;&#1089;&#1090;&#1100;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;: 'Keep-Alive'
    </p>
    <p>
      <b>'HTTP_HOST'</b>&#160; &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; Host: &#1080;&#1079; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1077;&#1089;&#1090;&#1100;.
    </p>
    <p>
      <b>'HTTP_REFERER'</b>&#160; &#1040;&#1076;&#1088;&#1077;&#1089; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; (&#1077;&#1089;&#1083;&#1080; &#1077;&#1089;&#1090;&#1100;), &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1096;&#1105;&#1083; &#1085;&#1072; &#1101;&#1090;&#1091; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091;. &#1069;&#1090;&#1086;&#1090; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1082; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
