    </p>
    <p>
      <b>'SCRIPT_NAME'&#160; </b>&#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1087;&#1091;&#1090;&#1100; &#1082; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1084;&#1091; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1084;&#1086;&#1084;&#1091; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1091;. &#1069;&#1090;&#1086; &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1086; &#1076;&#1083;&#1103; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; &#1089;&#1072;&#1084;&#1080;&#1093; &#1089;&#1077;&#1073;&#1103;. &#1050;&#1086;&#1085;&#1089;&#1090;&#1072;&#1085;&#1090;&#1072; __FILE__ &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1087;&#1086;&#1083;&#1085;&#1099;&#1081; &#1087;&#1091;&#1090;&#1100; &#1080; &#1080;&#1084;&#1103; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; (&#1090;&#1086; &#1077;&#1089;&#1090;&#1100; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086;) &#1092;&#1072;&#1081;&#1083;&#1072;.
    </p>
