    <p>
      <b>'PHP_AUTH_USER'</b>&#160; &#1055;&#1088;&#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1080; HTTP-&#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1101;&#1090;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1087;&#1088;&#1080;&#1089;&#1074;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080;&#1084;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;
    </p>
    <p>
      <b>'PHP_AUTH_PW'</b>&#160; &#1055;&#1088;&#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1080; HTTP-&#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1101;&#1090;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1087;&#1088;&#1080;&#1089;&#1074;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;, &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;.
    </p>
    <p>
      <b>'AUTH_TYPE'</b>&#160; &#1055;&#1088;&#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1080; HTTP-&#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1101;&#1090;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1087;&#1088;&#1080;&#1089;&#1074;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1080;&#1087; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;.
    </p>
    <p>
      <b>'PATH_INFO'</b>&#160; &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1083;&#1102;&#1073;&#1086;&#1081; &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; &#1087;&#1091;&#1090;&#1100;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081;&#1089;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077; &#1080;&#1084;&#1077;&#1085;&#1080; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072;, &#1085;&#1086; &#1076;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085;&#1072; &#1077;&#1089;&#1090;&#1100;
    </p>
    <p>
      <b>'ORIG_PATH_INFO'</b>&#160; &#1048;&#1089;&#1093;&#1086;&#1076;&#1085;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; 'PATH_INFO' &#1087;&#1077;&#1088;&#1077;&#1076; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1086;&#1081; PHP.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="$_REQUEST" ID="ID_220028265" CREATED="1548780597618" MODIFIED="1548783056024"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>$_REQUEST</b>&#160;&#8212; &#1055;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; HTTP-&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;. &#1040;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; (array), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; $_GET, $_POST &#1080; $_COOKIE.
    </p>
    <p>
      
    </p>
    <p>
      &#1042; &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1085;&#1085;&#1086;&#1084; &#1085;&#1080;&#1078;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1077; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1085;&#1072; &#1092;&#1086;&#1088;&#1084;&#1072; &#1089; &#1087;&#1086;&#1083;&#1077;&#1084; &#1074;&#1074;&#1086;&#1076;&#1072; &#1080; &#1082;&#1085;&#1086;&#1087;&#1082;&#1086;&#1081; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080;. &#1050;&#1086;&#1075;&#1076;&#1072; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;, &#1085;&#1072;&#1078;&#1072;&#1074; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091; &quot;&#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100;&quot;, &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1092;&#1086;&#1088;&#1084;&#1099; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1074; &#1092;&#1072;&#1081;&#1083;, &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1081; &#1074; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1077; action &#1090;&#1077;&#1075;&#1072; &lt;form&gt;. &#1042; &#1101;&#1090;&#1086;&#1084; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1077;, &#1084;&#1099; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; &#1085;&#1072; &#1101;&#1090;&#1086;&#1090; &#1092;&#1072;&#1081;&#1083; &#1076;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1092;&#1086;&#1088;&#1084;&#1099;. &#1045;&#1089;&#1083;&#1080; &#1074;&#1099; &#1093;&#1086;&#1090;&#1080;&#1090;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1092;&#1072;&#1081;&#1083; PHP &#1076;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1092;&#1086;&#1088;&#1084;&#1099;, &#1079;&#1072;&#1084;&#1077;&#1085;&#1080;&#1090;&#1077; &#1077;&#1075;&#1086; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; &#1092;&#1072;&#1081;&#1083;&#1072; &#1087;&#1086; &#1074;&#1072;&#1096;&#1077;&#1084;&#1091; &#1074;&#1099;&#1073;&#1086;&#1088;&#1091;. &#1047;&#1072;&#1090;&#1077;&#1084; &#1084;&#1099; &#1084;&#1086;&#1078;&#1077;&#1084; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1091;&#1087;&#1077;&#1088;&#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; $_REQUEST &#1076;&#1083;&#1103; &#1089;&#1073;&#1086;&#1088;&#1072; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1083;&#1103; &#1074;&#1074;&#1086;&#1076;&#1072;:
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;form method=&quot;post&quot; action=&quot;&lt;?php echo $_SERVER['PHP_SELF'];?&gt;&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;Name: &lt;input type=&quot;text&quot; name=&quot;fname&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;input type=&quot;submit&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/form&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">if ($_SERVER[&quot;REQUEST_METHOD&quot;] == &quot;POST&quot;) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;// collect value of input field </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;$name = htmlspecialchars($_REQUEST['fname']); </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;if (empty($name)) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo &quot;Name is empty&quot;; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;} else { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo $name; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;} </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="$_POST" ID="ID_1786865873" CREATED="1548780606469" MODIFIED="1548783427138"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>$_POST</b>&#160;&#8212; &#1055;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; HTTP POST. &#1040;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1091; &#1095;&#1077;&#1088;&#1077;&#1079; HTTP &#1084;&#1077;&#1090;&#1086;&#1076;&#1086;&#1084; POST &#1087;&#1088;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; application/x-www-form-urlencoded &#1080;&#1083;&#1080; multipart/form-data &#1074; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1077; Content-Type &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; HTTP.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1088;&#1080;&#1084;&#1077;&#1088;</b>. &#1055;&#1086;&#1076;&#1088;&#1072;&#1079;&#1091;&#1084;&#1077;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083; &#1095;&#1077;&#1088;&#1077;&#1079; POST name=&#1048;&#1074;&#1072;&#1085;. &#1056;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1086;&#1084; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1095;&#1090;&#1086;-&#1090;&#1086; &#1087;&#1086;&#1076;&#1086;&#1073;&#1085;&#1086;&#1077;: &#1055;&#1088;&#1080;&#1074;&#1077;&#1090;, &#1048;&#1074;&#1072;&#1085;!
    </p>
    <p>
      <font color="#008000">echo '&#1055;&#1088;&#1080;&#1074;&#1077;&#1090; ' . htmlspecialchars($_POST[&quot;name&quot;]) . '!';</font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="$_GET" ID="ID_1254340377" CREATED="1548780624921" MODIFIED="1548783427118"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>$_GET</b>&#160;&#8212; &#1055;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; HTTP GET. &#1040;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1091; &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; URL (&#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1077; &#1090;&#1072;&#1082;&#1078;&#1077; &#1082;&#1072;&#1082; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;). &#1052;&#1072;&#1089;&#1089;&#1080;&#1074; &#1085;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; GET-&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;, &#1072; &#1089;&#1082;&#1086;&#1088;&#1077;&#1077; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; &#1089;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;&#1086;&#1081; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1088;&#1080;&#1084;&#1077;&#1088;</b>. &#1055;&#1086;&#1076;&#1088;&#1072;&#1079;&#1091;&#1084;&#1077;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1074;&#1074;&#1077;&#1083; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077; &#1072;&#1076;&#1088;&#1077;&#1089; http://example.com/?name=&#1048;&#1074;&#1072;&#1085;. &#1056;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1086;&#1084; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1095;&#1090;&#1086;-&#1090;&#1086; &#1087;&#1086;&#1076;&#1086;&#1073;&#1085;&#1086;&#1077;: &#1055;&#1088;&#1080;&#1074;&#1077;&#1090;, &#1048;&#1074;&#1072;&#1085;!
    </p>
    <p>
      <font color="#008000">echo '&#1055;&#1088;&#1080;&#1074;&#1077;&#1090;, ' . htmlspecialchars($_GET[&quot;name&quot;]) . '!';</font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="global Ключевое слово" ID="ID_856896690" CREATED="1548590298440" MODIFIED="1548778781905"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1050;&#1083;&#1102;&#1095;&#1077;&#1074;&#1086;&#1077; &#1089;&#1083;&#1086;&#1074;&#1086; Global</b>&#160; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1080;&#1079; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">$x = 5; </font>
    </p>
    <p>
      <font color="#008000">$y = 10; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">function myTest() { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160; <b>global</b>&#160;$x, $y; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;$y = $x + $y; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">myTest();&#160;&#160;// run function </font>
    </p>
    <p>
      <font color="#008000">echo $y; // output the new value for variable $y </font>
    </p>
    <p>
      <font color="#008000">?&gt;</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Сериализация" FOLDED="true" ID="ID_912829538" CREATED="1549446435013" MODIFIED="1549450045309"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1614659804">&#1043;&#1086;&#1089;&#1090;&#1077;&#1074;&#1072;&#1103; &#1082;&#1085;&#1080;&#1075;&#1072; (&#1055;&#1088;&#1080;&#1084;&#1077;&#1088;) </a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; serialize()</b>&#160;- &#1043;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1091;&#1077;&#1090; &#1087;&#1088;&#1080;&#1075;&#1086;&#1076;&#1085;&#1086;&#1077; &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081;. &#1044;&#1083;&#1103; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086;&#1075;&#1086; php &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072; &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1089;&#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1085;&#1103;&#1090;&#1100; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;. &#1055;&#1086;&#1083;&#1077;&#1079;&#1085;&#1086; &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1080;&#1083;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; PHP &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072;&#1084;&#1080; &#1073;&#1077;&#1079; &#1087;&#1086;&#1090;&#1077;&#1088;&#1080; &#1080;&#1093; &#1090;&#1080;&#1087;&#1072; &#1080; &#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1099;.
    </p>
    <ul>
      <li>
        &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; <b>unserialize()</b>&#160;&#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1101;&#1090;&#1091; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; &#1076;&#1083;&#1103; &#1074;&#1086;&#1089;c&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1077;&#1088;&#1080;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1076;&#1083;&#1103; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090; &#1074;&#1089;&#1077; &#1077;&#1075;&#1086; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077;. &#1052;&#1077;&#1090;&#1086;&#1076;&#1099; &#1074; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1077; &#1085;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1099;, &#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1080;&#1084;&#1103; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072;.
      </li>
      <li>
        &#1063;&#1090;&#1086;&#1073;&#1099; &#1080;&#1084;&#1077;&#1090;&#1100; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; unserialize() &#1076;&#1083;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072; &#1085;&#1091;&#1078;&#1085;&#1086; &#1095;&#1090;&#1086;&#1073;&#1099; &#1082;&#1083;&#1072;&#1089;&#1089; &#1101;&#1090;&#1086;&#1075;&#1086; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072; &#1073;&#1099;&#1083; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085; &#1079;&#1072;&#1088;&#1072;&#1085;&#1077;&#1077;
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="Пример" ID="ID_1573070957" CREATED="1549447470828" MODIFIED="1549447651538"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      ...
    </p>
    <p>
      // &#1060;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1084; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086;&#1089;&#1090;&#1072;
    </p>
    <p>
      <font color="#008000">$posts[1]['date'] = date('d-m-Y'); </font>
    </p>
    <p>
      <font color="#008000">$posts[1]['name'] = $text1; </font>
    </p>
    <p>
      <font color="#008000">$posts[1]['mess'] = $text2; </font>
    </p>
    <p>
      // &#1047;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1074; &#1092;&#1072;&#1081;&#1083; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;, &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091;
    </p>
    <p>
      <font color="#008000">file_put_contents('text.txt', serialize($posts)); </font>
    </p>
    <p>
      <font color="#008000">... </font>
    </p>
    <p>
      // &#1044;&#1077;&#1089;&#1077;&#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1091;&#1077;&#1084; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;
    </p>
    <p>
      <font color="#008000">$array = unserialize($array);</font>
    </p>
  </body>
</html></richcontent>
