<node TEXT="Типы данных" FOLDED="true" ID="ID_1421486067" CREATED="1548582346343" MODIFIED="1657719096917"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        Как правило, программист не устанавливает тип переменной; обычно это делает PHP во время выполнения программы в зависимости от контекста, в котором используется переменная
      </li>
      <li>
        Если вы хотите принудительно изменить тип переменной, вы можете либо <a href="#ID_1406015465">привести</a>&nbsp;&nbsp;переменную, либо использовать функцию <b>settype()</b>.
      </li>
    </ul>
    <p>
      <b>Скалярные типы: </b>
    </p>
    <ul>
      <li>
        boolean
      </li>
      <li>
        integer
      </li>
      <li>
        float (число с плавающей точкой, также известное как double)
      </li>
      <li>
        string
      </li>
    </ul>
    <p>
      <b>Смешанные типы: </b>
    </p>
    <ul>
      <li>
        array
      </li>
      <li>
        object
      </li>
      <li>
        callable
      </li>
      <li>
        iterable
      </li>
    </ul>
    <p>
      <b>Специальные типы: </b>
    </p>
    <ul>
      <li>
        resource
      </li>
      <li>
        NULL
      </li>
    </ul>
    <p>
      <b>Операции с типами переменных</b>
    </p>
    <p>
      <font color="#008000">echo gettype ();&nbsp;</font>&nbsp;# Вернуть тип переменной
    </p>
    <p>
      <font color="#008000">is_string($str);</font>&nbsp;&nbsp;# --&gt; true. Проверяет, является ли переменная строкой. Также проверяем другие типы.
    </p>
    <p>
      <font color="#008000">$int_from_str = (int)$str;</font>&nbsp;&nbsp;# Приведение типов
    </p>
    <p>
      <font color="#008000">isset($x);</font>&nbsp;&nbsp;# Было ли присвоено переменной какое-либо значение
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="# Приведение типов" ID="ID_1406015465" CREATED="1548595876399" MODIFIED="1548598587616"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">$foo = 10;&#160;&#160;&#160;// $foo - &#1101;&#1090;&#1086; &#1094;&#1077;&#1083;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; </font>
    </p>
    <p>
      <font color="#008000">$bar = (boolean) $foo;&#160;&#160;&#160;// $bar - &#1101;&#1090;&#1086; &#1073;&#1091;&#1083;&#1077;&#1074; &#1090;&#1080;&#1087; </font>
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1077; &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1103; &#1090;&#1080;&#1087;&#1086;&#1074;: </b>
    </p>
    <ul>
      <li>
        (int), (integer) - &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1082; integer
      </li>
      <li>
        (bool), (boolean) - &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1082; boolean
      </li>
      <li>
        (float), (double), (real) - &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1082; float
      </li>
      <li>
        (string) - &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1082; string
      </li>
      <li>
        (array) - &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1082; array
      </li>
      <li>
        (object) - &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1082; object
      </li>
      <li>
        (unset) - &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1082; NULL
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="NULL" ID="ID_1236517395" CREATED="1548595609932" MODIFIED="1548690130608"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; NULL</b>&#160; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1073;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; &#1073;&#1077;&#1079; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;. NULL - &#1101;&#1090;&#1086; &#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1080;&#1087;&#1072; null.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1089;&#1095;&#1080;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; NULL, &#1077;&#1089;&#1083;&#1080;: </b>
    </p>
    <ul>
      <li>
        &#1073;&#1099;&#1083;&#1072; <b>&#1087;&#1088;&#1080;&#1089;&#1074;&#1086;&#1077;&#1085;&#1072; &#1082;&#1086;&#1085;&#1089;&#1090;&#1072;&#1085;&#1090;&#1072; NULL</b>
      </li>
      <li>
        &#1077;&#1097;&#1077; <b>&#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &#1087;&#1088;&#1080;&#1089;&#1074;&#1086;&#1077;&#1085;&#1086;</b>&#160; &#1085;&#1080;&#1082;&#1072;&#1082;&#1086;&#1075;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        &#1086;&#1085;&#1072; &#1073;&#1099;&#1083;&#1072; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1072; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; <b>unset()</b>
      </li>
    </ul>
    <p>
      <font color="#008000">$var = NULL;&#160;&#160;&#160;&#160;&#160;&#160; </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Булев" ID="ID_1625041460" CREATED="1548595569818" MODIFIED="1548689795594"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>boolean</b>&#160;&#1074;&#1099;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090; &#1080;&#1089;&#1090;&#1080;&#1085;&#1085;&#1086;&#1089;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;. &#1054;&#1085; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1083;&#1080;&#1073;&#1086; <b>TRUE</b>, &#1083;&#1080;&#1073;&#1086; <b>FALSE</b>.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">$foo = true;&#160;&#160;// &#1087;&#1088;&#1080;&#1089;&#1074;&#1086;&#1080;&#1090;&#1100; $foo &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; TRUE </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Массивы" FOLDED="true" ID="ID_849975691" CREATED="1548595581813" MODIFIED="1549447668434"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1104368640">array()</a><b>&#160; <a href="#ID_1573070957">&#1057;&#1077;&#1088;&#1080;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;</a></b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1072;&#1089;&#1089;&#1080;&#1074; &#1074; PHP</b>&#160;- &#1101;&#1090;&#1086; &#1091;&#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1095;&#1077;&#1085;&#1085;&#1086;&#1077; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1084;&#1077;&#1078;&#1076;&#1091; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1080; &#1082;&#1083;&#1102;&#1095;&#1086;&#1084;
    </p>
    <ul>
      <li>
        &#1058;&#1072;&#1082; &#1082;&#1072;&#1082; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; PHP, &#1084;&#1086;&#1078;&#1085;&#1086; &#1090;&#1072;&#1082;&#1078;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1076;&#1077;&#1088;&#1077;&#1074;&#1100;&#1103; &#1080; &#1084;&#1085;&#1086;&#1075;&#1086;&#1084;&#1077;&#1088;&#1085;&#1099;&#1077; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1099;.
      </li>
      <li>
        &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; <b>array()</b>
      </li>
    </ul>
    <p>
      <b>&#1058;&#1080;&#1087;&#1099; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;. </b>&#1052;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1089;&#1084;&#1077;&#1097;&#1072;&#1085;&#1085;&#1099;&#1077;
    </p>
    <ul>
      <li>
        <b>&#1048;&#1085;&#1076;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077;</b>&#160; - &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1099; &#1089; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1099;&#1084; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1086;&#1084;
      </li>
      <li>
        <b>&#1040;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1077;</b>&#160; - &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1099; &#1089; &#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1082;&#1083;&#1102;&#1095;&#1072;&#1084;&#1080;
      </li>
      <li>
        <b>&#1052;&#1085;&#1086;&#1075;&#1086;&#1084;&#1077;&#1088;&#1085;&#1099;&#1077;</b>&#160; &#160;- &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1099;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1077; &#1086;&#1076;&#1080;&#1085; &#1080;&#1083;&#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;
      </li>
    </ul>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 60%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$cars = array(&quot;Volvo&quot;,&quot;BMW&quot;,&quot;Toyota&quot;); </font>
          </p>
        </td>
        <td valign="top" style="width: 40%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">array( </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;key&#160;&#160;=&gt; value, </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;key2 =&gt; value2, </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;key3 =&gt; value3, </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;... </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;) </font>
          </p>
        </td>
      </tr>
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$arr = array( </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&quot;foo&quot; =&gt; &quot;bar&quot;, </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&quot;bar&quot; =&gt; &quot;foo&quot;, </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>// &#1053;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; PHP 5.4</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$arr = [ </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&quot;foo&quot; =&gt; &quot;bar&quot;, </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&quot;bar&quot; =&gt; &quot;foo&quot;, </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">]; </font>
          </p>
        </td>
      </tr>
    </table>
    <p>
      
    </p>
    <p>
      <font color="#008000">echo $arr[0];</font>&#160;&#160;# &#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1085;&#1091;&#1083;&#1077;&#1074;&#1086;&#1081; &#1101;&#1083;. &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;
    </p>
    <p>
      <font color="#008000">$arr[] = 5;</font>&#160;&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;
    </p>
    <p>
      <font color="#008000">$arr[10] = 5</font>;&#160;&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072; &#1089; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1086;&#1084; 10
    </p>
    <p>
      <font color="#008000">$arr = [<b>1=&gt;</b>&quot;Volvo&quot;,&quot;BMW&quot;,&quot;Toyota&quot;]</font>&#160;&#160;# &#1048;&#1085;&#1076;&#1077;&#1082;&#1089; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072; &#1085;&#1072;&#1095;&#1072;&#1090;&#1100; &#1089; 1, &#1072; &#1085;&#1077; &#1089; 0
    </p>
    <p>
      <font color="#008000">echo <b>count</b>($arr); </font>&#160;# &#1055;&#1086;&#1089;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100; &#1095;&#1080;&#1089;&#1083;&#1086; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;
    </p>
    <p>
      <font color="#008000">print_r($arr);</font>&#160;&#160;# &#1042;&#1099;&#1074;&#1086;&#1076; (&#1082;&#1088;&#1072;&#1090;&#1082;&#1080;&#1081;) &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;
    </p>
    <p>
      <font color="#008000">var_dump($cars);</font>&#160;&#160;# &#1042;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1090;&#1080;&#1087; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#008000">unset($arr[10])</font>&#160;&#160;# &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; 10 &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;
    </p>
