<node TEXT="# Индексированные" ID="ID_13159969" CREATED="1548765308538" MODIFIED="1549305510277"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1048;&#1085;&#1076;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;</b>&#160; - &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1089; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1099;&#1084; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1086;&#1084;
    </p>
    <p>
      
    </p>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$cars = array(&quot;Volvo&quot;, &quot;BMW&quot;, &quot;Toyota&quot;); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            # &#1080;&#1083;&#1080; &#1082;&#1072;&#1082; &#1074;&#1086; &#1074;&#1090;&#1086;&#1088;&#1086;&#1084; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1077;
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$cars<b>[0]</b>&#160;= &quot;Volvo&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$cars<b>[1]</b>&#160;= &quot;BMW&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$cars<b>[2]</b>&#160;= &quot;Toyota&quot;; </font>
          </p>
        </td>
      </tr>
    </table>
    <p>
      <font color="#008000">echo &quot;$cars<b>[0]</b>&#160;$cars<b>[1] </b>$cars<b>[2]</b>&quot;;&#160; </font># --&gt; Volvo BMW Toyota
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1076;&#1089;&#1095;&#1077;&#1090; &#1076;&#1083;&#1080;&#1085;&#1099; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;. count()</b>
    </p>
    <p>
      <font color="#008000">$cars = array(&quot;Volvo&quot;, &quot;BMW&quot;, &quot;Toyota&quot;); </font>
    </p>
    <p>
      <font color="#008000">echo <b>count</b>($cars);</font>&#160;&#160;# --&gt; 3
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1062;&#1080;&#1082;&#1083; &#1095;&#1077;&#1088;&#1077;&#1079; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;</b>
    </p>
    <p>
      <font color="#008000">$cars = array(&quot;Volvo&quot;, &quot;BMW&quot;, &quot;Toyota&quot;); </font>
    </p>
    <p>
      <font color="#008000">$arrlength = count($cars); </font>
    </p>
    <p>
      <font color="#008000"><b>for</b>($x = 0; $x &lt; $arrlength; $x++) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo $cars[$x]; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;\n&quot;; </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="# Ассоциативные" ID="ID_1723046969" CREATED="1548765323717" MODIFIED="1549305522538"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1040;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;</b>&#160; - &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1089; &#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1082;&#1083;&#1102;&#1095;&#1072;&#1084;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;</b>
    </p>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 60%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$age = array(&quot;Peter&quot;=&gt;&quot;35&quot;, &quot;Ben&quot;=&gt;&quot;37&quot;, &quot;Joe&quot;=&gt;&quot;43&quot;);</font>
          </p>
        </td>
        <td valign="top" style="width: 40%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$age['Peter'] = &quot;35&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$age['Ben'] = &quot;37&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$age['Joe'] = &quot;43&quot;;</font>
          </p>
        </td>
      </tr>
    </table>
    <p style="text-align: left">
      <font color="#008000">echo &quot;Peter is &quot; . $age['Peter'] . &quot; years old.&quot;;&#160; </font># Peter is 35 years old.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1062;&#1080;&#1082;&#1083; &#1095;&#1077;&#1088;&#1077;&#1079; &#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;</b>
    </p>
    <p>
      <font color="#008000">$age = array(&quot;Peter&quot;=&gt;&quot;35&quot;, &quot;Ben&quot;=&gt;&quot;37&quot;, &quot;Joe&quot;=&gt;&quot;43&quot;); </font>
    </p>
    <p>
      <font color="#008000"><b>foreach</b>($age <b>as</b>&#160;$x =&gt; $x_value) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Key=&quot; . $x . &quot;, Value=&quot; . $x_value; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;\n&quot;; </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="# Многомерные" ID="ID_203931669" CREATED="1548765332846" MODIFIED="1549304305455"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1085;&#1086;&#1075;&#1086;&#1084;&#1077;&#1088;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;</b>&#160;&#160;- &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081; &#1086;&#1076;&#1080;&#1085; &#1080;&#1083;&#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">$cars = array </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;( </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;array(&quot;Volvo&quot;,22,18), </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;array(&quot;BMW&quot;,15,13), </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;); </font>
    </p>
    <p>
      <font color="#008000">echo $cars[0][0].&quot;: In stock: &quot;.$cars[0][1].&quot;, sold: &quot;.$cars[0][2].&quot;.\n&quot;; </font>
    </p>
    <p>
      <font color="#008000">echo $cars[1][0].&quot;: In stock: &quot;.$cars[1][1].&quot;, sold: &quot;.$cars[1][2].&quot;.\n&quot;;</font>
    </p>
    <p>
      ---------&gt;
    </p>
    <p>
      <font size="1">Volvo: In stock: 22, sold: 18. </font>
    </p>
    <p>
      <font size="1">BMW: In stock: 15, sold: 13.</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Сортировка массивов" ID="ID_593291256" CREATED="1548770895474" MODIFIED="1549447304755"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;</b>
    </p>
    <ul>
      <li>
        &#1042; &#1086;&#1076;&#1085;&#1080;&#1093; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103;&#1093; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1099; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; <b>&#1087;&#1086; &#1082;&#1083;&#1102;&#1095;&#1072;&#1084; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;</b>, &#1074; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; - <b>&#1087;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;&#1084;</b>
      </li>
      <li>
        &#1042; &#1082;&#1072;&#1082;&#1080;&#1093;-&#1090;&#1086; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103;&#1093; &#1089;&#1074;&#1103;&#1079;&#1100; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1083;&#1102;&#1095;&#1072;&#1084;&#1080; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103;, &#1074; &#1082;&#1072;&#1082;&#1080;&#1093;-&#1090;&#1086; &#1085;&#1077;&#1090;. &#1069;&#1090;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1082; &#1090;&#1086;&#1084;&#1091;, &#1095;&#1090;&#1086; &#1082;&#1083;&#1102;&#1095;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1089;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; (0, 1, 2, ...)
      </li>
      <li>
        <b>&#1056;&#1072;&#1079;&#1083;&#1080;&#1095;&#1080;&#1103; &#1074; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080;</b>: &#1072;&#1083;&#1092;&#1072;&#1074;&#1080;&#1090;&#1085;&#1099;&#1081;, &#1074;&#1086;&#1079;&#1088;&#1072;&#1089;&#1090;&#1072;&#1102;&#1097;&#1080;&#1081;, &#1091;&#1073;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081;, &#1095;&#1080;&#1089;&#1083;&#1086;&#1074;&#1086;&#1081;, &#1077;&#1089;&#1090;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1081;, &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1099;&#1081; &#1080;&#1083;&#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;
      </li>
      <li>
        &#1042;&#1089;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; <b>&#1084;&#1086;&#1076;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1091;&#1102;&#1090;</b>&#160;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;, &#1072; &#1085;&#1077; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1102;&#1090; &#1086;&#1090;&#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1091;&#1102; &#1082;&#1086;&#1087;&#1080;&#1102;
      </li>
    </ul>
    <p>
      <b>* - &#1057;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090; &#1089;&#1074;&#1103;&#1079;&#1100; &#1082;&#1083;&#1102;&#1095;-&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;</b>&#160; (<b>&#1044;&#1040; / &#1053;&#1045;&#1058;</b>)
    </p>
    <p>
      <a href="#ID_33851721">sort()</a>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086; &#1074;&#1086;&#1079;&#1088;&#1072;&#1089;&#1090;&#1072;&#1085;&#1080;&#1102; (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;). &#1053;&#1045;&#1058;
    </p>
    <p>
      <a href="#ID_529177125">rsort()</a>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086; &#1091;&#1073;&#1099;&#1074;&#1072;&#1085;&#1080;&#1102; (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;). &#1053;&#1045;&#1058;
    </p>
    <p>
      <a href="#ID_1961797723">asort()</a>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086; &#1074;&#1086;&#1079;&#1088;&#1072;&#1089;&#1090;&#1072;&#1085;&#1080;&#1102; (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;). &#1044;&#1040;
    </p>
    <p>
      <a href="#ID_1142870260">ksort()</a>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086; &#1074;&#1086;&#1079;&#1088;&#1072;&#1089;&#1090;&#1072;&#1085;&#1080;&#1102; (&#1082;&#1083;&#1102;&#1095;&#1077;&#1081;). &#1044;&#1040;
    </p>
    <p>
      <a href="#ID_514785642">arsort()</a>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086; &#1091;&#1073;&#1099;&#1074;&#1072;&#1085;&#1080;&#1102; (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;). &#1044;&#1040;
    </p>
    <p>
      <a href="#ID_1477787308">krsort()</a>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086; &#1091;&#1073;&#1099;&#1074;&#1072;&#1085;&#1080;&#1102; (&#1082;&#1083;&#1102;&#1095;&#1077;&#1081;). &#1044;&#1040;
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Объекты" ID="ID_1806952064" CREATED="1548595598656" MODIFIED="1548765306904"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_958919816">&#1050;&#1083;&#1072;&#1089;&#1089;&#1099; &#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1054;&#1073;&#1098;&#1077;&#1082;&#1090;</b>&#160;- &#1101;&#1090;&#1086; &#1090;&#1080;&#1087; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1080; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1090;&#1086;&#1084;, &#1082;&#1072;&#1082; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1101;&#1090;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;.
    </p>
    <ul>
      <li>
        &#1044;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1085;&#1086;&#1074;&#1086;&#1075;&#1086; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1081;&#1090;&#1077; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; new, &#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1097;&#1077;&#1077; &#1074; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1101;&#1082;&#1079;&#1077;&#1084;&#1087;&#1083;&#1103;&#1088; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072;
      </li>
      <li>
        &#1054;&#1073;&#1098;&#1077;&#1082;&#1090; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1103;&#1074;&#1085;&#1086; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;
      </li>
      <li>
        &#1057;&#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1084;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1086;&#1073;&#1098;&#1103;&#1074;&#1080;&#1090;&#1100;<b>&#160;&#1082;&#1083;&#1072;&#1089;&#1089; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072; (</b>&#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1086;&#1077; &#1089;&#1083;&#1086;&#1074;&#1086; class). <b>&#1050;&#1083;&#1072;&#1089;&#1089;</b>&#160;- &#1101;&#1090;&#1086; &#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1080; &#1084;&#1077;&#1090;&#1086;&#1076;&#1099;
      </li>
    </ul>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">class foo&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; </font>// &#1054;&#1073;&#1098;&#1103;&#1074;&#1080;&#1090;&#1100; &#1082;&#1083;&#1072;&#1089;&#1089; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;
    </p>
    <p>
      <font color="#008000">{ </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;function do_foo() </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;{ </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo &quot;&#1050;&#1086;&#1076; foo.&quot;; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;} </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">$bar = new foo;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; </font>// &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;
    </p>
    <p>
      <font color="#008000">$bar-&gt;do_foo();&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; </font>// --&gt; &#1050;&#1086;&#1076; foo.
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Ресурс" ID="ID_519026597" CREATED="1548595624144" MODIFIED="1548689413408"><richcontent TYPE="NOTE">
