</html></richcontent>
</node>
<node TEXT="Строки" ID="ID_1407614579" CREATED="1548595469397" MODIFIED="1549365318473"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1642111380">&#1057;&#1090;&#1088;&#1086;&#1082;&#1086;&#1074;&#1099;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1099;</a>&#160;&#160;<a href="#ID_1527980780">echo</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1090;&#1088;&#1086;&#1082;&#1072; (&#1090;&#1080;&#1087; string)</b>&#160;- &#1101;&#1090;&#1086; &#1085;&#1072;&#1073;&#1086;&#1088; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074;, &#1075;&#1076;&#1077; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083; - &#1101;&#1090;&#1086; &#1090;&#1086; &#1078;&#1077; &#1089;&#1072;&#1084;&#1086;&#1077;, &#1095;&#1090;&#1086; &#1080; &#1073;&#1072;&#1081;&#1090;.
    </p>
    <ul>
      <li>
        &#1052;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; <b>&#1086;&#1076;&#1080;&#1085;&#1072;&#1088;&#1085;&#1099;&#1077; </b>(&#1085;&#1077; &#1091;&#1095;&#1080;&#1090;. &#1089;&#1087;&#1077;&#1094;&#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1099;)&#160;&#1080;&#1083;&#1080; <b>&#1076;&#1074;&#1086;&#1081;&#1085;&#1099;&#1077; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1080;</b>
      </li>
      <li>
        &#1063;&#1090;&#1086;&#1073;&#1099; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; <b>&#1086;&#1076;&#1080;&#1085;&#1072;&#1088;&#1085;&#1091;&#1102; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1091;</b>&#160;&#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;, &#1087;&#1088;&#1086;&#1101;&#1082;&#1088;&#1072;&#1085;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1077;&#1077; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1084; &#1089;&#1083;&#1077;&#1096;&#1077;&#1084; (\). &#1045;&#1089;&#1083;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089;&#1072;&#1084; <b>&#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1089;&#1083;&#1077;&#1096;</b>, &#1087;&#1088;&#1086;&#1076;&#1091;&#1073;&#1083;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1077;&#1075;&#1086; (\\)
      </li>
      <li>
        <b>&#1055;&#1077;&#1088;&#1074;&#1072;&#1103; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1103; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072; </b>&#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; -<b>&#160;0 (&#1085;&#1077; 1)</b>.
      </li>
      <li>
        &#1057;&#1090;&#1088;&#1086;&#1082;&#1080; &#1079;&#1072;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1074; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1080; <b><font color="#008000">$x = &quot;3&quot;;</font></b>
      </li>
    </ul>
    <p>
      <b>&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1077; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074;</b>&#160;(&#1077;&#1089;&#1083;&#1080; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072; &#1079;&#1072;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1072; &#1074; <b>&#1076;&#1074;&#1086;&#1081;&#1085;&#1099;&#1077; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1080;</b>)
    </p>
    <p>
      <font color="#008000">echo <b>&quot;</b>&#1041;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1086; <b>\n</b>&#160;&#1074; &#1076;&#1074;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;<b>&quot;;</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">echo <b>'</b>&#1053;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1086; \n &#1074; &#1076;&#1074;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;<b>';</b></font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1077;&#1088;&#1077;&#1085;&#1086;&#1089; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;.</b>&#160;&#1045;&#1089;&#1083;&#1080; &#1074;&#1099;&#1074;&#1086;&#1076; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; - <b>&lt;br&gt;</b>, &#1077;&#1089;&#1083;&#1080; &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100; &#1080;&#1083;&#1080; &#1092;&#1072;&#1081;&#1083; - <b>\n</b>
    </p>
    <ul>
      <li>
        <b>&lt;br/&gt;</b>&#160;&#1080;&#1083;&#1080; <b>&lt;br&gt;</b>&#160;&#1085;&#1086;&#1074;&#1072;&#1103; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072;
      </li>
      <li>
        <b>\n</b>&#160;&#1085;&#1086;&#1074;&#1072;&#1103; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072; (LF &#1080;&#1083;&#1080; 0x0A (10) &#1074; ASCII)
      </li>
    </ul>
    <ul>
      <li>
        <b>\r</b>&#160;&#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090; &#1082;&#1072;&#1088;&#1077;&#1090;&#1082;&#1080; (CR &#1080;&#1083;&#1080; 0x0D (13) &#1074; ASCII)
      </li>
      <li>
        <b>\t</b>&#160;&#1075;&#1086;&#1088;&#1080;&#1079;&#1086;&#1085;&#1090;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1090;&#1072;&#1073;&#1091;&#1083;&#1103;&#1094;&#1080;&#1103; (HT &#1080;&#1083;&#1080; 0x09 (9) &#1074; ASCII)
      </li>
      <li>
        <b>\v</b>&#160;&#1074;&#1077;&#1088;&#1090;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1090;&#1072;&#1073;&#1091;&#1083;&#1103;&#1094;&#1080;&#1103; (VT &#1080;&#1083;&#1080; 0x0B (11) &#1074; ASCII) (&#1089; PHP 5.2.5)
      </li>
      <li>
        <b>\e</b>&#160;escape-&#1079;&#1085;&#1072;&#1082; (ESC &#1080;&#1083;&#1080; 0x1B (27) &#1074; ASCII) (&#1089; PHP 5.4.4)
      </li>
      <li>
        <b>\f</b>&#160;&#1087;&#1086;&#1076;&#1072;&#1095;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; (FF &#1080;&#1083;&#1080; 0x0C (12) &#1074; ASCII) (&#1089; PHP 5.2.5)
      </li>
      <li>
        <b>\\</b>&#160;&#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1072;&#1103; &#1082;&#1086;&#1089;&#1072;&#1103; &#1095;&#1077;&#1088;&#1090;&#1072;
      </li>
      <li>
        <b>\$</b>&#160;&#1079;&#1085;&#1072;&#1082; &#1076;&#1086;&#1083;&#1083;&#1072;&#1088;&#1072;
      </li>
      <li>
        <b>\&quot;</b>&#160;&#1076;&#1074;&#1086;&#1081;&#1085;&#1072;&#1103; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1072;
      </li>
    </ul>
    <p>
      <font color="#008000">$str = &quot;from&quot;; </font>
    </p>
    <p>
      <font color="#008000">echo $str{1};</font>&#160;&#160;# 1 &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;. &#1042;&#1099;&#1074;&#1086;&#1076;&#160;&#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072; (&#1073;&#1072;&#1081;&#1090;&#1072;) &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077;
    </p>
    <p>
      <font color="#008000">echo $str{strlen($str)-3};</font>&#160;&#160;# 2 &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;. &#1042;&#1099;&#1074;&#1086;&#1076;&#160;&#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072; (&#1073;&#1072;&#1081;&#1090;&#1072;) &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; &#1076;&#1083;&#1080;&#1085;&#1091; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;
    </p>
    <p>
      <font color="#008000">echo $str{strlen($str)-1} = 'g';</font>&#160;&#160;# &#1047;&#1072;&#1084;&#1077;&#1085;&#1072;&#160;&#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1075;&#1086; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;
    </p>
    <p>
      <font color="#008000">echo strlen(&quot;Hello world!&quot;);</font>&#160;&#160;# &#1044;&#1083;&#1080;&#1085;&#1072;&#160;&#1089;&#1090;&#1088;&#1086;&#1082;&#1080;. --&gt; 12
    </p>
    <p>
      <font color="#008000">echo str_word_count(&quot;Hello world!&quot;);</font>&#160;&#160;#&#160;&#160;&#1063;&#1080;&#1089;&#1083;&#1086; &#1089;&#1083;&#1086;&#1074;&#160;&#1089;&#1090;&#1088;&#1086;&#1082;&#1080;. --&gt; 2
    </p>
    <p>
      <font color="#008000">echo strrev(&quot;Hello world!&quot;);</font>&#160;&#160;#&#160;&#160;&#1056;&#1080;&#1074;&#1077;&#1088;&#1089; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;. --&gt; !dlrow olleH
    </p>
    <p>
      <font color="#008000">echo strpos(&quot;Hello world!&quot;, &quot;world&quot;);</font>&#160;&#160;# &#1055;&#1086;&#1080;&#1089;&#1082;&#160;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1090;&#1077;&#1082;&#1089;&#1090;&#1072; &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077;. &#1042;&#1099;&#1074;&#1086;&#1076; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1080;. --&gt; 6
    </p>
    <p>
      <font color="#008000">echo str_replace(&quot;world&quot;, &quot;Dolly&quot;, &quot;Hello world!&quot;);</font>&#160;&#160;# &#1047;&#1072;&#1084;&#1077;&#1085;&#1072;&#160;&#1090;&#1077;&#1082;&#1089;&#1090;&#1072;. --&gt; Hello Dolly!
    </p>
    <p>
      <font color="#008000">echo htmlspecialchars();</font>&#160;&#160;# &#1055;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1077;&#1090; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1099; &#1074; HTML-&#1089;&#1091;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080;. &amp;, &quot;, ', &lt;, &gt;
    </p>
    <p>
      <font color="#008000">echo nl2br();</font>&#160;&#160;# &#1042;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; HTML-&#1082;&#1086;&#1076; &#1088;&#1072;&#1079;&#1088;&#1099;&#1074;&#1072; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076; &#1082;&#1072;&#1078;&#1076;&#1099;&#1084; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1086;&#1084; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Числа целые" ID="ID_1288134974" CREATED="1548595499561" MODIFIED="1548689249673"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Integer</b>&#160;- &#1101;&#1090;&#1086; &#1095;&#1080;&#1089;&#1083;&#1086; &#1080;&#1079; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1072; ? = {..., -2, -1, 0, 1, 2, ...}.
    </p>
    <ul>
      <li>
        &#1063;&#1080;&#1089;&#1083;&#1072; &#1085;&#1077; &#1079;&#1072;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1074; &#1082;&#1072;&#1074;&#1099;&#1095;&#1082;&#1080; <b><font color="#008000">$x = 3;</font></b>
      </li>
      <li>
        &#1062;&#1077;&#1083;&#1099;&#1077; &#1095;&#1080;&#1089;&#1083;&#1072; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1079;&#1072;&#1076;&#1072;&#1085;&#1099; &#1074; &#1090;&#1088;&#1077;&#1093; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1072;&#1093;:

        <ul>
          <li>
            &#1076;&#1077;&#1089;&#1103;&#1090;&#1080;&#1095;&#1085;&#1099;&#1081; (&#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; 10)
          </li>
          <li>
            &#1096;&#1077;&#1089;&#1090;&#1085;&#1072;&#1076;&#1094;&#1072;&#1090;&#1077;&#1088;&#1080;&#1095;&#1085;&#1099;&#1081; (&#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; 16 &#1089; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;&#1086;&#1084; 0x)
          </li>
          <li>
            &#1074;&#1086;&#1089;&#1100;&#1084;&#1077;&#1088;&#1080;&#1095;&#1085;&#1099;&#1081; (&#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; 8 &#1089; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;&#1086;&#1084; 0)
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <font color="#008000">&lt;?php&#160; </font>
    </p>
    <p>
      <font color="#008000">$x = 5985; </font>
    </p>
    <p>
      <font color="#008000">var_dump($x);</font>&#160;&#160;# --&gt; int(5985). &#1042;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081;
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Числа с плавающий точкой" ID="ID_1868258170" CREATED="1548595503525" MODIFIED="1548618522188"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1063;&#1080;&#1089;&#1083;&#1072; &#1089; &#1087;&#1083;&#1072;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1090;&#1086;&#1095;&#1082;&#1086;&#1081;</b>&#160; (&#1090;&#1072;&#1082;&#1078;&#1077; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1077; &#1082;&#1072;&#1082; &quot;<b>float</b>&quot;, &quot;double&quot; &#1080;&#1083;&#1080; &quot;real&quot;) &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1099; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084;&#1080; &#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;&#1072;&#1084;&#1080;:
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">$a = 1.234; </font>
    </p>
    <p>
      <font color="#008000">$b = 1.2e3; </font>
    </p>
    <p>
      <font color="#008000">$c = 7E-10; </font>
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Управляющие конструкции" FOLDED="true" ID="ID_1005477783" CREATED="1548582375145" MODIFIED="1658050856315"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>break</b>&nbsp;- прерывает выполнение текущей структуры for, foreach, while, do-while или switch. Значение по умолчанию 1, только ближайшая структура будет прервана.
    </p>
    <p>
      
    </p>
    <p>
      <b>continue</b>&nbsp;- используется внутри циклических структур для пропуска оставшейся части текущей итерации цикла и, при соблюдении условий, начала следующей итерации. Значением по умолчанию является 1, при которой пропускается оставшаяся часть текущего цикла
    </p>
    <p>
      
    </p>
    <p>
      --------------------
    </p>
    <p>
      
    </p>
    <p>
      declare
    </p>
    <p>
      return
    </p>
    <p>
      require
    </p>
    <p>
      include
    </p>
    <p>
      require_once
    </p>
    <p>
      include_once
    </p>
    <p>
      goto
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="if...elseif...else" FOLDED="true" ID="ID_716749121" CREATED="1548681290743" MODIFIED="1569485222328"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1911037030">switch</a>&#160; <a href="#ID_500386631">&#1083;&#1086;&#1075;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1099;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1077;&#1090;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;</b>
    </p>
    <p>
      
    </p>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p>
            <b>&#1057;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089; if</b>
          </p>
          <p>
            <font color="#008000"><b>if</b>&#160;(&#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077;) { </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;&#1082;&#1086;&#1076; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; <b>&#1080;&#1089;&#1090;&#1080;&#1085;&#1085;&#1086;</b>; </font>
          </p>
          <p>
            <font color="#008000">} </font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p>
            <font color="#008000">$t = date(&quot;H&quot;); </font>
          </p>
          <p>
            <font color="#008000"><b>if</b>&#160;($t &lt; &quot;20&quot;) { </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Have a good day!&quot;; </font>
          </p>
          <p>
            <font color="#008000">}</font>
          </p>
        </td>
      </tr>
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p>
            <b>&#1057;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089; if...else</b>
          </p>
          <p>
            <font color="#008000"><b>if</b>&#160;(&#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077;) { </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;&#1082;&#1086;&#1076; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; <b>&#1080;&#1089;&#1090;&#1080;&#1085;&#1085;&#1086;</b>; </font>
          </p>
          <p>
            <font color="#008000">} <b>else</b>&#160;{ </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;&#1082;&#1086;&#1076; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; <b>&#1083;&#1086;&#1078;&#1085;&#1086;</b>; </font>
          </p>
          <p>
            <font color="#008000">} </font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p>
            <font color="#008000">$t = date(&quot;H&quot;); </font>
          </p>
          <p>
            <font color="#008000"><b>if</b>&#160;($t &lt; &quot;20&quot;) { </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Have a good day!&quot;; </font>
          </p>
          <p>
            <font color="#008000">} <b>else</b>&#160;{ </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Have a good night!&quot;; </font>
          </p>
          <p>
            <font color="#008000">}</font>
          </p>
        </td>
      </tr>
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p>
            <b>&#1057;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089; if...elseif...else</b>
          </p>
          <p>
            <font color="#008000"><b>if</b>&#160;(&#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077;) { </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;&#1082;&#1086;&#1076; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; <b>&#1080;&#1089;&#1090;&#1080;&#1085;&#1085;&#1086;</b>; </font>
          </p>
          <p>
            <font color="#008000">} <b>elseif</b>&#160;(&#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077;) { </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;&#1082;&#1086;&#1076; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; <b>&#1080;&#1089;&#1090;&#1080;&#1085;&#1085;&#1086;</b>; </font>
          </p>
          <p>
            <font color="#008000">} <b>else</b>&#160;{ </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;&#1082;&#1086;&#1076; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; <b>&#1083;&#1086;&#1078;&#1085;&#1086;</b>; </font>
          </p>
          <p>
            <font color="#008000">}</font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p>
            <font color="#008000">$t = date(&quot;H&quot;); </font>
          </p>
          <p>
            <font color="#008000"><b>if</b>&#160;($t &lt; &quot;10&quot;) { </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Have a good morning!&quot;; </font>
          </p>
          <p>
            <font color="#008000">} <b>elseif</b>&#160;($t &lt; &quot;20&quot;) { </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Have a good day!&quot;; </font>
          </p>
          <p>
            <font color="#008000">} <b>else</b>&#160;{ </font>
          </p>
          <p>
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Have a good night!&quot;; </font>
          </p>
          <p>
            <font color="#008000">}</font>
          </p>
        </td>
      </tr>
    </table>
    <p>
      
    </p>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 30%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">if ($weather_is_good) </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;&#1048;&#1076;&#1091; &#1075;&#1091;&#1083;&#1103;&#1090;&#1100;&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">else </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;&#1057;&#1080;&#1078;&#1091; &#1076;&#1086;&#1084;&#1072;&quot;;</font>
          </p>
        </td>
        <td valign="top" style="width: 70%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b><a href="#ID_1049361472">&#1058;&#1077;&#1088;&#1085;&#1072;&#1088;&#1085;&#1099;&#1081; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;</a>&#160; (&#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1089;&#1072;&#1093;&#1072;&#1088;)</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">echo ($weather_is_good) <b>?</b>&#160;&quot;&#1048;&#1076;&#1091; &#1075;&#1091;&#1083;&#1103;&#1090;&#1100;&quot; <b>:</b>&#160;&quot;&#1057;&#1080;&#1078;&#1091; &#1076;&#1086;&#1084;&#1072;&quot;;</font>
          </p>
        </td>
      </tr>
    </table>
  </body>
</html></richcontent>
<node TEXT="Альтернативный синтаксис (endif)" ID="ID_130695495" CREATED="1548695883242" MODIFIED="1548748022685"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1042; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1092;&#1086;&#1088;&#1084;&#1086;&#1081; &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;&#1072; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077;
    </p>
    <ul>
      <li>
        <b>&#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1092;&#1080;&#1075;&#1091;&#1088;&#1085;&#1086;&#1081; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080;</b>&#160;(<b><font size="4">{</font></b><font size="2">)</font>&#160;&#1085;&#1072; &#1076;&#1074;&#1086;&#1077;&#1090;&#1086;&#1095;&#1080;&#1077; (<b><font size="4">:</font></b>)
      </li>
      <li>
        &#1079;&#1072;&#1082;&#1088;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080; (<b><font size="4">}</font></b>)&#1085;&#1072;
      </li>
    </ul>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">if ($a == 5)</font><font color="#008000" size="4"><b>:</b></font><font color="#008000">&#160;</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;a &#1088;&#1072;&#1074;&#1085;&#1086; 5&quot;; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;...&quot;; </font>
    </p>
    <p>
      <font color="#008000">elseif ($a == 6)</font><font color="#008000" size="4"><b>:</b></font><font color="#008000">&#160;</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;a &#1088;&#1072;&#1074;&#1085;&#1086; 6&quot;; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;!!!&quot;; </font>
    </p>
    <p>
      <font color="#008000">else</font><font color="#008000" size="4"><b>:</b></font><font color="#008000">&#160;</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;a &#1085;&#1077; &#1088;&#1072;&#1074;&#1085;&#1086; &#1085;&#1080; 5 &#1085;&#1080; 6&quot;; </font>
    </p>
    <p>
      <font color="#008000" size="4"><b>endif;</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="switch" FOLDED="true" ID="ID_1911037030" CREATED="1548681370857" MODIFIED="1549307281293"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_716749121">if...elseif...else</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1054;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; switch</b>&#160; &#1087;&#1086;&#1093;&#1086;&#1078; &#1085;&#1072; &#1088;&#1103;&#1076; <b>&#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; IF</b>&#160;&#1089; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1099;&#1084; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077;&#1084;. &#1042;&#1086; &#1084;&#1085;&#1086;&#1075;&#1080;&#1093; &#1089;&#1083;&#1091;&#1095;&#1072;&#1103;&#1093; &#1074;&#1072;&#1084; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1085;&#1072;&#1076;&#1086;&#1073;&#1080;&#1090;&#1100;&#1089;&#1103; &#1089;&#1088;&#1072;&#1074;&#1085;&#1080;&#1074;&#1072;&#1090;&#1100; &#1086;&#1076;&#1085;&#1091; &#1080; &#1090;&#1091; &#1078;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; (&#1080;&#1083;&#1080; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;) &#1089; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1086;&#1084; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077; &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1080; &#1082;&#1086;&#1076;&#1072; &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1101;&#1090;&#1072; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; (&#1080;&#1083;&#1080; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;).
    </p>
    <p>
      
    </p>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>&#1057;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089; switch</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000"><b>switch</b>&#160;(n) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;<b>case</b>&#160;label1: </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1082;&#1086;&#1076; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; n=label1; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;<b>break</b>; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;<b>case</b>&#160;label2: </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1082;&#1086;&#1076; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; n=label2; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;<b>break</b>; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;<b>case</b>&#160;label3: </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1082;&#1086;&#1076; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; n=label3; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;<b>break</b>; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;<b>default</b>: </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1082;&#1086;&#1076; &#1074;&#1099;&#1087;. &#1077;&#1089;&#1083;&#1080; n &#1086;&#1090;&#1083;&#1080;&#1095;&#1085;&#1072; &#1086;&#1090; &#1074;&#1089;&#1077;&#1093; labels; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">}</font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$favcolor = &quot;red&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000"><b>switch</b>&#160;($favcolor) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;<b>case</b>&#160;&quot;red&quot;: </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo &quot;&#1042;&#1072;&#1096; &#1094;&#1074;&#1077;&#1090; red!&quot;; <b>break</b>; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;<b>case</b>&#160;&quot;blue&quot;: </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo &quot;&#1042;&#1072;&#1096; &#1094;&#1074;&#1077;&#1090; blue!&quot;; <b>break</b>; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;<b>case</b>&#160;&quot;green&quot;: </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000"><b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;</b>echo &quot;&#1042;&#1072;&#1096; &#1094;&#1074;&#1077;&#1090; green!&quot;; <b>break</b>; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;<b>default</b>: </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo &quot;&#1042;&#1072;&#1096; &#1094;&#1074;&#1077;&#1090; &#1085;&#1080;&#1082;&#1072;&#1082;&#1086;&#1081;&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">}</font>
          </p>
        </td>
      </tr>
    </table>
  </body>
</html></richcontent>
<node TEXT="Альтернативный синтаксис (endswitch)" ID="ID_1852745638" CREATED="1548697221857" MODIFIED="1548697527585"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1042; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1092;&#1086;&#1088;&#1084;&#1086;&#1081; &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;&#1072; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077;
    </p>
    <ul>
      <li>
        <b>&#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1092;&#1080;&#1075;&#1091;&#1088;&#1085;&#1086;&#1081; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080;</b>&#160;(<b><font size="4">{</font></b><font size="2">)</font>&#160;&#1085;&#1072; &#1076;&#1074;&#1086;&#1077;&#1090;&#1086;&#1095;&#1080;&#1077; (<b><font size="4">:</font></b>)
      </li>
      <li>
        &#1079;&#1072;&#1082;&#1088;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080; (<b><font size="4">}</font></b>)&#1085;&#1072;
      </li>
    </ul>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">switch ($i)</font><font color="#008000" size="4"><b>:</b></font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;case 0: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo &quot;i &#1088;&#1072;&#1074;&#1085;&#1086; 0&quot;; break; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;case 1: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo &quot;i &#1088;&#1072;&#1074;&#1085;&#1086; 1&quot;; break; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;case 2: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo &quot;i &#1088;&#1072;&#1074;&#1085;&#1086; 2&quot;; break; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;default: </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;echo &quot;i &#1085;&#1077; &#1088;&#1072;&#1074;&#1085;&#1086; to 0, 1 &#1080;&#1083;&#1080; 2&quot;; </font>
    </p>
    <p>
      <font color="#008000" size="4"><b>endswitch;</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
</node>
<node TEXT="while, do-while" FOLDED="true" ID="ID_1367968881" CREATED="1548747531920" MODIFIED="1549307236166"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1062;&#1080;&#1082;&#1083; while</b>&#160;&#160;&#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; PHP &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1074;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1086; &#1076;&#1086; &#1090;&#1077;&#1093; &#1087;&#1086;&#1088;, &#1087;&#1086;&#1082;&#1072; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; &#1074; &#1089;&#1072;&#1084;&#1086;&#1084; while &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; TRUE.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1095;&#1080;&#1089;&#1083;&#1072; &#1086;&#1090; 1 &#1076;&#1086; 10:</b>
    </p>
    <p>
      <font color="#008000"><b>$i</b>&#160;= 1; </font>
    </p>
    <p>
      <font color="#008000"><b>while</b>&#160;($i &lt;= 10) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Number: &quot; . <b>$i++</b>&#160;. &quot;\n&quot;;&#160;&#160;</font>/* &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; $i &#1087;&#1077;&#1088;&#1077;&#1076; &#1077;&#1105; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; (<a href="#ID_1372831277">post-increment</a>) */
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      =============================
    </p>
    <p>
      <b>&#1062;&#1080;&#1082;&#1083; do-while</b>&#160;&#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090; &#1094;&#1080;&#1082;&#1083;&#1072; while &#1090;&#1077;&#1084;, &#1095;&#1090;&#1086; &#1080;&#1089;&#1090;&#1080;&#1085;&#1085;&#1086;&#1089;&#1090;&#1100; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1082;&#1086;&#1085;&#1094;&#1077; &#1080;&#1090;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080;, &#1072; &#1085;&#1077; &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077;. &#1055;&#1077;&#1088;&#1074;&#1072;&#1103; &#1080;&#1090;&#1077;&#1088;&#1072;&#1094;&#1080;&#1103; &#1094;&#1080;&#1082;&#1083;&#1072; do-while &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1089;&#1103;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1095;&#1080;&#1089;&#1083;&#1072; &#1086;&#1090; 1 &#1076;&#1086; 10:&#160;</b>
    </p>
    <p>
      <font color="#008000"><b>$i</b>&#160;= 0; </font>
    </p>
    <p>
      <font color="#008000"><b>do</b>&#160;{ </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Number: &quot; . <b>$i++</b>&#160;. &quot;\n&quot;; </font>
    </p>
    <p>
      <font color="#008000">} <b>while</b>&#160;($i &lt;= 10);</font>
    </p>
  </body>
</html></richcontent>
<node TEXT="Альтернативный синтаксис (endwhile)" ID="ID_1434589785" CREATED="1548747953430" MODIFIED="1548750095705"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1042; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1092;&#1086;&#1088;&#1084;&#1086;&#1081; &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;&#1072; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077;
    </p>
    <ul>
      <li>
        <b>&#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1092;&#1080;&#1075;&#1091;&#1088;&#1085;&#1086;&#1081; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080;</b>&#160;(<b><font size="4">{</font></b><font size="2">)</font>&#160;&#1085;&#1072; &#1076;&#1074;&#1086;&#1077;&#1090;&#1086;&#1095;&#1080;&#1077; (<b><font size="4">:</font></b>)
      </li>
      <li>
        &#1079;&#1072;&#1082;&#1088;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080; (<b><font size="4">}</font></b>)&#1085;&#1072;
      </li>
    </ul>
    <p>
      <font color="#008000">while (expr)<b>:</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;statement </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;... </font>
    </p>
    <p>
      <font color="#008000"><b>endwhile;</b></font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1095;&#1080;&#1089;&#1083;&#1072; &#1086;&#1090; 1 &#1076;&#1086; 10: </b>
    </p>
    <p>
      <font color="#008000">$i = 1; </font>
    </p>
    <p>
      <font color="#008000"><b>while</b>&#160;($i &lt;= 10)<b>:</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo $i; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;$i++; </font>
    </p>
    <p>
      <font color="#008000"><b>endwhile;</b></font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="for" FOLDED="true" ID="ID_1391072423" CREATED="1548752485559" MODIFIED="1548754499772"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000">for (expr1; expr2; expr3) </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;statement</font>
    </p>
    <ul>
      <li>
        <b>expr1</b>&#160;- &#1080;&#1085;&#1080;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1089;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082;&#1072; &#1094;&#1080;&#1082;&#1083;&#1072;. &#1042;&#1089;&#1077;&#1075;&#1076;&#1072; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1080;&#1085; &#1088;&#1072;&#1079; &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077; &#1094;&#1080;&#1082;&#1083;&#1072;
      </li>
      <li>
        <b>expr2</b>&#160;- &#1089;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082;. &#1042;&#1099;&#1095;&#1080;&#1089;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1080;&#1090;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080; &#1094;&#1080;&#1082;&#1083;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1074;&#1085;&#1086; TRUE, &#1090;&#1086; &#1094;&#1080;&#1082;&#1083; &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103;. &#1045;&#1089;&#1083;&#1080; FALSE - &#1094;&#1080;&#1082;&#1083; &#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1072;&#1077;&#1090;&#1089;&#1103;
      </li>
      <li>
        <b>expr3</b>&#160;- &#1080;&#1085;&#1082;&#1088;&#1077;&#1084;&#1077;&#1085;&#1090; &#1089;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082;&#1072; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082;&#1072; &#1094;&#1080;&#1082;&#1083;&#1072;. &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1082;&#1086;&#1085;&#1094;&#1077; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1080;&#1090;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080;
      </li>
    </ul>
    <p>
      <b>&#1054;&#1090;&#1086;&#1073;&#1088;&#1072;&#1079;&#1080;&#1090;&#1100; &#1095;&#1080;&#1089;&#1083;&#1072; &#1086;&#1090; 1 &#1076;&#1086; 10</b>
    </p>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000"><b>for</b>&#160;($i = 1; $i &lt;= 10; $i++) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo $i; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">} </font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000"><b>for</b>&#160;($i = 1; ; $i++) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;if ($i &gt; 10) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;break; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;} </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo $i; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">} </font>
          </p>
        </td>
      </tr>
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$i = 1; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">for (; ; ) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;if ($i &gt; 10) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;break; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;} </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo $i; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;$i++; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">} </font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">for ($i = 1, $j = 0; $i &lt;= 10; $j += $i, print $i, $i++);</font>
          </p>
        </td>
      </tr>
    </table>
  </body>
</html></richcontent>
<node TEXT="Альтернативный синтаксис (endfor)" ID="ID_1428646516" CREATED="1548753332672" MODIFIED="1548753445794"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1042; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1092;&#1086;&#1088;&#1084;&#1086;&#1081; &#1072;&#1083;&#1100;&#1090;&#1077;&#1088;&#1085;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;&#1072; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077;
    </p>
    <ul>
      <li>
        <b>&#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1092;&#1080;&#1075;&#1091;&#1088;&#1085;&#1086;&#1081; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080;</b>&#160;(<b><font size="4">{</font></b><font size="2">)</font>&#160;&#1085;&#1072; &#1076;&#1074;&#1086;&#1077;&#1090;&#1086;&#1095;&#1080;&#1077; (<b><font size="4">:</font></b>)
      </li>
      <li>
        &#1079;&#1072;&#1082;&#1088;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1081; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080; (<b><font size="4">}</font></b>)&#1085;&#1072;
      </li>
    </ul>
    <p>
      <font color="#008000">for (expr1; expr2; expr3)<b>:</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;statement </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;... </font>
    </p>
    <p>
      <b><font color="#008000">endfor;</font></b>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="foreach" FOLDED="true" ID="ID_230853582" CREATED="1548753406947" MODIFIED="1549308334402"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>foreach</b>&#160;- &#1087;&#1088;&#1086;&#1089;&#1090;&#1086;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; &#1087;&#1077;&#1088;&#1077;&#1073;&#1086;&#1088;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;. <b>&#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;&#1084;&#1080; &#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072;&#1084;&#1080;</b>&#160; &#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1086;&#1096;&#1080;&#1073;&#1082;&#1091; &#1087;&#1088;&#1080; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1084;&#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1090;&#1080;&#1087;&#1086;&#1074; &#1080;&#1083;&#1080; &#1085;&#1077;&#1080;&#1085;&#1080;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1084;&#1080;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1074;&#1072; &#1074;&#1080;&#1076;&#1072; &#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089;&#1072;:</b>
    </p>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">foreach (array_expression as $value) </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;statement</font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            &#1087;&#1077;&#1088;&#1077;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;, &#1079;&#1072;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1099;&#1081; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; array_expression. &#1053;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1080;&#1090;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &#1087;&#1088;&#1080;&#1089;&#1074;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; $value &#1080; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1077;&#1076;&#1080;&#1085;&#1080;&#1094;&#1091; (&#1090;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1085;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1081; &#1080;&#1090;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080; &#1094;&#1080;&#1082;&#1083;&#1072; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1089;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1084;).
          </p>
        </td>
      </tr>
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">foreach (array_expression as $key =&gt; $value) </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;statement</font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1088;&#1080;&#1089;&#1074;&#1086;&#1080;&#1090; &#1082;&#1083;&#1102;&#1095; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; $key &#1085;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1080;&#1090;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080;
          </p>
        </td>
      </tr>
    </table>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1094;&#1074;&#1077;&#1090;&#1072; &#1080;&#1079; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;</b>
    </p>
    <p>
      <font color="#008000">$colors = array(&quot;red&quot;, &quot;green&quot;, &quot;blue&quot;, &quot;yellow&quot;); </font>
    </p>
    <p>
      <font color="#008000"><b>foreach</b>&#160;($colors <b>as</b>&#160;$value) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;echo &quot;$value \n&quot;; </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
  </body>
</html></richcontent>
