<node TEXT="array" ID="ID_1104368640" CREATED="1548584272834" MODIFIED="1548764154201"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_849975691">&#1052;&#1072;&#1089;&#1089;&#1080;&#1074;&#1099; (&#1090;&#1080;&#1087;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;)</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>array</b>&#160;- &#1103;&#1079;&#1099;&#1082;&#1086;&#1074;&#1072;&#1103; &#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1103;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1072;&#1103; &#1076;&#1083;&#1103; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1083;&#1080;&#1090;&#1077;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;, &#1072; &#1085;&#1077; &#1086;&#1073;&#1099;&#1095;&#1085;&#1072;&#1103; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">$cars = array(&quot;Volvo&quot;,&quot;BMW&quot;,&quot;Toyota&quot;); </font>
    </p>
    <p>
      <font color="#008000">var_dump($cars);&#160;&#160;# &#1042;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1090;&#1080;&#1087; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">array( </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;key&#160;&#160;=&gt; value, </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;key2 =&gt; value2, </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;key3 =&gt; value3, </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;... </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;) </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">$array = array( </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&quot;foo&quot; =&gt; &quot;bar&quot;, </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&quot;bar&quot; =&gt; &quot;foo&quot;, </font>
    </p>
    <p>
      <font color="#008000">); </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>// &#1053;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; PHP 5.4</b>
    </p>
    <p>
      <font color="#008000">$array = [ </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&quot;foo&quot; =&gt; &quot;bar&quot;, </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&quot;bar&quot; =&gt; &quot;foo&quot;, </font>
    </p>
    <p>
      <font color="#008000">];</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="arsort" ID="ID_514785642" CREATED="1548772410121" MODIFIED="1548777880133"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_593291256">&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;</a>&#160;&#160;<a href="#ID_1961797723">asort</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>arsort()</b>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086; &#1091;&#1073;&#1099;&#1074;&#1072;&#1085;&#1080;&#1102; (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;). C&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090; &#1082;&#1083;&#1102;&#1095;&#1080;
    </p>
    <ul>
      <li>
        <b>&#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103;</b>&#160; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1083;&#1102;&#1095;&#1072;&#1084;&#1080; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;
      </li>
      <li>
        &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1072; &#1087;&#1088;&#1080; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1077; <b>&#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1093; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;</b>
      </li>
    </ul>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$age = array(&quot;Peter&quot;=&gt;&quot;35&quot;, &quot;Ben&quot;=&gt;&quot;37&quot;, &quot;Joe&quot;=&gt;&quot;23&quot;); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">arsort($age); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">foreach($age as $x =&gt; $x_value) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Key=&quot; . $x . &quot;, Value=&quot; . $x_value; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;\n&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">}</font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            --&gt;
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Ben, Value=37
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Peter, Value=35
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Joe, Value=23
          </p>
        </td>
      </tr>
    </table>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="asort" ID="ID_1961797723" CREATED="1548772392996" MODIFIED="1548777275011"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_593291256">&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;</a>&#160;&#160;<a href="#ID_514785642">arsort</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>asort</b>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086; &#1074;&#1086;&#1079;&#1088;&#1072;&#1089;&#1090;&#1072;&#1085;&#1080;&#1102; (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081;), &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1103; &#1082;&#1083;&#1102;&#1095;&#1080;.
    </p>
    <ul>
      <li>
        &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1072; &#1087;&#1088;&#1080; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1077; <b>&#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1093; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;</b>, &#1082;&#1086;&#1075;&#1076;&#1072; &#1074;&#1072;&#1078;&#1085;&#1086; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1077; &#1082;&#1083;&#1102;&#1095; =&gt; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1083;&#1102;&#1095;&#1072;&#1084;&#1080; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;
      </li>
    </ul>
    <p>
      
    </p>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$age = array(&quot;Peter&quot;=&gt;&quot;35&quot;, &quot;Ben&quot;=&gt;&quot;37&quot;, &quot;Joe&quot;=&gt;&quot;23&quot;); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">asort($age); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">foreach($age as $x =&gt; $x_value) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Key=&quot; . $x . &quot;, Value=&quot; . $x_value; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;\n&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">}</font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            --&gt;
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Joe, Value=23
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Peter, Value=35
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Ben, Value=37
