<node TEXT="echo" ID="ID_1527980780" CREATED="1548580243600" MODIFIED="1548766577992"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_199582644">print</a>&#160;&#160;<a href="#ID_1407614579">&#1057;&#1090;&#1088;&#1086;&#1082;&#1080; (&#1090;&#1080;&#1087;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;)</a>&#160;&#160;<a href="#ID_1642111380">&#1057;&#1090;&#1088;&#1086;&#1082;&#1086;&#1074;&#1099;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1099;</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>echo</b>&#160;&#8212; &#1042;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090; &#1086;&#1076;&#1085;&#1091; &#1080;&#1083;&#1080; &#1073;&#1086;&#1083;&#1077;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082;
    </p>
    <p>
      echo ( string $arg1 [, string $... ] ) : void
    </p>
    <ul>
      <li>
        &#1042;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090; &#1074;&#1089;&#1077; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;. &#1057;&#1080;&#1084;&#1074;&#1086;&#1083; &#1082;&#1086;&#1085;&#1094;&#1072; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1085;&#1077; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103;
      </li>
      <li>
        <b>echo or echo() - </b>&#1079;&#1072;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &#1074; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080; <b>&#1085;&#1077;&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;</b>. &#1045;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1100; &#1073;&#1086;&#1083;&#1077;&#1077; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072; &#1074; echo - <b>&#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1079;&#1072;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1074; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080;</b>
      </li>
      <li>
        &#1045;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1077; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; <b>print</b>&#160; &#1074; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; <b>echo</b>&#160;&#160;&#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1080; <b>&#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;</b>
      </li>
      <li>
        <b>&#1050;&#1088;&#1072;&#1090;&#1082;&#1086;&#1077; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077;</b><br/><font color="#008000">&lt;h1&gt;&#1042;&#1072;&#1084; </font><font color="#008000" size="3"><b>&lt;?php echo</b></font><font color="#008000">&#160;$age ?&gt; &#1083;&#1077;&#1090;&lt;/h1&gt;<br color="#008000"/>&lt;h1&gt;&#1042;&#1072;&#1084; </font><font color="#008000" size="3"><b>&lt;?=</b></font><font color="#008000">&#160;$age ?&gt; &#1083;&#1077;&#1090;&lt;/h1&gt;</font>
      </li>
    </ul>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000"><b>echo &quot;&lt;h2&gt;PHP is Fun!&lt;/h2&gt;&quot;; </b></font>
    </p>
    <p>
      <font color="#008000"><b>echo &quot;&#1055;&#1088;&#1080;&#1074;&#1077;&#1090; &#1084;&#1080;&#1088;!&quot;;</b>&#160; </font>
    </p>
    <p>
      <font color="#008000"><b>echo 3+4;</b></font>&#160;&#160;# --&gt; 7
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>echo &quot;&#1069;&#1090;&#1086; &#1079;&#1072;&#1081;&#1084;&#1077;&#1090;</b>&#160; </font>
    </p>
    <p>
      <font color="#008000">&#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;. &#1055;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1099; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1090;&#1086;&#1078;&#1077; &#1074;&#1099;&#1074;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103;&quot;; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>echo &quot;&#1069;&#1090;&#1086; &#1079;&#1072;&#1081;&#1084;&#1077;&#1090;\n&#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;. &#1055;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076;&#1099; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080; &#1090;&#1086;&#1078;&#1077;\n&#1074;&#1099;&#1074;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103;&quot;;</b>&#160; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>echo &quot;&#1069;&#1082;&#1088;&#1072;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; \&quot;&#1058;&#1072;&#1082;\&quot;.&quot;;</b>&#160; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>// &#1089; echo &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; ...</b>&#160; </font>
    </p>
    <p>
      <font color="#008000">$foo = &quot;foobar&quot;; </font>
    </p>
    <p>
      <font color="#008000">echo &quot;foo - &#1101;&#1090;&#1086; $foo&quot;; // foo - &#1101;&#1090;&#1086; foobar </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>// ... &#1080; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1099;</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">$baz = array(&quot;value&quot; =&gt; &quot;foo&quot;); </font>
    </p>
    <p>
      <font color="#008000">echo &quot;&#1101;&#1090;&#1086; {$baz['value']} !&quot;; // &#1101;&#1090;&#1086; foo ! </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>// &#1055;&#1088;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1086;&#1076;&#1080;&#1085;&#1086;&#1095;&#1085;&#1099;&#1093; &#1082;&#1072;&#1074;&#1099;&#1095;&#1077;&#1082; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1080;&#1084;&#1103; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081;, &#1072; &#1085;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;</b>&#160; </font>
    </p>
    <p>
      <font color="#008000">echo 'foo - &#1101;&#1090;&#1086; $foo'; // foo - &#1101;&#1090;&#1086; $foo </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>// &#1045;&#1089;&#1083;&#1080; &#1074;&#1099; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1077; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1099;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093;</b>&#160; </font>
    </p>
    <p>
      <font color="#008000">echo $foo;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;// foobar </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>// &#1042;&#1084;&#1077;&#1089;&#1090;&#1086; &#1082;&#1086;&#1085;&#1082;&#1072;&#1090;&#1077;&#1085;&#1072;&#1094;&#1080;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1077;&#1076;&#1072;&#1090;&#1100; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1099; </b></font>
    </p>
    <p>
      <font color="#008000"><b>// &#1074; &#1086;&#1076;&#1085;&#1091; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; &#1080; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085;&#1099; &#1082;&#1072;&#1082; &#1086;&#1076;&#1080;&#1085; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;</b>&#160; </font>
    </p>
    <p>
      <font color="#008000">echo '&#1069;&#1090;&#1072; ', '&#1089;&#1090;&#1088;&#1086;&#1082;&#1072; ', '&#1073;&#1099;&#1083;&#1072; ', '&#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1072; ', '&#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1084;&#1080; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072;&#1084;&#1080;.', chr(10); </font>
    </p>
    <p>
      <font color="#008000">echo '&#1069;&#1090;&#1072; ' . '&#1089;&#1090;&#1088;&#1086;&#1082;&#1072; ' . '&#1073;&#1099;&#1083;&#1072; ' . '&#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1072; ' . '&#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1082;&#1086;&#1085;&#1082;&#1072;&#1090;&#1077;&#1085;&#1072;&#1094;&#1080;&#1080;.' . &quot;\n&quot;; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000"><b>echo &lt;&lt;&lt;END</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">&#1047;&#1076;&#1077;&#1089;&#1100; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1080;&#1085;&#1090;&#1072;&#1082;&#1089;&#1080;&#1089; &quot;here document&quot; &#1076;&#1083;&#1103; &#1074;&#1099;&#1074;&#1086;&#1076;&#1072; </font>
    </p>
    <p>
      <font color="#008000"><b>&#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1089;&#1090;&#1088;&#1086;&#1082;</b>&#160;&#1089; &#1087;&#1086;&#1076;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1086;&#1081; <b>&#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093;</b>&#160;$variable. </font>
    </p>
    <p>
      <font color="#008000">&#1047;&#1072;&#1084;&#1077;&#1090;&#1100;&#1090;&#1077;, &#1095;&#1090;&#1086; &#1079;&#1072;&#1082;&#1088;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; </font>
    </p>
    <p>
      <font color="#008000">&#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077;. &#1085;&#1080;&#1082;&#1072;&#1082;&#1080;&#1093; &#1087;&#1088;&#1086;&#1073;&#1077;&#1083;&#1086;&#1074;! </font>
    </p>
    <p>
      <font color="#008000">END - &#1080;&#1084;&#1103; &#1073;&#1083;&#1086;&#1082;&#1072;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1083;&#1102;&#1073;&#1086;&#1077; </font>
    </p>
    <p>
      <font color="#008000"><b>END;</b></font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">?&gt;</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="krsort" ID="ID_1477787308" CREATED="1548772419074" MODIFIED="1548777880095"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_593291256">&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;</a>&#160;&#160;<a href="#ID_1142870260">ksort</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>krsort()</b>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086; &#1091;&#1073;&#1099;&#1074;&#1072;&#1085;&#1080;&#1102; (&#1082;&#1083;&#1102;&#1095;&#1077;&#1081;)
    </p>
    <ul>
      <li>
        <b>&#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103;</b>&#160; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1083;&#1102;&#1095;&#1072;&#1084;&#1080; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;
      </li>
      <li>
        &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1072; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089; <b>&#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1084;&#1080; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;&#1084;&#1080;</b>
      </li>
    </ul>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$age = array(&quot;Peter&quot;=&gt;&quot;35&quot;, &quot;Ben&quot;=&gt;&quot;37&quot;, &quot;Joe&quot;=&gt;&quot;43&quot;); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">krsort($age); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">foreach($age as $x =&gt; $x_value) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Key=&quot; . $x . &quot;, Value=&quot; . $x_value; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;\n&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">}</font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            --&gt;
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Peter, Value=35
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Joe, Value=43
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Ben, Value=37
          </p>
        </td>
      </tr>
    </table>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="ksort" ID="ID_1142870260" CREATED="1548772395714" MODIFIED="1548777275038"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_593291256">&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;</a>&#160;&#160;<a href="#ID_1961797723">asort</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>ksort()</b>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1087;&#1086; &#1074;&#1086;&#1079;&#1088;&#1072;&#1089;&#1090;&#1072;&#1085;&#1080;&#1102; (&#1082;&#1083;&#1102;&#1095;&#1077;&#1081;)
    </p>
    <ul>
      <li>
        <b>&#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103;</b>&#160; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1083;&#1102;&#1095;&#1072;&#1084;&#1080; &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;
      </li>
      <li>
        &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1072; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089; <b>&#1072;&#1089;&#1089;&#1086;&#1094;&#1080;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1084;&#1080; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1072;&#1084;&#1080;</b>
      </li>
    </ul>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$age = array(&quot;Peter&quot;=&gt;&quot;35&quot;, &quot;Ben&quot;=&gt;&quot;37&quot;, &quot;Joe&quot;=&gt;&quot;43&quot;); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">ksort($age); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">foreach($age as $x =&gt; $x_value) { </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;Key=&quot; . $x . &quot;, Value=&quot; . $x_value; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;\n&quot;; </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">}</font>
          </p>
        </td>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            --&gt;
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Ben, Value=37
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Joe, Value=43
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            Key=Peter, Value=35
          </p>
        </td>
      </tr>
    </table>
  </body>
</html></richcontent>
</node>
<node TEXT="print" ID="ID_199582644" CREATED="1548580235620" MODIFIED="1548766677234"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1527980780">echo</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>print</b>&#160;&#8212; &#1042;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091;. &#1053;&#1077; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072;&#1089;&#1090;&#1086;&#1103;&#1097;&#1077;&#1081; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1077;&#1081; (&#1101;&#1090;&#1086; &#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1103; &#1103;&#1079;&#1099;&#1082;&#1072;), &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1079;&#1072;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &#1074; &#1089;&#1082;&#1086;&#1073;&#1082;&#1080; &#1085;&#1077;&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;.
    </p>
    <p>
      
    </p>
    <p>
      <b>print ( string $arg ) : int</b>
    </p>
    <ul>
      <li>
        <b>print</b>&#160;&#1080;&#1083;&#1080; <b>print()</b>
      </li>
      <li>
        &#1043;&#1083;&#1072;&#1074;&#1085;&#1086;&#1077; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; <b>echo</b>&#160;&#1074; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; print &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1080;&#1085; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090; &#1080; <b>&#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; 1</b>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">print &quot;&lt;h2&gt;PHP is Fun!&lt;/h2&gt;&quot;; </font>
    </p>
    <p>
      <font color="#008000">print &quot;Hello world!&lt;br&gt;&quot;; </font>
    </p>
    <p>
      <font color="#008000">print &quot;I'm about to learn PHP!&quot;; </font>
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">$x = 5; </font>
    </p>
    <p>
      <font color="#008000">$y = 4; </font>
    </p>
    <p>
      <font color="#008000">print $x + $y; </font>&#160;# --&gt; 9
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="rsort" ID="ID_529177125" CREATED="1548772374172" MODIFIED="1548775341910"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_593291256">&#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1086;&#1074;</a>&#160;&#160;<a href="#ID_33851721">sort</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>rsort()</b>&#160;- &#1057;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1074; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; (&#1086;&#1090; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1075;&#1086; &#1082; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1084;&#1091;).
    </p>
    <p>
      
    </p>
    <table border="0" style="width: 100%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 50%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">$cars = array(&quot;Volvo&quot;, &quot;BMW&quot;, &quot;Toyota&quot;); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <font color="#008000">rsort($cars); </font>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            
          </p>
