<node TEXT="Аргументы функции" ID="ID_325993457" CREATED="1548757446722" MODIFIED="1557676643290"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1040;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;.</b>&#160; &#1048;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; <b>&#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;</b>. &#1040;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090; &#1087;&#1086;&#1076;&#1086;&#1073;&#1077;&#1085; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081;
    </p>
    <ul>
      <li>
        &#1040;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077; &#1080;&#1084;&#1077;&#1085;&#1080; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1074; <b>&#1089;&#1082;&#1086;&#1073;&#1082;&#1072;&#1093; ( )</b>
      </li>
      <li>
        &#1083;&#1102;&#1073;&#1086;&#1077; &#1082;&#1086;&#1083;-&#1074;&#1086; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; - &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; <b>&#1079;&#1072;&#1087;&#1103;&#1090;&#1099;&#1084;&#1080; ,</b>
      </li>
    </ul>
    <p>
      <b>&#1054;&#1076;&#1080;&#1085; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;</b>
    </p>
    <p>
      <font color="#008000">function familyName(<b>$fname</b>) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;<b>$fname </b>\n&quot;; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">familyName(&quot;Jani&quot;); </font>
    </p>
    <p>
      <font color="#008000">familyName(&quot;Hege&quot;);</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1074;&#1072; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;</b>
    </p>
    <p>
      <font color="#008000">function familyName(<b>$fname, $year</b>) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;echo &quot;$fname. Born in $year \n&quot;; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">familyName(&quot;Hege&quot;, &quot;1975&quot;); </font>
    </p>
    <p>
      <font color="#008000">familyName(&quot;Stale&quot;, &quot;1978&quot;);</font>
    </p>
  </body>
</html></richcontent>
