<node TEXT="Возврат значений" ID="ID_1360767743" CREATED="1548758338689" MODIFIED="1549365204981"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_162374486">return</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1047;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1102;&#1090;&#1089;&#1103;</b>&#160;&#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; &#1085;&#1077;&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090;&#1072; (<b>return</b>)
    </p>
    <ul>
      <li>
        &#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1084;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; <b>&#1083;&#1102;&#1073;&#1086;&#1075;&#1086; &#1090;&#1080;&#1087;&#1072;</b>, &#1074; &#1090;&#1086;&#1084; &#1095;&#1080;&#1089;&#1083;&#1077; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074;&#1099; &#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099;
      </li>
      <li>
        &#1042;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090; &#1087;&#1088;&#1080;&#1074;&#1086;&#1076;&#1080;&#1090; &#1082; <b>&#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1077;&#1085;&#1080;&#1102; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;</b>&#160;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; &#1082; &#1090;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; &#1082;&#1086;&#1076;&#1072;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1076;&#1072;&#1085;&#1085;&#1072;&#1103; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1073;&#1099;&#1083;&#1072; &#1074;&#1099;&#1079;&#1074;&#1072;&#1085;&#1072;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1103; <b>return &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1072;</b>, &#1090;&#1086; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1074;&#1077;&#1088;&#1085;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; <b>NULL</b>
      </li>
    </ul>
    <p>
      <font color="#008000">function sum($x, $y) { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;$z = $x + $y; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160; <b>return</b>&#160;$z; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">echo &quot;5 + 10 = &quot; . sum(5, 10) . &quot;\n&quot;; </font>
    </p>
    <p>
      <font color="#008000">echo &quot;7 + 13 = &quot; . sum(7, 13) . &quot;\n&quot;; </font>
    </p>
    <p>
      <font color="#008000">echo &quot;2 + 4 = &quot; . sum(2, 4);</font>
    </p>
  </body>
</html></richcontent>
