    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&quot;command&quot;: &quot;editor.action.triggerSuggest&quot; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;} </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">]</span>
    </p>
  </body>
</html></richcontent>
</node>
