<node TEXT="Тип коммутации" ID="ID_1253837004" CREATED="1537257898517" MODIFIED="1540240510310"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1050;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;</b>&#160;- &#1055;&#1077;&#1088;&#1077;&#1076; &#1090;&#1077;&#1084; &#1082;&#1072;&#1082; &#1085;&#1072;&#1095;&#1072;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1084;&#1077;&#1078;&#1076;&#1091; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1077;&#1083;&#1077;&#1084; &#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;. &#1045;&#1089;&#1083;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083; &#1079;&#1072;&#1085;&#1103;&#1090;, &#1090;&#1086; &#1085;&#1080;&#1082;&#1090;&#1086; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1100; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090;
    </p>
    <ul>
      <li>
        &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;
      </li>
      <li>
        &#1040;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1072;&#1103; - &#1089;&#1072;&#1084;&#1099;&#1081; &#1089;&#1090;&#1072;&#1088;&#1099;&#1081; &#1090;&#1080;&#1087; &#1090;&#1077;&#1083;. &#1089;&#1074;&#1103;&#1079;&#1080;. &#1053;&#1072;&#1080;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1077; &#1082;&#1086;&#1083;-&#1074;&#1086; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081;
      </li>
      <li>
        &#1062;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1103; (<a href="#ID_1128731288">TDM</a>). ( - ) &#1062;&#1080;&#1092;&#1088;&#1086;&#1074;&#1099;&#1077; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1074;&#1077;&#1085;&#1076;&#1086;&#1088;&#1072; &#1087;&#1086;&#1076;&#1093;&#1086;&#1076;&#1103;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1083;&#1103; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1099;&#1093; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1081; &#1101;&#1090;&#1086;&#1075;&#1086; &#1078;&#1077; &#1074;&#1077;&#1085;&#1076;&#1086;&#1088;&#1072;. &#1057;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100; &#1090;&#1077;&#1083;. &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1086;&#1074; (&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085; + &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1103;) &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; 50-60% &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1087;&#1088;&#1086;&#1077;&#1082;&#1090;&#1072;.
      </li>
      <li>
        &#1057;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1089;&#1103; &#1086;&#1076;&#1080;&#1085; &#1088;&#1072;&#1079; &#1080; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1086;&#1074; &#1085;&#1072; <a href="#ID_123085290">&#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102;</a>&#160; &#1085;&#1077;&#1090;
      </li>
    </ul>
    <p>
      <b>&#1050;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1103; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;</b>&#160;- &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; &#1076;&#1077;&#1083;&#1103;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1090;&#1076;&#1077;&#1083;&#1085;&#1099;&#1077; &#1095;&#1072;&#1089;&#1090;&#1080; (&#1087;&#1072;&#1082;&#1077;&#1090;&#1099;), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;, &#1085;&#1077;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086; &#1076;&#1088;&#1091;&#1075; &#1086;&#1090; &#1076;&#1088;&#1091;&#1075;&#1072;. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1087;&#1072;&#1082;&#1077;&#1084; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1086;&#1081;&#1090;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1077;&#1090;&#1100; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084; &#1087;&#1091;&#1090;&#1077;&#1084;. &#1041;&#1086;&#1083;&#1077;&#1077; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
    </p>
    <ul>
      <li>
        &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1103;&#1093;
      </li>
      <li>
        Voice over IP (<a href="#ID_690503955">VoIP</a>)
      </li>
      <li>
        &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; <a href="#ID_1449357610">QoS</a>
      </li>
      <li>
        &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1072;&#1103; &#1087;&#1086;&#1083;&#1086;&#1089;&#1072; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1085;&#1080;&#1103;
      </li>
      <li>
        &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1095;&#1085;&#1099;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1102;&#1090;&#1089;&#1103; <a href="%23#ID_123085290">&#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1077;&#1081;</a>
