        &#1057;&#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1080;&#1076;&#1077;&#1090; &#1055;&#1088;&#1077;&#1072;&#1073;&#1091;&#1083;&#1072; - &#1089;&#1077;&#1081;&#1095;&#1072;&#1089; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072;. &#1042;&#1089;&#1077; PC &#1074; &#1089;&#1077;&#1090;&#1080; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1102;&#1090; &#1089;&#1083;&#1091;&#1096;&#1072;&#1090;&#1100;
