    <p>
      <b>&#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089;&#1074;&#1080;&#1090;&#1095;&#1077;&#1081; &#1074; &#1087;&#1091;&#1083;&#1077;</b>&#160; &#1095;&#1077;&#1088;&#1077;&#1079; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084;&#1099; IN &#1080; OUT. &#1055;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;, &#1087;&#1086;&#1102;&#1085;&#1080;&#1090;&#1085;&#1086; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1086;&#1076;&#1080;&#1085; &#1089; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084;, &#1085;&#1080;&#1078;&#1085;&#1080;&#1081; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089; &#1074;&#1077;&#1088;&#1093;&#1085;&#1080;&#1084;. &#1055;&#1088;&#1080; &#1088;&#1072;&#1079;&#1088;&#1099;&#1074;&#1077; &#1082;&#1086;&#1083;&#1100;&#1094;&#1072; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1074; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080;. &#1056;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; &#1073;&#1086;&#1083;&#1077;&#1077; 400 (&#1090;.&#1077;. &#1076;&#1083;&#1103; &#1082;&#1088;&#1091;&#1087;&#1085;&#1086;&#1075;&#1086; &#1073;&#1080;&#1079;&#1085;&#1077;&#1089;&#1072;). &#1057;&#1088;&#1077;&#1076;&#1080; &#1074;&#1089;&#1077;&#1093; &#1089;&#1074;&#1080;&#1090;&#1095;&#1077;&#1081; &#1077;&#1089;&#1090;&#1100; &#1075;&#1083;&#1072;&#1074;&#1085;&#1099;&#1081; (&#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081;) &#1089;&#1074;&#1080;&#1090;&#1095; &#1086;&#1090; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1074;&#1089;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#10