        &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1083;&#1080;&#1089;&#1100; <b>Hub</b>&#160;&#160;(&#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1082;&#1086;&#1085;&#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;, &#1088;&#1077;&#1087;&#1080;&#1090;&#1077;&#1088;) - &#1086;&#1089;&#1085;. &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; - <b>&#1091;&#1089;&#1080;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072;</b>.<br/><b>&#1047;&#1072;&#1082;&#1086;&#1085; 4-&#1093; &#1093;&#1072;&#1073;&#1086;&#1074;</b>&#160;- &#1086;&#1090; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1076;&#1086; &#1076;&#1088;&#1091;&#1075;&#1086;&#1075;&#1086; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1089;&#1090;&#1086;&#1103;&#1090;&#1100; &#1085;&#1077; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1095;&#1077;&#1090;&#1099;&#1088;&#1077;&#1093; &#1093;&#1072;&#1073;&#1086;&#1074;.
