<node TEXT="Дерево (Tree, Hybrid)" ID="ID_351534292" CREATED="1519112080072" MODIFIED="1519112080072"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1054;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &quot;&#1079;&#1074;&#1077;&#1079;&#1076;&quot;</b>.
    </p>
    <p>
      <b>&#1053;&#1072;&#1080;&#1073;&#1086;&#1083;&#1077;&#1077; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1077;&#1085;&#1085;&#1072;&#1103; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103;</b>&#160;&#1087;&#1088;&#1080; &#1087;&#1086;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1080;&#1080; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081;.
    </p>
    <ul>
      <li>
        &#1043;&#1088;&#1072;&#1092; &#1073;&#1077;&#1079; &#1087;&#1077;&#1090;&#1077;&#1083;&#1100; (&#1084;&#1077;&#1078;&#1076;&#1091; &#1076;&#1074;&#1091;&#1103; &#1090;&#1086;&#1095;&#1082;&#1072;&#1084;&#1080; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1089;&#1083;&#1072;&#1090;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; 2&#1103; &#1087;&#1091;&#1090;&#1103;&#1084;&#1080;). &#1045;&#1089;&#1083;&#1080; &#1087;&#1086;&#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1090;&#1083;&#1103;, &#1090;&#1086; &quot;&#1079;&#1074;&#1077;&#1079;&#1076;&#1072;&quot; &#1087;&#1088;&#1077;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; <a href="#ID_1979011078">partial mesh</a>
      </li>
      <li>
        &#1058;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; &#1089;&#1074;&#1099;&#1096;&#1077; 300 PC (&#1084;&#1086;&#1078;&#1085;&#1086; &#1080; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;)
      </li>
      <li>
        &#1057;&#1090;&#1088;&#1086;&#1080;&#1090;&#1089;&#1103; &#1085;&#1072; &#1089;&#1074;&#1080;&#1090;&#1095;&#1072;&#1093; (&#1073;&#1086;&#1083;&#1077;&#1077; 3&#1093;)
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; <b>&#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1072;&#1103; &#1092;&#1072;&#1073;&#1088;&#1080;&#1082;&#1072; (switching fabric)</b>&#160;&#1091; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086; &#1089;&#1074;&#1080;&#1090;&#1095;&#1072; 17&#1043;&#1073;&#1080;&#1090;, &#1079;&#1085;&#1072;&#1095;&#1080;&#1090; &#1087;&#1088;&#1080;&#1076;&#1072;&#1090;&#1082;&#1086;&#1074; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1074;&#1077;&#1089;&#1080;&#1090;&#1100; &#1076;&#1086; 17&#1043;&#1073;&#1080;&#1090;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1086;&#1074;&#1077;&#1089;&#1080;&#1090;&#1100; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;, &#1090;&#1086; &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099;
      </li>
      <li>
        &#1052;&#1086;&#1078;&#1085;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1077; &#1082;&#1072;&#1073;&#1077;&#1083;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072;&#1084;&#1080; (&#1082;&#1072;&#1073;&#1077;&#1083;&#1080; &#1085;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1099;), &#1085;&#1086; &#1087;&#1088;&#1080; &#1086;&#1073;&#1088;&#1099;&#1074;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1090;&#1089;&#1103;, &#1072; &#1087;&#1086;&#1090;&#1086;&#1084; &#1080;&#1097;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1072;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1074;&#1089;&#1077; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080; &#1091;&#1078;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090;. &#1048;&#1083;&#1080; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1099; &#1089; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1084; STP (&#1089;&#1072;&#1084;&#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1087;&#1077;&#1090;&#1083;&#1077;&#1074;&#1099;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;)
      </li>
      <li>
        &#1073;&#1086;&#1083;&#1077;&#1077; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1095;&#1080;&#1074;&#1099;&#1077; &#1089;&#1077;&#1090;&#1080;
      </li>
      <li>
        &#1073;&#1086;&#1083;&#1077;&#1077; &#1088;&#1072;&#1079;&#1074;&#1077;&#1090;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1089;&#1077;&#1090;&#1080;
      </li>
      <li>
        &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; <b>&#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; (&#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077;) &#1084;&#1077;&#1089;&#1090;&#1086;</b>&#160;&#1082;&#1091;&#1076;&#1072; &#1073;&#1091;&#1076;&#1091;&#1090; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1074;&#1089;&#1077; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1099; + &#1074;&#1077;&#1085;&#1090;&#1080;&#1083;&#1103;&#1090;&#1086;&#1088;&#1099; (&#1077;&#1089;&#1083;&#1080; &#1085;&#1077;&#1090; &#1082;&#1086;&#1085;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1077;&#1088;&#1072;)
      </li>
    </ul>
  </body>
</html></richcontent>
