<node TEXT="Ячеистая (Mesh)" ID="ID_1979011078" CREATED="1519112080072" MODIFIED="1519112080072"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1071;&#1095;&#1077;&#1080;&#1089;&#1090;&#1072;&#1103; (Mesh)</b>&#160;- &#1091;&#1079;&#1083;&#1099; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1099; &#1087;&#1086;&#1087;&#1072;&#1088;&#1085;&#1086; (&#1087;&#1086; &#1087;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087;&#1091; &quot;&#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1089; &#1082;&#1072;&#1078;&#1076;&#1099;&#1084;&quot;)
    </p>
    <ul>
      <li>
        &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1077; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080; &#1089;&#1077;&#1090;&#1080; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1076;&#1088;&#1091;&#1075; &#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084; &#1080; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1099; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1085;&#1072; &#1089;&#1077;&#1073;&#1103; &#1088;&#1086;&#1083;&#1100; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072; &#1076;&#1083;&#1103; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1086;&#1074;
      </li>
      <li>
        <b>partial mesh topology</b>&#160;- &#1085;&#1077;&#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1074;&#1103;&#1079;&#1085;&#1072;&#1103; (&#1095;&#1072;&#1089;&#1090;&#1080;&#1095;&#1085;&#1086; &#1089;&#1074;&#1103;&#1079;&#1085;&#1072;&#1103;) &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; - &#1087;&#1086; &#1082;&#1088;&#1072;&#1081;&#1085;&#1077;&#1081; &#1084;&#1077;&#1088;&#1077; &#1086;&#1076;&#1085;&#1086; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081; &#1089; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;&#1080; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1084;&#1080;
      </li>
      <li>
        <b>full mesh topology</b>&#160;- &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1074;&#1103;&#1079;&#1085;&#1072;&#1103; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; - &#1074;&#1089;&#1077; &#1091;&#1079;&#1083;&#1099; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1099; &#1076;&#1088;&#1091;&#1075; &#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;. &#1053;&#1072;&#1080;&#1073;&#1086;&#1083;&#1077;&#1077; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1072;&#1103; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103;, &#1085;&#1086; &#1089;&#1072;&#1084;&#1072;&#1103; &#1076;&#1086;&#1088;&#1086;&#1075;&#1072;&#1103; (&#1089;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1084;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1086;&#1074;, &#1087;&#1086;&#1088;&#1090;&#1086;&#1074;). &#1059; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1089;&#1074;&#1103;&#1079;&#1080;. &#1042;&#1099;&#1089;&#1086;&#1082;&#1072;&#1103; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1100;. &#1044;&#1086;&#1088;&#1086;&#1075;&#1086;&#1089;&#1090;&#1086;&#1103;&#1097;&#1077;&#1077; &#1074;&#1085;&#1077;&#1076;&#1088;&#1077;&#1085;&#1080;&#1077;. (e.g. DMVPN)
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
