<node TEXT="Одноранговая сеть (P2P, Workgroup)" FOLDED="true" ID="ID_189378427" CREATED="1519112080290" MODIFIED="1544799660461"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1054;&#1076;&#1085;&#1086;&#1088;&#1072;&#1085;&#1075;&#1086;&#1074;&#1072;&#1103;</b>, &#1076;&#1077;&#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1083;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1080;&#1083;&#1080; <b>&#1087;&#1080;&#1088;&#1080;&#1085;&#1075;&#1086;&#1074;&#1072;&#1103;</b>&#160; (peer-to-peer, P2P - &#1088;&#1072;&#1074;&#1085;&#1099;&#1081; &#1082; &#1088;&#1072;&#1074;&#1085;&#1086;&#1084;&#1091;) &#1089;&#1077;&#1090;&#1100; - &#1101;&#1090;&#1086; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1085;&#1072;&#1103; &#1089;&#1077;&#1090;&#1100;, &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1085;&#1072; &#1088;&#1072;&#1074;&#1085;&#1086;&#1087;&#1088;&#1072;&#1074;&#1080;&#1080; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1086;&#1074;.
    </p>
    <ul>
      <li>
        &#1063;&#1072;&#1089;&#1090;&#1086; &#1074; &#1090;&#1072;&#1082;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080; &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1099;, &#1072; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1091;&#1079;&#1077;&#1083; (peer) <b>&#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1084;, &#1090;&#1072;&#1082; &#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;</b>
      </li>
      <li>
        &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1100; &#1088;&#1072;&#1073;&#1086;&#1090;&#1086;&#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1077;&#1090;&#1080; &#1087;&#1088;&#1080; &#1083;&#1102;&#1073;&#1086;&#1084; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1080; &#1083;&#1102;&#1073;&#1086;&#1084; &#1089;&#1086;&#1095;&#1077;&#1090;&#1072;&#1085;&#1080;&#1080; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;&#1093; &#1091;&#1079;&#1083;&#1086;&#1074;
      </li>
    </ul>
