<node TEXT="Развертывание" ID="ID_849232970" CREATED="1519112080291" MODIFIED="1519112080291"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ol>
      <li>
        <b>&#1057;&#1090;&#1072;&#1074;&#1080;&#1084; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1091;&#1102; OS</b>&#160;(&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; WXP).
      </li>
      <li>
        <b>&#1057;&#1077;&#1090;&#1077;&#1074;&#1099;&#1077; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#160;(&#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077;)</b>&#160;&#1091; &#1074;&#1089;&#1077;&#1093; PC &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103;, &#1085;&#1086; &#1080;&#1084;&#1077;&#1090;&#1100; &#1086;&#1076;&#1085;&#1091; &#1084;&#1072;&#1089;&#1082;&#1091; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; 192.168.0.x, mask 255.255.255.0)
      </li>
      <li>
        <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1089;&#1077;&#1090;&#1100;.</b>&#160;&#1042;&#1088;&#1077;&#1084;&#1103; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1099;&#1084;.

        <ul>
          <li>
            <b>Windows XP</b>. Network Connections\ Set up a home or small office network &gt; 2Next\ Select a connection metod\ Other &gt; Other Internet connection methods\ This computer belongs to a network that does not have an Internet connection &gt; &lt;&#1053;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099;&gt; File and printer sharing\ Turn on... &gt; Just finish the wizard...
          </li>
          <li>
            <b>W7</b>. <b>W8.1</b>. &#1052;&#1077;&#1085;&#1103;&#1077;&#1084; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1085;&#1072; &#1091;&#1078;&#1077; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1091;&#1102; &#1074; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;. Compuper\ Properties\ Change settings\ Network ID\ This computer is part...<br/>&#1055;&#1077;&#1088;&#1074;&#1099;&#1081; PC &#1080;&#1085;&#1080;&#1094;&#1080;&#1080;&#1088;&#1091;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1056;&#1072;&#1073;&#1086;&#1095;&#1077;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099;, &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; HomeGroupUser$ &#1089; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1084;, &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1077;&#1075;&#1086; &#1080; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1102;&#1090; &#1087;&#1088;&#1080;&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1102;&#1097;&#1080;&#1077;&#1089;&#1103; &#1082; &#1056;&#1072;&#1073;&#1086;&#1095;&#1077;&#1081; &#1075;&#1088;&#1091;&#1087;&#1087;&#1077;. &#1044;&#1088;&#1091;&#1075;&#1080;&#1077; Join&#1103;&#1090;&#1089;&#1103; (&#1090;&#1086;&#1078;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; &#1044;&#1086;&#1084;&#1096;&#1085;&#1102;&#1102; &#1089;&#1077;&#1090;&#1100;).<br/>Open network and sharing Center\ Choose homegroup and sharing options\ <b>Home network</b>. &#1045;&#1089;&#1083;&#1080; &#1089;&#1077;&#1090;&#1100; &#1085;&#1077; &#1093;&#1086;&#1095;&#1077;&#1090; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1086;&#1084;&#1072;&#1096;&#1085;&#1077;&#1081;, <b>&#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1096;&#1083;&#1102;&#1079;&#1086;&#1084;</b>&#160;&#1076;&#1088;&#1091;&#1075;&#1091;&#1102; &#1084;&#1072;&#1096;&#1080;&#1085;&#1091;.
          </li>
          <li>
            &#1063;&#1090;&#1086;&#1073;&#1099; XP &#1073;&#1088;&#1072;&#1074;&#1086; &#1079;&#1072;&#1093;&#1086;&#1076;&#1080;&#1083;&#1080; &#1085;&#1072; W7 &#1080; W8, &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1074;&#1093;&#1086;&#1076; &#1087;&#1086; &#1087;&#1072;&#1088;&#1086;&#1083;&#1102; (<i>Network and Sharing Center\ Change advanced sharing settings\ (current profile)\ <b>Turn off passsword protected sharing</b></i>), &#1083;&#1080;&#1073;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1089; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1084; (&#1095;&#1077;&#1088;&#1077;&#1079; Competer\ Manage)
          </li>
        </ul>
      </li>
      <li>
        <b>&#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1074;&#1072;&#1077;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084; &#1087;&#1088;&#1072;&#1074;&#1072;</b>. &#1063;&#1090;&#1086;&#1073;&#1099; &#1074;&#1080;&#1088;&#1091;&#1089; &#1085;&#1077; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1083; &#1089; &#1087;&#1088;&#1072;&#1074;&#1072;&#1084;&#1080; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1072;&#1076;&#1084;&#1080;&#1085;&#1072;, &#1085;&#1091; &#1080; &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1085;&#1077; &#1089;&#1090;&#1072;&#1074;&#1080;&#1083; &#1074;&#1089;&#1103;&#1082;&#1091;&#1102; &#1093;&#1088;&#1077;&#1085;&#1100; &#1085;&#1072; PC. &#1044;&#1077;&#1083;&#1072;&#1077;&#1084; &#1074;&#1089;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; Computer Management (<font color="#0000c0">compmgmt.msc</font>&#160;&#1080;&#1083;&#1080; MyComputer\Manage). &#1053;&#1072;&#1096;&#1077;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1084; &#1080;&#1079; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1072;&#1076;&#1084;&#1080;&#1085;&#1086;&#1074; &#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084;&#160;&#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; Users.
      </li>
      <li>
        <b>&#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1073;&#1099;&#1089;&#1090;&#1088;&#1099;&#1081; &#1083;&#1086;&#1075;&#1086;&#1085; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;</b>. <b>XP</b>\ Control Panel\ User Accounts\ Change the way user log on or off. <b>W7</b>\ Administrative Tools\ Local Security Policy &gt; Local Policies\ Security Options\ Interactive logon: Do not require CTRL+ALT+DEL &gt; Disabled
      </li>
      <li>
        <b>&#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1074;&#1099;&#1074;&#1086;&#1076; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1075;&#1086; &#1080;&#1084;&#1077;&#1085;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1087;&#1088;&#1080; &#1083;&#1086;&#1075;&#1086;&#1085;&#1077;</b>. Administrative Tools\ Local Security Policy &gt; Local Policies\ Security Options\ Interactive logon: Do not desplay last user name\ Enabled
      </li>
    </ol>
  </body>
</html></richcontent>
