<node TEXT="Ring Logical (FDDI and token ring)" ID="ID_879528160" CREATED="1519112080073" MODIFIED="1519112080073"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1058;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; FDDI </b>&#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1072; &#1076;&#1083;&#1103; &#1087;&#1086;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1080;&#1103; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1089;&#1074;&#1103;&#1079;&#1080; (backbone), &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1103;&#1102;&#1097;&#1080;&#1093; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;. &#1055;&#1088;&#1086;&#1089;&#1090;&#1077;&#1081;&#1096;&#1080;&#1084; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1086;&#1084; &#1090;&#1072;&#1082;&#1086;&#1081; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1080; &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1076;&#1074;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;, &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1085;&#1099;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1084; &#1089;&#1074;&#1103;&#1079;&#1080;, &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1084; &#1085;&#1072; &#1073;&#1072;&#1079;&#1077; &#1076;&#1074;&#1091;&#1093; &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1093; &#1082;&#1072;&#1088;&#1090; &#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;.
    </p>
    <ul>
      <li>
        FDDI &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; 100 &#1052;&#1073;&#1080;&#1090;/&#1089;
      </li>
      <li>
        &#1057;&#1077;&#1090;&#1100; FDDI &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1102; &#1076;&#1074;&#1086;&#1081;&#1085;&#1086;&#1075;&#1086; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1082;&#1086;&#1083;&#1100;&#1094;&#1072;. <b>&#1044;&#1074;&#1086;&#1081;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;&#1100;&#1094;&#1086;</b>. &#1055;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1097;&#1080;&#1077;&#1089;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1099; &#1076;&#1074;&#1080;&#1078;&#1091;&#1090;&#1089;&#1103; &#1087;&#1086; &#1082;&#1086;&#1083;&#1100;&#1094;&#1072;&#1084; &#1074; &#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1086;&#1087;&#1086;&#1083;&#1086;&#1078;&#1085;&#1099;&#1093; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;&#1093;. &#1054;&#1076;&#1085;&#1086; &#1080;&#1079; &#1082;&#1086;&#1083;&#1077;&#1094; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; <b>&#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1099;&#1084;</b>, &#1072; &#1076;&#1088;&#1091;&#1075;&#1086;&#1077; - <b>&#1074;&#1090;&#1086;&#1088;&#1080;&#1095;&#1085;&#1099;&#1084;</b>. &#1055;&#1088;&#1080; &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1085;&#1086;&#1084; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1089;&#1077;&#1090;&#1080; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;&#1100;&#1094;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1072; &#1074;&#1090;&#1086;&#1088;&#1080;&#1095;&#1085;&#1086;&#1077; &#1074;&#1099;&#1089;&#1090;&#1091;&#1087;&#1072;&#1077;&#1090; &#1074; &#1088;&#1086;&#1083;&#1080; &#1079;&#1072;&#1087;&#1072;&#1089;&#1085;&#1086;&#1075;&#1086;
      </li>
      <li>
        &#1042; &#1089;&#1077;&#1090;&#1080; FDDI &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; (&#1091;&#1079;&#1077;&#1083; &#1089;&#1077;&#1090;&#1080;) &#1080;&#1075;&#1088;&#1072;&#1077;&#1090; &#1088;&#1086;&#1083;&#1100; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1080;&#1090;&#1077;&#1083;&#1103;. FDDI &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1095;&#1077;&#1090;&#1099;&#1088;&#1077; &#1074;&#1080;&#1076;&#1072; &#1091;&#1079;&#1083;&#1086;&#1074;: &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1103; &#1089; &#1076;&#1074;&#1086;&#1081;&#1085;&#1099;&#1084; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; (DAS - dual-attached stations), &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1103; &#1089; &#1086;&#1076;&#1080;&#1085;&#1072;&#1088;&#1085;&#1099;&#1084; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; (SAS - single-attached stations), &#1082;&#1086;&#1085;&#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088; &#1089; &#1076;&#1074;&#1086;&#1081;&#1085;&#1099;&#1084; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; (DAC - dual-attached concentrator) &#1080; &#1082;&#1086;&#1085;&#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088; &#1089; &#1086;&#1076;&#1080;&#1085;&#1072;&#1088;&#1085;&#1099;&#1084; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; (SAC-single-attached concentrator). DAS &#1080; DAC &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1090;&#1089;&#1103; &#1082; &#1086;&#1073;&#1086;&#1080;&#1084; &#1082;&#1086;&#1083;&#1100;&#1094;&#1072;&#1084;, a SAS &#1080; SAC - &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1086;&#1084;&#1091; &#1082;&#1086;&#1083;&#1100;&#1094;&#1091;
      </li>
      <li>
