        &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1086;&#1073;&#1084;&#1077;&#1085; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1077;&#1081; &#1084;&#1077;&#1078;&#1076;&#1091; &#1090;&#1072;&#1082;&#1080;&#1084;&#1080; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1084;&#1080;, &#1082;&#1072;&#1082; &#1087;&#1077;&#1088;&#1089;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1099;, &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1099;&#1077; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1099;, &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1099;, &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1099;&#1077; &#1092;&#1086;&#1090;&#1086;&#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1099;, &#1084;&#1099;&#1096;&#1082;&#1080;, &#1082;&#1083;&#1072;&#1074;&#1080;&#1072;&#1090;&#1091;&#1088;&#1099;, &#1076;&#1078;&#1086;&#1081;&#1089;&#1090;&#1080;&#1082;&#1080;, &#1085;&#1072;&#1091;&#1096;&#1085;&#1080;&#1082;&#1080;, &#1075;&#1072;&#1088;&#1085;&#1080;&#1090;&#1091;&#1088;&#1099; &#1085;&#1072; &#1085;&#1072;&#1076;&#1105;&#1078;&#1085;&#1086;&#1081;, &#1073;&#1077;&#1089;&#1087;&#1083;&#1072;&#1090;&#1085;&#1086;&#1081;, &#1087;&#1086;&#1074;&#1089;&#1077;&#1084;&#1077;&#1089;&#1090;&#1085;&#1086; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1081; &#1088;&#1072;&#1076;&#1080;&#1086;&#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1077; &#1076;&#1083;&#1103; &#1073;&#1083;&#1080;&#1078;&#1085;&#1077;&#1081; &#1089;&#1074;&#1103;&#1079;&#1080;.
