    <p>
      <b>LAN (Local Area Network) - &#1051;&#1042;&#1057; (&#1051;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1077;&#1090;&#1100;, &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1077;&#1090;&#1100;) -&#160; </b>&#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1085;&#1072;&#1103; &#1089;&#1077;&#1090;&#1100;, &#1087;&#1086;&#1082;&#1088;&#1099;&#1074;&#1072;&#1102;&#1097;&#1072;&#1103; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1091;&#1102; &#1090;&#1077;&#1088;&#1088;&#1080;&#1090;&#1086;&#1088;&#1080;&#1102; &#1080;&#1083;&#1080; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1091;&#1102; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; &#1079;&#1076;&#1072;&#1085;&#1080;&#1081; (&#1076;&#1086;&#1084;, &#1086;&#1092;&#1080;&#1089;, &#1092;&#1080;&#1088;&#1084;&#1091;, &#1080;&#1085;&#1089;&#1090;&#1080;&#1090;&#1091;&#1090;).
    </p>
    <ul>
      <li>
        &#1076;&#1086; &#1089;&#1086;&#1090;&#1077;&#1085; &#1091;&#1095;&#1072;&#1089;&#1090;&#1085;&#1080;&#1082;&#1086;&#1074;
      </li>
      <li>
        &#1088;&#1072;&#1076;&#1080;&#1091;&#1089; - 100 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1086;&#1076;&#1080;&#1085; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090; (&#1086;&#1076;&#1080;&#1085; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;)
      </li>
      <li>
        &#1085;&#1077;&#1090; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1089;&#1077;&#1073;&#1103;
      </li>
      <li>
        &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1077;&#1089;&#1090;&#1100; &#1096;&#1083;&#1102;&#1079; &#1074;&#1099;&#1093;&#1086;&#1076;&#1072; &#1074; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090; - &#1086;&#1085; &#1086;&#1076;&#1080;&#1085;
      </li>
      <li>
        802.3, 802.4, 802.5, 802.11
      </li>
      <li>
        &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; - &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1099; (&#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1074;&#1090;&#1099;&#1082;&#1072;&#1102;&#1090;&#1089;&#1103; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1099; - &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1099;, &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1077; &#1084;&#1077;&#1089;&#1090;&#1072;, &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;), &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1099; (&#1076;&#1083;&#1103; &#1074;&#1099;&#1093;&#1086;&#1076;&#1072; &#1074; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1089;&#1077;&#1090;&#1100;)
      </li>
      <li>
        &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; <a href="#ID_293756873">NIC</a>&#160;
      </li>
      <li>
        &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1099;: Ethernet, IP, ARP, DHCP
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>Ethernet Type II Frame (64-1518 bytes)</b>
    </p>
    <ul>
      <li>
        MAC Header (14 bytes)

        <ul>
          <li>
            Destination MAC Address
          </li>
          <li>
            Source MAC Address
          </li>
          <li>
            EtherType
          </li>
        </ul>
      </li>
      <li>
        Data (46-1500 bytes)

        <ul>
          <li>
            Payload
          </li>
        </ul>
      </li>
      <li>
        CRC Checksum (4 bytes)
      </li>
    </ul>
  </body>
</html></richcontent>
