<node TEXT="Помехозащищенность" ID="ID_1508079063" CREATED="1519112080066" MODIFIED="1519112080066"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1086;&#1084;&#1077;&#1093;&#1086;&#1079;&#1072;&#1097;&#1080;&#1097;&#1077;&#1085;&#1085;&#1086;&#1089;&#1090;&#1100; &#1083;&#1080;&#1085;&#1080;&#1080;</b>&#160;- &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1100; &#1083;&#1080;&#1085;&#1080;&#1080; &#1091;&#1084;&#1077;&#1085;&#1100;&#1096;&#1072;&#1090;&#1100; &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1087;&#1086;&#1084;&#1077;&#1093;, &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1099;&#1093; &#1074;&#1086; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1089;&#1088;&#1077;&#1076;&#1077; &#1080; &#1085;&#1072; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1085;&#1080;&#1082;&#1072;&#1093;.
    </p>
    <ul>
      <li>
        &#1088;&#1072;&#1076;&#1080;&#1086;&#1083;&#1080;&#1085;&#1080;&#1080; &#1080;&#1084;&#1077;&#1102;&#1090; &#1085;&#1072;&#1080;&#1084;&#1077;&#1085;&#1100;&#1096;&#1080;&#1081; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100; &#1087;&#1086;&#1084;&#1077;&#1093;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1080;
      </li>
      <li>
        &#1074;&#1080;&#1090;&#1072;&#1103; &#1087;&#1072;&#1088;&#1072; &#1073;&#1086;&#1083;&#1077;&#1077; &#1087;&#1086;&#1076;&#1074;&#1077;&#1088;&#1078;&#1077;&#1085;&#1072; &#1096;&#1091;&#1084;&#1091; &#1095;&#1077;&#1084; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1086;-&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1083;&#1080;&#1085;&#1080;&#1103;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>&#1058;&#1080;&#1087;&#1099; &#1096;&#1091;&#1084;&#1086;&#1074; &#1080; &#1087;&#1086;&#1084;&#1077;&#1093;.</b>
    </p>
    <ul>
      <li>
        <b>&#1055;&#1077;&#1088;&#1077;&#1082;&#1088;&#1077;&#1089;&#1090;&#1085;&#1099;&#1077; &#1085;&#1072;&#1074;&#1086;&#1076;&#1082;&#1080; (Crosstalk)</b>&#160;&#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1072;&#1102;&#1090;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1101;&#1083;.&#1084;&#1072;&#1075;&#1085;&#1080;&#1090;&#1085;&#1086;&#1077; &#1087;&#1086;&#1083;&#1077; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1086;&#1075;&#1086; &#1074;&#1099;&#1093;&#1086;&#1076;&#1086;&#1084; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1072; &#1087;&#1086; &#1086;&#1076;&#1085;&#1086;&#1081; &#1087;&#1072;&#1088;&#1077; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1086;&#1074;, &#1085;&#1072;&#1074;&#1086;&#1076;&#1080;&#1090; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1091;&#1102; &#1087;&#1072;&#1088;&#1091; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1086;&#1074; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1087;&#1086;&#1084;&#1077;&#1093;&#1080;:

        <ul>
          <li>
            &#1085;&#1072; &#1073;&#1083;&#1080;&#1078;&#1085;&#1077;&#1084; &#1082;&#1086;&#1085;&#1094;&#1077; (Near End Cross Talk, NEXT)
          </li>
          <li>
            &#1085;&#1072; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1084; &#1082;&#1086;&#1085;&#1094;&#1077;&#160;(Far End Cross Talk, FEXT )
          </li>
        </ul>
      </li>
      <li>
        <b>&#1069;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1084;&#1072;&#1075;&#1085;&#1080;&#1090;&#1085;&#1072;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1103;&#160;(Electro Magnetic Interference, EMI)</b>. &#1069;&#1083;&#1077;&#1082;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1096;&#1091;&#1084; &#1086;&#1090; &#1083;&#1072;&#1084;&#1087; &#1076;&#1085;&#1077;&#1074;&#1085;&#1086;&#1075;&#1086; &#1089;&#1074;&#1077;&#1090;&#1072;, &#1082;&#1086;&#1085;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1077;&#1088;&#1086;&#1074;, &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1086;&#1074;, &#1101;&#1083;. &#1076;&#1074;&#1080;&#1075;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;.
      </li>
      <li>
        <b>&#1056;&#1072;&#1076;&#1080;&#1086;&#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1085;&#1072;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1088;&#1077;&#1085;&#1094;&#1080;&#1103; (Radio Friquency Interference, RFI)</b>. &#1069;&#1083;&#1077;&#1082;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1096;&#1091;&#1084; &#1086;&#1090; &#1088;&#1072;&#1076;&#1080;&#1086;&#1089;&#1080;&#1089;&#1090;&#1077;&#1084;.
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1087;&#1086;&#1089;&#1086;&#1073;&#1099; &#1073;&#1086;&#1088;&#1100;&#1073;&#1099; &#1089; &#1087;&#1086;&#1084;&#1077;&#1093;&#1072;&#1084;&#1080;.</b>
    </p>
    <ul>
      <li>
        <b>&#1069;&#1082;&#1088;&#1072;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; (shielding).</b>&#160;&#1042; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077; &#1084;&#1077;&#1090;. &#1086;&#1087;&#1083;&#1077;&#1090;&#1082;&#1072; &#1080;&#1083;&#1080; &#1092;&#1086;&#1083;&#1100;&#1075;&#1072; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1082;&#1072;&#1082; &#1073;&#1072;&#1088;&#1100;&#1077;&#1088; &#1076;&#1083;&#1103; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1093; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1086;&#1074;.
      </li>
      <li>
        <b>&#1055;&#1086;&#1076;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; (cancellation)</b>. &#1052;&#1072;&#1075;&#1085;. &#1087;&#1086;&#1083;&#1103; &#1076;&#1074;&#1091;&#1093; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1086;&#1074; &#1089;&#1090;&#1072;&#1085;&#1091;&#1090; &#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1086;&#1087;&#1086;&#1083;&#1086;&#1078;&#1085;&#1099;, &#1090;.&#1086;. &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1086;&#1076;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1076;&#1088;&#1091;&#1075; &#1076;&#1088;&#1091;&#1075;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1080;&#1093; &#1086;&#1095;&#1077;&#1085;&#1100; &#1073;&#1083;&#1080;&#1079;&#1082;&#1086; &#1076;&#1088;&#1091;&#1075; &#1082; &#1076;&#1088;&#1091;&#1075;&#1091;. &#1057;&#1082;&#1088;&#1091;&#1095;&#1080;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1086;&#1074; &#1091;&#1089;&#1080;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090; &#1087;&#1086;&#1076;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
      </li>
    </ul>
  </body>
</html></richcontent>
