      </li>
      <li>
        <b>&#1089;&#1087;&#1083;&#1080;&#1090;&#1090;&#1077;&#1088;</b>&#160;(Splitter, &#1084;&#1080;&#1082;&#1088;&#1086;&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;, &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1099; &#1085;&#1080;&#1079;&#1082;&#1080;&#1093; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;)&#160;&#1086;&#1090;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1090;&#1077;&#1083;. &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1086;&#1090; ADSL &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;. &#1055;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; &#1082; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072;&#1084; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; <b>&#1085;&#1080;&#1079;&#1082;&#1086;&#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1085;&#1091;&#1102;</b>&#160;&#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1091;&#1102; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072;. &#1055;&#1086;&#1076;&#1082;&#1083;. &#1082; &#1090;&#1077;&#1083;. &#1088;&#1086;&#1079;&#1077;&#1090;&#1082;&#1077;.
      </li>
