  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103; PON</b>
    </p>
    <ul>
      <li>
        &#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1072;&#1103; &#1080;&#1076;&#1077;&#1103; &#1072;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1099; PON &#8212; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1080;&#1105;&#1084;&#1086;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1074; <b>OLT</b>&#160; (optical line terminal) &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1091; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074; <b>ONT</b>&#160; (optical network terminal &#1074; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; ITU-T), &#1090;&#1072;&#1082;&#1078;&#1077; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;&#1099;&#1093; <b>ONU</b>&#160; (optical network unit) &#1074; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; IEEE &#1080; &#1087;&#1088;&#1080;&#1105;&#1084;&#1072; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1086;&#1090; &#1085;&#1080;&#1093;.
      </li>
      <li>
        &#1063;&#1080;&#1089;&#1083;&#1086; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1093; &#1091;&#1079;&#1083;&#1086;&#1074;, &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; &#1082; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1087;&#1088;&#1080;&#1105;&#1084;&#1086;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1097;&#1077;&#1084;&#1091; &#1084;&#1086;&#1076;&#1091;&#1083;&#1102; <b>OLT</b>, &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1085;&#1072;&#1089;&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084;, &#1085;&#1072;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1073;&#1102;&#1076;&#1078;&#1077;&#1090; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1087;&#1088;&#1080;&#1105;&#1084;&#1086;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1097;&#1077;&#1081; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1091;&#1088;&#1099;. &#1044;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1087;&#1086;&#1090;&#1086;&#1082;&#1072; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1086;&#1090; <b>OLT</b>&#160;&#1082; <b>ONT</b>&#160;- &#1087;&#1088;&#1103;&#1084;&#1086;&#1075;&#1086; (&#1085;&#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1075;&#1086;) &#1087;&#1086;&#1090;&#1086;&#1082;&#1072;, &#1082;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1080;&#1085;&#1092;&#1088;&#1072;&#1082;&#1088;&#1072;&#1089;&#1085;&#1086;&#1077; &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089; &#1076;&#1083;&#1080;&#1085;&#1086;&#1081; &#1074;&#1086;&#1083;&#1085;&#1099; 1490 &#1085;&#1084;. &#1053;&#1072;&#1086;&#1073;&#1086;&#1088;&#1086;&#1090;, &#1087;&#1086;&#1090;&#1086;&#1082;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1086;&#1090; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1093; &#1091;&#1079;&#1083;&#1086;&#1074; &#1074; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1091;&#1079;&#1077;&#1083;, &#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1085;&#1086; &#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1102;&#1097;&#1080;&#1077; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; (&#1074;&#1086;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081;) &#1087;&#1086;&#1090;&#1086;&#1082;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; 1310 &#1085;&#1084;. &#1044;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1090;&#1077;&#1083;&#1077;&#1074;&#1080;&#1076;&#1077;&#1085;&#1080;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1080;&#1085;&#1072; &#1074;&#1086;&#1083;&#1085;&#1099; 1550 &#1085;&#1084;. &#1042; OLT &#1080; ONT &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1099; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1086;&#1088;&#1099; <a href="#ID_1220708720">WDM</a>, &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1103;&#1102;&#1097;&#1080;&#1077; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1080; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1087;&#1086;&#1090;&#1086;&#1082;&#1080;.
      </li>
      <li>
        <b>&#1055;&#1088;&#1103;&#1084;&#1086;&#1081; &#1087;&#1086;&#1090;&#1086;&#1082;</b>&#160;&#1085;&#1072; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1086;&#1074; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1074;&#1077;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084;. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1081; &#1091;&#1079;&#1077;&#1083; <b>ONT</b>, &#1095;&#1080;&#1090;&#1072;&#1103; &#1072;&#1076;&#1088;&#1077;&#1089;&#1085;&#1099;&#1077; &#1087;&#1086;&#1083;&#1103;, &#1074;&#1099;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1080;&#1079; &#1101;&#1090;&#1086;&#1075;&#1086; &#1086;&#1073;&#1097;&#1077;&#1075;&#1086; &#1087;&#1086;&#1090;&#1086;&#1082;&#1072; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1091;&#1102; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1077;&#1084;&#1091; &#1095;&#1072;&#1089;&#1090;&#1100; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;. &#1060;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1084;&#1099; &#1080;&#1084;&#1077;&#1077;&#1084; &#1076;&#1077;&#1083;&#1086; &#1089; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1105;&#1085;&#1085;&#1099;&#1084; &#1076;&#1077;&#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1086;&#1088;&#1086;&#1084;.
      </li>
      <li>
        &#1054;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1087;&#1086;&#1090;&#1086;&#1082;. &#1042;&#1089;&#1077; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1077; &#1091;&#1079;&#1083;&#1099; <b>ONT</b>&#160; &#1074;&#1077;&#1076;&#1091;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1091; &#1074; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084; &#1087;&#1086;&#1090;&#1086;&#1082;&#1077; &#1085;&#1072; &#1086;&#1076;&#1085;&#1086;&#1081; &#1080; &#1090;&#1086;&#1081; &#1078;&#1077; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; &#1082;&#1086;&#1085;&#1094;&#1077;&#1087;&#1094;&#1080;&#1102; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1089; <b>&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1067;&#1084; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084;</b>&#160;TDMA (time division multiple access). &#1063;&#1090;&#1086;&#1073;&#1099; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1089;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1086;&#1074; &#1086;&#1090; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; ONT, &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1080;&#1079; &#1085;&#1080;&#1093; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1074;&#1086;&#1105; &#1080;&#1085;&#1076;&#1080;&#1074;&#1080;&#1076;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1087;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089; &#1091;&#1095;&#1105;&#1090;&#1086;&#1084; &#1087;&#1086;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1085;&#1072; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1091;, &#1089;&#1074;&#1103;&#1079;&#1072;&#1085;&#1085;&#1091;&#1102; &#1089; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; ONT &#1086;&#1090; OLT. &#1069;&#1090;&#1091; &#1079;&#1072;&#1076;&#1072;&#1095;&#1091; &#1088;&#1077;&#1096;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; TDMA.
      </li>
    </ul>
