      <b>&#160;&#160;&#160;&#160;&#1042; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1093; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103;&#1093; &#1080; &#1089;&#1074;&#1103;&#1079;&#1080;</b>, <b>&#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; (multiplexing, muxing)</b>&#160; &#8212; &#1091;&#1087;&#1083;&#1086;&#1090;&#1085;&#1077;&#1085;&#1080;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;, &#1090;. &#1077;. &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074; (&#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;) &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1081; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100;&#1102; (&#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1085;&#1086;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;) &#1087;&#1086; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1082;&#1072;&#1085;&#1072;&#1083;&#1091;.
    </p>
    <p>
      <b>&#160;&#160;&#160;&#160;&#1042; &#1090;&#1077;&#1083;&#1077;&#1082;&#1086;&#1084;&#1084;&#1091;&#1085;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;&#1093;</b>&#160; <b>&#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;</b>&#160; - &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1084; &#1083;&#1086;&#1075;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;&#1084; &#1089;&#1074;&#1103;&#1079;&#1080; &#1074; &#1086;&#1076;&#1085;&#1086;&#1084; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083;&#1077;. &#1055;&#1086;&#1076; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1084; &#1087;&#1086;&#1076;&#1088;&#1072;&#1079;&#1091;&#1084;&#1077;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083; &#1089;&#1086; &#1089;&#1074;&#1086;&#1077;&#1081; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1085;&#1086;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#8212; &#1084;&#1077;&#1076;&#1085;&#1099;&#1081; &#1080;&#1083;&#1080; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;, &#1088;&#1072;&#1076;&#1080;&#1086;&#1082;&#1072;&#1085;&#1072;&#1083;.
    </p>
    <p>
      &#160;&#160;&#160; <b>&#1042; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1093; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103;&#1093; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;</b>&#160; - &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; (&#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;) &#1074; &#1086;&#1076;&#1080;&#1085;. &#1055;&#1088;&#1080;&#1084;&#1077;&#1088;&#1086;&#1084; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1089;&#1083;&#1091;&#1078;&#1080;&#1090;&#1100; &#1074;&#1080;&#1076;&#1077;&#1086;&#1092;&#1072;&#1081;&#1083;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1087;&#1086;&#1090;&#1086;&#1082; (&#1082;&#1072;&#1085;&#1072;&#1083;) &#1074;&#1080;&#1076;&#1077;&#1086; &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089; &#1086;&#1076;&#1085;&#1080;&#1084; &#1080;&#1083;&#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1084;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;&#1084;&#1080; &#1072;&#1091;&#1076;&#1080;&#1086;.
    </p>
    <ul>
      <li>
        &#1059;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1080;&#1083;&#1080; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072;, &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1102;&#1097;&#1072;&#1103; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;, &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; <b>&#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1086;&#1088;&#1086;&#1084;</b>
      </li>
      <li>
        &#1085;&#1072; &#1084;&#1085;&#1086;&#1075;&#1080;&#1093; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1086;&#1088;&#1072;&#1093; &#1077;&#1089;&#1090;&#1100; <b>&#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1081; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;</b>&#160;&#1076;&#1083;&#1103; &#1089;&#1074;&#1103;&#1079;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1091;&#1079;&#1083;&#1072;&#1084;&#1080; &#1089;&#1077;&#1090;&#1080;
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="FDM" ID="ID_72839121" CREATED="1519112080067" MODIFIED="1519112080067"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084; &#1087;&#1086; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1077; (FDM), Frequency Division Multiplexing</b>&#160;- &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077; &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1087;&#1086;&#1083;&#1086;&#1089;&#1099; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1085;&#1080;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1089; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1081; &#1096;&#1080;&#1088;&#1080;&#1085;&#1086;&#1081;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1088;&#1072;&#1076;&#1080;&#1086;&#1074;&#1077;&#1097;&#1072;&#1085;&#1080;&#1077;, &#1075;&#1076;&#1077; &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072; (&#1088;&#1072;&#1076;&#1080;&#1086;&#1101;&#1092;&#1080;&#1088;&#1072;) &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1077;&#1085;&#1086; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1086; &#1088;&#1072;&#1076;&#1080;&#1086;&#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1085;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1072;&#1093; (&#1074; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1085;&#1099;&#1093; &#1087;&#1086;&#1083;&#1086;&#1089;&#1072;&#1093;). &#1055;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077;:
    </p>
    <ul>
      <li>
        &#1074; &#1089;&#1077;&#1090;&#1103;&#1093; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1074;&#1103;&#1079;&#1080; (FDMA) &#1076;&#1083;&#1103; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;
      </li>
      <li>
        &#1074; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1086;-&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1089;&#1074;&#1103;&#1079;&#1080; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1084; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084; &#1087;&#1086; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; (WDM) (&#1075;&#1076;&#1077; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1072; &#8212; &#1101;&#1090;&#1086; &#1094;&#1074;&#1077;&#1090; &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1080;&#1079;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1103;)
      </li>
      <li>
        &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; X-DSL. &#1055;&#1086; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1099;&#1084; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1072;&#1084; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1099; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1086;&#1081; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1099;: &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1099;&#1081; &#1088;&#1072;&#1079;&#1075;&#1086;&#1074;&#1086;&#1088;-0,3-3,4 &#1082;&#1043;&#1094; &#1072; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1083;&#1086;&#1089;&#1072; &#1086;&#1090; 28 &#1076;&#1086; 1300 &#1082;&#1043;&#1094;
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
