    <p>
      <b>&#1052;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084; &#1087;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; (TDM), Time Division Multiplexing, &#1042;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;</b>&#160;- &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1086;&#1075;&#1086; &#1080;&#1083;&#1080; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1086;&#1075;&#1086; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1086;&#1074; &#1080;&#1083;&#1080; &#1073;&#1080;&#1090;&#1086;&#1074;&#1099;&#1093; &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086; &#1082;&#1072;&#1082; &#1087;&#1086;&#1076;&#1082;&#1072;&#1085;&#1072;&#1083;&#1099; &#1074; &#1086;&#1076;&#1085;&#1086;&#1084; &#1082;&#1086;&#1084;&#1084;&#1091;&#1085;&#1080;&#1082;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083;&#1077;. &#1050;&#1072;&#1076;&#1088;&#1086;&#1074;&#1072;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076; &#1089; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1081; &#1096;&#1080;&#1088;&#1080;&#1085;&#1099; (&#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1085;&#1086;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1080;) &#1085;&#1072; &#1082;&#1072;&#1085;&#1072;&#1083;&#1099; &#1089; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1081; &#1086;&#1089;&#1074;&#1086;&#1073;&#1086;&#1078;&#1076;&#1072;&#1077;&#1090; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1076;&#1088;&#1072; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1075;&#1086; &#1086;&#1073;&#1098;&#1105;&#1084;&#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1082;&#1072;&#1076;&#1088;&#1086;&#1074; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1075;&#1086;. &#1055;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077;:
    </p>
    <ul>
      <li>
        &#1073;&#1077;&#1089;&#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1085;&#1099;&#1077; TDMA-&#1089;&#1077;&#1090;&#1080;, Wi-Fi, WiMAX;
      </li>
      <li>
        &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1103; &#1074; PDH &#1080; SONET/SDH;
      </li>
      <li>
        &#1087;&#1072;&#1082;&#1077;&#1090;&#1085;&#1072;&#1103; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1103; &#1074; ATM, Frame Relay, Ethernet, FDDI;
      </li>
      <li>
        &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1103; &#1074; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1103;&#1093;;
      </li>
      <li>
        &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1096;&#1080;&#1085;&#1099;: PCIe, USB
      </li>
    </ul>
  </body>
