  <body>
    <p>
      <b>PRI</b>, Primary Rate Interface - &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1089;&#1077;&#1090;&#1080; ISDN, &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081; &#1076;&#1080;&#1089;&#1094;&#1080;&#1087;&#1083;&#1080;&#1085;&#1091; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1081; ISDN &#1082; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1087;&#1086;&#1083;&#1086;&#1089;&#1085;&#1099;&#1084; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1103;&#1084;, &#1089;&#1074;&#1103;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1084; &#1084;&#1077;&#1089;&#1090;&#1085;&#1099;&#1077; &#1080; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1040;&#1058;&#1057; &#1080;&#1083;&#1080; &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1077; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1099;.
    </p>
    <ul>
      <li>
        <b>B-&#1082;&#1072;&#1085;&#1072;&#1083;&#1099;</b>&#160;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090; &#1079;&#1074;&#1091;&#1082;, &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1080; &#1087;&#1088;
      </li>
      <li>
        <b>D-&#1082;&#1072;&#1085;&#1072;&#1083;&#1099;</b>&#160;&#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084;&#1080;
      </li>
    </ul>
    <p>
      &#1048;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1103;&#1077;&#1090;:
    </p>
    <ul>
      <li>
        <b>&#1057;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090; E1</b>&#160; (&#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1105;&#1085; &#1074; &#1045;&#1074;&#1088;&#1086;&#1087;&#1077;) 30 &#1042;-&#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1080; &#1086;&#1076;&#1080;&#1085; D-&#1082;&#1072;&#1085;&#1072;&#1083; 30B+D. &#1069;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1085;&#1099;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1099; PRI &#1084;&#1086;&#1075;&#1091;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082;&#1072;&#1082; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1090;&#1072;&#1082; &#1080; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1086;&#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072;. (30B+D=32*64=2048[kBit/s])
      </li>
      <li>
        <b>&#1057;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090; &#1058;1</b>&#160; (&#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1077;&#1085; &#1074; &#1057;&#1077;&#1074;&#1077;&#1088;&#1085;&#1086;&#1081; &#1040;&#1084;&#1077;&#1088;&#1080;&#1082;&#1077; &#1080; &#1071;&#1087;&#1086;&#1085;&#1080;&#1080;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; - &#1074; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; DECT) 23 &#1042;-&#1082;&#1072;&#1085;&#1072;&#1083;&#1072; &#1080; &#1086;&#1076;&#1080;&#1085; D-&#1082;&#1072;&#1085;&#1072;&#1083; 23B+D. (23B + D=24*64=1536[kBit/s])
      </li>
    </ul>
    <p>
      ----------------
    </p>
    <p>
      E1 &#1103;&#1095;&#1077;&#1081;&#1082;&#1080;
    </p>
    <p>
