<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;, &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1087;&#1086; &#1090;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102; (On-Demand Multiplexing) -</b>&#160;&#1057;&#1093;&#1077;&#1084;&#1072; &#1072;&#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1085;&#1072;: &#1086;&#1073;&#1097;&#1080;&#1081; &#1074;&#1099;&#1093;&#1086;&#1076;&#1085;&#1086;&#1081; &#1087;&#1086;&#1090;&#1086;&#1082; &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1084;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;&#1084;&#1080;, &#1073;&#1083;&#1086;&#1082;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; (&#1087;&#1072;&#1082;&#1077;&#1090;&#1099;) &#1087;&#1086; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1087;&#1088;&#1080;&#1073;&#1099;&#1074;&#1072;&#1102;&#1090; &#1095;&#1077;&#1088;&#1077;&#1079; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077;, &#1074; &#1090;.&#1095;. &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1099;&#1077;, &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083;&#1099; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;, &#1085;&#1077;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086; &#1086;&#1090; &#1087;&#1088;&#1080;&#1073;&#1099;&#1090;&#1080;&#1081; &#1087;&#1086; &#1083;&#1102;&#1073;&#1086;&#1084;&#1091; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1084;&#1091; &#1082;&#1072;&#1085;&#1072;&#1083;&#1091;, &#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1080;&#1084;&#1077;&#1090;&#1100; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1083;&#1100;&#1085;&#1091;&#1102; &#1076;&#1083;&#1080;&#1085;&#1091;, &#1074; &#1090;.&#1095;. &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1091;&#1102;. &#1045;&#1089;&#1083;&#1080; &#1074;&#1086; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090;, &#1090;&#1086; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089; &#1074;&#1099;&#1093;&#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072; &#1077;&#1084;&#1091; &#1085;&#1077; &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103;. &#1055;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1079;&#1072;&#1085;&#1103;&#1090;, &#1085;&#1072; &#1074;&#1093;&#1086;&#1076;&#1072;&#1093; &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1085;&#1099; &#1073;&#1091;&#1092;&#1077;&#1088;&#1099; &#1076;&#1083;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;. &#1042; &#1089;&#1074;&#1103;&#1079;&#1080; &#1089; &#1101;&#1090;&#1080;&#1084; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1099; &#1074; &#1084;&#1077;&#1089;&#1090;&#1086; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1089; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1084;&#1080; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072;&#1084;&#1080;. &#1055;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077;:
    </p>
    <ul>
      <li>
        &#1089;&#1077;&#1090;&#1080; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1080; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;, &#1074; &#1090;.&#1095;. &#1089;&#1077;&#1090;&#1080; &#1089; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;&#1081; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1077;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;
      </li>
