<node TEXT="WDM/CWDM/DWDM" ID="ID_1220708720" CREATED="1519112080069" MODIFIED="1555180009360"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1930220747">&#1058;&#1088;&#1072;&#1085;&#1089;&#1080;&#1074;&#1077;&#1088;&#1099;</a>&#160;&#160;<a href="#ID_878800065">&#1054;&#1082;&#1085;&#1072; &#1087;&#1088;&#1086;&#1079;&#1088;&#1072;&#1095;&#1085;&#1086;&#1089;&#1090;&#1080;</a>&#160; <a href="#ID_503077712">OADM, WDM-&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1099;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084; &#1087;&#1086; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; (WDM),&#160;&#160;Wavelength Division Multiplexing, &#1057;&#1087;&#1077;&#1082;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1091;&#1087;&#1083;&#1086;&#1090;&#1085;&#1077;&#1085;&#1080;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; </b>- &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1072;&#1103; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1087;&#1086; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084;&#1091; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1091; &#1085;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1085;&#1077;&#1089;&#1091;&#1097;&#1080;&#1093; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1072;&#1093;. &#1042; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; &#1083;&#1077;&#1078;&#1080;&#1090; &#1092;&#1072;&#1082;&#1090; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086; &#1074;&#1086;&#1083;&#1085;&#1099; &#1089; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084;&#1080; &#1076;&#1083;&#1080;&#1085;&#1072;&#1084;&#1080; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1085;&#1077;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086; &#1076;&#1088;&#1091;&#1075; &#1086;&#1090; &#1076;&#1088;&#1091;&#1075;&#1072;. &#1042;&#1099;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090; &#1090;&#1088;&#1080; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1093; &#1090;&#1080;&#1087;&#1072; &#1089;&#1087;&#1077;&#1082;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1091;&#1087;&#1083;&#1086;&#1090;&#1085;&#1077;&#1085;&#1080;&#1103;: WDM, CWDM &#1080; DWDM.
    </p>
    <ul>
      <li>
        &#1075;&#1086;&#1088;&#1086;&#1076;&#1089;&#1082;&#1080;&#1077; &#1089;&#1077;&#1090;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
      </li>
      <li>
        &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1089;&#1077;&#1090;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
      </li>
    </ul>
    <p>
      <b>WDM (&#1089;&#1087;&#1077;&#1082;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;) - </b>&#1076;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1076;&#1091;&#1087;&#1083;&#1077;&#1082;&#1089;&#1085;&#1086;&#1075;&#1086; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1088;&#1080; &#1085;&#1072;&#1080;&#1073;&#1086;&#1083;&#1077;&#1077; &#1095;&#1072;&#1089;&#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1086;&#1081; &#1074;&#1086;&#1083;&#1085;&#1086;&#1074;&#1086;&#1081; &#1087;&#1072;&#1088;&#1077; 1310/1550 &#1085;&#1084;, &#1080;&#1079; O- &#1080; C-&#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1072; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;.
    </p>
    <ul>
      <li>
        &#1087;&#1072;&#1088;&#1072; &#171;&#1079;&#1077;&#1088;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093;&#187; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;, &#1086;&#1076;&#1080;&#1085; &#1089; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1086;&#1084; 1550 &#1085;&#1084; &#1080; &#1087;&#1088;&#1080;&#1077;&#1084;&#1085;&#1080;&#1082;&#1086;&#1084; 1310 &#1085;&#1084;, &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#8212; &#1085;&#1072;&#1086;&#1073;&#1086;&#1088;&#1086;&#1090;, &#1089; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1086;&#1084; 1310 &#1085;&#1084; &#1080; &#1087;&#1088;&#1080;&#1077;&#1084;&#1085;&#1080;&#1082;&#1086;&#1084; 1550 &#1085;&#1084;. &#1056;&#1072;&#1079;&#1085;&#1080;&#1094;&#1072; &#1074; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; &#1086;&#1073;&#1086;&#1080;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; 240 &#1085;&#1084;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1072;&#1090;&#1100; &#1086;&#1073;&#1072; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1073;&#1077;&#1079; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074; &#1076;&#1077;&#1090;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
      </li>
      <li>
        &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1099;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103;&#1093; &#1076;&#1086; 60 &#1082;&#1084;
      </li>
      <li>
        &#1042; &#1088;&#1077;&#1076;&#1082;&#1080;&#1093; &#1089;&#1083;&#1091;&#1095;&#1072;&#1103;&#1093; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1087;&#1072;&#1088;&#1099; 1490/1550, 1510/1570 &#1080; &#1087;&#1088;&#1086;&#1095;&#1080;&#1077; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1099; &#1080;&#1079; &#1086;&#1082;&#1086;&#1085; &#1087;&#1088;&#1086;&#1079;&#1088;&#1072;&#1095;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089; &#1084;&#1077;&#1085;&#1100;&#1096;&#1080;&#1084; &#1091;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077;&#1084; &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; O-&#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1072;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1086;&#1074;&#1099;&#1074;&#1072;&#1090;&#1100; &#1073;&#1086;&#1083;&#1077;&#1077; &#171;&#1076;&#1072;&#1083;&#1100;&#1085;&#1086;&#1073;&#1086;&#1081;&#1085;&#1099;&#1077;&#187; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        &#1042;&#1089;&#1090;&#1088;&#1077;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1084;&#1073;&#1080;&#1085;&#1072;&#1094;&#1080;&#1103; 1310/1490, &#1082;&#1086;&#1075;&#1076;&#1072; &#1087;&#1072;&#1088;&#1072;&#1083;&#1083;&#1077;&#1083;&#1100;&#1085;&#1086; &#1089; &#1076;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1085;&#1072; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; 1550 &#1085;&#1084; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1090;&#1077;&#1083;&#1077;&#1074;&#1080;&#1076;&#1077;&#1085;&#1080;&#1103;.
      </li>
    </ul>
    <p>
      <b>&#1043;&#1088;&#1091;&#1073;&#1099;&#1077; WDM (&#1089;oarse WDM, CWDM)</b>&#160;- &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1089; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1085;&#1099;&#1084; &#1088;&#1072;&#1079;&#1085;&#1086;&#1089;&#1086;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1073;&#1086;&#1083;&#1077;&#1077; 2500&#1043;&#1043;&#1094;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1080;&#1077; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; 18 &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1077; &#1074; &#1085;&#1072;&#1089;&#1090;&#1086;&#1103;&#1097;&#1077;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; CWDM &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1074; &#1087;&#1086;&#1083;&#1086;&#1089;&#1077; &#1086;&#1090; 1271&#1085;&#1084; &#1076;&#1086; 1611&#1085;&#1084;, &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1082; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;&#1084;&#1080; 20&#1085;&#1084; (2500 &#1043;&#1043;&#1094;), &#1084;&#1086;&#1078;&#1085;&#1086; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; 16 &#1089;&#1087;&#1077;&#1082;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;
    </p>
    <ul>
      <li>
        &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1076;&#1086; 18 &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085; &#1086;&#1090; 1270 &#1076;&#1086; 1610 &#1085;&#1084; &#1089; &#1096;&#1072;&#1075;&#1086;&#1084; &#1074; 20 &#1085;&#1084;
      </li>
      <li>
        CWDM &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; &#1074; &#1087;&#1086;&#1076;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;&#1074; <b>&#1076;&#1074;&#1091;&#1093;&#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1099;&#1077;</b>. &#1057;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; BiDi, &#1076;&#1074;&#1091;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; SFP CWDM &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;, &#1087;&#1088;&#1080;&#1077;&#1084; &#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1080;&#1076;&#1077;&#1090; &#1087;&#1086; <b>&#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1091;</b>
      </li>
      <li>
        &#1055;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1080; (&#1084;&#1086;&#1076;&#1091;&#1083;&#1080;) SFP &#1080; SFP+ CWDM &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090; &#1085;&#1072; &#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1072;&#1082;&#1086;&#1081;-&#1083;&#1080;&#1073;&#1086; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099;. &#1055;&#1088;&#1080;&#1077;&#1084;&#1085;&#1080;&#1082; &#1078;&#1077; &#1091; &#1090;&#1072;&#1082;&#1080;&#1093; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1087;&#1086;&#1083;&#1086;&#1089;&#1085;&#1099;&#1081;, &#1090;. &#1077;.&#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1081; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1086;&#1076;&#1080;&#1085;&#1086;&#1095;&#1085;&#1099;&#1081; &#1076;&#1091;&#1087;&#1083;&#1077;&#1082;&#1089;&#1085;&#1099;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083; &#1089; &#1083;&#1102;&#1073;&#1099;&#1084;&#1080; &#1076;&#1074;&#1091;&#1084;&#1103; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1084;&#1080;, &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1085;&#1072; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; CWDM. &#1044;&#1083;&#1103; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1087;&#1072;&#1089;&#1089;&#1080;&#1074;&#1085;&#1099;&#1077; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1086;&#1088;&#1099;-&#1076;&#1077;&#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1086;&#1088;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1102;&#1090; &#1087;&#1086;&#1090;&#1086;&#1082;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1086;&#1090; &#171;&#1094;&#1074;&#1077;&#1090;&#1085;&#1099;&#1093;&#187; SFP-&#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; (&#1091; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1080;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082; &#1089;&#1086; &#1089;&#1074;&#1086;&#1077;&#1081; &#1076;&#1083;&#1080;&#1085;&#1086;&#1081; &#1074;&#1086;&#1083;&#1085;&#1099;) &#1074; &#1077;&#1076;&#1080;&#1085;&#1099;&#1081; &#1083;&#1091;&#1095; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1087;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1091; &#1080; &#1088;&#1072;&#1079;&#1073;&#1080;&#1088;&#1072;&#1102;&#1090; &#1077;&#1075;&#1086; &#1085;&#1072; &#1080;&#1085;&#1076;&#1080;&#1074;&#1080;&#1076;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1086;&#1090;&#1086;&#1082;&#1080; &#1074; &#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1086;&#1081; &#1090;&#1086;&#1095;&#1082;&#1077;.
      </li>
    </ul>
    <p>
      <b>&#1055;&#1083;&#1086;&#1090;&#1085;&#1099;&#1077; WDM (dense WDM, DWDM)</b>&#160;- &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1089; &#1088;&#1072;&#1079;&#1085;&#1086;&#1089;&#1086;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1086;&#1082;&#1086;&#1083;&#1086; 100 &#1043;&#1043;&#1094;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1080;&#1077; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1086; 40 &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;
    </p>
    <ul>
      <li>
        &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1086; 24, &#1072; &#1074; &#1080;&#1079;&#1075;&#1086;&#1090;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1085;&#1072; &#1079;&#1072;&#1082;&#1072;&#1079; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1093; &#8212; &#1080; &#1076;&#1086; 80 &#1076;&#1091;&#1087;&#1083;&#1077;&#1082;&#1089;&#1085;&#1099;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1089;&#1074;&#1103;&#1079;&#1080;, &#1074; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085; 1528,77-1563,86 &#1085;&#1084; &#1089; &#1096;&#1072;&#1075;&#1086;&#1084; 0,79-0,80 &#1085;&#1084;. &#1057;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1077; CWDM &#1080; DWDM
      </li>
      <li>
        &#1087;&#1088;&#1077;&#1080;&#1084;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1072; &#1087;&#1077;&#1088;&#1077;&#1076; CWDM - &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1075;&#1086; &#1095;&#1080;&#1089;&#1083;&#1072; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1085;&#1072; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1077; &#1076;&#1080;&#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080;, &#1073;&#1083;&#1072;&#1075;&#1086;&#1076;&#1072;&#1088;&#1103; &#1090;&#1086;&#1084;&#1091;, &#1095;&#1090;&#1086; DWDM &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1074; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1077; &#1085;&#1072;&#1080;&#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1081; &#1087;&#1088;&#1086;&#1079;&#1088;&#1072;&#1095;&#1085;&#1086;&#1089;&#1090;&#1080; (1525-1565 &#1085;&#1084;).
      </li>
      <li>
        &#1042; CWDM &#1080; DWDM &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1080;&#1085;&#1076;&#1080;&#1074;&#1080;&#1076;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083; &#1084;&#1086;&#1078;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1085;&#1072; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1103;&#1093;, &#1082;&#1072;&#1082; &#1074; 1 &#1043;&#1073;&#1080;&#1090;/&#1089;, &#1090;&#1072;&#1082; &#1080; 10 &#1043;&#1073;&#1080;&#1090;/&#1089;. &#1042; &#1089;&#1074;&#1086;&#1102; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100;, &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1099; 40 &#1043;&#1073;&#1080;&#1090; &#1080; 100 &#1043;&#1073;&#1080;&#1090; Ethernet &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1087;&#1091;&#1090;&#1077;&#1084; &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1085;&#1086;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; 10 &#1043;&#1073;&#1080;&#1090; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;.
      </li>
    </ul>
    <p>
      <b>&#1042;&#1099;&#1089;&#1086;&#1082;&#1086;&#1087;&#1083;&#1086;&#1090;&#1085;&#1099;&#1077; WDM&#160;&#160;(high dense WDM, &#1089;&#1086;&#1082;&#1088;. HDWDM)</b>&#160;&#8212; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1089; &#1088;&#1072;&#1079;&#1085;&#1086;&#1089;&#1086;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; 50 &#1043;&#1043;&#1094; &#1080; &#1084;&#1077;&#1085;&#1077;&#1077;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1080;&#1077; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1073;&#1086;&#1083;&#1077;&#1077; 64 &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;.
    </p>
  </body>
</html></richcontent>
