<node TEXT="OADM, WDM-фильтр" ID="ID_503077712" CREATED="1554282985684" MODIFIED="1554284033220"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1038430817">&#1042;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1086;-&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>Optical Add Drop Multiplexor (OADM) &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;</b>&#160;&#1085;&#1077; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084; &#1090;&#1088;&#1072;&#1085;&#1089;&#1080;&#1074;&#1077;&#1088;&#1086;&#1084; - &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;, &#1086;&#1076;&#1080;&#1085; &#1080;&#1079; &#1074;&#1080;&#1076;&#1086;&#1074; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1086;&#1088;&#1072; - &#1101;&#1090;&#1086; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086;, &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084;&#1086;&#1077; &#1074; &#1088;&#1072;&#1079;&#1088;&#1099;&#1074; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1080; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1077;&#1077; &#1086;&#1090;&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1080;&#1079; &#1086;&#1073;&#1097;&#1077;&#1075;&#1086; &#1083;&#1091;&#1095;&#1072; &#1076;&#1074;&#1072; &#1087;&#1086;&#1090;&#1086;&#1082;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.
    </p>
    <ul>
      <li>
        OADM (Add-Drop &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;), &#8212; OADM, &#1082;&#1072;&#1082; &#1080; &#1074;&#1089;&#1077; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1086;&#1088;&#1099;, &#1074; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; SFP &#1080; SFP+ &#1090;&#1088;&#1072;&#1085;&#1089;&#1080;&#1074;&#1077;&#1088;&#1086;&#1074; &#8212; <b>&#1087;&#1072;&#1089;&#1089;&#1080;&#1074;&#1085;&#1099;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;</b>, &#1073;&#1083;&#1072;&#1075;&#1086;&#1076;&#1072;&#1088;&#1103; &#1095;&#1077;&#1084;&#1091; &#1086;&#1085;&#1080; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1102;&#1090; &#1087;&#1086;&#1076;&#1074;&#1086;&#1076;&#1072; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103; &#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1099; &#1074; &#1083;&#1102;&#1073;&#1099;&#1093; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103;&#1093;
      </li>
      <li>
        &#1055;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086; &#1089;&#1087;&#1083;&#1072;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1084;&#1087;&#1083;&#1077;&#1082;&#1090; OADM &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1073;&#1086;&#1081;&#1090;&#1080;&#1089;&#1100; &#1073;&#1077;&#1079; &#1086;&#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1086;&#1075;&#1086; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1086;&#1088;&#1072; &#1080; <b>&#171;&#1088;&#1072;&#1079;&#1076;&#1072;&#1090;&#1100;&#187; &#1087;&#1086;&#1090;&#1086;&#1082;&#1080;</b>&#160;&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1095;&#1085;&#1099;&#1084; &#1090;&#1086;&#1095;&#1082;&#1072;&#1084;
      </li>
      <li>
        &#1053;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1082;&#1086;&#1084; OADM &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; <b>&#1089;&#1085;&#1080;&#1078;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080;</b>&#160;&#1080; &#1086;&#1090;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084;&#1086;&#1075;&#1086;, &#1080; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090;&#1085;&#1086;&#1075;&#1086; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1086;&#1074;, &#1072; &#1079;&#1085;&#1072;&#1095;&#1080;&#1090; &#1080; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1076;&#1072;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; &#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080;. &#1055;&#1086; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1084; &#1076;&#1072;&#1085;&#1085;&#1099;&#1084;, &#1089;&#1085;&#1080;&#1078;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1086;&#1090; 1,5 &#1076;&#1086; 2 &#1076;&#1041; &#1085;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; Add-Drop
      </li>
    </ul>
    <p>
      <b>WDM-&#1092;&#1080;&#1083;&#1100;&#1090;&#1088; - </b>&#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1090;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1080;&#1079; &#1086;&#1073;&#1097;&#1077;&#1075;&#1086; &#1087;&#1086;&#1090;&#1086;&#1082;&#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1080;&#1085; &#1082;&#1072;&#1085;&#1072;&#1083; &#1089; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1081; &#1076;&#1083;&#1080;&#1085;&#1086;&#1081; &#1074;&#1086;&#1083;&#1085;&#1099;. &#1058;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1090;&#1100; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080; OADM &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1083;&#1100;&#1085;&#1099;&#1093; &#1087;&#1072;&#1088;, &#1095;&#1090;&#1086; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1075;&#1080;&#1073;&#1082;&#1086;&#1089;&#1090;&#1100; &#1087;&#1086;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1080;&#1103; &#1089;&#1077;&#1090;&#1080; &#1076;&#1086; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1091;&#1084;&#1072;.
    </p>
    <ul>
      <li>
        WDM-&#1092;&#1080;&#1083;&#1100;&#1090;&#1088; &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082;&#1072;&#1082; &#1074; &#1089;&#1077;&#1090;&#1103;&#1093; &#1089; WDM &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1087;&#1083;&#1077;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084;, &#1090;&#1072;&#1082; &#1080; &#1089; CWDM, DWDM &#1091;&#1087;&#1083;&#1086;&#1090;&#1085;&#1077;&#1085;&#1080;&#1077;&#1084;.
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      &#1042; CWDM, DWDM &#1074; &#1089;&#1087;&#1077;&#1094;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1102; &#1079;&#1072;&#1083;&#1086;&#1078;&#1077;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; <b>OADM</b>&#160; &#1080; <b>&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;</b>.
    </p>
  </body>
</html></richcontent>
