  <body>
    <p>
      <b>&#1056;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; - &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1090;&#1080;&#1087;&#1099; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;</b>
    </p>
    <ul>
      <li>
        <b>Web-&#1090;&#1088;&#1072;&#1092;&#1080;&#1082;</b>. &#1050;&#1080;&#1076;&#1072;&#1077;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; --&gt; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1082;&#1080;&#1076;&#1072;&#1077;&#1090; &#1086;&#1090;&#1074;&#1077;&#1090; c&#1086; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;&#1081; &#1080; &#1089;&#1089;&#1099;&#1083;&#1082;&#1072;&#1084;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; --&gt; &#1091; &#1085;&#1072;&#1089; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1072;&#1103; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; &#1087;&#1088;&#1077;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1087;&#1072;&#1095;&#1082;&#1091; &#1089;&#1077;&#1089;&#1089;&#1080;&#1081;, &#1087;&#1086;&#1076;&#1075;&#1088;&#1091;&#1078;&#1072;&#1102;&#1090;&#1089;&#1103; &#1092;&#1072;&#1081;&#1083;&#1099; --&gt; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072;. &#1050;&#1088;&#1072;&#1090;&#1082;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1081; &#1074;&#1089;&#1087;&#1083;&#1077;&#1089;&#1082; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1089;&#1077;&#1089;&#1089;&#1080;&#1081;, &#1074;&#1099;&#1082;&#1072;&#1095;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1076;&#1072;&#1083;&#1077;&#1077; &#1090;&#1080;&#1096;&#1080;&#1085;&#1072;.
      </li>
      <li>
        <b>&#1043;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1080; &#1074;&#1080;&#1076;&#1077;&#1086;-&#1090;&#1088;&#1072;&#1092;&#1080;&#1082;</b>. &#1050;&#1086;&#1076;&#1077;&#1082; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1077;&#1090; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1087;&#1086;&#1090;&#1086;&#1082; &#1074; &#1093;&#1072;&#1088;&#1072;&#1082;&#1090;&#1077;&#1088;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080;, &#1074;&#1099;&#1076;&#1072;&#1095;&#1072; &#1089;&#1090;&#1072;&#1073;&#1080;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; N KB/s
      </li>
      <li>
        <b>&#1058;&#1088;&#1072;&#1092;&#1080;&#1082; &#1087;&#1077;&#1095;&#1072;&#1090;&#1080; &#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;</b>. &#1054;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1072; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072; &#1085;&#1072; &#1087;&#1077;&#1095;&#1072;&#1090;&#1100; --&gt; &#1085;&#1072; &#1083;&#1086;&#1075;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088; &#1091;&#1093;&#1086;&#1076;&#1080;&#1090; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090; --&gt; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;&#1072; (PCL6, PostScript) --&gt; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1087;&#1086;&#1090;&#1086;&#1082; &#1080;&#1076;&#1077;&#1090; &#1085;&#1072; &#1087;&#1088;&#1080;&#1085;&#1090;&#1077;&#1088;. &#1042;&#1099;&#1089;&#1086;&#1082;&#1086;&#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1085;&#1072;&#1103; &#1086;&#1090;&#1076;&#1072;&#1095;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; <a href="#ID_1449357610">QoS</a>, &#1090;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1072; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072; &#1085;&#1072; &#1087;&#1077;&#1095;&#1072;&#1090;&#1100; &#1084;&#1086;&#1078;&#1077;&#1090; &quot;&#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100;&quot; &#1082;&#1072;&#1085;&#1072;&#1083;.
      </li>
      <li>
        &#1055;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;
      </li>
      <li>
        &#1055;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; (collaboration &#1080; &#1080;&#1075;&#1088;&#1099;). &#1054;&#1095;&#1077;&#1085;&#1100; &#1084;&#1085;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1089;&#1074;&#1103;&#1079;&#1072;&#1085;&#1086; &#1089; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1077;&#1081; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1075;&#1086;. &#1054;&#1095;&#1077;&#1085;&#1100; &#1073;&#1086;&#1083;&#1100;&#1096;&#1072;&#1103; &#1095;&#1091;&#1074;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1082; &#1083;&#1072;&#1075;&#1072;&#1084; &#1080; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072;&#1084;
      </li>
    </ul>
    <p>
      <b>&#1058;&#1088;&#1072;&#1092;&#1080;&#1082; &#1087;&#1086; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1102; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1089; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084;</b>
    </p>
    <ul>
      <li>
        <b>&#1056;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; (P2P)</b>. &#1055;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1075;&#1086;&#1083;&#1086;&#1089;&#1072; &#1080;&#1083;&#1080; &#1074;&#1080;&#1076;&#1077;&#1086;. &#1058;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;.
      </li>
      <li>
        <b>&#1048;&#1085;&#1090;&#1077;&#1088;&#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; (P2M)</b>. &#1055;&#1086;&#1080;&#1089;&#1082;&#1086;&#1074;&#1080;&#1082;. &#1046;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; (&#1073;&#1091;&#1092;&#1077;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103;, &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; <a href="#ID_1449357610">QoS</a>, &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;, &#1082;&#1083;&#1072;&#1089;&#1089;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;, &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080;)
      </li>
      <li>
        <b>&#1041;&#1077;&#1079; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103; &#1089; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; (M2M)</b>. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081; &#1080; &#1080;&#1093; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072;. Backup. &#1050;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072; &#1085;&#1077; &#1074;&#1072;&#1078;&#1085;&#1086;
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
