<node TEXT="Технологии" FOLDED="true" ID="ID_1744801760" CREATED="1519112080070" MODIFIED="1519112080070">
<node TEXT="BYOD" ID="ID_117298094" CREATED="1519112080070" MODIFIED="1519112080070"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      BYOD (Bring Your Own Device) - &#1101;&#1090;&#1086; &#1084;&#1086;&#1076;&#1085;&#1072;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077; &#1082;&#1088;&#1080;&#1079;&#1080;&#1089;&#1072; &#1074; 2008 &#1075;&#1086;&#1076;&#1091; &#1090;&#1077;&#1084;&#1072; &#1101;&#1082;&#1086;&#1085;&#1086;&#1084;&#1080;&#1080; &#1085;&#1072; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1093; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1103;&#1093; &#1076;&#1083;&#1103; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1086;&#1074;. &#1051;&#1086;&#1075;&#1080;&#1082;&#1072; &#1087;&#1088;&#1086;&#1089;&#1090;&#1072; - &#1077;&#1089;&#1083;&#1080; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1083;&#1102;&#1076;&#1103;&#1084; &#1085;&#1077; &#1087;&#1086;&#1082;&#1091;&#1087;&#1072;&#1090;&#1100; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;, &#1072; &#1087;&#1088;&#1077;&#1076;&#1083;&#1072;&#1075;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080;&#1085;&#1086;&#1089;&#1080;&#1090;&#1100; &#1089;&#1074;&#1086;&#1105; - &#1085;&#1086;&#1091;&#1090;&#1073;&#1091;&#1082;&#1080;, &#1089;&#1084;&#1072;&#1088;&#1090;&#1092;&#1086;&#1085;&#1099; - &#1090;&#1086; &#1101;&#1090;&#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1080;&#1083;&#1100;&#1085;&#1086; &#1076;&#1077;&#1096;&#1077;&#1074;&#1083;&#1077; &#1095;&#1090;&#1086; &#1074; &#1088;&#1072;&#1079;&#1086;&#1074;&#1086;&#1081; &#1087;&#1086;&#1082;&#1091;&#1087;&#1082;&#1077;, &#1095;&#1090;&#1086; &#1074; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1087;&#1072;&#1088;&#1082;&#1072; &#1090;&#1077;&#1093;&#1085;&#1080;&#1082;&#1080;, &#1095;&#1090;&#1086; &#1074; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1080;.
    </p>
    <ul>
      <li>
        &#1087;&#1086; &#1092;&#1072;&#1082;&#1090;&#1091; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1072;&#1103; &#1101;&#1082;&#1086;&#1085;&#1086;&#1084;&#1080;&#1103; &#1074; BYOD &#1086;&#1095;&#1077;&#1085;&#1100; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086; &#1091;&#1073;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1077;&#1079;&#1082;&#1080;&#1084; <b>&#1088;&#1086;&#1089;&#1090;&#1086;&#1084; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1086;&#1074; &#1085;&#1072; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1091; &#1080; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080;</b>. &#1054;&#1076;&#1085;&#1086; &#1076;&#1077;&#1083;&#1086;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1083;&#1102;&#1076;&#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1085;&#1072; &#1092;&#1080;&#1088;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1081; &#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1080;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1078;&#1105;&#1089;&#1090;&#1082;&#1080;&#1077; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1083;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; &#1087;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1077; &#1055;&#1054; &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;&#1084;, &#1076;&#1088;&#1091;&#1075;&#1086;&#1077; - &#1082;&#1086;&#1075;&#1076;&#1072; &#1101;&#1090;&#1086; &#1083;&#1080;&#1095;&#1085;&#1099;&#1081; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1072;, &#1075;&#1076;&#1077; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1074;&#1099;&#10