      </li>
      <li>
        <b>&#1074;&#1099;&#1075;&#1086;&#1076;&#1085;&#1077;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1093; &#1084;&#1077;&#1089;&#1090; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1082;&#1086;&#1074; &#1090;&#1086;&#1085;&#1082;&#1080;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1099;</b>&#160; - &#1101;&#1090;&#1086; &#1089;&#1085;&#1080;&#1078;&#1072;&#1077;&#1090; &#1079;&#1072;&#1090;&#1088;&#1072;&#1090;&#1099; &#1085;&#1072; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1091; &#1080; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1090;&#1077;&#1093;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1082;&#1072; &#1087;&#1088;&#1080; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1080; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084;&#1086;&#1089;&#1090;&#1080;
