<node TEXT="DOCSYS" ID="ID_90363586" CREATED="1519112080070" MODIFIED="1543398509711"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Data Over Cable Service Interface Specifications (DOCSIS) </b>&#8212; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086; &#1082;&#1086;&#1072;&#1082;&#1089;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084;&#1091; (&#1090;&#1077;&#1083;&#1077;&#1074;&#1080;&#1079;&#1080;&#1086;&#1085;&#1085;&#1086;&#1084;&#1091;) &#1082;&#1072;&#1073;&#1077;&#1083;&#1102;. &#1042; 1998 &#1075;. &#1073;&#1099;&#1083; &#1086;&#1076;&#1086;&#1073;&#1088;&#1077;&#1085; &#1086;&#1089;&#1085;&#1086;&#1074;&#1086;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1102;&#1097;&#1080;&#1081; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090; J.112, &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081; &#1084;&#1077;&#1090;&#1086;&#1076;&#1099; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086; &#1089;&#1077;&#1090;&#1103;&#1084; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1090;&#1077;&#1083;&#1077;&#1074;&#1080;&#1076;&#1077;&#1085;&#1080;&#1103;. &#1041;&#1072;&#1079;&#1080;&#1088;&#1091;&#1103;&#1089;&#1100; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1086;&#1074; ITU J.112 &#1080; J.83, &#1082;&#1086;&#1085;&#1089;&#1086;&#1088;&#1094;&#1080;&#1091;&#1084;&#1086;&#1084; &#171;CableLabs&#187; &#1074; &#1089;&#1086;&#1090;&#1088;&#1091;&#1076;&#1085;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1089; &#1096;&#1080;&#1088;&#1086;&#1082;&#1080;&#1084; &#1082;&#1088;&#1091;&#1075;&#1086;&#1084; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1077;&#1081; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1073;&#1099;&#1083; &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085; &#1077;&#1076;&#1080;&#1085;&#1099;&#1081; &#1084;&#1077;&#1078;&#1076;&#1091;&#1085;&#1072;&#1088;&#1086;&#1076;&#1085;&#1099;&#1081; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;, &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1081; &#1087;&#1086;&#1076; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &quot;Data Over Cable Service Interface Specification&quot; (DOCSIS).
    </p>
    <ul>
      <li>
        &#1069;&#1090;&#1086;&#1090; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090; &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1072;&#1090;&#1088;&#1080;&#1074;&#1072;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1091; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1090;&#1077;&#1083;&#1077;&#1074;&#1080;&#1076;&#1077;&#1085;&#1080;&#1103; &#1089; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100;&#1102; &#1076;&#1086; 42 &#1052;&#1073;&#1080;&#1090;/&#1089; (&#1087;&#1088;&#1080; &#1096;&#1080;&#1088;&#1080;&#1085;&#1077; &#1087;&#1086;&#1083;&#1086;&#1089;&#1099; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1085;&#1080;&#1103; 6 &#1052;&#1043;&#1094; &#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1084;&#1085;&#1086;&#1075;&#1086;&#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1081; &#1072;&#1084;&#1087;&#1083;&#1080;&#1090;&#1091;&#1076;&#1085;&#1086;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1094;&#1080;&#1080; 256 QAM) &#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1086;&#1090; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1089;&#1086; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100;&#1102; &#1076;&#1086; 10,24 &#1052;&#1073;&#1080;&#1090;/&#1089;
      </li>
      <li>
        &#1040;&#1050;&#1040;&#1044;&#1054;
      </li>
      <li>
        &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1090;&#1077;&#1083;&#1077;&#1074;&#1080;&#1079;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1072;&#1082;&#1089;&#1080;&#1072;&#1083;
      </li>
    </ul>
  </body>
</html></richcontent>
