        IP &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1080;&#1103;, Skipe, &#1074;&#1080;&#1076;&#1077;&#1086;&#1095;&#1072;&#1090;&#1099; (&#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &quot;&#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082;-&#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082;&quot;) &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1087;&#1077;&#1074;&#1091;&#1102; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; (&#1085;&#1072;&#1080;&#1074;&#1099;&#1089;&#1096;&#1080;&#1081; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;).
