<node TEXT="Пассивный режим" ID="ID_230178212" CREATED="1519112080127" MODIFIED="1519112080127"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1042; &#1087;&#1072;&#1089;&#1089;&#1080;&#1074;&#1085;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1087;&#1077;&#1088;&#1074;&#1099;&#1077; <b>&#1090;&#1088;&#1080; &#1096;&#1072;&#1075;&#1072; &#1090;&#1072;&#1082;&#1080;&#1077; &#1078;&#1077;, &#1082;&#1072;&#1082; &#1080; &#1074; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1084;</b>.
    </p>
