<node FOLDED="true" ID="ID_474961511" CREATED="1547133255584" MODIFIED="1570524546996"><richcontent TYPE="NODE">

<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1077;&#1090;&#1086;&#1076; POST</b>
    </p>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1077;&#1090;&#1086;&#1076; POST</b>&#160;- &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1074; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1077; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;. &#1069;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1095;&#1077;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086; &#1084;&#1077;&#1090;&#1086;&#1076;&#1091; get, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1091; &#1085;&#1077;&#1075;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1086; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074; 4 &#1050;&#1073;. &#1041;&#1086;&#1083;&#1100;&#1096;&#1080;&#1077; &#1086;&#1073;&#1098;&#1077;&#1084;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1074; &#1092;&#1086;&#1088;&#1091;&#1084;&#1072;&#1093;, &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1093; &#1089;&#1083;&#1091;&#1078;&#1073;&#1072;&#1093;, &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1080; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1089;&#1099;&#1083;&#1082;&#1077; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1080; &#1076;&#1088;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; &#1089;&#1091;&#1097;&#1085;&#1086;&#1089;&#1090;&#1077;&#1081; &#1082; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1105;&#1085;&#1085;&#1086;&#1084;&#1091; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1091;. &#1063;&#1072;&#1089;&#1090;&#1086; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1080;&#1083;&#1080; &#1082;&#1072;&#1082;&#1080;&#1077;-&#1090;&#1086; &#1087;&#1086;&#1073;&#1086;&#1095;&#1085;&#1099;&#1077; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1099; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;.
    </p>
    <ul>
