<node TEXT="Cookies" ID="ID_24543696" CREATED="1531318525837" MODIFIED="1576147461864"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>cookie</b>&#160;&#8212; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084; &#1080; &#1093;&#1088;&#1072;&#1085;&#1080;&#1084;&#1099;&#1081; &#1085;&#1072; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1042;&#1077;&#1073;-&#1082;&#1083;&#1080;&#1077;&#1085;&#1090; (&#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1074;&#1077;&#1073;-&#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;) &#1074;&#1089;&#1103;&#1082;&#1080;&#1081; &#1088;&#1072;&#1079; &#1087;&#1088;&#1080; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1077; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1100; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086; &#1089;&#1072;&#1081;&#1090;&#1072; &#1087;&#1077;&#1088;&#1077;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090; &#1101;&#1090;&#1086;&#1090; &#1092;&#1088;&#1072;&#1075;&#1084;&#1077;&#1085;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1074; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1077; HTTP-&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;. &#1055;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1085;&#1072; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1085;&#1072; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1077; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103;:
    </p>
    <ul>
      <li>
        &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072;;
      </li>
      <li>
        &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1077;&#1088;&#1089;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1087;&#1088;&#1077;&#1076;&#1087;&#1086;&#1095;&#1090;&#1077;&#1085;&#1080;&#1081; &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;;
      </li>
      <li>
        &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;;
      </li>
      <li>
        &#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1103; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1080; &#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1093;.
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>1. &#1042;&#1077;&#1073;-&#1092;&#1086;&#1088;&#1084;&#1072;</b>
    </p>
    <p>
      <font color="#008000">&lt;form action=&quot;action.php&quot; method=&quot;post&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#1050;&#1072;&#1082; &#1074;&#1072;&#1089; &#1079;&#1086;&#1074;&#1091;&#1090;? </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;input name=&quot;name&quot; type=&quot;text&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&lt;input type=&quot;submit&quot;&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/form&gt;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>2. &#1055;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;</b>
    </p>
    <p>
      <font color="#008000">POST /action.php HTTP/1.1 </font>
    </p>
    <p>
      <font color="#008000">Host: mysite.ru </font>
    </p>
    <p>
      <font color="#008000">... </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">name=&#1042;&#1072;&#1089;&#1103;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>3. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; cookie</b>
    </p>
    <p>
      <font color="#008000">HTTP/1.1 200 OK </font>
    </p>
    <p>
      <font color="#008000">Server: Microsoft-IIS/8.0 </font>
    </p>
    <p>
      <font color="#008000">... </font>
    </p>
    <p>
      <font color="#008000"><b>Set-Cookie:</b>&#160;user=&#1042;&#1072;&#1089;&#1103; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;html&gt; </font>
    </p>
    <p>
      <font color="#008000">. . . </font>
    </p>
    <p>
      <font color="#008000">&lt;/html&gt;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>4. &#1055;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; cookie &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;</b>
    </p>
    <p>
      <font color="#008000">GET /page.php HTTP/1.1 </font>
    </p>
    <p>
      <font color="#008000">&#1050;&#1091;&#1082;&#1080; (cookie) </font>
    </p>
    <p>
      <font color="#008000">&#1052;&#1086;&#1076;&#1091;&#1083;&#1100; 2. &#1053;&#1058;&#1058;&#1056; Page 36GET /page.php HTTP/1.1 </font>
    </p>
    <p>
      <font color="#008000">Host: mysite.ru </font>
    </p>
    <p>
      <font color="#008000">... </font>
    </p>
    <p>
      <font color="#008000"><b>Cookie:</b>&#160;user=&#1042;&#1072;&#1089;&#1103; </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103;</b>
    </p>
    <ul>
      <li>
        &#1074;&#1088;&#1077;&#1084;&#1103; &#1078;&#1080;&#1079;&#1085;&#1080; (expires, max-age)
      </li>
      <li>
        &#1083;&#1086;&#1082;&#1072;&#1094;&#1080;&#1103; (path, domain)
      </li>
      <li>
        &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1072;&#1090;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099; (httponly,secure)
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="localStorage" ID="ID_656532130" CREATED="1547135970428" MODIFIED="1547137170069"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1077; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077;
