<node TEXT="Команды" ID="ID_886394552" CREATED="1519112080129" MODIFIED="1519112080129"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#160;&#160;&#160;APOP</b>&#160;[&#1080;&#1084;&#1103;] [digest]. &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1089;&#1083;&#1091;&#1078;&#1080;&#1090; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1080;&#1084;&#1077;&#1085;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1080; &#1079;&#1072;&#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;(digest). &#1055;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1085;&#1077; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081;
    </p>
    <p>
      <b>[&#1080;&#1084;&#1103;]</b>&#160;- &#1089;&#1090;&#1088;&#1086;&#1082;&#1072;, &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1072;&#1103; &#1080;&#1084;&#1103; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1103;&#1097;&#1080;&#1082;&#1072;.
    </p>
    <p>
      <b>[digest]</b>&#160;- &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1084;&#1077;&#1090;&#1082;&#1072;, &#1079;&#1072;&#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1087;&#1086; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084;&#1091; MD5. &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;
    </p>
    <p>
      &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; &#1101;&#1090;&#1086;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1084;&#1077;&#1090;&#1082;&#1072; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1080; &#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084;
    </p>
    <p>
      <b>&#160;&#160;&#160;DELE</b>&#160;[&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;]. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1086;&#1084;&#1077;&#1095;&#1072;&#1077;&#1090; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1103;. &#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1086;&#1084;&#1077;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1085;&#1072; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077;, &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086; &#1091;&#1076;&#1072;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1080;&#1103; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1080; (&#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1080;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1081; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; <b>QUIT</b>, &#1082;&#1088;&#1086;&#1084;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1093; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1080;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1102; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;, &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084;).
    </p>
    <p>
      &#1040;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;: [&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;] - &#1085;&#1086;&#1084;&#1077;&#1088; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;. &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103;: &#1044;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086;&#1081; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      <b>&#160;&#160;&#160;LIST</b>&#160;[&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;]. &#1057; &#1072;&#1075;&#1088;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1084; - &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1074;&#1099;&#1076;&#1072;&#1105;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086;&#1073; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1080;. &#1041;&#1077;&#1079; &#1072;&#1075;&#1088;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072; - &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1074;&#1099;&#1076;&#1072;&#1105;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086;&#1073;&#1086; &#1074;&#1089;&#1077;&#1093; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;&#1093;, &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093;&#1089;&#1103; &#1074; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1084; &#1103;&#1097;&#1080;&#1082;&#1077;.
    </p>
    <p>
      &#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1086;&#1084;&#1077;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1076;&#1083;&#1103; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1089;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103;.
    </p>
    <p>
      &#1040;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;: [&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;]-&#1085;&#1086;&#1084;&#1077;&#1088; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; (&#1085;&#1077;&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;). &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103;: &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086;&#1081; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      <b>&#160;&#160;&#160;NOOP.</b>&#160;&#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;, &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;
    </p>
    <p>
      &#160;&#160; <b>PASS</b>&#160;[&#1087;&#1072;&#1088;&#1086;&#1083;&#1100;]. &#1055;&#1077;&#1088;&#1077;&#1076;&#1072;&#1105;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1103;&#1097;&#1080;&#1082;&#1072;
    </p>
    <p>
      &#1040;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;: [&#1087;&#1072;&#1088;&#1086;&#1083;&#1100;] - &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1103;&#1097;&#1080;&#1082;&#1072;. &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103;: &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1087;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1080;&#1084;&#1077;&#1085;&#1080; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1103;&#1097;&#1080;&#1082;&#1072;.
    </p>
    <p>
      <b>&#160;&#160; RETR</b>&#160;[&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;]. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1105;&#1090; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1089; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1084; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1084;
    </p>
    <p>
      &#1040;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;: [&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;] - &#1085;&#1086;&#1084;&#1077;&#1088; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;. &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103;: &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086;&#1081; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      &#160;&#160; <b>RSET</b>. &#1069;&#1090;&#1086;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1086;&#1081; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1086;&#1090;&#1082;&#1072;&#1090; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1081; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1089;&#1077;&#1089;&#1089;&#1080;&#1080;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1077;&#1089;&#1083;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1086; &#1087;&#1086;&#1084;&#1077;&#1090;&#1080;&#1083; &#1085;&#1072; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077; &#1082;&#1072;&#1082;&#1080;&#1077;-&#1083;&#1080;&#1073;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1086;&#1085; &#1084;&#1086;&#1078;&#1077;&#1090; &#1091;&#1073;&#1088;&#1072;&#1090;&#1100; &#1101;&#1090;&#1080; &#1087;&#1086;&#1084;&#1077;&#1090;&#1082;&#1080;, &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1074; &#1101;&#1090;&#1091; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091;. &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103;: &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1080; &#1076;&#1086; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086;&#1081; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      &#160;&#160; <b>STAT</b>. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1074; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1084; &#1103;&#1097;&#1080;&#1082;&#1077; &#1087;&#1083;&#1102;&#1089; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;, &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1077;&#1084;&#1099;&#1084;&#1080; &#1101;&#1090;&#1080;&#1084;&#1080; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080; &#1085;&#1072; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1084; &#1103;&#1097;&#1080;&#1082;&#1077;
    </p>
    <p>
      &#160;&#160; <b>TOP</b>&#160;[&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;] [&#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;]. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1080; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1091;&#1089;&#1090;&#1091;&#1102; &#1089;&#1090;&#1088;&#1086;&#1082;&#1091; &#1080; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1077;&#1088;&#1074;&#1099;&#1093; &#1089;&#1090;&#1088;&#1086;&#1082; &#1090;&#1077;&#1083;&#1072; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;.
    </p>
    <p>
      &#1040;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;: [&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;] - &#1085;&#1086;&#1084;&#1077;&#1088; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;; [&#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;] - &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082; &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080;
    </p>
    <p>
      &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103;: &#1044;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1087;&#1077;&#1096;&#1085;&#1086;&#1081; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      &#160;&#160; <b>USER</b>&#160;[&#1080;&#1084;&#1103;]. &#1055;&#1077;&#1088;&#1077;&#1076;&#1072;&#1105;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1080;&#1084;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
    </p>
    <p>
      &#1040;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099;: [&#1080;&#1084;&#1103;] - &#1089;&#1090;&#1088;&#1086;&#1082;&#1072;, &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1072;&#1103; &#1080;&#1084;&#1103; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1103;&#1097;&#1080;&#1082;&#1072;.
    </p>
    <p>
      &#160;&#160; <b>QUIT</b>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="PTP" ID="ID_1114644580" CREATED="1538398669182" MODIFIED="1728138867999"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1608731112">NTP</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>PTP</b>&#xa0;(Precision Time Protocol — «протокол точного времени») — протокол, используемый для синхронизации часов по компьютерной сети. В локальных сетях он достигает точности синхронизации менее микросекунды.
    </p>
    <ul>
      <li>
        2002 IEEE 1588—2002
      </li>
      <li>
        2008 IEEE 1588—2008 (PTP Version 2) - Повышена точность и устойчивость, потеряна обратная совместимость с версией 2002 года.
      </li>
      <li>
        более точен чем NTP
      </li>
    </ul>
    <p>
      IEEE 1588-2008 вводит понятие Transparent Clock (ТС) относящееся к сетевому оборудованию, которое используется для передачи сообщений PTP. TC изменяет содержание сообщения PTP, когда они проходят через устройство. Метки времени в сообщениях корректируются на величину времени, потраченного на прохождение через сетевое оборудование. Эта схема повышает точность раздачи времени потребителям, компенсируя изменчивость времени доставки сообщений по сети.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="RDP" ID="ID_527128262" CREATED="1519112080130" MODIFIED="1779780677093"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1763206283">RDP Windows</a>&#xa0; <a href="#ID_623941253">Менеджер рабочих мест</a>&#xa0;&#xa0;<a href="#ID_778448411">Удаленный доступ</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Remote Desktop Protocol (RDP)</b>&#xa0;- протокол удалённого рабочего стола. Протокол Microsoft для подключения к удаленному серверу
    </p>
    <ul>
      <li>
        содержит в себе 2 нижних уровня (представления, сеансовый) - он сам это делает
      </li>
      <li>
        порт TCP <b>3389</b>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      ----------
    </p>
    <p>
      <span style="color: #0000c0;">apt install xrdp</span>&#xa0;&#xa0;# установка сервера удаленного рабочего стола (xRDP)
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="RTP" ID="ID_455814438" CREATED="1519112080130" MODIFIED="1728138867880"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_552841983">RTCP</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>RTP</b>&#xa0;(<b>Real-time Transport Protocol</b>) используется при передаче трафика реального времени (аудио и видео потоки) по IP сетям
    </p>
    <ul>
      <li>
        1996 год (RFC 1889 --&gt; RFC 3550 (2003 год))
      </li>
      <li>
        Протокол RTP переносит в своём заголовке данные, необходимые для восстановления аудиоданных или видеоизображения в приёмном узле, а также данные о типе кодирования информации (JPEG, MPEG и т. п.). В заголовке данного протокола, в частности, передаются временная метка и номер пакета. Эти параметры позволяют при минимальных задержках определить порядок и момент декодирования каждого пакета, а также интерполировать потерянные пакеты
      </li>
      <li>
        не имеет стандартного зарезервированного номера порта. Cоединение проходит с использованием <b>чётного UDP&#xa0;порта</b>&#xa0;(в диапазоне 16384-32767), а следующий нечётный номер используется для связи по протоколу RTCP
      </li>
      <li>
        Тот факт, что RTP использует динамически назначаемые адреса портов, создаёт ему трудности для прохождения межсетевых экранов, для обхода этой проблемы, как правило, используется STUN-сервер
      </li>
      <li>
        Установление и разрыв соединения не входит в список возможностей RTP, такие действия выполняются сигнальным протоколом (например, RTSP или SIP протоколом)
      </li>
    </ul>
    <table border="0" style="width: 80%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 0; border-right-width: 0; border-bottom-width: 0; border-left-width: 0">
      <tr>
        <td valign="top" style="width: 25%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>Payload Type</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            тип полезной нагрузки
          </p>
        </td>
        <td valign="top" style="width: 25%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>Sequence Number </b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            нумерация посылок - для соблюдения правильной последовательности
          </p>
        </td>
        <td valign="top" style="width: 25%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>Time Stamp</b>
          </p>
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            временные метки - для определения задержки переданного пакета
          </p>
        </td>
        <td valign="top" style="width: 25%; border-top-style: solid; border-right-style: solid; border-bottom-style: solid; border-left-style: solid; border-top-width: 1; border-right-width: 1; border-bottom-width: 1; border-left-width: 1">
          <p style="margin-top: 1; margin-right: 1; margin-bottom: 1; margin-left: 1">
            <b>Payload </b>
          </p>
        </td>
      </tr>
    </table>
  </body>
</html></richcontent>
</node>
<node TEXT="RTSP" ID="ID_1465540705" CREATED="1519112080130" MODIFIED="1723046009514"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Потоковый протокол реального времени (real time streaming protocol, сокр. RTSP) — прикладной протокол, предназначенный для использования в системах, работающих с мультимедийными данными (мультимедийным содержимым, медиасодержимым), и позволяющий удалённо управлять потоком данных с сервера, предоставляя возможность выполнения команд, таких как запуск (старт), приостановку (пауза) и остановку (стоп) вещания
    </p>
    <ul>
      <li>
        Порт 554
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="SCP" ID="ID_1491473344" CREATED="1519112080130" MODIFIED="1723046003747"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      SCP (secure copy) — протокол особого RCP копирования файлов, использующий в качестве транспорта не RSH, а SSH.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="SDP" ID="ID_778940595" CREATED="1538499254361" MODIFIED="1728138867725"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>SDP&#xa0;(Session Description Protocol)</b>&#xa0;— сетевой протокол прикладного уровня, предназначенный для описания сессии передачи потоковых данных, включая телефонию (ТФОП и VoIP), Интернет-радио, приложения мультимедиа.
    </p>
    <ul>
      <li>
        Сессия SDP может реализовывать несколько потоков данных. В протоколе SDP в настоящее время определены аудио, видео, данные, управление и приложения (поточные), сходные с MIME типами электронной почты в Интернет-адресах.
      </li>
      <li>
        Сообщение SDP, передаваемое от одного узла другому, может указывать:

        <ul>
          <li>
            адреса места назначения, которые могут быть для медиа-потоков мультикастинг-адресами
          </li>
          <li>
            номера UDP портов для отправителя и получателя
          </li>
          <li>
            медиа-форматы (например кодеки, описываемые профилем), которые могут применяться во время сессии
          </li>
          <li>
            время старта и остановки. Используется в случае широковещательных сессий, например, телевизионных или радиопрограмм. Можно внести время начала, завершения и времена повторов сессии
          </li>
        </ul>
      </li>
      <li>
        Поля сообщения протокола SDP нередко включаются в сообщения сигнальных протоколов телефонии, таких, например как SIP и MGCP. Таким образом SDP дополняет процесс управления вызовом, выполняя функции описания параметров медиа-сессии.
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="SFTP" ID="ID_130233551" CREATED="1536489803677" MODIFIED="1728138867672"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_579851018">FTP</a>&#xa0; <a href="#ID_1765896503">FTP-сервер</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>SFTP (</b>SSH File Transfer Protocol) - <b>не связан с FTP</b>, за исключением того, что он тоже передаёт файлы и имеет аналогичный набор команд для пользователей. SFTP, или безопасный FTP
    </p>
    <ul>
      <li>
        шифрует и команды, и данные, предохраняя пароли и конфиденциальную информацию от открытой передачи через сеть
      </li>
      <li>
        клиенты стандартного FTP не могут связаться с SFTP-сервером и наоборот.
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">get &lt;файл&gt;</span>&#xa0;&#xa0;# Скачать файл на локальный ПК с sftp-хоста
    </p>
    <p>
      <span style="color: #0000c0;">put &lt;файл&gt;</span>&#xa0;&#xa0;# Закачать файл с локального ПК на sftp-хост
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="SMB/CIFS" ID="ID_451071160" CREATED="1519112080130" MODIFIED="1790496552961"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1308310872">NFS</a>&#xa0; <a href="#ID_579851018">FTP</a>&#xa0; <a href="#ID_815209504">СХД</a>&#xa0;&#xa0;<a href="#ID_224618777">SMB-сервер</a>&#xa0;&#xa0;<a href="#ID_54245610">Samba</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">SMB (Server Message Block)</span>&#xa0;- сетевой протокол для совместного доступа к файлам, принтерам и межпроцессного взаимодействия (IPC). Лежит в основе служб Microsoft Windows Network и File and Printer Sharing. Оптимизирован для локальных сетей (LAN)
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">CIFS (Common Internet File System)</span>&#xa0;- <span style="color: #ff0000;">устаревшее</span>&#xa0;название (диалект) SMBv1, представленное Microsoft в 1996 году
      </li>
      <li>
        <span style="font-weight: bold;">Сетевые порты:</span>&#xa0;SMB работает напрямую через <span style="font-weight: bold;">TCP-порт 445</span>&#xa0;(SMB over TCP). Старые версии требовали NetBIOS (порты 137, 138, 139) и могли работать поверх NetBEUI или IPX/SPX
      </li>
      <li>
        SMB работает на файловом уровне
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Хронология развития</span>
    </p>
    <ul>
      <li>
        1983 г. - Создание протокола SMB компанией IBM (до появления BAF/BAFS)
      </li>
      <li>
        1992 г. - Samba: свободная реверс-инжиниринговая реализация SMB для UNIX/Linux
      </li>
      <li>
        1996 г. - CIFS (SMB 1.0): попытка Microsoft адаптировать протокол для интернета
      </li>
      <li>
        2006 г. - SMB 2.0 (Windows Vista): кардинальная переработка, сократившая число команд со 100+ до 19 для снижения задержек
      </li>
      <li>
        2008 г. - Microsoft открыла спецификации протокола под давлением регуляторов.
      </li>
      <li>
        2012 г. - SMB 3.0 (Windows 8 / Server 2012): появление Multichannel (многопоточность), шифрования и высокой доступности
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Плюсы и минусы</span>
    </p>
    <ul>
      <li>
        [+] Мультиплатформенность: Работает на Windows, Linux и macOS (благодаря <span style="font-weight: bold;">Samba</span>&#xa0;и встроенным клиентам)
      </li>
      <li>
        [+] Простота: Легко настраивается встроенными средствами ОС без сложного ПО
      </li>
      <li>
        [-] Безопасность: Старые версии (SMBv1/CIFS) уязвимы для критических атак (например, WannaCry). Требует обязательного отключения SMBv1 и настройки сетевых экранов
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="SMTP / ESMTP" FOLDED="true" ID="ID_1843701421" CREATED="1519112080130" MODIFIED="1740814394646"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1364483952">POP3</a>&#xa0; <a href="#ID_628659371">IMAP</a>&#xa0;&#xa0;<a href="#ID_761049270">MTA</a>&#xa0; <a href="#ID_1440596754">AA</a>&#xa0; <a href="#ID_1511068979">Почта</a>
    </p>
    <p>
      
    </p>
    <p>
      SMTP (Simple Mail Transfer Protocol - простой протокол передачи почты) - протокол, используемый для отправки электронной почты через интернет
    </p>
    <p>
      <b>ESMTP, Extended SMTP - </b>работа с аттачами и др. расширениями
    </p>
    <ul>
      <li>
        RFC5321
      </li>
      <li>
        <b>порт&#xa0;25 или 2525/TCP, 587/TCP, 465/TCP (SMTP over SSL)</b>
      </li>
      <li>
        все команды <b>4 символа</b>
      </li>
      <li>
        не предполагает верификации
      </li>
      <li>
        аттачи кодирутся в <a href="#ID_1698941296">Base64</a>&#xa0;представления
      </li>
      <li>
        ESMTP Предписывает начинать сессию не командой HELO, а командой EHLO. В случае, если сервер не поддерживает расширений, то он ответит на EHLO ошибкой, в этом случае клиент должен послать команду HELO и не использовать расширения протокола. Если же сервер поддерживает ESMTP, то кроме приветствия он сообщит список поддерживаемых расширений протокола SMTP
      </li>
      <li>
        <b>Внешние пакеты шифрования:</b>&#xa0;PGP, его свободный клон <a href="#ID_374529531">GPG</a>, S/MIME, облачные - Zix
      </li>
    </ul>
    <p>
      <b>Основные команды :</b>
    </p>
    <p>
      HELO имя_компьютера&#xa0;&#xa0;# Проверяет, поддерживает ли компьютер протокол SMTP
    </p>
    <p>
      EHLO имя_компьютера&#xa0;&#xa0;# Проверяет, поддерживает ли компьютер протокол ESMTP
    </p>
    <p>
      МАIL FROM: обратный_адрес Идентифицирует конверт отправителя
    </p>
    <p>
      RCPT TO: прямой_адрес&#xa0;&#xa0;# Идентифицирует конверт получателя
    </p>
    <p>
      VRFY адрес&#xa0;&#xa0;# Проверяет корректность адреса (возможность доставки)
    </p>
    <p>
      EXPN адрес&#xa0;&#xa0;# Демонстрирует расширение альтернативных имен и отображения файла .forward
    </p>
    <p>
      DATA&#xa0;&#xa0;# Отмечает начало тела сообщения. Тело завершается пустой строкой, содержащей одну точку
    </p>
    <p>
      QUIT&#xa0;&#xa0;# Завершает диалог с сервером и прерывает соединение
    </p>
    <p>
      RSET&#xa0;&#xa0;# Восстанавливает состояние соединения
    </p>
    <p>
      HELP&#xa0;&#xa0;# Выводит на экран описание команд SMTP
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      -----------------------
    </p>
    <p>
      USER
    </p>
    <p>
      PASS
    </p>
  </body>
</html></richcontent>
<font BOLD="false"/>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="Коды ошибок" ID="ID_19950568" CREATED="1651209075954" MODIFIED="1740814315724">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>delivery status notification - DSN</b>&#xa0;-- RFC3463 (Приложение A). Ранее ошбики трехзначным числом, позднее 3 числа через точку
    </p>
    <p>
      
    </p>
    <p>
      Первое число может принимать значения 2, 4 и 5
    </p>
    <ul>
      <li>
        2 - прошло успешно
      </li>
      <li>
        4 - произошла временная ошибка
      </li>
      <li>
        5 - постоянная ошибка
      </li>
    </ul>
    <p>
      Второе число означает тему
    </p>
    <p>
      Третье число кодирует подробности
    </p>
    <p>
      
    </p>
    <p>
      4.2.1&#xa0;&#xa0;5.2.1&#xa0;&#xa0;Почтовый ящик недоступен
    </p>
    <p>
      4.2.2&#xa0;&#xa0;5.2.2&#xa0;&#xa0;Почтовый ящик полон
    </p>
    <p>
      4.2.3&#xa0;&#xa0;5.2.3&#xa0;&#xa0;Слишком длинное сообщение
    </p>
    <p>
      4.4.1&#xa0;&#xa0;5.4.1&#xa0;&#xa0;Нет ответа от компьютера
    </p>
    <p>
      4.4.4&#xa0;&#xa0;5.4.4&#xa0;&#xa0;Невозможно выполнить маршрутизацию
    </p>
    <p>
      4.5.3&#xa0;&#xa0;5.5.3&#xa0;&#xa0;Слишком много получателей
    </p>
    <p>
      4.7.1&#xa0;&#xa0;5.7.1&#xa0;&#xa0;Доставка не авторизована, сообщение отклонено
    </p>
    <p>
      4.7.*&#xa0;&#xa0;5.7.*&#xa0;&#xa0;&#xa0;Нарушение правил организации
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="письмо через netcat" ID="ID_72151148" CREATED="1552646943643" MODIFIED="1651044687526"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1267228856">netcat</a>&nbsp;&nbsp;<a href="#ID_625898645">telnet</a>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"><b>netcat mail 25</b></font>&nbsp;&nbsp;# Установить соединение. Можно <font color="#0000c0">telnet smtp</font>
    </p>
    <ol>
      <li>
        <font color="#0000c0">EHLO с4</font>&nbsp;&nbsp;# представляемся, с4-имя компьютера
      </li>
      <li>
        <font color="#0000c0">MAIL FROM: &lt;otpravitel@kontora1.ru&gt;</font>&nbsp;&nbsp;# говорим от кого письмо
      </li>
      <li>
        <font color="#0000c0">RCPT TO: &lt;poluchantel@kontora2.ru&gt;</font>&nbsp;&nbsp;# кому письмо
      </li>
      <li>
        <font color="#0000c0">DATA</font>
      </li>
      <li>
        <font color="#0000c0">SUBJECT:&lt;заголовок письма&gt;</font>
      </li>
      <li>
        <font color="#0000c0">&lt;текст тела письма&gt; </font>
      </li>
      <li>
        <font color="#0000c0">&nbsp;<b>.&nbsp; </b></font><b>#</b>&nbsp;конец письма (Enter . Enter), на что сервером присваивается уникальный идентификатор
      </li>
      <li>
        <font color="#0000c0">&nbsp;</font><font color="#ff0000">quit&nbsp;&nbsp;# ??? выход</font>
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      <b>коды статуса (начиная с цифры) :</b>
    </p>
    <p>
      2 - хорошо
    </p>
    <p>
      3 - хорошо, обратить внимание
    </p>
    <p>
      4 - плохо
    </p>
    <p>
      5 - ошибка
    </p>
    <p>
      
    </p>
    <p>
      стандартное ограничениз заголовка до 32КБ
    </p>
  </body>
</html></richcontent>
