<node TEXT="link-local" ID="ID_770903605" CREATED="1519112080106" MODIFIED="1519112080106"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Link-Local Address</b>&#160;&#8212; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1089;&#1077;&#1090;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1099; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1083;&#1103; &#1082;&#1086;&#1084;&#1084;&#1091;&#1085;&#1080;&#1082;&#1072;&#1094;&#1080;&#1081; &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072; &#1084;&#1077;&#1089;&#1090;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080; &#1080;&#1083;&#1080; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1083;&#1080;&#1085;&#1080;&#1080;. &#1054;&#1085;&#1080; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1090; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1093;&#1086;&#1089;&#1090;&#1072;&#1084;, &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; &#1086;&#1073;&#1097;&#1080;&#1081; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;.
    </p>
    <ul>
      <li>
        &#1055;&#1086;&#1076;&#1089;&#1077;&#1090;&#1080; link-local &#1085;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103;: &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1099; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1089; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1084;&#1080; link-local &#1074; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1089;&#1077;&#1090;&#1080;
      </li>
      <li>
        &#1040;&#1076;&#1088;&#1077;&#1089;&#1072; link-local &#1095;&#1072;&#1089;&#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1075;&#1086; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;, &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1103;&#1093;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1077; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1080; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1086;&#1073; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1093; &#1089;&#1077;&#1090;&#1080; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;
      </li>
      <li>
        &#1040;&#1076;&#1088;&#1077;&#1089; &#1080;&#1079; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1072; link-local &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1054;&#1057; &#1093;&#1086;&#1089;&#1090;&#1072; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1086;&#1074; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; DHCP.
      </li>
    </ul>
    <p>
      <b>IPv4</b>
    </p>
    <p>
      &#1044;&#1083;&#1103; IPv4 &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; link-local &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1072; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1100; 169.254.0.0/16 (&#1079;&#1072; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1080; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1081; /24 &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1080;). &#1044;&#1083;&#1103; link-local &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1079;&#1072;&#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1073;&#1083;&#1086;&#1082; &#1089; 169.254.1.0 &#1087;&#1086; 169.254.254.255
    </p>
    <p>
      <b>IPv6</b>
    </p>
    <p>
      &#1044;&#1083;&#1103; IPv6 &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; link-local &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1072; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1100; <b>FE80::/10</b>.
    </p>
    <p>
      &#1040;&#1076;&#1088;&#1077;&#1089; &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1090;&#1072;&#1082; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;&#1086;&#1075;&#1086; &quot;&#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&quot; (interface identifier) IEEE EUI-64, &#1091;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1076;&#1083;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;. &#1042; &#1089;&#1077;&#1090;&#1103;&#1093; Ethernet &#1076;&#1083;&#1103; &#1077;&#1075;&#1086; &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1073;&#1080;&#1090;&#1099; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; MAC (IEEE MAC-48) &#1080; &#1082;&#1086;&#1085;&#1089;&#1090;&#1072;&#1085;&#1090;&#1072; 0xFF.
    </p>
  </body>
</html></richcontent>
</node>
