<node TEXT="Физическое" ID="ID_558611599" CREATED="1519112080138" MODIFIED="1519112080138"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1057;&#1087;&#1086;&#1089;&#1086;&#1073;&#1099; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1076;&#1080;&#1089;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1081; &#1080;&#1085;&#1092;. &#1074; &#1074;&#1080;&#1076;&#1077; &#1101;&#1083;. &#1080;&#1083;&#1080; &#1086;&#1087;&#1090;. &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1086;&#1074;, &#1087;&#1086;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1099;&#1093; &#1085;&#1072; &#1083;&#1080;&#1085;&#1080;&#1102; &#1089;&#1074;&#1103;&#1079;&#1080;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1087;&#1086;&#1089;&#1086;&#1073;&#1099; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;:</b>
    </p>
    <ul>
      <li>
        &#1055;&#1086;&#1090;&#1077;&#1085;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1086;&#1076; <b>NRZ</b>&#160;(Non Return to Zero) - &#1082;&#1086;&#1076; &#1073;&#1077;&#1079; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090;&#1072; &#1082; &#1085;&#1091;&#1083;&#1102;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1092;&#1080;&#1079;. &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1086;&#1074; 1000Base-SX, 1000Base-LX. &#1048;&#1084;&#1077;&#1077;&#1090; &#1076;&#1074;&#1072; &#1087;&#1086;&#1090;&#1077;&#1085;&#1094;&#1080;&#1072;&#1083;&#1072; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072;: &#1074;&#1099;&#1089;&#1086;&#1082;&#1080;&#1081; &#1080; &#1085;&#1080;&#1079;&#1082;&#1080;&#1081;. &#1055;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; &#1077;&#1076;&#1080;&#1085;&#1080;&#1094; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1085;&#1077; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1085;&#1091;&#1083;&#1102; &#1074; &#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1072;&#1082;&#1090;&#1072;.
      </li>
      <li>
        &#1055;&#1086;&#1090;&#1077;&#1085;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1086;&#1076; <b>NRZI</b>&#160;(Non Return to Zero with one Inverted) - &#1082;&#1086;&#1076; &#1073;&#1077;&#1079; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090;&#1072; &#1082; &#1085;&#1091;&#1083;&#1102; &#1089; &#1080;&#1085;&#1074;&#1077;&#1088;&#1089;&#1080;&#1077;&#1081; &#1087;&#1088;&#1080; &#1077;&#1076;&#1080;&#1085;&#1080;&#1094;&#1077;. &#1048;&#1089;&#1082;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1092;&#1080;&#1079;. &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1072; 100Base-FX Fast Ethernet. NRZI &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1085;&#1091;&#1083;&#1103;&#160;&#160;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090; &#1087;&#1086;&#1090;&#1077;&#1085;&#1094;&#1080;&#1072;&#1083;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1099;&#1083; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085; &#1085;&#1072; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1077;&#1084; &#1090;&#1072;&#1082;&#1090;&#1077; (&#1090;.&#1077;. &#1085;&#1077; &#1084;&#1077;&#1085;&#1103;&#1077;&#1090; &#1077;&#1075;&#1086;), &#1072; &#1087;&#1088;&#1080;&#160;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1077;&#1076;&#1080;&#1085;&#1080;&#1094;&#1099; &#1087;&#1086;&#1090;&#1077;&#1085;&#1094;&#1080;&#1072;&#1083; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1086;&#1087;&#1086;&#1083;&#1086;&#1078;&#1085;&#1099;&#1081;.
      </li>
      <li>
        <b>&#1052;&#1072;&#1085;&#1095;&#1077;&#1089;&#1090;&#1077;&#1088;&#1089;&#1082;&#1080;&#1081; &#1082;&#1086;&#1076;</b>. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1092;&#1080;&#1079;. &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1086;&#1074; Ethernet 10 &#1052;&#1073;&#1080;&#1090;/&#1089; (10Base5, 10Base2, 10Base-T, 10Base-F). &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1090;&#1072;&#1082;&#1090; &#1076;&#1077;&#1083;&#1080;&#1090;&#1089;&#1103; &#1085;&#1072; &#1076;&#1074;&#1077; &#1095;&#1072;&#1089;&#1090;&#1080;. &#1048;&#1085;&#1092;. &#1082;&#1086;&#1076;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1077;&#1087;&#1072;&#1076;&#1072;&#1084;&#1080; &#1087;&#1086;&#1090;&#1077;&#1085;&#1094;&#1080;&#1072;&#1083;&#1072;, &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1084;&#1080; &#1074; &#1089;&#1077;&#1088;&#1077;&#1076;&#1080;&#1085;&#1077; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1090;&#1072;&#1082;&#1090;&#1072;.
      </li>
      <li>
        &#1050;&#1086;&#1076; <b>MLT-3</b>&#160;(Multi Level Transmission-3). &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1092;&#1080;&#1079;. &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1072; 100Base-TX Fast Ethernet. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; 3 &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; (3 &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1103;): U, 0, +U. &#1045;&#1076;&#1080;&#1085;&#1080;&#1094;&#1077; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076; &#1089; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1085;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1081;. &#1055;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &quot;&#1085;&#1091;&#1083;&#1103;&quot; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1085;&#1077; &#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103;.&#160;
      </li>
    </ul>
  </body>
</html></richcontent>
