<node TEXT="Q-in-Q (Double VLAN)" FOLDED="true" ID="ID_1574594557" CREATED="1565843123429" MODIFIED="1565844253810"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>QinQ, Q-in-Q, Double VLAN, &#1044;&#1074;&#1086;&#1081;&#1085;&#1086;&#1077; &#1090;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; Q-in-Q</b>&#160;&#8212; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1087;&#1086; &#1091;&#1087;&#1072;&#1082;&#1086;&#1074;&#1082;&#1077; &#1074;&#1089;&#1077;&#1093; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1090;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080; &#1085;&#1077;&#1090;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1093; &#1092;&#1088;&#1077;&#1081;&#1084;&#1086;&#1074; &#1074; &#1086;&#1076;&#1080;&#1085; VLAN, &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;&#1099;&#1081; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1084; (Outer VLAN). &#1059;&#1087;&#1072;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1074;&#1085;&#1091;&#1090;&#1088;&#1100; &#1085;&#1077;&#1075;&#1086; VLAN'&#1099; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1084;&#1080; (Inner VLAN).
    </p>
    <ul>
      <li>
        &#1057;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1076;&#1074;&#1077; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; Q-in-Q: Port-based Q-in-Q &#1080; Selective Q-in-Q
      </li>
      <li>
        &#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1072;&#1103; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1081; Q-in-Q - &#1089;&#1077;&#1090;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1089;&#1082;&#1086;&#1075;&#1086; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1079;&#1088;&#1072;&#1095;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1093; &#1074; &#1089;&#1074;&#1086;&#1080;&#1093; &#1089;&#1077;&#1090;&#1103;&#1093; VLAN, &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1077;&#1090;&#1100; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;
      </li>
      <li>
        &#1074;&#1085;&#1091;&#1090;&#1088;&#1100; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1074;&#1083;&#1072;&#1085;&#1072; &#1085;&#1072; &#1074;&#1093;&#1086;&#1076;&#1077; &#1091;&#1087;&#1072;&#1082;&#1086;&#1074;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074;&#1083;&#1072;&#1085;&#1099;, &#1072; &#1085;&#1072; &#1074;&#1099;&#1093;&#1086;&#1076;&#1077; &#1090;&#1088;&#1072;&#1085;&#1089;&#1087;&#1086;&#1088;&#1090;&#1072; &#1088;&#1072;&#1089;&#1087;&#1072;&#1082;&#1086;&#1074;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103;
      </li>
      <li>
        &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; Q-in-Q, &#1090;&#1072;&#1082;&#1078;&#1077; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1072;&#1103; &#1082;&#1072;&#1082; Double VLAN, &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1091; IEEE 802.1ad, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077;&#1084; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1072; IEEE 802.1Q. &#1054;&#1085;&#1072; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1074; &#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1082;&#1072;&#1076;&#1088;&#1099; Ethernet &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#1090;&#1077;&#1075; IEEE 802.1Q
      </li>
      <li>
        &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1099; &#1084;&#1086;&#1075;&#1091;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1080;&#1093; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1077; &#1091;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1099; VLAN (<b>Service Provider VLAN ID</b>&#160;&#1080;&#1083;&#1080; <b>SP-VLANID</b>) &#1087;&#1088;&#1080; &#1086;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1080; &#1091;&#1089;&#1083;&#1091;&#1075; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084;, &#1074; &#1089;&#1077;&#1090;&#1103;&#1093; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1086; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; VLAN. &#1069;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084;&#1080; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1099; VLAN (<b>Customer VLAN ID</b>&#160;&#1080;&#1083;&#1080; <b>CVLAN ID</b>), &#1080;&#1079;&#1073;&#1077;&#1078;&#1072;&#1090;&#1100; &#1080;&#1093; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1103; &#1080; &#1080;&#1079;&#1086;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074; &#1074;&#1086; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1081; &#1089;&#1077;&#1090;&#1080; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;
      </li>
      <li>
        &#1082; &#1091;&#1078;&#1077; &#1090;&#1101;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; &#1092;&#1088;&#1077;&#1081;&#1084;&#1091; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1077;&#1097;&#1077; &#1086;&#1076;&#1080;&#1085; &#1090;&#1101;&#1075;
      </li>
    </ul>
    <p>
      <b>&#1055;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1089;&#1082;&#1080;&#1093; &#1089;&#1077;&#1090;&#1103;&#1093; &#1087;&#1086; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1072;&#1084;:</b>
    </p>
    <ul>
      <li>
        &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1073;&#1080;&#1090; &#1074; ethernet-&#1092;&#1088;&#1077;&#1081;&#1084;&#1077;, &#1074;&#1099;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084;&#1086;&#1077; &#1087;&#1086;&#1076; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080; (VID), &#1088;&#1072;&#1074;&#1085;&#1086; 12. &#1058;&#1086; &#1077;&#1089;&#1090;&#1100;, &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086; &#1095;&#1080;&#1089;&#1083;&#1086; &#1101;&#1090;&#1086; 111111111111 &#1080;&#1083;&#1080; 4095. &#1055;&#1088;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1084;&#1086;&#1076;&#1077;&#1083;&#1080; &#1086;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1103; &#1091;&#1089;&#1083;&#1091;&#1075; &quot;vlan &#1085;&#1072; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&quot; , &#1082;&#1086;&#1075;&#1076;&#1072; &#1087;&#1086;&#1088;&#1090; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; &#1080;&#1079;&#1086;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1086;&#1090; &#1076;&#1088;&#1091;&#1075;&#1086;&#1075;&#1086; &#1080; &#1086;&#1073;&#1084;&#1077;&#1085; &#1084;&#1077;&#1078;&#1076;&#1091; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1077;&#1085; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1077; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072;, &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; vlan'&#1086;&#1074; &#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1088;&#1080;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084;
      </li>
      <li>
        &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; &#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1091;&#1089;&#1083;&#1091;&#1075;&#1080; &#1087;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1090;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1093; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1093; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1074;&#1089;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1089;&#1082;&#1080;&#1077; vlan'&#1099; &#1091;&#1087;&#1072;&#1082;&#1086;&#1074;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1086;&#1076;&#1080;&#1085; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1089;&#1082;&#1080;&#1081;. &#1041;&#1077;&#1079; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; QinQ &#1101;&#1090;&#1086; &#1073;&#1099;&#1083;&#1086; &#1073;&#1099; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1099;&#1084;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1073;&#1099; &#1087;&#1088;&#1080;&#1096;&#1083;&#1086;&#1089;&#1100; &#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1086;&#1074;&#1099;&#1074;&#1072;&#1090;&#1100; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; vlan
      </li>
      <li>
        &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088; &#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091; &#1091;&#1089;&#1083;&#1091;&#1075;&#1080; &#1087;&#1086; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &quot;&#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1081; &#1084;&#1080;&#1083;&#1080;&quot;. &#1050;&#1083;&#1080;&#1077;&#1085;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1076;&#1074;&#1086;&#1081;&#1085;&#1086;&#1077; &#1090;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1089;&#1090;&#1099;&#1082;&#1077; &#1089; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1084; &#1087;&#1086; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1072;&#1084; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080; &#1094;&#1077;&#1083;&#1077;&#1089;&#1086;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1089;&#1090;&#1080;.
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="Port-based Q-in-Q" ID="ID_1477455511" CREATED="1565843715768" MODIFIED="1565844333284"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Port-based Q-in-Q </b>
    </p>
    <ol>
      <li>
        &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1088;&#1080;&#1089;&#1074;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090; &#1083;&#1102;&#1073;&#1086;&#1084;&#1091; &#1082;&#1072;&#1076;&#1088;&#1091;, &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1080;&#1074;&#1096;&#1077;&#1084;&#1091; &#1085;&#1072; &#1087;&#1086;&#1088;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;, &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; SP-VLAN, &#1088;&#1072;&#1074;&#1085;&#1099;&#1081; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1091; PVID &#1087;&#1086;&#1088;&#1090;&#1072;.
      </li>
      <li>
        &#1055;&#1086;&#1088;&#1090; &#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1091;&#1077;&#1090; &#1082;&#1072;&#1076;&#1088; &#1085;&#1077;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086; &#1086;&#1090; &#1090;&#1086;&#1075;&#1086;, &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1086;&#1085; &#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084; &#1080;&#1083;&#1080; &#1085;&#1077;&#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084;.
      </li>
      <li>
        &#1055;&#1088;&#1080; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1083;&#1077;&#1085;&#1080;&#1080; &#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1076;&#1088;&#1072; &#1074; &#1085;&#1077;&#1075;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#1090;&#1077;&#1075; &#1089; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1086;&#1084;, &#1088;&#1072;&#1074;&#1085;&#1099;&#1084; SP-VLAN.
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1085;&#1072; &#1087;&#1086;&#1088;&#1090; &#1087;&#1088;&#1080;&#1096;&#1077;&#1083; &#1085;&#1077;&#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1082;&#1072;&#1076;&#1088;, &#1074; &#1085;&#1077;&#1075;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1090;&#1077;&#1075; &#1089; SP-VLAN &#1087;&#1086;&#1088;&#1090;&#1072;.
