<node TEXT="Selective Q-in-Q" ID="ID_1943953914" CREATED="1565843623505" MODIFIED="1565843695833"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Selective Q-in-Q - </b>&#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1080;&#1079;&#1073;&#1080;&#1088;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; Outer VLAN &#1090;&#1077;&#1075;&#1072; &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1090;&#1077;&#1075;&#1072; Inner VLAN.
    </p>
    <ul>
      <li>
        &#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1072;&#1103; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; - &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1074; &#1089;&#1077;&#1090;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1093;&#1077;&#1084;&#1099; &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1091;&#1089;&#1083;&#1091;&#1075; &#171;VLAN &#1085;&#1072; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#187;
      </li>
      <li>
        &#1044;&#1086;&#1087;&#1091;&#1089;&#1090;&#1080;&#1084;, &#1087;&#1077;&#1088;&#1077;&#1076; &#1085;&#1072;&#1084;&#1080; &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1072; &#1079;&#1072;&#1076;&#1072;&#1095;&#1072; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1090;&#1077;&#1075; Outer VLAN 200 &#1082;&#1086; &#1074;&#1089;&#1077;&#1084; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;&#1084; &#1089; &#1090;&#1077;&#1075;&#1072;&#1084;&#1080; Inner VLAN 601-610,&#160;&#160;&#1082; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;&#1084; &#1089; &#1090;&#1101;&#1075;&#1072;&#1084;&#1080; Inner VLAN 611-620 &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1090;&#1101;&#1075; Outer VLAN 210, &#1072; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1089; &#1090;&#1077;&#1075;&#1086;&#1084; 1000, 1001 &#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1073;&#1077;&#1079; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1081;.
      </li>
      <li>
        &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; Selective Q-in-Q &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1073;&#1086;&#1083;&#1077;&#1077; &#1075;&#1080;&#1073;&#1082;&#1086;&#1081; &#1087;&#1086; &#1089;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1102; &#1089; Port-based Q-in-Q. &#1054;&#1085;&#1072; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090;:

        <ul>
          <li>
            &#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1072;&#1076;&#1088;&#1099; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1084;&#1080; &#1090;&#1077;&#1075;&#1072;&#1084;&#1080; &#1089; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1084;&#1080; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1072;&#1084;&#1080; SP-VLAN &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; CVLAN;
          </li>
          <li>
            &#1079;&#1072;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1099; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1082;&#1072;&#1076;&#1088;&#1086;&#1074; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; SP-VLAN &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1081; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1086;&#1074; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1093; CVLAN;
          </li>
          <li>
            &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1082; &#1085;&#1077;&#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1084; &#1082;&#1072;&#1076;&#1088;&#1072;&#1084; &#1087;&#1086;&#1084;&#1080;&#1084;&#1086; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1075;&#1086; &#1090;&#1077;&#1075;&#1072; SP-VLAN &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1090;&#1077;&#1075; CVLAN
          </li>
        </ul>
      </li>
    </ul>
  </body>
