<node TEXT="Voice VLAN" ID="ID_1989050167" CREATED="1519112080089" MODIFIED="1565843622104"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Voice VLAN</b>&#160;&#1080;&#1083;&#1080; <b>&#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; VLAN</b>&#160; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1080;&#1079;&#1086;&#1083;&#1103;&#1094;&#1080;&#1080; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1086;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
    </p>
    <ul>
      <li>
        <b>&#1041;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1100;</b>. &#1055;&#1054; (Wireshark &#1080; Voice Over Misconfigured Internet Telephones (VOMIT)) &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1079;&#1083;&#1086;&#1091;&#1084;&#1099;&#1096;&#1083;&#1077;&#1085;&#1085;&#1080;&#1082;&#1072;&#1084; &#1088;&#1072;&#1089;&#1087;&#1086;&#1079;&#1085;&#1072;&#1074;&#1072;&#1090;&#1100; &#1080; &#1074;&#1099;&#1083;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1099;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099;, &#1072; &#1079;&#1072;&#1090;&#1077;&#1084; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1080; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1099;&#1074;&#1072;&#1090;&#1100; &#1080;&#1093; &#1074; &#1072;&#1091;&#1076;&#1080;&#1086;-&#1092;&#1072;&#1081;&#1083;&#1099; &#1089; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1077;&#1084; WAV. &#1063;&#1090;&#1086;&#1073;&#1099; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1077; &#1087;&#1088;&#1086;&#1080;&#1079;&#1086;&#1096;&#1083;&#1086;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1080;&#1079;&#1086;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1086;&#1090; &#1087;&#1088;&#1086;&#1095;&#1077;&#1075;&#1086;
      </li>
      <li>
        <a href="#ID_1449357610">QoS</a>. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1086;&#1073;&#1083;&#1077;&#1075;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1079;&#1072;&#1094;&#1080;&#1080; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1089;&#1088;&#1077;&#1076;&#1080; &#1087;&#1088;&#1086;&#1095;&#1077;&#1075;&#1086;.
      </li>
    </ul>
    <p>
      &#160;&#160;&#160;1. &#1057; &#1094;&#1077;&#1083;&#1100;&#1102; &#1101;&#1082;&#1086;&#1085;&#1086;&#1084;&#1080;&#1080; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1093; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; &#1089;&#1077;&#1090;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080;, <b>&#1074; IP &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1077;</b>, &#1082;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086;, &#1080;&#1084;&#1077;&#1077;&#1090;&#1089;&#1103; <b>&#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1074;&#1091;&#1093;&#1087;&#1086;&#1088;&#1090;&#1086;&#1074;&#1099;&#1081; &#1089;&#1074;&#1080;&#1095;</b>, &#1082; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1080;&#1079; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; WS, &#1072; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1087;&#1086;&#1088;&#1090;&#1086;&#1084; IP &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1086;&#1073;&#1097;&#1077;&#1081; &#1089;&#1077;&#1090;&#1080; &#1087;&#1088;&#1077;&#1076;&#1087;&#1088;&#1080;&#1103;&#1090;&#1080;&#1103;.
    </p>
    <p>
      &#160;&#160;&#160;2. <b>&#1058;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1090;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;</b>&#160;(&#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1091; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;) &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; 802.1Q, &#1095;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1077;&#1084;&#1091; &#1086;&#1090;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1086;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.
    </p>
    <p>
      &#160;&#160;&#160;3.&#160;&#160;<b>&#1053;&#1072; &#1087;&#1086;&#1088;&#1090;&#1091; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072;&#160;&#160;&#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1086;&#1084;&#1077;&#1088;</b>&#160;&#160;Data VLAN &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1084; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1086;&#1084;, &#1079;&#1072;&#1090;&#1077;&#1084; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1086;&#1081; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1086;&#1084;&#1077;&#1088; Voice VLAN
    </p>
    <p>
      &#160;&#160;&#160;4. &#1050;&#1072;&#1076;&#1088;&#1099; &#1089; &#1076;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1086;&#1090; <b>WS</b>&#160;&#1086;&#1089;&#1090;&#1072;&#1102;&#1090;&#1089;&#1103; <b>&#1085;&#1077;&#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080;</b>, &#1090;.&#1077;. &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1102;&#1090; &#1074; Data VLAN, &#1072; &#1082;&#1072;&#1076;&#1088;&#1099;, &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1091;&#1077;&#1084;&#1099;&#1077; <b>&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1084;</b>, <b>&#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1089;&#1072;&#1084;&#1080;&#1084; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1084;</b>&#160; &#1080;&#160;&#160;&#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1102;&#1090; &#1074; Voice VLAN.
    </p>
  </body>
</html></richcontent>
</node>
