    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Автосогласование скорости и дуплекса" ID="ID_414494856" CREATED="1519112080077" MODIFIED="1519112080077"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#160;&#160;&#160;&#1052;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084; &#1072;&#1074;&#1090;&#1086;&#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;</b>&#160;- &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1073;&#1080;&#1090;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1087;&#1088;&#1080; &#1089;&#1090;&#1072;&#1088;&#1090;&#1077; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072; Ethernet &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;. &#1057;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1080; &#1076;&#1091;&#1087;&#1083;&#1077;&#1082;&#1089; &#1072;&#1074;&#1090;&#1086;&#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1086;&#1074;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;.
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; <b>&#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1086;&#1090;&#1083;&#1080;&#1095;&#1085;&#1072; &#1086;&#1090; auto</b>, &#1090;&#1086; &#1101;&#1090;&#1080;&#1084; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1072;&#1074;&#1090;&#1086;&#1089;&#1086;&#1075;&#1083;. &#1089;&#1086; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;, &#1080; &#1086;&#1085;
    </p>
    <ul>
      <li>
        &#1091;&#1087;&#1072;&#1076;&#1077;&#1090; &#1076;&#1086; &#1089;&#1072;&#1084;&#1099;&#1093; &#1087;&#1083;&#1086;&#1093;&#1080;&#1093; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1080;
      </li>
      <li>
        &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090; &#1091; &#1089;&#1077;&#1073;&#1103; half duplex
      </li>
    </ul>
