<node TEXT="10 Мбит/с Ethernet" ID="ID_602911843" CREATED="1519112080082" MODIFIED="1519112080082"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>10 &#1052;&#1073;&#1080;&#1090;/&#1089; Ethernet </b>
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>10BASE5, IEEE 802.3</b>&#160;(&#171;&#1058;&#1086;&#1083;&#1089;&#1090;&#1099;&#1081; Ethernet&#187;) &#8212; &#1087;&#1077;&#1088;&#1074;&#1086;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1072; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; &#1089;&#1086; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100;&#1102; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; 10 &#1052;&#1073;&#1080;&#1090;/&#1089;. &#1057;&#1083;&#1077;&#1076;&#1091;&#1103; &#1088;&#1072;&#1085;&#1085;&#1077;&#1084;&#1091; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1091;, IEEE &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1082;&#1086;&#1072;&#1082;&#1089;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1089; &#1074;&#1086;&#1083;&#1085;&#1086;&#1074;&#1099;&#1084; &#1089;&#1086;&#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084; 50 &#1054;&#1084; (RG-8), &#1089; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1076;&#1083;&#1080;&#1085;&#1086;&#1081; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072; 500 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>10BASE2, IEEE 802.3a</b>&#160;(&#171;&#1058;&#1086;&#1085;&#1082;&#1080;&#1081; Ethernet&#187;) &#8212; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; RG-58, &#1089; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1076;&#1083;&#1080;&#1085;&#1086;&#1081; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072; 185 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;, &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1099; &#1087;&#1088;&#1080;&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1083;&#1080;&#1089;&#1100; &#1086;&#1076;&#1080;&#1085; &#1082; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091;, &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1082; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1082;&#1072;&#1088;&#1090;&#1077; &#1085;&#1091;&#1078;&#1077;&#1085; T-&#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;, &#1072; &#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; BNC-&#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;. &#1058;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1085;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1082;&#1086;&#1085;&#1094;&#1077;. &#1052;&#1085;&#1086;&#1075;&#1080;&#1077; &#1075;&#1086;&#1076;&#1099; &#1101;&#1090;&#1086;&#1090; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090; &#1073;&#1099;&#1083; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1084; &#1076;&#1083;&#1103; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; Ethernet.
