    <p>
      &#160;&#160;&#160;&#160;<b>100BASE-FX WDM</b>&#160;&#8212; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1081; &#1086;&#1076;&#1085;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;. &#1052;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1076;&#1083;&#1080;&#1085;&#1072; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1085;&#1086;&#1081; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103; &#1074; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1086;-&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077; &#1080; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1086;&#1074;. &#1048;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099; &#1073;&#1099;&#1074;&#1072;&#1102;&#1090; &#1076;&#1074;&#1091;&#1093; &#1074;&#1080;&#1076;&#1086;&#1074;, &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1102;&#1090;&#1089;&#1103; &#1076;&#1083;&#1080;&#1085;&#1086;&#1081; &#1074;&#1086;&#1083;&#1085;&#1099; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1072; &#1080; &#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1083;&#1080;&#1073;&#1086; &#1094;&#1080;&#1092;&#1088;&#1072;&#1084;&#1080; (&#1076;&#1083;&#1080;&#1085;&#1072; &#1074;&#1086;&#1083;&#1085;&#1099;), &#1083;&#1080;&#1073;&#1086; &#1086;&#1076;&#1085;&#1086;&#1081; &#1083;&#1072;&#1090;&#1080;&#1085;&#1089;&#1082;&#1086;&#1081; &#1073;&#1091;&#1082;&#1074;&#1086;&#1081; A (1310) &#1080;&#1083;&#1080; B (1550). &#1042; &#1087;&#1072;&#1088;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1072;&#1088;&#1085;&#1099;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;: &#1089; &#1086;&#1076;&#1085;&#1086;&#1081; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082; &#1085;&#1072; 1310 &#1085;&#1084;, &#1072; &#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#8212; &#1085;&#1072; 1550 &#1085;&#1084;.
