        500 &#1074; &#1086;&#1076;&#1085;&#1091; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091;, 500 - &#1074; &#1076;&#1088;&#1091;&#1075;&#1091;&#1102;
      </li>
    </ul>
    <p>
      &#160;&#160;&#160;&#160;<b>1000BASE-T, IEEE 802.3ab</b>&#160;&#8212; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1075;&#1080;&#1075;&#1072;&#1073;&#1080;&#1090;&#1085;&#1099;&#1081; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;, &#1086;&#1087;&#1091;&#1073;&#1083;&#1080;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1074; 1999 &#1075;&#1086;&#1076;&#1091;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1074;&#1080;&#1090;&#1091;&#1102; &#1087;&#1072;&#1088;&#1091; &#1082;&#1072;&#1090;&#1077;&#1075;&#1086;&#1088;&#1080;&#1080; 5e. &#1042; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1091;&#1095;&#1072;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; 4 &#1087;&#1072;&#1088;&#1099;, &#1082;&#1072;&#1078;&#1076;&#1072;&#1103; &#1087;&#1072;&#1088;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1087;&#1086; &#1086;&#1073;&#1086;&#1080;&#1084; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;&#1084; &#1089;&#1086; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100;&#1102; &#8212; 250 &#1052;&#1073;&#1080;&#1090;/&#1089;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1084;&#1077;&#1090;&#1086;&#1076; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; PAM5 (5-level Phase Amplitude Modulation, &#1087;&#1103;&#1090;&#1080;&#1091;&#1088;&#1086;&#1074;&#1085;&#1077;&#1074;&#1072;&#1103; &#1092;&#1072;&#1079;&#1086;&#1072;&#1084;&#1087;&#1083;&#1080;&#1090;&#1091;&#1076;&#1085;&#1072;&#1103; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1094;&#1080;&#1103;) &#1089; 4 &#1083;&#1080;&#1085;&#1080;&#1103;&#1084;&#1080; (4D-PAM5) &#1080; 4-&#1084;&#1077;&#1088;&#1085;&#1086;&#1081; &#1058;&#1088;&#1077;&#1083;&#1083;&#1080;&#1089;-&#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1094;&#1080;&#1077;&#1081; (TCM), &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1075;&#1072;&#1088;&#1084;&#1086;&#1085;&#1080;&#1082;&#1080; - 62,5 &#1052;&#1043;&#1094;. &#1056;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#8212; &#1076;&#1086; 100 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>1000BASE-TX</b>&#160;&#1086;&#1087;&#1091;&#1073;&#1083;&#1080;&#1082;&#1086;&#1074;&#1072;&#1085; &#1074; &#1084;&#1072;&#1088;&#1090;&#1077; 2001 &#1075;&#1086;&#1076;&#1072;. &#1056;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1083; &#1080;&#1079;-&#1079;&#1072; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1081; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;&#1081;, &#1092;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1091;&#1089;&#1090;&#1072;&#1088;&#1077;&#1083;. &#1057;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1084;&#1099;&#1077; &#1080; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1084;&#1099;&#1077; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1099; &#1087;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084; (&#1076;&#1074;&#1077; &#1087;&#1072;&#1088;&#1099; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;, &#1082;&#1072;&#1078;&#1076;&#1072;&#1103; &#1085;&#1072; 500 &#1052;&#1073;&#1080;&#1090;/&#1089; &#1080; &#1076;&#1074;&#1077; &#1087;&#1072;&#1088;&#1099; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1102;&#1090;), &#1095;&#1090;&#1086; &#1091;&#1087;&#1088;&#1086;&#1097;&#1072;&#1083;&#1086; &#1073;&#1099; &#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1102; &#1087;&#1088;&#1080;&#1105;&#1084;&#1086;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1097;&#1080;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;. &#1045;&#1097;&#1105; &#1086;&#1076;&#1085;&#1080;&#1084; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1084; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077;&#1084; 1000BASE-TX &#1103;&#1074;&#1083;&#1103;&#1083;&#1086;&#1089;&#1100; &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1089;&#1093;&#1077;&#1084;&#1099; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1086;&#1081; &#1082;&#1086;&#1084;&#1087;&#1077;&#1085;&#1089;&#1072;&#1094;&#1080;&#1080; &#1085;&#1072;&#1074;&#1086;&#1076;&#1086;&#1082; &#1080; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090;&#1085;&#1099;&#1093; &#1087;&#1086;&#1084;&#1077;&#1093;, &#1074; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1077; &#1095;&#1077;&#1075;&#1086; &#1089;&#1083;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1101;&#1085;&#1077;&#1088;&#1075;&#1086;&#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1083;&#1077;&#1085;&#1080;&#1103; &#1080; &#1094;&#1077;&#1085;&#1072; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1081; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1080;&#1078;&#1077;, &#1095;&#1077;&#1084; &#1091; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1072; 1000BASE-T. &#1044;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; 6-&#1081; &#1082;&#1072;&#1090;&#1077;&#1075;&#1086;&#1088;&#1080;&#1080;. &#1053;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1072; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1088;&#1086;&#1076;&#1091;&#1082;&#1090;&#1086;&#1074; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1084;&#1099;&#1096;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>1000BASE-X</b>&#160;&#8212; &#1086;&#1073;&#1097;&#1080;&#1081; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085; &#1076;&#1083;&#1103; &#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1086;&#1074; &#1089;&#1086; &#1089;&#1084;&#1077;&#1085;&#1085;&#1099;&#1084;&#1080; &#1087;&#1088;&#1080;&#1105;&#1084;&#1086;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1072;&#1084;&#1080; &#1074; &#1092;&#1086;&#1088;&#1084;-&#1092;&#1072;&#1082;&#1090;&#1086;&#1088;&#1072;&#1093; GBIC &#1080;&#1083;&#1080; SFP.
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>1000BASE-SX, IEEE 802.3z</b>&#160;&#8212; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1081; &#1084;&#1085;&#1086;&#1075;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1077; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; (62,5/50 &#1084;&#1080;&#1082;&#1088;&#1086;&#1085;) &#1074; &#1087;&#1077;&#1088;&#1074;&#1086;&#1084; &#1086;&#1082;&#1085;&#1077; &#1087;&#1088;&#1086;&#1079;&#1088;&#1072;&#1095;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089; &#1076;&#1083;&#1080;&#1085;&#1086;&#1081; &#1074;&#1086;&#1083;&#1085;&#1099;, &#1088;&#1072;&#1074;&#1085;&#1086;&#1081; 850 &#1085;&#1084;. &#1044;&#1072;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1088;&#1086;&#1093;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1076;&#1086; 550 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>1000BASE-LX, IEEE 802.3z</b>&#160;&#8212; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1081; &#1086;&#1076;&#1085;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1077; &#1080;&#1083;&#1080; &#1084;&#1085;&#1086;&#1075;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1077; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; (9 &#1084;&#1080;&#1082;&#1088;&#1086;&#1085;) &#1074;&#1086; &#1074;&#1090;&#1086;&#1088;&#1086;&#1084; &#1086;&#1082;&#1085;&#1077; &#1087;&#1088;&#1086;&#1079;&#1088;&#1072;&#1095;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089; &#1076;&#1083;&#1080;&#1085;&#1086;&#1081; &#1074;&#1086;&#1083;&#1085;&#1099;, &#1088;&#1072;&#1074;&#1085;&#1086;&#1081; 1310 &#1085;&#1084;. &#1044;&#1072;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1088;&#1086;&#1093;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1090; &#1090;&#1080;&#1087;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1093; &#1087;&#1088;&#1080;&#1105;&#1084;&#1086;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1086;&#1074; &#1080;, &#1082;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086;, &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1076;&#1083;&#1103; &#1086;&#1076;&#1085;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1075;&#1086; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1076;&#1086; 5 &#1082;&#1084; &#1080; &#1076;&#1083;&#1103; &#1084;&#1085;&#1086;&#1075;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1075;&#1086; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#