    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>1000BASE-CX</b>&#160;&#8212; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090; &#1076;&#1083;&#1103; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1080;&#1093; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1081; (&#1076;&#1086; 25 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;), &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1081; 2-&#1087;&#1072;&#1088;&#1085;&#1099;&#1081; &#1101;&#1082;&#1088;&#1072;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; (150 &#1054;&#1084;, STP IBM Type I &#1080;&#1083;&#1080; &#1083;&#1091;&#1095;&#1096;&#1077;). &#1055;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1076;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; 8B/10B, &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1105;&#1090;&#1089;&#1103; &#1087;&#1086; &#1086;&#1076;&#1085;&#1086;&#1081; &#1087;&#1072;&#1088;&#1077;, &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1087;&#1072;&#1088;&#1077; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1086;&#1074;; &#1088;&#1072;&#1079;&#1098;&#1105;&#1084;&#1099; - 9-&#1082;&#1086;&#1085;&#1090;&#1072;&#1082;&#1090;&#1085;&#1099;&#1081; D, HSSDC. &#1047;&#1072;&#1084;&#1077;&#1085;&#1105;&#1085; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1086;&#1084; 1000BASE-T &#1080; &#1089;&#1077;&#1081;&#1095;&#1072;&#1089; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>1000BASE-LH (Long Haul)</b>&#160;&#8212; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1081; &#1086;&#1076;&#1085;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;. &#1044;&#1072;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1088;&#1086;&#1093;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1073;&#1077;&#1079; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1080;&#1090;&#1077;&#1083;&#1103; &#8212; &#1076;&#1086; 100 &#1082;&#1080;&#1083;&#1086;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;.
