    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>10GBASE-SR</b>&#160;&#8212; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; 10-&#1075;&#1080;&#1075;&#1072;&#1073;&#1080;&#1090;&#1085;&#1086;&#1075;&#1086; Ethernet &#1076;&#1083;&#1103; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1080;&#1093; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1081; (&#1076;&#1086; 26 &#1080;&#1083;&#1080; 82 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;, &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1090;&#1080;&#1087;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;), &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1084;&#1085;&#1086;&#1075;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;. &#1054;&#1085; &#1090;&#1072;&#1082;&#1078;&#1077; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1076;&#1086; 300 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1085;&#1086;&#1074;&#1086;&#1075;&#1086; &#1084;&#1085;&#1086;&#1075;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1075;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; (2000 &#1052;&#1043;&#1094;/&#1082;&#1084;).
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>10GBASE-LX4</b>&#160;&#8212; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1091;&#1087;&#1083;&#1086;&#1090;&#1085;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1081; &#1086;&#1090; 240 &#1076;&#1086; 300 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1087;&#1086; &#1084;&#1085;&#1086;&#1075;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1084;&#1091; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1091;. &#1058;&#1072;&#1082;&#1078;&#1077; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1076;&#1086; 10 &#1082;&#1080;&#1083;&#1086;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1087;&#1088;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1086;&#1076;&#1085;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1075;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>10GBASE-LR</b>&#160;&#1080; <b>10GBASE-ER</b>&#160;&#8212; &#1101;&#1090;&#1080; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1099; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1090; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1076;&#1086; 10 &#1080; 40 &#1082;&#1080;&#1083;&#1086;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;, &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>10GBASE-SW</b>, <b>10GBASE-LW</b>&#160;&#1080; <b>10GBASE-EW</b>&#160; &#8212; &#1101;&#1090;&#1080; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1099; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;, &#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1080;&#1084;&#1099;&#1081; &#1087;&#1086; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1080; &#1080; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1084; OC-192 / STM-64 SONET/SDH. &#1054;&#1085;&#1080; &#1087;&#1086;&#1076;&#1086;&#1073;&#1085;&#1099; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1072;&#1084; 10GBASE-SR, 10GBASE-LR &#1080; 10GBASE-ER &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090; &#1090;&#1077; &#1078;&#1077; &#1089;&#1072;&#1084;&#1099;&#1077; &#1090;&#1080;&#1087;&#1099; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;&#1081; &#1080; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>10GBASE-T, IEEE 802.3an-2006</b>&#160;&#8212; &#1087;&#1088;&#1080;&#1085;&#1103;&#1090; &#1074; &#1080;&#1102;&#1085;&#1077; 2006 &#1075;&#1086;&#1076;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; 4 &#1083;&#1077;&#1090; &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1074;&#1080;&#1090;&#1091;&#1102; &#1087;&#1072;&#1088;&#1091; &#1082;&#1072;&#1090;&#1077;&#1075;&#1086;&#1088;&#1080;&#1080; 6 (&#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; 55 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;) &#1080; 6&#1072; (&#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; 100 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;).
    </p>
    <p>
      &#160;&#160;&#160;&#160;<b>10GBASE-KR</b>&#160;&#8212; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; 10-&#1075;&#1080;&#1075;&#1072;&#1073;&#1080;&#1090;&#1085;&#1086;&#1075;&#1086; Ethernet &#1076;&#1083;&#1103; &#1082;&#1088;&#1086;&#1089;&#1089;-&#1087;&#1083;&#1072;&#1090; (backplane/midplane) &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;/&#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074; (Modular/Blade).
    </p>
  </body>
