<node TEXT="FHRP резервирование" FOLDED="true" ID="ID_1283278995" CREATED="1519112080100" MODIFIED="1556476452188"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>FHRP&#160;(First Hop Redundancy Protocol)</b>&#160;- &#1057;&#1077;&#1084;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1087;&#1077;&#1088;&#1074;&#1086;&#1075;&#1086; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1072;
    </p>
    <ul>
      <li>
        <b>HSRP (Hot Standby Roter Protocol)</b>&#160;- &#1087;&#1088;&#1086;&#1087;&#1088;&#1080;&#1077;&#1090;&#1072;&#1088;&#1085;&#1099;&#1081;, Cisco
      </li>
      <li>
        <b>VRRP (Virtual Router Redundency Protocol)</b>&#160;- &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081;, &#1086;&#1090;&#1103;&#1075;&#1086;&#1097;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1072;&#1090;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080;, &#1089;&#1076;&#1077;&#1083;&#1072;&#1085; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; HSRP
      </li>
      <li>
        <b>GLBP (Gateway Load Balancing Protocol)</b>&#160;- &#1087;&#1088;&#1086;&#1087;&#1088;&#1080;&#1077;&#1090;&#1072;&#1088;&#1085;&#1099;&#1081;, Cisco. &#1054;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1085;&#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; (&#1096;&#1083;&#1102;&#1079;&#1086;&#1074;) &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; &#1086;&#1076;&#1080;&#1085; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; IP-&#1072;&#1076;&#1088;&#1077;&#1089;
      </li>
      <li>
        SMLT- &#1087;&#1088;&#1086;&#1087;&#1088;&#1080;&#1077;&#1090;&#1072;&#1088;&#1085;&#1099;&#1081;, Cisco
      </li>
      <li>
        <b>CARP&#160;(Common Address Redundency Protocol)</b>&#160;- &#1089;&#1074;&#1086;&#1073;&#1086;&#1076;&#1085;&#1099;&#1081;, &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085; &#1082;&#1072;&#1082; &#1095;&#1072;&#1089;&#1090;&#1100; OpenBSD, &#1087;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1074; FreeBSD
      </li>
    </ul>
    <p>
      <b>&#1056;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1077; &#1080;&#1079; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1099; &#1074; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1084;&#1091;&#1102; (&#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1099;) </b>
    </p>
    <ul>
      <li>
        &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; &quot;&#1087;&#1088;&#1080;&#1082;&#1080;&#1076;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103;&quot; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084; &#1089; &#1086;&#1076;&#1085;&#1080;&#1084; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1084;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086; &#1096;&#1083;&#1102;&#1079;&#1072; &#1076;&#1083;&#1103; &#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1099;&#1093; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074;
      </li>
      <li>
        &#1086;&#1076;&#1080;&#1085; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1086; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; (Forwarding Router), &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; - &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1081; (Standby Router)
      </li>
      <li>
        &#1055;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1099; &#1082;&#1083;&#1072;&#1089;&#1089;&#1072; FHRP &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; &#1085;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;&#1093;, &#1090;&#1072;&#1082; &#1080; &#1085;&#1072; L3 &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072;&#1093;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      &#1089;&#1084;. <a href="#ID_1703168196">FHRP &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; (Cisco)</a>
    </p>
  </body>
</html></richcontent>
<node TEXT="HSRP" FOLDED="true" ID="ID_1874048794" CREATED="1519112080100" MODIFIED="1556476449598"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>HSRP (Hot Standby Router Protocol)</b>&#160;&#160;&#8212; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1089;&#1077;&#1084;&#1077;&#1081;&#1089;&#1090;&#1074;&#1072; FHRP, &#1087;&#1088;&#1086;&#1087;. Cisco
    </p>
    <ul>
      <li>
        &#1080;&#1084;&#1077;&#1077;&#1090; &#1085;&#1072;&#1075;&#1086;&#1090;&#1086;&#1074;&#1077; <b>standby &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;</b>
      </li>
      <li>
        <b>&#1090;&#1072;&#1081;&#1084;&#1077;&#1088;&#1099;</b>&#160;&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; - hello (3 &#1089;&#1077;&#1082;.), hold (10 &#1089;&#1077;&#1082;.)
      </li>
      <li>
        &#1074;&#1080;&#1088;&#1090;. &#1072;&#1076;&#1088;&#1077;&#1089; <b>&#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103;</b>&#160;&#1086;&#1090; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077;
      </li>
      <li>
        &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; <b>&#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1082;&#1072;&#1089;&#1090; &#1072;&#1076;&#1088;&#1077;&#1089;</b>&#160;224.0.0.2 (&#1074;&#1077;&#1088;&#1089;.1) &#1080; 224.0.0.102 (&#1074; &#1074;&#1077;&#1088;&#1089;.2)
      </li>
      <li>
        &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; <b>&#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1102;</b>
      </li>
      <li>
        &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099; &#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1099;
      </li>
      <li>
        &#1085;&#1077; &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1072;&#1090;&#1088;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1086;&#1090;&#1076;&#1085;&#1086;&#1075;&#1086; &#1080; &#1090;&#1086;&#1075;&#1086; &#1078;&#1077; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;
      </li>
    </ul>
    <p>
      &#160;&#160;&#160; <b>&#1040;&#1082;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (Active Router)</b>&#160; &#8212; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1080;&#1083;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1081; &#1089;&#1074;&#1080;&#1095; L3, &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1102;&#1097;&#1080;&#1081; &#1088;&#1086;&#1083;&#1100; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072; &#1080; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081; &#1087;&#1077;&#1088;&#1077;&#1089;&#1099;&#1083;&#1082;&#1091; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1080;&#1079; &#1086;&#1076;&#1085;&#1086;&#1081; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1080; &#1074; &#1076;&#1088;&#1091;&#1075;&#1091;&#1102;;
    </p>
    <p>
      &#160;&#160;&#160; <b>&#1056;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (Standby Router)</b>&#160; &#8212; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1080;&#1083;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1081; &#1089;&#1074;&#1080;&#1095; L3, &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1102;&#1097;&#1080;&#1081; &#1088;&#1086;&#1083;&#1100; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1075;&#1086; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;, &#1086;&#1078;&#1080;&#1076;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1086;&#1090;&#1082;&#1072;&#1079;&#1072; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072; &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1086;&#1076;&#1085;&#1086;&#1081; HSRP &#1075;&#1088;&#1091;&#1087;&#1087;&#1099;;
    </p>
    <p>
      &#160;&#160;&#160; <b>&#1043;&#1088;&#1091;&#1087;&#1087;&#1072; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; (Standby Group)</b>&#160; &#8212; &#1075;&#1088;&#1091;&#1087;&#1087;&#1072; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; &#1080;&#1083;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1093; &#1089;&#1074;&#1080;&#1095;&#1077;&#1081; L3, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1095;&#1083;&#1077;&#1085;&#1072;&#1084;&#1080; &#1086;&#1076;&#1085;&#1086;&#1081; HSRP-&#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1080; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1102;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091; &#1080; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1100; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;;
    </p>
    <p>
      &#160;&#160;&#160; <b>&#1058;&#1072;&#1081;&#1084;&#1077;&#1088; &#1087;&#1088;&#1080;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1103; (Hello Time)</b>&#160; &#8212; &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1082; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;, &#1074; &#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1099; &#1080;&#1083;&#1080; L3 &#1089;&#1074;&#1080;&#1095;&#1080;, &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077;&#1089;&#1103; &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; &#1086;&#1076;&#1085;&#1086;&#1081; HSRP &#1075;&#1088;&#1091;&#1087;&#1087;&#1099;, &#1086;&#1078;&#1080;&#1076;&#1072;&#1102;&#1090; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1087;&#1088;&#1080;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1103; (Hello Packet - 3 &#1089;&#1077;&#1082;.) &#1086;&#1090; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;;
    </p>
    <p>
      &#160;&#160;&#160; <b>&#1058;&#1072;&#1081;&#1084;&#1077;&#1088; &#1091;&#1076;&#1077;&#1088;&#1078;&#1072;&#1085;&#1080;&#1103; (Hold Time)</b>&#160; &#8212; &#1087;&#1088;&#1086;&#1084;&#1077;&#1078;&#1091;&#1090;&#1086;&#1082; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;, &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090; &#1087;&#1072;&#1082;&#1077;&#1090;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090;&#1089;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1086;&#1073; &#1086;&#1090;&#1082;&#1072;&#1079;&#1077; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;, &#1090;&#1077;&#1084; &#1089;&#1072;&#1084;&#1099;&#1084; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1090; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1085;&#1086;&#1077; &#1087;&#1088;&#1077;&#1088;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; &#1074; &#1075;&#1088;&#1091;&#1087;&#1087;&#1077; &#1080; &#1073;&#1077;&#1088;&#1077;&#1090; &#1085;&#1072; &#1089;&#1077;&#1073;&#1103; &#1088;&#1086;&#1083;&#1100; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;.
    </p>
  </body>
</html></richcontent>
<node TEXT="Состояния" ID="ID_1447475570" CREATED="1519112080101" MODIFIED="1519112080101"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1055;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090; 120. Initial &gt; Learn &gt; Listen &gt; Speak &gt; Standby &gt; Active
    </p>
    <p>
      &#1055;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090; 110. Initial &gt; Learn &gt; Listen &gt; Speak &gt; Standby
    </p>
    <p>
      &#1055;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090; 100. Initial &gt; Learn &gt; Listen
    </p>
    <p>
      
    </p>
    <p>
      <b>Initial</b>&#160;- &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; HSRP
    </p>
    <p>
      <b>Learn</b>&#160;- &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1087;&#1099;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1099;&#1103;&#1089;&#1085;&#1080;&#1090;&#1100; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099;
    </p>
    <p>
      <b>Listen</b>&#160;- &#1084;&#1086;&#1083;&#1095;&#1080;&#1090;, &#1078;&#1076;&#1077;&#1090; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; hello-&#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1086;&#1090; &#1089;&#1086;&#1089;&#1077;&#1076;&#1077;&#1081;
    </p>
    <p>
      <b>Speak</b>&#160;- &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1074;&#1099;&#1073;&#1086;&#1088;&#1072; (Standby &#1080;&#1083;&#1080; Active). &#1054;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1072; &#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; Hello-&#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;
    </p>
    <p>
      <b>Standbay</b>&#160;-&#160;&#160;&#1079;&#1072;&#1087;&#1072;&#1089;&#1085;&#1086;&#1081;
    </p>
    <p>
      <b>Active</b>&#160;- &#1077;&#1089;&#1083;&#1080; &#1089;&#1072;&#1084;&#1099;&#1081; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;
    </p>
  </body>
</html></richcontent>
</node>
