<node TEXT="InARP" ID="ID_1339169807" CREATED="1519112080109" MODIFIED="1519112080109"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>InARP (Inverse Address Resolution Protocol) - &#1054;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; ARP (Inverse ARP &#8212; InARP)</b>&#160;-&#160;&#160;&#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; ARP &#1076;&#1083;&#1103; &#1089;&#1077;&#1090;&#1077;&#1081; NBMA (Non-Broadcast MultiAccess &#8212; &#1085;&#1077;&#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1074;&#1077;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1077;&#1090;&#1100; &#1089; &#1084;&#1085;&#1086;&#1075;&#1086;&#1089;&#1090;&#1072;&#1085;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1086;&#1084;)
    </p>
    <ul>
      <li>
        &#1054;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; ARP &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085; &#1074; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1077; RFC 2390
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086; &#1095;&#1090;&#1086;&#1073; &#1086;&#1090;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1083; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; InARP, &#1085;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090;. &#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; InARP &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; LMI-&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1086; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1077; PVC. &#1045;&#1089;&#1083;&#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; LMI, &#1090;&#1086; InARP &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1080;&#1082;&#1072;&#1082;&#1080;&#1093; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1080;&#1085;&#1080;&#1094;&#1080;&#1080;&#1088;&#1086;&#1074;&#1072;&#1083;&#1080; &#1073;&#1099; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1091; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; InARP. &#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; InARP &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; VC. &#1045;&#1089;&#1083;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;&#1084;&#1080; &#1085;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1086; VC, &#1090;&#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1079;&#1072;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1080; DLCI
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>R1&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;WAN&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;R2&#160; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1</b>----Status Inquiry-----------------&gt;&#160;&#160;&#160;&#160;&#160;&lt;-----------------Status Inquiry----<b>1</b>
    </p>
    <p>
      &lt;----Local DLCI 100=Active----<b>2</b>&#160;&#160;&#160;&#160;&#160; <b>2</b>----Local DLCI 200=Active----&gt;
    </p>
    <p>
      <b>3</b>----Hello, I'm 10.0.1.1-------------------------------------------------------------&gt;
    </p>
    <p>
      &lt;-------------------------------------------------------------Hello, I'm 10.0.1.2----<b>3 </b>
    </p>
    <p>
      <b>4</b>---Keepalives----------------------&gt;&#160;&#160;&#160;&#160;&#160; &lt;---------------------Keepalives----<b>4 </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. </b>&#1055;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1090;&#1100; &#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1089;&#1082;&#1086;&#1075;&#1086; FR-&#1089;&#1074;&#1080;&#1095;&#1072; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1080;&#1084;&#1077;&#1102;&#1097;&#1080;&#1093;&#1089;&#1103; <b>DLCI</b>&#160; (&#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; Status Inquery)
    </p>
  </body>
</html></richcontent>
