<node TEXT="IP-транзит" ID="ID_746884470" CREATED="1567414090164" MODIFIED="1567421229717"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_479443184">BGP</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>IP-&#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090; - </b>&#1091;&#1089;&#1083;&#1091;&#1075;&#1072; &#1087;&#1086; &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084;&#1086;&#1075;&#1086; &#1080; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1085;&#1086;&#1075;&#1086; (&#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1087;&#1086;&#1083;&#1086;&#1089;&#1085;&#1086;&#1075;&#1086;) &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1074; &#1089;&#1077;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074; &#1080; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1089;&#1077;&#1090;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; BGP. IP-&#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090; - &#1101;&#1090;&#1086; &#171;&#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1086;&#1087;&#1090;&#1086;&#1084;&#187;
    </p>
    <ul>
      <li>
        &#1058;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1090;&#1086;, &#1095;&#1090;&#1086; &#1089;&#1077;&#1090;&#1080; &#1085;&#1077; &#1089;&#1084;&#1086;&#1075;&#1083;&#1080; &#1076;&#1086;&#1089;&#1090;&#1080;&#1095;&#1100; &#1087;&#1091;&#1090;&#1077;&#1084; &#1087;&#1080;&#1088;&#1080;&#1085;&#1075;&#1072; &#8211; &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1089;&#1074;&#1103;&#1079;&#1085;&#1086;&#1089;&#1090;&#1100; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1089; &#1082;&#1072;&#1078;&#1076;&#1099;&#1084;. &#1048; &#1079;&#1072; &#1101;&#1090;&#1086; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103;, &#1082;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086;, &#1087;&#1083;&#1072;&#1090;&#1080;&#1090;&#1100;
      </li>
      <li>
        &#1074;&#1099;&#1096;&#1077;&#1089;&#1090;&#1086;&#1103;&#1097;&#1080;&#1081; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088; &#1087;&#1088;&#1086;&#1076;&#1072;&#1105;&#1090; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090; IP-&#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1076;&#1086; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1072;
      </li>
      <li>
        &#1057; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; BGP &#1087;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088; &#1086;&#1076;&#1085;&#1086;&#1081; AS &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1087;&#1080;&#1088;&#1080;&#1085;&#1075; &#1089; &#1087;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1084; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1086;&#1084; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; AS, &#1072; &#1079;&#1072;&#1090;&#1077;&#1084; &#1101;&#1090;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1099; &#1086;&#1073;&#1084;&#1077;&#1085;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1076;&#1088;&#1091;&#1075; &#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1084;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1084;&#1080;
