      </li>
      <li>
        <b>Tier-2</b>&#160;- &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1080;&#1084;&#1077;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1095;&#1072;&#1089;&#1090;&#1080; &#1089;&#1077;&#1090;&#1080; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090; &#1095;&#1077;&#1088;&#1077;&#1079; &#1087;&#1080;&#1088;&#1080;&#1085;&#1075;&#1086;&#1074;&#1099;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1085;&#1086; &#1087;&#1086;&#1082;&#1091;&#1087;&#1072;&#1077;&#1090; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090; IP-&#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1095;&#1072;&#1089;&#1090;&#1080; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&#1072;
      </li>
      <li>
        <b>Tier-3</b>&#160;- &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1089;&#1077;&#1090;&#1080; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1082;&#1072;&#1085;&#1072;&#1083;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1086;&#1082;&#1091;&#1087;&#1072;&#1077;&#1090; &#1091; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;
      </li>
    </ul>
    <p>
      <b>PIPEX</b>&#160;&#1080;&#1083;&#1080; <b>IXN</b>&#160;(Internet Exchange Network) - &#1084;&#1086;&#1076;&#1077;&#1083;&#1100; - &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1100; &#1075;&#1077;&#1086;&#1075;&#1088;&#1072;&#1092;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1077; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099; &#1074; &#1077;&#1076;&#1080;&#1085;&#1086;&#1077; &#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1089;&#1090;&#1074;&#1086;.
