<node TEXT="Терминология" ID="ID_1925198574" CREATED="1519112080120" MODIFIED="1519112080120"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#160;&#160;&#160; <b>Hello-&#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; (hello protocol)</b>&#160; &#8212; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1072;&#1085;&#1080;&#1103; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1082;&#1080;&#1093; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1081;.
    </p>
    <p>
