<node TEXT="Таймеры протокола" ID="ID_1581274061" CREATED="1519112080121" MODIFIED="1519112080121"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#160;&#160;&#160; <b>HelloInterval</b>&#160;&#8212; &#1048;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;, &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1081; hello-&#1087;&#1072;&#1082;&#1077;&#1090; &#1089; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;. &#1044;&#1083;&#1103; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1074;&#1077;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081; &#1080; &#1089;&#1077;&#1090;&#1077;&#1081; &#1090;&#1086;&#1095;&#1082;&#1072;-&#1090;&#1086;&#1095;&#1082;&#1072; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;, <b>10 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;</b>. &#1044;&#1083;&#1103; &#1085;&#1077;&#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1074;&#1077;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081; &#1089;&#1086; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1086;&#1084; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; <b>30 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;</b>.
    </p>
    <p>
      &#160;&#160;&#160; <b>RouterDeadInterval</b>&#160;&#8212; &#1048;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;, &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1089;&#1086;&#1089;&#1077;&#1076; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100;&#1089;&#1103; &#171;&#1084;&#1077;&#1088;&#1090;&#1074;&#1099;&#1084;&#187;. &#1069;&#1090;&#1086;&#1090; &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1082;&#1088;&#1072;&#1090;&#1085;&#1099;&#1084; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1102; HelloInterval. &#1050;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086;, RouterDeadInterval &#1088;&#1072;&#1074;&#1077;&#1085; 4 &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083;&#1072;&#1084; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1080; hello-&#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;, &#1090;&#1086; &#1077;&#1089;&#1090;&#1100; <b>40 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;</b>.
    </p>
    <p>
      &#160;&#160;&#160; <b>Wait Timer</b>&#160;&#8212; &#1048;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;, &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1074;&#1099;&#1073;&#1077;&#1088;&#1077;&#1090; DR &#1074; &#1089;&#1077;&#1090;&#1080;. &#1045;&#1075;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1074;&#1085;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1102; &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083;&#1072; RouterDeadInterval.
    </p>
    <p>
      &#160;&#160;&#160; <b>RxmtInterval (Retransmit interval)</b>&#160;&#8212; &#1048;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;, &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090; &#1087;&#1072;&#1082;&#1077;&#1090; &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1085;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1083; &#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1080; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, Database Description &#1087;&#1072;&#1082;&#1077;&#1090; &#1080;&#1083;&#1080; Link State Request &#1087;&#1072;&#1082;&#1077;&#1090;&#1099;). &#1047;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083;&#1072; <b>5 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;</b>.
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        &#1058;&#1072;&#1081;&#1084;&#1077;&#1088;&#1099; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; &#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1099; <b>&#1076;&#1086;&#1083;&#1078;&#1085;&#1099;&#160; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100;</b>
      </li>
    </ul>
  </body>
