  <body>
    <p>
      <b>&#1054;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072; (link-state advertisement, LSA)</b>&#160;- &#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1074;&#1089;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1099; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;, &#1074;&#1089;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099; &#1080; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;. LSA-&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1102;&#1090; DR&#160;&#160;(&#1080; BDR)-&#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1086;&#1085; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1088;&#1072;&#1089;&#1082;&#1080;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100;
    </p>
    <ul>
      <li>
        &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1086; &#1089;&#1077;&#1090;&#1080;, &#1087;&#1086;&#1084;&#1077;&#1097;&#1072;&#1077;&#1084;&#1072;&#1103; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;. &#1087;&#1072;&#1082;&#1077;&#1090;
      </li>
    </ul>
    <p>
      <b>Type 1 LSA &#8212; Router LSA</b>&#160;&#8212; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;. &#1056;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1074;&#1089;&#1077;&#1084;&#1080; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084;&#1080;. &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1074;&#1089;&#1077;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072; &#1080; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100; (cost) &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;. &#1056;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1086;&#1076;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099;.
    </p>
    <p>
      <b>Type 2 LSA &#8212; Network LSA (&#1074;&#1089;&#1087;&#1086;&#1084;&#1086;&#1075;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; Type 1)</b>&#160;- &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1089;&#1077;&#1090;&#1080;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1075;&#1076;&#1072; &#1074; &#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1095;&#1077;&#1084; 2 &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;.&#160;&#160;&#1060;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1075;&#1083;&#1072;&#1074;&#1085;&#1099;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084; (DR). &#1042; LSA &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090;&#1089;&#1103; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1074;&#1089;&#1077;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074;, &#1087;&#1088;&#1080;&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1085;&#1099;&#1093; &#1082; &#1089;&#1077;&#1090;&#1080;, &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1103; DR. &#1055;&#1086;&#1084;&#1086;&#1075;&#1072;&#1077;&#1090; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084; &#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1082;&#1072;&#1088;&#1090;&#1091; &#1089;&#1077;&#1090;&#1080; &#1056;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1086;&#1076;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099;.
    </p>
    <p>
      <b>Type 3 LSA - Network Summary LSA</b>&#160;- &#1089;&#1091;&#1084;&#1084;&#1072;&#1088;&#1085;&#1086;&#1077; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1089;&#1077;&#1090;&#1080;. &#1054;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1084;&#1080; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084;&#1080; (ABR). &#1054;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1082; &#1089;&#1077;&#1090;&#1103;&#1084; &#1074;&#1085;&#1077; &#1079;&#1086;&#1085;&#1099; &#1080; &#1085;&#1077; &#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. ABR &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1086;&#1081; &#1077;&#1084;&#1091; &#1089;&#1077;&#1090;&#1080;. &#1050;&#1086;&#1075;&#1076;&#1072; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; Network Summary LSA &#1086;&#1090; ABR, &#1086;&#1085; &#1085;&#1077; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1103; &#1082;&#1088;&#1072;&#1090;&#1095;&#1072;&#1081;&#1096;&#1077;&#1075;&#1086; &#1087;&#1091;&#1090;&#1080;. &#1056;&#1086;&#1091;&#1090;&#1077;&#1088; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1082; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1074; LSA &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072; &#1082; ABR. &#1047;&#1072;&#1090;&#1077;&#1084; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1082; &#1089;&#1077;&#1090;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; ABR &#1087;&#1086;&#1084;&#1077;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;.
    </p>
    <p>
      <b>Type 4 LSA &#8212; ASBR Summary LSA</b>&#160;&#8212; &#1089;&#1091;&#1084;&#1084;&#1072;&#1088;&#1085;&#1086;&#1077; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; ABR &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1054;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; ABR. ASBR Summary LSA &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090; Network Summary LSA &#1090;&#1077;&#1084;, &#1095;&#1090;&#1086; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1085;&#1077; &#1086; &#1089;&#1077;&#1090;&#1080;, &#1072; &#1086; ABR &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. E2
    </p>
    <p>
      <b>Type 5 LSA &#8212; AS External LSA</b>&#160;&#8212; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1054;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; ASBR &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1074;&#1089;&#1077;&#1081; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1054;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; OSPF, &#1080;&#1083;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; (default route), &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; OSPF. E2
    </p>
    <p>
      <b>Type 6 LSA &#8212; Multicast OSPF LSA</b>&#160;&#8212; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; LSA, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1082;&#1072;&#1089;&#1090; OSPF &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; (Not implemented by CISCO). &#1053;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;
    </p>
    <p>
      <b>Type 7 LSA &#8212; AS External LSA for NSSA (Not-So-Stubby Area)</b>&#160;&#8212; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1086; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1074; NSSA &#1079;&#1086;&#1085;&#1077;. &#1069;&#1090;&#1086; &#1086;&#1073;&#1098;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; NSSA &#1079;&#1086;&#1085;&#1077;. &#1053;&#1072; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077; &#1079;&#1086;&#1085;&#1099; &#1087;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1077;&#1090; type 7 LSA &#1074; type 5 LSA. N1 (&#1085;&#1077; &#1091;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090;&#1072; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080;) &#1080; N2 (&#1091;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090;&#1072; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080;)
    </p>
    <p>
      <b>Type 8 LSA &#8212; Link LSA</b>&#160;&#8212; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090; link-local &#1072;&#1076;&#1088;&#1077;&#1089; &#1080; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;(&#1099;) &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072; &#1074;&#1089;&#1077;&#1084; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;&#1084; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1103;&#1102;&#1097;&#1080;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083; (link). &#1054;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1077;&#1089;&#1083;&#1080; &#1085;&#1072; &#1082;&#1072;&#1085;&#1072;&#1083;&#1077; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1073;&#1086;&#1083;&#1077;&#1077; &#1095;&#1077;&#1084; &#1086;&#1076;&#1080;&#1085; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;. &#1056;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072; (link). &#1053;&#1077; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1084;&#1072;&#1090;&#1096;&#1088;&#1091;&#1090;&#1085;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      <b>Type 9 LSA &#8212; Intra-Area-Prefix LSA</b>&#160;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077;: &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;&#1086;&#1074; IPv6 &#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;, &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1103; &#1085;&#1072; Router LSA, &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;&#1086;&#1074; IPv6 &#1080; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090;&#1085;&#1091;&#1102; &#1089;&#1077;&#1090;&#1100;, &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1103; &#1085;&#1072; Network LSA. &#1056;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1086;&#1076;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099;.
    </p>
    <p>
      <b>Type 10 or 11 LSA</b>&#160;- Opaque LSAs/. IPv6 &#1089;&#1077;&#1090;&#1080;. &#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1089;&#1074;&#1086;&#1077;&#1081; &#1079;&#1086;&#1085;&#1099;.
    </p>
  </body>
</html></richcontent>
