    <ul>
      <li>
        &#1057;&#1085;&#1080;&#1079;&#1080;&#1090;&#1100; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091; &#1085;&#1072; CPU &#1080; RAM &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; &#1079;&#1072; &#1089;&#1095;&#1105;&#1090; &#1091;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1085;&#1080;&#1103; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1087;&#1077;&#1088;&#1077;&#1088;&#1072;&#1089;&#1095;&#1105;&#1090;&#1086;&#1074; &#1087;&#1086; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084;&#1091; OSPF
      </li>
      <li>
        &#1059;&#1084;&#1077;&#1085;&#1100;&#1096;&#1080;&#1090;&#1100; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;
      </li>
      <li>
        &#1059;&#1084;&#1077;&#1085;&#1100;&#1096;&#1080;&#1090;&#1100; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1081; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;
      </li>
    </ul>
    <p>
      &#1050;&#1072;&#1078;&#1076;&#1086;&#1081; &#1079;&#1086;&#1085;&#1077; &#1087;&#1088;&#1080;&#1089;&#1074;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; &#1079;&#1086;&#1085;&#1099; (area ID). &#1048;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085; &#1074; &#1076;&#1077;&#1089;&#1103;&#1090;&#1080;&#1095;&#1085;&#1086;&#1084; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; &#1080;&#1083;&#1080; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;. &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1099; &#1079;&#1086;&#1085; &#1085;&#1077; &#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1084;&#1080; &#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089; &#1083;&#1102;&#1073;&#1099;&#1084; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1099;&#1084; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1084;.
    </p>
    <ul>
      <li>
        <b>&#160;&#160;&#160;&#1045;&#1089;&#1083;&#1080; &#1077;&#1089;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1086;&#1085;</b>, &#1090;&#1086; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; <b>&#1079;&#1086;&#1085;&#1072; 0</b>&#160;&#1080; <b>&#1074;&#1089;&#1077; &#1079;&#1086;&#1085;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1074; &#1079;&#1086;&#1085;&#1091; 0</b>&#160;(&#1076;&#1083;&#1103; &#1079;&#1072;&#1097;&#1080;&#1090;&#1099; &#1086;&#1090; &#1087;&#1077;&#1090;&#1077;&#1083;&#1100;).
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; (backbone area)</b>. &#1052;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; (&#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1072;&#1103; &#1090;&#1072;&#1082;&#1078;&#1077; &#1082;&#1072;&#1082; &#1085;&#1091;&#1083;&#1077;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; &#1080;&#1083;&#1080; &#1079;&#1086;&#1085;&#1072; 0.0.0.0) &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1091;&#1077;&#1090; &#1103;&#1076;&#1088;&#1086; &#1089;&#1077;&#1090;&#1080; OSPF. &#1042;&#1089;&#1077; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1079;&#1086;&#1085;&#1099; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1099; &#1089; &#1085;&#1077;&#1081;, &#1080; &#1084;&#1077;&#1078;&#1079;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1095;&#1077;&#1088;&#1077;&#1079; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1086;&#1081;. &#1052;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; &#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1072; &#1079;&#1072; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1085;&#1077;&#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084;&#1080; &#1079;&#1086;&#1085;&#1072;&#1084;&#1080;. &#1052;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1089;&#1084;&#1077;&#1078;&#1085;&#1086;&#1081; &#1089; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;&#1080; &#1079;&#1086;&#1085;&#1072;&#1084;&#1080;, &#1085;&#1086; &#1086;&#1085;&#1072; &#1085;&#1077; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1089;&#1084;&#1077;&#1078;&#1085;&#1086;&#1081;; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1089; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1086;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1086; &#1080; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;.
    </p>
    <p>
      <b>&#1057;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; (standard area)</b>. &#1054;&#1073;&#1099;&#1095;&#1085;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;. &#1069;&#1090;&#1072; &#1079;&#1086;&#1085;&#1072; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;, &#1089;&#1091;&#1084;&#1084;&#1072;&#1088;&#1085;&#1099;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;.
    </p>
    <p>
      <b>&#1058;&#1091;&#1087;&#1080;&#1082;&#1086;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; (stub area)</b>. &#1058;&#1091;&#1087;&#1080;&#1082;&#1086;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; &#1085;&#1077; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1093; &#1076;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;, &#1085;&#1086; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1080;&#1079; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1079;&#1086;&#1085;. &#1045;&#1089;&#1083;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;&#1084; &#1080;&#1079; &#1090;&#1091;&#1087;&#1080;&#1082;&#1086;&#1074;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1079;&#1072; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;, &#1090;&#1086; &#1086;&#1085;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;. &#1042; &#1090;&#1091;&#1087;&#1080;&#1082;&#1086;&#1074;&#1086;&#1081; &#1079;&#1086;&#1085;&#1077; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; ASBR.
    </p>
    <p>
      <b>Totally stubby area</b>. Totally stubby area &#1085;&#1077; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1093; &#1076;&#1083;&#1103; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1080;&#1079; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1079;&#1086;&#1085;. &#1045;&#1089;&#1083;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;&#1084; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1079;&#1072; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1099; &#1079;&#1086;&#1085;&#1099;, &#1090;&#1086; &#1086;&#1085;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;. Cisco-proprietary &#1090;&#1080;&#1087; &#1079;&#1086;&#1085;&#1099;.
    </p>
    <p>
      <b>Not-so-stubby area (NSSA)</b>. &#1047;&#1086;&#1085;&#1072; NSSA &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1090;&#1080;&#1087; LSA &#8212; LSA type 7. &#1042; NSSA &#1079;&#1086;&#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; ASBR.
    </p>
  </body>
</html></richcontent>
