  <body>
    <p>
      <b>&#160;&#160;&#160;&#1042;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (internal router)</b>&#160;&#8212; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;, &#1074;&#1089;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1072;&#1090; &#1086;&#1076;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1077;. &#1059; &#1090;&#1072;&#1082;&#1080;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1085;&#1072; &#1073;&#1072;&#1079;&#1072; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;. &#1042;&#1085;. &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1079;&#1085;&#1072;&#1077;&#1090; &#1082;&#1072;&#1082; &#1091;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1074;&#1086;&#1103; &#1089;&#1077;&#1090;&#1100;.
    </p>
    <p>
      <b>&#160;&#160;&#160;&#1055;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (area border router, ABR)</b>&#160;&#8212; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1077;&#1090; &#1086;&#1076;&#1085;&#1091; &#1080;&#1083;&#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1079;&#1086;&#1085; &#1089; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1086;&#1081; (&#1079;&#1086;&#1085;&#1072; 0) &#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1096;&#1083;&#1102;&#1079;&#1072; &#1076;&#1083;&#1103; &#1084;&#1077;&#1078;&#1079;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;. &#1059; &#1087;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1093;&#1086;&#1090;&#1103; &#1073;&#1099; &#1086;&#1076;&#1080;&#1085; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1077; (&#1079;&#1086;&#1085;&#1077; 0). &#1044;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1087;&#1088;&#1080;&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1091;&#1102; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;. &#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1085;&#1077; &#1082;&#1072;&#1082; Link state &#1072; &#1082;&#1072;&#1082; Distance-vector. &#1055;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085; DR-&#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084; (&#1075;&#1083;&#1072;&#1074;&#1085;&#1099;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084;). DR-&#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1091; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1082;&#1080;&#1076;&#1072;&#1102;&#1090; LSA-&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1086;&#1085; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1088;&#1072;&#1089;&#1082;&#1080;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100;. &#1044;&#1083;&#1103; ABR &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1090;&#1100;&#1089;&#1103; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1089; &#1087;&#1086;&#1074;&#1099;&#1096;&#1077;&#1085;&#1085;&#1086;&#1081; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;.
    </p>
    <p>
      <b>&#160;&#160;&#160;&#1052;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (backbone router)</b>&#160;&#8212; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1091; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1093;&#1086;&#1090;&#1103; &#1073;&#1099; &#1086;&#1076;&#1080;&#1085; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1077;. &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1093;&#1086;&#1078;&#1077; &#1085;&#1072; &#1087;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;, &#1086;&#1076;&#1085;&#1072;&#1082;&#1086; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1085;&#1077; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1084;. &#1042;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;, &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1072;&#1090; &#1079;&#1086;&#1085;&#1077; 0, &#1090;&#1072;&#1082;&#1078;&#1077; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084;. <b>&#1056;&#1086;&#1091;&#1090;&#1077;&#1088; &#1079;&#1086;&#1085;&#1099; 0</b>&#160;&#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1079;&#1085;&#1072;&#1077;&#1090; &#1086; connected &#1089;&#1077;&#1090;&#1103;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; &#1076;&#1088;&#1091;&#1075;&#1080;&#1079; &#1079;&#1086;&#1085; (&#1086;&#1085; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1086;&#1090;&#1076;&#1072;&#1077;&#1090; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; ABR-&#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084;)
    </p>
    <p>
      <b>&#160;&#160;&#160;&#1055;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; (AS boundary router, ASBR)</b>&#160;&#8212; &#1086;&#1073;&#1084;&#1077;&#1085;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1077;&#1081; &#1089; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084;&#1080; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1072;&#1097;&#1080;&#1084;&#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1099;&#1084; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1084; (e.g. &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1090; &#1074; <b>&#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;</b>). &#1055;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; &#1083;&#1102;&#1073;&#1086;&#1084; &#1084;&#1077;&#1089;&#1090;&#1077; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1080; &#1073;&#1099;&#1090;&#1100; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1084;, &#1087;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1084; &#1080;&#1083;&#1080; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084;
    </p>
    <p>
      &#160;&#160; <b>&#1042;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (designated router, DR)</b>
    </p>
    <p>
      &#160;&#160;&#160;&#1042; &#1089;&#1077;&#1090;&#1103;&#1093; &#1089;&#1086; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1086;&#1084; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1084;&#1077;&#1078;&#1076;&#1091; &#1074;&#1089;&#1077;&#1084;&#1080; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084;&#1080;. &#1045;&#1089;&#1083;&#1080; &#1073;&#1099; &#1074;&#1089;&#1077; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1099; &#1074; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072; &#1086;&#1073;&#1084;&#1077;&#1085;&#1080;&#1074;&#1072;&#1083;&#1080;&#1089;&#1100; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1077;&#1081;, &#1101;&#1090;&#1086; &#1087;&#1088;&#1080;&#1074;&#1077;&#1083;&#1086; &#1073;&#1099; &#1082; &#1088;&#1072;&#1089;&#1089;&#1099;&#1083;&#1082;&#1077; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1075;&#1086; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1082;&#1086;&#1087;&#1080;&#1081; LSA. <b>&#1044;&#1083;&#1103; &#1087;&#1088;&#1077;&#1076;&#1086;&#1090;&#1074;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099; &#1088;&#1072;&#1089;&#1089;&#1099;&#1083;&#1082;&#1080; &#1082;&#1086;&#1087;&#1080;&#1081; LSA</b>&#160; &#1074; &#1089;&#1077;&#1090;&#1103;&#1093; &#1089;&#1086; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1084; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1086;&#1084; &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (DR)&#160;&#160;&#1080; &#1079;&#1072;&#1087;&#1072;&#1089;&#1085;&#1086;&#1081; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (BDR). <b>&#1042;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (designated router, DR)</b>&#160;&#160;&#8212; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1084; &#1088;&#1072;&#1089;&#1089;&#1099;&#1083;&#1082;&#1080; LSA &#1074; &#1089;&#1077;&#1090;&#1080;. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1089;&#1077;&#1090;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103; &#1089;&#1084;&#1077;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089; DR. &#1048;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1086;&#1073; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103;&#1093; &#1074; &#1089;&#1077;&#1090;&#1080; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084;, &#1086;&#1073;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080;&#1074;&#1096;&#1080;&#1084; &#1101;&#1090;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077;, &#1085;&#1072; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;, &#1072; &#1090;&#1086;&#1090;, &#1074; &#1089;&#1074;&#1086;&#1102; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100;, &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1090;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1101;&#1090;&#1072; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1073;&#1099;&#1083;&#1072; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1072; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072; &#1084;&#1085;&#1086;&#1078;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;. &#1053;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1082;&#1086;&#1084; &#1074; &#1089;&#1093;&#1077;&#1084;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089; DR &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;, &#1095;&#1090;&#1086; &#1087;&#1088;&#1080; &#1074;&#1099;&#1093;&#1086;&#1076;&#1077; &#1077;&#1075;&#1086; &#1080;&#1079; &#1089;&#1090;&#1088;&#1086;&#1103; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085; &#1085;&#1086;&#1074;&#1099;&#1081; DR. &#1053;&#1086;&#1074;&#1099;&#1077; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1089;&#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1099; &#1080;, &#1087;&#1086;&#1082;&#1072; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; &#1085;&#1077; &#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1080;&#1079;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1089; &#1073;&#1072;&#1079;&#1086;&#1081; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1085;&#1086;&#1074;&#1086;&#1075;&#1086; DR, &#1089;&#1077;&#1090;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1089;&#1099;&#1083;&#1082;&#1080; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;. &#1044;&#1083;&#1103; &#1091;&#1089;&#1090;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1082;&#1072; <b>&#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090;&#1089;&#1103; BDR</b>.
    </p>
    <p>
      &#160;&#160; <b>&#1056;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1081; &#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (backup designated router, BDR)</b>. &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1089;&#1077;&#1090;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072; &#1085;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089; DR, &#1085;&#1086; &#1080; BDR. DR &#1080; BDR &#1090;&#1072;&#1082;&#1078;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1102;&#1090; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072; &#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1086;&#1073;&#1086;&#1081;. &#1055;&#1088;&#1080; &#1074;&#1099;&#1093;&#1086;&#1076;&#1077; &#1080;&#1079; &#1089;&#1090;&#1088;&#1086;&#1103; DR, BDR &#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1089;&#1103; DR &#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1074;&#1089;&#1077; &#1077;&#1075;&#1086; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;. &#1058;&#1072;&#1082; &#1082;&#1072;&#1082; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1099; &#1089;&#1077;&#1090;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1083;&#1080; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072; &#1089; BDR, &#1074;&#1088;&#1077;&#1084;&#1103; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089;&#1077;&#1090;&#1080; &#1084;&#1080;&#1085;&#1080;&#1084;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;.
    </p>
  </body>
</html></richcontent>
