<node TEXT="Алгоритм вычисления метрики" ID="ID_1934213867" CREATED="1519112080117" MODIFIED="1519112080117"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1052;&#1077;&#1090;&#1088;&#1080;&#1082;&#1072;</b>&#160;- &#1095;&#1080;&#1089;&#1083;&#1086;, &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1077;&#1077; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1089;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;. &#1058;&#1088;&#1072;&#1092;&#1080;&#1082; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1087;&#1091;&#1090;&#1080; &#1089; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1081; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1086;&#1081;
    </p>
    <p>
      
    </p>
    <p>
      EIGRP &#1080;&#1084;&#1077;&#1077;&#1090; &#1087;&#1088;&#1086;&#1076;&#1074;&#1080;&#1085;&#1091;&#1090;&#1099;&#1081; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1103; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1080; <b>DUAL&#160;(Diffusing Update ALgorithm)</b>, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; 5 &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074; &#1076;&#1083;&#1103; &#1088;&#1072;&#1089;&#1095;&#1077;&#1090;&#1072;:
    </p>
    <ul>
      <li>
        <b>Bandwidth&#160;(&#1055;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1085;&#1072;&#1103; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1100;)</b>. &#1052;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1085;&#1072;&#1103; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1100; &#1076;&#1083;&#1103; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072; (&#1072; &#1085;&#1077; &#1089;&#1091;&#1084;&#1084;&#1072; &#1094;&#1077;&#1085; (cost) &#1074; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; OSPF).
      </li>
      <li>
        <b>Delay (&#1047;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072;)</b>. &#1057;&#1091;&#1084;&#1084;&#1072;&#1088;&#1085;&#1072;&#1103; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; &#1085;&#1072; &#1074;&#1089;&#1105;&#1084; &#1087;&#1091;&#1090;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;.
      </li>
      <li>
        <b>Reliability (&#1053;&#1072;&#1076;&#1077;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100;)</b>. &#1053;&#1072;&#1080;&#1093;&#1091;&#1076;&#1096;&#1080;&#1081; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100; &#1085;&#1072;&#1076;&#1105;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; &#1085;&#1072; &#1074;&#1089;&#1105;&#1084; &#1087;&#1091;&#1090;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;, &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1085;&#1072; keepalive.
      </li>
      <li>
        <b>Loading (&#1047;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085;&#1085;&#1086;&#1089;&#1090;&#1100;)</b>. &#1053;&#1072;&#1080;&#1093;&#1091;&#1076;&#1096;&#1080;&#1081; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1085;&#1072; &#1074;&#1089;&#1105;&#1084; &#1087;&#1091;&#1090;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;, &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1085;&#1072; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1075;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1086;&#1084; &#1085;&#1072; &#1085;&#1105;&#1084; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1077; bandwidth.
      </li>
      <li>
        <b>MTU</b>. &#1052;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; MTU &#1085;&#1072; &#1074;&#1089;&#1105;&#1084; &#1087;&#1091;&#1090;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;.
      </li>
    </ul>
    <p>
      &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;, EIGRP &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; <b>&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1077;&#1088;&#1074;&#1099;&#1077; &#1076;&#1074;&#1072;</b>&#160;&#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072;, &#1090;.&#1082;. &#1085;&#1072;&#1076;&#1077;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085;&#1085;&#1086;&#1089;&#1090;&#1100; - &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1085;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1080;&#1079;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1076;&#1086; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1088;&#1072;&#1079; &#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1091;. &#1057;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;, &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1088;&#1072;&#1089;&#1095;&#1077;&#1090; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1080; &#1076;&#1083;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; &#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1085;&#1086;&#1081; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072; &#1076;&#1086; 100%. MTU &#1085;&#1077; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1085;&#1086;&#1081;, &#1085;&#1086; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1077; &#1089;&#1083;&#1072;&#1073;&#1086;&#1075;&#1086; &#1074;&#1083;&#1080;&#1103;&#1085;&#1080;&#1103; &#1085;&#1072; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;. &#1048; &#1076;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1088;&#1072;&#1089;&#1095;&#1077;&#1090;&#1072;, &#1090;&#1086; &#1101;&#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1093;
    </p>
    <p>
      
    </p>
    <p style="text-align: center">
      <b>&#1052;&#1077;&#1090;&#1088;&#1080;&#1082;&#1072;=(10^7/min bandwidth &#1074; &#1082;&#1080;&#1083;&#1086;&#1073;&#1072;&#1081;&#1090;&#1072;&#1093;)*256+(&#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; n*100)*256</b>
    </p>
  </body>
</html></richcontent>
