      <b>&#1054;&#1073;&#1084;&#1077;&#1085; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;&#1084;&#1080; EIGRP</b>
    </p>
    <p>
      
    </p>
    <p>
      R1 --&gt; <b>Hello-&#1087;&#1072;&#1082;&#1077;&#1090;&#1099;</b>&#160;--&gt; R2 //&#160;&#1055;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072;
    </p>
    <p>
      &#160;&#160;&#160;R1 &lt;-- Hello-&#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &lt;-- R2
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;<b>&#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1089;&#1086;&#1089;&#1077;&#1076;&#1077;&#1081;</b>&#160; (neighbour table)
    </p>
    <p>
      &#160;&#160;&#160;R1 --&gt; Update-&#1087;&#1072;&#1082;&#1077;&#1090;&#1099; --&gt; R2
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;R1 &lt;-- Ack-&#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &lt;-- R2
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;<b>&#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080;</b>&#160; (&#1074;&#1089;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1074;&#1089;&#1077;&#1093; &#1089;&#1086;&#1089;&#1077;&#1076;&#1077;&#1081;)
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;<b>&#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;</b>&#160; (&#1083;&#1091;&#1095;&#1096;&#1080;&#1077;-Successors &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;)
    </p>
    <p>
      &#160;&#160;&#160;R2 --&gt; Update-&#1087;&#1072;&#1082;&#1077;&#1090;&#1099; --&gt; R1
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;R2 &lt;-- Ack-&#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &lt;-- R1
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; (&#1074;&#1089;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1074;&#1089;&#1077;&#1093; &#1089;&#1086;&#1089;&#1077;&#1076;&#1077;&#1081;)
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#1058;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; (&#1083;&#1091;&#1095;&#1096;&#1080;&#1077;-Successors &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;)
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1072;&#1082;&#1077;&#1090;&#1099;</b>
    </p>
    <p>
      Hello - &#1087;&#1072;&#1082;&#1077;&#1090; &#1076;&#1083;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1072;
    </p>
    <p>
      Update - &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1086;&#1073;&#1086; &#1074;&#1089;&#1077;&#1093; &#1089;&#1077;&#1090;&#1103;&#1093;, &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1091; (&#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;)
    </p>
    <p>
      ACK -
    </p>
    <p>
      <b>Queries (Query)</b>&#160;- &#1087;&#1086;&#1080;&#1089;&#1082; &#1087;&#1086;&#1090;&#1077;&#1088;&#1103;&#1085;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;
    </p>
    <p>
      <b>&#160;&#160;&#160;Replies (Reply)</b>&#160;- &#1086;&#1090;&#1074;&#1077;&#1090; &#1085;&#1072; Query. &#1055;&#1086;&#1090;&#1077;&#1088;&#1103; Reply-&#1087;&#1072;&#1082;&#1077;&#1090;&#1072; (Stuck-in-Active)
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160; <b>SIA-Queries</b>&#160;- &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1099;&#1081; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1087;&#1088;&#1080; &#1084;&#1086;&#1083;&#1095;&#1080;&#1085;&#1080;&#1080; (3min) &#1089;&#1086;&#1089;&#1077;&#1076;&#1077;&#1081; &#1085;&#1072; Query
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; <b>SIA-Replies</b>&#160;- &#1086;&#1090;&#1074;&#1077;&#1090; &#1085;&#1072; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1099;&#1081; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;
    </p>
  </body>
</html></richcontent>
