<node TEXT="Сообщения BGP" ID="ID_1818575999" CREATED="1519112080116" MODIFIED="1519112080116"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; BGP </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>open</b>&#160;- &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; router id &#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1090;&#1072;&#1081;&#1084;&#1077;&#1088;&#1086;&#1074;
    </p>
    <p>
      <b>keepalive</b>&#160;- &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1080; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089;&#1086;&#1089;&#1077;&#1076;&#1085;&#1077;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;
    </p>
    <p>
      <b>update</b>&#160;- &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089;&#1077;&#1090;&#1080; &#1080; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;
    </p>
    <p>
      <b>notification</b>&#160;- &#1076;&#1083;&#1103; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1080;&#1103; &#1089;&#1077;&#1089;&#1089;&#1080;&#1080;
    </p>
    <ul>
      <li>
        &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; <a href="#ID_971470020">TCP</a>&#160;(&#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090; &#1085;&#1072;&#1076;&#1077;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1082;&#1080; &#1073;&#1083;&#1072;&#1075;&#1086;&#1076;&#1072;&#1088;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102; TCP-&#1089;&#1077;&#1089;&#1089;&#1080;&#1080;
      </li>
      <li>
        &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1077;&#1089;&#1089;&#1080;&#1080; &#1085;&#1072; <b>179 &#1087;&#1086;&#1088;&#1090;</b>
      </li>
      <li>
        &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1087;&#1086;&#1085;&#1103;&#1090;&#1080;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &quot;<b>&#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090; TCP-&#1089;&#1077;&#1089;&#1089;&#1080;&#1080;</b>&quot; &#1080; <b>&#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081;</b>, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1097;&#1080;&#1093;&#1089;&#1103; &#1074; &#1101;&#1090;&#1086;&#1081; &#1089;&#1077;&#1089;&#1089;&#1080;&#1080;
      </li>
    </ul>
  </body>
