<node TEXT="Состояния BGP" ID="ID_1261866350" CREATED="1519112080116" MODIFIED="1519112080116"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; BGP</b>
    </p>
    <p>
      
    </p>
