<node TEXT="Коды" ID="ID_779173551" CREATED="1519112080124" MODIFIED="1519112080124"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Codes:</b>
    </p>
    <p>
      C - connected (&#1085;&#1072;&#1087;&#1088;&#1103;&#1084;&#1091;&#1102; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; &#1082; &#1085;&#1072;&#1096;&#1077;&#1084;&#1091; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1091;)
    </p>
    <p>
      S - static (&#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1085; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;)
    </p>
    <p>
      192.168.0.0/16 [110/4] // 110 - &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072; (&#1095;&#1077;&#1084; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; &#1095;&#1080;&#1092;&#1088;&#1072;, &#1090;&#1077;&#1084; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1074;&#1072;&#1078;&#1085;&#1077;&#1077;), 4 - &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      I - IGRP, R - RIP, M - mobile, B - BGP
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;D - EIGRP, EX - EIGRP external, O - OSPF, IA - OSPF inter area (&#1080;&#1079; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099;)
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;N1 - OSPF NSSA external type 1, N2 - OSPF NSSA external type 2
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;E1 - OSPF external type 1, E2 - OSPF external type 2, E - EGP
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;i - IS-IS, L1 - IS-IS level-1, L2 - IS-IS level-2, ia - IS-IS inter area
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;* - candidate default, U - per-user static route, o - ODR
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;P - periodic downloaded static route
    </p>
    <ul>
      <li>
        &#1091;&#1076;&#1072;&#1083;&#1103;&#1090;&#1100; &#1084;&#1086;&#1078;&#1085;&#1086; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; (connected &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1085;&#1077; &#1091;&#1076;&#1072;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103;)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      ------------
    </p>
    <p>
      1. directly connected &#1089;&#1077;&#1090;&#1080;
    </p>
    <p>
      2. &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1084;
    </p>
    <p>
      3. &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1089;&#1077;&#1090;&#1080; - &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1099; &#1076;&#1088;&#1091;&#1075; &#1076;&#1088;&#1091;&#1075;&#1091; &#1089;&#1086;&#1086;&#1073;&#1097;&#1080;&#1083;&#1080;
    </p>
    <p>
      4. default &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; - &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1080;&#1083;&#1080; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081;
