      </li>
    </ul>
    <p>
      4. Dual-Multihomed. &#1053;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1074;. <b>R==ISP1</b>, <b>R==ISP2 </b>
    </p>
    <ul>
      <li>
        &#1089;&#1083;&#1086;&#1078;&#1085;&#1072;&#1103; &#1089;&#1093;&#1077;&#1084;&#1072; &#1089; &#1076;&#1074;&#1086;&#1081;&#1085;&#1099;&#1084; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084;
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Методы ускорения маршрутизации" ID="ID_1907360751" CREATED="1519112080125" MODIFIED="1567414552833"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Process switching</b>. &#1057;&#1072;&#1084;&#1099;&#1081; &#1084;&#1077;&#1076;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1084;&#1077;&#1090;&#1086;&#1076; - &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; CPU, &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1085;&#1086;&#1084; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077;
    </p>
    <p>
      <b>Fast switching (route caching)</b>. &#1041;&#1099;&#1089;&#1090;&#1088;&#1099;&#1081; &#1084;&#1077;&#1090;&#1086;&#1076; - &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1087;&#1086;&#1090;&#1086;&#1082;&#1072; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; CPU, &#1086;&#1076;&#1085;&#1072;&#1082;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1091;&#1097;&#1080;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1085;&#1086; &#1085;&#1072; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1093;&#1077;&#1084;&#1077; ASIC (&#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1093;&#1077;&#1084;&#1072; &#1076;&#1083;&#1103; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;)
    </p>
    <p>
      <b>Cisco Express Forwarding&#160;- <a href="#ID_1081071164">CEF</a>&#160;- (topology-based switching)</b>. &#1057;&#1072;&#1084;&#1099;&#1081; &#1073;&#1099;&#1089;&#1090;&#1088;&#1099;&#1081; &#1084;&#1077;&#1090;&#1086;&#1076; - &#1074;&#1089;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1085;&#1086; &#1077;&#1097;&#1077; &#1076;&#1086; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090; &#1080;&#1079; &#1087;&#1086;&#1090;&#1086;&#1082;&#1072;
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Policy-based Routing (PBR)" ID="ID_80996055" CREATED="1519112080125" MODIFIED="1567414403991"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Policy-based Routing (PBR)</b>&#160;- &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082; (&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;, &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1081;)
    </p>
    <ul>
      <li>
        &#1095;&#1072;&#1089;&#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; <b>&#1076;&#1083;&#1103; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1080;&#1079;&#1073;&#1099;&#1090;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1080;</b>&#160; &#1074; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1086;&#1092;&#1080;&#1089;&#1072;&#1093;, &#1087;&#1088;&#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;&#1093; &#1089;&#1074;&#1103;&#1079;&#1080; &#1089; &#171;&#1074;&#1077;&#1096;&#1085;&#1080;&#1084; &#1084;&#1080;&#1088;&#1086;&#1084;&#187; (&#171;&#1075;&#1091;&#1075;&#1083;&#1080;&#1090;&#1089;&#1103;&#187; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1084; PBR 2 ISP)
      </li>
      <li>
        <b>SLA &#1080; tracking</b>&#160;- &#1076;&#1074;&#1077; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1091;&#1102;&#1090; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1088;&#1086;&#1076;&#1072; icmp &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; (&#1087;&#1088;&#1080; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103;&#1093; - SLA), &#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1102;&#1090; &#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;&#1080;&#1085;&#1075; &#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1075;&#1077;&#1085;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072; (tracking).
      </li>
      <li>
        &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1074; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;&#1093; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; (&#1082; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1091; BGP; OSPF;EIGRP) &#1076;&#1083;&#1103; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080; &#1080; redistributions (&#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;) &#1088;&#1086;&#1091;&#1090;&#1086;&#1074; &#1080; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; &#1080; &#1090;.&#1087;., &#1074; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;
      </li>
      <li>
        &#1087;&#1086;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1080;&#1077; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084;&#1086;&#1074; &#1091;&#1083;&#1091;&#1095;&#1096;&#1077;&#1085;&#1080;&#1077; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1086;&#1074; (QoS)
      </li>
    </ul>
    <p>
      &#1089;&#1084;. <a href="#ID_1496954781">PBR (Cisco)</a>
    </p>
  </body>
</html></richcontent>
