<node TEXT="Команды Huawei" ID="ID_1405401906" CREATED="1559038846838" MODIFIED="1719916890325"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">display interface brief</font>&nbsp;&nbsp;#&nbsp;&nbsp;Список всех портов
    </p>
    <p>
      <font color="#0000c0">display interface description</font>&nbsp;&nbsp;# Список всех портов
    </p>
    <p>
      <font color="#0000c0">display interface &lt;интерфейс&gt;</font>&nbsp;&nbsp;&nbsp;# Просмотр состояния интерфейса
    </p>
    <ul>
      <li>
        Input bandwidth utilization&nbsp;&nbsp;: 10.13%. Утилизация от клиента 100Mb. Т.е. 10% от 1000Mb
      </li>
      <li>
        Output bandwidth utilization : 20.23%. Утилизация к клиенту 200Mb. Т.е. 20% от 1000Mb
      </li>
    </ul>
    <p>
      <font color="#0000c0">display transceiver interface XGigabitEthernet0/0/15 verbose</font>&nbsp;&nbsp;# Состояние трансивера
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">display mac-address interface &lt;интерфейс&gt;</font>&nbsp;&nbsp;&nbsp;#&nbsp;&nbsp;MAC-адреса
    </p>
    <p>
      <font color="#0000c0">display vlan</font>&nbsp;&nbsp;# Список VLAN'ов
    </p>
    <p>
      <font color="#0000c0">display mac-address vlan &lt;VLAN&gt;</font>&nbsp;&nbsp;# MAC-адреса VLAN
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">display traffic policy interface &lt;интерфейс&gt;</font>&nbsp;&nbsp;# Показать скорость (по тарифу)
    </p>
    <p>
      <font color="#0000c0">display version</font>&nbsp;&nbsp;# Uptime
    </p>
    <p>
      
    </p>
    <p>
      <b>*********Поиск порта на коммутаторе по известному IP-адресу*****************</b>
    </p>
    <ol>
      <li>
        <font color="#0000c0">telnet <b>sw___.dev</b></font>&nbsp;&nbsp;# Подключиться к свитчу в стойке (<b>Huawei</b>)<br/><font color="#0000c0">display mac-address | i &lt;часть MAC-адреса&gt;</font>&nbsp;&nbsp;# Видим на каком порту MAC-адрес и соотв. IP
      </li>
    </ol>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Команды Juniper" ID="ID_1922070384" CREATED="1556031531022" MODIFIED="1719916908406"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">Show ?</font>&nbsp;&nbsp;# Вывод справки по командам
    </p>
    <p>
      <font color="#0000c0">show version</font>&nbsp;&nbsp;# Версия сетевого оборудования
    </p>
    <p>
      <font color="#0000c0">show vlans&nbsp;&lt;id vlan&gt;</font>&nbsp;&nbsp;# (<font color="#ff0000">???</font>)VLAN
    </p>
    <p>
      <font color="#0000c0">show arp | match c8:be:19:25:dc:40</font>&nbsp;&nbsp;# arp
    </p>
    <p>
      <font color="#0000c0">show arp no-resolve | match ae0.12983</font>&nbsp;&nbsp;# arp, показать MAC-адреса и привязанные к ним IP
    </p>
    <p>
      <font color="#0000c0">show configuration interfaces ae0.11096</font>&nbsp;&nbsp;# Скорость выделяемая клиенту и текущие ограничения
    </p>
    <p>
      <font color="#0000c0">show interfaces ae0.79</font>&nbsp;&nbsp;# Информация на порту
    </p>
    <p>
      <font color="#0000c0">show chassis alarms</font>&nbsp;&nbsp;# Информацияя по алармам
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">show interfaces descriptions | match ae0.14390</font>&nbsp;&nbsp;# Состояние интерфейса
    </p>
    <p>
      <font color="#0000c0">show interfaces descriptions | match ae0</font>&nbsp;&nbsp;# Линк и куда уходит интерфейс
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">show log messages | match ae0</font>&nbsp;&nbsp;# Общие логи на порту
    </p>
    <p>
      <font color="#0000c0">show log messages | match ae0.11006</font>&nbsp;&nbsp;# Логи нужного юнита
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">show bgp summary</font>&nbsp;&nbsp;# BGP сессии
    </p>
    <p>
      <font color="#0000c0">show bgp summary | match 62.152.40.166 </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>*********Поиск порта на коммутаторе по известному IP-адресу*****************</b>
    </p>
    <ol>
      <li>
        <font color="#0000c0">telnet <b>rt1.msk.dev</b></font>&nbsp;&nbsp;# Подключиться к роутеру (<b>Juniper</b>)<br/><font color="#0000c0">show arp | match &lt;IP-адрес&gt;</font>&nbsp;&nbsp;# Определить MAC-адрес сервера (сетевой карты)
      </li>
    </ol>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Команды Qtech" ID="ID_1203429635" CREATED="1556018679524" MODIFIED="1719916546352"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        Qtech 2900 (<b>Ctrl+H</b>&nbsp;- вместо Backspace)
      </li>
    </ul>
    <p>
      <b>Коммутаторы Qtech 2700, 2800, 2900</b>
    </p>
    <p>
      <font color="#0000c0">show interface ethernet status</font>&nbsp;&nbsp;# Список всех портов
    </p>
    <p>
      <font color="#0000c0">show interface brief</font>&nbsp;&nbsp;# <b>2900</b>. Список всех портов. Админ down смотреть по <b>false или true. </b>
    </p>
    <p>
      <font color="#0000c0">show description interface</font>&nbsp;&nbsp;# <b>2900</b>. Сокращенный список портов
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">show mac-address-table vlan 22</font>&nbsp;&nbsp;# MAC-адреса VLAN. Смотреть только у конечных клиентов
    </p>
    <p>
      <font color="#0000c0">show mac-address-table interface ethernet 0/5</font>&nbsp;&nbsp;# MAC-адрес на порту
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">show&nbsp;interface ethernet 0/5</font>&nbsp;&nbsp;# Статистика (ошибки) по порту
    </p>
    <p>
      <font color="#0000c0">show statistics interface ethernet 0/5</font>&nbsp;&nbsp;# <b>2900</b>. Статистика (ошибки) на порту
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">virtual-cable-test interface ethernet 1/1&nbsp; </font># Проверить физику меди.
    </p>
    <ul>
      <li>
        норма&nbsp;- well, 40 (до клиента 40 метров)
      </li>
      <li>
        обрыв, пара открыта (кабель не подключен) - open, 10 - (проблемы на 10 метре)
      </li>
      <li>
        пара закорочена -short
      </li>
      <li>
        combo порт (оптика и RJ45) длину не должен показывать ибо не умеет и выдает &quot;EthernetПорт active media is fiber doesn't support VCT&quot;
      </li>
      <li>
        abnormal - ненормальное состояние линии, например короткое замыкание между разными парами
      </li>
    </ul>
    <p>
      <font color="#0000c0">show transceiver interface e1/25</font>&nbsp;&nbsp;# Проверка SFP
    </p>
    <p>
      <font color="#0000c0">show logging buffered level warnings</font>&nbsp;&nbsp;# Логи по всем портам
    </p>
    <p>
      <font color="#0000c0">show logging buffered level warnings | i 0/5</font>&nbsp;&nbsp;# Логи по конкретному порту. <b>i</b>&nbsp;- это include (аналог grep)
    </p>
    <p>
      <font color="#0000c0">show logging buffered </font>&nbsp;#&nbsp;&nbsp;<b>2900</b>. Логи по всем портам. <b>Если отключение по unicast шторм, то это в 90% сбой конфига. </b>НОК убрать настройку на срабатывание.
    </p>
    <p>
      <font color="#0000c0">show logging buffered module &lt;module_name&gt;</font>&nbsp;&nbsp;# <b>2900</b>. (<font color="#ff0000">???Проверить</font>) Логи по конкретному порту.
    </p>
    <p>
      <font color="#0000c0">show info-center logbuffer I i &lt;интерфейс&gt;</font>&nbsp;&nbsp;# 2900
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">show version</font>&nbsp;&nbsp;# uptime
    </p>
    <p>
      show system&nbsp;&nbsp;#&nbsp; <b>2900</b>. uptime
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">show vlan</font>&nbsp;&nbsp;# Список всех вланов. <font color="#ff0000">Можно не использовать</font>
    </p>
    <p>
      <font color="#0000c0">show vlan 4065</font>&nbsp;&nbsp;#&nbsp;<b>2900</b>. Конкретный VLAN. <font color="#ff0000">Можно не использовать</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">show cpu-utilization</font>&nbsp;&nbsp;# Сколько свободных ресурсов еще есть, т.е. это обратное нагрузке
    </p>
    <p>
      
    </p>
    <p>
      Посмотреть есть ли какое ограничение на клиентском порту
    </p>
    <p>
      <font color="#0000c0">show bandwidth-control interface ethernet 0/6</font>
    </p>
    <p>
      <font color="#0000c0">show running-config interface ethernet 0/6 </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">show statistics dynamic interface</font>&nbsp;&nbsp;# Статистика интерфейсов в динамике (счетчики вх/исх пакетов, кол-во переданных данных, счетчики броадкаст трафика)
    </p>
    <p>
      <font color="#0000c0">show bandwidth-control interface</font>&nbsp;&nbsp;# Ограничения на порту
    </p>
    <p>
      
    </p>
    <p>
      ----------------------------
    </p>
    <p>
      <font color="#0000c0">sh power</font>&nbsp;&nbsp;# 2995. Питание
    </p>
    <p>
      <font color="#0000c0">show logging buffered 8</font>&nbsp;&nbsp;#&nbsp;<b>2900</b>. Логи в т.ч. перезагрузка холодная или горячая. 8 - level number
    </p>
    <p>
      <font color="#0000c0">show logging buffered level-list 3 to 8</font>&nbsp;&nbsp;# <b>2900</b>. Логи в т.ч. перезагрузка холодная или горячая.
    </p>
    <p>
      <font color="#0000c0">clear logging buffered</font>
    </p>
    <p>
      <font color="#0000c0">show logging buffered level critical</font>&nbsp;&nbsp;# Логи в т.ч. перезагрузка холодная или горячая
    </p>
    <p>
      clear counters interface e 1/0/16&nbsp;&nbsp;# Очистка статистики по порту
    </p>
    <p>
      <font color="#0000c0">show transceiver interface eternet 1/0/28</font>&nbsp;&nbsp;# Проверка оптического модуля
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
