        <font color="#0000c0">telnet <b>rt1.msk.dev</b></font>&nbsp;&nbsp;# Подключиться к роутеру (<b>Juniper</b>)<br/><font color="#0000c0">show arp | match &lt;IP-адрес&gt;</font>&nbsp;&nbsp;# Определить MAC-адрес сервера (сетевой карты)
      </li>
