        <font color="#0000c0">telnet <b>sw___.dev</b></font>&nbsp;&nbsp;# Подключиться к свитчу в стойке (<b>Huawei</b>)<br/><font color="#0000c0">display mac-address | i &lt;часть MAC-адреса&gt;</font>&nbsp;&nbsp;# Видим на каком порту MAC-адрес и соотв. IP
