<node TEXT="Активное" FOLDED="true" ID="ID_1216505151" CREATED="1519112080139" MODIFIED="1680193611546"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1628663721">SNMP</a>
    </p>
    <ul>
      <li>
        нуждается в доп. энергии
      </li>
    </ul>
