<node TEXT="Proxy ARP" ID="ID_545010114" CREATED="1519112080140" MODIFIED="1555583001667"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1665435259">ARP</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Proxy ARP</b>&#160;&#8212; &#1090;&#1077;&#1093;&#1085;&#1080;&#1082;&#1072;, &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1102;&#1097;&#1072;&#1103;&#1089;&#1103; &#1074; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;&#1093; &#1076;&#1083;&#1103; &#1090;&#1088;&#1072;&#1085;&#1089;&#1083;&#1103;&#1094;&#1080;&#1080; ARP-&#1086;&#1090;&#1074;&#1077;&#1090;&#1086;&#1074; &#1080;&#1079; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072; &#1089;&#1077;&#1090;&#1080; &#1074; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081;. (<b>&#1045;&#1089;&#1083;&#1080; &#1085;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1072; &#1084;&#1072;&#1089;&#1082;&#1072;</b>) &#1069;&#1090;&#1072; &#1090;&#1077;&#1093;&#1085;&#1080;&#1082;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084;&#1080; &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1084;&#1080; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1084;&#1080;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1080;&#1090;&#1100; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1090;&#1100; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072; ARP MAC-&#1072;&#1076;&#1088;&#1077;&#1089; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;, &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077;&#1089;&#1103; &#1074; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084; &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1077;.
