  <body>
    <p>
      <b>&#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;-&#1096;&#1083;&#1102;&#1079;&#1099; - &#1090;</b>&#1086;, &#1095;&#1090;&#1086; &#1074; &#1084;&#1072;&#1075;&#1072;&#1079;&#1080;&#1085;&#1072;&#1093; &#1087;&#1088;&#1086;&#1076;&#1072;&#1102;&#1090; &#1076;&#1086; 10&#1050; (&#1080; &#1090;&#1086; &#1095;&#1090;&#1086; &#1074;&#1080;&#1089;&#1080;&#1090; &#1076;&#1086;&#1084;&#1072;) &#1101;&#1090;&#1086; <font color="#ff0000">&#1085;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1099;</font><b>.</b><br/><b>&#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;-&#1096;&#1083;&#1102;&#1079;</b>&#160;&#160;--&gt; <b>&#1057;&#1074;&#1080;&#1090;&#1095; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1072; (&#1085;&#1072; &#1095;&#1077;&#1088;&#1076;&#1072;&#1082;&#1077;)</b>&#160;&#160;--&gt; <b>&#1055;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1057;&#1074;&#1080;&#1090;&#1095;&#1077;&#1081;</b>&#160;&#160;(&#1086;&#1090; &#1076;&#1086;&#1084;&#1072; &#1082; &#1076;&#1086;&#1084;&#1091;) --&gt; <b>&#1052;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088; (&#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;)</b>&#160;&#160;--&gt; &#1048;&#1084;&#1077;&#1077;&#1090; &#1076;&#1074;&#1072; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1089;&#1082;&#1080;&#1084; &#1089;&#1077;&#1090;&#1103;&#1084;: &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1077;, &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1077; (&#1101;&#1090;&#1086; 2 &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;) --&gt; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1080;&#1079; &#1085;&#1080;&#1093; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; &#1082; 2&#1084; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084;
    </p>
    <p>
      
    </p>
    <p>
      <b>Edge Router</b>&#160;- &#1087;&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;, &#1077;&#1089;&#1083;&#1080; &#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1080;&#1079;&#1085;&#1091;&#1090;&#1088;&#1080; &#1087;&#1088;&#1077;&#1076;&#1087;&#1088;&#1080;&#1103;&#1090;&#1080;&#1103;. <b>Customer edge (CE) - </b>&#1077;&#1089;&#1083;&#1080; &#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1089;&#1086; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;. &#1044;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1082; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1091;
    </p>
    <p>
      <b>ISP Router</b>&#160;- &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;
    </p>
    <p>
      <b>HQ &#1080; Branch router</b>&#160;- &#1087;&#1088;&#1080; &#1088;&#1072;&#1089;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077; &#1074; &#1088;&#1072;&#1084;&#1082;&#1072;&#1093; VPN, &#1075;&#1083;&#1072;&#1074;&#1085;&#1099;&#1081; &#1080; &#1092;&#1080;&#1083;&#1080;&#1072;&#1083;&#1100;&#1089;&#1082;&#1080;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;.
    </p>
  </body>
