<node TEXT="Рекомендации" ID="ID_354478727" CREATED="1519112080141" MODIFIED="1519112080141"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        &#1064;&#1080;&#1088;&#1086;&#1082;&#1086;&#1074;&#1077;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; (Broadcast) &#1076;&#1086;&#1084;&#1077;&#1085; <b>&#1088;&#1072;&#1079;&#1073;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084;&#1080;</b>, &#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1074;&#1080;&#1090;&#1095;&#1080; &#1085;&#1077; &#1083;&#1077;&#1075;&#1083;&#1080; &#1086;&#1090; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1074;&#1077;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;.
      </li>
      <li>
        &#1055;&#1088;&#1077;&#1076;&#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1084;, &#1087;&#1086; <b>200-300</b>&#160;&#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1086;&#1074; <b>&#1074; Broadcast-&#1076;&#1086;&#1084;&#1077;&#1085;&#1077;</b>.
      </li>
      <li>
        <p>
          <b>Hardware router </b>- &#1085;&#1077; &#1082;&#1088;&#1091;&#1090;&#1086; - &#1076;&#1077;&#1083;&#1072;&#1077;&#1090; <b>&#1095;&#1072;&#1089;&#1090;&#1100; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1081;</b>&#160;&#1085;&#1072; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;. &#1058;.&#1077;. &#1101;&#1090;&#1086; software router &#1089; &#1089;&#1077;&#1090;&#1077;&#1074;&#1091;&#1093;&#1072;&#1084;&#1080;, &#1080; &#1101;&#1090;&#1080; &#1089;&#1077;&#1090;&#1077;&#1074;&#1091;&#1093;&#1080; &#1091;&#1084;&#1077;&#1102;&#1090; &#1089;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100; &#1095;&#1077;&#1082;&#1089;&#1091;&#1084;&#1084;&#1099; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;. &#1045;&#1089;&#1083;&#1080; &#1074; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1080; <b>Silicon-Based (SBR) </b>- &#1101;&#1090;&#1086; &#1090;&#1086; &#1095;&#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; - &#1074;&#1089;&#1077; &#1088;&#1072;&#1089;&#1095;&#1077;&#1090;&#1099; &#1095;&#1077;&#1088;&#1077;&#1079; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1093;&#1077;&#1084;&#1099;
        </p>
      </li>
      <li>
        <p>
          &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1091;&#1090;&#1080; &#1083;&#1091;&#1095;&#1096;&#1077; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1085;&#1072; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;.
        </p>
      </li>
      <li>
        &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;, &#1080;&#1076;&#1091;&#1097;&#1080;&#1077; &#1085;&#1072; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; <b>Passive interface (</b>&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1079;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1085;&#1077;&#1090; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074;). &#1056;&#1086;&#1091;&#1090;&#1077;&#1088; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1077;&#1072;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; EIGRP, OSPF-&#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1086;&#1090; &#1101;&#1090;&#1086;&#1075;&#1086; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;
      </li>
      <li>
        &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; <b>&#1072;&#1074;&#1090;&#1086;&#1089;&#1091;&#1084;&#1084;&#1072;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102;</b>&#160; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; &#1085;&#1072; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1093;
