      <li>
        Console cable - <b>COM &lt;----&gt; RJ45 (8P8C)</b>&#160;&#1074;&#1090;&#1099;&#1082;&#1072;&#1077;&#1084; &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1086;&#1088;&#1090; &#1085;&#1072; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1077; (&#1074;&#1099;&#1076;&#1077;&#1083;&#1077;&#1085; &#1075;&#1086;&#1083;&#1091;&#1073;&#1086;&#1081; &#1088;&#1072;&#1084;&#1082;&#1086;&#1081;)
