    <p>
      &#1057;&#1074;&#1103;&#1079;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; &#1051;&#1069;&#1055;, <b>PLC</b>&#160; (&#1072;&#1085;&#1075;&#1083;. <b>Power line communication</b>) &#8212; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;, &#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084; &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1083;&#1080;&#1085;&#1080;&#1081; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; (&#1051;&#1069;&#1055;) &#1076;&#1083;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1080;&#1083;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;. &#1057;&#1077;&#1090;&#1100; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1075;&#1086;&#1083;&#1086;&#1089; &#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077;, &#1085;&#1072;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1103; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1099;&#1081; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1087;&#1086;&#1074;&#1077;&#1088;&#1093; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086;&#1075;&#1086; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1090;&#1086;&#1082;&#1072; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1086;&#1081; 50 &#1043;&#1094; &#1080;&#1083;&#1080; 60 &#1043;&#1094;. PLC &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; BPL (&#1072;&#1085;&#1075;&#1083;. Broadband over Power Lines &#8212; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1087;&#1086;&#1083;&#1086;&#1089;&#1085;&#1