<node TEXT="3" OBJECT="java.lang.Long|3" ID="ID_1424746422" CREATED="1519112080151" MODIFIED="1725178002066"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>cat 3.</b>&#160;&#160;&#1055;&#1086;&#1083;&#1086;&#1089;&#1072; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090; 16&#1052;&#1043;&#1094;. 10BASE-T, 100BASE-T4 Ethernet. 4-&#1087;&#1072;&#1088;&#1085;&#1099;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;
    </p>
    <ul>
      <li>
        &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1087;&#1086;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1080;&#1080; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1085;&#1099;&#1093; &#1080; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081; 10BASE-T &#1080; token ring
      </li>
      <li>
