      </li>
      <li>
        &#1042; &#1089;&#1090;&#1072;&#1088;&#1099;&#1093; &#1084;&#1086;&#1076;&#1077;&#1083;&#1103;&#1093; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1076;&#1083;&#1080;&#1085;&#1072; &#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1084;&#1086;&#1075;&#1083;&#1072; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; <b>&#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082;&#1080;&#1083;&#1086;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;</b>. &#1042; &#1085;&#1086;&#1074;&#1099;&#1093; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1072;&#1093;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1093; &#1073;&#1086;&#1083;&#1077;&#1077; &#1086;&#1090;&#1079;&#1099;&#1074;&#1095;&#1080;&#1074;&#1099;&#1077; &#1092;&#1086;&#1090;&#1086;&#1087;&#1088;&#1080;&#1077;&#1084;&#1085;&#1080;&#1082;&#1080;, &#1076;&#1083;&#1080;&#1085;&#1072; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1080; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; <b>100-150 &#1084;</b>
