      </li>
      <li>
        &#1058;&#1086;&#1075;&#1076;&#1072; &#1091;&#1095;&#1072;&#1089;&#1090;&#1086;&#1082; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;, &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1099;&#1081; &#1084;&#1105;&#1088;&#1090;&#1074;&#1086;&#1081; &#1079;&#1086;&#1085;&#1086;&#1081;, &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1090;&#1100;&#1089;&#1103; &#1075;&#1076;&#1077;-&#1090;&#1086; &#1087;&#1086;&#1089;&#1077;&#1088;&#1077;&#1076;&#1080;&#1085;&#1077; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;, &#1072; &#1084;&#1105;&#1088;&#1090;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; &#1090;&#1077;&#1087;&#1077;&#1088;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1072; &#1082;&#1080;&#1083;&#1086;&#1084;&#1077;&#1090;&#1088;&#1077; &#1085;&#1072;&#1096;&#1077;&#1081; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1080;
      </li>
      <li>
        &#1053;&#1086; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1086;&#1081; &#1080; &#1090;&#1088;&#1072;&#1089;&#1089;&#1086;&#1081; &#1074;&#1089;&#1105; &#1088;&#1072;&#1074;&#1085;&#1086; &#1080;&#1084;&#1077;&#1077;&#1090;&#1089;&#1103; &#1082;&#1088;&#1086;&#1089;&#1089;&#1086;&#1074;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;, &#1080; &#1096;&#1083;&#1077;&#1081;&#1092; &#1086;&#1090; &#1077;&#1075;&#1086; &#1087;&#1080;&#1082;&#1072; &#1085;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086; &#1096;&#1080;&#1088;&#1080;&#1085;&#1077; &#1090;&#1072;&#1082;&#1086;&#1081; &#1078;&#1077;, &#1082;&#1072;&#1082; &#1080; &#1084;&#1105;&#1088;&#1090;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072;, &#1082;&#1072;&#1082; &#1080; &#1087;&#1088;&#1086;&#1095;&#1080;&#1077; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1080; &#1084;&#1099; &#1074;&#1089;&#1105; &#1088;&#1072;&#1074;&#1085;&#1086; &#1085;&#1077; &#1091;&#1074;&#1080;&#1076;&#1080;&#1084; &#1085;&#1072;&#1095;&#1072;&#1083;&#1086; &#1085;&#1072;&#1096;&#1077;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#8212; &#1096;&#1083;&#1077;&#1081;&#1092; &#1086;&#1090; &#1087;&#1080;&#1082;&#1072; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1080; &#1089; &#1082;&#1088;&#1086;&#1089;&#1089;&#1086;&#1084; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1074;&#1089;&#1105; &#1079;&#1072;&#1089;&#1083;&#1086;&#1085;&#1080;&#1090;.
      </li>
      <li>
        &#1058;&#1086;&#1075;&#1076;&#1072; &#1076;&#1083;&#1103; &#1095;&#1077;&#1075;&#1086; &#1085;&#1072;&#1084; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1072;? &#1040; &#1074;&#1086;&#1090; &#1076;&#1083;&#1103; &#1095;&#1077;&#1075;&#1086;. &#1048;&#1079;&#1084;&#1077;&#1088;&#1103;&#1103; &#1073;&#1077;&#1079; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1080;, &#1084;&#1099; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1084; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1090;&#1086;&#1095;&#1085;&#1086; &#1089;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1086; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1080; &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077; &#1085;&#1072;&#1096;&#1077;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;. &#1040; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1089; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1086;&#1081; &#1091; &#1085;&#1072;&#1089; &#1090;&#1077;&#1087;&#1077;&#1088;&#1100; &#1085;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1077; &#1077;&#1089;&#1090;&#1100; &#1088;&#1086;&#1074;&#1085;&#1099;&#1081; &#1091;&#1095;&#1072;&#1089;&#1090;&#1086;&#1082; &#1076;&#1083;&#1080;&#1085;&#1086;&#1081; 1 &#1082;&#1084; (&#1085;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; 1 &#1082;&#1084; &#8212; &#1095;&#1072;&#1089;&#1090;&#1100; &#1089;&#1098;&#1077;&#1089;&#1090; &#1084;&#1105;&#1088;&#1090;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072;) &#1087;&#1077;&#1088;&#1077;&#1076; &#1090;&#1088;&#1072;&#1089;&#1089;&#1086;&#1081;, &#1080; &#1077;&#1089;&#1090;&#1100; &#1091;&#1095;&#1072;&#1089;&#1090;&#1086;&#1082; &#1082;&#1072;&#1082;&#1086;&#1081;-&#1090;&#1086; &#1076;&#1083;&#1080;&#1085;&#1099; (&#1076;&#1086; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080;/&#1082;&#1088;&#1086;&#1089;&#1089;&#1072;) &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;!
      </li>
      <li>
        &#1048; &#1090;&#1077;&#1087;&#1077;&#1088;&#1100; &#1084;&#1099; &#1084;&#1086;&#1078;&#1077;&#1084; &#1087;&#1086;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1082;&#1088;&#1086;&#1089;&#1089;&#1077; <b>&#1084;&#1077;&#1090;&#1086;&#1076;&#1086;&#1084; &#1095;&#1077;&#1090;&#1099;&#1088;&#1105;&#1093; &#1084;&#1072;&#1088;&#1082;&#1077;&#1088;&#1086;&#1074;</b>! &#160;&#1052;&#1099; &#1091;&#1074;&#1080;&#1076;&#1080;&#1084; &#1090;&#1080;&#1087;&#1080;&#1095;&#1085;&#1091;&#1102; &#1082;&#1072;&#1088;&#1090;&#1080;&#1085;&#1091; &#1082;&#1088;&#1086;&#1089;&#1089;&#1086;&#1074;&#1086;&#1075;&#1086; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1094;&#1077;&#1085;&#1080;&#1090;&#1100;. &#1044;&#1072;, &#1084;&#1099; &#1085;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1084;, &#1075;&#1076;&#1077; &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1086;&#1085;&#1086; &#1088;&#1086;&#1078;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085;&#1086; &#1077;&#1089;&#1090;&#1100; (&#1090;&#1086; &#1083;&#1080; &#1087;&#1086;&#1090;&#1077;&#1088;&#1080; &#1085;&#1072; &#1088;&#1072;&#1079;&#1098;&#1105;&#1084;&#1077; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1086;&#1081; &#1080; &#1082;&#1088;&#1086;&#1089;&#1089;&#1086;&#1084;, &#1090;&#1086; &#1083;&#1080; &#1073;&#1088;&#1072;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1088;&#1086;&#1079;&#1077;&#1090;&#1082;&#1072;, &#1090;&#1086; &#1083;&#1080; &#1095;&#1090;&#1086;-&#1090;&#1086; &#1074; &#1082;&#1088;&#1086;&#1089;&#1089;&#1077;, &#1090;&#1086; &#1083;&#1080; &#1085;&#1072; &#1087;&#1077;&#1088;&#1074;&#1099;&#1093; &#1084;&#1077;&#1090;&#1088;&#1072;&#1093; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, &#1091;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1075;&#1086; &#1086;&#1090; &#1082;&#1088;&#1086;&#1089;&#1089;&#1072;). &#1053;&#1086; &#1077;&#1089;&#1083;&#1080; &#1084;&#1099; &#1074;&#1089;&#1105; &#1078;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1084;, &#1095;&#1090;&#1086; &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1085;&#1077;&#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082;, &#1084;&#1099; &#1084;&#1086;&#1078;&#1077;&#1084; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1074;&#1089;&#1077; &#1101;&#1090;&#1080; &#1087;&#1088;&#1077;&#1076;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1080; &#1074;&#1089;&#1105;-&#1090;&#1072;&#1082;&#1080; &#1085;&#1072;&#1081;&#1090;&#1080; &#1080; &#1091;&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1091; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103;.
      </li>
