      <li>
        <b>&#1055;&#1086;&#1080;&#1089;&#1082; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1081;.</b>&#160; &#1048;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1103;&#1076;&#1088;&#1086; &#1089;&#1074;&#1077;&#1090;&#1086;&#1074;&#1086;&#1076;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1074; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1077; &#1077;&#1089;&#1090;&#1100; <b>&#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1080;&#1083;&#1080; &#1088;&#1077;&#1079;&#1082;&#1080;&#1077; &#1087;&#1077;&#1088;&#1077;&#1075;&#1080;&#1073;&#1099;</b>, &#1074; &#1101;&#1090;&#1086;&#1081; &#1090;&#1086;&#1095;&#1082;&#1077; &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1082;&#1080;&#1085;&#1077;&#1090; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1099; &#1089;&#1074;&#1077;&#1090;&#1086;&#1074;&#1086;&#1076;&#1072; &#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1079;&#1072;&#1084;&#1077;&#1090;&#1085;&#1086; &#1089;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080; &#1087;&#1088;&#1103;&#1084;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; &#1073;&#1091;&#1092;&#1077;&#1088;. &#1048;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1080;&#1085;&#1090;&#1077;&#1085;&#1089;&#1080;&#1074;&#1085;&#1086; &#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1050;&#1044;&#1047;&#1057; &#1080; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1086;&#1074;
      </li>
      <li>
        <b>&#1044;&#1083;&#1103; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1082;&#1088;&#1086;&#1089;&#1089;&#1072; &#1087;&#1088;&#1080; &#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1077;.</b>
      </li>
      <li>
        <b>&#1058;&#1077;&#1093;&#1085;&#1080;&#1082;&#1072; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080;.</b>&#160; &#1063;&#1090;&#1086;&#1073;&#1099; &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1077; &#1087;&#1086;&#1087;&#1072;&#1083;&#1086; &#1074; &#1075;&#1083;&#1072;&#1079;&#1072;. &#1054;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086; &#1101;&#1090;&#1086; &#1082;&#1072;&#1089;&#1072;&#1077;&#1090;&#1089;&#1103; VFL &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074; &#1089; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; <b>&#1073;&#1086;&#1083;&#1077;&#1077; 1 &#1084;&#1042;&#1090; (0&#1076;&#1041;&#1084;)</b>.
      </li>
    </ul>
    <p>
      &#1061;&#1072;&#1088;&#1072;&#1082;&#1090;&#1077;&#1088;&#1080;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;:
