      <a href="#ID_1152328865">&#1050;&#1086;&#1084;&#1087;&#1077;&#1085;&#1089;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1072;&#1103; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1072;</a>&#160; &#160;<a href="#ID_230821641">&#1058;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1077;&#1090;&#1080; (&#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;)</a>&#160;
