    <p>
      <b>&#1056;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088; (OTDR, Optical Time Domain Reflectometer) - </b>&#1087;&#1088;&#1080;&#1073;&#1086;&#1088; &#1076;&#1083;&#1103; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1042;&#1054;&#1051;&#1055;.
    </p>
    <ul>
      <li>
        &#1055;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085; &#1085;&#1072; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;&#1077; &#1086;&#1090;&#1088;&#1072;&#1078;&#1105;&#1085;&#1085;&#1099;&#1093; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1086;&#1074;, &#1080;&#1079;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084;&#1099;&#1093; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1086;&#1084; &#1074; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;. &#1048;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1099; &#1085;&#1072; &#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1075;&#1086; &#1088;&#1072;&#1089;&#1089;&#1077;&#1103;&#1085;&#1080;&#1103; &#1089;&#1074;&#1077;&#1090;&#1072; &#1074; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1077; &#1080; &#1085;&#1072; &#1086;&#1090;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1080; &#1089;&#1074;&#1077;&#1090;&#1072; &#1086;&#1090; &#1089;&#1082;&#1072;&#1095;&#1082;&#1086;&#1074; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1077;&#1083;&#1103; &#1087;&#1088;&#1077;&#1083;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103;. <b>&#1052;&#1077;&#1090;&#1086;&#1076; &#1084;&#1077;&#1085;&#1077;&#1077; &#1090;&#1086;&#1095;&#1085;&#1099;&#1081;</b>, &#1095;&#1077;&#1084; &#1085;&#1077;&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1077; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100; &#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072; &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1086;&#1076;&#1085;&#1086;&#1084; &#1082;&#1086;&#1085;&#1094;&#1077; &#1080; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1103; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;. &#1042;&#1084;&#1077;&#1089;&#1090;&#1077; &#1089; &#1090;&#1077;&#1084;, &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1080;&#1103; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100;, <b>&#1082;&#1072;&#1082;&#1086;&#1081; &#1080;&#1079; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1042;&#1054;&#1051;&#1057; &#1074;&#1085;&#1086;&#1089;&#1080;&#1090; &#1085;&#1072;&#1080;&#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1081; &#1074;&#1082;&#1083;&#1072;&#1076; &#1074; &#1086;&#1073;&#1097;&#1080;&#1077; &#1087;&#1086;&#1090;&#1077;&#1088;&#1080;</b>
      </li>
      <li>
        &#1054;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089; &#1074;&#1074;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1086;&#1090;&#1074;&#1077;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;. &#1069;&#1090;&#1086;&#1090; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089; &#1088;&#1072;&#1089;&#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1091; &#1080; &#1086;&#1089;&#1083;&#1072;&#1073;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1080; &#1089; &#1082;&#1086;&#1101;&#1092;&#1092;&#1080;&#1094;&#1080;&#1077;&#1085;&#1090;&#1086;&#1084; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;. &#1053;&#1077;&#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1095;&#1072;&#1089;&#1090;&#1100; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080; &#1088;&#1072;&#1089;&#1089;&#1077;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1080; &#1074; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1077; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; &#1088;&#1072;&#1089;&#1089;&#1077;&#1103;&#1085;&#1085;&#1086;&#1077; &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1086;&#1090;&#1074;&#1077;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090; &#1085;&#1072; &#1092;&#1086;&#1090;&#1086;&#1076;&#1077;&#1090;&#1077;&#1082;&#1090;&#1086;&#1088; (&#1085;&#1072; &#1090;&#1086;&#1084; &#1078;&#1077; &#1087;&#1086;&#1088;&#1090;&#1091;), &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;, &#1091;&#1089;&#1080;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1085;&#1072; &#1076;&#1080;&#1089;&#1087;&#1083;&#1077;&#1081;
      </li>
      <li>
        <b>&#1044;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; </b>(&#1095;&#1091;&#1074;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100;) <b>35-50 &#1076;&#1041;</b>&#160;(&#1076;&#1072;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1072; &#1076;&#1086; ~ 220 &#1082;&#1084;.). &#1044;&#1086;&#1088;&#1086;&#1075;&#1080;&#1077; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1099; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1090; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086; &#1080; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1080;&#1079;&#1084;&#1077;&#1088;&#1103;&#1090;&#1100; &#1076;&#1083;&#1080;&#1085;&#1085;&#1099;&#1077; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1080;, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1090; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1100; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1103;&#1077;&#1084;&#1099;&#1077; &#1086;&#1090; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1082; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1102; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1077; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;
      </li>
      <li>
        <b>&#1052;&#1077;&#1088;&#1090;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; &#1087;&#1086; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1102;</b>&#160;- &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077; &#1090;&#1072;&#1088;&#1072;&#1089;&#1089;&#1099; (4-10 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;), &#1095;&#1077;&#1084; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;, &#1090;&#1077;&#1084; &#1083;&#1091;&#1095;&#1096;&#1077;
      </li>
      <li>
        <b>&#1052;&#1077;&#1088;&#1090;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; &#1087;&#1086; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103;&#1084;</b>&#160;- &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1084;&#1077;&#1078;&#1076;&#1091; &#1076;&#1074;&#1091;&#1084;&#1103; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103;&#1084;&#1080;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1089;&#1083;&#1080;&#1074;&#1072;&#1083;&#1080;&#1089;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1081; &#1074; &#1086;&#1076;&#1085;&#1086;. 0.8&#1084; - 1&#1084; - &#1093;&#1086;&#1088;&#1086;&#1096;&#1077;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        &#1048;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1085;&#1072; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; &#1089;&#1074;&#1077;&#1090;&#1072; <b>1,31</b>&#160; &#1080;&#1083;&#1080; <b>1,55 &#1084;&#1082;&#1084;</b>
      </li>
      <li>
        &#1055;&#1088;&#1080; &#1087;&#1088;&#1086;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1080; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1081; <b>&#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1084; &#1082;&#1086;&#1085;&#1094;&#1077; &#1083;&#1091;&#1095;&#1096;&#1077; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;</b>&#160;&#1080;&#1079; &#1089;&#1086;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1081; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080;. &#1055;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1092;&#1086;&#1090;&#1086;&#1087;&#1088;&#1080;&#1077;&#1084;&#1085;&#1080;&#1082;&#1080; - &#1086;&#1095;&#1077;&#1085;&#1100; &#1095;&#1091;&#1074;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077;, &#1072; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1080; &#8211; &#1086;&#1095;&#1077;&#1085;&#1100; &#1084;&#1086;&#1097;&#1085;&#1099;&#1077;
      </li>
      <li>
        <b>&#1058;&#1077;&#1093;&#1085;&#1080;&#1082;&#1072; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080;:</b>&#160; &#1047;&#1072;&#1082;&#1088;&#1099;&#1090;&#1100; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1081; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084; &#1074; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1077; &#1079;&#1072;&#1097;&#1080;&#1090;&#1085;&#1099;&#1084; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1082;&#1086;&#1074;&#1099;&#1084; &#1080;&#1083;&#1080; &#1088;&#1077;&#1079;&#1080;&#1085;&#1086;&#1074;&#1099;&#1084; &#1082;&#1086;&#1083;&#1087;&#1072;&#1095;&#1082;&#1086;&#1084;
      </li>
      <li>
        <b>&#1057;&#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077; &#1087;&#1086;&#1088;&#1090;&#1099;</b>&#160;--&gt; <b>&#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;</b>
      </li>
    </ul>
    <p>
      <b>&#1042;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080;:</b>
    </p>
    <ul>
      <li>
        &#1057;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1074; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1080; &#1088;&#1091;&#1095;&#1085;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1072;&#1093;
      </li>
      <li>
        &#1053;&#1072; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1086;&#1084; &#1076;&#1080;&#1089;&#1087;&#1083;&#1077;&#1077; &#1087;&#1088;&#1086;&#1089;&#1084;&#1072;&#1090;&#1088;&#1080;&#1074;&#1072;&#1090;&#1100; &#1080;&#1093;, &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;, &#1089;&#1088;&#1072;&#1079;&#1091; &#1091;&#1079;&#1085;&#1072;&#1074;&#1072;&#1090;&#1100; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084; &#1080;&#1085;&#1090;&#1077;&#1088;&#1077;&#1089;&#1091;&#1102;&#1097;&#1077;&#1084; &#1085;&#1072;&#1089; &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1077;, &#1085;&#1072; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1080; (&#1084;&#1091;&#1092;&#1090;&#1072; &#1080;&#1083;&#1080; &#1082;&#1088;&#1086;&#1089;&#1089;), &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1076;&#1083;&#1080;&#1085;&#1091; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; (&#1074;&#1089;&#1077;&#1081; &#1080;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086;&#1081; &#1085;&#1072;&#1084; &#1095;&#1072;&#1089;&#1090;&#1080;), &#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1085;&#1099; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090;&#1085;&#1099;&#1093; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100; &#1080; &#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1085;&#1099; &#1086;&#1090;&#1088;&#1072;&#1078;&#1105;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072;
      </li>
      <li>
        &#1048;&#1084;&#1077;&#1077;&#1090; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1091;&#1102; &#1092;&#1083;&#1101;&#1096;-&#1087;&#1072;&#1084;&#1103;&#1090;&#1100;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1087;&#1086;&#1088;&#1090; USB &#1076;&#1083;&#1103; &#1092;&#1083;&#1077;&#1096;&#1082;&#1080; &#1080; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1099;&#1081; &#1084;&#1077;&#1085;&#1077;&#1076;&#1078;&#1077;&#1088;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1077;&#1088;&#1077;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;
      </li>
      <li>
        &#1063;&#1072;&#1089;&#1090;&#1086; &#1080;&#1084;&#1077;&#1102;&#1090;&#1089;&#1103; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1090;&#1077;&#1089;&#1090;&#1077;&#1088;&#1072;, &#1101;&#1090;&#1086; &#1086;&#1095;&#1077;&#1085;&#1100; &#1091;&#1076;&#1086;&#1073;&#1085;&#1086; &#1080; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1073;&#1099;&#1074;&#1072;&#1077;&#1090; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;
      </li>
      <li>
        &#1063;&#1072;&#1089;&#1090;&#1086; &#1080;&#1084;&#1077;&#1077;&#1090;&#1089;&#1103; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1088;&#1086;&#1079;&#1077;&#1090;&#1082;&#1072; &#1089; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1086;&#1084; &#1082;&#1088;&#1072;&#1089;&#1085;&#1086;&#1075;&#1086; &#1089;&#1074;&#1077;&#1090;&#1072; (&#1082;&#1072;&#1082; &#1074; &#1083;&#1072;&#1079;&#1077;&#1088;&#1085;&#1086;&#1081; &#1091;&#1082;&#1072;&#1079;&#1082;&#1077;) &#1076;&#1083;&#1103; &#1074;&#1080;&#1079;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1087;&#1088;&#1086;&#1079;&#1074;&#1086;&#1085;&#1082;&#1080; (&#1090;&#1086;&#1095;&#1085;&#1077;&#1077;, &#1087;&#1088;&#1086;&#1089;&#1074;&#1077;&#1090;&#1082;&#1080;) &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1085;&#1072; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103;&#1093; (&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; &#1076;&#1086; 5 &#1082;&#1084;). &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; <b>VFL</b>. &#1055;&#1086;&#1084;&#1086;&#1075;&#1072;&#1077;&#1090; &#1087;&#1088;&#1080; &#1086;&#1090;&#1099;&#1089;&#1082;&#1072;&#1085;&#1080;&#1080; &#171;&#1082;&#1088;&#1077;&#1089;&#1090;&#1086;&#1074;&#187;, &#1080;&#1079;&#1075;&#1080;&#1073;&#1086;&#1074; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1074; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1072;&#1093; &#1080; &#1089;&#1083;&#1086;&#1084;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;, &#1080; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1087;&#1086;&#1084;&#1086;&#1075;&#1072;&#1077;&#1090; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086; &#1085;&#1072;&#1081;&#1090;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1074; &#1087;&#1091;&#1095;&#1082;&#1077;
      </li>
      <li>
        &#1052;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1081; &#1090;&#1077;&#1089;&#1090;&#1077;&#1088; &#1076;&#1083;&#1103; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1099;&#1093; &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074;
      </li>
      <li>
        &#1059;&#1084;&#1077;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1073;&#1077;&#1079; &#1089;&#1077;&#1090;&#1080; &#1079;&#1072; &#1089;&#1095;&#1105;&#1090; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1093; &#1072;&#1082;&#1082;&#1091;&#1084;&#1091;&#1083;&#1103;&#1090;&#1086;&#1088;&#1086;&#1074;
      </li>
      <li>
        &#1055;&#1088;&#1080;&#1083;&#1072;&#1075;&#1072;&#1077;&#1084;&#1086;&#1077; &#1055;&#1054; &#1076;&#1083;&#1103; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1072; &#1091;&#1084;&#1077;&#1077;&#1090; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1075;&#1086;&#1090;&#1086;&#1074;&#1099;&#1081; &#1086;&#1090;&#1095;&#1105;&#1090; &#1086;&#1073; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1080;, &#1089; &#1082;&#1072;&#1088;&#1090;&#1080;&#1085;&#1082;&#1086;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1080; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072;&#1084;&#1080; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;. &#1060;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1074; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1085;&#1085;&#1086;&#1084; &#1074;&#1080;&#1076;&#1077; &#1072;&#1082;&#1090;&#1072; &#1087;&#1088;&#1080;&#1105;&#1084;&#1086;-&#1089;&#1076;&#1072;&#1090;&#1086;&#1095;&#1085;&#1099;&#1093; &#1080;&#1089;&#1087;&#1099;&#1090;&#1072;&#1085;&#1080;&#1081; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;
      </li>
      <li>
        &#1048;&#1085;&#1086;&#1075;&#1076;&#1072; &#1080;&#1084;&#1077;&#1077;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; &#1080; &#1072;&#1082;&#1089;&#1077;&#1089;&#1089;&#1091;&#1072;&#1088;&#1086;&#1074;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1082;&#1086;&#1087;&#1072; &#1089; &#1082;&#1072;&#1084;&#1077;&#1088;&#1086;&#1081; &#1080; &#1087;&#1086;&#1076;&#1089;&#1074;&#1077;&#1090;&#1082;&#1086;&#1081; &#1076;&#1083;&#1103; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1103; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1090;&#1086;&#1088;&#1094;&#1086;&#1074; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1086;&#1074; &#1091; &#1087;&#1072;&#1090;&#1095;-&#1082;&#1086;&#1088;&#1076;&#1086;&#1074; &#1080; &#1087;&#1080;&#1075;-&#1090;&#1077;&#1081;&#1083;&#1086;&#1074;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1087;&#1083;&#1072;&#1090;&#1092;&#1086;&#1088;&#1084;&#1072; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;&#1085;&#1072;&#1103;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1074; &#171;&#1082;&#1086;&#1088;&#1079;&#1080;&#1085;&#1091;&#187; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1072;&#1084; &#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1091;&#1102;&#1090;&#1089;&#1103;: &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1072; &#1080; &#1082;&#1072;&#1082;&#1086;&#1081;-&#1085;&#1080;&#1073;&#1091;&#1076;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1094;&#1080;&#1092;&#1088;&#1086;&#1074;&#1099;&#1093; &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074;.
      </li>
    </ul>
