  <body>
    <p>
      <a href="#ID_1004884906">&#1055;&#1086;&#1090;&#1077;&#1088;&#1080; &#1074; &#1054;&#1042;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1056;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072;</b>&#160; - &#1075;&#1088;&#1072;&#1092;&#1080;&#1082; (&#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1086;&#1073; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1085;&#1086;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1077;) &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103; (&#1086;&#1089;&#1100; &#1086;&#1088;&#1076;&#1080;&#1085;&#1072;&#1090;) &#1086;&#1090; &#1076;&#1083;&#1080;&#1085;&#1099; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; (&#1086;&#1089;&#1100; &#1072;&#1073;&#1089;&#1094;&#1080;&#1089;&#1089;).
    </p>
    <ul>
      <li>
        &#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1080;&#1081; &#1092;&#1072;&#1081;&#1083;&#1080;&#1082; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; <b>.sor</b>&#160; (&#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1085;&#1089;&#1090;&#1074;&#1086; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;), <b>.trc </b>(&#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1099; &#1092;&#1080;&#1088;&#1084;&#1099; EXFO)&#160;&#1080;&#1083;&#1080; &#1074; &#1082;&#1072;&#1082;&#1086;&#1084;-&#1090;&#1086; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;. &#1045;&#1105; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1100; &#1082;&#1072;&#1082; &#1085;&#1072; &#1089;&#1072;&#1084;&#1086;&#1084; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1077;, &#1090;&#1072;&#1082; &#1080; &#1085;&#1072; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1077; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1081; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1077; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;,&#160;&#160;&#1055;&#1054; &#1086;&#1090; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1077;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; Yokogawa)
      </li>
    </ul>
    <p>
      <b>&#1057;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103;</b>
    </p>
    <ol>
      <li>
        &#1053;&#1072;&#1095;&#1072;&#1083;&#1086; &#1083;&#1080;&#1085;&#1080;&#1080; (&#1074;&#1093;&#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;) - &#1087;&#1080;&#1082; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1075;&#1086; &#1086;&#1090;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1086;&#1090; &#1074;&#1093;&#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1072; &#1080; &#1096;&#1083;&#1077;&#1081;&#1092; &#1087;&#1086;&#1089;&#1083;&#1077; &#1085;&#1077;&#1075;&#1086; - <b>&#1084;&#1077;&#1088;&#1090;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072;</b>

        <ul>
          <li>
            &#1050;&#1086;&#1089;&#1074;&#1077;&#1085;&#1085;&#1086; &#1091;&#1079;&#1085;&#1072;&#1090;&#1100; &#1086; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1080; &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1084;&#1086;&#1078;&#1085;&#1086;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; <b>&#1082;&#1086;&#1084;&#1087;&#1077;&#1085;&#1089;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1091;&#1102; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1091;</b>&#160;&#1089; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;&#1084;
          </li>
          <li>
            &#1045;&#1089;&#1083;&#1080; &#1084;&#1105;&#1088;&#1090;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; &#1089;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1096;&#1080;&#1088;&#1086;&#1082;&#1072;&#1103; (&#1080; &#1087;&#1088;&#1086;&#1095;&#1080;&#1077; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103; &#1090;&#1086;&#1078;&#1077; &#1096;&#1080;&#1088;&#1086;&#1082;&#1080;&#1077;) &#8212; &#1079;&#1085;&#1072;&#1095;&#1080;&#1090;, &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085; <b>&#1089;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1076;&#1083;&#1080;&#1085;&#1085;&#1099;&#1081; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089; &#1076;&#1083;&#1103; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;</b>, &#1076;&#1083;&#1080;&#1085;&#1072; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1072; &#1089;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1074;&#1077;&#1083;&#1080;&#1082;&#1072; &#1087;&#1086; &#1089;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1102; &#1089; &#1076;&#1083;&#1080;&#1085;&#1086;&#1081; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1072;. &#1053;&#1091;&#1078;&#1085;&#1086; <b>&#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089; &#1087;&#1086;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;</b>&#160;&#1080; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;.
          </li>
          <li>
            &#1045;&#1089;&#1083;&#1080; &#1084;&#1105;&#1088;&#1090;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072; &#1085;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1096;&#1080;&#1088;&#1086;&#1082;&#1072;&#1103;, &#1085;&#1086; &#1080; <b>&#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; &#1090;&#1088;&#1072;&#1089;&#1089;&#1091; &#1087;&#1083;&#1072;&#1074;&#1085;&#1086;</b>, &#1076;&#1072; &#1077;&#1097;&#1105; &#1080; &#1087;&#1086;&#1088;&#1086;&#1081; &#1085;&#1077;&#1088;&#1086;&#1074;&#1085;&#1086; &#1089; &#1096;&#1091;&#1084;&#1072;&#1084;&#1080; &#8212; &#1101;&#1090;&#1086; &#1074;&#1077;&#1088;&#1085;&#1099;&#1081; &#1087;&#1088;&#1080;&#1079;&#1085;&#1072;&#1082; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086; &#1095;&#1090;&#1086;-&#1090;&#1086; &#1085;&#1077; &#1074; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1074; &#1089;&#1072;&#1084;&#1086;&#1084; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;: &#1080;&#1083;&#1080; &#1082;&#1072;&#1082;&#1086;&#1081;-&#1090;&#1086; &#1080;&#1079; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; (&#1085;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1077; &#1080;&#1083;&#1080; &#1085;&#1072; &#1082;&#1088;&#1086;&#1089;&#1089;&#1077;) &#1075;&#1088;&#1103;&#1079;&#1085;&#1099;&#1081;, &#1080;&#1083;&#1080; &#1088;&#1086;&#1079;&#1077;&#1090;&#1082;&#1072; &#1085;&#1072; &#1082;&#1088;&#1086;&#1089;&#1089;&#1077; &#1080;&#1083;&#1080; &#1085;&#1072; &#1089;&#1072;&#1084;&#1086;&#1084; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1077; &#1089;&#1083;&#1086;&#1084;&#1072;&#1085;&#1072; (&#1074; &#1101;&#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1088;&#1080; &#1084;&#1085;&#1086;&#1075;&#1086;&#1082;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080;/&#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1080;&#1083;&#1100;&#1085;&#1086; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1074;&#1087;&#1083;&#1086;&#1090;&#1100; &#1076;&#1086; &#1087;&#1086;&#1083;&#1085;&#1086;&#1075;&#1086; &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1080;&#1103; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;), &#1080;&#1083;&#1080; &#1087;&#1072;&#1090;&#1095;-&#1082;&#1086;&#1088;&#1076;/&#1087;&#1080;&#1075;&#1090;&#1077;&#1081;&#1083; &#1087;&#1083;&#1086;&#1093;&#1086;&#1081;, &#1080;&#1083;&#1080; &#1089;&#1074;&#1072;&#1088;&#1082;&#1072; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1082;&#1088;&#1086;&#1089;&#1089;&#1072; &#1087;&#1083;&#1086;&#1093;&#1072;&#1103;. &#1048;&#1083;&#1080;, &#1089;&#1072;&#1084;&#1099;&#1081; &#1088;&#1077;&#1076;&#1082;&#1080;&#1081; &#1080; &#1089;&#1072;&#1084;&#1099;&#1081; &#1085;&#1077;&#1087;&#1088;&#1080;&#1103;&#1090;&#1085;&#1099;&#1081; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;, &#1087;&#1088;&#1103;&#1084;&#1086; &#1086;&#1082;&#1086;&#1083;&#1086; &#1082;&#1088;&#1086;&#1089;&#1089;&#1072; (&#1076;&#1077;&#1089;&#1103;&#1090;&#1082;&#1080; &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;) &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;.
          </li>
        </ul>
      </li>
      <li>
        <b>&#1056;&#1072;&#1073;&#1086;&#1095;&#1080;&#1081; &#1091;&#1095;&#1072;&#1089;&#1090;&#1086;&#1082;, &#1090;&#1088;&#1072;&#1089;&#1089;&#1072;</b>&#160;&#160;- &#1074; &#1080;&#1076;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; (&#1084;&#1099; &#1080;&#1079;&#1084;&#1077;&#1088;&#1103;&#1077;&#1084; &#1094;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1091;&#1089;&#1086;&#1082; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, &#1073;&#1077;&#1079; &#1089;&#1074;&#1072;&#1088;&#1086;&#1082; &#1080; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081;) &#1101;&#1090;&#1086; &#1087;&#1088;&#1103;&#1084;&#1072;&#1103; &#1083;&#1080;&#1085;&#1080;&#1103;. &#1054;&#1085;&#1072; &#1080;&#1084;&#1077;&#1077;&#1090; &#1085;&#1072;&#1082;&#1083;&#1086;&#1085; (&#1087;&#1086;&#1089;&#1090;&#1077;&#1087;&#1077;&#1085;&#1085;&#1086; &#1088;&#1072;&#1074;&#1085;&#1086;&#1084;&#1077;&#1088;&#1085;&#1086; &#1089;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090;), &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1074;&#1085;&#1086;&#1089;&#1080;&#1090; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1077; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; (&#1074; &#171;&#1086;&#1082;&#1085;&#1072;&#1093; &#1087;&#1088;&#1086;&#1079;&#1088;&#1072;&#1095;&#1085;&#1086;&#1089;&#1090;&#1080;&#187; &#1086;&#1076;&#1085;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1075;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1101;&#1090;&#1086; &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; 0,22 &#1076;&#1041;/&#1082;&#1084; &#1085;&#1072; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; 1550 &#1085;&#1084; &#1080; &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; 0,36 &#1076;&#1041;/&#1082;&#1084; &#1087;&#1088;&#1080; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; 1310 &#1085;&#1084;)
      </li>
      <li>
        <b>&#1050;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1085;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;</b>&#160;- &#1087;&#1080;&#1082;-&#1089;&#1087;&#1072;&#1076; (&#1092;&#1088;&#1077;&#1085;&#1077;&#1083;&#1077;&#1074;&#1089;&#1082;&#1086;&#1077; &#1086;&#1090;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; (&#1082;&#1086;&#1083;-&#1074;&#1086; &#1089;&#1074;&#1077;&#1090;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1086;&#1090;&#1088;&#1072;&#1079;&#1080;&#1083;&#1086;&#1089;&#1100; &#1085;&#1072;&#1079;&#1072;&#1076; &#1082; &#1080;&#1079;&#1083;&#1091;&#1095;&#1072;&#1090;&#1077;&#1083;&#1102;) - -38 &#1076;&#1041;, &#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080; (&#1074;&#1085;&#1086;&#1089;&#1080;&#1084;&#1099;&#1077; &#1087;&#1086;&#1090;&#1077;&#1088;&#1080;). FC &#1089; &#1087;&#1086;&#1083;&#1080;&#1088;&#1086;&#1074;&#1082;&#1086;&#1081; &#1092;&#1077;&#1088;&#1091;&#1083;&#1099; - &#1085;&#1086;&#1088;&#1084;&#1072; -45&#1076;&#1041;. &#1063;&#1077;&#1084; &#1086;&#1090;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;, &#1090;&#1077;&#1084; &#1083;&#1091;&#1095;&#1096;&#1077; &#1076;&#1083;&#1103; &#1083;&#1080;&#1085;&#1080;&#1080;
      </li>
      <li>
        <b>&#1057;&#1074;&#1072;&#1088;&#1082;&#1072;</b>

        <ul>
          <li>
            &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1085;&#1077; &#1074;&#1080;&#1076;&#1085;&#1072;
          </li>
          <li>
            &#1089;&#1090;&#1091;&#1087;&#1077;&#1085;&#1100;&#1082;&#1072; &#1074;&#1085;&#1080;&#1079; (&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080;) &#1085;&#1072; &#1086;&#1073;&#1077;&#1080;&#1093; &#1076;&#1083;&#1080;&#1085;&#1072;&#1093; &#1074;&#1086;&#1083;&#1085; (1310 &#1085;&#1084;, 1550 &#1085;&#1084;) - &#1095;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1089;&#1090;&#1091;&#1087;&#1077;&#1085;&#1100;&#1082;&#1072;, &#1090;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1085;&#1072; &#1085;&#1077;&#1081; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1080; &#1090;&#1077;&#1084; &#1089;&#1074;&#1072;&#1088;&#1082;&#1072; &#1093;&#1091;&#1078;&#1077;
          </li>
          <li>
            &#1089;&#1090;&#1091;&#1087;&#1077;&#1085;&#1100;&#1082;&#1072; &#1074;&#1074;&#1077;&#1088;&#1093; (Gainer) -&#160;&#160;&#1082;&#1086;&#1075;&#1076;&#1072; &#1089;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1074;&#1072; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1089; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084;&#1080; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084;&#1080; &#1087;&#1088;&#1077;&#1083;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103; &#1080; &#1088;&#1072;&#1079;&#1085;&#1086;&#1081; &#1076;&#1080;&#1089;&#1087;&#1077;&#1088;&#1089;&#1080;&#1077;&#1081;, &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1101;&#1090;&#1086; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086;&#1077; SM &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1080; &#1082;&#1072;&#1082;&#1072;&#1103;-&#1085;&#1080;&#1073;&#1091;&#1076;&#1100; &#171;&#1089;&#1084;&#1077;&#1097;&#1105;&#1085;&#1082;&#1072;&#187; (DS)
          </li>
          <li>
            &#1077;&#1089;&#1083;&#1080; &#1089;&#1074;&#1072;&#1088;&#1077;&#1085;&#1099; &#1082;&#1072;&#1073;&#1077;&#1083;&#1080; &#1089; &#1088;&#1072;&#1079;&#1085;&#1086;&#1081; &#1076;&#1080;&#1089;&#1087;&#1077;&#1088;&#1089;&#1080;&#1077;&#1081; &#1080; &#1074;&#1086;&#1086;&#1073;&#1097;&#1077; <b>&#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1077;&#1081;</b>, &#1090;&#1086; &#1085;&#1077; &#1092;&#1072;&#1082;&#1090;, &#1095;&#1090;&#1086; &#1087;&#1083;&#1086;&#1093;&#1072;&#1103; &#1089;&#1074;&#1072;&#1088;&#1082;&#1072; &#1085;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1077; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1083;&#1086;&#1093;&#1072;&#1103;! &#1053;&#1072;&#1076;&#1086; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099; &#1080; <b>&#1074;&#1079;&#1103;&#1090;&#1100; &#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;</b>
          </li>
        </ul>
      </li>
      <li>
        <b>&#1052;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; (&#1082;&#1088;&#1086;&#1089;&#1089; &#1080;&#1083;&#1080; fibrlok) &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;</b>&#160; - &#1089;&#1080;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1080;&#1082; (&#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1077; &#1086;&#1090;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;). &#1059;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1080;&#1082;&#1072; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1072;&#1076;&#1072;&#1077;&#1090;, &#1087;&#1088;&#1080;&#1095;&#1105;&#1084; &#1089;&#1080;&#1083;&#1100;&#1085;&#1077;&#1077;, &#1095;&#1077;&#1084; &#1085;&#1072; &#1089;&#1074;&#1072;&#1088;&#1085;&#1086;&#1084; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1080;
      </li>
      <li>
        <b>&#1047;&#1072;&#1075;&#1080;&#1073; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; (&#1084;&#1072;&#1082;&#1088;&#1086;&#1080;&#1079;&#1075;&#1080;&#1073;)</b>&#160;- &#1074;&#1099;&#1075;&#1083;&#1103;&#1076;&#1080;&#1090; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1090;&#1072;&#1082; &#1078;&#1077;, &#1082;&#1072;&#1082; &#1089;&#1074;&#1072;&#1088;&#1082;&#1072;, &#1085;&#1086; &#1085;&#1072; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1076;&#1083;&#1080;&#1085;&#1072;&#1093; &#1074;&#1086;&#1083;&#1085; &#1088;&#1072;&#1079;&#1085;&#1099;&#1081; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090; (&#1085;&#1072; 1310 &#1085;&#1084; - &#1089;&#1083;&#1072;&#1073;&#1086; &#1074;&#1080;&#1076;&#1077;&#1085;, &#1072; &#1085;&#1072; 1550 &#1085;&#1084; - &#1084;&#1086;&#1078;&#1077;&#1090; &#1076;&#1072;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1077;&#1094;&#1080;&#1073;&#1077;&#1083;)
      </li>
      <li>
        <b>&#1058;&#1088;&#1077;&#1097;&#1080;&#1085;&#1072; &#1074; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1077;</b>&#160; (&#1077;&#1097;&#1105; &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1096;&#1077;&#1076;&#1096;&#1072;&#1103; &#1074; &#1086;&#1073;&#1088;&#1099;&#1074;) - &#1087;&#1086;&#1093;&#1086;&#1078;&#1077; &#1085;&#1072; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;, &#1085;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1082;&#1072;&#1082; &#1089;&#1083;&#1072;&#1073;&#1077;&#1077; (&#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1080;&#1081; &#1087;&#1080;&#1082;), &#1090;&#1072;&#1082; &#1080; &#1085;&#1072;&#1084;&#1085;&#1086;&#1075;&#1086; &#1089;&#1080;&#1083;&#1100;&#1085;&#1077;&#1077; (&#1087;&#1080;&#1082; &#1087;&#1086;&#1095;&#1090;&#1080; &#1082;&#1072;&#1082; &#1082;&#1086;&#1085;&#1077;&#1094; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;, &#1079;&#1072; &#1101;&#1090;&#1080;&#1084; &#1086;&#1075;&#1088;&#1086;&#1084;&#1085;&#1099;&#1084; &#1087;&#1080;&#1082;&#1086;&#1084; &#1085;&#1072; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1096;&#1091;&#1084;&#1086;&#1074; &#1082;&#1086;&#1077;-&#1082;&#1072;&#1082; &#1074;&#1080;&#1076;&#1085;&#1086; &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1078;&#1077;&#1085;&#1080;&#1077; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;).
      </li>
      <li>
        <b>&#1054;&#1073;&#1088;&#1099;&#1074;, &#1050;&#1086;&#1085;&#1077;&#1094; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;</b>&#160;- &#1087;&#1080;&#1082; &gt; <b>&#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1100; &#1096;&#1091;&#1084;&#1086;&#1074;</b>. &#160;&#1048;&#1085;&#1086;&#1075;&#1076;&#1072; &#1089;&#1088;&#1077;&#1076;&#1080; &#1096;&#1091;&#1084;&#1086;&#1074; &#1086;&#1090;&#1088;&#1072;&#1078;&#1105;&#1085;&#1085;&#1099;&#1081; <b>&#1092;&#1072;&#1085;&#1090;&#1086;&#1084;&#1085;&#1099;&#1081; &#1087;&#1080;&#1082;</b>
