    </ol>
    <p>
      <b>1. &#1052;&#1072;&#1089;&#1096;&#1090;&#1072;&#1073; &#1087;&#1086; &#1076;&#1083;&#1080;&#1085;&#1077;</b>, &#1080;&#1083;&#1080; <b>&#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077;</b>, &#1080;&#1083;&#1080; <b>&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;/&#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103;</b>. &#1042;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1090;&#1091;&#1087;&#1077;&#1085;&#1095;&#1072;&#1090;&#1086;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;: 300 &#1084;, 500 &#1084;, 1 &#1082;&#1084;, 2 &#1082;&#1084;, 5 &#1082;&#1084;, 10 &#1082;&#1084;, 25 &#1082;&#1084;, 50 &#1082;&#1084;, 100 &#1082;&#1084; &#1080; &#1090;.&#1076;. &#1063;&#1077;&#1084; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1077; &#1084;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1077; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;, &#1090;&#1077;&#1084; &#1086;&#1085; &#1082;&#1088;&#1091;&#1095;&#1077;. &#1042;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; <b>&#1095;&#1091;&#1090;&#1100; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;, &#1095;&#1077;&#1084; &#1074; 2 &#1088;&#1072;&#1079;&#1072; &#1076;&#1083;&#1080;&#1085;&#1085;&#1077;&#1077; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;</b>. &#1055;&#1086;&#1095;&#1077;&#1084;&#1091; &#1074; 2 &#1088;&#1072;&#1079;&#1072; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;? &#1063;&#1090;&#1086;&#1073;&#1099; &#1084;&#1099; &#1084;&#1086;&#1075;&#1083;&#1080; &#1089;&#1088;&#1077;&#1076;&#1080; &#1096;&#1091;&#1084;&#1086;&#1074; &#1087;&#1086;&#1089;&#1083;&#1077; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1091;&#1074;&#1080;&#1076;&#1077;&#1090;&#1100; &#1087;&#1080;&#1082; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1075;&#1086; &#1086;&#1090;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;. &#1041;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1081; &#1087;&#1086;&#1083;&#1100;&#1079;&#1099; &#1086;&#1085; &#1085;&#1077; &#1085;&#1077;&#1089;&#1105;&#1090;, &#1085;&#1086; &#1074;&#1089;&#1105; &#1078;&#1077; &#1083;&#1091;&#1095;&#1096;&#1077; &#1077;&#1075;&#1086; &#1091;&#1074;&#1080;&#1076;&#1077;&#1090;&#1100;: &#1074;&#1076;&#1088;&#1091;&#1075; &#1091; &#1085;&#1072;&#1089; &#1083;&#1086;&#1087;&#1085;&#1091;&#1074;&#1096;&#1077;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1083;&#1077;&#1075;&#1082;&#1086; &#1087;&#1088;&#1080;&#1085;&#1103;&#1090;&#1100; &#1079;&#1072; &#1082;&#1086;&#1085;&#1077;&#1094; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;, &#1072; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083; &#1087;&#1086; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1102; &#1089; &#1079;&#1072;&#1087;&#1072;&#1089;&#1086;&#1084;, &#1084;&#1099;, &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;, &#1089;&#1084;&#1086;&#1078;&#1077;&#1084; &#1091;&#1074;&#1080;&#1076;&#1077;&#1090;&#1100;, &#1095;&#1090;&#1086; &#1101;&#1090;&#1086; &#1077;&#1097;&#1105; &#1085;&#1077; &#1082;&#1086;&#1085;&#1077;&#1094; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1080; &#1089;&#1082;&#1074;&#1086;&#1079;&#1100; &#1096;&#1091;&#1084;&#1099; &#1087;&#1088;&#1086;&#1075;&#1083;&#1103;&#1076;&#1099;&#1074;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1078;&#1077;&#1085;&#1080;&#1077;.
    </p>
    <p>
      <b>&#1042;&#1072;&#1078;&#1085;&#1086;:</b>&#160;&#1095;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1086; &#1101;&#1090;&#1086; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; (&#1090;.&#1077;. &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1081;), &#1090;&#1077;&#1084; &#1096;&#1080;&#1088;&#1077; &#1085;&#1072;&#1076;&#1086; &#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089; &#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; (&#1082;&#1086;&#1083;-&#1074;&#1086; &#1091;&#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1085;&#1080;&#1081;): &#1074;&#1077;&#1076;&#1100; &#1089;&#1074;&#1077;&#1090; &#1076;&#1086;&#1083;&#1100;&#1096;&#1077; &#1087;&#1088;&#1086;&#1083;&#1077;&#1090;&#1072;&#1077;&#1090; &#1076;&#1083;&#1080;&#1085;&#1085;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;, &#1080; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1091; &#1090;&#1088;&#1091;&#1076;&#1085;&#1077;&#1077; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;. &#1048;&#1085;&#1086;&#1075;&#1076;&#1072; &#1087;&#1086;&#1083;&#1095;&#1072;&#1089;&#1072; &#1085;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; - &#1077;&#1089;&#1083;&#1080; &#1090;&#1088;&#1072;&#1089;&#1089;&#1072; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; 50 &#1082;&#1084;.
    </p>
    <p>
      <b>2. &#1055;&#1088;&#1086;&#1076;&#1086;&#1083;&#1078;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1072;.</b>&#160;&#1057;&#1074;&#1103;&#1079;&#1072;&#1085;&#1072; &#1089; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1084; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077;&#1084; (&#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#8212; &#1096;&#1080;&#1088;&#1077; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;), &#1085;&#1086; &#1087;&#1088;&#1080; &#1085;&#1072;&#1076;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1080; &#1077;&#1105; &#1084;&#1086;&#1078;&#1085;&#1086; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1085;&#1077;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086; &#1086;&#1090; &#1076;&#1083;&#1080;&#1085;&#1099;. &#1058;&#1080;&#1087;&#1080;&#1095;&#1085;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#8212; &#1086;&#1090; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1085;&#1072;&#1085;&#1086;&#1089;&#1077;&#1082;&#1091;&#1085;&#1076; &#1076;&#1086; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1077;&#1082;&#1091;&#1085;&#1076;. &#1044;&#1083;&#1103; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1086;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#8212; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1080;&#1081; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;. &#1044;&#1083;&#1103; &#1076;&#1083;&#1080;&#1085;&#1085;&#1086;&#1081; &#8212; &#1076;&#1083;&#1080;&#1085;&#1085;&#1099;&#1081;. &#1057;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1080;&#1081; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089; &#1085;&#1072; &#1076;&#1083;&#1080;&#1085;&#1085;&#1086;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1077; &#1076;&#1072;&#1089;&#1090; &#1086;&#1090;&#1083;&#1080;&#1095;&#1085;&#1091;&#1102; &#1076;&#1077;&#1090;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102; &#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077;, &#1085;&#1086; &#1082;&#1086;&#1085;&#1077;&#1094; &#1087;&#1086;&#1090;&#1086;&#1085;&#1077;&#1090; &#1074; &#1096;&#1091;&#1084;&#1072;&#1093;. &#1057;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1076;&#1083;&#1080;&#1085;&#1085;&#1099;&#1081; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089; &#1085;&#1072; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1086;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1077; &#1087;&#1088;&#1080;&#1074;&#1077;&#1076;&#1105;&#1090; &#1082; &#1087;&#1086;&#1090;&#1077;&#1088;&#1077; &#1076;&#1077;&#1090;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1080; &#1088;&#1072;&#1089;&#1090;&#1103;&#1075;&#1080;&#1074;&#1072;&#1085;&#1080;&#1102;, &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1079;&#1072;&#1085;&#1080;&#1102; &#1074;&#1089;&#1077;&#1093; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1087;&#1086; &#1075;&#1086;&#1088;&#1080;&#1079;&#1086;&#1085;&#1090;&#1072;&#1083;&#1080;.
    </p>
    <p>
      <b>3. &#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1086;&#1074;/&#1091;&#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1085;&#1080;&#1081;</b>&#160;(&#1080;&#1083;&#1080; <b>&#1074;&#1088;&#1077;&#1084;&#1103; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103;</b>). &#1044;&#1077;&#1083;&#1086; &#1074; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1086;&#1076;&#1080;&#1085;-&#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086;&#1089;&#1083;&#1072;&#1085;&#1085;&#1099;&#1081; &#1074; &#1083;&#1080;&#1085;&#1080;&#1102; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089; &#1085;&#1072;&#1084; &#1085;&#1077; &#1076;&#1072;&#1089;&#1090; &#1087;&#1086;&#1095;&#1090;&#1080; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086;, &#1082;&#1088;&#1086;&#1084;&#1077; &#1096;&#1091;&#1084;&#1086;&#1074;. &#1044;&#1083;&#1103; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1093;&#1086;&#1088;&#1086;&#1096;&#1077;&#1081; &#1082;&#1072;&#1088;&#1090;&#1080;&#1085;&#1082;&#1080;-&#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1080; &#1091;&#1089;&#1090;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1099;&#1093; &#1092;&#1083;&#1091;&#1082;&#1090;&#1091;&#1072;&#1094;&#1080;&#1081; &#1088;&#1101;&#1083;&#1077;&#1077;&#1074;&#1089;&#1082;&#1086;&#1075;&#1086; &#1088;&#1072;&#1089;&#1089;&#1077;&#1103;&#1085;&#1080;&#1103; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1074;&#1077;&#1089;&#1090;&#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1086;&#1090;&#1077;&#1085; &#1080;&#1083;&#1080; &#1090;&#1099;&#1089;&#1103;&#1095; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1081;, &#1072; &#1079;&#1072;&#1090;&#1077;&#1084; &#1074;&#1079;&#1103;&#1090;&#1100; &#1091;&#1089;&#1088;&#1077;&#1076;&#1085;&#1105;&#1085;&#1085;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;. &#1058;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1095;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1084;&#1099; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1084; &#1082;&#1086;&#1083;-&#1074;&#1086; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1084;&#1099;&#1093; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1086;&#1074;, &#1090;&#1077;&#1084; &#1095;&#1105;&#1090;&#1095;&#1077; &#1080; &#1088;&#1086;&#1074;&#1085;&#1077;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1072;&#1096;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; (&#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103;, &#1087;&#1086; &#1089;&#1091;&#1090;&#1080;, &#1080; &#1077;&#1089;&#1090;&#1100; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090; &#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1072;&#1094;&#1080;&#1080; &#1089;&#1086;&#1090;&#1077;&#1085; &#1080; &#1090;&#1099;&#1089;&#1103;&#1095; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1081;).
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1090;&#1088;&#1072;&#1089;&#1089;&#1072; &#1076;&#1083;&#1080;&#1085;&#1085;&#1072;&#1103;, &#1073;&#1083;&#1080;&#1079;&#1082;&#1072;&#1103; &#1082; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1091; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1077;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1072;, &#1080; &#1082;&#1086;&#1085;&#1077;&#1094; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1079;&#1072;&#1096;&#1091;&#1084;&#1083;&#1105;&#1085;, &#1090;&#1086; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1084;&#1085;&#1086;&#1075;&#1086; &#1091;&#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1085;&#1080;&#1081; (&#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1072; 10000 &#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;) &#1080;&#1083;&#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; (&#1084;&#1080;&#1085;&#1091;&#1090; 5-10), &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1076;&#1086;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;. &#1045;&#1089;&#1083;&#1080; &#1078;&#1077; &#1084;&#1099; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1082;&#1091;&#1089;&#1086;&#1082; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1074; 300, &#1090;&#1086; &#1090;&#1091;&#1090; &#1089;&#1091;&#1087;&#1077;&#1088;-&#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1085;&#1080;&#1082;&#1086;&#1084;&#1091; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086;, &#1093;&#1074;&#1072;&#1090;&#1080;&#1090; &#1080; 1000 &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1081; (&#1080;&#1083;&#1080; 10-30 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;). &#1050;&#1089;&#1090;&#1072;&#1090;&#1080;, &#1074;&#1086; &#1084;&#1085;&#1086;&#1075;&#1080;&#1093; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1072;&#1093; &#1085;&#1077;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1086;&#1074;, &#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1074; &#1084;&#1080;&#1085;&#1091;&#1090;&#1072;&#1093;/&#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1072;&#1093;.
    </p>
    <p>
      <b>4. &#1050;&#1086;&#1101;&#1092;&#1092;&#1080;&#1094;&#1080;&#1077;&#1085;&#1090; &#1087;&#1088;&#1077;&#1083;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103;</b>, &#1080;&#1083;&#1080; <b>&#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1086;&#1081; &#1080;&#1085;&#1076;&#1077;&#1082;&#1089;</b>. &#1069;&#1090;&#1086;&#1090; &#1082;&#1086;&#1101;&#1092;&#1092;&#1080;&#1094;&#1080;&#1077;&#1085;&#1090; &#1074;&#1083;&#1080;&#1103;&#1077;&#1090; &#1085;&#1072; &#1088;&#1072;&#1089;&#1090;&#1103;&#1075;&#1080;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1085;&#1080;&#1084;&#1072;&#1077;&#1084;&#1086;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1087;&#1086; &#1075;&#1086;&#1088;&#1080;&#1079;&#1086;&#1085;&#1090;&#1072;&#1083;&#1080; (&#1085;&#1077; &#1087;&#1091;&#1090;&#1072;&#1090;&#1100; &#1089; &#1079;&#1091;&#1084;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1091;&#1078;&#1077; &#1075;&#1086;&#1090;&#1086;&#1074;&#1086;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1087;&#1088;&#1080; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;!). &#1060;&#1080;&#1079;&#1080;&#1082;&#1072; &#1074; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1074; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;&#1093; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1086;&#1073;&#1099;&#1095;&#1085;&#1086;&#1077; &#1080; &#171;&#1089;&#1084;&#1077;&#1097;&#1105;&#1085;&#1082;&#1072;&#187;) &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1089;&#1074;&#1077;&#1090;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103;. &#1042; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1077; &#1077;&#1089;&#1083;&#1080; &#1084;&#1099; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1084; &#1090;&#1088;&#1072;&#1089;&#1089;&#1091; &#1089; &#1085;&#1077;&#1074;&#1077;&#1088;&#1085;&#1099;&#1084; &#1082;&#1086;&#1101;&#1092;&#1092;&#1080;&#1094;&#1080;&#1077;&#1085;&#1090;&#1086;&#1084; &#1087;&#1088;&#1077;&#1083;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103;, &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#171;&#1089;&#1078;&#1072;&#1090;&#1086;&#1081;&#187; &#1080;&#1083;&#1080; &#171;&#1088;&#1072;&#1089;&#1090;&#1103;&#1085;&#1091;&#1090;&#1086;&#1081;&#187; &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1083;&#1080;&#1085;&#1077;&#1081;&#1082;&#1080; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1081;. &#1069;&#1090;&#1086; &#1075;&#1088;&#1086;&#1079;&#1080;&#1090; &#1090;&#1077;&#1084;, &#1095;&#1090;&#1086; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1072;&#1074;&#1072;&#1088;&#1080;&#1080; &#1085;&#1072; &#1076;&#1083;&#1080;&#1085;&#1085;&#1086;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1077; &#1084;&#1099; &#1084;&#1086;&#1078;&#1077;&#1084; &#1087;&#1086;&#1089;&#1083;&#1072;&#1090;&#1100; &#1073;&#1088;&#1080;&#1075;&#1072;&#1076;&#1091; &#1091;&#1089;&#1090;&#1088;&#1072;&#1085;&#1103;&#1090;&#1100; &#1072;&#1074;&#1072;&#1088;&#1080;&#1102; &#1085;&#1077; &#1089;&#1086;&#1074;&#1089;&#1077;&#1084; &#1090;&#1091;&#1076;&#1072;.
    </p>
    <p>
      &#1044;&#1072;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1101;&#1092;&#1092;&#1080;&#1094;&#1080;&#1077;&#1085;&#1090; &#1087;&#1088;&#1077;&#1083;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1074;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086;&#1084; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1080; <b>&#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1087;&#1072;&#1089;&#1087;&#1086;&#1088;&#1090;&#1077; &#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;</b>. &#1058;&#1080;&#1087;&#1080;&#1095;&#1085;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#8212; 1,46800, &#1080;&#1083;&#1080; &#1090;&#1072;&#1084; 1,46820.
    </p>
    <p>
      &#1061;&#1086;&#1090;&#1103; <b>&#1076;&#1083;&#1103; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1090;&#1088;&#1072;&#1089;&#1089;</b>, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, FTTB, &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1101;&#1090;&#1086;&#1090; &#1082;&#1086;&#1101;&#1092;&#1092;&#1080;&#1094;&#1080;&#1077;&#1085;&#1090; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1077; &#1086;&#1090; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1089;&#1084;&#1077;&#1097;&#1105;&#1085;&#1082;&#1080; &#1085;&#1072; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1080; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;, &#1080; &#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1095;&#1090;&#1086;-&#1090;&#1086; &#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1077;. &#1042; &#1101;&#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072; &#1074; &#1087;&#1083;&#1102;&#1089;-&#1084;&#1080;&#1085;&#1091;&#1089; &#1087;&#1086;&#1083;&#1084;&#1077;&#1090;&#1088;&#1072; &#1085;&#1077;&#1082;&#1088;&#1080;&#1090;&#1080;&#1095;&#1085;&#1072;, &#1072; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1086; &#1101;&#1090;&#1086;&#1090; &#1082;&#1086;&#1101;&#1092;&#1092;&#1080;&#1094;&#1080;&#1077;&#1085;&#1090; &#1085;&#1077;&#1091;&#1076;&#1086;&#1073;&#1085;&#1086;. &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; <b>&#1085;&#1072; &#1076;&#1083;&#1080;&#1085;&#1085;&#1099;&#1093; &#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1103;&#1093;</b>&#160; &#1101;&#1090;&#1086;&#1090; &#1082;&#1086;&#1101;&#1092;&#1092;&#1080;&#1094;&#1080;&#1077;&#1085;&#1090; &#1085;&#1072;&#1076;&#1086; <b>&#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1090;&#1086;&#1095;&#1085;&#1086; &#1082;&#1072;&#1082; &#1074; &#1087;&#1072;&#1089;&#1087;&#1086;&#1088;&#1090;&#1077; &#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;</b>, &#1080;&#1085;&#1072;&#1095;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1096;&#1080;&#1073;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1087;&#1083;&#1102;&#1089;/&#1084;&#1080;&#1085;&#1091;&#1089; &#1076;&#1077;&#1089;&#1103;&#1090;&#1082;&#1080; &#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1080; &#1073;&#1086;&#1083;&#1077;&#1077;. &#1048;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1080;&#1084;&#1077;&#1090;&#1100; &#1074; &#1074;&#1080;&#1076;&#1091;, &#1095;&#1090;&#1086; <b>&#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1080;&#1084;&#1077;&#1077;&#1090; &#1076;&#1074;&#1077; &#1076;&#1083;&#1080;&#1085;&#1099;</b>&#160; (&#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102;, &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102;), &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1103; &#1073;&#1088;&#1080;&#1075;&#1072;&#1076;&#1091; &#1085;&#1072; &#1084;&#1077;&#1089;&#1090;&#1086; &#1072;&#1074;&#1072;&#1088;&#1080;&#1080;: &#1091;&#1074;&#1080;&#1076;&#1080;&#1090; &#1086;&#1085; &#1085;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1077; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102; &#1076;&#1083;&#1080;&#1085;&#1091;, &#1072; &#1073;&#1088;&#1080;&#1075;&#1072;&#1076;&#1072;-&#1090;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1082;&#1072;&#1090;&#1100; &#1087;&#1086; &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;&#1099;&#1084; &#1084;&#1077;&#1090;&#1082;&#1072;&#1084; &#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;, &#1086;&#1090;&#1088;&#1072;&#1078;&#1072;&#1102;&#1097;&#1080;&#1084; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102; &#1076;&#1083;&#1080;&#1085;&#1091;.
    </p>
    <p>
      <b>5. &#1044;&#1083;&#1080;&#1085;&#1072; &#1074;&#1086;&#1083;&#1085;&#1099;.</b>&#160; &#1058;&#1091;&#1090; &#1090;&#1086;&#1078;&#1077; &#1074;&#1089;&#1105; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086;. &#1044;&#1083;&#1103; &#1086;&#1076;&#1085;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1081; &#1086;&#1087;&#1090;&#1080;&#1082;&#1080; &#1101;&#1090;&#1086; 1310 &#1080;&#1083;&#1080; 1550 &#1085;&#1084;. &#1044;&#1083;&#1103; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;&#1094;&#1080;&#1080; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1085;&#1072; &#1086;&#1073;&#1077;&#1080;&#1093; &#1076;&#1083;&#1080;&#1085;&#1072;&#1093; &#1074;&#1086;&#1083;&#1085;. &#1044;&#1083;&#1103; &#1089;&#1077;&#1073;&#1103;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1083;&#1091;&#1095;&#1096;&#1077; &#1087;&#1086;&#1085;&#1103;&#1090;&#1100; &#1095;&#1090;&#1086; &#1089; &#1083;&#1080;&#1085;&#1080;&#1077;&#1081;, &#1083;&#1091;&#1095;&#1096;&#1077; &#1085;&#1072; 1550 &#1085;&#1084;: &#1085;&#1072; &#1101;&#1090;&#1086;&#1081; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; (&#1083;&#1091;&#1095;&#1096;&#1077; &#1091;&#1074;&#1080;&#1076;&#1080;&#1084; &#1082;&#1086;&#1085;&#1077;&#1094; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;), &#1080; &#1088;&#1077;&#1079;&#1095;&#1077; &#1074;&#1080;&#1076;&#1085;&#1086; &#1079;&#1072;&#1075;&#1080;&#1073;&#1099; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;.
    </p>
    <p>
      <b>6. &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077;.</b>&#160; &#1042; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1072;&#1093; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1101;&#1090;&#1086;&#1090; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;. &#1058;&#1091;&#1090; &#1086;&#1087;&#1103;&#1090;&#1100; &#1078;&#1077; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1103; &#1089; &#1092;&#1086;&#1090;&#1086;&#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1086;&#1084;. &#1055;&#1088;&#1080; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1084; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1080; &#1084;&#1099; &#1083;&#1091;&#1095;&#1096;&#1077; &#1091;&#1074;&#1080;&#1076;&#1080;&#1084; &#1085;&#1077;&#1086;&#1076;&#1085;&#1086;&#1088;&#1086;&#1076;&#1085;&#1086;&#1089;&#1090;&#1080;, &#1085;&#1086; &#1092;&#1072;&#1081;&#1083; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1077;&#1089;&#1080;&#1090;&#1100; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;, &#1072; &#1090;&#1072;&#1082;&#1078;&#1077;, &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;, &#1090;&#1088;&#1072;&#1089;&#1089;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1073;&#1086;&#1083;&#1077;&#1077; &#1096;&#1091;&#1084;&#1085;&#1072;&#1103;. &#1051;&#1091;&#1095;&#1096;&#1077; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077;
    </p>
  </body>
