  </head>
  <body>
    <p>
      <b>&#1056;&#1077;&#1078;&#1080;&#1084; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;.</b>&#160; &#1056;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088; &#1074; &#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1099;-&#1076;&#1074;&#1091;&#1093; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090; &#1074; &#1083;&#1080;&#1085;&#1080;&#1102; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1077;&#1089;&#1103;&#1090;&#1082;&#1086;&#1074; &#1080;&#1083;&#1080; &#1089;&#1086;&#1090;&#1077;&#1085; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1086;&#1074; (&#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1076;&#1083;&#1103; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;, &#1087;&#1088;&#1080;&#1075;&#1086;&#1076;&#1085;&#1086;&#1081; &#1076;&#1083;&#1103; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;, &#1085;&#1086; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1086;&#1073;&#1097;&#1080;&#1081; &#1074;&#1080;&#1076; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;) &#1080; &#1086;&#1090;&#1088;&#1080;&#1089;&#1086;&#1074;&#1099;&#1074;&#1072;&#1077;&#1090; &#1091;&#1089;&#1088;&#1077;&#1076;&#1085;&#1105;&#1085;&#1085;&#1099;&#1081; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;. &#1055;&#1086;&#1090;&#1086;&#1084; &#1089;&#1085;&#1086;&#1074;&#1072; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090; &#1089;&#1077;&#1088;&#1080;&#1102; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1086;&#1074; &#1080; &#1086;&#1087;&#1103;&#1090;&#1100; &#1086;&#1090;&#1088;&#1080;&#1089;&#1086;&#1074;&#1099;&#1074;&#1072;&#1077;&#1090; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;. &#1048; &#1090;&#1072;&#1082; &#1087;&#1086;&#1082;&#1072; &#1084;&#1099; &#1085;&#1077; &#1086;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1084;. &#1055;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1084;&#1099; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; &#1089; &#1095;&#1072;&#1089;&#1090;&#1086;&#1090;&#1086;&#1081; 1 &#1082;&#1072;&#1076;&#1088; &#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1091; &#1074; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1074;&#1080;&#1076;&#1080;&#1084;, &#1095;&#1090;&#1086; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1085;&#1072; &#1090;&#1088;&#1072;&#1089;&#1089;&#1077;. &#1047;&#1072;&#1095;&#1077;&#1084; &#1101;&#1090;&#1086;&#1090; &#1088;&#1077;&#1078;&#1080;&#1084; &#1085;&#1091;&#1078;&#1077;&#1085;? &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1080;&#1089;&#1082;&#1072;&#1090;&#1100; &#171;&#1082;&#1088;&#1077;&#1089;&#1090;&#1099;&#187;, &#1072; &#1074; &#1086;&#1073;&#1097;&#1077;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1085;&#1072;&#1081;&#1090;&#1080; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;.
    </p>
    <ol>
      <li>
        &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1085;&#1077;&#1087;&#1088;&#1077;&#1088;&#1099;&#1074;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;. &#1058;&#1088;&#1072;&#1089;&#1089;&#1072; &#1088;&#1072;&#1079; &#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1091; &#1087;&#1088;&#1086;&#1088;&#1080;&#1089;&#1086;&#1074;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1082;&#1088;&#1080;&#1074;&#1086;, &#1085;&#1086; &#171;&#1076;&#1083;&#1103; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100;&#187; &#1087;&#1086;&#1081;&#1076;&#1105;&#1090;.&#160;&#160;&#1053;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1077; &#1089;&#1080;&#1076;&#1080;&#1090; &#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082;.
      </li>
      <li>
        &#1044;&#1072;&#1083;&#1100;&#1096;&#1077; &#1077;&#1075;&#1086; &#1085;&#1072;&#1087;&#1072;&#1088;&#1085;&#1080;&#1082; &#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090; &#1084;&#1091;&#1092;&#1090;&#1091;, &#1079;&#1074;&#1086;&#1085;&#1080;&#1090; &#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082;&#1091; &#1085;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1077; &#1087;&#1086; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1091; &#1080;, &#1086;&#1090;&#1082;&#1088;&#1099;&#1074; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1091;, &#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1078;&#1085;&#1086; &#1087;&#1080;&#1085;&#1094;&#1077;&#1090;&#1086;&#1084; &#1079;&#1072;&#1075;&#1080;&#1073;&#1072;&#1077;&#1090; &#1074;&#1089;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1087;&#1086; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; (&#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1086;, &#1083;&#1091;&#1095;&#1096;&#1077; &#1085;&#1072;&#1095;&#1072;&#1090;&#1100; &#1089; &#1090;&#1077;&#1093; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1074;&#1077;&#1088;&#1086;&#1103;&#1090;&#1085;&#1077;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; &#1086;&#1082;&#1072;&#1078;&#1091;&#1090;&#1089;&#1103; &#1085;&#1072;&#1096;&#1080;&#1084;&#1080;: &#1079;&#1072;&#1075;&#1080;&#1073; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1099;&#1079;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1080;&#1081; &#1087;&#1077;&#1088;&#1077;&#1088;&#1099;&#1074; &#1089;&#1074;&#1103;&#1079;&#1080;, &#1077;&#1089;&#1083;&#1080; &#1084;&#1099; &#1079;&#1072;&#1075;&#1085;&#1105;&#1084; &#1095;&#1091;&#1078;&#1086;&#1077; &#1079;&#1072;&#1085;&#1103;&#1090;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;). &#1050;&#1072;&#1082; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072;&#1087;&#1072;&#1088;&#1085;&#1080;&#1082; &#1079;&#1072;&#1075;&#1080;&#1073;&#1072;&#1077;&#1090; &#1085;&#1091;&#1078;&#1085;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1085;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1077; &#1090;&#1088;&#1072;&#1089;&#1089;&#1072; &#1088;&#1077;&#1079;&#1082;&#1086; &#1089;&#1090;&#1072;&#1085;&#1077;&#1090; &#1082;&#1086;&#1088;&#1086;&#1095;&#1077;, &#1086;&#1073;&#1086;&#1088;&#1074;&#1072;&#1074;&#1096;&#1080;&#1089;&#1100; &#1085;&#1072; &#1101;&#1090;&#1086;&#1081; &#1084;&#1091;&#1092;&#1090;&#1077; (&#1086;&#1082;&#1086;&#1083;&#1086; 30 &#1082;&#1084; &#1086;&#1090; &#1082;&#1088;&#1086;&#1089;&#1089;&#1072;). &#1053;&#1091;&#1078;&#1085;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1089;&#1088;&#1072;&#1079;&#1091; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072;&#1077;&#1090;&#1089;&#1103;. &#1055;&#1086;&#1090;&#1086;&#1084; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1086; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; 28-&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;, &#1080; &#1074;&#1086;&#1090; &#1084;&#1099; &#1079;&#1085;&#1072;&#1077;&#1084;, &#1082;&#1072;&#1082;&#1080;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1072;&#1088;&#1080;&#1090;&#1100;.
      </li>
      <li>
        &#1053;&#1072; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103;&#1093; &#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1092;&#1086;&#1085;&#1072;&#1088;&#1080;&#1082; (&#1087;&#1086; &#1089;&#1091;&#1090;&#1080; &#1082;&#1088;&#1072;&#1089;&#1085;&#1072;&#1103; &#1083;&#1072;&#1079;&#1077;&#1088;&#1085;&#1072;&#1103; &#1091;&#1082;&#1072;&#1079;&#1082;&#1072; &#1089; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1086;&#1084;) &#1080; &#1085;&#1072; &#1080;&#1079;&#1075;&#1080;&#1073;&#1072;&#1093; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1080;&#1076;&#1085;&#1086; &#1082;&#1088;&#1072;&#1089;&#1085;&#1099;&#1081; &#1089;&#1074;&#1077;&#1090;, &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082; &#1085;&#1072; &#1082;&#1088;&#1086;&#1089;&#1089;&#1077; &#1085;&#1077; &#1085;&#1091;&#1078;&#1077;&#1085;, &#1085;&#1086; &#1076;&#1072;&#1083;&#1100;&#1096;&#1077; 5 &#1082;&#1084; &#1086;&#1085; &#1085;&#1077; &#1087;&#1088;&#1086;&#1089;&#1074;&#1077;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090;, &#1080; &#1074; &#1103;&#1088;&#1082;&#1080;&#1081; &#1076;&#1077;&#1085;&#1100; &#1087;&#1086;&#1085;&#1103;&#1090;&#1100;, &#1082;&#1072;&#1082;&#1086;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1085;&#1072; &#1080;&#1079;&#1075;&#1080;&#1073;&#1077; &#1089;&#1074;&#1077;&#1090;&#1080;&#1090;&#1089;&#1103; &#1082;&#1088;&#1072;&#1089;&#1085;&#1099;&#1084;, &#1086;&#1095;&#1077;&#1085;&#1100; &#1090;&#1088;&#1091;&#1076;&#1085;&#1086; &#8212; &#1084;&#1077;&#1096;&#1072;&#1077;&#1090; &#1089;&#1074;&#1077;&#1090;
      </li>
    </ol>
