    <p>
      <b>&#1056;&#1072;&#1089;&#1095;&#1077;&#1090; &#1082;&#1080;&#1083;&#1086;&#1084;&#1077;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>0. &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;</b>&#160; - &#1085;&#1077; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1085;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;, &#1075;&#1076;&#1077; &#1084;&#1105;&#1088;&#1090;&#1074;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072;, &#1075;&#1076;&#1077; &#1082;&#1086;&#1085;&#1077;&#1094; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;, &#1075;&#1076;&#1077; &#1096;&#1091;&#1084;&#1099; - <b>&#1088;&#1072;&#1089;&#1095;&#1077;&#1090; &#1085;&#1077;&#1074;&#1077;&#1088;&#1085;&#1099;&#1081; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1041;&#1077;&#1079; &#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1072;&#1094;&#1080;&#1080; (TPA), &#1084;&#1077;&#1090;&#1086;&#1076; &#1076;&#1074;&#1091;&#1093; &#1084;&#1072;&#1088;&#1082;&#1077;&#1088;&#1086;&#1074;/&#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1086;&#1074;</b>&#160;-&#160;&#1075;&#1088;&#1091;&#1073;&#1099;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;
    </p>
    <ol>
      <li>
        &#1057;&#1090;&#1072;&#1074;&#1080;&#1084; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088; (&#1084;&#1072;&#1088;&#1082;&#1077;&#1088;) &#1085;&#1072; &#1085;&#1072;&#1095;&#1072;&#1083;&#1086; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1089;&#1088;&#1072;&#1079;&#1091; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1080;&#1082;&#1072; &#1084;&#1105;&#1088;&#1090;&#1074;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099;, &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#8212; &#1087;&#1088;&#1103;&#1084;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076; &#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1099;&#1084; &#1087;&#1080;&#1082;&#1086;&#1084; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;. (&#1054;&#1088;&#1072;&#1085;&#1078;&#1077;&#1074;&#1072;&#1103; &#1083;&#1080;&#1085;&#1080;&#1103;, &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1102;&#1097;&#1072;&#1103; 2 &#1084;&#1072;&#1088;&#1082;&#1077;&#1088;&#1072; &#8212; &#1101;&#1090;&#1086; &#1090;&#1072; &#1089;&#1072;&#1084;&#1072;&#1103; &#1086;&#1087;&#1086;&#1088;&#1085;&#1072;&#1103; &#1083;&#1080;&#1085;&#1080;&#1103;, &#1080;&#1079;&#1084;&#1077;&#1088;&#1103;&#1103; &#1091;&#1075;&#1086;&#1083; &#1085;&#1072;&#1082;&#1083;&#1086;&#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081;, &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090; &#1074;&#1099;&#1074;&#1086;&#1076; &#1086; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1084;&#1072;&#1088;&#1082;&#1077;&#1088;&#1072;&#1084;&#1080;. &#1045;&#1105; &#1074;&#1080;&#1079;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; - &#1101;&#1090;&#1086; &#1086;&#1087;&#1094;&#1080;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1076;&#1083;&#1103; &#1091;&#1076;&#1086;&#1073;&#1089;&#1090;&#1074;&#1072; &#1080;&#1083;&#1080; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1084;&#1077;&#1096;&#1072;&#1083;&#1072; &#1085;&#1072;&#1073;&#1083;&#1102;&#1076;&#1072;&#1090;&#1100; &#1085;&#1077;&#1088;&#1086;&#1074;&#1085;&#1086;&#1089;&#1090;&#1080; &#1085;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1077;).
      </li>
      <li>
        &#1055;&#1088;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1077; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1086;&#1074; (&#1084;&#1072;&#1088;&#1082;&#1077;&#1088;&#1086;&#1074;) &#1085;&#1072; &#1084;&#1105;&#1088;&#1090;&#1074;&#1091;&#1102; &#1079;&#1086;&#1085;&#1091; &#1080; &#1085;&#1072; &#1087;&#1080;&#1082; &#1082;&#1086;&#1085;&#1094;&#1072; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; <b>&#1085;&#1077; &#1079;&#1072;&#1083;&#1072;&#1079;&#1080;&#1084;</b>! &#1056;&#1072;&#1079;&#1085;&#1080;&#1094;&#1072; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1074; &#1101;&#1090;&#1080;&#1093; &#1076;&#1074;&#1091;&#1093; &#1090;&#1086;&#1095;&#1082;&#1072;&#1093; &#8212; &#1080; &#1077;&#1089;&#1090;&#1100; &#1075;&#1088;&#1091;&#1073;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1074; &#1076;&#1041;; &#1076;&#1077;&#1083;&#1080;&#1084; &#1085;&#1072; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102; &#1076;&#1083;&#1080;&#1085;&#1091; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1072;&#1084;&#1080; (&#1084;&#1072;&#1088;&#1082;&#1077;&#1088;&#1072;&#1084;&#1080;) &#8212; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084; &#1082;&#1080;&#1083;&#1086;&#1084;&#1077;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; (&#1093;&#1086;&#1090;&#1103; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088; &#1080;&#1083;&#1080; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1085;&#1072; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1084; &#1089;&#1072;&#1084; &#1085;&#1072; &#1083;&#1077;&#1090;&#1091; &#1087;&#1086;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1080; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;). &#1043;&#1088;&#1091;&#1073;&#1086;&#1077; &#8212; &#1087;&#1086;&#1090;&#1086;&#1084;&#1091;, &#1095;&#1090;&#1086; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#171;&#1096;&#1091;&#1084;&#1085;&#1086;&#1081;&#187;, &#1085;&#1077;&#1088;&#1086;&#1074;&#1085;&#1086;&#1081; &#1080; &#1088;&#1072;&#1079;&#1085;&#1086;&#1089;&#1090;&#1100; &#1074;&#1099;&#1089;&#1086;&#1090; &#1101;&#1090;&#1080;&#1093; &#1084;&#1080;&#1082;&#1088;&#1086;-&#1085;&#1077;&#1088;&#1086;&#1074;&#1085;&#1086;&#1089;&#1090;&#1077;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1076;&#1086;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1076;&#1086; &#1076;&#1077;&#1089;&#1103;&#1090;&#1099;&#1093; &#1076;&#1086;&#1083;&#1077;&#1081; &#1076;&#1077;&#1094;&#1080;&#1073;&#1077;&#1083;&#1072; &#1080; &#1074;&#1099;&#1096;&#1077;. &#1040; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1096;&#1091;&#1084;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1085;&#1094;&#1072; &#1076;&#1083;&#1080;&#1085;&#1085;&#1086;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1101;&#1090;&#1086;&#1090; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; &#1085;&#1077;&#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1084;
      </li>
    </ol>
    <p>
      <b>2. &#1057; &#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1072;&#1094;&#1080;&#1077;&#1081; (LSA)</b>&#160;- &#1073;&#1086;&#1083;&#1077;&#1077; &#1090;&#1086;&#1095;&#1085;&#1099;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;
    </p>
    <p>
      &#1042; &#1101;&#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072; &#1089;&#1090;&#1088;&#1086;&#1080;&#1090; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1083;&#1080;&#1085;&#1080;&#1102;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1091;&#1089;&#1088;&#1077;&#1076;&#1085;&#1103;&#1077;&#1090; (&#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1080;&#1088;&#1091;&#1077;&#1090;) &#1074;&#1089;&#1077; &#1085;&#1077;&#1088;&#1086;&#1074;&#1085;&#1086;&#1089;&#1090;&#1080; &#1085;&#1072; &#1090;&#1088;&#1072;&#1089;&#1089;&#1077;, &#1080; &#1087;&#1086; &#1085;&#1072;&#1082;&#1083;&#1086;&#1085;&#1091; &#1101;&#1090;&#1086;&#1081; &#1083;&#1080;&#1085;&#1080;&#1080; &#1091;&#1078;&#1077; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077;.
    </p>
    <ol>
      <li>
        &#1054;&#1087;&#1086;&#1088;&#1085;&#1072;&#1103; &#1083;&#1080;&#1085;&#1080;&#1103; &#1091;&#1078;&#1077; &#1085;&#1077; &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1072;&#1085;&#1072; &#1087;&#1086; &#1074;&#1099;&#1089;&#1086;&#1090;&#1077; &#1082; &#1090;&#1086;&#1095;&#1082;&#1072;&#1084; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;, &#1075;&#1076;&#1077; &#1089;&#1090;&#1086;&#1103;&#1090; &#1085;&#1072;&#1096;&#1080; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1099; (&#1084;&#1072;&#1088;&#1082;&#1077;&#1088;&#1099;). &#1054;&#1085;&#1072; &#1088;&#1072;&#1089;&#1089;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1085;&#1072;&#1096;&#1077;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;, &#1087;&#1086; &#1084;&#1077;&#1090;&#1086;&#1076;&#1091; &#1085;&#1072;&#1080;&#1084;&#1077;&#1085;&#1100;&#1096;&#1080;&#1093; &#1082;&#1074;&#1072;&#1076;&#1088;&#1072;&#1090;&#1086;&#1074;.
      </li>
      <li>
        &#1057;&#1087;&#1086;&#1089;&#1086;&#1073; &#1073;&#1086;&#1083;&#1077;&#1077; &#1090;&#1086;&#1095;&#1085;&#1099;&#1081;, &#1085;&#1086;! <b>&#1045;&#1089;&#1083;&#1080; &#1085;&#1072; &#1090;&#1088;&#1072;&#1089;&#1089;&#1077; &#1080;&#1084;&#1077;&#1077;&#1090;&#1089;&#1103; &#1084;&#1085;&#1086;&#1075;&#1086; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081;</b>&#160;&#1089; &#1074;&#1099;&#1089;&#1086;&#1082;&#1080;&#1084;&#1080; &#1087;&#1080;&#1082;&#1072;&#1084;&#1080; &#1086;&#1090;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;, &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1072;&#1094;&#1080;&#1080; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1090; &#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086; &#1080; &#1084;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1084; <b>&#1085;&#1077;&#1074;&#1077;&#1088;&#1085;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;</b>.
      </li>
    </ol>
    <p>
      <b>3. &#1056;&#1091;&#1095;&#1085;&#1086;&#1081; &#1088;&#1072;&#1089;&#1095;&#1077;&#1090;.</b>
    </p>
    <ol>
      <li>
        &#1055;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103; &#1074;&#1089;&#1077;&#1093; &#1082;&#1091;&#1089;&#1082;&#1086;&#1074; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1084;&#1077;&#1078;&#1076;&#1091; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084;&#1080; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;, &#1085;&#1077; &#1079;&#1072;&#1093;&#1074;&#1072;&#1090;&#1099;&#1074;&#1072;&#1103; &#1080;&#1093; &#1087;&#1080;&#1082;&#1080;
      </li>
      <li>
        &#1054;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103; &#1085;&#1072; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;&#1093;
      </li>
      <li>
        &#1042;&#1089;&#1105; &#1089;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1080; &#1087;&#1086;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1085;&#1072; &#1076;&#1083;&#1080;&#1085;&#1091; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082;&#1080;&#1083;&#1086;&#1084;&#1077;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103;
      </li>
    </ol>
  </body>
