      <b>&#1056;&#1072;&#1089;&#1095;&#1077;&#1090; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103; &#1085;&#1072; &#1085;&#1077;&#1086;&#1076;&#1085;&#1086;&#1088;&#1086;&#1076;&#1085;&#1086;&#1089;&#1090;&#1080; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1089;&#1074;&#1072;&#1088;&#1082;&#1077;) </b>
