    <ol>
      <li>
        &#1057;&#1090;&#1072;&#1074;&#1080;&#1084; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088; &#1087;&#1077;&#1088;&#1077;&#1076; &#1089;&#1074;&#1072;&#1088;&#1082;&#1086;&#1081;, &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#8212; &#1089;&#1088;&#1072;&#1079;&#1091; &#1087;&#1086;&#1089;&#1083;&#1077; &#1085;&#1077;&#1105;
