      </li>
      <li>
        &#1055;&#1086;&#1090;&#1077;&#1088;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1072;&#1084;&#1080; - &#1075;&#1088;&#1091;&#1073;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1103;
      </li>
    </ol>
    <p>
      <b>2. &#1057;&#1087;&#1086;&#1089;&#1086;&#1073; &#1089; &#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1072;&#1094;&#1080;&#1077;&#1081; (LSA, &#1084;&#1077;&#1090;&#1086;&#1076; &#1095;&#1077;&#1090;&#1099;&#1088;&#1105;&#1093; &#1084;&#1072;&#1088;&#1082;&#1077;&#1088;&#1086;&#1074;/&#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1086;&#1074;) - &#1073;&#1086;&#1083;&#1077;&#1077; &#1090;&#1086;&#1095;&#1085;&#1099;&#1081;. </b>&#1056;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072;, &#1082;&#1072;&#1082; &#1084;&#1099; &#1079;&#1085;&#1072;&#1077;&#1084;, &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1096;&#1091;&#1084;&#1085;&#1086;&#1081; &#1080; &#1077;&#1089;&#1083;&#1080; &#1084;&#1099; &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1084; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1082;&#1091;&#1088;&#1089;&#1086;&#1088; &#1080; &#1087;&#1086;&#1087;&#1072;&#1076;&#1105;&#1084; &#1085;&#1072; &#1084;&#1080;&#1082;&#1088;&#1086;-&#1087;&#1080;&#1082;, &#1072; &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1084; &#1080; &#1087;&#1086;&#1087;&#1072;&#1076;&#1105;&#1084; &#1085;&#1072; &#1084;&#1080;&#1082;&#1088;&#1086;-&#1087;&#1088;&#1086;&#1074;&#1072;&#1083;, &#1090;&#1086; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088; &#1085;&#1072;&#1084; &#1087;&#1086;&#1082;&#1072;&#1078;&#1077;&#1090; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1089;&#1074;&#1072;&#1088;&#1082;&#1077; &#1075;&#1086;&#1088;&#1072;&#1079;&#1076;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;, &#1095;&#1077;&#1084; &#1086;&#1085;&#1086; &#1090;&#1072;&#1084; &#1077;&#1089;&#1090;&#1100; &#1085;&#1072; &#1089;&#1072;&#1084;&#1086;&#1084; &#1076;&#1077;&#1083;&#1077;. &#1048; &#1085;&#1072;&#1086;&#1073;&#1086;&#1088;&#1086;&#1090;: &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1079;&#1077;&#1074;&#1072;&#