    </p>
    <ol>
      <li>
        &#1042;&#1086;&#1079;&#1100;&#1084;&#1105;&#1084; &#1076;&#1086; &#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1087;&#1086; &#1082;&#1072;&#1082; &#1084;&#1086;&#1078;&#1085;&#1086; &#1073;&#1086;&#1083;&#1077;&#1077; &#1076;&#1083;&#1080;&#1085;&#1085;&#1086;&#1084;&#1091; &#1082;&#1091;&#1089;&#1086;&#1095;&#1082;&#1091; &#1095;&#1080;&#1089;&#1090;&#1086;&#1075;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1073;&#1077;&#1079; &#1085;&#1077;&#1086;&#1076;&#1085;&#1086;&#1088;&#1086;&#1076;&#1085;&#1086;&#1089;&#1090;&#1077;&#1081;
      </li>
      <li>
        &#1053;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1080;&#1079; &#1101;&#1090;&#1080;&#1093; &#1082;&#1091;&#1089;&#1086;&#1095;&#1082;&#1086;&#1074; &#1087;&#1086;&#1089;&#1090;&#1088;&#1086;&#1080;&#1084; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1087;&#1088;&#1103;&#1084;&#1091;&#1102;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1086;&#1084; &#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1072;&#1094;&#1080;&#1080; &#1088;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086;, &#1085;&#1086; &#1074;&#1089;&#1105; &#1078;&#1077; &#1096;&#1091;&#1084;&#1085;&#1086;&#1075;&#1086; &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1087;&#1086;&#1076; &#1085;&#1077;&#1081; (&#1085;&#1077; &#1079;&#1072;&#1073;&#1099;&#1074;&#1072;&#1077;&#1084; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1072;&#1094;&#1080;&#1102; &#8212; &#1082;&#1085;&#1086;&#1087;&#1082;&#1072; &#171;LSA/TPA&#187; &#1074; &#1088;&#1091;&#1078;&#1080;&#1084;&#1077; LSA)
