      </li>
      <li>
        &#1055;&#1077;&#1088;&#1074;&#1099;&#1077; 2 &#1084;&#1072;&#1088;&#1082;&#1077;&#1088;&#1072;/&#1082;&#1091;&#1088;&#1089;&#1086;&#1088;&#1072; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090; &#1075;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1081; &#1083;&#1080;&#1085;&#1080;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076; &#1089;&#1074;&#1072;&#1088;&#1082;&#1086;&#1081;, &#1072; &#1090;&#1088;&#1077;&#1090;&#1080;&#1081; &#1080; &#1095;&#1077;&#1090;&#1074;&#1105;&#1088;&#1090;&#1099;&#1081; - &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#1072;&#1087;&#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1084;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1081; &#1083;&#1080;&#1085;&#1080;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080;. &#1045;&#1089;&#1083;&#1080; &#1084;&#1099; &#1086;&#1073;&#1077; &#1083;&#1080;&#1085;&#1080;&#1080; &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1084; &#1085;&#1072; &#1095;&#1080;&#1089;&#1090;&#1099;&#1093;, &#1073;&#1077;&#1079; &#1085;&#1077;&#1086;&#1076;&#1085;&#1086;&#1088;&#1086;&#1076;&#1085;&#1086;&#1089;&#1090;&#1103;&#1093;, &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1072;&#1093;, &#1090;&#1086; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1089;&#1074;&#1072;&#1088;&#1082;&#1077; &#1084;&#1099; &#1091;&#1079;&#1085;&#1072;&#1077;&#1084; &#1086;&#1095;&#1077;&#1085;&#1100; &#1090;&#1086;&#1095;&#1085;&#1086;
      </li>
      <li>
        &#1069;&#1090;&#1086; &#1085;&#1077; &#1092;&#1080;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;: &#1076;&#1083;&#1103; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086;&#1081; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1078;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;, &#1072; &#1076;&#1083;&#1103; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; SM &#1080; NZ/DS &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1080;&#1090;&#1100; &#1074;&#1089;&#1105; &#1101;&#1090;&#1086; &#1077;&#1097;&#1105; &#1080; &#1085;&#1072; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1077; (&#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1075;&#1086; &#1082;&#1086;&#1085;&#1094;&#1072; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;) &#1080; &#1087;&#1086;&#1089;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100; &#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;. &#1048; &#1090;&#1072;&#1082; &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1077;&#1089;&#1091;&#1102;&#1097;&#1077;&#1081; &#1085;&#1072;&#1089; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080;. &#1053;&#1086; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#171;&#1089;&#1084;&#1077;&#1097;&#1105;&#1085;&#1082;&#1080;&#187; &#1085;&#1077;&#1090;, &#1084;&#1085;&#1086;&#1075;&#1080;&#1077; &#1085;&#1077; &#1079;&#1072;&#1084;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089; &#1076;&#1074;&#1091;&#1093;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1080;&#1084; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1077;&#1084;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1074; &#1101;&#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1095;&#1090;&#1086; &#1080;&#1079; &#1040; &#1074; &#1041;, &#1095;&#1090;&#1086; &#1080;&#1079; &#1041; &#1074; &#1040; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1095;&#1090;&#1080; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1099;&#1084;.
