  <body>
    <p>
      <a href="#ID_1635640741">&#1048;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100; &#1086;&#1087;&#1090;. &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080;</a>&#160;&#160;<a href="#ID_1513461510">&#1048;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082; &#1086;&#1087;&#1090;. &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1054;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1090;&#1077;&#1089;&#1090;&#1077;&#1088; (&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1084;&#1077;&#1090;&#1088;, OLTS)</b>&#160;- &#1079;&#1072;&#1084;&#1077;&#1088;&#1103;&#1102;&#1090; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1087;&#1086;&#1076;&#1072;&#1085;&#1085;&#1091;&#1102; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084; <b>&#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1086;&#1084; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103;</b>, &#1080;&#1079;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1075;&#1086; &#1074; &#1082;&#1086;&#1084;&#1087;&#1083;&#1077;&#1082;&#1090; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1090;&#1077;&#1089;&#1090;&#1077;&#1088;&#1072; &#1080;&#1083;&#1080; &#1087;&#1088;&#1080;&#1086;&#1073;&#1088;&#1077;&#1090;&#1072;&#1077;&#1084;&#1086;&#1075;&#1086; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;. &#1055;&#1086;&#1090;&#1077;&#1088;&#1080; &#1074;&#1099;&#1088;&#1072;&#1078;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; <b>&#1076;&#1041;</b>&#160;&#1080; &#1093;&#1072;&#1088;&#1072;&#1082;&#1090;&#1077;&#1088;&#1080;&#1079;&#1091;&#1102;&#1090; <b>&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102; &#1083;&#1080;&#1085;&#1080;&#1102;</b>
    </p>
    <ul>
      <li>
        &#1048;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082; &#1086;&#1087;&#1090;. &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; + &#1048;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100; &#1086;&#1087;&#1090;. &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080;
      </li>
      <li>
        &#1055;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1077; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1074;&#1085;&#1086;&#1089;&#1080;&#1084;&#1099;&#1093; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100; (&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077;).
      </li>
      <li>
        &#1042; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; 2 &#1076;&#1083;&#1080;&#1085;&#1099; &#1074;&#1086;&#1083;&#1085;&#1099;, &#1072; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1103; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080; - &#1076;&#1077;&#1089;&#1103;&#1090;&#1082;&#1080; &#1074;&#1086;&#1083;&#1085;
      </li>
      <li>
        &#1050;&#1072;&#1082; &#1086;&#1087;&#1094;&#1080;&#1102;, &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1090;&#1077;&#1089;&#1090;&#1077;&#1088;&#1099; &#1084;&#1086;&#1075;&#1091;&#1090; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1081; &#1074;&#1080;&#1079;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1076;&#1077;&#1092;&#1077;&#1082;&#1090;&#1086;&#1089;&#1082;&#1086;&#1087; (<a href="#ID_529466421">VFL</a>). &#1053;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1086;&#1076;&#1077;&#1083;&#1080; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1090; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1082;&#1086;&#1087;&#1072; &#1076;&#1083;&#1103; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1103; &#1090;&#1086;&#1088;&#1094;&#1086;&#1074; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1086;&#1074; &#1091; &#1087;&#1072;&#1090;&#1095;-&#1082;&#1086;&#1088;&#1076;&#1086;&#1074; &#1080; &#1087;&#1080;&#1075;-&#1090;&#1077;&#1081;&#1083;&#1086;&#1074;, &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1080;&#1084;&#1080;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1072;
      </li>
    </ul>
    <p>
      &#1050;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077;:
    </p>
    <ul>
      <li>
        &#1042; &#1074;&#1080;&#1076;&#1077; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1072;
      </li>
      <li>
        &#1042; &#1074;&#1080;&#1076;&#1077; &#1086;&#1087;&#1094;&#1080;&#1080; &#1085;&#1072; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1077;
      </li>
    </ul>
  </body>
