      </li>
      <li>
        &#1054;&#1090;&#1088;&#1080;&#1094;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; (&#1074; &#1076;&#1077;&#1094;&#1080;&#1073;&#1077;&#1083;&#1072;&#1093;) &#1085;&#1072; &#1076;&#1080;&#1089;&#1087;&#1083;&#1077;&#1077; &#1087;&#1088;&#1080;&#1105;&#1084;&#1085;&#1080;&#1082;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1076;&#1086; &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1088;&#1080; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1105;&#1085;&#1085;&#1099;&#1093; &#1087;&#1072;&#1090;&#1095;-&#1082;&#1086;&#1088;&#1076;&#1072;&#1084;&#1080; &#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1105;&#1085;&#1085;&#1099;&#1093; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1072;&#1093; &#1073;&#1099;&#1083; &#1085;&#1086;&#1083;&#1100; &#1080; &#1086;&#1085; &#1073;&#1099;&#1083; &#1086;&#1087;&#1086;&#1088;&#1085;&#1099;&#1084;, &#1080; &#1077;&#1089;&#1090;&#1100; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1074;&#1089;&#1077;&#1081; &#1085;&#1072;&#1096;&#1077;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;. &#1044;&#1077;&#1083;&#1080;&#1084; &#1085;&#1072; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102; &#1076;&#1083;&#1080;&#1085;&#1091; &#1085;&#1072;&#1096;&#1077;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#8212; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1084; &#1082;&#1080;&#1083;&#1086;&#1084;&#1077;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; (&#1074; &#1076;&#1041;/&#1082;&#1084;).
      </li>
    </ol>
    <p>
      <b>&#1047;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077;</b>
    </p>
    <p>
      A[&#1076;&#1041;] = P&#1074;&#1093;[&#1076;&#1041;&#1084;] - P&#1074;&#1099;&#1093;[&#1076;&#1041;&#1084;]
    </p>
