    <ul>
      <li>
        &#1052;&#1085;&#1086;&#1075;&#1080;&#1077; &#1084;&#1086;&#1076;&#1077;&#1083;&#1080; &#1091;&#1084;&#1077;&#1102;&#1090; &#1089;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1090;&#1100; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086; &#1089;&#1086; &#1089;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077;&#1084;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1074;&#1072;&#1088;&#1082;&#1072; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1083;&#1072;&#1089;&#1100; &#1089; <b>&#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1099;&#1084; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077;&#1084;</b>, &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; <b>&#1072;&#1090;&#1090;&#1077;&#1085;&#1102;&#1072;&#1090;&#1086;&#1088; </b>
      </li>
    </ul>
    <p>
      <b>&#1043;&#1088;&#1091;&#1087;&#1087;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1089;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1099;&#1093; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1086;&#1074;:</b>
    </p>
    <ol>
      <li>
        <b>&#1044;&#1083;&#1103; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1081; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080;&#1080; &#1086;&#1076;&#1080;&#1085;&#1086;&#1095;&#1085;&#1099;&#1093; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;.</b>&#160;&#160;&#1055;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1103;&#1090; &#1102;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1091; (&#1074;&#1079;&#1072;&#1080;&#1084;&#1085;&#1086;&#1077; &#1074;&#1099;&#1088;&#1072;&#1074;&#1085;&#1080;&#1074;&#1072;&#1085;&#1080;&#1077;) &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1085;&#1072; &#1087;&#1088;&#1086;&#1089;&#1074;&#1077;&#1090; &#1080; &#1087;&#1086; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1077;, &#1080; &#1087;&#1086; &#1089;&#1077;&#1088;&#1076;&#1094;&#1077;&#1074;&#1080;&#1085;&#1077;
      </li>
      <li>
        <b>&#1044;&#1083;&#1103; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1084;&#1077;&#1085;&#1077;&#1077; &#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1093; &#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1082;&#1080;&#1093; &#1083;&#1080;&#1085;&#1080;&#1081;.</b>&#160;&#1057;&#1074;&#1086;&#1076;&#1080;&#1090; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1089;&#1076;&#1074;&#1080;&#1075;&#1072;&#1103; &#1087;&#1086; &#1076;&#1074;&#1091;&#1084; &#1079;&#1072;&#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084; V-&#1086;&#1073;&#1088;&#1072;&#1079;&#1085;&#1099;&#1084; &#1082;&#1072;&#1085;&#1072;&#1074;&#1082;&#1072;&#1084;. &#1042; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1084;, &#1076;&#1083;&#1103; &#1084;&#1085;&#1086;&#1075;&#1086;&#1084;&#1086;&#1076;&#1072;.&#160;&#1047;&#1072; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077;&#1084; &#1085;&#1072; &#1089;&#1074;&#1072;&#1088;&#1082;&#1077; &#1085;&#1077; &#1075;&#1086;&#1085;&#1103;&#1090;&#1089;&#1103;
      </li>
      <li>
        <b>&#1044;&#1083;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1086;&#1074;&#1086;&#1081; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1083;&#1077;&#1085;&#1090;&#1086;&#1095;&#1085;&#1099;&#1093; (ribbon) &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;.</b>&#160; &#1050;&#1072;&#1073;&#1077;&#1083;&#1100; &#1090;&#1072;&#1082;&#1086;&#1075;&#1086; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1072; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1074; &#1089;&#1077;&#1095;&#1077;&#1085;&#1080;&#1080; &#1087;&#1088;&#1103;&#1084;&#1086;&#1091;&#1075;&#1086;&#1083;&#1100;&#1085;&#1099;&#1081;, &#1080; &#1074; &#1085;&#1105;&#1084; &#1083;&#1077;&#1078;&#1072;&#1090; &#1083;&#1077;&#1085;&#1090;&#1099;, &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1077; &#1080;&#1079; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; (&#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1076;&#1086; 12) &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;. &#1057;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1099;&#1081; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090; &#1074;&#1072;&#1088;&#1080;&#1090; &#1089;&#1088;&#1072;&#1079;&#1091; &#1074;&#1089;&#1102; &#1083;&#1077;&#1085;&#1090;&#1091;. &#1042; &#1056;&#1086;&#1089;&#1089;&#1080;&#1080; &#1088;&#1077;&#1076;&#1082;&#1080;.
      </li>
      <li>
        <b>&#1044;&#1083;&#1103; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; <a href="#ID_451128731">FTTx</a>-&#1089;&#1077;&#1090;&#1077;&#1081; (&#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1099; &#171;&#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1101;&#1096;&#1077;&#1083;&#1086;&#1085;&#1072;&#187;).</b>&#160;&#1050;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1103; &#1084;&#1077;&#1085;&#1077;&#1077; &#1087;&#1088;&#1086;&#1076;&#1074;&#1080;&#1085;&#1091;&#1090;&#1072;&#1103; &#1080; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1085;&#1077; &#1090;&#1072;&#1082;&#1086;&#1077; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1077;, &#1082;&#1072;&#1082; &#1091; &#171;&#1084;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093;&#187; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1086;&#1074;, &#1072;&#1082;&#1082;&#1091;&#1084;&#1091;&#1083;&#1103;&#1090;&#1086;&#1088; &#1089;&#1083;&#1072;&#1073;&#1077;&#1077;, &#1085;&#1086; &#1075;&#1072;&#1073;&#1072;&#1088;&#1080;&#1090;&#1099; &#1080; &#1094;&#1077;&#1085;&#1072; &#1085;&#1080;&#1078;&#1077;. &#1058;&#1072;&#1082; &#1078;&#1077; &#1076;&#1077;&#1096;&#1077;&#1074;&#1099;&#1077; &#1082;&#1080;&#1090;&#1072;&#1081;&#1089;&#1082;&#1080;&#1077; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1099;
      </li>
      <li>
        <b>&#1057;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1080; &#1083;&#1072;&#1073;&#1086;&#1088;&#1072;&#1090;&#1086;&#1088;&#1085;&#1099;&#1077; &#1089;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1099;&#1077; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1099;.</b>&#160;&#1044;&#1083;&#1103; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1089; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1077;&#1084; &#1087;&#1086;&#1083;&#1103;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;. &#1058;&#1072;&#1082;&#1080;&#1077; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1099; &#1086;&#1095;&#1077;&#1085;&#1100; &#1076;&#1086;&#1088;&#1086;&#1075;&#1080;&#1077;, &#1080;&#1084;&#1077;&#1102;&#1090; &#1082;&#1091;&#1095;&#1091; &#1075;&#1080;&#1073;&#1082;&#1080;&#1093; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082;, &#1090;&#1088;&#1077;&#1073;&#1091;&#1102;&#1090; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1080;&#1084;&#1077;&#1102;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1089;&#1082;&#1086;&#1083;&#1099; &#1087;&#1086;&#1076; &#1091;&#1075;&#1083;&#1086;&#1084; 45 &#1075;&#1088;&#1072;&#1076;&#1091;&#1089;&#1086;&#1074; &#1080; &#1090;&#1072;&#1082; &#1089;&#1074;&#1072;&#1088;&#1080;&#1090;&#1100;
      </li>
    </ol>
    <p>
      <b>&#1055;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1080; (&#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1077;)</b>
