    <p>
      <b>&#1052;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084; &#1076;&#1083;&#1103; &#1082;&#1080;&#1090;&#1072;&#1081;&#1094;&#1077;&#1074;</b>. &#1042;&#1089;&#1105; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1085;&#1086;, &#1095;&#1077;&#1088;&#1077;&#1079; &#1084;&#1077;&#1085;&#1102;, &#1080; &#1074;&#1089;&#1105; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1086; &#1074; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1080;
    </p>
    <ul>
      <li>
        &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1091; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1086;&#1074; &#1084;&#1086;&#1097;&#1085;&#1099;&#1084; &#1090;&#1086;&#1082;&#1086;&#1084;
      </li>
      <li>
        &#1082;&#1072;&#1083;&#1080;&#1073;&#1088;&#1086;&#1074;&#1082;&#1091; &#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1076;&#1091;&#1075;&#1080;
      </li>
      <li>
        &#1082;&#1072;&#1083;&#1080;&#1073;&#1088;&#1086;&#1074;&#1082;&#1091; &#1089;&#1080;&#1083;&#1099; &#1090;&#1086;&#1082;&#1072; &#1074; &#1076;&#1091;&#1075;&#1077;
      </li>
      <li>
        &#1053;&#1072; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1082;&#1080;&#1090;&#1072;&#1081;&#1094;&#1072;&#1093; &#1087;&#1086;&#1089;&#1083;&#1077; <b>9999</b>&#160; &#1089;&#1074;&#1072;&#1088;&#1086;&#1082; (&#1074;&#1077;&#1089;&#1100;&#1084;&#1072; &#1074;&#1085;&#1091;&#1096;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1086;&#1073;&#1098;&#1105;&#1084;) &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;, &#1090;&#1088;&#1077;&#1073;&#1091;&#1103; &#1085;&#1077;&#1089;&#1090;&#1080; &#1077;&#1075;&#1086; &#1074; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;-&#1094;&#1077;&#1085;&#1090;&#1088; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;
      </li>
    </ul>
    <p>
      <b>&#1059; &#1103;&#1087;&#1086;&#1085;&#1094;&#1077;&#1074; &#1085;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;-&#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091;</b>, &#1090;&#1072;&#1084; &#1077;&#1089;&#1090;&#1100; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1089;&#1072;&#1084;&#1086;&#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
    </p>
    <ul>
      <li>
        &#1058;&#1077;&#1089;&#1090;&#1099; &#1078;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1088;&#1086;&#1075;&#1086;&#1085;&#1103;&#1090;&#1100; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1088;&#1072;&#1079; &#1087;&#1077;&#1088;&#1077;&#1076; &#1085;&#1072;&#1095;&#1072;&#1083;&#1086;&#1084; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1077;&#1081; &#1082;&#1072;&#1083;&#1080;&#1073;&#1088;&#1086;&#1074;&#1082;&#1080; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1083;&#1072;&#1089;&#1100; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1072;/&#1074;&#1083;&#1072;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1072; (&#1074;&#1083;&#1080;&#1103;&#1077;&#1090; &#1085;&#1072; &#1076;&#1091;&#1075;&#1091;)
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1089; &#1087;&#1088;&#1086;&#1096;&#1083;&#1086;&#1081; &#1082;&#1072;&#1083;&#1080;&#1073;&#1088;&#1086;&#1074;&#1082;&#1080; &#1073;&#1099;&#1083;&#1086; &#1089;&#1076;&#1077;&#1083;&#1072;&#1085;&#1086; &#1084;&#1085;&#1086;&#1075;&#1086; &#1089;&#1074;&#1072;&#1088;&#1086;&#1082; (&#1082;&#1086;&#1085;&#1095;&#1080;&#1082;&#1080; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1086;&#1074; &#1091;&#1089;&#1087;&#1077;&#1083;&#1080; &#1085;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1080;&#1079;&#1085;&#1086;&#1089;&#1080;&#1090;&#1100;&#1089;&#1103;).
      </li>
    </ul>
    <p>
      <b>&#1048;&#1085;&#1086;&#1075;&#1076;&#1072; &#1090;&#1088;&#1077;&#1073;&#1091;&#1102;&#1090; &#1079;&#1072;&#1084;&#1077;&#1085;&#1099; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1099;</b>&#160;(&#1087;&#1086;&#1089;&#1083;&#1077; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1090;&#1099;&#1089;&#1103;&#1095; &#1089;&#1074;&#1072;&#1088;&#1086;&#1082;) &#1080; <b>&#1072;&#1082;&#1082;&#1091;&#1084;&#1091;&#1083;&#1103;&#1090;&#1086;&#1088;</b>. &#1055;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1084;&#1077;&#1085;&#1099; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1086;&#1074; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1088;&#1086;&#1075;&#1086;&#1085;&#1103;&#1090;&#1100; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1091;&#1102; &#1082;&#1072;&#1083;&#1080;&#1073;&#1088;&#1086;&#1074;&#1082;&#1091;. &#1048;&#1079;&#1085;&#1086;&#1089; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1086;&#1074;:
    </p>
    <ol>
      <li>
        &#1085;&#1072; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1099; &#1087;&#1086;&#1089;&#1090;&#1077;&#1087;&#1077;&#1085;&#1085;&#1086; &#1085;&#1072;&#1087;&#1099;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1083;&#1086;&#1081; &#1089;&#1090;&#1077;&#1082;&#1083;&#1072; &#1089;&#1086; &#1089;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1077;&#1084;&#1099;&#1093; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;. <b>&#1052;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1076;&#1083;&#1080;&#1090;&#1100; &#1080;&#1093; &#1078;&#1080;&#1079;&#1085;&#1100; &#1085;&#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1086;&#1090;&#1077;&#1085; &#1089;&#1074;&#1072;&#1088;&#1086;&#1082;.</b>&#160; &#1058;&#1072;&#1082; &#1074;&#1086;&#1090;, &#1082;&#1088;&#1086;&#1096;&#1082;&#1080; &#1085;&#1072;&#1087;&#1099;&#1083;&#1105;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1090;&#1077;&#1082;&#1083;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1082;&#1086;&#1074;&#1099;&#1088;&#1085;&#1091;&#1090;&#1100; &#1073;&#1088;&#1080;&#1090;&#1074;&#1086;&#1081;, &#1090;&#1086;, &#1095;&#1090;&#1086; &#1086;&#1089;&#1090;&#1072;&#1083;&#1086;&#1089;&#1100; &#8212; &#1089;&#1085;&#1103;&#1090;&#1100; &#1095;&#1080;&#1089;&#1090;&#1082;&#1086;&#1081; &#1074; &#1089;&#1090;&#1080;&#1088;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1088;&#1077;&#1079;&#1080;&#1085;&#1082;&#1077;. &#1058;&#1086;&#1083;&#1100;&#1082;&#1086; &#1088;&#1077;&#1079;&#1080;&#1085;&#1082;&#1091; &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1090;&#1100; &#171;&#1085;&#1077;&#1078;&#1085;&#1091;&#1102;&#187;, &#1073;&#1077;&#1079; &#1072;&#1073;&#1088;&#1072;&#1079;&#1080;&#1074;&#1085;&#1099;&#1093; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074;, &#1080;&#1085;&#1072;&#1095;&#1077; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1099; &#1087;&#1088;&#1080;&#1076;&#1105;&#1090;&#1089;&#1103; &#1074;&#1099;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1087;&#1086;&#1095;&#1090;&#1080; &#1089;&#1088;&#1072;&#1079;&#1091;.
      </li>
      <li>
        &#1074; &#1074;&#1099;&#1075;&#1086;&#1088;&#1072;&#1085;&#1080;&#1080; &#171;&#1074;&#1086;&#1088;&#1086;&#1085;&#1086;&#1082;&#187; &#1085;&#1072; &#1082;&#1086;&#1085;&#1095;&#1080;&#1082;&#1072;&#1093; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1086;&#1074;, &#1095;&#1090;&#1086; &#1087;&#1088;&#1080;&#1074;&#1086;&#1076;&#1080;&#1090; &#1082; &#1085;&#1077;&#1089;&#1090;&#1072;&#1073;&#1080;&#1083;&#1100;&#1085;&#1086;&#1081; &#1076;&#1091;&#1075;&#1077;
      </li>
    </ol>
    <p>
      <b>&#1048;&#1085;&#1086;&#1075;&#1076;&#1072; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1095;&#1080;&#1089;&#1090;&#1082;&#1072; &#1086;&#1090; &#1087;&#1099;&#1083;&#1080;</b>&#160; (<font color="#ff0000">&#1087;&#1088;&#1086;&#1076;&#1091;&#1074;&#1072;&#1090;&#1100; &#1073;&#1072;&#1083;&#1083;&#1086;&#1085;&#1095;&#1080;&#1082;&#1086;&#1084; &#1089;&#1086; &#1089;&#1078;&#1072;&#1090;&#1099;&#1084; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1086;&#1084; &#1079;&#1072;&#1087;&#1088;&#1077;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103;</font>&#160; - &#1089;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1095;&#1091;&#1074;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1082;&#1072;)
    </p>
    <p>
      <b>&#1055;&#1088;&#1080; &#1089;&#1074;&#1072;&#1088;&#1082;&#1077; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1092;&#1086;&#1088;&#1084;&#1091; &#1076;&#1091;&#1075;&#1080;</b>&#160; (&#1077;&#1089;&#1083;&#1080; &#1076;&#1091;&#1075;&#1072; &#1082;&#1088;&#1080;&#1074;&#1072;&#1103; &#1080; &#1085;&#1077;&#1089;&#1090;&#1072;&#1073;&#1080;&#1083;&#1100;&#1085;&#1072;&#1103; &#8212; &#1095;&#1090;&#1086;-&#1090;&#1086; &#1085;&#1077; &#1090;&#1072;&#1082;: &#1084;&#1086;&#1078;&#1077;&#1090;, &#1087;&#1086;&#1088;&#1072; &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1099;, &#1080;&#1083;&#1080; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1082;&#1072;&#1083;&#1080;&#1073;&#1088;&#1086;&#1074;&#1082;&#1091;?)
    </p>
  </body>
</html></richcontent>
