  <body>
    <p>
      <a href="#ID_550273367">&#1057;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; &#1054;&#1042;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;</b>&#160;- &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1090;&#1086;&#1095;&#1085;&#1086;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1076;&#1083;&#1103; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1082;&#1072;&#1082; &#1084;&#1086;&#1078;&#1085;&#1086; &#1073;&#1086;&#1083;&#1077;&#1077; &#1087;&#1083;&#1086;&#1089;&#1082;&#1086;&#1081; &#1080; &#1087;&#1077;&#1088;&#1087;&#1077;&#1085;&#1076;&#1080;&#1082;&#1091;&#1083;&#1103;&#1088;&#1085;&#1086;&#1081; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1091; &#1087;&#1086;&#1074;&#1077;&#1088;&#1093;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089;&#1082;&#1086;&#1083;&#1072;
    </p>
    <ul>
      <li>
        &#1053;&#1072; &#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1101;&#1082;&#1086;&#1085;&#1086;&#1084;&#1080;&#1090;&#1100;
      </li>
      <li>
        &#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1084; <b>&#1073;&#1077;&#1079; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1072;</b>&#160;&#1076;&#1083;&#1103; &#1089;&#1082;&#1086;&#1083;&#1086;&#1090;&#1099;&#1093; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; <b>&#1085;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103;</b>
      </li>
      <li>
        &#1045;&#1075;&#1086; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1073;&#1080;&#1090;&#1100; &#1080;&#1083;&#1080; &#1088;&#1086;&#1085;&#1103;&#1090;&#1100;. &#1041;&#1091;&#1076;&#1077;&#1090; &#1074;&#1084;&#1103;&#1090;&#1080;&#1085;&#1072; &#1080; &#1089;&#1086;&#1076;&#1088;&#1072;&#1085;&#1085;&#1072;&#1103; &#1082;&#1088;&#1072;&#1089;&#1082;&#1072; &#8212; &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1080; &#1082;&#1086;&#1085;&#1077;&#1094;
      </li>
      <li>
        &#1053;&#1077;&#1083;&#1100;&#1079;&#1103; &#1082;&#1072;&#1089;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082;&#1088;&#1091;&#1075;&#1086;&#1074;&#1086;&#1075;&#1086; &#1085;&#1086;&#1078;&#1072; &#1087;&#1072;&#1083;&#1100;&#1094;&#1072;&#1084;&#1080; &#1080; &#1087;&#1088;&#1086;&#1095;&#1080;&#1084;&#1080; &#1087;&#1088;&#1077;&#1076;&#1084;&#1077;&#1090;&#1072;&#1084;&#1080;. &#1042;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1085;&#1091;&#1078;&#1085;&#1086; &#1079;&#1072;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100; &#1086;&#1095;&#1077;&#1085;&#1100; &#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1078;&#1085;&#1086;, &#1086;&#1076;&#1085;&#1086; &#1076;&#1074;&#1080;&#1078;&#1077;&#1085;&#1080;&#1077; &#1088;&#1091;&#1082;&#1072;&#1084;&#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1074;&#1083;&#1077;&#1095;&#1100; &#1087;&#1086;&#1088;&#1077;&#1079; &#1087;&#1072;&#1083;&#1100;&#1094;&#1072; &#1080; &#1084;&#1080;&#1085;&#1091;&#1089; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1072; &#1074; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1090;&#1099;&#1089;&#1103;&#1095; &#1089;&#1082;&#1086;&#1083;&#1086;&#1074; (&#1077;&#1089;&#1083;&#1080; &#1085;&#1086;&#1078; &#1095;&#1072;&#1089;&#1090;&#1080;&#1095;&#1085;&#1086; &#1079;&#1072;&#1090;&#1091;&#1087;&#1080;&#1090;&#1089;&#1103;)
      </li>
      <li>
        &#1053;&#1077;&#1083;&#1100;&#1079;&#1103; &#1085;&#1072;&#1076;&#1086;&#1083;&#1075;&#1086; &#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1074;&#1086; &#1074;&#1083;&#1072;&#1078;&#1085;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1077;
      </li>
    </ul>
    <p>
      <b>&#1055;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;:</b>
    </p>
    <p>
      1. &#1042;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; (&#1079;&#1072;&#1095;&#1080;&#1097;&#1077;&#1085;&#1085;&#1086;&#1077; &#1086;&#1090; &#1083;&#1072;&#1082;&#1072; &#1080; &#1087;&#1088;&#1086;&#1090;&#1105;&#1088;&#1090;&#1086;&#1077; &#1086;&#1090; &#1075;&#1088;&#1103;&#1079;&#1080;) &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1079;&#1072;&#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1086;.
    </p>
    <p>
      2. &#1042; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1085;&#1072; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1077; &#1072;&#1083;&#1084;&#1072;&#1079;&#1085;&#1099;&#1084; &#1085;&#1086;&#1078;&#1086;&#1084; &#1080;&#1083;&#1080; &#1085;&#1086;&#1078;&#1086;&#1084; &#1080;&#1079; &#1090;&#1074;&#1105;&#1088;&#1076;&#1086;&#1081; &#1089;&#1090;&#1072;&#1083;&#1080; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1087;&#1077;&#1088;&#1077;&#1095;&#1085;&#1072;&#1103; &#1084;&#1080;&#1082;&#1088;&#1086;&#1094;&#1072;&#1088;&#1072;&#1087;&#1080;&#1085;&#1072;.
    </p>
    <p>
      3. &#1050; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1091; &#1087;&#1088;&#1080;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1072;&#1082;&#1086;&#1077; &#1091;&#1089;&#1080;&#1083;&#1080;&#1077;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1085;&#1086; &#1090;&#1088;&#1077;&#1089;&#1085;&#1091;&#1083;&#1086; &#1087;&#1086; &#1087;&#1086;&#1094;&#1072;&#1088;&#1072;&#1087;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; &#1084;&#1077;&#1089;&#1090;&#1091;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1050;&#1088;&#1091;&#1075;&#1086;&#1074;&#1086;&#1081; &#1085;&#1086;&#1078;</b>
    </p>
    <ul>
      <li>
        &#1056;&#1077;&#1089;&#1091;&#1088;&#1089; &#1082;&#1088;&#1091;&#1075;&#1086;&#1074;&#1086;&#1075;&#1086; 16-&#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1085;&#1086;&#1078;&#1072; &#1091; &#1082;&#1080;&#1090;&#1072;&#1081;&#1089;&#1082;&#1086;&#1075;&#1086; &#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1076;&#1086;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086; &#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1080;&#1081;:

        <ul>
          <li>
            &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1095;&#1072;&#1089;&#1090;&#1086; (&#1087;&#1086; &#1089;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1102; &#1089; &#1092;&#1091;&#1076;&#1078;&#1080;&#1082;&#1091;&#1088;&#1086;&#1074;&#1089;&#1082;&#1080;&#1084;) &#1087;&#1086;&#1074;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1091;&#1102; &#1087;&#1086;&#1079;&#1080;&#1094;&#1080;&#1102;, &#1080;&#1085;&#1072;&#1095;&#1077; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1090; &#1087;&#1083;&#1086;&#1093;&#1086; &#1082;&#1086;&#1083;&#1086;&#1090;&#1100;
          </li>
          <li>
            &#1050;&#1086;&#1075;&#1076;&#1072; &#1085;&#1086;&#1078; &#1087;&#1088;&#1086;&#1096;&#1105;&#1083; &#1087;&#1086;&#1083;&#1085;&#1099;&#1081; &#1086;&#1073;&#1086;&#1088;&#1086;&#1090;, &#1077;&#1075;&#1086; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1084; &#1088;&#1077;&#1075;&#1091;&#1083;&#1080;&#1088;&#1086;&#1074;&#1086;&#1095;&#1085;&#1099;&#1084; &#1074;&#1080;&#1085;&#1090;&#1086;&#1084; &#1087;&#1086;&#1076;&#1085;&#1080;&#1084;&#1072;&#1102;&#1090; &#1085;&#1072; &#1082;&#1072;&#1082;&#1080;&#1077;-&#1090;&#1086; &#1084;&#1080;&#1082;&#1088;&#1086;&#1085;&#1099; &#1080; &#1086;&#1085; &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074;&#1090;&#1086;&#1088;&#1086;&#1081; &#1086;&#1073;&#1086;&#1088;&#1086;&#1090;
          </li>
          <li>
            &#1055;&#1086;&#1089;&#1083;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086; &#8212; &#1074;&#1090;&#1086;&#1088;&#1086;&#1077; &#1087;&#1086;&#1076;&#1085;&#1103;&#1090;&#1080;&#1077; &#1080; &#1090;&#1088;&#1077;&#1090;&#1080;&#1081; &#1086;&#1073;&#1086;&#1088;&#1086;&#1090;
          </li>
          <li>
            &#1087;&#1086;&#1090;&#1086;&#1084; &#1079;&#1072;&#1084;&#1077;&#1085;&#1072; &#1085;&#1086;&#1078;&#1072;
          </li>
        </ul>
      </li>
      <li>
        &#1055;&#1086;&#1083;&#1085;&#1099;&#1081; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089; &#1093;&#1086;&#1088;&#1086;&#1096;&#1077;&#1075;&#1086; &#1103;&#1087;&#1086;&#1085;&#1089;&#1082;&#1086;&#1075;&#1086; &#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#8212; &#1075;&#1076;&#1077;-&#1090;&#1086; <b>48000</b>&#160; &#1089;&#1082;&#1086;&#1083;&#1086;&#1074;
      </li>
    </ul>
  </body>
</html></richcontent>
