<node TEXT="1. Разделка кабеля" ID="ID_1148017204" CREATED="1554318441621" MODIFIED="1554555843767"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1056;&#1072;&#1079;&#1076;&#1077;&#1083;&#1082;&#1072; &#1080; &#1084;&#1086;&#1085;&#1090;&#1072;&#1078; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1074; &#1084;&#1091;&#1092;&#1090;&#1091;</b>
    </p>
    <ul>
      <li>
        &#1055;&#1088;&#1080; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1082;&#1077; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1076;&#1083;&#1080;&#1085;&#1091; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;. &#1054;&#1085;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1085;&#1077; &#1084;&#1077;&#1085;&#1077;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1081; &#1074; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1080;, &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1101;&#1090;&#1086; <b>1,5 - 2 &#1084;&#1077;&#1090;&#1088;&#1072;</b>. &#1047;&#1072;&#1087;&#1072;&#1089; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1085;&#1091;&#1078;&#1077;&#1085; &#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1073;&#1099;&#1083; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086;&#1088; &#1076;&#1083;&#1103; &#171;&#1084;&#1072;&#1085;&#1105;&#1074;&#1088;&#1086;&#1074;&#187; &#1087;&#1088;&#1080; &#1091;&#1082;&#1083;&#1072;&#1076;&#1082;&#1077;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1084;&#1086;&#1078;&#1085;&#1086; &#1073;&#1099;&#1083;&#1086; &#171;&#1089;&#1099;&#1075;&#1088;&#1072;&#1090;&#1100;&#187; &#1087;&#1086; &#1076;&#1083;&#1080;&#1085;&#1077; &#1080; &#1082;&#1088;&#1072;&#1089;&#1080;&#1074;&#1086; &#1091;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1074;&#1089;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1074; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1091;
      </li>
    </ul>
    <p>
      <b>0.</b>&#160;&#1045;&#1089;&#1083;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1076;&#1086;&#1083;&#1075;&#1086; &#1093;&#1088;&#1072;&#1085;&#1080;&#1083;&#1089;&#1103; &#1074;&#1086; &#1074;&#1083;&#1072;&#1078;&#1085;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1077; &#1073;&#1077;&#1079; &#1075;&#1080;&#1076;&#1088;&#1086;&#1080;&#1079;&#1086;&#1083;&#1103;&#1094;&#1080;&#1080; &#1090;&#1086;&#1088;&#1094;&#1072; &#8211; <b>&#1086;&#1090;&#1088;&#1077;&#1079;&#1072;&#1090;&#1100; &#1080; &#1074;&#1099;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; 1 &#1084;&#1077;&#1090;&#1088; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;</b>. &#1054;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; &#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1080; &#1090;&#1077;&#1088;&#1103;&#1102;&#1090; &#1089;&#1074;&#1086;&#1080; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1087;&#1088;&#1080; &#1076;&#1083;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1084; &#1074;&#1086;&#1079;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1080; &#1074;&#1083;&#1072;&#1075;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1042;&#1085;&#1077;&#1096;&#1085;&#1103;&#1103; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1072; &#1080; &#1090;&#1088;&#1086;&#1089;. </b>
    </p>
    <ol>
      <li>
        &#1044;&#1083;&#1103; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1082;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084; <b>&#1085;&#1086;&#1078;-&#1089;&#1090;&#1088;&#1080;&#1087;&#1087;&#1077;&#1088;</b>&#160;&#8211; &#1083;&#1080;&#1073;&#1086; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;, &#1083;&#1080;&#1073;&#1086; &#1090;&#1086;&#1090;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1082;&#1080; &#1089;&#1080;&#1083;&#1086;&#1074;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;
      </li>
      <li>
        <b>&#1058;&#1086;&#1083;&#1097;&#1080;&#1085;&#1072; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1072; &#1090;&#1086;&#1095;&#1085;&#1086;</b>. &#1045;&#1089;&#1083;&#1080; &#1086;&#1085; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1089;&#1103; &#1089;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1075;&#1083;&#1091;&#1073;&#1086;&#1082;&#1080;&#1084; &#8211; &#1077;&#1089;&#1090;&#1100; &#1088;&#1080;&#1089;&#1082; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072;&#1090;&#1100; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;, &#1080;&#1083;&#1080; &#1078;&#1077; &#1079;&#1072;&#1090;&#1091;&#1087;&#1080;&#1090;&#1100; &#1083;&#1077;&#1079;&#1074;&#1080;&#1077; &#1085;&#1086;&#1078;&#1072; &#1086; &#1073;&#1088;&#1086;&#1085;&#1102;. &#1045;&#1089;&#1083;&#1080; &#1078;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079; &#1073;&#1091;&#1076;&#1077;&#1090; &#1084;&#1077;&#1083;&#1082;&#1080;&#1084; &#8211; &#1087;&#1088;&#1080;&#1076;&#1077;&#1090;&#1089;&#1103; &#1090;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100; &#1074;&#1088;&#1077;&#1084;&#1103;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1086;&#1076;&#1088;&#1072;&#1090;&#1100; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1091;. &#1055;&#1088;&#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1077; &#1089; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084;&#1080; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;&#1081; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; <b>&#1087;&#1088;&#1086;&#1073;&#1091;&#1081;&#1090;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079; &#1085;&#1072; &#1082;&#1086;&#1085;&#1095;&#1080;&#1082;&#1077; &#1085;&#1086;&#1074;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;</b>&#160;&#8211; &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100;, &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086; &#1083;&#1080; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1072; &#1090;&#1086;&#1083;&#1097;&#1080;&#1085;&#1072; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072;.
      </li>
      <li>
        &#1042;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1085;&#1091;&#1078;&#1085;&#1091;&#1102; &#1090;&#1086;&#1083;&#1097;&#1080;&#1085;&#1091; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072;, &#1079;&#1072;&#1082;&#1088;&#1077;&#1087;&#1083;&#1103;&#1077;&#1084; &#1085;&#1086;&#1078; &#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077; &#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1088;&#1072;&#1079; (5-10) &#1087;&#1086;&#1074;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1077;&#1084; &#1074;&#1086;&#1082;&#1088;&#1091;&#1075; &#1086;&#1089;&#1080;. &#1055;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; <b>&#1082;&#1088;&#1091;&#1075;&#1086;&#1074;&#1086;&#1081; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;</b>
      </li>
      <li>
        &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1086;&#1090; &#1085;&#1077;&#1075;&#1086; &#1076;&#1077;&#1083;&#1072;&#1077;&#1084; <b>&#1076;&#1074;&#1072; &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1100;&#1085;&#1099;&#1093;</b>&#160;&#1074; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1085;&#1094;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#8211; &#1080; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1072; &#1088;&#1072;&#1089;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; 2 &#1087;&#1086;&#1083;&#1086;&#1074;&#1080;&#1085;&#1082;&#1080;
      </li>
      <li>
        &#1058;&#1088;&#1086;&#1089; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1074;&#1077;&#1089;&#1072; &#1074; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;&#1093; &#1090;&#1080;&#1087;&#1072; &#171;&#1074;&#1086;&#1089;&#1100;&#1084;&#1077;&#1088;&#1082;&#1072;&#187; &#1087;&#1077;&#1088;&#1077;&#1082;&#1091;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1088;&#1086;&#1089;&#1086;&#1082;&#1091;&#1089;&#1072;&#1084;&#1080;, &#1077;&#1075;&#1086; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1072; &#1086;&#1090; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1086;&#1090;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1085;&#1086;&#1078;&#1086;&#1084;.
      </li>
    </ol>
    <p>
      <b>2. &#1056;&#1072;&#1079;&#1076;&#1077;&#1083;&#1082;&#1072; &#1073;&#1088;&#1086;&#1085;&#1080;, &#1075;&#1086;&#1092;&#1088;&#1086;&#1073;&#1088;&#1086;&#1085;&#1080; &#1080; &#1082;&#1077;&#1074;&#1083;&#1072;&#1088;&#1072;. </b>
    </p>
    <ol>
      <li>
        &#1042; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1074;&#1080;&#1076;&#1072; &#1084;&#1091;&#1092;&#1090;&#1099; &#1082;&#1077;&#1074;&#1083;&#1072;&#1088;, &#1075;&#1086;&#1092;&#1088;&#1086;&#1073;&#1088;&#1086;&#1085;&#1102; &#1080;&#1083;&#1080; &#1073;&#1088;&#1086;&#1085;&#1102; &#1080;&#1079; &#1087;&#1088;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074;&#1099;&#1088;&#1077;&#1079;&#1072;&#1090;&#1100; &#1085;&#1077; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;, <b>&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1074; &#1082;&#1072;&#1082;&#1091;&#1102;-&#1090;&#1086; &#1095;&#1072;&#1089;&#1090;&#1100; &#1076;&#1083;&#1103; &#1082;&#1088;&#1077;&#1087;&#1083;&#1077;&#1085;&#1080;&#1103;</b>
      </li>
      <li>
        &#1058;&#1072;&#1082;&#1078;&#1077; &#1073;&#1088;&#1086;&#1085;&#1103; &#1080; &#1075;&#1086;&#1092;&#1088;&#1086;&#1073;&#1088;&#1086;&#1085;&#1103; &#1084;&#1086;&#1075;&#1091;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; <b>&#1076;&#1083;&#1103; &#1079;&#1072;&#1079;&#1077;&#1084;&#1083;&#1077;&#1085;&#1080;&#1103; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;</b>&#160;&#8211; &#1090;&#1072;&#1082;&#1078;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1086;&#1090;&#1088;&#1077;&#1079;&#1086;&#1082;.
      </li>
      <li>
        <b>&#1041;&#1088;&#1086;&#1085;&#1103; &#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084;&#1080; &#1087;&#1088;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1072;&#1084;&#1080;.</b>&#160;&#1051;&#1091;&#1095;&#1096;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; &#1090;&#1072;&#1082;&#1091;&#1102; &#1073;&#1088;&#1086;&#1085;&#1102; &#1074;&#1099;&#1082;&#1091;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100; <b>&#1090;&#1088;&#1086;&#1089;&#1086;&#1082;&#1091;&#1089;&#1072;&#1084;&#1080;</b>, &#1087;&#1086; 3-4 &#1087;&#1088;&#1091;&#1090;&#1072;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1073;&#1086;&#1082;&#1086;&#1088;&#1077;&#1079;&#1099;, &#1085;&#1086; &#1091;&#1089;&#1080;&#1083;&#1080;&#1081; &#1080; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1074; &#1101;&#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1090;&#1088;&#1072;&#1090;&#1080;&#1090;&#1089;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;
      </li>
      <li>
        <b>&#1041;&#1088;&#1086;&#1085;&#1103; &#1075;&#1086;&#1092;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1081; &#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1083;&#1077;&#1085;&#1090;&#1086;&#1081;.</b>&#160; &#1056;&#1072;&#1079;&#1076;&#1077;&#1083;&#1082;&#1072; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; &#1086;&#1089;&#1086;&#1073;&#1086;&#1081; &#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080;, &#1090;.&#1082;. &#1074;&#1084;&#1103;&#1074;&#1096;&#1072;&#1103;&#1089;&#1103; &#1087;&#1086;&#1076; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1084; &#1075;&#1086;&#1092;&#1088;&#1086;&#1073;&#1088;&#1086;&#1085;&#1103; &#1080;&#1083;&#1080; &#1077;&#1077; &#1086;&#1089;&#1090;&#1088;&#1099;&#1077; &#1082;&#1088;&#1072;&#1103; &#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1086;&#1074;&#1088;&#1077;&#1076;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;, &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1103; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;. &#1056;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072;&#1077;&#1090;&#1089;&#1103; <b>&#1091;&#1089;&#1080;&#1083;&#1077;&#1085;&#1085;&#1099;&#1084; &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1100;&#1085;&#1086; &#1087;&#1083;&#1091;&#1078;&#1082;&#1086;&#1074;&#1099;&#1084; &#1085;&#1086;&#1078;&#1086;&#1084;</b>
      </li>
      <li>
        <b>&#1050;&#1077;&#1074;&#1083;&#1072;&#1088;&#1086;&#1074;&#1072;&#1103; &#1073;&#1088;&#1086;&#1085;&#1103;.</b>&#160; &#1050;&#1077;&#1074;&#1083;&#1072;&#1088; &#1083;&#1091;&#1095;&#1096;&#1077; &#1085;&#1077; &#1088;&#1077;&#1079;&#1072;&#1090;&#1100; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1084;&#1080; &#1088;&#1077;&#1078;&#1091;&#1097;&#1080;&#1084; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1084;&#1077;&#1085;&#1090;&#1086;&#1084; &#8211; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086; &#1090;&#1091;&#1087;&#1080;&#1090;&#1089;&#1103;. &#1053;&#1072; <b>&#1085;&#1086;&#1078;&#1085;&#1080;&#1094;&#1072;&#1093; &#1076;&#1083;&#1103; &#1088;&#1077;&#1079;&#1082;&#1080; &#1082;&#1077;&#1074;&#1083;&#1072;&#1088;&#1072;</b>&#160; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; <b>&#1082;&#1077;&#1088;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1085;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080;</b>. &#1051;&#1080;&#1073;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1089;&#1103; <b>&#1090;&#1088;&#1086;&#1089;&#1086;&#1082;&#1091;&#1089;&#1072;&#1084;&#1080;</b>.
      </li>
    </ol>
    <p>
      <b>3. &#1042;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1077; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1080; &#1080; &#1075;&#1080;&#1076;&#1088;&#1086;&#1092;&#1086;&#1073;&#1085;&#1072;&#1103; &#1087;&#1088;&#1086;&#1087;&#1080;&#1090;&#1082;&#1072;.</b>&#160;&#1044;&#1083;&#1103; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072;&#1085;&#1080;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1081; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1080; (&#1086;&#1085;&#1072; &#1077;&#1089;&#1090;&#1100; &#1085;&#1077; &#1074;&#1086; &#1074;&#1089;&#1077;&#1093; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;&#1093;) &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;:
    </p>
    <ul>
      <li>
        &#1054;&#1073;&#1099;&#1095;&#1085;&#1099;&#1081; <b>&#1084;&#1072;&#1082;&#1077;&#1090;&#1085;&#1099;&#1081; &#1085;&#1086;&#1078;</b>&#160; (&#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1093;&#1086;&#1088;&#1086;&#1096;&#1080;&#1081; &#1086;&#1087;&#1099;&#1090; &#1080; &#1089;&#1085;&#1086;&#1088;&#1086;&#1074;&#1082;&#1072;, &#1090;.&#1082;. &#1074;&#1077;&#1083;&#1080;&#1082; &#1088;&#1080;&#1089;&#1082; &#1087;&#1086;&#1074;&#1088;&#1077;&#1076;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; &#1089; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;&#1084;)
      </li>
      <li>
        &#1058;&#1072;&#1082;&#1086;&#1081; &#1078;&#1077; <b>&#1085;&#1086;&#1078;-&#1089;&#1090;&#1088;&#1080;&#1087;&#1087;&#1077;&#1088;</b>, &#1082;&#1072;&#1082; &#1080; &#1076;&#1083;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1080;, &#1085;&#1086; &#1074;&#1099;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1091;&#1102; &#1090;&#1086;&#1083;&#1097;&#1080;&#1085;&#1091; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072;. &#1051;&#1091;&#1095;&#1096;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; &#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1087;&#1086;&#1076; &#1088;&#1091;&#1082;&#1086;&#1081; <b>&#1076;&#1074;&#1072; &#1085;&#1086;&#1078;&#1072;-&#1089;&#1090;&#1088;&#1080;&#1087;&#1087;&#1077;&#1088;&#1072;</b>&#160; &#8211; &#1086;&#1076;&#1080;&#1085; &#1089; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;&#1084;&#1080; &#1085;&#1072; &#1074;&#1085;&#1077;&#1096;&#1085;&#1102;&#1102; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1091; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#8211; &#1076;&#1083;&#1103; &#1073;&#1086;&#1083;&#1077;&#1077; &#1090;&#1086;&#1085;&#1082;&#1086;&#1075;&#1086; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1081; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1080;.
      </li>
      <li>
        &#1057;&#1090;&#1088;&#1080;&#1087;&#1087;&#1077;&#1088;-&#1087;&#1088;&#1080;&#1097;&#1077;&#1087;&#1082;&#1072;
      </li>
    </ul>
    <p>
      &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1087;&#1077;&#1088;&#1077;&#1076; &#1084;&#1086;&#1085;&#1090;&#1072;&#1078;&#1085;&#1080;&#1082;&#1086;&#1084; &#1086;&#1089;&#1090;&#1072;&#1102;&#1090;&#1089;&#1103; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; &#1089; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;&#1084;, &#1089;&#1074;&#1077;&#1088;&#1093;&#1091; &#1087;&#1086;&#1082;&#1088;&#1099;&#1090;&#1099;&#1077; &#1087;&#1083;&#1077;&#1085;&#1082;&#1086;&#1081;, &#1087;&#1077;&#1088;&#1077;&#1087;&#1083;&#1077;&#1090;&#1077;&#1085;&#1080;&#1077;&#1084; &#1085;&#1080;&#1090;&#1077;&#1081; &#1080; &#1075;&#1080;&#1076;&#1088;&#1086;&#1092;&#1086;&#1073;&#1086;&#1084; ( &#1074;&#1089;&#1077; &#1101;&#1090;&#1086; &#1074;&#1084;&#1077;&#1089;&#1090;&#1077;, &#1080;&#1083;&#1080; &#1078;&#1077; &#1074; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1082;&#1086;&#1084;&#1073;&#1080;&#1085;&#1072;&#1094;&#1080;&#1103;&#1093;).
    </p>
    <ol>
      <li>
        <b>&#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1084; &#1074; &#1086;&#1076;&#1085;&#1086;&#1088;&#1072;&#1079;&#1086;&#1074;&#1099;&#1093; &#1087;&#1077;&#1088;&#1095;&#1072;&#1090;&#1082;&#1072;&#1093;</b>&#160;(&#1093;&#1080;&#1088;&#1091;&#1088;&#1075;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093;, &#1087;&#1086;&#1083;&#1080;&#1101;&#1090;&#1080;&#1083;&#1077;&#1085;&#1086;&#1074;&#1099;&#1093; &#1080;&#1083;&#1080; &#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093;), &#1090;.&#1082;. &#1075;&#1080;&#1076;&#1088;&#1086;&#1092;&#1086;&#1073;&#1085;&#1072;&#1103; &#1089;&#1084;&#1072;&#1079;&#1082;&#1072; &#8211; &#1086;&#1095;&#1077;&#1085;&#1100; &#1085;&#1077;&#1087;&#1088;&#1080;&#1103;&#1090;&#1085;&#1072;&#1103; &#1080; &#1090;&#1088;&#1091;&#1076;&#1085;&#1086; &#1089;&#1084;&#1099;&#1074;&#1072;&#1077;&#1084;&#1072;&#1103; &#1089; &#1088;&#1091;&#1082; &#1078;&#1080;&#1076;&#1082;&#1086;&#1089;&#1090;&#1100;.
      </li>
      <li>
        &#1058;&#1086;&#1085;&#1082;&#1072;&#1103; &#1087;&#1083;&#1077;&#1085;&#1082;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085;&#1072; &#1077;&#1089;&#1090;&#1100; &#8211; &#1083;&#1077;&#1075;&#1082;&#1086; &#1089;&#1088;&#1077;&#1079;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1086;&#1078;&#1086;&#1084;
      </li>
      <li>
        &#1053;&#1080;&#1090;&#1082;&#1080; &#1091;&#1076;&#1072;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; &#1080;&#1083;&#1080; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; &#1082;&#1088;&#1102;&#1095;&#1082;&#1086;&#1084;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1077;&#1089;&#1090;&#1100; &#1085;&#1072; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1084;&#1086;&#1076;&#1077;&#1083;&#1103;&#1093; &#1085;&#1086;&#1078;&#1077;&#1081;-&#1089;&#1090;&#1088;&#1080;&#1087;&#1087;&#1077;&#1088;&#1086;&#1074;
      </li>
      <li>
        &#1041;&#1077;&#1088;&#1077;&#1084; &#1089;&#1072;&#1083;&#1092;&#1077;&#1090;&#1082;&#1080;, &#1078;&#1080;&#1076;&#1082;&#1086;&#1089;&#1090;&#1100; D-Gel (&#171;&#1072;&#1087;&#1077;&#1083;&#1100;&#1089;&#1080;&#1085;&#1082;&#1072;&#187;) &#8211; &#1077;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1073;&#1077;&#1085;&#1079;&#1080;&#1085;&#1086;&#1084; (&#1077;&#1089;&#1083;&#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1084; &#1085;&#1072; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1086;&#1084; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1077;) &#1080; &#1090;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1086;&#1095;&#1080;&#1097;&#1072;&#1077;&#1084; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; &#1086;&#1090; &#1074;&#1089;&#1077;&#1075;&#1086;
      </li>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077; &#1086;&#1073;&#1097;&#1077;&#1081; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080; &#1090;&#1086;&#1095;&#1085;&#1086; &#1090;&#1072;&#1082;&#1078;&#1077; &#1086;&#1095;&#1080;&#1097;&#1072;&#1077;&#1084; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1095;&#1077;&#1075;&#1086; &#1087;&#1088;&#1086;&#1090;&#1080;&#1088;&#1072;&#1077;&#1084; &#1089;&#1087;&#1080;&#1088;&#1090;&#1086;&#1084;
      </li>
      <li>
        <b><font color="#ff0000">&#1053;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1102;&#1090; &#1073;&#1086;&#1083;&#1077;&#1077; &#1073;&#1099;&#1089;&#1090;&#1088;&#1099;&#1081; &#1080; &#171;&#1095;&#1080;&#1089;&#1090;&#1099;&#1081;&#187; &#1084;&#1077;&#1090;&#1086;&#1076;:</font></b>&#160;&#1085;&#1077; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1099;&#1074;&#1072;&#1102;&#1090; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1076;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;, &#1086;&#1095;&#1080;&#1089;&#1090;&#1080;&#1074; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1091;&#1095;&#1072;&#1089;&#1090;&#1086;&#1082;, &#1089; &#1087;&#1086;&#1083;&#1084;&#1077;&#1090;&#1088;&#1072;. &#1053;&#1072; &#1085;&#1077;&#1084; &#1085;&#1072;&#1076;&#1082;&#1091;&#1089;&#1099;&#1074;&#1072;&#1102;&#1090; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; &#1080; &#1089;&#1090;&#1103;&#1075;&#1080;&#1074;&#1072;&#1102;&#1090; &#1074;&#1089;&#1077; &#1074;&#1084;&#1077;&#1089;&#1090;&#1077; &#8211; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;, &#1085;&#1080;&#1090;&#1082;&#1080;, &#1087;&#1083;&#1077;&#1085;&#1082;&#1091; &#1080; &#1090;.&#1076;. - &#1082;&#1072;&#1082; &#1095;&#1091;&#1083;&#1086;&#1082;. &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; &#1087;&#1088;&#1080; &#1074;&#1089;&#1077;&#1081; &#1101;&#1082;&#1086;&#1085;&#1086;&#1084;&#1080;&#1080; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1101;&#1090;&#1086;&#1090; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; &#1095;&#1088;&#1077;&#1074;&#1072;&#1090; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077;&#1084; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; , &#1077;&#1089;&#1083;&#1080; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1086;&#1077; &#1091;&#1089;&#1080;&#1083;&#1080;&#1077; &#1086;&#1082;&#1072;&#1078;&#1077;&#1090;&#1089;&#1103; &#1089;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084;. &#1054;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086; &#1101;&#1090;&#1086; &#1086;&#1087;&#1072;&#1089;&#1085;&#1086; &#1074; &#1079;&#1080;&#1084;&#1085;&#1077;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1075;&#1080;&#1076;&#1088;&#1086;&#1092;&#1086;&#1073;&#1085;&#1072;&#1103; &#1089;&#1084;&#1072;&#1079;&#1082;&#1072; &#1075;&#1091;&#1089;&#1090;&#1077;&#1077;&#1090;.
      </li>
    </ol>
    <p>
      <b>4. &#1056;&#1072;&#1079;&#1076;&#1077;&#1083;&#1099;&#1074;&#1072;&#1077;&#1084; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;.</b>&#160;
    </p>
    <ol>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1099;&#1081; <b>&#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1084;&#1086;&#1085;&#1086;&#1090;&#1091;&#1073;&#1085;&#1099;&#1081;</b>&#160;&#1080; &#1077;&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085; &#1074; &#1074;&#1080;&#1076;&#1077; &#1090;&#1074;&#1077;&#1088;&#1076;&#1086;&#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1082;&#1086;&#1074;&#1086;&#1081; &#1090;&#1088;&#1091;&#1073;&#1082;&#1080; &#8211; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1088;&#1091;&#1075;&#1086;&#1074;&#1086;&#1081; &#1085;&#1072;&#1076;&#1088;&#1077;&#1079; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084; &#1090;&#1088;&#1091;&#1073;&#1086;&#1088;&#1077;&#1079;&#1086;&#1084;&#160;&#1080; &#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1078;&#1085;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1087;&#1086;&#1074;&#1088;&#1077;&#1076;&#1080;&#1090;&#1100; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;, &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1085;&#1072;&#1076;&#1083;&#1072;&#1084;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;.
      </li>
      <li>
        &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1089; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077;&#1084; <b>&#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;</b>&#160;&#1074;&#1089;&#1077; &#1089;&#1083;&#1086;&#1078;&#1085;&#1077;&#1077;. &#1042;&#1086;-&#1087;&#1077;&#1088;&#1074;&#1099;&#1093;, &#1087;&#1086;&#1082;&#1072; &#1074;&#1099; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;&#1077; &#1089; &#1086;&#1076;&#1085;&#1080;&#1084;, &#1074;&#1072;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1080;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086; &#1083;&#1077;&#1079;&#1091;&#1090; &#1087;&#1086;&#1076; &#1088;&#1091;&#1082;&#1080;. &#1042;&#1086;-&#1074;&#1090;&#1086;&#1088;&#1099;&#1093;, &#1089;&#1072;&#1084; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1085;&#1072; &#1074;&#1077;&#1089;&#1091; &#1080; &#1101;&#1090;&#1086; &#1085;&#1077; &#1086;&#1095;&#1077;&#1085;&#1100; &#1091;&#1076;&#1086;&#1073;&#1085;&#1086;. &#1051;&#1091;&#1095;&#1096;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; <b>&#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1101;&#1090;&#1091; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091; &#1074;&#1076;&#1074;&#1086;&#1077;&#1084;</b>.
      </li>
      <li>
        &#1055;&#1091;&#1089;&#1090;&#1099;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;-&#1079;&#1072;&#1075;&#1083;&#1091;&#1096;&#1082;&#1080; &#1074;&#1099;&#1088;&#1077;&#1079;&#1072;&#1077;&#1084; &#1087;&#1086;&#1076; &#1082;&#1086;&#1088;&#1077;&#1085;&#1100;. &#1052;&#1086;&#1076;&#1091;&#1083;&#1080; &#1089; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;&#1084; &#1085;&#1072;&#1076;&#1082;&#1091;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; <b>&#1089;&#1090;&#1088;&#1080;&#1087;&#1087;&#1077;&#1088;&#1086;&#1084; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;</b>. &#1042;&#1072;&#1078;&#1085;&#1086; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1091;&#1102; &#1075;&#1083;&#1091;&#1073;&#1080;&#1085;&#1091; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072;.
      </li>
      <li>
        &#1053;&#1072; &#1089;&#1090;&#1088;&#1080;&#1087;&#1087;&#1077;&#1088;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; &#1077;&#1089;&#1090;&#1100; <b>&#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1086;&#1073;&#1072;&#1095;&#1082;&#1072;</b>, &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1102;&#1097;&#1072;&#1103; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1093;&#1086;&#1076;. &#1063;&#1072;&#1089;&#1090;&#1086; &#1073;&#1099;&#1074;&#1072;&#1077;&#1090; &#1090;&#1072;&#1082;, &#1095;&#1090;&#1086; &#1086;&#1085;&#1072; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1082;&#1072;&#1082; &#1088;&#1072;&#1079; &#1074; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1085;&#1072;&#1076;&#1082;&#1091;&#1089;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;. &#1042;&#1099; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090;&#1077; &#1088;&#1072;&#1079;&#1078;&#1072;&#1090;&#1100; &#1089;&#1090;&#1088;&#1080;&#1087;&#1087;&#1077;&#1088; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;, &#1077;&#1076;&#1080;&#1085;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; &#1086;&#1089;&#1074;&#1086;&#1073;&#1086;&#1076;&#1080;&#1090;&#1100; &#1092;&#1080;&#1082;&#1089;&#1072;&#1090;&#1086;&#1088; &#8211; &#1077;&#1097;&#1077; &#1088;&#1072;&#1079; &#1085;&#1072;&#1076;&#1082;&#1091;&#1089;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;, &#1095;&#1090;&#1086; &#1095;&#1088;&#1077;&#1074;&#1072;&#1090;&#1086; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077;&#1084; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1085;&#1091;&#1078;&#1085;&#1086; <b>&#1089;&#1083;&#1077;&#1076;&#1080;&#1090;&#1100; &#1079;&#1072; &#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;&#1084; &#1089;&#1086;&#1073;&#1072;&#1095;&#1082;&#1080;-&#1092;&#1080;&#1082;&#1089;&#1072;&#1090;&#1086;&#1088;&#1072;</b>
      </li>
      <li>
        &#1053;&#1077;&#1083;&#1100;&#1079;&#1103; &#1089;&#1090;&#1103;&#1075;&#1080;&#1074;&#1072;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; &#1089; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1089; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084; &#1091;&#1089;&#1080;&#1083;&#1080;&#1077;&#1084;, &#1101;&#1090;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1074;&#1088;&#1077;&#1076;&#1080;&#1090;&#1100; &#1080;&#1093; &#1080; &#1089;&#1082;&#1072;&#1078;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1089;&#1074;&#1103;&#1079;&#1080; &#1074; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1081;&#1096;&#1077;&#1084;. &#1051;&#1091;&#1095;&#1096;&#1077; &#1086;&#1089;&#1074;&#1086;&#1073;&#1086;&#1078;&#1076;&#1072;&#1090;&#1100; <b>&#1084;&#1077;&#1076;&#1083;&#1077;&#1085;&#1085;&#1086;, &#1095;&#1072;&#1089;&#1090;&#1103;&#1084;&#1080;</b>.
      </li>
    </ol>
    <p>
      <b>5. &#1054;&#1095;&#1080;&#1089;&#1090;&#1082;&#1072; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;.</b>&#160;&#1042;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1076;&#1083;&#1103; &#1084;&#1086;&#1085;&#1090;&#1072;&#1078;&#1072; &#1080; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1080;&#1076;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086; &#1094;&#1077;&#1083;&#1099;&#1084;&#1080; &#1080; &#1080;&#1076;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086; &#1095;&#1080;&#1089;&#1090;&#1099;&#1084;&#1080;.
    </p>
    <ol>
      <li>
        <b>&#1055;&#1088;&#1086;&#1090;&#1080;&#1088;&#1072;&#1077;&#1084;</b>&#160;&#1080;&#1093; &#1074; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1081; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080;, &#1076;&#1086;&#1088;&#1086;&#1075;&#1080;&#1077; &#1089;&#1072;&#1083;&#1092;&#1077;&#1090;&#1082;&#1080; &#1085;&#1072; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1077; &#1095;&#1072;&#1089;&#1090;&#1086; &#1079;&#1072;&#1084;&#1077;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1081; &#1090;&#1091;&#1072;&#1083;&#1077;&#1090;&#1085;&#1086;&#1081; &#1073;&#1091;&#1084;&#1072;&#1075;&#1086;&#1081; (&#1085;&#1077;&#1072;&#1088;&#1086;&#1084;&#1072;&#1090;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1081;)

        <ol>
          <li>
            &#1041;&#1077;&#1079;&#1074;&#1086;&#1088;&#1089;&#1086;&#1074;&#1099;&#1077; <b>&#1089;&#1091;&#1093;&#1080;&#1077;</b>&#160; &#1089;&#1072;&#1083;&#1092;&#1077;&#1090;&#1082;&#1080; - 3-4 &#1096;&#1090;&#1091;&#1082;&#1080; &#8211; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1084; &#1075;&#1080;&#1076;&#1088;&#1086;&#1092;&#1086;&#1073;
          </li>
          <li>
            &#1041;&#1077;&#1079;&#1074;&#1086;&#1088;&#1089;&#1086;&#1074;&#1099;&#1077; &#1089;&#1072;&#1083;&#1092;&#1077;&#1090;&#1082;&#1080;, <b>&#1089;&#1084;&#1086;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1089;&#1087;&#1080;&#1088;&#1090;&#1086;&#1084;</b>&#160;(&#1101;&#1090;&#1080;&#1083;, &#1080;&#1079;&#1086;&#1087;&#1088;&#1086;&#1087;&#1080;&#1083;)
          </li>
        </ol>
      </li>
      <li>
        &#1042;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; <b>&#1090;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1086;&#1089;&#1084;&#1072;&#1090;&#1088;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1087;&#1088;&#1077;&#1076;&#1084;&#1077;&#1090; &#1094;&#1077;&#1083;&#1086;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080;</b>. &#1044;&#1072;&#1078;&#1077; &#1077;&#1089;&#1083;&#1080; &#1083;&#1072;&#1082;&#1086;&#1074;&#1086;&#1077; &#1087;&#1086;&#1082;&#1088;&#1099;&#1090;&#1080;&#1077; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1086; &#1089;&#1086;&#1074;&#1089;&#1077;&#1084; &#1085;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#8211; &#1083;&#1091;&#1095;&#1096;&#1077; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1079;&#1072;&#1085;&#1086;&#1074;&#1086;. &#1047;&#1072;&#1090;&#1088;&#1072;&#1090;&#1099; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1075;&#1086;&#1088;&#1072;&#1079;&#1076;&#1086; &#1085;&#1080;&#1078;&#1077;, &#1095;&#1077;&#1084; &#1077;&#1089;&#1083;&#1080; &#1087;&#1088;&#1080;&#1076;&#1077;&#1090;&#1089;&#1103; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1102;&#1076;&#1072; &#1095;&#1077;&#1088;&#1077;&#1079; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1103;&#1090;&#1100; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1086;&#1090; &#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1076;&#1086; &#1082;&#1086;&#1085;&#1094;&#1072;.
      </li>
    </ol>
