      <b>&#1042;&#1074;&#1072;&#1088;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090;&#1085;&#1099;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;, &#1085;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072;&#1103; &#1077;&#1075;&#1086;. </b>
