    <ol>
      <li>
        &#1050;&#1072;&#1073;&#1077;&#1083;&#1100; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;
