      <li>
        &#1052;&#1086;&#1076;&#1091;&#1083;&#1080; &#1072;&#1082;&#1082;&#1091;&#1088;&#1072;&#1090;&#1085;&#1086; &#1074;&#1074;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1074; &#171;&#1086;&#1074;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081;&#187; &#1074;&#1074;&#1086;&#1076; &#1084;&#1091;&#1092;&#1090;&#1099; (&#1074; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1081; &#1082;&#1088;&#1091;&#1075;&#1083;&#1099;&#1081; &#1085;&#1077; &#1074;&#1086;&#1081;&#1076;&#1091;&#1090; &#8212; &#1089;&#1083;&#1086;&#1084;&#1072;&#1102;&#1090;&#1089;&#1103;), &#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1074;&#1074;&#1086;&#1076;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1086;&#1084;&#1087;&#1083;&#1077;&#1082;&#1090; &#1080;&#1079; &#1090;&#1077;&#1088;&#1084;&#1086;&#1091;&#1089;&#1072;&#1076;&#1082;&#1080; &#1080; &#1084;&#1077;&#1090;&#1072;&#1083;&#1083;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1082;&#1083;&#1080;&#1087;&#1089;&#1099; &#1089; &#1073;&#1083;&#1086;&#1082;&#1086;&#1084; &#1090;&#1077;&#1088;&#1084;&#1086;&#1082;&#1083;&#1077;&#1103;. &#1069;&#1090;&#1086;&#1090; &#1082;&#1083;&#1077;&#1081; &#1087;&#1088;&#1080; &#1091;&#1089;&#1072;&#1076;&#1082;&#1077; &#1086;&#1090; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1081; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1099; &#1088;&#1072;&#1089;&#1087;&#1083;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080; &#1079;&#1072;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1089;&#1090;&#1074;&#1086; &#1084;&#1077;&#1078;&#1076;&#1091; &#1076;&#1074;&#1091;&#1093; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;&#1081;, &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1080;&#1074;&#1072;&#1103; &#1075;&#1077;&#1088;&#1084;&#1077;&#1090;&#1080;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;
      </li>
      <li>
        &#1090;&#1086;&#1090; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1085;&#1072;&#1076;&#1086; &#1074;&#1074;&#1072;&#1088;&#1080;&#1090;&#1100;&#1089;&#1103;, &#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1072;&#1077;&#1090;&#1089;&#1103;
      </li>
      <li>
        &#1090;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1080;&#1079; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1086;&#1090;&#1087;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077; &#1085;&#1072;&#1076;&#1086;, &#1089;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090;&#1086;&#1084;
      </li>
      <li>
        &#1072; &#1090;&#1077;, &#1095;&#1090;&#1086; &#1085;&#1072;&#1084; &#1085;&#1091;&#1078;&#1085;&#1099; &#8212; &#1087;&#1088;&#1080;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1082; &#171;&#1086;&#1090;&#1087;&#1072;&#1081;&#1085;&#1086;&#1084;&#1091;&#187; (&#1086;&#1090;&#1074;&#1077;&#1090;&#1074;&#1083;&#1103;&#1102;&#1097;&#1077;&#1084;&#1091;&#1089;&#1103;) &#1082;&#1072;&#1073;&#1077;&#1083;&#1102;
      </li>
      <li>
        &#1054;&#1095;&#1077;&#1085;&#1100; &#1088;&#1077;&#1076;&#1082;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1085;&#1091;&#1090;&#1100; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1103;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1072;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1079;&#1103;&#1090;&#1100; &#1080;&#1079; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;, &#1085;&#1086; &#1088;&#1077;&#1079;&#1072;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; (&#1087;&#1086; &#1085;&#1077;&#1084;&#1091; &#1080;&#1076;&#1105;&#1090; &#1074;&#1072;&#1078;&#1085;&#1072;&#1103; &#1089;&#1074;&#1103;&#1079;&#1100;). &#1058;&#1086;&#1075;&#1076;&#1072; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1084;&#1087;&#1083;&#1077;&#1082;&#1090; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1100;&#1085;&#1086;&#1081; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1082;&#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;: &#1089; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1087;&#1088;&#1086;&#1076;&#1086;&#1083;&#1100;&#1085;&#1086; &#1089;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;&#1089;&#1103; &#171;&#1092;&#1072;&#1089;&#1082;&#1072;&#187;, &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1080;&#1079; &#1085;&#1077;&#1075;&#1086; &#1080;&#1079;&#1074;&#1083;&#1077;&#1082;&#1072;&#1102;&#1090;&#1089;&#1103;, &#1087;&#1088;&#1086;&#1090;&#1080;&#1088;&#1072;&#1102;&#1090;&#1089;&#1103; &#1086;&#1090; &#1075;&#1080;&#1076;&#1088;&#1086;&#1092;&#1086;&#1073;&#1072; &#1080; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103;. &#1058;&#1077;, &#1095;&#1090;&#1086; &#1085;&#1072;&#1084; &#1085;&#1091;&#1078;&#1085;&#1099;, &#1088;&#1077;&#1078;&#1091;&#1090;&#1089;&#1103; &#1080; &#1074;&#1072;&#1088;&#1103;&#1090;&#1089;&#1103; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1085;&#1086; &#1089;&#1093;&#1077;&#1084;&#1077;, &#1072; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1091;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1091;. &#1042; &#1101;&#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1079;&#1072;&#1074;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1085;&#1077;&#1088;&#1072;&#1079;&#1088;&#1077;&#1079;&#1085;&#1086;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;, &#1076;&#1083;&#1080;&#1085;&#1072; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; <b>2-3 &#1084;</b>
      </li>
    </ol>
  </body>
</html></richcontent>
