  </head>
  <body>
    <p>
      <a href="#ID_679118521">&#1054;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1084;&#1091;&#1092;&#1090;&#1072;</a>&#160; &#160;<a href="#ID_1176216305">&#1052;&#1086;&#1085;&#1090;&#1072;&#1078; &#1084;&#1091;&#1092;&#1090;&#1099;</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1088;&#1080; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1082;&#1077; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;&#1081; &#1074;&#1072;&#1078;&#1085;&#1086; &#1074;&#1099;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1076;&#1083;&#1080;&#1085;&#1099; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1086;&#1074; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1080; &#1089; &#1090;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1080; &#1082; &#1084;&#1091;&#1092;&#1090;&#1077;.</b>&#160;&#1042;&#1089;&#1105; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1081; &#1084;&#1091;&#1092;&#1090;&#1099; &#1080; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;:
    </p>
    <ul>
      <li>
        &#1042; &#1086;&#1076;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1085;&#1072;&#1076;&#1086;&#1073;&#1080;&#1090;&#1100;&#1089;&#1103; &#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1076;&#1083;&#1080;&#1085;&#1085;&#1099;&#1081; <b>&#1089;&#1080;&#1083;&#1086;&#1074;&#1086;&#1081; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;</b>, &#1095;&#1090;&#1086;&#1073;&#1099; &#1079;&#1072;&#1082;&#1088;&#1077;&#1087;&#1080;&#1090;&#1100; &#1077;&#1075;&#1086; &#1074; &#1084;&#1091;&#1092;&#1090;&#1077;/&#1082;&#1088;&#1086;&#1089;&#1089;&#1077;, &#1074; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1086;&#1085; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103;;
      </li>
      <li>
        &#1042; &#1086;&#1076;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1080;&#1079; <b>&#1082;&#1077;&#1074;&#1083;&#1072;&#1088;&#1072;</b>&#160;&#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1087;&#1083;&#1077;&#1090;&#1105;&#1090;&#1089;&#1103; &#1082;&#1086;&#1089;&#1080;&#1095;&#1082;&#1072; &#1080; &#1079;&#1072;&#1078;&#1080;&#1084;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1076; &#1074;&#1080;&#1085;&#1090;, &#1074; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1082;&#1077;&#1074;&#1083;&#1072;&#1088; &#1086;&#1090;&#1088;&#1077;&#1079;&#1072;&#1077;&#1090;&#1089;&#1103;.
      </li>
    </ul>
    <p>
      <b>&#1052;&#1086;&#1085;&#1090;&#1072;&#1078; &#1074; &#1084;&#1091;&#1092;&#1090;&#1091;</b>&#160; &#1084;&#1086;&#1078;&#1085;&#1086; (&#1076;&#1072;&#1078;&#1077; &#1091;&#1076;&#1086;&#1073;&#1085;&#1077;&#1077;) &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; <b>&#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1082;&#1080; &#1054;&#1042;</b>
    </p>
    <ol>
      <li>
        &#1055;&#1077;&#1088;&#1077;&#1076; &#1079;&#1072;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077;&#1084; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1074; &#1084;&#1091;&#1092;&#1090;&#1091; &#1085;&#1072; &#1085;&#1077;&#1075;&#1086; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1085;&#1072;&#1076;&#1077;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1077;&#1088;&#1084;&#1086;&#1091;&#1089;&#1072;&#1076;&#1082;&#1072; (&#1079;&#1072; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1090;&#1077;&#1093; &#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1081;, &#1075;&#1076;&#1077; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1089;&#1099;&#1088;&#1086;&#1081; &#1088;&#1077;&#1079;&#1080;&#1085;&#1077;). &#1069;&#1090;&#1086; &#1087;&#1086;&#1083;&#1080;&#1101;&#1090;&#1080;&#1083;&#1077;&#1085;&#1086;&#1074;&#1072;&#1103; &#1090;&#1088;&#1091;&#1073;&#1082;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1086;&#1076; &#1074;&#1086;&#1079;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077;&#1084; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1081; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1099; &#171;&#1091;&#1089;&#1072;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;&#187; &#1080; &#1087;&#1083;&#1086;&#1090;&#1085;&#1086; &#1086;&#1073;&#1093;&#1074;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1080; &#1087;&#1072;&#1090;&#1088;&#1091;&#1073;&#1086;&#1082; &#1084;&#1091;&#1092;&#1090;&#1099;. &#1058;&#1077;&#1084; &#1089;&#1072;&#1084;&#1099;&#1084; &#1075;&#1077;&#1088;&#1084;&#1077;&#1090;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074;&#1093;&#1086;&#1076; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;. &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1101;&#1090;&#1086; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1092;&#1080;&#1082;&#1089;&#1072;&#1094;&#1080;&#1080;.
      </li>
      <li>
        &#1059;&#1089;&#1072;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1083;&#1091;&#1095;&#1096;&#1077; &#1087;&#1086;&#1089;&#1083;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082; &#1084;&#1091;&#1092;&#1090;&#1072; &#1089;&#1074;&#1072;&#1088;&#1077;&#1085;&#1072;
      </li>
      <li>
        &#1056;&#1072;&#1079;&#1076;&#1077;&#1083;&#1072;&#1085;&#1085;&#1099;&#1077; &#1082;&#1072;&#1073;&#1077;&#1083;&#1080; <b>&#1074;&#1074;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103;</b>&#160;&#1074; &#1084;&#1091;&#1092;&#1090;&#1091; &#1080;&#1083;&#1080; &#1082;&#1088;&#1086;&#1089;&#1089;, <b>&#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103;</b>&#160;(&#1088;&#1091;&#1082;&#1086;&#1074;&#1086;&#1076;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1077;&#1081; &#1087;&#1086; &#1084;&#1086;&#1085;&#1090;&#1072;&#1078;&#1091;), &#1072; &#1089;&#1072;&#1084;&#1072; &#1084;&#1091;&#1092;&#1090;&#1072; &#1080;&#1083;&#1080; &#1082;&#1088;&#1086;&#1089;&#1089; <b>&#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;</b>&#160;&#1085;&#1072; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1084; &#1089;&#1090;&#1086;&#1083;&#1077;
      </li>
      <li>
        &#1053;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1081; &#1101;&#1090;&#1072;&#1087; &#8211; <a href="#ID_218084524">&#1087;&#1086;&#1076;&#1075;&#1086;&#1090;&#1086;&#1074;&#1082;&#1072; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;</a>.
      </li>
    </ol>
  </body>
