  <body>
    <p>
      <b>0. &#1050;&#1072;&#1073;&#1077;&#1083;&#1100; &#1079;&#1072;&#1074;&#1077;&#1076;&#1077;&#1085; &#1074; &#1082;&#1088;&#1086;&#1089;&#1089; &#1080;&#1083;&#1080; &#1084;&#1091;&#1092;&#1090;&#1091;.</b>
    </p>
    <p>
      <b>1. &#1055;&#1088;&#1086;&#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; &#1080; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;.</b>&#160;
    </p>
    <ol>
      <li>
        &#1055;&#1091;&#1089;&#1090;&#1099;&#1096;&#1082;&#1080; (&#1086;&#1090;&#1088;&#1077;&#1079;&#1072;&#1077;&#1084; &#1087;&#1086;&#1076; &#1082;&#1086;&#1088;&#1077;&#1085;&#1100;)
      </li>
      <li>
        &#1056;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; &#1074; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;.

        <ol>
          <li>
            &#1055;&#1077;&#1088;&#1074;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; - <b>&#1082;&#1088;&#1072;&#1089;&#1085;&#1099;&#1081;</b>.
          </li>
          <li>
            &#1042;&#1090;&#1086;&#1088;&#1086;&#1081; - &#1088;&#1103;&#1076;&#1086;&#1084; &#1089; &#1082;&#1088;&#1072;&#1089;&#1085;&#1099;&#1084; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; <b>&#1094;&#1074;&#1077;&#1090;&#1085;&#1086;&#1081;</b>, &#1094;&#1074;&#1077;&#1090; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1083;&#1102;&#1073;&#1086;&#1081;, &#1085;&#1086; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1080;&#1084;&#1099;&#1081; (&#1089;&#1080;&#1085;&#1080;&#1081;, &#1079;&#1077;&#1083;&#1077;&#1085;&#1099;&#1081;, &#1078;&#1077;&#1083;&#1090;&#1099;&#1081; &#1080; &#1090;.&#1076;.)
          </li>
          <li>
            &#1058;&#1088;&#1077;&#1090;&#1080;&#1081; &#1080;&#1076;&#1077;&#1090; &#1087;&#1086;&#1089;&#1083;&#1077; &#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1074; &#1058;&#1054;&#1052; &#1046;&#1045; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1095;&#1072;&#1089;&#1086;&#1074;&#1086;&#1081; &#1089;&#1090;&#1088;&#1077;&#1083;&#1082;&#1080;
          </li>
          <li>
            &#1055;&#1086;&#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1077; - &#1090;&#1072;&#1082; &#1078;&#1077;
          </li>
        </ol>
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; <b>&#1085;&#1072;&#1082;&#1083;&#1077;&#1081;&#1082;&#1080;-&#1094;&#1080;&#1092;&#1077;&#1088;&#1082;&#1080; &#1086;&#1090; 0 &#1076;&#1086; 9</b>. &#1053;&#1072; &#1074;&#1089;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1080;&#1079; 1-&#1075;&#1086;, &#1082;&#1088;&#1072;&#1089;&#1085;&#1086;&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1084;&#1099; &#1082;&#1083;&#1077;&#1080;&#1084; &#1094;&#1080;&#1092;&#1088;&#1091; 1, &#1085;&#1072; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; 2-&#1075;&#1086; - &#1094;&#1080;&#1092;&#1088;&#1091; 2 &#1080; &#1090;.&#1076;. &#1044;&#1083;&#1103; &#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1073;&#1091;&#1084;&#1072;&#1078;&#1085;&#1099;&#1077; &#1080;&#1083;&#1080; &#1090;&#1088;&#1103;&#1087;&#1080;&#1095;&#1085;&#1099;&#1077; &#1085;&#1072;&#1082;&#1083;&#1077;&#1081;&#1082;&#1080;-&#1084;&#1072;&#1088;&#1082;&#1077;&#1088;&#1099;. &#1054;&#1085;&#1080; &#1095;&#1072;&#1089;&#1090;&#1086; &#1087;&#1088;&#1086;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1074;&#1080;&#1076;&#1077; &#1073;&#1083;&#1086;&#1082;&#1085;&#1086;&#1090;&#1080;&#1082;&#1072; &#1089; &#1083;&#1080;&#1089;&#1090;&#1072;&#1084;&#1080; &#1080;&#1083;&#1080; &#1074; &#1074;&#1080;&#1076;&#1077; &#1076;&#1077;&#1089;&#1103;&#1090;&#1080; &#1073;&#1072;&#1088;&#1072;&#1073;&#1072;&#1085;&#1095;&#1080;&#1082;&#1086;&#1074;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1072;&#1082;&#1088;&#1091;&#1095;&#1077;&#1085;&#1099; &#1083;&#1077;&#1085;&#1090;&#1099; &#1089; &#1094;&#1080;&#1092;&#1088;&#1072;&#1084;&#1080; &#1086;&#1090; 0 &#1076;&#1086; 9. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1074;&#1093;&#1086;&#1076;&#1103;&#1090; &#1074; &#1082;&#1086;&#1084;&#1087;&#1083;&#1077;&#1082;&#1090; &#1084;&#1091;&#1092;&#1090;, &#1088;&#1077;&#1078;&#1077; &#8212; &#1074; &#1082;&#1086;&#1084;&#1087;&#1083;&#1077;&#1082;&#1090; &#1082;&#1088;&#1086;&#1089;&#1089;&#1072;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1084;&#1099; &#1089;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1077;&#1084; &#1085;&#1077; &#1082;&#1072;&#1073;&#1077;&#1083;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1086;&#1073;&#1086;&#1081; (&#1084;&#1091;&#1092;&#1090;&#1072;), &#1072; <b>&#1082;&#1072;&#1073;&#1077;&#1083;&#1100; - &#1089; &#1087;&#1080;&#1075;&#1090;&#1077;&#1081;&#1083;&#1072;&#1084;&#1080; (&#1082;&#1088;&#1086;&#1089;&#1089;)</b>, &#1090;&#1086; &#1074;&#1089;&#1077; <b>&#1087;&#1080;&#1075;&#1090;&#1077;&#1081;&#1083;&#1099; &#1090;&#1086;&#1078;&#1077; &#1083;&#1091;&#1095;&#1096;&#1077; &#1087;&#1088;&#1086;&#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;</b>. &#1047;&#1072; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1090;&#1077;&#1093; &#1082;&#1088;&#1086;&#1089;&#1089;&#1086;&#1074;, &#1075;&#1076;&#1077; &#1086;&#1073; &#1101;&#1090;&#1086;&#1084; &#1087;&#1086;&#1079;&#1072;&#1073;&#1086;&#1090;&#1080;&#1083;&#1089;&#1103; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;. &#1055;&#1086;&#1090;&#1088;&#1072;&#1090;&#1080;&#1083;&#1080; 10 &#1084;&#1080;&#1085;&#1091;&#1090; - &#1089;&#1101;&#1082;&#1086;&#1085;&#1086;&#1084;&#1080;&#1083;&#1080; &#1084;&#1072;&#1089;&#1089;&#1091; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1080; &#1085;&#1077;&#1088;&#1074;&#1086;&#1074;.
      </li>
    </ol>
    <p>
      <b>2. &#1054;&#1090;&#1084;&#1077;&#1088;&#1103;&#1077;&#1084; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1076;&#1083;&#1103; &#1091;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080; &#1074; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1091;.</b>&#160;
    </p>
    <ol>
      <li>
        &#1047;&#1072;&#1082;&#1088;&#1077;&#1087;&#1083;&#1103;&#1077;&#1084; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; <b>&#1074; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1077; &#1089;&#1090;&#1103;&#1078;&#1082;&#1072;&#1084;&#1080;</b>. &#1046;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1074; &#1084;&#1077;&#1089;&#1090;&#1077; &#1079;&#1072;&#1082;&#1088;&#1077;&#1087;&#1083;&#1077;&#1085;&#1080;&#1103; &#1086;&#1073;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1080;&#1079;&#1086;&#1083;&#1077;&#1085;&#1090;&#1086;&#1081;, &#1080;&#1085;&#1072;&#1095;&#1077; &#1086;&#1085; &#1083;&#1077;&#1075;&#1082;&#1086; &#1074;&#1099;&#1089;&#1082;&#1086;&#1095;&#1080;&#1090; &#1080;&#1079; &#1085;&#1077;&#1075;&#1086;. &#1053;&#1072; &#1087;&#1083;&#1086;&#1093;&#1086; &#1086;&#1095;&#1080;&#1097;&#1077;&#1085;&#1085;&#1091;&#1102; &#1086;&#1090; &#1075;&#1080;&#1076;&#1088;&#1086;&#1092;&#1086;&#1073;&#1072; &#1087;&#1086;&#1074;&#1077;&#1088;&#1093;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1082;&#1089;&#1090;&#1072;&#1090;&#1080;, &#1080;&#1079;&#1086;&#1083;&#1077;&#1085;&#1090;&#1072; &#1090;&#1086;&#1083;&#1082;&#1086;&#1084; &#1085;&#1077; &#1087;&#1088;&#1080;&#1082;&#1083;&#1077;&#1080;&#1090;&#1089;&#1103;
      </li>
      <li>
        &#1054;&#1090;&#1084;&#1077;&#1088;&#1103;&#1077;&#1084; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1076;&#1083;&#1103; &#1091;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080; &#1074; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1091;. &#1055;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1087;&#1086;&#1084;&#1085;&#1080;&#1084;, &#1095;&#1090;&#1086; &#1087;&#1091;&#1090;&#1100; &#1091;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080; &#1085;&#1091;&#1078;&#1077;&#1085; &#1089;&#1072;&#1084;&#1099;&#1081; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086;&#1081; - &#1073;&#1077;&#1079; &#1089;&#1083;&#1086;&#1078;&#1085;&#1099;&#1093; &#1080;&#1079;&#1075;&#1080;&#1073;&#1086;&#1074;. <b>&#1051;&#1091;&#1095;&#1096;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; - &#1087;&#1086; &#1082;&#1088;&#1091;&#1075;&#1091;</b>. &#1046;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1080;&#1079;&#1073;&#1077;&#1075;&#1072;&#1090;&#1100; &#1080;&#1079;&#1086;&#1075;&#1085;&#1091;&#1090;&#1086;&#1081; &#1087;&#1077;&#1090;&#1083;&#1080; &#1087;&#1086;&#1089;&#1077;&#1088;&#1077;&#1076;&#1080;&#1085;&#1077;

        <ul>
          <li>
            &#1042;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1086;&#1090;&#1084;&#1077;&#1088;&#1103;&#1102;&#1090;&#1089;&#1103; &#1087;&#1091;&#1090;&#1105;&#1084; &#1087;&#1088;&#1077;&#1076;&#1074;&#1072;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1091;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080; &#1074; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1091; &#1080; &#1087;&#1086;&#1076;&#1088;&#1077;&#1079;&#1072;&#1102;&#1090;&#1089;&#1103; &#1085;&#1086;&#1078;&#1085;&#1080;&#1094;&#1072;&#1084;&#1080; &#1091; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072; &#1083;&#1086;&#1078;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &#1076;&#1083;&#1103; &#1050;&#1044;&#1047;&#1057;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1087;&#1083;&#1072;&#1085;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1080;&#1093; &#1091;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1087;&#1086;&#1089;&#1083;&#1077; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; - <b>2 &#1087;&#1086;&#1083;&#1085;&#1099;&#1093; &#1086;&#1073;&#1086;&#1088;&#1086;&#1090;&#1072;</b>&#160; &#1076;&#1086; &#1083;&#1086;&#1078;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072; &#1050;&#1044;&#1047;&#1057;
          </li>
          <li>
            &#1042; &#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; &#1079;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090; &#171;<b>&#1089;&#1086;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;</b>&#187; (&#1090;&#1072;&#1082; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103;, &#1077;&#1089;&#1083;&#1080; &#1074; &#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1077; &#1074;&#1072;&#1088;&#1080;&#1084; 3 &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;), &#1086;&#1076;&#1085;&#1086; &#1080;&#1079; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1086;&#1090;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; &#1082;&#1072;&#1082; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086;, &#1074;&#1090;&#1086;&#1088;&#1086;&#1077; &#1078;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1086;&#1090;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; &#1089; &#1091;&#1095;&#1105;&#1090;&#1086;&#1084; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1086;&#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; S-&#1086;&#1073;&#1088;&#1072;&#1079;&#1085;&#1086;&#1081; &#1087;&#1077;&#1090;&#1083;&#1105;&#1081; &#1087;&#1086;&#1089;&#1077;&#1088;&#1077;&#1076;&#1080;&#1085;&#1077; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1099;. &#1057;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1080; <b>&#1089; S-&#1086;&#1073;&#1088;&#1072;&#1079;&#1085;&#1099;&#1084; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1086;&#1084; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1080;&#1079;&#1073;&#1077;&#1075;&#1072;&#1090;&#1100;</b>&#160;&#1080; &#1089;&#1090;&#1072;&#1088;&#1072;&#1090;&#1100;&#1089;&#1103; &#1079;&#1072;&#1074;&#1077;&#1089;&#1090;&#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; &#171;&#1074;&#1089;&#1090;&#1088;&#1077;&#1095;&#1085;&#1086;&#187; - &#1085;&#1077; &#1074;&#1089;&#1077; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1099; &#1088;&#1072;&#1089;&#1089;&#1095;&#1080;&#1090;&#1072;&#1085;&#1099; &#1085;&#1072; &#1090;&#1072;&#1082;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;, &#1101;&#1090;&#1086; &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1085;&#1072; &#1086;&#1090;&#1084;&#1077;&#1088;&#1082;&#1091; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;. &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1072; &#1085;&#1077; &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1085;&#1072; &#1076;&#1083;&#1103; &#1090;&#1072;&#1082;&#1086;&#1075;&#1086; &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1080; &#1080;&#1093; &#1087;&#1088;&#1080;&#1076;&#1077;&#1090;&#1089;&#1103; &#1082;&#1088;&#1077;&#1087;&#1080;&#1090;&#1100; &#1080;&#1079;&#1086;&#1083;&#1077;&#1085;&#1090;&#1086;&#1081;, &#1095;&#1090;&#1086; &#1085;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086; &#1080; &#1085;&#1077;&#1085;&#1072;&#1076;&#1077;&#1078;&#1085;&#1086;. &#1101;&#1090;&#1086; &#1091;&#1089;&#1083;&#1086;&#1078;&#1085;&#1103;&#1077;&#1090; &#1089;&#1093;&#1077;&#1084;&#1091; &#1087;&#1072;&#1081;&#1082;&#1080; &#1080; &#1087;&#1088;&#1080;&#1074;&#1086;&#1076;&#1080;&#1090; &#1082; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;&#1084;. &#1061;&#1086;&#1090;&#1103; &#1080;&#1085;&#1086;&#1075;&#1076;&#1072;, &#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1086;, &#1073;&#1077;&#1079; &#1090;&#1072;&#1082;&#1086;&#1075;&#1086; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1072; &#1085;&#1077; &#1086;&#1073;&#1086;&#1081;&#1090;&#1080;&#1089;&#1100;
          </li>
        </ul>
      </li>
    </ol>
    <p>
      <b>3. &#1056;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1084; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1074; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1077;.</b>&#160;
    </p>
    <p>
      &#1057;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1099; &#1088;&#1072;&#1089;&#1089;&#1095;&#1080;&#1090;&#1072;&#1085;&#1099; &#1085;&#1072; <b>32 &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;</b>. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091;, &#1077;&#1089;&#1083;&#1080; &#1091; &#1085;&#1072;&#1089; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1089;&#1086;&#1089;&#1090;&#1086;&#1080;&#1090; &#1080;&#1079; 4 &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; &#1087;&#1086; 8 &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; - &#1074;&#1089;&#1077; &#1083;&#1077;&#1075;&#1082;&#1086; &#1088;&#1072;&#1089;&#1089;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;:
    </p>
    <ul>
      <li>
        &#1042;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; 1-&#1075;&#1086; &#1080; 2-&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1089;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1099;&#1084;&#1080; &#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1080; &#1083;&#1086;&#1078;&#1072;&#1090;&#1089;&#1103; &#1074; &#1074;&#1077;&#1088;&#1093;&#1085;&#1080;&#1093; &#1083;&#1086;&#1078;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;&#1093; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1099;. (16 &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;)
      </li>
      <li>
        3-&#1081; &#1080; 4-&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; - &#1074; &#1085;&#1080;&#1078;&#1085;&#1080;&#1093; &#1083;&#1086;&#1078;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;&#1093;
      </li>
    </ul>
    <p>
      <b>&#1044;&#1074;&#1072; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1099;&#1093; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1085;&#1072; 64 &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;</b>. &#1042; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; 8 &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; &#1087;&#1086; 8 &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;, &#1090;&#1086; &#1074;&#1089;&#1077; &#1077;&#1097;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1082;&#1088;&#1091;&#1090;&#1080;&#1090;&#1100;&#1089;&#1103;, <b>&#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1080;&#1074; &#1080;&#1093; &#1085;&#1072; &#1076;&#1074;&#1077; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1099;: </b>
    </p>
    <ul>
      <li>
        &#1055;&#1077;&#1088;&#1074;&#1099;&#1077; &#1095;&#1077;&#1090;&#1099;&#1088;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1087;&#1077;&#1088;&#1074;&#1086;&#1075;&#1086; &#1080; &#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1089;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1077;
      </li>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1077; &#1095;&#1077;&#1090;&#1099;&#1088;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; - &#1080;&#1076;&#1091;&#1090; &#1074;&#1086; &#1074;&#1090;&#1086;&#1088;&#1091;&#1102;
      </li>
      <li>
        &#1050;&#1072;&#1082;&#1091;&#1102; &#1087;&#1086;&#1083;&#1086;&#1074;&#1080;&#1085;&#1091; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1074; &#1074;&#1077;&#1088;&#1093;&#1085;&#1102;&#1102;, &#1072; &#1082;&#1072;&#1082;&#1091;&#1102; - &#1074; &#1085;&#1080;&#1078;&#1085;&#1102;&#1102; - &#1074;&#1089;&#1077; &#1088;&#1072;&#1074;&#1085;&#1086;
      </li>
    </ul>
    <p>
      <b>&#1044;&#1074;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1089; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086;&#1084; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1074; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1093;, &#1080;&#1083;&#1080; &#1089;&#1074;&#1072;&#1088;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; 3-4 &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; </b>
    </p>
    <ul>
      <li>
        &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1086;&#1095;&#1077;&#1085;&#1100; &#1090;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1087;&#1083;&#1072;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1088;&#1072;&#1079;&#1074;&#1086;&#1076;&#1082;&#1080; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;
      </li>
      <li>
        <b>&#1042;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1103;&#1090; &#1074; &#1076;&#1088;&#1091;&#1075;&#1091;&#1102; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1091;</b>&#160;(&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1083;&#1080;&#1096;&#1085;&#1080;&#1077; &#1080;&#1079;-&#1079;&#1072; &#1088;&#1072;&#1079;&#1085;&#1086;&#1089;&#1090;&#1080; &#1095;&#1080;&#1089;&#1083;&#1072; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1074; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1093;) &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1072;&#1084;&#1080; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; <b>&#1078;&#1077;&#1089;&#1090;&#1082;&#1086;&#1081; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1082;&#1086;&#1074;&#1086;&#1081; &#1090;&#1088;&#1091;&#1073;&#1086;&#1095;&#1082;&#1077;</b>, &#1087;&#1088;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1079;&#1072;&#1084;&#1077;&#1085;&#1103;&#1077;&#1084;&#1086;&#1081; &#1090;&#1088;&#1091;&#1073;&#1086;&#1095;&#1082;&#1086;&#1081; &#1086;&#1090; &#1082;&#1072;&#1087;&#1077;&#1083;&#1100;&#1085;&#1080;&#1094;&#1099;. &#1053;&#1077;&#1083;&#1100;&#1079;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1091;&#1089;&#1090;&#1091;&#1102; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1091; &#1086;&#1090; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;, &#1087;&#1086;&#1090;&#1086;&#1084;&#1091; &#1095;&#1090;&#1086; &#1086;&#1085;&#1072; &#1083;&#1086;&#1084;&#1082;&#1072;&#1103;, &#1082; &#1090;&#1086;&#1084;&#1091; &#1078;&#1077; &#1086;&#1090; &#1075;&#1080;&#1076;&#1088;&#1086;&#1092;&#1086;&#1073;&#1072; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1077;&#1077; &#1085;&#1077; &#1086;&#1095;&#1080;&#1089;&#1090;&#1080;&#1090;&#1100; &#1090;&#1086;&#1083;&#1082;&#1086;&#1084;, &#1080; &#1090;&#1077;&#1084; &#1073;&#1086;&#1083;&#1077;&#1077; - &#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1090;&#1072;&#1082;.
      </li>
    </ul>
    <p>
      <b>4. &#1054;&#1076;&#1077;&#1074;&#1072;&#1077;&#1084; &#1075;&#1080;&#1083;&#1100;&#1079;&#1099; &#1050;&#1044;&#1047;&#1057; (&#1050;&#1086;&#1084;&#1087;&#1083;&#1077;&#1082;&#1090; &#1076;&#1083;&#1103; &#1079;&#1072;&#1097;&#1080;&#1090;&#1099; &#1089;&#1074;&#1072;&#1088;&#1085;&#1086;&#1075;&#1086; &#1089;&#1090;&#1099;&#1082;&#1072;). </b>&#1055;&#1086;&#1083;&#1080;&#1084;&#1077;&#1088;&#1085;&#1072;&#1103; &#1090;&#1088;&#1077;&#1093;&#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1085;&#1072;&#1103; &#1075;&#1080;&#1083;&#1100;&#1079;&#1072;: &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1089;&#1083;&#1086;&#1081; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1082;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1083;&#1077;&#1075;&#1082;&#1086; &#1087;&#1083;&#1072;&#1074;&#1080;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1087;&#1086;&#1074;&#1099;&#1096;&#1077;&#1085;&#1085;&#1086;&#1081; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1077;, &#1087;&#1086;&#1090;&#1086;&#1084; &#1087;&#1086; &#1076;&#1083;&#1080;&#1085;&#1077; &#1075;&#1080;&#1083;&#1100;&#1079;&#1099; - &#1087;&#1088;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1072; &#1076;&#1083;&#1103; &#1078;&#1077;&#1089;&#1090;&#1082;&#1086;&#1089;&#1090;&#1080; &#1080; &#1074;&#1077;&#1088;&#1093;&#1085;&#1103;&#1103; &#1090;&#1077;&#1088;&#1084;&#1086;&#1091;&#1089;&#1072;&#1076;&#1086;&#1095;&#1085;&#1072;&#1103; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1072;.
    </p>
    <ul>
      <li>
        &#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1077; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1050;&#1044;&#1047;&#1057; - &#1079;&#1072;&#1097;&#1080;&#1090;&#1080;&#1090;&#1100; &#1084;&#1077;&#1089;&#1090;&#1086; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1086;&#1090; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1081;. &#1045;&#1077; &#1085;&#1072;&#1076;&#1077;&#1074;&#1072;&#1102;&#1090; &#1085;&#1072; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076; &#1089;&#1074;&#1072;&#1088;&#1082;&#1086;&#1081;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1085;&#1072;&#1076;&#1074;&#1080;&#1075;&#1072;&#1102;&#1090; &#1085;&#1072; &#1084;&#1077;&#1089;&#1090;&#1086; &#1089;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1086;&#1075;&#1086; &#1089;&#1090;&#1099;&#1082;&#1072; &#1080; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090; &#1085;&#1072; <b>30-40 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076; &#1074; &#1087;&#1077;&#1095;&#1082;&#1091;</b>. &#1047;&#1072; &#1101;&#1090;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1082; &#1086;&#1087;&#1083;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080; &#1086;&#1093;&#1074;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;, &#1072; &#1074;&#1077;&#1088;&#1093;&#1085;&#1080;&#1081; &#1089;&#1083;&#1086;&#1081; &#1087;&#1083;&#1086;&#1090;&#1085;&#1086; &quot;&#1091;&#1089;&#1072;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;&quot; &#1074;&#1089;&#1077; &#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1102;, &#1074;&#1084;&#1077;&#1089;&#1090;&#1077; &#1089; &#1087;&#1088;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1081; &#1076;&#1083;&#1103; &#1078;&#1077;&#1089;&#1090;&#1082;&#1086;&#1089;&#1090;&#1080;
      </li>
      <li>
        <b>&#1053;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103;:</b>&#160;&#1059;&#1089;&#1072;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1050;&#1044;&#1047;&#1057; &#1079;&#1072;&#1078;&#1080;&#1075;&#1072;&#1083;&#1082;&#1086;&#1081;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1087;&#1086;&#1076;&#1078;&#1077;&#1095;&#1100; &#1083;&#1072;&#1082; &#1080;&#1083;&#1080; &#1087;&#1077;&#1088;&#1077;&#1078;&#1077;&#1095;&#1100; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;. &#1054;&#1076;&#1085;&#1091; &#1075;&#1080;&#1083;&#1100;&#1079;&#1091; &#1086;&#1076;&#1077;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1089;&#1088;&#1072;&#1079;&#1091;.
      </li>
      <li>
        &#1052;&#1077;&#1090;&#1086;&#1076;&#1080;&#1082;&#1072; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089; &#1075;&#1080;&#1083;&#1100;&#1079;&#1072;&#1084;&#1080;: &#1085;&#1072;&#1076;&#1077;&#1083; &#1086;&#1076;&#1085;&#1091; &#1075;&#1080;&#1083;&#1100;&#1079;&#1091;, &#1089;&#1074;&#1072;&#1088;&#1080;&#1083; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;, &#1091;&#1089;&#1072;&#1076;&#1080;&#1083; &#1075;&#1080;&#1083;&#1100;&#1079;&#1091;, &#1074;&#1079;&#1103;&#1083; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1091;&#1102; &#1080; &#1090;.&#1076;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1077;&#1076;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1095;&#1091;&#1090;&#1100; &#1073;&#1086;&#1083;&#1077;&#1077; &#1087;&#1088;&#1086;&#1076;&#1074;&#1080;&#1085;&#1091;&#1090;&#1099;&#1081; &#1084;&#1077;&#1090;&#1086;&#1076;: <b>&#1085;&#1072;&#1076;&#1077;&#1090;&#1100; &#1074;&#1089;&#1077; &#1075;&#1080;&#1083;&#1100;&#1079;&#1099; &#1085;&#1072; &#1042;&#1057;&#1045; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1089;&#1088;&#1072;&#1079;&#1091;</b>&#160; (&#1076;&#1086; &#1079;&#1072;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080; &#1089;&#1090;&#1088;&#1080;&#1087;&#1087;&#1077;&#1088;&#1086;&#1084;)&#160;&#1080; &#1091;&#1078;&#1077; &#1087;&#1086;&#1090;&#1086;&#1084; &#1074;&#1072;&#1088;&#1080;&#1090;&#1100;. &#1058;&#1072;&#1082; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; &#1088;&#1080;&#1089;&#1082; &#1079;&#1072;&#1073;&#1099;&#1090;&#1100; &#1086; &#1085;&#1080;&#1093; &#1074; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077;
      </li>
      <li>
        &#1046;&#1077;&#1083;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1086;&#1095;&#1085;&#1086;&#1077; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1086;&#1074; &#1075;&#1080;&#1083;&#1100;&#1079;&#1099; &#1080; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1099;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082;

        <ul>
          <li>
            &#1042; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1077;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1086;&#1081; &#1076;&#1083;&#1103; &#1050;&#1044;&#1047;&#1057; 60 &#1084;&#1084;, &#1089;&#1086;&#1088;&#1086;&#1082;&#1072;&#1084;&#1080;&#1083;&#1080;&#1084;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;&#1099;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1073;&#1086;&#1083;&#1090;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1087;&#1086;&#1089;&#1072;&#1076;&#1086;&#1095;&#1085;&#1099;&#1093; &#1084;&#1077;&#1089;&#1090;&#1072;&#1093;.
          </li>
          <li>
            &#1042; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1077;, &#1088;&#1072;&#1089;&#1089;&#1095;&#1080;&#1090;&#1072;&#1085;&#1085;&#1086;&#1081; &#1076;&#1083;&#1103; &#1050;&#1044;&#1047;&#1057; 40 &#1084;&#1084;, &#1075;&#1080;&#1083;&#1100;&#1079;&#1099; &#1085;&#1072; 60 &#1084;&#1084; &#1089; &#1090;&#1088;&#1091;&#1076;&#1086;&#1084; &#1073;&#1091;&#1076;&#1091;&#1090; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1074; &#1101;&#1090;&#1080; &#1087;&#1086;&#1089;&#1072;&#1076;&#1086;&#1095;&#1085;&#1099;&#1077; &#1084;&#1077;&#1089;&#1090;&#1072; (&#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1073;&#1086;&#1083;&#1077;&#1077; &#1090;&#1086;&#1083;&#1089;&#1090;&#1099;&#1077;), &#1076;&#1072; &#1080; &#1091;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100; &#1080;&#1093; &#1087;&#1088;&#1080;&#1076;&#1077;&#1090;&#1089;&#1103; &#1089;&#1090;&#1088;&#1086;&#1075;&#1086; &#1087;&#1086; &#1094;&#1077;&#1085;&#1090;&#1088;&#1091;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1080;&#1089;&#1082;&#1088;&#1080;&#1074;&#1083;&#1103;&#1090;&#1100; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;. &#1042; &#1082;&#1088;&#1072;&#1081;&#1085;&#1077;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1093;&#1086;&#1090;&#1103; &#1073;&#1099; &#1086;&#1090;&#1082;&#1091;&#1089;&#1080;&#1090;&#1100; &#1083;&#1080;&#1096;&#1085;&#1080;&#1077; &#1089;&#1072;&#1085;&#1090;&#1080;&#1084;&#1077;&#1090;&#1088;&#1099; &#1073;&#1086;&#1082;&#1086;&#1088;&#1077;&#1079;&#1072;&#1084;&#1080;.
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <b>5. &#1047;&#1072;&#1095;&#1080;&#1097;&#1072;&#1077;&#1084; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;&#160;&#160;&#1086;&#1090; &#1087;&#1086;&#1083;&#1080;&#1072;&#1084;&#1080;&#1076;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1082;&#1088;&#1099;&#1090;&#1080;&#1103;-&#1083;&#1072;&#1082;&#1072;.</b>
    </p>
    <ul>
      <li>
        &#1044;&#1083;&#1103; &#1086;&#1095;&#1080;&#1089;&#1090;&#1082;&#1080; &#1083;&#1072;&#1082;&#1072; &#1089; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; <b>&#1089;&#1090;&#1088;&#1080;&#1087;&#1087;&#1077;&#1088; &#1076;&#1083;&#1103; &#1083;&#1072;&#1082;&#1086;&#1074;&#1086;&#1075;&#1086; &#1087;&#1086;&#1082;&#1088;&#1099;&#1090;&#1080;&#1103;</b>. &#1069;&#1090;&#1086; &#1076;&#1086;&#1088;&#1086;&#1075;&#1086;&#1081; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1084;&#1077;&#1085;&#1090;, &#1088;&#1072;&#1089;&#1089;&#1095;&#1080;&#1090;&#1072;&#1085;&#1085;&#1099;&#1081; &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1085;&#1072; &#1089;&#1085;&#1103;&#1090;&#1080;&#1077; &#1083;&#1072;&#1082;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1074;&#1099; &#1073;&#1091;&#1076;&#1077;&#1090;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1077;&#1075;&#1086; &#1076;&#1083;&#1103; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1094;&#1077;&#1083;&#1077;&#1081; &#1074; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; - &#1074;&#1089;&#1082;&#1086;&#1088;&#1077; &#1087;&#1088;&#1080;&#1076;&#1077;&#1090;&#1089;&#1103; &#1074;&#1099;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100; &#1076;&#1077;&#1085;&#1100;&#1075;&#1080; &#1079;&#1072; &#1085;&#1086;&#1074;&#1099;&#1081;
      </li>
      <li>
        &#1047;&#1072;&#1095;&#1080;&#1097;&#1072;&#1090;&#1100; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; <b>3 &#1089;&#1084;</b>. &#1043;&#1083;&#1072;&#1074;&#1085;&#1086;&#1077; - &#1085;&#1077; &#1089;&#1083;&#1086;&#1084;&#1072;&#1090;&#1100; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1084;&#1099; &#1078;&#1077; &#1091;&#1078;&#1077; &#1086;&#1090;&#1084;&#1077;&#1088;&#1103;&#1083;&#1080; &#1077;&#1075;&#1086; &#1076;&#1083;&#1080;&#1085;&#1091; &#1080; &#1086;&#1090;&#1088;&#1077;&#1079;&#1072;&#1083;&#1080;, &#1079;&#1072;&#1087;&#1072;&#1089;&#1072; &#1085;&#1077;&#1090;.
      </li>
    </ul>
    <p>
      <b>6. &#1057;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1081; &#1101;&#1090;&#1072;&#1087;</b>&#160;- <a href="#ID_1423549107">&#1089;&#1074;&#1072;&#1088;&#1082;&#1072; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;</a>.
    </p>
  </body>
</html></richcontent>
