  <body>
    <p>
      <a href="#ID_1402771472">&#1057;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1099;&#1081; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;</a>&#160; &#160;<a href="#ID_1015835175">&#1057;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;</a>&#160; <a href="#ID_1229787669">&#1047;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1074; &#1054;&#1042;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1081; &#1087;&#1088;&#1080; &#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1085;&#1080;&#1080; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; </b>
    </p>
    <ol>
      <li>
        <b>&#1047;&#1072;&#1095;&#1080;&#1097;&#1072;&#1077;&#1084;</b>&#160;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1086;&#1090; &#1083;&#1072;&#1082;&#1072;
      </li>
      <li>
        <b>&#1055;&#1088;&#1086;&#1090;&#1080;&#1088;&#1072;&#1077;&#1084;</b>&#160;&#1073;&#1077;&#1079;&#1074;&#1086;&#1088;&#1089;&#1086;&#1074;&#1086;&#1081; &#1089;&#1072;&#1083;&#1092;&#1077;&#1090;&#1082;&#1086;&#1081;, &#1089;&#1084;&#1086;&#1095;&#1077;&#1085;&#1085;&#1086;&#1081; &#1089;&#1087;&#1080;&#1088;&#1090;&#1086;&#1084; - &#1087;&#1088;&#1086;&#1074;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1103; &#1074;&#1086;&#1082;&#1088;&#1091;&#1075; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1085;&#1103;&#1090;&#1100; &#1074;&#1089;&#1102; &#1075;&#1088;&#1103;&#1079;&#1100;
      </li>
      <li>
        <b>&#1047;&#1072;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1077;&#1084; &#1074; &#1082;&#1072;&#1085;&#1072;&#1074;&#1082;&#1091;</b>&#160;&#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1087;&#1086; &#1083;&#1080;&#1085;&#1077;&#1081;&#1082;&#1077;. &#1042;&#1072;&#1078;&#1085;&#1086; &#1077;&#1075;&#1086; &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1085;&#1077; &#1074;&#1099;&#1087;&#1072;&#1095;&#1082;&#1072;&#1090;&#1100; &#1080; &#1085;&#1077; &#1074;&#1083;&#1077;&#1079;&#1090;&#1100; &#1074; &#1085;&#1086;&#1078;. &#1043;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072;, &#1075;&#1076;&#1077; &#1079;&#1072;&#1082;&#1072;&#1085;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1083;&#1072;&#1082;&#1086;&#1074;&#1086;&#1077; &#1087;&#1086;&#1082;&#1088;&#1099;&#1090;&#1080;&#1077; &#1080; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1075;&#1086;&#1083;&#1077;&#1085;&#1085;&#1086;&#1077; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;, &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1091;&#1102; &#1094;&#1080;&#1092;&#1088;&#1091; &#1085;&#1072; &#1083;&#1080;&#1085;&#1077;&#1081;&#1082;&#1077;. &#1050;&#1072;&#1082;&#1091;&#1102; &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1094;&#1080;&#1092;&#1088;&#1091; - &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1084;&#1086;&#1076;&#1077;&#1083;&#1080; &#1074;&#1072;&#1096;&#1077;&#1075;&#1086; &#1089;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1086;&#1075;&#1086; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1074;&#1099; &#1077;&#1077; &#1087;&#1088;&#1077;&#1074;&#1099;&#1089;&#1080;&#1090;&#1077; - &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1085;&#1086;&#1088;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086; &#1089;&#1074;&#1072;&#1088;&#1080;&#1090;&#1089;&#1103;, &#1086;&#1076;&#1085;&#1072;&#1082;&#1086; &#1075;&#1080;&#1083;&#1100;&#1079;&#1072; &#1050;&#1044;&#1047;&#1057; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1087;&#1086;&#1082;&#1088;&#1099;&#1074;&#1072;&#1090;&#1100; &#1086;&#1075;&#1086;&#1083;&#1077;&#1085;&#1085;&#1091;&#1102; &#1095;&#1072;&#1089;&#1090;&#1100;. &#1045;&#1089;&#1083;&#1080; &#1078;&#1077; &#1086;&#1085;&#1086; &#1086;&#1082;&#1072;&#1078;&#1077;&#1090;&#1089;&#1103; &#1089;&#1083;&#1080;&#1096;&#1082;&#1086;&#1084; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1080;&#1084;, &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090; &#1085;&#1077; &#1089;&#1087;&#1072;&#1103;&#1077;&#1090; &#1082;&#1086;&#1085;&#1094;&#1099;
      </li>
      <li>
        <b>&#1057;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1077;&#1084;</b>&#160;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; (&#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1084;&#1086;&#1076;&#1077;&#1083;&#1080; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1072; - &#1085;&#1072;&#1078;&#1080;&#1084;&#1072;&#1077;&#1084; &#1085;&#1072; &#1082;&#1088;&#1099;&#1096;&#1082;&#1091; &#1080;&#1083;&#1080; &#1090;&#1086;&#1083;&#1082;&#1072;&#1077;&#1084; &#1082;&#1072;&#1088;&#1077;&#1090;&#1082;&#1091;)
      </li>
      <li>
        &#1054;&#1089;&#1090;&#1086;&#1088;&#1086;&#1078;&#1085;&#1086; &#1076;&#1086;&#1089;&#1090;&#1072;&#1077;&#1084; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1080; <b>&#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1082;&#1072;&#1089;&#1072;&#1103;&#1089;&#1100;</b>&#160;&#160;&#1089;&#1082;&#1086;&#1083;&#1086;&#1084;, &#1085;&#1077; &#1094;&#1077;&#1087;&#1083;&#1103;&#1103;&#1089;&#1100; &#1079;&#1072; &#1073;&#1086;&#1088;&#1090;&#1080;&#1082;&#1080; &#1082;&#1072;&#1085;&#1072;&#1074;&#1082;&#1080; &#1085;&#1080; &#1074; &#1089;&#1082;&#1072;&#1083;&#1099;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;, &#1085;&#1080; &#1074; &#1089;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1086;&#1084; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1077;, <b>&#1091;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1077;&#1084; &#1074; &#1089;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1080;&#1082;</b>
      </li>
      <li>
        <b>&#1045;&#1089;&#1083;&#1080; &#1095;&#1077;&#1075;&#1086;-&#1090;&#1086; &#1082;&#1086;&#1089;&#1085;&#1091;&#1083;&#1080;&#1089;&#1100;</b>, &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1087;&#1099;&#1090;&#1072;&#1090;&#1100;&#1089;&#1103; &#1086;&#1095;&#1080;&#1089;&#1090;&#1080;&#1090;&#1100; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; - &#1079;&#1072;&#1085;&#1086;&#1074;&#1086; &#1087;&#1088;&#1086;&#1090;&#1077;&#1088;&#1077;&#1090;&#1100; &#1089;&#1072;&#1083;&#1092;&#1077;&#1090;&#1082;&#1086;&#1081;, &#1072; &#1087;&#1086;&#1074;&#1077;&#1088;&#1093;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1089;&#1082;&#1086;&#1083;&#1072; &quot;&#1087;&#1086;&#1090;&#1099;&#1082;&#1072;&#1090;&#1100;&quot; &#1074; &#1089;&#1087;&#1080;&#1088;&#1090;&#1086;&#1074;&#1091;&#1102; &#1089;&#1072;&#1083;&#1092;&#1077;&#1090;&#1082;&#1091; (&#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1078;&#1085;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1089;&#1083;&#1086;&#1084;&#1072;&#1090;&#1100; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;), &#1087;&#1086;&#1089;&#1083;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086; - &#1074; &#1089;&#1091;&#1093;&#1091;&#1102;. &#1053;&#1086; &#1101;&#1090;&#1086; &#1085;&#1077; &#1076;&#1072;&#1077;&#1090; &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1080; &#1087;&#1086;&#1083;&#1085;&#1086;&#1075;&#1086; &#1086;&#1095;&#1080;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1083;&#1091;&#1095;&#1096;&#1077; &#1087;&#1077;&#1088;&#1077;&#1089;&#1082;&#1086;&#1083;&#1086;&#1090;&#1100;.
      </li>
    </ol>
    <p>
      <b>&#1055;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1074; &#1089;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1086;&#1084; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1077;:</b>
    </p>
    <ol>
      <li>
        <b>&#1057;&#1082;&#1086;&#1083;&#1086;&#1090;&#1099;&#1077; &#1086;&#1095;&#1080;&#1097;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1091;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1082;&#1072;&#1085;&#1072;&#1074;&#1082;&#1080; </b>&#1080; &#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1079;&#1072;&#1078;&#1080;&#1084;&#1072;&#1084;&#1080;. &#1042;&#1072;&#1078;&#1085;&#1086; &#1079;&#1072;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100; &#1090;&#1072;&#1082;, &#1095;&#1090;&#1086;&#1073; &#1082;&#1086;&#1085;&#1077;&#1094; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1089;&#1074;&#1077;&#1096;&#1080;&#1074;&#1072;&#1083;&#1089;&#1103; &#1080;&#1079; V-&#1082;&#1072;&#1085;&#1072;&#1074;&#1082;&#1080; &#1085;&#1072; &#1087;&#1072;&#1088;&#1091; &#1084;&#1080;&#1083;&#1083;&#1080;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074;, &#1085;&#1086; &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1089;&#1077;&#1082;&#1072;&#1083; &#1089;&#1077;&#1088;&#1077;&#1076;&#1080;&#1085;&#1091; &#1089;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072; (&#1074;&#1086;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1084;&#1091;&#1102; &#1083;&#1080;&#1085;&#1080;&#1102; &#1084;&#1077;&#1078;&#1076;&#1091; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1072;&#1084;&#1080;).
      </li>
      <li>
        &#1040;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1074;&#1080;&#1075;&#1072;&#1090;&#1100; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1087;&#1086; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102; &#1076;&#1088;&#1091;&#1075; &#1082; &#1076;&#1088;&#1091;&#1075;&#1091; &#1076;&#1086; &#1090;&#1077;&#1093; &#1087;&#1086;&#1088;, &#1087;&#1086;&#1082;&#1072; &#1085;&#1077; &#1079;&#1072;&#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090; &#1080;&#1093; &#1074; &#1089;&#1074;&#1086;&#1077;&#1081; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077;
      </li>
      <li>
        <b>&#1059;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086;&#1076;&#1072;&#1077;&#1090; &#1085;&#1072; &#1082;&#1086;&#1085;&#1094;&#1099; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1082;&#1086;&#1088;&#1086;&#1090;&#1082;&#1080;&#1081; &#1088;&#1072;&#1079;&#1088;&#1103;&#1076;</b>, &#1086;&#1095;&#1080;&#1097;&#1072;&#1103; &#1086;&#1090; &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1086; &#1087;&#1086;&#1087;&#1072;&#1074;&#1096;&#1077;&#1081; &#1087;&#1099;&#1083;&#1080;. &#1053;&#1086; &#1077;&#1089;&#1083;&#1080; &#1085;&#1072; &#1082;&#1086;&#1085;&#1094;&#1072;&#1093; &#1089;&#1082;&#1086;&#1083;&#1086;&#1074; - &#1078;&#1080;&#1088;&#1085;&#1099;&#1077; &#1086;&#1090;&#1087;&#1077;&#1095;&#1072;&#1090;&#1082;&#1080; &#1087;&#1072;&#1083;&#1100;&#1094;&#1077;&#1074; &#1080;&#1083;&#1080; &#1075;&#1088;&#1103;&#1079;&#1100;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1090;&#1072;&#1082; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1085;&#1077; &#1089;&#1076;&#1091;&#1077;&#1096;&#1100;, &#1086;&#1085;&#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1072;&#1087;&#1077;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1086;&#1088;&#1090;&#1080;&#1090; &#1089;&#1082;&#1086;&#1083;
      </li>
      <li>
        &#1044;&#1072;&#1083;&#1077;&#1077; &#1089;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1099;&#1081; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090; &#1089;&#1074;&#1086;&#1076;&#1080;&#1090; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1076;&#1083;&#1103; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; - &#1087;&#1086; &#1090;&#1088;&#1077;&#1084; &#1082;&#1086;&#1086;&#1088;&#1076;&#1080;&#1085;&#1072;&#1090;&#1072;&#1084;, &#1089; &#1085;&#1072;&#1088;&#1072;&#1089;&#1090;&#1072;&#1102;&#1097;&#1077;&#1081; &#1090;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1072; &#1101;&#1090;&#1086;&#1084; &#1101;&#1090;&#1072;&#1087;&#1077; &#1091;&#1084;&#1085;&#1086;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1086;&#1073;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080;&#1090; &#1085;&#1077;&#1088;&#1086;&#1074;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1082;&#1086;&#1083;&#1086;&#1074; &#1080;&#1083;&#1080; &#1077;&#1097;&#1077; &#1095;&#1090;&#1086;-&#1090;&#1086;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1084;&#1077;&#1096;&#1072;&#1077;&#1090; &#1080;&#1093; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1089;&#1074;&#1072;&#1088;&#1080;&#1090;&#1100; - &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1086;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1089;&#1103;, &#1085;&#1072; &#1101;&#1082;&#1088;&#1072;&#1085;&#1077; &#1089;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1086;&#1075;&#1086; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1072; &#1087;&#1086;&#1103;&#1074;&#1080;&#1090;&#1089;&#1103; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1078;&#1077; &#1074;&#1089;&#1077; &#1085;&#1086;&#1088;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;, <b>&#1087;&#1086;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1072;&#1079;&#1088;&#1103;&#1076;, &#1089;&#1082;&#1086;&#1083;&#1099; &#1086;&#1087;&#1083;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103;</b>, &#1080; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1088;&#1080;&#1076;&#1074;&#1080;&#1075;&#1072;&#1077;&#1090; &#1080;&#1093; &#1091;&#1078;&#1077; &#1074;&#1087;&#1083;&#1086;&#1090;&#1085;&#1091;&#1102; &#1076;&#1088;&#1091;&#1075; &#1082; &#1076;&#1088;&#1091;&#1075;&#1091;. &#1042;&#1089;&#1077;, &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1089;&#1087;&#1072;&#1103;&#1085;&#1099;
      </li>
      <li>
        <b>&#1057;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1099;&#1081; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090; &#1086;&#1094;&#1077;&#1085;&#1080;&#1074;&#1072;&#1077;&#1090; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080;</b>&#160;&#1087;&#1086; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1102; &#1084;&#1077;&#1089;&#1090;&#1072; &#1089;&#1090;&#1099;&#1082;&#1072; &#1087;&#1086;&#1076; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1082;&#1086;&#1087;&#1072;&#1084;&#1080; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;, &#1080; &#1085;&#1072; &#1087;&#1088;&#1086;&#1089;&#1074;&#1077;&#1090; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077;. &#1057;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1072;&#1103; &#1089;&#1090;&#1072;&#1076;&#1080;&#1103; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1080; - <b>&#1085;&#1072; &#1087;&#1088;&#1086;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;</b>, &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1087;&#1099;&#1090;&#1072;&#1077;&#1090;&#1089;&#1103; &#1088;&#1072;&#1079;&#1074;&#1077;&#1089;&#1090;&#1080; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1095;&#1090;&#1086; &#1089;&#1074;&#1072;&#1088;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1074; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099;. &#1054;&#1076;&#1085;&#1072;&#1082;&#1086; <b>&#1084;&#1085;&#1086;&#1075;&#1080;&#1077; &#1101;&#1090;&#1091; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1090;</b>, &#1073;&#1086;&#1103;&#1089;&#1100; &#1095;&#1090;&#1086; &#1085;&#1077; &#1086;&#1089;&#1090;&#1099;&#1074;&#1096;&#1072;&#1103; &#1076;&#1086; &#1082;&#1086;&#1085;&#1094;&#1072; &#1089;&#1074;&#1072;&#1088;&#1082;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1088;&#1090;&#1080;&#1090;&#1100;&#1089;&#1103;.<br/><b>&#1045;&#1089;&#1083;&#1080; &#1077;&#1089;&#1090;&#1100; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1083;&#1091;&#1095;&#1096;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; &#1074;&#1072;&#1088;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1077;&#1084; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1072;.</b>&#160; &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1076;&#1074;&#1086;&#1077; &#1074;&#1072;&#1088;&#1103;&#1090;, &#1072; &#1090;&#1088;&#1077;&#1090;&#1080;&#1081; &#1089;&#1080;&#1076;&#1080;&#1090; &#1085;&#1072; &#1073;&#1083;&#1080;&#1078;&#1072;&#1081;&#1096;&#1077;&#1084; &#1082;&#1088;&#1086;&#1089;&#1089;&#1077; &#1080; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1080;&#1088;&#1091;&#1077;&#1090; &#1087;&#1086; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1091; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1088;&#1086;&#1089;&#1082;&#1086;&#1095;&#1080;&#1083; &#1085;&#1077;&#1079;&#1072;&#1084;&#1077;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1082;&#1086;&#1089;&#1103;&#1082; &#8212; &#1086;&#1085; &#1089;&#1088;&#1072;&#1079;&#1091; &#1087;&#1077;&#1088;&#1077;&#1079;&#1074;&#1086;&#1085;&#1080;&#1090; &#1089;&#1087;&#1072;&#1081;&#1097;&#1080;&#1082;&#1072;&#1084;, &#1095;&#1090;&#1086;&#1073; &#1087;&#1077;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1083;&#1080;.
      </li>
      <li>
        <b>&#1048;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1086; &#1089;&#1074;&#1072;&#1088;&#1082;&#1077;</b>&#160; (&#1076;&#1072;&#1090;&#1072;, &#1074;&#1088;&#1077;&#1084;&#1103;, &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077;) &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;, &#1085;&#1077;&#1086;&#1073;&#1085;&#1091;&#1083;&#1103;&#1077;&#1084;&#1099;&#1081; &#1089;&#1095;&#1105;&#1090;&#1095;&#1080;&#1082; &#1089;&#1074;&#1072;&#1088;&#1086;&#1082; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1077;&#1076;&#1080;&#1085;&#1080;&#1094;&#1091;.
      </li>
      <li>
        &#1055;&#1072;&#1081;&#1097;&#1080;&#1082; <b>&#1076;&#1086;&#1089;&#1090;&#1072;&#1077;&#1090;</b>&#160; &#1089;&#1087;&#1072;&#1103;&#1085;&#1085;&#1099;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;, &#1085;&#1072;&#1076;&#1074;&#1080;&#1075;&#1072;&#1077;&#1090; &#1075;&#1080;&#1083;&#1100;&#1079;&#1091; &#1050;&#1044;&#1047;&#1057;, &#1079;&#1072;&#1082;&#1088;&#1099;&#1074;&#1072;&#1103; &#1084;&#1077;&#1089;&#1090;&#1086; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080; &#1080; &#1087;&#1088;&#1080;&#1083;&#1077;&#1075;&#1072;&#1102;&#1097;&#1077;&#1077; &#1086;&#1075;&#1086;&#1083;&#1077;&#1085;&#1085;&#1086;&#1077; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;, &#1080; &#1082;&#1083;&#1072;&#1076;&#1077;&#1090; <b>&#1075;&#1080;&#1083;&#1100;&#1079;&#1091; &#1074; &#1087;&#1077;&#1095;&#1082;&#1091;</b>&#160;&#160;&#1076;&#1083;&#1103; &#1091;&#1089;&#1072;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;
      </li>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077; &#1080;&#1079;&#1074;&#1083;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &#1080;&#1079; &#1087;&#1077;&#1095;&#1082;&#1080; <b>&#1075;&#1080;&#1083;&#1100;&#1079;&#1072; &#1074;&#1099;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1087;&#1086;&#1083;&#1086;&#1095;&#1082;&#1091;</b>, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1089;&#1090;&#1099;&#1090;&#1100;. &#1042; &#1075;&#1086;&#1088;&#1103;&#1095;&#1077;&#1084; &#1074;&#1080;&#1076;&#1077; &#1077;&#1077; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1090;&#1100; &#1074; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1077; - &#1077;&#1089;&#1090;&#1100; &#1088;&#1080;&#1089;&#1082; &#1089;&#1083;&#1086;&#1084;&#1072;&#1090;&#1100; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086;, &#1090;.&#1082;. &#1079;&#1072;&#1097;&#1080;&#1097;&#1072;&#1102;&#1097;&#1072;&#1103; &#1077;&#1075;&#1086; &#1075;&#1080;&#1083;&#1100;&#1079;&#1072; &#1077;&#1097;&#1077; &#1084;&#1103;&#1075;&#1082;&#1072;&#1103;. &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1083;&#1072;&#1089;&#1090;&#1100; &#1077;&#1077; &#1082;&#1091;&#1076;&#1072;-&#1090;&#1086; &#1082;&#1088;&#1086;&#1084;&#1077; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1086;&#1081; &#1087;&#1086;&#1083;&#1086;&#1095;&#1082;&#1080; &#1090;&#1086;&#1078;&#1077; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; - &#1075;&#1086;&#1088;&#1103;&#1095;&#1080;&#1081; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1082; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1083;&#1080;&#1087;&#1085;&#1091;&#1090;&#1100;. &#1048;&#1084;&#1077;&#1085;&#1085;&#1086; &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1080; &#1079;&#1072;&#1073;&#1099;&#1074;&#1072;&#1090;&#1100; &#1077;&#1077; &#1074; &#1087;&#1077;&#1095;&#1082;&#1077; &#1090;&#1086;&#1078;&#1077; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; - &#1087;&#1088;&#1080;&#1083;&#1080;&#1087;&#1085;&#1077;&#1090;. &#1042;&#1099;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1075;&#1080;&#1083;&#1100;&#1079;&#1091; &#1080;&#1079; &#1087;&#1077;&#1095;&#1082;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1088;&#1072;&#1079;&#1091; &#1087;&#1086;&#1089;&#1083;&#1077; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1090;&#1072;&#1081;&#1084;&#1077;&#1088;&#1072;.
      </li>
      <li>
        &#1057;&#1074;&#1072;&#1088;&#1077;&#1085;&#1085;&#1099;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1091;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; <b>&#1089;&#1087;&#1083;&#1072;&#1081;&#1089;-&#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1085;&#1091;</b>, &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1091; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1084;&#1091;&#1092;&#1090;&#1099; &#1080;&#1083;&#1080; &#1082;&#1088;&#1086;&#1089;&#1089;&#1072;.
      </li>
    </ol>
