      4. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1077;&#1083;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1091;&#1102; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1091; &#1074;&#1084;&#1077;&#1089;&#1090;&#1086; &#1050;&#1044;&#1047;&#1057;.
