    <p>
      5. &#1054;&#1076;&#1080;&#1085; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1099;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1076;&#1077;&#1083;&#1086;&#1082; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;, &#1072; &#1075;&#1080;&#1083;&#1100;&#1079;&#1072; &#1050;&#1044;&#1047;&#1057; &#1086;&#1076;&#1085;&#1086;&#1088;&#1072;&#1079;&#1086;&#1074;&#1072;&#1103;.
