    </p>
    <p>
      3. &#1053;&#1072;&#1076;&#1105;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1085;&#1080;&#1078;&#1077;. &#1048;&#1085;&#1086;&#1075;&#1076;&#1072; (&#1086;&#1090; &#1074;&#1080;&#1073;&#1088;&#1072;&#1094;&#1080;&#1080;, &#1086;&#1090; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;) &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1088;&#1091;&#1096;&#1080;&#1090;&#1100;&#1089;&#1103;, &#1086;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086; &#1077;&#1089;&#1083;&#1080; &#1092;&#1072;&#1081;&#1073;&#1088;&#1083;&#1086;&#1082;&#1080;/&#1082;&#1086;&#1088;&#1077;&#1083;&#1080;&#1085;&#1082;&#1080; &#1089;&#1090;&#1072;&#1074;&#1080;&#1083;&#1080;&#1089;&#1100; &#1091;&#1078;&#1077; &#1073;/&#1091;
    </p>
    <p>
      4. &#1057;&#1074;&#1072;&#1088;&#1086;&#1095;&#1085;&#1099;&#1081; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090; &#1089;&#1090;&#1086;&#1080;&#1090; &#1076;&#1086;&#1088;&#1086;&#1075;&#1086;, &#1085;&#1086; &#1087;&#1086;&#1090;&#1086;&#1084; &#1094;&#1077;&#1085;&#1072; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1089;&#1088;&#1072;&#1097;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1072;&#1103;. &#1057; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084;&#1080; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1077;&#1083;&#1103;&#1084;&#1080; &#8212; &#1085;&#1072;&#1086;&#1073;&#1086;&#1088;&#1086;&#1090;.
    </p>
    <p>
      5. &#1044;&#1083;&#1103; &#1084;&#1085;&#1086;&#1075;&#1080;&#1093; &#1079;&#1072;&#1082;&#1072;&#1079;&#1095;&#1080;&#1082;&#1086;&#1074; &#1090;&#1072;&#1082;&#1086;&#1081; &#1084;&#1086;&#1085;&#1090;&#1072;&#1078; &#8212; &#1101;&#1090;&#1086; &#1085;&#1077;&#1089;&#1077;&#1088;&#1100;&#1105;&#1079;&#1085;&#1086;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1086;&#1074; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1089;&#1088;&#1072;&#1097;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;</b>&#160; &#1084;&#1085;&#1086;&#1075;&#1086;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, <b>fibrlok</b>, <b>Corelink</b>&#160;(&#1087;&#1086;&#1093;&#1086;&#1078; &#1085;&#1072; Fibrlok, &#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1083;&#1102;&#1095;&#1080;&#1082;&#1086;&#1084;)
