<node TEXT="5. Монтаж муфты" ID="ID_1176216305" CREATED="1554562327808" MODIFIED="1554563148286"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_679118521">&#1054;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1084;&#1091;&#1092;&#1090;&#1072;</a>&#160; &#160;<a href="#ID_1672716241">&#1052;&#1086;&#1085;&#1090;&#1072;&#1078; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1074; &#1084;&#1091;&#1092;&#1090;&#1091;</a>&#160;
    </p>
    <ol>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1091;&#1083;&#1086;&#1078;&#1077;&#1085;&#1099;, &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; <b>&#1085;&#1072; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1077; &#1087;&#1086;&#1076;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1080; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100;</b>&#160; &#1089;&#1090;&#1088;&#1077;&#1083;&#1086;&#1095;&#1082;&#1072;&#1084;&#1080; &#1080; &#1092;&#1080;&#1075;&#1091;&#1088;&#1085;&#1099;&#1084;&#1080; &#1089;&#1082;&#1086;&#1073;&#1086;&#1095;&#1082;&#1072;&#1084;&#1080;, &#1082;&#1072;&#1082;&#1080;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1082;&#1091;&#1076;&#1072; &#1080;&#1076;&#1091;&#1090;. &#1058;&#1072;&#1082;&#1078;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1090;&#1088;&#1077;&#1083;&#1082;&#1072;&#1084;&#1080; &#1089; &#1085;&#1072;&#1076;&#1087;&#1080;&#1089;&#1103;&#1084;&#1080; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100;, &#1082;&#1072;&#1082;&#1086;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1082;&#1091;&#1076;&#1072; &#1080;&#1076;&#1105;&#1090;, &#1080;&#1083;&#1080; &#1085;&#1072;&#1082;&#1083;&#1077;&#1080;&#1090;&#1100; &#1080;&#1079;&#1085;&#1091;&#1090;&#1088;&#1080; &#1084;&#1091;&#1092;&#1090;&#1099; &#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1080; &#1073;&#1080;&#1088;&#1082;&#1080; &#1089; &#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;. &#1040;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1099;&#1077; &#1073;&#1080;&#1088;&#1082;&#1080;, &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1083;&#1072;&#1075;&#1086;&#1079;&#1072;&#1097;&#1080;&#1090;&#1085;&#1099;&#1077;, &#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1086; <b>&#1082;&#1088;&#1077;&#1087;&#1080;&#1090;&#1100; &#1080; &#1089;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080; &#1084;&#1091;&#1092;&#1090;&#1099;/&#1082;&#1088;&#1086;&#1089;&#1089;&#1072; &#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;</b>, &#1085;&#1072; &#1101;&#1090;&#1080;&#1093; &#1073;&#1080;&#1088;&#1082;&#1072;&#1093; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1091;&#1076;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1080;&#1076;&#1105;&#1090;, &#1082;&#1086;&#1076; &#1083;&#1080;&#1085;&#1080;&#1080; &#1089;&#1074;&#1103;&#1079;&#1080;, &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1077;&#1094; &#1080; &#1087;&#1088;&#1086;&#1095;&#1077;&#1077; &#1087;&#1086; &#1078;&#1077;&#1083;&#1072;&#1085;&#1080;&#1102; &#1079;&#1072;&#1082;&#1072;&#1079;&#1095;&#1080;&#1082;&#1072;. &#1058;&#1072;&#1082;&#1078;&#1077; &#1093;&#1086;&#1088;&#1086;&#1096;&#1080;&#1084; &#1090;&#1086;&#1085;&#1086;&#1084; &#1073;&#1091;&#1076;&#1077;&#1090; &#1082;&#1080;&#1085;&#1091;&#1090;&#1100; &#1074; &#1084;&#1091;&#1092;&#1090;&#1091; &#1082;&#1086;&#1087;&#1080;&#1102; &#1089;&#1093;&#1077;&#1084;&#1099; &#1088;&#1072;&#1089;&#1087;&#1072;&#1081;&#1082;&#1080;
      </li>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082; &#1074;&#1089;&#1077; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1089;&#1074;&#1072;&#1088;&#1077;&#1085;&#1099; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1080; &#1089;&#1086; &#1089;&#1093;&#1077;&#1084;&#1086;&#1081; &#1088;&#1072;&#1079;&#1074;&#1072;&#1088;&#1082;&#1080; &#1080; &#1091;&#1083;&#1086;&#1078;&#1077;&#1085;&#1099;, &#1084;&#1086;&#1078;&#1085;&#1086; (&#1085;&#1077; &#1079;&#1072;&#1073;&#1099;&#1074; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; <b>&#1092;&#1086;&#1090;&#1086;&#1075;&#1088;&#1072;&#1092;&#1080;&#1102; &#1084;&#1091;&#1092;&#1090;&#1099;</b>, &#1077;&#1089;&#1083;&#1080; &#1101;&#1090;&#1086; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090; &#1079;&#1072;&#1082;&#1072;&#1079;&#1095;&#1080;&#1082;, &#1080; &#1082;&#1080;&#1085;&#1091;&#1074; &#1074; &#1084;&#1091;&#1092;&#1090;&#1091; <b>&#1087;&#1072;&#1082;&#1077;&#1090; &#1089;&#1080;&#1083;&#1080;&#1082;&#1072;&#1075;&#1077;&#1083;&#1103;</b>, &#1095;&#1090;&#1086;&#1073;&#1099; &#1089;&#1080;&#1083;&#1080;&#1082;&#1072;&#1075;&#1077;&#1083;&#1100; &#1074;&#1087;&#1080;&#1090;&#1072;&#1083; &#1074; &#1089;&#1077;&#1073;&#1103; &#1074;&#1083;&#1072;&#1075;&#1091; &#1080;&#1079; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1072; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1084;&#1091;&#1092;&#1090;&#1099;) &#1087;&#1088;&#1080;&#1089;&#1090;&#1091;&#1087;&#1072;&#1090;&#1100; &#1082; <b>&#1089;&#1073;&#1086;&#1088;&#1082;&#1077; &#1084;&#1091;&#1092;&#1090;&#1099; &#1080; &#1075;&#1077;&#1088;&#1084;&#1077;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; (</b>&#1074; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1080; &#1089; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1077;&#1081; &#1087;&#1086; &#1089;&#1073;&#1086;&#1088;&#1082;&#1077; &#1084;&#1091;&#1092;&#1090;&#1099;).
      </li>
      <li>
        <b>&#1059;&#1089;&#1072;&#1076;&#1082;&#1091;</b>&#160;&#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1087;&#1072;&#1103;&#1083;&#1100;&#1085;&#1086;&#1081; &#1083;&#1072;&#1084;&#1087;&#1086;&#1081;, &#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084; &#1092;&#1077;&#1085;&#1086;&#1084; &#1080;&#1083;&#1080; &#1075;&#1072;&#1079;&#1086;&#1074;&#1086;&#1081; &#1075;&#1086;&#1088;&#1077;&#1083;&#1082;&#1086;&#1081;. &#1053;&#1072; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1082;&#1077; &#1086;&#1095;&#1077;&#1085;&#1100; &#1091;&#1076;&#1086;&#1073;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1085;&#1089;&#1090;&#1088;&#1091;&#1082;&#1094;&#1080;&#1102; &#1080;&#1079; &#1090;&#1091;&#1088;&#1080;&#1089;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1073;&#1072;&#1083;&#1083;&#1086;&#1085;&#1095;&#1080;&#1082;&#1072; &#1089; &#1075;&#1072;&#1079;&#1086;&#1084; &#1080; &#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1086;&#1081; &#1075;&#1086;&#1088;&#1077;&#1083;&#1082;&#1080;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; <b>&#1090;&#1077;&#1088;&#1084;&#1086;&#1091;&#1089;&#1072;&#1076;&#1082;&#1091; &#1086;&#1076;&#1077;&#1090;&#1100; &#1079;&#1072;&#1073;&#1099;&#1083;&#1080;</b>&#160;- &#1087;&#1086;&#1084;&#1086;&#1078;&#1077;&#1090; &#1090;&#1077;&#1088;&#1084;&#1086;&#1091;&#1089;&#1072;&#1078;&#1080;&#1074;&#1072;&#1077;&#1084;&#1072;&#1103; &#1084;&#1072;&#1085;&#1078;&#1077;&#1090;&#1072; &#1089; &#1079;&#1072;&#1084;&#1082;&#1086;&#1084; (&#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1072;&#1103; &#1082;&#1072;&#1082; XAGA)
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1084;&#1091;&#1092;&#1090;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1089;&#1090;&#1086;&#1083;&#1073;&#1077; (&#1086;&#1087;&#1086;&#1088;&#1077;), &#1090;&#1086; &#1079;&#1072;&#1087;&#1072;&#1089; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1085;&#1072;&#1084;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1073;&#1086;&#1083;&#1100;&#1096;&#1091;&#1102; &#1078;&#1077;&#1083;&#1077;&#1079;&#1085;&#1091;&#1102; &#1082;&#1088;&#1077;&#1089;&#1090;&#1086;&#1074;&#1080;&#1085;&#1091;-&#1059;&#1055;&#1052;&#1050;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1079;&#1072;&#1088;&#1072;&#1085;&#1077;&#1077; &#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082; &#1089;&#1090;&#1086;&#1083;&#1073;&#1091; &#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1083;&#1077;&#1085;&#1090;&#1086;&#1081;.
      </li>
    </ol>
  </body>
</html></richcontent>
