      <b>&#1042;&#1080;&#1079;&#1091;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1094;&#1077;&#1083;&#1086;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080; &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1086;&#1074;</b>
    </p>
    <ol>
      <li>
        &#1055;&#1088;&#1080;&#1073;&#1086;&#1088; &#1074;&#1080;&#1076;&#1080;&#1084;&#1086;&#1075;&#1086; &#1080;&#1079;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103;: &quot;<b>&#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1099;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1080;&#1088;&#1086;&#1074;&#1097;&#1080;&#1082;</b>&quot; &#1080;&#1083;&#1080;&#160;&#160;&quot;<b>&#1087;&#1086;&#1088;&#1090;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088; &#1076;&#1083;&#1103; &#1074;&#1080;&#1079;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1085;&#1072;&#1088;&#1091;&#1078;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077;&#1080;&#1089;&#1087;&#1088;&#1072;&#1074;&#1085;&#1086;&#1089;&#1090;&#1077;&#1081;</b>&quot;. &#1052;&#1086;&#1085;&#1090;&#1072;&#1078;&#1085;&#1080;&#1082;&#1080; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090; &quot;<b>&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084; &#1092;&#1086;&#1085;&#1072;&#1088;&#1080;&#1082;&#1086;&#1084;</b>&quot;. &#1057;&#1074;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074; &#1074;&#1080;&#1076;&#1077; <b><font color="#ff0000">&#1082;&#1088;&#1072;&#1089;&#1085;&#1086;&#1075;&#1086; &#1094;&#1074;&#1077;&#1090;&#1072;</font></b>&#160;&#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1095;&#1077;&#1085;&#1100; &#1079;&#1072;&#1084;&#1077;&#1090;&#1085;&#1099;&#1084; &#1076;&#1072;&#1078;&#1077; &#1085;&#1077;&#1074;&#1086;&#1086;&#1088;&#1091;&#1078;&#1077;&#1085;&#1085;&#1099;&#1084; &#1075;&#1083;&#1072;&#1079;&#1086;&#1084; &#1074; &#1084;&#1077;&#1089;&#1090;&#1077; &#1084;&#1072;&#1082;&#1088;&#1086;&#1080;&#1079;&#1075;&#1080;&#1073;&#1072; - &#1076;&#1091;&#1075;&#1072; &#1087;&#1088;&#1080; &#1089;&#1080;&#1083;&#1100;&#1085;&#1086;&#1084; &#1089;&#1075;&#1080;&#1073;&#1077;, &#1074; &#1084;&#1077;&#1089;&#1090;&#1077; &#1086;&#1073;&#1088;&#1099;&#1074;&#1072;/&#1085;&#1072;&#1076;&#1083;&#1086;&#1084;&#1072; - &#1078;&#1080;&#1088;&#1085;&#1072;&#1103; &#1090;&#1086;&#1095;&#1082;&#1072; &#1087;&#1088;&#1080; &#1085;&#1077;&#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1084; &#1089;&#1075;&#1080;&#1073;&#1077; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;.
      </li>
      <li>
        &#1055;&#1088;&#1086;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1085;&#1072; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1077; (&#1073;&#1086;&#1073;&#1080;&#1085;&#1077;) &#1076;&#1086; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090;&#1072; &#1077;&#1075;&#1086; &#1087;&#1088;&#1086;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080;. &#1047;&#1076;&#1077;&#1089;&#1100;, &#1082;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086;, &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1094;&#1077;&#1083;&#1086;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#160;&#1087;&#1086;&#1089;&#1083;&#1077; &#1090;&#1088;&#1072;&#1085;&#1089;&#1087;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1080; &#1085;&#1072; &#1084;&#1077;&#1089;&#1090;&#1086; &#1073;&#1091;&#1076;&#1091;&#1097;&#1077;&#1081; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080;. &#1042;&#1085;&#1080;&#1084;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1080;&#1097;&#1080;&#1090;&#1077; &#1074;&#1080;&#1076;&#1080;&#1084;&#1099;&#1077; &#1089;&#1083;&#1077;&#1076;&#1099; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1081;. &#1069;&#1090;&#1086; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1086;&#1094;&#1072;&#1088;&#1072;&#1087;&#1072;&#1085;&#1085;&#1099;&#1077; &#1080;&#1083;&#1080; &#1089;&#1083;&#1086;&#1084;&#1072;&#1085;&#1085;&#1099;&#1077; &#1088;&#1077;&#1073;&#1088;&#1072; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1080;, &#1087;&#1077;&#1088;&#1077;&#1075;&#1080;&#1073;&#1099; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1080; &#1090;.&#1087;. &#1042; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1077; &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1072;&#1077;&#1090; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100; &#1089;&#1086;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1072; &#1074;&#1080;&#1079;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1085;&#1072;&#1088;&#1091;&#1078;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077;&#1080;&#1089;&#1087;&#1088;&#1072;&#1074;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089; &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;&#1099;&#1084; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;&#1084;. &#1069;&#1090;&#1086; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; <b>&#1072;&#1076;&#1072;&#1087;&#1090;&#1077;&#1088;&#1072; &#1075;&#1086;&#1083;&#1086;&#1075;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;</b>.
      </li>
    </ol>
    <p>
      &#1063;&#1072;&#1089;&#1090;&#1072;&#1103; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1072; &#1087;&#1088;&#1086;&#1087;&#1072;&#1076;&#1072;&#1085;&#1080;&#1103; &#1089;&#1074;&#1103;&#1079;&#1080; &#8212; &#1101;&#1090;&#1086; <b>&#1083;&#1086;&#1087;&#1085;&#1091;&#1074;&#1096;&#1072;&#1103; &#1082;&#1077;&#1088;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1074;&#1089;&#1090;&#1072;&#1074;&#1082;&#1072; &#1074; &#1088;&#1086;&#1079;&#1077;&#1090;&#1082;&#1077;</b>.
