      </li>
      <li>
        &#1048;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; 850&#1085;&#1084;, 1300&#1085;&#1084;,&#160;1310&#1085;&#1084;, 1490&#1085;&#1084;, 1550&#1085;&#1084; &#1080; 1625&#1085;&#1084;
      </li>
      <li>
        &#1047;&#1072;&#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1086;&#1087;&#1086;&#1088;&#1085;&#1091;&#1102; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1100;: &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082; --&gt; &#1101;&#1090;&#1072;&#1083;&#1086;&#1085;&#1085;&#1099;&#1081; &#1096;&#1085;&#1091;&#1088; --&gt; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100; - &#1090;.&#1077;. &#1086;&#1090;&#1082;&#1072;&#1083;&#1080;&#1073;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;.
      </li>
      <li>
        &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084;&#1089;&#1103; &#1082; &#1083;&#1080;&#1085;&#1080;&#1080;: &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082; --&gt; <b>&#1101;&#1090;&#1072;&#1083;&#1086;&#1085;&#1085;&#1099;&#1081; &#1096;&#1085;&#1091;&#1088;</b>&#160;--&gt; &#1083;&#1080;&#1085;&#1080;&#1103; --&gt; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1100;
      </li>
    </ol>
    <p>
      <b>&#1052;&#1077;&#1090;&#1086;&#1076;&#1099;.</b>&#160;&#1059;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1080;&#1079;&#1084;&#1077;&#1088;&#1103;&#1102;&#1090; &#1076;&#1074;&#1091;&#1084;&#1103; &#1084;&#1077;&#1090;&#1086;&#1076;&#1072;&#1084;&#1080;
    </p>
    <ul>
      <li>
        <b>&#1084;&#1077;&#1090;&#1086;&#1076; &#1086;&#1076;&#1085;&#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1077;&#1075;&#1086; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100;</b>&#160;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1091;&#1089;&#1082;&#1086;&#1074;&#1086;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;
      </li>
      <li>
        <b>&#1084;&#1077;&#1090;&#1086;&#1076; &#1076;&#1074;&#1091;&#1093;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1077;&#1075;&#1086; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100;</b>&#160;&#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085; &#1077;&#1097;&#1105; &#1080; &#1087;&#1088;&#1080;&#1077;&#1084;&#1085;&#1099;&#1084; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;&#1084;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1077;&#1083;&#1102; &#1085;&#1072; &#1087;&#1088;&#1080;&#1077;&#1084;&#1085;&#1086;&#1081; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1077;.
      </li>
    </ul>
    <p>
      <b>&#1055;&#1086;&#1090;&#1077;&#1088;&#1080;</b>
    </p>
    <ul>
      <li>
        &#1053;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1077; &#1087;&#1086;&#1090;&#1077;&#1088;&#1103; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#160;<b>0.5 &#1076;&#1041;</b>&#160;(&#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1091;&#1084; - 0.75 &#1076;&#1041;, &#1085;&#1086;&#1088;&#1084;&#1072; -0.4&#1076;&#1041;).
      </li>
      <li>
        &#1053;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1089;&#1088;&#1086;&#1089;&#1090;&#1082;&#1077; <b>&#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077;&#160;0.3 &#1076;&#1041; (&#1085;&#1086;&#1088;&#1084;&#1072; 0.2&#1076;&#1041;)</b>
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1084;&#1085;&#1086;&#1075;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1075;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072;, &#1087;&#1086;&#1090;&#1077;&#1088;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;

        <ul>
          <li>
            3,5 &#1076;&#1041;/&#1082;&#1084; &#1087;&#1088;&#1080; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; 850 &#1085;&#1084;
          </li>
          <li>
            1,5 &#1076;&#1041;/&#1082;&#1084; &#1087;&#1088;&#1080; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; 1300 &#1085;&#1084;.<br/>
          </li>
        </ul>
      </li>
      <li>
        &#1044;&#1083;&#1103; &#1086;&#1076;&#1085;&#1086;&#1084;&#1086;&#1076;&#1086;&#1074;&#1086;&#1075;&#1086; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1087;&#1086;&#1090;&#1077;&#1088;&#1103; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;

        <ul>
          <li>
            1 &#1076;&#1041;/&#1082;&#1084; &#1087;&#1088;&#1080;&#160;&#160;&#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; 1310 &#1085;&#1084; &#1080; 1550 &#1085;&#1084; (&#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; G.652 A &#1080; B)
          </li>
          <li>
            0.4 &#1076;&#1041;/&#1082;&#1084; &#1085;&#1072; &#1082;&#1080;&#1083;&#1086;&#1084;&#1077;&#1090;&#1088; (&#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; G.652 &#1057; &#1080; D)
          </li>
        </ul>
      </li>
      <li>
        &#1060;&#1086;&#1088;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;, &#1087;&#1086;&#1090;&#1077;&#1088;&#1080;&#160;&#160;&#1085;&#1072; &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1077; &#1042;&#1054;&#1051;&#1057; &#1087;&#1088;&#1080;&#1073;&#1083;&#1080;&#1079;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1100; &#1087;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1081; &#1092;&#1086;&#1088;&#1084;&#1091;&#1083;&#1077;: (0.5 &#1076;&#1041; X &#1095;&#1080;&#1089;&#1083;&#1086; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084;&#1086;&#1074;) + (0.2 &#1076;&#1041; x &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1089;&#1088;&#1086;&#1089;&#1090;&#1082;&#1086;&#1074;) + &#1079;&#1072;&#1090;&#1091;&#1093;&#1072;&#1085;&#1080;&#1077; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1074; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077; &#1085;&#1072; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; &#1093; &#1076;&#1083;&#1080;&#1085;&#1091; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1074; (&#1082;&#1084;).
      </li>
    </ul>
    <p>
      <b>&#1056;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1072;&#1094;&#1080;&#1080;</b>
    </p>
    <ul>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1074;&#1099; &#1086;&#1073;&#1085;&#1072;&#1088;&#1091;&#1078;&#1080;&#1083;&#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1077; &#1087;&#1086;&#1090;&#1077;&#1088;&#1080; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1074; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;, &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1077; &#1077;&#1075;&#1086; &#1074; &#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1086;&#1087;&#1086;&#1083;&#1086;&#1078;&#1085;&#1086;&#1084; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1080; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1100;&#1090;&#1077; &#1077;&#1075;&#1086; &#1087;&#1086; &#1084;&#1077;&#1090;&#1086;&#1076;&#1091; &#1086;&#1076;&#1085;&#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1077;&#1075;&#1086; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100;. &#1055;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1074; &#1101;&#1090;&#1086;&#1084; &#1084;&#1077;&#1090;&#1086;&#1076;&#1077; &#1087;&#1086;&#1090;&#1077;&#1088;&#1080; &#1080;&#1079;&#1084;&#1077;&#1088;&#1103;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084;&#1077; &#1085;&#1072; &#1086;&#1076;&#1085;&#1086;&#1084; &#1082;&#1086;&#1085;&#1094;&#1077; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, &#1074;&#1099; &#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1089;&#1084;&#1086;&#1078;&#1077;&#1090;&#1077; &#1083;&#1086;&#1082;&#1072;&#1083;&#1080;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1084;&#1077;&#1089;&#1090;&#1086;&#1085;&#1072;&#1093;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084;&#1072;
      </li>
      <li>
        &#1055;&#1088;&#1080;&#1095;&#1080;&#1085;&#1072; &#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1085;&#1086;&#1074;&#1077;&#1085;&#1080;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100;, &#1074;&#1099;&#1103;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1084;&#1077;&#1090;&#1086;&#1076;&#1072; &#1076;&#1074;&#1091;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1077;&#1075;&#1086; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100;, &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1083;&#1086;&#1082;&#1072;&#1083;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1072; &#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084;&#160; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1086;&#1075;&#1086; &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086; &#1084;&#1077;&#1090;&#1086;&#1076;&#1091; &#1086;&#1076;&#1085;&#1086;&#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1085;&#1077;&#1075;&#1086; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100; &#1089; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1081;&#1096;&#1080;&#1084; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1074; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1076;&#1083;&#1103; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103;, &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1083;&#1080; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084; &#1085;&#1072; &#1082;&#1086;&#1085;&#1094;&#1077; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1086;&#1084; &#1101;&#1090;&#1080;&#1093; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1086;&#1090;&#1077;&#1088;&#1080; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072; &#1073;&#1091;&#1076;&#1091;&#1090; &#1090;&#1072;&#1082;&#1080;&#1084;&#1080; &#1078;&#1077;, &#1074;&#1072;&#1084; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; <b>&#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1074; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080;</b>, &#1080;&#1083;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; <b>&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;</b>
      </li>
    </ul>
    <p>
      <b>&#1055;&#1088;&#1080;&#1095;&#1080;&#1085;&#1099; &#1087;&#1086;&#1090;&#1077;&#1088;&#1100;</b>
    </p>
    <p>
      - &#1075;&#1088;&#1103;&#1079;&#1085;&#1099;&#1077; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1099; --&gt; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1082;&#1086;&#1087;&#1086;&#1084; --&gt; &#1095;&#1080;&#1089;&#1090;&#1080;&#1084; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1095;&#1080;&#1089;&#1090;&#1103;&#1097;&#1077;&#1081; &#1082;&#1072;&#1089;&#1089;&#1077;&#1090;&#1099;
    </p>
  </body>
