  </head>
  <body>
    <p>
      <a href="#ID_1219366350">&#1054;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;</a><b>&#160; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1045;&#1089;&#1083;&#1080; &#1085;&#1077;&#1087;&#1086;&#1083;&#1072;&#1076;&#1082;&#1080; &#1086;&#1073;&#1085;&#1072;&#1088;&#1091;&#1078;&#1072;&#1090;&#1089;&#1103; &#1074; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077;, &#1090;&#1086; &#1076;&#1083;&#1103; &#1080;&#1093; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1081;&#1096;&#1077;&#1081; &#1083;&#1086;&#1082;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;</b>
    </p>
    <ul>
      <li>
        &#1055;&#1077;&#1088;&#1080;&#1086;&#1076;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; (&#1088;&#1072;&#1079; &#1074; &#1075;&#1086;&#1076;) <b>&#1089;&#1088;&#1072;&#1074;&#1085;&#1080;&#1074;&#1072;&#1090;&#1100; &#1089;&#1090;&#1072;&#1088;&#1099;&#1077; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1089; &#1085;&#1086;&#1074;&#1099;&#1084;&#1080;</b>, &#1089;&#1088;&#1072;&#1079;&#1091; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1080;&#1076;&#1085;&#1086;, &#1075;&#1076;&#1077; &#1095;&#1090;&#1086; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090;, &#1075;&#1076;&#1077; &#1085;&#1072;&#1095;&#1072;&#1083;&#1080; &#1074;&#1099;&#1083;&#1072;&#1079;&#1080;&#1090;&#1100; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1074; &#1084;&#1091;&#1092;&#1090;&#1072;&#1093;, &#1075;&#1076;&#1077; &#1087;&#1086;&#1076;&#1086;&#1079;&#1088;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077;, &#1075;&#1076;&#1077; &#1075;&#1088;&#1103;&#1079;&#1085;&#1099;&#1077; &#1088;&#1086;&#1079;&#1077;&#1090;&#1082;&#1080; &#1074; &#1082;&#1088;&#1086;&#1089;&#1089;&#1077; &#1080; &#1087;&#1088;.
      </li>
      <li>
        <b>&#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1101;&#1082;&#1089;&#1090;&#1088;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1087;&#1072;&#1076;&#1072;&#1085;&#1080;&#1103; &#1089;&#1074;&#1103;&#1079;&#1080;</b>&#160; &#1091; &#1101;&#1082;&#1089;&#1087;&#1083;&#1091;&#1072;&#1090;&#1072;&#1094;&#1080;&#1086;&#1085;&#1097;&#1080;&#1082;&#1086;&#1074; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1072;&#1103; &#1080; &#1072;&#1082;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1093;&#1077;&#1084;&#1072; &#1074;&#1089;&#1077;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; &#1089; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103;&#1084;&#1080;: &#1084;&#1077;&#1078;&#1076;&#1091; &#1073;&#1083;&#1080;&#1078;&#1072;&#1081;&#1096;&#1080;&#1084;&#1080; &#1084;&#1091;&#1092;&#1090;&#1072;&#1084;&#1080; (&#1090;&#1086; &#1077;&#1089;&#1090;&#1100; &#1076;&#1083;&#1080;&#1085;&#1099; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1085;&#1099;&#1093; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1086;&#1074;), &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1086;&#1090; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1084;&#1091;&#1092;&#1090;&#1099; &#1076;&#1086; &#1086;&#1073;&#1086;&#1080;&#1093; &#1082;&#1086;&#1085;&#1094;&#1086;&#1074; &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1072; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099; (&#1076;&#1086; &#1082;&#1088;&#1086;&#1089;&#1089;&#1086;&#1074;). &#1069;&#1090;&#1086; &#1092;&#1086;&#1088;&#1084;&#1072; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1080;&#1079;&#1086;&#1074;&#1072;&#1085;&#1072; &#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1087;&#1072;&#1089;&#1087;&#1086;&#1088;&#1090; &#1090;&#1088;&#1072;&#1089;&#1089;&#1099;, &#1077;&#1105; &#1085;&#1086;&#1084;&#1077;&#1088; &#8212; <b>&#1042;&#1054;&#1051;&#1057; &#1055;&#1058;-4</b>. &#1055;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1077;&#1105; &#1074; &#1072;&#1082;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1101;&#1082;&#1089;&#1087;&#1083;&#1091;&#1072;&#1090;&#1072;&#1094;&#1080;&#1086;&#1085;&#1097;&#1080;&#1082;&#1080;.
      </li>
      <li>
        &#1054;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084;&#1099; &#1080; &#1084;&#1077;&#1089;&#1090;&#1072; &#1089;&#1088;&#1072;&#1097;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1080;&#1080; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &quot;&#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103;&#1084;&#1080;&quot;
      </li>
      <li>
        <b>&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084;&#1099;</b>&#160;&#1080; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1077;&#1083;&#1080; (&#1089;&#1087;&#1083;&#1072;&#1081;&#1089;&#1099;) <b>&#1087;&#1086;&#1088;&#1086;&#1078;&#1076;&#1072;&#1102;&#1090; &#1086;&#1090;&#1088;&#1072;&#1078;&#1072;&#1102;&#1097;&#1080;&#1081; &#1074;&#1089;&#1087;&#1083;&#1077;&#1089;&#1082;. </b>&#1042;&#1099;&#1089;&#1086;&#1090;&#1091; &#1087;&#1080;&#1082;&#1072; (&#1085;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1077;) &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1084;&#1077;&#1085;&#1100;&#1096;&#1080;&#1090;&#1100;, <b>&#1087;&#1086;&#1095;&#1080;&#1089;&#1090;&#1080;&#1074; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;</b>
      </li>
      <li>
        <b>&#1084;&#1077;&#1089;&#1090;&#1072; &#1089;&#1074;&#1072;&#1088;&#1082;&#1080;</b>&#160;&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1086;&#1090;&#1088;&#1072;&#1078;&#1072;&#1102;&#1097;&#1080;&#1081; <b>&#1074;&#1089;&#1087;&#1083;&#1077;&#1089;&#1082; &#1085;&#1077; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090;</b>
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; <b>&#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1086; &#1073;&#1099;&#1083;&#1086; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1086;</b>,&#160;&#1090;&#1086; &#1077;&#1075;&#1086; <b>&#1076;&#1083;&#1080;&#1085;&#1072;</b>, &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1105;&#1085;&#1085;&#1072;&#1103; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1072;, &#1086;&#1082;&#1072;&#1078;&#1077;&#1090;&#1089;&#1103; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; <b>&#1084;&#1077;&#1085;&#1100;&#1096;&#1077; &#1074;&#1089;&#1077;&#1081; &#1076;&#1083;&#1080;&#1085;&#1099;</b>&#160;&#160;&#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, &#1072; &#1084;&#1077;&#1089;&#1090;&#1086; &#1089;&#1082;&#1086;&#1083;&#1072; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1080;&#1076;&#1085;&#1086; &#1085;&#1072; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1077; &#1082;&#1072;&#1082; &#1084;&#1077;&#1089;&#1090;&#1086; &#1089;&#1088;&#1072;&#1097;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1089; &#1074;&#1099;&#1089;&#1086;&#1082;&#1080;&#1084;&#1080; &#1087;&#1086;&#1090;&#1077;&#1088;&#1103;&#1084;&#1080;
      </li>
      <li>
        &#1042;&#1089;&#1077;&#1075;&#1076;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1081;&#1090;&#1077; &#1076;&#1083;&#1080;&#1085;&#1085;&#1099;&#1081; <b>&#1087;&#1091;&#1089;&#1082;&#1086;&#1074;&#1086;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;</b>, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1080;&#1090; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1091; &#1089;&#1090;&#1072;&#1073;&#1080;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077; &#1089;&#1090;&#1072;&#1088;&#1090;&#1086;&#1074;&#1086;&#1075;&#1086; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1072;. &#1069;&#1090;&#1086;&#1090; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1101;&#1090;&#1072;&#1083;&#1086;&#1085;&#1085;&#1099;&#1084; &#1076;&#1083;&#1103; &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1091;&#1095;&#1072;&#1089;&#1090;&#1082;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1077;&#1088;&#1074;&#1086;&#1075;&#1086; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100;. &#1044;&#1083;&#1103; &#1083;&#1091;&#1095;&#1096;&#1077;&#1075;&#1086; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;, &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1081;&#1090;&#1077; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1091; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088;&#1086;&#1084; &#1089; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1085;&#1072;&#1080;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1081; &#1076;&#1083;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; &#1080;&#1084;&#1087;&#1091;&#1083;&#1100;&#1089;&#1072; &#1080;&#160;&#160;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1081;&#1090;&#1077; &#1087;&#1091;&#1089;&#1082;&#1086;&#1074;&#1086;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; (&#1085;&#1086;&#1088;&#1084;&#1072;&#1083;&#1080;&#1079;&#1091;&#1102;&#1097;&#1091;&#1102; &#1082;&#1072;&#1090;&#1091;&#1096;&#1082;&#1091;), <b>&#1076;&#1083;&#1080;&#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1072;&#1077;&#1090; &#1076;&#1083;&#1080;&#1085;&#1091; &#1086;&#1087;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1074;&#1099; &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090;&#1077;, &#1082;&#1072;&#1082; &#1084;&#1080;&#1085;&#1080;&#1084;&#1091;&#1084;, &#1074; &#1076;&#1074;&#1072; &#1088;&#1072;&#1079;&#1072;</b>.<br/>&#1057;&#1076;&#1077;&#1083;&#1072;&#1081;&#1090;&#1077; &#1089;&#1090;&#1072;&#1088;&#1090;&#1086;&#1074;&#1091;&#1102; &#1090;&#1088;&#1072;&#1089;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1091;, &#1080; &#1074;&#1099; &#1091;&#1074;&#1080;&#1076;&#1080;&#1090;&#1077;, &#1082;&#1072;&#1082;&#1080;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1093;&#1086;&#1088;&#1086;&#1096;&#1080;&#1077; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1099;.
      </li>
      <li>
        <b><font color="#ff0000">&#1053;&#1080;&#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1077; &#1080;&#1076;&#1080;&#1090;&#1077; &#1087;&#1086; &#1083;&#1077;&#1075;&#1082;&#1086;&#1084;&#1091; &#1087;&#1091;&#1090;&#1080;</font></b>, &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1087;&#1086;&#1076;&#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1074; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1090;&#1086;&#1084;&#1077;&#1090;&#1088; &#1082; &#1080;&#1079;&#1084;&#1077;&#1088;&#1103;&#1077;&#1084;&#1086;&#1081; &#1042;&#1054;&#1051;&#1057; &#1080; &#1085;&#1072;&#1078;&#1072;&#1074; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091; &quot;&#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1090;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&quot;)! &#1055;&#1086;&#1076;&#1086;&#1073;&#1085;&#1099;&#1077; &#1089;&#1083;&#1091;&#1095;&#1072;&#1080;, &#1079;&#1072;&#1095;&#1072;&#1089;&#1090;&#1091;&#1102;, &#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1088;&#1080;&#1074;&#1077;&#1089;&#1090;&#1080; &#1082; <font color="#ff0000">&#1087;&#1086;&#1083;&#1086;&#1084;&#1082;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;</font>
      </li>
      <li>
        <b>&#1058;&#1088;&#1077;&#1097;&#1080;&#1085;&#1072; &#1074; &#1074;&#1086;&#1083;&#1086;&#1082;&#1085;&#1077;, &#1086;&#1073;&#1088;&#1099;&#1074; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1074; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077;.</b>&#160;&#160;&#1045;&#1089;&#1083;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077; &#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1077; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1081; &#1085;&#1077; &#1079;&#1072;&#1084;&#1077;&#1090;&#1085;&#1086; (&#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#160;&#160;&#1083;&#1086;&#1082;&#1072;&#1083;&#1080;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077;). &#1042; &#1093;&#1091;&#1076;&#1096;&#1077;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074;&#1099;&#1088;&#1077;&#1079;&#1072;&#1090;&#1100; &#1084;&#1077;&#1090;&#1088;&#1086;&#1074; 200-400 &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1080; &#1074;&#1072;&#1088;&#1080;&#1090;&#1100; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1091;&#1102; &#1074;&#1089;&#1090;&#1072;&#1074;&#1082;&#1091;, &#1095;&#1090;&#1086;&#1073; &#1085;&#1072;&#1074;&#1077;&#1088;&#1085;&#1103;&#1082;&#1072; &#1087;&#1077;&#1088;&#1077;&#1082;&#1088;&#1099;&#1090;&#1100; &#1087;&#1088;&#1077;&#1076;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1077;&#1084;&#1086;&#1077; &#1084;&#1077;&#1089;&#1090;&#1086; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103;.
      </li>
    </ul>
