      <li>
        &#1045;&#1089;&#1083;&#1080; &#1089;&#1093;&#1077;&#1084;&#1072; &#1088;&#1072;&#1089;&#1087;&#1072;&#1081;&#1082;&#1080; &#1089;&#1083;&#1086;&#1078;&#1085;&#1072;&#1103;, &#1074; &#1083;&#1080;&#1085;&#1080;&#1080; &#1084;&#1085;&#1086;&#1075;&#1086; &#171;&#1090;&#1088;&#1086;&#1081;&#1085;&#1080;&#1082;&#1086;&#1074;&#1099;&#1093;&#187; (&#1080;&#1083;&#1080; &#171;&#1086;&#1090;&#1087;&#1072;&#1081;&#1085;&#1099;&#1093;&#187;) &#1084;&#1091;&#1092;&#1090;, &#1089;&#1087;&#1072;&#1103;&#1085;&#1099; &#1082;&#1072;&#1073;&#1077;&#1083;&#1080; &#1089; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084;&#1080; &#1094;&#1074;&#1077;&#1090;&#1072;&#1084;&#1080; &#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085; &#1080; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086;&#1084; &#1080;&#1093; &#1074; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1093; &#8212; &#1079;&#1072;&#1076;&#1072;&#1095;&#1072; &#1089;&#1080;&#1083;&#1100;&#1085;&#1086; &#1091;&#1089;&#1083;&#1086;&#1078;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103;. &#1058;&#1091;&#1090; &#1091;&#1078; &#1087;&#1088;&#1080;&#1076;&#1105;&#1090;&#1089;&#1103; &#1089;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100; &#1084;&#1086;&#1079;&#1075;&#1086;&#1074;&#1086;&#1081; &#1096;&#1090;&#1091;&#1088;&#1084;, &#1074;&#1089;&#1077;&#1088;&#1100;&#1105;&#1079; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1084;&#1086;&#1079;&#1075; &#1080; &#1087;&#1086;&#1089;&#1080;&#1076;&#1077;&#1090;&#1100; &#1085;&#1072;&#1076; &#1089;&#1093;&#1077;&#1084;&#1072;&#1084;&#1080;, &#1074;&#1099;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1103; &#1089;&#1072;&#1084;&#1099;&#1081; &#1086;&#1087;&#1090;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1083;&#1072;&#1085; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072; &#1084;&#1091;&#1092;&#1090;&#1099; &#1089; &#1087;&#1077;&#1088;&#1077;&#1087;&#1091;&#1090;&#1082;&#1086;&#1081;. &#1040; &#1074;