  <body>
    <p>
      <b>10BASE-5</b>&#160;(&#1090;&#1072;&#1082;&#1078;&#1077; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1077;&#1085; &#1082;&#1072;&#1082; <b>&#1090;&#1086;&#1083;&#1089;&#1090;&#1099;&#1081; Ethernet</b>) &#8212; &#1086;&#1088;&#1080;&#1075;&#1080;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; (&#1087;&#1077;&#1088;&#1074;&#1099;&#1081;) &#171;&#1087;&#1086;&#1083;&#1085;&#1099;&#1081; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#187; &#1089;&#1087;&#1077;&#1094;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; Ethernet, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1083; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1086;&#1072;&#1082;&#1089;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1090;&#1080;&#1087;&#1072; RG-8X. &#1069;&#1090;&#1086; &#1078;&#1105;&#1089;&#1090;&#1082;&#1080;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;, &#1076;&#1080;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1084; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1085;&#1086; 9 &#1084;&#1084;, &#1089; &#1074;&#1086;&#1083;&#1085;&#1086;&#1074;&#1099;&#1084; &#1089;&#1086;&#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;&#1084; 50 &#1054;&#1084;, &#1089; &#1078;&#1105;&#1089;&#1090;&#1082;&#1086;&#1081; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1078;&#1080;&#1083;&#1086;&#1081;, &#1087;&#1086;&#1088;&#1080;&#1089;&#1090;&#1099;&#1084; &#1080;&#1079;&#1086;&#1083;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1084; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1077;&#1084;, &#1079;&#1072;&#1097;&#1080;&#1090;&#1085;&#1099;&#1084; &#1087;&#1083;&#1077;&#1090;&#1105;&#1085;&#1099;&#1084; &#1101;&#1082;&#1088;&#1072;&#1085;&#1086;&#1084; &#1080; &#1079;&#1072;&#1097;&#1080;&#1090;&#1085;&#1086;&#1081; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1086;&#1081;. &#1042;&#1085;&#1077;&#1096;&#1085;&#1103;&#1103; &#1086;&#1073;&#1086;&#1083;&#1086;&#1095;&#1082;&#1072; &#1082;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086; &#1080;&#1084;&#1077;&#1083;&#1072; &#1078;&#1105;&#1083;&#1090;&#1086;-&#1086;&#1088;&#1072;&#1085;&#1078;&#1077;&#1074;&#1091;&#1102; &#1086;&#1082;&#1088;&#1072;&#1089;&#1082;&#1091; &#1080;&#1079; &#1101;&#1090;&#1080;&#1083;&#1077;&#1085; &#1087;&#1088;&#1086;&#1087;&#1080;&#1083;&#1077;&#1085;&#1072; (&#1076;&#1083;&#1103; &#1086;&#1075;&#1085;&#1077;&#1089;&#1090;&#1086;&#1081;&#1082;&#1086;&#1089;&#1090;&#1080;)
    </p>
    <ul>
      <li>
        &#1084;&#1072;&#1082;&#1089;. &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; - <b>10 &#1052;&#1073;&#1080;&#1090;/&#1089;</b>. BASE (&#1086;&#1090; baseband - &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1072; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1086;&#1074; &#1073;&#1077;&#1079; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1094;&#1080;&#1080;), 5 (&#1086;&#1090;&#1089;&#1099;&#1083;&#1082;&#1072; &#1082; &#1095;&#1080;&#1089;&#1083;&#1091; <b>500 - &#1084;&#1072;&#1082;&#1089;. &#1076;&#1083;&#1080;&#1085;&#1072; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072; &#1089;&#1077;&#1090;&#1080;</b>, &#1083;&#1080;&#1073;&#1086; &#1074;&#1085;&#1077;&#1096;&#1085;&#1103;&#1103; &#1090;&#1086;&#1083;&#1097;&#1080;&#1085;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1074;&#160;&#160;0,5 &#1076;&#1102;&#1081;&#1084;&#1072;)
      </li>
      <li>
        &#1084;&#1086;&#1078;&#1085;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; <b>&#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1073;&#1077;&#1079; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080; &#1080; &#1088;&#1072;&#1079;&#1088;&#1099;&#1074;&#1072; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;.</b>&#160;&#1069;&#1090;&#1086; &#1076;&#1086;&#1089;&#1090;&#1080;&#1075;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1090;. &#1085;. &#171;&#1090;&#1088;&#1077;&#1079;&#1091;&#1073;&#1094;&#1077;&#1074;&#187; &#1080;&#1083;&#1080; &#171;&#1074;&#1072;&#1084;&#1087;&#1080;&#1088;&#1095;&#1080;&#1082;&#1086;&#1074;&#187; (vampire tap) &#8212; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1089; &#1076;&#1086;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084; &#1091;&#1089;&#1080;&#1083;&#1080;&#1077;&#1084; &#171;&#1087;&#1088;&#1086;&#1082;&#1091;&#1089;&#1099;&#1074;&#1072;&#1083;&#1086;&#187; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;, &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1096;&#1080;&#1087; &#1082;&#1086;&#1085;&#1090;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1083; &#1089; &#1094;&#1077;&#1085;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1078;&#1080;&#1083;&#1086;&#1081; &#1082;&#1086;&#1072;&#1082;&#1089;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, &#1072; &#1076;&#1074;&#1072; &#1073;&#1086;&#1082;&#1086;&#1074;&#1099;&#1093; &#1096;&#1080;&#1087;&#1072; &#1074;&#1093;&#1086;&#1076;&#1080;&#1083;&#1080; &#1074; &#1082;&#1086;&#1085;&#1090;&#1072;&#1082;&#1090; &#1089; &#1101;&#1082;&#1088;&#1072;&#1085;&#1086;&#1084; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;. &#1050;&#1072;&#1082; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086; &#171;&#1090;&#1088;&#1077;&#1079;&#1091;&#1073;&#1077;&#1094;&#187; &#1089;&#1086;&#1074;&#1084;&#1077;&#1097;&#1072;&#1083;&#1089;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1084; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1077; &#1089; &#1087;&#1088;&#1080;&#1105;&#1084;&#1086;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1086;&#1084;
      </li>
      <li>
        &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; <b>&#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1091;&#1079;&#1083;&#1086;&#1074;</b>, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1099; &#1089; 10BASE-5 &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1086;&#1084;, &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1086; <b>100</b>, &#1072; <b>&#1076;&#1083;&#1080;&#1085;&#1072;</b>&#160;&#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; <b>500 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074;</b>. &#1055;&#1088;&#1080;&#1105;&#1084;&#1086;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; <b>&#1089; &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083;&#1086;&#1084; &#1074; 2,5 &#1084;&#1077;&#1090;&#1088;&#1072; (</b>&#1069;&#1090;&#1086; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1075;&#1088;&#1091;&#1073;&#1086; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1076;&#1083;&#1080;&#1085;&#1077; &#1074;&#1086;&#1083;&#1085;&#1099; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072;. &#1055;&#1086;&#1076;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1084;&#1077;&#1089;&#1090;&#1072; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1087;&#1088;&#1080;&#1105;&#1084;&#1086;&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1095;&#1080;&#1082;&#1086;&#1074; <b>&#1086;&#1090;&#1084;&#