      </li>
      <li>
        &#1050;&#1072;&#1073;&#1077;&#1083;&#1100; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1088;&#1086;&#1082;&#1083;&#1072;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1077;&#1076;&#1080;&#1085;&#1099;&#1084; &#1094;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1086;&#1084;, T-&#1086;&#1073;&#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1089;&#1074;&#1103;&#1079;&#1077;&#1081; &#1085;&#1077; &#1076;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103;. &#1053;&#1072; &#1082;&#1086;&#1085;&#1094;&#1072;&#1093; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1090;&#1086;&#1088;&#1099; 50 &#1054;&#1084;
      </li>
    </ul>
