    <p>
      <b>&#1050;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1096;&#1085;&#1091;&#1088;</b>, <b>&#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;</b>, &#1078;&#1072;&#1088;&#1075;. <b>&#1087;&#1072;&#1090;&#1095;-&#1082;&#1086;&#1088;&#1076;</b>&#160; (&#1086;&#1090; &#1072;&#1085;&#1075;&#1083;. patching cord &#8212; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1096;&#1085;&#1091;&#1088;) &#8212; &#1086;&#1076;&#1085;&#1072; &#1080;&#1079; &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1085;&#1099;&#1093; &#1095;&#1072;&#1089;&#1090;&#1077;&#1081; &#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1055;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1073;&#1086;&#1081; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1080;&#1083;&#1080; &#1086;&#1087;&#1090;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1086;&#1085;&#1085;&#1099;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1082; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091; &#1080;&#1083;&#1080; &#1082; &#1087;&#1072;&#1089;&#1089;&#1080;&#1074;&#1085;&#1086;&#1084;&#1091; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1072;.
    </p>
    <ul>
      <li>
        &#1052;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1083;&#1102;&#1073;&#1099;&#1093; &#1090;&#1080;&#1087;&#1086;&#1074;, &#1085;&#1086; &#1085;&#1077; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1086;&#1074;, &#1087;&#1086; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1091; ANSI EIA TIA 568B.1 &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1072;&#1090;&#1100; 5 &#1084; &#1076;&#1083;&#1080;&#1085;&#1099;, &#1079;&#1072; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;&#1084; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1080;&#1103; TSB-75 &#1076;&#1083;&#1103; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1093; &#1086;&#1092;&#1080;&#1089;&#1086;&#1074; (&#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1085;&#1086; TSB-75 &#1076;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1081; &#1076;&#1083;&#1080;&#1085;&#1099;)
      </li>
      <li>
        &#1053;&#1072; &#1086;&#1073;&#1086;&#1080;&#1093; &#1082;&#1086;&#1085;&#1094;&#1072;&#1093; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1077;&#1084;&#1099;&#1084; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1084; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1099;
      </li>
      <li>
        &#1052;&#1085;&#1086;&#1075;&#1086; &#1078;&#1080;&#1083;&#1086;&#1082;. &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079; &#1075;&#1080;&#1073;&#1082;&#1086;&#1075;&#1086; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;. &#1048;&#1079;-&#1079;&#1072; &#1084;&#1085;&#1086;&#1075;&#1086;&#1078;&#1080;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080; &#1087;&#1083;&#1086;&#1093;&#1086; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1080;&#1090; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;. &#1053;&#1086;&#1078; &#1074; &#1087;&#1072;&#1090;&#1095;-&#1082;&#1086;&#1088;&#1076;&#1086;&#1074;&#1086;&#1081; &#1074;&#1080;&#1083;&#1082;&#1077; &#1074; &#1092;&#1086;&#1088;&#1084;&#1077; &#1079;&#1091;&#1073;&#1080;&#1083;&#1072;, &#1088;&#1072;&#1079;&#1076;&#1074;&#1080;&#1075;&#1072;&#1077;&#1090; &#1078;&#1080;&#1083;&#1082;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;
