    </p>
    <p>
      <b>Cisco Catalyst 4900 - </b>&#1052;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100;, &#1089;&#1091;&#1087;&#1077;&#1088;&#1073;&#1099;&#1089;&#1090;&#1088;&#1099;&#1077; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1099; &#1076;&#1083;&#1103; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081;.&#160;&#160;&#1047;&#1072;&#1090;&#1086;&#1095;&#1077;&#1085;&#1099; &#1085;&#1072; &#1089;&#1082;&#1074;&#1086;&#1079;&#1085; &#1086;&#1077; &#1087;&#1088;&#1086;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1085;&#1080;&#1077; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;
    </p>
    <p>
      <b>Cisco Catalyst 6500</b>&#160;- &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1099; &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1077;&#1081; <b>Distribution</b>&#160; (&#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &quot;&#1093;&#1086;&#1083;&#1086;&#1076;&#1080;&#1083;&#1100;&#1085;&#1080;&#1082;&quot;), &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;&#1085;&#1099;&#1081; - &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086; &#1096;&#1072;&#1089;&#1089;&#1080;, &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086; &#1083;&#1080;&#1085;&#1077;&#1081;&#1085;&#1099;&#1077; &#1082;&#1072;&#1088;&#1090;&#1099;
    </p>
    <ul>
      <li>
        &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; (&#1089;&#1091;&#1087;&#1077;&#1088;&#1074;&#1080;&#1079;&#1086;&#1088;) - &#1062;&#1055;, RAM, Flash &#1087;&#1072;&#1084;&#1103;&#1090;&#1100; (NVRAM). &#1052;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; <b>&#1076;&#1074;&#1072; </b>(&#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1080; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1081;). <b>&#1056;&#1077;&#1078;&#1080;&#1084;&#1099; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1080;</b>:<br/><b>RPR - Route Processor Redundancy</b>&#160;- (&gt;2x &#1084;&#1080;&#1085;&#1091;&#1090;) - &#1079;&#1072;&#1087;&#1072;&#1089;&#1085;&#1086;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1086;&#1090;&#1082;&#1072;&#1079;&#1072; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;<br/><b>RPR+</b>&#160; - (~30 &#1089;&#1077;&#1082;.) - &#1054;&#1057; &#1079;&#1072;&#1087;&#1072;&#1089;&#1085;&#1086;&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085;&#1072;, &#1086;&#1076;&#1085;&#1072;&#1082;&#1086; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1080; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1099; &#1073;&#1091;&#1076;&#1091;&#1090; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085;&#1099; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1086;&#1090;&#1082;&#1072;&#1079;&#1072; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;<br/><b>SSO - Stateful Switchover</b>&#160;- (~1 &#1089;&#1077;&#1082;.)&#160;&#160;- &#1079;&#1072;&#1087;&#1072;&#1089;&#1085;&#1086;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1077;&#1090; &#1090;&#1077;&#1082;&#1091;&#1097;&#1091;&#1102; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; &#1086;&#1089;&#1085;&#1086;&#1074;&#1086;&#1085;&#1086;&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;<br/>
      </li>
      <li>
        &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080; - &#1087;&#1086;&#1088;&#1090;&#1099;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>Cisco Catalyst 6500 Virtual Switching System</b>&#160;- &#1052;&#1072;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100;
    </p>
  </body>
</html></richcontent>
</node>
