<node TEXT="Задачи" FOLDED="true" ID="ID_89852568" CREATED="1519112080155" MODIFIED="1733837985841">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_917847831">Команды Cisco (troubleshooting)</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">enable</span>&#xa0;&#xa0;// Включить режим <b>привилегированного</b>&#xa0;доступа
    </p>
    <p>
      <span style="color: #0000c0;">configure terminal</span>&#xa0;&#xa0;// Перейти в&#xa0;режим <b>конфигурирования</b>.&#xa0;--&gt; (config) #
    </p>
    <p>
      (config)# <span style="color: #0000c0;">exit</span>&#xa0;&#xa0;//&#xa0;<b>Выйти</b>&#xa0;из режима конфигурирования
    </p>
    <p>
      (config)# <span style="color: #0000c0;">end</span>
    </p>
    <p>
      <span style="color: #0000c0;">write&#xa0;memory</span>&#xa0;&#xa0;// <b>Сохранить</b>&#xa0;в энергонезависимой памяти. (Говорят) <span style="color: #0000c0;">copy running-config startup-config</span>&#xa0;также сохраняет настройки после перезагрузки
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">reload</span>&#xa0;&#xa0;// <b>Перезагрузить</b>&#xa0;устройство
    </p>
  </body>
</html></richcontent>
<node TEXT="# Help" ID="ID_43964075" CREATED="1519112080155" MODIFIED="1519112080155"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1086;&#1082;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100; (e.g. <font color="#0000c0">write</font>&#160; --&gt; <font color="#0000c0">wr</font>)</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;&#160;&#160;(User EXEC mode)</b>&#160;- 1 &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; (0-15). &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102; (&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1085;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1072;), &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;
    </p>
    <p>
      <b>&#1055;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084; (Privileged EXEC)</b>&#160; - 15 &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; (0-15). &#1052;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#0000c0">&gt;&#160;</font>// &#1085;&#1077;&#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1077; &#1087;&#1088;&#1080;&#1075;&#1083;&#1072;&#1096;&#1077;&#1085;&#1080;&#1077; <b>(&gt;)</b>. &#1058;.&#1077;. &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1085;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090;.
    </p>
    <p>
      <font color="#0000c0">&gt; enable</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080; &#1074; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084; (&#1089;&#1086;&#1082;&#1088;. <font color="#0000c0">en</font>) 15 &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; (0-15)
    </p>
    <p>
      <font color="#0000c0"># disable</font>&#160;// &#1074;&#1099;&#1093;&#1086;&#1076; &#1080;&#1079; &#1087;&#1088;&#1080;&#1074;. &#1088;&#1077;&#1078;&#1080;&#1084;&#1072; &#1074; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1081; (0 &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">&gt; ?</font>&#160;&#1080;&#1083;&#1080; <font color="#0000c0"># ?</font>&#160;// &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1074;&#1089;&#1077;&#1093; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;&#1093; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;
    </p>
    <p>
      <font color="#0000c0"># cl?</font>&#160;// &#1074;&#1099;&#1076;&#1072;&#1090;&#1100; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1102;&#1097;&#1080;&#1093;&#1089;&#1103; &#1085;&#1072; <b>cl</b>&#160;
    </p>
    <p>
      <font color="#0000c0"># clock ?</font>&#160;// &#1074;&#1099;&#1076;&#1072;&#1090;&#1100; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1076;&#1083;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;
    </p>
    <p>
      <b>Ctrl-Shift-6&#160;</b>// &#1087;&#1088;&#1077;&#1088;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; (ping or traceroute)
    </p>
    <p>
      <b>Ctrl-C</b>&#160;// &#1087;&#1088;&#1077;&#1088;&#1074;&#1072;&#1090;&#1100; &#1090;&#1077;&#1082;&#1091;&#1097;&#1091;&#1102; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1080; &#1074;&#1099;&#1081;&#1090;&#1080; &#1074; &#1082;&#1086;&#1085;&#1092;. &#1088;&#1077;&#1078;&#1080;&#1084;
    </p>
    <p>
      <b>Ctrl-Z</b>&#160;// &#1079;&#1072;&#1082;&#1086;&#1085;&#1095;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;. &#1088;&#1077;&#1078;&#1080;&#1084; &#1080; &#1074;&#1099;&#1081;&#1090;&#1080; &#1074; &#1082;&#1086;&#1088;&#1077;&#1085;&#1100; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># show history</font>&#160;// &#1080;&#1089;&#1090;&#1086;&#1088;&#1080;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076; (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;. 20), &#1089;&#1086;&#1093;&#1088;. &#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1089;&#1077;&#1089;&#1089;&#1080;&#1080;
    </p>
    <p>
      <font color="#0000c0"># terminal history size 50</font>&#160;// &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1080;&#1090;&#1100; &#1080;&#1089;&#1090;&#1086;&#1088;&#1080;&#1102; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076; &#1076;&#1086; 50
    </p>
    <p>
      <font color="#0000c0">(config)# <b>do &lt;command&gt;</b>&#160;</font>// &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076; &#1085;&#1077; &#1074;&#1099;&#1093;&#1086;&#1076;&#1103; &#1080;&#1079; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; (&#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1072;&#1074;&#1090;&#1086;&#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1077; &lt;Tab&gt;). <b>&#1042; Cisco ASA - &#1084;&#1086;&#1078;&#1085;&#1086; &#1073;&#1077;&#1079; do</b>
    </p>
    <p>
      <font color="#0000c0">(config-if)# interface &lt;<b>&#1044;&#1088;&#1091;&#1075;&#1086;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;</b>&gt;</font>&#160; // &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1073;&#1077;&#1079; &#1074;&#1099;&#1093;&#1086;&#1076;&#1072;
    </p>
    <p>
      <font color="#0000c0">(config)# <b>no</b>&#160;&lt;&#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072;&gt;</font>&#160;// &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1080;&#1077;/&#1086;&#1090;&#1084;&#1077;&#1085;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1080;&#1079; running-config
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      &#1089;&#1084;. <a href="#ID_170108090">&#1059;&#1085;&#1080;&#1074;&#1077;&#1088;&#1089;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1088;&#1080;&#1077;&#1084;&#1099; CLI &#1076;&#1083;&#1103; Unix &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      ------------------------------&#1088;&#1072;&#1079;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100;
    </p>
    <p>
      <b>sw # </b><font color="#0000c0">show cdp neighbors</font><font color="#000000">&#160;# &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; <a href="#ID_17970777">CDP</a>. </font>
    </p>
    <p>
      <b>sw # </b><font color="#0000c0">configure terminal</font>&#160;# &#1074;&#1093;&#1086;&#1076; &#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083; &gt; <b>sw (config) #</b>
    </p>
    <p>
      <font color="#000000"><b>sw (config) # </b></font><font color="#0000c0">hostname &lt;NewName&gt;</font>&#160;# &#1089;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1080;&#1084;&#1103; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072; &gt; <b>NewName (config) # </b>
    </p>
    <p>
      <font color="#000000"><b>Ctrl+Z</b></font>&#160;# &#1074;&#1099;&#1093;&#1086;&#1076; &#1080;&#1079; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1072;
    </p>
    <p>
      <font color="#000000"><b>sw #</b></font><font color="#0000c0">&#160;copy running-config startup-config</font>&#160;# &#1082;&#1086;&#1087;&#1080;&#1088;&#1091;&#1077;&#1090; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1080;&#1079; RAM &#1085;&#1072; &#1092;&#1083;&#1077;&#1096;&#1082;&#1091; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072;; &#1085;&#1072; &#1078;&#1077;&#1083;&#1077;&#1079;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090; <font color="#0000c0">write</font>&#160;(&#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1085;&#1072; &#1101;&#1084;&#1091;&#1083;&#1103;&#1090;&#1086;&#1088;&#1077;)
    </p>
    <p>
      <font color="#000000"><b>sw #</b></font><font color="#0000c0">&#160;show vlan brief </font><font color="#000000"># &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; VLAN&#1099;</font>
    </p>
    <p>
      <b>sw # </b><font color="#0000c0">reload</font>&#160;# &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072;
    </p>
    <p>
      <font color="#0000c0"># erase flash</font>&#160;// &#1092;&#1086;&#1084;&#1072;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1054;&#1057; &#1085;&#1072; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; (&#1089;&#1090;&#1077;&#1088;&#1077;&#1090;&#1100; &#1074;&#1089;&#1105; &#1085;&#1072; flash)
    </p>
    <p>
      <font color="#0000c0"># erase nvram</font>&#160;// &#1089;&#1090;&#1077;&#1088;&#1077;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;
    </p>
  </body>
</html></richcontent>
</node>
