<node TEXT="Access List (ACL)" FOLDED="true" ID="ID_607884616" CREATED="1519112080156" MODIFIED="1725457197612"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1586644377">Access List</a>&nbsp;&nbsp; <a href="#ID_1231772881">VLAN (Cisco)</a>
    </p>
    <ul>
      <li>
        ACL настраивается на <b>роутере</b>
      </li>
      <li>
        действие - <b>сверху-вниз</b>, от <b>частного к общему</b>
      </li>
      <li>
        <b>сменить очередь в нумерованном ACL</b>&nbsp;- пересоздать, т.е. отменить и создать заново (используя блокнот)
      </li>
      <li>
        <font color="#000000">неявное правило&nbsp; <b>deny ip any any</b></font>
      </li>
      <li>
        <p>
          <b>in</b>&nbsp;- пакет будет обрабатываться ACLом на входе
        </p>
        <p>
          <b>out</b>&nbsp;- пакет обрабатывается роутером, потом ACL (на выходе)
        </p>
      </li>
      <li>
        <b>Стандартные ACL&nbsp;размещать ближе к получателю </b>(на исходящий трафик). Т.е. трафик проходя роутер дропается на выходе <b>Расширенные ACL&nbsp;- размещать ближе к источнику</b>&nbsp;(на входящий трафик)
      </li>
      <li>
        стандартные (номера 1-99, 1300-1999) расширенные (номера 100-199, 2000-2699)
      </li>
    </ul>
    <p>
      <font color="#0000c0">show access-lists</font>&nbsp;&nbsp;// <b>Список</b>&nbsp;ACLs. Содержание тамже. Можно вывести только один, указав номер ACL
    </p>
    <p>
      <font color="#0000c0">show running-config</font>&nbsp;&nbsp;// <b>К какому порту</b>&nbsp;какое ACL-правило <b>прикреплено</b>. Внимательно смотрим вывод
    </p>
    <p>
      <font face="Monospaced">interface FastEthernet0/0&nbsp;</font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;ip access-group 100 in</font>
    </p>
    <p>
      <font color="#0000c0">show ip interface | include <b>list</b></font>&nbsp;&nbsp;// Есть ли прикрепленны ACL-правила. Если нашли, уже без фильтрации просматриваем к какому порту прикреплено
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;Outgoing access <b>list</b>&nbsp;is not set </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;Inbound&nbsp;&nbsp;access list is 100 </font>
    </p>
    <p>
      <font face="Monospaced">&nbsp;&nbsp;Outgoing access list is not set </font>
    </p>
    <p>
      
    </p>
    <p>
      (config)# <font color="#0000c0">no access-list 1</font>&nbsp;&nbsp;// <b>Удалить</b>&nbsp;ACL 1
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      --------------
    </p>
    <p>
      <font color="#0000c0"><b>(config)# ip nat inside source static tcp 192.168.3.2 80 213.235.10.2 80</b></font>&nbsp;// <b>Cтатический NAT</b>. Для доступа к локальному web-серверу на SRV1
    </p>
  </body>
</html></richcontent>
<node TEXT="case 0" ID="ID_1335735847" CREATED="1519112080156" MODIFIED="1519112080156"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>SRV (www)&lt;==&gt;R&#1087;&lt;-----&gt;R&lt;==&gt;SW&lt;==&gt;SRV 1C (vlan 5) </b>
    </p>
    <p>
      <b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;==&gt;WS &#1073;&#1091;&#1093;&#1075;. (vlan 2) </b>
    </p>
    <p>
      <b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;==&gt;WSs users+admin (vlan 3) </b>
    </p>
    <p>
      <b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;==&gt;WS &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; (vlan 4) </b>
    </p>
    <p>
      <b>1. &#1044;&#1086;&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (&#1087;&#1086;&#1076;&#1082;&#1083;. &#1082; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1091;)</b>
    </p>
    <p>
      <font color="#0000c0">.................. </font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0.0</font>&#160;// <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1074; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;</b>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# ip address 210.210.0.2 255.255.255.252</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# no shutdown </font>
    </p>
    <p>
      <font color="#0000c0">(config)# ip route&#160;&#160;0.0.0.0 0.0.0.0 210.210.0.1&#160;</font><font color="#000000">// <b>&#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1076;&#1086; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;</b></font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0</font>&#160;// <b>NAT. &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1074;&#1085;&#1077;&#1096;. &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;</b>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip nat outside </font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1.2-f0/1.4</font>&#160;// <b>NAT. &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1074;&#1085;&#1091;&#1090;&#1088;. &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;</b>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip nat inside</font>
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list standard&#160;FOR-NAT</font><font color="#000000">&#160;// <b>NAT. </b></font><b>&#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; Access List &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; (&#1082;&#1072;&#1082;&#1086;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1073;&#1091;&#1076;&#1077;&#1084; NAT&#1080;&#1090;&#1100;)</b>
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-std-nacl)#&#160;&#160;permit 192.168.<b>2</b>.0 0.0.0.255</font>&#160;// <b>NAT. &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1089;&#1077;&#1090;&#1080; NAT </b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat inside source list FOR-NAT interface f0/0 overload</font><b>&#160; // NAT.<a href="#ID_31864175">PAT</a></b>
    </p>
    <p>
      <b>2. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &quot;&#1082;&#1072;&#1082;-&#1073;&#1099; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;&quot; - &#1076;&#1083;&#1103; Cisco Packet Tracer</b>
    </p>
    <p>
      <font color="#0000c0">R2(config)# interface f0/0</font>&#160;// &#1087;&#1086;&#1076;&#1085;&#1103;&#1090;&#1100; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1087;&#1086;&#1088;&#1090; (&#1074; DOWN&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;)
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">R2(config-if)# ip address 210.210.0.1 255.255.255.252</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1076;&#1086; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; &#1091;&#1089;&#1083;&#1091;&#1075; (30 &#1073;&#1080;&#1090;)
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# no shutdown</font>
    </p>
    <p>
      <font color="#0000c0">R2(config)# interface f0/1</font>&#160;// &#1087;&#1086;&#1076;&#1085;&#1103;&#1090;&#1100; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1087;&#1086;&#1088;&#1090; (&#1074; DOWN&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;)
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">R2(config-if)# ip address 210.210.1.1 255.255.255.0</font>&#160;// IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1076;&#1086; SRV2
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# no shutdown</font>
    </p>
    <p>
      SRV2: 210.210.1.2/24 gw 210.210.1.1
    </p>
    <p>
      <font color="#0000c0">R2(config)# ip route&#160;&#160;192.168.0.0 255.255.0.0 210.210.0.2&#160;</font><font color="#000000">//</font><font color="#ff0000">&#160;<b>&#1080;&#1084;&#1080;&#1090;&#1072;&#1094;&#1080;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1072;&#1090;&#1072;&#1082;&#1080; (&#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072; &#1074;&#1079;&#1083;&#1086;&#1084;&#1072;&#1085;). &#1042; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082;&#1086; &#1074;&#1089;&#1077;&#1081; &#1089;&#1077;&#1090;&#1080; </b></font>
    </p>
    <p>
      <b>3. &#1047;&#1072;&#1097;&#1080;&#1090;&#1072;. &#1055;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;. <a href="#ID_1586644377">Access List</a>-&#1099; (&#1085;&#1072; &#1074;&#1093;&#1086;&#1076;. &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;) &#1076;&#1083;&#1103; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; </b>
    </p>
    <p>
      <font color="#0000c0">(config)#&#160;ip access-list extended FROM-OUTSIDE</font>&#160;// <b>&#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; ACL &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084;</b>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-ext-nacl)#&#160;permit ip any host 210.210.0.2</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; <b>&#1090;&#1086;&#1083;&#1100;&#1082;&#1086;</b>&#160; &#1085;&#1072; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1081; ip-&#1072;&#1076;&#1088;&#1077;&#1089; (&#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1083;&#1102;&#1073;&#1099;&#1077; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1099;, &#1089; &#1083;&#1102;&#1073;&#1086;&#1075;&#1086; ip-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;)
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0</font>&#160;//&#160;<b>&#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1072;&#1090;&#1100; ACL &#1082; &#1074;&#1085;&#1077;&#1096;. &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091;</b>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# ip access-group FROM-OUTSIDE in</font>&#160;//&#160;ACL + &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;. &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1083;&#1102;&#1073;&#1086;&#1081; &#1074;&#1093;. &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;
    </p>
    <p>
      <b>4. &#1059;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1087;&#1086; Telnet</b>
    </p>
    <p>
      <font color="#0000c0">(config)# username admin privilege 15 password cisco</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
    </p>
    <p>
      <font color="#0000c0">(config)# enable password cisco</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1085;&#1072; enable
    </p>
    <p>
      <font color="#0000c0">(config)# line vty 0 4</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-line)# login local</font>&#160;// &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1073;&#1072;&#1079;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;
    </p>
    <p>
      <b><font color="#ff0000">&#1048;&#1084;&#1080;&#1090;&#1072;&#1094;&#1080;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1072;&#1090;&#1072;&#1082;&#1080;. &#1054;&#1090;&#1082;&#1088;&#1099;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1085;&#1072;&#1096;&#1077;&#1084;&#1091; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1084;&#1091; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1091; (&#1095;&#1077;&#1088;&#1077;&#1079; Telnet). &#1061;&#1072;&#1082;&#1077;&#1088; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1076;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;.</font></b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list extended FROM-OUTSIDE </font>// <b>&#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1087;&#1086; Telnet</b>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-ext-nacl)#&#160;deny tcp any host 210.210.0.2 eq telnet</font>&#160;// &#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; tcp &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1089; &#1083;&#1102;&#1073;&#1086;&#1075;&#1086; &#1093;&#1086;&#1089;&#1090;&#1072; &#1085;&#1072; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; (&#1087;&#1086;&#1088;&#1090;). &#1055;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1090;&#1100;&#1089;&#1103; <b>&#1074;&#1099;&#1096;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1102;&#1097;&#1080;&#1093;</b>
    </p>
    <p>
      <b>5. &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; 1&#1057; (&#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1089;&#1077;&#1090;&#1080;)</b>
    </p>
    <p>
      <font color="#0000c0">(config)# &#160;ip access-list standard TO-1C</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; <b>&#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; ACL</b>&#160;&#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; 1&#1057;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-std-nacl)#&#160;permit 192.168.2.0 0.0.0.255</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1086;&#1076;&#1085;&#1091; &#1089;&#1077;&#1090;&#1100; (&#1073;&#1091;&#1093;&#1075;&#1072;&#1083;&#1090;&#1077;&#1088;&#1080;&#1103;), &#1074;&#1089;&#1077; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1089;&#1077;&#1090;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1079;&#1072;&#1087;&#1088;&#1077;&#1097;&#1077;&#1085;&#1099; <b>&#1085;&#1077;&#1103;&#1074;&#1085;&#1099;&#1084; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086;&#1084; <font color="#0000c0">deny ip any any</font></b>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1.5</font>&#160;//&#160;<b>&#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1072;&#1090;&#1100; ACL &#1082; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091; (&#1089; &#1091;&#1095;&#1077;&#1090;&#1086;&#1084; VLAN)</b>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# ip access-group TO-1C&#160;out</font>&#160;//&#160;ACL &#1085;&#1072; &#1074;&#1099;&#1093;&#1086;&#1076;&#1077;
    </p>
    <p>
      <b>6. Access List &#1076;&#1083;&#1103; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; + 1 (&#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; Web &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1080; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;)</b>
    </p>
    <p>
      <font color="#0000c0">(config)#&#160;ip access-list extended FROM-USERS</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;. ACL &#1086;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-ext-nacl)# permit tcp 192.168.3.0 0.0.0.255 host 210.210.1.2 eq www</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084; &#1082; &#1093;&#1086;&#1089;&#1090;&#1091; &#1087;&#1086; &#1087;&#1086;&#1088;&#1090;&#1091; 80
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-ext-nacl)# permit ip host 192.168.3.100 host 210.210.1.2</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1072;&#1076;&#1084;&#1080;&#1085;&#1091; (+1) &#1074;&#1077;&#1089;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1093;&#1086;&#1089;&#1090;&#1091;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-ext-nacl)# deny ip 192.168.3.0 0.0.0.255 host 210.210.1.2</font>&#160;// &#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1074;&#1077;&#1089;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1082; &#1093;&#1086;&#1089;&#1090;&#1091;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-ext-nacl)# permit ip any any</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; (&#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1074; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;)
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1.3</font>&#160;//&#160;<b>&#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1072;&#1090;&#1100; ACL &#1082; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091; (&#1089; &#1091;&#1095;&#1077;&#1090;&#1086;&#1084; VLAN)</b>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# ip access-group FROM-USERS in</font>&#160;//&#160;ACL &#1085;&#1072; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="case 1 Запрет доступа VLAN" ID="ID_480606723" CREATED="1519112080157" MODIFIED="1725453567713"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Запретить доступ из VLAN 2 в VLAN 3 с помощью ACL. </b><font color="#ff0000">Стандартные ACL нельзя использовать применительно к VLANам</font>, поскольку блокируется сеть без указания направления
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list extended&nbsp;PROTECT1</font>&nbsp;// <b>создать именованный, расшеренный</b>&nbsp;ACL
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-ext-nacl)# deny ip &lt;IP-адрес сети VLAN 2&gt; &lt;IP-адрес сети VLAN 3&gt;</font>&nbsp;//&nbsp;&nbsp;запретить доступ по любому протоколу
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-ext-nacl)# permit ip any any </font>// разрешить хостам доступ в Интернет
    </p>
    <p>
      <font color="#0000c0">(config)# interface vlan 2</font>&nbsp;// повесить ACL на вирт. интерфейс (<b>SVI</b>), обслуживающий VLAN 2
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# ip access-group PROTECT1 in // </font>применить ACL на входной интерфейс
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Нумерованный ACL" ID="ID_943387480" CREATED="1519112080157" MODIFIED="1725456708426"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Нумерованный ACL (numbered)</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>ACL Standard. Запретить хосту доступ в Интернет, остальным - разрешить</b>
    </p>
    <p>
      <font color="#000000">(config)# </font><font color="#0000c0">access-list 1 deny host 192.168.1.6</font>&nbsp;&nbsp;// <b>1. запретить</b>&nbsp;хост 192.168.10.5 ИЛИ<br/><font color="#000000">(config)# </font><font color="#0000c0">access-list 1 deny 192.168.1.6 0.0.0.0</font>
    </p>
    <p>
      (config)#<font color="#0000c0">&nbsp;access-list 1 permit 192.168.1.0 0.0.0.255</font>&nbsp;&nbsp;//&nbsp;<b>2. разрешить</b>&nbsp;остальную подсеть, Wildcard mask. ИЛИ <font color="#0000c0">(config)</font>(config)#<font color="#0000c0">&nbsp;&nbsp;access-list 1 permit any&nbsp; </font>// разрешить остальные подсети
    </p>
    <p>
      (config)#<font color="#0000c0">&nbsp;interface f0/1</font>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;(config-if)#<font color="#0000c0">&nbsp;ip access-group 1&nbsp;in</font>&nbsp;&nbsp;// <b>3. повесить</b>&nbsp;созданный access-list на вход интерфейса
    </p>
    <p>
      
    </p>
    <p>
      <b>ACL Extended. Запретить хосту доступ к узлу, остальным - разрешить</b>
    </p>
    <p>
      (config)# <font color="#0000c0">access-list 110 deny <b>ip</b>&nbsp;host &lt;IP src&gt; host &lt;IP-dest&gt;</font>&nbsp;
    </p>
    <p>
      (config)# <font color="#0000c0">access-list 110 deny <b>ip</b>&nbsp;host 192.168.8.2 host 210.210.210.4</font>&nbsp;&nbsp;//&nbsp;<b>1. запретить</b>&nbsp;&nbsp;хосту доступ к узлу (<b>ip</b>&nbsp;&nbsp;- любой интернет протокол)
    </p>
    <p>
      (config)#<font color="#0000c0">&nbsp;access-list 110 permit ip 192.168.8.0 0.0.0.255 any</font>&nbsp;&nbsp;// <b>2. разрешить</b>&nbsp;остальную подсеть <b>ИЛИ</b>
    </p>
    <p>
      (config)# <font color="#0000c0">access-list 110 permit ip any any</font>&nbsp;&nbsp;// разрешить между любыми узлами в сети
    </p>
    <p>
      (config)#<font color="#0000c0">&nbsp;interface f0/1</font>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;(config-if)#<font color="#0000c0">&nbsp;ip access-group 110 in</font>&nbsp;&nbsp;// <b>3. повесить</b>&nbsp;ACL на вход интерфейса
    </p>
    <p>
      
    </p>
    <p>
      <b>ACL Extended. Запретить хосту использовать протоколы (проверять вложения в IP), остальным - разрешить</b>
    </p>
    <p>
      <font color="#0000c0">(config)# access-list 110 deny tcp host 192.168.8.2 any <a href="#ID_1409186499">eq</a>&nbsp;80</font>&nbsp;// &nbsp;<b>1. запретить</b>&nbsp;хосту доступ к любому хосту по протоколу 80
    </p>
    <p>
      <font color="#0000c0">(config)# access-list 110 permit ip 192.168.8.0 0.0.0.255 any</font>&nbsp;// <b>2. разрешить</b>&nbsp;остальную подсеть
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;<font color="#0000c0">(config-if)# ip access-group 110 in</font>&nbsp;// <b>3. повесить</b>&nbsp;ACL на вход интерфейса
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Именованный ACL" ID="ID_949900187" CREATED="1519112080157" MODIFIED="1725456603171"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Именованный ACL (named) </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>Standard (запретить одному хосту)</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list standard MYLIST1</font>&nbsp;// <b>1. создать</b>&nbsp;standard ACL MYLIST1
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-std-nacl)# deny host 192.168.1.2</font>&nbsp;// <b>2. запретить</b>&nbsp;хост
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-std-nacl)# permit 192.168.1.0 0.0.0.255</font>&nbsp;// <b>3. разрешить</b>&nbsp;подсеть
    </p>
    <p>
      &nbsp;
    </p>
    <p>
      <b>Extended (разрешить одному хосту)</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list extended MYLIST2</font>&nbsp;// <b>1. создать</b>&nbsp;extended ACL MYLIST2
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-ext-nacl)# permit ip host 192.168.1.2 any</font>&nbsp;// <b>2. разрешить</b>&nbsp;&nbsp;доступ по любому протоколу
    </p>
    <p>
      
    </p>
    <p>
      <b>Редактирование записей</b>&nbsp;&nbsp;(строки идут с шагом 10)
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list standard MYLIST1</font>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-std-nacl)# <b>5</b>&nbsp;permit host 7.7.7.7</font>&nbsp;// разместить запись в строке<b>&nbsp;5 </b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-std-nacl)# no <b>20</b></font>&nbsp;// удалить строку <b>20 </b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-std-nacl)# no &lt;содержание строки&gt;</font>&nbsp;// удалить строку
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list resequence MYLIST1 10 20</font>&nbsp;// перенумеровать все строки ACL. 10 – первый номер, 20 – шаг нумераци
    </p>
    <p>
      <font color="#0000c0"># show access-lists</font>&nbsp;// показать ACL (с указанием номеров строк)
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="PACL" ID="ID_814209952" CREATED="1519112080157" MODIFIED="1519112080157"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Port Access List (PACL). &#1053;&#1072; &#1089;&#1074;&#1080;&#1095;&#1072;&#1093;</b>
    </p>
    <ul>
      <li>
        &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1074;&#1077;&#1089;&#1080;&#1090;&#1100; <b>&#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1057;&#1042;&#1048;&#1063;&#1040;</b>. &#1053;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&#1093;, &#1082; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1089;&#1086; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084;&#1080; IP (DHCP, &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1096;&#1083;&#1102;&#1079;))
      </li>
      <li>
        &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1084; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1086;&#1084; (<b>IN</b>)
      </li>
      <li>
        &#1084;&#1086;&#1075;&#1091;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1089; <b>MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1084;&#1080;</b>
      </li>
      <li>
        <b>&#1087;&#1086;&#1095;&#1090;&#1080; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;</b>, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1074;&#1089;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1077;
      </li>
    </ul>
    <p>
      <font color="#0000c0">(config)# ip access-list standard SERVER1</font>&#160;// <b>1. &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100;</b>&#160;&#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; access-list
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-std-nacl)# permit 192.168.1.1</font>&#160;// <b>2. &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;</b>&#1100; ip-&#1072;&#1076;&#1088;&#1077;&#1089;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-std-nacl)# deny any log</font>&#160;// <b>3. &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100;</b>. log - &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100; &#1073;&#1091;&#1076;&#1091;&#1090; &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; deny-&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072;
    </p>
    <p>
      <font color="#0000c0">(config)# int f0/1 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip access-group SERVER1 in</font>&#160;// <b>4. &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100;</b>&#160;access-list &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
    <p>
      
    </p>
    <p>
      MAC ACL
    </p>
    <p>
      <font color="#0000c0">(config)# mac access-list extended SERVER1 </font>
    </p>
    <p>
      <font color="#0000c0">&#160; </font>&#160;<font color="#0000c0">(config-ext-nacl)# permit host&#160;&lt;MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&gt; </font>
    </p>
    <p>
      <font color="#0000c0">(config)# int f0/1 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# mac access-group SERVER1</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="VACL" ID="ID_1967918111" CREATED="1519112080158" MODIFIED="1519112080158"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Vlan Access List (VACL). &#1053;&#1072; &#1089;&#1074;&#1080;&#1095;&#1072;&#1093;. </b>&#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1102;&#1090;&#1089;&#1103; &#1082;&#1086; &#1074;&#1089;&#1077;&#1084; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;&#1084; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1084;&#1089;&#1103; &#1074; VLAN, &#1083;&#1080;&#1073;&#1086; &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1093; &#1095;&#1077;&#1088;&#1077;&#1079; WAN &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;. VACL &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077;, &#1085;&#1077; &#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1103; &#1074;&#1083;&#1080;&#1103;&#1085;&#1080;&#1103; &#1085;&#1072; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072;.
    </p>
    <ul>
      <li>
        <b>&#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; </b>(&#1084;&#1086;&#1078;&#1085;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1084;&#1080; ACL)
      </li>
    </ul>
    <p>
      <font color="#0000c0">(config)# mac access-list extended MAC_LIST</font>&#160;// <b>1. &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100;&#160; mac ACL</b>&#160;(&#1077;&#1089;&#1083;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;)
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-ext-macl)# permit host &lt;MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&gt; any</font>&#160; // &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1093;&#1086;&#1089;&#1090;&#1091; &#1087;&#1086;&#1076;&#1082;&#1083;. &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1081; &#1093;&#1086;&#1089;&#1090;
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list extended IP_LIST</font>&#160;// <b>2. &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100;&#160;&#160;ip ACL</b>&#160;(&#1077;&#1089;&#1083;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;)
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-ext-nacl)# permit ip host &lt;IP-&#1072;&#1076;&#1088;&#1077;&#1089;&gt; any</font>&#160; // &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1093;&#1086;&#1089;&#1090;&#1091; &#1087;&#1086;&#1076;&#1082;&#1083;. &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1081; &#1093;&#1086;&#1089;&#1090;
    </p>
    <p>
      <font color="#0000c0">(config)# vlan access-map VLAN_MAP</font>&#160;// <b>3. &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; vlan access-map</b>
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-access-map)# match mac address MAC_LIST</font>&#160; // &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; mac ACL. &#1058;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1080;&#1085; ACL
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-access-map)# match ip address IP_LIST</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; ip ACL. &#1058;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1076;&#1080;&#1085; ACL
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-access-map)# action forward</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1087;&#1088;&#1086;&#1093;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090; &#1087;&#1086; access-list
    </p>
    <p>
      <font color="#0000c0">(config)# vlan filter VLAN_MAP vlan-list 150-170</font>&#160;// <b>4. &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; VLAN&#1099;</b>, &#1082; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; VLAN_MAP
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Cisco ASA" FOLDED="true" ID="ID_1383651692" CREATED="1519112080158" MODIFIED="1725278391512"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. Подключение к Cisco ASA</b>
    </p>
    <ul>
      <li>
        пароль по умолчанию пустой
      </li>
      <li>
        по умолчанию включен DHCP-сервер
      </li>
      <li>
        обязательно задавать имя VLANов
      </li>
      <li>
        пароли шифруются по умолчанию<br/>
      </li>
    </ul>
    <p>
      <b>2. Проверка лицензии</b>
    </p>
    <p>
      <font color="#0000c0"># show version</font>
    </p>
    <p>
      
    </p>
    <p>
      ----
    </p>
    <p>
      # show nat // счетчик прошедших пакетов
    </p>
    <p>
      # show xlate //
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      ------------------------------??????????------------
    </p>
    <p>
      dhcpd auto_config outside
    </p>
    <p>
      dhcpd address 192.168.2.5-192.168.2.35 inside
    </p>
    <p>
      dhcpd enable inside
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      см. <a href="#ID_1844616027">DMZ через ASA</a>
    </p>
  </body>
</html></richcontent>
<node TEXT="case 0" ID="ID_866894120" CREATED="1519112080158" MODIFIED="1519112080158" HGAP_QUANTITY="14.8 pt"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1084;&#1077;&#1078;&#1089;&#1077;&#1090;. &#1101;&#1082;&#1088;&#1072;&#1085;&#1091;</b>
    </p>
    <p>
      <font color="#0000c0">(config)# enable password cisco</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1085;&#1072; enable
    </p>
    <p>
      <font color="#0000c0">(config)# username admin privilege 15 password cisco</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; (&#1074; CPT &#1085;&#1077; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;). &#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; <font color="#0000c0">username admin password cisco</font>
    </p>
    <p>
      <font color="#0000c0">(config)# ssh 192.168.1.0 255.255.255.0 inside&#160;</font>// &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1089;&#1077;&#1090;&#1100;, &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1080; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; (&#1080;&#1084;&#1103;)
    </p>
    <p>
      <font color="#0000c0">(config)# aaa authentication ssh console LOCAL </font>// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1073;&#1072;&#1079;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;
    </p>
    <p>
      -------------
    </p>
    <p>
      <font color="#0000c0">(config)# crypto key generate rsa modulus 1024 </font>
    </p>
    <p>
      <b>2. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; Security Level</b>&#160;(&#1059;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1076;&#1086;&#1074;&#1077;&#1088;&#1080;&#1103; &#1082; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091;. max- 100, min-0). &#1044;&#1074;&#1080;&#1078;&#1077;&#1085;&#1080;&#1077;&#160;&#160;&#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1090; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1075;&#1086; &#1082; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1084;&#1091; (&#1082;&#1072;&#1082; &#1074;&#1086;&#1076;&#1072; &#1089; &#1075;&#1086;&#1088;&#1099;)
    </p>
    <p>
      <font color="#0000c0">(config)# interface vlan 1 </font>// &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# security-level 95 </font>// &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; SL
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# nameif inside </font>// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1080;&#1084;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip address 192.168.1.1 255.255.255.0 </font>// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# no shutdown </font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface vlan 2 </font>// &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1076;&#1086; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# security-level 0 </font>// &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; SL
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# nameif outside </font>// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1080;&#1084;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if )# ip address 210.210.0.2 255.255.255.252 </font>// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#160;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# no shutdown</font>
    </p>
    <p>
      <b>3. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; (&#1076;&#1086; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;)</b>
    </p>
    <p>
      <font color="#0000c0">(config)# route outside 0.0.0.0 0.0.0.0 210.210.0.1 </font>// &#1089;&#1077;&#1090;&#1100; &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103;, &#1096;&#1083;&#1102;&#1079; (IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;)
    </p>
    <p>
      <b>4. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1072; &#1080;&#1085;&#1089;&#1087;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; (Stateful Inspection)</b>. &#1048;&#1085;&#1089;&#1087;&#1077;&#1082;&#1094;&#1080;&#1103; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1089; &#1079;&#1072;&#1087;&#1086;&#1084;&#1080;&#1085;&#1072;&#1085;&#1080;&#1077;&#1084; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103;. &#1055;&#1072;&#1082;&#1077;&#1090; &#1087;&#1088;&#1086;&#1081;&#1076;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1080;&#1085;&#1080;&#1094;&#1080;&#1072;&#1094;&#1080;&#1080; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1084; &#1073;&#1086;&#1083;&#1077;&#1077; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1075;&#1086; Security Level
    </p>
    <p>
      <font color="#0000c0">(config)# class-map inspection_default </font>// <b>&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1090;&#1080;&#1087;</b>&#160;&#1080;&#1089;&#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1084;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-cmap)# match default-inspection-traffic </font>// &#1074;&#1077;&#1089;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;, &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1095;&#1077;&#1088;&#1077;&#1079; ASA
    </p>
    <p>
      <font color="#0000c0">(config)# policy-map global_policy </font>// <b>&#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091;</b>&#160;(&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077; &#1085;&#1072;&#1076; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1086;&#1084;)
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-pmap)# class inspection_default </font>// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091; &#1082; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; &#1082;&#1083;&#1072;&#1089;&#1089;&#1091;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#160;&#160;&#160;(config-pmap-c)# inspect <b>icmp</b>&#160;</font>// &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1099; &#1080;&#1085;&#1089;&#1087;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#0000c0">(config)# service-policy global_policy global </font>// <b>&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;</b>&#160;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103;. &#1055;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1091; &#1080;&#1085;&#1089;&#1087;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; - &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1086;
    </p>
    <p>
      <b>5. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; NAT</b>
    </p>
    <p>
      <font color="#0000c0">(config)# object network FOR-NAT </font>// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-network-object)# subnet 192.168.1.0 255.255.255.0 </font>// &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1085;&#1072;&#1096;&#1091; &#1089;&#1077;&#1090;&#1100;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1073;&#1091;&#1076;&#1077;&#1084; NAT&#1080;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-network-object)# nat (inside,outside) dynamic interface</font>
    </p>
  </body>
</html></richcontent>
</node>
