<node TEXT="через ASA" ID="ID_1844616027" CREATED="1519112080159" MODIFIED="1519112080159"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><u>DMZ &#1095;&#1077;&#1088;&#1077;&#1079; ASA</u>&#160;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>Rpr&lt;--&gt;SRV2 </b>
    </p>
    <p>
      <b>&#160;&#9550; </b>
    </p>
    <p>
      <b>ASA&lt;--&gt;DMZ (SRV) IP 210.210.3.2 </b>
    </p>
    <p>
      <b>&#160;&#9550; </b>
    </p>
    <p>
      <b>SW&lt;--&gt;WSs </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; DMZ &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; Security Level (&#1086;&#1073;&#1099;&#1095;&#1085;&#1086; 50)</b>
    </p>
    <p>
      <font color="#0000c0">Rprov(config)# ip route 210.210.3.0 255.255.255.252 210.210.0.2</font>&#160;// &#1086;&#1090; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1074; DMZ &#1095;&#1077;&#1088;&#1077;&#1079; ASA
    </p>
    <p>
      <font color="#0000c0">ASA(config)# interface e0/2</font>&#160;// &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; (&#1087;&#1086;&#1076;&#1082;&#1083;. DMZ) &#1074; &#1085;&#1086;&#1074;&#1099;&#1081; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">ASA(config-if)# switchport access vlan3</font>
    </p>
    <p>
      <font color="#0000c0">ASA(config)# interface vlan 3</font>&#160;// &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1084; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">ASA(config-if)# no forward interface vlan 1</font>&#160;// <font color="#ff0000">&#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1080;. &#1042;&#1074;&#1086;&#1076;&#1080;&#1084; &#1095;&#1090;&#1086;&#1073;&#1099; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; dmz</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;ASA(config-if)# nameif dmz </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;ASA(config-if)# security-level 50 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;ASA(config-if)# ip address 210.210.3.1 255.255.255.252 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;ASA(config-if)# no shutdown</font>
    </p>
    <p>
      <b>2.&#160;&#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; Access List &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; DMZ &#1080;&#1079;&#1074;&#1085;&#1077; (&#1080;&#1079; SRV2)</b>
    </p>
    <p>
      <font color="#0000c0">ASA(config)# access-list FROM-OUTSIDE extended permit icmp any host 210.210.3.2</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; icmp &#1089; &#1083;&#1102;&#1073;&#1086;&#1075;&#1086; &#1093;&#1086;&#1089;&#1090;&#1072;
    </p>
    <p>
      <font color="#0000c0">ASA(config)# access-list FROM-OUTSIDE extended permit tcp any host 210.210.3.2 eq www </font>// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1074;&#1077;&#1073;-&#1090;&#1088;&#1072;&#1092;&#1080; &#1089; &#1083;&#1102;&#1073;&#1086;&#1075;&#1086; &#1093;&#1086;&#1089;&#1090;&#1072;
    </p>
    <p>
      <font color="#0000c0">ASA(config)# access-group FROM-OUTSIDE in interface outside </font>// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; access-group
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="через рутер (CBAC)" ID="ID_1645863773" CREATED="1519112080159" MODIFIED="1519112080159"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Rpr&lt;--&gt;SRV2 </b>
    </p>
    <p>
      <b>&#160;&#9550; </b>
    </p>
    <p>
      <b>R&lt;--&gt;DMZ (SRV) IP 210.210.3.2 </b>
    </p>
    <p>
      <b>&#160;&#9550; </b>
    </p>
    <p>
      <b>SW&lt;--&gt;WSs </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1088;&#1091;&#1090;&#1077;&#1088; R</b>
    </p>
    <p>
      <font color="#0000c0">(config)# int f0/0</font>&#160;// <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1074; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;</b>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# description outside&#160;</font>// &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; (&#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077;)
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip address 210.210.0.2 255.255.255.252 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# no shutdown </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip nat outside&#160;</font>// NAT
    </p>
    <p>
      <font color="#0000c0">(config)# int f0/1</font>&#160;// <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1074; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091; DMZ</b>. NAT &#1085;&#1077; &#1085;&#1091;&#1078;&#1077;&#1085; (&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080;&#1084;&#1077;&#1077;&#1090; &#1087;&#1091;&#1073;. &#1072;&#1076;&#1088;&#1077;&#1089;)
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# description dmz</font>&#160;// &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; (&#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077;)
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip address 210.210.3.1 255.255.255.252 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# no shutdown </font>
    </p>
    <p>
      <font color="#0000c0">(config)# int f1/0</font>&#160;// <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;</b>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# description inside</font>&#160;// &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; (&#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077;)
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip address 192.168.1.1 255.255.255.0 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# no shutdown </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip nat inside</font>&#160;//&#160;NAT
    </p>
    <p>
      <font color="#0000c0">(config)# ip route&#160;&#160;0.0.0.0 0.0.0.0 210.210.0.1&#160;</font><font color="#000000">// <b>&#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1076;&#1086; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072; (Rpr)</b></font>
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list standard&#160;FOR-NAT</font><font color="#000000">&#160;//<b>&#160;NAT.</b>&#160; </font>&#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; access list &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; (&#1082;&#1072;&#1082;&#1086;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1073;&#1091;&#1076;&#1077;&#1084; NAT&#1080;&#1090;&#1100;)
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-std-nacl)#&#160;permit 192.168.1.0 0.0.0.255</font>&#160;// NAT. &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1089;&#1077;&#1090;&#1080; NAT<b>&#160;</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat inside source list FOR-NAT interface f0/0 overload</font>&#160;// NAT. <a href="#ID_31864175">PAT</a>
    </p>
    <p>
      <b>2.&#160;&#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1074; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1089;&#1077;&#1090;&#1100; (&#1080;&#1079; DMZ &#1080; &#1080;&#1079;&#1074;&#1085;&#1077;)</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list extended FROM-OUTSIDE </font>// <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; ACL &#1076;&#1083;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1075;&#1086; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;</b>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-ext-nacl)#&#160;permit icmp any host 210.210.3.2</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1084; ping &#1076;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; DMZ
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-ext-nacl)#&#160;permit tcp any host 210.210.3.2 eq www</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1077;&#1084; &#1074;&#1077;&#1073;-&#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1076;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; DMZ
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-ext-nacl)#&#160;deny ip any any </font>// &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">(config)# int f0/0&#160;</font>// &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1072;&#1090;&#1100; ACL &#1082; &#1074;&#1085;&#1077;&#1096;. &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip access-group FROM-OUTSIDE in</font>&#160;// &#1074; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;. &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;
    </p>
    <p>
      <b>2.1 CBAC. &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1082;&#1072;&#1082;&#1086;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084; &#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1085;&#1091;&#1078;&#1085;&#1086; &#1080;&#1085;&#1089;&#1087;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;</b>&#160;
    </p>
    <p>
      <font color="#0000c0">(config)# ip inspect&#160;name Inside-Outside http</font>&#160;// &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;, &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; &#1080;&#1085;&#1089;&#1087;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#0000c0">(config)# ip inspect name Inside-Outside icmp</font>&#160;//
    </p>
    <p>
      <font color="#0000c0">(config)# ip inspect name Inside-Outside tcp</font>&#160;//
    </p>
    <p>
      <font color="#0000c0">(config)# int f1/0 </font>// &#1087;&#1088;&#1080;&#1074;&#1103;&#1078;&#1077;&#1084; &#1080;&#1085;&#1089;&#1087;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1082; &#1074;&#1093;.&#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1084;&#1091; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# ip inspect Inside-Outside in</font>
    </p>
    <p>
      <b>3. &#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1080;&#1079; DMZ &#1074; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1089;&#1077;&#1090;&#1100;</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list extended FROM-DMZ </font>// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; ACL &#1076;&#1083;&#1103; DMZ
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-ext-nacl)#&#160;deny ip host 210.210.3.2 192.168.1.0 0.0.0.255 </font>// &#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1086;&#1090; &#1093;&#1086;&#1089;&#1090;&#1072; DMZ &#1076;&#1086; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-ext-nacl)#&#160;permit ip any any </font>// &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; DMZ &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1090;&#1100; &#1085;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1086;&#1074;
    </p>
    <p>
      <font color="#0000c0">(config)# int f0/1 </font>// &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1072;&#1090;&#1100; ACL &#1082; &#1074;&#1085;&#1091;&#1090;&#1088;. &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip access-group FROM-DMZ in</font>&#160;// &#1074; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;. DMZ
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="через рутер (ZFW)" ID="ID_1689902900" CREATED="1519112080159" MODIFIED="1519112080159"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Zone-Based Policy firewall, ZFW, &#1041;&#1088;&#1072;&#1085;&#1076;&#1084;&#1072;&#1091;&#1101;&#1088; &#1079;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1041;&#1088;&#1072;&#1085;&#1076;&#1084;&#1072;&#1091;&#1101;&#1088; &#1079;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1087;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; (Zone-Based Policy firewall &#1080;&#1083;&#1080; ZFW)</b>&#160; &#8212; &#1084;&#1077;&#1078;&#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1081; &#1101;&#1082;&#1088;&#1072;&#1085;, &#1103;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1081;&#1089;&#1103; &#1086;&#1076;&#1085;&#1080;&#1084; &#1080;&#1079; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1085;&#1086;&#1075;&#1086; &#1086;&#1073;&#1077;&#1089;&#1087;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; Cisco IOS. ZFW &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1077;&#1090;&#1103;&#1084;&#1080;. &#1055;&#1088;&#1077;&#1076;&#1096;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1080;&#1082;&#1086;&#1084; ZFW &#1073;&#1099;&#1083; &#1082;&#1083;&#1072;&#1089;&#1089;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1073;&#1088;&#1072;&#1085;&#1076;&#1084;&#1072;&#1091;&#1101;&#1088; &#1089; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1077;&#1084; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; (&#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1075;&#1086; &#1080;&#1083;&#1080; CBAC). &#1042;&#1087;&#1077;&#1088;&#1074;&#1099;&#1077; zone-based firewall &#1073;&#1099;&#1083; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085; &#1074; Cisco IOS &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; 12.4(6)T
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Баннер на вход" ID="ID_1404490557" CREATED="1519112080159" MODIFIED="1725288083301"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Баннер (приветственный) </b>
    </p>
    <p>
      (config)# <font color="#0000c0">banner motd <b>$</b></font>&nbsp;&nbsp;// motd (Message of the Day). Вместо <b>$</b>&nbsp;может быть другой разделитьель.
    </p>
    <p>
      <font color="#0000c0">&lt;сообщение&gt; </font>
    </p>
    <p>
      <font color="#0000c0"><b>$</b></font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>Баннер, который выводится перед запросом имени пользователя и пароля:</b>
    </p>
    <ul>
      <li>
        Это собственность компании &lt;Компания&gt;. Вход сюда будет преследоваться по закону.
      </li>
    </ul>
    <p>
      (config)# <font color="#0000c0">banner login &quot; Access for authorized user only. Please enter your username and password. &quot;</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Пароли" FOLDED="true" ID="ID_1962735246" CREATED="1519112080160" MODIFIED="1725285709136"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Пароль для входа в устройство</b>
    </p>
    <p>
      <font color="#0000c0">enable</font>&nbsp;&nbsp;// Включить режим привилегированного доступа
    </p>
    <p>
      <font color="#0000c0">configure terminal</font>&nbsp;&nbsp;// Перейти в&nbsp;режим конфигурирования.&nbsp;--&gt; (config) #
    </p>
    <p>
      (config)#<font color="#0000c0">&nbsp;line console 0</font>&nbsp;&nbsp;// <b>Пароль консоли. </b>конф-ть первичную терминальную линиию (консоль)
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;(config-line)# <font color="#0000c0">login local</font>&nbsp;&nbsp;// использовать лок. базу при аутентификации
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;(config-line)#<font color="#0000c0">&nbsp;login</font>&nbsp;&nbsp;// Включить проверку пароля
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;(config-line)# <font color="#0000c0">password &lt;пароль&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>Пароль для входа в режим конфигурации</b>
    </p>
    <p>
      <font color="#0000c0">enable</font>&nbsp;&nbsp;// Включить режим привилегированного доступа
    </p>
    <p>
      <font color="#0000c0">configure terminal</font>&nbsp;&nbsp;// Перейти в&nbsp;режим конфигурирования.&nbsp;--&gt; (config) #
    </p>
    <p>
      (config)# <font color="#0000c0">enable <b>secret</b>&nbsp;&lt;пароль&gt;</font>&nbsp;&nbsp;// <b>секретный пароль</b>&nbsp;(закрыт в конф.файле)
    </p>
    <p>
      (config)#<font color="#0000c0">&nbsp;enable password &lt;пароль&gt;</font>&nbsp;&nbsp;// <b>пароль</b>&nbsp;(открыт в конф. файле)
    </p>
    <p>
      (config)#<font color="#0000c0">&nbsp;<b>no</b>&nbsp;enable secret/password</font>&nbsp;&nbsp;// <b>Отменить</b>&nbsp;конф. по паролю
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      (config)#<font color="#0000c0">&nbsp;line vty 0 4 // </font><b>Пароль виртуального терминала для Telnet и SSH. 0 4;&nbsp;&nbsp;&nbsp;5 15</b><font color="#0000c0">&nbsp;</font>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;(config-line)#<font color="#0000c0">&nbsp;transport input telnet</font>&nbsp;// трансп. протокол входящий telnet (можно <a href="#ID_776356394">поставть SSH</a>)
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;(config-line)# <font color="#0000c0">login local</font>&nbsp;// использовать лок. базу при аутентификации
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;(config-line)#<font color="#0000c0">&nbsp;login</font>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;(config-line)# <font color="#0000c0">password cisco </font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      (config)#<font color="#0000c0">&nbsp;service password-encryption</font>&nbsp;//<font color="#0000c0">&nbsp;</font><b>Шифрование паролей. </b>Вводить всегда - для безопасности<font color="#0000c0">&nbsp; </font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      (config)#<font color="#0000c0">&nbsp;username admin privilege 15 password <b>cisco</b></font>&nbsp;// <b>создать&nbsp;пользователя</b>&nbsp;(с max привилегиями) для локальной базы
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="case 1" ID="ID_1706898411" CREATED="1519112080160" MODIFIED="1519112080160"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1-&#1081; &#1084;&#1077;&#1090;&#1086;&#1076; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1073;&#1072;&#1079;&#1099; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# enable secret <b>cisco</b></font>&#160;// <b>&#1089;&#1077;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;</b>&#160;(&#1079;&#1072;&#1082;&#1088;&#1099;&#1090; &#1074; &#1082;&#1086;&#1085;&#1092;.&#1092;&#1072;&#1081;&#1083;&#1077;)
    </p>
    <p>
      <font color="#0000c0">(config)# username admin privilege 15 password <b>cisco</b></font>&#160;// <b>&#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100;&#160;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;</b>&#160;(&#1089; max &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;&#1084;&#1080;) &#1076;&#1083;&#1103; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1073;&#1072;&#1079;&#1099;
    </p>
    <p>
      <font color="#0000c0">(config)# aaa new-model</font>
    </p>
    <p>
      <font color="#0000c0">(config)# aaa authentication login default local</font>&#160;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="case 2 (aaa-сервер)" ID="ID_516887080" CREATED="1519112080160" MODIFIED="1519112080160"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>R==SW==WSs </b>
    </p>
    <p>
      <b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#9562; ==SRV (aaa-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;) </b>
    </p>
    <p>
      
    </p>
    <p>
      SRV&gt; <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; AAA-server</b>. &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;
    </p>
    <p>
      SRV&gt; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;: &#1048;&#1084;&#1103;, IP-&#1072;&#1076;&#1088;&#1077;&#1089;, &#1082;&#1083;&#1102;&#1095;, &#1090;&#1080;&#1087; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; (RADIUS/TACACS)
    </p>
    <p>
      SRV&gt; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1073;&#1072;&#1079;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">R(config)# enable secret <b>cisco</b></font>&#160;// <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;.</b>&#160; <b>&#1089;&#1077;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;</b>&#160;(&#1079;&#1072;&#1082;&#1088;&#1099;&#1090; &#1074; &#1082;&#1086;&#1085;&#1092;.&#1092;&#1072;&#1081;&#1083;&#1077;)
    </p>
    <p>
      <font color="#0000c0">R(config)# username admin privilege 15 password <b>cisco</b></font>&#160;// <b>&#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100;&#160;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;</b>&#160;(&#1089; max &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;&#1084;&#1080;) &#1076;&#1083;&#1103; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1073;&#1072;&#1079;&#1099;
    </p>
    <p>
      <font color="#0000c0">R(config)# aaa new-model</font>&#160;// <b>&#1082;&#1086;&#1085;&#1092;-&#1090;&#1100; AAA &#1084;&#1086;&#1076;&#1077;&#1083;&#1100;</b>
    </p>
    <p>
      <font color="#0000c0">R(config)# aaa authentication login default group radius local</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1089;&#1087;&#1080;&#1089;&#1086;&#1082; &#1084;&#1077;&#1090;&#1086;&#1076;&#1086;&#1074; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1091;. &#1055;&#1088;&#1080; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080; &#1085;&#1072; &#1088;&#1091;&#1090;&#1077;&#1088;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1084;&#1077;&#1090;&#1086;&#1076; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; aaa-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; (&#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; RADIUS), &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1077;&#1085;, &#1090;&#1086;&#1075;&#1076;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1083;&#1086;&#1082;. &#1073;&#1072;&#1079;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;
    </p>
    <p>
      <font color="#0000c0">R(config)# radius-server host &lt;IP-&#1072;&#1076;&#1088;&#1077;&#1089; AAA-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&gt; &lt;&#1082;&#1083;&#1102;&#1095;&gt;</font>&#160; // <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; RADIUS</b>
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Сброс пароля (роутер)" ID="ID_1190158174" CREATED="1519112080160" MODIFIED="1519112080160"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1058;&#1086;&#1083;&#1100;&#1082;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1086;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1047;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074;</b>&#160;<a href="#ID_28641932">ROMMON.</a>&#160; &#1044;&#1083;&#1103;&#160;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1074; ROMMON &#1085;&#1091;&#1078;&#1085;&#1086; <a href="#ID_28641932">&#1087;&#1088;&#1077;&#1088;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;</a>&#160;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; IOS
    </p>
    <p>
      <b>2. &#1048;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088; &#1085;&#1072; 0x2142</b>. &#1069;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1080;&#1090; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1089; &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084; running-config. &#1058;&#1086; &#1077;&#1089;&#1090;&#1100; &#1091;&#1078;&#1077; &#1080;&#1084;&#1077;&#1102;&#1097;&#1080;&#1081;&#1089;&#1103; startup-config &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103;, &#1085;&#1086; &#1086;&#1089;&#1090;&#1072;&#1085;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1077;. &#1058;&#1077;&#1082;&#1091;&#1097;&#1080;&#1081; &#1082;&#1086;&#1085;&#1092;. &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1074; <font color="#0000c0">show version</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;rommon 2 &gt; confreg 0x2142 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;rommon 3 &gt; boot</font>&#160;// &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; IOS &#1074; &#1085;&#1091;&#1083;&#1077;&#1074;&#1086;&#1081; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      <b>3. &quot;&#1042;&#1085;&#1077;&#1076;&#1088;&#1080;&#1090;&#1100;&quot; &#1089;&#1090;&#1072;&#1088;&#1099;&#1081; startup-config</b>&#160;&#1074; &#1091;&#1078;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1097;&#1080;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;
    </p>
    <p>
      <font color="#0000c0"># copy startup-confiig running-config</font>
    </p>
    <p>
      <b>4. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1085;&#1086;&#1074;&#1099;&#1081; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;</b>:
    </p>
    <p>
      <font color="#0000c0">(config)# enable secret cisco </font>
    </p>
    <p>
      <font color="#0000c0">(config)# username user1 secret cisco</font>
    </p>
    <p>
      <b>5. &#1042;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;. &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#160;&#1085;&#1072; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; 0x2102</b>. &#1055;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1074; ROMMON (&#1087;&#1088;&#1077;&#1088;&#1099;&#1074;&#1072;&#1077;&#1084; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;)
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">rommon 2 &gt; confreg 0x2102 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;rommon 3 &gt; boot </font>
    </p>
    <p>
      <b>6. &#1055;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100;&#1089;&#1103;</b>&#160;--&gt; &#1080;&#1084;&#1077;&#1077;&#1084; <b>&#1089;&#1090;&#1072;&#1088;&#1091;&#1102; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; &#1089; &#1085;&#1086;&#1074;&#1099;&#1084; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1084;</b>. &#1048;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;&#160;&#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1076;&#1085;&#1103;&#1090;&#1100; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;)
    </p>
    <p>
      <b>7. &#1047;&#1072;&#1087;&#1088;&#1077;&#1090; &#1089;&#1084;&#1077;&#1085;&#1099; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;</b>
    </p>
    <p>
      <font color="#0000c0">(config)# no service password-recovery</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1079;&#1072;&#1097;&#1080;&#1090;&#1091; ROMMON (ROMMON security). &#1053;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; &#1087;&#1088;&#1077;&#1088;&#1074;&#1072;&#1090;&#1100; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091; &#1080; &#1074;&#1086;&#1081;&#1090;&#1080; &#1074; ROMMON. &#1053;&#1077; &#1089;&#1090;&#1086;&#1080;&#1090; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;
    </p>
    <p>
      <b>8. &#1057;&#1073;&#1088;&#1086;&#1089; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072; &#1076;&#1086; &#1079;&#1072;&#1074;&#1086;&#1076;&#1089;&#1082;&#1080;&#1093; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082;</b>&#160;(&#1089; &#1085;&#1091;&#1083;&#1077;&#1074;&#1099;&#1084; startup-config). &#1044;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086;, &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; IOS &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1085;&#1072;&#1078;&#1072;&#1090;&#1100; &#1080; &#1091;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1095;&#1077;&#1090;&#1072;&#1085;&#1080;&#1103; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096; &#1076;&#1083;&#1103; &#1087;&#1088;&#1077;&#1088;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;<b>&#160; ctrl + pause break</b>, &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1090; &#1086;&#1090; &#1090;&#1080;&#1087;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1086;&#1075;&#1086; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1072;). &#1055;&#1086;&#1089;&#1083;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086;, &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1077;&#1076;&#1083;&#1086;&#1078;&#1077;&#1085;&#1086; &#1089;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1076;&#1086; &#1079;&#1072;&#1074;&#1086;&#1076;&#1089;&#1082;&#1080;&#1093; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Сброс пароля (свич)" ID="ID_121398409" CREATED="1519112080161" MODIFIED="1519112080161"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1058;&#1086;&#1083;&#1100;&#1082;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1086;&#1077; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077;</b>
    </p>
    <p>
      
    </p>
    <p>
      &#1053;&#1072; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1077; Cisco Catalyst:
    </p>
    <p>
      <b>1. &#1042;&#1099;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;</b>&#160; --&gt; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; --&gt; &#1085;&#1072;&#1078;&#1072;&#1090;&#1100; &#1080; &#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091; &#171;Mode&#187; 15 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;. &#1069;&#1090;&#1086; &#1087;&#1088;&#1077;&#1088;&#1074;&#1077;&#1090; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; --&gt; &#1087;&#1088;&#1080;&#1075;&#1083;&#1072;&#1096;&#1077;&#1085;&#1080;&#1077; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1095;&#1080;&#1082;&#1072; --&gt; &#1085;&#1091;&#1078;&#1085;&#1086; &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1080;&#1083;&#1080; &#1087;&#1077;&#1088;&#1077;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1083;&#1089;&#1103; &#1073;&#1077;&#1079; &#1085;&#1077;&#1075;&#1086;. &#1053;&#1086; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1095;&#1080;&#1082; &#1085;&#1077; &#1091;&#1084;&#1077;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1089; &#1092;&#1083;&#1101;&#1096;-&#1087;&#1072;&#1084;&#1103;&#1090;&#1100;&#1102;. &#1062;&#1077;&#1087;&#1083;&#1103;&#1077;&#1084; flash &#1087;&#1072;&#1084;&#1103;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;switch: flash_init </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;switch: load_helper</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;switch: dir flash:</font>&#160;// &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1092;&#1083;&#1101;&#1096; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;
    </p>
    <p>
      <b>2. &#1092;&#1072;&#1081;&#1083; config.text</b>. &#1045;&#1089;&#1083;&#1080; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072; &#1085;&#1072;&#1084; &#1085;&#1077; &#1074;&#1072;&#1078;&#1085;&#1072;, &#1090;&#1086; &#1092;&#1072;&#1081;&#1083; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100;, &#1077;&#1089;&#1083;&#1080; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;, &#1085;&#1086; &#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;, &#1092;&#1072;&#1081;&#1083; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1090;&#1100;:
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">switch: rename flash:config.text flash:config.text.old </font>
    </p>
    <p>
      <b>3. <font color="#0000c0">switch: boot</font>&#160;// &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; IOS</b>
    </p>
    <p>
      &#1057;&#1074;&#1080;&#1095; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100;&#1089;&#1103; &#1073;&#1077;&#1079; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; (&#1085;&#1077; &#1089;&#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1081;&#1090;&#1080; &#1092;&#1072;&#1081;&#1083; config.text).
    </p>
    <p>
      <font color="#0000c0"># rename flash:/config.text.old flash:/config.text</font>&#160;// &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083;
    </p>
    <p>
      <font color="#0000c0"># copy flash:config.text running-config</font>&#160;// &#1089;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; confix.text &#1074; running-config
    </p>
    <p>
      <font color="#0000c0">(config)# enable secret cisco</font>
    </p>
    <p>
      <font color="#0000c0">(config)# username user1 secret cisco </font>// &#1089;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;
    </p>
    <p>
      <font color="#0000c0"># copy running-config startup-config</font>&#160;// &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Защита коммутируемой сети" FOLDED="true" ID="ID_1759634887" CREATED="1519112080161" MODIFIED="1720876939056"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>По умолчанию</b>&nbsp;&nbsp;на порту свитча включен <b>режим dynamic auto. </b>Рекомендуется <font color="#ff0000">отключать</font>&nbsp;&nbsp;автосогласование командой <font color="#0000c0">switchport nonegotiate</font>. В целях безопасности (подключение злоумышленника через access port как через trunk и последующее получение кадров). Рекомендуется <b>вручную устанавливать</b>&nbsp;&nbsp;режим работы порта (<b>trunk/access</b>)
    </p>
  </body>
</html></richcontent>
<node TEXT="Port Security" FOLDED="true" ID="ID_158786016" CREATED="1519112080161" MODIFIED="1519112080161"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_1316379476">Port Security</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1047;&#1072;&#1097;&#1080;&#1090;&#1072; &#1087;&#1086; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1084;. Port Security (&#1079;&#1072;&#1097;&#1080;&#1090;&#1072; &#1086;&#1090; &#1072;&#1090;&#1072;&#1082;&#1080; </b><a href="#ID_534359421">MAC Flooding</a><b>)</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# int f0/1</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport mode access</font>&#160;// <b>1. &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;</b>&#160;&#1087;&#1086;&#1088;&#1090; &#1074; access &#1088;&#1077;&#1078;&#1080;&#1084;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport port-security</font>&#160;// <b>2. &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;</b>&#160;&#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102; port-security
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport port-security maximum 2 [vlan &lt;vlan-list&gt;]</font>&#160;&#160;// <b>3. &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;</b>&#160;&#1084;&#1072;&#1082;&#1089;. &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077; - 2. &#1044;&#1083;&#1103; &#1090;&#1088;&#1072;&#1085;&#1082;&#1086;&#1074;&#1099;&#1093; &#1087;&#1086;&#1088;&#1090;&#1086;&#1074; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1085;&#1086; &#1077;&#1089;&#1083;&#1080; &#1086;&#1095;&#1077;&#1085;&#1100; &#1085;&#1091;&#1078;&#1085;&#1086;, &#1090;&#1086; &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1086;&#1087;&#1094;. &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#160;&#160;vlan, &#1087;&#1088;&#1080; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1080; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1099;&#1093; MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1090;&#1100; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1076;&#1083;&#1103; [VLAN &#1080;&#1083;&#1080; &lt;&#1087;&#1077;&#1088;&#1077;&#1095;&#1085;&#1103; VLAN&gt;], &#1080; &#1085;&#1077; &#1079;&#1072;&#1073;&#1099;&#1074;&#1072;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1087;&#1086;&#1088;&#1090; &#1074; &#1090;&#1088;&#1072;&#1085;&#1082;&#1086;&#1074;&#1099;&#1081; &#1088;&#1077;&#1078;&#1080;&#1084;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport port-security mac-address <b>sticky</b></font>&#160; // <b>4. &#1079;&#1072;&#1076;&#1072;&#1090;&#1100;</b>&#160;&#1088;&#1077;&#1078;&#1080;&#1084;, &#1087;&#1088;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; port-security &#1073;&#1091;&#1076;&#1077;&#1090; <b>&#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1080;&#1079;&#1091;&#1095;&#1072;&#1090;&#1100; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;</b>&#160; &#1080; &#1086;&#1085;&#1080; <b>&#1086;&#1089;&#1090;&#1072;&#1085;&#1091;&#1090;&#1089;&#1103;</b>&#160;&#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1089;&#1074;&#1080;&#1095;&#1072;. &#1042;&#1084;&#1077;&#1089;&#1090;&#1086; &#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1086;&#1075;&#1086; &#1089;&#1083;&#1086;&#1074;&#1072; sticky &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1085;&#1099;&#1081; MAC &#1072;&#1076;&#1088;&#1077;&#1089;. &#1045;&#1089;&#1083;&#1080; &#1101;&#1090;&#1091; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;, &#1090;&#1086; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1073;&#1091;&#1076;&#1091;&#1090; &#1080;&#1079;&#1091;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103;, &#1085;&#1086; &#1086;&#1085;&#1080; &#1085;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1099; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport port-security violation <b>shutdown</b></font>&#160; // <b>5. &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100;</b>&#160;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077; &#1087;&#1088;&#1080; &#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1077;&#1085;&#1080;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;. &#1042; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1086;&#1088;&#1090; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;. <b>Restrict</b>&#160; - &#1087;&#1088;&#1080; &#1085;&#1072;&#1088;&#1091;&#1096;&#1077;&#1085;&#1080;&#1080; &#1079;&#1072;&#1097;&#1080;&#1090;&#1099; &#1085;&#1077; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1088;&#1090;&#1072;, &#1082;&#1072;&#1076;&#1088;&#1099; &#1085;&#1077;&#1083;&#1077;&#1075;&#1080;&#1090;&#1080;&#1084;&#1085;&#1086;&#1075;&#1086; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072; &#1085;&#1077; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103;, &#1089;&#1080;&#1089;&#1072;&#1076;&#1084;&#1080;&#1085;&#1091; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077;. <b>Protect</b>&#160; - &#1090;&#1086;&#1078;&#1077; &#1095;&#1090;&#1086; &#1080; restrict, &#1085;&#1086; &#1073;&#1077;&#1079; &#1091;&#1074;&#1077;&#1076;&#1086;&#1084;&#1083;&#1077;&#1085;&#1080;&#1081;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport port-security aging time 2</font>&#160; //&#160;<b>&#1085;&#1077; sticky</b>. &#1089;&#1074;&#1080;&#1095; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1085;&#1077; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1090; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1080;&#1079; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1086;&#1088;&#1080;&#1077;&#1085;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; port-security. &#1045;&#1089;&#1083;&#1080; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1101;&#1090;&#1091; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091;, &#1090;&#1086; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1074;&#1099;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; (&#1085;&#1077; sticky, &#1072; &#1080;&#1084;&#1077;&#1077;&#1085;&#1086; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077;) &#1073;&#1091;&#1076;&#1091;&#1090; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1091;&#1076;&#1072;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; 2 &#1084;&#1080;&#1085;&#1091;&#1090;&#1099;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport port-security aging type [absolute | inactivity]</font>&#160;// <b>&#1085;&#1077; sticky</b>. &#1077;&#1089;&#1083;&#1080; &#1073;&#1099;&#1083;&#1072; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1072; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1072;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072;, &#1090;&#1086; &#1101;&#1090;&#1072; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1074; &#1082;&#1072;&#1082;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1091;&#1076;&#1072;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1074;&#1099;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;. Absolute &#8211; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1073;&#1091;&#1076;&#1091;&#1090; &#1091;&#1076;&#1072;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1074; &#1083;&#1102;&#1073;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1102; aging time. Inactivity - MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1073;&#1091;&#1076;&#1091;&#1090; &#1091;&#1076;&#1072;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; MAC &#1072;&#1076;&#1088;&#1077;&#1089; &#1085;&#1077; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1083;&#1089;&#1103; &#1085;&#1072; &#1087;&#1086;&#1088;&#1090; &#1089;&#1074;&#1080;&#1095;&#1072;
    </p>
    <p>
      <font color="#0000c0">(config)# mls rate-limit layer2 port-security rate_in_pps [burst_size]</font>&#160; // &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1087;&#1086;&#1083;&#1077;&#1079;&#1085;&#1072; &#1087;&#1088;&#1080; violation &#1088;&#1077;&#1078;&#1080;&#1084;&#1072;&#1093; protect &#1080; restrict. &#1054;&#1085;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1082;&#1072;&#1076;&#1088;&#1086;&#1074; &#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1091;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1102;&#1090; &#1085;&#1072; &#1087;&#1086;&#1088;&#1090; &#1086;&#1090; &#1072;&#1090;&#1072;&#1082;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086;. CPU &#1085;&#1077; &#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1086;&#1081; &#1083;&#1080;&#1096;&#1085;&#1080;&#1084;&#1080;&#1093; &#1082;&#1072;&#1076;&#1088;&#1086;&#1074;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072;: IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;</b>
    </p>
    <p>
      &#1063;&#1072;&#1089;&#1090;&#1086; &#1074;&#1089;&#1090;&#1088;&#1077;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1103;, &#1087;&#1088;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1082; &#1087;&#1086;&#1088;&#1090;&#1091; Access &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072; &#1089;&#1085;&#1072;&#1095;&#1072;&#1083;&#1072; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; <b>IP &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;</b>, &#1072; &#1082; IP &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1091; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; PC. &#1042; &#1101;&#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1091;&#1084; &#1085;&#1077; 1, &#1072; 2 &#1052;&#1040;&#1057;-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;. &#1042; &#1085;&#1086;&#1074;&#1099;&#1093; IOS &#1084;&#1086;&#1078;&#1085;&#1086; &#1103;&#1074;&#1085;&#1086; &#1088;&#1072;&#1079;&#1085;&#1077;&#1089;&#1090;&#1080; MAC &#1072;&#1076;&#1088;&#1077;&#1089; PC &#1080; MAC &#1072;&#1076;&#1088;&#1077;&#1089; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072; &#1074; &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; VLAN &#1089; &#1090;&#1086;&#1095;&#1082;&#1080; &#1079;&#1088;&#1077;&#1085;&#1080;&#1103; port security:
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport port-security maximum 1 vlan access</font>&#160; // &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1074; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086;&#1084; VLAN (&#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1099;&#1081; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;)
    </p>
    <p>
      &#160;<font color="#0000c0">&#160;&#160;(config-if)# switchport port-security maximum 1 vlan voice</font>&#160; // &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1074; &#1075;&#1086;&#1083;&#1086;&#1089;&#1086;&#1074;&#1086;&#1084; VLAN (&#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;)
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport port-security mac-address mac_&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072; vlan voice</font>&#160;// MAC IP-&#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1072;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport port-security mac-address mac_PC vlan access</font>&#160;// MAC-&#1072;&#1076;&#1088;&#1077;&#1089; PC
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1080;&#1072;&#1075;&#1085;&#1086;&#1089;&#1090;&#1080;&#1082;&#1072;:</b>
    </p>
    <p>
      <font color="#0000c0"># show port-security</font>&#160;// &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; port-security
    </p>
    <p>
      <font color="#0000c0"># show port-security interface f0/1</font>&#160;// &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; port-security
    </p>
    <p>
      <font color="#0000c0"># show port-security address</font>&#160;// MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1079;&#1072;&#1097;&#1080;&#1097;&#1072;&#1102;&#1090;&#1089;&#1103; port-security
    </p>
    <p>
      <font color="#0000c0"># show mls rate-limit</font>&#160;// &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; mls (rate-limit)
    </p>
    <p>
      <font color="#0000c0"># clear port-security sticky</font>&#160;// &#1086;&#1095;&#1080;&#1089;&#1090;&#1080;&#1090;&#1100; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1074;&#1099;&#1091;&#1095;&#1080;&#1083; port-security
    </p>
    <p>
      <font color="#0000c0"># clear port-security all</font>&#160;// &#1086;&#1095;&#1080;&#1089;&#1090;&#1080;&#1090;&#1100; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1074;&#1099;&#1091;&#1095;&#1080;&#1083; port-security
    </p>
    <p>
      <font color="#0000c0">(config)# errdisable recovery cause psecure-violation</font>&#160;// &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1100; &#1074;&#1089;&#1077; &#1087;&#1086;&#1088;&#1090;&#1099; &#1080;&#1079; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; err-disable (&#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1072; Port Security)
    </p>
    <p>
      <font color="#0000c0">(config-if)# shutdown</font>&#160;--&gt; <font color="#0000c0">no shutdown</font>&#160;// <b>&#1074;&#1099;&#1074;&#1086;&#1076;</b>&#160;&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1080;&#1079; <b>error\disable </b>
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="file1.txt" ID="ID_546305041" CREATED="1519112080162" MODIFIED="1519112080162"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      ! =================&#160;&#160;PORT SECURITY ====================
    </p>
    <p>
      !
    </p>
    <p>
      conf t
    </p>
    <p>
      !
    </p>
    <p>
      int fa0/2
    </p>
    <p>
      !
    </p>
    <p>
      &#160;switchport mode access
    </p>
    <p>
      &#160;switchport port-security max 2
    </p>
    <p>
      &#160;switchport port-security violation shut
    </p>
    <p>
      &#160;switchport port-security mac sticky
    </p>
    <p>
      &#160;switchport port-security
    </p>
    <p>
      exit
    </p>
    <p>
      ! ===========CONFIGURING ERRDISABLE RECOVERY===========
    </p>
    <p>
      errdisable recovery cause psecure-violation
    </p>
    <p>
      errdisable recovery interval 120
    </p>
    <p>
      end
    </p>
    <p>
      wr mem
    </p>
    <p>
      
    </p>
    <p>
      ! ROUTER
    </p>
    <p>
      conf t
    </p>
    <p>
      int e0/0
    </p>
    <p>
      no sh
    </p>
    <p>
      ip add 10.1.1.73 255.255.255.0
    </p>
    <p>
      mac 01.02.03
    </p>
    <p>
      
    </p>
    <p>
      exit
    </p>
    <p>
      exit
    </p>
    <p>
      ping 10.1.1.3
    </p>
  </body>
</html></richcontent>
</node>
</node>
