    <p>
      
    </p>
    <p>
      <b>Storm-Control </b>
    </p>
    <ul>
      <li>
        &#1085;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; unicast-&#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; (&#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1077;&#1075;&#1086; &#1074; &#1089;&#1077;&#1090;&#1080; &#1084;&#1085;&#1086;&#1075;&#1086;)
      </li>
      <li>
        Access &#1089;&#1074;&#1080;&#1095; - &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1082;&#1072;&#1082; &#1085;&#1072; &#1072;&#1087;&#1083;&#1080;&#1085;&#1082;&#1072;&#1093; (&#1087;&#1086;&#1088;&#1086;&#1075; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1080;&#1084;, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1084;&#1085;&#1086;&#1075;&#1086; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1074;&#1077;&#1097;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;), &#1090;&#1072;&#1082; &#1080; &#1085;&#1072; &#1087;&#1086;&#1088;&#1090;&#1072;&#1093;, &#1089;&#1084;&#1086;&#1090;&#1088;&#1103;&#1097;&#1080;&#1093; &#1085;&#1072; &#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1099;&#1093; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074;
      </li>
      <li>
        Distribution &#1089;&#1074;&#1080;&#1095; - &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1085;&#1072; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;&#1099;&#1093; &#1087;&#1086;&#1088;&#1090;&#1072;&#1093; (&#1085;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1084;&#1099;&#1093; - &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086;)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# storm-control <b>broadcast</b>&#160;level 50 30</font>&#160;// <b>1. &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1096;&#1080;&#1088;&#1086;&#1082;&#1086;&#1074;&#1077;&#1097;.</b>&#160;L2 &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1074; &#1087;&#1088;&#1086;&#1094;&#1077;&#1085;&#1090;&#1072;&#1093; (50 &#8211; &#1074;&#1077;&#1088;&#1093;. &#1087;&#1088;&#1077;&#1076;&#1077;&#1083; (Rising Threshold), 30 - &#1085;&#1080;&#1078;&#1085;. &#1087;&#1088;&#1077;&#1076;&#1077;&#1083; (Falling Threshold))
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# storm-control <b>multicast</b>&#160;level pps 30k 20k</font>&#160;//<b>&#160;2. &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1100; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1082;&#1072;&#1089;&#1090; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;</b>&#160;&#1074; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;&#1093; &#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1091;. 30k - 30000
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# storm-control <b>unicast</b>&#160;level bps 30m</font>&#160;// <b>3. &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1102;&#1085;&#1080;&#1082;&#1072;&#1089;&#1090; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;</b>&#160;&#1074; &#1073;&#1080;&#1090;&#1072;&#1093; &#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1091;. m - &#1084;&#1077;&#1075;&#1072;&#1073;&#1080;&#1090;&#1099;. &#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074; 30 &#1084;&#1077;&#1075;&#1072;&#1073;&#1080;&#1090; &#1085;&#1072; &#1102;&#1085;&#1080;&#1082;&#1072;&#1089;&#1090;&#1086;&#1074;&#1099;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# storm-control action &lt;shutdown | trap&gt;</font>&#160;// <b>4. &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077; &#1087;&#1088;&#1080; &#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1077;&#1085;&#1080;&#1080;</b>&#160;&#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074;&#1099;&#1096;&#1077; &#1083;&#1080;&#1084;&#1080;&#1090;&#1086;&#1074;. &#1042; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1088;&#1086;&#1080;&#1079;&#1086;&#1081;&#1076;&#1105;&#1090; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;. trap - &#1089;&#1088;&#1077;&#1079;&#1072;&#1085;&#1080;&#1077; &#1095;&#1088;&#1077;&#1079;&#1084;&#1077;&#1088;&#1085;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;, &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; <a href="#ID_1919197376">SNMP-&#1083;&#1086;&#1074;&#1091;&#1096;&#1082;&#1091;</a>.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># show storm-control [broadcast | multicast | unicast] </font>// &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1072; strom-control
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="DHCP Snooping" ID="ID_1818476919" CREATED="1519112080162" MODIFIED="1552639177533"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_567091282">DHCP</a>
    </p>
    <p>
      
    </p>
    <p>
      <b><a href="#ID_655589989">DHCP Snooping</a>&#160;(&#1079;&#1072;&#1097;&#1080;&#1090;&#1072; &#1086;&#1090; &#1072;&#1090;&#1072;&#1082;&#1080; </b><a href="#ID_1974769802">DHCP Spoofing</a><b>)</b>
    </p>
    <ul>
      <li>
        &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;&#160;&#1085;&#1072; &#1087;&#1086;&#1088;&#1090;&#1072;&#1093;, &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1087;&#1088;&#1077;&#1076;&#1087;&#1086;&#1083;&#1072;&#1075;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; DHCP-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
      </li>
    </ul>
    <p>
      <font color="#0000c0">(config)# ip dhcp snooping</font>&#160;// &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; dhcp snooping
    </p>
    <p>
      <font color="#0000c0">(config)# ip dhcp snooping vlan 1</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; dhcp snooping &#1076;&#1083;&#1103; vlan 1. &#1053;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086; vlan
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip dhcp snooping trust</font>&#160;// &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;., &#1086;&#1090; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1086;&#1078;&#1080;&#1076;&#1072;&#1077;&#1084; &#1087;&#1086;&#1083;&#1091;&#1095;. &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1086;&#1090; DHCP &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip dhcp snooping limit rate 2</font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; DHCP &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1074; 2 &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1091;. (&#1055;&#1088;&#1086;&#1090;&#1080;&#1074; <a href="#ID_953309800">&#1048;&#1089;&#1090;&#1086;&#1097;&#1077;&#1085;&#1080;&#1103; DHCP</a>). &#1055;&#1086;&#1088;&#1090;&#1099;, &#1089;&#1084;&#1086;&#1090;&#1088;&#1103;&#1097;&#1080;&#1077; &#1085;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1074;
    </p>
    <p>
      <font color="#0000c0">(config)# ip dhcp snooping binding &lt;mac-address&gt; vlan &lt;vid&gt; &lt;ip-address&gt; interface &lt;interface-id&gt; expiry &lt;seconds&gt;</font>&#160;// &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1074; &#1073;&#1072;&#1079;&#1091; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1082;&#1080; DHCP
    </p>
    <p>
      <font color="#0000c0">(config)# no ip dhcp snooping verify mac-address</font>&#160;// &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; DHCP snooping, &#1085;&#1072; &#1089;&#1074;&#1080;&#1095;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1072; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1103; MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;. &#1057;&#1074;&#1080;&#1095; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1090; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1074; DHCP-&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1077; MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&#1091; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1086;&#1085;&#1080; &#1085;&#1077; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090;, &#1090;&#1086; &#1089;&#1074;&#1080;&#1095; &#1086;&#1090;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090; &#1087;&#1072;&#1082;&#1077;&#1090;. &#1055;&#1088;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1101;&#1090;&#1091; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1091;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip dhcp relay information trusted</font>&#160;// &#1090;&#1072;&#1082; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1086;&#1074;&#1077;&#1088;&#1077;&#1085;&#1085;&#1099;&#1081; DHCP &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081;&#1089;&#1103; &#1074;&#1085;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1099;. &#1050;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; SVI &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077; &#1089;&#1074;&#1080;&#1095;&#1072;
    </p>
    <p>
      <font color="#0000c0">(config)# ip dhcp relay information trust-all</font>&#160;// &#1072;&#1085;&#1072;&#1083;&#1086;&#1075; &#1087;&#1088;&#1077;&#1076;&#1099;&#1076;&#1091;&#1097;&#1077;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;, &#1086;&#1076;&#1085;&#1072;&#1082;&#1086; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090; DHCP &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1076;&#1086;&#1074;&#1077;&#1088;&#1077;&#1085;&#1085;&#1099;&#1084; &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; SVI
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1080;&#1072;&#1075;&#1085;&#1086;&#1089;&#1090;&#1080;&#1082;&#1072;:</b>
    </p>
    <p>
      <font color="#0000c0"># show ip dhcp snooping</font>&#160;// &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1082; dhcp snooping
    </p>
    <p>
