<node TEXT="IP Source Guard" ID="ID_1687981971" CREATED="1519112080163" MODIFIED="1519112080163"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>IP Source Guard</b>
    </p>
    <ul>
      <li>
        <b>Access &#1089;&#1074;&#1080;&#1095;&#1080;</b>&#160;(&#1087;&#1086;&#1088;&#1090;&#1099;, &#1089;&#1084;&#1086;&#1090;&#1088;&#1103;&#1097;&#1080;&#1077; &#1085;&#1072; &#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1099;&#1093; &#1072;&#1073;&#1086;&#1085;&#1077;&#1085;&#1090;&#1086;&#1074;)
      </li>
      <li>
        &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1072; <a href="#ID_1818476919">dhcp snooping</a>
      </li>
    </ul>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip verify source vlan dhcp-snooping</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102; IP Source Guard
    </p>
    <p>
      <font color="#0000c0">(config)# ip source binding 00:E0:F7:EC:D0:10 vlan 1 192.168.1.1 interface f0/4</font>&#160;// &#1079;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1084; f0/4 &#1089;&#1080;&#1076;&#1080;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; (&#1083;&#1080;&#1073;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1089; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1084; &#1096;&#1083;&#1102;&#1079;&#1086;&#1084;), <b>IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;</b>. &#1069;&#1090;&#1086; &#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077; DHCP Snooping &#1085;&#1077;&#1090; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1086; &#1090;&#1086;&#1084;, &#1082;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084; &#1101;&#1090;&#1086;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1083; IP. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1085;&#1072; &#1085;&#1077;&#1075;&#1086; &#1089;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1079;&#1072;&#1097;&#1080;&#1090;&#1072;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1077; &#1073;&#1099;&#1083;&#1086;, &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1080; ip &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># show ip verify source</font>&#160;// &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1087;&#1086; IP Source Guard
    </p>
    <p>
      <font color="#0000c0"># show ip source binding</font>&#160;// &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1086; &#1089;&#1086;&#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1080; IP &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;
    </p>
    <p>
      <font color="#0000c0"># show ip dhcp snooping binding</font>&#160;// &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1082;&#1080; DHCP
    </p>
    <p>
      
    </p>
    <p>
      &#1089;&#1084;. <a href="#ID_1687373546">IP-spoofing </a>
    </p>
    <p>
      &#1089;&#1084;. <a href="#ID_1924269520">IP Source Guard</a>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Dynamic ARP Inspection" ID="ID_1708006955" CREATED="1519112080163" MODIFIED="1519112080163"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Dynamic ARP Inspection</b>
    </p>
    <p>
      &#1089;&#1084;. <a href="#ID_567022565">ARP Spoofing</a>
    </p>
    <p>
      &#1089;&#1084;. <a href="#ID_57330633">Dynamic ARP Inspection</a>
    </p>
    <ul>
      <li>
        &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; <b>dhcp snooping</b>
      </li>
    </ul>
    <p>
      <font color="#0000c0">(config)# ip arp inspection vlan 1</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102;. &#1044;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; vlan
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip arp inspection trust</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&#1093;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1087;&#1086;&#1090;&#1077;&#1085;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1072;&#1090;&#1072;&#1082;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1085;&#1072; uplink (&#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1074;&#1080;&#1095;&#1072;&#1084;&#1080;)
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip arp inspection limit rate 2</font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1082;&#1086;&#1083;-&#1074;&#1086; arp &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; &#1074; &#1089;&#1077;&#1082;. &#1085;&#1077; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; 2
    </p>
    <p>
      <font color="#0000c0">(config)# errdisable recovery cause arp-inspection interval 600</font>&#160;// &#1074;&#1099;&#1074;&#1077;&#1089;&#1090;&#1080; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1080;&#1079; errdisable &#1095;&#1077;&#1088;&#1077;&#1079; 600 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076; (&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1087;&#1072;&#1076;&#1077;&#1090; &#1074; errdisable &#1087;&#1088;&#1080; &#1085;&#1072;&#1088;&#1091;&#1096;&#1077;&#1085;&#1080;&#1080; arp-inspection)
    </p>
    <p>
      <font color="#0000c0">(config)# arp access-list <b>ARP-INSPECTION-EXCEPTIONS</b></font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; arp ACL
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-std-nacl)# permit ip host 192.168.1.1 mac host 00:E0:F7:EC:D0:10</font>&#160;//<b>&#160;&#1078;&#1077;&#1089;&#1090;&#1082;&#1086; &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1080; MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;.</b>&#160;&#1042; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1084;&#1091; &#1096;&#1083;&#1102;&#1079;&#1091;. &#1058;&#1086; &#1077;&#1089;&#1090;&#1100; &#1085;&#1072; &#1086;&#1090;&#1074;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &quot;MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1076;&#1083;&#1103; ip 192.168.1.1&quot;&#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1086;&#1090;&#1074;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1080;&#1079; &#1087;&#1086;&#1076; &#1085;&#1072;&#1089;&#1090;&#1086;&#1103;&#1097;&#1077;&#1075;&#1086; &#1096;&#1083;&#1102;&#1079;&#1072; &#1089; &#1084;&#1072;&#1082;&#1086;&#1084; 00:E0:F7:EC:D0:10. &#1045;&#1089;&#1083;&#1080; &#1086;&#1090;&#1074;&#1077;&#1090; &#1087;&#1088;&#1080;&#1076;&#1077;&#1090; &#1080;&#1079;-&#1087;&#1086;&#1076; &#1076;&#1088;&#1091;&#1075;&#1086;&#1075;&#1086; MAC &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;, &#1090;&#1086; &#1087;&#1086;&#1088;&#1090; &#1087;&#1077;&#1088;&#1077;&#1081;&#1076;&#1077;&#1090; &#1074; errdisable. (&#1055;&#1088;&#1080; &#1085;&#1072;&#1088;&#1091;&#1096;&#1077;&#1085;&#1080;&#1080; dhcp snooping &#1087;&#1086;&#1088;&#1090; &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; errdisable). &#1069;&#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1090;&#1072;&#1082; &#1078;&#1077; &#1090;&#1086;&#1075;&#1076;&#1072;, &#1082;&#1086;&#1075;&#1076;&#1072; ip &#1072;&#1076;&#1088;&#1077;&#1089; &#1079;&#1072;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; (&#1074; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1089;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1080; &#1082;&#1072;&#1082; &#1088;&#1072;&#1079; &#1091; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086; &#1096;&#1083;&#1102;&#1079;&#1072;) &#1080; &#1077;&#1089;&#1083;&#1080; &#1087;&#1086;&#1088;&#1090;, &#1079;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1096;&#1083;&#1102;&#1079; &#1085;&#1077; &#1087;&#1086;&#1084;&#1077;&#1095;&#1077;&#1090; &#1082;&#1072;&#1082; trusted (&#1082;&#1072;&#1082; trusted &#1076;&#1083;&#1103; Dynamic ARP Inspection, &#1072; &#1085;&#1077; &#1076;&#1083;&#1103; DHCP Snooping)
    </p>
    <p>
      <font color="#0000c0">(config)# ip arp inspection filter ARP-INSPECTION-EXCEPTIONS vlan 1</font>&#160;// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; ACL &#1085;&#1072; VLAN
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># show ip arp inspection</font>&#160;// &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; Dynamic ARP Inspection
    </p>
    <p>
      <font color="#0000c0"># show ip arp inspection interface</font>&#160;// &#1085;&#1072; &#1082;&#1072;&#1082;&#1080;&#1093; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&#1093; &#1074;&#1082;&#1083;. &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; Dynamic ARP Inspection
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="не исп. Native VLAN" ID="ID_225649924" CREATED="1519112080163" MODIFIED="1519112080163"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><a href="#ID_1802094515">Native VLAN</a><font color="#ff0000">&#160;1 &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074; &#1101;&#1085;&#1090;&#1077;&#1088;&#1087;&#1088;&#1072;&#1081;&#1079;&#1077;</font></b><font color="#ff0000">.</font>&#160;&#1050;&#1083;&#1072;&#1089;&#1089; &#1072;&#1090;&#1072;&#1082; - &#1072;&#1090;&#1072;&#1082;&#1072; &#1085;&#1072; Native VLAN&#160;&#160;(<a href="#ID_1537027905">VLAN Hopping) - VLAN double-tagging</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1077;&#1088;&#1099; &#1087;&#1088;&#1086;&#1090;&#1080;&#1074; VLAN double-tagging</b>
    </p>
    <p>
      1. &#1053;&#1072; &#1090;&#1088;&#1072;&#1085;&#1082;&#1072;&#1093; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1085;&#1077;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1081; Native VLAN. &#1053;&#1072; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1089;&#1074;&#1080;&#1095;&#1072;&#1093; &#1085;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084;
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# switchport trunk native vlan <b>50</b></font>&#160;// &#1085;&#1077; &#1087;&#1088;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100; &#1084;&#1077;&#1090;&#1082;&#1080;, &#1077;&#1089;&#1083;&#1080; &#1082;&#1072;&#1076;&#1088;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1099; &#1080;&#1079; &#1087;&#1086;&#1076; vlan 50. &#1044;&#1072;&#1085;&#1085;&#1099;&#1077; vlan 50 &#1085;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1090;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;
    </p>
    <p>
      2. &#1044;&#1083;&#1103; &#1090;&#1088;&#1072;&#1085;&#1082;&#1072; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; VLAN&#1099; &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084;&#1080; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">(config)# interface g0/1 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport trunk allowed vlan 2,3 </font>// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1091; &#1087;&#1086; &#1090;&#1088;&#1072;&#1085;&#1082;-&#1087;&#1086;&#1088;&#1090;&#1091; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; vlan'&#1086;&#1074;. <font color="#0000c0">(config-if)# switchport trunk allowed vlan <b>add</b>&#160;4 </font>// &#1076;&#1083;&#1103; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
    </p>
    <p>
      3. &#1042;&#1089;&#1077; &#1085;&#1077;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1077; &#1087;&#1086;&#1088;&#1090;&#1099; &#1087;&#1077;&#1088;&#1077;&#1074;&#1077;&#1089;&#1090;&#1080; &#1074; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; VLAN &#1080; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">(config)# interface range f0/4-6</font>
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-if-range)# switchport mode access</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1074;&#1077;&#1089;&#1090;&#1080; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084; access, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1073;&#1099;&#1083;&#1086; &#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1088;&#1072;&#1085;&#1082;
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-if-range)# switchport nonegotiate</font>&#160;// &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1072;&#1074;&#1090;&#1086;&#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1084;. <a href="#ID_1001585185">DTP </a>
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-if-range)# switchport access vlan 99</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1074;&#1077;&#1089;&#1090;&#1080; &#1074; &#1085;&#1077;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1081; VLAN
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-if-range)# shutdown</font>&#160;// &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1074;&#1089;&#1077; &#1085;&#1077;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;
    </p>
    <p>
      4. &#1058;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; Native VLAN
    </p>
    <p>
      <font color="#0000c0">(config)# vlan dot1q native</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
