    </p>
    <p>
      <font color="#0000c0">(config)# interface range fa0/1-2</font>&#160;// &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1074;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if-range)# channel-group 1 mode on </font>// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1083;&#1086;&#1075;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;. (&#1072;&#1075;&#1088;&#1077;&#1075;. &#1082;&#1072;&#1085;&#1072;&#1083;)
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1072;&#1075;&#1088;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1086;&#1074;</b>
    </p>
    <p>
      <font color="#000000">1.&#160;</font><font color="#0000c0">(config)# interface range fa0/1-2</font>&#160;// &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1074; &#1085;&#1072; <b>&#1089;&#1074;&#1080;&#1090;&#1095;&#1077; L3</b>
