<node TEXT="STP" FOLDED="true" ID="ID_1284575967" CREATED="1519112080166" MODIFIED="1519112080166"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_1119944958">STP (Spanning Tree Protocol)</a>
    </p>
    <ul>
      <li>
        &#1076;&#1083;&#1103; &#1094;&#1077;&#1083;&#1077;&#1081; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;&#1084;&#1080; &#1088;&#1072;&#1079;&#1085;&#1086;&#1081; &#1096;&#1080;&#1088;&#1080;&#1085;&#1099;
      </li>
      <li>
        Bridge ID --&gt; Root path cost) --&gt; Port priority ( Priority+vlan(sys-id-ext - Extend System ID))
      </li>
    </ul>
    <p>
      <b>&#1044;&#1080;&#1072;&#1075;&#1085;&#1086;&#1089;&#1090;&#1080;&#1082;&#1072;</b>
    </p>
    <p>
      <font color="#0000c0"># show spanning-tree summary</font>&#160;// &#1074;&#1089;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1074; spanning-tree
    </p>
    <p>
      <font color="#0000c0"># show spanning-tree (vlan 1)</font>&#160;// &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1087;&#1086; spanning-tree
    </p>
    <p>
      <font color="#0000c0"># show spanning-tree int f0/1 portfast</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; &#1083;&#1080; &#1085;&#1072; f0/1 &#1088;&#1077;&#1078;&#1080;&#1084; portfast
