<node TEXT="FHRP резервирование" FOLDED="true" ID="ID_1703168196" CREATED="1519112080173" MODIFIED="1519112080173"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_1283278995">FHRP &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;</a>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># show standby (vrrp or glbp)</font>&#160;// &#1080;&#1085;&#1092;&#1086; &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; FHRP
    </p>
    <p>
      <font color="#0000c0"># show standby brief</font>&#160;//&#160;&#160;&#1080;&#1085;&#1092;&#1086; &#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; &#1075;&#1088;&#1091;&#1087;&#1087;&#1099; FHRP &#1074; &#1074;&#1080;&#1076;&#1077; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# interface vlan 10 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# standby 1 version 2</font>&#160;// &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; <b>&#1085;&#1086;&#1084;&#1077;&#1088; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080;</b>&#160;2 (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 1), &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1086; &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1093; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080;
    </p>
    <p>
      &#160;
    </p>
  </body>
</html></richcontent>
<node TEXT="HSRP на SVI (L3)" ID="ID_1603069535" CREATED="1519112080173" MODIFIED="1519112080173"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1874048794">HSRP</a>&#160;&#160;&#160;<a href="#ID_1597419282">SVI</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1050;&#1072;&#1082; &quot;&#1054;&#1076;&#1080;&#1085; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081;, &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; - &#1079;&#1072;&#1087;&#1072;&#1089;&#1085;&#1086;&#1081;&quot;, &#1090;&#1072;&#1082; &#1080; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; - </b>&#160;(&#1088;&#1077;&#1075;&#1091;&#1083;&#1080;&#1088;&#1091;&#1077;&#1084; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1086;&#1084;)
    </p>
    <ul>
      <li>
        &#1074; STP &#1088;&#1091;&#1090;&#1086;&#1084; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1089;&#1074;&#1080;&#1095;
      </li>
    </ul>
    <p>
      <b>&#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1100; &#1096;&#1083;&#1102;&#1079;&#1072;</b>
    </p>
    <p>
      <b>&#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; HSRP Router1 </b><font color="#0000c0">R1,<b>2</b>&#160;(config)# int vlan 10(20)</font>&#160;// &#1076;&#1083;&#1103; SVI
    </p>
    <p>
      <font color="#0000c0">R1,<b>2</b>&#160;(config)# int f0/1</font>&#160;// &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1090; &#1074; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1089;&#1077;&#1090;&#1100; &#1085;&#1072; &#1089;&#1074;&#1080;&#1095;&#1080;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">R1,<b>2</b>(config-if)# standby <b>1</b>&#160;ip(ipv6) 192.168.1.<b>1</b></font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1074;&#1080;&#1088;&#1090;. ip-&#1072;&#1076;&#1088;&#1077;&#1089; (&#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1084; &#1096;&#1083;&#1102;&#1079;&#1086;&#1084; &#1076;&#1083;&#1103; &#1089;&#1074;&#1080;&#1090;&#1095;&#1077;&#1081;, &#1089;&#1084;&#1086;&#1090;&#1088;&#1103;&#1097;&#1080;&#1093; &#1085;&#1072; &#1082;&#1086;&#1085;&#1092;. &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;). &#1059; &#1086;&#1073;&#1086;&#1080;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; &#1086;&#1085;&#160;&#160;&#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1099;&#1081;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1101;&#1082;&#1079;&#1077;&#1084;&#1087;&#1083;&#1103;&#1088;&#1086;&#1074;. &#1045;&#1089;&#1083;&#1080; &#1079;&#1072;&#1076;&#1072;&#1077;&#1084; 2 &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072; (&#1096;&#1083;&#1102;&#1079;&#1072;), &#1090;&#1086; &#1082;&#1072;&#1078;&#1076;&#1086;&#1084;&#1091; - &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088; &#1101;&#1082;&#1079;&#1077;&#1084;&#1087;&#1083;&#1103;&#1088;&#1072; (&#1095;&#1090;&#1086;&#1073;&#1099; &#1073;&#1099;&#1083;&#1080; &#1074;&#1099;&#1076;&#1072;&#1085;&#1099;&#160;&#160;&#1088;&#1072;&#1079;&#1085;&#1099;&#1077; MAC-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;)
    </p>
    <p>
      <b>&#160;&#160;&#160;-----------------&#1086;&#1089;&#1085;&#1086;&#1074;&#1072; &#1074;&#1099;&#1096;&#1077;, &#1085;&#1080;&#1078;&#1077; &#1076;&#1077;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080;-----------</b>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;R1(config-if)# stanby 1 priority 110</font>&#160;// <b>&#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1072;&#1082;&#1090;&#1080;&#1074;&#1085;&#1099;&#1084; (Active)</b>. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#160;110 (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;. 100). &#1053;&#1091;&#1078;&#1085;&#1086; <b>&#1074;&#1082;&#1083;./&#1074;&#1099;&#1082;&#1083;</b>. &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099; &#1085;&#1072; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1093; - &#1077;&#1089;&#1083;&#1080; &#1085;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; <b>preempt</b>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">R1,<b>2</b>(config-if)# standby 1 preempt</font>&#160;// &#1076;&#1077;&#1083;&#1072;&#1077;&#1090; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1089; &#1085;&#1072;&#1080;&#1074;&#1099;&#1089;&#1096;. &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1086;&#1084; &#1072;&#1082;&#1090;&#1080;&#1074;. &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;R1,<b>2</b>(config-if)# standby 1 authentication md5 key-string cisco</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1102;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">R1,<b>2</b>(config-if)# standby 1 timers 200 750</font>&#160;// &#1088;&#1077;&#1075;&#1091;&#1083;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; <b>&#1090;&#1072;&#1081;&#1084;&#1077;&#1088;&#1086;&#1074;</b>&#160;hsrp, &#1089;&#1077;&#1082;. &#1043;&#1076;&#1077; 200 &#8211; hello &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083; (&#1082;&#1072;&#1082; &#1095;&#1072;&#1089;&#1090;&#1086; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1090;&#1100; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; hello &#1080; keep-alive) &#1080; 750 &#8211; hold interval (&#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1080;&#1079;&#1085;&#1072;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;&#1084;)
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">R1,<b>2</b>(config-if)# standby 1 preempt delay minimum 300</font>&#160;&#160;// &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1074;&#1088;&#1077;&#1084;&#1103; &#1079;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1080; &#1074; &#1089;&#1077;&#1082;., &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1073;&#1091;&#1076;&#1077;&#1090; <b>&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;&#1089;&#1103; &#1075;&#1083;&#1072;&#1074;&#1085;&#1099;&#1084;.</b>&#160;&#1047;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; &#1085;&#1091;&#1078;&#1085;&#1072; &#1076;&#1083;&#1103; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="HSRP падение канала" ID="ID_607302375" CREATED="1519112080174" MODIFIED="1519112080174"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;, &#1072; &#1085;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>I. &#1054;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1103; &#1083;&#1080;&#1085;&#1082;&#1072;</b>
    </p>
    <p>
      <b>#----&#1076;&#1083;&#1103; HSRP &#1080; VRRP-----</b>
    </p>
    <p>
      <font color="#0000c0">R2(config)# track 1 interface f0/0 line-protocol</font>&#160;// <b>&#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077;</b>&#160;&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1089;&#1084;&#1086;&#1090;&#1088;&#1103;&#1097;&#1077;&#1075;&#1086; &#1085;&#1072; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1087;&#1072;&#1076;&#1072;&#1077;&#1090;, &#1090;&#1086; &#1089;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; <b>track 1</b>
    </p>
    <p>
      <font color="#0000c0">R<b>2</b>&#160;(config)# int f0/1</font>&#160;// &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1090; &#1074; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1089;&#1077;&#1090;&#1100;
    </p>
    <p>
      <b>&#160;&#160;&#160;<font color="#0000c0">R2(config-if)# standby 1 track 1 decrement 20</font></b>&#160;// &#1082;&#1086;&#1075;&#1076;&#1072; &#1089;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; track 1, &#1090;&#1086; &#1090;&#1077;&#1082;. &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1085;&#1080;&#1078;&#1077;&#1085; &#1085;&#1072; 20 &#1077;&#1076;&#1080;&#1085;&#1080;&#1094;
    </p>
    <p>
      #-----<b>&#1048;&#1051;&#1048; (&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; HSRP)</b>---------
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">R2(config-if)# standby 1 track 1 f0/1 20</font>&#160;// <b>&#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;</b>&#160;&#1073;&#1077;&#1079; &#1076;&#1086;&#1087;. &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1103; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072; &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;.
    </p>
    <p>
      
    </p>
    <p>
      <b>II. &#1054;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1086;&#1090;&#1077;&#1088;&#1080; &#1089;&#1074;&#1103;&#1079;&#1080; (&#1083;&#1080;&#1085;&#1082; &#1074; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077;). </b>
    </p>
    <p>
      <b>&#1058;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; IP SLA (Service Level Agreements)</b>&#160;- <b>&#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;&#1080;&#1085;&#1075; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1080; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1072; </b>- &#1076;&#1083;&#1103; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1103; &#1083;&#1080;&#1085;&#1082;&#1086;&#1074; &#1080; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1103; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1082;&#1072;&#1085;&#1072;&#1083;&#1072;, &#1086;&#1085;&#1072; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1090; &#1086;&#1073; &#1101;&#1090;&#1086;&#1084; &#1080; &#1094;&#1080;&#1089;&#1082;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1089;&#1103; &#1085;&#1072; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;.
    </p>
