    </p>
    <p>
      <b>1. &#1056;&#1072;&#1079;&#1073;&#1080;&#1090;&#1100; &#1085;&#1072; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1099;</b>
    </p>
    <p>
      <font color="#0000c0">(config)# vlan 2</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-vlan)# name VLAN2</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1080;&#1084;&#1103; &#1076;&#1083;&#1103; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072;
    </p>
    <p>
      <font color="#0000c0">(config)# interface fa0/1</font><font color="#000000">&#160;// &#1085;</font>&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;, &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;. &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;<font color="#000000">&#160; </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport mode access</font><font color="#000000">&#160;// &#1087;&#1086;&#1088;&#1090; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084; Access Port</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# switchport access vlan 2 </font><font color="#000000">// &#1082;&#1072;&#1082;&#1080;&#1084; VLAN&#1086;&#1084; &#1084;&#1072;&#1088;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1088;&#1090; </font>
    </p>
    <p>
      <b>2. &#1053;&#1072;&#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1084; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1072;&#1084;</b>
    </p>
    <p>
      <font color="#0000c0">(config)# interface vlan 2 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip address 2.2.2.1 255.255.255.0 </font>
    </p>
    <p>
      <b>3. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; WS</b>
    </p>
    <p>
      2.2.2.2/24 GW 2.2.2.1
    </p>
    <p>
      <b>4. Switch L3 &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip routing </font>// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; IP &#1088;&#1086;&#1091;&#1090;&#1080;&#1085;&#1075;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="NAT/PAT (доступ в Интернет)" FOLDED="true" ID="ID_1962508493" CREATED="1519112080175" MODIFIED="1725796431921"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_31864175">NAT/PAT</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Диагностика</b>
    </p>
    <p>
      <font color="#0000c0"># show ip nat translation</font>&nbsp;// показать текущую трансляцию (таблица трансляции)
    </p>
    <p>
      <font color="#0000c0"># show ip nat statistics</font>&nbsp;// показать кол ичество срабатываний (счетчики) NAT
    </p>
    <p>
      <font color="#0000c0"># show ip nat nvi translation</font>&nbsp;// показать текущую трансляцию (для NVI NAT)
    </p>
    <p>
      <font color="#0000c0"># show ip nat nvi statistics</font>&nbsp;// показать количество срабатываний (счетчики) NAT (для NVI NAT)
    </p>
    <p>
      <font color="#0000c0"># debug ip nat</font>&nbsp;// включить вывод отладочной информации. Не использовать на нагруженном оборудовании (сильно нагружает процессор, может подвесить оборудование)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># clear ip nat translantion *</font>&nbsp;// удалить записи из таблицы трансляции
    </p>
    <p>
      
    </p>
    <p>
      Настройки NAT для <b>Cisco ASA</b>&nbsp;см. <a href="#ID_1383651692">здесь</a>
    </p>
  </body>
</html></richcontent>
<node TEXT="1. Static NAT" ID="ID_937725173" CREATED="1519112080175" MODIFIED="1364430727486"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Static NAT (не используется)</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0 </font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;&nbsp;(config-if)# ip nat <b>inside</b></font>&nbsp;&nbsp;// <b>Пометить</b>&nbsp;&nbsp;интерфейс как <b>внутренний</b>&nbsp;(локальная сеть)
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1 </font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;&nbsp;(config-if)# ip nat <b>outside</b></font>&nbsp;&nbsp;// <b>Пометить</b>&nbsp;&nbsp;интерфейс как <b>внешний</b>&nbsp;(интернет)
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat inside source static 192.168.1.2 210.210.210.30</font>&nbsp;&nbsp;// включить статический NAT. IP адрес 192.168.1.2 будет транслироваться на 210.210.210.30 (предоставляет провайдер)
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="2. Dynamic NAT" ID="ID_1652269167" CREATED="1519112080175" MODIFIED="1725864914618"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Dynamic NAT (не используется)</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0</font>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;<font color="#0000c0">(config-if)# ip nat inside</font>&nbsp;// пометить интерфейс как внутренний (локальная сеть)
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# ip nat outside</font>&nbsp;// пометить интерфейс как внешний (интернет)
    </p>
    <p>
      <font color="#0000c0">(config)# access-list <b>1</b>&nbsp;permit 192.168.1.0 0.0.0.255</font>&nbsp;// создать стандартный нумерованный ACL, который будет указывать диапазон частных ip адресов, которым будет разрешено транслироваться на внешние ip адреса
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat pool EXT_IP 210.210.210.30&nbsp;210.210.210.40&nbsp;netmask 255.255.255.0</font>&nbsp;// создать пул ip адресов с именем EXT_IP. Это IP-адреса, на которые будут транслироваться частные IP-адреса, указанные в access-list 1
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat inside source list <b>1</b>&nbsp;pool EXT_IP</font>&nbsp;// включить динамический NAT, где list 1 – диапазон частных IP-адресов, pool EXT_IP – диапазон публичных IP-адресов
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="3. PAT (NAT с перегрузкой)" FOLDED="true" ID="ID_1935978126" CREATED="1519112080176" MODIFIED="1725864914556"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>PAT (NAT с перегрузкой) - Port address translation </b>
    </p>
    <p>
      <b>Подмена адреса источника</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0</font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;&nbsp;(config-if)# ip nat inside</font>&nbsp;&nbsp;// <b>1.1 пометить интерфейс</b>&nbsp;как внутренний (локальная сеть)
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;&nbsp;(config-if)# ip nat outside</font>&nbsp;&nbsp;// <b>1.2 пометить интерфейс</b>&nbsp;&nbsp;как внешний (интернет)
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat pool OVRLD 210.210.210.30&nbsp;210.210.210.30&nbsp;netmask 255.255.255.0</font>&nbsp;&nbsp;// <b>2. указать</b>&nbsp;&nbsp;на какой ip будем транслировать внутренние IP-адреса локальной сети (здесь он только один, поэтому повторяется два раза)
    </p>
    <p>
      <font color="#0000c0">(config)# access-list 7 permit 192.168.1.0 0.0.0.255</font>&nbsp;&nbsp;// <b>3. указать пул внутренних IP-адресов</b>, которые будем транслировать
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat inside source list 7 pool OVRLD overload</font>&nbsp;&nbsp;// <b>4. включить PAT</b>, где list 7 – диапазон частных IP-адресов, pool OVRLD – диапазон публичных IP-адресов
    </p>
    <p>
      
    </p>
    <p>
      (config)# <font color="#0000c0">interface FastEthernet0/0</font>&nbsp;&nbsp;// <b>1.1</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;(config-if)# <font color="#0000c0">ip nat inside</font>
    </p>
    <p>
      (config)# <font color="#0000c0">interface FastEthernet0/1</font>&nbsp;&nbsp;// <b>1.2</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;(config-if)# <font color="#0000c0">ip nat outside</font>
    </p>
    <p>
      (config)# <font color="#0000c0">access-list 1 permit 192.168.0.0 0.0.0.255</font>&nbsp;&nbsp;// <b>3.&nbsp;Создать</b>&nbsp;стандартный список доступа (ACL) с номером 1, который разрешает трафик с подсети 192.168.0.0/24
    </p>
    <p>
      (config)# <font color="#0000c0">ip nat inside source list 1 interface FastEthernet0/1 <b>overload</b></font>&nbsp;&nbsp;// <b>4. Включить&nbsp;PAT</b>&nbsp;для обработки исходящего трафика с внутреннего интерфейса (FastEthernet0/0) и его преобразования через интерфейс FastEthernet0/1. <b>overload</b>&nbsp;указывает на использование PAT (на использование одного общего IP-адреса, который проецируется на множество приватных)
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>Проброс портов&nbsp;(например, до нашего Web-сервера из Интернета)</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat inside source static 192.168.1.3 interface f0/0</font>&nbsp;// <b>проброс всех портов</b>&nbsp;на ip 192.168.1.3. f0/0 – интерфейс, направленный в интернет (аналог DMZ в простых роутерах)
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat inside source static 192.168.1.3 210.210.210.30</font>&nbsp;// <b>ИЛИ</b>&nbsp;&nbsp;проброс (что перебиваем - на что перебиваем)
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat inside source static tcp 192.168.1.3 80 210.210.210.30&nbsp;80</font>&nbsp;// <b>проброс веб-порта</b>, где 192.168.1.3 - адрес компьютера в локальной сети&nbsp;и 210.210.210.30 -&nbsp;белый IP-адрес, то есть адрес, на который NAT транслирует внутренние IP-адреса
    </p>
    <p>
      
    </p>
    <p>
      <font color="#ff0000">!!!</font>&nbsp;Команда «<b>ip nat inside source list 7 pool OVRLD overload</b>» (см. выше) перебивает внутренние (частные) IP-адреса на любой адрес, который мы указываем в ip nat pool ovrld. Дело в том, что этот IP-адрес (на который мы перебиваем) не будет привязан к IP-адресу, который весит на интерфейсе смотрящего на провайдера. Это может создать множество проблем, поэтому есть альтернативная команда (<b>вместо пункта 2</b>&nbsp;и <b>пункта 4</b>):
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat inside source list 7 interface f0/1 overload </font>// перебивать частные IP-адреса на IP-адрес, который висит на интерфейсе, смотрящем на провайдера
    </p>
    <p>
      
    </p>
    <p>
      <b>Подмена адреса назначения - двойной NAT. </b>Перебивка источника и <b>назначения</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat outside source static 5.5.5.5 95.213.4.228</font>&nbsp;// (на что перебивать - что перебивать)
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="case1" ID="ID_565049042" CREATED="1725864919127" MODIFIED="1725865189723"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Чтобы использовать оба IP-адреса</b>, выделенных провайдером, нужно настроить NAT так, чтобы трафик от каждой организации транслировался через свой IP-адрес.
    </p>
    <p>
      Это можно сделать с помощью настройки <b>NAT overload (PAT)</b>&nbsp;с использованием разных пулов адресов для каждого отдела.
    </p>
    <p>
      
    </p>
    <p>
      <b>******* Router1 *******</b>
    </p>
    <p>
      <b>Создать два пула NAT, каждый из которых содержит один из IP-адресов.</b>
    </p>
    <p>
      Router1(config)#<font color="#0000c0">ip nat pool org1 210.0.11.10 210.0.11.10 netmask 255.255.255.0</font>
    </p>
    <p>
      Router1(config)#<font color="#0000c0">ip nat pool org2 210.0.11.20 210.0.11.20 netmask 255.255.255.0</font>
    </p>
    <p>
      <b>Создать списки доступа (access-list), чтобы различать трафик разных организаций.</b>
    </p>
    <p>
      Router1(config)#<font color="#0000c0">access-list 1 permit 172.16.10.0 0.0.0.255</font>
    </p>
    <p>
      Router1(config)#<font color="#0000c0">access-list 1 permit 192.168.10.0 0.0.0.255</font>
    </p>
    <p>
      Router1(config)#<font color="#0000c0">access-list 2 permit 172.16.20.0 0.0.0.255</font>
    </p>
    <p>
      Router1(config)#<font color="#0000c0">access-list 2 permit 192.168.20.0 0.0.0.255 </font>
    </p>
    <p>
      <b>Применить настройки NAT, используя созданные списки доступа и пулы IP-адресов.</b>
    </p>
    <p>
      Router1(config)#i<font color="#0000c0">p nat inside source list 1 pool org1 overload</font>
    </p>
    <p>
      Router1(config)#<font color="#0000c0">ip nat inside source list 2 pool org2 overload</font>
    </p>
    <p>
      <b>Назначить интерфейсы. Указать, какие интерфейсы находятся внутри сети (inside), а какой интерфейс является внешним (outside).</b>
    </p>
    <p>
      Router1(config)#<font color="#0000c0">interface FastEthernet 0/0</font>
    </p>
    <p>
      Router1(config-if)#<font color="#0000c0">ip nat inside</font>
    </p>
    <p>
      Router1(config)#<font color="#0000c0">interface FastEthernet 0/1</font>
    </p>
    <p>
      Router1(config-if)#<font color="#0000c0">ip nat outside</font>
    </p>
    <p>
      <b>Проверить, что трансляция адресов работает корректно.</b>
    </p>
    <p>
      Router1#<font color="#0000c0">show ip nat translations</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="4. NVI NAT" ID="ID_770483862" CREATED="1519112080176" MODIFIED="1519112080176"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>NVI NAT (&#1085;&#1072; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1077; PAT). &#1041;&#1077;&#1079; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1103; inside\outside &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip nat enable</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; NAT &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077;
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>&#160;// &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1090; &#1074; &#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip nat enable</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; NAT &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077;
    </p>
    <p>
      <font color="#0000c0">(config)# access-list 7 permit 192.168.1.0 0.0.0.255</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1087;&#1091;&#1083; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1093; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1073;&#1091;&#1076;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1073;&#1080;&#1074;&#1072;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat source list 7 interface f0/1 overload</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; PAT, &#1075;&#1076;&#1077; list 7 &#8211; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085; &#1095;&#1072;&#1089;&#1090;&#1085;&#1099;&#1093; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;, f0/1 &#8211; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;, &#1085;&#1072; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1073;&#1091;&#1076;&#1091;&#1090; &#1090;&#1088;&#1072;&#1085;&#1089;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1095;&#1072;&#1089;&#1090;&#1085;&#1099;&#1077; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#ff0000">!!! </font>&#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#171;<b>inside</b>&#187; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103;.
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="case 0" ID="ID_1874352379" CREATED="1519112080176" MODIFIED="1725607080700"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>SRV2&lt;--&gt;R2(Провайдер)&lt;------&gt;R1&lt;—&gt;SW1&lt;—&gt;SRV1 (локальный Web-сервер)</b>
    </p>
    <p>
      <b>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&lt;—&gt;WSs1</b>
    </p>
    <p>
      <b>1. Настройки WSs и SRV</b>
    </p>
    <p>
      WSs1: 192.168.2.2/24 gw 192.168.2.1
    </p>
    <p>
      SRV1: 192.168.3.2/24 gw 192.168.3.1
    </p>
    <p>
      <b>2. Настроить коммутатор SW1 </b>
    </p>
    <p>
      <font color="#0000c0">(config)# vlan 2</font>&nbsp;// создать сегмент
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-vlan)# name users</font>&nbsp;// задать имя для сегмента, аналогично для сервера
    </p>
    <p>
      <font color="#0000c0">(config)# interface fa0/2</font><font color="#000000">&nbsp;// н</font>астраиваем интерфейс, обслуж. сегмент <b>или range</b>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# switchport mode access</font><font color="#000000">&nbsp;// порт в режим Access Port</font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# switchport access vlan 2 </font><font color="#000000">// каким VLANом маркировать порт </font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font><font color="#000000">&nbsp;// настроить Trunk Port до маршрутизатора</font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# switchport mode trunk </font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# switchport trunk allowed vlan 2,3</font>
    </p>
    <p>
      <b>3. Настроить роутер R1</b>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>&nbsp;// поднять физический порт (в DOWNе по умолчанию)
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# no shutdown</font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0.2</font>&nbsp;// <b>создать подинтерфейсы для каждого VLANа</b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-subif)# encapsulation dot1Q 2</font>&nbsp;// указать номер VLANа
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-subif)# ip address 192.168.2.1 255.255.255.0</font>&nbsp;// задать IP-адрес
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-subif)# no shutdown </font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0</font>&nbsp;// <b>настроить доступ в Интернет</b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-if)# ip address 213.235.10.2 255.255.255.252</font>&nbsp;// задать IP-адрес
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-if)# no shutdown </font>
    </p>
    <p>
      <font color="#0000c0">(config)# ip route&nbsp;&nbsp;0.0.0.0 0.0.0.0 213.235.10.1&nbsp;</font><font color="#000000">// <b>задать маршрут до провайдера</b>&nbsp;&nbsp;(R2) </font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0</font>&nbsp;// <b>NAT. задать внеш. интерфейс</b>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# ip nat outside </font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1.2</font>&nbsp;// <b>NAT. задать&nbsp;&nbsp;внутр. интерфейс</b>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# ip nat inside</font>
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list standard&nbsp;FOR-NAT</font><font color="#000000">&nbsp;// <b>NAT. </b></font><b>создать access list с именем (какой трафик будем NATить)</b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-std-nacl)#&nbsp;&nbsp;permit 192.168.2.0 0.0.0.255</font>&nbsp;// <b>NAT. указать сети NAT </b>
    </p>
    <p>
      <b><font color="#0000c0">(config)# ip nat inside source list FOR-NAT interface f0/0 overload</font>&nbsp;&nbsp;// NAT.<a href="#ID_31864175">PAT</a></b>
    </p>
    <p>
      <font color="#0000c0"><b>(config)# ip nat inside source static tcp 192.168.3.2 80 213.235.10.2 80</b></font>&nbsp;// <b>Cтатический NAT</b>. Для доступа к локальному web-серверу на SRV1
    </p>
    <p>
      <b>4. Настроить &quot;как-бы Интернет&quot; - для Cisco Packet Tracer</b>
    </p>
    <p>
      <font color="#0000c0">R2(config)# interface f0/0</font>&nbsp;// поднять физический порт (в DOWNе по умолчанию)
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">R2(config-if)# ip address 213.235.10.1 255.255.255.252</font>&nbsp;// задать IP-адрес до R1 (30 бит)
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# no shutdown</font>
    </p>
    <p>
      <font color="#0000c0">R2(config)# interface f0/1</font>&nbsp;// поднять физический порт (в DOWNе по умолчанию)
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">R2(config-if)# ip address 213.235.20.1 255.255.255.252</font>&nbsp;// IP-адрес до SRV2(30 бит)
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# no shutdown</font>
    </p>
    <p>
      SRV2: 213.235.20.2/30 gw 213.235.20.1
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="PPP, HDLC, Frame relay" FOLDED="true" ID="ID_1155581270" CREATED="1519112080177" MODIFIED="1744533678308"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      см. <a href="#ID_123300154">Serial link</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Диагностика</b>
    </p>
    <p>
      <span style="color: #0000c0;"># show frame-relay pvc</span>&#xa0;// показать pvc frame-relay
    </p>
    <p>
      <span style="color: #0000c0;"># show frame-relay map</span>&#xa0;// показать соответствие IP-адреса и DLCI
    </p>
    <p>
      <span style="color: #0000c0;">#&#xa0;&#xa0;show controllers s1/0</span>&#xa0;// состояние и доп. сведения Serial Link
    </p>
    <p>
      
    </p>
    <p>
      <b>Задать скорость для DCE.</b>&#xa0;&#xa0;DTE начнет работать с этой скоростью
    </p>
    <p>
      <span style="color: #0000c0;">(config)# interface s1/0</span>&#xa0;// clock rate и bandwidth должны примерно совпадать
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;(config-if)# clock rate &lt;bitps&gt;</span>&#xa0;// задать clock rate (фактическая скорость работы интерфейса Serial Link)
    </p>
    <p>
      <span style="color: #0000c0;">&#xa0;&#xa0;&#xa0;(config-if)# bandwidth &lt;bitps&gt;</span>&#xa0;// скорость для самой Cisco
    </p>
  </body>
</html></richcontent>
<node TEXT="R1&lt;--&gt;R2 по PPP+authentication" ID="ID_556795476" CREATED="1519112080177" MODIFIED="1519112080177"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1076;&#1074;&#1091;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074; &#1087;&#1086; L2 &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; PPP</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">R1,2(config)# username R2(R1) password cisco</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1091;&#1095;&#1077;&#1090;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;
    </p>
    <p>
      <font color="#0000c0">R1,2(config)# interface s9/0</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1080;&#1084; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">R1,2(config-if)# encapsulation ppp</font>&#160;//&#160;&#1088;&#1077;&#1078;&#1080;&#1084; &#1080;&#1085;&#1082;&#1072;&#1087;&#1089;&#1091;&#1083;&#1103;&#1094;&#1080;&#1080;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;R1,2(config-if)# ppp <b>authentication</b>&#160;chap</font>&#160;//&#160;&#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082; R1(R2) &#1073;&#1077;&#1079; <b>&#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;</b>.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">R(config)# debug ppp authentication</font>&#160;// &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1076;&#1080;&#1072;&#1075;&#1085;&#1086;&#1089;&#1090;&#1080;&#1082;&#1091;, &#1077;&#1089;&#1083;&#1080; &#1095;&#1090;&#1086;-&#1083;&#1080;&#1073;&#1086; &#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1050;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1085;&#1077;&#1090;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; Point-to-Point &#1089;&#1088;&#1077;&#1076;&#1072;</b>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Frame relay" ID="ID_1261826038" CREATED="1519112080177" MODIFIED="1519112080177"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_1699877913">Frame relay</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1085;&#1077;&#1089;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074; &#1087;&#1086; L2 &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; Frame relay</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">R1,2(config)# interface s<b>9</b>/0</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;R1,2(config-if)# encapsulation frame-relay</font>&#160;// &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1085;&#1072; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091; &#1087;&#1086; L2 &#1087;&#1088;&#1086;&#1090;. frame relay
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;R1,2(config-if)# ip address 192.168.0.<b>1(2)</b>&#160; 255.255.255.0</font>&#160;// &#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1100; IP &#1072;&#1076;&#1088;&#1077;&#1089; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
    <p>
      
    </p>
    <p>
      -------------------
    </p>
    <p>
      <font color="#0000c0">(config-if)# frame-relay map ip 10.1.1.1 110 broadcast</font>&#160;// &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1077; ip &#1080; DLCI (&#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;). broadcast - &#1101;&#1084;&#1091;&#1083;&#1103;&#1094;&#1080;&#1103; broadcast (&#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1072; &#1073;&#1088;&#1086;&#1072;&#1076;&#1082;&#1072;&#1089;&#1090;&#1072; &#1102;&#1085;&#1080;&#1082;&#1072;&#1089;&#1090;&#1086;&#1084;)
    </p>
    <p>
      <font color="#0000c0">(config-if)# frame-relay lmi-type &lt;&gt;</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; LMI &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1099;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084; InARP</b>
    </p>
    <p>
      - &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102;
    </p>
    <p>
      <font color="#0000c0">(config-if)# no frame-relay inverse-arp</font>&#160;// &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; InARP
    </p>
    <p>
      <font color="#0000c0">(config-if)# shutdown </font>
    </p>
    <p>
      <font color="#0000c0">(config-if)# no shutdown</font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Multiport Frame relay" ID="ID_1733647412" CREATED="1519112080177" MODIFIED="1725607132117"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Конфигурация Multipoint Frame relay</b>&nbsp;&nbsp;(на примере <a href="#ID_890375223">hub-роутера</a>):
    </p>
    <p>
      
    </p>
    <p>
      <b>Multipoint</b>
    </p>
    <ul>
      <li>
        Присутствуют все <a href="#ID_1616422048">проблемы</a>, связанные с <a href="#ID_1699877913">NBMA</a>&nbsp;&nbsp;сетями
      </li>
      <li>
        экономия адресного пространства, т.к. используется единая подсеть
      </li>
      <li>
        удобно применять для <a href="#ID_890375223">partial-mesh</a>&nbsp;&nbsp;и <a href="#ID_890375223">full-mesh</a>&nbsp;топологий
      </li>
    </ul>
    <p>
      <font color="#0000c0">(config)# interface serial 0/0</font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# no ip address</font>&nbsp;// снять ip адрес (если ранее он был сконфигурирован)
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# encapsulation frame-relay</font>&nbsp;// настроить интерфейс на работу с протоколом L2 frame-relay
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# interface serial 0/0.1 multipoint</font>&nbsp;// создать виртуальный подинтерфейс и пометить его как multipoint
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-subif)# ip address 10.0.1.1 255.255.255.0</font>&nbsp;&nbsp;// задать ip адрес на виртуальный подинтерфейс
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-subif)# frame-relay map ip 10.0.1.2 100 broadcast</font>&nbsp;&nbsp;// задать соответствие ip адреса первого канального соседа и DLCI
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-subif)# frame-relay map ip 10.0.1.3 200 broadcast </font>// задать соответствие ip адреса второго канального соседа и DLCI
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        При конфигурировании Multipoint или Point-to-Point интерфейса, Inverse <b>ARP отключается</b>. Необходимо вручную прописывать сопоставления IP-адресов соседей по каналу и DLCI
      </li>
      <li>
        <b>На spoke роутерах</b>&nbsp;&nbsp;нет необходимости создавать виртуальный подинтерфейс и помечать его как multipoint.
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Point-to-Point Frame relay" ID="ID_714895037" CREATED="1519112080178" MODIFIED="1725607198386"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Конфигурация Point-to-Point Frame Relay</b>&nbsp;&nbsp;(на примере <a href="#ID_890375223">hub роутера</a>):
    </p>
    <p>
      
    </p>
    <p>
      <b>Point-to-Point</b>
    </p>
    <ul>
      <li>
        <b>Устраняет все <a href="#ID_1616422048">проблемы</a></b>, свойственные <a href="#ID_1699877913">NBMA</a>&nbsp;&nbsp;сетям
      </li>
      <li>
        Для каждого подинтерфейса необходимо выделять отдельную подсеть
      </li>
      <li>
        удобно применять для <a href="#ID_890375223">hub-and-spoke</a>&nbsp;&nbsp;топологий
      </li>
    </ul>
    <p>
      <font color="#0000c0">(config)# interface serial 0/0</font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# no ip address</font>&nbsp;// снять ip адрес (если ранее он был сконфигурирован)
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# encapsulation frame-relay</font>&nbsp;// настроить интерфейс на работу с протоколом L2 уровня frame-relay
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# interface serial 0/0.100 point-to-point</font>&nbsp;// создать виртуальный подинтерфейс&nbsp;и пометить его как point-to-point
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-subif)# ip address 10.0.1.1 255.255.255.0</font>&nbsp;&nbsp;// задать ip адрес на виртуальный подинтерфейс
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-subif)# frame-relay interface-dlci 100</font>&nbsp;// если внутри роутера будет сформирован кадр у которого в поле «назначение» будет указана DLCI 100, то такой кадр будет обрабатывать подинетрфейс serial 0/0.100
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# interface serial 0/0.110 point-to-point</font>&nbsp;// создать виртуальный подинтерфейс serial 0/0.110 и пометить его как point-to-point
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-subif)# ip address 10.0.2.1 255.255.255.0</font>&nbsp;&nbsp;// задать IP-адрес на виртуальный подинтерфейс
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-subif)# frame-relay interface-dlci 110</font>&nbsp;// если внутри роутера будет сформирован кадр у которого в поле «назначение» будет указана DLCI 110, то такой кадр будет обрабатывать подинетрфейс serial 0/0.110
    </p>
    <p>
      
    </p>
    <p>
      <font color="#ff0000"><b>!!! </b></font><b>На spoke роутерах</b>&nbsp;&nbsp;необходимо <b>создать подинтерфейс</b>&nbsp;&nbsp;и <b>пометить его как Point-to-Point</b>.
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="PBR" ID="ID_1496954781" CREATED="1519112080178" MODIFIED="1519112080178"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_80996055">Policy-based Routing (PBR)</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Policy-based Routing (PBR)</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list extended CTRL-ACL</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; ACL &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; CTRL-ACL
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-ext-nacl)# permit ip host 192.168.1.2 any</font>&#160; // &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; ip &#1072;&#1076;&#1088;&#1077;&#1089; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1076;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1076; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077; route-map
    </p>
    <p>
      <font color="#0000c0">(config)# route-map CONTROL-RM</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; CONTROL-RM
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-route-map)# match ip address CTRL -ACL</font>&#160;// route-map &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100;, &#1077;&#1089;&#1083;&#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; access-list CTRL-ACL
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-route-map)# set ip next-hop 10.0.2.1</font>&#160;// &#1077;&#1089;&#1083;&#1080; &#1089;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; route-map, &#1090;&#1086; next-hop &#1073;&#1091;&#1076;&#1077;&#1090; 10.0.2.1
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>&#160;// &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1089; &#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1099;&#1084;&#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;&#1084;&#1080;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip policy route-map CONTROL-RM</font>&#160;// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; route-map &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1044;&#1080;&#1072;&#1075;&#1085;&#1086;&#1089;&#1090;&#1080;&#1082;&#1072;:</b>
    </p>
    <p>
      <font color="#0000c0"># show route-map</font>&#160;// &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; route-map
    </p>
    <p>
      <font color="#0000c0"># show ip policy</font>&#160;// &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; route-map
    </p>
    <p>
      <font color="#0000c0"># debug ip policy</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1074;&#1099;&#1074;&#1086;&#1076; &#1086;&#1090;&#1083;&#1072;&#1076;&#1086;&#1095;&#1085;&#1086;&#1081; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;
    </p>
  </body>
</html></richcontent>
</node>
<node ID="ID_514555543" CREATED="1519112080178" MODIFIED="1519112080178"><richcontent TYPE="NODE">

<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#ff0000">Route-Map???</font>
    </p>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Route-map &#1101;&#1090;&#1086; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; &#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1084; &#1092;&#1072;&#1081;&#1083;&#1077;, &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1090;&#1072;&#1082;&#1086;&#1081; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;:
    </p>
    <ul>
      <li>
        NAT
      </li>
      <li>
        &#1055;&#1086;&#1083;&#1080;&#1090;&#1080;&#1082;&#1080; BGP
      </li>
      <li>
        &#1055;&#1077;&#1088;&#1077;&#1088;&#1072;&#1089;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; (route redistribution)
      </li>
      <li>
        <a href="#ID_80996055">PBR (Policy-based routing)</a>
      </li>
    </ul>
    <p>
      (config)# route-map 1
    </p>
    <p>
      &#160;&#160;&#160;(config-router-map)# set community // &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074; &#1087;&#1086;&#1083;&#1077; community.&#160;&#160;&#1055;&#1088;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; (&#1086;&#1088;&#1075;&#1072;&#1085;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;) &#1082; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1091; &#1095;&#1077;&#1088;&#1077;&#1079; BGP. &#1055;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088; (&#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1085;&#1077;&#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1099;&#1093; &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;) &#1076;&#1083;&#1103; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; &#1089;&#1074;&#1103;&#1079;&#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1087;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; community
    </p>
  </body>
</html></richcontent>
</node>
