<node TEXT="EIGRP" FOLDED="true" ID="ID_1769652059" CREATED="1519112080179" MODIFIED="1519112080179"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_1668704299">EIGRP</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; EIGRP</b>
    </p>
    <p>
      <font color="#0000c0">(config)# router eigrp 1</font>&#160;// &#160;&#1042;&#1093;&#1086;&#1076; &#1074; &#1082;&#1086;&#1085;&#1092;. &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072; (1 - &#1085;&#1086;&#1084;&#1077;&#1088; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;, &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1093;)
    </p>
    <p>
      <font color="#000000"><b>2. &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1089;&#1091;&#1084;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;</b></font>&#160; (&#1095;&#1072;&#1089;&#1090;&#1086; &#1088;&#1077;&#1096;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1091; &#1089; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1084;&#1080;). &#1056;&#1091;&#1095;&#1085;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1074;&#1086;&#1076; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072; EIGRP &#1085;&#1072; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091; &#1089; &#1073;&#1077;&#1089;&#1082;&#1083;&#1072;&#1089;&#1089;&#1086;&#1074;&#1099;&#1084;&#1080; &#1089;&#1077;&#1090;&#1103;&#1084;&#1080;. &#1054;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086; &#1074; &#1074;&#1077;&#1088;&#1089;&#1080;&#1103;&#1093; IOS &#1076;&#1086; 12.4
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# no auto-summary </font>//
    </p>
    <p>
      <b>3. &#1040;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#160;&#160;(&#1088;&#1072;&#1089;&#1089;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077;&#1084; &#1089;&#1086;&#1089;&#1077;&#1076;&#1103;&#1084;) &#1089;&#1077;&#1090;&#1080;</b>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# network 192.168.<b>1</b>.0 0.0.0.255</font>&#160;// &#1089;&#1077;&#1090;&#1100;,&#160;&#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1091;&#1102; &#1082; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1091; (IP / Wildcard)
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# network 192.168.0.0 0.0.255.255</font>&#160;// &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; &#1089;&#1077;&#1090;&#1077;&#1081;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# network 0.0.0.0 255.255.255.255</font>&#160;// &#1074;&#1089;&#1077; &#1089;&#1077;&#1090;&#1080;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# network 10.0.<b>1</b>.0 0.0.0.3</font>&#160;// &#1089;&#1077;&#1090;&#1080; &#1076;&#1086; &#1089;&#1086;&#1089;&#1077;&#1076;&#1085;&#1080;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074;
    </p>
    <p>
      <b>4. Passive interface</b>&#160;- &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1079;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; <b>&#1085;&#1077;&#1090; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074;</b>. &#1056;&#1086;&#1091;&#1090;&#1077;&#1088; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1077;&#1072;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; EIGRP-&#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1086;&#1090; &#1101;&#1090;&#1086;&#1075;&#1086; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# passive-interface f0/3 </font>// &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1087;&#1072;&#1089;&#1089;&#1080;&#1074;&#1085;&#1099;&#1084; &#1086;&#1076;&#1080;&#1085; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# passive-interface default</font>&#160;// <b>4.1</b>&#160;&#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1087;&#1072;&#1089;&#1089;&#1080;&#1074;&#1085;&#1099;&#1084;&#1080; &#1074;&#1089;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# no passive-interface f0/3 </font>// <b>4.2</b>&#160;&#1086;&#1090;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1087;&#1072;&#1089;&#1089;&#1080;&#1074;&#1085;&#1086;&#1089;&#1090;&#1100; &#1085;&#1072; &#1085;&#1091;&#1078;&#1085;&#1099;&#1093; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&#1093;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># show ip protocols</font>&#160;// &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074;
    </p>
    <p>
      <font color="#0000c0"># show ip eigrp neighbor</font>&#160;// &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1089;&#1086;&#1089;&#1077;&#1076;&#1077;&#1081;
    </p>
    <p>
      <font color="#0000c0"># show ip eigrp topology</font>&#160;// &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080;
    </p>
    <p>
