    </p>
    <p>
      <font color="#0000c0"># debug eigrp packets</font>&#160;// &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; (&#1076;&#1083;&#1103; &#1086;&#1090;&#1083;&#1072;&#1076;&#1082;&#1080;). &#1057;&#1080;&#1083;&#1100;&#1085;&#1086; &#1085;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; (&#1086;&#1085;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1074;&#1080;&#1089;&#1085;&#1091;&#1090;&#1100; - &#1090;&#1086;&#1075;&#1076;&#1072; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072;).&#160; <b>&#1054;&#1090;&#1082;&#1083;</b>. <font color="#0000c0"># undebug al</font>l
    </p>
  </body>
