<node TEXT="Метрика и балансировка трафика" ID="ID_876187673" CREATED="1519112080180" MODIFIED="1519112080180"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_1934213867">&#1040;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1103; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1080; EIGRP</a>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># show ip route</font>&#160;// &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; IP-&#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      <font color="#0000c0"># show ip eigrp topology</font>&#160;// &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080;, &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; Successor &#1080; Feasible Successor
    </p>
    <ul>
      <li>
        <b>Successor</b>&#160;- &#1085;&#1072;&#1080;&#1073;&#1086;&#1083;&#1077;&#1077; &#1074;&#1099;&#1075;&#1086;&#1076;&#1085;&#1099;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1074; &#1085;&#1072;&#1089;&#1090;&#1086;&#1103;&#1097;&#1077;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103;
      </li>
      <li>
        <b>Feasible Successor</b>&#160;- &#1079;&#1072;&#1087;&#1072;&#1089;&#1085;&#1086;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;, &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085; &#1087;&#1088;&#1080; &#1087;&#1086;&#1090;&#1077;&#1088;&#1077; &#1086;&#1089;&#1085;. &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;. &#1052;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086;.
      </li>
      <li>
        &lt;&#1052;&#1077;&#1090;&#1088;&#1080;&#1082;&#1072; &#1087;&#1086; &#1088;&#1072;&#1089;&#1095;&#1077;&#1090;&#1072;&#1084; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&gt; / &lt;&#1052;&#1077;&#1090;&#1088;&#1080;&#1082;&#1072; &#1087;&#1086; &#1088;&#1072;&#1089;&#1095;. &#1089;&#1086;&#1089;&#1077;&#1076;&#1085;&#1077;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&gt;
      </li>
      <li>
        <font color="#ff0000">&#1082;&#1072;&#1082; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; (&#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;) &#1074;&#1089;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;, &#1082;&#1088;&#1086;&#1084;&#1077; 2-&#1093; (Bandwidth, Delay) &#1087;&#1088;&#1080; &#1088;&#1072;&#1089;&#1095;&#1077;&#1090;&#1077; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1080;?</font>
      </li>
    </ul>
    <p>
      <font color="#0000c0"># show ip eigrp topology&#160;all-links</font>&#160;// &#1074;&#1089;&#1077; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1099;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        &#1041;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; - &#1076;&#1083;&#1103; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1086;&#1089;&#1090;&#1080;.
      </li>
      <li>
        &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1087;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1084; <b>&#1088;&#1072;&#1074;&#1085;&#1086;&#1081; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080;&#160;&#160;- &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1072;</b>
      </li>
      <li>
        &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1087;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1084; <b>&#1085;&#1077;&#1088;&#1072;&#1074;&#1085;&#1086;&#1081; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080;&#160;&#160;- &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1072;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;</b>&#160;&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; EIGRP (&#1074; OSPF - &#1085;&#1077;&#1083;&#1100;&#1079;&#1103;)
      </li>
      <li>
        &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1084;&#1086;&#1078;&#1085;&#1086; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1084;&#1077;&#1078;&#1076;&#1091; successor &#1080; feasible successors
      </li>
      <li>
        <b>&#1076;&#1086; 4 &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;</b>&#160;&#1076;&#1083;&#1103; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;)
      </li>
      <li>
        EIGRP &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; Bandwidth, Delay (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;)
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# router eigrp 1</font>&#160;// &#160;&#1074;&#1093;&#1086;&#1076; &#1074; &#1082;&#1086;&#1085;&#1092;. &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-router)# variance 3</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1080; &#1084;&#1077;&#1078;&#1076;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1084;&#1080; &#1089; &#1088;&#1072;&#1079;&#1085;&#1086;&#1081; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1086;&#1081;. 3 - &#1084;&#1085;&#1086;&#1078;&#1080;&#1090;&#1077;&#1083;&#1100; &#1074;&#1086; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1088;&#1072;&#1079; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; feasible successor &#1073;&#1091;&#1076;&#1077;&#1090; &#1093;&#1091;&#1078;&#1077; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086;. &#1045;&#1089;&#1083;&#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1085;&#1077; &#1093;&#1091;&#1078;&#1077; &#1095;&#1077;&#1084; &#1074; 3 &#1088;&#1072;&#1079;, &#1090;&#1086; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103;. &#1055;&#1088;&#1080; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1077; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;) - &#1095;&#1077;&#1090;&#1085;&#1099;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1080;&#1076;&#1091;&#1090; &#1087;&#1086; &#1086;&#1076;&#1085;&#1086;&#1081; &#1090;&#1088;&#1072;&#1089;&#1089;&#1077;, &#1085;&#1077;&#1095;&#1077;&#1090;&#1085;&#1099;&#1077; - &#1087;&#1086; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# variance 1 //</font>&#160;&#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1091;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# traffic-share balanced</font>&#160;// &#1095;&#1077;&#1084; &#1083;&#1091;&#1095;&#1096;&#1077; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1072;, &#1090;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# traffic-share min</font>&#160;// &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1087;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1084; &#1089; &#1085;&#1072;&#1080;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1081; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1086;&#1081;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# maximum-paths 6</font>&#160;// &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; (&#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1095;&#1080;&#1089;&#1083;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; <font color="#0000c0"># show ip protocols</font>) &#1089; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1086;&#1081; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1086;&#1081; &#1076;&#1083;&#1103; &#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080;. &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1073;&#1072;&#1083;. &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; <font color="#0000c0">(config-router)# maximum-paths <b>1</b></font>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Суммаризация маршрутов" ID="ID_577439884" CREATED="1519112080181" MODIFIED="1519112080181"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>R1</b>=========<b>R2&gt;</b>=======R3========R4
    </p>
    <p>
      LAN1&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;LAN2&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;LAN3&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;LAN4
    </p>
    <p>
      <b>192.168.1.0&#160;&#160;&#160;192.168.2.0</b>&#160;&#160;&#160;192.168.3.0&#160;&#160;&#160;192.168.4.0&#160;&#160;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">R2(conf-if)# ip summary-address eigrp 1 192.168<b>.0.0</b>&#160;255.255<b>.0.0</b></font>&#160;// &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1089;&#1091;&#1084;&#1084;&#1091;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#0000c0">R2(conf)# ip route 192.168<b>.0.0</b>&#160;255.255<b>.0.0</b></font>&#160;// &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1089;&#1091;&#1084;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        &#1076;&#1083;&#1103; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1080; &#1080; &#1086;&#1087;&#1090;&#1080;&#1084;&#1072;&#1079;&#1072;&#1094;&#1080;&#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1089;&#1077;&#1090;&#1080;
      </li>
      <li>
        &#1095;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;, &#1090;&#1077;&#1084; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103;
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="BGP" FOLDED="true" ID="ID_1360122851" CREATED="1519112080181" MODIFIED="1749647146092"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_479443184">BGP</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">show ip bgp summary</span>&#xa0;&#xa0;# соседи; <b>V</b>-версия протокола; <b>TblVer</b>&#xa0;- версия таблицы (меняется когда что-то происходит), <b>InQ OutQ</b>&#xa0;- сообщения в очереди на отправку/обработку
    </p>
    <p>
      <span style="color: #0000c0;">show ip bgp neighbors</span>&#xa0;&#xa0;# инфо о соседях
    </p>
    <p>
      <span style="color: #0000c0;">show ip bgp</span>&#xa0;&#xa0;# все маршруты, пришедшие по BGP. &quot;<b>&gt;</b>&quot; - обозначение лучшего маршрута; r - маршрут есть, но не вброшен в таблицу маршрутизации. Weight, LocPrf - вес маршрута,
    </p>
    <p>
      <span style="color: #0000c0;">show ip route bgp&#xa0;&#xa0;#</span>&#xa0;маршруты, полученные по BGP
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">clear ip bgp *</span>&#xa0;&#xa0;# hard reset для BGP процессов. Все маршруты в таблице маршрутизации будут удалены. Закачка маршрутом может занять 1 час и более.
    </p>
    <p>
      <span style="color: #0000c0;">clear ip bgp &lt;IP-адрес соседа&gt;</span>&#xa0;&#xa0;# очистить маршруты с соседом
    </p>
    <p>
      <b><span style="color: #0000c0;">route refresh</span></b>&#xa0;&#xa0;# таблица маршрутизации не очищается --&gt; накачиваемые маршруты складываются отдельно --&gt; потом таблицы синхронизируются
    </p>
    <p>
      <span style="color: #0000c0;">clear ip bgp &lt;IP-адрес соседа&gt; in/out</span>&#xa0;&#xa0;&#xa0;# заново загрузить/выгрузить от соседа(у) маршруты<span style="color: #0000c0;">&#xa0;</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="IBGP" ID="ID_1687499653" CREATED="1519112080181" MODIFIED="1519112080181"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>IBGP &#1089;&#1074;&#1103;&#1079;&#1100; (&#1101;&#1090;&#1086; &#1085;&#1077; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;) &#1084;&#1077;&#1078;&#1076;&#1091; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084;&#1080; &#1086;&#1076;&#1085;&#1086;&#1081; AS </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; loopback &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;</b>. <b>loopback</b>&#160;- &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;, &#1079;&#1072;&#1084;&#1082;&#1085;&#1091;&#1090;&#1099;&#1081; &#1085;&#1072; &#1089;&#1077;&#1073;&#1103;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1076;&#1080;&#1072;&#1075;&#1085;&#1086;&#1089;&#1090;&#1080;&#1082;&#1080;. loopback&#1080; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1103;&#1093; (lo0: 50.0.<b>1</b>.1, lo0: 50.0.<b>2</b>.1...)
    </p>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; loopback &#1074; &#1072;&#1085;&#1086;&#1085;&#1089; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072; &#1076;&#1080;&#1085;. &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; (&#1080;&#1083;&#1080; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;), &#1090;&#1086; <b>loopback &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1080;&#1085;&#1075;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1089; &#1076;&#1088;&#1091;&#1075;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072; </b>
    </p>
    <p>
      <font color="#0000c0">(config)# interface loopback 0</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; loopback &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip&#160;50.0.1.1 255.255.255.0</font>&#160;// &#1087;&#1088;&#1080;&#1089;&#1074;&#1086;&#1080;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089;
    </p>
    <p>
      <b>2. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;</b>&#160;- IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;, &#1087;&#1086;&#1076;&#1085;&#1103;&#1090;&#1080;&#1077;
    </p>
    <p>
      <b>3.1. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086; BGP. &#1040;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1091;&#1077;&#1084; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1076;&#1083;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1077;&#1081; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1074; &#1076;&#1088;&#1091;&#1075;&#1091;&#1102; AS</b>
    </p>
    <p>
      <font color="#0000c0">(config)# router bgp 66020</font>&#160;// 66020 - &#1085;&#1086;&#1084;&#1077;&#1088; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; (AS)
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# network 220.10.10.2&#160;mask 255.255.255.0</font>&#160;// &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; <b>connected &#1089;&#1077;&#1090;&#1100;</b>, &#1084;&#1072;&#1089;&#1082;&#1072;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# neighbor 50.0.<b>2</b>.1 remote-as 660020</font>&#160;// &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1089;&#1077;&#1076;&#1077;&#1081; &#1080;&#1079; AS (<b>loopback &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;</b>, # AS). &#1058;&#1077;&#1078;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1084;&#1077;&#1089;&#1090;&#1086; loopback &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;, &#1085;&#1086; &#1074;&#1088;&#1086;&#1076;&#1077; &#1090;&#1072;&#1082; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# neighbor 50.0.<b>2</b>.1 update-source <b>loopback 0</b></font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; <b>loopback</b>&#160;&#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; (&#1091;&#1082;&#1072;&#1079;. loopback &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;)
    </p>
    <p>
      <b>3.2. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086; OSPF</b>
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1 </font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# network 10.0.1.0&#160;0.0.0.255 area 0</font>&#160;// &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1077;&#1090;&#1100; &#1084;&#1077;&#1078;&#1076;&#1091; &#1089;&#1086;&#1089;&#1077;&#1076;&#1103;&#1084;&#1080;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# network 50.0.<b>1</b>.0&#160;0.0.0.255 area 0</font>&#160;// &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1074;&#1086;&#1102; &#1089;&#1077;&#1090;&#1100; loopback
    </p>
    <p>
      <b>4. &#1055;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; AS &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1099; IGP &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1083;&#1091;&#1095;&#1096;&#1077; &#1095;&#1077;&#1084; EGP, &#1090;&#1086; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1087;&#1088;&#1086; &#1089;&#1077;&#1090;&#1080; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1088;&#1072;&#1089;&#1089;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083; OSPF. &#1059; OSPF &#1072;&#1076;&#1084;. &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1083;&#1091;&#1095;&#1096;&#1077;.</b>
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1 </font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# network 220.10.10.2&#160;0.0.0.255 area 0</font>&#160;// &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; connected &#1089;&#1077;&#1090;&#1100;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="EBGP" FOLDED="true" ID="ID_485130576" CREATED="1519112080182" MODIFIED="1545299451622"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>EBGP &#1089;&#1074;&#1103;&#1079;&#1100; (&#1101;&#1090;&#1086; &#1085;&#1077; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;) &#1084;&#1077;&#1078;&#1076;&#1091; AS</b>
    </p>
    <ul>
      <li>
        AS &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1077;
      </li>
    </ul>
    <p>
      <b>1. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1099;</b>&#160;- IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;, &#1087;&#1086;&#1076;&#1085;&#1103;&#1090;&#1080;&#1077;
    </p>
    <p>
      <b>2. &#1057;&#1086;&#1077;&#1076;&#1080;&#1085;&#1080;&#1090;&#1100; &#1076;&#1074;&#1077; AS. &#1045;&#1089;&#1083;&#1080; &#1074;&#1089;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086; - &#1089;&#1086;&#1089;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1086;</b>
    </p>
    <p>
      <font color="#0000c0">R1_AS1(config)# router bgp <b>65020</b></font>&#160;// 66020 - &#1085;&#1086;&#1084;&#1077;&#1088; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; (<b>AS1</b>)
    </p>
    <p>
      &#160;<font color="#0000c0">&#160;&#160;&#160;R1_AS2(config-router)# neighbor 172.10.10.2&#160;remote-as <b>650010</b></font>&#160;// &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072; &#1080;&#1079; <b>AS2</b>
    </p>
    <p>
      <font color="#0000c0">R1_AS2(config)# router bgp <b>65010</b></font>&#160;// 66010 - &#1085;&#1086;&#1084;&#1077;&#1088; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; (<b>AS1</b>)
    </p>
    <p>
      &#160;<font color="#0000c0">&#160;&#160;&#160;R1_AS2(config-router)# neighbor 172.10.10.1&#160;remote-as <b>650020</b></font>&#160;// &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072; &#1080;&#1079; <b>AS2</b>
    </p>
    <p>
      <b>3. &#1076;&#1083;&#1103; &#1074;&#1073;&#1088;&#1086;&#1089;&#1072; &#1074; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; AS</b>&#160;&#1085;&#1091;&#1078;&#1085;&#1086; &#1083;&#1080;&#1073;&#1086; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; OSPF, &#1083;&#1080;&#1073;&#1086; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;
    </p>
    <p>
      <font color="#0000c0">R2_AS1(config)# ip route 172.10.10.0 255.255.255.0 10.0.1.2</font>&#160;// &#1089;&#1090;&#1072;&#1090;. &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1076;&#1086; &#1089;&#1077;&#1090;&#1080; AS1--AS2
    </p>
    <p>
      <font color="#0000c0">R1_AS2(config)# router ospf 1 </font>// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1089;&#1077;&#1090;&#1100; AS1--AS2 &#1074; &#1072;&#1085;&#1086;&#1085;&#1089;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">R1_AS2(config-router)# network 172.10.10.0 0.0.0.255 area 0 </font>
    </p>
    <p>
      <b>4. &#1063;&#1090;&#1086;&#1073;&#1099; R1 &#1088;&#1072;&#1089;&#1089;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1083; &#1086;&#1090; &#1089;&#1074;&#1086;&#1077;&#1075;&#1086; &#1080;&#1084;&#1077;&#1085;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; (&#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1080;&#1079; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; AS), &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084; &#1089;&#1074;&#1086;&#1077;&#1081; AS</b>
    </p>
    <p>
      <font color="#0000c0">R1_AS2(config)# router bgp <b>65010 </b></font>
    </p>
    <p>
      &#160;<font color="#0000c0">&#160;&#160;&#160;R1_AS2(config-router)# neighbor 50.0.4.1&#160;next-hop-self </font>// 50.0.4.1 - loopback R4 AS2
    </p>
  </body>
</html></richcontent>
<node TEXT="AS1---R0---AS2" ID="ID_1575578867" CREATED="1519112080182" MODIFIED="1519112080182"><richcontent TYPE="NOTE">
