<node TEXT="Управление трафиком (Route-Map)" ID="ID_27183252" CREATED="1519112080182" MODIFIED="1519112080182"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1086;&#1084; (Route-Map)</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074;&#1077;&#1089; &#1076;&#1083;&#1103; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; &#1086;&#1090; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;:</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip prefix-list WEIGHT permit 55.30.30.0/24</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; prefix-list, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1083;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1076;&#1086; &#1089;&#1077;&#1090;&#1080; 55.30.30.0 &#1087;&#1086; &#1084;&#1072;&#1089;&#1082;&#1077; 255.255.255.0
    </p>
    <p>
      <font color="#0000c0">(config)# route-map MAP1 permit 10</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; MAP1, &#1074;&#1077;&#1090;&#1082;&#1072; 10
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# match ip address prefix-list WEIGHT</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; prefix-list &#1082; route-map
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# set weight 150</font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074;&#1077;&#1089; &#1085;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1076;&#1086; &#1089;&#1077;&#1090;&#1080; 55.30.30.0/24 = 150
    </p>
    <p>
      <font color="#0000c0">(config)# route-map MAP1 permit 20</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1077;&#1097;&#1077; &#1074;&#1077;&#1090;&#1082;&#1091; 20 route-map
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# set weight 0</font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074;&#1077;&#1089; &#1085;&#1072; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; = 0
    </p>
    <p>
      <font color="#0000c0">(config)# router bgp 62010</font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# neighbor 50.0.1.1 route-map MAP1 in</font>&#160; // &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; route-map &#1082; IBGP &#1089;&#1086;&#1089;&#1077;&#1076;&#1091;
    </p>
    <p>
      <font color="#0000c0">(config)# clear ip bgp *</font>&#160;// &#1086;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Управление трафиком (Local preference)" ID="ID_1871202908" CREATED="1519112080182" MODIFIED="1519112080182"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_646672065">&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099; &#1087;&#1091;&#1090;&#1080;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;:</b>&#160;&#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100;&#160;&#1090;&#1072;&#1082;, &#1095;&#1090;&#1086; &#1074;&#1089;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1086;&#1090; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072; 172.10.10.1 &#1073;&#1091;&#1076;&#1091;&#1090; &#1080;&#1084;&#1077;&#1090;&#1100; local-preference &#1074; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1080; 150, &#1090;.&#1077;. &#1086;&#1085;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1073;&#1086;&#1083;&#1077;&#1077; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1085;&#1099; &#1087;&#1086; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1102; &#1082; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1084; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1084;, &#1091; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 100
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# route-map FILTER permit 10</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; route-map
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# set local-preference 150</font>&#160;// &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1084;&#1072;&#1088;&#1096;&#1088;. &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1084; &#1086;&#1090; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;
    </p>
    <p>
      <font color="#0000c0">(config)# router bgp 62010</font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# neighbor 172.10.10.1&#160;route-map FILTER in</font>&#160;// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; route-map &#1082; &#1089;&#1086;&#1089;&#1077;&#1076;&#1091;
    </p>
    <p>
      <font color="#0000c0">(config)# clear ip bgp *</font>&#160;// &#1086;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Управление трафиком (AS Path)" ID="ID_10559787" CREATED="1519112080182" MODIFIED="1519112080182"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_646672065">&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099; &#1087;&#1091;&#1090;&#1080;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; (&#1091;&#1093;&#1091;&#1076;&#1096;&#1077;&#1085;&#1080;&#1077; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;)</b>. &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1089;&#1086;&#1089;&#1077;&#1076; 217.145.14.2 &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090; &#1087;&#1091;&#1090;&#1100; &#1076;&#1086; &#1085;&#1072;&#1096;&#1077;&#1081; AS &#1088;&#1072;&#1074;&#1085;&#1099;&#1081; 64100 64100 64100 64100 &#1080; &#1088;&#1072;&#1089;&#1089;&#1082;&#1072;&#1078;&#1077;&#1090; &#1086;&#1073; &#1101;&#1090;&#1086;&#1084; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;, &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1074; &#1077;&#1097;&#1077; &#1080; &#1089;&#1074;&#1086;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088; AS. &#1042; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1077; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;-&#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1087;&#1086;&#1081;&#1076;&#1077;&#1090; &#1095;&#1077;&#1088;&#1077;&#1079; &#1076;&#1088;&#1091;&#1075;&#1086;&#1075;&#1086; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;, &#1076;&#1083;&#1103; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1084;&#1099; &#1085;&#1077; &#1091;&#1093;&#1091;&#1076;&#1096;&#1072;&#1083;&#1080; as-path.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# route-map SET-ASPATH permit 10</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map SET-ASPATH Router
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-route-map)# set as-path prepend 64100 64100 ... </font>// &#1091;&#1093;&#1091;&#1076;&#1096;&#1072;&#1077;&#1084; &#1087;&#1091;&#1090;&#1100; &#1076;&#1086; &#1085;&#1072;&#1096;&#1077;&#1081; AS, &#1091;&#1093;&#1091;&#1076;&#1096;&#1072;&#1090;&#1100; &#1084;&#1086;&#1078;&#1077;&#1084; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1084; &#1089;&#1074;&#1086;&#1077;&#1081; AS
    </p>
    <p>
      <font color="#0000c0">(config)# router bgp 64100</font>&#160;//&#160;&#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1080;&#1084; &#1074; &#1101;&#1082;&#1079;&#1077;&#1084;&#1087;&#1083;&#1103;&#1088; bgp &#1089; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1084; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; 64100
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# neighbor 217.145.14.2 route-map SET-ASPATH out</font>&#160; // &#1087;&#1086;&#1074;&#1077;&#1089;&#1080;&#1090;&#1100; &#1085;&#1072;&#1096; route-map &#1085;&#1072; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;
    </p>
    <p>
      <font color="#0000c0">(config)# clear ip bgp *</font>&#160;// &#1086;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Управление трафиком (MED, route-map)" ID="ID_991729095" CREATED="1519112080183" MODIFIED="1519112080183"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1089;&#1084;. <a href="#ID_646672065">&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1099; &#1087;&#1091;&#1090;&#1080;</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1040;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; MED (Multi Exit Discriminator)</b>:
    </p>
    <p>
      <font color="#0000c0">(config)# route-map SET-MED permit 10</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map SET-MED
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# set metric 200</font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; MED &#1088;&#1072;&#1074;&#1085;&#1086;&#1077; 200
    </p>
    <p>
      <font color="#0000c0">(config)# router bgp 64100</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080; &#1074; &#1101;&#1082;&#1079;&#1077;&#1084;&#1087;&#1083;&#1103;&#1088; bgp &#1089; &#1085;&#1086;&#1084;&#1077;&#1088;&#1086;&#1084; AS 64100
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# neighbor 217.145.14.2 route-map SET-MED out</font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; route-map &#1085;&#1072; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Фильтрация маршрутов" FOLDED="true" ID="ID_918872453" CREATED="1519112080183" MODIFIED="1758556919036"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        для запрета пропуска транзитного трафика через нашу AS
      </li>
      <li>
        нельзя устанавливать соседство с другой AS без фильтрации маршрутов
      </li>
      <li>
        при организации провайдеронезависимых IP-адресов
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>Очередность обработки фильтров при ПРИЕМЕ пакета от роутера другой AS. </b>Обработка при отправке пакета - в обратном порядке
    </p>
    <ol>
      <li>
        Prefix-list. Выполняется первичная фильтраци. Развертываение пакета
      </li>
      <li>
        Filter-list. as-path access-list. Работа с регулярными выражениями
      </li>
      <li>
        Route-map. Несколько веток, несколько условий. Напоминает язык программирования
      </li>
    </ol>
  </body>
</html></richcontent>
<node TEXT="prefix-list" ID="ID_1623751430" CREATED="1519112080183" MODIFIED="1519112080183"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; prefix-list </b>
    </p>
    <p>
      &#1089;&#1084;. <a href="#ID_1409186499">&#1057;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1077; &#1095;&#1080;&#1089;&#1077;&#1083;</a>
    </p>
    <ul>
      <li>
        &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084; &#1082;&#1086;&#1075;&#1076;&#1072; &#1090;&#1086;&#1095;&#1085;&#1086; &#1079;&#1085;&#1072;&#1077;&#1084;, &#1082;&#1072;&#1082;&#1080;&#1077; &#1089;&#1077;&#1090;&#1080; &#1093;&#1086;&#1090;&#1080;&#1084; &#1087;&#1088;&#1086;&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;. &#1047;&#1072;&#1097;&#1080;&#1090;&#1080;&#1090;&#1100;&#1089;&#1103; &#1086;&#1090; &#1095;&#1091;&#1078;&#1080;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081; &#1080;&#1083;&#1080; &#1085;&#1077; &#1086;&#1090;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1089;&#1074;&#1086;&#1080;
      </li>
      <li>
        &#1076;&#1083;&#1103; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1080; &#1087;&#1086; &#1084;&#1077;&#1089;&#1090;&#1091; &#1079;&#1072;&#1088;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1089;&#1077;&#1090;&#1080; (&#1074; &#1082;&#1072;&#1082;&#1086;&#1081; AS) &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; <a href="#ID_1282836540">AS-Path Access-List</a>
      </li>
    </ul>
    <p>
      <font color="#0000c0">(config)# ip prefix-list 1 permit 215.20.22.0/24</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1077;&#1090;&#1100;&#160;
    </p>
    <p>
      <b>&#1080;&#1083;&#1080; </b><font color="#0000c0">(config)# ip prefix-list 1 permit 0.0.0.0/0 ge 8 le 24</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100;&#160;&#160;&#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1089;&#1086;&#1089;&#1077;&#1076;&#1091; (&#1083;&#1080;&#1073;&#1086; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1090;&#1100; &#1086;&#1090; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;) &#1074;&#1089;&#1077; &#1089;&#1077;&#1090;&#1080;, &#1084;&#1072;&#1089;&#1082;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1080;&#1083;&#1080; &#1088;&#1072;&#1074;&#1085;&#1072; 8, &#1085;&#1086; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; &#1080;&#1083;&#1080; &#1088;&#1072;&#1074;&#1085;&#1072; 24
    </p>
    <p>
      <font color="#0000c0">(config)# router bgp 65010</font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# neighbor 217.145.14.2 prefix-list 1 out</font>&#160; // &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; prefix-list &#1082; &#1089;&#1086;&#1089;&#1077;&#1076;&#1091;
    </p>
    <p>
      <font color="#0000c0"># clear ip bgp * out</font>&#160;// &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1085;&#1086;&#1074;&#1099;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1085;&#1072; &#1089;&#1086;&#1089;&#1077;&#1076;&#1077;&#1081;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="AS-Path Access-List" ID="ID_1282836540" CREATED="1519112080183" MODIFIED="1519112080183"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; AS-Path Access-Lists </b>
    </p>
    <p>
      &#1089;&#1084;. <a href="#ID_1143117695">RegEx </a>
    </p>
    <ul>
      <li>
        &#1084;&#1086;&#1075;&#1091;&#1090; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1079;&#1072;&#1088;&#1086;&#1076;&#1080;&#1074;&#1096;&#1080;&#1077;&#1089;&#1103; &#1074; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; AS (&#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1093;)
      </li>
    </ul>
    <p>
      <font color="#0000c0">(config)# ip as-path <b>access-list 1</b>&#160;permit ^$</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; as-path access-list, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1090;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1079;&#1072;&#1088;&#1086;&#1076;&#1080;&#1083;&#1080;&#1089;&#1100; &#1074; &#1085;&#1072;&#1096;&#1077;&#1081; AS. &#1056;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1086;&#1077; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; <b>^$ (^</b>&#160;- &#1085;&#1072;&#1095;&#1072;&#1083;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;, <b>$</b>&#160; - &#1082;&#1086;&#1085;&#1077;&#1094; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;. &#1052;&#1077;&#1078;&#1076;&#1091; &#1101;&#1090;&#1080;&#1084;&#1080; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072;&#1084;&#1080; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090; &#1087;&#1091;&#1089;&#1090;&#1086;&#1081; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090; AS PATH).
    </p>
    <p>
      &#1080;&#1083;&#1080; &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#160; <font color="#0000c0">(config)# ip as-path <b>access-list 1</b>&#160;permit _65030$</font>&#160;// AS-Path Access-Lists &#1086;&#1090;&#1083;&#1086;&#1074;&#1080;&#1090; &#1074;&#1089;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1079;&#1072;&#1088;&#1086;&#1076;&#1080;&#1083;&#1080;&#1089;&#1100; &#1074; AS 65030 &#1080; &#1085;&#1077; &#1074;&#1072;&#1078;&#1085;&#1086;, &#1095;&#1077;&#1088;&#1077;&#1079; &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090;&#1085;&#1099;&#1093; AS &#1087;&#1088;&#1086;&#1096;&#1077;&#1083; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;, &#1087;&#1088;&#1077;&#1078;&#1076;&#1077; &#1095;&#1077;&#1084; &#1087;&#1088;&#1080;&#1096;&#1077;&#1083; &#1074; &#1085;&#1072;&#1096;&#1091; AS (&#1086;&#1090;&#1083;&#1086;&#1074;&#1080;&#1090; &#1074;&#1089;&#1077; as-path, &#1091; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1103;&#1103; AS &#1073;&#1091;&#1076;&#1077;&#1090; 65030).
    </p>
    <p>
      <font color="#0000c0">(config)# router bgp 65010</font>
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-router)# neighbor 217.145.14.2 <b>filter-list 1</b>&#160;out</font>&#160;// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; As-Path Access-List &#1082; &#1089;&#1086;&#1089;&#1077;&#1076;&#1091;
    </p>
    <p>
      <font color="#0000c0"># clear ip bgp * out</font>&#160;// &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1085;&#1086;&#1074;&#1099;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1085;&#1072; &#1089;&#1086;&#1089;&#1077;&#1076;&#1077;&#1081;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="route-map" ID="ID_764601050" CREATED="1519112080183" MODIFIED="1519112080183"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; Route-Map</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# ip as-path access-list 1 permit ^65020$</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; as-path access-list, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1080;&#1079; AS 65020
    </p>
    <p>
      <font color="#0000c0">(config)# ip prefix-list default-only permit 0.0.0.0/0</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; prefix-list, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; default &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;
    </p>
    <p>
      <font color="#0000c0"><b>(config)# route-map FILTERING permit 10</b></font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; FILTERING &#1080; &#1074;&#1077;&#1090;&#1082;&#1086;&#1081; 10
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# match ip address prefix-list default-only</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; prefix-list &#1082; route-map
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# match as-path 10</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; as-path access-list &#1082; route-map
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# set local-preference 150</font>&#160;// &#1077;&#1089;&#1083;&#1080; route-map &#1089;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;, &#1085;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; 0.0.0.0/0 &#1073;&#1091;&#1076;&#1077;&#1090; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085; local-preference &#1074; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; 150
    </p>
    <p>
      <font color="#0000c0"><b>(config)# route-map FILTERING permit 20</b></font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; FILTERING &#1080; &#1074;&#1077;&#1090;&#1082;&#1086;&#1081; 20
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# match ip address prefix-list default-only</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; prefix-list, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1077;&#1092;&#1086;&#1083;&#1090;&#1085;&#1086;&#1075;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;. &#1047;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; local-preference &#1086;&#1089;&#1090;&#1072;&#1085;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1074;&#1085;&#1086; 100
    </p>
    <p>
      <font color="#0000c0">(config)# router bgp 65010</font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# neighbor <b>172.10.10.1</b>&#160;route-map FILTERING in</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; route-map &#1082; &#1088;&#1072;&#1079;&#1085;&#1099;&#1084; &#1089;&#1086;&#1089;&#1077;&#1076;&#1103;&#1084;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="#Рекомендации" ID="ID_1215913317" CREATED="1519112080184" MODIFIED="1519112080184"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <b>&#1054;&#1087;&#1090;&#1080;&#1084;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;. </b>&#1057; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; prefix-list&#1086;&#1074; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1090;&#1082;&#1080;&#1076;&#1099;&#1074;&#1072;&#1090;&#1100; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1077; (&#1085;&#1086; &#1085;&#1077;&#1085;&#1091;&#1078;&#1085;&#1099;&#1077; &#1089;&#1077;&#1090;&#1080;). &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1072;&#1085;&#1086;&#1085;&#1089; &#1085;&#1072;&#1096;&#1080;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081;
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Peer Group" ID="ID_676201825" CREATED="1519112080184" MODIFIED="1519112080184"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; Peer Group</b>
    </p>
    <ul>
      <li>
        &#1086;&#1076;&#1085;&#1072; &#1080; &#1090;&#1072; &#1078;&#1077; peer-&#1075;&#1088;&#1091;&#1087;&#1087;&#1072; &#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1072; &#1076;&#1083;&#1103; IBGP-&#1089;&#1086;&#1089;&#1077;&#1076;&#1072; &#1080; EBGP-&#1089;&#1086;&#1089;&#1077;&#1076;&#1072;
      </li>
    </ul>
    <p>
      <font color="#0000c0">(config)# router bgp 65010</font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# neighbor ISP peer-group</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1080;&#1088;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1091; &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; ISP
    </p>
    <p>
      &#160; <font color="#0000c0">&#160;(config-router)# neighbor ISP filter-list 1 out</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1082; &#1087;&#1080;&#1088;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1077; filter-list 1
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# neighbor ISP prefix-list 25 in</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1082; &#1087;&#1080;&#1088;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1077; as-path access-lists 1
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# neighbor ISP route-map FILTER out</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1082; &#1087;&#1080;&#1088;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1077; route-map &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; FILTER
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# neighbor 172.10.10.1 remote-as 65020</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# neighbor 172.10.10.1 peer-group ISP</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1087;&#1080;&#1088;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1091; ISP &#1082; &#1087;&#1077;&#1088;&#1074;&#1086;&#1084;&#1091; &#1089;&#1086;&#1089;&#1077;&#1076;&#1091;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# neighbor 134.15.15.1 remote-as 65030</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1089;&#1086;&#1089;&#1077;&#1076;&#1072;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# neighbor 134.15.15.1 peer-group ISP</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1078;&#1077; &#1089;&#1072;&#1084;&#1091;&#1102; &#1087;&#1080;&#1088;-&#1075;&#1088;&#1091;&#1087;&#1087;&#1091; ISP &#1082;&#1086; &#1074;&#1090;&#1086;&#1088;&#1086;&#1084;&#1091; &#1089;&#1086;&#1089;&#1077;&#1076;&#1091;
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="OSPF" FOLDED="true" ID="ID_531198500" CREATED="1519112080184" MODIFIED="1725723043384"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_450841264">OSPF</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>I. Создать зону 0</b>
    </p>
    <p>
      <b>1. Включить протокол динамической маршрутизации OSPF</b>
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1</font>&nbsp;// настроить ospf экземпляр 1 (может не совпадать на разных роутерах)
    </p>
    <p>
      <font color="#0000c0">2. (config-router)# router-id 1.1.1.1</font>&nbsp;// назначить ID роутеру (можно всем, для удобства воспр.)
    </p>
    <p>
      <b>3. Анонсировать подключенные сети</b>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-router)# network 192.168.1.0 0.0.0.255 area 0</font>&nbsp;// анонсировать сети в зоне 0. Должно появиться сообщение о загрузке от других роутеров
    </p>
    <p>
      <b>II. Пограничный роутер (ABR)</b>
    </p>
    <p>
      1. пограничный роутер соединить с зонами 0,1,2...
    </p>
    <p>
      2. интерфейсам присвоить адреса согласно разным канальным средам зон&nbsp;
    </p>
    <p>
      3. роутер ID, анонсировать сети, смотрящие в зоны 0,1,2
    </p>
    <p>
      4. Пограничный роутер должен быть выбран DR-роутером (главным роутером)
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0</font>&nbsp;//
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;&nbsp;(config-if)# ip ospf priority 100</font>&nbsp;// изменить приоритет для OSPF на интерфейсе (влияет на выбор DR/BDR)
    </p>
    <p>
      <font color="#0000c0">5. # clear ip ospf process</font>&nbsp;// сбросить маршрутную информацию на всех роутерах
    </p>
    <p>
      6. <font color="#0000c0"># show ip ospf neighbor</font>&nbsp;// проверить кто DR/BDR
    </p>
    <p>
      <b>III. Создать зону 1,2...</b>
    </p>
    <p>
      1. присвоить IP-адреса
    </p>
    <p>
      2. <font color="#0000c0">(config-router)# network 0.0.0.0 255.255.255.255 area <b>1</b></font>&nbsp;// анонсировать все сети
    </p>
    <p>
      
    </p>
    <p>
      <b>Должны быть одинаковыми у роутеров одной канальной среды</b>
    </p>
    <p>
      <font color="#0000c0">(config-if)# ip ospf hello-interval 8</font>&nbsp;// посылать hello-пакеты каждые 8 секунд
    </p>
    <p>
      <font color="#0000c0">(config-if)# ip ospf dead-interval 30</font>&nbsp;// признавать соседа недоступным, если от него не получен hello-пакет через 30 секунд
    </p>
    <p>
      <font color="#0000c0">(config-if)# ip mtu 1400</font>&nbsp;// изменить размер MTU
    </p>
    <p>
      <font color="#0000c0">(config-)# auto-cost reference-bandwith 10000</font>&nbsp;// изменить полосу пропуская (в мегабитах)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config-router)# passive-interface f9/0</font>&nbsp;// не посылать hello-пакеты по интерфейсу f9/0 ( для интерфейсов, смотрящих на пользователей, за которыми нет роутеров)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config-if)# ip ospf cost 10</font>&nbsp;// изменть стоимость интерфейса. см. <a href="#ID_972815075">вычисл. метрики</a>
    </p>
    <p>
      <font color="#0000c0">(config-router)# bandwidth 10000</font>&nbsp;// установить расчетную скорость интерфейса в 10000 килобит. Для адекватной оценки маршрута (по фактической скорости а не по скорости интерфейса)
    </p>
  </body>
</html></richcontent>
