<node TEXT="Фильтрация маршрутов" ID="ID_477596972" CREATED="1519112080186" MODIFIED="1519112080186"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;</b>&#160; - &#1079;&#1072;&#1087;&#1088;&#1077;&#1090; &#1072;&#1085;&#1086;&#1085;&#1089;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;
    </p>
    <p>
      
    </p>
    <p>
      <b>1 &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;. &#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1085;&#1072; BR-&#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1077;. Prefix-&#1083;&#1080;&#1089;&#1090;&#1099;. &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1090;&#1077; &#1089;&#1077;&#1090;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1080;&#1079; &#1079;&#1086;&#1085;&#1099; 0 &#1074; &#1079;&#1086;&#1085;&#1091; 1.</b>&#160;&#160;&#1042;&#1089;&#1077; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1073;&#1091;&#1076;&#1091;&#1090; &#1079;&#1072;&#1087;&#1088;&#1077;&#1097;&#1077;&#1085;&#1099;. &#1053;&#1086; &#1085;&#1077; default &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; <b>0.0.0.0</b>&#160;- &#1086;&#1085; &#1074;&#1089;&#1077; &#1088;&#1072;&#1074;&#1085;&#1086; &#1087;&#1086;&#1087;&#1072;&#1076;&#1077;&#1090; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;. &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1091; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1091;
    </p>
    <p>
      <font color="#0000c0">(config)# ip prefix-list OSPF permit 192.168.0.0/16&#160;<a href="#ID_1409186499"><b>le</b></a><b>&#160; 20</b></font>&#160;&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; prefix-list &#1080; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1100; (&#1084;&#1072;&#1089;&#1082;&#1072; <b>&#1084;&#1077;&#1085;&#1100;&#1096;&#1077; 20</b>). &#1058;.&#1077;. &#1084;&#1086;&#1078;&#1085;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1089; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1072;&#1084;&#1080;.
    </p>
    <p>
      <font color="#0000c0">(config)# route ospf 1 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# area 0 filter-list prefix &lt;prefix-name&gt; &lt;in | out&gt;</font>&#160;// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1101;&#1090;&#1086;&#1090; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088; &#1085;&#1072; ABR &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;. <b>in</b>&#160; &#8212; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1089;&#1077;&#1090;&#1077;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1091;&#1102; &#1079;&#1086;&#1085;&#1091;. <b>out</b>&#160; &#8212; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1089;&#1077;&#1090;&#1077;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1080;&#1079; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1081; &#1079;&#1086;&#1085;&#1099;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# distance ospf external 255</font>&#160;// &#1091;&#1093;&#1091;&#1076;&#1096;&#1080;&#1090;&#1100; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1091; &#1076;&#1083;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; ospf &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;. &#1042; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072; &#1086;&#1089;&#1090;&#1072;&#1085;&#1077;&#1090;&#1089;&#1103; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; default &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;, &#1072; &#1087;&#1088;&#1080;&#1096;&#1077;&#1076;&#1096;&#1080;&#1081; default &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1075;&#1085;&#1086;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;
    </p>
    <p>
      
    </p>
    <p>
      <b>2 &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;. <a href="#ID_1586644377">ACL</a>. &#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1072;&#1074;&#1090;&#1086;&#1085;&#1086;&#1084;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; &#1085;&#1072; &#1083;&#1102;&#1073;&#1086;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1077; &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1079;&#1086;&#1085;&#1099;. &#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1074;&#1073;&#1088;&#1086;&#1089; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084; &#1074; &#1089;&#1074;&#1086;&#1102; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;</b>. &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1091; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;
    </p>
    <p>
      <font color="#0000c0">(config)# access-list 4 permit 192.168.0.0 0.0.255.255</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; ACL &#1080; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# distribute-list 4 in</font>&#160;// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; ACL &#1082; OSPF
    </p>
    <p>
      
    </p>
    <p>
      <b>3 &#1089;&#1087;&#1086;&#1089;&#1086;&#1073;. &#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; &#1087;&#1088;&#1080; &#1088;&#1077;&#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1094;&#1080;&#1080;. &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1085;&#1072; ASBR-&#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1077; (&#1089;&#1084;. <a href="#ID_1359857024">&#1056;&#1077;&#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1094;&#1080;&#1103;</a>). &#1050;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1099; &#1073;&#1091;&#1076;&#1091;&#1090; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1074; OSPF, &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; - &#1085;&#1077;&#1090;. </b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip prefix-list PREFLIST1 deny 172.10.2.0/16</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; prefix-list &#1080; &#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1100;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; OSPF
    </p>
    <p>
      <font color="#0000c0">(config)# ip prefix-list PREFLIST1 permit any</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077;
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1</font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# redistrubute eigrp 1 subnets</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1088;&#1077;&#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1094;&#1080;&#1102; &#1080;&#1079; eigrp &#1074; ospf
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# destribute-list prefix PREFLIST1 out eigrp 1</font>&#160;// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; prefix-list &#1085;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1074;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1077;&#1084;&#1099;&#1077; &#1080;&#1079; EIGRP &#1074; OSPF
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="case 1.1 (3 роутера) OSPF" ID="ID_985656826" CREATED="1519112080186" MODIFIED="1519112080186"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><font face="SansSerif">WS1--R1-----------------R2--WS2</font></b>
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#9550;<font face="SansSerif">&#160;&#160;&#160;&#160;<b>&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;</b></font>&#9550;<font face="SansSerif">&#160; </font>
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#9584;<b><font face="SansSerif">-------R3------</font></b>&#9583;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#9550;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; <b>WS3</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; R1</b>
    </p>
    <p>
      <font color="#0000c0">(config)# interface g0/2</font>&#160;// <b>&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; WS1, &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084; R2,R3 (&#1084;&#1072;&#1089;&#1082;&#1072; /30)</b>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# ip address 192.168.1.1 255.255.255.0</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-if)# no shutdown </font>
    </p>
    <p>
      <font color="#0000c0" face="SansSerif">(config)# interface loopback 0</font><font face="SansSerif">&#160;// <b>OSPF</b>. &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1085;</font>&#1072; <b>loopback &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077;</b>
    </p>
    <p>
      <font color="#0000c0" face="SansSerif">&#160;&#160;&#160;(config-if)# ip address 192.168.100.<b>1</b>&#160;255.255.255.255</font><font face="SansSerif">&#160;// &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1089;&#1077;&#1090;&#1100; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074; (1,2,...7)</font>
    </p>
    <p>
      <font face="SansSerif">&#160;&#160; </font><font color="#0000c0" face="SansSerif">(config-if)# no shutdown </font><font face="SansSerif">// &#1087;&#1086;&#1076;&#1085;&#1103;&#1090;&#1100; </font>
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1</font>&#160;//<b>OSPF</b>. &#1074;&#1093;&#1086;&#1076; &#1074; &#1082;&#1086;&#1085;&#1092;-&#1085;&#1080;&#1077; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072; (1 - &#1074;&#1099;&#1073;&#1086;&#1088; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072;)
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# network 192.168.<b>1</b>.0 0.0.0.255 area 0</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; (<b>&#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;) &#1074;&#1089;&#1077; &#1089;&#1077;&#1090;&#1080;</b>&#160;&#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1077; &#1082; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1091; (IP / Wildcard / &#1077;&#1076;&#1080;&#1085;&#1072;&#1103; &#1086;&#1073;&#1083;&#1072;&#1089;&#1090;&#1100; &#1076;&#1083;&#1103; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1074;). OSPF &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1086;&#1084; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1074;&#1089;&#1077;&#1093; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&#1093;
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="case 1.2 (два здания) OSPF" ID="ID_842927179" CREATED="1519112080186" MODIFIED="1725607275248"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Internet--R0--R1--SW1--WSs(Vlan10,20) </b>
    </p>
    <p>
      <b>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;╰---R2--SW2--WSs(Vlan30,40) </b>
    </p>
    <p>
      <b>Два здания через роутер R0 подключены к Интернет </b>
    </p>
    <p>
      <b>1. Настройки WSs</b>
    </p>
    <p>
      WSs1: 192.168.10.2/24 gw 192.168.10.1
    </p>
    <p>
      <b>2. Настроить коммутатор SW1 </b>
    </p>
    <p>
      <font color="#0000c0">(config)# vlan 10</font>&nbsp;// создать сегмент
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-vlan)# name users</font>&nbsp;// задать имя для сегмента, аналогично для сервера
    </p>
    <p>
      <font color="#0000c0">(config)# interface fa0/2</font><font color="#000000">&nbsp;// н</font>астраиваем интерфейс, обслуж. сегмент <b>или range</b>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# switchport mode access</font><font color="#000000">&nbsp;// порт в режим Access Port</font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# switchport access vlan 10 </font><font color="#000000">// каким VLANом маркировать порт </font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font><font color="#000000">&nbsp;// настроить Trunk Port до маршрутизатора</font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# switchport mode trunk </font>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# switchport trunk allowed vlan 10,20</font>
    </p>
    <p>
      <b>3. Настроить роутер R1</b>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>&nbsp;// поднять физический порт (в DOWNе по умолчанию)
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# no shutdown</font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1.10</font>&nbsp;// <b>создать подинтерфейсы для каждого VLANа</b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-subif)# encapsulation dot1Q 2</font>&nbsp;// указать номер VLANа
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-subif)# ip address 192.168.10.1 255.255.255.0</font>&nbsp;// задать IP-адрес
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-subif)# no shutdown</font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/0</font>&nbsp;// <b>настроить доступ к роутеру R0</b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-if)# ip address 192.168.2.2 255.255.255.252</font>&nbsp;// задать IP-адрес
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-if)# no shutdown </font>
    </p>
    <p>
      <font color="#0000c0" face="SansSerif">(config)# interface loopback 0</font><font face="SansSerif">&nbsp;// <b>OSPF. настроить IP-адрес н</b></font><b>а loopback интерфейсе</b>
    </p>
    <p>
      <font color="#0000c0" face="SansSerif">&nbsp;&nbsp;&nbsp;(config-if)# ip address 192.168.100.<b>1</b>&nbsp;255.255.255.255</font><font face="SansSerif">&nbsp;// выбрать сеть для всех роутеров (1,2,...7)</font>
    </p>
    <p>
      <font face="SansSerif">&nbsp;&nbsp; </font><font color="#0000c0" face="SansSerif">(config-if)# no shutdown </font><font face="SansSerif">// поднять </font>
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1</font>&nbsp;// <b>настроить OSPF процесс</b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-router)# network 192.168.<b>10</b>.0 0.0.0.255 area 0</font>&nbsp;// указать (<b>анонсировать</b>) все сети подключенные к роутеру (IP / Wildcard / единая область для роутеров). OSPF автоматом включается на всех интерфейсах
    </p>
    <p>
      <b>4. Настроить роутер R0 </b>
    </p>
    <p>
      <font color="#0000c0">(config)# interface g0/1</font>&nbsp;// <b>настроить интерфейс до R1</b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-if)# ip address 192.168.1.1 255.255.255.252</font>&nbsp;// задать IP-адрес
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-if)# no shutdown </font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface g0/0</font>&nbsp;// <b>настроить доступ в Интернет</b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-if)# ip address 210.214.1.2 255.255.255.252</font>&nbsp;// адрес провайдера
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-if)# no shutdown</font>
    </p>
    <p>
      <font color="#0000c0" face="SansSerif">(config)# interface loopback 0</font><font face="SansSerif">&nbsp;// <b>OSPF. настроить IP-адрес н</b></font><b>а loopback интерфейсе</b>
    </p>
    <p>
      <font color="#0000c0" face="SansSerif">&nbsp;&nbsp;&nbsp;(config-if)# ip address 192.168.100.<b>3</b>&nbsp;255.255.255.255</font><font face="SansSerif">&nbsp;// выбрать сеть для всех роутеров (1,2,...7)</font>
    </p>
    <p>
      <font face="SansSerif">&nbsp;&nbsp; </font><font color="#0000c0" face="SansSerif">(config-if)# no shutdown </font><font face="SansSerif">// поднять </font>
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1</font>&nbsp;// <b>настроить OSPF процесс</b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-router)# network 192.168.<b>1</b>.0 0.0.0.3 area 0</font>&nbsp;// <b>анонсировать</b>&nbsp;две сети (2-х зданий) подключенные к роутеру. <b>Сеть к провайдеру анонсировать не нужно</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip route 0.0.0.0 0.0.0.0 210.214.1.1 // </font><b>default gw в сторону провайдера</b>
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1</font>&nbsp;// <b>сообщить default gw роутерам R1 и R2</b>. вход в режим OSPF
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-router)# default-information originate</font>&nbsp;// распространить дефолтный gw маршрут
    </p>
    <p>
      <font color="#0000c0">(config)# interface g0/0</font>&nbsp;// <b>NAT. настроить внешний интерфейс</b>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# ip nat outside </font>
    </p>
    <p>
      <font color="#0000c0">(config)# interface g0/<b>1</b></font>&nbsp;// <b>NAT. настроить внутренний интерфейс для 2-х сетей</b>
    </p>
    <p>
      <font color="#0000c0">&nbsp;&nbsp;&nbsp;(config-if)# ip nat inside</font>
    </p>
    <p>
      <font color="#0000c0">(config)# ip access-list standart&nbsp;FOR-NAT</font><font color="#000000">&nbsp;// <b>NAT. </b></font><b>создать access list с именем (какой трафик будем NATить)</b>
    </p>
    <p>
      &nbsp;&nbsp; <font color="#0000c0">(config-std-nacl)#&nbsp;permit 192.168.<b>10</b>.0 0.0.0.255</font>&nbsp;// <b>NAT. сети, которым треб. доступ в Инт. </b>
    </p>
    <p>
      <b><font color="#0000c0">(config)# ip nat inside source list FOR-NAT interface g0/0 overload</font>&nbsp;&nbsp;// NAT.<a href="#ID_31864175">PAT</a></b>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
</node>
<node TEXT="Редистрибуция. OSPF+EIGRP" FOLDED="true" ID="ID_1359857024" CREATED="1519112080187" MODIFIED="1519112080187"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>OSPF + EIGRP</b>
    </p>
    <ul>
      <li>
        &#1053;&#1072; &#1086;&#1076;&#1085;&#1086;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085; &#1082;&#1072;&#1082; OSPF &#1090;&#1072;&#1082; &#1080; EIGRP
      </li>
      <li>
        &#1074;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1085;&#1091;&#1078;&#1085;&#1086; &#1082;&#1072;&#1082; &#1080;&#1079; &#1086;&#1076;&#1085;&#1086;&#1081; &#1074; &#1076;&#1088;&#1091;&#1075;&#1091;&#1102;, &#1090;&#1072;&#1082; &#1080; &#1080;&#1079; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1074; &quot;&#1086;&#1076;&#1085;&#1091;&quot;
      </li>
      <li>
        &#1087;&#1088;&#1080; &#1074;&#1073;&#1088;&#1086;&#1089;&#1077; &#1074; EIGRP - &#1087;&#1083;&#1086;&#1093;&#1072;&#1103; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1072; =&gt; <font color="#ff0000">&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090;</font>
      </li>
      <li>
        &#1087;&#1088;&#1080; &#1074;&#1073;&#1088;&#1086;&#1089;&#1077; &#1074; OSPF - &#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1072; 20
      </li>
    </ul>
    <p>
      <b>1. &#1042;&#1073;&#1088;&#1086;&#1089; &#1074; OSPF. &#1056;&#1077;&#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1094;&#1080;&#1103; &#1089;&#1077;&#1090;&#1077;&#1081;.</b>&#160;&#1056;&#1072;&#1079;&#1086;&#1089;&#1083;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;&#1084; &#1074;&#1089;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1076;&#1086; &#1074;&#1089;&#1077;&#1093; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1099;&#1093; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081;. <font color="#ff0000">&#1053;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;</font>&#160;&#1077;&#1089;&#1083;&#1080; &#1089;&#1077;&#1090;&#1077;&#1081; &#1084;&#1085;&#1086;&#1075;&#1086; (&#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1074; OSPF &#1074;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100; BGP). &#1052;&#1086;&#1078;&#1085;&#1086; &#1074; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1088;&#1077;&#1075;&#1080;&#1086;&#1085;&#1099; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1090;&#1100; &#1085;&#1077; &#1074;&#1089;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1072; &#1079;&#1072;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1080;&#1093; &#1076;&#1077;&#1092;&#1086;&#1083;&#1090;&#1085;&#1099;&#1084; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1084;. &#1069;&#1090;&#1086; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090; ABR &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; (&#1089;&#1084;. <a href="#ID_1220648200">Stub &#1074; OSPF</a>)
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# redistrubute eigrp 1 metric-type 1 subnets</font>&#160;// &#1074;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1074; OSPF &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1080;&#1079; EIGRP (&#1089; &#1091;&#1095;&#1077;&#1090;&#1086;&#1084; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090;&#1072; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080; OSPF, &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;)<font color="#0000c0">&#160;&#160; </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#1080;&#1083;&#1080; (config-router)# redistribute connected (static,eigrp, bgp &#1080; &#1090;.&#1076;) subnets</font>&#160;// &#1074;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1074; OSPF connected-&#1089;&#1077;&#1090;&#1080; (&#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; eigrp, bgp) ASBR &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;
    </p>
    <p>
      <b>2. &#1042;&#1073;&#1088;&#1086;&#1089; &#1074; EIGRP. &#1056;&#1077;&#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1094;&#1080;&#1103; &#1089;&#1077;&#1090;&#1077;&#1081;</b>
    </p>
    <p>
      <font color="#0000c0">(config)# router eigrp 1</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# redistrubute ospf 1 metric 100000 10 255 1 1500&#160; </font>// &#1074;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1074; EIGRP &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1080;&#1079; OSPF. &#1059;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1076;&#1083;&#1103; &#1088;&#1072;&#1089;&#1095;&#1077;&#1090;&#1072; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1080; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; (&#1080;&#1085;&#1072;&#1095;&#1077; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100;)
    </p>
    <p>
      <b>3. &#1048;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; (&#1076;&#1083;&#1103; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1072;)</b>
    </p>
    <p>
      <font color="#0000c0">(config)# router <b>ospf</b>&#160;1</font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# distance ospf external | inter-area | intra-area 1-255</font>&#160;// &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; OSPF &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# distance 1-255 172.20.0.0 0.0.255.255</font>&#160; // &#1076;&#1083;&#1103; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;
    </p>
    <p>
      <font color="#0000c0">(config)# router <b>eigrp</b>&#160;1</font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# distance eigrp | internal | external 1-255</font>&#160;// &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; eigrp &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;
    </p>
  </body>
</html></richcontent>
