<node TEXT="через Route-map" ID="ID_1653955850" CREATED="1519112080187" MODIFIED="1519112080187"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1084;&#1080; &#1087;&#1088;&#1080; &#1088;&#1077;&#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1094;&#1080;&#1080; (&#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; Route-Map)</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# route-map &lt;Name1&gt; permit(deny) 10</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map, 10-&#1074;&#1077;&#1090;&#1082;&#1072; route-map (&#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; route-map &#1089; &#1086;&#1076;&#1085;&#1080;&#1084; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; &#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1080;&#1093; &#1087;&#1086;&#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1085;&#1086;)
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-route-map)# match <b>&lt;statement1&gt;, &lt;statement2&gt;, ...</b></font><b>&#160;</b>// &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103; &#1087;&#1086;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1076; route-map, &#1083;&#1086;&#1075;&#1080;&#1082;&#1072; <b>&#1048;&#1051;&#1048;</b>
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-route-map)# match <b>&lt;statement1&gt;</b></font>&#160; // &#1083;&#1086;&#1075;&#1080;&#1082;&#1072; <b>&#1048;</b>, &#1090;.&#1077;. &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1089;&#1086;&#1074;&#1087;&#1072;&#1089;&#1090;&#1100; &#1074;&#1089;&#1077; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1103;
    </p>
    <p>
      &#160;&#160;&#160;<font color="#0000c0">(config-route-map)# match <b>&lt;statement2&gt;</b></font>
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# set &lt;statement&gt;</font>&#160;// &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;-----&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;<b>192.168.1.0/24</b>
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;ASBR&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;<b>192.168.2.0/24</b>
    </p>
    <p>
      &#9500;--R1----------<b>R2</b>---------R3---&#9508;192.168.3.0/24
    </p>
    <p>
      &#160;&#160;&#160;&#160;OSPF&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;EIGRP&#160;&#160;&#160;&#160;&#160;&#160;192.168.4.0/24
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;
    </p>
    <p>
      <font color="#0000c0">(config)# ip prefix-list <b>LIST1</b>&#160;permit 192.168.1.0/24</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1089;&#1077;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">(config)# ip prefix-list <b>LIST1</b>&#160;permit 192.168.1.0/24</font>&#160;// &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1089;&#1077;&#1090;&#1100;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# route-map <b>redist_in_ospf</b>&#160;permit 10</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0">(config-route-map)# match ip address prefix-list <b>LIST1</b></font>&#160;// &#1089;&#1088;&#1072;&#1074;&#1085;&#1080;&#1074;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072; &#1089; prefix-&#1083;&#1080;&#1089;&#1090;&#1086;&#1084;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0">(config-route-map)# set metric 25</font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1091; &#1076;&#1083;&#1103; &#1089;&#1086;&#1074;&#1087;&#1072;&#1074;&#1096;&#1080;&#1093; &#1089; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077;&#1084; &#1089;&#1077;&#1090;&#1077;&#1081;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0">(config-route-map)# set metric-type type-1</font>&#160;// &#1090;&#1080;&#1087; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1080; 1 - &#1089; &#1091;&#1095;&#1077;&#1090;&#1086;&#1084; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090;&#1072; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1087;&#1086; &#1089;&#1077;&#1090;&#1080;
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# redistribute eigrp 1 subnets route-map <b>redist_in_ospf</b>&#160;</font>// &#1087;&#1086;&#1074;&#1077;&#1089;&#1080;&#1090;&#1100; route-map &#1085;&#1072; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1088;&#1077;&#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1094;&#1080;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
