<node TEXT="Редистрибуция. RIP+OSPF" FOLDED="true" ID="ID_1535810025" CREATED="1519112080188" MODIFIED="1519112080188"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1042;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1074; OSPF &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1079;&#1072;&#1088;&#1086;&#1076;&#1080;&#1074;&#1096;&#1080;&#1077;&#1089;&#1103; &#1074; RIP</b>
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# redistribute rip subnets </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# redistribute rip metric 50 </font>// &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1080; &#1084;&#1086;&#1078;&#1077;&#1084; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1080;&#1079; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1099; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1093;&#1091;&#1076;&#1096;&#1080;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1074; RIP &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099;, &#1079;&#1072;&#1088;&#1086;&#1076;&#1080;&#1074;&#1096;&#1080;&#1077;&#1089;&#1103; &#1074; OSPF</b>
    </p>
    <p>
      <font color="#0000c0">(config)# router rip </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# redistribute ospf 1 metric 10</font>&#160;// &#1089; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1081; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1086;&#1081; OSPF &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1074;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1089;&#1103; &#1074; RIP
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1063;&#1090;&#1086;&#1073;&#1099; &#1080;&#1079;&#1073;&#1077;&#1078;&#1072;&#1090;&#1100; &#1087;&#1077;&#1090;&#1083;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;, &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1083;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; OSPF &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074; &#1091;&#1093;&#1091;&#1076;&#1096;&#1080;&#1090;&#1100; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077;. </b>
    </p>
    <p>
      <font color="#0000c0">(config)# router ospf 1 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-router)# distance ospf external 130</font>&#160;// &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1077; &#1088;&#1072;&#1089;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; OSPF &#1076;&#1083;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1086;&#1074;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; &#1080;&#1079; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1075;&#1086; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072;. &#1059; RIP 125.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1058;&#1072;&#1082;&#1078;&#1077; &#1076;&#1083;&#1103; &#1080;&#1079;&#1073;&#1077;&#1078;&#1072;&#1085;&#1080;&#1103; &#1087;&#1077;&#1090;&#1083;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084; <a href="#ID_1779390885">&#1090;&#1077;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;</a></b>
    </p>
  </body>
</html></richcontent>
