<node TEXT="Тэгирование" ID="ID_1779390885" CREATED="1519112080188" MODIFIED="1519112080188"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;&#1084;&#1080; &#1087;&#1088;&#1080; &#1088;&#1077;&#1076;&#1080;&#1089;&#1090;&#1088;&#1080;&#1073;&#1091;&#1094;&#1080;&#1080;. &#1058;&#1101;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;</b>
    </p>
    <p>
      
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#1086;&#1090;&#1082;&#1083;&#1086;&#1085;. &#1090;&#1077;&#1075;&#1072; 50 --&gt;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;
    </p>
    <p>
      &#9500;-R1----------<b>R2</b>---------R3&#9508;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#9584;-----------<b>R4---------</b>&#9583;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; &#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;
    </p>
    <p>
      &#160;&#160;RIP&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;OSPF&#160;
    </p>
    <p>
      &#160;&#160;&#160;&#160;&#160;&lt;-- &#1091;&#1089;&#1090;. &#1090;&#1077;&#1075;&#1072; 50&#160;&#160;&#160;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">R4(config)# route-map <b>ospf_to_rip</b>&#160;permit 10</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">R4(config-route-map)# set tag 50</font>&#160;// &#1074;&#1089;&#1077; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1090;&#1101;&#1075;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &quot;50&quot;
    </p>
    <p>
      <font color="#0000c0">R4(config)# router rip </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;R4(config-router)# redistribute ospf 1 subnets route-map <b>ospf_to_rip</b>&#160;</font>// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; route-map
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">R2(config)# route-map <b>rip_to_ospf</b>&#160;deny 10</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map
    </p>
    <p>
