<node TEXT="2 пров., 1 CE. Мониторинг доступности ресурса" ID="ID_1029990420" CREATED="1519112080189" MODIFIED="1519112080189"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082; &#1076;&#1074;&#1091;&#1084; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;&#1084; &#1087;&#1086; &#1089;&#1093;&#1077;&#1084;&#1077; <a href="#ID_160948091">Multihomed</a>&#160;&#1089; &#1086;&#1076;&#1085;&#1080;&#1084; CE &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084;.</b>
    </p>
    <p>
      <b>&#1052;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;&#1080;&#1085;&#1075; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1080; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1072;. IP SLA</b>
    </p>
    <p>
      
    </p>
    <p>
      &#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103; IP SLA &#1085;&#1072; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082; &#1076;&#1074;&#1091;&#1084; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;&#1084; &#1087;&#1086; &#1089;&#1093;&#1077;&#1084;&#1077; Multihomed &#1073;&#1077;&#1079; BGP c &#1086;&#1076;&#1085;&#1080;&#1084; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1086;&#1084;:
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1087;&#1086;&#1089;&#1086;&#1073; 1:</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip sla 1</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1079;&#1086;&#1085;&#1076; &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-ip-sla)# icmp-echo 20.0.1.2 source-interface e0/2</font>&#160;// &#1087;&#1086;&#1089;&#1083;&#1072;&#1090;&#1100; icmp echo ping &#1085;&#1072; 20.0.1.2
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#160;&#160;&#160;(config-ip-sla-echo)# frequency 10</font>&#160;// &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1090;&#1100; icmp echo ping &#1082;&#1072;&#1078;&#1076;&#1099;&#1077; 10 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;
    </p>
    <p>
      <font color="#0000c0">(config)# ip sla schedule 1 start-time now life forever</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1088;&#1072;&#1089;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; ip sla. &#1042; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1079;&#1086;&#1085;&#1076; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085; &#1087;&#1088;&#1103;&#1084;&#1086; &#1089;&#1077;&#1081;&#1095;&#1072;&#1089;, &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1074;&#1088;&#1077;&#1084;&#1103; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1085;&#1080;&#1103; &#1085;&#1077; &#1079;&#1072;&#1076;&#1072;&#1085;&#1086; (&#1085;&#1072;&#1074;&#1089;&#1077;&#1075;&#1076;&#1072;)
    </p>
    <p>
      <font color="#0000c0"><b>(config)# track 1 ip sla 1 reachability</b></font><b>&#160;</b>// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1085;&#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1100; &#1090;&#1086;&#1075;&#1086; &#1093;&#1086;&#1089;&#1090;&#1072;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1084; icmp echo ping. &#1048;&#1084;&#1077;&#1085;&#1086; &#1101;&#1090;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1077; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;, &#1090;&#1086;&#1075;&#1076;&#1072; - &#1089;&#1084;. &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; 2
    </p>
    <p>
      <font color="#0000c0">(config)# ip route 0.0.0.0 0.0.0.0 2.2.2.2 track 1</font>&#160;// &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1087;&#1086; &#1101;&#1090;&#1086;&#1084;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1091; &#1077;&#1089;&#1083;&#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; &#1090;&#1088;&#1077;&#1082;&#1080;&#1085;&#1075;&#1072; track 1 &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; (&#1093;&#1086;&#1089;&#1090; &#1087;&#1080;&#1085;&#1075;&#1091;&#1077;&#1090;&#1089;&#1103;)
    </p>
    <p>
      <font color="#0000c0">(config)# ip route 0.0.0.0 0.0.0.0 3.3.3.3 10</font>&#160;// &#1077;&#1089;&#1083;&#1080; &#1085;&#1077; &#1087;&#1080;&#1085;&#1075;&#1091;&#1077;&#1090;&#1089;&#1103;, &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1074; &#1080;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090; &#1087;&#1086; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1091; (!!! &#1047;&#1076;&#1077;&#1089;&#1100; &#1074;&#1072;&#1078;&#1085;&#1086; &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1087;&#1083;&#1086;&#1093;&#1091;&#1102; &#1084;&#1077;&#1090;&#1088;&#1080;&#1082;&#1091;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; 10, &#1080;&#1085;&#1072;&#1095;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1086;&#1073;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;! (&#1073;&#1072;&#1083;&#1072;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1082;&#1072;))
    </p>
    <p>
      <font color="#0000c0"># show track 1</font>&#160;&#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090;&#1072; &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1087;&#1086;&#1089;&#1086;&#1073; 2 (&#1077;&#1089;&#1083;&#1080; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; &#1085;&#1077; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;):</b>
    </p>
    <p>
      <font color="#0000c0">(config)# ip sla monitor 1</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-sla-monitor)# type echo protocol IpIcmpEcho 20.0.1.2 source-interface e0/2</font>&#160;// &#1087;&#1086;&#1089;&#1083;&#1072;&#1090;&#1100; icmp echo ping &#1085;&#1072; 20.0.1.2
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;&#160;&#160;&#160;(config-sla-monitor-echo)# frequency 10</font>&#160; // &#1087;&#1086;&#1089;&#1099;&#1083;&#1090;&#1100; icmp echo ping &#1089; &#1082;&#1072;&#1078;&#1076;&#1099;&#1077; 10 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;
    </p>
    <p>
      <font color="#0000c0">(config)# ip sla monitor schedule 1 life forever start-time now</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1088;&#1072;&#1089;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; ip sla. &#1042; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1079;&#1086;&#1085; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085; &#1087;&#1088;&#1103;&#1084;&#1086; &#1089;&#1077;&#1081;&#1095;&#1072;&#1089;, &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1074;&#1088;&#1077;&#1084;&#1103; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1085;&#1080;&#1103; &#1085;&#1077; &#1079;&#1072;&#1076;&#1072;&#1085;&#1086; (&#1085;&#1072;&#1074;&#1089;&#1077;&#1075;&#1076;&#1072;)
    </p>
    <p>
      <font color="#0000c0">(config)# track 1 rtr 1 reachability</font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1085;&#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1100; &#1090;&#1086;&#1075;&#1086; &#1093;&#1086;&#1089;&#1090;&#1072;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1084; icmp echo ping
    </p>
    <p>
      <font color="#0000c0">(config)# ip route 0.0.0.0 0.0.0.0 2.2.2.2 track 1</font>&#160;// &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1087;&#1086; &#1101;&#1090;&#1086;&#1084;&#1091; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1091; &#1077;&#1089;&#1083;&#1080; &#1086;&#1073;&#1098;&#1077;&#1082;&#1090; &#1090;&#1088;&#1077;&#1082;&#1080;&#1085;&#1075;&#1072; track 1 &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; (&#1093;&#1086;&#1089;&#1090; &#1087;&#1080;&#1085;&#1075;&#1091;&#1077;&#1090;&#1089;&#1103;)
