    </p>
    <p>
      &#1055;&#1088;&#1080; Multihomed &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082; &#1076;&#1074;&#1091;&#1084; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;&#1084; &#1087;&#1086; BGP &#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1076;&#1074;&#1091;&#1093; CE, &#1086;&#1073;&#1072; CE &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1091;&#1102;&#1090; &#1086;&#1076;&#1085;&#1091; &#1080; &#1090;&#1091; &#1078;&#1077; &#1089;&#1077;&#1090;&#1100; (Provider Independent, &#1080;&#1083;&#1080; PI)&#160;&#1086;&#1073;&#1086;&#1080;&#1084; ISP. &#1048;&#1079;-&#1079;&#1072; &#1101;&#1090;&#1086;&#1075;&#1086; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1085;&#1077; &#1095;&#1077;&#1088;&#1077;&#1079; &#1090;&#1086;&#1090; CE, &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1086;&#1085; &#1074;&#1099;&#1096;&#1077;&#1083;. &#1055;&#1088;&#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1086;&#1084; NAT &#1085;&#1072; &#1086;&#1073;&#1086;&#1080;&#1093; CE &#1088;&#1072;&#1073;&#1086;&#1090;&#1072; &#1090;&#1072;&#1082;&#1086;&#1081; &#1089;&#1077;&#1090;&#1080; &#1085;&#1077; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1072;, &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1088;&#1080;&#1081;&#1090;&#1080; &#1085;&#1072; &#1090;&#1086;&#1090; CE &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;, &#1091; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &#1079;&#1072;&#1076;&#1072;&#1085;&#1086; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086; &#1090;&#1088;&#1072;&#1085;&#1089;&#1083;&#1103;&#1094;&#1080;&#1080;. &#1044;&#1083;&#1103; &#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1103; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099;, &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; CE &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1091;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085; &#1085;&#1072; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1081; ISP, &#1079;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; PI &#1072;&#1076;&#1088;&#1077;&#1089;&#160;&#1087;&#1086;&#1082;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; ISP &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074; &#1088;&#1072;&#1073;&#1086;&#1090;&#1086;&#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1084; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080;. &#1044;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; CE, &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1085;&#1072; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1081; ISP, &#1084;&#1086;&#1075; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1090;&#1100; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086; ISP, &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; ISP &#1087;&#1086;&#1084;&#1080;&#1084;&#1086; &#1076;&#1077;&#1092;&#1086;&#1083;&#1090;&#1085;&#1086;&#1075;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1088;&#1080;&#1089;&#1099;&#1083;&#1072;&#1090;&#1100; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;. &#1053;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;, &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; route-map, CE &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1085;&#1072; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1083;&#1080;&#1073;&#1086; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1083;&#1080;&#1073;&#1086; &#1085;&#1077; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; PI &#1072;&#1076;&#1088;&#1077;&#1089;&#160;&#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1084;&#1091; ISP.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103;:</b>
    </p>
    <p>
      <font color="#0000c0">(config-router)# ip prefix-list NONEXIST seq 5 permit 1.2.3.0/24</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; prefix-list, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1083;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;
    </p>
    <p>
      <font color="#0000c0">(config)# ip prefix-list our-network seq 5 permit 147.45.67.34/24</font>&#160; // &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1089;&#1077;&#1090;&#1100;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1073;&#1091;&#1076;&#1077;&#1090; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1081; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1086;&#1084;&#1091; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1091; (&#1090;&#1091; &#1089;&#1072;&#1084;&#1091;&#1102;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1074;&#1093;&#1086;&#1076;&#1080;&#1090; &#1082;&#1091;&#1087;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1085;&#1072;&#1084;&#1080; PI &#1072;&#1076;&#1088;&#1077;&#1089;)
    </p>
    <p>
      <font color="#0000c0">(config)# route-map NONEXIST_MAP permit 10</font>&#160;//&#160;&#160;&#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1074; &#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; prefix-list NONEXIST &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1083;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; 1.2.3.0/24
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# match ip address prefix-list NONEXIS</font>
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# route-map ournets permit 100</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; route-map ournets
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-route-map)# match ip address prefix-list our-network route-map ournets</font>&#160;// &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072;, &#1086;&#1085; &#1085;&#1091;&#1078;&#1077;&#1085; &#1076;&#1083;&#1103; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084;&#1072; advertise-map
    </p>
    <p>
      <font color="#0000c0">(config)# router bgp 65100 </font>// &#1087;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080; &#1082; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102; BGP &#1085;&#1072; AS 65100
    </p>
    <p>
      &#160;&#160;&#160; <font color="#0000c0">(config-router)# neighbor 132.56.43.21 route-map ournets out</font>&#160;// &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1082; &#1089;&#1086;&#1089;&#1077;&#1076;&#1091; (&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1085;&#1072;&#1089; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1099;&#1084; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1086;&#1084;)&#160;&#160;router-map &#1089; &#1080;&#1084;&#1077;&#1085;&#1077;&#1084; ournets out
    </p>
    <p>
      &#160;&#160; <font color="#0000c0">(config-router)# neighbor 132.56.43.21 advertise-map ournets non-exist-map NONEXIST_MAP</font>&#160;// &#1089;&#1077;&#1090;&#1100;, &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1085;&#1072;&#1103; &#1074; prefix-list our-network, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; &#1082; route-map ournets, &#1073;&#1091;&#1076;&#1077;&#1090; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074; &#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; route-map NONEXIST_MAP &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100;, &#1090;&#1086; &#1077;&#1089;&#1090;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1072;&#1085;&#1086;&#1085;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;
    </p>
  </body>
