  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_89578272">PPPoE</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1091; &#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; PPPoE (<a href="#ID_160948091">Single-Homed</a>)</b>
    </p>
    <p>
      
    </p>
    <p>
      1. &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; Dialer:
    </p>
    <p>
      <font color="#0000c0">(config)# interface Dialer1</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; dialer1
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip address negotiated ip</font>&#160;// &#1072;&#1076;&#1088;&#1077;&#1089; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1080;&#1089;&#1074;&#1086;&#1077;&#1085; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ip mtu 1492 </font>// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; mtu &#1074; 1492 &#1073;&#1072;&#1081;&#1090;&#1072; (&#1101;&#1090;&#1086; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1086;&#1075;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; PPPoE)
    </p>
    <p>
      &#160;<font color="#0000c0">&#160;&#160;(config-if)# ip nat outside </font>// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; NAT &#1080; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# encapsulation ppp</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1088;&#1077;&#1078;&#1080;&#1084; &#1080;&#1085;&#1082;&#1072;&#1087;&#1089;&#1091;&#1083;&#1103;&#1094;&#1080;&#1080; (&#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072; &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;)
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# dialer pool 1</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; dialer pool (&#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085; &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1082;&#1080; &#1082; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084;&#1091; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091;)
    </p>
    <p>
      &#160;<font color="#0000c0">&#160;&#160;(config-if)# ppp authentication chap callin</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1080; &#1087;&#1086;&#1076;&#1083;&#1080;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080;. &#1042; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; chap
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ppp chap hostname Name</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1080;&#1084;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# ppp chap password 0 Cisco</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1077;&#1084; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;
    </p>
    <p>
      
    </p>
    <p>
      2. &#1050; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; &#1082; &#1089;&#1077;&#1090;&#1080; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;, &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; dialer pool, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1099; &#1091;&#1082;&#1072;&#1079;&#1072;&#1083;&#1080; &#1087;&#1088;&#1080; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; Dialer1):
    </p>
    <p>
      <font color="#0000c0">(config)# interface f0/1</font>&#160;// &#1087;&#1077;&#1088;&#1077;&#1081;&#1090;&#1080; &#1082; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1102; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;, &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1085;&#1072; &#1087;&#1088;&#1086;&#1074;&#1072;&#1081;&#1076;&#1077;&#1088;&#1072;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# pppoe-client dial-pool-number 1</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1088;&#1072;&#1085;&#1077;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1081; dialer pool, &#1090;&#1077;&#1084; &#1089;&#1072;&#1084;&#1099;&#1084; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; dialer 1 &#1082; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084;&#1091; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091; f0/1
    </p>
    <p>
      
    </p>
    <p>
      3. &#1047;&#1072;&#1076;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1095;&#1077;&#1088;&#1077;&#1079; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; Dialer &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; NAT:
    </p>
    <p>
      <font color="#0000c0">(config)# ip route 0.0.0.0 0.0.0.0 dialer 1</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090; &#1095;&#1077;&#1088;&#1077;&#1079; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; dialer 1
    </p>
    <p>
      <font color="#0000c0">(config)# access-list 1 permit 192.168.0.0 0.0.255.255</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1091;&#1083; &#1095;&#1072;&#1089;&#1090;&#1085;&#1099;&#1093; ip &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1099; &#1073;&#1091;&#1076;&#1077;&#1084; &#1090;&#1088;&#1072;&#1085;&#1089;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; ip &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; dialer 1
    </p>
    <p>
      <font color="#0000c0">(config)# ip nat inside source static list 1 interface dialer 1 overload</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; NAT
    </p>
  </body>
