  </head>
  <body>
    <p>
      <font color="#0000c0">#&#160;copy running-config tftp:</font>&#160;//&#160;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; &#1085;&#1072; TFTP-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;
    </p>
    <p>
      <font color="#0000c0">#&#160;copy tftp: flash:</font>&#160;//&#160;&#1082;&#1086;&#1087;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; &#1089; TFTP-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1085;&#1072; &#1092;&#1083;&#1077;&#1096;&#1082;&#1091;
    </p>
    <p>
      <font color="#0000c0"># show flash:</font>&#160;// &#1092;&#1072;&#1081;&#1083;&#1099; &#1085;&#1072; &#1092;&#1083;&#1101;&#1096;&#1082;&#1077;
    </p>
    <p>
      
    </p>
    <p>
