      <font color="#0000c0"># copy tftp: startup-config</font>&#160;// &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1080;&#1079; backup
    </p>
    <p>
      <font color="#0000c0"># erase nvram:</font>&#160;// &#1089;&#1090;&#1077;&#1088;&#1077;&#1090;&#1100; &#1089;&#1090;&#1072;&#1088;&#1090;&#1086;&#1074;&#1091;&#1102; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;
    </p>
    <p>
      <font color="#0000c0"># erase startup-config</font>&#160;// &#1089;&#1090;&#1077;&#1088;&#1077;&#1090;&#1100; &#1089;&#1090;&#1072;&#1088;&#1090;&#1086;&#1074;&#1091;&#1102; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># delete flash:&lt;&#1080;&#1084;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072;&gt;</font>&#160; // &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; &#1089; flash
    </p>
