<node TEXT="CLI" ID="ID_3146066" CREATED="1519112080192" MODIFIED="1519112080192"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>CLI (Command Line Interface)</b>
    </p>
    <p>
      <b>&#1055;&#1088;&#1086;&#1084;&#1086;&#1090;&#1082;&#1072; &#1074;&#1099;&#1074;&#1086;&#1076;&#1072;</b>
    </p>
    <ul>
      <li>
        --More-- <b>&lt;space bar</b>&gt; - next page
      </li>
      <li>
        --More-- <b>Enter</b>&#160;- &#1087;&#1088;&#1086;&#1084;&#1086;&#1090;&#1082;&#1072; &#1085;&#1072; &#1086;&#1076;&#1085;&#1091; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091;
      </li>
      <li>
        --More-- <b>&lt;AnyKey&gt;</b>&#160;- &#1086;&#1090;&#1084;&#1077;&#1085;&#1072;
      </li>
      <li>
        --More-- <b>Ctrl-C</b>&#160;- &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1090;
      </li>
      <li>
        Putty + &#1089;&#1085;&#1103;&#1090;&#1100; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;. &#1101;&#1082;&#1088;&#1072;&#1085;&#1072; // &#1074;&#1099;&#1074;&#1086;&#1076; &#1085;&#1072; &#1074;&#1077;&#1089;&#1100; &#1101;&#1082;&#1088;&#1072;&#1085;
      </li>
    </ul>
    <p>
      <font color="#0000c0"># show terminal</font>&#160;// &#1090;&#1077;&#1082;&#1091;&#1097;&#1080;&#1077; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1072;
    </p>
    <p>
      <font color="#0000c0"># terminal length 0</font>&#160;// &#1074;&#1099;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1074;&#1077;&#1089;&#1100; &#1090;&#1077;&#1082;&#1089;&#1090; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1073;&#1077;&#1079; &#1087;&#1072;&#1091;&#1079;&#1099;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1072; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080;</b>
    </p>
    <p>
      <font color="#0000c0">(config)# line console 0</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-line)# login</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-line)# password cisco </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-line)# exec-timeout 360 0</font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074;&#1088;&#1077;&#1084;&#1103; &#1090;&#1072;&#1081;&#1084;-&#1072;&#1091;&#1090;&#1072; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072; EXEC (&#1084;&#1080;&#1085;. &#1089;&#1077;&#1082;.). &#1063;&#1077;&#1088;&#1077;&#1079; 15 &#1084;&#1080;&#1085;&#1091;&#1090; (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;). 0 0 - &#1090;&#1072;&#1081;&#1084;-&#1072;&#1091;&#1090; &#1085;&#1080;&#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1077; &#1085;&#1072;&#1089;&#1090;&#1091;&#1087;&#1080;&#1090;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-line)# logging synchronous</font>&#160;// &#1079;&#1072;&#1087;&#1088;&#1077;&#1097;&#1072;&#1077;&#1090; &#1074;&#1099;&#1074;&#1086;&#1076; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1088;&#1077;&#1088;&#1099;&#1074;&#1072;&#1102;&#1090; &#1074;&#1074;&#1086;&#1076; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076; &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077;. &#1069;&#1090;&#1086; &#1091;&#1087;&#1088;&#1086;&#1089;&#1090;&#1080;&#1090; &#1095;&#1090;&#1077;&#1085;&#1080;&#1077; &#1080; &#1074;&#1074;&#1086;&#1076; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1074; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1072;&#1088;&#1086;&#1083;&#1100; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1072;. 0 4;&#160;&#160;&#160;5 15</b>
    </p>
    <p>
      <font color="#0000c0">(config)# line vty 0 4 </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-line)# login</font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-line)# password cisco </font>
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-line)# exec-timeout 120 0</font>&#160;// &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1074;&#1088;&#1077;&#1084;&#1103; &#1090;&#1072;&#1081;&#1084;-&#1072;&#1091;&#1090;&#1072; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072; EXEC (&#1084;&#1080;&#1085;. &#1089;&#1077;&#1082;.). &#1063;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1085;&#1072;&#1087;&#1088;&#1103;&#1075;&#1072;&#1083;&#1086; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1080;&#1077; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072; &#1095;&#1077;&#1088;&#1077;&#1079; 15 &#1084;&#1080;&#1085;&#1091;&#1090; (&#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;). 0 0 - &#1090;&#1072;&#1081;&#1084;-&#1072;&#1091;&#1090; &#1085;&#1080;&#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1077; &#1085;&#1072;&#1089;&#1090;&#1091;&#1087;&#1080;&#1090; &#1080; &#1087;&#1088;&#1080; &#1086;&#1073;&#1088;&#1099;&#1074;&#1072;&#1093; &#1073;&#1091;&#1076;&#1091;&#1090; &#1074;&#1080;&#1089;&#1077;&#1090;&#1100; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;&#1077; &#1089;&#1077;&#1089;&#1089;&#1080;&#1080;. &#1053;&#1072; 5-&#1102; &#1091;&#1078;&#1077; &#1085;&#1072; &#1079;&#1072;&#1081;&#1076;&#1077;&#1084;. &#1058;.&#1077;. 0 0 &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1090;&#1100; &#1085;&#1072; &#1085;&#1091;&#1083;&#1077;&#1074;&#1091;, &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; 120 &#1084;&#1080;&#1085;&#1091;&#1090;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-line)# logging synchronous</font>&#160;// &#1079;&#1072;&#1087;&#1088;&#1077;&#1097;&#1072;&#1077;&#1090; &#1074;&#1099;&#1074;&#1086;&#1076; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1088;&#1077;&#1088;&#1099;&#1074;&#1072;&#1102;&#1090; &#1074;&#1074;&#1086;&#1076; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076; &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1086;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077;. &#1069;&#1090;&#1086; &#1091;&#1087;&#1088;&#1086;&#1089;&#1090;&#1080;&#1090; &#1095;&#1090;&#1077;&#1085;&#1080;&#1077; &#1080; &#1074;&#1074;&#1086;&#1076; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1074; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;.
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="ROMMON" ID="ID_28641932" CREATED="1519112080193" MODIFIED="1519112080193"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1047;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; <a href="#ID_533534271">ROMMON</a>.</b>&#160;&#160;&#1044;&#1083;&#1103; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1074; ROMMON &#1085;&#1091;&#1078;&#1085;&#1086; <b>&#1087;&#1088;&#1077;&#1088;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;</b>&#160;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; IOS
    </p>
    <ul>
      <li>
        Cisco packet tracer <b>Ctrl-Break &#1080;&#1083;&#1080; Ctrl-ScrLk</b>
      </li>
      <li>
        Hyperterminal <b>Ctrl-Break</b>&#160;&#1080;&#1083;&#1080; <b>Ctrl-F6-Break</b>
      </li>
      <li>
        Kermit (Sun Workstation, UNIX) <b>Ctrl-\l</b>&#160;&#1080;&#1083;&#1080; <b>Ctrl-\b</b>
      </li>
      <li>
        MicroPhone Pro (Windows) <b>Ctrl-Break</b>
      </li>
      <li>
        Minicom (Linux) <b>Ctrl-a f</b>
      </li>
      <li>
        ProComm Plus (DOS or Windows) <b>Alt-b</b>
      </li>
      <li>
        SecureCRT (Windows) <b>Ctrl-Break</b>
      </li>
      <li>
        Telix (DOS) <b>Ctrl-End</b>
      </li>
      <li>
        Telnet <b>Ctrl-]</b>, then type send <b>brk</b>
      </li>
      <li>
        Teraterm (Windows) <b>Alt-b</b>
      </li>
      <li>
        Terminal (Windows) <b>Break</b>&#160;&#1080;&#1083;&#1080; <b>Ctrl-Break</b>
      </li>
      <li>
        Tip (Sun Workstation, UNIX) <b>Ctrl-]</b>, then <b>Break</b>&#160;or <b>Ctrl-c</b>&#160;&#1080;&#1083;&#1080; <b>~#</b>
      </li>
      <li>
        VT 100 Emulation (Data General) <b>F16</b>
      </li>
      <li>
        Windows NT (Windows) <b>Break-F5</b>&#160;&#1080;&#1083;&#1080; <b>Shift-F5</b>&#160;&#1080;&#1083;&#1080; <b>Shift-6</b>&#160;<b>Shift-4</b>&#160;<b>Shift-b</b>&#160;(<b>^$B</b>)
      </li>
      <li>
        Z-TERMINAL (Mac, Apple) <b>Command-b</b>
      </li>
      <li>
        Break-Out Box Connect pin 2 (X-mit) to +V for half a second
      </li>
      <li>
        Cisco to aux port <b>Control-Shft-6</b>, then <b>b</b>
      </li>
      <li>
        IBM Compatible <b>Ctrl-Break</b>
      </li>
    </ul>
    <p>
      <font color="#ff0000">&#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1086;&#1088;&#1090;</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">rommon 2 &gt; confreg 0x2102</font><font color="#000000">&#160;// &#1042;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;. &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086; &#1085;&#1072; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; 0x2102</font>
    </p>
    <p>
      <font color="#0000c0">rommon 3 &gt; boot </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1053;&#1072; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1077; Cisco Catalyst:</b>
    </p>
    <ul>
      <li>
        <b>&#1042;&#1093;&#1086;&#1076; &#1074; ROMMON</b>. &#1042;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090; 1. &#1042;&#1099;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#160;--&gt; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; --&gt; &#1085;&#1072;&#1078;&#1072;&#1090;&#1100; &#1080; &#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091; &#171;Mode&#187; 15 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;. &#1069;&#1090;&#1086; &#1087;&#1088;&#1077;&#1088;&#1074;&#1077;&#1090; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; --&gt; &#1087;&#1088;&#1080;&#1075;&#1083;&#1072;&#1096;&#1077;&#1085;&#1080;&#1077; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1095;&#1080;&#1082;&#1072; --&gt; &#1085;&#1091;&#1078;&#1085;&#1086; &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1080;&#1083;&#1080; &#1087;&#1077;&#1088;&#1077;&#1080;&#1084;&#1077;&#1085;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1083;&#1089;&#1103; &#1073;&#1077;&#1079; &#1085;&#1077;&#1075;&#1086;. &#1053;&#1086; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1095;&#1080;&#1082; &#1085;&#1077; &#1091;&#1084;&#1077;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1089; &#1092;&#1083;&#1101;&#1096;-&#1087;&#1072;&#1084;&#1103;&#1090;&#1100;&#1102;. &#1062;&#1077;&#1087;&#1083;&#1103;&#1077;&#1084; flash &#1087;&#1072;&#1084;&#1103;&#1090;&#1100;

        <ul>
          <li>
            <font color="#0000c0">switch: flash_init</font>
          </li>
          <li>
            <font color="#0000c0">switch: load_helper</font>
          </li>
          <li>
            <font color="#0000c0">switch: dir flash:</font>&#160;// &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1092;&#1083;&#1101;&#1096; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;
          </li>
        </ul>
      </li>
      <li>
        <b>&#1042;&#1093;&#1086;&#1076; &#1074; ROMMON</b>. &#1042;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090; 2

