<node TEXT="Инфо" FOLDED="true" ID="ID_1143405338" CREATED="1519112080193" MODIFIED="1725276391505"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">(config)# do &lt;command&gt; </font>// выполнение команд не выходя из конфигурирования (не работает автодополнение &lt;Tab&gt;)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># show version</font>&nbsp;// информация об оборудовании (flash, NVRAM, RAM (для ОС / под буфер интерфейсов), OC). Version 12.4 (15)T1 - 15-релиз, T1-технологический код
    </p>
    <p>
      <font color="#0000c0"># show flash</font>&nbsp;// файл прошивки
    </p>
    <p>
      <font color="#0000c0"># show flash:</font>&nbsp;// свободное место на flash памяти
    </p>
    <p>
      <font color="#0000c0"># show running-config </font>// показать текущую конфигурацию (из RAM, не файл)
    </p>
    <p>
      <font color="#0000c0"># show&nbsp;startup-config </font>// показать сохр. конфигурацию (файл из NVRAM)
    </p>
    <p>
      <font color="#0000c0"># show ip interface brief</font><font color="#000000">&nbsp;// состояние всех интерфейсов, построчно </font>
    </p>
    <p>
      <font color="#0000c0"># show interfaces status</font><font color="#000000">&nbsp;// (свитчи) состояние всех интерфейсов</font>
    </p>
    <p>
      <font color="#0000c0"># show interfaces&nbsp;</font>// инф-я по всем интерфейсам (редкий запрос). Слишком много информации.
    </p>
    <p>
      <font color="#0000c0"># show interfaces FastEthernet0/1</font>&nbsp;// инф-я по порту
    </p>
    <p>
      <font color="#0000c0"># show mac-address-table</font>&nbsp;// таблица коммутации
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;FastEthernet0/1 is <b>up</b>, line protocol is <b>up</b>&nbsp;(connected) // биты передаются, кадры складываются
    </p>
    <p>
      <font color="#0000c0"># show processes cpu | exclude 0.00</font><font color="#000000">&nbsp;// выводит список текущих процессов, аналог команды <b>top</b>&nbsp;в unix</font>
    </p>
  </body>
</html></richcontent>
<node TEXT="interfaces" ID="ID_571443784" CREATED="1519112080193" MODIFIED="1519112080193"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0"># show interfaces f0/1 </font>// &#1089;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082;&#1080; &#1087;&#1086; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084;&#1091; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091;. 5-&#1080; &#1084;&#1080;&#1085;&#1091;&#1090;&#1085;&#1086;&#1077; &#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1077;.
    </p>
    <p>
      <b>FastEthernet0/0 is up. </b>&#1048;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1085;&#1086; &#1072;&#1082;&#1090;&#1080;&#1074;&#1077;&#1085; (&#1074; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1074;&#1086;&#1090;&#1082;&#1085;&#1091;&#1090; &#1087;&#1072;&#1090;&#1095; &#1080; &#1077;&#1089;&#1090;&#1100; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1085;&#1072; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1099;&#1093; &#1094;&#1077;&#1087;&#1103;&#1093;). &#1055;&#1088;&#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; RJ45 &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; down. &#1054;&#1087;&#1090;&#1080;&#1082;&#1072; &#1078;&#1077; - &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; (&#1090;&#1086;&#1075;&#1076;&#1072; &#1089;&#1084;&#1086;&#1090;&#1088;&#1080;&#1084; line protocol)
    </p>
    <p>
      <b>Line protocol is up. </b>&#1056;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; (Ethernet)&#160; (&#1089; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1086;&#1081; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1103;&#1090; keepalive).
    </p>
    <p>
      <b>bia - build in address</b>&#160;- &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1085;&#1099;&#1081; MAC &#1072;&#1076;&#1088;&#1077;&#1089; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072;
    </p>
    <p>
      <b>MTU 1500 bytes. </b>&#1056;&#1072;&#1079;&#1084;&#1077;&#1088; MTU (Maximum Transmission Unit) &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077;
    </p>
    <p>
      <b>BW 100000 Kbit</b>. &#1055;&#1086;&#1083;&#1086;&#1089;&#1072; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1085;&#1080;&#1103; (bandwidth) &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1074; &#1082;&#1080;&#1083;&#1086;&#1073;&#1080;&#1090;&#1072;&#1093; &#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1091;. &#1047;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1086;&#1081; &#171;bandwidth&#187; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;. &#1053;&#1077; &#1074;&#1083;&#1080;&#1103;&#1077;&#1090; &#1085;&#1072; &#1088;&#1077;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1087;&#1086;&#1083;&#1086;&#1089;&#1091; &#1087;&#1088;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1085;&#1080;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;. &#1059;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072;&#1084;&#1080; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1087;&#1088;&#1080; &#1074;&#1099;&#1073;&#1086;&#1088;&#1077; &#1086;&#1087;&#1090;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1072;. &#1048; &#1087;&#1088;&#1080; &#1088;&#1072;&#1089;&#1095;&#1077;&#1090;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; txload/rxload
    </p>
    <p>
      <b>DLY 100 usec</b>. &#1047;&#1072;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; &#1074;&#1085;&#1086;&#1089;&#1080;&#1084;&#1072;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1084; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1074; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1072;&#1093;.
    </p>
    <p>
      <b>reliability 255/255</b>. &#1053;&#1072;&#1076;&#1077;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1082;&#1072;&#1082; &#1076;&#1086;&#1083;&#1103; &#1086;&#1090; 255 (255/255 &#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090; 100% &#1085;&#1072;&#1076;&#1077;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100;), &#1088;&#1072;&#1089;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; &#1101;&#1082;&#1089;&#1087;&#1086;&#1085;&#1077;&#1085;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1077;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1072;&#1073;&#1083;&#1102;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1088;&#1073;&#1083;&#1077;&#1084;&#1099; &#1085;&#1072; 1 &#1080;&#1083;&#1080; 2 &#1091;&#1088;&#1086;&#1074;&#1085;&#1077;, &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072;&#1076;&#1077;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; &#1087;&#1086;&#1085;&#1080;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;: 236/255
    </p>
    <p>
      <b>txload 1/255, rxload 1/255. </b>&#1047;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1085;&#1072; &#1087;&#1088;&#1080;&#1077;&#1084;/&#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1091; &#1082;&#1072;&#1082; &#1076;&#1086;&#1083;&#1103; &#1086;&#1090; 255 (255/255 &#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085;&#1085;&#1099;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;). &#1056;&#1072;&#1089;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; &#171;bandwidth&#187; &#1079;&#1072;&#1076;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077;.
    </p>
    <p>
      <b>Encapsulation ARPA. </b>&#1058;&#1080;&#1087; &#1080;&#1085;&#1082;&#1072;&#1087;&#1089;&#1091;&#1083;&#1103;&#1094;&#1080;&#1080; &#1089;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077;.
    </p>
    <p>
      <b>Keepalive set (10 sec)</b>. &#1055;&#1072;&#1082;&#1077;&#1090; keepalive &#1087;&#1086;&#1089;&#1099;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1078;&#1076;&#1099;&#1077; 10 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076; &#1076;&#1083;&#1103; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1072;&#1085;&#1080;&#1103; &#1083;&#1080;&#1085;&#1082;&#1072; &#1074; &#1088;&#1072;&#1073;&#1086;&#1090;&#1077;.
    </p>
    <p>
      <b>Full-duplex, 100Mb/s, 100BaseTX/FX</b>. &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1076;&#1091;&#1087;&#1083;&#1077;&#1082;&#1089;&#1072;, &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1080;, &#1080; &#1090;&#1080;&#1087; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1072; &#1083;&#1080;&#1085;&#1080;&#1080;. &#1053;&#1077;&#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077; &#1101;&#1090;&#1080;&#1093; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1095;&#1072;&#1097;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1086;&#1081; &#1086;&#1090;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1080;&#1103; &#1089;&#1074;&#1103;&#1079;&#1080; &#1095;&#1077;&#1088;&#1077;&#1079; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;.
    </p>
    <p>
      <b>Last clearing of &#171;show interface&#187; counters 00:00:02</b>. &#1048;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;. &#1050;&#1086;&#1075;&#1076;&#1072; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1081; &#1088;&#1072;&#1079; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1083;&#1072;&#1089;&#1100; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1072; &#1089;&#1073;&#1088;&#1086;&#1089;&#1072; &#1089;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082;&#1086;&#1074; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &quot;clear counters&quot;. &#1047;&#1072; &#1082;&#1072;&#1082;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1085;&#1072;&#1082;&#1086;&#1087;&#1083;&#1077;&#1085;&#1072; &#1089;&#1090;&#1072;&#1090;&#1080;&#1089;&#1090;&#1080;&#1082;&#1072; &#1087;&#1086; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1091;.
    </p>
    <p>
      <b>Queueing strategy: fifo</b>. &#1058;&#1080;&#1087; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1080; &#1089;&#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077;. &#1042; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1077; &#8212; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1087;&#1088;&#1080;&#1096;&#1077;&#1083; &#8212; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1091;&#1096;&#1077;&#1083; (fifo &#8212; first in, first out).
    </p>
    <p>
      <b>Output queue 0/40, 0 drops; input queue 0/75, 0 drops</b>. &#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1089;&#1090;&#1086;&#1103;&#1097;&#1080;&#1093; &#1074;&#1086; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1081; &#1080; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1081; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1103;&#1093;. &#1045;&#1089;&#1083;&#1080; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1087;&#1077;&#1088;&#1077;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085; &#8212; &#1073;&#1091;&#1076;&#1077;&#1090; &#1088;&#1072;&#1089;&#1090;&#1080; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1076;&#1088;&#1086;&#1087;&#1086;&#1074;.
    </p>
    <p>
      <b>30 minute input rate 624000 bits/sec, 254 packets/sec </b>
    </p>
    <p>
      <b>30 minute output rate 571000 bits/sec, 231 packets/sec</b>
    </p>
    <p>
      &#1057;&#1088;&#1077;&#1076;&#1085;&#1103;&#1103; &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1075;&#1086; &#1080; &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1077;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072; &#1079;&#1072; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076; (&#1074; &#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1077; &#1079;&#1072; 30 &#1084;&#1080;&#1085;&#1091;&#1090;). &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076; &#1091;&#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1085;&#1080;&#1103; 5 &#1084;&#1080;&#1085;&#1091;&#1090;. &#1052;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076; &#8212; 30 &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;. &#1047;&#1072;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1086;&#1081; &#171;load-interval&#187; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;
    </p>
    <p>
      <b>runts. </b>&#1045;&#1089;&#1083;&#1080; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1091;&#1084;&#1084;&#1072; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072; CRC &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1072;&#1103;, &#1072; &#1089;&#1072;&#1084; <b>&#1087;&#1072;&#1082;&#1077;&#1090; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;</b>, &#1095;&#1077;&#1084; &#1084;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1086;&#1084; Ethernet, &#1087;&#1072;&#1082;&#1077;&#1090; &#1086;&#1090;&#1082;&#1083;&#1086;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103;. &#1057;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082; runts &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1086;&#1090;&#1082;&#1083;&#1086;&#1085;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1077; &#1080;&#1093; &#1084;&#1072;&#1083;&#1086;&#1075;&#1086; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072;. &#1051;&#1102;&#1073;&#1086;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; 64 &#1073;&#1072;&#1081;&#1090; &#1085;&#1072; FastEthernet &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077; &#1086;&#1090;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; runts
    </p>
    <p>
      <b>giants(Jabber)</b>. &#1045;&#1089;&#1083;&#1080; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1091;&#1084;&#1084;&#1072; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072; CRC &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1072;&#1103;, &#1072; &#1089;&#1072;&#1084; &#1087;&#1072;&#1082;&#1077;&#1090; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;, &#1095;&#1077;&#1084; &#1084;&#1080;&#1085;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1086;&#1084; Ethernet, &#1087;&#1072;&#1082;&#1077;&#1090; &#1086;&#1090;&#1082;&#1083;&#1086;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103;. &#1057;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082; giants(Jabber) &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1086;&#1090;&#1082;&#1083;&#1086;&#1085;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1077; &#1080;&#1093; &#1084;&#1072;&#1083;&#1086;&#1075;&#1086; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072;. &#1051;&#1102;&#1073;&#1086;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; 1518 &#1073;&#1072;&#1081;&#1090; &#1085;&#1072; FastEthernet &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077; &#1086;&#1090;&#1073;&#1088;&#1072;&#1089;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1082; giants(Jabber).
    </p>
    <p>
      <b>input errors</b>. &#1054;&#1073;&#1097;&#1077;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077;. &#1057;&#1091;&#1084;&#1084;&#1072; &#1089;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082;&#1086;&#1074; runts, giants, no buffer, CRC, frame, overrun, ignored
    </p>
    <p>
      <b>&#160;&#160;&#160;CRC</b>. &#1057;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1089; &#1085;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;&#1081; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1091;&#1084;&#1084;&#1086;&#1081; CRC (Cyclic Redundancy Checksum). &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1088;&#1072;&#1089;&#1090;&#1077;&#1090; &#1087;&#1088;&#1080; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1080; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084; &#1085;&#1072; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077;, &#1087;&#1088;&#1080; &#1085;&#1077;&#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1080; &#1088;&#1077;&#1078;&#1080;&#1084;&#1072; &#1076;&#1091;&#1087;&#1083;&#1077;&#1082;&#1089;&#1072; &#1080;&#1083;&#1080; &#1087;&#1088;&#1080; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1080; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1081;/&#1087;&#1086;&#1084;&#1077;&#1093; &#1085;&#1072; &#1092;&#1080;&#1079;&#1080;&#1082;&#1077;
    </p>
    <p>
      <b>&#160;&#160;&#160;frame</b>. &#1050;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; &#1089; &#1087;&#1086;&#1074;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1086;&#1081; &#1082;&#1072;&#1076;&#1088;&#1072;
    </p>
    <p>
      <b>&#160;&#160;&#160;overrun</b>. &#1057;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082; &#1074;&#1099;&#1079;&#1074;&#1072;&#1085;&#1085;&#1099;&#1093; &#1085;&#1077;&#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1087;&#1088;&#1080;&#1077;&#1084;&#1085;&#1080;&#1082;&#1072; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1087;&#1086;&#1090;&#1086;&#1082; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;: &#1087;&#1072;&#1082;&#1077;&#1090;&#1099; &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1080;&#1079; &#1089;&#1077;&#1090;&#1080; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1103;&#1090; &#1072; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1100; &#1080;&#1093; &#1074; &#1073;&#1091;&#1092;&#1077;&#1088; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1085;&#1077; &#1091;&#1089;&#1087;&#1077;&#1074;&#1072;&#1077;&#1090;. &#1055;&#1088;&#1080; &#1088;&#1086;&#1089;&#1090;&#1077; &#1090;&#1072;&#1082;&#1080;&#1093; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1072; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072; (&#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; show processes cpu &#1080; show processes cpu history)
    </p>
    <p>
      &#160;&#160; <b>ignored</b>. &#1057;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1086;&#1090;&#1073;&#1088;&#1086;&#1096;&#1077;&#1085;&#1085;&#1099;&#1093; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1084; &#1087;&#1086; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1077; &#1079;&#1072;&#1085;&#1103;&#1090;&#1086;&#1089;&#1090;&#1080; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1075;&#1086; &#1073;&#1091;&#1092;&#1077;&#1088;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;
    </p>
    <p>
      <b>watchdog</b>. &#1057;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &#1080;&#1085;&#1090;&#1077;&#1088;&#1074;&#1072;&#1083;&#1072; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080;&#1077;&#1084;&#1072; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072;. &#1057;&#1080;&#1090;&#1091;&#1072;&#1094;&#1080;&#1103; &#1074;&#1086;&#1079;&#1085;&#1080;&#1082;&#1072;&#1077;&#1090; &#1087;&#1088;&#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1080; &#1087;&#1072;&#1082;&#1077;&#1090;&#1072; &#1076;&#1083;&#1080;&#1085;&#1085;&#1086;&#1081; &#1073;&#1086;&#1083;&#1077;&#1077; 2048 &#1073;&#1072;&#1081;&#1090;
    </p>
    <p>
      <b>input packets with dribble condition detected</b>. &#1057;&#1095;&#1077;&#1090;&#1095;&#1080;&#1082;, &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1082;&#1072;&#1076;&#1088;&#1086;&#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#171;&#1085;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1076;&#1083;&#1080;&#1085;&#1085;&#1077;&#1077;&#187; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086;&#1075;&#1086;. &#1048;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#1090;&#1072;&#1082; &#1082;&#1072;&#1082; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1090;&#1072;&#1082;&#1080;&#1077; &#1082;&#1072;&#1076;&#1088;&#1099; &#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;.
    </p>
    <p>
      <b>packets output</b>. &#1054;&#1073;&#1097;&#1077;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;
    </p>
    <p>
      <b>packets input</b>. &#1054;&#1073;&#1097;&#1077;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;
    </p>
    <p>
      <b>late collision.</b>&#160;&#1050;&#1072;&#1076;&#1088; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1086; &#1085;&#1077; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;. C &#1088;&#1072;&#1079;&#1085;&#1099;&#1093; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085; &#1088;&#1072;&#1079;&#1085;&#1099;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; duplex
    </p>
  </body>
