    </p>
    <p>
      <b>Ctrl-Z</b>&#160;// <b>&#1079;&#1072;&#1074;&#1077;&#1088;&#1096;&#1080;&#1090;&#1100; (&#1085;&#1077; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072;)&#160;&#160;&#1074;&#1074;&#1086;&#1076;</b>&#160;&#1080; &#1074;&#1099;&#1081;&#1090;&#1080; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1072;
    </p>
    <p>
      <b>Ctrl-C</b>&#160;//<b>&#160;&#1087;&#1088;&#1077;&#1082;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100;&#160;&#160;&#1074;&#1074;&#1086;&#1076;</b>&#160;&#1080; &#1074;&#1099;&#1081;&#1090;&#1080; &#1074; &#1088;&#1077;&#1078;&#1080;&#1084; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1072;
    </p>
    <ul>
      <li>
        &#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1080; &#1083;&#1091;&#1095;&#1096;&#1077; &#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1047;&#1040;&#1043;&#1051;&#1040;&#1042;&#1053;&#1067;&#1052;&#1048; &#1041;&#1059;&#1050;&#1042;&#1040;&#1052;&#1048; &#1090;&#1086;&#1075;&#1076;&#1072; &#1086;&#1085;&#1080; &#1073;&#1091;&#1076;&#1091;&#1090; &#1051;&#1045;&#1043;&#1050;&#1054; &#1042;&#1067;&#1061;&#1042;&#1040;&#1058;&#1067;&#1042;&#1040;&#1058;&#1068;&#1057;&#1071; &#1080;&#1079; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1090;&#1077;&#1082;&#1089;&#1090;&#1072;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>&#1057;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100;/&#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1085;&#1091;&#1102; &#1082;&#1086;&#1087;&#1080;&#1102; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1085;&#1072;/c TFTP-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;</b>
    </p>
    <p>
      <font color="#0000c0"># copy startup-config tftp:</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1080; &#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1076;&#1080;&#1090;&#1100; &#1080;&#1084;&#1103;
    </p>
    <p>
      # copy tftp: running-config // &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1073;&#1101;&#1082;&#1072;&#1087; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# service compress-config</font>&#160;// &#1089;&#1078;&#1072;&#1090;&#1080;&#1077; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1072; &#1087;&#1088;&#1080; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1080;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Конфигурационные регистры" ID="ID_641198239" CREATED="1519112080195" MODIFIED="1519112080195"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;</b>
    </p>
    <ul>
      <li>
        &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; &#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1080; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072; (&#1074; ROMmon, NetBoot),
      </li>
      <li>
        &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1099; &#1087;&#1088;&#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; (&#1080;&#1075;&#1085;&#1086;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;, &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077;),
      </li>
      <li>
        &#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080; (&#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100; &#1074; &#1073;&#1086;&#1076;&#1072;&#1093; &#1076;&#1083;&#1103; &#1089;&#1077;&#1072;&#1085;&#1089;&#1072; &#1101;&#1084;&#1091;&#1083;&#1103;&#1094;&#1080;&#1080; &#1090;&#1077;&#1088;&#1084;&#1080;&#1085;&#1072;&#1083;&#1072;).
      </li>
    </ul>
    <p>
      <font color="#0000c0">rommon 2&#160;&gt; confreg 0x2102</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; <a href="#ID_28641932">ROMMON</a>
    </p>
    <p>
      <font color="#0000c0">(config)# config-registe 0x2120</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; &#1075;&#1083;&#1086;&#1073;. &#1082;&#1086;&#1085;&#1092;. (&#1089;&#1088;&#1072;&#1079;&#1091; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1090;&#1100; ROMMON)
    </p>
    <p>
      <font color="#0000c0"># show version</font>&#160;// &#1090;&#1077;&#1082;&#1091;&#1097;&#1072;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1072; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">rommon 3 &gt; boot</font><font color="#000000">&#160;// &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072;</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Прошивка (TFTP)" ID="ID_1149477388" CREATED="1519112080195" MODIFIED="1723012423237"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_410438924">TFTP</a>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># show version</font>&nbsp;// версия прошивки
    </p>
    <p>
      <font color="#0000c0"># reload</font>&nbsp;// какая прошивка грузится и откуда гурзится
    </p>
    <p>
      <font color="#0000c0"># show flash</font>&nbsp;// файл прошивки
    </p>
    <p>
      
    </p>
    <p>
      <b>Обновление прошивки</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0"># copy tftp: flash:</font>&nbsp;// <b>1. загрузить прошивку</b>&nbsp;&nbsp;с TFTP-сервера на флэш. Далее ввести адрес TFTP-сервера (можно точный, можно 255.255.255.255) и название файла
    </p>
    <p>
      <font color="#0000c0"># verify /md5 flash:&lt;образ.bin&gt;</font>&nbsp;&nbsp;// <b>2. проверить целостность образа. </b>Полученный хеш необходимо сравнить с тем хешем, который указывает производитель (правильный MD5 показывается при скачивании файла с cisco.com)
    </p>
    <p>
      <font color="#0000c0">(config)# boot system flash:&lt;образ.bin&gt;</font>&nbsp;// <b>3. указать образ</b>, &nbsp;который использовать при загрузке
    </p>
    <p>
      <font color="#0000c0"># write memory </font>
    </p>
    <p>
      <font color="#0000c0"># reload </font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      см. <a href="#ID_439385925">Образы </a>
    </p>
    <p>
      см. <a href="#ID_1200909097">Восстановление IOS с помощью режима ROMMON</a>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Процессы" ID="ID_375359731" CREATED="1519112080195" MODIFIED="1519112080195"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Exec - &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1072; &#1074;&#1074;&#1086;&#1076;&#1072; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1080;
