<node TEXT="Удаленный доступ" FOLDED="true" ID="ID_494523439" CREATED="1519112080195" MODIFIED="1570734695339"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1059;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1087;&#1086; Telnet</b>
    </p>
    <p>
      <font color="#0000c0">(config)# enable password cisco</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1085;&#1072; enable
    </p>
    <p>
      <font color="#0000c0">(config)# username admin privilege 15 password cisco</font>&#160;// &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;
    </p>
    <p>
      <font color="#0000c0">(config)# line vty 0 4</font>&#160;// &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-line)# login LOCAL</font>&#160;// &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1073;&#1072;&#1079;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; SSH (&#1085;&#1072; &#1089;&#1074;&#1080;&#1090;&#1095;&#1077;). </b>&#1055;&#1077;&#1088;&#1077;&#1076; &#1101;&#1090;&#1080;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1086;&#1073;&#1072;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1073;&#1077;&#1079; &#1101;&#1090;&#1086;&#1075;&#1086; &#1079;&#1072;&#1081;&#1090;&#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; &#1085;&#1077; &#1091;&#1076;&#1072;&#1089;&#1090;&#1089;&#1103;
    </p>
    <ol>
      <li>
        <font color="#0000c0">(config)# username cisco password cisco</font>&#160;// &#1079;&#1072;&#1076;&#1072;&#1090;&#1100; &#1080;&#1084;&#1103; &#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; SSH &#1089;&#1077;&#1089;&#1089;&#1080;&#1080;
      </li>
      <li>
        <font color="#0000c0">(config)# ip domain-name mydomain.com</font>
      </li>
      <li>
        <font color="#0000c0">(config)#&#160;crypto key generate rsa </font>// &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1091;&#1077;&#1084; &#1072;&#1089;&#1080;&#1084;&#1084;&#1077;&#1090;&#1088;&#1080;&#1095;&#1085;&#1099;&#1077; &#1082;&#1083;&#1102;&#1095;&#1080;
      </li>
      <li>
        <font color="#0000c0">(config)# ip ssh version 2</font>
      </li>
      <li>
        <font color="#0000c0">(config)# line vty 0 4</font>

        <ol>
          <li>
            <p>
              <font color="#0000c0">login local </font>
            </p>
          </li>
          <li>
            <font color="#0000c0">transport input ssh</font>&#160;// &#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &#1089;&#1093;&#1077;&#1084;&#1091; &#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1074; &#1083;&#1080;&#1085;&#1080;&#1080;
          </li>
        </ol>
      </li>
    </ol>
    <p>
      <b>&#1053;&#1072; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088;&#1077;</b>&#160; &#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1072;&#1082;&#1078;&#1077; &#1082;&#1072;&#1082; &#1085;&#1072; &#1089;&#1074;&#1080;&#1090;&#1095;&#1077;, &#1089; &#1086;&#1076;&#1085;&#1080;&#1084; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077;&#1084;. &#1042;&#1084;&#1077;&#1089;&#1090;&#1086; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; vlan1 &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; <b>e0/0</b>
    </p>
  </body>
</html></richcontent>
<node TEXT="VPN" FOLDED="true" ID="ID_1707633030" CREATED="1519112080196" MODIFIED="1739697246567"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
