        <b>% Incomplete command</b>&#160;// &#1085;&#1077;&#1087;&#1086;&#1083;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099;
      </li>
      <li>
        <b>% Invalid input detected at &quot;^&quot; marker</b>&#160;// &#1086;&#1096;&#1080;&#1073;&#1086;&#1095;&#1085;&#1099;&#1081; &#1074;&#1074;&#1086;&#1076; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072;
