      <li>
        &#1087;&#1088;&#1080; &#1074;&#1074;&#1086;&#1076;&#1077; &#1085;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;&#1081; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099; &#1073;&#1091;&#1076;&#1077;&#1090; (&#1076;&#1083;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103;) &#1087;&#1099;&#1090;&#1072;&#1090;&#1100;&#1089;&#1103; &#1077;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1080;&#1090;&#1100; (&#1079;&#1072;&#1088;&#1077;&#1079;&#1086;&#1083;&#1074;&#1080;&#1090;&#1100;). &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077;. <font color="#ff0000">Show running-config - sh run (?????????)</font>.<br/><b>no ip domain-lookup</b>&#160;// o&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1074; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1077; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1087;&#1086;&#1080;&#1089;&#1082;&#1072; &#1087;&#1086; DNS
