<node TEXT="Восстановление IOS" ID="ID_1200909097" CREATED="1519112080198" MODIFIED="1519112080198"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; IOS &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1088;&#1077;&#1078;&#1080;&#1084;&#1072; ROMMON</b>
    </p>
    <ul>
      <li>
        &#1047;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; <a href="#ID_28641932">ROMMON</a>&#160;&#1080; &#1089;&#1082;&#1072;&#1095;&#1072;&#1090;&#1100; &#1089; tftp &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1085;&#1086;&#1074;&#1091;&#1102; &#1087;&#1088;&#1086;&#1096;&#1080;&#1074;&#1082;&#1091; (<b>ftp &#1085;&#1077; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;</b>, &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; tftp)
      </li>
    </ul>
    <p>
      <b>&#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1077; &#1080;&#1083;&#1080; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1077; Cisco:</b>
    </p>
    <p>
      <font color="#0000c0">rommon&gt; IP_ADDRESS=192.168.0.1</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089;
    </p>
    <p>
      <font color="#0000c0">rommon&gt; IP_SUBNET_MASK=255.255.255.0</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1084;&#1072;&#1089;&#1082;&#1091; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1080;
    </p>
    <p>
      <font color="#0000c0">rommon&gt; DEFAULT_GATEWAY=192.168.0.2</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1096;&#1083;&#1102;&#1079;. &#1044;&#1072;&#1078;&#1077; &#1077;&#1089;&#1083;&#1080; &#1085;&#1072;&#1096; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1080; tftp &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1077;, &#1074;&#1089;&#1077; &#1088;&#1072;&#1074;&#1085;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1096;&#1083;&#1102;&#1079;. &#1045;&#1089;&#1083;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080; &#1088;&#1086;&#1091;&#1090;&#1077;&#1088; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1074; &#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1088;&#1077;&#1076;&#1077;, &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1075;&#1086; &#1096;&#1083;&#1102;&#1079;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1072;&#1076;&#1088;&#1077;&#1089; tftp &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <p>
      <font color="#0000c0">rommon&gt; TFTP_SERVER=192.168.0.2</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089; tftp &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <p>
      <font color="#0000c0">rommon&gt; TFTP_FILE=&lt;&#1087;&#1088;&#1086;&#1096;&#1080;&#1074;&#1082;&#1072;.bin&gt;</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; &#1087;&#1088;&#1086;&#1096;&#1080;&#1074;&#1082;&#1080;
    </p>
    <p>
      <font color="#0000c0">rommon&gt; set</font>&#160;// &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; &#1082; &#1076;&#1074;&#1080;&#1078;&#1082;&#1091; tftpdnld
    </p>
    <p>
      <font color="#0000c0">rommon&gt; tftpdnld</font>&#160;// &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;. <b>&#1057; flash &#1074;&#1089;&#1105; &#1073;&#1091;&#1076;&#1077;&#1090; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1086;</b>
    </p>
    <p>
      <font color="#0000c0">rommon&gt; boot</font>&#160;// &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; &#1085;&#1086;&#1074;&#1091;&#1102; &#1087;&#1088;&#1086;&#1096;&#1080;&#1074;&#1082;&#1091;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; Cisco ASA:</b>
    </p>
    <p>
      <font color="#0000c0">rommon&gt; ADDRESS=192.168.0.1</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089;
    </p>
    <p>
      <font color="#0000c0">rommon&gt; SERVER=192.168.0.2</font>&#160;// &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100; &#1084;&#1072;&#1089;&#1082;&#1091; &#1087;&#1086;&#1076;&#1089;&#1077;&#1090;&#1080;
    </p>
    <p>
