<node TEXT="CEF" ID="ID_1081071164" CREATED="1519112080201" MODIFIED="1519112080201"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Cisco Express Forwarding (CEF)</b>&#160;&#8212; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1089;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1085;&#1086;&#1081; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;/&#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1080; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1072;&#1103;&#1089;&#1103; &#1074; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;&#1093; &#1080; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072;&#1093; &#1090;&#1088;&#1077;&#1090;&#1100;&#1077;&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103; &#1092;&#1080;&#1088;&#1084;&#1099; Cisco Systems, &#1080; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1072;&#1103; &#1076;&#1086;&#1073;&#1080;&#1090;&#1100;&#1089;&#1103; &#1073;&#1086;&#1083;&#1077;&#1077; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;&#1081; &#1080; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1081; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1090;&#1085;&#1086;&#1075;&#1086; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1072;&#1083;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; CEF:</b>&#160;QoS, ACL, Zone Based Firewall, NAT, Netflow, IPSec, GRE, <a href="#ID_80996055">PBR</a>
    </p>
    <p>
      <b><font color="#ff0000">CEF &#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;</font>, &#1082;&#1086;&#1075;&#1076;&#1072;:</b>
    </p>
    <ul>
      <li>
        &#1042;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; ACL Logging (&#1074; &#1082;&#1086;&#1085;&#1094;&#1077; ACL &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1086; &#1089;&#1083;&#1086;&#1074;&#1086; log, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; deny ip any any log)
      </li>
      <li>
        &#1055;&#1072;&#1082;&#1077;&#1090;&#1099; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1099; &#1076;&#1083;&#1103; &#1089;&#1072;&#1084;&#1086;&#1075;&#1086; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1072;/&#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1072;.
      </li>
      <li>
        &#1053;&#1077;&#1090; L2 Adjacency
      </li>
    </ul>
    <p>
      <b>Forwarding Information Base (FIB)</b>&#160;&#1080;&#1083;&#1080; <b>CEF Table</b>&#160;&#8212; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072; &#1076;&#1083;&#1103; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;&#1081; &#1087;&#1077;&#1088;&#1077;&#1089;&#1099;&#1083;&#1082;&#1080; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074;. &#1057;&#1090;&#1088;&#1086;&#1080;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; Routing Table &#1080; Adjacency Table. Adjacency Table &#1074; &#1089;&#1074;&#1086;&#1102; &#1086;&#1095;&#1077;&#1088;&#1077;&#1076;&#1100; &#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; ARP Table. &#1056;&#1072;&#1079;&#1083;&#1080;&#1095;&#1072;&#1102;&#1090; <b>2 &#1074;&#1080;&#1076;&#1072; CEF</b>&#160;- <b>Software CEF</b>&#160;(&#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1074;&#1080;&#1076;&#1077;&#1090;&#1100; &#1085;&#1072; ISR G1/G2 &#1080; 7200) &#1080; Hardware CEF (&#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1074;&#1080;&#1076;&#1077;&#1090;&#1100; &#1085;&#1072; 6500/7600, Nexus 7000 &#1080; ASR9000). <b>Hardware CEF</b>&#160;- &#1101;&#1090;&#1086; &#1082;&#1086;&#1075;&#1076;&#1072; &#1087;&#1086;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1072;&#1103; FIB &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1089;&#1103; &#1074; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; <a href="#ID_1270640899">TCAM</a>&#160; (Ternary Content Addressable Memory). &#1048;&#1090;&#1086;&#1075;&#1086; FIB - &#1101;&#1090;&#1086; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1072;, &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1072;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;, &#1080;&#1089;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1081; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089; &#1080; L2 destination.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">(config)# no ip cef</font>&#160;// &#1075;&#1083;&#1086;&#1073;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084;&#1072; CEF (&#1085;&#1072; &#1074;&#1089;&#1077;&#1093; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072;&#1093;)
    </p>
    <p>
      <font color="#0000c0">&#160;&#160;&#160;(config-if)# no ip route-cache cef</font>&#160;// &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084;&#1072; CEF &#1085;&#1072; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1077;
    </p>
    <p>
      <font color="#0000c0"># show ip cef</font>&#160;// &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1099; &#1074; <b>CEF-&#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077;</b>&#160;(<b>FIB</b>&#160;- forwarding information base)
    </p>
    <p>
      <font color="#0000c0"># show adjacency</font>&#160;// &#1073;&#1083;&#1080;&#1078;&#1072;&#1081;&#1096;&#1080;&#1077; &#1089;&#1086;&#1089;&#1077;&#1076;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      &#1089;&#1084;. <a href="#ID_1907360751">&#1052;&#1077;&#1090;&#1086;&#1076;&#1099; &#1091;&#1089;&#1082;&#1086;&#1088;&#1077;&#1085;&#1080;&#1103; &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080;</a>
    </p>
  </body>
</html></richcontent>
</node>
</node>
