<node TEXT="IEEE 802" ID="ID_1085226498" CREATED="1519112080204" MODIFIED="1519112080204"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>IEEE 802</b>&#160;- &#1075;&#1088;&#1091;&#1087;&#1087;&#1072; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1086;&#1074; &#1089;&#1077;&#1084;&#1077;&#1081;&#1089;&#1090;&#1074;&#1072; IEEE, &#1082;&#1072;&#1089;&#1072;&#1102;&#1097;&#1080;&#1093;&#1089;&#1103; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1089;&#1077;&#1090;&#1077;&#1081; (LAN) &#1080; &#1089;&#1077;&#1090;&#1077;&#1081; &#1084;&#1077;&#1075;&#1072;&#1087;&#1086;&#1083;&#1080;&#1089;&#1086;&#1074; (MAN)
    </p>
    <p>
      
    </p>
    <p>
      IEEE 802.1&#160;&#160;&#160;&#160;&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1084;&#1080; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1084;&#1080; &#1080; &#1080;&#1093; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077;
    </p>
    <p>
      IEEE 802.2&#160;&#160;&#160;&#160;Logical Link Control (LLC)
    </p>
    <p>
