    <p>
      &#1069;&#1090;&#1086; &#1082;&#1086;&#1084;&#1087;&#1072;&#1082;&#1090;&#1085;&#1099;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;, &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1084;&#1099;&#1077; &#1074; &#1086;&#1073;&#1097;&#1077;&#1077; &#1096;&#1072;&#1089;&#1089;&#1080;. &#1064;&#1072;&#1089;&#1089;&#1080; &#1090;&#1072;&#1082;&#1078;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1090;&#1100;&#1089;&#1103; &#1074; 19-&#1076;&#1102;&#1084;&#1086;&#1074;&#1091;&#1102; &#1089;&#1090;&#1086;&#1081;&#1082;&#1091;. &#1042; &#1096;&#1072;&#1089;&#1089;&#1080; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1074;&#1083;&#1077;&#1079;&#1072;&#1077;&#1090; &#1086;&#1090; 10 &#1076;&#1086; 20 &#1073;&#1083;&#1077;&#1081;&#1076;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074;. &#1056;&#1072;&#1089;&#1089;&#1095;&#1080;&#1090;&#1072;&#1085;&#1099; &#1085;&#1072; &#1074;&#1099;&#1089;&#1086;&#1082;&#1091;&#1102; &#1087;&#1083;&#1086;&#1090;&#1085;&#1086;&#1089;&#1090;&#1100; &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1103;, &#1080;&#1084;&#1077;&#1102;&#1090; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1077;, &#1087;&#1086; &#1089;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1102; &#1089; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;&#1080; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074;, &#1101;&#1085;&#1077;&#1088;&#1075;&#1086;&#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1083;&#1077;&#1085;&#1080;&#1077;. &#1051;&#1077;&#1075;&#1082;&#1086; &#1084;&#1072;&#1089;&#1096;&#1090;&#1072;&#1073;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1080; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086; &#1088;&#1072;&#1079;&#1074;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1079;&#1072; &#1089;&#1095;&#1077;&#1090; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;&#1085;&#1086;&#1081; &#1080;&#1085;&#1092;&#1088;&#1072;&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1099;. &#1058;&#1072;&#1082;&#1080;&#1077; &#1084;&#1086;&#1076;&#1077;&#1083;&#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1074; &#1082;&#1086;&#1088;&#1087;&#1086;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1084; &#1089;&#1077;&#1075;&#1084;&#1077;&#1085;&#1090;&#1077;.
    </p>
    <ul>
      <li>
        &#1055;&#1083;&#1102;&#1089;&#1099;: &#1051;&#1077;&#1075;&#1082;&#1086;&#1089;&#1090;&#1100; &#1084;&#1072;&#1089;&#1096;&#1090;&#1072;&#1073;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;, &#1082;&#1086;&#1084;&#1087;&#1072;&#1082;&#1090;&#1085;&#1086;&#1089;&#1090;&#1100;, &#1101;&#1085;&#1077;&#1088;&#1075;&#1086;&#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1089;&#1090;&#1100; &#1080; &#1075;&#1080;&#1073;&#1082;&#1086;&#1089;&#1090;&#1100; &#1080;&#1085;&#1092;&#1088;&#1072;&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1099; &#1073;&#1083;&#1072;&#1075;&#1086;&#1076;&#1072;&#1088;&#1103; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1080;.
