    </ul>
    <p>
      <b>&#1052;&#1077;&#1081;&#1085;&#1092;&#1088;&#1077;&#1081;&#1084;</b>&#160;(&#1090;&#1072;&#1082;&#1078;&#1077; &#1084;&#1101;&#1081;&#1085;&#1092;&#1088;&#1077;&#1081;&#1084;, mainframe) - &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1091;&#1085;&#1080;&#1074;&#1077;&#1088;&#1089;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1086;&#1090;&#1082;&#1072;&#1079;&#1086;&#1091;&#1089;&#1090;&#1086;&#1081;&#1095;&#1080;&#1074;&#1099;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1089;&#1086; &#1079;&#1085;&#1072;&#1095;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084;&#1080; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1072;&#1084;&#1080; &#1074;&#1074;&#1086;&#1076;&#1072;-&#1074;&#1099;&#1074;&#1086;&#1076;&#1072;, &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084; &#1086;&#1073;&#1098;&#1105;&#1084;&#1086;&#1084; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1081; &#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;, &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074; &#1082;&#1088;&#1080;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1074;&#1072;&#1078;&#1085;&#1099;&#1093; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1093; &#1089; &#1080;&#1085;&#1090;&#1077;&#1085;&#1089;&#1080;&#1074;&#1085;&#1086;&#1081; &#1087;&#1072;&#1082;&#1077;&#1090;&#1085;&#1086;&#1081; &#1080; &#1086;&#1087;&#1077;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1086;&#1081; &#1090;&#1088;&#1072;&#1085;&#1079;&#1072;&#1082;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1081; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1086;&#1081;.
    </p>
    <p>
      &#1054;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1095;&#1080;&#1082; &#1084;&#1077;&#1081;&#1085;&#1092;&#1088;&#1077;&#1081;&#1084;&#1086;&#1074; &#8212; &#1082;&#1086;&#1088;&#1087;&#1086;&#1088;&#1072;&#1094;&#1080;&#1103; IBM, &#1042; &#1088;&#1072;&#1079;&#1085;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1084;&#1077;&#1081;&#1085;&#1092;&#1088;&#1077;&#1081;&#1084;&#1099; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1083;&#1080; Hitachi, Bull, Unisys, DEC, Honeywell, Burroughs, Siemens, Amdahl, Fujitsu, &#1074; &#1089;&#1090;&#1088;&#1072;&#1085;&#1072;&#1093; &#1057;&#1069;&#1042; &#1074;&#1099;&#1087;&#1091;&#1089;&#1082;&#1072;&#1083;&#1080;&#1089;&#1100; &#1084;&#1077;&#1081;&#1085;&#1092;&#1088;&#1077;&#1081;&#1084;&#1099; &#1045;&#1057; &#1069;&#1042;&#1052;.
    </p>
    <p>
      
    </p>
    <p>
      <b>Rig (&#1088;&#1080;&#1075; &#1076;&#1083;&#1103; &#1084;&#1072;&#1081;&#1085;&#1080;&#1085;&#1075;&#1072;)</b>&#160;- &#1086;&#1076;&#1080;&#1085; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1092;&#1077;&#1088;&#1084;&#1099;. &#1056;&#1080;&#1075; &#1076;&#1083;&#1103; &#1084;&#1072;&#1081;&#1085;&#1080;&#1085;&#1075;&#1072; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1074; &#1089;&#1077;&#1073;&#1103; &#1086;&#1076;&#1085;&#1091; &#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1091;&#1102; &#1077;&#1076;&#1080;&#1085;&#1080;&#1094;&#1091; &#1076;&#1083;&#1103; &#1076;&#1086;&#1073;&#1099;&#1095;&#1080;, &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1097;&#1091;&#1102; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1077; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099;: &#1084;&#1072;&#1090;&#1077;&#1088;&#1080;&#1085;&#1089;&#1082;&#1072;&#1103; &#1087;&#1083;&#1072;&#1090;&#1072; &#1089; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1086;&#1084; &#1080; &#1054;&#1047;&#1059;; &#1073;&#1083;&#1086;&#1082; (&#1073;&#1083;&#1086;&#1082;&#1080;) &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103;; &#1089;&#1090;&#1086;&#1081;&#1082;&#1072; &#1089; &#1079;&#1072;&#1082;&#1088;&#1077;&#1087;&#1083;&#1077;&#1085;&#1085;&#1099;&#1084;&#1080; &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1088;&#1090;&#1072;&#1084;&#1080;. &#1053;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1088;&#1080;&#1075;&#1086;&#1074; &#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1102;&#1090; &#1090;&#1072;&#1082; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084;&#1091;&#1102; &#171;&#1092;&#1077;&#1088;&#1084;&#1091;&#187;, &#1072; &#1092;&#1077;&#1088;&#1084;&#1072; &#1080;&#1079; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1075;&#1086; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1072; &#1088;&#1080;&#1075;&#1086;&#1074; &#1080;&#1084;&#10