        <b>&#1076;&#1083;&#1080;&#1085;&#1072; &#1092;&#1088;&#1077;&#1086;&#1085;&#1086;&#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1086;&#1074;:</b>&#160;&#1076;&#1083;&#1103; &#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1072;&#1090;&#1100; 50 &#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1087;&#1086; &#1075;&#1086;&#1088;&#1080;&#1079;&#1086;&#1085;&#1090;&#1072;&#1083;&#1080;, &#1077;&#1089;&#1083;&#1080; &#1077;&#1089;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1087;&#1072;&#1076; &#1074;&#1099;&#1089;&#1086;&#1090; &#8211; &#1077;&#1097;&#1077; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077;. &#1057; &#1084;&#1085;&#1086;&#1075;&#1086;&#1101;&#1090;&#1072;&#1078;&#1085;&#1099;&#1084; &#1076;&#1072;&#1090;&#1072;-&#1094;&#1077;&#1085;&#1090;&#1088;&#1086;&#1084; &#1089;&#1083;&#1086;&#1078;&#1085;&#1086; &#1091;&#1083;&#1086;&#1078;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; &#1101;&#1090;&#1080; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103;
