<node TEXT="Kyoto Cooling" ID="ID_797936132" CREATED="1544516821076" MODIFIED="1544517306749"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Kyoto Cooling.</b>&#160;&#1069;&#1090;&#1086; &#1076;&#1074;&#1091;&#1093;&#1082;&#1086;&#1085;&#1090;&#1091;&#1088;&#1085;&#1072;&#1103; &#1089;&#1093;&#1077;&#1084;&#1072; &#1089; &#1077;&#1089;&#1090;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1084; &#1074;&#1086;&#1079;&#1076;&#1091;&#1096;&#1085;&#1099;&#1084; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077;&#1084; (&#1092;&#1088;&#1080;&#1082;&#1091;&#1083;&#1080;&#1085;&#1075;&#1086;&#1084;). &#1042;&#1086; &#1074;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1077;&#1084; &#1082;&#1086;&#1085;&#1090;&#1091;&#1088;&#1077; &#1094;&#1080;&#1088;&#1082;&#1091;&#1083;&#1080;&#1088;&#1091;&#1077;&#1090; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093; &#1076;&#1072;&#1090;&#1072;-&#1094;&#1077;&#1085;&#1090;&#1088;&#1072;, &#1072; &#1074; &#1085;&#1072;&#1088;&#1091;&#1078;&#1085;&#1099;&#1081; &#1082;&#1086;&#1085;&#1090;&#1091;&#1088; &#1087;&#1086;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1091;&#1083;&#1080;&#1095;&#1085;&#1099;&#1081; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;. &#1042; &#1090;&#1077;&#1087;&#1083;&#1086;&#1086;&#1073;&#1084;&#1077;&#1085;&#1085;&#1080;&#1082;&#1077;-&#1088;&#1077;&#1082;&#1091;&#1087;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1077; &#1088;&#1086;&#1090;&#1086;&#1088;&#1085;&#1086;&#1075;&#1086; &#1090;&#1080;&#1087;&#1072;, &#1080;&#1083;&#1080; &#171;&#1082;&#1086;&#1083;&#1077;&#1089;&#1077;&#187;, &#1075;&#1086;&#1088;&#1103;&#1095;&#1080;&#1081; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093; &#1086;&#1090; &#1048;&#1058;-&#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072; &#1089;&#1095;&#1077;&#1090; &#1091;&#1083;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1072;. &#1042; &#1088;&#1072;&#1073;&#1086;&#1090;&#1077; Kyoto Cooling &#1085;&#1077; &#1091;&#1095;&#1072;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1082;&#1086;&#1084;&#1087;&#1088;&#1077;&#1089;&#1089;&#1086;&#1088;&#1099; (&#1090;&#1086; &#1089;&#1072;&#1084;&#1086;&#1077; &#1077;&#1089;&#1090;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1077; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077;) &#1087;&#1088;&#1080; &#1085;&#1080;&#1079;&#1082;&#1080;&#1093; &#1091;&#1083;&#1080;&#1095;&#1085;&#1099;&#1093; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1072;&#1093;.
    </p>
    <p>
      <b>&#1055;&#1088;&#1080;&#1085;&#1094;&#1080;&#1087; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; Kyoto Cooling. </b>&#1069;&#1090;&#1086;&#1090; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090; &#1087;&#1086;&#1076;&#1082;&#1091;&#1087;&#1072;&#1083; &#1089;&#1074;&#1086;&#1077;&#1081; <b>&#1101;&#1085;&#1077;&#1088;&#1075;&#1086;&#1101;&#1092;&#1092;&#1077;&#1082;&#1090;&#1080;&#1074;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;:</b>
    </p>
    <ul>
      <li>
        &#1074; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1092;&#1088;&#1080;&#1082;&#1091;&#1083;&#1080;&#1085;&#1075;&#1072; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1087;&#1088;&#1080;&#1074;&#1086;&#1076; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1074;&#1080;&#1075;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1074;&#1077;&#1085;&#1090;&#1080;&#1083;&#1103;&#1090;&#1086;&#1088;&#1086;&#1074;. &#1044;&#1072;&#1090;&#1072;-&#1094;&#1077;&#1085;&#1090;&#1088;&#1099;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1077; &#1101;&#1090;&#1091; &#1089;&#1093;&#1077;&#1084;&#1091;, &#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1086;&#1093;&#1074;&#1072;&#1089;&#1090;&#1072;&#1090;&#1100;&#1089;&#1103; &#1086;&#1076;&#1085;&#1080;&#1084; &#1080;&#1079; &#1089;&#1072;&#1084;&#1099;&#1093; &#1085;&#1080;&#1079;&#1082;&#1080;&#1093; PUE &#8211; 1,09&#8211;1,13
      </li>
      <li>
        &#1042; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; &#1095;&#1080;&#1083;&#1083;&#1077;&#1088;&#1085;&#1086;&#1081; &#1089;&#1093;&#1077;&#1084;&#1099;, Kyoto Cooling &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1073;&#1077;&#1079; &#1074;&#1086;&#1076;&#1099;, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1085;&#1077;&#1090; &#1088;&#1080;&#1089;&#1082;&#1072; &#1087;&#1088;&#1086;&#1090;&#1077;&#1095;&#1077;&#1082;
      </li>
    </ul>
    <p>
      &#1042; &#1090;&#1086; &#1078;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; Kyoto Cooling &#1087;&#1088;&#1077;&#1076;&#1098;&#1103;&#1074;&#1083;&#1103;&#1083;&#1072; &#1089;&#1087;&#1077;&#1094;&#1080;&#1092;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; <b>&#1090;&#1088;&#1077;&#1073;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1082; &#1087;&#1083;&#1072;&#1085;&#1080;&#1088;&#1086;&#1074;&#1082;&#1077; &#1079;&#1076;&#1072;&#1085;&#1080;&#1103;:</b>
    </p>
    <ul>
      <li>
        &#1090;&#1077;&#1087;&#1083;&#1086;&#1086;&#1073;&#1084;&#1077;&#1085;&#1085;&#1080;&#1082; &#171;&#1082;&#1086;&#1083;&#1077;&#1089;&#1086;&#187; &#1089;&#1086; &#1074;&#1089;&#1077;&#1084;&#1080; &#1074;&#1077;&#1085;&#1090;&#1080;&#1083;&#1103;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1084;&#1080; &#1082;&#1072;&#1084;&#1077;&#1088;&#1072;&#1084;&#1080; &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1084;&#1085;&#1086;&#1075;&#1086; &#1084;&#1077;&#1089;&#1090;&#1072;. &#1060;&#1072;&#1082;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1087;&#1086;&#1076; &#1085;&#1077;&#1075;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1090;&#1077;&#1093;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1077; &#1087;&#1086;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1089;&#1083;&#1086;&#1078;&#1085;&#1086; &#1074;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1074; &#1075;&#1086;&#1090;&#1086;&#1074;&#1099;&#1081; &#1087;&#1088;&#1086;&#1077;&#1082;&#1090; &#1079;&#1076;&#1072;&#1085;&#1080;&#1103;
      </li>
      <li>
        &#1091; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1072; &#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1072;&#1103; &#1090;&#1077;&#1087;&#1083;&#1086;&#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100;: &#1095;&#1090;&#1086;&#1073;&#1099; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1100; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1086;&#1073;&#1098;&#1077;&#1084; &#1090;&#1077;&#1087;&#1083;&#1072;, &#1085;&#1091;&#1078;&#1085;&#1099; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1077; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1086;&#1074;&#1086;&#1076;&#1099;. &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1102; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1086;&#1074;&#1086;&#1076;&#1086;&#1074; &#1084;&#1086;&#1075;&#1091;&#1090; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100; &#1082;&#1086;&#1088;&#1080;&#1076;&#1086;&#1088;&#1099;, &#1085;&#1086; &#1101;&#1090;&#1086; &#1086;&#1087;&#1103;&#1090;&#1100;-&#1090;&#1072;&#1082;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1077;&#1076;&#1091;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1085;&#1072; &#1101;&#1090;&#1072;&#1087;&#1077; &#1087;&#1088;&#1086;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1079;&#1076;&#1072;&#1085;&#1080;&#1103;
      </li>
      <li>
        &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1084;&#1072;&#1096;&#1080;&#1085;&#1085;&#1086;&#1075;&#1086; &#1079;&#1072;&#1083;&#1072; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1080;&#1079;&#1086;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1075;&#1086;&#1088;&#1103;&#1095;&#1080;&#1077; &#1082;&#1086;&#1088;&#1080;&#1076;&#1086;&#1088;&#1099;. &#1069;&#1090;&#1086; &#1089;&#1083;&#1086;&#1078;&#1085;&#1086; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1089;&#1090;&#1086;&#1081;&#1082;&#1080; &#1088;&#1072;&#1079;&#1085;&#1086;&#1082;&#1072;&#1083;&#1080;&#1073;&#1077;&#1088;&#1085;&#1099;&#1077; &#1080; &#1079;&#1072;&#1083; &#1079;&#1072;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1089;&#1090;&#1077;&#1087;&#1077;&#1085;&#1085;&#1086;
      </li>
      <li>
        &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1099; &#1085;&#1072; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1099;. &#1059;&#1083;&#1080;&#1095;&#1085;&#1099;&#1081; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1090; &#1085;&#1072; &#1082;&#1086;&#1083;&#1077;&#1089;&#1086;, &#1085;&#1091;&#1078;&#1085;&#1086; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1080;&#1085;&#1072;&#1095;&#1077; &#1087;&#1099;&#1083;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1086;&#1087;&#1072;&#1076;&#1072;&#1090;&#1100; &#1074; &#1084;&#1072;&#1096;&#1080;&#1085;&#1085;&#1099;&#1077; &#1079;&#1072;&#1083;&#1099;
      </li>
    </ul>
    <p>
      &#1055;&#1086; &#1089;&#1090;&#1086;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1083;&#1072;&#1089;&#1100; &#1076;&#1086;&#1088;&#1086;&#1075;&#1086;&#1081;. &#1063;&#1090;&#1086;&#1073;&#1099; Kyoto Cooling &#1089;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1083;&#1089;&#1103; &#1089; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077;&#1084; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1072; &#1089;&#1095;&#1077;&#1090; &#1091;&#1083;&#1080;&#1095;&#1085;&#1086;&#1075;&#1086; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1072;, &#1085;&#1072; &#1091;&#1083;&#1080;&#1094;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1085;&#1077; &#1078;&#1072;&#1088;&#1095;&#1077; 25 &#176;&#1057;.
    </p>
  </body>
</html></richcontent>
