<node TEXT="Чиллер-фанкойл" ID="ID_268318145" CREATED="1544516986687" MODIFIED="1544519084979"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1063;&#1080;&#1083;&#1083;&#1077;&#1088;-&#1092;&#1072;&#1085;&#1082;&#1086;&#1081;&#1083;.&#160;&#1044;&#1074;&#1091;&#1093;&#1082;&#1086;&#1085;&#1090;&#1091;&#1088;&#1085;&#1072;&#1103; &#1095;&#1080;&#1083;&#1083;&#1077;&#1088;&#1085;&#1072;&#1103; &#1089;&#1093;&#1077;&#1084;&#1072;</b>&#160; &#1085;&#1072; &#1101;&#1090;&#1080;&#1083;&#1077;&#1085;&#1075;&#1083;&#1080;&#1082;&#1086;&#1083;&#1077; &#1080; &#1074;&#1086;&#1076;&#1077;. &#1042;&#1085;&#1077;&#1096;&#1085;&#1080;&#1081; &#1082;&#1086;&#1085;&#1090;&#1091;&#1088; &#1089; &#1085;&#1077;&#1079;&#1072;&#1084;&#1077;&#1088;&#1079;&#1072;&#1102;&#1097;&#1080;&#1084; &#1088;&#1072;&#1089;&#1090;&#1074;&#1086;&#1088;&#1086;&#1084; &#1101;&#1090;&#1080;&#1083;&#1077;&#1085;&#1075;&#1083;&#1080;&#1082;&#1086;&#1083;&#1103; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1077;&#1090; &#1095;&#1080;&#1083;&#1083;&#1077;&#1088;&#1099; &#1080; &#1090;&#1077;&#1087;&#1083;&#1086;&#1086;&#1073;&#1084;&#1077;&#1085;&#1085;&#1080;&#1082;. &#1042;&#1085;&#1091;&#1090;&#1088;&#1077;&#1085;&#1085;&#1080;&#1081; &#1082;&#1086;&#1085;&#1090;&#1091;&#1088; &#1089; &#1074;&#1086;&#1076;&#1086;&#1081; &#1080;&#1076;&#1077;&#1090; &#1086;&#1090; &#1090;&#1077;&#1087;&#1083;&#1086;&#1086;&#1073;&#1084;&#1077;&#1085;&#1085;&#1080;&#1082;&#1072; &#1082; &#1096;&#1082;&#1072;&#1092;&#1085;&#1099;&#1084; &#1082;&#1086;&#1085;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1077;&#1088;&#1072;&#1084;. &#1058;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;, &#1074;&#1086;&#1079;&#1076;&#1091;&#1093; &#1074; &#1084;&#1072;&#1096;&#1080;&#1085;&#1085;&#1099;&#1093; &#1079;&#1072;&#1083;&#1072;&#1093; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1090;&#1077;&#1087;&#1083;&#1086;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1077;&#1081; &#8211; &#1074;&#1086;&#1076;&#1099; &#1080; &#1088;&#1072;&#1089;&#1090;&#1074;&#1086;&#1088;&#1072; &#1101;&#1090;&#1080;&#1083;&#1077;&#1085;&#1075;&#1083;&#1080;&#1082;&#1086;&#1083;&#1103;.
    </p>
    <ul>
      <li>
        &#1042;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1077;&#1089;&#1090;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1074; &#1093;&#1086;&#1083;&#1086;&#1076;&#1085;&#1086;&#1077; &#1074;&#1088;&#1077;&#1084;&#1103; &#1075;&#1086;&#1076;&#1072; &#8211; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1077; &#1087;&#1088;&#1077;&#1080;&#1084;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1086; &#1101;&#1090;&#1086;&#1081; &#1089;&#1093;&#1077;&#1084;&#1099;. &#1055;&#1088;&#1080; <b>&#1092;&#1088;&#1080;&#1082;&#1091;&#1083;&#1080;&#1085;&#1075;&#1077;</b>&#160; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1088;&#1072;&#1089;&#1093;&#1086;&#1076;&#1091;&#1102;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1074;&#1077;&#1085;&#1090;&#1080;&#1083;&#1103;&#1090;&#1086;&#1088;&#1099; &#1080; &#1085;&#1072;&#1089;&#1086;&#1089;&#1099;. &#1050;&#1086;&#1084;&#1087;&#1088;&#1077;&#1089;&#1089;&#1086;&#1088;&#1099;, &#1089;&#1072;&#1084;&#1099;&#1081; &#171;&#1087;&#1088;&#1086;&#1078;&#1086;&#1088;&#1083;&#1080;&#1074;&#1099;&#1081;&#187; &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;, &#1089;&#1090;&#1086;&#1103;&#1090; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1084;&#1080;
      </li>
      <li>
        &#1055;&#1088;&#1080; &#1087;&#1086;&#1083;&#1085;&#1086;&#1081; &#1087;&#1088;&#1086;&#1077;&#1082;&#1090;&#1085;&#1086;&#1081; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1076;&#1072;&#1090;&#1072;-&#1094;&#1077;&#1085;&#1090;&#1088;&#1072; &#1089;&#1088;&#1077;&#1076;&#1085;&#1077;&#1075;&#1086;&#1076;&#1086;&#1074;&#1086;&#1081; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; PUE (&#171;&#1087;&#1086; &#1093;&#1086;&#1083;&#1086;&#1076;&#1091;&#187;) &#1089;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090; &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; 1,21
      </li>
      <li>
        <p>
          <b>&#1042;&#1086;&#1076;&#1072; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1081; &#1089;&#1093;&#1077;&#1084;&#1077;.</b>&#160; &#1063;&#1080;&#1083;&#1083;&#1077;&#1088; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1072;&#1077;&#1090; &#1075;&#1083;&#1080;&#1082;&#1086;&#1083;&#1100;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1077;&#1090; &#1074; &#1090;&#1077;&#1087;&#1083;&#1086;&#1086;&#1073;&#1084;&#1077;&#1085;&#1085;&#1080;&#1082;. &#1047;&#1072; &#1089;&#1095;&#1077;&#1090; &#1093;&#1086;&#1083;&#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1075;&#1083;&#1080;&#1082;&#1086;&#1083;&#1103; &#1074; &#1090;&#1077;&#1087;&#1083;&#1086;&#1086;&#1073;&#1084;&#1077;&#1085;&#1085;&#1080;&#1082;&#1077; &#1090;&#1077;&#1087;&#1083;&#1072;&#1103; &#1074;&#1086;&#1076;&#1072; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103;. &#1055;&#1086;&#1089;&#1083;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1072;&#1082; &#1074;&#1086;&#1076;&#1072; &#1080; &#1075;&#1083;&#1080;&#1082;&#1086;&#1083;&#1100; &#171;&#1086;&#1073;&#1084;&#1077;&#1085;&#1103;&#1083;&#1080;&#1089;&#1100;&#187; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1072;&#1084;&#1080;, &#1074;&#1086;&#1076;&#1072; &#1080;&#1076;&#1077;&#1090; &#1074; &#1082;&#1086;&#1085;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1077;&#1088;&#1099; &#1074; &#1079;&#1072;&#1083;&#1072;&#1093;, &#1072; &#1075;&#1083;&#1080;&#1082;&#1086;&#1083;&#1100; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1095;&#1080;&#1083;&#1083;&#1077;&#1088;.
        </p>
      </li>
    </ul>
    <p>
      <b>&#1063;&#1080;&#1083;&#1083;&#1077;&#1088;</b>&#160;(&#1042;&#1086;&#1076;&#1086;&#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1072;&#1102;&#1097;&#1072;&#1103; &#1084;&#1072;&#1096;&#1080;&#1085;&#1072;) - &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090; &#1076;&#1083;&#1103; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1078;&#1080;&#1076;&#1082;&#1086;&#1089;&#1090;&#1080;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1097;&#1080;&#1081; &#1055;&#1072;&#1088;&#1086;&#1082;&#1086;&#1084;&#1087;&#1088;&#1077;&#1089;&#1089;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1080;&#1083;&#1080; &#1072;&#1073;&#1089;&#1086;&#1088;&#1073;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1081; &#1093;&#1086;&#1083;&#1086;&#1076;&#1080;&#1083;&#1100;&#1085;&#1099;&#1081; &#1094;&#1080;&#1082;&#1083;. &#1055;&#1086;&#1089;&#1083;&#1077; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1074; &#1095;&#1080;&#1083;&#1083;&#1077;&#1088;&#1077; &#1078;&#1080;&#1076;&#1082;&#1086;&#1089;&#1090;&#1100; &#1084;&#1086;&#1078;&#1077;&#1090; &#1087;&#1086;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1074; &#1090;&#1077;&#1087;&#1083;&#1086;&#1086;&#1073;&#1084;&#1077;&#1085;&#1085;&#1080;&#1082;&#1080; &#1076;&#1083;&#1103; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1072; (&#1092;&#1072;&#1085;&#1082;&#1086;&#1081;&#1083;&#1099;) &#1080;&#1083;&#1080; &#1076;&#1083;&#1103; &#1086;&#1090;&#1074;&#1086;&#1076;&#1072; &#1090;&#1077;&#1087;&#1083;&#1072; &#1086;&#1090; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;. &#1042; &#1093;&#1086;&#1076;&#1077; &#1086;&#1093;&#1083;&#1072;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; &#1078;&#1080;&#1076;&#1082;&#1086;&#1089;&#1090;&#1080; &#1095;&#1080;&#1083;&#1083;&#1077;&#1088; &#1089;&#1086;&#1079;&#1076;&#1072;&#1105;&#1090; &#1080;&#1079;&#1073;&#1099;&#1090;&#1086;&#1095;&#1085;&#1086;&#1077; &#1090;&#1077;&#1087;&#1083;&#1086;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1086;&#1090;&#1074;&#1077;&#1076;&#1077;&#1085;&#1086; &#1074; &#1086;&#1082;&#1088;&#1091;&#1078;&#1072;&#1102;&#1097;&#1091;&#1102; &#1089;&#1088;&#1077;&#1076;&#1091;. &#1056;&#1072;&#1073;&#1086;&#1090;&#1072; &#1074; &#1087;&#1072;&#1088;&#1077; &#1089; &#1092;&#1072;&#1085;&#1082;&#1086;&#1081;&#1083;&#1086;&#1084; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1072;&#1093; &#1082;&#1086;&#1085;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1095;&#1072;&#1089;&#1090;&#1085;&#1099;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1103;&#1084; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1095;&#1080;&#1083;&#1083;&#1077;&#1088;&#1086;&#1074;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1050;&#1086;&#1085;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1077;&#1088;</b>&#160; - &#1058;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1072; &#1074;&#1086;&#1076;&#1099; &#1085;&#1072; &#1074;&#1093;&#1086;&#1076;&#1077; &#1074; &#1082;&#1086;&#1085;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1077;&#1088; 18 &#176;&#1057;, &#1085;&#1072; &#1074;&#1099;&#1093;&#1086;&#1076;&#1077; &#8211; 24 &#176;&#1057;. &#1041;&#1083;&#1072;&#1075;&#1086;&#1076;&#1072;&#1088;&#1103; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1081; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1077; &#1090;&#1077;&#1087;&#1083;&#1086;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1103; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077; &#1082;&#1086;&#1085;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1077;&#1088;&#1099; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1074;&#1099;&#1096;&#1077; &#1090;&#1086;&#1095;&#1082;&#1080; &#1088;&#1086;&#1089;&#1099;, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1085;&#1077; &#1090;&#1088;&#1072;&#1090;&#1080;&#1090;&#1089;&#1103; &#1083;&#1080;&#1096;&#1085;&#1103;&#1103; &#1101;&#1085;&#1077;&#1088;&#1075;&#1080;&#1103; &#1085;&#1072; &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1094;&#1080;&#1102; &#1074;&#1083;&#1072;&#1075;&#1080; &#1080; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1077;&#1077; &#1091;&#1074;&#1083;&#1072;&#1078;&#1085;&#1077;&#1085;&#1080;&#1077; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1072;.
    </p>
  </body>
</html></richcontent>
