<node TEXT="ERD Commander (ERDC)" ID="ID_83084896" CREATED="1519112080356" MODIFIED="1519112080356"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>ERD (Emergency Repair Disk)</b>&#160;- &#1076;&#1080;&#1089;&#1082; &#1072;&#1074;&#1072;&#1088;&#1080;&#1081;&#1085;&#1086;&#1075;&#1086; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;. ERD Commander - &#1101;&#1090;&#1086; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1086;&#1095;&#1085;&#1099;&#1081; &#1076;&#1080;&#1089;&#1082; &#1089; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1086;&#1081; Windows PE, &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084;&#1086;&#1081; &#1089;&#1086; &#1089;&#1084;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1103; (CD/DVD, &#1092;&#1083;&#1101;&#1096;&#1082;&#1080; &#1080;&#1083;&#1080; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1075;&#1086; USB &#1076;&#1080;&#1089;&#1082;&#1072;) , &#1087;&#1083;&#1102;&#1089; &#1085;&#1072;&#1073;&#1086;&#1088; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1085;&#1099;&#1093; &#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074; &#1076;&#1083;&#1103; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103; <b>&#1088;&#1072;&#1073;&#1086;&#1090;&#1086;&#1089;&#1087;&#1086;&#1089;&#1086;&#1073;&#1085;&#1086;&#1089;&#1090;&#1080; Windows</b>
    </p>
    <ul>
      <li>
        &#1052;&#1072;&#1089;&#1090;&#1077;&#1088; &#1089;&#1073;&#1086;&#1088;&#1082;&#1080; Microsoft Diagnostics and Recovery Toolset (<b>MS DaRT</b>) &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1086;&#1095;&#1085;&#1099;&#1081; &#1086;&#1073;&#1088;&#1072;&#1079; DaRT (&#1074; &#1085;&#1072;&#1088;&#1086;&#1076;&#1077; - <b>ERD Commander</b>)
      </li>
    </ul>
    <p>
