<node TEXT="Zalman (IODD)" FOLDED="true" ID="ID_276670737" CREATED="1519112080357" MODIFIED="1519112080357"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1057;&#1090;&#1088;&#1086;&#1075;&#1086; &#1075;&#1086;&#1074;&#1086;&#1088;&#1103;, Zalman &#1085;&#1077; &#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1074;&#1099;&#1087;&#1091;&#1089;&#1090;&#1080;&#1083;&#1072; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086; &#1101;&#1090;&#1086; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1080; &#1074;&#1086;&#1086;&#1073;&#1097;&#1077; &#1074;&#1089;&#1102; &#1083;&#1080;&#1085;&#1077;&#1081;&#1082;&#1091;. &#1055;&#1077;&#1088;&#1074;&#1077;&#1085;&#1089;&#1090;&#1074;&#1086; &#1079;&#1076;&#1077;&#1089;&#1100; &#1087;&#1088;&#1080;&#1085;&#1072;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090; &#1082;&#1086;&#1088;&#1077;&#1081;&#1089;&#1082;&#1086;&#1081; &#1092;&#1080;&#1088;&#1084;&#1077; iODD. Zalman &#1083;&#1080;&#1096;&#1100; &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1083;&#1072; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1080;, &#1085;&#1086; &#1073;&#1083;&#1072;&#1075;&#1086;&#1076;&#1072;&#1088;&#1103; &#1101;&#1090;&#1086;&#1084;&#1091; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1089;&#1084;&#1086;&#1075;&#1083;&#1086; &#1074;&#1099;&#1081;&#1090;&#1080; &#1085;&#1072; &#1082;&#1086;&#1084;&#1084;&#1077;&#1088;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1088;&#1077;&#1083;&#1100;&#1089;&#1099; &#1079;&#1072; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1099; &#1050;&#1086;&#1088;&#1077;&#1080;. &#1054;&#1088;&#1080;&#1075;&#1080;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1085;&#1086;&#1089;&#1080;&#1090; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; iODD2531 &#1080; &#1085;&#1080;&#1095;&#1077;&#1084;, &#1082;&#1088;&#1086;&#1084;&#1077; &#1073;&#1088;&#1077;&#1085;&#1076;&#1072; iODD &#1085;&#1072; &#1082;&#1086;&#1088;&#1087;&#1091;&#1089;&#1077; &#1080; &#1082;&#1086;&#1088;&#1086;&#1073;&#1082;&#1077; &#1085;&#1077; &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103;.
    </p>
    <p>
      <b>Zalman ZM-VE300</b>. &#1053;&#1080;&#1082;&#1072;&#1082;&#1086;&#1081; &#1074;&#1086;&#1079;&#1100;&#1085;&#1080; &#1089; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1095;&#1080;&#1082;&#1072;&#1084;&#1080;, &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1103;&#1084;&#1080; &#1080; &#1074;&#1089;&#1077;&#1084; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084;, &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1082;&#1083;&#1072;&#1076;&#1077;&#1090;&#1077; &#1086;&#1073;&#1088;&#1072;&#1079; &#1074; &#1087;&#1072;&#1087;&#1082;&#1091; _ISO &#1085;&#1072; &#1087;&#1077;&#1088;&#1074;&#1086;&#1084; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077; &#1080; &#1074;&#1089;&#1077;. &#1055;&#1083;&#1102;&#1089; &#1085;&#1072; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1099; &#1076;&#1080;&#1089;&#1082;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1085;&#1086;&#1094;&#1077;&#1085;&#1085;&#1099;&#1081; Linux &#1089; &#1090;&#1077;&#1084;&#1080; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072;&#1084;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1091;&#1078;&#1085;&#1099; &#1080;&#1084;&#1077;&#1085;&#1085;&#1086; &#1074;&#1072;&#1084;.
    </p>
    <p>
      &#1055;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;. Zalman <b>ZM-VE200/300/400</b>&#160; &#1080; &#1085;&#1080;&#1082;&#1072;&#1082;&#1080;&#1093; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;. &#1044;&#1072; &#1080; &#1085;&#1077;&#1090; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1089;&#1086;&#1073;&#1080;&#1088;&#1072;&#1090;&#1100; &#1092;&#1083;&#1077;&#1096;&#1082;&#1091;. &#1047;&#1072;&#1084;&#1077;&#1085;&#1080;&#1083; &#1091;&#1089;&#1090;&#1072;&#1088;&#1077;&#1074;&#1096;&#1080;&#1081; &#1080;&#1089;&#1086;&#1096;&#1085;&#1080;&#1082; &#1082;&#1072;&#1082;&#1086;&#1081;-&#1083;&#1080;&#1073;&#1086; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099;(&#1085;&#1072;&#1073;&#1086;&#1088;&#1072; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;) &#1085;&#1072; &#1085;&#1086;&#1074;&#1099;&#1081; &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; _ISO &#1080; &#1074;&#1089;&#1077;. &#1044;&#1072; &#1080; &#1076;&#1077;&#1096;&#1077;&#1074;&#1083;&#1077; &#1074;&#1099;&#1093;&#1086;&#1076;&#1080;&#1090; &#1085;&#1072;&#1084;&#1085;&#1086;&#1075;&#1086;. &#1053;&#1072; &#1061;&#1044;&#1044; &#1074; &#1090;&#1072;&#1082;&#1086;&#1084; &#1073;&#1086;&#1082;&#1089;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1087;&#1080;&#1093;&#1085;&#1091;&#1090;&#1100; &#1074;&#1089;&#1077; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1077; &#1086;&#1073;&#1088;&#1072;&#1079;&#1099; (&#1085;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1090;&#1077;, &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1085;&#1072;&#1076;&#1086; &#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100;&#1089;&#1103;), &#1074;&#1089;&#1077; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1099;&#1077; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1099; &#1080; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1072;.
    </p>
    <p>
      +1 &#1057;&#1082;&#1086;&#1088;&#1086;&#1089;&#1090;&#1100;. &#1057;&#1072;&#1084;&#1099;&#1081; &#1075;&#1083;&#1072;&#1074;&#1085;&#1099;&#1081; &#1082;&#1088;&#1080;&#1090;&#1077;&#1088;&#1080;&#1081; &#1087;&#1086;&#1089;&#1083;&#1077; &#1091;&#1076;&#1086;&#1073;&#1089;&#1090;&#1074;&#1072;. &#1054;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086; &#1077;&#1089;&#1083;&#1080; &#1074; Zalman &#1087;&#1086;&#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; SSD. &#1053;&#1086; &#1079;&#1072;&#1083;&#1084;&#1072;&#1085;, &#1101;&#1090;&#1086; &#1076;&#1083;&#1103; &#1089;&#1077;&#1073;&#1103; &#1076;&#1083;&#1103; &#1076;&#1091;&#1096;&#1080;, &#1072; &#1076;&#1083;&#1103; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1087;&#1088;&#1072;&#1082;&#1090;&#1080;&#1095;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; 3-5 &#1092;&#1083;&#1077;&#1096;&#1077;&#1082;:
    </p>
    <p>
      
