<node TEXT="Сброс BIOS" ID="ID_321789745" CREATED="1519112079652" MODIFIED="1579684821741"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1072;&#1088;&#1086;&#1083;&#1100; &#1074; CMOS</b>
    </p>
    <ul>
      <li>
        <b>&#1042;&#1099;&#1090;&#1072;&#1097;&#1080;&#1090;&#1100; &#1073;&#1072;&#1090;&#1072;&#1088;&#1077;&#1081;&#1082;&#1091;</b>&#160;&#1085;&#1072; 5-7 &#1089;&#1077;&#1082;.
      </li>
      <li>
        <b>&#1047;&#1072;&#1082;&#1086;&#1088;&#1086;&#1090;&#1080;&#1090;&#1100;</b>&#160;&#1082;&#1086;&#1085;&#1090;&#1072;&#1082;&#1090;&#1099; <b>CLR_CMOS (&#1047;&#1072;&#1084;&#1082;&#1085;&#1080;&#1090;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1099;&#1095;&#1082;&#1086;&#1081; (&#1076;&#1078;&#1072;&#1084;&#1087;&#1077;&#1088;&#1086;&#1084;) &#1074;&#1090;&#1086;&#1088;&#1091;&#1102; &#1087;&#1072;&#1088;&#1091; &#1082;&#1086;&#1085;&#1090;&#1072;&#1082;&#1090;&#1086;&#1074;)</b>&#160;&#1085;&#1072; 5-7 &#1089;&#1077;&#1082;., &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1073;&#1072;&#1090;&#1072;&#1088;&#1077;&#1081;&#1082;&#1072; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1089;&#1074;&#1086;&#1077;&#1084; &#1084;&#1077;&#1089;&#1090;&#1077;, &#1072; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077; &#1055;&#1050; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1086;.
      </li>
      <li>
        &#1080;&#1085;&#1078;&#1077;&#1085;&#1077;&#1088;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;. &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1072;&#1088;&#1086;&#1083;&#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; BIOS &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; 4,55G &#1080; &#1085;&#1080;&#1078;&#1077; (&#1082;&#1083;&#1072;&#1089;&#1089; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1099;&#1093; &#1087;&#1083;&#1072;&#1090; &#1076;&#1086; i845P &#1095;&#1080;&#1087;&#1089;&#1077;&#1090;&#1072;) (&#1089;&#1090;&#1072;&#1088;&#1100;&#1077;, &#1085;&#1086; &#1074;&#1076;&#1088;&#1091;&#1075;): <b>AWARD</b>: 01322222 589589 589721 595595 ALFAROME Ally ALLY aLLy aPAf AWARD PW AWARD SW AWARD_SW Awkward BIOSTAR CONCAT Condo d8on HLT J262 J332 J64 Lkwpeter LKWPETER Pint PINT SER SKY_FOX SYXZ TTPTHA ZJAAADC;&#160;j256;ZBAAACA; ZAAADA; jo9F; KDD; g6PJ; t0cH88; TzqF; Wodj; 1EEAAh.
      </li>
      <li>
        <b>&#1080;&#1085;&#1078;&#1077;&#1085;&#1077;&#1088;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100; &#1076;&#1083;&#1103; AMI:</b>&#160;A.M.I. AAAMMMIII AMI AMI?SW AMI_SW BIOS CONDO HEWINTT RAND LKWPETER PASSWORD SER&#160;CTRL+ALT+DEL+INSERT &#1080;&#1085;&#1086;&#1075;&#1076;&#1072; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; INSERT
      </li>
      <li>
        &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100;&#1089;&#1103; &#1074; &#1089;&#1088;&#1077;&#1076;&#1091; DOS (&#1095;&#1080;&#1089;&#1090;&#1091;&#1102; DOS, &#1072; &#1085;&#1077; &#1101;&#1084;&#1091;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1091;&#1102; &#1080;&#1079;-&#1087;&#1086;&#1076; Windows) &#1080; &#1074;&#1074;&#1077;&#1089;&#1090;&#1080; &#1090;&#1072;&#1082;&#1080;&#1077; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1099;: <b>AWARD &#1080; AMI BIOS</b>: DEBUG &gt; -O 70 17 &gt; -O 71 17 &gt; Q <b>Phoenix BIOS</b>: DEBUG &gt; -O 70 FF &gt; -O 71 FF &gt; Q
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1079;&#1072;&#1090;&#1088;&#1091;&#1076;&#1085;&#1077;&#1085; &#1075;&#1072;&#1088;&#1072;&#1085;&#1090;&#1080;&#1081;&#1085;&#1099;&#1084; &#1089;&#1090;&#1080;&#1082;&#1077;&#1088;&#1086;&#1084;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; CMOS &#1073;&#1077;&#1079; &#1088;&#1072;&#1079;&#1073;&#1086;&#1088;&#1082;&#1080; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1073;&#1083;&#1086;&#1082;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084;: &#1087;&#1088;&#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1072; (&#1074; &#1089;&#1072;&#1084;&#1086;&#1084; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1077;&#1097;&#1077; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1080;&#1076;&#1077;&#1090; &#1088;&#1072;&#1089;&#1082;&#1088;&#1091;&#1090;&#1082;&#1072; &#1074;&#1080;&#1085;&#1090;&#1086;&#1074;) &#1090;&#1091;&#1090; &#1078;&#1077; &#1089;&#1076;&#1105;&#1088;&#1085;&#1091;&#1090; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103;. &#1053;&#1072; 2-3 &#1081; &#1087;&#1086;&#1087;&#1099;&#1090;&#1082;&#1077; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1089;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089; &#1085;&#1072;&#1076;&#1087;&#1080;&#1089;&#1100;&#1102; CMOS checksum error/
      </li>
    </ul>
    <p>
