        &#1085;&#1077; &#1079;&#1072;&#1090;&#1088;&#1072;&#1075;&#1080;&#1074;&#1072;&#1077;&#1090; &#1091;&#1088;&#1086;&#1074;&#1085;&#1080; &#1074;&#1099;&#1096;&#1077; Ethernet, &#1090;&#1072;&#1082;&#1080;&#1077; &#1082;&#1072;&#1082; IP &#1080; TCP
      </li>
      <li>
        &#1089;&#1088;&#1072;&#1074;&#1085;&#1080;&#1084; &#1089; Fibre Channel over Ethernet, &#1095;&#1077;&#1084; &#1089; iSCSI
      </li>
