        &#1084;&#1077;&#1085;&#1077;&#1077; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1105;&#1084;&#1082;&#1080;&#1081; (&#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1072;&#1103; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1085;&#1072; &#1093;&#1086;&#1089;&#1090;)
      </li>
      <li>
        &#1083;&#1105;&#1075;&#1082;&#1080;&#1081; &#1082; &#1074;&#1085;&#1077;&#1076;&#1088;&#1077;&#1085;&#1080;&#1102;, &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1085;&#1077;&#1082;&#1080;&#1081; &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1079;&#1072;&#1097;&#1080;&#1090;&#1099;, &#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1091;&#1102; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100;.
