    <ol>
      <li>
        Instument Configuration &gt; Emission (&#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086;&#1084; &#1080;&#1079;&#1083;&#1091;&#1095;&#1072;&#1102;&#1097;&#1080;&#1084;).
      </li>
      <li>
        <b>&#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100;&#1089;&#1103; &#1089; &#1094;&#1077;&#1083;&#1077;&#1074;&#1099;&#1084;&#1080; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072;&#1084;&#1080; &#1082;&#1072;&#1083;&#1080;&#1073;&#1088;&#1086;&#1074;&#1082;&#1080;</b>.

        <ol>
          <li>
            &#1050;&#1086;&#1088;&#1088;&#1077;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1094;&#1074;&#1077;&#1090;&#1086;&#1074;&#1072;&#1103; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1072; (&#1050;&#1062;&#1058;) &#1072;&#1076;&#1072;&#1087;&#1090;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086; &#1089;&#1074;&#1077;&#1090;&#1072; (&#1080;&#1079;&#1084;&#1077;&#1088;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1075;&#1088;&#1072;&#1076;&#1091;&#1089;&#1072;&#1093; &#1050;&#1077;&#1083;&#1100;&#1074;&#1080;&#1085;&#1072;). &#1058;&#1072;, &#1050;&#1062;&#1058; &#1082; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1087;&#1086;&#1076;&#1086;&#1075;&#1085;&#1072;&#1090;&#1100; &#1073;&#1077;&#1083;&#1091;&#1102; &#1090;&#1086;&#1095;&#1082;&#1091; &#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1101;&#1082;&#1088;&#1072;&#1085;&#1072;. &#1041;&#1077;&#1083;&#1072;&#1103; &#1090;&#1086;&#1095;&#1082;&#1072; &#1101;&#1082;&#1088;&#1072;&#1085;&#1072; - &#1090;&#1086; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1079;&#1072;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1086;&#1076;&#1086;&#1084; 255,255,255. &#1045;&#1089;&#1083;&#1080; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1085;&#1080;&#1082; &#1088;&#1072;&#1079;&#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1085;&#1072; &#1074;&#1077;&#1089;&#1100; &#1101;&#1082;&#1088;&#1072;&#1085;, &#1086;&#1085; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1089;&#1074;&#1077;&#1090;&#1080;&#1090;&#1100;&#1089;&#1103; &#1073;&#1077;&#1083;&#1099;&#1084;. &#1053;&#1072; &#1079;&#1077;&#1084;&#1083;&#1102; &#1087;&#1072;&#1076;&#1072;&#1077;&#1090; &#1089;&#1074;&#1077;&#1090; &#1089; &#1050;&#1062;&#1058; 5000 &#1050;&#1077;&#1083;&#1100;&#1074;&#1080;&#1085;&#1086;&#1074; (&#1074; &#1087;&#1086;&#1083;&#1076;&#1077;&#1085;&#1100;).
          </li>
          <li>
            &#1055;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086; &#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1050;&#1062;&#1058; &#1073;&#1077;&#1083;&#1086;&#1081; &#1090;&#1086;&#1095;&#1082;&#1080; &#1101;&#1082;&#1088;&#1072;&#1085;&#1072;. &#1053;&#1072; &#1101;&#1090;&#1086;&#1084; &#1101;&#1090;&#1072;&#1087;&#1077; &#1076;&#1086;&#1087;&#1091;&#1089;&#1082;&#1072;&#1102;&#1090;&#1089;&#1103; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1099;&#1077; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080;. <b>&#1045;&#1089;&#1083;&#1080; &#1084;&#1099; &#1073;&#1077;&#1079;&#1076;&#1091;&#1084;&#1085;&#1086; &#1091;&#1088;&#1072;&#1074;&#1085;&#1103;&#1077;&#1084;</b>&#160;&#1050;&#1062;&#1058; &#1073;&#1077;&#1083;&#1086;&#1081; &#1090;&#1086;&#1095;&#1082;&#1080; &#1101;&#1082;&#1088;&#1072;&#1085;&#1072; &#1089; &#1050;&#1062;&#1058; &#1072;&#1076;&#1072;&#1087;&#1090;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1075;&#1086; &#1089;&#1074;&#1077;&#1090;&#1072;, <b>&#1084;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1084; &#1078;&#1077;&#1083;&#1090;&#1091;&#1102;, &#1088;&#1086;&#1079;&#1086;&#1074;&#1072;&#1090;&#1091;&#1102; &#1080;&#1083;&#1080; &#1086;&#1088;&#1072;&#1085;&#1078;&#1077;&#1074;&#1072;&#1090;&#1091;&#1102; &#1090;&#1086;&#1095;&#1082;&#1091;</b>&#160;&#1085;&#1072;&#1096;&#1077;&#1075;&#1086; &#1076;&#1080;&#1089;&#1087;&#1083;&#1077;&#1103;. &#1058;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1080; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1080;, &#1077;&#1089;&#1083;&#1080; &#1050;&#1062;&#1058; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072; &#1083;&#1077;&#1078;&#1080;&#1090; &#1074; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1077; &#1086;&#1090; 4000 &#1076;&#1086; 9000 &#1050;. &#1058;.&#1077;. &#1077;&#1089;&#1083;&#1080; &#1083;&#1072;&#1084;&#1087;&#1072; D50, &#1090;&#1086; &#1082;&#1086;&#1075;&#1085;&#1080;&#1090;&#1080;&#1074;&#1085;&#1099;&#1081; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;. &#1053;&#1086; &#1077;&#1089;&#1083;&#1080; &#1050;&#1062;&#1058; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; 4000&#1050; &#1080;&#1083;&#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; 9000&#1050;, &#1082;&#1086;&#1075;&#1085;&#1080;&#1090;&#1080;&#1074;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1084;&#1087;&#1086;&#1085;&#1077;&#1085;&#1090;&#1072; &#1085;&#1077;&#1090;. &#1045;&#1089;&#1083;&#1080; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; 4000&#1050; - &#1078;&#1077;&#1083;&#1090;&#1099;&#1081;, &#1073;&#1086;&#1083;&#1100;&#1096;&#1077; 9000&#1050;-&#1089;&#1080;&#1085;&#1080;&#1081;. &#1050;&#1072;&#1082; &#1078;&#1077; &#1101;&#1090;&#1086; &#1091;&#1095;&#1077;&#1089;&#1090;&#1100;. &#1045;&#1089;&#1083;&#1080; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; &#1050;&#1062;&#1058; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1072; (&#1074; &#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1072;&#1093; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1072; 4000-9000&#1050;), &#1095;&#1090;&#1086; &#1087;&#1088;&#1077;&#1076;&#1083;&#1086;&#1078;&#1080;&#1090; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072;, &#1080; &#1087;&#1088;&#1080;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; 1000, &#1090;&#1086; &#1084;&#1099; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1084; &#1095;&#1080;&#1089;&#1083;&#1086;, &#1082; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084;&#1091; &#1084;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1087;&#1086;&#1076;&#1086;&#1075;&#1085;&#1072;&#1090;&#1100; &#1073;&#1077;&#1083;&#1091;&#1102; &#1090;&#1086;&#1095;&#1082;&#1091; &#1101;&#1082;&#1088;&#1072;&#1085;&#1072;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1084;&#1099; &#1080;&#1079;&#1084;&#1077;&#1088;&#1080;&#1083;&#1080; <b>&#1050;&#1062;&#1058; &#1087;&#1072;&#1076;&#1072;&#1102;&#1097;&#1077;&#1075;&#1086; &#1089;&#1074;&#1077;&#1090;&#1072;, &#1074;&#1099;&#1103;&#1089;&#1085;&#1080;&#1083;&#1086;&#1089;&#1100; &#1095;&#1090;&#1086; &#1086;&#1085;&#1072; 5000&#1050;. &#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; 1000&#1050; &#1080; &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1074; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1094;&#1077;&#1083;&#1077;&#1074;&#1086;&#1075;&#1086; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1077;&#1083;&#1103; 6000&#1050;</b>. &#1045;&#1089;&#1083;&#1080; &#1050;&#1062;&#1058; &#1074;&#1099;&#1073;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079; &#1076;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;&#1072; 4000-9000&#1050;, &#1090;&#1086; &quot;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1086; 1000&quot; &#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;. &#1045;&#1089;&#1083;&#1080; &#1050;&#1062;&#1058; &#1074; &#1087;&#1086;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1080; &#1085;&#1080;&#1078;&#1077; 4000&#1050; (&#1083;&#1072;&#1084;&#1087;&#1072; &#1085;&#1072;&#1082;&#1072;&#1083;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;) - &#1082;&#1072;&#1083;&#1080;&#1073;&#1088;&#1091;&#1077;&#1084;&#1089;&#1103; &#1085;&#1072; 6000&#1050;(5000&#1050;+1000&#1050;).
          </li>
          <li>
            <b>I1Share.</b>&#160;&#1053;&#1091;&#1078;&#1085;&#1086; &#1086;&#1094;&#1077;&#1085;&#1080;&#1090;&#1100; &#1089;&#1074;&#1077;&#1090;. Evaluate &gt; Light. &#1053;&#1091;&#1078;&#1085;&#1086; &#1080;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; <b>Color Temperature</b>. &#1056;&#1072;&#1089;&#1089;&#1077;&#1080;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; (&#1089; &#1073;&#1077;&#1083;&#1099;&#1084; &#1075;&#1083;&#1072;&#1079;&#1082;&#1086;&#1084;) &#1085;&#1072;&#1076;&#1077;&#1074;&#1072;&#1077;&#1084; &#1085;&#1072; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088; &#1073;&#1072;&#1081;&#1086;&#1085;&#1077;&#1090;&#1086;&#1084;. &#1046;&#1084;&#1077;&#1084; &#1085;&#1072; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1072;. &#1042;&#1099;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1086;&#1073; &#1086;&#1073;&#1085;&#1091;&#1083;&#1077;&#1085;&#1080;&#1080; &#1090;&#1077;&#1084;&#1085;&#1086;&#1074;&#1086;&#1075;&#1086; &#1090;&#1086;&#1082;&#1072;. &#1055;&#1086;&#1089;&#1083;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1090;&#1103;&#1085;&#1091;&#1090;&#1100; (&#1085;&#1077; &#1086;&#1090;&#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100;) &#1082;&#1088;&#1099;&#1096;&#1082;&#1091;. &#1055;&#1086;&#1076;&#1085;&#1103;&#1090;&#1100; &#1088;&#1091;&#1082;&#1091;, &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1080;&#1090;&#1100; &#1072;&#1087;&#1077;&#1088;&#1090;&#1091;&#1088;&#1091; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1072; &#1085;&#1072; &#1083;&#1072;&#1084;&#1087;&#1091; &#1080; &#1087;&#1088;&#1080;&#1073;&#1083;&#1080;&#1079;&#1080;&#1090;&#1100;&#1089;&#1103; &#1082; &#1083;&#1072;&#1084;&#1087;&#1077; &#1082;&#1072;&#1082; &#1084;&#1086;&#1078;&#1085;&#1086; &#1073;&#1083;&#1080;&#1078;&#1077; (&#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &#1088;&#1077;&#1092;&#1083;&#1077;&#1082;&#1089;&#1086;&#1074; &#1086;&#1090; &#1089;&#1090;&#1077;&#1085;), &#1085;&#1072;&#1078;&#1072;&#1090;&#1100; &#1082;&#1085;&#1086;&#1087;&#1082;&#1091;. &#1055;&#1086;&#1103;&#1074;&#1080;&#1083;&#1080;&#1089;&#1100; &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1103; Color Temperature. &#1047;&#1072;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1091;.
          </li>
          <li>
            &#1057;&#1083;&#1077;&#1076;&#1091;&#1102;&#1097;&#1080;&#1081; &#1094;&#1077;&#1083;&#1077;&#1074;&#1086;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; - <b>&#1043;&#1072;&#1084;&#1084;&#1072;</b>. &#1042;&#1099;&#1073;&#1086;&#1088; &#1094;&#1077;&#1083;&#1077;&#1074;&#1086;&#1081; &#1075;&#1072;&#1084;&#1084;&#1072; &#1074;&#1083;&#1080;&#1103;&#1077;&#1090; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1085;&#1072; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1086;&#1074; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084; &#1080; &#1080;&#1085;&#1090;&#1077;&#1088;&#1092;&#1077;&#1081;&#1089;&#1072; &#1054;&#1057;, &#1085;&#1072; &#1074;&#1080;&#1079;&#1091;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1075;&#1086; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1101;&#1090;&#1086; &#1085;&#1077; &#1087;&#1086;&#1074;&#1083;&#1080;&#1103;&#1077;&#1090;. &#1042;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; 2.2.
          </li>
          <li>
            <b>Brightness</b>&#160;- &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; &#1074;&#1086; &#1084;&#1085;&#1086;&#1075;&#1080;&#1093; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1072;&#1093; &#1085;&#1077;&#1090;. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &quot;&#1076;&#1086;&#1087;&#1086;&#1085;&#1080;&#1078;&#1077;&#1085;&#1080;&#1103;&quot; &#1103;&#1088;&#1082;&#1086;&#1089;&#1090;&#1080;. &#1045;&#1089;&#1083;&#1080; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1085;&#1086; &#1103;&#1088;&#1082;&#1086;&#1089;&#1090;&#1100; &#1087;&#1086;&#1085;&#1080;&#1079;&#1080;&#1090;&#1100; &#1085;&#1077; &#1091;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103;. &#1054;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1084; &#1085;&#1072; 100%.
          </li>
          <li>
            &#1042;&#1089;&#1077; &#1095;&#1090;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1082;&#1085;&#1086;&#1087;&#1082;&#1072;&#1084;&#1080; &#1085;&#1072; &#1087;&#1077;&#1088;&#1077;&#1076;&#1085;&#1077;&#1081; &#1087;&#1072;&#1085;&#1077;&#1083;&#1080;, &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1082;&#1085;&#1086;&#1087;&#1082;&#1072;&#1084;&#1080;. &#1058;&#1086; &#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1089;&#1084;&#1086;&#1075;&#1083;&#1080;, &#1076;&#1086;&#1073;&#1080;&#1074;&#1072;&#1081;&#1090;&#1077;&#1089;&#1100; &#1087;&#1088;&#1080; &#1087;&#1086;&#1084;&#1086;&#1097;&#1080; <b>LUT</b>. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1043;&#1072;&#1084;&#1084;&#1072; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1079;&#1072; &#1089;&#1095;&#1077;&#1090; LUT &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1088;&#1090;&#1099;. &#1048;&#1085;&#1086;&#1075;&#1076;&#1072; LUT &#1074;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1102;&#1090; &#1074; &#1076;&#1080;&#1089;&#1087;&#1083;&#1077;&#1081;, &#1090;&#1072;&#1082;&#1080;&#1084; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1084; &#1080;&#1084;&#1077;&#1077;&#1084; &#1076;&#1074;&#1072; LUT(&#1091; &#1074;&#1080;&#1076;&#1077;&#1086;&#1082;&#1072;&#1088;&#1090;&#1099; &#1080; &#1076;&#1080;&#1089;&#1087;&#1083;&#1077;&#1103;). &#1052;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;&#1099; &#1089;&#1086; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1084; LUT &#1085;&#1091;&#1078;&#1085;&#1099; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1076;&#1083;&#1103; &#1090;&#1077;&#1093;, &#1082;&#1090;&#1086; &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1080;&#1076;&#1077;&#1086;.
