#1075;&#1091;&#1083;&#1103;&#1102;&#1090;, &#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1080;&#1090;, &#1095;&#1090;&#1086; &#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088; &#1089;&#1090;&#1086;&#1080;&#1090; &#1074;&#1086;&#1079;&#1083;&#1077; &#1089;&#1090;&#1077;&#1085;&#1099; &#1089; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1082;&#1086;&#1081; (&#1089;&#1080;&#1083;&#1086;&#1074;&#1086;&#1081; &#1082;&#1072;&#1073;&#1077;&#1083;&#1100;). &#1042; &#1090;&#1072;&#1082;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1085;&#1080;&#1090;&#1086;&#1088;&#1072;.
