84; &#1087;&#1088;&#1077;&#1076;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100; &#1089;&#1088;&#1072;&#1079;&#1091; &#1087;&#1086;&#1089;&#1083;&#1077; &#1074;&#1093;&#1086;&#1076;&#1072; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1082;&#1080;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085; &#1089;&#1075;&#1086;&#1088;&#1077;&#1083; (&#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1090;&#1072;&#1082; &#1086;&#1085; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1085;&#1077; &#1089;&#1075;&#1086;&#1088;&#1072;&#1077;&#1090;) &#1080;&#1097;&#1077;&#1084; &#1076;&#1072;&#1083;&#1077;&#1077;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1074; &#1082;&#1072;&#1082;&#1086;&#1084; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &quot;&#1082;&#1083;&#1102;&#1095;&#1080;&quot;. &#1053;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100;, &#1095;&#1090;&#1086; &#1094;&#1077;&#1087;&#1100; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1086;&#1075;&#1086; &#1090;&#1086;&#1082;&#1072; &#1085;&#1077; &#1079;&#1072;&#1084;&#1082;&#1085;&#1091;&#1090;&#1072;. &#1069;&#1090;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1085;&#1072; &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1090;&#1086;&#1088;&#1077; (&#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1084;), &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1050;&#1047;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1072; &#1101;&#1090;&#1086;&#1084; &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1090;&#1086;&#1088;&#1077; &#1050;&#1047;, &#1079;&#1085;&#1072;&#1095;&#1080;&#1090; &#1082;&#1083;&#1102;&#1095;&#1080; (&#1087;&#1086;&#1083;&#1077;&#1074;&#1099;&#1077;&#160;&#160;&#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088;&#1099;) &#1079;&#1072;&#1084;&#1082;&#1085;&#1091;&#1090;&#1099; &#1085;&#1072; &#1050;&#1047;. &#1058;.&#1077;. &#1087;&#1088;&#1077;&#1076;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100; &#1087;&#1086;&#1082;&#1072; &#1074;&#1087;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103;. &#1053;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1083;&#1080;&#1090;&#1099; &#1074; &#1079;&#1072;&#1076;&#1072;&#1102;&#1097;&#1077;&#1081; &#1095;&#1072;&#1089;&#1090;&#1080; &#1041;&#1055;. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &quot;&#1082;&#1083;&#1102;&#1095;&#1080;&quot; (&#1087;&#1086;&#1083;&#1077;&#1074;&#1099;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088;&#1099; - &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1085;&#1072; &#1088;&#1072;&#1076;&#1080;&#1072;&#1090;&#1086;&#1088;&#1077;). &#1054;&#1090;&#1082;&#1088;&#1091;&#1095;&#1080;&#1074;&#1072;&#1077;&#1084;, &#1074;&#1099;&#1087;&#1072;&#1080;&#1074;&#1072;&#1077;&#1084;, &#1087;&#1088;&#1086;&#1079;&#1074;&#1072;&#1085;&#1080;&#1074;&#1072;&#1077;&#1084; - &#1085;&#1072; <b>&#1087;&#1086;&#1083;&#1077;&#1074;&#1099;&#1093; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088;&#1072;&#1093;</b>&#160;&#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100; &#1050;&#1047;. &#1050;&#1086;&#1075;&#1076;&#1072; &#1074;&#1099;&#1093;&#1086;&#1076;&#1103;&#1090; &#1080;&#1079; &#1089;&#1090;&#1088;&#1086;&#1103; &#1087;&#1086;&#1083;&#1077;&#1074;&#1099;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088;&#1099;, &#1090;&#1086; &#1095;&#1072;&#1089;&#1090;&#1086; &#1074;&#1099;&#1093;&#1086;&#1076;&#1080;&#1090; &#1080;&#1079; &#1089;&#1090;&#1088;&#1086;&#1103; <b>&#1064;&#1048;&#1052;-&#1082;&#1086;&#1085;&#1090;&#1088;&#1086;