      <li>
        &#1045;&#1089;&#1083;&#1080; &#1058;&#1042; <b>&#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;</b>&#160;&#1082;&#1072;&#1085;&#1072;&#1083;&#1099;, &#1075;&#1088;&#1086;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1080; &#1090;.&#1076;. &#1090;&#1086; 99% &#1095;&#1090;&#1086; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099; &#1074; <b>&#1082;&#1083;&#1072;&#1074;&#1080;&#1072;&#1090;&#1091;&#1088;&#1077; (&#1074; &#1082;&#1085;&#1086;&#1087;&#1082;&#1072;&#1093;</b>). &#1058;.&#1077;. &#1086;&#1076;&#1085;&#1072; &#1082;&#1085;&#1086;&#1087;&#1082;&#1072; &#1074;&#1090;&#1072;&#1077;&#1090; &#1085;&#1072; &#1050;&#1047; &#1080; &#1086;&#1085;&#1072; &#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1089;&#1103; &quot;&#1087;&#1086;&#1083;&#1091;&#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1085;&#1080;&#1082;&#1086;&#1084;&quot;. &#1044;&#1072;&#1078;&#1077; &#1077;&#1089;&#1083;&#1080; &#1076;&#1077;&#1083;&#1086; &#1074; &#1086;&#1076;&#1085;&#1086;&#1081; &#1082;&#1085;&#1086;&#1087;&#1082;&#1077;, &#1085;&#1091;&#1078;&#1085;&#1086; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1042;&#1057;&#1045; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080;. &#1054;&#1076;&#1080;&#1085; &#1080;&#1079; &#1074;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1086;&#1074;: <b>&#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1082;&#1083;&#1072;&#1074;&#1080;&#1072;&#1090;&#1091;&#1088;&#1091;</b>. &#1042; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077; &#1088;&#1072;&#1079;&#1074;&#1083;&#1077;&#1095;&#1077;&#1085;&#1080;&#1103; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1082;&#1085;&#1086;&#1087;&#1082;&#1080;, &#1085;&#1077;&#1080;&#1089;&#1087;&#1088;&#1072;&#1074;&#1085;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1090;&#1072;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1086;&#1082;&#1072;&#1078;&#1077;&#1090; &#1089;&#1086;&#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1086;&#1084; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080;.
      </li>
      <li>
        &#1041;&#1077;&#1075;&#1091;&#1090;<b>&#160;&#1075;&#1086;&#1088;&#1080;&#1079;&#1086;&#1085;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1088;&#1072;&#1079;&#1085;&#1086;&#1094;&#1074;&#1077;&#1090;&#1085;&#1099;&#1077; &#1087;&#1086;&#1083;&#1086;&#1089;&#1099;</b>&#160;&#1087;&#1086; &#1101;&#1082;&#1088;&#1072;&#1085;&#1091; (&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1077;&#1088;&#1090;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077;). &#1053;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1096;&#1080;&#1085;&#1091; LVDS (&#1080;&#1076;&#1077;&#1090; &#1085;&#1072; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; T-con). &#1063;&#1072;&#1089;&#1090;&#1086; &#1082;&#1086;&#1085;&#1090;&#1072;&#1082;&#1090;&#1099; &#1086;&#1082;&#1080;&#1089;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103;. &#1063;&#1080;&#1089;&#1090;&#1080;&#1084; &#1089;&#1090;&#1080;&#1088;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1088;&#1077;&#1079;&#1080;&#1085;&#1082;&#1086;&#1081;, &#1090;&#1091;&#1087;&#1086;&#1081; &#1086;&#1090;&#1074;&#1077;&#1088;&#1090;&#1082;&#1086;&#1081;.
      </li>
      <li>
        &#1069;&#1082;&#1088;&#1072;&#1085; &#1073;&#1077;&#1083;&#1099;&#1081; &#1080;&#1083;&#1080; &#1074; &#1087;&#1086;&#1083;&#1086;&#1089;&#1086;&#1082;&#1091; &#1074;&#1077;&#1088;&#1090;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1089;&#1090;&#1086;&#1083;&#1073;&#1099; &#1077;&#1089;&#1090;&#1100; &#1079;&#1074;&#1091;&#1082;, &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1090;&#1089;&#1103; &#1082;&#1072;&#1085;&#1072;&#1083;&#1099;. &#1042;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1083;&#1080;&#1090; T-con &#1080; &#1091;&#1073;&#1080;&#1090;&#1099; &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1072;, &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102; &#1085;&#1077; &#1087;&#1086;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090;, &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1072;&#1084;&#1077;&#1085;&#1072; &#1084;&#1072;&#1090;&#1088;&#1080;&#1094;&#1099;.
      </li>
      <li>
        <b>LED TV </b>(SUPRA-&#1091;&#1078;&#1072;&#1089;&#1085;&#1072;&#1103; &#1087;&#1072;&#1081;&#1082;&#1072;)<b>&#160;&#1075;&#1072;&#1089;&#1085;&#1077;&#1090; &#1080;&#1079;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077;</b>&#160;(&#1080;&#1085;&#1086;&#1075;&#1076;&#1072;). &#1055;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1087;&#1086;&#1076;&#1089;&#1074;&#1077;&#1090;&#1082;&#1072; &#1087;&#1088;&#1086;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;, &#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1085;&#1103;&#1090;&#1100; &#1041;&#1055; &#1080; <b>&#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1087;&#1072;&#1081;&#1082;&#1091;</b>. &#1042;&#1077;&#1079;&#1076;&#1077; &#1087;&#1086; &#1074;&#1089;&#1077;&#1084;&#1091; &#1041;&#1055; &#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1072;&#1083;&#1080;&#1089;&#1100; <b>&#1082;&#1086;&#1083;&#1094;&#1077;&#1074;&#1099;&#1077; &#1090;&#1088;&#1077;&#1097;&#1080;&#1085;&#1099;</b>. &#1053;&#1091;&#1078;&#1085;&#1086; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1080; &#1087;&#1088;&#1086;&#1087;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1074;&#1077;&#1089;&#1100; &#1041;&#1055;, &#1086;&#1089;&#1086;&#1073;&#1077;&#1085;&#1085;&#1086; &#1090;&#1072;&#1084;, &#1075;&#1076;&#1077; &#1073;&#1099;&#1083;&#1086; &#1090;&#1077;&#1084;&#1087;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1085;&#1086;&#1077; &#1074;&#1086;&#1079;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077;. SMD &#1101;&#1083;&#1077;&#1084;&#1077;&#1085;&#1090;&#1099; &#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1077; &#1087;&#1088;&#1086;&#1087;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100;. <b>&#1047;&#1072;&#1095;&#1080;&#1089;&#1090;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1090;&#1072;&#1082;&#1090;&#1099; LVDS (T-con) - &#1101;&#1090;&#1086; &#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1080; &#1074;&#1077;&#1079;&#1076;&#1077;</b>. &#1056;&#1072;&#1079;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1084;&#1072;&#1090;&#1088;&#1080;&#1094;&#1091;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1076;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1086; &#1076;&#1080;&#1086;&#1076;&#1085;&#1086;&#1081; &#1087;&#1086;&#1076;&#1089;&#1090;&#1074;&#1077;&#1090;&#1082;&#1080;. &#1043;&#1085;&#1077;&#1079;&#1076;&#1072; &#1089;&#1074;&#1077;&#1090;&#1086;&#1076;&#1080;&#1086;&#1076;&#1085;&#1086;&#1081; &#1087;&#1083;&#1072;&#1085;&#1082;&#1080; &#1086;&#1082;&#1072;&#1079;&#1072;&#1083;&#1080;&#1089;&#1100; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; <b>&#1085;&#1077; &#1087;&#1088;&#1080;&#1087;&#1072;&#1103;&#1085;&#1099; - &#1101;&#1090;&#1086; &#1073;&#1099;&#1083;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1072;&#1103; &#1087;&#1088;&#1080;&#1095;&#1080;&#1085;&#1072;</b>. &#1051;&#1091;&#1095;&#1096;&#1077; &#1087;&#1088;&#1080;&#1087;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1072; &#1082; &#1089;&#1074;&#1077;&#1090;&#1086;&#1076;&#1080;&#1086;&#1076;&#1085;&#1086;&#1081; &#1087;&#1083;&#1072;&#1085;&#1082;&#1077; &#1073;&#1077;&#1079; &#1074;&#1089;&#1103;&#1082;&#1080;&#1093; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084;&#1086;&#1074; &#1080; &#1082; &#1041;&#1055; &#1090;&#1086;&#1078;&#1077; &#1073;&#1077;&#1079; &#1074;&#1089;&#1103;&#1082;&#1080;&#1093; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084;&#1086;&#1074;. &#1055;&#1086;&#1089;&#1083;&#1077; &#1087;&#1072;&#1081;&#1082;&#1080; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1085;&#1072; &#1050;&#1047; &#1089; &#1082;&#1086;&#1088;&#1087;&#1091;&#1089;&#1086;&#1084;.
      </li>
      <li>
        <b>&#1087;&#1088;&#1086;&#1087;&#1072;&#1076;&#1072;&#1077;&#1090;, &#1083;&#1080;&#1073;&#1086; &#1085;&#1077;&#1090; &#1079;&#1074;&#1091;&#1082;&#1072; SUPRA</b>&#160;. &#1053;&#1091;&#1078;&#1085;&#1086; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1085;&#1086;&#1078;&#1082;&#1072;&#1093; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1093;&#1077;&#1084;&#1099; &#1091;&#1089;&#1080;&#1083;&#1080;&#1090;&#1077;&#1083;&#1103; &#1079;&#1074;&#1091;&#1082;&#1072;, &#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1088;&#1072;&#1089;&#1087;&#1077;&#1095;&#1072;&#1090;&#1072;&#1090;&#1100; &#1077;&#1077; &#1076;&#1072;&#1090;&#1072;&#1096;&#1080;&#1090; (&#1089;&#1072;&#1081;&#1090; alldatasheet). AVCC - &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1086;&#1074;&#1086;&#1077; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1088;&#1072;&#1079;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100;&#1089;&#1103; &#1080; &#1087;&#1088;&#1086;&#1089;&#1083;&#1077;&#1076;&#1080;&#1090;&#1100; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1089;&#1085;&#1103;&#1090;&#1100; &#1087;&#1083;&#1072;&#1090;&#1091;. &#1054;&#1090; &#1085;&#1086;&#1078;&#1077;&#1082; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1093;&#1077;&#1084;&#1099; &#1080;&#1076;&#1091;&#1090; 2 &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1090;&#1086;&#1088;&#1072;, &#1084;&#1077;&#1078;&#1076;&#1091; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084;&#1080; &#1074; &#1086;&#1073;&#1088;&#1099;&#1074;&#1077; &#1088;&#1077;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088; (&#1085;&#1086;&#1084;&#1080;&#1085;&#1072;&#1083; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1074; &#1090;&#1086;&#1084; &#1078;&#1077; &#1076;&#1072;&#1090;&#1072;&#1096;&#1080;&#1090;&#1077; &#1084;&#1080;&#1082;&#1088;&#1086;&#1089;&#1093;&#1077;&#1084;&#1099;) &#1080; &#1091; &#1085;&#1077;&#1075;&#1086; &#1087;&#1083;&#1103;&#1096;&#1077;&#1090; &#1089;&#1086;&#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077;. &#1052;&#1077;&#1085;&#1103;&#1077;&#1084; &#1077;&#1075;&#1086; &#1080; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1073;&#1099;&#1083;&#1086; &#1079;&#1072;&#1084;&#1099;&#1082;&#1072;&#1085;&#1080;&#1103; &#1085;&#1072; &#1082;&#1086;&#1088;&#1087;&#1091;&#1089;.
      </li>
    </ol>
  </body>
