      <li>
        &#1053;&#1077; &#1088;&#1072;&#1079;&#1073;&#1080;&#1088;&#1072;&#1103; &#1058;&#1042;, &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1089;&#1074;&#1077;&#1090; &#1074; &#1087;&#1086;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1080; &#1080; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1079;&#1072;&#1075;&#1086;&#1088;&#1072;&#1077;&#1090;&#1089;&#1103; &#1083;&#1080; &#1087;&#1086;&#1076;&#1089;&#1074;&#1077;&#1090;&#1082;&#1072; &#1046;&#1050;-&#1087;&#1072;&#1085;&#1077;&#1083;&#1080; &#1091; &#1058;&#1042;. &#1045;&#1089;&#1083;&#1080; <b>&#1087;&#1086;&#1076;&#1089;&#1074;&#1077;&#1090;&#1082;&#1080; &#1085;&#1077;&#1090;</b>&#160;- &#1040;&#1043;&#1040;.
