      <li>
        &#1053;&#1091;&#1078;&#1085;&#1086; &#1085;&#1072;&#1081;&#1090;&#1080; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1072; (ON/OFF), &#1085;&#1072;&#1081;&#1090;&#1080; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1072;. &#1057;&#1085;&#1103;&#1090;&#1100; &#1041;&#1055; &#1080; &#1048;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088; &#1089; &#1094;&#1077;&#1083;&#1100;&#1102; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1087;&#1072;&#1081;&#1082;&#1080;, &#1074;&#1099;&#1075;&#1086;&#1088;&#1077;&#1074;&#1096;&#1080;&#1077; &#1076;&#1086;&#1088;&#1086;&#1078;&#1082;&#1080;, &#1087;&#1088;&#1086;&#1089;&#1083;&#1077;&#1076;&#1080;&#1090;&#1100; - &#1076;&#1086;&#1093;&#1086;&#1076;&#1080;&#1090; &#1083;&#1080; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077; &#1076;&#1086; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1072;.
      </li>
      <li>
        &#1055;&#1077;&#1088;&#1077;&#1076; &#1089;&#1085;&#1103;&#1090;&#1080;&#1077;&#1084; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1072; &#1084;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100;, &#1082;&#1072;&#1082;&#1080;&#1077; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103; &#1091; &#1085;&#1072;&#1089; &#1080;&#1084;&#1077;&#1102;&#1090;&#1089;&#1103;. &#1044;&#1077;&#1078;&#1091;&#1088;&#1085;&#1086;&#1077; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077; &#1084;&#1099; &#1091;&#1078;&#1077; &#1079;&#1085;&#1072;&#1077;&#1084;, &#1095;&#1090;&#1086; &#1077;&#1089;&#1090;&#1100;, &#1082;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086; &#1077;&#1075;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; <b>&#1087;&#1086;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; &#1085;&#1072; &#1082;&#1086;&#1085;&#1085;&#1077;&#1082;&#1090;&#1086;&#1088;&#1077; (BU5V)</b>. &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086; &#1085;&#1072;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100;&#1089;&#1103; &#1075;&#1076;&#1077; &#1095;&#1090;&#1086; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103;. &#1052;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1080;&#1081; &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1088; &#1089; &#1064;&#1048;&#1052;-&#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1083;&#1077;&#1088;&#1086;&#1084; - &#1101;&#1090;&#1086; &#1076;&#1077;&#1078;&#1091;&#1088;&#1085;&#1099;&#1081; &#1041;&#1055; (&#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1041;&#1055;). &#1044;&#1072;&#1083;&#1077;&#1077; &#1080;&#1076;&#1077;&#1090; &#1083;&#1080;&#1085;&#1080;&#1103; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1103;. &#1055;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1099;&#1081; &#1073;&#1083;&#1086;&#1082;, &#1074;&#1090;&#1086;&#1088;&#1080;&#1095;&#1085;&#1099;&#1081; &#1073;&#1083;&#1086;&#1082;. &#1042; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1086;&#1084; &#1073;&#1083;&#1086;&#1082;&#1077; &#1079;&#1072;&#1076;&#1072;&#1102;&#1097;&#1080;&#1077; &#1075;&#1077;&#1085;&#1077;&#1088;&#1072;&#1090;&#1086;&#1088;&#1099;, &#1080; &#1089;&#1074;&#1086;&#1103; &#1079;&#1077;&#1084;&#1083;&#1103;. &#1042;&#1086; &#1074;&#1090;&#1086;&#1088;&#1080;&#1095;&#1085;&#1086;&#1084; &#1073;&#1083;&#1086;&#1082;&#1077; &#1089;&#1074;&#1086;&#1103; &#1079;&#1077;&#1084;&#1083;&#1103; &#1080; &#1089;&#1074;&#1086;&#1081; &#1086;&#1073;&#1097;&#1080;&#1081; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076; (&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &quot;&#1090;&#1077;&#1083;&#1077;&#1074;&#1080;&#1079;&#1080;&#1086;&#1085;&#1085;&#1099;&#1084;&quot;). &#1042; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1086;&#1084; &#1073;&#1083;&#1086;&#1082;&#1077; &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1088; (&#1076;&#1088;&#1086;&#1089;&#1089;&#1077;&#1083;&#1100;) PFC, &#1086;&#1085; &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1090; &#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1083;&#1103;&#1077;&#1084;&#1091;&#1102; &#1084;&#1086;&#1097;&#1085;&#1086;&#1089;&#1090;&#1100; &#1058;&#1042; &#1080; &#1087;&#1086;&#1076;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1090;&#1086;&#1088;&#1077; (&#1089;&#1072;&#1084;&#1099;&#1081; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1083;&#1080;&#1090;). &#1041;&#1077;&#1079; PFC &#1085;&#1072; &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1090;&#1086;&#1088;&#1077; &#1086;&#1082;&#1086;&#1083;&#1086; 300V, &#1089; PFC &#1085;&#1072; &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1090;&#1086;&#1088; &#1085;&#1072;&#1082;&#1072;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1086; 400V.
      </li>
      <li>
        <b>&#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; PFC.</b>&#160;&#1045;&#1089;&#1083;&#1080; &#1086;&#1085; &#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;, &#1090;&#1086; &#1085;&#1072; &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1090;&#1086;&#1088;&#1077; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1073;&#1088;&#1099;&#1074; &#1085;&#1072; &#1041;&#1055; &#1087;&#1080;&#1090;&#1072;&#1102;&#1097;&#1080;&#1081; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1099; (&#1074;&#1080;&#1076;&#1080;&#1084; &#1084;&#1086;&#1097;&#1085;&#1099;&#1081; &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1088;, &#1074;&#1086;&#1079;&#1083;&#1077; &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1090;&#1086;&#1088;&#1072; &#1077;&#1089;&#1090;&#1100; &#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1099;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1072; &#1085;&#1077;&#1075;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090;). <b>&#1052;&#1077;&#1088;&#1080;&#1084; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1090;&#1086;&#1088;&#1077;</b>, &#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1084;&#1077;&#1090;&#1088; &#1085;&#1072; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1082;&#1091; 1000V, &#1097;&#1091;&#1087;&#1099; &quot;-&quot; &#1085;&#1072; &#1082;&#1072;&#1090;&#1086;&#1076; &quot;+&quot; &#1085;&#1072; &#1072;&#1085;&#1086;&#1076; &#1082;&#1086;&#1085;&#1076;&#1077;&#1085;&#1089;&#1072;&#1090;&#1086;&#1088;&#1072;.&#160;&#1045;&#1089;&#1083;&#1080; 400V, &#1079;&#1085;&#1072;&#1095;&#1080;&#1090; PFC &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;. &#1057;&#160;&#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1088;&#1072; &#1084;&#1086;&#1078;&#1077;&#1084; &#1087;&#1086;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; &#1082;&#1072;&#1082;&#1080;&#1077; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077; &#1086;&#1085; &#1085;&#1072;&#1084; &#1076;&#1072;&#1077;&#1090;. &#1054;&#1073;&#1088;&#1072;&#1097;&#1072;&#1077;&#1084; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1088;&#1072;&#1076;&#1080;&#1072;&#1090;&#1086;&#1088;&#1099; &#1080; &#1095;&#1090;&#1086; &#1085;&#1072; &#1085;&#1080;&#1093; &#1089;&#1090;&#1086;&#1080;&#1090;.&#160;&#1040; &#1085;&#1072; &#1088;&#1072;&#1076;&#1080;&#1072;&#1090;&#1086;&#1088;&#1077; &#1074;&#1086;&#1079;&#1083;&#1077; &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1088;&#1072; &#1089;&#1090;&#1086;&#1103;&#1090; 2 &#1089;&#1087;&#1072;&#1088;&#1077;&#1085;&#1085;&#1099;&#1093; &#1076;&#1080;&#1086;&#1076;&#1072; (2 &#1072;&#1085;&#1086;&#1076;&#1072; &#1089; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099;, &#1082;&#1072;&#1090;&#1086;&#1076; &#1087;&#1086; &#1094;&#1077;&#1085;&#1090;&#1088;&#1091;). <b>&#1052;&#1086;&#1078;&#1077;&#1084; &#1087;&#1086;&#1084;&#1077;&#1088;&#1080;&#1090;&#1100; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1101;&#1090;&#1080;&#1093; &#1076;&#1080;&#1086;&#1076;&#1072;&#1093;</b>&#160;(&#1074; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1084; &#1088;&#1077;&#1078;&#1080;&#1084;&#1077; &#1058;&#1042;, &#1090;.&#1077;. &#1085;&#1077; &#1076;&#1077;&#1078;&#1091;&#1088;&#1085;&#1086;&#1084;) &#1052;&#1091;&#1083;&#1100;&#1090;&#1080;&#1084;&#1077;&#1090;&#1088; &#1085;&#1072; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1082;&#1091; 200V:&#1097;&#1091;&#1087;&#1099; &quot;- &quot;&#1085;&#1072; &#1086;&#1073;&#1097;&#1080;&#1081; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;, &quot;+&quot; &#1085;&#1072; &#1082;&#1072;&#1090;&#1086;&#1076;. &#1045;&#1089;&#1090;&#1100; &#1077;&#1097;&#1077; &#1086;&#1076;&#1080;&#1085; &#1088;&#1072;&#1076;&#1080;&#1072;&#1090;&#1086;&#1088;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1089;&#1090;&#1086;&#1103;&#1090; &#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1099;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1085;&#1072; &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1088;&#1099;-&#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1099; (&#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1082;&#1072; &#1080;&#1076;&#1077;&#1090; &#1085;&#1072; &#1083;&#1072;&#1084;&#1087;&#1099;). &#1053;&#1072;&#1084; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1089;&#1083;&#1077;&#1076;&#1080;&#1090;&#1100; &#1082;&#1072;&#1082;&#1086;&#1077; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077; &#1087;&#1080;&#1090;&#1072;&#1077;&#1090; &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1088;&#1099;-&#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1099; &#1080; &#1074;&#1089;&#1102; &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1091;&#1102; &#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1091;&#1102; &#1089;&#1093;&#1077;&#1084;&#1091;, &#1089;&#1074;&#1103;&#1079;&#1072;&#1085;&#1085;&#1091;&#1102; &#1089; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088;&#1072;&#1084;&#1080; (&#1082;&#1086;&#1075;&#1076;&#1072; &#1089;&#1085;&#1080;&#1084;&#1077;&#1084; &#1087;&#1083;&#1072;&#1090;&#1091;).
      </li>
      <li>
        &#1057;&#1085;&#1080;&#1084;&#1072;&#1077;&#1084; &#1087;&#1083;&#1072;&#1090;&#1091;. &#1054;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1088;&#1072;&#1079;&#1098;&#1077;&#1084;&#1099;. &#1059;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1058;&#1042; &#1089; &#1088;&#1072;&#1073;&#1086;&#1095;&#1077;&#1075;&#1086; &#1089;&#1090;&#1086;&#1083;&#1072;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1085; &#1085;&#1072;&#1084; &#1085;&#1077; &#1084;&#1077;&#1096;&#1072;&#1083;.
