      <li>
        <b>&#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1085;&#1072; &#1050;&#1047; &#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1099;&#1077; &#1082;&#1072;&#1089;&#1082;&#1072;&#1076;&#1099;</b>&#160;(4 &#1087;&#1086;&#1083;&#1077;&#1074;&#1099;&#1093; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088;&#1072; (2-n-&#1082;&#1072;&#1085;&#1072;&#1083;, 2-p-&#1082;&#1072;&#1085;&#1072;&#1083;) &#1085;&#1072; &#1088;&#1072;&#1076;&#1080;&#1072;&#1090;&#1086;&#1088;&#1077; &#1074;&#1086;&#1079;&#1083;&#1077; &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;-&#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1086;&#1074;). &#1069;&#1090;&#1086; &#1082;&#1083;&#1102;&#1095;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090; &#1085;&#1072; &#1087;&#1077;&#1088;&#1074;&#1080;&#1095;&#1085;&#1091;&#1102; &#1086;&#1073;&#1084;&#1086;&#1090;&#1082;&#1091; &#1074;&#1089;&#1077;&#1093; &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074;-&#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1086;&#1074;. &#1057;&#1090;&#1072;&#1074;&#1080;&#1084; &#1087;&#1088;&#1086;&#1079;&#1074;&#1086;&#1085;&#1082;&#1091;. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1085;&#1072; &#1057;&#1090;&#1086;&#1082; &#1080; &#1048;&#1089;&#1090;&#1086;&#1082; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088;&#1072;. &#1065;&#1091;&#1087;&#1099;: &quot;-&quot; &#1085;&#1072; &#1089;&#1088;&#1077;&#1076;&#1085;&#1102;&#1102; &#1085;&#1086;&#1078;&#1082;&#1091; &quot;+&quot; &#1085;&#1072; &#1087;&#1088;&#1072;&#1074;&#1091;&#1102; &#1085;&#1086;&#1078;&#1082;&#1091;. &#1059;&#1073;&#1077;&#1078;&#1076;&#1072;&#1077;&#1084;&#1089;&#1103;, &#1095;&#1090;&#1086; &#1091; &#1085;&#1072;&#1089; &#1085;&#1077;&#1090; &#1050;&#1047;.
      </li>
      <li>
