      </li>
      <li>
        &#1042;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1077; &#1087;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;&#1077;&#1090; &#1089;&#1080;&#1075;&#1085;&#1072;&#1083; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1103; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1072;. &#1063;&#1090;&#1086; &#1084;&#1086;&#1075;&#1083;&#1086; &#1087;&#1088;&#1086;&#1080;&#1079;&#1086;&#1081;&#1090;&#1080;? &#160;&#1048;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088; &#1084;&#1086;&#1078;&#1077;&#1090; &#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1086;&#1096;&#1080;&#1073;&#1082;&#1091;, &#1095;&#1090;&#1086;-&#1090;&#1086; &#1085;&#1077; &#1074; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1089; &#1083;&#1072;&#1084;&#1087;&#1072;&#1084;&#1080; &#1083;&#1080;&#1073;&#1086; &#1089; &#1089;&#1072;&#1084;&#1080;&#1084; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1086;&#1084;. &#1048; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088; &#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1091; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088;&#1072;, &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1072;&#1103; &#1077;&#1075;&#1086;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088; &#1086;&#1087;&#1103;&#1090;&#1100; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100;, &#1101;&#1090;&#1091; <b>&#1086;&#1096;&#1080;&#1073;&#1082;&#1091; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1095;&#1080;&#1089;&#1090;&#1080;&#1090;&#1100;</b>. &#1048; &#1080;&#1085;&#1074;&#1077;&#1088;&#1090;&#1086;&#1088; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1089;&#1103;. &#1044;&#1083;&#1103; &#1089;&#1073;&#1088;&#1086;&#1089;&#1072; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1079;&#1072;&#1081;&#1090;&#1080; &#1074; &#1089;&#1077;&#1088;&#1074;&#1080;&#1089;&#1085;&#1086;&#1077; &#1084;&#1077;&#1085;&#1102; &#1058;&#1042;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1089;&#1073;&#1088;&#1086;&#1089;&#1080;&#1090;&#1100; &#1085;&#1091;&#1078;&#1085;&#1086; &#1085;&#1072;&#1078;&#1072;&#1090;&#1100;: &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1091; &quot;<b>&#1043;&#1056;&#1054;&#1052;&#1050;&#1054;&#1057;&#1058;&#1068;-</b>&quot;+&quot;<b>INPUT</b>&#160;(&#1090;.&#1077;. &#1074;&#1093;&#1086;&#1076; &#1074; AV &#1088;&#1077;&#1078;&#1080;&#1084;)&quot; &#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; <b>&#1042;&#1048;&#1051;&#1050;&#1059; &#1042; &#1056;&#1054;&#1047;&#1045;&#1058;&#1050;&#1059;</b>. &#1050;&#1086;&#1075;&#1076;&#1072; &#1101;&#1082;&#1088;&#1072;&#1085; &#1079;&#1072;&#1089;&#1074;&#1077;&#1090;&#1080;&#1090;&#1089;&#1103;, &#1085;&#1072;&#1078;&#1080;&#1084;&#1072;&#1077;&#1084; &#1082;&#1083;&#1072;&#1074;&#1080;&#1096;&#1091; &quot;<b>PROGRAM-</b>&quot;. &#1050;&#1086;&#1075;&#1076;&#1072; &#1079;&#1072;&#1075;&#1086;&#1088;&#1072;&#1077;&#1090;&#1089;&#1103; &#1101;&#1082;&#1088;&#1072;&#1085;, &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100; &#1074;&#1085;&#1080;&#1084;&#1072;&#1085;&#1080;&#1077; &#1085;&#1072; &#1089;&#1074;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1083;&#1072;&#1084;&#1087;, &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1083;&#1072;&#1084;&#1087;&#1099; &#1089;&#1077;&#1083;&#1080;. &#1055;&#1086;&#1087;&#1072;&#1076;&#1072;&#1077;&#1084; &#1074; &#1084;&#1077;&#1085;&#1102;: <b>Factory init (Russia); EPP Clear (ON);</b>&#160;&#1076;&#1072;&#1083;&#1077;&#1077; <b>&#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1058;&#1042; &#1080;&#1079; &#1088;&#1086;&#1079;&#1077;&#1090;&#1082;&#1080;</b>. &#1048;&#1085;&#1086;&#1075;&#1076;&#1072; &#1076;&#1083;&#1103; &#1074;&#1099;&#1093;&#1086;&#1076;&#1072; &#1080;&#1079; &#1084;&#1077;&#1085;&#1102; &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1090;&#1091; &#1078;&#1077; &#1089;&#1072;&#1084;&#1091;&#1102; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1102;, &#1090;.&#1077;. <b>&#1043;&#1088;&#1086;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &quot;-&quot; + &#1042;&#1093;&#1086;&#1076;</b>.
      </li>
      <li>
        &#1058;&#1077;&#1087;&#1077;&#1088;&#1100; &#1058;&#1042; &#1073;&#1091;&#1076;&#1077;&#1090; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103;, &#1085;&#1086; &#1087;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099; &#1089; &#1083;&#1072;&#1084;&#1087;&#1072;&#1084;&#1080; &#1086;&#1089;&#1090;&#1072;&#1085;&#1091;&#1090;&#1089;&#1103; &#1080; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1072;&#1082;&#1086;&#1077;-&#1090;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1074;&#1089;&#1077; &#1086;&#1087;&#1103;&#1090;&#1100; &#1073;&#1083;&#1086;&#1082;&#1077;&#1088;&#1085;&#1077;&#1090;&#1089;&#1103;.
      </li>
      <li>
        &#1053;&#1091;&#1078;&#1085;&#1086; &#1088;&#1072;&#1079;&#1086;&#1073;&#1088;&#1072;&#1090;&#1100; &#1087;&#1072;&#1085;&#1077;&#1083;&#1100; &#1080; &#1087;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1083;&#1072;&#1084;&#1087;&#1099; (&#1095;&#1077;&#1088;&#1085;&#1099;&#1077; &#1087;&#1086;&#1090;&#1077;&#1084;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074;&#1086;&#1079;&#1083;&#1077; &#1094;&#1086;&#1082;&#1086;&#1083;&#1077;&#1081;). &#1042;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1074;&#1089;&#1077; &#1083;&#1072;&#1084;&#1087;&#1099;, &#1077;&#1089;&#1083;&#1080; &#1086;&#1085;&#1080; &#1074; &#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1086; &#1087;&#1083;&#1086;&#1093;&#1086;&#1084; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1080;. &#1045;&#1089;&#1083;&#1080; CCFL &#1083;&#1072;&#1084;&#1087;&#1099; &#1073;&#1077;&#1079; &#1094;&#1086;&#1082;&#1086;&#1083;&#1103; (&#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089; &#1074;&#1099;&#1074;&#1086;&#1076;&#1072;&#1084;&#1080; - &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1090;&#1072;&#1082;&#1080;&#1077; &#1083;&#1072;&#1084;&#1087;&#1099; &#1076;&#1077;&#1096;&#1077;&#1074;&#1083;&#1077; &#1080;&#1083;&#1080; &#1077;&#1097;&#1077; &#1095;&#1090;&#1086;), &#1090;&#1086; &#1074;&#1080;&#1090;&#1099;&#1077; &#1094;&#1086;&#1082;&#1086;&#1083;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1076;&#1077;&#1083;&#1072;&#1090;&#1100; &#1089;&#1072;&#1084;&#1086;&#1084;&#1091;, &#1085;&#1072;&#1082;&#1088;&#1091;&#1090;&#1080;&#1074; &#1084;&#1077;&#1076;&#1085;&#1091;&#1102; &#1087;&#1088;&#1086;&#1074;&#1086;&#1083;&#1086;&#1082;&#1091; &#1085;&#1072; &#1087;&#1086;&#1093;&#1086;&#1078;&#1080;&#1081; &#1082;&#1086;&#1085;&#1091;&#1089; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;&#1072; &#1085;&#1072; &#1086;&#1090;&#1074;&#1077;&#1088;&#1090;&#1082;&#1091;) &#1080; &#1079;&#1072;&#1083;&#1091;&#1076;&#1080;&#1074;. &#1051;&#1091;&#1078;&#1077;&#1085;&#1072;&#1103; &#1087;&#1086;&#1074;&#1077;&#1088;&#1093;&#1085;&#1086;&#1089;&#1090;&#1100; &#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1084;&#1077;&#1089;&#1090;&#1086;&#1084; &#1082;&#1086;&#1085;&#1090;&#1072;&#1082;&#1090;&#1072;. &#1058;&#1072;&#1082;&#1080;&#1077; &#1094;&#1086;&#1082;&#1086;&#1083;&#1103; &#1073;&#1091;&#1076;&#1077;&#1084; &#1089;&#1090;&#1072;&#1074;&#1080;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089; &#1075;&#1086;&#1088;&#1103;&#1095;&#1077;&#1081; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099;, &#1072; &#1093;&#1086;&#1088;&#1086;&#1076;&#1085;&#1099;&#1077; &#1082;&#1086;&#1085;&#1094;&#1099; &#1073;&#1091;&#1076;&#1077;&#1084; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1103;&#1090;&#1100; &#1074;&#1084;&#1077;&#1089;&#1090;&#1077;. &#1055;&#1088;&#1080; &#1080;&#1079;&#1075;&#1086;&#1090;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1094;&#1086;&#1082;&#1086;&#1083;&#1077;&#1081; &#1085;&#1091;&#1078;&#1085;&#1086; &#1091;&#1095;&#1077;&#1089;&#1090;&#1100;, &#1095;&#1090;&#1086; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1090;&#1077;&#1087;&#1083;&#1086;&#1074;&#1086;&#1081; &#1079;&#1072;&#1079;&#1086;&#1088; &#1084;&#1077;&#1078;&#1076;&#1091; &#1094;&#1086;&#1082;&#1086;&#1083;&#1077;&#1084; &#1080; &#1083;&#1072;&#1084;&#1087;&#1086;&#1081;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1083;&#1072;&#1084;&#1087;&#1072; &#1085;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086; &#1083;&#1102;&#1092;&#1090;&#1080;&#1083;&#1072;.
      </li>
      <li>
        &#1057;&#1085;&#1103;&#1090;&#1100; &#1083;&#1072;&#1084;&#1087;&#1099;, &#1087;&#1086;&#1084;&#1099;&#1090;&#1100; &#1086;&#1090;&#1088;&#1072;&#1078;&#1072;&#1090;&#1077;&#1083;&#1100; &#1074;&#1086;&#1076;&#1086;&#1081;. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1085;&#1086;&#1074;&#1099;&#1077; &#1083;&#1072;&#1084;&#1087;&#1099; &#1089; &#1094;&#1086;&#1082;&#1086;&#1083;&#1103;&#1084;&#1080;. &#1055;&#1088;&#1086;&#1074;&#1086;&#1083;&#1086;&#1095;&#1085;&#1099;&#1084;&#1080; &#1093;&#1086;&#1084;&#1091;&#1090;&#1080;&#1082;&#1072;&#1084;&#1080; (&#1080; &#1087;&#1072;&#1103;&#1083;&#1100;&#1085;&#1080;&#1082;&#1086;&#1084;) &#1079;&#1072;&#1082;&#1088;&#1077;&#1087;&#1080;&#1090;&#1100; &#1089;&#1077;&#1088;&#1077;&#1076;&#1080;&#1085;&#1099; &#1083;&#1072;&#1084;&#1087;.
      </li>
    </ol>
