        &#1077;&#1089;&#1083;&#1080; &#1087;&#1088;&#1077;&#1076;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100; &#1087;&#1088;&#1086;&#1073;&#1080;&#1090;, &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; &#1087;&#1086;&#1095;&#1077;&#1084;&#1091;. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1087;&#1088;&#1077;&#1076;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100; &#1087;&#1088;&#1086;&#1073;&#1080;&#1074;&#1072;&#1077;&#1090; &#1077;&#1089;&#1083;&#1080; &#1074;&#1099;&#1096;&#1083;&#1080; &#1080;&#1079; &#1089;&#1090;&#1088;&#1086;&#1103; &#1082;&#1083;&#1102;&#1095;&#1077;&#1074;&#1099;&#1077; &#1090;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088;&#1099; (&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1088;&#1072;&#1089;&#1082;&#1072;&#1095;&#1080;&#1074;&#1072;&#1102;&#1090; &#1090;&#1088;&#1072;&#1085;&#1089;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1088;&#1099;)
