        &#1050;&#1091;&#1083;&#1077;&#1088;. &#1089;&#1090;&#1088;&#1077;&#1083;&#1082;&#1072; &#1085;&#1072; &#1082;&#1086;&#1088;&#1087;&#1091;&#1089;&#1077;. &#1077;&#1089;&#1083;&#1080; &#1089;&#1090;&#1088;&#1077;&#1083;&#1082;&#1080; &#1085;&#1077;&#1090;, &#1090;&#1086; <b>&#1074;&#1086;&#1079;&#1076;&#1091;&#1093; &#1076;&#1074;&#1080;&#1078;&#1077;&#1090;&#1089;&#1103; &#1074; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1091; &#1085;&#1072;&#1082;&#1083;&#1077;&#1081;&#1082;&#1080;</b>
      </li>
      <li>
        &#1050;&#1091;&#1083;&#1077;&#1088; &#1085;&#1072; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1077; &#1092;&#1080;&#1082;&#1089;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072;&#1078;&#1072;&#1090;&#1080;&#1077;&#1084; &#1085;&#1072; &#1085;&#1086;&#1078;&#1082;&#1080;, &#1077;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086;<b>&#160;&#1089;&#1085;&#1103;&#1090;&#1100;</b>&#160;&#1082;&#1091;&#1083;&#1077;&#1088;, <b>&#1087;&#1086;&#1074;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1077;&#1084;</b>&#160;&#1085;&#1086;&#1078;&#1082;&#1080; &#1087;&#1086; &#1089;&#1090;&#1088;&#1077;&#1083;&#1082;&#1077; (&#1087;&#1088;&#1086;&#1090;&#1080;&#1074; &#1095;&#1072;&#1089;&#1086;&#1074;&#1086;&#1081;) &#1080; <b>&#1090;&#1103;&#1085;&#1077;&#1084;</b>&#160;&#1085;&#1072; &#1089;&#1077;&#1073;&#1103;. &#1044;&#1083;&#1103; &#1087;&#1086;&#1074;&#1090;&#1086;&#1088;&#1085;&#1086;&#1081; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1085;&#1086;&#1078;&#1082;&#1091; &#1085;&#1091;&#1078;&#1085;&#1086; &#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1074; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1086;&#1077; &#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;. &#1060;&#1080;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1086;&#1078;&#1082;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1074; &#1087;&#1086; &#1076;&#1080;&#1072;&#1075;&#1086;&#1085;&#1072;&#1083;&#1080;
      </li>
      <li>
        &#1087;&#1077;&#1088;&#1077;&#1076;&#1085;&#1103;&#1103; &#1087;&#1072;&#1085;&#1077;&#1083;&#1100; &#1082;&#1086;&#1088;&#1087;&#1091;&#1089;&#1072; (&#1074;&#1076;&#1091;&#1074;), &#1074;&#1089;&#1077; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1074;&#1099;&#1076;&#1091;&#1074; &#1074;&#1086;&#1079;&#1076;&#1091;&#1093;&#1072;
      </li>
    </ul>
  </body>
