        &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1074;&#1077;&#1085;&#1090;&#1080;&#1083;&#1103;&#1090;&#1086;&#1088;&#1072; - &#1074;&#1086;&#1079;&#1076;&#1091;&#1093; &#1074;&#1099;&#1076;&#1091;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1091;&#1083;&#1077;&#1088; <b>&#1087;&#1086; &#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102; &#1082; &#1079;&#1072;&#1076;&#1085;&#1077;&#1081; &#1089;&#1090;&#1077;&#1085;&#1082;&#1077; &#1082;&#1086;&#1088;&#1087;&#1091;&#1089;&#1072; </b>
