</html></richcontent>
</node>
<node TEXT="Matrix RAID" ID="ID_1232676396" CREATED="1519112080322" MODIFIED="1532237549878"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Matrix RAID</b>&#160;&#8212; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; Intel &#1074; &#1102;&#1078;&#1085;&#1099;&#1093; &#1084;&#1086;&#1089;&#1090;&#1072;&#1093; &#1089;&#1074;&#1086;&#1080;&#1093; &#1095;&#1080;&#1087;&#1089;&#1077;&#1090;&#1086;&#1074; (&#1090;.&#1077;. &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1072; &#1074; &#1084;&#1072;&#1090;&#1077;&#1088;&#1080;&#1085;&#1089;&#1082;&#1091;&#1102; &#1087;&#1083;&#1072;&#1090;&#1091;), &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; ICH6R.
    </p>
    <ul>
      <li>
        &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1103; &#1085;&#1077; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1085;&#1086;&#1074;&#1099;&#1084; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077;&#1084; RAID (&#1080; &#1077;&#1105; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1074; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1085;&#1099;&#1093; RAID-&#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1083;&#1077;&#1088;&#1072;&#1093; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103;)
