      </li>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077; &#1088;&#1077;&#1084;&#1072;&#1087;&#1072; &#1076;&#1080;&#1089;&#1082;&#1072; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1084; &#1088;&#1077;&#1084;&#1072;&#1087; &#1089;&#1085;&#1086;&#1074;&#1072;. Remap &gt; Start. &#1045;&#1089;&#1083;&#1080; &#1073;&#1099;&#1090;&#1099;&#1077; &#1089;&#1077;&#1082;&#1090;&#1086;&#1088;&#1072; &#1080;&#1089;&#1095;&#1077;&#1079;&#1083;&#1080;, &#1079;&#1085;&#1072;&#1095;&#1080;&#1090; &#1080;&#1093; &#1091;&#1076;&#1072;&#1083;&#1086;&#1089;&#1100; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100;.
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1085;&#1077;&#1090;, &#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1079;&#1072;&#1084;&#1077;&#1090;&#1080;&#1090;&#1100; &#1075;&#1076;&#1077; &#1085;&#1072;&#1093;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1073;&#1080;&#1090;&#1099;&#1077; &#1089;&#1077;&#1082;&#1090;&#1086;&#1088;&#1072; (&#1074; &#1085;&#1072;&#1095;&#1072;&#1083;&#1077;, &#1074; &#1082;&#1086;&#1085;&#1094;&#1077; &#1080;&#1083;&#1080; &#1074; &#1089;&#1077;&#1088;&#1077;&#1076;&#1080;&#1085;&#1077;). &#1069;&#1090;&#1072; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1085;&#1072;&#1084; &#1087;&#1086;&#1085;&#1072;&#1076;&#1086;&#1073;&#1080;&#1090;&#1100;&#1089;&#1103; &#1076;&#1083;&#1103; &#1087;&#1088;&#1080;&#1085;&#1103;&#1090;&#1080;&#1103; &#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1103; &#1086;&#1073; <b>&#1086;&#1073;&#1088;&#1077;&#1079;&#1082;&#1077; &#1076;&#1080;&#1089;&#1082;&#1072;</b>&#160;&#160;
