<node TEXT="Промпт (prompt)" ID="ID_165092821" CREATED="1774114409693" MODIFIED="1774115216607"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_359453570">Markdown</a>&#xa0;&#xa0;<a href="#ID_1972221554">XML </a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">XML промпт</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&lt;запрос&gt; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&lt;роль&gt;backend-разработчик&lt;/роль&gt; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&lt;задача&gt;предложи три способа валидации email-адреса в python&lt;/задача&gt; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;&lt;результат&gt;верни примеры кода&lt;/результат&gt; </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&lt;/запрос&gt; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Markdown промпт</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;"># Проведение ревью кода </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">## Синтаксис </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">…описание правил кодстайла… </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">## Принципы именования переменных </span>
