<node TEXT="main.py" ID="ID_1109022491" CREATED="1772258288473" MODIFIED="1772263337589"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">from fastapi import FastAPI </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">import uvicorn </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">app = FastAPI() </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">@app.get(&quot;/&quot;) </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">def root(): </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;return {&quot;msg&quot;: &quot;Hello World!&quot;} </span>
