<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      # Пример: разные деплои для разных веток
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">deploy_staging: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;stage: deploy </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;script: ./deploy.sh staging </span>
    </p>
