      <span style="color: #008000; font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;&#xa0;file_content: &quot;Hello from Ansible! The time is </span><span style="color: #008000; font-family: Lucida Console; font-weight: bold;">{{ ansible_date_time.iso8601 }}</span><span style="color: #008000; font-family: Lucida Console;">&quot; </span>
    </p>
