<node TEXT="Задания по расписанию (cron)" ID="ID_1688925744" CREATED="1738608177120" MODIFIED="1738608595352"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1176501301">cron</a>&#xa0;&#xa0;<a href="#ID_458158038">anacron</a>&#xa0; <a href="#ID_109866290">юнит systemd.timer</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000; font-weight: bold;">- name: Добавить задание cron для запуска скрипта каждые 5 минут</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;</span><span style="font-family: Lucida Console; color: #008000; font-weight: bold;">cron:</span><span style="font-family: Lucida Console; color: #008000;">&#xa0; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;name: &quot;Запуск unison-sync.sh&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;minute: &quot;*/5&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;job: &quot;/usr/local/bin/unison-sync.sh &amp;&gt; /dev/null&quot;</span>
    </p>
  </body>
</html></richcontent>
</node>
