<node TEXT="zabbix-агент, nginx" FOLDED="true" POSITION="bottom_or_right" ID="ID_1350646382" CREATED="1733385921685" MODIFIED="1759936120508"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_563338974"><span style="font-size: 10pt;">Zabbix</span></a><span style="font-size: 10pt;">&#xa0;</span>&#xa0;<a href="#ID_1610922364">Nginx</a>&#xa0;&#xa0;
    </p>
    <ul>
      <li>
        ansible - управляющая ВМ (ansible)
      </li>
      <li>
        vm_1 - управляемая ВМ на Debian 10-12
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">apt-get update &amp;&amp; apt-get install ansible sshpass -y</span>&#xa0;&#xa0;&#xa0;# Обновить и установить пакеты
    </p>
    <p>
      
    </p>
    <h6>
      <span style="font-weight: bold;">Inventory</span>
    </h6>
    <p>
      <span style="color: #0000c0;">mkdir ansible &amp;&amp; cd ansible</span>&#xa0;&#xa0;# Создать каталог и перейти в него
    </p>
    <p>
      <span style="color: #0000c0;">vim <a href="#ID_837748627">inventory.yaml</a></span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">vm_1: Включить доступ по паролю для root и задать пароль для него</span>
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/ssh/sshd_config</span>&#xa0;&#xa0;# Настроить SSH-сервер
    </p>
    <p>
      <span style="color: #008000;">PasswordAuthentication yes&#xa0; </span># Разрешить аутентификацию по паролю
    </p>
    <p>
      <span style="color: #008000;">PermitRootLogin yes</span>&#xa0;&#xa0;# Если нужно входить под учеткой root
    </p>
    <p>
      <span style="color: #0000c0;">systemctl restart sshd </span>
    </p>
    <p>
      <span style="color: #0000c0;">passwd root</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">vim <a href="#ID_1129244587">ansible.cfg</a></span>&#xa0;&#xa0;# Отключить проверку ключей хоста при <span style="font-weight: bold;">первом подключении</span><span style="font-weight: normal;">&#xa0;и настроить доступы по ключу (если требуется)</span>
    </p>
    <p>
      <span style="color: #0000c0;">ansible all -m ping -i inventory.yaml</span>&#xa0;&#xa0;&#xa0;# Проверить синтаксис и доступность vm_1
    </p>
    <p>
      
    </p>
    <h6>
      <span style="font-weight: bold;">Две роли, вызываемые по тегам</span>
    </h6>
    <ul>
      <li>
        default_packages - будет устанавливать стандартные пакеты
      </li>
      <li>
        nginx_custom - будет устанавливать nginx и изменять страницу на кастомную
      </li>
    </ul>
    <p>
      <span style="color: #0000c0;">vim <a href="#ID_592666802">playbook.yaml</a></span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать плейбук</span>
    </p>
    <p>
      <span style="color: #0000c0;">ansible-galaxy init default_packages</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать роли</span>
    </p>
    <p>
      <span style="color: #0000c0;">ansible-galaxy init nginx_custom</span>&#xa0;
    </p>
    <p>
      <span style="color: #0000c0;">vim </span><span style="color: #0000c0; font-weight: bold;">default_packages</span><span style="color: #0000c0;">/vars/<a href="#ID_408396860">main.yml</a></span>&#xa0;&#xa0;# Список устанавливаемых пакетов<span style="color: #0000c0;">&#xa0;</span>
    </p>
    <p>
      <span style="color: #0000c0;">vim </span><span style="color: #0000c0; font-weight: bold;">default_packages</span><span style="color: #0000c0;">/tasks/<a href="#ID_1888676364">main.yml</a>&#xa0; </span>&#xa0;# <span style="font-weight: bold;">Условие</span>: установка только на <span style="font-weight: bold;">Debian-системы</span>
    </p>
    <p>
      <span style="color: #0000c0;">ansible-playbook playbook.yaml -i inventory.yaml --tags=&quot;install_packages&quot;</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Запустить</span>&#xa0;плейбук
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Настройка Zabbix-агента: нужно изменить его конфигурационный файл. Перезапустить и поставить в автозагрузку.</span>
    </p>
    <p>
      <span style="color: #0000c0;">vim default_packages/templates/<a href="#ID_106498387">zabbix_agentd.j2</a></span>&#xa0;&#xa0;# Создать шаблон конфигурации агента
    </p>
    <p>
      <span style="color: #0000c0;">echo &quot;zbx_server_addr: 127.0.0.1&quot; &gt;&gt; default_packages/vars/main.yml</span>&#xa0;&#xa0;# Добавьте переменную zbx_server_addr: 127.0.0.1
    </p>
    <p>
      <span style="color: #0000c0;">vim default_packages/tasks/<a href="#ID_1888676364">main.yml</a></span>&#xa0;&#xa0;# Добавить 2-е задачи
    </p>
    <p>
      <span style="color: #0000c0;">ansible-playbook playbook.yaml -i inventory.yaml --tags=&quot;install_packages&quot;</span>&#xa0;&#xa0;# Запустить Playbook
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Настройки Nginx. </span>установить Nginx. Подменить стандартную веб-страницу на нужную
    </p>
    <p>
      <span style="color: #0000c0;">vim nginx_custom/templates/<a href="#ID_946148841">index.j2</a></span>&#xa0;&#xa0;# Нужная нам страница
    </p>
    <p>
      <span style="color: #0000c0;">vim nginx_custom/tasks/<a href="#ID_749416452">main.yml</a></span>&#xa0;&#xa0;# Создать две задачи
    </p>
    <p>
      <span style="color: #0000c0;">vim nginx_custom/handlers/<a href="#ID_456832235">main.yml</a></span>&#xa0;&#xa0;# Добавить постобработчик
    </p>
    <p>
      <span style="color: #0000c0;">ansible-playbook playbook.yaml -i inventory.yaml --tags=&quot;nginx_custom&quot;</span>&#xa0;&#xa0;# Запустить Playbook
    </p>
  </body>
</html></richcontent>
<node TEXT="ansible.cfg" ID="ID_1129244587" CREATED="1734003452443" MODIFIED="1734007002490"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">vim ansible.cfg</span>&#xa0;&#xa0;
    </p>
    <p>
      <span style="color: #008000;">[defaults] </span>
    </p>
    <p>
      <span style="color: #008000;">host_key_checking = false</span>&#xa0;&#xa0;# Отключить проверку ключей хоста при первом подключении
    </p>
    <p>
      <span style="color: #008000;">private_key_file = /путь/к/закрытому/ключу/id_rsa</span>&#xa0;&#xa0;# Аутентификация по ключу - если ключ один для всех хостов. Если отличается - можно прописать в <a href="#ID_837748627">inventory.yaml</a>&#xa0;для группы хостов или индивидуально
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">ansible all -m ping -i inventory.yaml</span>&#xa0;&#xa0;&#xa0;# Проверить синтаксис и доступность vm_1
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="inventory.yaml" ID="ID_837748627" CREATED="1733403662456" MODIFIED="1741682226613"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0; font-family: Lucida Console;">vim inventory.yaml</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">--- </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">linux: </span><span style="font-family: Lucida Console;">#Группа хостов </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;children: </span><span style="font-family: Lucida Console;">#Обозначение, что будет подгруппа хостов </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;nginx: </span><span style="font-family: Lucida Console;">#Имя подгруппы хостов</span><span style="font-family: Lucida Console; color: #008000;">&#xa0;</span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;hosts: </span><span style="font-family: Lucida Console;">#Узлы группы </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;vm-1: </span><span style="font-family: Lucida Console;">#Имя машины </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;ansible_host: 192.168.1.90 </span><span style="font-family: Lucida Console;">#Адрес машины </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;vars: </span><span style="font-family: Lucida Console;">#Переменные, доступные или используемые для всех подгрупп </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ansible_user: &quot;root&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ansible_password: &quot;&lt;пароль&gt;&quot; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ansible_ssh_private_key_file: /путь/к/закрытому/ключу/id_rsa</span><span style="font-family: Lucida Console;">&#xa0;&#xa0;&#xa0;# Для доступа по ключу </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;connection_protocol: ssh </span><span style="font-family: Lucida Console;">#тип подключения </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ansible_become: true </span><span style="font-family: Lucida Console;">#Становиться ли другим пользователем после подключения </span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="playbook.yaml" ID="ID_592666802" CREATED="1733403789736" MODIFIED="1733403806523"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">vim playbook.yaml</span>&#xa0;&#xa0;# <span style="font-weight: bold;">Создать плейбук</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">--- </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">- name: Установка стандартных пакетов </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;hosts: all </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;roles: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;&#xa0;&#xa0;- role: default_packages </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;tags: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;&#xa0;&#xa0;- install_packages </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">- name: Установка и настройка nginx c кастомной страницей </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;hosts: nginx </span><span style="font-family: Monospaced;"># Будет работать на узлах в группе nginx</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;roles: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;&#xa0;&#xa0;- role: nginx_custom </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;tags: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;&#xa0;&#xa0;- nginx_custom</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="default_packages/vars/main.yml" ID="ID_408396860" CREATED="1733403889513" MODIFIED="1733403905563"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">vim </span><span style="color: #0000c0; font-weight: bold;">default_packages</span><span style="color: #0000c0;">/vars/main.yml</span>&#xa0;&#xa0;# Список устанавливаемых пакетов<span style="color: #0000c0;">&#xa0;</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">--- </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">packages_to_install: </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- dnsutils </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- net-tools </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- zabbix-agent </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- rsync </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- rsyslog </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- mc </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- curl </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- wget </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- apt-transport-https </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- gnupg2 </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- software-properties-common </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- ca-certificates </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Monospaced;">&#xa0;&#xa0;- parted </span>
