</node>
<node TEXT="Поменять содержание файла" POSITION="bottom_or_right" ID="ID_1449908111" CREATED="1734098519554" MODIFIED="1735999869383"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">vim ansible/nginx_custom/</span><span style="color: #0000c0; font-weight: bold;">tasks</span><span style="color: #0000c0;">/main.yml</span>&#xa0;&#xa0;#
    </p>
    <p>
      <span style="font-family: Monospaced; color: #008000;">--- </span>
    </p>
    <p>
      <span style="font-family: Monospaced; color: #008000;">- name: Подмена веб-страницы </span>
    </p>
    <p>
      <span style="font-family: Monospaced; color: #008000;">&#xa0;&#xa0;template: </span>
    </p>
    <p>
      <span style="font-family: Monospaced; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;src: index.j2 </span>
    </p>
