<node TEXT="Функции" ID="ID_627145436" CREATED="1772093317897" MODIFIED="1772094333326"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Функции</span>
    </p>
    <p>
      
    </p>
