<node TEXT="# История" ID="ID_401300902" CREATED="1536484593798" MODIFIED="1579267117467"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1069;&#1074;&#1086;&#1083;&#1102;&#1094;&#1080;&#1103; web &#1089;&#1072;&#1081;&#1090;&#1086;&#1074;</b>
    </p>
    <ul>
      <li>
        <b>Web 1.0</b>&#160;- &#1076;&#1086; .com bubble. &#1057;&#1090;&#1072;&#1090;&#1080;&#1095;&#1085;&#1086;&#1077; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1085;&#1080;&#1077; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;, &#1072;&#1089;&#1082;&#1077;&#1090;&#1080;&#1095;&#1085;&#1099;&#1081; &#1076;&#1080;&#1079;&#1072;&#1081;&#1085;, &#1095;&#1072;&#1090;&#1099;, &#1092;&#1086;&#1088;&#1091;&#1084;&#1099;, &#1075;&#1086;&#1089;&#1090;&#1077;&#1074;&#1099;&#1077; &#1082;&#1085;&#1080;&#1075;&#1080;. &#1057;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1099;&#1084; &#1089;&#1072;&#1081;&#1090;&#1072; &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;&#1089;&#1103; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;
      </li>
      <li>
        <b>Web 2.0</b>&#160;- User-generated content (&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1080; &#1084;&#1086;&#1075;&#1091;&#1090; &#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1089;&#1090;&#1072;&#1090;&#1100;&#1080;, &#1086;&#1073;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103;). &#1087;&#1086;&#1082;&#1086;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1072;&#1081;&#1090;&#1086;&#1074; &#1087;&#1086;&#1089;&#1083;&#1077; 2001 &#1075;&#1086;&#1076;&#1072; . &#1055;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1080; &#1087;&#1086;&#1090;&#1088;&#1077;&#1073;&#1083;&#1077;&#1085;&#1080;&#1077; API. RSS. &#1054;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094; &quot;&#1085;&#1072; &#1083;&#1077;&#1090;&#1091;&quot; (ajax). &#1052;&#1101;&#1096;&#1072;&#1087; &#8212; &#1101;&#1090;&#1086; &#1074;&#1077;&#1073;-&#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;, &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1103;&#1102;&#1097;&#1077;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1080;&#1079; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1080;&#1093; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1086;&#1074; &#1074; &#1086;&#1076;&#1080;&#1085; &#1080;&#1085;&#1090;&#1077;&#1075;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1080;&#1085;&#1089;&#1090;&#1088;&#1091;&#1084;&#1077;&#1085;&#1090;; &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1087;&#1088;&#1080; &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1080; &#1082;&#1072;&#1088;&#1090;&#1086;&#1075;&#1088;&#1072;&#1092;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; Google Maps &#1089; &#1076;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1086; &#1085;&#1077;&#1076;&#1074;&#1080;&#1078;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1089; Craigslist &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1086;&#1074;&#1099;&#1081; &#1091;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1080;&#1089;, &#1080;&#1079;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086; &#1085;&#1077; &#1087;&#1088;&#1077;&#1076;&#1083;&#1072;&#1075;&#1072;&#1077;&#1084;&#1099;&#1081; &#1085;&#1080; &#1086;&#1076;&#1085;&#1080;&#1084; &#1080;&#1079; &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082;&#1086;&#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;.<br/>&#1041;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; - &#1101;&#1090;&#1086; &#1054;&#1057;.
      </li>
      <li>
        <b>Web 3.0</b>&#160;- Community-generation content. &#1057;&#1077;&#1084;&#1072;&#1085;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1087;&#1072;&#1091;&#1090;&#1080;&#1085;&#1072; - &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099; &#1087;&#1086;&#1085;&#1103;&#1090;&#1085;&#1099; &#1088;&#1086;&#1073;&#1086;&#1090;&#1072;&#1084;. &#1059;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1099; &#1080; &#1084;&#1080;&#1082;&#1088;&#1086;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1099;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      1969-70 - UNIX, tcp/ip
    </p>
    <p>
      1989-92 - &#1047;&#1072;&#1088;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077; WWW
    </p>
    <p>
      1995-96 - &#1048;&#1085;&#1090;&#1077;&#1075;&#1088;&#1072;&#1094;&#1080;&#1103; js &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1099;. Apache, MySQL, PHP, ASP
    </p>
    <p>
      1995-2000 - MySQL 3.23, jsp
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="# Как работает сайт" ID="ID_736196031" CREATED="1536487284395" MODIFIED="1563853730958"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1143233258">DNS</a>&#160;&#160;&#160;<a href="#ID_746161295">Web server</a>&#160;&#160;&#160;<a href="#ID_66090749">&#1041;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;</a>&#160;&#160; <a href="#ID_1914210795">HTTP</a>&#160;&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1040;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1072;</b>
    </p>
    <p>
      <b>&#1050;&#1083;&#1080;&#1077;&#1085;&#1090;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1086;&#1077; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077;.</b>&#160;&#1050;&#1083;&#1080;&#1077;&#1085;&#1090; - &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; - web &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;.
    </p>
    <ul>
      <li>
        &#1050;&#1083;&#1080;&#1077;&#1085;&#1090; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;:&#160;&#160;&#1054;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        &#1050;&#1083;&#1080;&#1077;&#1085;&#1090; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1086;&#1090;&#1074;&#1077;&#1090;
      </li>
    </ul>
    <p>
      <b>&#1056;&#1077;&#1089;&#1091;&#1088;&#1089;&#1099; &#1080; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1094;&#1080;&#1103;</b>
    </p>
    <ul>
      <li>
        &#1050;&#1083;&#1080;&#1077;&#1085;&#1090; &#1079;&#1072;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1077;&#1090; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089; &#1089; &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1086;&#1084; (URL). &#1057;&#1077;&#1088;&#1074;&#1077;&#1088; &#1086;&#1090;&#1076;&#1072;&#1077;&#1090; &#1101;&#1090;&#1086;&#1090; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;.
      </li>
    </ul>
    <p>
      <b>&#1047;&#1072;&#1087;&#1088;&#1086;&#1089; - &#1086;&#1090;&#1074;&#1077;&#1090;</b>
    </p>
    <ul>
      <li>
        &#1047;&#1072;&#1087;&#1088;&#1086;&#1089; - &#1086;&#1090;&#1074;&#1077;&#1090; - &#1101;&#1090;&#1086; &#1086;&#1076;&#1085;&#1086; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        <b>RFC822</b>&#160;- Internet Text Message format. &#1060;&#1086;&#1088;&#1084;&#1072;&#1090; &#1087;&#1086;&#1095;&#1090;&#1086;&#1074;&#1099;&#1093; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1086;&#1074;
      </li>
    </ul>
    <p>
      ----------
    </p>
    <ol>
      <li>
        &#1042; &#1072;&#1076;&#1088;&#1077;&#1089;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; &#1074;&#1073;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; ya.ru (&#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103;)
      </li>
      <li>
        DNS LOOKUP. &#1044;&#1086;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; IP-&#1072;&#1076;&#1088;&#1077;&#1089;. &#1041;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091; DNS &#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; IP
      </li>
      <li>
        &#1041;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1090; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089; web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. <b>&#1059;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; (TCP)</b>. &#1041;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1086;&#1090;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090; &#1089;&#1086;&#1082;&#1077;&#1090; (&#1092;&#1072;&#1081;&#1083; &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1080; &#1080;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1095;&#1080;&#1090;&#1072;&#1090;&#1100;), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1089; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1086;&#1081; &#1084;&#1072;&#1096;&#1080;&#1085;&#1086;&#1081;. <b>&#1054;&#1090;&#1087;&#1088;&#1072;&#1074;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;</b>&#160;&#1074; HTTP &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077;
      </li>
      <li>
        Web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; <b>&#1087;&#1088;&#1080;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;</b>&#160;&#1087;&#1086; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1091; HTTP --&gt; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1091;&#1077;&#1090; &#1077;&#1075;&#1086; --&gt; &#1080;&#1079;&#1074;&#1083;&#1077;&#1082;&#1072;&#1077;&#1090; &#1086;&#1090;&#1090;&#1091;&#1076;&#1072; URL --&gt; &#1087;&#1086; URL &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1082;&#1072;&#1082;&#1086;&#1081; &#1092;&#1072;&#1081;&#1083; &#1085;&#1091;&#1078;&#1085;&#1086; &#1086;&#1090;&#1076;&#1072;&#1090;&#1100; --&gt; &#1086;&#1090;&#1076;&#1072;&#1077;&#1090; &#1092;&#1072;&#1081;&#1083;.
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103;, &#1090;&#1086; Web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1084;&#1086;&#1078;&#1077;&#1090; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; CGI-&#1089;&#1082;&#1088;&#1080;&#1087;&#1090; --&gt; CGI &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1091;&#1077;&#1090; HTML-&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;
      </li>
      <li>
        &#1041;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;, &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1074; HTML-&#1092;&#1072;&#1081;&#1083;, &#1086;&#1090;&#1088;&#1080;&#1089;&#1086;&#1074;&#1099;&#1074;&#1072;&#1077;&#1090; &#1077;&#1075;&#1086; (&#1087;&#1072;&#1088;&#1089;&#1080;&#1085;&#1075; HTML &#1080; &#1087;&#1086;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1080;&#1077; <a href="#ID_1729317984">DOM</a>) --&gt; &#1055;&#1088;&#1080; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1087;&#1086;&#1076;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1090; CSS &#1092;&#1072;&#1081;&#1083; --&gt; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090; &#1089;&#1090;&#1080;&#1083;&#1080; CSS --&gt; &#1077;&#1089;&#1083;&#1080; &#1077;&#1089;&#1090;&#1100; &#1089;&#1089;&#1099;&#1083;&#1082;&#1080; &#1085;&#1072; JavaScript, &#1090;&#1086; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1090; &#1092;&#1072;&#1081;&#1083;&#1099; &#1089; JS &#1080; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090; &#1080;&#1093;. &#1047;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1093; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1074;.
