<node TEXT="CAPTCHA" ID="ID_619010388" CREATED="1591784992467" MODIFIED="1591785903939"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>CAPTCHA</b>&#160;(Completely Automated Public Turing test to tell Computers and Humans Apart), <b>&#1082;&#1072;&#1087;&#1095;&#1072; </b>
    </p>
    <p>
      &#1055;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081; &#1087;&#1091;&#1073;&#1083;&#1080;&#1095;&#1085;&#1099;&#1081; &#1090;&#1077;&#1089;&#1090; &#1058;&#1100;&#1102;&#1088;&#1080;&#1085;&#1075;&#1072; &#1076;&#1083;&#1103; &#1088;&#1072;&#1079;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1086;&#1074; &#1080; &#1083;&#1102;&#1076;&#1077;&#1081;)
    </p>
    <p>
      &#1050;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1085;&#1099;&#1081; &#1090;&#1077;&#1089;&#1090;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1081; &#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100;, &#1082;&#1077;&#1084; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;: &#1095;&#1077;&#1083;&#1086;&#1074;&#1077;&#1082;&#1086;&#1084; &#1080;&#1083;&#1080; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1086;&#1084;.
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        <b>1 &#1055;&#1086;&#1082;&#1086;&#1083;&#1077;&#1085;&#1080;&#1077;</b>&#160;- &#1082;&#1083;&#1080;&#1082;&#1072;&#1077;&#1084; &#1085;&#1072; &#1075;&#1072;&#1083;&#1086;&#1095;&#1082;&#1091; &quot;&#1071; &#1085;&#1077; &#1088;&#1086;&#1073;&#1086;&#1090;&quot;
      </li>
      <li>
        <b>2 &#1055;&#1086;&#1082;&#1086;&#1083;&#1077;&#1085;&#1080;&#1077;&#160;(v2)</b>&#160;- &#1088;&#1077;&#1096;&#1080;&#1090;&#1100; &#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1083;&#1086;&#1084;&#1082;&#1091; (&#1074;&#1099;&#1073;&#1088;&#1072;&#1090;&#1100; &#1072;&#1074;&#1090;&#1086;&#1073;&#1091;&#1089;&#1099;)
      </li>
      <li>
        <b>3 &#1055;&#1086;&#1082;&#1086;&#1083;&#1077;&#1085;&#1080;&#1077; (v3)</b>&#160;- &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1082;&#1072; &#1082; <b>google.com/recaptcha</b>. &#1040;&#1085;&#1072;&#1083;&#1080;&#1079; &#1087;&#1086;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1080; &#1089;&#1090;&#1080;&#1083;&#1103; &#1074;&#1074;&#1086;&#1076;&#1072;. &#1043;&#1086;&#1083;&#1086;&#1074;&#1086;&#1083;&#1086;&#1084;&#1082;&#1080; &#1086;&#1090;&#1075;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086;
      </li>
    </ul>
  </body>
</html></richcontent>
