<node TEXT="URN" ID="ID_160533741" CREATED="1536490723687" MODIFIED="1571651583239"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>URN</b>&#160;(Uniform Resource Name) &#8212; &#1077;&#1076;&#1080;&#1085;&#1086;&#1086;&#1073;&#1088;&#1072;&#1079;&#1085;&#1086;&#1077; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; (&#1080;&#1084;&#1103;) &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1072;. URN &#8212; &#1101;&#1090;&#1086; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1072;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074;, &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1091;&#1102;&#1097;&#1072;&#1103; &#1072;&#1073;&#1089;&#1090;&#1088;&#1072;&#1082;&#1090;&#1085;&#1099;&#1081; &#1080;&#1083;&#1080; &#1092;&#1080;&#1079;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;.
    </p>
    <ul>
      <li>
        URN &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1095;&#1072;&#1089;&#1090;&#1100;&#1102; &#1082;&#1086;&#1085;&#1094;&#1077;&#1087;&#1094;&#1080;&#1080; URI
      </li>
      <li>
        &#1080;&#1084;&#1077;&#1085;&#1072; URN, &#1074; &#1086;&#1090;&#1083;&#1080;&#1095;&#1080;&#1077; &#1086;&#1090; URL, &#1085;&#1077; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1102;&#1090; &#1074; &#1089;&#1077;&#1073;&#1103; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1103; &#1085;&#1072; &#1084;&#1077;&#1089;&#1090;&#1086;&#1085;&#1072;&#1093;&#1086;&#1078;&#1076;&#1077;&#1085;&#1080;&#1077; &#1080; &#1089;&#1087;&#1086;&#1089;&#1086;&#1073; &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1103; &#1082; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1091;
      </li>
      <li>
        &#1057;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090; URN &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086; &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085; &#1090;&#1072;&#1082;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1085; &#1084;&#1086;&#1075; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1074; &#1089;&#1077;&#1073;&#1103; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1087;&#1088;&#1086;&#1089;&#1090;&#1088;&#1072;&#1085;&#1089;&#1090;&#1074;&#1072; &#1080;&#1084;&#1105;&#1085;.
      </li>
      <li>
        &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088; &#1074; jabber-&#1089;&#1077;&#1090;&#1080;
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="WAP-сайт" ID="ID_1009936173" CREATED="1533754720318" MODIFIED="1607630412143"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1698633245">WAP</a>&#160;&#160; <a href="#ID_579920365">WML</a>&#160;&#160; <a href="#ID_666472769">WTP</a>
    </p>
    <p>
      &#160;&#160;
    </p>
    <p>
      <b>&#1052;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1099;&#1081; &#1089;&#1072;&#1081;&#1090;</b>&#160; &#8212; &#1089;&#1072;&#1081;&#1090;, &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1085;&#1099;&#1081; &#1074; &#1089;&#1077;&#1090;&#1080; &#1083;&#1080;&#1073;&#1086; &#1085;&#1072; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1077; &#1087;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1105;&#1085;&#1085;&#1086;&#1084;&#1091; &#1072;&#1076;&#1088;&#1077;&#1089;&#1091; (&#1076;&#1086;&#1084;&#1077;&#1085;&#1091;), &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072; &#1085;&#1072; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1099;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;&#1093;, &#1095;&#1072;&#1097;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1072; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;.
    </p>
    <p>
      
    </p>
    <p>
      <b>WAP-&#1089;&#1072;&#1081;&#1090;</b>&#160;&#8212; &#1101;&#1090;&#1086; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1105;&#1085;&#1085;&#1099;&#1081; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084; &#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1084; (&#1076;&#1086;&#1084;&#1077;&#1085;&#1086;&#1084;) &#1080;&#1089;&#1090;&#1086;&#1095;&#1085;&#1080;&#1082; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1074; &#1089;&#1077;&#1090;&#1080; &#1048;&#1085;&#1090;&#1077;&#1088;&#1085;&#1077;&#1090;, &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1076;&#1083;&#1103; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1086;&#1084; (&#1089;&#1086;&#1090;&#1086;&#1074;&#1086;&#1084;) &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1077; &#1080;&#1083;&#1080; &#1080;&#1085;&#1086;&#1084; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1086;&#1084; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1077; &#1080;&#1083;&#1080; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1077; &#1087;&#1088;&#1080; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1080; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1074;, &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1097;&#1080;&#1093; &#1101;&#1090;&#1091; &#1090;&#1077;&#1093;&#1085;&#1086;&#1083;&#1086;&#1075;&#1080;&#1102;.
    </p>
    <p>
      &#1057;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1077;&#1084; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#171;WAP-&#1089;&#1072;&#1081;&#1090;&#187; &#1089;&#1090;&#1072;&#1083;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1082;&#1086; &#1074;&#1089;&#1077;&#1084; &#1089;&#1072;&#1081;&#1090;&#1072;&#1084;, &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1086; &#1087;&#1088;&#1077;&#1076;&#1085;&#1072;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1085;&#1099;&#1084; &#1076;&#1083;&#1103; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1076;&#1080;&#1089;&#1087;&#1083;&#1077;&#1103;&#1093; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1099;&#1093; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;, &#1074;&#1085;&#1077; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; (WAP, GPRS, 3G).
    </p>
    <p>
      WAP-&#1089;&#1072;&#1081;&#1090; &#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1089;&#1086;&#1079;&#1076;&#1072;&#1105;&#1090;&#1089;&#1103; &#1089; &#1091;&#1095;&#1105;&#1090;&#1086;&#1084; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1091;&#1089;&#1083;&#1086;&#1074;&#1080;&#1081;:
    </p>
    <ul>
      <li>
        &#1059;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; &#1103;&#1079;&#1099;&#1082;&#1072;. WAP-&#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1085;&#1077; &#1074;&#1089;&#1077; &#1090;&#1077;&#1075;&#1080; &#1103;&#1079;&#1099;&#1082;&#1072; &#1088;&#1072;&#1079;&#1084;&#1077;&#1090;&#1086;&#1082; HTML, &#1074; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1077; &#1095;&#1077;&#1075;&#1086; &#171;HTML-&#1089;&#1072;&#1081;&#1090;&#187; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1082;&#1086;&#1088;&#1088;&#1077;&#1082;&#1090;&#1085;&#1086; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1076;&#1080;&#1089;&#1087;&#1083;&#1077;&#1077; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1072;. &#1042; &#1095;&#1072;&#1089;&#1090;&#1085;&#1086;&#1089;&#1090;&#1080;, &#1076;&#1083;&#1103; WAP-&#1089;&#1072;&#1081;&#1090;&#1086;&#1074; &#1073;&#1099;&#1083; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085; &#1082;&#1086;&#1085;&#1089;&#1086;&#1088;&#1094;&#1080;&#1091;&#1084;&#1086;&#1084; WAP Forum &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1103;&#1079;&#1099;&#1082; &#1088;&#1072;&#1079;&#1084;&#1077;&#1090;&#1086;&#1082; &#8212; WML;
      </li>
      <li>
        &#1059;&#1089;&#1083;&#1086;&#1074;&#1080;&#1077; &#1090;&#1088;&#1072;&#1092;&#1080;&#1082;&#1072;. WAP-&#1090;&#1088;&#1072;&#1092;&#1080;&#1082; &#1080;&#1079;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086; &#1089;&#1090;&#1086;&#1080;&#1083; &#1075;&#1086;&#1088;&#1072;&#1079;&#1076;&#1086; &#1076;&#1086;&#1088;&#1086;&#1078;&#1077;, &#1095;&#1077;&#1084; GPRS-&#1090;&#1088;&#1072;&#1092;&#1080;&#1082;, &#1087;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; WAP-&#1089;&#1072;&#1081;&#1090; &#1074; &#1080;&#1085;&#1090;&#1077;&#1088;&#1077;&#1089;&#1072;&#1093; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1083; &#1080;&#1084;&#1077;&#1090;&#1100; &#1085;&#1077;&#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;. &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1074; &#1085;&#1077;&#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1084;&#1086;&#1076;&#1077;&#1083;&#1103;&#1093; &#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1099;&#1093; &#1090;&#1077;&#1083;&#1077;&#1092;&#1086;&#1085;&#1086;&#1074; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1087;&#1086;&#1076;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084;&#1099;&#1093; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1082; &#1073;&#1099;&#1083; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1085;&#1086; (&#1086;&#1082;&#1086;&#1083;&#1086; 3 &#1082;&#1080;&#1083;&#1086;&#1073;&#1072;&#1081;&#1090;).
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT=" App-сервер (сервер приложений)" ID="ID_1918148420" CREATED="1519112080217" MODIFIED="1760958364372"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_746161295">Web-сервер</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Сервер приложений (Application Server)</span>&#xa0;- программная платформа для выполнения кода веб-приложений. Обеспечивает запуск динамической логики, управление сессиями, транзакциями, безопасностью и другими сервисами. Позволяет разработчику сосредоточиться на бизнес-логике.
    </p>
    <ul>
      <li>
        В отличие от веб-сервера (Nginx, Apache), который отдаёт статику и проксирует запросы, сервер приложений <span style="font-weight: bold;">выполняет само приложение</span>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Путь запроса в типовой архитектуре</span>
    </p>
    <ol>
      <li>
        WAF - фильтрация вредоносных запросов
      </li>
      <li>
        Балансировщик нагрузки - распределение трафика
      </li>
      <li>
        Кэш - возврат ответа из кэша, если возможно
      </li>
      <li>
        Веб-сервер - отдача статики или проксирование
      </li>
      <li>
        <span style="font-weight: bold;">Сервер приложений</span>&#xa0;- выполнение бизнес-логики
      </li>
      <li>
        База данных - хранение и выборка данных
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console;">| Экосистема&#xa0;&#xa0;| Веб-сервер (front-end) | Сервер приложений (app server)&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">|-------------|------------------------|-------------------------------------| </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">| Python&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Nginx, Apache&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Gunicorn, uWSGI, Waitress&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">| Java&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Nginx, Apache HTTPD&#xa0;&#xa0;&#xa0;&#xa0;| Tomcat, WildFly, Jetty&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">| Node.js&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Nginx&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Сам Node.js (часто играет обе роли) | </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">| Ruby&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Nginx&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Puma, Unicorn, Passenger&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">| PHP&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| Nginx, Apache&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| PHP-FPM&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;| </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">| Go (Golang)&#xa0;| часто не требуется)&#xa0;&#xa0;&#xa0;&#xa0;| Собственный HTTP-сервер в приложении|</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Web-сервер" FOLDED="true" ID="ID_746161295" CREATED="1519112080250" MODIFIED="1775221139590"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1918148420">App-сервер</a>&#xa0;&#xa0;<a href="#ID_501818183">PHP</a>&#xa0; <a href="#ID_1685390784">SAPI</a>&#xa0;&#xa0;<a href="#ID_705480727">VPS/VDS (шаблоны)</a>&#xa0; <a href="#ID_1009203346">SSL/TLS</a>&#xa0;&#xa0;<a href="#ID_1914210795">HTTP</a>&#xa0; <a href="#ID_1404821710">Локальный web-сервер</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Веб-сервер</b>&#xa0;— сервер, принимающий HTTP-запросы от клиентов, обычно веб-браузеров, и выдающий им HTTP-ответы, как правило, вместе с HTML-страницей, изображением, файлом, медиа-потоком или другими данными. Веб-сервером называют как ПО, выполняющее функции веб-сервера, так и непосредственно компьютер, на котором это ПО работает
    </p>
    <ul>
      <li>
        Типы веб-серверов: <b>Акселераторы</b>&#xa0;(Nginx, Apache HTTP Server, ...), <b>Серверы приложений</b>&#xa0;&#xa0;(Apache Tomcat, ...)
      </li>
      <li>
        <b>многопоточные</b>&#xa0;(multi thread), <b>многопроцессные</b>&#xa0;(multi process) веб-серверы
      </li>
      <li>
        Веб-серверы могут иметь различные функции:

        <ul>
          <li>
            проксирование на бэкенд
          </li>
          <li>
            аутентификация и авторизация пользователей
          </li>
          <li>
            автоматизация работы веб-страниц
          </li>
          <li>
            SSL. поддержка шифрования трафика (поддержка HTTPS для защищённых соединений с клиентами)
          </li>
          <li>
            логирование запросов (ведение журнала обращений пользователей к ресурсам)
          </li>
          <li>
            запуск приложений (<a href="#ID_1685390784">CGI</a>)
          </li>
          <li>
            поддержка динамически генерируемых страниц
          </li>
          <li>
            URL Rewrite
          </li>
          <li>
            кэширование
          </li>
          <li>
            сжатие трафика (gzip, ...)
          </li>
        </ul>
      </li>
      <li>
        <p>
          каждый сайт имеет такое понятие как <b>binding</b>&#xa0;(4 уникальных значения, которые идентифицируют сайт в пределах веб-сервера
        </p>
        <ol>
          <li>
            protocol
          </li>
          <li>
            IP-адрес
          </li>
          <li>
            hostname
          </li>
          <li>
            port
          </li>
        </ol>
      </li>
      <li>
        <p>
          В пределах LAN можно поднять сайт на локальном Веб-сервере
        </p>
        <ul>
          <li>
            Website
          </li>
          <li>
            портал обмена сообщениями
          </li>
          <li>
            электронный документооборот
          </li>
          <li>
            система учета заявок в IT-отдел (см. <a href="#ID_1473300892">GLPI</a>)
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Web серверы:</span>
    </p>
    <ul>
      <li>
        Apache HTTP Server (httpd)
      </li>
      <li>
        Nginx
      </li>
      <li>
        Caddy - позиционирует себя как более простая и автоматизированная альтернатива классическим Nginx и Apache. Его главная особенность - Automatic HTTPS: сервер сам получает и продлевает SSL-сертификаты через Let's Encrypt без использования внешних утилит вроде Certbot
      </li>
    </ul>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
