<node TEXT="# Процесс обслуживания запроса к веб-серверу" ID="ID_119675656" CREATED="1550580134045" MODIFIED="1571396075857"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1058;&#1080;&#1087;&#1080;&#1095;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1082; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;</b>&#160; &#1080; &#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1072; &#1089;&#1072;&#1084;&#1086;&#1075;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;:
    </p>
    <ol>
      <li>
        &#1050;&#1083;&#1080;&#1077;&#1085;&#1090; &#1080;&#1085;&#1080;&#1094;&#1080;&#1080;&#1088;&#1091;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;
      </li>
      <li>
        &#1045;&#1075;&#1086; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084;.
      </li>
      <li>
        &#1042;&#1072;&#1096; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, Apache) &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090; &#1085;&#1086;&#1074;&#1099;&#1081; &#1087;&#1086;&#1090;&#1086;&#1082;/&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1076;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;.
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1080;&#1083; <b>&#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;</b>&#160;(&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1082; php-&#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1091;), &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; <a href="#ID_245151265">CGI</a>-&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1080;&#1083;&#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, <b>mod_php</b>) &#1080; &#1078;&#1076;&#1077;&#1090;, &#1087;&#1086;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085;. &#1050;&#1072;&#1082; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1086;&#1085; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090;&#160;&#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1080;&#1088;&#1091;&#1102;&#1097;&#1091;&#1102; web-&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091;, &#1090;&#1086; &#1086;&#1085;&#1072; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1078;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1080;&#1083; <b>&#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1092;&#1072;&#1081;&#1083;</b>, &#1090;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1088;&#1086;&#1089;&#1090;&#1086; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1101;&#1090;&#1086;&#1090; &#1092;&#1072;&#1081;&#1083; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091;
      </li>
      <li>
        &#1041;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; &#1086;&#1090;&#1074;&#1077;&#1090;, &#1079;&#1072;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1089; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084; &#1080; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1077;&#1090; &quot;&#1086;&#1090;&#1074;&#1077;&#1090;&quot;
      </li>
    </ol>
    <p>
      &#1045;&#1089;&#1083;&#1080; &#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1087;&#1088;&#1080;&#1093;&#1086;&#1076;&#1080;&#1090; <b>&#1086;&#1095;&#1077;&#1085;&#1100; &#1084;&#1085;&#1086;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;</b>, &#1086;&#1085; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1084;&#1085;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1072;&#1083;&#1083;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1087;&#1086;&#1090;&#1086;&#1082;&#1086;&#1074;/&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1074; &#1080; &#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1080;&#1093; &#1074; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;, &#1087;&#1086;&#1082;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090; &#1085;&#1077; &#1079;&#1072;&#1082;&#1088;&#1086;&#1077;&#1090; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;. &#1045;&#1089;&#1083;&#1080; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1091; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; &#1085;&#1077; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;&#1077;, &#1090;&#1086; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1099; &#1073;&#1091;&#1076;&#1091;&#1090; &#1074;&#1080;&#1089;&#1077;&#1090;&#1100; &#1074; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1076;&#1086;&#1083;&#1075;&#1086; &#1080; <b>&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1077; &#1080;&#1084;&#1080; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1099; &#1073;&#1091;&#1076;&#1091;&#1090; &#1091;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1086;&#1095;&#1077;&#1085;&#1100; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;</b>.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1100; nginx (&#1084;&#1086;&#1078;&#1085;&#1086; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; reverse proxy) &#1087;&#1077;&#1088;&#1077;&#1076; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1084; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084;</b>&#160;&#1080; &#1076;&#1072;&#1090;&#1100; &#1077;&#1084;&#1091; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1082; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084; &#1092;&#1072;&#1081;&#1083;&#1072;&#1084;, &#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1082; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1082;&#1077; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1082; &#1075;&#1083;&#1072;&#1074;&#1085;&#1086;&#1084;&#1091; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;. &#1055;&#1088;&#1080; &#1090;&#1072;&#1082;&#1086;&#1084; &#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1076;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1074; &#1076;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094; &#1080; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1099; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; &#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1086;&#1084;&#1091; frontend-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091; &#1086;&#1095;&#1077;&#1085;&#1100; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086;, &#1095;&#1090;&#1086; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1080;&#1090; &#1077;&#1084;&#1091; &#1086;&#1089;&#1074;&#1086;&#1073;&#1086;&#1076;&#1080;&#1090;&#1100; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1099; &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1077; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;. &#1052;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1080;&#1081; frontend &#1078;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1078;&#1076;&#1072;&#1090;&#1100; &#1089;&#1082;&#1086;&#1083;&#1100; &#1091;&#1075;&#1086;&#1076;&#1085;&#1086; &#1076;&#1086;&#1083;&#1075;&#1086;, &#1087;&#1086;&#1082;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090; &#1079;&#1072;&#1073;&#1077;&#1088;&#1077;&#1090; &#1089;&#1074;&#1086;&#1081; &quot;&#1086;&#1090;&#1074;&#1077;&#1090;&quot; &#1080; &#1079;&#1072;&#1082;&#1088;&#1086;&#1077;&#1090; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;, &#1072; backend &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1090;&#1088;&#1072;&#1090;&#1080;&#1090;&#1100; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1099; &#1076;&#1083;&#1103; &#1101;&#1090;&#1086;&#1075;&#1086;.
    </p>
    <p>
