    </p>
    <p>
      &#1069;&#1090;&#1091; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1072;&#1085;&#1072;&#1083;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1077;&#1089;&#1083;&#1080; &#1074;&#1099; &#1079;&#1072;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090;&#1077;&#1089;&#1100; &#1087;&#1088;&#1080;&#1077;&#1084;&#1086;&#1084; &#1080; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1086;&#1081; POST-&#1092;&#1086;&#1088;&#1084;&#1099;.
    </p>
    <p>
      <b>CONTENT_TYPE</b>&#160;- &#1090;&#1080;&#1087; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1099;&#1093; &#1074; POST &#1080;&#1083;&#1080; PUT &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1073;&#1077;&#1088;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; Content-Type &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;.
    </p>
    <p>
      <b>GATEWAY_INTERFACE</b>&#160;- &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1072;&#1103; &#1074;&#1077;&#1088;&#1089;&#1080;&#1103; CGI. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#171;CGI/1.1&#187;.
    </p>
    <p>
      <b>HTTP_ACCEPT</b>&#160;- &#1074;&#1089;&#1077; MIME-&#1090;&#1080;&#1087;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1074;&#1086;&#1089;&#1087;&#1088;&#1080;&#1085;&#1103;&#1090;&#1099; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1084;
    </p>
    <p>
      <b>HTTP_COOKIE</b>&#160;- &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1082; Cookie
    </p>
    <p>
      <b>HTTP_HOST</b>&#160;- &#1044;&#1086;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103; Web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1083;&#1089;&#1103; &#1089;&#1094;&#1077;&#1085;&#1072;&#1088;&#1080;&#1081;. &#1059;&#1076;&#1086;&#1073;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1075;&#1077;&#1085;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080; &#1087;&#1086;&#1083;&#1085;&#1086;&#1075;&#1086; &#1087;&#1091;&#1090;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1077; Location, &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084;&#1091; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1091;. &#1045;&#1089;&#1083;&#1080; &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1083;&#1086;&#1089;&#1100; &#1082; &#1085;&#1077;&#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1086;&#1084;&#1091;, &#1086;&#1090;&#1083;&#1080;&#1095;&#1085;&#1086;&#1084;&#1091; &#1086;&#1090; 80-&#1075;&#1086;, &#1087;&#1086;&#1088;&#1090;&#1091; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, 81 &#1080;&#1083;&#1080; 8080), &#1090;&#1086; HTTP_HOST &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1090;&#1072;&#1082;&#1078;&#1077; &#1080; &#1085;&#1086;&#1084;&#1077;&#1088; &#1087;&#1086;&#1088;&#1090;&#1072;
    </p>
    <p>
      <b>HTTP_REFERER</b>&#160;- &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1082; Referer. &#1047;&#1072;&#1076;&#1072;&#1077;&#1090; &#1080;&#1084;&#1103; &#1076;&#1086;&#1082;&#1091;&#1084;&#1077;&#1085;&#1090;&#1072;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1092;&#1086;&#1088;&#1084;&#1072;, &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1074;&#1096;&#1072;&#1103; CGI-&#1089;&#1094;&#1077;&#1085;&#1072;&#1088;&#1080;&#1081;. &#1052;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1090;&#1089;&#1083;&#1077;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1087;&#1086; &#1089;&#1072;&#1081;&#1090;&#1091;
    </p>
    <p>
      <b>HTTP_USER_AGENT</b>&#160;- &#1048;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1094;&#1080;&#1088;&#1091;&#1077;&#1090; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1087;&#1086;&#1076;&#1089;&#1090;&#1088;&#1086;&#1082;&#1072; MSIE, &#1090;&#1086; &#1101;&#1090;&#1086; Internet Explorer, &#1074; &#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1085;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1074; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1080; &#1083;&#1080;&#1096;&#1100; &#1089;&#1083;&#1086;&#1074;&#1086; Mozilla - Firefox, Chrome &#1080;&#1083;&#1080; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;
    </p>
    <p>
      <b>PATH_INFO</b>&#160;- &#1095;&#1072;&#1089;&#1090;&#1100; &#1087;&#1091;&#1090;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1091;&#1090;&#1080; &#1082; CGI-&#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1102;, &#1085;&#1086; &#1076;&#1086; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1076;&#1083;&#1103; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &quot;/somewhere/cgiapp.exe/test/?qwerty=123&quot; &#1101;&#1090;&#1086; &#1073;&#1091;&#1076;&#1077;&#1090; &quot;/test/&quot;.
    </p>
    <p>
      <b>PATH_TRANSLATED</b>&#160;- &#1090;&#1086; &#1078;&#1077; &#1089;&#1072;&#1084;&#1086;&#1077;, &#1095;&#1090;&#1086; &#1080; PATH_INFO, &#1085;&#1086; &#1089;&#1087;&#1088;&#1086;&#1077;&#1094;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1077; &#1085;&#1072; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1091;&#1102; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1091;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &quot;./htdocs/test/&quot;.
    </p>
    <p>
      <b>QUERY_STRING</b>&#160;- &#1089;&#1090;&#1088;&#1086;&#1082;&#1072; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; (&#1074; URL &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1099; &#1087;&#1086;&#1089;&#1083;&#1077; &#1074;&#1086;&#1087;&#1088;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1079;&#1085;&#1072;&#1082;&#1072;). &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099; &#1082;&#1072;&#1082; &#1087;&#1088;&#1080; &#1084;&#1077;&#1090;&#1086;&#1076;&#1077; GET, &#1090;&#1072;&#1082; &#1080; &#1087;&#1088;&#1080; &#1084;&#1077;&#1090;&#1086;&#1076;&#1077; POST (&#1077;&#1089;&#1083;&#1080; &#1073;&#1099;&#1083;&#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1099; &#1074; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1077; action &#1090;&#1077;&#1075;&#1072; &lt;form&gt;). &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#171;qwerty=123&#187;.
    </p>
    <p>
      <b>REMOTE_ADDR</b>&#160;- IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1091;&#1079;&#1083;&#1072; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;
    </p>
    <p>
      <b>REMOTE_HOST</b>&#160;- &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1088;&#1072;&#1074;&#1085;&#1086; REMOTE_ADDR.
    </p>
    <p>
      <b>REMOTE_IDENT</b>&#160;- &#1080;&#1076;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1089;&#1086;&#1075;&#1083;&#1072;&#1089;&#1085;&#1086; RFC 1314. &#1048;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1088;&#1077;&#1076;&#1082;&#1086;.
    </p>
    <p>
      <b>REMOTE_PORT</b>&#160;- &#1055;&#1086;&#1088;&#1090;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1079;&#1072;&#1082;&#1088;&#1077;&#1087;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1086;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1086;&#1090;&#1074;&#1077;&#1090;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <p>
      <b>REMOTE_USER</b>&#160;- &#1080;&#1084;&#1103; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1085;&#1086;&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;, &#1087;&#1088;&#1086;&#1096;&#1077;&#1076;&#1096;&#1077;&#1075;&#1086; HTTP-&#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1102;.
    </p>
    <p>
      <b>REQUEST_METHOD</b>&#160;- &#1084;&#1077;&#1090;&#1086;&#1076; (GET, POST... &#1089;&#1084;. &#1052;&#1077;&#1090;&#1086;&#1076;&#1099; HTTP-&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
    </p>
    <p>
      <b>SCRIPT_NAME</b>&#160;- &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1102;&#1097;&#1077;&#1075;&#1086;&#1089;&#1103; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1072; (&#1090;. &#1077;. &#1095;&#1072;&#1089;&#1090;&#1100; URL &#1087;&#1086;&#1089;&#1083;&#1077; &#1080;&#1084;&#1077;&#1085;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;, &#1085;&#1086; &#1076;&#1086; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1072; ?). &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &quot;/somewhere/cgiapp.exe&quot;. &#1059;&#1076;&#1086;&#1073;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080; &#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; Location &#1087;&#1088;&#1080; &quot;&#1087;&#1077;&#1088;&#1077;&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1094;&#1080;&#1080; &#1085;&#1072; &#1089;&#1077;&#1073;&#1103;&quot; (selfredirect), &#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1087;&#1088;&#1080; &#1087;&#1088;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1072;&#1090;&#1088;&#1080;&#1073;&#1091;&#1090;&#1072; action &#1090;&#1077;&#1075;&#1072; &lt;form&gt; &#1085;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1091;&#1102; &#1074;&#1099;&#1076;&#1072;&#1077;&#1090; &#1089;&#1094;&#1077;&#1085;&#1072;&#1088;&#1080;&#1081; &#1087;&#1088;&#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1077; &#1073;&#1077;&#1079; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; (&#1076;&#1083;&#1103; &#1090;&#1086;&#1075;&#1086; &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1087;&#1088;&#1080;&#1074;&#1103;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084;&#1091; &#1080;&#1084;&#1077;&#1085;&#1080; &#1089;&#1094;&#1077;&#1085;&#1072;&#1088;&#1080;&#1103;)
    </p>
    <p>
      <b>SERVER_NAME</b>&#160;- &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; (&#1080;&#1084;&#1103; &#1093;&#1086;&#1089;&#1090;&#1072; &#1080;&#1083;&#1080; &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103;).
    </p>
    <p>
      <b>SERVER_PORT</b>&#160;- &#1087;&#1086;&#1088;&#1090;, &#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;. &#1055;&#1086;&#1088;&#1090; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; (&#1086;&#1073;&#1099;&#1095;&#1085;&#1086; 80), &#1082; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084;&#1091; &#1086;&#1073;&#1088;&#1072;&#1090;&#1080;&#1083;&#1089;&#1103; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;. &#1052;&#1086;&#1078;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1083;&#1103; &#1075;&#1077;&#1085;&#1077;&#1088;&#1072;&#1094;&#1080;&#1080; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; Location
    </p>
    <p>
      <b>SERVER_PROTOCOL</b>&#160;- &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1084;&#1099;&#1081; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1084;. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#171;HTTP/1.1&#187;.
    </p>
    <p>
      <b>SERVER_SOFTWARE</b>&#160;- &#1074;&#1077;&#1088;&#1089;&#1080;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#171;MyServer 1.0&#187;.
    </p>
  </body>
</html></richcontent>
