<node TEXT="Основы" FOLDED="true" ID="ID_638968341" CREATED="1536565894548" MODIFIED="1663783843147"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>/var/www/html</b>&nbsp;- здесь по умолчанию расположены файлы сайта
    </p>
    <p>
      
    </p>
    <p>
      <b>Имя пакета</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;httpd -- RHEL/CentOS
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;apache2 -- Debian/Ubuntu
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;apache24 -- FreeBSD
    </p>
    <p>
      <b>Корневой каталог</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;/etc/httpd -- RHEL/CentOS
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;/etc/apache2 -- Debian/Ubuntu
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;/usr/local/etc/apache24 -- FreeBSD
    </p>
    <p>
      <b>Расположение журнала</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;/var/log/httpd -- RHEL/CentOS
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;/var/log/apache2 -- Debian/Ubuntu
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;/var/log/httpd-*.loq -- FreeBSD
    </p>
    <p>
      <b>Пользователь</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;apache -- RHEL/CentOS
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;www-data -- Debian/Ubuntu
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;www -- FreeBSD
    </p>
  </body>
</html></richcontent>
