  <head>
    
  </head>
  <body>
    <p>
      1. Master (root, 1 &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;). &#1047;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1084;. &#1054;&#1073;&#1103;&#1079;&#1072;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080;:
    </p>
    <ul>
      <li>
        &#1063;&#1090;&#1077;&#1085;&#1080;&#1077; &#1080; &#1074;&#1072;&#1083;&#1080;&#1076;&#1072;&#1094;&#1080;&#1103; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1072;
      </li>
      <li>
        &#1054;&#1090;&#1082;&#1088;&#1099;&#1090;&#1080;&#1077; &#1089;&#1086;&#1082;&#1077;&#1090;&#1072;(&#1086;&#1074;)
      </li>
      <li>
        &#1054;&#1090;&#1082;&#1088;&#1099;&#1090;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1083;&#1086;&#1075;&#1086;&#1074;
      </li>
      <li>
        &#1047;&#1072;&#1087;&#1091;&#1089;&#1082; &#1080; &#1091;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1086;&#1095;&#1077;&#1088;&#1085;&#1080;&#1084;&#1080; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072;&#1084;&#1080; (worker)
      </li>
      <li>
        <b>Graceful restart</b>&#160;(Web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;, &#1087;&#1086;&#1089;&#1083;&#1077; &#1095;&#1077;&#1075;&#1086; &#1087;&#1086;&#1089;&#1090;&#1077;&#1087;&#1077;&#1085;&#1085;&#1086; &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090; &#1080;&#1079; &#1088;&#1072;&#1073;&#1086;&#1090;&#1099; &#1076;&#1086;&#1095;&#1077;&#1088;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1099; - &#1090;.&#1077;. &#1087;&#1086;&#1089;&#1090;&#1077;&#1087;&#1077;&#1085;&#1085;&#1099;&#1081; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076; &#1085;&#1072; &#1085;&#1086;&#1074;&#1099;&#1081; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075; ), Binary updates
      </li>
    </ul>
    <p>
      2. Worker (www-data, 1+&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1074;). &#1054;&#1073;&#1103;&#1079;&#1072;&#1085;&#1085;&#1086;&#1089;&#1090;&#1080; - &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; HTTP &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072;
    </p>
