<node TEXT="Порядок применения при обработке запроса" ID="ID_395286548" CREATED="1536582348234" MODIFIED="1551269419506"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1087;&#1088;&#1080; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;</b>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      1. VirtualHost - &#1087;&#1086; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1091; Host. Web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080;&#1079;&#1074;&#1083;&#1077;&#1082;&#1072;&#1077;&#1090; &#1080;&#1079; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1086;&#1077; &#1080;&#1084;&#1103;. &#1055;&#1086; &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1086;&#1084;&#1091; &#1080;&#1084;&#1077;&#1085;&#1080; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1082;&#1072;&#1082;&#1086;&#1081; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083; &#1093;&#1086;&#1089;&#1090; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100;. Web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1080;&#1079;&#1074;&#1083;&#1077;&#1082;&#1072;&#1077;&#1090; URL &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1080; &#1087;&#1086; URL &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090; &#1082;&#1072;&#1082;&#1080;&#1077; &#1083;&#1086;&#1082;&#1077;&#1081;&#1096;&#1077;&#1085;&#1099; &#1085;&#1091;&#1078;&#1085;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100;
    </p>
    <p>
      2. DocumentRoot / Alias - &#1074;&#1099;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1091;&#1090;&#1080;. &#1055;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1077;&#1090; URL &#1074; &#1080;&#1084;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      3. Directory &#1080; .htaccess. Web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1086; &#1080;&#1084;&#1077;&#1085;&#1080; &#1092;&#1072;&#1081;&#1083;&#1072; &#1087;&#1086;&#1076;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090; &#1074;&#1089;&#1077; &#1087;&#1086;&#1076;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1099;.
    </p>
    <p>
      4. DierctoryMatch. Web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1086; &#1080;&#1084;&#1077;&#1085;&#1080; &#1092;&#1072;&#1081;&#1083;&#1072; &#1087;&#1086;&#1076;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090; &#1074;&#1089;&#1077; &#1087;&#1086;&#1076;&#1093;&#1086;&#1076;&#1103;&#1097;&#1080;&#1077; &#1082;&#1086;&#1085;&#1090;&#1077;&#1081;&#1085;&#1077;&#1088;&#1099;.
    </p>
    <p>
      5. Files &#1080; FilesMatch
    </p>
    <p>
      6. Location &#1080; LocationMatch
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1099; &#1074; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077;</b>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Установка" FOLDED="true" ID="ID_1131029936" CREATED="1542631844618" MODIFIED="1669908424649"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
