<node TEXT="Аутентификация базовая" FOLDED="true" ID="ID_993892964" CREATED="1535449627956" MODIFIED="1584087780513"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1041;&#1072;&#1079;&#1086;&#1074;&#1072;&#1103; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;</b>
    </p>
    <ul>
      <li>
        RFC 2617
      </li>
      <li>
        &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1089;&#1077;&#1084;&#1080; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;&#1084;&#1080;
      </li>
      <li>
        &#1089;&#1077;&#1088;&#1074;&#1077;&#1088; + &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <font size="2"><b>&#1050;&#1072;&#1082; &#1101;&#1090;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090; &#1085;&#1072; &#1091;&#1088;&#1086;&#1074;&#1085;&#1077; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1086;&#1074;</b></font>
    </p>
    <p>
      <font size="1">HTTP/1.x 401 Unauthorized</font>
    </p>
    <p>
      <font size="1">... </font>
    </p>
    <p>
      <font size="1">WWW-Authenticate: Basic realm=&quot;www.mysite.local&quot;</font>&#160;&#160;# &#1042;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1085;&#1072;&#1076;&#1087;&#1080;&#1089;&#1100; &#1074; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1083;&#1086;&#1075;&#1080;&#1085;&#1072; &#1080; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1091;&#1074;&#1080;&#1076;&#1080;&#1090; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077;
    </p>
    <p>
      <font size="1">GET / HTTP/1.1</font>
    </p>
    <p>
      <font size="1">... </font>
    </p>
    <p>
      <font size="1">Authorization: Basic QWRtaW5pc3RyYXRvcjpwYXNzQHdvcmQx</font>&#160;&#160;# Administrator:pass@word1 --&gt; &#1054;&#1073;&#1086;&#1088;&#1072;&#1095;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084; &#1089;&#1077;&#1088;&#1080;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; <a href="#ID_1698941296">Base64</a>
    </p>
  </body>
</html></richcontent>
