<node TEXT="Блокировка" FOLDED="true" ID="ID_1101207284" CREATED="1584087717103" MODIFIED="1667700347616"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Блокировака URL:</b>
    </p>
    <p>
      <font color="#008000">RedirectMatch 403 ^/novosti/?$ </font>
    </p>
    <p>
      <b>или</b>
    </p>
    <p>
      <font color="#008000">RewriteCond %{THE_REQUEST} /news\/\? [NC] </font>
    </p>
    <p>
      <font color="#008000">RewriteRule ^ - [F] </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>Блокировка запросов: </b>
    </p>
    <p>
      <b>&nbsp;&nbsp;get запросы:</b>
    </p>
    <p>
      <font color="#008000">RewriteEngine On </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{QUERY_STRING} <b>s=</b>&nbsp;[NC] </font>
    </p>
    <p>
      <font color="#008000">RewriteRule ^ - [F]&nbsp;&nbsp;ИЛИ&nbsp;&nbsp;RewriteRule ^.*$ - [R=403,L]</font>
    </p>
    <p>
      <b>&nbsp;&nbsp;post-запросы:</b>
    </p>
    <p>
      <font color="#008000">&lt;Limit POST&gt;&nbsp; </font>
    </p>
    <p>
      <font color="#008000">order deny,allow&nbsp; </font>
    </p>
    <p>
      <font color="#008000">deny from all </font>
    </p>
    <p>
      <font color="#008000">allow from 127.0.0.1 </font>
    </p>
    <p>
      <font color="#008000">&lt;/Limit&gt; </font>
    </p>
    <p>
      <b>&nbsp;&nbsp;определенный запрос:</b>
    </p>
    <p>
      <font color="#008000">RewriteCond %{QUERY_STRING} route=information/blogger&amp;blogger_id=10 </font>
    </p>
    <p>
      <font color="#008000">RewriteRule ^.*$ - [F,L] </font>
    </p>
    <p>
      &nbsp; <b>Определенный файл:</b>
    </p>
    <p>
      <font color="#008000">&lt;Files viewforum.php&gt; </font>
    </p>
    <p>
      <font color="#008000">Order Allow,Deny </font>
    </p>
    <p>
      <font color="#008000">Deny from all </font>
    </p>
    <p>
      <font color="#008000">&lt;/Files&gt;</font>
    </p>
    <p>
      <b>&nbsp;&nbsp;Post-запрос к определенному URL:</b>
    </p>
    <p>
      <font color="#008000">RewriteEngine on </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{QUERY_STRING} route=information/contact </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{REQUEST_METHOD} POST </font>
    </p>
    <p>
      <font color="#008000">RewriteRule ^.*$ - [F,L]</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">RewriteEngine on </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{REQUEST_URI} /bitrix/redirect.php </font>
    </p>
    <p>
      <font color="#008000">RewriteRule ^.*$ - [F,L] </font>
    </p>
    <p>
      <b>&nbsp;&nbsp;Проломанная Joomla:</b>
    </p>
    <p>
      <font color="#008000">RewriteEngine on&nbsp; </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{REQUEST_URI} index.php/component/k2.* </font>
    </p>
    <p>
      <font color="#008000">RewriteRule ^.*$ - [F,L] </font>
    </p>
    <p>
      <b>&nbsp;&nbsp;Редирект /index.php =&gt; / </b>
    </p>
    <p>
      <font color="#008000">RewriteCond %{REQUEST_URI} index\.php </font>
    </p>
    <p>
      <font color="#008000">RewriteRule ^(.*)index\.php$ /$1/ [R=301,L] </font>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="IP" ID="ID_865810840" CREATED="1665818196893" MODIFIED="1667707310060"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Разрешить 1 IP</b>
    </p>
    <p>
      <font color="#008000">Order Deny,Allow</font>&nbsp;&nbsp;# Apache 2.2 и ниже
    </p>
    <p>
      <font color="#008000">Deny from all </font>
    </p>
    <p>
      <font color="#008000">Allow from &lt;your ip&gt;</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;RequireAll&gt;</font>&nbsp;&nbsp;# Apache 2.4 и выше
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;Require ip xx.xx.xx.xx yy.yy.yy.yy </font>
    </p>
    <p>
      <font color="#008000">&lt;/RequireAll&gt;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>Запретить 1 IP</b>
    </p>
    <p>
      Order Allow,Deny
    </p>
    <p>
      Allow from all
    </p>
    <p>
      Deny from 66.249.66.26 66.249.66.28 66.249.66.30
    </p>
    <p>
      
    </p>
    <p>
      <b>Блокировка по маске</b>
    </p>
    <p>
      Order Allow,Deny
    </p>
    <p>
      Deny from 66.249.74.0/24
    </p>
    <p>
      Allow from all
    </p>
    <p>
      
    </p>
    <p>
      RewriteEngine on
    </p>
    <p>
      RewriteCond %{REMOTE_ADDR} ^66\.249\.74\.
    </p>
    <p>
      RewriteRule ^ - [F]
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>Разрешение по маске</b>
    </p>
    <p>
      Order Deny,Allow
    </p>
    <p>
      Deny from all&nbsp;&nbsp;# Запретить подключение из всех сетей
    </p>
    <p>
      Allow from 192.168.10.0/24&nbsp;&nbsp;# Разрешить подключение из нашей сети
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>Маска</b>
    </p>
    <p>
      <b>Apache 2.2</b>&nbsp;и ниже:
    </p>
    <p>
      <font color="#008000">Order deny,allow </font>
    </p>
    <p>
      <font color="#008000">Deny from all </font>
    </p>
    <p>
      <font color="#008000">Allow from 24.18&nbsp;&nbsp;&nbsp;&nbsp;# allow access from home </font>
    </p>
    <p>
      <font color="#008000">Allow from 162.12&nbsp;&nbsp;&nbsp;# allow access from work</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>Apache 2.4</b>&nbsp;и выше:
    </p>
    <p>
      <font color="#008000">&lt;RequireAny&gt; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;#IPv4 range at my work </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;Require ip 207.100 </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;#IPv6 from home </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;Require ip 2a02:4126:2aa4::/48&nbsp; </font>
    </p>
    <p>
      <font color="#008000">&lt;/RequireAny&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      Полный IP-адрес:
    </p>
    <p>
      <font color="#008000">Require ip 10.1.2.3 </font>
    </p>
    <p>
      <font color="#008000">Require ip 192.168.1.104 192.168.1.205</font>
    </p>
    <p>
      
    </p>
    <p>
      Частичный IP-адрес:
    </p>
    <p>
      <font color="#008000">Require ip 10.1 </font>
    </p>
    <p>
      <font color="#008000">Require ip 10 172.20 192.168.2 </font>
    </p>
    <p>
      
    </p>
    <p>
      A network/netmask pair:
    </p>
    <p>
      <font color="#008000">Require ip 10.1.0.0/255.255.0.0 </font>
    </p>
    <p>
      
    </p>
    <p>
      A network/nnn CIDR specification:
    </p>
    <p>
      <font color="#008000">Require ip 10.1.0.0/16 </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="geoip" ID="ID_1073249557" CREATED="1665818457858" MODIFIED="1665818559401"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>htaccess и geoip:</b>
    </p>
    <ul>
      <li>
        нужно проверить, что модуль geoip подгружен. Смотреть в phpinfo
      </li>
    </ul>
    <p>
      <b>Разрешить только отдельные страны: </b>
    </p>
    <p>
      <font color="#008000">GeoIPEnable On </font>
    </p>
    <p>
      <font color="#008000"># Put countries to allow here&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </font>
    </p>
    <p>
      <font color="#008000">SetEnvIf GEOIP_COUNTRY_CODE US AllowCountry&nbsp; </font>
    </p>
    <p>
      <font color="#008000">SetEnvIf GEOIP_COUNTRY_CODE RU AllowCountry&nbsp; </font>
    </p>
    <p>
      <font color="#008000">SetEnvIf GEOIP_COUNTRY_CODE UA AllowCountry&nbsp; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">Deny from all&nbsp; </font>
    </p>
    <p>
      <font color="#008000">Allow from env=AllowCountry&nbsp;&nbsp; </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>Заблокировать отдельные страны: </b>
    </p>
    <p>
      <font color="#008000">GeoIPEnable On </font>
    </p>
    <p>
      <font color="#008000"># Put countries to deny here&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </font>
    </p>
    <p>
      <font color="#008000">SetEnvIf GEOIP_COUNTRY_CODE CN DenyCountry&nbsp; </font>
    </p>
    <p>
      <font color="#008000">SetEnvIf GEOIP_COUNTRY_CODE KR DenyCountry&nbsp; </font>
    </p>
    <p>
      <font color="#008000">SetEnvIf GEOIP_COUNTRY_CODE KP DenyCountry&nbsp; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">Allow from all&nbsp; </font>
    </p>
    <p>
      <font color="#008000">Deny from env=DenyCountry&nbsp; </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>На серверах с RHEL8 используются перемеменные с префиксом MM: </b>
    </p>
    <p>
      <font color="#008000"># Put countries to allow here&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </font>
    </p>
    <p>
      <font color="#008000">SetEnvIf MM_COUNTRY_CODE US AllowCountry&nbsp; </font>
    </p>
    <p>
      <font color="#008000">SetEnvIf MM_COUNTRY_CODE RU AllowCountry&nbsp; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">Deny from all&nbsp; </font>
    </p>
    <p>
      <font color="#008000">Allow from env=AllowCountry</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="переходы со сторонних ресурсов" ID="ID_1399583795" CREATED="1667212493286" MODIFIED="1667212647994"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Блокировка переходов со сторонних ресурсов</b>
    </p>
    <p>
      
    </p>
    <p>
      # Для запрета перехода c baddomain.ru на domain.ru
    </p>
    <p>
      <font color="#008000">RewriteEngine on </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{HTTP_REFERER} baddomain.ru [NC] </font>
    </p>
    <p>
      <font color="#008000">RewriteRule .* - [F]</font>
    </p>
    <p>
      
    </p>
    <p>
      # Если требуется запретить переходы с нескольких доменов
    </p>
    <p>
      <font color="#008000">RewriteEngine on </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{HTTP_REFERER} baddomain.ru [NC,OR] </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{HTTP_REFERER} baddomain2.ru [NC,OR] </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{HTTP_REFERER} baddomain3.ru [NC] </font>
    </p>
    <p>
      <font color="#008000">RewriteRule .* - [F]</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Спам комментарии в WP" ID="ID_1981748130" CREATED="1665818662555" MODIFIED="1667212519182"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Wordpress, блокировка спам-комментариев. </b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">RewriteEngine On </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{REQUEST_METHOD} POST </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{REQUEST_URI} .wp-comments-post\.php* </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{HTTP_REFERER} !.*example.com.* [OR]&nbsp; </font># Заменить example.com на имя домена
    </p>
    <p>
      <font color="#008000">RewriteCond %{HTTP_USER_AGENT} ^$ </font>
    </p>
    <p>
      <font color="#008000">RewriteRule (.*) ^http://%{REMOTE_ADDR}/$ [R=301,L]</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="По времени" ID="ID_1800583253" CREATED="1695567669354" MODIFIED="1695567918165"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      RewriteEngine On
    </p>
    <p>
      RewriteCond %{TIME_HOUR}%{TIME_MIN} &gt;=0330
    </p>
    <p>
      RewriteCond %{TIME_HOUR}%{TIME_MIN} &lt;=0335
    </p>
    <p>
      RewriteRule ^ - [F,L]
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Виртуальные директории" FOLDED="true" ID="ID_1944481186" CREATED="1535355845589" MODIFIED="1577862964101"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1007420448">&#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; &#1086;&#1073; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;&#1093;</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; - </b>&#1089;&#1086;&#1079;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1074;&#1099; Alias
    </p>
    <p>
      
    </p>
    <p>
