      <li>
        <b>Alias</b>&#160;&quot;/info&quot; &quot;c:/users/folders/vasya/folder&quot;
      </li>
      <li>
        <b>Alias</b>&#160;&quot;/info<b>/</b>&quot; &quot;c:/users/folders/vasya/folder<b>/</b>&quot;
      </li>
      <li>
        &#1054;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1102;!
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="Создать вирт. дир. (лаб.)" ID="ID_556627753" CREATED="1535359860857" MODIFIED="1535360080982"><richcontent TYPE="NOTE">
