<node TEXT="Виртуальные хосты" FOLDED="true" ID="ID_994847955" CREATED="1535354577157" MODIFIED="1742385298496"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_18292238">Виртуальные хосты (Nginx)</a>&#xa0;&#xa0;<a href="#ID_401373032">Виртуальный хостинг</a>
    </p>
    <ul>
      <li>
        /etc/httpd/conf.d/vhost.conf&#xa0;&#xa0;(<b>CentOS</b>)
      </li>
      <li>
        /etc/apache2/sites-available/<b>&lt;virtual.host&gt;</b>.conf (<b>Debian</b>). Для каждого хоста создается свой конфиг
      </li>
      <li>
        <span style="color: #ff0000;">/etc/httpd/Includes/...</span>
      </li>
    </ul>
    <p>
      <b>Директива</b>
    </p>
    <p>
      <span style="color: #008000;">&lt;VirtualHost ip:port&gt;</span>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# Описание виртуального хоста (где находится папка)<br color="#008000" style="color: #008000;"/>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ServerName <b>virtual.host </b></span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ServerAlias www.virtual.host mysite.ru supersite.ru&#xa0;&#xa0;# Если несколько имен </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ServerAdmin webmaster@virtual.host </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;DocumentRoot /home/debian/public_html </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ErrorLog /var/log/apache2/virtual.host.error.log </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;CustomLog /var/log/apache2/virtual.host.access.log combined </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;LogLevel warn </span>
    </p>
    <p>
      <span style="color: #008000;">&lt;/VirtualHost&gt;</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">apachectl -S 2&gt;&amp;1 | grep 'port 80'</span>&#xa0;&#xa0;# Список виртуальных хостов. <span style="color: #0000c0;">httpd -S</span>
    </p>
    <p>
      <span style="color: #0000c0;">a2ensite virtual.host</span>&#xa0;&#xa0;# Подключает виртуальный хост
    </p>
    <p>
      <span style="color: #0000c0;">a2dissite virtual.host</span>&#xa0;&#xa0;# Отключить виртуальный хост (например 000_default).
    </p>
    <p>
      <span style="color: #0000c0;">systemctl restart apache2</span>&#xa0;&#xa0;# Перезагрузить apache2
    </p>
  </body>
</html></richcontent>
<node TEXT="Настройка вирт. хоста" ID="ID_1699103568" CREATED="1535355478955" MODIFIED="1570789583514"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1587510430">&#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; PHP</a>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;VirtualHost 127.0.0.1:80&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;ServerName site.ru&#160; </font># &#1048;&#1084;&#1103; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;ServerAlias mysite.ru supersite.ru&#160;&#160;</font># &#1045;&#1089;&#1083;&#1080; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1080;&#1084;&#1077;&#1085;
    </p>
    <p>
      &#160;&#160;&#160;&#160;<font color="#008000">ServerAdmin admin@site.ru&#160; </font># &#1040;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088; (&#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080; Error 5xx)<font color="#008000">&#160;</font>
    </p>
    <p>
      &#160;&#160;&#160;&#160;<font color="#008000">DirectoryIndex index.php&#160; </font># &#1055;&#1077;&#1088;&#1077;&#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1072; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;
    </p>
    <p>
      &#160;&#160;&#160;&#160;<font color="#008000">DocumentRoot /var/www/&#1084;&#1086;&#1081;&#1089;&#1072;&#1081;&#1090;&#160; </font># &#1043;&#1076;&#1077; &#1083;&#1077;&#1078;&#1080;&#1090; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090; (&#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1089;&#1072;&#1081;&#1090;&#1072;)
    </p>
    <p>
      # &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1087;&#1072;&#1087;&#1082;&#1080;. &#1042;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1075;&#1088;&#1091;&#1087;&#1087;&#1091; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1091; &#1080; &#1077;&#1075;&#1086; &#1087;&#1086;&#1076;&#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#1072;&#1084;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;Directory /var/www/&#1084;&#1086;&#1081;&#1089;&#1072;&#1081;&#1090;&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;# &#1044;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1074;&#1099; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;/Directory&gt; </font>
    </p>
    <p>
      # &#1046;&#1091;&#1088;&#1085;&#1072;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;. CustomLog - &#1079;&#1072;&#1076;&#1072;&#1077;&#1084; &#1087;&#1086;&#1083;&#1103; &#1089;&#1072;&#1084;&#1080;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;ErrorLog /var/log/apache2/&#1084;&#1086;&#1081;&#1089;&#1072;&#1081;&#1090;-error_log </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;CustomLog /var/log/apache2/&#1084;&#1086;&#1081;&#1089;&#1072;&#1081;&#1090;-access_log common </font>
    </p>
    <p>
      # &#1055;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1082;&#1072; PHP
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;FilesMatch \.php$&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;SetHandler &quot;proxy:fcgi://127.0.0.1:9000/&quot; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;/FilesMatch&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/VirtualHost&gt; </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Варианты разделения у хостера" ID="ID_982438484" CREATED="1550489744192" MODIFIED="1551203842836"><richcontent TYPE="NOTE">
