<node TEXT="Управление кэшированием ресурсов" ID="ID_1753274816" CREATED="1535363664197" MODIFIED="1535364352852"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1074;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1047;&#1072;&#1087;&#1088;&#1077;&#1090; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;</b>
    </p>
    <p>
      <font color="#008000">Header set Cache-Control &quot;no-cache&quot;&#160;&#160;# &#1053;&#1077; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; &#1076;&#1080;&#1089;&#1082;</font>
    </p>
    <p>
      <font color="#008000">Header set Cache-Control &quot;no-store&quot;&#160;&#160;# &#1053;&#1077; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; &#1076;&#1080;&#1089;&#1082; &#1080; &#1074; &#1087;&#1072;&#1084;&#1103;&#1090;&#1100;</font>
    </p>
    <p>
      <font color="#008000">Header set Cache-Control &quot;private, no-cache, must-revalidate&quot; </font>
    </p>
    <p>
      <font color="#008000">ExpiresActive On </font>
    </p>
    <p>
      <font color="#008000">ExpiresDefault &quot;now&quot;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1056;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;</b>
    </p>
    <p>
      <font color="#008000">Header set Cache-Control &quot;public, max-age=600&quot;&#160;&#160;# &#1057;&#1077;&#1082;&#1091;&#1085;&#1076; &#1086;&#1090; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080;</font>
    </p>
    <p>
      <font color="#008000">ExpiresActive On </font>
    </p>
    <p>
      <font color="#008000">ExpiresDefault &quot;access plus 2 days&quot;&#160;&#160;# &#1054;&#1090; &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1081; &#1076;&#1072;&#1090;&#1099;</font>
    </p>
    <p>
      <font color="#008000">ExpiresDefault &quot;modification plus 3 hours&quot;&#160;&#160;# &#1054;&#1090; &#1076;&#1072;&#1090;&#1099; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1050;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1086; &#1090;&#1080;&#1087;&#1091; &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1074;</b>
    </p>
    <p>
      <font color="#008000">ExpiresByType text/html &quot;access plus 2 days&quot; </font>
    </p>
    <p>
      <font color="#008000">ExpiresByType image/gif &quot;access plus 2 weeks&quot;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090; &#1079;&#1072;&#1076;&#1072;&#1085;&#1080;&#1103; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1091; Expires</b>
    </p>
    <p>
      <font color="#008000">ExpiresDefault A3600 </font>
    </p>
    <p>
      <font color="#008000">ExpiresByType image/png M3600</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
