    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE application/rss+xml </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE application/vnd.ms-fontobject </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE application/x-font </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE application/x-font-opentype </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE application/x-font-otf </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE application/x-font-truetype </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE application/x-font-ttf </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE application/x-javascript </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE application/xhtml+xml </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE application/xml </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE font/opentype </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE font/otf </font>
    </p>
    <p>
      <font color="#008000">&nbsp;AddOutputFilterByType DEFLATE font/ttf </font>
    </p>
