<node TEXT="301 в PHP" ID="ID_346040131" CREATED="1739364406095" MODIFIED="1739364438991"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">vi index.php</span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">&lt;?php </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Header( &quot;HTTP/1.1 301 Moved Permanently&quot; ); </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">Header( &quot;Location: news.php&quot; ); </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">exit(); </span>
    </p>
    <p>
      <span style="color: #008000; font-family: Lucida Console;">?&gt; </span>
    </p>
  </body>
</html></richcontent>
</node>
