</node>
<node TEXT="Сообщения об ошибках" FOLDED="true" ID="ID_1007420448" CREATED="1535359657142" MODIFIED="1577862958228"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1944481186">&#1042;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080;</a>&#160; &#160;<a href="#ID_1826669319">&#1050;&#1086;&#1076;&#1099; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1103; HTTP</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1086;&#1073; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;&#1093;.</b>&#160; &#1058;.&#1077;. &#1095;&#1090;&#1086;&#1073;&#1099; &#1085;&#1077; &#1087;&#1086;&#1090;&#1077;&#1088;&#1103;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1072;&#1103; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082; (&#1073;&#1086;&#1083;&#1077;&#1077; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1080;&#1074;&#1085;&#1072;&#1103;, &#1095;&#1077;&#1084; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1072;&#1103;)
    </p>
    <p>
      <font color="#0000c0">vi .htaccess</font>
    </p>
    <p>
      <font color="#008000">ErrorDocument 500 &quot;http://www.somesite.ru/error-handler&quot; </font>
    </p>
    <p>
      <font color="#008000">ErrorDocument 404 &quot;/errors/script-404.php&quot;&#160;&#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1089;&#1086;&#1086;&#1090;&#1074;. &#1092;&#1072;&#1081;&#1083; </font>
    </p>
    <p>
      <font color="#008000">ErrorDocument 401 &quot;/errors/401.html&quot;&#160;&#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1089;&#1086;&#1086;&#1090;&#1074;. &#1092;&#1072;&#1081;&#1083; </font>
    </p>
    <p>
      <font color="#008000">ErrorDocument 403 &quot;&#1059; &#1074;&#1072;&#1089; &#1085;&#1077;&#1090; &#1087;&#1088;&#1072;&#1074; &#1085;&#1072; &#1087;&#1088;&#1086;&#1089;&#1084;&#1086;&#1090;&#1088; &#1101;&#1090;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072;&quot; </font>
    </p>
    <p>
      <font color="#008000">ErrorDocument 403 /error403.htm&#160;&#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1089;&#1086;&#1086;&#1090;&#1074;. &#1092;&#1072;&#1081;&#1083;</font>
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
<node TEXT="Создать сообщения об ошибках (лаб.)" ID="ID_516725912" CREATED="1535359888279" MODIFIED="1535360409306"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1057;&#1086;&#1079;&#1076;&#1072;&#1085;&#1080;&#1077; &#1089;&#1086;&#1073;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1093; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1086;&#1073; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;&#1093;</b>
    </p>
    <ul>
      <li>
        &#1057;&#1086;&#1079;&#1076;&#1072;&#1081;&#1090;&#1077; &#1085;&#1086;&#1074;&#1099;&#1081; &#1092;&#1072;&#1081;&#1083; 404.html &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; mysite\errors
      </li>
    </ul>
    <p>
      <font color="#008000">&lt;html&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;head&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;title&gt;&#1054;&#1096;&#1080;&#1073;&#1082;&#1072; 404&lt;/title&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;/head&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;body&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;h1&gt;&#1054;&#1096;&#1080;&#1073;&#1082;&#1072; 404&lt;/h1&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;p&gt;&#1060;&#1072;&#1081;&#1083; &#1085;&#1077; &#1085;&#1072;&#1081;&#1076;&#1077;&#1085;!&lt;/p&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&lt;p&gt;&#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1100;&#1090;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1103; &#1072;&#1076;&#1088;&#1077;&#1089;&#1072;.&lt;/p&gt; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&lt;/body&gt; </font>
    </p>
    <p>
      <font color="#008000">&lt;/html&gt;</font>
    </p>
    <ul>
      <li>
        &#1042; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077; &#1085;&#1072;&#1073;&#1077;&#1088;&#1080;&#1090;&#1077; &#1074; &#1072;&#1076;&#1088;&#1077;&#1089;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077;: <b>http://mysite.local/err/404.html</b>
      </li>
      <li>
        &#1059;&#1073;&#1077;&#1076;&#1080;&#1090;&#1077;&#1089;&#1100; &#1074; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; &#1092;&#1072;&#1081;&#1083; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;
      </li>
      <li>
        &#1042; &#1092;&#1072;&#1081;&#1083;&#1077; <b>mysite\conf\mysite.conf</b>&#160;&#1074; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1084; &#1093;&#1086;&#1089;&#1090;&#1077; &#1076;&#1086;&#1073;&#1072;&#1074;&#1100;&#1090;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1080;&#1077;: &#1076;&#1083;&#1103; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1072; 404 &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1090;&#1100; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091; <b>404.html</b>&#160;&#1080;&#1079; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1086;&#1081; &#1087;&#1072;&#1087;&#1082;&#1080; <b>err</b>
      </li>
      <li>
        &#1057;&#1086;&#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1077; &#1092;&#1072;&#1081;&#1083; &#1080; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1077; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;
      </li>
      <li>
        &#1042; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077; &#1085;&#1072;&#1073;&#1077;&#1088;&#1080;&#1090;&#1077; &#1074; &#1072;&#1076;&#1088;&#1077;&#1089;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077;: <b>http://mysite.local/abc/</b>. &#1045;&#1089;&#1083;&#1080; &#1074;&#1099; &#1074;&#1080;&#1076;&#1080;&#1090;&#1077; &#1074;&#1072;&#1096;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1086;&#1073; &#1086;&#1096;&#1080;&#1073;&#1082;&#1077;, &#1079;&#1085;&#1072;&#1095;&#1080;&#1090;, &#1074;&#1099; &#1089;&#1076;&#1077;&#1083;&#1072;&#1083;&#1080; &#1074;&#1089;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Файлы и папки" FOLDED="true" ID="ID_375068688" CREATED="1559217296562" MODIFIED="1665323742669"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>DirectoryIndex</b>&nbsp;test.html</font>&nbsp;&nbsp;# Переопределить индексный файл (файл, открываемый по умолчанию). Можно указать несколько файлов через пробел. Они будут искаться по очереди. Если их найти не удастся,&nbsp;&nbsp;сервер выдаст список файлов в каталоге (избежать этого - <a href="#ID_20712152">Options -Indexes</a>).
    </p>
    <p>
      <font color="#008000"><b>IndexIgnore</b>&nbsp;*.php</font>&nbsp;&nbsp;# Не отображать определенные файлы при показе директории
    </p>
  </body>
</html></richcontent>
<node TEXT="Пароль на директорию" ID="ID_1611251367" CREATED="1559212360622" MODIFIED="1559213806210"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1047;&#1072;&#1082;&#1088;&#1099;&#1090;&#1100; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1102; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1084; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>1.</b><font color="#008000">&#160;</font><font color="#0000c0">vi .htaccess</font>
    </p>
    <p>
      <font color="#008000">AuthType Basic </font>
    </p>
    <p>
      <font color="#008000">AuthName &quot;Enter a password&quot; </font>
    </p>
    <p>
      <font color="#008000">AuthUserFile &#1087;&#1091;&#1090;&#1100;_&#1082;_&#1092;&#1072;&#1081;&#1083;&#1091;_&#1089;_&#1087;&#1072;&#1088;&#1086;&#1083;&#1103;&#1084;&#1080; </font>
    </p>
    <p>
      <font color="#008000">require valid-user</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>2.</b>&#160;&#1042; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; shadow &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; &#1089; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;&#1084;&#1080; (<b>.htpasswd).</b>&#160;&#1058;&#1072;&#1082;&#1078;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; &#1084;&#1086;&#1078;&#1085;&#1086; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1076;&#1086;&#1087;. &#1089;&#1086;&#1092;&#1090;&#1072; &#1080; &#1079;&#1072;&#1082;&#1072;&#1095;&#1072;&#1090;&#1100; &#1077;&#1075;&#1086; &#1087;&#1086; ftp &#1074; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1102; shadow<b>&#160;</b>
    </p>
    <p>
      <font color="#0000c0">htpasswd -c &#1080;&#1084;&#1103;_&#1092;&#1072;&#1081;&#1083;&#1072;_&#1089;_&#1087;&#1072;&#1088;&#1086;&#1083;&#1103;&#1084;&#1080;&#160;&#160;&#1080;&#1084;&#1103;_&#1087;&#1086;&#1083;&#1100;&#1079;.&#160; </font># &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; 1-&#1075;&#1086; &#1087;&#1086;&#1083;&#1100;&#1079;. &#1042;&#1074;&#1077;&#1089;&#1090;&#1080; &#1080; &#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1076;&#1080;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;
    </p>
    <p>
      <font color="#0000c0">htpasswd&#160;&#160;&#1080;&#1084;&#1103;_&#1092;&#1072;&#1081;&#1083;&#1072;_&#1089;_&#1087;&#1072;&#1088;&#1086;&#1083;&#1103;&#1084;&#1080; &#1080;&#1084;&#1103;_&#1087;&#1086;&#1083;&#1100;&#1079;_2</font>&#160;&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1074; &#1092;&#1072;&#1081;&#1083; &#1089; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;&#1084;&#1080;
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Не показывать папку если файл не найден" ID="ID_20712152" CREATED="1559216805273" MODIFIED="1559216832508"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>Options -Indexes</b></font>&#160;&#160;# &#1053;&#1077; &#1087;&#1086;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1087;&#1072;&#1087;&#1082;&#1091;, &#1077;&#1089;&#1083;&#1080; &#1092;&#1072;&#1081;&#1083; &#1085;&#1077; &#1085;&#1072;&#1081;&#1076;&#1077;&#1085;. &#1059;&#1073;&#1080;&#1088;&#1072;&#1077;&#1084; &#1084;&#1080;&#1085;&#1091;&#1089; - &#1087;&#1086;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100;.
    </p>
    <ul>
      <li>
        &#1054;&#1092;&#1086;&#1088;&#1084;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074;&#1080;&#1076;&#1072; &#1087;&#1072;&#1087;&#1086;&#1082; &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074; &#1092;&#1072;&#1081;&#1083;&#1077; <b>httpd-autoindex.conf</b>
      </li>
      <li>
        &#1077;&#1089;&#1083;&#1080; &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; <b>header.html &#1080; readme.html</b>, &#1090;&#1086; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1084;&#1086;&#1077; &#1101;&#1090;&#1080;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1086; &#1074; <b>&#1089;&#1074;&#1077;&#1088;&#1093;&#1091; / &#1089;&#1085;&#1080;&#1079;&#1091; </b>&#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; (&#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074; <b>httpd-autoindex.conf</b>)
      </li>
    </ul>
  </body>
</html></richcontent>
