<node TEXT="mod_pervasive" ID="ID_1544720048" CREATED="1570800402425" MODIFIED="1570801129501"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>mod_pervasive</b>
    </p>
    <p>
      
    </p>
    <p>
      &#1050;&#1072;&#1082; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1086;, &#1086;&#1076;&#1085;&#1080;&#1084; &#1080;&#1079; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1093; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1082;&#1086;&#1074; &#1074;&#1105;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; Apache &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1100; &#1077;&#1075;&#1086; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072; &#1080;&#1083;&#1080; &#1093;&#1086;&#1090;&#1103; &#1073;&#1099; &quot;kill -HUP&quot;, &#1087;&#1088;&#1080; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1086;&#1085; &#1087;&#1077;&#1088;&#1077;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1074;&#1089;&#1077; &#1089;&#1074;&#1086;&#1080; &#1083;&#1086;&#1075;&#1080; &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1093;&#1086;&#1089;&#1090;&#1086;&#1074;. &#1044;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1087;&#1088;&#1080;&#1079;&#1074;&#1072;&#1085; &#1091;&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1101;&#1090;&#1086;&#1090; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1082;, &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1093;&#1086;&#1089;&#1090;&#1086;&#1074; &#1086;&#1085; &#1089;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1080;&#1079; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1072; CDB, &#1089; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1105;&#1085;&#1085;&#1086;&#1081; &#1074; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1086;&#1084; &#1092;&#1072;&#1081;&#1083;&#1077; &#1087;&#1077;&#1088;&#1080;&#1086;&#1076;&#1080;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;.
    </p>
    <p>
      
    </p>
    <p>
      &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1074; &#1091; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; &#1085;&#1077;&#1084;&#1085;&#1086;&#1075;&#1086;:
    </p>
    <p>
      &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#160;&#160;&#160;&#160;&#160;&#1058;&#1077;&#1082;&#1091;&#1097;&#1077;&#1077; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1077;&#160;&#160;&#160;&#160;&#160;&#1089;&#1084;&#1099;&#1089;&#1083;
    </p>
    <p>
      PervasiveDrv&#160;&#160;&#160;&#160;&#160;&quot;CDB&quot;&#160;&#160;&#160;&#160;&#160;&#1044;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088; &#1076;&#1083;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072; &#1082; &#1073;&#1072;&#1079;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;
    </p>
    <p>
      PervasiveDrvParam&#160;&#160;&#160;&#160;&#160;&quot;/var/db/apachemap.db&quot;&#160;&#160;&#160;&#160;&#160;&#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1092;&#1072;&#1081;&#1083; &#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1103; &#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1093;&#1086;&#1089;&#1090;&#1086;&#1074;
    </p>
    <p>
      PervasiveDrvCfgParam&#160;&#160;&#160;&#160;&#160;&quot;/var/db/apachemap-cfg.db&quot;&#160;&#160;&#160;&#160;&#160;&#1092;&#1072;&#1081;&#1083; &#1088;&#1072;&#1089;&#1096;&#1080;&#1088;&#1077;&#1085;&#1085;&#1086;&#1081; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080;
    </p>
    <p>
      PervasiveDrvMaskParam&#160;&#160;&#160;&#160;&#160;&quot;/var/db/apachemap-mask.db&quot;&#160;&#160;&#160;&#160;
    </p>
    <p>
      PervasiveEnable&#160;&#160;&#160;&#160;&#160;on&#160;&#160;&#160;&#160;&#160;&#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;
    </p>
    <p>
      PervasiveTTL&#160;&#160;&#160;&#160;&#160;120&#160;&#160;&#160;&#160;&#160;&#1074;&#1088;&#1077;&#1084;&#1103; &#1078;&#1080;&#1079;&#1085;&#1080; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1074; &#1082;&#1101;&#1096;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      &#1058;&#1072;&#1082;&#1078;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1088;&#1077;&#1072;&#1083;&#1080;&#1079;&#1091;&#1077;&#1090; &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1077; Apache &#1082; &#1103;&#1076;&#1077;&#1088;&#1085;&#1086;&#1084;&#1091; &#1084;&#1086;&#1076;&#1091;&#1083;&#1102; so&#1089;huid.so, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1097;&#1077;&#1084;&#1091; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100; UID &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1085;&#1072; &#1085;&#1091;&#1078;&#1085;&#1099;&#1081; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1081; &#1087;&#1088;&#1080; &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1080; &#1082; &#1089;&#1072;&#1081;&#1090;&#1091;.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">cdb -d /var/db/apachemap.db | grep -a &lt;host&gt;.ru</font>
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Диагностика" FOLDED="true" ID="ID_298808516" CREATED="1567547023038" MODIFIED="1721567895535"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_210702592">DDoS</a>&nbsp; <a href="#ID_862790472">логи httpd</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Не отвечает web-сервер</b>
    </p>
    <p>
      
    </p>
    <p>
      1. Проверяем сервер статус через строку браузера
    </p>
    <p>
      <font color="#0000c0">&lt;server&gt;.&lt;хостинг&gt;/server-status </font>
    </p>
    <p>
      <font color="#0000c0">_______________/info.php </font>
    </p>
    <p>
      2. systemctl restart php-fpm73.service&nbsp;&nbsp;# Перезапуск php-fpm
    </p>
    <p>
      3. <font color="#0000c0">top</font>&nbsp;&nbsp;# Смотрим какие процессы грузят систему
    </p>
    <p>
      <font color="#0000c0">ps aux | grep httpd </font>
    </p>
    <p>
      <font color="#0000c0">ps aux | grep httpd | cut -d' ' -f1 | sort -f | uniq -c | sort -n | tail</font>&nbsp;&nbsp;# Посмотреть процессы пользователей
    </p>
    <p>
      <font color="#0000c0">ps -A -eo user | sort | uniq -c | sort -n </font>&nbsp;# поиск грузчика на сервере по числу процессов
    </p>
    <p>
      <font color="#0000c0">ps aux | awk '{cpu[$1]+=$3; mem[$1]+=$4; procs[$1]+=1} END { for (user in cpu){ print user,&quot;cpu:&quot;,cpu[user],&quot;mem:&quot;,mem[user],&quot;proc:&quot;,procs[user] } }'|sort -n -k3|tail</font>
    </p>
    <p>
      <font color="#0000c0">killall -u srv123</font>&nbsp;&nbsp;&nbsp;&nbsp;# Убить процессы-грузчики. Можно поставить на watch )
    </p>
    <p>
      <font color="#0000c0">killall -HUP &lt;PID процесса&gt; </font>
    </p>
    <p>
      <font color="#0000c0">ps aux | grep &lt;user&gt; | awk '{print $2}' | xargs kill -9 </font>
    </p>
    <p>
      4. Если после удаления процессов снова появляются процессы от этого пользователя, необходимо анализировать access.log и в соответствии с ним блокировать отдельные пулы адресов, адреса, временно выключать ресурс для останова DDoS, направлять поток запросов через очистку трафика
    </p>
    <p>
      5. Проверить БД на наличие зависших запросов и количество запросов вообще
    </p>
  </body>
</html></richcontent>
