<node TEXT="Перезагрузить apache2" ID="ID_703902380" CREATED="1562097738797" MODIFIED="1721287205559"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">service httpd restart </font>
    </p>
    <p>
      <font color="#0000c0">service apache2 restart </font>
    </p>
    <p>
      <font color="#0000c0">service httpd start </font>
    </p>
    <p>
      <font color="#0000c0">service httpd stop</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">systemctl restart httpd.service </font>
    </p>
    <p>
      <font color="#0000c0">systemctl restart apache2 </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">apache2ctl restart </font>
    </p>
    <p>
      <font color="#0000c0">apachectl -k restart</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">/etc/init.d/apache2 restart </font>
    </p>
    <p>
      <font color="#0000c0">/etc/init.d/httpd start</font>
    </p>
    <p>
      <font color="#0000c0">/etc/init.d/apache2 start </font>
    </p>
    <p>
      <font color="#0000c0">/etc/init.d/apache2 stop </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">/usr/local/etc/rc.d/apache22 graceful</font>&nbsp;&nbsp;# <font color="#ff0000">FreeBSD</font>. Перезапуск без прерывания открытых соединений
    </p>
    <p>
      <font color="#0000c0">/usr/local/etc/rc.d/apache22 restart </font>
    </p>
    <p>
      <font color="#0000c0">/usr/local/etc/rc.d/apache22 stop </font>
    </p>
    <p>
      <font color="#0000c0">/usr/local/etc/rc.d/apache22 start</font><br/>
    </p>
    <p>
      
    </p>
    <p>
      <b>centos6</b>
    </p>
    <p>
      <font color="#0000c0">/etc/init.d/httpd_default restart </font>
    </p>
    <p>
      <font color="#0000c0">/etc/init.d/httpd_530 restart </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>centos7 </b>На сервере запущено несколько веб-серверов httpd для разных версий PHP
    </p>
    <p>
      <font color="#0000c0">systemctl restart httpd_default </font>
    </p>
    <p>
      <font color="#0000c0">systemctl restart httpd_720 </font>
    </p>
    <p>
      
    </p>
    <p>
      <br/>
      <br/>
    </p>
  </body>
</html></richcontent>
