    </p>
    <p>
      &#160;&#160; <b>W3SVC</b>&#160;&#1089;&#1088;&#1072;&#1079;&#1091; &#1092;&#1086;&#1088;&#1074;&#1072;&#1088;&#1076;&#1080;&#1090; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; <b>WAS</b>&#160;--&gt; <b>WAS</b>&#160;&#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; <b>&#1082;&#1086;&#1085;&#1092;. &#1092;&#1072;&#1081;&#1083;&#1072;&#1084;</b>&#160;&#1080; &#1089;&#1095;&#1080;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090; &#1080;&#1085;&#1092;. &#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1077; (&#1082;&#1072;&#1082; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085; &#1074;&#1077;&#1073;-&#1089;&#1072;&#1081;&#1090;; &#1074; &#1082;&#1072;&#1082;&#1086;&#1084; Application Pool &#1089;&#1072;&#1081;&#1090; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;) --&gt; &#1048;&#1079; &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1086;&#1085;&#1080;&#1084;&#1072;&#1077;&#1090; &#1073;&#1099;&#1083;&#1080; &#1083;&#1080; &#1082; &#1089;&#1072;&#1081;&#1090;&#1091; &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1077;&#1085;&#1080;&#1103;, &#1080; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085; &#1083;&#1080; &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; (&#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1097;&#1080;&#1081; &#1074;&#1089;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1082; &#1101;&#1090;&#1086;&#1084;&#1091; &#1089;&#1072;&#1081;&#1090;&#1091;) &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085; &#1080;&#1083;&#1080; &#1085;&#1077;&#1090; --&gt;
    </p>
    <p>
      &#160;&#160;&#160;&#1045;&#1089;&#1083;&#1080; &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1103; &#1073;&#1099;&#1083;&#1080;, <b>WAS</b>&#160;&#1087;&#1077;&#1088;&#1077;&#1085;&#1072;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1080;&#1085;&#1092;. &#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1091; <b>HTTP.SYS</b>
    </p>
    <p>
      &#160;&#160;&#160;&#1045;&#1089;&#1083;&#1080; &#1101;&#1090;&#1086; &#1087;&#1077;&#1088;&#1074;&#1086;&#1077; &#1086;&#1073;&#1088;&#1072;&#1097;&#1077;&#1085;&#1080;&#1077; &#1082; &#1076;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; &#1089;&#1072;&#1081;&#1090;&#1091;, &#1079;&#1085;&#1072;&#1095;&#1080;&#1090; <b>&#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1077; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1099;</b>&#160;(&#1089;&#1074;&#1103;&#1079;&#1072;&#1085;&#1085;&#1099;&#1077; &#1089; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1086;&#1081; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; &#1082; &#1101;&#1090;&#1086;&#1084;&#1091; &#1089;&#1072;&#1081;&#1090;&#1091;) &#1074; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077; &#1085;&#1077; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;&#1099; --&gt; <b>WAS</b>&#160;&#1086;&#1090;&#1074;&#1077;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072; &#1090;&#1086;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1101;&#1090;&#1086;&#1090; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; --&gt; &#1089;&#1086;&#1073;&#1088;&#1072;&#1074; &#1080;&#1085;&#1092;. &#1080;&#1079; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1082;&#1086;&#1085;&#1092;., <b>&#1072;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1077;&#1090; &#1089;&#1086;&#1086;&#1090;&#1074;. &#1088;&#1072;&#1073;&#1086;&#1095;&#1080;&#1081; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;</b>&#160;--&gt; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090; &#1089;&#1086;&#1073;&#1088;&#1072;&#1085;&#1085;&#1091;&#1102; &#1080;&#1085;&#1092;. &#1095;&#1077;&#1088;&#1077;&#1088;&#1077;&#1079; <b>W3SVC</b>&#160;&#1076;&#1088;&#1072;&#1081;&#1074;&#1077;&#1088;&#1091; <b>HTTP.SYS </b>
    </p>
    <p>
