<node TEXT="Безопасность" FOLDED="true" ID="ID_1385526905" CREATED="1519112079765" MODIFIED="1519112079765"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1050;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;.</b>
    </p>
    <p>
      <b>&#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1087;&#1086; IP &#1080; &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1099;&#1084; &#1080;&#1084;&#1077;&#1085;&#1072;&#1084;</b>. (&#1053;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102;). &#1058;.&#1077;. &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1093; IP &#1080;&#1083;&#1080; &#1076;&#1086;&#1084;&#1077;&#1085;&#1086;&#1074;. &#1053;&#1091; &#1080;&#1083;&#1080; &#1072;&#1085;&#1072;&#1083;&#1086;&#1075;&#1080;&#1095;&#1085;&#1099;&#1081; &#1079;&#1072;&#1087;&#1088;&#1077;&#1090;. &#1063;&#1090;&#1086; &#1082;&#1072;&#1089;&#1072;&#1077;&#1090;&#1089;&#1103; &#1076;&#1086;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; &#1080;&#1084;&#1077;&#1085;, &#1090;&#1086; &#1074; DNS &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1087;&#1088;&#1086;&#1087;&#1080;&#1089;&#1072;&#1085;&#1072; &#1088;&#1077;&#1074;&#1077;&#1088;&#1089;&#1085;&#1072;&#1103; &#1079;&#1086;&#1085;&#1072;.
    </p>
    <p>
      <b>&#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; (Request Filtering)</b>. &#1055;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; Administration Pack (&#1076;&#1083;&#1103; IIS 7.0)&#160;&#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; &#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1103;&#1090;&#1089;&#1103; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099; &#1074; IIS Manager.
    </p>
    <p>
      <a href="#ID_1789063705">&#1040;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;</a>. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1072;&#1085;&#1086;&#1085;&#1080;&#1084;&#1085;&#1072;&#1103; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;
    </p>
    <p>
      <b>&#1040;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103;</b>. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1081; NTFS.
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1048;&#1079;&#1086;&#1083;&#1103;&#1094;&#1080;&#1103; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1081;.</b>
    </p>
    <p>
      <b>Application Pool Identity.</b>&#160;&#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; Network Service. &#1044;&#1083;&#1103; &#1072;&#1085;&#1086;&#1085;. &#1072;&#1091;&#1090;. &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1091;&#1095;&#1077;&#1090;&#1085;&#1091;&#1102; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1087;&#1091;&#1083;&#1072;.
    </p>
    <p>
      <b>Application Pool SID</b>. &#1044;&#1083;&#1103; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1087;&#1091;&#1083;&#1072; &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1091;&#1085;&#1080;&#1082;. SID IIS APPPOOL\&lt;&#1080;&#1084;&#1103; &#1087;&#1091;&#1083;&#1072;&gt;. &#1069;&#1090;&#1086;&#1090; SID &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1080;&#1079;&#1086;&#1083;&#1103;&#1094;&#1080;&#1080;: &#1088;&#1077;&#1089;&#1091;&#1088;&#1089;&#1086;&#1074; &#1087;&#1088;&#1080;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; &#1086;&#1089;&#1085;&#1086;&#1074;&#1077; NTFS-&#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1081; (&#1085;&#1072;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;); &#1082;&#1086;&#1085;&#1092;. &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1080; &#1080;&#1079; ApplicationHost.config (&#1072;&#1074;&#1090;. &#1074; %SystemDrive%\Inetpub\Temp\Apppools)
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1072;&#1094;&#1080;&#1103; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;</b>. <a href="#ID_839831148">Request Filtering</a>. &#1048;&#1085;&#1090;&#1077;&#1075;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1072; &#1074; IIS 7, &#1073;&#1072;&#1079;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; URLScan (&#1087;&#1086;&#1103;&#1074;&#1080;&#1083;&#1089;&#1103; &#1074; IIS 6). &#1047;&#1072;&#1076;&#1072;&#1077;&#1090; &#1086;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1103; &#1085;&#1072; URL-&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099;.
    </p>
    <p>
      
    </p>
    <p>
      <a href="#ID_1832763518">URL-&#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103;</a>. &#1053;&#1072;&#1095;&#1080;&#1085;&#1072;&#1103; &#1089; IIS 7. &#1057;&#1086;&#1079;&#1076;&#1072;&#1077;&#1084; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1074; IIS. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; URL-&#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1085;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103;.
    </p>
  </body>
</html></richcontent>
