        &#1053;&#1080;&#1095;&#1077;&#1075;&#1086; &#1082;&#1088;&#1086;&#1084;&#1077; Web-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1085;&#1072; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1077; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1073;&#1099;&#1090;&#1100;
      </li>
      <li>
        Directory Browsing &#1076;&#1083;&#1103; &#1089;&#1072;&#1081;&#1090;&#1072;, &#1089;&#1084;&#1086;&#1090;&#1088;&#1103;&#1097;&#1077;&#1075;&#1086; &#1074; &#1084;&#1080;&#1088;, &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085; &#1074; &#1094;&#1077;&#1083;&#1103;&#1093; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080; (&#1089;&#1090;&#1088;&#1091;&#1082;&#1090;&#1091;&#1088;&#1072; &#1087;&#1072;&#1087;&#1086;&#1082; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1085;&#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1072;&#1076;&#1084;&#1080;&#1085;&#1091;)
