<node TEXT="Location блоки" FOLDED="true" ID="ID_888726527" CREATED="1550594820206" MODIFIED="1551273298238"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1041;&#1083;&#1086;&#1082;&#1080; Location</b>&#160;- &#1087;&#1077;&#1088;&#1077;&#1093;&#1074;&#1072;&#1090;&#1095;&#1080;&#1082;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1074; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1081; &#1089;&#1089;&#1099;&#1083;&#1082;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1102;&#1090; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1081; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;
    </p>
    <ul>
      <li>
        &#1084;&#1086;&#1078;&#1085;&#1086; &#1091;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100; &#1087;&#1086;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1080; &#1087;&#1086;&#1089;&#1077;&#1097;&#1077;&#1085;&#1080;&#1080; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1093; URI &#1080;&#1083;&#1080; &#1087;&#1088;&#1080; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;&#1093;
      </li>
      <li>
        &#1042; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; &#1082; <b>&#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1084; &#1092;&#1072;&#1081;&#1083;&#1072;&#1084;</b>&#160;&#1074;&#1089;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1073;&#1099;&#1090;&#1100; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1099; (mapped) &#1085;&#1072; &#1087;&#1091;&#1090;&#1100; &#1074; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1077;
      </li>
    </ul>
    <p>
      <b>&#1057;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;&#1072; (&#1073;&#1077;&#1079; &#1084;&#1086;&#1076;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1072;).</b>&#160; &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; <b>/&#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;</b>
    </p>
    <p>
      <font color="#008000">server {</font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;location <b>/abc</b>&#160;{</font>&#160;&#160;# &#1059;&#1082;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1084; &#1087;&#1086; &#1082;&#1072;&#1082;&#1086;&#1081; &#1089;&#1089;&#1099;&#1083;&#1082;&#1077; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1077;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;return 200 'Hello'</font>&#160;&#160;# &#1042;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; &#1082;&#1086;&#1076; 200
    </p>
    <p>
      <font color="#008000">&#160;&#160;}</font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
    <p style="text-align: left">
      
    </p>
    <p style="text-align: left">
      <b>&#1055;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1103;</b>
    </p>
    <ol>
      <li>
        <font color="#008000">location <b>=</b>&#160;/&#160;{}</font>&#160;&#160;# <b>&#1055;&#1086;&#1083;&#1085;&#1086;&#1077; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077;</b><br/>
      </li>
      <li>
        <font color="#008000">location <b>^~</b>&#160;/images/ {}<b>&#160; </b></font><b># &#1056;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1099;&#1077; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; &#1053;&#1045;&#160;&#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1102;&#1090;&#1089;&#1103;</b>
      </li>
      <li>
        <font color="#008000">location ~ /abc[0-9] {}&#160; </font><b># &#1056;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1099;&#1077; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103;</b>&#160;(&#1095;&#1091;&#1074;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099; &#1082; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1091;)
      </li>
      <li>
        <font color="#008000">location <b>~*</b>&#160;/abc[0-9] {}<b>&#160; </b></font><b># &#1056;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1099;&#1077; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1103; (&#1085;&#1077;&#1095;&#1091;&#1074;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099; (*)</b>&#160;&#1082; &#1088;&#1077;&#1075;&#1080;&#1089;&#1090;&#1088;&#1091;) ~*==*~
      </li>
      <li>
        <font color="#008000">location / {}&#160;</font>&#160;<b># &#1057;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;&#1072; (&#1073;&#1077;&#1079; &#1084;&#1086;&#1076;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1088;&#1072;).</b>&#160;&#160;&#1057;&#1083;&#1101;&#1096; &#1080; &#1095;&#1090;&#1086; &#1091;&#1075;&#1086;&#1076;&#1085;&#1086; &#1076;&#1072;&#1083;&#1077;&#1077;
      </li>
    </ol>
  </body>
</html></richcontent>
