<node TEXT="Именование локейшена" ID="ID_145345167" CREATED="1551206090812" MODIFIED="1551206689500"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000">location /abc { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;<b>@fallback</b>&#160; </font># &#1058;&#1091;&#1090; &#1084;&#1099; &#1087;&#1077;&#1088;&#1077;&#1076;&#1091;&#1084;&#1072;&#1083;&#1080; &#1076;&#1072;&#1083;&#1100;&#1096;&#1077; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1080; &#1088;&#1077;&#1096;&#1080;&#1083;&#1080; &#1087;&#1077;&#1088;&#1077;&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;&#1072;&#1090;&#1100; &#1085;&#1072; &#1083;&#1086;&#1082;&#1077;&#1096;&#1081;&#1077;&#1085; &#1089; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077;&#1084;
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">location <b>@fallback</b>&#160;{ </font>
    </p>
    <p>
      <font color="#008000">&#8230; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1052;&#1086;&#1078;&#1085;&#1086; &#1085;&#1072;&#1079;&#1074;&#1072;&#1090;&#1100; &#1077;&#1075;&#1086; &#1083;&#1086;&#1082;&#1077;&#1081;&#1096;&#1077;&#1085; &#1080; &#1089;&#1089;&#1099;&#1083;&#1072;&#1090;&#1100;&#1089;&#1103; &#1085;&#1072; &#1083;&#1086;&#1082;&#1077;&#1096;&#1081;&#1077;&#1085; &#1083;&#1086;&#1082;&#1077;&#1081;&#1096;&#1077;&#1085;.</b>
    </p>
    <p>
      <font color="#008000">location /abc { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;@location </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">location @location { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#8230; </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Приоритеты локейшенов" ID="ID_1773818927" CREATED="1536583395780" MODIFIED="1550580135326"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1099; &#1083;&#1086;&#1082;&#1077;&#1081;&#1096;&#1077;&#1085;&#1086;&#1074;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042; nginx:</b>
    </p>
    <ul>
      <li>
        <b>location=/img/1.jpg</b>&#160;&#160;# &#1058;&#1086;&#1095;&#1085;&#1086;&#1077; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077;
      </li>
      <li>
        <b>location^~/pic/</b>&#160;&#160;#&#160;&#1051;&#1086;&#1082;&#1077;&#1081;&#1096;&#1077;&#1085; &#1087;&#1086; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;&#1091;
      </li>
      <li>
        <b>location*~/.jpg$</b>&#160;&#160;#&#160;&#1051;&#1086;&#1082;&#1077;&#1081;&#1096;&#1077;&#1085; &#1087;&#1086; &#1088;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1086;&#1084;&#1091; &#1074;&#1099;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1102;
      </li>
      <li>
        <b>location /img/</b>&#160;&#160;#&#160;&#1051;&#1086;&#1082;&#1077;&#1081;&#1096;&#1077;&#1085; &#1087;&#1086; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;&#1091;, &#1085;&#1086; &#1089; &#1084;&#1077;&#1085;&#1100;&#1096;&#1080;&#1084; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1086;&#1084;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>&#1042; apache:</b>
    </p>
    <ul>
      <li>
        &lt;Location&gt; &#1080; &lt;LocationMatch&gt;
      </li>
      <li>
        &lt;Files&gt; &#1080; &lt;FilesMatch&gt;
      </li>
      <li>
        &lt;DirectoryMatch&gt;
      </li>
      <li>
        &lt;Directory&gt;
      </li>
    </ul>
  </body>
</html></richcontent>
