<node TEXT="Архитектура" ID="ID_1835154574" CREATED="1551269442386" MODIFIED="1551271179410"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_635214160">&#1040;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1072; Apache</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1040;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1072; Nginx</b>
    </p>
    <ul>
      <li>
        &#1048;&#1079;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086; &#1073;&#1099;&#1083; &#1089;&#1087;&#1088;&#1086;&#1077;&#1082;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1085;&#1072; &#1073;&#1072;&#1079;&#1077; &#1072;&#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1085;&#1099;&#1093; &#1085;&#1077;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1102;&#1097;&#1080;&#1093; <b>event-driven</b>&#160; &#1072;&#1083;&#1075;&#1086;&#1088;&#1080;&#1090;&#1084;&#1086;&#1074;
      </li>
      <li>
        &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1090;<b>&#160;&#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1072;&#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1085;&#1086;</b>&#160;- 1 &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089; &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;
      </li>
      <li>
        &#1055;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; <b>&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1086;&#1076;&#1085;&#1086;&#1087;&#1086;&#1090;&#1086;&#1095;&#1085;&#1099;&#1081;</b>&#160; &#1080; &#1086;&#1085; &#1085;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1099; &#1087;&#1086;&#1076; &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;, &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1080; CPU &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1088;&#1072;&#1074;&#1085;&#1086;&#1084;&#1077;&#1088;&#1085;&#1086;, &#1076;&#1072;&#1078;&#1077; &#1087;&#1088;&#1080; &#1074;&#1099;&#1089;&#1086;&#1082;&#1080;&#1093; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072;&#1093;.
      </li>
      <li>
        &#1074;&#1089;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1082; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084;&#1091; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;&#1091; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1103;&#1090;&#1100;&#1089;&#1103; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1084; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, <a href="#ID_203776548">php-fpm</a>). &#1056;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091; &#1095;&#1077;&#1088;&#1077;&#1079; <a href="#ID_1399766583">&#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1087;&#1088;&#1086;&#1082;&#1089;&#1080;</a>
      </li>
      <li>
        &#1074;&#1099;&#1076;&#1072;&#1095;&#1072; <b>&#1089;&#1090;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;&#1072;</b>&#160; &#1073;&#1099;&#1089;&#1090;&#1088;&#1077;&#1077; Apache. &#1053;&#1077; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1082; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1085;&#1099;&#1084; &#1103;&#1079;&#1099;&#1082;&#1072;&#1084;
      </li>
      <li>
        &#1085;&#1077; &#1080;&#1084;&#1077;&#1077;&#1090; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1080; &#1089;&#1072;&#1084;&#1086;&#1089;&#1090;&#1086;&#1103;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099; &#1082; <b>&#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084;&#1091; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;&#1091;</b>. &#1044;&#1083;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; &#1082; PHP &#1080;&#1083;&#1080; &#1076;&#1088;&#1091;&#1075;&#1086;&#1084;&#1091; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1084;&#1091; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;&#1091; Nginx &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1090;&#1100; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1074;&#1085;&#1077;&#1096;&#1085;&#1077;&#1084;&#1091; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1091; &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;, &#1087;&#1086;&#1076;&#1086;&#1078;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1082;&#1072; &#1086;&#1090;&#1074;&#1077;&#1090; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085; &#1080; &#1087;&#1086;&#1083;&#1091;&#1095;&#1080;&#1090;&#1100; &#1077;&#1075;&#1086;. &#1047;&#1072;&#1090;&#1077;&#1084; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091;.<br/>&#1044;&#1083;&#1103; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1086;&#1088;&#1086;&#1074; &#1101;&#1090;&#1086; &#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090;, &#1095;&#1090;&#1086; &#1085;&#1091;&#1078;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; &#1074;&#1079;&#1072;&#1080;&#1084;&#1086;&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1077; Nginx &#1089; &#1090;&#1072;&#1082;&#1080;&#1084; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1086;&#1084; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1103; &#1086;&#1076;&#1080;&#1085; &#1080;&#1079; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1080;&#1079;&#1074;&#1077;&#1089;&#1090;&#1077;&#1085; Nginx'&#1091; (http, <a href="#ID_1685390784">FastCGI</a>, SCGI, uWSGI, memcache). Apache &#1090;&#1086;&#1078;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1074; &#1090;&#1072;&#1082;&#1086;&#1081; &#1084;&#1072;&#1085;&#1077;&#1088;&#1077;
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      1. Nginx &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090; <b>&#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1099;-&#1074;&#1086;&#1088;&#1082;&#1077;&#1088;&#1099;</b>&#160;&#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1080;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1084;&#1086;&#1078;&#1077;&#1090; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1090;&#1100; &#1090;&#1099;&#1089;&#1103;&#1095;&#1080; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1081;. &#1042;&#1086;&#1088;&#1082;&#1077;&#1088;&#1099; &#1076;&#1086;&#1089;&#1090;&#1080;&#1075;&#1072;&#1102;&#1090; &#1090;&#1072;&#1082;&#1086;&#1075;&#1086; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1072; &#1073;&#1083;&#1072;&#1075;&#1086;&#1076;&#1072;&#1088;&#1103; &#1084;&#1077;&#1093;&#1072;&#1085;&#1080;&#1079;&#1084;&#1091; &#1086;&#1089;&#1085;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1084;&#1091; &#1085;&#1072; <b>&#1073;&#1099;&#1089;&#1090;&#1088;&#1086;&#1084; &#1094;&#1080;&#1082;&#1083;&#1077;</b>, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1102;&#1090;&#1089;&#1103; &#1080; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103;.
    </p>
    <p>
      2. &#1050;&#1072;&#1078;&#1076;&#1086;&#1077; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077;, &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1077;&#1084;&#1086;&#1077; &#1074;&#1086;&#1088;&#1082;&#1077;&#1088;&#1086;&#1084;, &#1087;&#1086;&#1084;&#1077;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; <b>event loop</b>&#160;&#1074;&#1084;&#1077;&#1089;&#1090;&#1077; &#1089; &#1076;&#1088;&#1091;&#1075;&#1080;&#1084;&#1080; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103;&#1084;&#1080;. &#1042; &#1101;&#1090;&#1086;&#1084; &#1094;&#1080;&#1082;&#1083;&#1077; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103; <b>&#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1072;&#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1085;&#1086;</b>, &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1103; &#1086;&#1073;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1090;&#1100; &#1079;&#1072;&#1076;&#1072;&#1095;&#1080; &#1074; &#1085;&#1077;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1091;&#1102;&#1097;&#1077;&#1081; &#1084;&#1072;&#1085;&#1077;&#1088;&#1077;.
    </p>
    <p>
      3. &#1050;&#1086;&#1075;&#1076;&#1072; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1079;&#1072;&#1082;&#1088;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1085;&#1086; &#1091;&#1076;&#1072;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1080;&#1079; &#1094;&#1080;&#1082;&#1083;&#1072;.
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Встроенные переменные" ID="ID_1770371151" CREATED="1551249036317" MODIFIED="1551269443596"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1042;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077;</b>
    </p>
    <ul>
      <li>
        &#1052;&#1086;&#1076;&#1091;&#1083;&#1100; ngx_http_core_module &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1077;&#1090; &#1074;&#1089;&#1090;&#1088;&#1086;&#1077;&#1085;&#1085;&#1099;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077;, &#1080;&#1084;&#1077;&#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1089;&#1086;&#1074;&#1087;&#1072;&#1076;&#1072;&#1102;&#1090; &#1089; &#1080;&#1084;&#1077;&#1085;&#1072;&#1084;&#1080; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; Apache. &#1055;&#1088;&#1077;&#1078;&#1076;&#1077; &#1074;&#1089;&#1077;&#1075;&#1086;, &#1101;&#1090;&#1086; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077;, &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1102;&#1097;&#1080;&#1077; &#1080;&#1079; &#1089;&#1077;&#1073;&#1103; &#1087;&#1086;&#1083;&#1103; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;, &#1090;&#1072;&#1082;&#1080;&#1077; &#1082;&#1072;&#1082; $http_user_agent, $http_cookie &#1080; &#1090;&#1086;&#1084;&#1091; &#1087;&#1086;&#1076;&#1086;&#1073;&#1085;&#1086;&#1077;
      </li>
      <li>
        &#1050;&#1088;&#1086;&#1084;&#1077; &#1090;&#1086;&#1075;&#1086;, &#1077;&#1089;&#1090;&#1100; &#1080; &#1076;&#1088;&#1091;&#1075;&#1080;&#1077; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077;:
      </li>
    </ul>
    <p>
      $arg_&#1080;&#1084;&#1103; - &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090; &#1080;&#1084;&#1103; &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;
    </p>
    <p>
      $args - &#1072;&#1088;&#1075;&#1091;&#1084;&#1077;&#1085;&#1090;&#1099; &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;
    </p>
    <p>
      $binary_remote_addr - &#1072;&#1076;&#1088;&#1077;&#1089; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072; &#1074; &#1073;&#1080;&#1085;&#1072;&#1088;&#1085;&#1086;&#1084; &#1074;&#1080;&#1076;&#1077;, &#1076;&#1083;&#1080;&#1085;&#1072; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1103; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; 4 &#1073;&#1072;&#1081;&#1090;&#1072; &#1076;&#1083;&#1103; IPv4-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074; &#1080;&#1083;&#1080; 16 &#1073;&#1072;&#1081;&#1090; &#1076;&#1083;&#1103; IPv6-&#1072;&#1076;&#1088;&#1077;&#1089;&#1086;&#1074;
    </p>
    <p>
      $body_bytes_sent - &#1095;&#1080;&#1089;&#1083;&#1086; &#1073;&#1072;&#1081;&#1090;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085;&#1085;&#1086;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091;, &#1073;&#1077;&#1079; &#1091;&#1095;&#1105;&#1090;&#1072; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; &#1086;&#1090;&#1074;&#1077;&#1090;&#1072;; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1089;&#1086;&#1074;&#1084;&#1077;&#1089;&#1090;&#1080;&#1084;&#1072; &#1089; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1086;&#1084; &#8220;%B&#8221; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103; Apache mod_log_config
    </p>
    <p>
      $bytes_sent - &#1095;&#1080;&#1089;&#1083;&#1086; &#1073;&#1072;&#1081;&#1090;, &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091; (1.3.8, 1.2.5)
    </p>
    <p>
      $connection - &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1086;&#1074;&#1099;&#1081; &#1085;&#1086;&#1084;&#1077;&#1088; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; (1.3.8, 1.2.5)
    </p>
    <p>
      $connection_requests - &#1090;&#1077;&#1082;&#1091;&#1097;&#1077;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074; &#1074; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1080; (1.3.8, 1.2.5)
    </p>
    <p>
      $content_length - &#1087;&#1086;&#1083;&#1077; &#8220;Content-Length&#8221; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;
    </p>
    <p>
      $content_type - &#1087;&#1086;&#1083;&#1077; &#8220;Content-Type&#8221; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;
    </p>
    <p>
      $cookie_&#1080;&#1084;&#1103; - cookie &#1080;&#1084;&#1103;
