      </li>
      <li>
        <b>large_client_header_buffers 2 1k;</b>&#160;# &#1047;&#1072;&#1076;&#1072;&#1105;&#1090; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1086;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1080; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1073;&#1091;&#1092;&#1077;&#1088;&#1086;&#1074; &#1076;&#1083;&#1103; &#1095;&#1090;&#1077;&#1085;&#1080;&#1103; &#1073;&#1086;&#1083;&#1100;&#1096;&#1086;&#1075;&#1086; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;. &#1057;&#1090;&#1088;&#1086;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1072;&#1090;&#1100; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1073;&#1091;&#1092;&#1077;&#1088;&#1072;, &#1080;&#1085;&#1072;&#1095;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072; 414 (Request-URI Too Large). &#1055;&#1086;&#1083;&#1077; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1090;&#1072;&#1082;&#1078;&#1077; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1086; &#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1072;&#1090;&#1100; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1073;&#1091;&#1092;&#1077;&#1088;&#1072;, &#1080;&#1085;&#1072;&#1095;&#1077; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072; 400 (Bad Request). &#1041;&#1091;&#1092;&#1077;&#1088;&#1099; &#1074;&#1099;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1086; &#1084;&#1077;&#1088;&#1077; &#1085;&#1077;&#1086;&#1073;&#1093;&#1086;&#1076;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1073;&#1091;&#1092;&#1077;&#1088;&#1072; &#1088;&#1072;&#1074;&#1077;&#1085; 8K &#1073;&#1072;&#1081;&#1090;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1086; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1085;&#1080;&#1080; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1087;&#1077;&#1088;&#1077;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074; &#1089;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1080;&#1077; keep-alive, &#1101;&#1090;&#1080; &#1073;&#1091;&#1092;&#1077;&#1088;&#1099; &#1086;&#1089;&#1074;&#1086;&#1073;&#1086;&#1078;&#1076;&#1072;&#1102;&#1090;&#1089;&#1103;.
      </li>
    </ul>
    <p>
      <b>&#1058;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090;&#1099;</b>
    </p>
    <ul>
      <li>
        <b>client_body_timeout 60s;</b>&#160;&#160;# &#1047;&#1072;&#1076;&#1072;&#1105;&#1090; &#1090;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090; &#1087;&#1088;&#1080; &#1095;&#1090;&#1077;&#1085;&#1080;&#1080; &#1090;&#1077;&#1083;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;. &#1058;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1077; &#1085;&#1072; &#1074;&#1089;&#1102; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1091; &#1090;&#1077;&#1083;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1084;&#1077;&#1078;&#1076;&#1091; &#1076;&#1074;&#1091;&#1084;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1084;&#1080; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1103;&#1084;&#1080; &#1095;&#1090;&#1077;&#1085;&#1080;&#1103;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1080; &#1101;&#1090;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1089;&#1090;, &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1087;&#1088;&#1077;&#1082;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089; &#1086;&#1096;&#1080;&#1073;&#1082;&#1086;&#1081; 408 (Request Time-out).
      </li>
      <li>
        <b>client_header_timeout 60s;</b>&#160;&#160;# &#1047;&#1072;&#1076;&#1072;&#1105;&#1090; &#1090;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090; &#1087;&#1088;&#1080; &#1095;&#1090;&#1077;&#1085;&#1080;&#1080; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1080; &#1101;&#1090;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090; &#1085;&#1077; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1089;&#1090; &#1087;&#1086;&#1083;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1086;&#1082;, &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1087;&#1088;&#1077;&#1082;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1089; &#1086;&#1096;&#1080;&#1073;&#1082;&#1086;&#1081; 408 (Request Time-out).
      </li>
      <li>
        <b>keepalive_timeout 300;</b>&#160;&#160;# &#1055;&#1077;&#1088;&#1074;&#1099;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#1079;&#1072;&#1076;&#1072;&#1105;&#1090; &#1090;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090;, &#1074; &#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; keep-alive &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1089; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1086;&#1084; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1086; &#1089;&#1086; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. &#1047;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; 0 &#1079;&#1072;&#1087;&#1088;&#1077;&#1097;&#1072;&#1077;&#1090; keep-alive &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1103; &#1089; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1072;&#1084;&#1080;. &#1042;&#1090;&#1086;&#1088;&#1086;&#1081; &#1085;&#1077;&#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1099;&#1081; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#1079;&#1072;&#1076;&#1072;&#1105;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074; &#1087;&#1086;&#1083;&#1077; &#8220;Keep-Alive: timeout=&#1074;&#1088;&#1077;&#1084;&#1103;&#8221; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; &#1086;&#1090;&#1074;&#1077;&#1090;&#1072;. &#1044;&#1074;&#1072; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; &#1084;&#1086;&#1075;&#1091;&#1090; &#1086;&#1090;&#1083;&#1080;&#1095;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1088;&#1091;&#1075; &#1086;&#1090; &#1076;&#1088;&#1091;&#1075;&#1072;.
      </li>
      <li>
        <b>send_timeout 10;</b>&#160;&#160;# &#1047;&#1072;&#1076;&#1072;&#1105;&#1090; &#1090;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1077; &#1086;&#1090;&#1074;&#1077;&#1090;&#1072; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090;&#1091;. &#1058;&#1072;&#1081;&#1084;&#1072;&#1091;&#1090; &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1077; &#1085;&#1072; &#1074;&#1089;&#1102; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1095;&#1091; &#1086;&#1090;&#1074;&#1077;&#1090;&#1072;, &#1072; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1084;&#1077;&#1078;&#1076;&#1091; &#1076;&#1074;&#1091;&#1084;&#1103; &#1086;&#1087;&#1077;&#1088;&#1072;&#1094;&#1080;&#1103;&#1084;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1103;&#1084;&#1080;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1086; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1080; &#1101;&#1090;&#1086;&#1075;&#1086; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1082;&#1083;&#1080;&#1077;&#1085;&#1090; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1087;&#1088;&#1080;&#1084;&#1077;&#1090;, &#1089;&#1086;&#1077;&#1076;&#1080;&#1085;&#1077;&#1085;&#1080;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1082;&#1088;&#1099;&#1090;&#1086;.
      </li>
    </ul>
    <p>
      <b>&#1058;&#1080;&#1087;&#1099; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;&#1072;</b>
    </p>
    <ul>
      <li>
        <b>include mime.types;</b>&#160;&#160;# &#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; &#1089;&#1086; &#1074;&#1089;&#1077;&#1084;&#1080; &#1090;&#1080;&#1087;&#1072;&#1084;&#1080; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;&#1072; &#1080;&#1083;&#1080; &#1074;&#1074;&#1086;&#1076;&#1080;&#1084; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; types {}
      </li>
      <li>
        <b>types {</b>&#160;&#160;# &#1058;&#1080;&#1087; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;&#1072;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1077; &#1091;&#1082;&#1072;&#1079;&#1072;&#1090;&#1100;, &#1090;&#1086; &#1085;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1082;&#1072;&#1088;&#1090;&#1080;&#1085;&#1082;&#1080;<br/>&#160;&#160;&#160;&#160;text/html html;<br/>&#160;&#160;&#160;&#160;text/css css;<br/>&#160;&#160;&#160;&#160;application/x-httpd-php;<br/><b>}</b>
      </li>
    </ul>
    <p>
      <b>}</b>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
