<node TEXT="Авторизация" FOLDED="true" ID="ID_253059287" CREATED="1536911372893" MODIFIED="1550925158347"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1086;&#1089;&#1090;&#1072;&#1103; &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1103;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1043;&#1077;&#1085;&#1077;&#1088;&#1072;&#1094;&#1080;&#1103; &#1087;&#1072;&#1088;&#1086;&#1083;&#1077;&#1081;</b>
    </p>
    <p>
      <font color="#0000c0">apt install apache2-utils </font>
    </p>
    <p>
      <font color="#0000c0">htpassword&#160;&#160;-c /etc/nginx/.htpassw &lt;&#1080;&#1084;&#1103;&gt;</font>&#160; &#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1072;&#1088;&#1086;&#1083;&#1100;
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000"># nginx.conf</font></b>
    </p>
    <p>
      <font color="#008000">http { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;server { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;location / { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;auth_basic &quot;&#1057;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1077; &#1086; &#1085;&#1077;&#1086;&#1073;&#1093;. &#1072;&#1091;&#1090;&#1077;&#1085;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;&quot;; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;auth_basic_user_file /etc/nginx/.htpassw; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;} </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;} </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="HTTP Авторизация" ID="ID_225120247" CREATED="1536910787790" MODIFIED="1550924582221"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b><font color="#008000"># nginx</font></b>
    </p>
    <p>
      <font color="#008000">location / { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;auth_basic&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&quot;closed site&quot;&#160; </font># &#1044;&#1072;&#1085;&#1085;&#1099;&#1081; &#1083;&#1086;&#1082;&#1077;&#1081;&#1096;&#1085; &#1085;&#1091;&#1078;&#1085;&#1086; &#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;auth_basic_user_file&#160;&#160;&#160;&#160;conf/myhtpasswd;</font>&#160; &#160;# &#1060;&#1072;&#1081;&#1083; &#1089; &#1083;&#1086;&#1075;&#1080;&#1085;&#1072;&#1084;&#1080;/&#1087;&#1072;&#1088;&#1086;&#1083;&#1103;&#1084;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Авторизация по IP-адресам" ID="ID_1121468042" CREATED="1536911379452" MODIFIED="1536915299739"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1054;&#1075;&#1088;&#1072;&#1085;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077; &#1083;&#1086;&#1082;&#1077;&#1081;&#1096;&#1085;&#1086;&#1074; &#1087;&#1086; ip-&#1072;&#1076;&#1088;&#1077;&#1089;&#1072;&#1084;.</b>&#160;&#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1086;&#1092;&#1080;&#1089;&#1072; (&#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1072;&#1103; &#1089;&#1077;&#1090;&#1100;)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">location / { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;satisfy any;</font>&#160;&#160;# &#1044;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1074;&#1072;, &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1102;&#1097;&#1072;&#1103; &#1084;&#1077;&#1090;&#1086;&#1076; &#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; (&#1087;&#1086; &#1083;&#1086;&#1075;&#1080;&#1085;&#1091; &#1080;&#1083;&#1080; &#1087;&#1086; ip-&#1072;&#1076;&#1088;&#1077;&#1089;&#1091;)
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;allow 192.168.1.0/24; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;allow 2001:0db8::/32; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;deny all; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;auth_basic&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&quot;closed site&quot;&#160;&#160;</font># &#1044;&#1072;&#1085;&#1085;&#1099;&#1081; &#1083;&#1086;&#1082;&#1077;&#1081;&#1096;&#1085; &#1085;&#1091;&#1078;&#1085;&#1086; &#1072;&#1074;&#1090;&#1086;&#1088;&#1080;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;auth_basic_user_file&#160;&#160;&#160;&#160;conf/myhtpasswd;</font>&#160; &#160;# &#1060;&#1072;&#1081;&#1083; &#1089; &#1083;&#1086;&#1075;&#1080;&#1085;&#1072;&#1084;&#1080;/&#1087;&#1072;&#1088;&#1086;&#1083;&#1103;&#1084;&#1080;
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>htpasswd</b>&#160;- &#1092;&#1072;&#1081;&#1083; &#1089; &#1087;&#1072;&#1088;&#1086;&#1083;&#1103;&#1084;&#1080; (&#1079;&#1072;&#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1081;)
    </p>
    <p>
      <font color="#0000c0"># htpasswd -m ./myhtpasswd user pass</font>&#160;&#160;#&#160;&#160;&#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0"># htpasswd -D ./myhtpasswd user</font>&#160;&#160;# &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100;
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="SSL" ID="ID_1130665279" CREATED="1663847703238" MODIFIED="1721566373971"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1009203346">SSL</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Разрешения:</b>
    </p>
    <ul>
      <li>
        444 - для сертификата
      </li>
      <li>
        400 - для ключа
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <font color="#008000">server { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;listen 443; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;ssl on; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;ssl_certificate/etc/ssl/certs/admin.com.cr t; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;ssl_certificate_key/etc/ssl/private/admin.com.crt; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;ssl_protocols TLSv1 TLSv1.1 TLSv1.2;&nbsp;</font>&nbsp;# Должны быть включены только фактические протоколы TLS (а не старые версии SSL); все протоколы SSL устарели
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;ssl_ciphers ECDHE-RSA-AES... </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;ssl_prefer_server_ciphers on; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;server_name admin.com www.admin.com; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;root /var/www/admin.com/site1; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="SSL - Самоподписанный сертификат" ID="ID_1084274061" CREATED="1550923738591" MODIFIED="1663848302917"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1009203346">SSL</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Создать самоподписанный сертификат и ключ</b>
    </p>
    <p>
      <font color="#0000c0">mkdir /etc/nginx/ssl</font>
    </p>
    <p>
      <font color="#0000c0">openssl&nbsp;&nbsp;req -x509 -nodes -days 365 -newkey rsa:2048 -keyout /etc/nginx/ssl/nginx.key -out /etc/nginx/ssl/nginx.crt </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">http { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;server { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;listen 443 ssl;&nbsp; </font># Прослушивать порт 443 и использовать SSL
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;ssl_certificate&nbsp;&nbsp;/etc/nginx/ssl/nginx.crt;&nbsp; </font># Расположение файла сертификата
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;ssl_certificate_key&nbsp;&nbsp;/etc/nginx/ssl/nginx.key;&nbsp; </font># Расположение ключа
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;} </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="SSL - сертификат Let&apos;s Encrypt" ID="ID_1536983228" CREATED="1550929097436" MODIFIED="1556453999935"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_711545847">&#1062;&#1077;&#1085;&#1090;&#1088; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1094;&#1080;&#1080;</a>&#160;&#160;<a href="#ID_1009203346">SSL</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      &#1050;&#1083;&#1080;&#1077;&#1085;&#1090; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072; ACME, <b>certbot</b>&#160;(&#1088;&#1072;&#1085;&#1077;&#1077; letsencrypt), &#1086;&#1090;&#1082;&#1088;&#1099;&#1090; &#1087;&#1086;&#1076; &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1077;&#1081; Apache &#1080; &#1085;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085; &#1085;&#1072; &#1103;&#1079;&#1099;&#1082;&#1077; Python.
    </p>
    <ul>
      <li>
        &#1059;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; &#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1086;&#1084; &#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077; &#1080; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072;, &#1087;&#1088;&#1086;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1103; &#1074;&#1072;&#1083;&#1080;&#1076;&#1072;&#1094;&#1080;&#1080; &#1076;&#1086;&#1084;&#1077;&#1085;&#1072;, &#1080;&#1085;&#1089;&#1090;&#1072;&#1083;&#1083;&#1103;&#1094;&#1080;&#1080; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072; &#1080; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1080; HTTPS-&#1096;&#1080;&#1092;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1074; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1077;
      </li>
      <li>
        &#1042; &#1076;&#1072;&#1083;&#1100;&#1085;&#1077;&#1081;&#1096;&#1077;&#1084; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1076;&#1083;&#1103; &#1088;&#1077;&#1075;&#1091;&#1083;&#1103;&#1088;&#1085;&#1086;&#1075;&#1086; &#1087;&#1077;&#1088;&#1077;&#1074;&#1099;&#1087;&#1091;&#1089;&#1082;&#1072; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072; &#1087;&#1086; &#1084;&#1077;&#1088;&#1077; &#1086;&#1082;&#1086;&#1085;&#1095;&#1072;&#1085;&#1080;&#1103; &#1089;&#1088;&#1086;&#1082;&#1072; &#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103;
      </li>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; &#1080; &#1087;&#1088;&#1080;&#1085;&#1103;&#1090;&#1080;&#1103; &#1083;&#1080;&#1094;&#1077;&#1085;&#1079;&#1080;&#1080; &#1076;&#1086;&#1089;&#1090;&#1072;&#1090;&#1086;&#1095;&#1085;&#1086; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1086;&#1076;&#1085;&#1091; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1076;&#1083;&#1103; &#1087;&#1086;&#1083;&#1091;&#1095;&#1077;&#1085;&#1080;&#1103; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072;. &#1044;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1084;&#1086;&#1075;&#1091;&#1090; &#1073;&#1099;&#1090;&#1100; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1099; &#1086;&#1087;&#1094;&#1080;&#1080; OCSP stapling &#1080; HTTP Strict Transport Security (HSTS, &#1087;&#1088;&#1080;&#1085;&#1091;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1077; &#1087;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1089; HTTP &#1085;&#1072; HTTPS). &#1040;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1081;&#1082;&#1072; https-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072; &#1080;&#1079;&#1085;&#1072;&#1095;&#1072;&#1083;&#1100;&#1085;&#1086; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1072; &#1076;&#1083;&#1103; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1086;&#1074; Apache &#1080; nginx.
      </li>
    </ul>
    <p>
      <b>1. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; nginx </b>
    </p>
    <p>
      <font color="#008000">#nginx.conf </font>
    </p>
    <p>
      <font color="#008000">server { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;server_name a1.com; </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
    <p>
      <b>2. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; certbot&#160;</b>&#160; (https://certbot.eff.org)
    </p>
    <p>
      <b>3. &#1057;&#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; SSL &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1099; &#1095;&#1077;&#1088;&#1077;&#1079; Let's Enctypt.</b>&#160; &#1058;&#1072;&#1082;&#1078;&#1077; &#1074;&#1085;&#1086;&#1089;&#1103;&#1090;&#1089;&#1103; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1074; nginx.conf
    </p>
    <p>
      <font color="#0000c0">certbot --nginx</font>
    </p>
    <ul>
      <li>
        /etc/letsencrypt/live/a1.com/ - &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1089;&#1086; &#1089;&#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1072;&#1084;&#1080;
      </li>
    </ul>
    <p>
      <b>4. &#1054;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1089;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090;&#1086;&#1074;.</b>&#160; &#1057;&#1077;&#1088;&#1090;&#1080;&#1092;&#1080;&#1082;&#1072;&#1090; &#1074;&#1099;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1072; <b>90 &#1076;&#1085;&#1077;&#1081; </b>
    </p>
    <p>
      <font color="#0000c0">certbot renew</font>&#160;&#160;# &#1054;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102;. &#1054;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1077;&#1076;&#1077;&#1085;&#1086; &#1077;&#1089;&#1083;&#1080; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103;.
    </p>
    <p>
      <font color="#0000c0">certbot renew --dry-run</font>&#160;&#160;# &#1054;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074;&#1088;&#1091;&#1095;&#1085;&#1091;&#1102; (<b>force</b>)
    </p>
    <p>
      <font color="#0000c0">crontab -e</font>&#160;&#160;# &#1042;&#1085;&#1086;&#1089;&#1080;&#1084; &#1074; &#1087;&#1083;&#1072;&#1085;&#1080;&#1088;&#1086;&#1074;&#1097;&#1080;&#1082; &#1079;&#1072;&#1076;&#1072;&#1095;&#1091;
    </p>
    <p>
      <font color="#008000">@daily certbot renew</font>&#160;&#160;# &#1047;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100; &#1082;&#1086;&#1084;&#1072;&#1085;&#1076;&#1091; &#1074; &#1087;&#1086;&#1083;&#1085;&#1086;&#1095;&#1100; &#1082;&#1072;&#1078;&#1076;&#1099;&#1077; &#1089;&#1091;&#1090;&#1082;&#1080;
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Скрыть версию nginx" ID="ID_935044666" CREATED="1657886055240" MODIFIED="1657886138143">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Скрыть информацию о серере в ответах на запросы</b>&nbsp;- Отключить серверные токены
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">vim /etc/nginx/nginx.conf</font>
    </p>
    <p>
      <font color="#008000">http { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;server_tokens off; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Скрыть версию PHP" ID="ID_502277849" CREATED="1657886047740" MODIFIED="1657886157985">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Скрыть заголовок о версии PHP (X-Powered-By:) для каждого сайта</b>&nbsp;(в глобальной конфигурации не работает)
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">vim /etc/nginx/site-available/домен_или_поддомен</font>
    </p>
    <p>
      <font color="#008000">server </font>
    </p>
    <p>
      <font color="#008000">{ </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;fastcgi_hide_header 'X-Powered-By'; </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Защита от XSS" ID="ID_1686706048" CREATED="1657887793932" MODIFIED="1657889727398">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1824377443">XSS</a>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">vim /etc/nginx/nginx.conf</font>
    </p>
    <p>
      <font color="#008000">#Avoiding XSS attacks - код можно вставить после gzip </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;add_header X-Frame-Options SAMEORIGIN;</font>&nbsp;&nbsp;# X-Frame-Options разрешен только с того же домена
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;add_header X-Content-Type-Options nosniff;&nbsp; </font># Запрет перехватов&nbsp;&nbsp;MIME-type ответов сервера
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;add_header X-XSS-Protection &quot;1; mode=block&quot;;</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Защита от DDoS" ID="ID_1542506391" CREATED="1657891576030" MODIFIED="1659134536874">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_210702592">DoS/DDoS</a>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">vim /etc/nginx/nginx.conf</font>
    </p>
    <p>
      #Mitigating DoS and DDoS attacts -- можно писать после gzip
    </p>
    <p>
      <font color="#008000">client_body_buffer_size 4m;</font>&nbsp;&nbsp;# Не получать запросы буфер более 4MB
    </p>
    <p>
      <font color="#008000">large_client_header_buffers 4 4m;&nbsp; </font># Макс. разер заголовка 4MB
    </p>
    <p>
      <font color="#008000">limit_conn_zone $binary_remote_addr zone=conn_limit_per_ip:10m;&nbsp; </font># Ограничить кол-во подключений из одной области IP
    </p>
    <p>
      <font color="#008000">limit_req_zone $binary_remote_addr zone=req_limit_per_ip:10m rate=3r/s;&nbsp; </font># Кол-во запросов в секунду с одного IP
    </p>
    <p>
      <font color="#008000">limit_conn conn_limit_per_ip 15;&nbsp; </font># Кол-во подключений с одного IP
    </p>
    <p>
      <font color="#008000">limit_req zone=req_limit_per_ip burst=20;</font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Виртуальные хосты" FOLDED="true" ID="ID_18292238" CREATED="1535546169132" MODIFIED="1742384879377"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_994847955">Виртуальные хосты (Apache)</a>&#xa0;&#xa0;<a href="#ID_401373032">Виртуальный хостинг</a>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">nginx -T | grep &quot;server_name&quot;&#xa0; </span># Список виртуальных хостов
    </p>
    <p>
      <span style="color: #0000c0;">netstat&#xa0;-tlpn</span>&#xa0;# убедитесь, что порт 80 никем не занят. Если занят - освободите его
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/nginx/<b>nginx.conf</b></span>
    </p>
    <ol>
      <li>
        Очистить контекст <b>http {}</b>
      </li>
      <li>
        Очистить основной контекст
      </li>
      <li>
        Очистить контекст <b>events {}</b>
      </li>
    </ol>
    <p>
      <span style="color: #008000;">events {}</span>&#xa0;&#xa0;# Без этого контекста не будет работать
    </p>
    <p>
      <span style="color: #008000;">http {</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;include <b>mime.types</b>;</span>&#xa0;&#xa0;# Подключить файл со всеми типами контента или вводим контекст <b>types {}</b>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;types {&#xa0; </span># Тип контента. Если не указать, то не будут отображаться, например, картинки
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;text/html html;</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;text/css css;</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;...;</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;}</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;server {</span>&#xa0;&#xa0;# Описание виртуального хоста <b>ИЛИ</b>&#xa0;&#xa0;контекст server выносим в отдельные файлы (см. <a href="#ID_735491559">Каталоги sites-available и sites-enabled</a>)
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;listen 80;</span>&#xa0;# Определить порт, который будет прослушивать vhost =&gt; 127.0.0.1:80
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;server_name localhost;</span>&#xa0;&#xa0;# Имя домена, сервера, IP-адрес. Что прийдет в заголовке host
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;root /var/www/мойсайт.com;</span>&#xa0;&#xa0;# Корневая папка
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;location /abc {&#xa0; </span># Указываем по какой ссылке пользователь переходит в браузере
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;return 200 'Hello'</span>&#xa0;&#xa0;# Вернуть код 200
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;}</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;}</span>
    </p>
    <p>
      <span style="color: #008000;">}</span>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="Каталоги sites-available и sites-enabled" FOLDED="true" ID="ID_735491559" CREATED="1551100402954" MODIFIED="1742384879386"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Подключить каталоги sites-available и sites-enabled</b>.
    </p>
    <ul>
      <li>
        <b>/etc/nginx/</b>
      </li>
      <li>
        Некоторые дистрибутивы не создают данные каталоги
      </li>
      <li>
        каталоги sites-available и sites-enabled - очень хорошая и <b>удобная практика</b>
      </li>
    </ul>
    <p>
      <b>1. Создать каталоги</b>
    </p>
    <p>
      <span style="color: #0000c0;">mkdir /etc/nginx/sites-available </span>
    </p>
    <p>
      <span style="color: #0000c0;">mkdir /etc/nginx/sites-enabled </span>
    </p>
    <p>
      <b>2. В nginx.conf прописать ссылку на enabled</b>
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/nginx/nginx.conf</span>
    </p>
    <p>
      <span style="color: #008000;">http { </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;include /etc/nginx/sites-enabled/*; </span>
    </p>
    <p>
      <span style="color: #008000;">} </span>
    </p>
    <p>
      <b>3. Настроить виртуальные хосты. Например, <a href="#ID_738781883">a1.com</a>, <a href="#ID_482788545">b2.com</a>&#xa0;</b>
    </p>
    <p>
      
    </p>
    <p>
      <b>4. Активировать вирт. хосты.</b>&#xa0;&#xa0;Для этого надо создать <a href="#ID_1371009817">символические ссылки</a>&#xa0;на эти файлы и положить их в каталог sites-enabled, которые Nginx считывает при запуске<br/><span style="color: #0000c0;">ln -s /etc/nginx/sites-available/a1.com.conf /etc/nginx/sites-enabled/</span><br color="#0000c0" style="color: #0000c0;"/><span style="color: #0000c0;">ln -s /etc/nginx/sites-available/b2.com.conf /etc/nginx/sites-enabled/</span>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<node TEXT="a1.com.conf" POSITION="bottom_or_right" ID="ID_738781883" CREATED="1551096130328" MODIFIED="1742384909449"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">vim /etc/nginx/sites-available/a1.com.conf</span>
    </p>
    <p>
      <span style="color: #008000;">server {</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;listen 80 <b>default_server</b>;&#xa0; </span># Только одному блоку server мы можем установить значение default_server. Блок с таким значением будет обслуживать запросы, если не было найдено подходящего блока
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;listen [::]:80 <b>default_server</b>&#xa0;ipv6only=on; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;root /var/www/a1.com; </span>&#xa0;# Корневой каталог, где лежат все документы сайта
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;index index.html index.htm;</span>&#xa0;&#xa0;# Файл по умолчанию
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;server_name a1.com www.a1.com; </span>&#xa0;# Что прийдет в заголовке host. Директива должна соответствовать первому доменному имени. Можно добавить псевдоним
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;location / {</span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;try_files $uri $uri/ =404; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;} </span>
    </p>
    <p>
      <span style="color: #008000;">}</span>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="b2.com.conf" POSITION="bottom_or_right" ID="ID_482788545" CREATED="1551096938950" MODIFIED="1742384897603"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">vim /etc/nginx/sites-available/b2.com.conf</span>
    </p>
    <p>
      <span style="color: #008000;">server { </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;listen 80; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;listen [::]:80; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;root /var/www/b2.com; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;index index.html index.htm; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;server_name b2.com www.b2.com; </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;location / { </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;try_files $uri $uri/ =404; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;} </span>
    </p>
    <p>
      <span style="color: #008000;">}</span>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
</node>
<node TEXT="https виртуальные хосты" ID="ID_345940254" CREATED="1742384914864" MODIFIED="1742385459969"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1009203346">SSL/TLS</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      SNI (Server Name Indication), которая является расширением протокола TLS (Transport Layer Security). SNI позволяет серверу выбирать правильный сертификат для каждого виртуального хоста на основе имени хоста, указанного клиентом во время handshake-процесса TLS.
    </p>
    <p>
      
    </p>
    <p>
      Пример конфигурации:
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">server { </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;listen 443 ssl; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;server_name site1.example.com; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ssl_certificate /path/to/site1.crt; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ssl_certificate_key /path/to/site1.key; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;root /var/www/site1; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">} </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">server { </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;listen 443 ssl; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;server_name site2.example.com; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ssl_certificate /path/to/site2.crt; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;ssl_certificate_key /path/to/site2.key; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;root /var/www/site2; </span>
    </p>
    <p>
      <span style="font-family: Lucida Console; color: #008000;">}</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">systemctl reload nginx</span>&#xa0;&#xa0;# Перезагрузить Nginx
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Диагностика" ID="ID_1710377602" CREATED="1764760320254" MODIFIED="1764760442926"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">nginx -T</span>&#xa0;&#xa0;# Выводит полный составной конфигурационный файл со всеми include, раскрытыми в том порядке, в каком они обрабатываются
    </p>
    <p>
      <span style="color: #0000c0;">nginx -T | grep -A 5 -B 5 &quot;listen.*80&quot; </span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Динамические модули" ID="ID_1242843822" CREATED="1550845736609" MODIFIED="1551173276187"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1044;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;</b>&#160;- &#1084;&#1086;&#1076;&#1091;&#1083;&#1080;, &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1097;&#1080;&#1077; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1091;&#1102; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;
    </p>
    <ul>
      <li>
        <font color="#0000c0">./configure&#160;--help</font>&#160;# =&gt; --with mail<b>=dinamic</b>. &#1042;&#1099;&#1074;&#1086;&#1076; &#1092;&#1083;&#1072;&#1075;&#1086;&#1074; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;
      </li>
      <li>
        &#1057; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; Nginx 1.9.1
      </li>
      <li>
        &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085; &#1084;&#1072;&#1082;&#1089;&#1080;&#1084;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1083;&#1080;&#1084;&#1080;&#1090; &#1074; <b>128</b>&#160; &#1086;&#1076;&#1085;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084;&#1099;&#1093; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1093; &#1084;&#1086;&#1076;&#1091;&#1083;&#1077;&#1081;. &#1069;&#1090;&#1086; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1074; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; NGX_MAX_DYNAMIC_MODULES &#1074; &#1080;&#1089;&#1093;&#1086;&#1076;&#1085;&#1086;&#1084; &#1082;&#1086;&#1076;&#1077; nginx.
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">./configure --&lt;&#1092;&#1083;&#1072;&#1075; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;=dynamic&gt;</font>&#160;&#160;# &#1042;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102;
    </p>
    <p>
      ./configure --with-http_image_filter_module=dynamic
    </p>
    <p>
      <b>make </b>
    </p>
    <p>
      <b>make install </b>
    </p>
    <p>
      <b>service nginx start </b>
    </p>
    <ul>
      <li>
        &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1072;&#1087;&#1082;&#1072; <b>modules</b>&#160;&#1089; &#1089;&#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1084;&#1080; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;&#1084;&#1080; <b>file.so</b>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <b>&#1047;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1072; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;</b>
    </p>
    <p>
      &#1052;&#1086;&#1076;&#1091;&#1083;&#1080; &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1090;&#1100; &#1074; nginx &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1074;&#1099; load_module
    </p>
    <p>
      <font color="#008000">load_module modules/ngx_my_module.so;</font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b>----------------------------- </b>
    </p>
    <p>
      <b>&#1050;&#1086;&#1084;&#1087;&#1080;&#1083;&#1103;&#1094;&#1080;&#1103; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1084;&#1086;&#1076;&#1091;&#1083;&#1103;</b>
    </p>
    <p>
      &#1042;&#1084;&#1077;&#1089;&#1090;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; --add-module &#1087;&#1080;&#1096;&#1077;&#1084; --add-dynamic-module. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;:
    </p>
    <p>
      ./configure --add-dynamic-module=/opt/source/ngx_my_module/
    </p>
    <ul>
      <li>
        &#1055;&#1086;&#1089;&#1083;&#1077; &#1082;&#1086;&#1084;&#1087;&#1080;&#1083;&#1103;&#1094;&#1080;&#1080; &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1086;&#1079;&#1076;&#1072;&#1085; &#1073;&#1080;&#1085;&#1072;&#1088;&#1085;&#1099;&#1081; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; &#1074; &#1092;&#1072;&#1081;&#1083;&#1077; .so (Shared Object). &#1069;&#1090;&#1086;&#1090; &#1092;&#1072;&#1081;&#1083; &#1079;&#1072;&#1090;&#1077;&#1084; &#1087;&#1077;&#1088;&#1077;&#1085;&#1086;&#1089;&#1080;&#1090;&#1089;&#1103; &#1074; &#1087;&#1086;&#1076;&#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1102; modules &#1074; &#1087;&#1072;&#1087;&#1082;&#1077; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; nginx
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">nginx -V</font>&#160;&#160;# &#1055;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1099; &#1089; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084;&#1080; &#1073;&#1099;&#1083; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085; Nginx
    </p>
    <p>
      -------------------------
    </p>
    <p>
      <font color="#0000c0">add-apt-repository ppa:nginx/stable </font>
    </p>
    <p>
      <font color="#0000c0">apt-get update </font>
    </p>
    <p>
      <font color="#0000c0">apt-get install nginx-module-geoip&#160;</font>&#160;# &#1052;&#1086;&#1076;&#1091;&#1083;&#1100; &#1074; /usr/lib/nginx/modules
    </p>
    <p>
      
    </p>
    <p>
      &#1063;&#1090;&#1086;&#1073;&#1099; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; nginx, &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1100; nginx.conf, &#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1074; &#1086;&#1089;&#1085;&#1086;&#1074;&#1085;&#1086;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090;
    </p>
    <p>
      <font color="#0000c0">vim /etc/nginx/nginx.conf</font>
    </p>
    <p>
      <font color="#008000">load_module &quot;modules/ngx_http_geoip_module.so&quot;;</font>
    </p>
    <p>
      
    </p>
    <p>
      &#1052;&#1086;&#1076;&#1091;&#1083;&#1100; &#1073;&#1091;&#1076;&#1077;&#1090; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085; &#1087;&#1088;&#1080; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1080; &#1080;&#1083;&#1080; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1077; nginx.
    </p>
    <p>
      &#1063;&#1090;&#1086;&#1073;&#1099; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &quot;&#1074;&#1099;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100;&quot; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100;, &#1079;&#1072;&#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1080;&#1088;&#1091;&#1081;&#1090;&#1077; &#1080;&#1083;&#1080; &#1091;&#1076;&#1072;&#1083;&#1080;&#1090;&#1077; &#1077;&#1075;&#1086; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1074;&#1091; load_module &#1080; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1077; &#1082;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1072;&#1094;&#1080;&#1102; nginx.
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
