<node TEXT="Журналирование" ID="ID_1925141681" CREATED="1550743633452" MODIFIED="1663843317240"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        логи ошибок - <b>error.log</b>
      </li>
      <li>
        логи доступа - <b>access.log</b>&nbsp;&nbsp;- инфо о всех запросах к серверу
      </li>
      <li>
        логирование активируется <b>по умолчанию</b>
      </li>
      <li>
        <b>/var/log/nginx/. </b>Место хранения логов указывается при сборке из <a href="#ID_745686580">исходных кодов</a>
      </li>
      <li>
        <b>404 - не ошибка</b>. Отражается в <b>access.log</b>
      </li>
    </ul>
    <p>
      <font color="#0000c0">echo '' &gt; /var/log/nginx/access.log</font>&nbsp;&nbsp;# Очистить лог доступа
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">error_log /var/log/nginx/error.log warn;&nbsp; </font><b># Расположение error-лога (указ. в основном контексте)</b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">location /download {&nbsp; </font><b># Ошибки блока /downloads складывать в отдельный файл</b>
    </p>
    <p>
      <font color="#008000">&nbsp; <b>error_log</b>&nbsp;/var/log/nginx/downloads.error.log <b>debug</b>;</font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      <font color="#008000">location /download {</font><b>&nbsp;&nbsp;# Отключение логов в определенных локейшнах</b>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;access_log off; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;error_log off; </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      <b>Уровни логирования</b>
    </p>
    <ul>
      <li>
        <b>debug</b>&nbsp;- информация для отладки, которая может помочь определить проблему
      </li>
      <li>
        <b>info</b>&nbsp;- важная информация, которую следует принять к сведению
      </li>
      <li>
        <b>notice</b>&nbsp;- система в норме, но стоит обратить внимание на её состояние
      </li>
      <li>
        <b>warn</b>&nbsp;- предупреждение; в системе что-то произошло, но причин для беспокойства нет
      </li>
      <li>
        <b>error</b>&nbsp;- произошла ошибка
      </li>
      <li>
        <b>crit</b>&nbsp;- критические проблемы, которые необходимо решить
      </li>
      <li>
        <b>alert</b>&nbsp;- сложная предаварийная ситуация, необходимо срочно принять меры
      </li>
      <li>
        <b>emerg</b>&nbsp;- критическая ситуация, аварийный сбой, система находится в нерабочем состоянии
      </li>
    </ul>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Кэширование в FastCGI" ID="ID_1216086750" CREATED="1550904860998" MODIFIED="1551249679157"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1050;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; FastCGI</b>&#160;- &#1084;&#1080;&#1082;&#1088;&#1086;&#1082;&#1101;&#1096;
    </p>
    <ul>
      <li>
        <font color="#0000c0">ab -n 100 -c 10 http://a1.com/</font>&#160;&#160;# &#1041;&#1077;&#1085;&#1095;&#1084;&#1072;&#1088;&#1082; Apache. &#1058;&#1077;&#1089;&#1090;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1076;&#1086; &#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1081;
      </li>
      <li>
        <font color="#0000c0">curl -I http://ya.ru</font>&#160;&#160;# &#1042;&#1079;&#1103;&#1090;&#1100; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1080;&#1079; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; HTTP &#1074;&#1077;&#1073;-&#1089;&#1072;&#1081;&#1090;&#1072;. -I (i &#1073;&#1086;&#1083;&#1100;&#1096;&#1072;&#1103;)
      </li>
    </ul>
    <p>
      <font color="#008000">http { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;fastcgi_cache microcache;</font>&#160;&#160;# &#1048;&#1084;&#1103; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; keys_zone
    </p>
    <p>
      <font color="#008000">&#160;&#160;fastcgi_cache_valid 200 60m;</font>&#160;&#160;# &#1050;&#1086;&#1076; &#1086;&#1090;&#1074;&#1077;&#1090;&#1072; &#1080; &#1084;&#1072;&#1082;&#1089;. &#1074;&#1088;&#1077;&#1084;&#1103; &#1093;&#1088;&#1072;&#1085;&#1077;&#1085;&#1080;&#1103; &#1082;&#1101;&#1096;&#1072;
    </p>
    <p>
      <font color="#008000">&#160;&#160;add_header microcache-status $upstream_cache_status;</font>&#160;&#160;# &#1044;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089;&#1072; &#1082;&#1101;&#1096;&#1072; &#1074; &#1086;&#1090;&#1074;&#1077;&#1090;. &#1063;&#1090;&#1086;&#1073;&#1099; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1073;&#1099;&#1083; &#1083;&#1080; &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1077;&#1085; &#1086;&#1090;&#1074;&#1077;&#1090; &#1080;&#1079; &#1082;&#1101;&#1096;&#1072;. microcache-status - &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086;&#1084;&#1077;&#1085;&#1103;&#1090;&#1100;. &#1045;&#1089;&#1083;&#1080; &#1086;&#1090;&#1074;&#1077;&#1090; (<font color="#0000c0">curl -I http://ya.ru</font>):
    </p>
    <ul>
      <li>
        HIT - &#1086;&#1090;&#1074;&#1077;&#1090; &#1080;&#1079; &#1082;&#1101;&#1096;&#1072;
      </li>
      <li>
        BYPASS - &#1085;&#1080;&#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1077; &#1082;&#1101;&#1096;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103;
      </li>
      <li>
        MISS - &#1082;&#1101;&#1096; &#1085;&#1077; &#1072;&#1082;&#1090;&#1091;&#1072;&#1083;&#1077;&#1085;
      </li>
    </ul>
    <p>
      <font color="#008000">&#160;&#160;server { </font>
    </p>
    <p>
      &#160;&#160;&#160;&#160;<font color="#008000">fastcgi_cache_path /tmp/nginx_cache levels=1:2 keys_zone=microcache:10m max_size=500m;</font>&#160;# &#1043;&#1076;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100;&#1089;&#1103; &#1092;&#1072;&#1081;&#1083;&#1099; &#1082;&#1101;&#1096;&#1072;. 1:2 - &#1091;&#1088;&#1086;&#1074;&#1077;&#1085;&#1100; &#1087;&#1086;&#1076;&#1087;&#1072;&#1087;&#1086;&#1082;. key_zone= - &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; &#1084;&#1080;&#1082;&#1088;&#1086;&#1082;&#1101;&#1096;&#1072; (&#1082;&#1072;&#1082; &#1084;&#1099; &#1073;&#1091;&#1076;&#1077;&#1084; &#1086;&#1073;&#1088;&#1072;&#1097;&#1072;&#1090;&#1100;&#1089;&#1103; &#1082; &#1085;&#1077;&#1084;&#1091; &#1087;&#1088;&#1080; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1074; &#1082;&#1086;&#1085;&#1090;&#1077;&#1082;&#1089;&#1090; &#1083;&#1086;&#1082;&#1077;&#1081;&#1096;&#1085;&#1072;). 10m - &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082;&#1101;&#1096; &#1073;&#1091;&#1076;&#1077;&#1090; &#1086;&#1089;&#1090;&#1072;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1072;&#1082;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084;. max_size - &#1084;&#1072;&#1082;&#1089;. &#1084;&#1077;&#1089;&#1090;&#1086; &#1076;&#1083;&#1103; &#1082;&#1101;&#1096;&#1072;
    </p>
    <p>
      &#160;&#160;&#160; <font color="#008000">fastcgi_cache_key &quot;$scheme$request_method$host$request_uri&quot;;</font>&#160;&#160;# &#1042; &#1082;&#1072;&#1082;&#1086;&#1084; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077; &#1073;&#1091;&#1076;&#1077;&#1084; &#1093;&#1088;&#1072;&#1085;&#1080;&#1090;&#1100; &#1082;&#1101;&#1096;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;set $no_cache 0;&#160; </font># &#1047;&#1072;&#1076;&#1072;&#1077;&#1084; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1091;&#1102; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102; =0. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1084;&#1099; &#1085;&#1080;&#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1077; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;if ($request_method = POST) { set $no_cache 1; }&#160; </font># &#1045;&#1089;&#1083;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090; &#1084;&#1077;&#1090;&#1086;&#1076; POST, &#1082;&#1101;&#1096; &#1085;&#1077; &#1080;&#1089;&#1087;.
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;if ($query_string != &quot;&quot;) { set $no_cache 1; }&#160; </font># &#1045;&#1089;&#1083;&#1080; &#1074; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1077; &#1087;&#1088;&#1080;&#1089;&#1091;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1082;&#1101;&#1096; &#1085;&#1077; &#1080;&#1089;&#1087;.
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;if ($request_uri ~* &quot;/wp-admin&quot;) { set $no_cache 1; } </font>&#160;# &#1045;&#1089;&#1083;&#1080; &#1074; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1077; &#1077;&#1089;&#1090;&#1100; wp-admin, &#1082;&#1101;&#1096; &#1085;&#1077; &#1080;&#1089;&#1087;. &#1040;&#1076;&#1084;&#1080;&#1085;&#1082;&#1091; wordpress &#1085;&#1080;&#1082;&#1086;&#1075;&#1076;&#1072; &#1085;&#1077; &#1085;&#1091;&#1078;&#1085;&#1086; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1090;&#1072;&#1084; &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1091;&#1085;&#1080;&#1082;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1086;&#1090;&#1085;&#1086;&#1089;&#1080;&#1090;&#1089;&#1103; &#1082; &#1082;&#1086;&#1085;&#1082;&#1088;&#1077;&#1090;&#1085;&#1086;&#1084;&#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1102;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;location ~ \.php$ { </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;fastcgi_cache_bypass $no_cache;&#160; </font># &#1054;&#1073;&#1077; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1080;&#1074;&#1099; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1102;&#1090;, &#1073;&#1091;&#1076;&#1077;&#1090; &#1083;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;&#160;&#160;fastcgi_no_cache $no_cache; </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;&#160;&#160;} </font>
    </p>
    <p>
      <font color="#008000">&#160;&#160;} </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Кэширование файлов" ID="ID_937516842" CREATED="1550848315498" MODIFIED="1657814328274"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Кэширование файлов браузером клиента </b>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">vim /etc/nginx/nginx.conf</font>
    </p>
    <p>
      <font color="#008000">server </font>
    </p>
    <p>
      <font color="#008000">{ </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;location ~*&nbsp;&nbsp;.(jpg|jpeg|png|gif|ico|css|js|eot|svg|ttf|woff|pdf)$ </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;{ </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;expires 365d; </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;} </font>
    </p>
    <p>
      <font color="#008000">} </font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">http { </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;server { </font>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;location ~* \.(css|js|jpg|png|gif)$ { </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;access_log off; </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;expires 1M; </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;add_header Pragma public; </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;add_header Cache-Control public; </font></b>
    </p>
    <p>
      <b><font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;add_header Vary Accept-Encoding;</font></b>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;&nbsp;&nbsp;} </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;} </font>
    </p>
    <p>
      <font color="#008000">}</font>
    </p>
  </body>
</html></richcontent>
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
</node>
<node TEXT="Настройка воркеров" ID="ID_1366486452" CREATED="1550831399473" MODIFIED="1551249438368"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#008000"><b>worker_processes auto;</b></font>&#160;&#160;# &#1052;&#1099; &#1089;&#1086;&#1086;&#1073;&#1097;&#1072;&#1077;&#1084; Nginx &#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1074; &#1080;&#1083;&#1080; &#1101;&#1082;&#1079;&#1077;&#1084;&#1087;&#1083;&#1103;&#1088;&#1086;&#1074; &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1090;&#1100;. <b>auto</b>&#160; - &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1091; &#1085;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; &#1103;&#1076;&#1088;&#1086;
    </p>
    <ul>
      <li>
        &#1053;&#1077;&#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1073;&#1086;&#1083;&#1077;&#1077; &#1086;&#1076;&#1085;&#1086;&#1075;&#1086; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1085;&#1072; &#1103;&#1076;&#1088;&#1086; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1072; (&#1080;&#1079;-&#1079;&#1072; &#1072;&#1089;&#1080;&#1085;&#1093;&#1088;&#1086;&#1085;&#1085;&#1086;&#1075;&#1086; &#1076;&#1080;&#1079;&#1072;&#1081;&#1085;&#1072; Nginx)
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1079;&#1072;&#1087;&#1091;&#1089;&#1090;&#1080;&#1090;&#1100; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1074;, &#1095;&#1077;&#1084; &#1095;&#1080;&#1089;&#1083;&#1086; &#1103;&#1076;&#1077;&#1088;, &#1090;&#1086; Nginx &#1085;&#1077; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; &#1086;&#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1077; &#1103;&#1076;&#1088;&#1072;
      </li>
    </ul>
  </body>
</html></richcontent>
