      <span style="color: #008000;">http { </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;server {&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;</span>&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;# a1.com
