<node ID="ID_1345607531" CREATED="1551118604900" MODIFIED="1728497173198"><richcontent TYPE="NODE">

<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#000000">&#1055;&#1088;&#1080;&#1084;&#1077;&#1088;. &#1058;&#1072;&#1082; &#1089;&#1077;&#1073;&#1077;</font>
    </p>
  </body>
</html>
</richcontent>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="color: #0000c0;">apt update</span>&#xa0;&#xa0;# Обновить список пакетов
    </p>
    <p>
      <span style="color: #0000c0;">apt install apache2 libapache2-mod-rpaf</span>&#xa0;&#xa0;# Ставим Apache2 и опционально модуль для работы с заголовками (X-Forwarded-For)
    </p>
    <p>
      <span style="color: #0000c0;">netstat -plunt</span>&#xa0;&#xa0;# Apache2 слушает на 80 порту
    </p>
    <p>
      <span style="color: #0000c0;">apt install curl</span>&#xa0;&#xa0;# Установить curl для просмотра ответов сервера
    </p>
    <p>
      <span style="color: #0000c0;">curl -I http://localhost/</span>&#xa0;&#xa0;# Посмотреть ответ веб-сервера
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/apache2/ports.conf</span>&#xa0;&#xa0;# Настроить чтобы Apache слушал другой порт
    </p>
    <p>
      <span style="color: #008000;">NameVirtualHost *:8000 </span>
    </p>
    <p>
      <span style="color: #008000;">Listen 8000 </span>
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/apache2/sites-available/default</span>&#xa0;&#xa0;# Изменить настройки сайта
    </p>
    <p>
      <span style="color: #008000;">&lt;VirtualHost 127.0.0.1:8000&gt; </span>
    </p>
    <p>
      <span style="color: #0000c0;">service apache2 restart</span>&#xa0;# Перезапустить веб-сервер Apache
    </p>
    <p>
      <span style="color: #0000c0;">netstat -plunt</span>&#xa0;&#xa0;# Проверить изменения. =&gt; Вместо 80 слушается 8000
    </p>
    <p>
      <span style="color: #0000c0;">apt install nginx</span>&#xa0;&#xa0;# Устновить nginx
    </p>
    <p>
      <span style="color: #0000c0;">service nginx start</span>&#xa0;&#xa0;# Запустить nginx
    </p>
    <p>
      <span style="color: #0000c0;">netstat -plunt</span>&#xa0;&#xa0;# Проверить изменения. =&gt; 80 слушается nginx
    </p>
    <p>
      <span style="color: #0000c0;">curl -I http://localhost/</span>&#xa0;&#xa0;# Посмотреть ответ веб-сервера. =&gt; nginx
    </p>
    <p>
      <span style="color: #0000c0;">cat /etc/nginx/proxy_params</span>&#xa0;&#xa0;# файл содержит настр. для работы в режиме прокси
    </p>
    <p>
      <span style="color: #0000c0;">vim /etc/nginx/sites-available/default </span>&#xa0;# Изменить настройки сайта
    </p>
    <p>
      <span style="color: #008000;">server { </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;location / { </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;proxy_pass http://localhost:8000/; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;proxy_redirect off; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;&#xa0;&#xa0;include /etc/nginx/proxy_params; </span>
    </p>
    <p>
      <span style="color: #008000;">&#xa0;&#xa0;} </span>
    </p>
    <p>
      <span style="color: #008000;">} </span>
    </p>
    <p>
      <span style="color: #0000c0;">service nginx restart</span>&#xa0;&#xa0;# Перезапуск nginx
    </p>
    <p>
      
    </p>
    <p>
      <b>Проверка</b>
    </p>
    <p>
      В браузере видим страницу Apache, но <span style="color: #0000c0;">curl -I http://localhost/</span>&#xa0;&#xa0;показывает nginx
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Редирект" ID="ID_282521903" CREATED="1657814407214" MODIFIED="1739363508427">
