    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.save_comments (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 1) &#8212; &#1077;&#1089;&#1083;&#1080; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1086;, &#1074;&#1089;&#1077; &#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1080; PHPDoc &#1073;&#1091;&#1076;&#1091;&#1090; &#1091;&#1076;&#1072;&#1083;&#1077;&#1085;&#1099; &#1080;&#1079; &#1082;&#1086;&#1076;&#1072; &#1089; &#1094;&#1077;&#1083;&#1100;&#1102; &#1091;&#1084;&#1077;&#1085;&#1100;&#1096;&#1077;&#1085;&#1080;&#1103; &#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072; &#1086;&#1087;&#1090;&#1080;&#1084;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1076;&#1072;. &#1053;&#1077; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1091;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.load_comments (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 1) &#8212; &#1077;&#1089;&#1083;&#1080; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1086;, &#1090;&#1086; &#1082;&#1086;&#1084;&#1084;&#1077;&#1085;&#1090;&#1072;&#1088;&#1080;&#1080; PHPDoc &#1085;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1080;&#1079; &#1086;&#1073;&#1097;&#1077;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.fast_shutdown (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 0) &#8212; &#1077;&#1089;&#1083;&#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1086;, &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100; &#1073;&#1099;&#1089;&#1090;&#1088;&#1099;&#1093; &#1074;&#1099;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1081; &#1076;&#1083;&#1103; &#1086;&#1087;&#1090;&#1080;&#1084;&#1080;&#1079;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1082;&#1086;&#1076;&#1072;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.enable_file_override (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 0) &#8212; &#1087;&#1088;&#1080; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1080; OPcache &#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1090;&#1100; &#1085;&#1072;&#1083;&#1080;&#1095;&#1080;&#1077; &#1079;&#1072;&#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072; &#1087;&#1088;&#1080; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072;&#1093; file_exists(), is_file() &#1080; is_readable().
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.optimization_level (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 0xffffffff) &#8212; &#1073;&#1080;&#1090;&#1086;&#1074;&#1072;&#1103; &#1084;&#1072;&#1089;&#1082;&#1072;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1082;&#1072;&#1078;&#1076;&#1099;&#1081; &#1073;&#1080;&#1090; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1080;&#1083;&#1080; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1080;&#1077; &#1087;&#1088;&#1086;&#1093;&#1086;&#1076;&#1099; OPcache.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.inherited_hack (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 1) &#8212; &#1074;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1101;&#1090;&#1086;&#1075;&#1086; &#1093;&#1072;&#1082;&#1072; &#1087;&#1088;&#1080; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;&#1093; &#1074;&#1080;&#1076;&#1072; can't redeclare class. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086;&#1089;&#1090;&#1100; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1072;, &#1090;.&#1077; &#1086;&#1087;&#1090;&#1080;&#1084;&#1080;&#1079;&#1072;&#1094;&#1080;&#1103; &#1072;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1072;. &#1042; PHP-5.3+ &#1101;&#1090;&#1086;&#1090; &#1093;&#1072;&#1082; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.dups_fix (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 0) &#8212; &#1074;&#1082;&#1083;&#1102;&#1095;&#1072;&#1081;&#1090;&#1077; &#1087;&#1088;&#1080; &#1087;&#1086;&#1103;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082; &#1074;&#1080;&#1076;&#1072; Can't redeclare class.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.blacklist_filename &#8212; &#1084;&#1077;&#1089;&#1090;&#1086;&#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1077; &#1089;&#1087;&#1080;&#1089;&#1082;&#1072; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;, &#1082; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1079;&#1072;&#1087;&#1088;&#1077;&#1097;&#1077;&#1085; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1076;&#1083;&#1103; OPcache (&#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1084;&#1072;&#1089;&#1082;&#1080;). &#1050;&#1072;&#1078;&#1076;&#1099;&#1081; &#1090;&#1072;&#1082;&#1086;&#1081; &#1092;&#1072;&#1081;&#1083; &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1090;&#1077;&#1082;&#1089;&#1090;&#1086;&#1074;&#1099;&#1084; &#1092;&#1072;&#1081;&#1083;&#1086;&#1084;, &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084; &#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1089;&#1103; &#1080;&#1084;&#1077;&#1085;&#1072; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1085;&#1077; &#1090;&#1088;&#1077;&#1073;&#1091;&#1077;&#1090;&#1089;&#1103; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1088;&#1072;&#1079;&#1084;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077; &#1080;&#1084;&#1077;&#1085;&#1080; &#1082;&#1072;&#1078;&#1076;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072; &#1089; &#1086;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1086;&#1082;&#1080;. &#1048;&#1084;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072; &#1084;&#1086;&#1078;&#1077;&#1090; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1085;&#1099;&#1081; &#1087;&#1091;&#1090;&#1100;, &#1083;&#1080;&#1073;&#1086; &#1087;&#1088;&#1077;&#1092;&#1080;&#1082;&#1089;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.max_file_size (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 0) &#8212; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1077;&#1090; &#1080;&#1089;&#1082;&#1083;&#1102;&#1095;&#1072;&#1090;&#1100; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1080;&#1079; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1082;&#1101;&#1096;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1074;&#1089;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.consistency_checks (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 0) &#8212; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1090;&#1100; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1091;&#1102; &#1089;&#1091;&#1084;&#1084;&#1091; &#1082;&#1101;&#1096;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; N-&#1086;&#1077; &#1082;&#1086;&#1083;&#1080;&#1095;&#1077;&#1089;&#1090;&#1074;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#1080;&#1084;&#1077;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; 0, &#1095;&#1090;&#1086; &#1086;&#1090;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1080;. &#1055;&#1086;&#1076;&#1089;&#1095;&#1077;&#1090; &#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1100;&#1085;&#1086;&#1081; &#1089;&#1091;&#1084;&#1084;&#1099; &#1089;&#1085;&#1080;&#1078;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.force_restart_timeout (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 180) &#8212; &#1074;&#1088;&#1077;&#1084;&#1103; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1103; (&#1074; &#1089;&#1077;&#1082;&#1091;&#1085;&#1076;&#1072;&#1093;) &#1087;&#1077;&#1088;&#1077;&#1076; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1086;&#1081; &#1074; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1086;&#1089;&#1090;&#1080; &#1082;&#1101;&#1096;&#1072;. &#1055;&#1086;&#1089;&#1083;&#1077; &#1080;&#1089;&#1090;&#1077;&#1095;&#1077;&#1085;&#1080;&#1077; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1086;&#1078;&#1080;&#1076;&#1072;&#1085;&#1080;&#1103; OPcache &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1077;&#1090; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1099;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1073;&#1099;&#1083;&#1080; &#1074;&#1089;&#1077; &#1101;&#1090;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1079;&#1072;&#1073;&#1083;&#1086;&#1082;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1099;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.error_log &#8212; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080; &#1084;&#1077;&#1089;&#1090;&#1086;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1083;&#1086;&#1075;&#1072; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082; OPcache. &#1055;&#1088;&#1080; &#1087;&#1091;&#1089;&#1090;&#1086;&#1084; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1080; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; &#1074;&#1099;&#1074;&#1086;&#1076;&#1103;&#1090;&#1089;&#1103; &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.log_verbosity_level (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 1) &#8212; &#1074;&#1089;&#1077; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; OPcache &#1086;&#1090;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1074; &#1083;&#1086;&#1075;-&#1092;&#1072;&#1081;&#1083; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088;&#1072;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1083;&#1086;&#1075;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082;&#1088;&#1080;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; (0) &#1080; &#1086;&#1073;&#1099;&#1095;&#1085;&#1099;&#1077; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; (1). &#1044;&#1086;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1084;&#1086;&#1078;&#1085;&#1086; &#1074;&#1082;&#1083;&#1102;&#1095;&#1080;&#1090;&#1100; &#1087;&#1088;&#1077;&#1076;&#1091;&#1087;&#1088;&#1077;&#1078;&#1076;&#1077;&#1085;&#1080;&#1103; (2), &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1086;&#1085;&#1085;&#1099;&#1077; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1103; (3) &#1080;&#1083;&#1080; &#1086;&#1090;&#1083;&#1072;&#1076;&#1086;&#1095;&#1085;&#1091;&#1102; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; (4).
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.preferred_memory_model &#8212; &#1087;&#1088;&#1077;&#1076;&#1087;&#1086;&#1095;&#1080;&#1090;&#1072;&#1077;&#1084;&#1072;&#1103; &#1084;&#1086;&#1076;&#1077;&#1083;&#1100; &#1086;&#1073;&#1097;&#1077;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.protect_memory (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; 0) &#8212; &#1079;&#1072;&#1097;&#1080;&#1090;&#1072; &#1086;&#1073;&#1097;&#1077;&#1081; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1086;&#1090; &#1085;&#1077;&#1089;&#1072;&#1085;&#1082;&#1094;&#1080;&#1086;&#1085;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1086;&#1081; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103;.
    </p>
    <p>
      &#160;&#160;&#160;&#160;opcache.restrict_api (&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1087;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1091;&#1089;&#1090;&#1072;&#1103; &#1089;&#1090;&#1088;&#1086;&#1082;&#1072;) &#8212; &#1088;&#1072;&#1079;&#1088;&#1077;&#1096;&#1077;&#1085;&#1080;&#1077; &#1074;&#1099;&#1079;&#1086;&#1074;&#1072; API-&#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1081; OPcache &#1080;&#1079; PHP-&#1089;&#1082;&#1088;&#1080;&#1087;&#1090;&#1086;&#1074;, &#1087;&#1091;&#1090;&#1100; &#1082; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1077;&#1090;&#1089;&#1103; &#1090;&#1077;&#1084;, &#1095;&#1090;&#1086; &#1091;&#1082;&#1072;&#1079;&#1072;&#1085;&#1086; &#1074; &#1089;&#1090;&#1088;&#1086;&#1082;&#1077;. &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1091;&#1089;&#1090;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1086;&#1079;&#1085;&#1072;&#1095;&#1072;&#1077;&#1090; &#1079;&#1072;&#1087;&#1088;&#1077;&#1090; &#1085;&#1072; &#1074;&#1089;&#1077;.
    </p>
  </body>
</html></richcontent>
</node>
</node>
</node>
</node>
<node TEXT="Web-proxy" FOLDED="true" ID="ID_388150524" CREATED="1662328700250" MODIFIED="1743777915728"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1610922364">Nginx</a>&#xa0; <a href="#ID_944749960">proxy</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>Web-proxy</b>&#xa0;получает НТТР-запросы от клиентов, (необязательно) выполняющий определенную&#xa0;&#xa0;обработку и передающий запросы в конечный пункт назначения.
    </p>
    <p>
      
    </p>
    <p>
      <b>Типы</b>
    </p>
    <ul>
      <li>
        балансировщики нагрузки
      </li>
      <li>
        брандмауэры web приложений
      </li>
      <li>
        серверы кэшей
      </li>
      <li>
        web-сервер также действует как прокси-сервер, если он пере­дает запросы серверам приложений
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="WAF (Web Арр Firewall)" ID="ID_1987264243" CREATED="1662328756461" MODIFIED="1662328775742"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      ModSecurity - firewall (WAF (Web Арр Firewall))
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Балансировщик нагрузки" FOLDED="true" ID="ID_1732335400" CREATED="1662327752897" MODIFIED="1748335288924"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1610922364">Nginx</a>&#xa0;&#xa0;<a href="#ID_342338330">HAProxy</a>&#xa0;&#xa0;<a href="#ID_1051566959">IPVS</a>&#xa0; <a href="#ID_944749960">Прокси (инфраструктура)</a>&#xa0;&#xa0;<a href="#ID_1140070626">iptables</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>Балансировщик нагрузки</b>&#xa0;- особый тип прокси-сервера. Распределяет входящие запросы среди множества нисходящих веб-серверов, также контролируют состояние этих серверов, чтобы обеспечить своевременную обработку клиентских запросов.
    </p>
    <p>
      
    </p>
    <ul>
      <li>
        дает возможность обновлять ПО, операционную систему или конфигурацию без простоя
      </li>
      <li>
        снижается уязвимость от перегрузок и преднамеренных атак
      </li>
      <li>
        не обрабатывают запросы, а направляют их в другие системы
      </li>
      <li>
        работают парами, чтобы самим не стать единственной точкой отказа
      </li>
      <li>
        обычно работают на 4-м уровне модели OSI (транспортный), перенаправляют запросы с учетом только IР-адреса и номера порта запроса
      </li>
      <li>
        ELB (Elastic Load Balancer) от AWS (облако)
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="HAProxy" FOLDED="true" ID="ID_342338330" CREATED="1574839780305" MODIFIED="1747901608748"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1610922364">nginx</a><b>&#xa0;</b>&#xa0;<a href="#ID_1051566959">IPVS</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <b>HAProxy (High Availability Proxy)</b>&#xa0;- серверное ПО для обеспечения высокой доступности и балансировки нагрузки для TCP и HTTP-приложений, посредством распределения входящих запросов на несколько обслуживающих серверов
    </p>
    <ul>
      <li>
        требуется перезапуск для обновления конфигов
      </li>
      <li>
        /etc/haproxy/haproxy.cfg - конф.файл
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">HATop</span>&#xa0;- интерактивный клиент для мониторинга HAProxy. Удобный интерфейсдля отображения статистики и управления экземплярами HAProxy в реальном времени
    </p>
    <p>
      
    </p>
    <p>
      <span style="color: #0000c0;">apt install haproxy </span>
    </p>
    <p>
      <span style="color: #0000c0;">apt install hatop</span>
    </p>
    <ol>
      <li>
        Активировать сокет статистики в конфигурации HAProxy
      </li>
      <li>
        <span style="color: #0000c0;">hatop -s /var/run/haproxy/haproxy.sock</span>&#xa0;&#xa0;# Запустить HATop с указанием пути к сокету
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      --------------------------------------------------
    </p>
    <p>
      <span style="color: #0000c0;">hatop -t</span>&#xa0;&#xa0;# Топ обращений к сайтам
    </p>
    <p>
      <span style="color: #0000c0;">hatop -T0 -d имя_домена</span>&#xa0;&#xa0;&#xa0;# Текущая статистика обращений к домену
    </p>
    <p>
      <span style="color: #0000c0;">hatop -h</span>&#xa0;&#xa0;# хелп по команде и возможных вариантах получения статистики
    </p>
  </body>
</html></richcontent>
<node TEXT="Цикл" ID="ID_656888512" CREATED="1663861076244" MODIFIED="1663864173385"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        прослушивать порт 80 и распределять запросы с помощью циклического режима между двумя веб-серверами web1 и web 2, запущенными на порту 8080
      </li>
      <li>
        Директива <b>frontend</b>&nbsp;определяет, как программа HAProxy будет обрабатывать запросы от клиентов: какие адреса и порты использовать, какие типы трафика обслуживать и другие ориентированные на клиента моменты
      </li>
      <li>
        Директива <b>backend</b>&nbsp;настраивает набор серверов, которые фактически обрабатывают запросы
      </li>
      <li>
        В одной конфигурации могут существовать несколько пар директив frontend / backend, позволяя одному балансировщику нагрузки HAProxy обслуживать несколько сайтов.
      </li>
      <li>
        Настройки timeout позвол яют осуществлять тщательн ый контрол ь над тем , как долго система должна ожидать при попытке открытия нового соединения с сервером и как долго нужно держать соединения открытыми после их установки. Точная настройка этих значений важна для загруженных веб-серверов. В локальных сетях значение timeout connect может быть довольно низким (500 мс или меньше), потому что новые соединения устанавливаются очень быстро.
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <font color="#008000">global </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;daemon </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;maxconn 5000 </font>
    </p>
    <p>
      <font color="#008000">defaults </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;mode http </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;timeout connect 5000&nbsp;&nbsp;# Миллисекунд </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;timeout client 10000 </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;timeout server 10000 </font>
    </p>
    <p>
      <font color="#008000">frontend http-in </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;bind *:80 </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;default_backend webservers </font>
    </p>
    <p>
      <font color="#008000">backend webservers </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;balance roundroЬin </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;server web1 10.0.0.10:8080 </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;server web2 10.0.0.11:8080 </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Проверка работоспособности" ID="ID_1274749385" CREATED="1664798164036" MODIFIED="1664798465778"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      Функция проверки состояния HAProxy выполняет регулярные НТТР-запросы для определения работоспособности каждого сервера. Пока серверы отвечают кодом ответа НТТР 200, они считаются в работоспособном состоянии и продолжают получать запросы от балансировщика нагрузки.
    </p>
    <p>
      Есл и сервер не проходит проверку работоспособности (возвращая что-либо, кроме кода состояния 200), то программа HAProxy удаляет его из пула. Однако HAProxy продолжает выполнять проверки работоспособности этого сервера. Если он снова начнет отвечать успешно, то программа HAProxy вернет его в пул.
    </p>
    <p>
      
    </p>
    <p>
      HAProxy выполняет запрос GET для каталога / на каждом сервере каждые 30 с
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">backend webservers </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;balance roundrobin </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;option httpchk GET / </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;server wеb1 10.0.0.10:8080 check inter 30000 </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;server web2 10.0.0.11:8080 check inter 30000</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="Статистика сервера" ID="ID_1189237094" CREATED="1663864174800" MODIFIED="1664802631784"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        web интерфейс, отображающий статистику сервера с возможностью включения и отключения каждого сервера в пуле
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      listen stats :8000
    </p>
    <p>
      &nbsp;&nbsp;mode http
    </p>
    <p>
      &nbsp;&nbsp;stats enable
    </p>
    <p>
      &nbsp;&nbsp;stats hide-version
    </p>
    <p>
      &nbsp;&nbsp;stats realm HAProxy\ Statistics
    </p>
    <p>
      &nbsp;&nbsp;stats uri /
    </p>
    <p>
      &nbsp;&nbsp;stats auth myuser:mypass
    </p>
    <p>
      &nbsp;&nbsp;stats admin if TRUE
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="cookies, липкие сессии" ID="ID_1952091948" CREATED="1664798700948" MODIFIED="1664803638703"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      HAProxy поддерживает параметры cookie SERVERNAМE для отслеживания сервера, с которым работает клиент.
    </p>
    <p>
      Ключевое слово <b>secure</b>&nbsp;указывает, что значение cookie следует отправлять только через ТLS-соединения
    </p>
    <p>
      Ключевое слово <b>httponly</b>&nbsp;сообщает браузерам использовать cooki e только через протокол НТТР.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">backend webservers </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;balance roundrobin </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;option httpchk GET / </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;server wеb1 10.0.0.10:8080 check inter 30000 </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;server web2 10.0.0.11:8080 check inter 30000</font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="TLS" ID="ID_1143770185" CREATED="1664802633297" MODIFIED="1664806312387"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      
    </p>
    <p>
      Поскольку HAProxy прерывает соединение TLS с клиентами, необходимо добавить соответствующие параметры в блок конфигурации интерфейса.
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">frontend https-in </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;bind *:443 ssl crt /etc/ssl/private/admin.com.pem </font>
    </p>
    <p>
      <font color="#008000">&nbsp;&nbsp;default backend webservers</font>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      Веб-серверы Apache и NGINX требуют, чтобы закрытый ключ и сертификат хранились в отдельных файлах в формате РЕМ, но НАРгоху ожидает, что оба компонента будут присутствовать в одном файле. Можно просто объединить отдельные файлы для создания составного файла:
    </p>
    <p>
      <font color="#0000c0">cat /etc/ssl/{private/admin.com.key,certs/admin.com.crt} &gt; /etc/ssl/private/admin.com.pem </font>
    </p>
    <p>
      <font color="#0000c0">chmod 400 /etc/ssl/private/admin.com.pem </font>
    </p>
    <p>
      
    </p>
    <p>
      Поскольку закрытый ключ является частью составного файла, убедитесь, что файл принадлежит пользователю root и не доступен для чтения другим пользователем. (Если вы не запускаете HAProxy от имени root, поскольку вам не нужно получать доступ к каким-либо привилегированным портам, убедитесь, что право собственности на файл ключа совпадает с идентификатором, под которым запускается HAProxy.)
    </p>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="IPVS" FOLDED="true" ID="ID_1051566959" CREATED="1747901451198" MODIFIED="1747903792185"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_916112796">kube-proxy</a>&#xa0; <a href="#ID_1610922364">Nginx</a>&#xa0;&#xa0;<a href="#ID_342338330">HAProxy</a>&#xa0; <a href="#ID_1732335400">Балансировщик нагрузки</a>&#xa0; <a href="#ID_944749960">Прокси (инфраструктура)</a>&#xa0;
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">IPVS (IP Virtual Server)</span>&#xa0;- технология балансировки нагрузки на уровне ядра Linux, разработанная как часть проекта Linux Virtual Server (LVS). Она позволяет распределять входящий сетевой трафик между несколькими серверами, создавая виртуальный сервер с одним IP-адресом.
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Используется:</span>
    </p>
    <ul>
      <li>
        Кластеры веб-серверов
      </li>
      <li>
        Балансировка в Kubernetes (режим kube-proxy=ipvs)
      </li>
      <li>
        Высоконагруженные системы (CDN, облачные платформы)
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Основные возможности IPVS</span>
    </p>
    <ol>
      <li>
        <span style="font-weight: bold;">Балансировка нагрузки</span>&#xa0;- распределение запросов между серверами (реальными серверами, RS) для повышения отказоустойчивости и производительности
      </li>
      <li>
        <span style="font-weight: bold;">Поддержка нескольких протоколов</span>&#xa0;- TCP, UDP, SCTP
      </li>
      <li>
        <span style="font-weight: bold;">Разные алгоритмы балансировки:</span>

        <ul>
          <li>
            Round Robin (RR) - циклическое распределение запросов
          </li>
          <li>
            Least Connections (LC) - отправка трафика на сервер с наименьшим числом активных соединений
          </li>
          <li>
            Weighted Round Robin (WRR) - Round Robin с учётом весов серверов
          </li>
          <li>
            Weighted Least Connections (WLC) - Least Connections с весами
          </li>
          <li>
            Source Hashing (SH) - привязка клиента к серверу по хешу IP
          </li>
          <li>
            Destination Hashing (DH) - балансировка на основе адреса назначения
          </li>
          <li>
            Shortest Expected Delay (SED) - выбор сервера с минимальной ожидаемой задержкой
          </li>
        </ul>
      </li>
      <li>
        <span style="font-weight: bold;">Несколько методов маршрутизации:</span>

        <ul>
          <li>
            NAT (Masquerading) - подмена адресов (источника/назначения)
          </li>
          <li>
            Direct Routing (DR) - пакеты идут напрямую к серверу, ответ - клиенту
          </li>
          <li>
            Tunneling (IPIP) - инкапсуляция пакетов для передачи через сеть
          </li>
        </ul>
      </li>
      <li>
        <span style="font-weight: bold;">Поддержка IPv6</span>
      </li>
      <li>
        <span style="font-weight: bold;">Интеграция с iptables</span>&#xa0;и <span style="font-weight: bold;">firewalld</span>
      </li>
      <li>
        <span style="font-weight: bold;">Высокая производительность</span>&#xa0;- работает на уровне ядра, минимизируя накладные расходы
      </li>
      <li>
        Нет встроенной проверки здоровья серверов (можно комбинировать с keepalived)
      </li>
    </ol>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Архитектура LVS (Linux Virtual Server)</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: normal;">Director (балансировщик)&#xa0;- сервер с IPVS, принимающий запросы </span>
      </li>
      <li>
        <span style="font-weight: normal;">Real Servers (RS)&#xa0;- серверы, обрабатывающие трафик </span>
      </li>
      <li>
        <span style="font-weight: normal;">Virtual IP (VIP)&#xa0;- общий IP-адрес, на который приходят запросы</span>
      </li>
    </ul>
  </body>
</html></richcontent>
<node TEXT="Настройка" ID="ID_771469591" CREATED="1747903391585" MODIFIED="1748503262165"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">1. Установка (в Linux):</span>
    </p>
    <p>
      <span style="color: #0000c0;">apt install ipvsadm</span>&#xa0;&#xa0;# Debian/Ubuntu
    </p>
    <p>
      <span style="color: #0000c0;">yum install ipvsadm</span>&#xa0;&#xa0;# CentOS/RHEL
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Пример добавления 1. Балансировщик нагрузки wlc</span>
    </p>
    <p>
      # Добавление виртуального сервера (например, для TCP-порта 80):
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm -A -t 192.168.1.100:80 -s wlc </span>
    </p>
    <p>
      #&#xa0;&#xa0;Добавление реальных серверов:
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm -a -t 192.168.1.100:80 -r 192.168.1.10:80 -g -w 1</span>
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm -a -t 192.168.1.100:80 -r 192.168.1.11:80 -g -w 1</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">-A, -E, -D</span>&#xa0;- добавить, редактировать, удалить виртуальные сервисы
      </li>
      <li>
        <span style="font-weight: bold;">-a, -e, -d</span>&#xa0;- добавить, редактировать, удалить бэкенды на хосте
      </li>
      <li>
        <span style="font-weight: bold;">-s</span>&#xa0;- алгоритм балансировки (rr, lc, wrr и др.).
      </li>
      <li>
        <span style="font-weight: bold;">-t</span>&#xa0;- TCP-сервис (например, HTTP, HTTPS, SSH)
      </li>
      <li>
        <span style="font-weight: bold;">-u</span>&#xa0;- UDP-сервис (например, DNS, NTP, QUIC)
      </li>
      <li>
        <span style="font-weight: bold;">-r</span>&#xa0;- IP и порт бэкенда
      </li>
      <li>
        <span style="font-weight: bold;">-g</span>&#xa0;- Direct Routing, DR - более производительный, но требует настройки на бэкендах
      </li>
      <li>
        <span style="font-weight: bold;">-m</span>&#xa0;- маскарадинг (NAT-режим) - подходит, если бэкенды находятся в приватной сети
      </li>
      <li>
        <span style="font-weight: bold;">-i</span>&#xa0;- Tunneling, IPIP - для географически распределённых серверов.
      </li>
      <li>
        <span style="font-weight: bold;">-w</span>&#xa0;- вес сервера в балансировке. Если не указан, используется по умолчанию -w 1
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">Пример добавления 2. Балансировщик нагрузки RR</span>
    </p>
    <p>
      # Добавление виртуального сервиса (VIP)
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm -A -t 192.168.1.100:80 -s rr</span>
    </p>
    <p>
      # Добавление реальных серверов (бэкендов) с одинаковым весом
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm -a -t 192.168.1.100:80 -r 192.168.1.2:80 -m -w 1 </span>
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm -a -t 192.168.1.100:80 -r 192.168.1.3:80 -m -w 1</span>
    </p>
    <p>
      
    </p>
    <p>
      4. Проверка состояния:
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm -Ln </span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">Для сохранения Правил после перезагрузки</span>
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm-save &gt; /etc/ipvsadm.rules </span>
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm-restore &lt; /etc/ipvsadm.rules</span>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT="WLC - DR" ID="ID_1649693446" CREATED="1748336322402" MODIFIED="1748503680666"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <span style="font-weight: bold;">Балансировщик нагрузки с WLC и DR</span>
    </p>
    <ul>
      <li>
        <span style="font-weight: bold;">алгоритм wlc (Weighted Least-Connections)</span>
      </li>
      <li>
        <span style="font-weight: bold;">режим Direct Routing (-g)</span>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">1. Алгоритм wlc (Weighted Least-Connections)</span>&#xa0;- Распределяет запросы на сервер с наименьшим количеством активных соединений с учётом веса (-w). Если вес не указан, используется 1 по умолчанию
    </p>
    <p>
      У бэкендов
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm -a -t 192.168.1.100:80 -r 192.168.1.10:80 -g -w 1 </span>
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm -a -t 192.168.1.100:80 -r 192.168.1.11:80 -g -w 1</span>
    </p>
    <p>
      
    </p>
    <p>
      <span style="font-weight: bold;">2. Режим -g (Direct Routing, DR)</span>
    </p>
    <ul>
      <li>
        Запросы приходят на VIP (192.168.1.100), но ответы идут напрямую от бэкендов к клиенту (без NAT)
      </li>
      <li>
        Если не настроить DR на бэкендах - Балансировщик будет принимать запросы, но бэкенды не смогут отвечать клиентам
      </li>
      <li>
        Требования:

        <ul>
          <li>
            На бэкендах (192.168.1.10, 192.168.1.11) нужно:&#xa0;

            <ol>
              <li>
                Настроить тот же VIP на loopback-интерфейсе (например, lo:0)
              </li>
              <li>
                Запретить ответы от VIP через ARP (иначе возможны конфликты)
              </li>
            </ol>
          </li>
          <li>
            Пример настройки на бэкенде:<br/><span style="color: #0000c0;">ip addr add 192.168.1.100/32 dev lo</span><br color="#0000c0" style="color: #0000c0;"/><span style="color: #0000c0;">echo 1 &gt; /proc/sys/net/ipv4/conf/all/arp_ignore</span><br color="#0000c0" style="color: #0000c0;"/><span style="color: #0000c0;">echo 2 &gt; /proc/sys/net/ipv4/conf/all/arp_announce</span>
          </li>
        </ul>
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">3. Проверка конфигурации</span>
    </p>
    <p>
      <span style="color: #0000c0;">ipvsadm -Ln</span>&#xa0;&#xa0;# Ожидаемый вывод:
    </p>
    <p>
      <span style="font-family: Lucida Console;">TCP&#xa0;&#xa0;192.168.1.100:80 wlc </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">&#xa0;&#xa0;-&gt; 192.168.1.10:80&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Route&#xa0;&#xa0;&#xa0;1&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;0&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;0 </span>
    </p>
    <p>
      <span style="font-family: Lucida Console;">&#xa0;&#xa0;-&gt; 192.168.1.11:80&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;Route&#xa0;&#xa0;&#xa0;1&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;0&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;&#xa0;0</span>
    </p>
    <ul>
      <li>
        Режим -g отображается как Route
      </li>
    </ul>
    <p>
      <span style="font-weight: bold;">4. Альтернативы</span>
    </p>
    <ul>
      <li>
        Если DR (-g) сложно настроить, можно использовать NAT (-m)
      </li>
      <li>
