<node TEXT="wp-config.php" ID="ID_1321496075" CREATED="1588255991350" MODIFIED="1591025639790"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <b>/&lt;&#1076;&#1086;&#1084;&#1077;&#1085;&gt;/wp-config.php</b>&#160;&#1080;&#1083;&#1080; &#1074; &#1088;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1086;&#1081;
      </li>
      <li>
        <font color="#ff0000">&#1041;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1100;.</font>&#160;&#1055;&#1077;&#1088;&#1077;&#1084;&#1077;&#1089;&#1090;&#1080;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; <b>wp-config.php</b>&#160;&#1074; &#1088;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1081; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;&#160;&#1101;&#1090;&#1086; &#1089;&#1076;&#1077;&#1083;&#1072;&#1077;&#1090; &#1077;&#1075;&#1086; &#1085;&#1077;&#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1085;&#1099;&#1084; &#1080;&#1093; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;&#1072;
      </li>
      <li>
        <font color="#008000"><b>define( 'OPTION_NAME', '&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; ' );</b></font>
      </li>
      <li>
        <b>&#1056;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084; &#1076;&#1086; &#1092;&#1088;&#1072;&#1079;&#1099;:</b><br/>/* &#1069;&#1090;&#1086; &#1074;&#1089;&#1105;, &#1076;&#1072;&#1083;&#1100;&#1096;&#1077; &#1085;&#1077; &#1088;&#1077;&#1076;&#1072;&#1082;&#1090;&#1080;&#1088;&#1091;&#1077;&#1084;. &#1059;&#1089;&#1087;&#1077;&#1093;&#1086;&#1074;! */<br/>/* That's all,&#160;&#160;stop editing! &#160;Happy blogging.&#160;&#160;*/
      </li>
    </ul>
    <p>
      <font color="#008000">define( 'DB_COLLATE', '' );</font>&#160;&#1086;&#1073;&#1099;&#1095;&#1085;&#1086; &#1087;&#1091;&#1089;&#1090;&#1086;&#1081;. &#1045;&#1089;&#1083;&#1080; &#1085;&#1091;&#1078;&#1085;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1089;&#1086;&#1088;&#1090;&#1080;&#1088;&#1086;&#1074;&#1082;&#1091; &#1041;&#1044;, &#1090;&#1086; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; &#1089;&#1083;&#1077;&#1076;&#1091;&#1077;&#1090; &#1084;&#1077;&#1085;&#1103;&#1090;&#1100; &#1076;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1080; WP
    </p>
    <p>
      
    </p>
    <p>
      <font color="#ff0000">&#1041;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1100;. </font><font color="#0000c0">https://api.wordpress.org/secret-key/1.1/salt/</font>&#160;&#160;# &#1040;&#1074;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1072;&#1103; &#1075;&#1077;&#1085;&#1077;&#1088;&#1072;&#1094;&#1080;&#1103; &#1082;&#1083;&#1102;&#1095;&#1077;&#1081; &#1073;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1080;. &#1057;&#1077;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1077; &#1082;&#1083;&#1102;&#1095;&#1080; &#1088;&#1072;&#1089;&#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1099; &#1074; &#1076;&#1074;&#1091;&#1093; &#1084;&#1077;&#1089;&#1090;&#1072;&#1093;: &#1074; &#1073;&#1072;&#1079;&#1077; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080; &#1092;&#1072;&#1081;&#1083;&#1077; wp-config.php.
    </p>
    <p>
      . wp_salt() &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; &#1089;&#1077;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1081; &#1082;&#1083;&#1102;&#1095; (salt), &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1081; &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1093;&#1101;&#1096;. &#1042; &#1041;&#1044; &#1089;&#1077;&#1082;&#1088;&#1077;&#1090;&#1085;&#1099;&#1077; &#1082;&#1083;&#1102;&#1095;&#1080; &#1075;&#1077;&#1085;&#1077;&#1088;&#1080;&#1088;&#1091;&#1102;&#1090;&#1089;&#1103; &#1089;&#1083;&#1091;&#1095;&#1072;&#1081;&#1085;&#1086;. &#1060;&#1091;&#1085;&#1082;&#1094;&#1080;&#1103; &#1086;&#1073;&#1098;&#1077;&#1076;&#1080;&#1085;&#1103;&#1077;&#1090; &#1082;&#1083;&#1102;&#1095;&#1080; &#1080;&#1079; &#1041;&#1044; &#1080; &#1080;&#1079; wp-config.php &#1080; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;
    </p>
    <p>
      <font color="#008000">define( 'AUTH_KEY',&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; 'A2mD+k-XkX9^Ba#!n&gt;jE?:d5rp7C|wv~*at1f&lt;^+.PT(nOX[y}I6Kvw!|1QS' ); </font>
    </p>
    <p>
      <font color="#008000">define( 'SECURE_AUTH_KEY',&#160; 'sQzk]^!5W^l59&lt;B6|fh?YK@q(crX-9Ey_swgtg{pCp+Y&amp;&gt;ds#2H+' ); </font>
    </p>
    <p>
      <font color="#008000">define( 'LOGGED_IN_KEY',&#160;&#160;&#160; 'omCo&lt;W&amp;{*hu7$6k_-N[|D+&gt;93Y@f[6|xK8r1:)FD=Z)/U_PZoI]h[+kH' ); </font>
    </p>
    <p>
      <font color="#008000">define( 'NONCE_KEY',&#160;&#160;&#160;&#160;&#160;&#160;&#160; '#i|I6BPnhFr-c,Ff~rJ:+6k[m?;.?C?+*Wf|Yt@COdH|SmHi!,/3E3}%(6kC' ); </font>
    </p>
    <p>
      <font color="#008000">define( 'AUTH_SALT',&#160;&#160;&#160;&#160;&#160;&#160;&#160; ')/#;i0G&lt;EZoy_~+hk?4$v01I1#c@wgu-+bA3L`b5/cGn*wA5yBSX+JLo ' ); </font>
