  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1574308262">.htaccess (Apache)</a>
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1099;&#1077; &#1089;&#1089;&#1099;&#1083;&#1082;&#1080;. </b>WP &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#160;<b>.htaccess</b>&#160;&#1087;&#1088;&#1080; &#1072;&#1082;&#1090;&#1080;&#1074;&#1072;&#1094;&#1080;&#1080; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1099;&#1093; &#1089;&#1089;&#1099;&#1083;&#1086;&#1082;&#160;&#1095;&#1077;&#1088;&#1077;&#1079; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100; WP. &#1042; .htaccess &#1076;&#1086;&#1073;&#1072;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103;:
    </p>
    <p>
      <font color="#008000">RewriteCond %{REQUEST_FILENAME} !-f </font>
    </p>
    <p>
      <font color="#008000">RewriteCond %{REQUEST_FILENAME} !-d </font>
    </p>
    <p>
      <font color="#008000">RewriteRule . /index.php [L]</font>&#160;&#160;#&#160;&#160;[L] - &#1054;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1086;&#1073;&#1088;&#1072;&#1073;&#1086;&#1090;&#1082;&#1091; &#1087;&#1086;&#1089;&#1083;&#1077; &#1076;&#1086;&#1089;&#1090;&#1080;&#1078;&#1077;&#1085;&#1080;&#1103; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1103; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1091;
    </p>
    <ol>
      <li>
        &#1055;&#1088;&#1072;&#1074;&#1080;&#1083;&#1072; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1102;&#1090; &#1089;&#1089;&#1099;&#1083;&#1082;&#1080; URL, &#1086;&#1090;&#1085;&#1086;&#1089;&#1103;&#1090;&#1089;&#1103; &#1083;&#1080; &#1086;&#1085;&#1080; &#1082; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1102;&#1097;&#1077;&#1084;&#1091; &#1092;&#1072;&#1081;&#1083;&#1091; &#1080;&#1083;&#1080; &#1082; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; &#1074; &#1080;&#1077;&#1088;&#1072;&#1088;&#1093;&#1080;&#1080; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074;&#1086;&#1081; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099;. &#1053;&#1086;&#1090;&#1072;&#1094;&#1080;&#1080; <b>!-f</b>&#160;&#1080; <b>!-d</b>&#160;&#1103;&#1074;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; &#1086;&#1090;&#1088;&#1080;&#1094;&#1072;&#1085;&#1080;&#1103;&#1084;&#1080;
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; URL &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1080;&#1084;&#1077;&#1102;&#1097;&#1077;&#1084;&#1091;&#1089;&#1103; &#1092;&#1072;&#1081;&#1083;&#1091;, &#1090;&#1086; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1085;&#1077; &#1076;&#1077;&#1083;&#1072;&#1077;&#1090;&#1089;&#1103; &#1080; &#1074;&#1077;&#1073;-&#1089;&#1077;&#1088;&#1074;&#1077;&#1088; &#1087;&#1088;&#1086;&#1073;&#1091;&#1077;&#1090; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1080;&#1090;&#1100; &#1101;&#1090;&#1086;&#1090; &#1092;&#1072;&#1081;&#1083; (&#1095;&#1090;&#1086;&#1073;&#1099; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1072;&#1097;&#1080;&#1081;&#1089;&#1103; &#1074; &#1085;&#1077;&#1084;&#160;&#1082;&#1086;&#1076; &#1056;&#1053;&#1056;)
      </li>
      <li>
        &#1045;&#1089;&#1083;&#1080; &#1087;&#1086; &#1087;&#1091;&#1090;&#1080;, &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1086;&#1084;&#1091;&#160;&#160;URL, &#1092;&#1072;&#1081;&#1083;&#1072; &#1080;&#1083;&#1080; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; &#1085;&#1077; &#1089;&#1091;&#1097;&#1077;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090;, &#1090;&#1086; &#1074;&#1093;&#1086;&#1076;&#1103;&#1097;&#1072;&#1103; &#1089;&#1089;&#1099;&#1083;&#1082;&#1072; &#1087;&#1088;&#1077;&#1086;&#1073;&#1088;&#1072;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; index.php, &#1079;&#1072;&#1087;&#1091;&#1089;&#1082;&#1072;&#1103; &#1103;&#1076;&#1088;&#1086; &#1089;&#1080;&#1089;&#1090;&#1077;&#1084;&#1099; WordPress.
      </li>
    </ol>
    <p>
      <b>&#1059;&#1074;&#1077;&#1083;&#1080;&#1095;&#1077;&#1085;&#1080;&#1077;&#160;&#1088;&#1072;&#1079;&#1084;&#1077;&#1088;&#1072;&#160;&#1087;&#1072;&#1084;&#1103;&#1090;&#1080;, &#1092;&#1072;&#1081;&#1083;&#1072;, &#1079;&#1072;&#1087;&#1080;&#1089;&#1080;</b>
    </p>
    <p>
      <font color="#008000">php_value memory_limit 64&#1052;</font>&#160;&#160;# &#1059;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1090;&#1100; &#1087;&#1072;&#1084;&#1103;&#1090;&#1100;.
    </p>
    <p>
      <font color="#008000">php_value upload_max_filesize 20&#1052;</font>&#160;&#160;# &#1059;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1090;&#1100; &#1084;&#1072;&#1082;&#1089;. &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1072;&#1077;&#1084;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072;
    </p>
    <p>
      <font color="#008000">php_value post_max_size 20M </font>&#160;&#160;# &#1059;&#1074;&#1077;&#1083;&#1080;&#1095;&#1080;&#1090;&#1100; &#1084;&#1072;&#1082;&#1089;. &#1088;&#1072;&#1079;&#1084;&#1077;&#1088; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1047;&#1072;&#1097;&#1080;&#1090;&#1072; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; wp-admin</b>. <font color="#ff0000">&#1041;&#1077;&#1079;&#1086;&#1087;&#1072;&#1089;&#1085;&#1086;&#1089;&#1090;&#1100;</font>. &#1047;&#1072;&#1087;&#1088;&#1077;&#1090;&#1080;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087; &#1082; &#1089;&#1072;&#1081;&#1090;&#1091; &#1087;&#1086;&#160;&#160;I&#1056;-&#1072;&#1076;&#1088;&#1077;&#1089;&#1091;
    </p>
    <p>
      <font color="#0000c0">vim /wordpress/wp-admi/.htaccess</font>
    </p>
    <p>
      <font color="#008000">AuthUserFile /dev/null </font>
    </p>
    <p>
      <font color="#008000">AuthGroupFile /dev/null </font>
    </p>
    <p>
      <font color="#008000">AuthName &quot;Access Control&quot; </font>
    </p>
    <p>
      <font color="#008000">AuthType Basic </font>
    </p>
    <p>
      <font color="#008000">order deny,allow </font>
    </p>
    <p>
      <font color="#008000">deny from all </font>
    </p>
    <p>
      # &#1044;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; IP-&#1072;&#1076;&#1088;&#1077;&#1089; &#1090;&#1086;&#1075;&#1086;, &#1082;&#1086;&#1084;&#1091; &#1093;&#1086;&#1090;&#1080;&#1084; &#1076;&#1072;&#1090;&#1100; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;
    </p>
    <p>
      <font color="#008000">allow from xxx.xxx.xxx.xxx</font>&#160;&#160;# &#1054;&#1076;&#1080;&#1085; &#1072;&#1076;&#1088;&#1077;&#1089;
    </p>
    <p>
      <font color="#008000">allow from xxx.xxx.xxx.</font><font color="#ff0000">*&#160;&#160;#&#160;&#160;(???&#1042;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1086; &#1085;&#1077; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;)</font>
    </p>
    <p>
      <font color="#008000">allow from xxx.xxx.xxx.110-230</font>&#160;&#160;# &#1044;&#1080;&#1072;&#1087;&#1072;&#1079;&#1086;&#1085;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1042;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082;.</b>&#160;&#1040;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1078;&#1091;&#1088;&#1085;&#1072;&#1083;&#1072;, &#1085;&#1086; &#1087;&#1086;&#1076;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1077; &#1082;&#1072;&#1082;&#1080;&#1093;-&#1083;&#1080;&#1073;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1086;&#1073; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;&#1093;
    </p>
    <p>
      1. &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; <b>php-errors.log</b>&#160;&#1074; &#1082;&#1086;&#1088;&#1085;&#1077;&#1074;&#1086;&#1081; &#1076;&#1080;&#1088;&#1077;&#1082;&#1090;&#1086;&#1088;&#1080;&#1080; WP
    </p>
    <p>
      2. <font color="#0000c0">vim .htaccess</font>
    </p>
    <p>
      <font color="#008000">php_flag display_startup_errors off </font>
    </p>
    <p>
      <font color="#008000">php_flag display_errors off </font>
    </p>
    <p>
      <font color="#008000">php_flag html_errors off </font>
    </p>
    <p>
      <font color="#008000">php_flag log_ernors on </font>
    </p>
    <p>
      <font color="#008000">php_value error_log /public_html/php-errors.log </font>
    </p>
  </body>
</html></richcontent>
</node>
<node TEXT=".maintenance (Обслуживание)" ID="ID_128640828" CREATED="1589431055867" MODIFIED="1591098836779"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>.maintenance</b>&#160;&#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; WP &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1072; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;. &#1069;&#1090;&#1086; &#1086;&#1073;&#1077;&#1088;&#1077;&#1075;&#1072;&#1077;&#1090;
    </p>
    <p>
      &#1087;&#1086;&#1089;&#1077;&#1090;&#1080;&#1090;&#1077;&#1083;&#1077;&#1081; &#1086;&#1090; &#1085;&#1072;&#1073;&#1083;&#1102;&#1076;&#1077;&#1085;&#1080;&#1103; &#1082;&#1072;&#1082;&#1080;&#1093;-&#1083;&#1080;&#1073;&#1086; &#1089;&#1086;&#1086;&#1073;&#1097;&#1077;&#1085;&#1080;&#1081; &#1086;&#1073; &#1086;&#1096;&#1080;&#1073;&#1082;&#1072;&#1093; &#1087;&#1088;&#1080; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1080; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1103;&#1076;&#1088;&#1072; WP
    </p>
    <ul>
      <li>
        .maintenance &#1089;&#1086;&#1079;&#1076;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1077;&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#160;&#160;&#1087;&#1077;&#1088;&#1077;&#1076; &#1090;&#1077;&#1084;, &#1082;&#1072;&#1082; WP &#1091;&#1089;&#1090;&#1072;&#1085;&#1072;&#1074;&#1083;&#1080;&#1074;&#1072;&#1077;&#1090; &#1085;&#1086;&#1074;&#1099;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1103;&#1076;&#1088;&#1072; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1086;&#1073;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;
      </li>
      <li>
        <p>
          <font color="#0000c0">vim /wordpress/.maintenance</font>&#160;&#160;# &#1055;&#1077;&#1088;&#1077;&#1074;&#1077;&#1089;&#1090;&#1080; &#1089;&#1072;&#1081;&#1090; &#1074; <b>&#1088;&#1077;&#1078;&#1080;&#1084; &#1090;&#1077;&#1093;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;</b>
        </p>
        <p>
          <font color="#008000">&lt;?php $upgrading = time();&#160;?&gt;</font>
        </p>
      </li>
      <li>
        &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1083;&#1100;&#1085;&#1086; &#1085;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; <b>&#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1091; &#1090;&#1077;&#1093;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1075;&#1086; &#1086;&#1073;&#1089;&#1083;&#1091;&#1078;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;</b>, &#1089;&#1086;&#1079;&#1076;&#1072;&#1074; &#1092;&#1072;&#1081;&#1083;<br/>/wordpress/wp-content/<b>maintenance.php</b>
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
</node>
<node TEXT="Административная панель" ID="ID_1268888843" CREATED="1584715173963" MODIFIED="1680778077315"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>Административная панель, консоль управления, &nbsp;«админка»</b>
    </p>
    <ul>
      <li>
        админка написана на jQuery
      </li>
    </ul>
    <p>
      <b>Вход через браузер</b>
    </p>
    <ul>
      <li>
        http://сайт/<b>wp-admin</b>
      </li>
      <li>
        http://сайт/<b>wp-login.php</b>
      </li>
    </ul>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      Поскольку изменить логин пользователя admin нельзя, то нужно<b>&nbsp;&nbsp;дать ему минимальные права</b>
    </p>
    <ol>
      <li>
        Создать пользователя с правами <b>Администратор</b>
      </li>
      <li>
        <b>Зайти</b>&nbsp;под этим пользователем
      </li>
      <li>
        Сменить права пользователя <b>admin</b>&nbsp;&nbsp;на <b>Подписчик</b>
      </li>
    </ol>
  </body>
</html></richcontent>
</node>
<node TEXT="База данных" FOLDED="true" ID="ID_579033626" CREATED="1590476174773" MODIFIED="1779697692915"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1886763756">MySQL</a>&#xa0;&#xa0;<a href="#ID_1445272606">SQL</a>
    </p>
    <ul>
      <li>
        MySQL
      </li>
      <li>
        Клиент для прямого доступа а MySQL - <a href="#ID_471343222">phpMyAdmin</a>
      </li>
      <li>
        При установке WP можно задать индивидуальный префикс таблицы БД. По умолчанию - wp_, желательно менять префикс по соображениям <span style="color: #ff0000;">безопасности</span>
      </li>
    </ul>
    <p>
      <b>Таблицы</b>
    </p>
    <ul>
      <li>
        wp_commentmeta - метаданные для комментариев
      </li>
      <li>
        wp_comments - комментарии в WP, которые подключаются к записи по ее ID
      </li>
      <li>
        wp_links - ссылки, добавленные через вкладку Ссылки
      </li>
      <li>
        wp_options -&#xa0;&#xa0;параметры сайта
      </li>
      <li>
        wp_postmeta - метаданные записи (произвольные поля)
      </li>
      <li>
        wp_posts - записи, страницы, медиафайлы и редакции. Обычно, самая большая таблица в БД
      </li>
      <li>
        wp_terms - элементы таксономии, определенные для веб-сайта
      </li>
      <li>
        wp_term_relationships - элементы таксономии с контентом. Отображает название метки или категории для соответствующей страницы или записи
      </li>
      <li>
        wp_term_taxonomy - определяет таксономию, к которой приписан каждый элемент
      </li>
      <li>
        wp_users - пользователи сайта (имя пользователя, пароль, электронный адрес)
      </li>
      <li>
        wp_usermeta — содержит метаданные пользователей
      </li>
    </ul>
    <p>
      <b>Запрос</b>
    </p>
    <p>
      <span style="color: #008000;">SELECT * FROM wp_posts</span>
    </p>
    <p>
      <span style="color: #008000;">WHERE post_type = 'post'</span>
    </p>
    <p>
      <span style="color: #008000;">AND post_status = 'publish'</span>
    </p>
    <p>
      <span style="color: #008000;">ORDER BY post_date DESC</span>
    </p>
  </body>
</html></richcontent>
<node TEXT="Поле post_status" ID="ID_157864623" CREATED="1590479229238" MODIFIED="1590479407692"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        <b>publish</b>&#160;- &#1086;&#1087;&#1091;&#1073;&#1083;&#1080;&#1082;&#1086;&#1074;&#1072;&#1085;&#1085;&#1072;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1080;&#1083;&#1080; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072;
      </li>
