      <li>
        <b>future</b>&#160;- &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1072;&#1103; &#1076;&#1086;&#1083;&#1078;&#1085;&#1072; &#1073;&#1099;&#1090;&#1100; &#1086;&#1087;&#1091;&#1073;&#1083;&#1080;&#1082;&#1086;&#1074;&#1072;&#1085;&#1072; &#1087;&#1086;&#1079;&#1078;&#1077; &#1074; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1080;&#1080; &#1089; &#1088;&#1072;&#1089;&#1087;&#1080;&#1089;&#1072;&#1085;&#1080;&#1077;&#1084;
      </li>
      <li>
        <b>draft</b>&#160;- &#1079;&#1072;&#1087;&#1080;&#1089;&#1100;-&#1095;&#1077;&#1088;&#1085;&#1086;&#1074;&#1080;&#1082;
      </li>
      <li>
        <b>trash</b>&#160;- &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090; &#1074; &#1082;&#1086;&#1088;&#1079;&#1080;&#1085;&#1077; &#1080; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1074;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Класс БД wpdb. Отображение ошибок" ID="ID_1711762264" CREATED="1590499021337" MODIFIED="1590500648191"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      &#1055;&#1086; &#1091;&#1084;&#1086;&#1083;&#1095;&#1072;&#1085;&#1080;&#1102; &#1087;&#1088;&#1080; &#1085;&#1077;&#1091;&#1076;&#1072;&#1095;&#1077; &#1089; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1089;&#1082;&#1080;&#1084;&#1080; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;&#1084;&#1080; &#1085;&#1077; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1077;&#1090;&#1089;&#1103; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086;. &#1050;&#1083;&#1072;&#1089;&#1089; wpdb &#1087;&#1088;&#1077;&#1076;&#1086;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1087;&#1086; &#1086;&#1090;&#1086;&#1073;&#1088;&#1072;&#1078;&#1077;&#1085;&#1080;&#1102; &#1086;&#1096;&#1080;&#1073;&#1086;&#1082; MySQL &#1085;&#1072; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">&lt;?php </font>
    </p>
    <p>
      <font color="#008000">$wpdb-&gt;show_errors(); </font>
    </p>
    <p>
      <font color="#008000">...&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160;&#160; </font>&#160;&#160;&#160;# &#1042;&#1099;&#1079;&#1086;&#1074; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;
    </p>
    <p>
      <font color="#008000">$wpdb-&gt;print_error(); </font>
    </p>
    <p>
      <font color="#008000">?&gt; </font>
    </p>
    <p>
      
    </p>
    <p>
      <font color="#008000">$wpdb-&gt;hide_errors();</font>&#160;&#160;# &#1057;&#1082;&#1088;&#1099;&#1090;&#1100; &#1074;&#1089;&#1077; &#1086;&#1096;&#1080;&#1073;&#1082;&#1080; MySQL
    </p>
    <p>
      <font color="#008000">$wpdb-&gt;flush();</font>&#160;&#160;# &#1059;&#1076;&#1072;&#1083;&#1080;&#1090;&#1100; &#1082;&#1101;&#1096;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1099;&#1077; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1099; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      &#1050;&#1083;&#1072;&#1089;&#1089; &#1073;&#1072;&#1079;&#1099; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1076;&#1086;&#1087;. &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077;, &#1093;&#1088;&#1072;&#1085;&#1103;&#1097;&#1080;&#1077; &#1080;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1102; &#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;&#1093; WP. &#1042;&#1089;&#1090;&#1072;&#1074;&#1100;&#1090;&#1077; &#1082;&#1086;&#1076; &#1085;&#1077;&#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1080;&#1103; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;, &#1095;&#1090;&#1086;&#1073;&#1099; &#1091;&#1074;&#1080;&#1076;&#1077;&#1090;&#1100; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1099;
    </p>
    <p>
      <font color="#008000">var_dump( $wpdb-&gt;num_queries );</font>&#160;&#160;# &#1054;&#1073;&#1097;&#1077;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;&#1085;&#1099;&#1093; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1074;
    </p>
    <p>
      <font color="#008000">var_dump( $wpdb-&gt;num_rows );</font>&#160;&#160;# &#1054;&#1073;&#1097;&#1077;&#1077; &#1095;&#1080;&#1089;&#1083;&#1086; &#1089;&#1090;&#1088;&#1086;&#1082;, &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1084; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1086;&#1084;
    </p>
    <p>
      <font color="#008000">var_dump( $wpdb-&gt;last_result );</font>&#160;&#160;# &#1056;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1099; &#1089;&#1072;&#1084;&#1086;&#1075;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;
    </p>
    <p>
      <font color="#008000">var_dump( $wpdb-&gt;last_query );</font>&#160;&#160;# &#1057;&#1072;&#1084;&#1099;&#1081; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1080;&#1081; &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1085;&#1099;&#1081; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;
    </p>
    <p>
      <font color="#008000">var_dump( $wpdb-&gt;col_info );</font>&#160;&#160;# &#1048;&#1085;&#1092;&#1086;&#1088;&#1084;&#1072;&#1094;&#1080;&#1103; &#1089;&#1090;&#1086;&#1083;&#1073;&#1094;&#1072; &#1076;&#1083;&#1103; &#1089;&#1072;&#1084;&#1086;&#1075;&#1086; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1085;&#1077;&#1075;&#1086; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1072;
    </p>
    <p>
      
    </p>
    <p>
      <b>&#1055;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1072;&#1103; &#1041;&#1044; $queries</b>&#160;- &#1093;&#1088;&#1072;&#1085;&#1080;&#1090; &#1074;&#1089;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099;, &#1079;&#1072;&#1087;&#1091;&#1097;&#1077;&#1085;&#1085;&#1099;&#1077; WP. &#1040;&#1082;&#1090;&#1080;&#1074;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1091;&#1102;:
    </p>
    <ol>
      <li>
        <font color="#0000c0">vi wp-config.php </font><br/><font color="#008000">define( 'SAVEQUERIES', true );</font>&#160;&#160;# WP &#1073;&#1091;&#1076;&#1077;&#1090; &#1089;&#1086;&#1093;&#1088;&#1072;&#1085;&#1103;&#1090;&#1100; &#1074;&#1089;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099;, &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1085;&#1099;&#1077; &#1085;&#1072; &#1082;&#1072;&#1078;&#1076;&#1086;&#1081; &#1079;&#1072;&#1075;&#1088;&#1091;&#1078;&#1077;&#1085;&#1085;&#1086;&#1081; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1077;, &#1074; &#1087;&#1077;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1086;&#1081; $queries
      </li>
      <li>
        *.php<br/><font color="#008000">var_dump( $wpdb-&gt;queries );</font>&#160;&#160;# &#1074;&#1099;&#1074;&#1086;&#1076;&#1080;&#1090; &#1074;&#1089;&#1077; &#1079;&#1072;&#1087;&#1088;&#1086;&#1089;&#1099;, &#1074;&#1099;&#1087;&#1086;&#1083;&#1085;&#1077;&#1085;&#1085;&#1099;&#1077; &#1087;&#1088;&#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1099;
      </li>
    </ol>
  </body>
</html></richcontent>
</node>
