      <b>&#1057;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; &#1073;&#1083;&#1086;&#1075;&#1072;.</b>&#160; &#1057;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072; &#1073;&#1083;&#1086;&#1075;&#1072; &#1087;&#1086;&#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103;, &#1082;&#1086;&#1075;&#1076;&#1072; &#1076;&#1083;&#1103; &#1075;&#1083;&#1072;&#1074;&#1085;&#1086;&#1081; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085;&#1072; &#1087;&#1086;&#1089;&#1090;&#1086;&#1103;&#1085;&#1085;&#1072;&#1103; &#1089;&#1090;&#1088;&#1072;&#1085;&#1080;&#1094;&#1072;
    </p>
    <ul>
      <li>
        home.php
      </li>
      <li>
        index.php
      </li>
    </ul>
    <p>
      <b>&#1042;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; (embeds).</b>&#160; &#1064;&#1072;&#1073;&#1083;&#1086;&#1085;&#1099; &#1074;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103; &#1082;&#1086;&#1075;&#1076;&#1072; &#1079;&#1072;&#1087;&#1088;&#1072;&#1096;&#1080;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1079;&#1072;&#1087;&#1080;&#1089;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; REST API. &#1042;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086;&#1103;&#1074;&#1080;&#1083;&#1080;&#1089;&#1100; &#1074; &#1074;&#1077;&#1088;&#1089;&#1080;&#1080; 4.5 &#1080; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1090; &#1074;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1090;&#1100; &#1074;&#1072;&#1096;&#1080; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1074; &#1095;&#1091;&#1078;&#1080;&#1077; &#1089;&#1072;&#1081;&#1090;&#1099;. &#1057;&#1084;. get_post_embed_url(). &#1063;&#1090;&#1086;&#1073;&#1099; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1090;&#1086;&#1083;&#1100;&#1082;&#1086; &#1082;&#1086;&#1085;&#1090;&#1077;&#1085;&#1090; &#1074;&#1089;&#1090;&#1088;&#1072;&#1080;&#1074;&#1072;&#1085;&#1080;&#1103;, &#1084;&#1086;&#1078;&#1085;&#1086; &#1074; &#1090;&#1077;&#1084;&#1077; &#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1092;&#1072;&#1081;&#1083; embed-content.php &#1080; &#1086;&#1087;&#1080;&#1089;&#1072;&#1090;&#1100; &#1090;&#1072;&#1084; HTML. &#1054;&#1088;&#1080;&#1075;&#1080;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; HTML &#1085;&#1072;&#1093;&#1086;&#1076;&#1080;&#1090;&#1089;&#1103; &#1074; &#1092;&#1072;&#1081;&#1083;&#1077; &#1076;&#1074;&#1080;&#1078;&#1082;&#1072; /wp-includes/theme-compat/embed-content.php
    </p>
    <p>
      &#1050;&#1072;&#1082; &#1101;&#1090;&#1086; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1077;&#1090;
    </p>
    <ul>
      <li>
        embed-{post-type}-{post_format}.php
      </li>
      <li>
        embed-{post-type}.php
      </li>
      <li>
        embed.php
      </li>
    </ul>
    <p>
      <b>&#1060;&#1080;&#1083;&#1100;&#1090;&#1088;&#1099;.</b>&#160;&#1048;&#1077;&#1088;&#1072;&#1088;&#1093;&#1080;&#1102; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1079;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1095;&#1077;&#1088;&#1077;&#1079; &#1076;&#1080;&#1085;&#1072;&#1084;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1077; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1099;:
    </p>
    <ul>
      <li>
        (type)_template_hierarchy - &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1091;&#1077;&#1090; &#1084;&#1072;&#1089;&#1089;&#1080;&#1074; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1081; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#1080;&#1077;&#1088;&#1072;&#1088;&#1093;&#1080;&#1080;, &#1087;&#1086; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1084;&#1091; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1076;&#1090;&#1080; &#1087;&#1086;&#1080;&#1089;&#1082; &#1085;&#1091;&#1078;&#1085;&#1086;&#1075;&#1086; &#1092;&#1072;&#1081;&#1083;&#1072;. &#1057; WP 4.7
      </li>
      <li>
        (type)_template - &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1091;&#1077;&#1090; &#1087;&#1091;&#1090;&#1100; &#1076;&#1086; &#1091;&#1078;&#1077; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1074;&#1096;&#1077;&#1075;&#1086;&#1089;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072; &#1096;&#1072;&#1073;&#1083;&#1086;&#1085;&#1072;
      </li>
      <li>
        &#1042;&#1072;&#1088;&#1080;&#1072;&#1085;&#1090;&#1099; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088;&#1072; type &#1074; &#1086;&#1076;&#1085;&#1086;&#1080;&#1084;&#1077;&#1085;&#1085;&#1086;&#1084; &#1087;&#1072;&#1088;&#1072;&#1084;&#1077;&#1090;&#1088; $type &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; get_query_template()
      </li>
    </ul>
    <p>
      <b>&#1044;&#1088;&#1091;&#1075;&#1080;&#1077; &#1092;&#1072;&#1081;&#1083;&#1099; &#1090;&#1077;&#1084;&#1099;.</b>&#160;&#1054;&#1085;&#1080; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084;&#1099;&#1077; &#1080; &#1085;&#1077; &#1091;&#1095;&#1072;&#1089;&#1090;&#1074;&#1091;&#1102;&#1090; &#1074; &#1080;&#1077;&#1088;&#1072;&#1088;&#1093;&#1080;&#1080;. &#1053;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; &#1092;&#1072;&#1081;&#1083;
    </p>
    <ul>
      <li>
        functions.php - &#1074;&#1089;&#1077;&#1075;&#1076;&#1072; &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080; &#1087;&#1088;&#1080; &#1079;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1077; &#1090;&#1077;&#1084;&#1099;.
      </li>
      <li>
        header.php - get_header()
      </li>
      <li>
        sidebar.php - get_sidebar(). &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1074; &#1083;&#1102;&#1073;&#1086;&#1084; &#1092;&#1072;&#1081;&#1083;&#1077; &#1090;&#1077;&#1084;&#1099; &#1089; &#1087;&#1086;&#1084;&#1086;&#1097;&#1100;&#1102; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; get_sidebar().
      </li>
      <li>
        footer.php - get_footer()
      </li>
      <li>
        searchform.php - get_search_form()
      </li>
    </ul>
  </body>
</html></richcontent>
</node>
<node TEXT="Хуки" ID="ID_846402441" CREATED="1591030174684" MODIFIED="1618742417788"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1061;&#1091;&#1082;&#1080;</b>&#160;- &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1090; &#1084;&#1072;&#1085;&#1080;&#1087;&#1091;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1086;&#1094;&#1077;&#1076;&#1091;&#1088;&#1086;&#1081; &#1073;&#1077;&#1079; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103; &#1092;&#1072;&#1081;&#1083;&#1072; &#1074; &#1103;&#1076;&#1088;&#1077; WordPress. &#1061;&#1091;&#1082; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1105;&#1085; &#1082;&#1072;&#1082; &#1082; &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1102; (action hook), &#1090;&#1072;&#1082; &#1080; &#1082; &#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1091; (filter hook).
    </p>
    <ul>
      <li>
        <b>Actions</b>&#160;(&#1076;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103;) - &#1089;&#1086;&#1073;&#1099;&#1090;&#1080;&#1103;, &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1102;&#1090; &#1074; &#1086;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1077;&#1085;&#1085;&#1099;&#1081; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1080; &#1085;&#1080;&#1095;&#1077;&#1075;&#1086; &#1085;&#1077; &#1074;&#1086;&#1079;&#1074;&#1088;&#1072;&#1097;&#1072;&#1102;&#1090;

        <ul>
          <li>
            &#1084;&#1086;&#1078;&#1085;&#1086; &#1079;&#1072;&#1076;&#1072;&#1074;&#1072;&#1090;&#1100; &#1087;&#1088;&#1080;&#1086;&#1088;&#1080;&#1090;&#1077;&#1090;&#1099;
          </li>
        </ul>
      </li>
      <li>
        <b>Filters</b>&#160;(&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1099;) - &#1095;&#1090;&#1086;&#1073;&#1099; &#1086;&#1090;&#1092;&#1080;&#1083;&#1100;&#1090;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100; &#1087;&#1077;&#1088;&#1077;&#1076;&#1072;&#1074;&#1072;&#1077;&#1084;&#1086;&#1077; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077;, &#1090;.&#1077;. &#1092;&#1080;&#1083;&#1100;&#1090;&#1088; &#1087;&#1086;&#1083;&#1091;&#1095;&#1072;&#1077;&#1090; &#1079;&#1085;&#1072;&#1095;&#1077;&#1085;&#1080;&#1077; &#1080; &#1086;&#1073;&#1103;&#1079;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086; &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1077;&#1075;&#1086; &#1074;&#1077;&#1088;&#1085;&#1091;&#1090;&#1100; (&#1080;&#1079;&#1084;&#1077;&#1085;&#1105;&#1085;&#1085;&#1086;&#1077; &#1080;&#1083;&#1080; &#1085;&#1077;&#1090;)
      </li>
      <li>
        &#1050; &#1093;&#1091;&#1082;&#1072;&#1084; &#1087;&#1088;&#1080;&#1082;&#1088;&#1077;&#1087;&#1083;&#1103;&#1102;&#1090;&#1089;&#1103; PHP &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080;, &#1079;&#1072;&#1090;&#1077;&#1084; &#1101;&#1090;&#1080; &#1092;&#1091;&#1085;&#1082;&#1094;&#1080;&#1080; &#1089;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1102;&#1090;, &#1074; &#1084;&#1086;&#1084;&#1077;&#1085;&#1090; &#1089;&#1088;&#1072;&#1073;&#1072;&#1090;&#1099;&#1074;&#1072;&#1085;&#1080;&#1103; &#1093;&#1091;&#1082;&#1072;. &#1058;&#1072;&#1082;&#1086;&#1077; &#1087;&#1086;&#1074;&#1077;&#1076;&#1077;&#1085;&#1080;&#1077; &#1074; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1080; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1077;&#1088;&#1077;&#1093;&#1074;&#1072;&#1090;
      </li>
    </ul>
    <p>
      <b>&#1055;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1080;&#1077; &#1093;&#1091;&#1082;&#1086;&#1074;</b>
    </p>
    <p>
      <font color="#008000">add_action( string $tag, callable $function_to_add, int $priority = 10, int $accepted_args = 1 ) </font>
    </p>
    <p>
      <font color="#008000">add_filter( string $tag, callable $function_to_add, int $priority = 10, int $accepted_args = 1 ) </font>
    </p>
    <p>
      <font color="#008000">add_shortcode( string $tag, callable $callback ) </font>&#160;# &#1064;&#1086;&#1088;&#1090;&#1082;&#1086;&#1076;. &#1044;&#1077;&#1081;&#1089;&#1090;&#1074;&#1080;&#1103;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1099;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; &#1076;&#1072;&#1078;&#1077; <b>&#1074;&#1085;&#1091;&#1090;&#1088;&#1080; &#1087;&#1086;&#1089;&#1090;&#1072;.</b>&#160;&#1058;.&#1077;. &#1084;&#1086;&#1078;&#1085;&#1086; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; <b>&#1090;&#1072;&#1084;, &#1075;&#1076;&#1077; &#1085;&#1077;&#1083;&#1100;&#1079;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100; PHP-&#1082;&#1086;&#1076; </b>
    </p>
    <p>
      
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">&lt;?php </font></b>
    </p>
    <p>
      <b><font color="#008000">&#160;&#160;function print_hello() { </font></b>
    </p>
    <p>
      <b><font color="#008000">&#160;&#160;&#160;&#160;echo 'Hello world'; </font></b>
    </p>
    <p>
      <b><font color="#008000">&#160;&#160;}; </font></b>
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">&#160;&#160;add_action('my_hook', 'print_hello'); </font></b>
    </p>
    <p>
      
    </p>
    <p>
      <b><font color="#008000">&#160;&#160;do_action( 'my_hook' ); </font></b>
    </p>
    <p>
      <b><font color="#008000">?&gt;</font></b>
    </p>
  </body>
</html></richcontent>
</node>
