<node TEXT="Установка (Debian 9)" ID="ID_248426287" CREATED="1550425907057" MODIFIED="1550830080032"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <a href="#ID_1084320639">MySQL (&#1079;&#1072;&#1076;&#1072;&#1095;&#1080;)</a>&#160;&#160;<a href="#ID_890571485">Apache</a>&#160; <a href="#ID_112544631">MariaDB</a>&#160;
    </p>
    <p>
      
    </p>
    <p>
      <b>1. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; Apache. </b>&#1055;&#1086;&#1083;&#1085;&#1086;&#1077; &#1050;&#1086;&#1085;&#1092;&#1080;&#1075;&#1091;&#1088;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089;&#1084;&#1086;&#1090;&#1088;&#1077;&#1090;&#1100; &#1074; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1077; &#1087;&#1086; &#1091;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1077; Apache. + &#1053;&#1072;&#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1100; <a href="#ID_1699103568">&#1074;&#1080;&#1088;&#1090;&#1091;&#1072;&#1083;&#1100;&#1085;&#1099;&#1081; &#1093;&#1086;&#1089;&#1090;</a>.
    </p>
    <p>
      <font color="#0000c0">apt-get install libapache2-mod-php7.0 -y </font>
    </p>
    <p>
      <font color="#0000c0">systemctl start apache2 </font>
    </p>
    <p>
      <font color="#0000c0">systemctl enable apache2</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>2. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; PHP7</b>
    </p>
    <p>
      <font color="#0000c0">apt install php7.0 php7.0-cli php7.0-mcrypt php7.0-intl php7.0-mysql php7.0-curl php7.0-gd php7.0-soap php7.0-xml php7.0-zip php7.0-readline php7.0-opcache php7.0-json php7.0-gd -y </font>&#160;# PHP+&#1084;&#1086;&#1076;&#1091;&#1083;&#1080;
    </p>
    <p>
      <font color="#008000"><b># /etc/php/7.0/apache2/php.ini&#160;&#160;&#1042;&#1085;&#1077;&#1089;&#1090;&#1080; &#1080;&#1079;&#1084;&#1077;&#1085;&#1077;&#1085;&#1080;&#1103;</b>&#160;</font>
    </p>
    <p>
      <font color="#008000">memory_limit = 256M </font>
    </p>
    <p>
      <font color="#008000">upload_max_filesize = 32M </font>
    </p>
    <p>
      <font color="#008000">post_max_size = 32M </font>
    </p>
    <p>
      <font color="#008000">max_execution_time = 300 </font>
    </p>
    <p>
      <font color="#008000">date.timezone = Europe/Moscow</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>3. &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1041;&#1044; &#1080; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103;.</b>
    </p>
    <p>
      <font color="#0000c0">systemctl status mysql</font>&#160;&#160;# &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100; &#1089;&#1090;&#1072;&#1090;&#1091;&#1089; MySQL. &#1044;&#1086;&#1083;&#1078;&#1077;&#1085; &#1073;&#1099;&#1090;&#1100; active
    </p>
    <p>
      <font color="#0000c0">apt install php-mysql</font>&#160;&#160;# &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1084;&#1086;&#1076;&#1091;&#1083;&#1100; <b>php-mysql</b>&#160; (&#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103; php&lt;&#1074;&#1077;&#1088;&#1089;&#1080;&#1103;&gt;-mysql)
    </p>
    <p>
      <font color="#0000c0">mysql -u root -p</font>&#160;&#160;# &#1042;&#1093;&#1086;&#1076; &#1074; &#1082;&#1086;&#1085;&#1089;&#1086;&#1083;&#1100; MySQL. &#1042;&#1084;&#1077;&#1089;&#1090;&#1086; &#1088;&#1091;&#1090;&#1072; &#1084;&#1086;&#1078;&#1085;&#1086; &#1083;&#1102;&#1073;&#1086;&#1075;&#1086; &#1072;&#1076;&#1084;&#1080;&#1085;&#1072; MySQL
    </p>
    <p>
      <font color="#008000">CREATE&#160;DATABASE joomla;</font>&#160;&#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1041;&#1044; (&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, joomla)
    </p>
    <p>
      <font color="#008000">CREATE USER 'joomla'@'localhost' IDENTIFIED BY '&#1087;&#1072;&#1088;&#1086;&#1083;&#1100;';</font>&#160;&#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; joomla
    </p>
    <p>
      <font color="#008000">GRANT ALL PRIVILEGES ON joomla.* TO 'joomla'@'localhost';</font>&#160;&#160;# &#1053;&#1072;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1103;&#1084;&#1080;. *.* - &#1079;&#1072;&#1076;&#1072;&#1102;&#1090; &#1073;&#1072;&#1079;&#1091; &#1080; &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1091;, &#1082; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1084; &#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; &#1073;&#1091;&#1076;&#1077;&#1090; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;
    </p>
    <p>
      <font color="#008000">FLUSH PRIVILEGES;</font>&#160;&#160;# &#1054;&#1073;&#1085;&#1086;&#1074;&#1080;&#1090;&#1100; &#1087;&#1088;&#1080;&#1074;&#1080;&#1083;&#1077;&#1075;&#1080;&#1080;
    </p>
    <p>
      <b>&#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1090;&#1100;</b>
    </p>
    <p>
      <font color="#008000">SHOW DATABASES;</font>&#160;&#160;# &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; &#1073;&#1072;&#1079; &#1076;&#1099;&#1085;&#1085;&#1099;&#1093;
    </p>
    <p>
      <font color="#008000">SELECT User,Host FROM mysql.user;</font>&#160;&#160;# &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1077;&#1081;
    </p>
    <p>
      <font color="#008000">SHOW GRANTS FOR joomla@localhost;</font>&#160;&#160;# &#1057;&#1087;&#1080;&#1089;&#1086;&#1082; &#1087;&#1088;&#1072;&#1074; &#1091; &#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1103; root@localhost
    </p>
    <p>
      <font color="#008000">exit;</font>
    </p>
    <p>
      
    </p>
    <p>
      <b>4. &#1059;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1082;&#1072; Joomla!</b>
    </p>
    <p>
      <font color="#0000c0">wget https://downloads.joomla.org/cms/&lt;joomla &#1074;&#1077;&#1088;&#1089;&#1080;&#1103;&gt;.tar.gz</font>&#160;&#160;# &#1057;&#1082;&#1072;&#1095;&#1072;&#1090;&#1100;
    </p>
    <p>
      <font color="#0000c0">mkdir /var/www/&lt;&#1084;&#1086;&#1081;&#1089;&#1072;&#1081;&#1090;&gt;</font>&#160; &#160;# &#1057;&#1086;&#1079;&#1076;&#1072;&#1090;&#1100; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075; &#1076;&#1083;&#1103; &#1089;&#1072;&#1081;&#1090;&#1072;
    </p>
    <p>
      <font color="#0000c0">tar -xvf &lt;joomla &#1074;&#1077;&#1088;&#1089;&#1080;&#1103;&gt;.tar.gz&#160;-C /var/www/&lt;&#1084;&#1086;&#1081;&#1089;&#1072;&#1081;&#1090;&gt;</font>&#160;&#160;# &#1056;&#1072;&#1089;&#1087;&#1072;&#1082;&#1086;&#1074;&#1072;&#1090;&#1100; &#1074; &#1082;&#1072;&#1090;&#1072;&#1083;&#1086;&#1075;
    </p>
    <p>
      <font color="#0000c0">chown -R www-data:www-data /var/www/&lt;&#1084;&#1086;&#1081;&#1089;&#1072;&#1081;&#1090;&gt;&#160;&#160;</font># &#1057;&#1084;&#1077;&#1085;&#1080;&#1090;&#1100; &#1074;&#1083;&#1072;&#1076;&#1077;&#1083;&#1100;&#1094;&#1072;<font color="#0000c0">&#160; </font>
    </p>
    <p>
      <font color="#0000c0">chmod -R 777 /var/www/&lt;&#1084;&#1086;&#1081;&#1089;&#1072;&#1081;&#1090;&gt;&#160;&#160;</font># &#1055;&#1088;&#1072;&#1074;&#1072; &#1076;&#1086;&#1089;&#1090;&#1091;&#1087;&#1072;
    </p>
    <p>
      &#1047;&#1072;&#1081;&#1090;&#1080; &#1085;&#1072; &#1089;&#1072;&#1081;&#1090; &#1095;&#1077;&#1088;&#1077;&#1079; &#1073;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088; &gt; &#1047;&#1072;&#1087;&#1086;&#1083;&#1085;&#1080;&#1090;&#1100; &#1074;&#1089;&#1077; &#1087;&#1086;&#1083;&#1103; &gt; &#1055;&#1088;&#1086;&#1080;&#1085;&#1089;&#1090;&#1072;&#1083;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1090;&#1100;&#1089;&#1103;
    </p>
    <p>
      
    </p>
    <p>
      &#1041;&#1088;&#1072;&#1091;&#1079;&#1077;&#1088;:&lt;&#1084;&#1086;&#1081;&#1089;&#1072;&#1081;&#1090;&gt;<b>/administrator</b>&#160;&#160;# &#1042;&#1086;&#1081;&#1090;&#1080; &#1074; &#1072;&#1076;&#1084;&#1080;&#1085;&#1080;&#1089;&#1090;&#1088;&#1072;&#1090;&#1080;&#1074;&#1085;&#1091;&#1102; &#1087;&#1072;&#1085;&#1077;&#1083;&#1100;
    </p>
  </body>
</html></richcontent>
</node>
