<node TEXT="команды" ID="ID_1157881599" CREATED="1647624079492" MODIFIED="1647631839087">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <font color="#0000c0">cat /var/log/xferlog&nbsp; </font># Осмотр <b>лог-файла</b>&nbsp;ftp поможет в поиске вирусов, если заражение было осуществленно по ftp
    </p>
    <p>
      <font color="#0000c0">file site.ru/uploads/* | grep -i php</font>&nbsp;&nbsp;# Показать <b>php файлы</b>&nbsp;в папке uploads, независимо от их расширения
    </p>
    <p>
      <font color="#0000c0">stat infected.js</font>&nbsp;&nbsp;# Дата последнего доступа, модификации и изменения атрибутов файла. Это может помочь установить время и дату взлома. По этим датам можно поискать файлы и события в логах
    </p>
    <p>
      
    </p>
    <p>
      <font color="#0000c0">grep -ril base64_decode site.ru&nbsp; </font># <b>Поиск</b>&nbsp;файлов с паттерном
    </p>
    <p>
      <font color="#0000c0">find site.ru/ -type f -mtime -20&nbsp; </font># <b>Поиск</b>&nbsp;файлов которые были изменены меньше чем 20 дней назад
    </p>
    <p>
      <font color="#0000c0">find ./ -name &quot;*.php&quot; | xargs ls -la | grep &quot;Nov 14&quot;</font>&nbsp;&nbsp;# <b>Поиск</b>&nbsp;файлов модиф. в определенную дату
    </p>
    <p>
      <font color="#0000c0">find ./ -name &quot;*.php&quot; | xargs ls -la | grep &quot;Nov 14&quot; | awk '{print $9}' | xargs grep &quot;eval(base6&quot;</font>&nbsp;&nbsp;# Проверим все эти файлы на наличие функции eval(base64_decode
    </p>
    <p>
      <font color="#0000c0">find ./ -name &quot;*.php&quot; | xargs grep -w &quot;eval(base64_decode&quot;</font>&nbsp;&nbsp;&nbsp;# <b>Поиск</b>&nbsp;всех скриптов, использующих функцию eval(base64_decode
    </p>
    <p>
      <font color="#0000c0">grep -Rils --include=\.{php,htm*} -e 'b=4594' -e 'e2aa4e' -e 'v58f57b98 = 0' -e 'forexam\@pandion.im' -e 'pathToDomains' -e 'if(navigator.userAgent.match(' -e 'var vst = String.fromCharCode' -e 'Menu\files\/jquery.js' -e 'i5463 == null' -e 'r57.gen.tr' -e '\/rsize.js' -e 'feelthesame.changeip.name' -e '40,101,115,110,98,114,105,110' -e 'c99sh' -e 'Shell by' -e ' sh_ver' -e '\.tcpflood' -e 'c999sh' -e 'Array(base64_decode' -e 'Attacker Perl File' -e 'bogel = ' -e '(\!function_exists(\&quot;getmicrotime\&quot;))' -e'\$d=substr' -e 'WSO ' -e 'r57shell' -e 'msg=@gzinflate(@base64_decode(@str_replace' -e '6POkiojiO7iY3ns1rn8' -e ' mysql_safe' -e 'sql2_safe' -e 'aHR0cDovLzE3OC4yMTEu' -e 'php function _' -e 'encodeURIComponent(document.URL)' -e '\; if(isset(\$_REQUEST' -e 'UdpFlood' -e 'udp\:\/\/1.1.1.1' -e '\ (md5(\$_POST\[' -e 'header(\&quot;Location\: http' -e 'fx29sh' -e 'c999sh_surl' -e 'c99sh' -e '\/request12.php' -e 'NlOThmMjgyODM0NjkyODdiYT' -e 'semi-priv8' -e 'JHNoX25hbWUgPSAiIj' -e '$shell_name' -e 'UvUbjYH4eJNgF4E1fedl' -e 'killall \-9' -e 'Angel Shell' -e 'c100.php' -e 'c2007.php' -e 'c99 mod Captain Crunch' -e '\$c99sh_updatefurl' -e 'C99 Modified By Psych0' -e 'php-backdoor' -e 'r577.php' -e 'wso shell' -e 'backdoor' -e 'eval(stripslashes(' -e 'Backdoor' -e 'Set WSHshell' -e 'WSHshell.Run DropPath' -e /var/www/*/data/www/</font>&nbsp;&nbsp;# <b>Поиск</b>&nbsp;паттернов вирусов в файлах php* и htm* директории /var/www/*/data/www/.
