<node TEXT="ClamAV" ID="ID_655066540" CREATED="1647628863766" MODIFIED="1647628887824">
<attribute_layout NAME_WIDTH="10 pt" VALUE_WIDTH="10 pt"/>
<richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>ClamAV</b>
    </p>
    <p>
      yum install -y clamav
    </p>
    <p>
      freshclam&nbsp;&nbsp;# Обновить БД вирусных сигнатур
    </p>
    <p>
      clamscan -ri /путь/к_нужной/директории&nbsp;&nbsp;#&nbsp;&nbsp;запустить сканирование нужной директории. -ri после сканирования выведет список только зараженных файлов и другую техническую информацию о сканировании
    </p>
    <p>
      clamscan -r /home/ -log=/var/log/clamscan.log&nbsp;&nbsp;# для ведения лог-файла
    </p>
    <p>
      clamscan -r --move=/home/USER/VIRUS /home/USER&nbsp;&nbsp;# Переместить зараженные файлы в другую директорию:
    </p>
    <p>
      clamav -r&nbsp;&nbsp;# Для проверки запустить из каталога сайта
    </p>
    <p>
      clamscan --help
    </p>
  </body>
</html></richcontent>
</node>
