<node TEXT="Конф. файлы для подключения БД" ID="ID_786804637" CREATED="1562062571364" MODIFIED="1680772410115"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <ul>
      <li>
        Если ничего из перечисленного не подошло, то ищем по названию базы<br/><font color="#0000c0">grep -Rl «название базы» /path/to/find</font>
      </li>
    </ul>
    <p>
      <b>Bitrix. </b>
    </p>
    <p>
      <b>/bitrix/php_interface/dbconn.php</b>&nbsp;(<font color="#ff0000">старое ядро</font>):
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$DBHost = &quot;сервер&quot;;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$DBLogin = &quot;имя_пользователя&quot;;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$DBPassword = &quot;пароль&quot;;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$DBName = &quot;имя_базы_данных&quot;;
    </p>
    <p>
      <b>/bitrix/.settings.php</b>&nbsp;(<font color="#0000c0">новое ядро</font>):
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'host' =&gt; 'сервер',
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'database' =&gt; 'имя_базы_данных',
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'login' =&gt; 'имя_пользователя',
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'password' =&gt; 'пароль',
    </p>
    <p>
      
    </p>
    <p>
      <b>Joomla.</b>&nbsp;/<b>configuration.php</b>:
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;var $host = 'сервер';
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;var $user = 'имя_пользователя';
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;var $db = 'имя_базы_данных';
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;var $password = 'пароль';
    </p>
    <p>
      
    </p>
    <p>
      <b>WordPress. wp-config.php</b>: wordpress БД. Прверить пути к сайту в таблице <b>wp_options</b>&nbsp;поля <b>siteurl</b>&nbsp;&nbsp;и <b>home</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_NAME', 'имя_базы_данных');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_USER', 'имя_пользователя');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_HOST', 'сервер');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_PASSWORD', 'пароль');
    </p>
    <p>
      
    </p>
    <p>
      <b>Opencart. /config.php</b>&nbsp;и <b>/admin/config.php</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_HOSTNAME', 'сервер');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_USERNAME', 'имя_пользователя');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_PASSWORD', 'пароль');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_DATABASE', 'имя_базы_данных');
    </p>
    <p>
      
    </p>
    <p>
      <b>Drupal 6.</b>&nbsp;<b>/site/default/settings.php. </b>$db_url = 'mysql://username:password@mysqlhost/databasename'; Где:
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;username - имя пользователя;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;password - пароль;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;mysqlhost - сервер базы данных;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;databasename - имя базы данных.
    </p>
    <p>
      
    </p>
    <p>
      <b>Drupal 7. /site/default/settings.php</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'database' =&gt; 'имя базы данных',
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'username' =&gt; 'имя пользователя',
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'password' =&gt; 'пароль',
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'host' =&gt; 'сервер',
    </p>
    <p>
      
    </p>
    <p>
      <b>DLE.</b>&nbsp;<b>/engine/data/dbconfig.php</b>:
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define (&quot;DBHOST&quot;, &quot;сервер&quot;);
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define (&quot;DBNAME&quot;, &quot;имя_базы_данных&quot;);
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define (&quot;DBUSER&quot;, &quot;имя_пользователя&quot;);
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define (&quot;DBPASS&quot;, &quot;пароль&quot;);
    </p>
    <p>
      
    </p>
    <p>
      <b>Shop-script.</b>&nbsp;<b>/cfg/connect.inc.php</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_HOST', 'сервер');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_USER', 'имя_пользователя');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_PASS', 'пароль');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_NAME', 'имя_базы_данных');
    </p>
    <p>
      
    </p>
    <p>
      <b>ShopCMS. /core/config/connect.inc.php</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_HOST', 'сервер');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_USER', 'имя_пользователя');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_PASS', 'пароль');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('DB_NAME', 'имя_базы_данных');
    </p>
    <p>
      
    </p>
    <p>
      <b>WebAsyst. /dblist/логин.xml</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;SQLSERVER=&quot;сервер&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;DB_NAME=&quot;имя_базы_данных&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;DB_PASSWORD=&quot;пароль&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;DB_USER=&quot;имя_пользователя&quot;
    </p>
    <p>
      а также в файле кеша <b>/temp/scdb/.settings</b>.логин дублируются эти же параметры:
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;&quot;DB_USER&quot; &quot;имя_пользователя&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;&quot;DB_PASS&quot; &quot;пароль&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;&quot;DB_NAME&quot; &quot;имя_базы_данных&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;&quot;DB_HOST&quot; &quot;сервер&quot;
    </p>
    <p>
      
    </p>
    <p>
      <b>PrestaShop. /config/settings.inc.php</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('_DB_NAME_', 'имя_базы_данных');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('_DB_SERVER_', 'сервер');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('_DB_USER_', 'имя_пользователя');
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;define('_DB_PASSWD_', 'пароль');
    </p>
    <p>
      
    </p>
    <p>
      <b>MODx.&nbsp;/manager/includes/config.inc.php</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$database_server = 'сервер';
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$database_user = 'имя_пользователя';
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$database_password = 'пароль';
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$dbase = 'имя_базы_данных’;
    </p>
    <p>
      
    </p>
    <p>
      <b>PHPShop. phpshop/inc/config.ini</b>:
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;host = &quot;сервер&quot;;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;user_db = &quot;имя_пользователя&quot;;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;pass_db = &quot;пароль&quot;;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;dbase = &quot;имя_базы_данных&quot;;
    </p>
    <p>
      
    </p>
    <p>
      <b>HostCMS. modules/core/config/database.php</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'driver' =&gt; 'mysql',
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'host' =&gt; 'localhost',
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'username' =&gt; 'srv83user',
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'password' =&gt; 'megapassword',
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;'database' =&gt; 'hostcms'
    </p>
    <p>
      
    </p>
    <p>
      <b>UMI</b>. в секции [connections] файла <b>docs/config.ini</b>: Код:
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;core.host = &quot;адрес_сервера&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;core.login = &quot;имя_пользователя&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;core.password = &quot;пароль&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;core.dbname = &quot;имя_базы_данных&quot;
    </p>
    <p>
      
    </p>
    <p>
      <b>phpBB</b>&nbsp;файле docs/config.php:
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$dbhost = 'адрес_сервера';
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$dbname = 'имя_базы_данных';
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$dbuser = 'имя_пользователя';
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$dbpasswd = 'пароль';
    </p>
    <p>
      
    </p>
    <p>
      <b>NetCat. docs/vars.inc.php</b>
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$MYSQL_HOST = &quot;адрес_сервера&quot;;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$MYSQL_USER = &quot;имя_пользователя&quot;;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$MYSQL_PASSWORD = &quot;пароль&quot;;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;$MYSQL_DB_NAME = &quot;имя_базы_данных&quot;;
    </p>
    <p>
      
    </p>
    <p>
      <b>Amiro.CMS</b>. <b>docs/_local/config.ini.php</b>:
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;DB_Host = &quot;адрес_сервера&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;DB_Database = &quot;имя_базы_данных&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;DB_User = &quot;имя_пользователя&quot;
    </p>
    <p>
      &nbsp;&nbsp;&nbsp;&nbsp;DB_Password = &quot;пароль&quot;
    </p>
  </body>
</html></richcontent>
