      <li>
        &#1057;&#1088;&#1086;&#1082; &#1089;&#1083;&#1091;&#1078;&#1073;&#1099; &#1073;&#1072;&#1090;&#1072;&#1088;&#1077;&#1080;&#160;&#160;&#160;&#160;&#160;5-10 &#1083;&#1077;&#1090;
