      <li>
        &#1055;&#1088;&#1080; &#1079;&#1072;&#1088;&#1103;&#1076;&#1082;&#1077; &#1089;&#1080;&#1083;&#1072; &#1090;&#1086;&#1082;&#1072; &#1085;&#1077; &#1073;&#1086;&#1083;&#1077;&#1077; 5-10% &#1086;&#1090; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1080; &#1040;&#1050;&#1041;
      </li>
      <li>
        &#1073;&#1077;&#1089;&#1087;&#1077;&#1088;&#1077;&#1073;&#1086;&#1081;&#1085;&#1080;&#1082; (UPS) &#1076;&#1086;&#1083;&#1078;&#1077;&#1085; &#1083;&#1080;&#1073;&#1086; &#1090;&#1086;&#1088;&#1084;&#1086;&#1079;&#1080;&#1090;&#1100; &#1079;&#1072;&#1088;&#1103;&#1076; &#1087;&#1086;&#1089;&#1083;&#1077; &#1087;&#1086;&#1083;&#1085;&#1086;&#1075;&#1086; &#1079;&#1072;&#1088;&#1103;&#1076;&#1072; &#1073;&#1072;&#1090;&#1072;&#1088;&#1077;&#1081;, &#1083;&#1080;&#1073;&#1086; &#1079;&#1072;&#1088;&#1103;&#1078;&#1072;&#1090;&#1100; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077;&#1084; &#1085;&#1077; &#1074;&#1099;&#1096;&#1077; 13.3V - &#1090;&#1086;&#1075;&#1076;&#1072; &#1073;&#1072;&#1090;&#1072;&#1088;&#1077;&#1080; &#1074; UPS &#1085;&#1077; &#1073;&#1091;&#1076;&#1091;&#1090; &#1074;&#1099;&#1082;&#1080;&#1087;&#1072;&#1090;&#1100; &#1080; &#1088;&#1072;&#1079;&#1088;&#1091;&#1096;&#1072;&#1090;&#1100;&#1089;&#1103; <b>&#1080;&#1079;-&#1079;&#1072; &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1088;&#1103;&#1076;&#1072; <font color="#ff0000">&#1080;&#1085;&#1072;&#1095;&#1077; 2 &#1075;&#1086;&#1076;&#1072; &#1080; &#1093;&#1072;&#1085;&#1072;</font>.</b>
      </li>
    </ul>
