<node TEXT="Проблемы" ID="ID_47696485" CREATED="1519112079710" MODIFIED="1519112079710"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>&#1055;&#1088;&#1086;&#1073;&#1083;&#1077;&#1084;&#1099;:</b>
    </p>
    <p>
      <b>&#1057;&#1091;&#1083;&#1100;&#1092;&#1072;&#1090;&#1072;&#1094;&#1080;&#1103; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1085;</b>. &#1055;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1086;&#1090; &#1085;&#1077;&#1076;&#1086;&#1079;&#1072;&#1088;&#1103;&#1076;&#1086;&#1074;, &#1087;&#1077;&#1088;&#1077;&#1075;&#1088;&#1077;&#1074;&#1072;. &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1080;&#1090;&#1100; &#1084;&#1086;&#1078;&#1085;&#1086; &#1087;&#1086; &#1073;&#1077;&#1083;&#1086;&#1084;&#1091; &#1085;&#1072;&#1083;&#1077;&#1090;&#1091; &#1085;&#1072; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1085;&#1072;&#1093; (&#1089;&#1091;&#1083;&#1100;&#1092;&#1072;&#1090; &#1089;&#1074;&#1080;&#1085;&#1094;&#1072;). &#1057;&#1091;&#1083;&#1100;&#1092;&#1072;&#1090;&#1072;&#1094;&#1080;&#1103; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1085; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1090;&#1072;&#1082;&#1078;&#1077; &#1086;&#1090; &#1074;&#1099;&#1082;&#1080;&#1087;&#1072;&#1085;&#1080;&#1103; &#1074;&#1086;&#1076;&#1099; - &#1085;&#1091;&#1078;&#1085;&#1086; &#1076;&#1086;&#1073;&#1072;&#1074;&#1080;&#1090;&#1100; &#1076;&#1080;&#1089;&#1090;&#1080;&#1083;&#1083;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1085;&#1091;&#1102; &#1074;&#1086;&#1076;&#1091;.
    </p>
    <p>
      <b>&#1050;&#1086;&#1088;&#1086;&#1073;&#1083;&#1077;&#1085;&#1080;&#1077; (&#1076;&#1077;&#1092;&#1086;&#1088;&#1084;&#1080;&#1088;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077;) &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1086;&#1074; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1085;</b>. &#1054;&#1095;&#1077;&#1085;&#1100; &#1095;&#1072;&#1089;&#1090;&#1086; &#1079;&#1080;&#1084;&#1086;&#1081; &#1080;&#1079;-&#1079;&#1072; &#1085;&#1077;&#1076;&#1086;&#1079;&#1072;&#1088;&#1103;&#1076;&#1082;&#1080; &#1072;&#1074;&#1090;&#1086;&#1084;&#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1099;&#1093; &#1040;&#1050;&#1041;. &#1054;&#1087;&#1088;&#1077;&#1076;&#1077;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074;&#1085;&#1077;&#1096;&#1085;&#1080;&#1084; &#1086;&#1089;&#1084;&#1086;&#1090;&#1088;&#1086;&#1084; - &#1074;&#1099;&#1075;&#1085;&#1091;&#1090;&#1099; &#1073;&#1086;&#1082;&#1072;. &#1058;&#1072;&#1082;&#1078;&#1077; &#1082;&#1086;&#1088;&#1086;&#1073;&#1083;&#1077;&#1085;&#1080;&#1077; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1086;&#1090; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1090;&#1086;&#1082;&#1086;&#1074; &#1088;&#1072;&#1079;&#1088;&#1103;&#1076;&#1072; &#1080; &#1079;&#1072;&#1088;&#1103;&#1076;&#1072;.
    </p>
    <p>
      <b>&#1054;&#1089;&#1099;&#1087;&#1072;&#1085;&#1080;&#1077; &#1084;&#1072;&#1089;&#1089;&#1099; &#1089; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1086;&#1074;</b>. &#1054;&#1090; &#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1080; &#1080; &#1086;&#1090; &#1085;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1086;&#1081; &#1101;&#1082;&#1089;&#1087;&#1083;&#1091;&#1072;&#1090;&#1072;&#1094;&#1080;&#1080; &#1040;&#1050;&#1041;. &#1055;&#1088;&#1080;&#1079;&#1085;&#1072;&#1082;&#1080; - &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1083;&#1080;&#1090; &#1089;&#1090;&#1072;&#1083; &#1090;&#1077;&#1084;&#1085;&#1099;&#1081;, &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; &#1089;&#1083;&#1072;&#1083;&#1072; &#1084;&#1072;&#1083;&#1077;&#1085;&#1100;&#1082;&#1072;&#1103;. &#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102; &#1085;&#1077; &#1087;&#1086;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090;. &#1042; &#1075;&#1077;&#1088;&#1084;&#1077;&#1090;&#1080;&#1095;&#1085;&#1099;&#1093; &#1040;&#1050;&#1041; &#1101;&#1090;&#1086;&#1075;&#1086; &#1085;&#1077; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090;.
    </p>
    <p>
      <b>&#1056;&#1072;&#1079;&#1088;&#1091;&#1096;&#1077;&#1085;&#1080;&#1077; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1085;</b>. &#1053;&#1077;&#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1072;&#1103; &#1101;&#1082;&#1089;&#1087;&#1083;&#1091;&#1072;&#1090;&#1072;&#1094;&#1080;&#1103;, &#1087;&#1077;&#1088;&#1077;&#1079;&#1072;&#1088;&#1103;&#1076;&#1099;, &#1089;&#1080;&#1083;&#1100;&#1085;&#1072;&#1103; &#1090;&#1088;&#1103;&#1089;&#1082;&#1072;, &#1074;&#1088;&#1077;&#1084;&#1103; &#1101;&#1082;&#1089;&#1087;&#1083;&#1091;&#1072;&#1090;&#1072;&#1094;&#1080;&#1080;. &#1053;&#1077; &#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1085;&#1080; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091;, &#1085;&#1080; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077;. &#1069;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1083;&#1080;&#1090; &#1084;&#1077;&#1085;&#1103;&#1077;&#1090; &#1094;&#1074;&#1077;&#1090; &#1085;&#1072; &#1095;&#1077;&#1088;&#1085;&#1099;&#1081;. &#1054;&#1090;&#1076;&#1077;&#1083;&#1100;&#1085;&#1099;&#1077; &#1073;&#1072;&#1085;&#1082;&#1080; &#1082;&#1080;&#1087;&#1103;&#1090;. &#1050;&#1086;&#1088;&#1087;&#1091;&#1089; &#1075;&#1088;&#1077;&#1077;&#1090;&#1089;&#1103; &#1074;&#1077;&#1089;&#1100;. &#1042; &#1075;&#1077;&#1088;&#1084;&#1077;&#1090;&#1080;&#1095;&#1085;&#1099;&#1093; &#1040;&#1050;&#1041; &#1093;&#1086;&#1088;&#1086;&#1096;&#1086; &#1074;&#1080;&#1076;&#1085;&#1086; &#1087;&#1086; &#1080;&#1089;&#1082;&#1088;&#1080;&#1074;&#1083;&#1077;&#1085;&#1085;&#1099;&#1084; &#1089;&#1090;&#1077;&#1085;&#1082;&#1072;&#1084;. &#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102; &#1085;&#1077; &#1087;&#1086;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090;.
    </p>
    <p>
      <b>&#1054;&#1090;&#1074;&#1072;&#1083; &#1087;&#1077;&#1088;&#1077;&#1084;&#1099;&#1095;&#1082;&#1080; (&#1086;&#1073;&#1088;&#1099;&#1074; &#1094;&#1077;&#1087;&#1080;).</b>&#160;&#1048;&#1079;-&#1079;&#1072; &#1073;&#1088;&#1072;&#1082;&#1072; &#1087;&#1088;&#1086;&#1080;&#1079;&#1074;&#1086;&#1076;&#1080;&#1090;&#1077;&#1083;&#1103;, &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1090;&#1086;&#1082;&#1086;&#1074;, &#1082;&#1086;&#1088;&#1088;&#1086;&#1079;&#1080;&#1080;. &#1042;&#1099;&#1076;&#1072;&#1077;&#1090; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077;, &#1085;&#1086; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1082;&#1091; &#1085;&#1077; &#1076;&#1077;&#1088;&#1078;&#1080;&#1090;. &#1055;&#1088;&#1080; &#1079;&#1072;&#1084;&#1099;&#1082;&#1072;&#1085;&#1080;&#1080; &#1096;&#1080;&#1087;&#1080;&#1090; &#1073;&#1072;&#1085;&#1082;&#1072; &#1074; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1086;&#1073;&#1088;&#1099;&#1074;, &#1053;&#1072;&#1075;&#1088;&#1077;&#1074; &#1082;&#1086;&#1088;&#1087;&#1091;&#1089;&#1072; &#1087;&#1088;&#1080; &#1101;&#1090;&#1086;&#1084; &#1087;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1083;&#1086;&#1082;&#1072;&#1083;&#1100;&#1085;&#1086; &#1089;&#1074;&#1077;&#1088;&#1093;&#1091;. &#1042;&#1086;&#1089;&#1089;&#1090;&#1072;&#1085;&#1086;&#1074;&#1083;&#1077;&#1085;&#1080;&#1102; &#1085;&#1077; &#1087;&#1086;&#1076;&#1083;&#1077;&#1078;&#1080;&#1090;.
    </p>
    <p>
      <b>&#1047;&#1072;&#1084;&#1099;&#1082;&#1072;&#1085;&#1080;&#1077; &#1101;&#1083;&#1077;&#1082;&#1090;&#1088;&#1086;&#1076;&#1086;&#1074;</b>.&#1055;&#1088;&#1086;&#1080;&#1089;&#1093;&#1086;&#1076;&#1080;&#1090; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1082;&#1086;&#1088;&#1086;&#1073;&#1083;&#1077;&#1085;&#1080;&#1103;. &#1053;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1040;&#1050;&#1041; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; &#1085;&#1086;&#1088;&#1084;&#1099; (&#1085;&#1077; &#1084;&#1086;&#1078;&#1077;&#1090; &#1085;&#1072;&#1073;&#1088;&#1072;&#1090;&#1100;), &#1079;&#1072;&#1088;&#1103;&#1076;&#1085;&#1099;&#1081; &#1090;&#1086;&#1082; &#1085;&#1077; &#1089;&#1085;&#1080;&#1078;&#1072;&#1077;&#1090;&#1089;&#1103;. &#1053;&#1072;&#1095;&#1080;&#1085;&#1072;&#1102;&#1090; &#1086;&#1073;&#1080;&#1083;&#1100;&#1085;&#1086; &#1082;&#1080;&#1087;&#1077;&#1090;&#1100; &#1074;&#1089;&#1077; &#1073;&#1072;&#1085;&#1082;&#1080;, &#1082;&#1088;&#1086;&#1084;&#1077; &#1086;&#1076;&#1085;&#1086;&#1081; - &#1084;&#1086;&#1083;&#1095;&#1080;&#1090;. &#1042; &#1101;&#1090;&#1086;&#1081; &#1073;&#1072;&#1085;&#1082;&#1077; &#1079;&#1072;&#1084;&#1099;&#1082;&#1072;&#1085;&#1080;&#1077;, &#1075;&#1088;&#1077;&#1077;&#1090;&#1089;&#1103; &#1089;&#1074;&#1077;&#1088;&#1093;&#1091;.
    </p>
    <p>
      <b>&#1054;&#1090;&#1074;&#1072;&#1083; &#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1085;&#1099;</b>. &#1041;&#1072;&#1085;&#1082;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1080;&#1084;&#1077;&#1090;&#1100; &#1089;&#1083;&#1072;&#1073;&#1091;&#1102; &#1077;&#1084;&#1082;&#1086;&#1089;&#1090;&#1100; (&#1073;&#1091;&#1076;&#1077;&#1090; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1079;&#1072;&#1088;&#1103;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1080; &#1087;&#1077;&#1088;&#1074;&#1086;&#1081; &#1088;&#1072;&#1079;&#1088;&#1103;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; - &#1074;&#1086;&#1079;&#1084;&#1086;&#1078;&#1085;&#1072; &#1087;&#1077;&#1088;&#1077;&#1087;&#1086;&#1083;&#1102;&#1089;&#1086;&#1074;&#1082;&#1072;). &#1054;&#1076;&#1085;&#1072; &#1073;&#1072;&#1085;&#1082;&#1072; &#1073;&#1091;&#1076;&#1077;&#1090; &#1073;&#1099;&#1089;&#1090;&#1088;&#1086; &#1088;&#1072;&#1079;&#1088;&#1072;&#1078;&#1072;&#1090;&#1100;&#1089;&#1103; &#1080; &#1085;&#1072;&#1095;&#1080;&#1085;&#1072;&#1090;&#1100; &#1075;&#1088;&#1077;&#1090;&#1100;&#1089;&#1103;. &#1042;&#1088;&#1086;&#1076;&#1077; &#1084;&#1086;&#1078;&#1085;&#1086; &quot;&#1074;&#1099;&#1090;&#1103;&#1085;&#1091;&#1090;&#1100;&quot; &#1089;&#1087;&#1077;&#1094;&#1080;&#1072;&#1083;&#1100;&#1085;&#1099;&#1084;&#1080; &#1079;&#1072;&#1088;&#1103;&#1076;&#1085;&#1080;&#1082;&#1072;&#1084;&#1080;.
    </p>
    <p>
