    </p>
    <p>
      - A (&#1074; &#1056;&#1086;&#1089;&#1089;&#1080;&#1080; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1102;&#1090;&#1089;&#1103;)
    </p>
    <p>
      
    </p>
    <p>
      &#1082;&#1072;&#1090;&#1077;&#1075;&#1086;&#1088;&#1080;&#1103; B (&#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1077;&#1085;&#1080;&#1077; &#1085;&#1086;&#1084;&#1080;&#1085;&#1072;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1090;&#1086;&#1082;&#1072; &#1074; 3-5 &#1088;&#1072;&#1079;) - &#1076;&#1083;&#1103; &#1088;&#1086;&#1079;&#1077;&#1090;&#1086;&#1082; &#1074; &#1082;&#1074;., &#1086;&#1089;&#1074;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      &#1082;&#1072;&#1090;&#1077;&#1075;&#1086;&#1088;&#1080;&#1103; &#1057; (&#1087;&#1088;&#1077;&#1074;&#1099;&#1096;. &#1085;&#1086;&#1084;. &#1090;&#1086;&#1082;&#1072; &#1074; 5-10 &#1088;&#1072;&#1079;) - &#1086;&#1089;&#1074;&#1077;&#1097;&#1077;&#1085;&#1080;&#1077;
    </p>
    <p>
      &#1082;&#1072;&#1090;&#1077;&#1075;&#1086;&#1088;&#1080;&#1103; D (&#1087;&#1088;&#1077;&#1074;&#1099;&#1096;. &#1085;&#1086;&#1084;. &#1090;&#1086;&#1082;&#1072; &#1074; 10-20 &#1088;&#1072;&#1079;) - &#1089;&#1080;&#1083;&#1086;&#1074;&#1099;&#1077; &#1087;&#1088;&#1080;&#1073;&#1086;&#1088;&#1099;, &#1083;&#1086;&#1076;&#1078;&#1080;&#1080;, &#1082;&#1086;&#1085;&#1076;&#1080;&#1094;&#1080;&#1086;&#1085;&#1077;&#1088;&#1099; - &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1085;&#1077;&#1090; &#1073;&#1086;&#1083;&#1100;&#1096;&#1080;&#1093; &#1087;&#1091;&#1089;&#1082;&#1086;&#1074;&#1099;&#1093; &#1090;&#1086;&#1082;&#1086;&#1074;, &#1085;&#1077;&#1090; &#1087;&#1080;&#1082;&#1086;&#1074;&#1099;&#1093; &#1085;&#1072;&#1075;&#1088;&#1091;&#1079;&#1086;&#1082;. &#1042; &#1082;&#1074;&#1072;&#1088;&#1090;&#1080;&#1088;&#1072;&#1093; &#1083;&#1091;&#1095;&#1096;&#1077; &#1085;&#1077; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1090;&#1100;, &#1087;&#1086;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1091; &#1086;&#1085;&#1080; &#1086;&#1073;&#1083;&#1072;&#1076;&#1072;&#1102;&#1090; &#1084;&#1072;&#1083;&#1086;&#1081; &#1095;&#1091;&#1074;&#1089;&#1090;&#1074;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102;
    </p>
    <p>
      
