  </head>
  <body>
    <p>
      (<b>&#1059;&#1047;&#1050; - &#1091;&#1089;&#1090;&#1088;&#1086;&#1081;&#1089;&#1090;&#1074;&#1086; &#1079;&#1072;&#1082;&#1083;&#1072;&#1076;&#1082;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;, </b>&#1082;&#1072;&#1073;&#1077;&#1083;&#1100;&#1085;&#1072;&#1103; &#1087;&#1088;&#1086;&#1090;&#1103;&#1078;&#1082;&#1072;) &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1090;&#1088;&#1086;&#1080;&#1090;&#1077;&#1083;&#1103;&#1084;&#1080; &#1080; &#1084;&#1086;&#1085;&#1090;&#1072;&#1078;&#1085;&#1080;&#1082;&#1072;&#1084;&#1080; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1090;&#1103;&#1078;&#1082;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;
    </p>
    <ul>
      <li>
        &#1085;&#1077;&#1081;&#1083;&#1086;&#1085; - &#1089;&#1072;&#1084;&#1099;&#1077; &#1076;&#1077;&#1096;&#1077;&#1074;&#1099;&#1077; &#1085;&#1086; &#1085;&#1077; &#1082;&#1072;&#1095;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1077;, &#1084;&#1080;&#1085;&#1091;&#1089; - &#1083;&#1077;&#1075;&#1082;&#1086; &#1075;&#1085;&#1091;&#1090;&#1089;&#1103;, &#1079;&#1072;&#1089;&#1090;&#1088;&#1077;&#1074;&#1072;&#1102;&#1090;
      </li>
      <li>
        &#1089;&#1090;&#1072;&#1083;&#1100; -
      </li>
      <li>
        &#1089;&#1090;&#1077;&#1082;&#1083;&#1086;-&#1087;&#1083;&#1072;&#1089;&#1090;&#1080;&#1082; - &#1089;&#1072;&#1084;&#1099;&#1077; &#1076;&#1086;&#1088;&#1086;&#1075;&#1080;&#1077;, &#1080; &#1074;&#1088;&#1086;&#1076;&#1077; &#1083;&#1091;&#1095;&#1096;&#1077; &#1089;&#1090;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093;
      </li>
