<node TEXT="Рекомендации" FOLDED="true" ID="ID_1567691981" CREATED="1544512564734" MODIFIED="1544512950712">
<node TEXT="Популярные ошибки при подключении оборудования" ID="ID_1005190789" CREATED="1544512828445" MODIFIED="1544513828701"><richcontent TYPE="NOTE">
<html>
  <head>
    
  </head>
  <body>
    <p>
      <b>1. &#1057;&#1077;&#1088;&#1074;&#1077;&#1088;, &#1057;&#1061;&#1044; &#1080;&#1083;&#1080; &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1077; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1086; &#1076;&#1074;&#1091;&#1093; &#1073;&#1083;&#1086;&#1082;&#1072;&#1093; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103;, &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1077;&#1085;&#1085;&#1099;&#1093; &#1079;&#1072;&#1095;&#1077;&#1084;-&#1090;&#1086; &#1082; &#1086;&#1076;&#1085;&#1086;&#1084;&#1091; PDU.</b>&#160; &#1042;&#1072;&#1088;&#1080;&#1072;&#1094;&#1080;&#1103; &#1085;&#1072; &#1090;&#1091; &#1078;&#1077; &#1090;&#1077;&#1084;&#1091; &#8212; &#1040;&#1042;&#1056;, &#1086;&#1073;&#1086;&#1080;&#1084;&#1080; &#1082;&#1072;&#1073;&#1077;&#1083;&#1103;&#1084;&#1080; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103; &#1074;&#1086;&#1090;&#1082;&#1085;&#1091;&#1090;&#1099;&#1081; &#1074; &#1086;&#1076;&#1080;&#1085; &#1080; &#1090;&#1086;&#1090; &#1078;&#1077; PDU.
    </p>
    <p>
      &#1042;&#1086; &#1080;&#1079;&#1073;&#1077;&#1078;&#1072;&#1085;&#1080;&#1077;: &#1040;&#1042;&#1056; (&#1072;&#1074;&#1090;&#1086;&#1084;&#1072;&#1090;&#1080;&#1095;&#1077;&#1089;&#1082;&#1080;&#1081; &#1074;&#1074;&#1086;&#1076; &#1088;&#1077;&#1079;&#1077;&#1088;&#1074;&#1072;) &#8212; &#1101;&#1090;&#1086; &#1090;&#1072;&#1082;&#1072;&#1103; &#1096;&#1090;&#1091;&#1082;&#1086;&#1074;&#1080;&#1085;&#1072;, &#1087;&#1086;&#1089;&#1088;&#1077;&#1076;&#1089;&#1090;&#1074;&#1086;&#1084; &#1082;&#1086;&#1090;&#1086;&#1088;&#1086;&#1081; &#1082; &#1076;&#1074;&#1091;&#1084; PDU (&#1080;, &#1089;&#1090;&#1072;&#1083;&#1086; &#1073;&#1099;&#1090;&#1100;, &#1082; &#1076;&#1074;&#1091;&#1084; &#1083;&#1091;&#1095;&#1072;&#1084;) &#1087;&#1086;&#1076;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1090;&#1089;&#1103; &#1086;&#1073;&#1086;&#1088;&#1091;&#1076;&#1086;&#1074;&#1072;&#1085;&#1080;&#1077; &#1089; &#1086;&#1076;&#1085;&#1080;&#1084; &#1073;&#1083;&#1086;&#1082;&#1086;&#1084; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1103; &#8212; &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1089;&#1077;&#1090;&#1077;&#1074;&#1086;&#1077;: &#1082;&#1086;&#1084;&#1084;&#1091;&#1090;&#1072;&#1090;&#1086;&#1088;&#1099;, &#1084;&#1072;&#1088;&#1096;&#1088;&#1091;&#1090;&#1080;&#1079;&#1072;&#1090;&#1086;&#1088;&#1099;
    </p>
    <p>
