      <li>
        (+) &#1082;&#1088;&#1072;&#1089;&#1085;&#1099;&#1081; &gt; Source
      </li>
      <li>
        <b>&#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1103;</b>&#160;(&#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088; 600mV)
      </li>
      <li>
        &#1084;&#1077;&#1085;&#1103;&#1077;&#1084; &#1097;&#1091;&#1087;&#1099; &#1084;&#1077;&#1089;&#1090;&#1072;&#1084;&#1080;
      </li>
      <li>
        <b>&#1073;&#1077;&#1089;&#1082;&#1086;&#1085;&#1077;&#1095;&#1085;&#1086;&#1089;&#1090;&#1100;</b>&#160;(1-&#1077;&#1076;&#1080;&#1085;&#1080;&#1094;&#1072;)
      </li>
      <li>
        &#1077;&#1089;&#1083;&#1080; &#1085;&#1072;&#1096;&#1083;&#1080; &#1087;&#1088;&#1086;&#1073;&#1080;&#1090;&#1099;&#1081; (&#1086;&#1076;&#1080;&#1085;&#1072;&#1082;&#1086;&#1074;&#1086;&#1077; &#1087;&#1072;&#1076;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077;, &#1074;&#1085;&#1077; &#1079;&#1072;&#1074;&#1080;&#1089;&#1080;&#1084;&#1086;&#1089;&#1090;&#1080; &#1086;&#1090; &#1089;&#1084;&#1077;&#1085;&#1099; &#1087;&#1086;&#1083;&#1086;&#1078;&#1077;&#1085;&#1080;&#1103; &#1097;&#1091;&#1087;&#1086;&#1074;), <b>&#1084;&#1091;&#1083;&#1100;&#1090;&#1080;&#1084;&#1077;&#1090;&#1088; &gt; &#1080;&#1079;&#1084;&#1077;&#1088;&#1077;&#1085;&#1080;&#1077; &#1089;&#1086;&#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1083;&#1077;&#1085;&#1080;&#1103;</b>
      </li>
      <li>
        &#1097;&#1091;&#1087;&#1099; &#1090;&#1072;&#1082;&#1078;&#1077; &#1082;&#1072;&#1082; &#1074; &#1087;&#1087; 1-2, 4. <b>&#1087;&#1086;&#1076;&#1090;&#1074;&#1077;&#1088;&#1078;&#1076;&#1072;&#1077;&#1084; &#1087;&#1088;&#1086;&#1073;&#1080;&#1090;&#1080;&#1077;</b>&#160;- &#1089;&#1086;&#1087;&#1088;&#1086;&#1090;&#1080;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1074; &#1086;&#1073;&#1077; &#1089;&#1090;&#1086;&#1088;&#1086;&#1085;&#1099;
      </li>
    </ol>
    <p>
      &#1058;&#1088;&#1072;&#1085;&#1079;&#1080;&#1089;&#1090;&#1086;&#1088; &#1084;&#1086;&#1078;&#1077;&#1090; &#1074;&#1099;&#1081;&#1090;&#1080; &#1080;&#1079; &#1089;&#1090;&#1088;&#1086;&#1103; &#1085;&#1077; &#1089;&#1072;&#1084;. &#1045;&#1089;&#1083;&#1080; &#1087;&#1086;&#1089;&#1083;&#1077; &#1079;&#1072;&#1084;&#1077;&#1085;&#1099; &#1085;&#1077;&#1090; &#1087;&#1086;&#1083;&#1086;&#1078;&#1080;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1075;&#1086; &#1088;&#1077;&#1079;&#1091;&#1083;&#1100;&#1090;&#1072;&#1090;&#1072; &gt; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1103;&#1077;&#1084; <b>&#1064;&#1048;&#1052;-&#1082;&#1086;&#1085;&#1090;&#1088;&#1086;&#1083;&#1083;&#1077;&#1088; </b>
    </p>
    <p>
      
    </p>
    <p>
      <b>2. MOSFET&#1099;</b>. <b>&#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1082;&#1072; &#1087;&#1088;&#1086;&#1079;&#1074;&#1086;&#1085;&#1082;&#1086;&#1081;.</b>&#160; &#1057;&#1090;&#1086;&#1082; &#1080; &#1080;&#1089;&#1090;&#1086;&#1082; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1082;&#1086;&#1088;&#1086;&#1090;&#1080;&#1090;&#1100;. &#1048;&#1089;&#1090;&#1086;&#1082; &#1080; &#1079;&#1072;&#1090;&#1074;&#1086;&#1088; &#1085;&#1077; &#1076;&#1086;&#1083;&#1078;&#1085;&#1099; &#1082;&#1086;&#1088;&#1086;&#1090;&#1080;&#1090;&#1100;. <b>&#1048;&#1089;&#1090;&#1086;&#1082;</b>&#160;- &#1087;&#1077;&#1088;&#1074;&#1099;&#1077; 3 &#1085;&#1086;&#1075;&#1080; &#1086;&#1090; &#1090;&#1086;&#1095;&#1082;&#1080;. <b>&#1047;&#1072;&#1090;&#1074;&#1086;&#1088;</b>&#160;- 4 &#1085;&#1086;&#1075;&#1072;. <b>&#1057;&#1090;&#1086;&#1082;</b>&#160;- 5-8 &#1085;&#1086;&#1075;&#1080;. (&#1069;&#1090;&#1072; &#1089;&#1093;&#1077;&#1084;&#1072; &#1076;&#1083;&#1103; &#1074;&#1089;&#1077;&#1093; MOSFET&#1086;&#1074; &#1074; &#1086;&#1076;&#1085;&#1086;&#1084; &#1082;&#1086;&#1088;&#1087;&#1091;&#1089;&#1077;)
    </p>
    <p>
      
    </p>
    <p>
      <b>3. MOSFET&#1099;</b>. &#1057; &#1087;&#1083;&#1102;&#1089;&#1072; &#1087;&#1080;&#1090;&#1072;&#1085;&#1080;&#1077; &#1080;&#1076;&#1077;&#1090; &#1085;&#1072; &#1087;&#1077;&#1088;&#1074;&#1099;&#1081; &#1080; &#1076;&#1072;&#1083;&#1077;&#1077; &#1074;&#1093;&#1086;&#1076;&#1085;&#1086;&#1081; MOSFET. &#1059;&#1087;&#1088;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090; &#1080;&#1084;&#1080; &#1095;&#1072;&#1088;&#1076;&#1078;&#1077;&#1088;. &#1055;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1084; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1074;&#1093;&#1086;&#1076;&#1077; (2 &#1085;&#1086;&#1075;&#1072;) &#1080; &#1074;&#1099;&#1093;&#1086;&#1076;&#1077; (6 &#1085;&#1086;&#1075;&#1072;) &#1087;&#1077;&#1088;&#1074;&#1086;&#1075;&#1086; MOSFET&#1072;, &#1085;&#1072; &#1074;&#1099;&#1093;&#1086;&#1076;&#1077; &#1074;&#1090;&#1086;&#1088;&#1086;&#1075;&#1086; (&#1087;&#1086;&#1095;&#1077;&#1084;&#1091;-&#1090;&#1086; &#1084;&#1077;&#1088;&#1080;&#1083; 2 &#1085;&#1086;&#1075;&#1091;)&#160;&#160;MOSFET&#1072;. 19v &#1075;&#1086;&#1074;&#1086;&#1088;&#1080;&#1090; &#1086; &#1090;&#1086;&#1084;, &#1095;&#1090;&#1086; MOSFET&#1099; &#1086;&#1090;&#1082;&#1088;&#1099;&#1090;&#1099;. &#1058;&#1072;&#1082;&#1078;&#1077; &#1087;&#1088;&#1086;&#1074;&#1077;&#1088;&#1080;&#1084; &#1085;&#1072;&#1087;&#1088;&#1103;&#1078;&#1077;&#1085;&#1080;&#1077; &#1085;&#1072; &#1079;&#1072;&#1090;&#1074;&#1086;&#1088;&#1072;&#1093; (4 &#1085;&#1086;&#1075;&#1072;) (&#1095;&#1090;&#1086;&#1073;&#1099; &#1091;&#1073;&#1077;&#1076;&#1080;&#1090;&#1100;&#1089;&#1103;, &#1095;&#1090;&#1086; MOSFET&#1099; &#1085;&#1077; &#1087;&#1088;&#1086;&#1073;&#1080;&#1090;&#1099;). 6v - &#1085;&#1086;&#1088;&#1084;&#1072; &#1076;&#1083;&#1103; p-&#1082;&#1072;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; MOSFETO&#1074;.
    </p>
  </body>
</html></richcontent>
</node>
