      <b>&#1055;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1086;&#1090; &#1089;&#1090;&#1072;&#1088;&#1096;&#1077;&#1075;&#1086; &#1082; &#1084;&#1083;&#1072;&#1076;&#1096;&#1077;&#1084;&#1091; (big-endian).</b>&#160;&#1069;&#1090;&#1086;&#1090; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1089;&#1086;&#1086;&#1090;&#1074;&#1077;&#1090;&#1089;&#1090;&#1074;&#1091;&#1077;&#1090; &#1087;&#1088;&#1080;&#1074;&#1099;&#1095;&#1085;&#1086;&#1084;&#1091; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1091; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1072;&#1088;&#1072;&#1073;&#1089;&#1082;&#1080;&#1093; &#1094;&#1080;&#1092;&#1088;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1095;&#1080;&#1089;&#1083;&#1086; &#1089;&#1090;&#1086; &#1076;&#1074;&#1072;&#1076;&#1094;&#1072;&#1090;&#1100; &#1090;&#1088;&#1080; &#1073;&#1099;&#1083;&#1086; &#1073;&#1099; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1086; &#1087;&#1088;&#1080; &#1090;&#1072;&#1082;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1082;&#1072;&#1082; 123. &#1042; &#1101;&#1090;&#1086;&#1084; &#1078;&#1077; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1087;&#1088;&#1080;&#1085;&#1103;&#1090;&#1086; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1090;&#1100; &#1073;&#1072;&#1081;&#1090;&#1099; &#1074; &#1090;&#1077;&#1093;&#1085;&#1080;&#1095;&#1077;&#1089;&#1082;&#1086;&#1081; &#1080; &#1091;&#1095;&#1077;&#1073;&#1085;&#1086;&#1081; &#1083;&#1080;&#1090;&#1077;&#1088;&#1072;&#1090;&#1091;&#1088;&#1077;, &#1077;&#1089;&#1083;&#1080; &#1076;&#1088;&#1091;&#1075;&#1086;&#1081; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1103;&#1074;&#1085;&#1086; &#1085;&#1077; &#1086;&#1073;&#1086;&#1079;&#1085;&#1072;&#1095;&#1077;&#1085;.
    </p>
    <ul>
      <li>
        &#1103;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1089;&#1090;&#1072;&#1085;&#1076;&#1072;&#1088;&#1090;&#1085;&#1099;&#1084; &#1076;&#1083;&#1103; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074; TCP/IP, &#1086;&#1085; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1074; &#1079;&#1072;&#1075;&#1086;&#1083;&#1086;&#1074;&#1082;&#1072;&#1093; &#1087;&#1072;&#1082;&#1077;&#1090;&#1086;&#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093; &#1080; &#1074;&#1086; &#1084;&#1085;&#1086;&#1075;&#1080;&#1093; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1072;&#1093; &#1073;&#1086;&#1083;&#1077;&#1077; &#1074;&#1099;&#1089;&#1086;&#1082;&#1086;&#1075;&#1086; &#1091;&#1088;&#1086;&#1074;&#1085;&#1103;, &#1088;&#1072;&#1079;&#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1085;&#1085;&#1099;&#1093; &#1076;&#1083;&#1103; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1086;&#1074;&#1072;&#1085;&#1080;&#1103; &#1087;&#1086;&#1074;&#1077;&#1088;&#1093; TCP/IP. &#1055;&#1086;&#1101;&#1090;&#1086;&#1084;&#1091; &#1101;&#1090;&#1086; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1095;&#1072;&#1089;&#1090;&#1086; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090; &#171;&#1089;&#1077;&#1090;&#1077;&#1074;&#1099;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1086;&#1084; &#1073;&#1072;&#1081;&#1090;&#1086;&#1074;&#187; (network byte order)
      </li>
      <li>
        &#1091;&#1076;&#1086;&#1073;&#1085;&#1086; &#1087;&#1088;&#1086;&#1074;&#1086;&#1076;&#1080;&#1090;&#1100; &#1089;&#1088;&#1072;&#1074;&#1085;&#1077;&#1085;&#1080;&#1077; &#1089;&#1090;&#1088;&#1086;&#1082; (&#1084;&#1086;&#1078;&#1085;&#1086; &#1089;&#1088;&#1072;&#1074;&#1085;&#1080;&#1074;&#1072;&#1090;&#1100; &#1080;&#1093; &#1094;&#1077;&#1083;&#1086;&#1095;&#1080;&#1089;&#1083;&#1077;&#1085;&#1085;&#1099;&#1084;&#1080; &#1073;&#1086;&#1083;&#1100;&#1096;&#1077;&#1081; &#1088;&#1072;&#1079;&#1088;&#1103;&#1076;&#1085;&#1086;&#1089;&#1090;&#1080;, &#1082;&#1072;&#1078;&#1076;&#1086;&#1077; &#1080;&#1079; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1089;&#1086;&#1076;&#1077;&#1088;&#1078;&#1080;&#1090; &#1085;&#1077;&#1089;&#1082;&#1086;&#1083;&#1100;&#1082;&#1086; &#1089;&#1080;&#1084;&#1074;&#1086;&#1083;&#1086;&#1074; &#1089;&#1088;&#1072;&#1079;&#1091;)
      </li>
      <li>
        &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074;&#1086; &#1084;&#1085;&#1086;&#1075;&#1080;&#1093; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1072;&#1093; &#1092;&#1072;&#1081;&#1083;&#1086;&#1074; &#8212; &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, PNG, FLV, EBML, JPEG.
      </li>
    </ul>
    <p>
      <b>&#1055;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1086;&#1090; &#1084;&#1083;&#1072;&#1076;&#1096;&#1077;&#1075;&#1086; &#1082; &#1089;&#1090;&#1072;&#1088;&#1096;&#1077;&#1084;&#1091;&#160;(little-endian).</b>&#160;&#1069;&#1090;&#1086; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1099;&#1081; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1087;&#1086; &#1086;&#1090;&#1085;&#1086;&#1096;&#1077;&#1085;&#1080;&#1102; &#1082; &#1087;&#1088;&#1080;&#1074;&#1099;&#1095;&#1085;&#1086;&#1084;&#1091; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1091; &#1079;&#1072;&#1087;&#1080;&#1089;&#1080; &#1072;&#1088;&#1072;&#1073;&#1089;&#1082;&#1080;&#1093; &#1094;&#1080;&#1092;&#1088;, &#1085;&#1072;&#1087;&#1088;&#1080;&#1084;&#1077;&#1088;, &#1095;&#1080;&#1089;&#1083;&#1086; &#1089;&#1090;&#1086; &#1076;&#1074;&#1072;&#1076;&#1094;&#1072;&#1090;&#1100; &#1090;&#1088;&#1080; &#1073;&#1099;&#1083;&#1086; &#1073;&#1099; &#1079;&#1072;&#1087;&#1080;&#1089;&#1072;&#1085;&#1086; &#1087;&#1088;&#1080; &#1090;&#1072;&#1082;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1082;&#1072;&#1082; 321.
    </p>
    <ul>
      <li>
        &#1087;&#1088;&#1080;&#1085;&#1103;&#1090; &#1074; &#1087;&#1072;&#1084;&#1103;&#1090;&#1080; &#1087;&#1077;&#1088;&#1089;&#1086;&#1085;&#1072;&#1083;&#1100;&#1085;&#1099;&#1093; &#1082;&#1086;&#1084;&#1087;&#1100;&#1102;&#1090;&#1077;&#1088;&#1086;&#1074; &#1089; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1072;&#1084;&#1080; &#1072;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1099; x86, &#1074; &#1089;&#1074;&#1103;&#1079;&#1080; &#1089; &#1095;&#1077;&#1084; &#1080;&#1085;&#1086;&#1075;&#1076;&#1072; &#1077;&#1075;&#1086; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090; &#1080;&#1085;&#1090;&#1077;&#1083;&#1086;&#1074;&#1089;&#1082;&#1080;&#1081; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1073;&#1072;&#1081;&#1090;&#1086;&#1074; (&#1087;&#1086; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1102; &#1082;&#1086;&#1084;&#1087;&#1072;&#1085;&#1080;&#1080;-&#1089;&#1086;&#1079;&#1076;&#1072;&#1090;&#1077;&#1083;&#1103; &#1072;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1099; x86). &#1057;&#1086;&#1074;&#1088;&#1077;&#1084;&#1077;&#1085;&#1085;&#1099;&#1077; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1099; x86 &#1087;&#1086;&#1079;&#1074;&#1086;&#1083;&#1103;&#1102;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1089; &#1086;&#1076;&#1085;&#1086;-, &#1076;&#1074;&#1091;&#1093;-, &#1095;&#1077;&#1090;&#1099;&#1088;&#1105;&#1093;- &#1080; &#1074;&#1086;&#1089;&#1100;&#1084;&#1080;&#1073;&#1072;&#1081;&#1090;&#1086;&#1074;&#1099;&#1084;&#1080; &#1086;&#1087;&#1077;&#1088;&#1072;&#1085;&#1076;&#1072;&#1084;&#1080;
      </li>
      <li>
        &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; &#1072;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1072;&#1093; VAX (&#1086;&#1090;&#1089;&#1102;&#1076;&#1072; &#1077;&#1097;&#1105; &#1086;&#1076;&#1085;&#1086; &#1085;&#1072;&#1079;&#1074;&#1072;&#1085;&#1080;&#1077; VAX byte order, DEC Alpha &#1080; &#1084;&#1085;&#1086;&#1075;&#1080;&#1093; &#1076;&#1088;&#1091;&#1075;&#1080;&#1093;
      </li>
      <li>
        &#1087;&#1088;&#1080;&#1084;&#1077;&#1085;&#1103;&#1077;&#1090;&#1089;&#1103; &#1074; USB, PCI, &#1090;&#1072;&#1073;&#1083;&#1080;&#1094;&#1077; &#1088;&#1072;&#1079;&#1076;&#1077;&#1083;&#1086;&#1074; GUID, &#1086;&#1085; &#1088;&#1077;&#1082;&#1086;&#1084;&#1077;&#1085;&#1076;&#1086;&#1074;&#1072;&#1085; FidoNet. &#1053;&#1086; &#1074; &#1094;&#1077;&#1083;&#1086;&#1084; &#1089;&#1086;&#1075;&#1083;&#1072;&#1096;&#1077;&#1085;&#1080;&#1077; little-endian &#1087;&#1086;&#1076;&#1076;&#1077;&#1088;&#1078;&#1080;&#1074;&#1072;&#1102;&#1090; &#1084;&#1077;&#1085;&#1100;&#1096;&#1077; &#1082;&#1088;&#1086;&#1089;&#1089;-&#1087;&#1083;&#1072;&#1090;&#1092;&#1086;&#1088;&#1084;&#1077;&#1085;&#1085;&#1099;&#1093; &#1087;&#1088;&#1086;&#1090;&#1086;&#1082;&#1086;&#1083;&#1086;&#1074; &#1080; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1086;&#1074; &#1076;&#1072;&#1085;&#1085;&#1099;&#1093;, &#1095;&#1077;&#1084; big-endian.
      </li>
    </ul>
    <p>
      <b>&#1055;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084;&#1099;&#1081; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082;.</b>&#160;&#1052;&#1085;&#1086;&#1075;&#1080;&#1077; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1099; &#1084;&#1086;&#1075;&#1091;&#1090; &#1088;&#1072;&#1073;&#1086;&#1090;&#1072;&#1090;&#1100; &#1080; &#1074; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1086;&#1090; &#1084;&#1083;&#1072;&#1076;&#1096;&#1077;&#1075;&#1086; &#1082; &#1089;&#1090;&#1072;&#1088;&#1096;&#1077;&#1084;&#1091;, &#1080; &#1074; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084;. &#1054;&#1073;&#1099;&#1095;&#1085;&#1086; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1073;&#1072;&#1081;&#1090;&#1086;&#1074; &#1074;&#1099;&#1073;&#1080;&#1088;&#1072;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1086;&#1075;&#1088;&#1072;&#1084;&#1084;&#1085;&#1086; &#1074;&#1086; &#1074;&#1088;&#1077;&#1084;&#1103; &#1080;&#1085;&#1080;&#1094;&#1080;&#1072;&#1083;&#1080;&#1079;&#1072;&#1094;&#1080;&#1080; &#1054;&#1057;, &#1085;&#1086; &#1084;&#1086;&#1078;&#1077;&#1090; &#1073;&#1099;&#1090;&#1100; &#1074;&#1099;&#1073;&#1088;&#1072;&#1085; &#1080; &#1072;&#1087;&#1087;&#1072;&#1088;&#1072;&#1090;&#1085;&#1086; &#1087;&#1077;&#1088;&#1077;&#1084;&#1099;&#1095;&#1082;&#1072;&#1084;&#1080; &#1085;&#1072; &#1084;&#1072;&#1090;&#1077;&#1088;&#1080;&#1085;&#1089;&#1082;&#1086;&#1081; &#1087;&#1083;&#1072;&#1090;&#1077;. &#1042; &#1101;&#1090;&#1086;&#1084; &#1089;&#1083;&#1091;&#1095;&#1072;&#1077; &#1087;&#1088;&#1072;&#1074;&#1080;&#1083;&#1100;&#1085;&#1077;&#1077; &#1075;&#1086;&#1074;&#1086;&#1088;&#1080;&#1090;&#1100; &#1086; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077; &#1073;&#1072;&#1081;&#1090;&#1086;&#1074; &#1054;&#1057;. &#1055;&#1077;&#1088;&#1077;&#1082;&#1083;&#1102;&#1095;&#1072;&#1077;&#1084;&#1099;&#1081; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1073;&#1072;&#1081;&#1090;&#1086;&#1074; &#1080;&#1085;&#1086;&#1075;&#1076;&#1072; &#1085;&#1072;&#1079;&#1099;&#1074;&#1072;&#1102;&#1090; bi-endian.
    </p>
    <p>
      <b>&#1057;&#1084;&#1077;&#1096;&#1072;&#1085;&#1085;&#1099;&#1081; &#1087;&#1086;&#1088;&#1103;&#1076;&#1086;&#1082; &#1073;&#1072;&#1081;&#1090;&#1086;&#1074; (middle-endian).</b>&#160;&#1048;&#1085;&#1086;&#1075;&#1076;&#1072; &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1087;&#1088;&#1080; &#1088;&#1072;&#1073;&#1086;&#1090;&#1077; &#1089; &#1095;&#1080;&#1089;&#1083;&#1072;&#1084;&#1080;, &#1076;&#1083;&#1080;&#1085;&#1072; &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1093; &#1087;&#1088;&#1077;&#1074;&#1099;&#1096;&#1072;&#1077;&#1090; &#1084;&#1072;&#1096;&#1080;&#1085;&#1085;&#1086;&#1077; &#1089;&#1083;&#1086;&#1074;&#1086;. &#1063;&#1080;&#1089;&#1083;&#1086; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1103;&#1077;&#1090;&#1089;&#1103; &#1087;&#1086;&#1089;&#1083;&#1077;&#1076;&#1086;&#1074;&#1072;&#1090;&#1077;&#1083;&#1100;&#1085;&#1086;&#1089;&#1090;&#1100;&#1102; &#1084;&#1072;&#1096;&#1080;&#1085;&#1085;&#1099;&#1093; &#1089;&#1083;&#1086;&#1074;, &#1082;&#1086;&#1090;&#1086;&#1088;&#1099;&#1077; &#1079;&#1072;&#1087;&#1080;&#1089;&#1099;&#1074;&#1072;&#1102;&#1090;&#1089;&#1103; &#1074; &#1092;&#1086;&#1088;&#1084;&#1072;&#1090;&#1077;, &#1077;&#1089;&#1090;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1086;&#1084; &#1076;&#1083;&#1103; &#1076;&#1072;&#1085;&#1085;&#1086;&#1081; &#1072;&#1088;&#1093;&#1080;&#1090;&#1077;&#1082;&#1090;&#1091;&#1088;&#1099;, &#1085;&#1086; &#1089;&#1072;&#1084;&#1080; &#1089;&#1083;&#1086;&#1074;&#1072; &#1089;&#1083;&#1077;&#1076;&#1091;&#1102;&#1090; &#1074; &#1086;&#1073;&#1088;&#1072;&#1090;&#1085;&#1086;&#1084; &#1087;&#1086;&#1088;&#1103;&#1076;&#1082;&#1077;. &#1042; &#1087;&#1088;&#1086;&#1094;&#1077;&#1089;&#1089;&#1086;&#1088;&#1072;&#1093; VAX &#1080; ARM &#1080;&#1089;&#1087;&#1086;&#1083;&#1100;&#1079;&#1091;&#1077;&#1090;&#1089;&#1103; &#1089;&#1084;&#1077;&#1096;&#1072;&#1085;&#1085;&#1086;&#1077; &#1087;&#1088;&#1077;&#1076;&#1089;&#1090;&#1072;&#1074;&#1083;&#1077;&#1085;&#1080;&#1077; &#1076;&#1083;&#1103; &#1076;&#1083;&#1080;&#1085;&#1085;&#1099;&#1093; &#1074;&#1077;&#1097;&#1077;&#1089;&#1090;&#1074;&#1077;&#1085;&#1085;&#1099;&#1093; &#1095;&#1080;&#1089;&#1077;&#1083;.
    </p>
